pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: penalize leftover space, with non-linear (quadratic/cubic) shaping
    let mut score = pr
        - 12.0 * norm_pr * (1.0 - norm_pr) * cap
        + 20.0 * norm_pr * norm_pr;

    // Smooth coupling: tight fits become more valuable as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= 30.0 * tightness * tightness * (0.3 + 0.7 * progress);

    // Penalize dead space relative to mean residual (smooth interaction)
    let mr = mean_residual / cap;
    score += 15.0 * (norm_pr - mr) * (norm_pr - mr) * (1.0 - progress);

    // Lookahead: reward if next item fits in post_residual (smooth term)
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let fits_next = (pr - ns).max(0.0) / cap;
        score += 10.0 * fits_next * fits_next;
        score -= 8.0 * (1.0 - (ns / cap)) * tightness * progress;
    }

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (0.5 + 0.5 * progress);
    }

    // Mild penalty for spreading across many bins early
    score += 2.0 * (open_bins_count as f64).ln() * (1.0 - progress);

    // Slight preference for fuller bins overall
    score -= 5.0 * item_size as f64 / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into "dead zone"
    // classes (small non-reusable slivers) are penalized.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let item = item_size as f64;

    // Perfect fit reward: exact fill is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic residue classes on post_residual (mod 10): residuals that are
    // multiples of 10 remain reusable by the smallest items (sizes >= 1).
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 25.0;
    }

    // Dead-space class: residual in (0, 10) is unusable waste -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Fractional capacity classes: post_residual as fraction of capacity.
    let frac = pr / cap;
    if frac < 0.1 {
        score += 30.0 * (0.1 - frac);
    } else if frac > 0.5 {
        score -= 15.0 * (frac - 0.5);
    }

    // Integer-division threshold: how many mid-size items (>= 10) still fit.
    let fits_count = post_residual / 10;
    score -= 8.0 * fits_count as f64;

    // Lookahead coupling: reward residual that can host the next item exactly
    // or comfortably; penalize residual just barely too small for next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack == 0 {
                score -= 120.0; // perfect lookahead fit
            } else if slack < 10 {
                score -= 40.0;  // near-perfect next fit
            } else {
                score -= 15.0;  // can host next item
            }
        } else {
            // residual cannot host next item: penalize proportionally to closeness
            let gap = (next_item_size - post_residual) as f64;
            score += 20.0 + 0.5 * gap;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 45.0;
    }

    // New-bin candidate handling: an empty bin is a fallback; make it attractive
    // only when current bin would leave large waste relative to mean residual.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 40.0;
        // more attractive late in the stream or when open bins are already tight
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 30.0 * progress;
        score -= 5.0 * open_bins_count as f64;
        // if mean residual across open bins is small, opening fresh bin is good
        if mean_residual < item {
            score -= 50.0;
        }
    }

    // Tightness bonus: prefer bins where the item fills a large share of residual.
    if bin_residual > 0 {
        let fill_ratio = item / bin_residual as f64;
        score -= 30.0 * fill_ratio;
    }

    // Mild penalty for spreading across many open bins when residuals are large.
    if mean_residual > 0.6 * cap && open_bins_count > 2 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=15) are heavily penalized.
    if post_residual > 0 && post_residual <= 15 {
        score += 40.0 * (16.0 - post_residual as f64);
    }
    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward placements that leave room for the lookahead item when possible.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: when many bins are open, avoid spreading; prefer tight fits.
    let pressure = open_bins_count as f64 / 10.0;
    score += pressure * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when no open bin fits well or
    // the item is large relative to typical residuals.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit = mean_residual < item_size as f64 * 0.6;
        if poor_fit || post_residual < 20 {
            score -= 12.0 + 10.0 * progress;
        } else {
            score += 15.0;
        }
    }

    // Mild preference for bins whose residual is close to the item (best fit flavor).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += 0.15 * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_post = post / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    let mut score = post;

    // Smooth non-linear coupling: waste grows quadratically as post-residual shrinks
    score += 18.0 * (1.0 - norm_post) * (1.0 - norm_post) * norm_item * cap;

    // Progress-dependent tightness reward: late in the stream, prefer tight fits more strongly
    score -= (12.0 + 26.0 * progress) * (1.0 - norm_post) * (1.0 - norm_post) * cap;

    // Dead-space penalty: residual too small to fit typical items (smooth sigmoid-like term)
    let dead = 1.0 / (1.0 + (norm_post * 12.0 - 4.0).exp());
    score += 22.0 * dead * cap * (0.3 + 0.7 * progress);

    // Lookahead coupling: reward if next item fits post-residual, penalize near-miss
    if next_item_size > 0 {
        let fits_next = (post_residual as f64 - next_item_size as f64) / cap;
        let smooth = 1.0 / (1.0 + (-fits_next * 20.0).exp());
        score -= 14.0 * smooth * cap;
        score += 6.0 * (1.0 - smooth) * norm_next * cap;
    }

    // Last-chance bonus: only one fitting bin left, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Mild penalty for spreading across many bins when mean residual is high
    score += 0.35 * (open_bins_count as f64).ln().max(0.0) * (mean_residual / cap - norm_post).abs() * cap;

    // Slight new-bin aversion that decays with progress
    if bin_residual == bin_capacity {
        score += 6.0 * (1.0 - progress) + 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: prefer small post-residual (tight fit), non-linearly.
    let mut score = norm_post * norm_post * cap;

    // Smooth coupling: waste matters more as the stream progresses.
    let urgency = 1.0 + 2.0 * progress * progress;
    score *= urgency;

    // Penalize post-residuals that are "just barely unusable" (dead space):
    // smooth penalty peaking when post_residual is small but < typical item size.
    let deadness = if post > 0.0 {
        let r = norm_post;
        r * (1.0 - r) * (1.0 - r) * cap
    } else {
        -3.0 // perfect fit reward
    };
    score += deadness * 4.0;

    // Reward bins whose residual was already small (consolidation).
    let pre_norm = bin_residual as f64 / cap;
    score -= (1.0 - pre_norm) * (1.0 - pre_norm) * 2.0;

    // Last-chance bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 6.0;
    } else if fitting_bins_count > 1 {
        // Among several candidates, mildly prefer tighter ones (already via post).
        score += 0.5;
    }

    // Lookahead: if next item fits in the post-residual, reward this placement.
    if next_item_size > 0 && (post_residual as u64) >= (next_item_size as u64) {
        let slack = (post_residual - next_item_size) as f64 / cap;
        score -= 3.0 * (1.0 - slack);
    } else if next_item_size > 0 {
        // Next item won't fit here; penalize leaving awkward residual.
        score += 1.5 * norm_post;
    }

    // New-bin candidate (empty bin): should only win when no decent fit exists.
    if bin_residual == bin_capacity {
        // Penalize opening new bins early; allow it late or when few bins fit.
        let open_pressure = (fitting_bins_count as f64).recip();
        score = cap * (0.6 + 0.4 * (1.0 - progress)) * open_pressure * open_pressure + 2.0;
        if fitting_bins_count == 0 {
            score -= 10.0; // no alternative
        }
        // Late in stream, small residual waste elsewhere favors reuse: keep new-bin expensive.
        score += 2.0 * progress;
    }

    // Mild penalty for proliferation of open bins.
    score += (open_bins_count as f64).ln().max(0.0) * 0.3;

    // Slight pull toward mean residual state (stability term).
    score += 0.1 * (norm_post * cap - mean_residual).abs() / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps.
    // Gaps that are too small for the smallest plausible item are pure waste.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // unusable dead space
        } else if post_residual < item_size.min(20) {
            score += 15.0; // likely unusable for future items
        }
    } else {
        // Perfect fit: strong reward
        score -= 40.0;
    }

    // Reward exact match of post_residual to next item (lookahead synergy)
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0; // gap still usable by next item
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only prefer opening a new bin when the
    // current bin would leave a large-ish awkward residual and open-bin
    // pressure is low.
    if bin_residual == bin_capacity {
        // brand-new bin: baseline score = item_size; adjust by stream progress
        score = item_size as f64 + 10.0 * (step_index as f64 / total_items.max(1) as f64);
        if open_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    } else {
        // Open-bin pressure: penalize spreading across many bins
        score += open_bins_count as f64 * 0.5;
        // Slight preference for bins with residuals below mean (tighten tight bins)
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // even the smallest plausible item are pure waste. Penalize them hard.
    let dead_threshold = 10.0f64.min(bin_capacity as f64 * 0.12);
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 6.0;
    }
    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Tight fit reward: how well the item fills this bin relative to its residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 25.0;

    // Last-chance pressure: if this is the only bin that fits, prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin is a fallback; make it
    // moderately unattractive unless the current item leaves a good gap
    // or no open bin fits well.
    if bin_residual == bin_capacity {
        score += 15.0 + open_bins_count as f64 * -1.0;
        // If next item is large, a fresh bin is more valuable.
        if next_item_size as f64 > bin_capacity as f64 * 0.5 {
            score -= 20.0;
        }
    }

    // Lookahead synergy: if the next item fits exactly into the post residual,
    // strongly favor this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    }
    // Penalize leaving a gap the next item cannot use.
    if next_item_size > post_residual && post_residual > 0 {
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing
    // bins rather than spreading out.
    score += open_bins_count as f64 * 0.8;

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is closer to being closed out; finishing it off is good.
    let residual_diff = mean_residual - bin_residual as f64;
    score += residual_diff * 0.3;

    // Stream progression: late in the stream, be more aggressive about
    // closing bins tightly.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score -= progress * (post_residual as f64) * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into capacity fractions.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap; // 0..1

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize "dead" residuals that no plausible item (1..=100) can use well.
        // Residual classes: tiny (<=5) is nearly dead; mid residuals (30..70) are reusable.
        if post_residual <= 5 {
            score += 20.0; // small dead space, but at least bin is nearly full
        } else if post_residual <= 20 {
            score += 5.0;
        } else if post_residual <= 50 {
            score -= 10.0; // highly reusable band
        } else {
            score += 8.0; // large leftover = wasteful placement
        }

        // Modulo-10 harmonic class: residuals that are multiples of 10 align with
        // typical integer item sizes, making them more usable.
        if post_residual % 10 == 0 {
            score -= 6.0;
        } else if post_residual % 5 == 0 {
            score -= 3.0;
        }

        // Lookahead coupling: reward if next item fits exactly or well in post_residual.
        if next_item_size > 0 {
            if next_item_size == post_residual {
                score -= 200.0; // perfect chaining
            } else if next_item_size < post_residual {
                let nxt_frac = next_item_size as f64 / post;
                if nxt_frac > 0.8 {
                    score -= 40.0; // near-perfect chain
                } else if nxt_frac > 0.4 {
                    score -= 15.0;
                }
            } else {
                // next item cannot fit here: leftover becomes single-item dead space risk
                score += 12.0;
            }
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0 + 0.5 * post;
    }

    // New-bin candidate handling: neutral baseline with slight preference when
    // open bins are collectively full or the fit here is bad.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = 55.0;
        // Cheaper to open a new bin early in the stream (more items to come,
        // better long-run packing) and when few bins are open.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 25.0 * (1.0 - progress);
        score -= 2.0 * (open_bins_count.min(20) as f64);
        // If mean residual across open bins is small, open bins are congested:
        // opening a fresh bin is more attractive.
        score -= (mean_residual / cap).max(0.0) * 20.0;
        // If next item is large and this item leaves a bad residual, new bin helps.
        if next_item_size >= 60 && post_residual < next_item_size as u32 {
            score -= 15.0;
        }
    }

    // Mild global regularization toward tighter bins overall.
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize unusable small gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 500.0;
    } else if post_residual < 20 {
        score += 120.0;
    } else if post_residual < 30 {
        score += 40.0;
    }

    // Perfect or near-perfect fit reward.
    if post_residual == 0 {
        score -= 300.0;
    } else if post_residual <= 5 {
        score -= 80.0;
    }

    // Dead space is worse if nothing else fits in it: penalize gaps smaller
    // than the lookahead item (which then cannot reuse this bin).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size as f64 {
        score += 60.0 + 0.5 * post_residual as f64;
    }

    // Reward bins whose residual exactly accommodates the next item.
    if next_item_size > 0 && post_residual as u32 == next_item_size {
        score -= 100.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // over spreading; with few open bins, opening a new bin is cheaper.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * 8.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Penalize the brand-new empty bin candidate unless open-bin pressure is
    // low or the fit would be terrible.
    let fit_quality = post_residual as f64 / bin_capacity as f64;
    if bin_residual == bin_capacity {
        let escape_cost = 40.0 + 250.0 * (1.0 - fit_quality);
        score += escape_cost - pressure * 12.0;
        if fitting_bins_count == 0 {
            score -= 400.0; // no alternative: new bin is the only choice
        }
    }

    // Mild progression term: later in the stream, waste hurts more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * fit_quality * 30.0;

    // Nudge toward bins with residuals close to item size (tight fits).
    score += (bin_residual as f64 - item_size as f64).abs() * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    let dead = (post_residual as f64) / (bin_capacity as f64);
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (1.0 - dead);
    } else if post_residual < 20 {
        score += 25.0 * (1.0 - dead);
    }

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Open-bin pressure: with many open bins, prefer reusing existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    score += pressure * 0.8;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead coupling: if next item fits the post residual, this is a great placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        score += 10.0; // dead space relative to lookahead
    }

    // Prefer bins tighter than average residual (good fits).
    score += ((bin_residual as f64) - mean_residual) * 0.3;

    // New-bin candidate: neutral-ish baseline, only attractive when no decent fit exists.
    if bin_residual == bin_capacity {
        score = 70.0 + pressure * 0.3;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item
    // (size 1 in the general interface, conservatively < 10) are unusable waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    }

    // Perfect or near-perfect fits are heavily rewarded.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Reward bins whose residual after placement can still host the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Residual that blocks the next item but is not zero: mild penalty.
        score += 8.0;
    }

    // Open-bin pressure: discourage spreading across many bins,
    // but relax pressure when this bin is the last chance.
    if fitting_bins_count > 1 {
        score += open_bins_count as f64 * 0.7;
    } else {
        score -= 12.0; // last-chance bin: strongly prefer filling it
    }

    // Prefer bins tighter than the average residual (good fits).
    score += (mean_residual - bin_residual as f64) * 0.25;

    // New-bin candidate: it is only attractive if it avoids creating dead space
    // elsewhere; make the empty-bin baseline moderate so poor fits into open
    // bins with small residuals still win, but very poor fits open a new bin.
    if bin_residual == bin_capacity {
        score = 45.0 + open_bins_count as f64 * 0.3 - (post_residual as f64) * 0.1;
        if post_residual < 10 && post_residual > 0 {
            score += 20.0;
        }
    }

    // Late-stream consolidation: as the stream ends, favor tightening existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Is this a brand-new empty bin candidate?
    let is_new_bin = bin_residual == bin_capacity;

    // Progress through the stream (0..1)
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };

    // ---- 2-step lookahead core ----
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64 - nxt).abs() < 1.0 {
            // Perfect match: next item exactly fills this bin afterwards
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item can also fit here afterwards: reward, scaled by tightness
            let tight = 1.0 - (post_residual as f64 - nxt) / bin_capacity as f64;
            score -= 25.0 * tight;
        } else {
            // Dead space: next item cannot use the remainder; penalize proportionally
            let waste = (nxt - post_residual as f64) / bin_capacity as f64;
            score += 30.0 * waste;
        }
    } else {
        // Last item: just minimize leftover waste
        score += 10.0;
    }

    // ---- Relative-to-mean residual coupling ----
    // Prefer bins whose post residual deviates favorably from mean residual:
    // leaving less than the mean is good (tight packing).
    let pr = post_residual as f64;
    if pr < mean_residual {
        score -= 0.5 * (mean_residual - pr);
    } else {
        score += 0.3 * (pr - mean_residual);
    }

    // ---- Last-chance bin bonus ----
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 15.0 + 10.0 * progress;
    }

    // ---- New-bin candidate handling ----
    if is_new_bin {
        // Opening a new bin is only attractive when current item leaves
        // a large unusable remainder in existing bins, or many bins are open.
        let tight_fit_penalty = if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            20.0
        } else {
            0.0
        };
        score += 35.0                       // base reluctance to open new bin
                 + tight_fit_penalty
                 - 2.0 * open_bins_count as f64 * (1.0 - progress);
    }

    // Small tie-break: prefer fuller bins overall
    score -= 0.05 * (bin_residual - post_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit: reward strongly.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: post_residual in unusable small gap zone.
    // A residual that no future item (min size 1..100 unknown) can plausibly fill
    // is dead space. Penalize the "awkward gap" band nonlinearly.
    if post_residual > 0 && post_residual <= 12 {
        score += 40.0 + (12 - post_residual) as f64 * 4.0;
    }

    // Reward tight fits generally (small waste relative to item size).
    if item_size > 0 {
        score -= (item_size as f64 / post_residual.max(1) as f64) * 2.0;
    }

    // Last chance: if this is the only bin that can fit the item, strongly favor it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // open bins are crowded (mean residual low) or many bins already open.
    if bin_residual == bin_capacity {
        // Base penalty so we prefer using existing bins, unless they're nearly full.
        let pressure = (open_bins_count as f64 * 0.5) + (bin_capacity as f64 - mean_residual).max(0.0) * 0.8;
        score += 80.0 - pressure.min(150.0);
        // If the next item is large and current bins are tight, new bin less bad.
        if next_item_size > 0 && next_item_size as f64 > mean_residual {
            score -= 25.0;
        }
    } else {
        // Placing into an open bin: penalize if it leaves the bin too full for
        // the lookahead item when alternatives exist.
        if next_item_size > 0 && post_residual as f64 > 0.0 && (next_item_size as f64) > post_residual as f64 {
            score += 5.0;
        } else if next_item_size > 0 && (next_item_size as u32) == post_residual {
            // Lookahead fits exactly after this placement: big reward.
            score -= 80.0;
        }
    }

    // Mild open-bins pressure: prefer filling existing bins as their count grows.
    score += open_bins_count as f64 * 0.3;

    // Slight preference for bins whose residual is close to the item (best-fit coupling).
    score += ((bin_residual as f64 - item_size as f64) / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: perfect match with next item is highly rewarded.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if diff == 0.0 {
            score -= 60.0; // exact fit for the next item
        } else {
            score += 0.8 * diff; // penalize mismatch proportional to distance
        }
        // Bonus if next item fits into the residual left behind (chainability)
        if next_item_size <= post_residual {
            score -= 15.0;
        } else {
            score += 10.0 * (next_item_size - post_residual as u32) as f64;
        }
    }

    // Penalize dead space relative to mean residual across open bins
    score += 0.5 * (post_residual as f64 - mean_residual).max(0.0);
    score -= 0.2 * (mean_residual - post_residual as f64).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are crowded
    if bin_residual == bin_capacity {
        let crowding = mean_residual / bin_capacity as f64;
        score += 30.0 * (1.0 - crowding);
        if fitting_bins_count == 0 {
            score -= 100.0; // nothing else fits: must open new bin
        }
    }

    // Waste ratio: small leftover relative to item size is good packing
    score += 0.3 * (post_residual as f64 / item_size.max(1) as f64);

    // Late in the stream, prefer tighter packing to close bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual gap is "dead" if it is smaller than the smallest plausible item (1..100, use 10 as typical lower bound).
    let dead_threshold = 10.0_f64;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += 40.0; // unusable sliver
    }

    // Penalize near-full waste mildly; reward tight fits (small positive post_residual).
    if post_residual > 0 && post_residual <= 5 {
        score -= 8.0;
    }

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Penalize leaving a gap that exactly fits the next item (wasted opportunity otherwise).
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 6.0;
    } else if next_item_size > 0 && post_residual < next_item_size {
        score += 4.0; // next item cannot use this gap
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is excellent.
    score += open_bins_count as f64 * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: make it attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        // Baseline cost of opening a new bin; compare against dead-space penalties of open bins.
        score = bin_capacity as f64 * 0.35 + open_bins_count as f64 * 0.3;
        if post_residual == 0 { score -= 25.0; }
    }

    // Progress-based mild adjustment: late in stream, tighten up (avoid waste more).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual modulo capacity fractions
    let pr = post_residual;
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;

    // Penalize residuals that are "dead zones" (small, hard to fill)
    if pr > 0 && pr < eighth {
        score += 25.0;
    } else if pr >= eighth && pr < quarter {
        score += 8.0;
    } else if pr == 0 {
        score -= 60.0; // perfect fit
    }

    // Harmonic bonus: residual divisible by common item sizes
    if pr % 10 == 0 && pr > 0 {
        score -= 12.0;
    }
    if pr % 20 == 0 && pr > 0 {
        score -= 8.0;
    }

    // Lookahead coupling: next item fits exactly into post residual
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size < pr {
            score -= 6.0;
        } else {
            score += 10.0; // next item won't fit here anyway
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make it moderately attractive only when open bins are crowded
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowding = (mean_residual / cap) - 0.3;
        score = cap as f64 * 0.5 + crowding * 50.0 - progress * 10.0;
        if next_item_size > 0 && next_item_size >= bin_residual {
            score -= 20.0;
        }
    }

    // Mild preference for tighter bins overall
    score += (mean_residual - post_residual as f64) * 0.15;
    score -= (bin_residual - item_size) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

