    // 2-step lookahead: reward if next item fits the post residual
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            // next item exactly fills this bin after current placement: excellent
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // next item still fits, but penalize leftover waste after both
            let two_step_waste = post_residual - next_item_size;
            score -= 100.0 - (two_step_waste as f64).min(100.0);
        } else {
            // next item won't fit: penalize creating dead space relative to next item
            let gap = next_item_size - post_residual;
