    }

    // New-bin candidate: penalize unless current open bins are crowded
    if bin_residual == bin_capacity {
        let crowding = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        score += 25.0 - crowding * 2.0;
        // still allow opening if lookahead won't fit anywhere nicely
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

