    // New-bin candidate handling: an empty bin should only win when the fit into
    // open bins is poor (large post_residual dead space) or few bins fit.
    if bin_residual == bin_capacity {
        // Base penalty so empty bins are not chosen for trivially good fits.
        score += 150.0;
        // Reward opening a new bin when current fit is bad and many items remain.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if post_residual > 50 {
            score -= 100.0 * (post_residual as f64 / 100.0) * (1.0 - progress * 0.5);
        }
        if fitting_bins_count == 0 {
            score -= 300.0;
        }
        // Late in the stream, avoid opening new bins (waste).
        if progress > 0.9 {
            score += 100.0 * progress;
        }
    }

    // Mild pressure to prefer bins with tighter residual when many bins are open.
    if open_bins_count > 4 {
        score += (bin_residual as f64) * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

