}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo arithmetic on capacity.
    // Perfect fits (residual 0) are heavily rewarded.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Classify dead space by integer-division thresholds on post_residual.
        // Small residuals (<10) are nearly unusable dead space -> penalize hard.
        if post_residual < 10 {
            score += 200.0;
        } else if post_residual < 20 {
            score += 80.0;
        }
        // Harmonic classes: residual mod capacity fraction buckets.
        // Residuals in "nice" classes (multiples of 10, matching typical item sizes)
        // are more likely to be filled by future items -> reward them.
        let class = post_residual % 10;
        if class == 0 {
            score -= 30.0;
        } else if class >= 5 {
            score -= 10.0;
        } else {
            score += 10.0;
        }
    }

    // Lookahead: does the next item fit exactly in the resulting residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            // Next item fits: reward proportionally to how well it fills.
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 50.0 + 100.0 * fill;
        } else {
            // Next item cannot use this residual: penalize proportional to leftover size.
            score += 0.5 * (post_residual as f64 - next_item_size as f64).abs();
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate handling: opening a new bin should only win when
    // no open bin offers a good fit. Give the fresh bin a mild penalty
    // so it's chosen only when all open bins score badly.
    if bin_residual == bin_capacity {
        score += 60.0 + mean_residual * 0.2;
    } else {
        // Slight reward for packing into bins with low mean residual overall.
        score -= (bin_residual as f64 - mean_residual) * 0.1;
    }

    // Progression: later in the stream, tighten up (prefer tight fits more).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 20.0 * (post_residual as f64 / bin_capacity as f64);

    // Prefer consolidating into fewer bins when many are open.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to be useful later
    // (but nonzero) are the worst outcome. Penalize them heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Reward very tight fits (almost-exact packing).
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead synergy: if the next item fits the post-residual, this placement
    // is doubly good.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
    }
    // If next item almost fits (off by a little), slight penalty for stranding it.
    if next_item_size > post_residual && next_item_size <= post_residual + 10 && next_item_size > 0 {
        score += 8.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing
    // bins rather than spreading; with few bins, new bins are cheaper.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln().max(0.0) * (2.0 + 3.0 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline is its post-residual (large). Nudge it down
        // when few bins are open (spreading is fine), push it up under pressure.
        score -= pressure * 0.5;
        score += mean_residual * 0.05;
    } else {
        score += pressure * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

