    // moves residuals toward balance (avoids one very-full bin + many loose bins)
    let post_f = post_residual as f64;
    let dev = post_f - mean_residual;
    score += 0.12 * dev.abs();

    // Prefer tighter fits generally
    score += 0.25 * (post_f / bin_capacity as f64) * 10.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

