        let poor_fit = post_residual as f64 > 55.0;
        if poor_fit || open_bins_count == 0 || (next_item_size > 0 && (next_item_size as f64) > post_f && post_f < 25.0) {
            score -= 20.0 + 30.0 * (1.0 - progress);
        } else {
            score += 15.0;
        }
    }

    // Mild penalty for very tiny residuals that likely become dead space
    if post_f > 0.0 && post_f < 10.0 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let is_new_bin = bin_residual == bin_capacity;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

