        score -= 5.0;
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 20.0;
    }

    // Many open bins: encourage consolidation into existing bins.
    score -= (open_bins_count as f64).ln().max(0.0) * 1.5;

    // If this bin's residual is well below the mean residual, it's a good
    // compaction target; if far above mean, it's a poor home for the item.
    if !is_new_bin {
        let diff = bin_residual as f64 - mean_residual;
        score += 0.15 * diff;
    }

    // New-bin candidate pricing: expensive baseline so it only wins when
    // every open-bin fit is genuinely bad (large post_residual + penalties).
    if is_new_bin {
        score += 35.0 + 10.0 * (1.0 - progress);
        // Opening a bin when few are open is cheaper than fragmenting many.
        score -= (open_bins_count as f64) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
