}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero gaps are the worst outcome.
    if post_residual > 0 {
        if post_residual < 10 {
            // Unusable sliver: heavy penalty.
            score += 25.0 + (10 - post_residual) as f64 * 2.0;
        } else if post_residual <= 20 {
            // Small gap: likely dead space unless future tiny items exist.
            score += 8.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 20.0;
    }

    // Reward leaving room for the lookahead item (k=2 lookahead).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else if post_residual > 0 {
            score += 4.0; // gap can't host next item
        }
    }

    // Tightness reward: fraction of bin consumed by this placement.
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= 10.0 * fill_frac;

    // Last-chance bin: strongly prefer using it over opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: penalize spreading across many bins when residuals are small;
    // encourage consolidation when mean residual is large.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
    score += 0.4 * pressure * (0.5 + progress);

    // Brand-new bin candidate: make it moderately attractive only when no
    // open bin offers a good fit (high mean residual spread / many slivers).
    if bin_residual == bin_capacity {
        score = 40.0
            + 2.0 * open_bins_count as f64
            - 0.15 * mean_residual
            - 10.0 * progress;
        // If this is a last chance elsewhere, opening new bin is bad.
        if fitting_bins_count == 1 {
            score += 30.0;
        }
        // If next item is huge, a fresh bin may be preferable.
        if next_item_size > 60 && post_residual == 0 {
            score -= 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual exactly matches
    // or can tightly hold the next item (perfect pairing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0; // perfect chain: bin fully consumed by two items
        } else if post_residual >= next_item_size {
            // reward tight-but-feasible pairing; tighter gap = better
            let gap = (post_residual - next_item_size) as f64;
            score -= 150.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item cannot follow here: penalize dead space, scaled by how
            // much space is wasted relative to next item
            let dead = (next_item_size - post_residual) as f64;
            score += 0.5 * dead;
        }
    }

    // Penalize residual far above the mean residual (leaving a lonely large hole
    // while other bins are tighter is usually wasteful)
    score += 0.3 * (post_residual as f64 - mean_residual).max(0.0);

    // Small residual is good in general (tight packing)
    if post_residual < 10 {
        score -= 50.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless fit is catastrophically bad).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: make empty bins attractive only when the item is large
    // (would leave little room anyway) or no bin fits well; otherwise discourage.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        if fill_ratio > 0.6 {
            score -= 120.0 * fill_ratio; // big item: fresh bin is fine
        } else {
            score += 80.0; // small item into fresh bin wastes capacity
        }
    }

    // Late in the stream: consolidate harder, avoid opening bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 100.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tightness reward: bins that become nearly full are heavily favored.
    let fill_ratio = 1.0 - (post_residual as f64) / cap;
    score -= 45.0 * fill_ratio * fill_ratio;

    // Perfect fit bonus (post residual small relative to item size).
    if post_residual <= 3 {
        score -= 60.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward;
    // if post-residual is a dead zone (too small for typical items), penalize.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (nxt - post_residual as f64).abs() <= 2.0 {
            score -= 35.0;
        } else if (post_residual as f64) < nxt && post_residual < 10 {
            score += 25.0; // dead space created
        } else if post_residual as f64 >= nxt {
            score -= 8.0 * (post_residual as f64 - nxt).tanh();
        }
    }

    // Last-chance bin: using the only fitting bin avoids opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: prefer keeping it closed unless current bins fit poorly.
    if bin_residual == bin_capacity {
        score += 20.0
            + 0.15 * open_bins_count as f64
            + (mean_residual / cap).max(0.0) * 10.0;
        // Late in the stream, consolidation matters more; opening new bins is worse.
        let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 30.0 * t;
        // If the item is large and would leave a big hole anyway, opening a fresh bin is fine.
        if item_size as f64 > 0.8 * cap {
            score -= 25.0;
        }
    }

    // Prefer bins with residuals close to the item (best-fit style) scaled by global mean.
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.5 * gap;
    if (bin_residual as f64) < mean_residual {
        score += 6.0; // tighter-than-average bins are precious; slight penalty
    }

    // Mild pressure to fill bins when many are open.
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let item_norm = item_size as f64 / cap;
    let next_norm = next_item_size as f64 / cap;

    let mut score = pr;

    // Smooth polynomial coupling: residual value decays non-linearly with stream progress
    score -= pr * (1.0 - progress) * (1.0 - progress) * 0.6;

    // Reward tight fits with a quartic term on normalized post-residual
    score -= 25.0 * (1.0 - pr_norm) * (1.0 - pr_norm) * (1.0 - pr_norm) * (1.0 - pr_norm);

    // Penalize dead space that cannot fit the lookahead item (smooth interaction)
    let unusable = (pr - next_norm * cap).max(0.0);
    score += 0.8 * unusable * (0.5 + progress);

    // Last-chance bonus: smooth ramp when few fitting bins remain
    let fit_term = (fitting_bins_count as f64).max(1.0);
    score -= 15.0 / (fit_term * fit_term);

    // Mild penalty for spreading across many open bins, growing with progress
    score += 0.15 * (open_bins_count as f64) * progress;

    // Encourage closing near-full bins relative to mean residual
    score -= 0.3 * (mean_residual - pr).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how it decomposes modulo common item sizes.
    // Residuals that are "harmonic" (divisible by / compatible with small sizes) are less dead.
    let pr = post_residual;
    if pr > 0 {
        // Dead space penalty: residual too small to hold anything meaningful (sizes >= 1..100 unknown,
        // but tiny slivers under ~10 are likely unusable).
        if pr < 10 {
            score += 60.0 * (10 - pr) as f64;
        }
        // Harmonic reward: post_residual divisible by small integers is reusable by many item classes.
        let mut harmony = 0.0;
        for m in [10u32, 20, 25, 50] {
            if pr % m == 0 {
                harmony += 15.0;
            }
        }
        if pr % 5 == 0 { harmony += 5.0; }
        score -= harmony;

        // Fractional-band logic: classify residual by capacity fractions.
        let frac = pr as f64 / cap;
        if frac > 0.5 {
            score -= 20.0; // half-full or better: healthy bin
        } else if frac > 0.25 {
            score -= 5.0;
        } else {
            score += 10.0; // quarter-slab: risky dead zone
        }

        // Integer division thresholds: can the residual host the next item exactly?
        if next_item_size > 0 {
            if pr >= next_item_size {
                if pr == next_item_size {
                    score -= 80.0; // perfect chaining: fills bin exactly with lookahead
                } else if pr % next_item_size == 0 {
                    score -= 40.0; // residual is a multiple of next item: perfect future packing
                } else {
                    score -= (pr - next_item_size) as f64 * 0.5;
                }
            } else {
                // next item cannot go here anyway; residual quality decides
                score += 15.0;
            }
        }
    } else {
        score -= 200.0; // exact fill: best possible outcome
    }

    // Tightness reward: item fills most of the current bin.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    if fill_ratio > 0.9 {
        score -= 50.0;
    } else if fill_ratio > 0.7 {
        score -= 25.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: only attractive late in the stream or when many bins are open
    // and this would consolidate; otherwise penalize spreading.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 70.0 - 60.0 * progress;
        if open_bins_count > 3 {
            score += 5.0 * open_bins_count as f64;
        }
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 30.0; // big lookahead: a fresh bin is a good host
        }
    }

    // Mild pressure toward consolidating into fewer bins when residuals are high.
    score -= 0.05 * mean_residual;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let is_new_bin = bin_residual == bin_capacity;

    // Dead-space penalty: small unusable gaps are worse than medium gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // tiny sliver: essentially dead space
    } else if post_residual < 25 {
        score += 25.0; // awkward gap that few items can use
    } else if post_residual <= 40 {
        score -= 10.0; // moderate gap still usable by small items
    }

    // Reward near-perfect fills strongly.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Last-chance bonus: if this is the only bin that fits, prefer it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly into the post_residual,
    // strongly favor this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 20.0 * (1.0 - slack / bin_capacity as f64);
    }
    // If next item would NOT fit here, mild penalty for creating a gap
    // that blocks the lookahead item.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 8.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins are
    // already open and have room (packing efficiency over bin count).
    if is_new_bin {
        let pressure = open_bins_count as f64 * 5.0
            + mean_residual * 0.5
            + (step_index as f64 / total_items.max(1) as f64) * 20.0;
        score += pressure;
    } else {
        // Mild reward for using existing bins as open count grows.
        score -= (open_bins_count as f64).sqrt() * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward when post_residual exactly matches next item (perfect 2-step chain)
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 100.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Slack left after hypothetically fitting the next item
        let slack = post_residual - next_item_size;
        score -= 30.0 - (slack as f64).min(30.0);
    } else if next_item_size > 0 {
        // Next item won't fit in residual: penalize proportional to wasted lookahead
        let miss = next_item_size - post_residual;
        score += miss as f64 * 0.5;
    }

    // Penalize residuals relative to mean residual (avoid creating outliers)
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bonus: if this is the only bin that fits, prefer it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize unless current residuals are all poor fits
    if bin_residual == bin_capacity {
        let tight = (100.0 - mean_residual).abs();
        score += 40.0 + tight * 0.2;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 15.0; // new bin useful if next item is bigger
        }
    }

    // Late in stream: consolidate, discourage new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 20.0;
    } else {
        score -= progress * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong preference for tight fits: reward small post_residual non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 3.0 * tightness * tightness * (item_size as f64);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: if the next item also fits in the post_residual, this bin is doubly valuable.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.5 * (next_item_size as f64);
    } else if next_item_size > 0 {
        // Penalize creating residual that is too small for the next item (dead space risk),
        // scaled by how close the wasted space is to being useless.
        let waste = post_residual as f64;
        if waste < next_item_size as f64 {
            score += 0.3 * (next_item_size as f64 - waste);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin gets a moderate penalty so it is only
    // chosen when every open bin would create bad dead space or is a poor fit.
    if bin_residual == bin_capacity {
        score += 12.0 + 0.15 * open_bins_count as f64;
        // Late in the stream, opening fresh bins is cheaper (less time to exploit them? no—
        // actually late stream: avoid fragmentation, prefer compacting into open bins).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 10.0 * progress;
    }

    // Global state coupling: if open bins are on average roomy, prefer filling them
    // rather than spreading; if mean residual is small, tighter bins matter more.
    score += 0.2 * (mean_residual - post_residual as f64).abs();

    // Penalize leaving residuals in the awkward 1..10 band (unusable for typical items).
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let prn = pr / cap;
    let p2 = progress * progress;
    let p3 = p2 * progress;
    // early stream: reward tight packing (low post residual); late stream: reward using open bins
    score -= prn * (1.0 - progress) * 30.0;
    score += prn * prn * (1.0 - progress) * 15.0;
    score -= prn * progress * 10.0;
    score += prn * p3 * 20.0;

    // reward filling bins nearly completely, smoothly
    let fill = 1.0 - prn;
    score -= fill * fill * fill * 12.0 * (0.5 + progress);

    // last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - prn * prn);
    }

    // penalize opening new bins when many open bins already exist
    score += (open_bins_count as f64).ln().max(0.0) * 3.0 * prn;

    // lookahead: reward residual that can still hold the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 8.0 * (1.0 - (pr - nx) / cap);
        } else {
            score += 6.0 * (nx - pr) / cap;
        }
    }

    // mean residual coupling: prefer bins near the mean residual
    let dev = (pr - mean_residual).abs() / cap;
    score += dev * dev * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space in "waste bands"
    let band = post_residual / 10;
    score += match band {
        0 => -30.0,                       // near-perfect fit
        1 => -15.0,                       // small gap, still useful
        2 | 3 => 0.0,                     // neutral mid gap
        4 | 5 => 8.0,                     // half-capacity gap: risky
        6 | 7 => 14.0,                    // large gap wasted
        _ => 20.0,                        // bin nearly empty after? bad reuse
    };

    // Modulo coupling: residual divisible into next item => reserve slot
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // can host next item too: reward strongly, scaled by leftover after
            let after2 = post_residual - next_item_size;
            score -= 18.0 + (after2 as f64).min(20.0) * 0.4;
            // exact harmonic pair: post_residual == next_item_size
            if after2 == 0 {
                score -= 25.0;
            }
        } else {
            // next item won't fit here: penalize if gap is "almost" fitting
            let miss = next_item_size - post_residual;
            if miss <= 10 {
                score += 10.0;
            }
        }
    }

    // Integer-division threshold classes of item_size (small/medium/large)
    let size_class = item_size / 25; // 0..=3
    score -= match size_class {
        0 => 6.0,        // small item: prefer filling leftover bins
        1 => 0.0,
        2 => -4.0,       // large item: any fit is valuable
        _ => -8.0,
    };

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 22.0;
    }

    // New-bin candidate: penalize opening unless current bin would leave bad gap
    if bin_residual == bin_capacity {
        score += 35.0;
        // allow new bin if item is huge (needs fresh space anyway)
        if item_size >= 60 {
            score -= 30.0;
        }
    }

    // Prefer tight residual relative to mean: tighter than average is good
    score += (mean_residual - bin_residual as f64) * 0.15;

    // Late-stream consolidation: favor existing bins as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0 - open_bins_count as f64 * 0.3;

    // Small tie-breaker on exact fill
    if post_residual == 0 {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let threshold = 10.0;
    if post_residual > 0 && post_residual < threshold {
        score += (threshold - post_residual as f64) * 12.0;
    }
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Reward leaving room for the lookahead item if it fits in the post-residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + next_item_size as f64 * 0.2;
    }
    // Penalize if post-residual can't fit the next item but is sizable waste.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 4.0;
    }

    // Last-chance bin: strong incentive to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Open-bin pressure: discourage opening new bins when many are already open.
    if bin_residual == bin_capacity {
        // Brand-new bin candidate.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 + 15.0 * progress + open_bins_count as f64 * 3.0;
    } else {
        score -= open_bins_count as f64 * 0.5;
    }

    // Mild coupling with mean residual: prefer bins below mean residual (tighter packs).
    score += (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward bins whose post-residual
    // can host the next item (chain packing), scaled by how tightly it fits.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let tightness = 1.0 - (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
            score -= 30.0 + 40.0 * tightness;
        } else {
            // next item won't fit here: slight penalty proportional to leftover gap
            score += 5.0 + 0.2 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Penalize large dead space (wasted residual unlikely to be reused)
    if post_residual < 10 {
        score -= 10.0; // near-perfect fill: excellent
    } else if post_residual < 20 {
        score -= 3.0;
    } else {
        score += 0.05 * (post_residual as f64 - 20.0);
    }

    // Prefer bins tighter than the mean residual (best-fit flavor)
    score += 0.3 * ((post_residual as f64) - mean_residual).max(0.0);
    score -= 0.1 * (mean_residual - post_residual as f64).max(0.0);

    // New-bin candidate: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 {
            0.0
        } else if fitting_bins_count == 1 {
            25.0
        } else {
            45.0
        };
        // Late in the stream, avoid opening bins even more.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 60.0 + desperation + 20.0 * progress;
    }

    // Last-chance bin: reward using it to avoid proliferation of open bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Mild preference for compact bin pools
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Strongly reward tight fits (small post-residual), with non-linear squashing.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space: residuals too small for typical future items are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a bin is expensive; make the empty-bin
    // candidate score poorly unless nothing fits well or the item is huge.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let poor_fit = post_residual as f64 > 60.0; // item tiny relative to fresh bin
        let mut penalty = 55.0;
        if poor_fit { penalty += 20.0; }
        // Late in the stream, closing out with new bins is more acceptable
        // (fewer future items to fill leftovers).
        penalty -= 25.0 * progress;
        // If many bins are open and mean residual is high, prefer reusing.
        penalty += 0.15 * open_bins_count as f64;
        penalty += 0.1 * mean_residual;
        // If the next item is large and this bin would be left nearly full,
        // a fresh bin helps the lookahead item.
        if next_item_size > 0 && next_item_size > post_residual {
            penalty -= 15.0;
        }
        score += penalty;
    } else {
        // Reuse bonus scaled by how many alternatives exist.
        score -= 5.0 + 2.0 * fitting_bins_count.min(5) as f64;
    }

    // Lookahead coupling: if the next item fits exactly into the post-residual,
    // reward heavily (perfect chaining).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size < 10 {
            score -= 15.0;
        }
    }

    // Mild time-horizon shaping: early on, prefer conservative (balanced) fills
    // relative to mean residual; late, prefer aggressive packing.
    score += 0.05 * (post_residual as f64 - mean_residual) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on (progress ~ 0): mild penalty on large residuals -> prefer tight fills.
    // Late (progress ~ 1): strongly reward small post_residual (tight packing).
    let base = pr * (1.0 + 2.0 * progress * progress);

    // Cubic dead-space term: heavily penalize residuals that are hard to fill later.
    let dead = 6.0 * norm_pr * norm_pr * norm_pr * cap * (0.3 + 0.7 * progress);

    // Reward bins that can also fit the next item (lookahead synergy).
    let mut score = base + dead;
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 4.0 * (1.0 + progress);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 + progress);
    }

    // New-bin candidate: make it attractive only when open bins would leave bad fits.
    if bin_residual == bin_capacity {
        // Empty bin gets neutral-ish score based on mean residual pressure.
        score = cap * (0.5 + 0.5 * progress) + (mean_residual - pr).abs();
    }

    // Mild penalty for spreading across many open bins.
    score += 0.05 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: small post_residual classes are
    // "dead space" zones; large ones are reusable. Use modulo classes on 10.
    let pr = post_residual;
    let pr_class = pr % 10;

    // Penalize residuals that fall into awkward low-value zones (1..=9 minus
    // exact divisors of capacity fractions). Reward residuals divisible by 25/50.
    if pr == 0 {
        score -= 40.0; // perfect fill
    } else if pr <= 9 {
        // dead space: the smaller, the worse; mod class refines granularity
        score += (10 - pr) as f64 * 2.5 + (pr_class as f64) * 0.3;
    } else if pr <= 20 {
        score += (20 - pr) as f64 * 0.6;
    } else {
        // reusable zone: reward proportionally, with bonus for harmonic sizes
        if pr % 50 == 0 {
            score -= 12.0;
        } else if pr % 25 == 0 {
            score -= 6.0;
        } else if pr % 10 == 0 {
            score -= 3.0;
        }
    }

    // Lookahead coupling: if the next item fits exactly in post_residual,
    // strongly reward this bin (chain fill).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size < pr {
            let nxt_post = pr - next_item_size;
            // reward small residual after the hypothetical next placement,
            // using harmonic class of nxt_post
            if nxt_post == 0 {
                score -= 20.0;
            } else if nxt_post <= 9 {
                score -= 5.0 - nxt_post as f64 * 0.4;
            } else if nxt_post % 25 == 0 || nxt_post % 50 == 0 {
                score -= 4.0;
            }
        } else {
            // next item cannot follow in this bin: mild penalty scaled by
            // how much it overshoots (integer division threshold classes)
            let over_class = (next_item_size - pr) / 20; // 0..=4
            score += over_class as f64 * 2.0;
        }
    }

    // Last-chance bin logic: if this is the only fitting bin, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate handling: an empty bin has high post_residual; make it
    // competitive only when the item is large relative to capacity or when the
    // stream is early (spread load for future flexibility).
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / bin_capacity as f64;
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = score.max(0.0) + 55.0 - frac * 60.0 - (1.0 - progress) * 10.0;
        if open_bins_count == 0 {
            score -= 100.0; // must open the first bin
        }
    }

    // Mild global pressure: prefer tighter bins when many bins are open.
    score += mean_residual * 0.05 - (bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual below the minimum item size (1) is impossible, but residuals
    // that are too small to host typical items create dead space.
    let dead_threshold = 10.0f64;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 25.0; // harsh penalty
    }
    // Perfect fit: strongly reward zero post_residual.
    if post_residual == 0 {
        score -= 60.0;
    }
    // Reward tight fits proportionally: item fills most of the bin.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    if fill_ratio > 0.8 {
        score -= 20.0 * (fill_ratio - 0.8) / 0.2;
    }

    // Dead space relative to bin: large leftover gaps in a mostly-full bin
    // are less harmful than in a nearly-empty bin.
    let residual_ratio = post_residual as f64 / bin_capacity as f64;
    score += residual_ratio * residual_ratio * 30.0;

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than opening new ones.
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when few bins fit the item
        // or all open bins would leave terrible dead space.
        let pressure = open_bins_count as f64;
        let last_chance_bonus = if fitting_bins_count <= 1 { -80.0 } else { 0.0 };
        score += 40.0 + pressure * 4.0 + last_chance_bonus;
    } else {
        // Existing bin: reward being chosen among few fitting bins.
        if fitting_bins_count == 1 {
            score -= 15.0; // last chance bin: use it or lose it
        }
        // Prefer bins whose residual is close to what we consume (good fit).
        let fit_gap = (bin_residual as f64 - item_size as f64).abs();
        score += fit_gap * 0.2;
    }

    // Lookahead: if the next item fits into post_residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 25.0;
    }
    // If next item is close to post_residual (near-perfect chain), extra reward.
    if next_item_size > 0 {
        let chain_gap = (post_residual as f64 - next_item_size as f64).abs();
        if chain_gap <= 5.0 {
            score -= 15.0;
        }
    }

    // Mild preference to keep mean residual balanced: avoid emptying one bin
    // while others stay full (helps future compaction).
    score += (post_residual as f64 - mean_residual).abs() * 0.1;

    // Late in the stream, tighten packing further (less slack for waste).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead matching.
    if next_item_size > 0 {
        // Perfect match: post_residual exactly fits the next item.
        if post_residual == next_item_size {
            score -= 200.0;
        } else if post_residual > next_item_size {
            // Next item fits with some slack left; reward closeness of match.
            let slack = (post_residual - next_item_size) as f64;
            score -= 150.0 - slack.min(150.0);
        } else {
            // Next item does NOT fit: leftover is dead space for the lookahead.
            let miss = (next_item_size - post_residual) as f64;
            score += miss * 1.5;
        }
    } else {
        // Last item: just minimize post_residual.
        score += 0.0;
    }

    // Penalize creating tiny unusable residuals (dead space < typical min item).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: make opening a new bin attractive only when the current
    // fit is poor (large post_residual) or no tight option exists.
    if bin_residual == bin_capacity {
        // Neutral base for a fresh bin; lookahead mismatch makes it relatively worse.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 40.0; // fresh bin can serve next item well
        }
        score += 25.0; // slight default bias toward reusing existing bins
    }

    // Context: prefer tightening bins when many are open and mean residual is high.
    if open_bins_count > 3 && (mean_residual - post_residual as f64) > 0.0 {
        score -= (mean_residual - post_residual as f64) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strong preference for small post_residual (best-fit core).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize leaving dead space that likely cannot fit a future item.
    if post_residual > 0 {
        // typical item scale ~ half capacity; residual below ~10 is near-useless
        let dead = if (post_residual as f64) < 0.12 * bin_capacity as f64 { 12.0 } else { 0.0 };
        score += dead;
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // reward heavily; if next item cannot fit post-residual but fits mean residual
    // elsewhere, mild penalty for wasting this bin's space.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let chain_fit = 1.0 - ((post_residual - next_item_size) as f64) / (bin_capacity as f64);
            score -= 10.0 + 8.0 * chain_fit;
        } else {
            score += 3.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0 + 0.05 * (post_residual as f64);
    }

    // New-bin candidate logic: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a bin (each bin costs 100 units of space).
        score += 55.0;
        // Cheap to open a bin when few bins are open (early stream) or when
        // mean residual across open bins is small (poor fits everywhere).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 25.0 * (1.0 - progress);
        score -= 0.4 * mean_residual.min(60.0);
        if fitting_bins_count == 0 {
            score -= 70.0; // no alternative: opening is fine
        }
        // If the current item fills the new bin almost fully, reward.
        if item_size as f64 > 0.8 * bin_capacity as f64 {
            score -= 20.0;
        }
    } else {
        // Reward using existing bins more when many are open (bin-count pressure).
        score -= (open_bins_count as f64).ln().max(0.0) * 2.0;
        // Slight preference for bins whose residual is below mean (consolidate emptier space).
        if (bin_residual as f64) < mean_residual {
            score -= 2.0;
        } else {
            score += 2.0;
        }
    }

    // Time horizon: late in the stream, closing gaps matters more -> stronger
    // tightness pressure and higher cost for new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 15.0 * progress * tightness;
    if is_new_bin {
        score += 30.0 * progress * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64) / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap;

    // Base: post-residual, with smooth polynomial shaping of dead-space penalty
    let mut score = pr as f64;

    // Non-linear coupling: residual squared/quartic terms weighted by progress
    let quad = x * x;
    let quart = quad * quad;
    score += (0.6 + 0.8 * progress) * quad * cap
           - (0.4 * (1.0 - progress)) * quart * cap;

    // Favor tight fits: subtract when post_residual is small relative to item
    let tightness = 1.0 - x;
    score -= 12.0 * tightness * tightness * (0.5 + progress);

    // Last-chance bonus: strongly reward using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (0.5 + progress);
    } else if fitting_bins_count > 1 {
        // mild competition penalty scaled by number of alternatives
        score += 2.0 * ((fitting_bins_count as f64) - 1.0).ln();
    }

    // Lookahead: penalize if next item cannot use the post-residual
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx > pr as f64 {
            score += 8.0 * (1.0 - progress) * (nx - pr) / cap;
        } else {
            score -= 6.0 * (pr - nx) / cap * (0.3 + 0.7 * progress);
        }
    }

    // Penalize bins far from mean residual (keep residuals homogeneous)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // New-bin candidate: discourage unless residual is large / stream early
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - progress) - 6.0 * progress;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: reward residuals that are "harmonious"
    // with common item sizes (multiples of 10 or small remainders divisible by 5),
    // penalize awkward dead space classes.
    let pr = post_residual;
    let class = pr % 10;
    match class {
        0 => score -= 8.0,               // perfectly reusable residual
        2 | 8 => score -= 1.5,           // fits small items (<= 10) with margin
        5 => score -= 4.0,               // half-class residual, decent reuse
        1 | 9 => score += 3.0,           // nearly useless slivers
        _ => score += 1.0,               // generic dead space
    }

    // Integer-division threshold on post_residual: buckets of capacity fractions.
    let frac = pr as f64 / bin_capacity as f64;
    if frac > 0.5 {
        score -= 5.0; // bin still half-full after placement: good compaction
    } else if frac > 0.25 {
        score -= 1.0;
    } else if pr > 0 {
        score += 4.0; // tiny residual: bin nearly wasted
    }

    // Coupling with next item (lookahead): reward residuals that can host next_item_size.
    if next_item_size > 0 {
        if pr >= next_item_size {
            // Exact or near-exact fit for the lookahead item is excellent.
            let gap = pr - next_item_size;
            if gap == 0 {
                score -= 12.0;
            } else if gap <= 5 {
                score -= 7.0;
            } else {
                score -= 3.0 * (1.0 - gap as f64 / bin_capacity as f64);
            }
        } else {
            // Post-residual too small for next item: penalize proportionally.
            score += 2.0 + (next_item_size - pr) as f64 / 10.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // (large item relative to mean residual) or stream is early.
    if bin_residual == bin_capacity {
        let pressure = item_size as f64 / mean_residual.max(1.0);
        if fitting_bins_count == 0 || pressure > 0.9 {
            score -= 6.0;
        } else {
            score += 15.0; // discourage opening new bins when open bins suffice
        }
    }

    // Mild stream-progression term: later in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 2.0 * progress * (bin_residual < bin_capacity) as i32 as f64;

    // Prefer bins tighter than the mean residual (best-fit flavor).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps of 1..=9 are nearly unusable
    // (min item size is 1, but small gaps rarely match future items).
    if post_residual > 0 && post_residual <= 9 {
        score += 25.0 + (10 - post_residual as i32) as f64 * 3.0;
    }
    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward leaving gaps that the lookahead item can exactly fill.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 18.0;
        } else if post_residual > next_item_size {
            score += 4.0; // mild preference to keep room for next item
        }
    }

    // Open-bin pressure: discourage scattering across many bins,
    // but relax pressure when this is the last fitting bin.
    let pressure = (open_bins_count as f64).ln().max(0.0) * 6.0;
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= pressure; // last chance: strongly prefer using this bin
    } else {
        score += pressure * 0.5;
    }

    // Prefer bins tighter than the mean residual (good packing).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate: only attractive when existing fits are poor
    // (large dead space would be created) or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let waste_penalty = if post_residual > 0 && post_residual <= 9 { 40.0 } else { 0.0 };
        score = 55.0 + waste_penalty - progress * 10.0;
        if fitting_bins_count > 1 {
            score += 20.0; // other options exist, deprioritize new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: this bin's post residual exactly fits the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Near-perfect match: next item fits with small slack.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 - slack.min(40.0);
    }
    // Dead space: post residual too small for the next item.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 30.0;
    }

    // Reward tight fits relative to mean residual.
    if (post_residual as f64) < mean_residual {
        score -= (mean_residual - post_residual as f64) * 0.5;
    } else {
        score += (post_residual as f64 - mean_residual) * 0.3;
    }

    // Last chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New empty bin candidate: only attractive if no open bin gives a good fit
    // (e.g. item is large / residual unusable). Otherwise penalize heavily.
    if bin_residual == bin_capacity {
        score += 500.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 150.0;
        }
        if item_size > bin_capacity / 2 {
            score -= 100.0;
        }
        // Late in the stream, prefer filling existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 100.0;
    }

    // Prefer more-filled bins overall.
    score -= (bin_residual as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post_residual quadratically.
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 60.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // relative to residual or the fit in open bins is poor.
    if bin_residual == bin_capacity {
        score += 35.0;
        // Opening a bin is more attractive early (long horizon ahead) and
        // when the item is big (leaves useful residual for future items).
        let t = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - t) * 12.0;
        score -= (item_size as f64 / bin_capacity as f64) * 15.0;
        // If many bins are open, discourage proliferation.
        score += open_bins_count as f64 * 1.5;
    }

    // Lookahead: if the next item fits exactly into post_residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size < post_residual {
            // Mild reward if next item still fits after this placement.
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize leaving small unusable gaps
            // that are smaller than the minimum plausible item.
            if post_residual < next_item_size {
                score += 8.0;
            }
        }
    }

    // Prefer bins with residual below the mean (compact near-full bins),
    // keeping larger-residual bins available for future large items.
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += dev * 25.0;

    // Late in the stream, prioritize closing bins tightly.
    let t = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * t * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with non-linear shaping
    let mut score = pr;

    // Polynomial coupling: post_residual^2 scaled by progress
    // Early in stream: mild penalty for waste; late: strong penalty (close bins tightly)
    let p2 = pr * pr / (cap * cap);
    score += p2 * (0.5 + 2.0 * progress) * cap * 0.2;

    // Cubic dead-space penalty when post_residual is small but unusable (< typical item)
    let dead = if pr < 10.0 { 0.0 } else if pr < item_size as f64 { (10.0 - pr / item_size as f64).max(0.0) } else { 0.0 };
    score -= dead * 3.0;

    // Lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 && (pr as u32) >= next_item_size {
        score -= 8.0 * (1.0 - (pr - next_item_size as f64) / cap);
    } else if next_item_size > 0 {
        score += 4.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: open fresh bins early, discourage late in the stream
    if bin_residual == bin_capacity {
        let open_pressure = (open_bins_count as f64).ln().max(0.0);
        score += 15.0 + open_pressure * (2.0 + 6.0 * progress) - 10.0 * (1.0 - progress);
    }

    // Coupling with mean residual: prefer bins close to the mean (balanced packing)
    let dev = (pr - mean_residual).abs() / cap;
    score += dev * dev * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: capacity fractions / integer division thresholds.
    // Classes: 0 (perfect), <=10 (excellent), <=25 (good), <=50 (mediocre), >50 (bad dead space).
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    if post_residual == 0 {
        score -= 1000.0; // perfect fit: always take it
    } else if post_residual <= 10 {
        score -= 60.0;
    } else if post_residual <= 25 {
        score -= 25.0;
    } else if post_residual <= 50 {
        score -= 5.0;
    } else {
        score += 20.0; // leaving more than half a bin empty is wasteful
    }

    // Modulo-arithmetic coupling: post_residuals that are "harmonic" with common
    // item sizes (multiples of 5/10) are more likely to be filled later.
    let harmonic = (post_residual % 10 == 0) as i32 as f64 * 8.0
        + (post_residual % 5 == 0) as i32 as f64 * 4.0;
    score -= harmonic;

    // Lookahead: reward if the next item fits exactly or well into post_residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        if gap == 0.0 {
            score -= 120.0; // next item fills this bin perfectly
        } else if gap <= 10.0 {
            score -= 40.0;
        } else {
            score -= 15.0 * (1.0 - gap / cap);
        }
    } else if next_item_size > post_residual {
        // next item can't use this residual; penalize proportionally to residual size
        score += 0.15 * pr;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless post_residual is huge waste).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
        if post_residual > 50 {
            score += 45.0; // but avoid dumping into near-empty bin creating dead space
        }
    }

    // New empty bin candidate: only attractive when no good fit exists among open bins.
    if bin_residual == bin_capacity {
        score += 55.0; // default: prefer existing bins
        // but if open bins are mostly full (low mean residual), a fresh bin is fine
        score -= (mean_residual / cap) * 40.0;
        // early stream: opening bins early is cheap and builds flexibility
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 15.0;
        // if next item is large, a fresh bin gives room
        if next_item_size >= 60 {
            score -= 30.0;
        }
    }

    // Slight preference for fuller bins overall (best-fit flavor beyond post_residual).
    score -= (bin_residual as f64 / cap) * 5.0;

    // Crowding: with many open bins, consolidate into already-open bins rather than
    // spreading out; with few bins, spreading is less costly.
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * (pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // unusable sliver
    } else if post_residual == 0 {
        score -= 30.0; // perfect fill
    } else if post_residual <= 20 {
        score += 12.0; // awkward small gap
    }

    // Reward tight fits relative to bin size.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 20.0 * fill_ratio;

    // Pressure from number of open bins: prefer consolidation when many bins open.
    score += (open_bins_count as f64) * 1.5;

    // Prefer bins whose residual is already near the mean (keep residuals uniform).
    score += ((bin_residual as f64) - mean_residual).abs() * 0.3;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when the item is huge or fit is bad elsewhere.
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64) * 2.0;
        let waste = (bin_capacity - item_size) as f64;
        score = waste + pressure + 15.0;
        // Big items open fresh bins more readily.
        if item_size >= 60 {
            score -= 20.0;
        }
        // Lookahead: if next item is small, opening a new bin wastes capacity.
        if next_item_size > 0 && next_item_size <= 20 {
            score += 25.0;
        }
    } else {
        // Lookahead: reward leaving room for the next item.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
        // Penalize leaving a gap that neither fits next item nor is useful.
        if next_item_size > 0 && post_residual < next_item_size && post_residual < 25 {
            score += 15.0;
        }
    }

    // Early in stream: be more conservative about fragmenting space.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 5.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio;

    // Aggressive 2-step lookahead: strongly reward bins whose post_residual
    // can host the next item (chained packing).
    if next_item_size > 0 && next_item_size <= post_residual {
        let next_fit = next_item_size as f64 / post_residual as f64;
        score -= 20.0 * next_fit;
    } else if next_item_size > 0 {
        // Penalize dead space the next item cannot use, scaled by how close
        // post_residual is to being useful.
        let waste = (post_residual as f64 - (next_item_size as f64 - post_residual as f64).max(0.0)) / bin_capacity as f64;
        score += 8.0 * waste;
    }

    // Last-chance bin: heavily favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Reward bins with residual above the mean (consume slack where it exists),
    // penalize dipping into already-tight bins.
    score -= 4.0 * ((bin_residual as f64 - mean_residual) / bin_capacity as f64);

    // Mild pressure to consolidate as the stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * fit_ratio;

    // New-bin candidate: only attractive when current bin's leftover is tiny
    // dead space and next item is large.
    if bin_residual == bin_capacity {
        score += 10.0;
        if next_item_size > 0 && post_residual < next_item_size as u32 && post_residual < 15 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits: penalize when post_residual is small relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 2.5 * tightness * tightness * (item_size as f64);

    // Perfect fit gets a big bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Penalize leaving dead space that cannot plausibly fit future items.
    if post_residual > 0 && next_item_size > 0 {
        let next_fits = (post_residual as u32) >= next_item_size;
        if next_fits {
            // Reward leaving room exactly sized for the next item.
            let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
            score -= 8.0 * (1.0 - gap / (bin_capacity as f64));
        } else {
            // Dead space: penalize proportionally to how much is wasted.
            score += 6.0 + 0.15 * (post_residual as f64);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Many fitting bins: mild penalty to encourage diversity / keep larger residuals free.
    if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64 - 1.0);
    }

    // Global state: when open bins are mostly empty (high mean residual), prefer filling them
    // rather than opening new bins.
    let mean_frac = mean_residual / (bin_capacity as f64);
    if bin_residual < bin_capacity {
        score -= 4.0 * mean_frac;
    }

    // New-bin candidate handling: only attractive when open bins are quite full or none exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = mean_frac * (open_bins_count as f64).ln().max(1.0);
        // High pressure -> new bin expensive; low pressure -> new bin cheap.
        score += 25.0 + 30.0 * pressure - 10.0 * progress;
        // If next item is large, opening a fresh bin early is less bad.
        if next_item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 8.0;
        }
    }

    // Discourage wasting large residual bins on small items.
    if (item_size as f64) < 0.35 * (bin_residual as f64) {
        score += 5.0 * (1.0 - (item_size as f64) / (bin_residual as f64));
    }

    // Mild time-horizon coupling: early in the stream, be conservative about fragmentation.
    let t = step_index as f64 / (total_items.max(1) as f64);
    score += 3.0 * (1.0 - t) * (post_residual as f64) / (bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let prog2 = progress * progress;
    let prog3 = prog2 * progress;
    let coupling = norm_pr * (1.0 + 2.0 * progress + 3.0 * prog2 + 1.5 * prog3);
    score += 20.0 * coupling;

    // Penalize wasted residual more as stream progresses (dead space matters more later)
    let waste = norm_pr * norm_pr;
    score += 15.0 * waste * (0.5 + progress);

    // Reward tight fits (small post_residual) with smooth decay
    let tightness = (-norm_pr * 4.0).exp();
    score -= 10.0 * tightness * (1.0 + progress);

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Lookahead: penalize if post_residual can't fit next item but bin_residual could
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt && bin_residual as f64 >= nxt {
            score += 8.0 + 6.0 * progress;
        }
        // Reward leaving residual that still fits the next item
        if pr >= nxt && pr < nxt * 2.0 {
            score -= 5.0;
        }
    }

    // Mild penalty for many open bins relative to progress (encourage consolidation early)
    let open_norm = open_bins_count as f64 / (total_items.max(1) as f64).sqrt();
    score += 2.0 * open_norm * (1.0 - progress);

    // Deviation from mean residual: prefer bins near the mean to keep balance
    score += 0.5 * (pr - mean_residual).abs();

    // New-bin candidate: penalize opening a new bin unless current residuals are poor
    if bin_residual == bin_capacity {
        let mean_bad = (mean_residual / cap).max(0.0).min(1.0);
        score += 30.0 - 20.0 * mean_bad * (1.0 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: best-fit preference (small post_residual wins).
    score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls in a "useful"
    // residue class (able to host common small items) are rewarded.
    // Class by integer division into deciles of capacity.
    let decile = post_residual / (bin_capacity / 10);
    let decile_f = decile as f64;

    // Reward mid-small leftovers that still fit typical items; penalize
    // dead-space classes (very small but nonzero leftovers).
    if post_residual > 0 {
        if post_residual < 10 {
            // dead space: nearly unusable
            score += 25.0;
        } else if post_residual <= 30 {
            // sweet spot: hosts next small items
            score -= 12.0;
        } else if post_residual <= 50 {
            score -= 4.0;
        } else {
            // large leftover: bin was "wasted" on a small item
            score += 8.0 + decile_f;
        }
    } else {
        // perfect fill
        score -= 30.0;
    }

    // Harmonic coupling with lookahead: if next item fits exactly into
    // post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            if gap == 0 {
                score -= 28.0;
            } else if gap < 10 {
                score -= 15.0;
            } else {
                score -= (10.0_f64).min(gap as f64 / 4.0);
            }
        } else {
            // next item cannot follow here: mild penalty scaled by closeness
            let miss = (next_item_size - post_residual) as f64;
            score += (15.0_f64).min(miss / 3.0);
        }
    } else {
        // last item: prefer exact fill
        score -= post_residual as f64 * 0.5;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only open a new bin when current bins are
    // fragmented or the item is large relative to residuals.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual - bin_residual as f64).abs();
        // Prefer new bin when open bins have small mean residual and item is big.
        let pressure = item_size as f64 / bin_capacity as f64;
        let new_bin_bonus = 35.0 * pressure
            + (mean_residual / bin_capacity as f64) * 20.0
            + open_bins_count as f64 * 0.5
            + progress * 5.0;
        score = bin_capacity as f64 - new_bin_bonus + fragmentation * 0.1;
        // Never open a new bin if a decent fit exists elsewhere.
        if mean_residual >= item_size as f64 + 15.0 {
            score += 60.0;
        }
    }

    // Mild normalization: prefer bins below mean residual (tighter packing).
    score += (bin_residual as f64 - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress factor: early in the stream we can afford to open bins / be picky.
    let progress = step_index as f64 / (total_items.max(1) as f64);

    // --- Strict dead-space avoidance ---
    // A gap is "unusable" if it is smaller than the smallest plausible item (1)
    // but more importantly smaller than the lookahead item or a small item (~10).
    let small_item_floor = 10u32.min(bin_capacity);
    if post_residual == 0 {
        // Perfect fill: strong reward.
        score -= 60.0;
    } else if post_residual < small_item_floor {
        // Tiny dead gap: nothing useful can ever go in here -> heavy penalty.
        score += 35.0 * (1.0 - 0.5 * progress);
    } else if post_residual < next_item_size && next_item_size > 0 {
        // Gap can't hold the next item: partially wasted space.
        score += 12.0;
    } else {
        // Usable gap: mild reward proportional to how well it matches the next item.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 3.0 + 6.0 * (next_item_size as f64 / post_residual as f64).min(1.0);
        }
    }

    // --- Tight fit reward: fraction of bin consumed ---
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill;

    // --- Open bins pressure: penalize spreading across many bins ---
    score += (open_bins_count as f64) * (1.5 + 2.0 * progress);

    // --- Mean residual coupling: prefer bins already below mean residual
    // (i.e., this bin is tighter than average -> keep loose bins for future items).
    score += (post_residual as f64 - mean_residual) * 0.25;

    // --- Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * progress;
    }

    // --- New-bin candidate handling: bin_residual == bin_capacity means a
    // fresh empty bin. Only attractive when the item is large or the fit in
    // existing bins would be terrible.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        // Base penalty so open bins are preferred for small/medium items.
        score += 20.0;
        // Reward opening a new bin for large items (they fill fresh capacity well).
        score -= 45.0 * large_item;
        // If no open bin fits well (few fitting bins), opening a bin is fine.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Aggressive 2-step lookahead matching ---
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let pr = post_residual as f64;

        // Perfect 2-chain: next item exactly fills the post residual.
        if (post_residual as u32) == next_item_size {
            score -= 60.0;
        }
        // Near-perfect chain: next item fits with small leftover.
        else if next_item_size <= post_residual {
            let leftover = pr - nx;
            score -= 40.0 - 0.8 * leftover;
        }
        // Next item does NOT fit in this residual: dead space unless residual is tiny.
        else {
            score += 0.5 * (nx - pr);
        }
    } else {
        // Last item: any residual is terminal waste; prefer tightest fill.
        score += 0.2 * post_residual as f64;
    }

    // --- Relative-to-mean-residual coupling ---
    // Bins with residual below the mean are "tight" -> favor them (reduce score).
    let tightness = mean_residual - post_residual as f64;
    score -= 0.6 * tightness;

    // --- Last-chance pressure ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when no open bin offers a good chain,
        // i.e. when the best post-residual would be large relative to capacity.
        // Base cost of a fresh bin: its full residual.
        score = bin_capacity as f64 - 30.0;
        if next_item_size > 0 {
            // A fresh bin can always chain with the next item if it fits.
            if next_item_size <= bin_capacity - item_size {
                score -= 35.0;
            }
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 40.0 * progress;
        // Few open bins -> opening is cheap; many open bins -> prefer using them.
        score += 5.0 * open_bins_count as f64;
    }

    // Small tie-break: prefer lower post-residual with finer granularity.
    score += 0.05 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize very small dead space that is hard to fill later (avoid residuals < ~10)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (10.0 - post_residual as f64) / 10.0;
    }

    // Reward tight fits strongly
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 15.0 * fit_ratio * fit_ratio;

    // Perfect fill bonus
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item exactly fits the post-residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            let gap = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - gap / post_residual as f64);
        } else {
            // next item won't fit here; slight penalty proportional to wasted potential
            score += 5.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        }
    }

    // Time horizon: early in stream, be conservative (prefer filling existing bins);
    // late in stream, closing bins tightly matters more
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * fit_ratio;

    // If many bins are open with slack, prefer consolidating into bins below mean residual
    if open_bins_count > 1 {
        if (bin_residual as f64) < mean_residual {
            score -= 4.0;
        } else {
            score += 4.0;
        }
    }

    // New-bin candidate: make it attractive only when no good fit exists.
    // Empty bin has post_residual = capacity - item_size; penalize it moderately
    // so open bins with reasonable fits win, but allow it when fits are poor.
    if bin_residual == bin_capacity {
        score += 20.0;
        // If this is the only fitting option (no open bins fit), the last-chance
        // logic doesn't apply; reduce penalty so new bin can win.
        if fitting_bins_count <= 1 {
            score -= 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post residual, with smooth polynomial shaping
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Polynomial coupling with stream progress: early on tolerate larger residuals,
    // late in the stream penalize them more strongly (quadratic in progress).
    let progress_coupling = pr * (0.8 * progress + 1.2 * progress * progress);
    score += progress_coupling;

    // Smooth interaction: dead-space penalty grows when residual is near mid-range
    // (least useful space), modeled with a concave polynomial term.
    let mid = norm_pr * (1.0 - norm_pr); // peaks at 0.5 residual
    score += 30.0 * mid * mid * (0.5 + progress);

    // Reward tight fits smoothly
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fit_ratio * fit_ratio * (1.0 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 40.0 + 20.0 * progress;
    }

    // Lookahead: reward if next item fits into post residual (smooth kernel)
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        let fits = if pr >= next_item_size as f64 { 1.0 } else { 0.0 };
        score -= 15.0 * fits * (1.0 - gap / cap).max(0.0);
    }

    // Mild bonus for bins with below-mean residual (consolidate fuller bins)
    if pr < mean_residual {
        score -= 5.0 * (mean_residual - pr) / cap;
    }

    // Slight penalty for spreading across too many open bins
    score += 0.5 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit: perfect placement, strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: dead space analysis.
    // Residuals that are "useful" (can hold common small items) are less penalized.
    let useful = if post_residual >= 10 && post_residual <= 80 { 1.0 } else if post_residual > 0 { 0.4 } else { 0.0 };
    score -= useful * 15.0;

    // Modulo-10 class: residuals that are multiples of 10 tend to pair well
    // with integer item sizes in [1,100] streams.
    if post_residual % 10 == 0 {
        score -= 12.0;
    } else if post_residual % 5 == 0 {
        score -= 5.0;
    }

    // Can the lookahead item fit into the post-residual? Chain reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0;
        // Extra reward for near-exact chained fit.
        let chain_slack = post_residual - next_item_size;
        if chain_slack <= 5 {
            score -= 25.0;
        }
    }

    // Dead space penalty: residual too small for typical items (1..100 unknown,
    // but small residuals < 10 are likely waste).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Prefer reusing open bins unless the item fits poorly everywhere.
    if bin_residual == bin_capacity {
        // Neutral base for a new bin; add mild penalty so tight fits in
        // existing bins win, but remove it when existing fit creates waste.
        score += 25.0;
        // Late in the stream, opening fresh bins is safer for future items.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= progress * 10.0;
    }

    // Prefer filling bins that are already low (tight packing): lower residual
    // before placement is better.
    score += (bin_residual as f64 / bin_capacity as f64) * 20.0;

    // Deviation from mean residual: prefer bins tighter than average.
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Large items: encourage placing them in bins with enough room so that
    // leftover stays usable (>= next typical small item).
    if item_size >= 50 && post_residual > 0 && post_residual < 20 {
        score += 20.0;
    }

    // Many open bins: encourage consolidation into existing bins.
    if open_bins_count > 4 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for the smallest item (1) are fine,
    // but residuals in the awkward small band (1..=15) can trap future items.
    let pr = post_residual as f64;
    if post_residual > 0 && post_residual <= 15 {
        // Unusable dead space: heavily penalize proportionally to how "wasted" it is.
        score += (16.0 - pr) * 6.0;
    } else if post_residual > 15 && post_residual <= 40 {
        // Semi-usable gap: moderate penalty scaled by residual size.
        score += pr * 0.35;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 40.0;
    } else {
        // Large usable residual: mild reward.
        score -= 5.0;
    }

    // Tight-fit reward: fraction of bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 15.0;

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin should only win when open bins
    // offer poor fits. Give it a baseline cost plus pressure from open bins.
    if bin_residual == bin_capacity {
        score += 10.0 + open_bins_count as f64 * 2.0;
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 8.0;
    }

    // Lookahead: if next item fits exactly into the post residual, reward this placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            score -= 6.0;
        }
    }

    // Mean-residual coupling: prefer bins near the mean residual (keeps balance),
    // penalize outliers far from the mean.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.08;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly fits the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    // Near-match: next item leaves a small leftover after being placed.
    if next_item_size > 0 && next_item_size <= post_residual {
        let two_step_leftover = post_residual - next_item_size;
        if two_step_leftover <= 10 {
            score -= 50.0 - (two_step_leftover as f64) * 4.0;
        }
        // Slight reward whenever next item can also fit here.
        score -= 5.0;
    }

    // Penalize post_residual that can't accommodate the next item (dead space risk).
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Small post_residual is generally good (tight fit).
    if post_residual <= 5 {
        score -= 20.0;
    }

    // Reward tightness relative to mean residual across open bins.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless it offers clear lookahead value.
    if bin_residual == bin_capacity {
        score += 15.0;
        if next_item_size > 0 && (bin_capacity as f64 - item_size as f64 - next_item_size as f64).abs() < 1.0 {
            score -= 100.0; // fresh bin fits both current and next item perfectly
        }
    }

    // Late in the stream: consolidate into fewer bins.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * (open_bins_count as f64).recip() * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (low post-residual) with a non-linear bonus.
    let tight = (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * (1.0 - tight).powi(4);

    // Penalize dead space that is too small for the smallest possible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: bonus if next item exactly fills the post residual.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }
    // Penalize if next item cannot fit in post residual but could fit elsewhere.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 8.0 * (post_residual as f64 / next_item_size as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Global state: many open bins with high mean residual -> prefer filling existing bins.
    let mean_fill = 1.0 - mean_residual / (bin_capacity as f64);
    score -= mean_fill * 10.0;
    score += (open_bins_count as f64).ln() * 2.0;

    // Time horizon: early in stream, be more open to new bins; late, consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 5.0;

    // New-bin candidate handling: neutral-ish baseline, penalized late, encouraged early
    // or when this bin is empty and item is large.
    if bin_residual == bin_capacity {
        if item_size > bin_capacity / 2 {
            score -= 12.0 * progress + 4.0;
        } else {
            score += 10.0 * progress;
        }
    }

    // Prefer placing larger items first into emptier bins (pairing large with large).
    let item_frac = item_size as f64 / bin_capacity as f64;
    score -= item_frac * (bin_residual as f64 / bin_capacity as f64) * 6.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / (total_items.max(1) as f64)).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let nxt = next_item_size as f64;

    // Base: prefer small post residual (tight fit), scaled non-linearly.
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth polynomial coupling of post residual with stream progress:
    // early on, tolerate loose fits (keep bins flexible); late, squeeze hard.
    let coupling = 24.0 * progress * (1.0 - progress) * (norm_pr * (1.0 - norm_pr)) * 4.0;
    score += coupling;

    // Penalize residuals that cannot host the lookahead item (dead space),
    // weighted smoothly by progress.
    if nxt > 0.0 && pr > 0.0 && pr < nxt {
        score += (nxt - pr) * (0.5 + 1.5 * progress);
    }
    // Reward residuals that exactly or nearly fit the next item.
    if nxt > 0.0 && pr >= nxt {
        let fit_ratio = nxt / pr;
        score -= 12.0 * fit_ratio * fit_ratio * (1.0 - progress * 0.5);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin,
    // unless the resulting residual is tiny (good fit already rewarded).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 + 15.0 * progress;
    }

    // Mild preference to keep the number of open bins balanced with mean residual.
    score += 0.05 * (open_bins_count as f64) * (norm_pr - mean_residual / cap).abs();

    // New empty bin candidate: raise its score slightly so it only wins
    // when all open fits are poor; dampen as stream progresses.
    if bin_residual == bin_capacity {
        score += 6.0 + 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;

    // Harmonic class of post_residual: reward small residuals strongly
    // (tight fits), with class boundaries at integer fractions of capacity.
    let post = post_residual as f64;
    if post == 0.0 {
        score -= 500.0; // perfect fit
    } else {
        // quarter-class reward: residual in [0,25) >> [25,50) >> [50,75) >> [75,100]
        let class = (post / (cap / 4.0)).floor() as f64;
        score -= 40.0 * (4.0 - class) * (4.0 - class);
        // modulo arithmetic: residuals divisible by common item sizes are reusable
        let pr = post_residual;
        if pr % 10 == 0 { score -= 8.0; }
        if pr % 20 == 0 { score -= 6.0; }
        if pr % 25 == 0 { score -= 5.0; }
        if pr % 50 == 0 { score -= 6.0; }
    }

    // Dead space penalty: residual too small for the smallest plausible item
    if post > 0 && post < 10.0 {
        score += 60.0;
    }

    // Lookahead harmony: does next_item_size fit the post_residual?
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= post {
            score -= 25.0;
            // harmonic bonus if next item exactly consumes residual class
            if (post - nx).abs() < 5.0 { score -= 15.0; }
        } else {
            // next item cannot use residual: mild penalty scaled by wasted fraction
            score += 10.0 * (nx - post) / cap;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: prefer new bin only when all fits are sloppy
    if bin_residual == bin_capacity {
        // baseline for a fresh bin: neutral residual = capacity
        score = cap;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a bin
        } else {
            // penalize opening new bin when a decent fit exists elsewhere
            let fit_quality = (bin_residual - item_size) as f64 / cap;
            score += 30.0 * (1.0 - fit_quality);
            if next_item_size > 0 && (next_item_size as f64) <= cap - item_size as f64 {
                score += 10.0;
            }
        }
    }

    // Slight preference for filling bins with more content as stream progresses
    score -= progress * 5.0 * (1.0 - post / cap);

    // Tie-break toward fewer open bins (bin consolidation)
    score += 0.01 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny gaps are nearly unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    } else if post_residual >= 10 {
        // Reward leaving a gap that could still hold a typical item.
        let usable = if next_item_size > 0 && next_item_size <= post_residual { 1.0 } else { 0.0 };
        score -= 12.0 * usable;
        // Smooth penalty proportional to wasted fraction of capacity.
        score += 0.35 * (post_residual as f64 / bin_capacity as f64) * (post_residual as f64 / bin_capacity as f64) * 100.0;
    }

    // Lookahead: reward if next item exactly fills the remaining gap.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    }
    // Penalize if next item cannot use the leftover space at all.
    if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
        score += 8.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += 0.6 * open_bins_count as f64;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
        if post_residual < 10 {
            score += 30.0; // but not if it creates dead space
        }
    }

    // New-bin candidate: make it moderately attractive only when open bins are crowded
    // or the fit into open bins would be poor.
    if bin_residual == bin_capacity {
        score = 55.0 + 0.5 * open_bins_count as f64 - 0.15 * mean_residual;
        if next_item_size > 0 && next_item_size <= 50 {
            score -= 10.0; // new bin keeps room for a mid-size follower
        }
    }

    // Slight stream-progression tilt: late in the stream, consolidation matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact / tight fits: small post_residual is good.
    score -= 12.0 * (1.0 - post_residual as f64 / bin_capacity as f64).powi(4);

    // 2-step lookahead: if the next item fits into post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 18.0 - 0.15 * slack; // prefer chains that leave little slack after next item
    } else if next_item_size > 0 && next_item_size <= bin_residual {
        // next item won't chain here but would have fit pre-placement: mild penalty
        score += 6.0;
    }

    // Penalize dead space that is too small for typical items (unusable gap).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Compare against mean residual: prefer bins with residuals near/below mean
    // (pack tight bins first, keep large-residual bins flexible).
    score -= 0.35 * (mean_residual - post_residual as f64);

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: neutral baseline; make it attractive only when open bins
    // are crowded (low mean residual) or late in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 30.0 + 25.0 * (1.0 - progress) + 0.3 * mean_residual;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0; // fresh bin chains well with next item
        }
    }

    // Mild penalty for proliferation of open bins.
    score += 0.4 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual is already favored by base score.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize large dead space that no future item (min size 1) can waste,
    // but especially penalize residuals that are awkwardly small-but-nonzero.
    if post_residual > 0 {
        let waste = post_residual as f64 / bin_capacity as f64;
        score += 8.0 * waste;
        // Very small residuals are nearly dead space: extra penalty.
        if post_residual < 10 {
            score += 10.0;
        }
    } else {
        // Perfect fit is excellent.
        score -= 15.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead coupling: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item fits here afterwards: good chaining.
            let chain_tight = (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 10.0 * (1.0 - chain_tight);
        } else {
            // Next item won't fit after this placement; penalize proportionally
            // to how much of the next item is "uncovered".
            let gap = (next_item_size - post_residual) as f64;
            score += 4.0 * (gap / 100.0);
        }
    }

    // Prefer using already-open bins over the new-bin candidate, especially
    // when many bins are open (consolidation pressure).
    if bin_residual == bin_capacity {
        // New-bin candidate: add penalty that grows with open bins and time.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 6.0 + 3.0 * (open_bins_count as f64).ln().max(0.0) + 4.0 * progress;
        // But if current bins fit poorly (large post_residual everywhere),
        // opening a new bin becomes more attractive: reduce penalty.
        let mean_gap = (mean_residual - item_size as f64).max(0.0);
        score -= 2.0 * mean_gap / 10.0;
    } else {
        // Slight preference for bins with residuals below the mean
        // (fill the fullest bins first, best-fit-like behavior).
        let diff = mean_residual - bin_residual as f64;
        score -= 0.5 * diff;
    }

    // Mild time-dependent exploration: early in the stream, be a bit more
    // tolerant of loose fits to keep options open; later, be strict.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * (post_residual as f64 / bin_capacity as f64) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early: prefer tight fills (low post_residual). Late: penalize large residuals harder.
    let prn = pr / cap; // normalized post residual in [0,1]
    let t = progress;
    let poly = 1.0 + 2.0 * t * t + 1.5 * t * prn * (1.0 - prn);
    score *= poly;

    // Reward near-perfect fits with a smooth quartic bonus.
    let fit_quality = 1.0 - prn;
    score -= 6.0 * fit_quality * fit_quality * fit_quality * fit_quality * item_size as f64 / cap;

    // Last-chance bonus: smooth function of fitting_bins_count.
    if fitting_bins_count <= 1 {
        score -= 8.0;
    }

    // Lookahead coupling: penalize leaving residual that neither fits next item well nor is tiny.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs();
        score += 0.05 * gap * (1.0 + t);
    }

    // Slight preference for consolidating into bins with smaller residuals relative to mean.
    score += 0.3 * (mean_residual - pr);

    // New-bin candidate: make it mildly unattractive unless residuals are getting large.
    if bin_residual == bin_capacity {
        score += 3.0 + 10.0 * t - 0.02 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: capacity fractions /10
    // Residuals that are "usable" multiples of 10 are more valuable to keep.
    let usable = post_residual % 10 == 0 && post_residual > 0;
    if usable {
        score -= 8.0;
    } else {
        score += 5.0;
    }

    // Integer division thresholds: small dead space (<10) is nearly useless
    if post_residual < 10 && post_residual > 0 {
        score += 20.0;
    }

    // Lookahead: does next item fit in the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // great, residual is reusable
            let tightness = (next_item_size as f64) / (post_residual as f64);
            score -= 15.0 * tightness;
            // harmonic class match: next item exactly fills residual
            if next_item_size == post_residual {
                score -= 60.0;
            }
        } else {
            // next item won't fit here: penalize wasted potential
            score += 6.0;
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad
    if bin_residual == bin_capacity {
        // base cost of a fresh bin
        score += 70.0;
        // cheaper to open new bin early when few bins open and stream is young
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 30.0 * (1.0 - progress) * (1.0 - progress);
        // if mean residual across open bins is large, prefer reusing them
        if mean_residual > item_size as f64 + 10.0 {
            score += 25.0;
        }
    } else {
        // prefer bins whose residual is close to item size (best fit coupling)
        let tight = (bin_residual - item_size) as f64 / bin_capacity as f64;
        score += 10.0 * tight;
    }

    // modulo-class harmony: residual divisible by next item's class
    if next_item_size > 0 && post_residual % next_item_size == 0 && post_residual > 0 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=15) are heavily penalized.
    if post_residual > 0 && post_residual <= 15 {
        score += 60.0 * (16.0 - post_residual as f64) / 16.0;
    }
    // Zero residual is a perfect fit: strong reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Reward tight fits relative to bin capacity.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 10.0 * fill_ratio;

    // Open bins pressure: with many open bins, favor consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.8 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when the item fits poorly everywhere
    // or the current bin's post-residual would be dead space.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, softened if open bins are crowded.
        score += 35.0 + 2.0 * open_bins_count as f64;
        // Attractive if next item is large (may pair with leftover space).
        if next_item_size > 0 && (bin_capacity - item_size) >= next_item_size {
            score -= 20.0;
        }
    } else {
        // Lookahead: if next item fits exactly in post_residual, big reward.
        if next_item_size > 0 && next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size > 0 && next_item_size > post_residual {
            score += 8.0; // post_residual likely wasted
        }
        // Prefer bins whose residual is close to item (best-fit behavior).
        score += 0.3 * (bin_residual as f64 - item_size as f64);
    }

    // Slight preference for bins with residual below mean (tighter bins).
    score += 0.2 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when leftover exactly matches next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // Next item still fits: mild reward proportional to tightness.
            score -= 50.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Dead space for the next item: penalize proportionally to wasted gap.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.5 * gap;
        }
    }

    // Relative to mean residual: prefer bins already tighter than average.
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: make it attractive only when no tight fit exists elsewhere.
    if bin_residual == bin_capacity {
        // Baseline cost of a fresh bin: slightly worse than a decent leftover.
        score += 40.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 30.0; // fresh bin also serves the lookahead well
        }
    }

    // Prefer filling bins more as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 20.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: prefer bins where the item fills most of the residual.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * tightness * tightness;

    // Penalize small dead space that no plausible item (>=1) can use well,
    // but only mildly since sizes are unknown; large post_residual is fine.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead coupling: if the next item fits the post-residual, reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Post-residual useless for the known next item: slight penalty.
        score += 4.0 * (next_item_size as f64 - post_residual as f64).min(40.0) / 40.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: prefer it only when open bins are crowded or the
    // fit is terrible; otherwise penalize opening a new bin.
    if bin_residual == bin_capacity {
        let crowded = open_bins_count as f64 / (mean_residual.max(1.0) / 20.0).max(1.0);
        let poor_fit = tightness < 0.5;
        if poor_fit && fitting_bins_count > 1 {
            score += 20.0;
        } else {
            score -= 5.0 + 3.0 * crowded.min(10.0);
        }
    }

    // Global residual balance: prefer bins below mean residual (consolidate).
    let diff = mean_residual - bin_residual as f64;
    score += 0.15 * diff;

    // Time horizon: late in the stream, consolidate harder; early, stay flexible.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * tightness;
    score += 5.0 * (1.0 - progress) * (bin_residual as f64 / bin_capacity as f64 - 0.5).abs();

    // Few open bins: encourage filling them rather than spreading.
    if open_bins_count <= 2 && bin_residual < bin_capacity {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic penalty on wasted space, amplified by progress.
    let tight = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * tight * tight * (0.5 + progress);

    // Penalize near-perfect fits only slightly less if next item could use leftover.
    if next_item_size > 0 && post_residual > 0 {
        if (next_item_size as f64) <= post_residual as f64 {
            score -= 12.0; // leftover usable by lookahead
        } else {
            score += 8.0 * (1.0 - (next_item_size as f64 - post_residual as f64) / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 + 20.0 * progress;
    }

    // New-bin candidate: penalize opening a bin unless residual would be huge/versatile.
    if bin_residual == bin_capacity {
        let versatility = (bin_capacity - item_size) as f64 / bin_capacity as f64;
        score += 15.0 + 30.0 * (1.0 - versatility) - 10.0 * progress;
        // discourage new bins when many are open with slack
        score += open_bins_count as f64 * 0.5;
    }

    // Mild preference for bins below mean residual (consolidate emptier bins).
    let dev = mean_residual - bin_residual as f64;
    score += 0.15 * dev;

    // Smooth non-linear coupling: interaction of fill ratio and progress.
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * fill * fill * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small" residue classes (near multiples of capacity fractions) are
    // more likely to be filled by future items.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fractional position of post_residual within the bin capacity.
    let frac = pr / cap;

    // Classify post residual into harmonic octiles; reward classes whose
    // leftover matches common item-size granularities.
    let octant = (frac * 8.0).floor() as i32;
    match octant {
        0 => score -= 6.0,   // nearly full bin: excellent packing
        1 => score -= 3.0,   // small dead space, still useful
        2 => score += 1.0,
        3 => score += 2.0,   // awkward mid-range leftover
        4 => score += 3.0,
        5 => score += 2.0,
        6 => score -= 1.0,   // large leftover: flexible
        _ => score -= 2.0,   // nearly empty bin
    }

    // Modulo coupling: leftover that is congruent to small item sizes
    // (mod 10 granularity) is more reusable.
    let residue_mod = post_residual % 10;
    if residue_mod == 0 {
        score -= 2.5;
    } else if residue_mod <= 3 {
        score -= 1.0;
    } else if residue_mod >= 8 {
        score += 0.5;
    }

    // Lookahead: if the next item fits exactly into post_residual, reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 8.0;
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            // Harmonic check on slack
            if slack % 10 == 0 {
                score -= 3.0;
            } else if slack < 10 {
                score -= 1.5;
            } else {
                score += (slack as f64) * 0.05;
            }
        } else {
            // Next item cannot follow into this bin: penalize mildly,
            // scaled by how much of the stream remains.
            let progress = step_index as f64 / total_items.max(1) as f64;
            score += 2.0 * (1.0 - progress);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 5.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when
    // current bins have poor residual structure (high mean residual spread
    // vs this bin) or many bins are already open with tight fits.
    if bin_residual == bin_capacity {
        let mean_gap = (mean_residual - pr).abs();
        // Base cost of a fresh bin, discounted late in the stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 12.0 - 4.0 * progress;
        // If open bins are crowded (low mean residual), new bin is fine.
        if mean_residual < 30.0 {
            score -= 4.0;
        }
        if mean_gap < 5.0 {
            score += 1.0;
        }
        // If item is large relative to capacity, avoid fragmenting open bins.
        if (item_size as f64) / cap > 0.7 {
            score -= 2.0;
        }
    }

    // Mild penalty for very tight fits that strand sub-10 dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 8.0;
    }
    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward residual that can still host the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (post_residual - next_item_size) as f64 * 0.3 + 5.0;
    } else if next_item_size > 0 {
        // Creating a gap that cannot fit the next item: dead space penalty.
        score += next_item_size as f64 * 0.4;
    }

    // Last chance: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Open-bins pressure: penalize bins with large residuals when many bins are open,
    // encouraging consolidation; but reward using bins when few are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 1.5 * progress;

    // Prefer bins whose residual deviates favorably from the mean (tighter bins first).
    score -= (bin_residual as f64 - mean_residual) * 0.2;

    // New-bin candidate: only attractive when current bin would leave a bad gap
    // or no open bin fits well. A fresh bin has full residual; make it moderately
    // costly so it wins only when open bins score poorly.
    if bin_residual == bin_capacity {
        score += 25.0 + open_bins_count as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
