            score -= 60.0;
        } else if post_residual > next_item_size {
            // next item also fits here: mild reward proportional to remaining match
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 - 0.25 * slack;
        } else {
            // next item cannot fit: dead space penalty scaled by gap
            let gap = (next_item_size - post_residual) as f64;
            score += 0.6 * gap;
        }
    } else {
        // last item: prefer tightest fill
        score += 10.0;
    }

    // Penalize bins far below mean residual (fragmented leftovers)
    score += 0.15 * (mean_residual - post_residual as f64).max(0.0);

    // Last-chance bin: avoid opening a new bin when this is the only fit
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Late in the stream: tighten packing, discourage opening new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 20.0 + 30.0 * progress;
    }

    // Slight bonus for well-filled bins (low post residual relative to capacity)
    score -= 0.1 * (bin_capacity as f64 - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
