        if item_size >= 50 && fitting_bins_count == 0 {
            score -= 60.0; // large item with no alternatives: open freely
        }
        if open_bins_count == 0 {
            score -= 100.0; // nothing open, must open
        }
        // Early in stream, opening bins is cheaper (more future items to fill them)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 * progress;
    }

    // Global state coupling: many open bins with high mean residual ->
    // prefer consolidating into existing bins (avoid bin sprawl).
    if bin_residual != bin_capacity {
        score += 0.05 * mean_residual * (open_bins_count as f64).sqrt();
    }

    // Slight preference for bins with residuals that pair well with
    // common item sizes (post_residual == 50 or 60 are versatile).
    if post_residual == 50 || post_residual == 60 || post_residual == 40 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress in [0,1]
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let prog2 = progress * progress;
    let prog3 = prog2 * progress;

    // Normalized post-residual
    let r = post_residual as f64 / bin_capacity as f64;

    // Smooth non-linear coupling: dead-space penalty grows with progress
    // (waste matters more late in the stream since fewer chances to fill it)
    let dead_space_weight = 1.0 + 3.0 * prog2 + 2.0 * prog3;
    score += dead_space_weight * r * r * bin_capacity as f64;

    // Reward tight fits (small post_residual) with smooth interaction between
    // item size and residual occupancy
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 8.0 * fill_ratio * (1.0 - r) * (1.0 + progress);

    // Penalize bins whose residual deviates from the mean residual (smooth divergence term)
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 2.0 * dev * dev * (1.0 + prog2);

    // Last-chance bonus: strongly prefer the only fitting bin, scaled by progress
    if fitting_bins_count == 1 {
        score -= 10.0 * (1.0 + prog2);
    }

    // Lookahead coupling: if the next item fits smoothly into the resulting
    // post-residual, reward it; if it barely fits, penalize fragmentation
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if n <= post_residual as f64 {
            let n_fit = n / post_residual as f64;
            score -= 4.0 * n_fit * (1.0 - n_fit) * (1.0 + progress);
        } else {
            // next item won't fit here: penalize leaving residual that is
            // large enough to be tempting but too small (smooth barrier)
            let gap = (n - post_residual as f64) / bin_capacity as f64;
            score += 3.0 * r * (1.0 - gap.min(1.0)) * (1.0 + prog2);
        }
    }

    // Mild dispersion of open bins: prefer filling existing bins when many are open
    let open_pressure = open_bins_count as f64 / (1.0 + open_bins_count as f64);
    score += 2.0 * open_pressure * r * (0.5 + 0.5 * progress);

    // Brand-new bin candidate: make it attractive only when the item is large
    // relative to capacity (smoothly), otherwise it loses to open bins
    if bin_residual == bin_capacity {
        let large = item_size as f64 / bin_capacity as f64;
        score -= 6.0 * large * large * (1.0 - progress);
        score += 2.0 * (1.0 - large) * (1.0 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which capacity-fraction band it lands in.
    // Residuals in (0, 10] are "dead space" -> heavy penalty; large residuals are fine.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Fractional band via integer division thresholds (harmonic classes 1..5).
    let class = (post_residual * 5) / bin_capacity; // 0..=4
    let class_penalty = match class {
        0 => 60.0,               // post_residual < 20% cap: near-dead space
        1 => 25.0,               // < 40% cap
        2 => 8.0,                // < 60% cap
        3 => -6.0,               // < 80% cap: good fit
        _ => -12.0,              // >= 80% cap: excellent fit
    };
    score += class_penalty;

    // Modulo arithmetic on post_residual: residuals divisible by common item sizes
    // (10/20/25/50) are more likely reusable by future items.
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 10.0; }
        if post_residual % 20 == 0 { score -= 5.0; }
        if post_residual % 25 == 0 { score -= 4.0; }
        if post_residual % 50 == 0 { score -= 4.0; }
        // Odd residuals below 10 are essentially dead.
        if post_residual < 10 { score += 40.0; }
    } else {
        // Perfect fill: best possible outcome.
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, strongly favor.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            // Next item fits but leaves its own residue; penalize small leftovers.
            let next_left = post_residual - next_item_size as f64;
            score += next_left * 0.4;
            if next_left <= 5.0 { score -= 8.0; }
        } else {
            // Next item won't fit here: slight penalty proportional to mismatch.
            score += (next_item_size as f64 - post) * 0.15;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && post_residual <= bin_residual {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin has huge raw score via post_residual;
    // adjust based on stream position and item size. Early in the stream, opening
    // fresh bins is cheap; late, prefer filling existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score -= 20.0 * (1.0 - progress);
        // Large items pair well with a fresh bin (room for a complement).
        if item_size >= bin_capacity / 2 { score -= 10.0; }
        else { score += 5.0; }
    } else {
        // Late in the stream, reward using open bins to avoid bin sprawl.
        score -= 10.0 * progress;
    }

    // Prefer bins tighter than the mean (concentrate filling).
    score += (post - mean_residual) * 0.3;

    // Slight penalty for too many open bins already.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small unusable gaps (post_residual < min item size 1..100, treat < 20 as likely dead)
    if post_residual > 0 && post_residual < 20 {
        score += (20 - post_residual) as f64 * 3.0; // harsh penalty for tiny useless gaps
    }

    // Reward very tight fits (post_residual near zero)
    if post_residual <= 5 {
        score -= 25.0;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: if next item can use the leftover space, reward; otherwise penalize
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= (next_item_size.min(post_residual)) as f64 * 0.5;
        } else {
            score += (next_item_size - post_residual.min(next_item_size)) as f64 * 0.8;
        }
    }

    // Open-bin pressure: discourage spreading across many bins
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive if this item would leave large dead space elsewhere
    // (i.e., poor fit in all open bins). Base cost of a new bin keeps it from being chosen casually.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.6 + item_size as f64 * 0.3;
        if fitting_bins_count == 0 {
            score -= 100.0; // no open bin fits: new bin is required
        } else if post_residual_in_others_proxy(item_size, mean_residual) {
            score -= 30.0; // poor fits everywhere: fresh bin is fine
        }
    }

    score
}

#[inline(always)]
fn post_residual_in_others_proxy(item_size: u32, mean_residual: f64) -> bool {
    // If mean residual barely exceeds item size, fits elsewhere are wasteful (large dead space)
    mean_residual < item_size as f64 + 15.0
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for a perfect (or near-perfect) fit
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: reward when the next item exactly matches post_residual
    if next_item_size > 0 {
        let post = post_residual as u32;
        if next_item_size == post {
            score -= 800.0;
        } else if next_item_size <= post {
            let slack = (post - next_item_size) as f64;
            score -= 100.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item can't use this bin's post-residual: penalize large leftovers
            let waste = (next_item_size - post) as f64;
            score += 0.3 * waste;
        }
    }

    // Relative-to-mean coupling: bins tighter than average are preferred targets
    let diff = (post_residual as f64) - mean_residual;
    score += 0.5 * diff;

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // Penalize opening a new bin when decent open bins exist
    if bin_residual == bin_capacity {
        // new-bin candidate: base cost plus penalty if mean residual could still host similar items
        score += 50.0 + 0.2 * mean_residual;
        if next_item_size > 0 && (bin_capacity as u32 - next_item_size) < item_size {
            // next item pairs well with a fresh bin too
            score -= 20.0;
        }
    }

    // Late in stream: consolidate aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 30.0 * progress * (1.0 - (post_residual as f64) / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual) nonlinearly.
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that can never be reused by typical items (<=80).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0; // hard to fill
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits the post-residual, big bonus.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 15.0;
            // exact chain fit bonus
            if post_residual as u32 == next_item_size {
                score -= 10.0;
            }
        } else {
            // next item won't fit here; penalize leaving large unusable gap
            let gap = post_residual as f64;
            if gap > next_item_size as f64 * 0.0 + 0.0 && gap >= 20.0 {
                score += gap * 0.15;
            }
        }
    }

    // Prefer bins with residual below mean (concentrate waste).
    let diff = bin_residual as f64 - mean_residual;
    score += diff * 0.25;

    // Many open bins: prefer filling existing ones rather than spreading.
    if open_bins_count > 3 {
        score -= (open_bins_count.min(20) as f64) * 0.8;
    }

    // New-bin candidate logic: only attractive early in the stream or when
    // the fit is very poor elsewhere.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Early: opening fresh bins is fine; late: discourage strongly.
        score += 55.0 * progress;
        // A new bin is fine if item is large relative to capacity.
        score -= (item_size as f64 / cap) * 20.0;
    }

    // Mild time-horizon modulation: as stream progresses, tighten packing.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 5.0 * (1.0 - tightness);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let x = post / cap; // normalized post residual in [0,1)

    // Base: prefer small post residual, with non-linear shaping
    let mut score = post * (1.0 + 0.8 * x * x);

    // Smooth polynomial coupling of fit quality with stream progress:
    // early on, tolerate loose fits; later, tighten preference for tight fits.
    let tightness = (1.0 - x) * (1.0 - x);
    score -= tightness * cap * (0.15 + 0.55 * progress);

    // Cubic dead-space penalty: small residuals (<~10) are hard to reuse
    let dead = (1.0 - x).powi(3);
    score += dead * cap * 0.35 * (1.0 - progress);

    // Last-chance bonus: only fitting bin -> reward strongly
    if fitting_bins_count == 1 {
        score -= cap * 0.6;
    } else if fitting_bins_count > 2 {
        score += (fitting_bins_count as f64 - 2.0) * 2.0;
    }

    // Lookahead coupling: if next item fits nicely in post residual, reward
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= post {
            let next_fit = 1.0 - (post - nx) / cap;
            score -= cap * 0.25 * next_fit * next_fit;
        } else {
            score += 5.0;
        }
    }

    // Mild pressure toward consolidation when many bins are open
    score += (open_bins_count as f64).ln1p() * (1.0 + x) * 3.0;

    // Deviation from mean residual: prefer bins near/below mean (keeps big bins free)
    let dev = (post - mean_residual) / cap;
    score += dev * cap * 0.1;

    // New-bin candidate: penalize slightly unless current fits are terrible
    if bin_residual == bin_capacity {
        score += cap * (0.55 - 0.4 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: integer division into buckets of 10.
    // Residuals in [0..=9] are near-perfect (dead space ~0); residuals in
    // [10..=19] are "harmonically useful" (can host the smallest items);
    // residuals >= 30 are wasteful unless a future item matches them.
    let class = post_residual / 10;
    match class {
        0 => { score -= 25.0; }                       // near-perfect closure
        1 => { score -= 8.0; }                        // still hostable for small items
        2 => { score += 6.0; }                        // awkward mid residual
        3 => { score += 12.0; }                       // large dead space
        _ => { score += 18.0; }                       // >40 free but item didn't fill well
    }

    // Exact fit reward: item perfectly closes the bin.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead harmony: does next_item_size fit into post_residual?
    if next_item_size > 0 && next_item_size <= post_residual {
        // Reward proportionally to how well the next item uses the leftover.
        let fill = next_item_size as f64 / post_residual as f64;
        score -= 10.0 + 15.0 * fill;
        // Bonus if the pair (item + next) exactly consumes the bin.
        if next_item_size == post_residual {
            score -= 20.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item won't fit here; penalize by how stranded the residual is.
        let stranded = next_item_size as f64 - post_residual as f64;
        score += 0.3 * stranded;
    }

    // Last-chance bin: if this is the only open bin that fits, strongly
    // prefer using it over opening a new bin (avoid bin proliferation),
    // unless the fit is terrible (post_residual very large).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 22.0;
        if post_residual > 50 {
            score += 15.0; // but a horrible fit shouldn't be forced
        }
    }

    // New-bin candidate handling: an empty bin should only win when no open
    // bin offers a decent fit. Give it a baseline penalty that shrinks if
    // the item is large relative to capacity (big items start fresh bins well).
    if bin_residual == bin_capacity {
        let big_item = item_size as f64 / cap;
        score += 30.0 - 20.0 * big_item;
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Mean-residual coupling: if open bins are already slack on average,
    // penalize adding more slack to this bin (encourage tight packing).
    score += 0.15 * (post_residual as f64 - mean_residual).max(0.0);

    // Modulo harmonic: post_residuals that are multiples of 10 align with
    // common item sizes (10,20,...); slightly reward such alignment.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    // Open-bin pressure: many open bins -> discourage opening more, encourage
    // filling existing ones (mild effect on all candidates).
    if open_bins_count > 4 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: residuals that are too small to hold
    // any plausible item (sizes 1..=100, but small gaps under ~10 are near-worthless)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Non-linear penalty for large wasted space relative to capacity
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 25.0 * waste_frac * waste_frac;

    // Reward tight fits strongly
    if post_residual <= 5 {
        score -= 30.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open bins pressure: when many bins are open, prefer filling existing ones
    // rather than opening new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64) * (0.5 + 0.5 * progress) * 0.5;

    // Lookahead: if the next item fits into the post-residual, reward this bin
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }
    // If next item would be blocked by this placement's dead space, penalize
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 5.0;
    }

    // New-bin candidate calibration: make empty bin slightly less attractive
    // unless residual pressure is high
    if bin_residual == bin_capacity {
        score += 8.0 - (open_bins_count as f64).min(8.0);
    }

    // Mean residual coupling: if mean residual is small, conserve open bin space
    if (bin_residual as f64) < mean_residual {
        score += 3.0;
    } else {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward: item exactly fills the bin.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // matches the next item's size exactly (chain fill).
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 * (1.0 - diff / 100.0).max(0.0);
        if post_residual == next_item_size {
            score -= 200.0;
        }
        // Penalize dead space the next item cannot use.
        if post_residual > 0 && post_residual < next_item_size {
            score += 15.0;
        }
    }

    // Penalize creating tiny unusable gaps (< 10, minimum item size).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // Compare against mean residual: bins tighter than average are
    // better candidates for consolidation.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Mild preference for keeping the number of open bins low,
    // slightly stronger late in the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 2.0 * open_bins_count as f64 * (0.5 + progress);

    // New-bin candidate: make it moderately attractive only when
    // item is large relative to residual, otherwise discourage it.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 > 0.6 * bin_capacity as f64;
        if large_item {
            score -= 80.0;
        } else {
            score += 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (low post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that no future item (sizes >= 1) can realistically fill:
    // small residuals are only useful if a tiny item arrives.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item exactly-ish.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 15.0; // perfect chain fit
        } else if post_residual >= next_item_size {
            score -= 3.0 * (post_residual as f64 - next_item_size as f64).min(10.0) / 10.0;
        } else {
            // next item won't fit here; slight penalty proportional to wasted opportunity
            score += 2.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Many open bins with slack: prefer consolidating into the fullest bins.
    let slack_bias = (mean_residual - post_residual as f64) / bin_capacity as f64;
    score -= 4.0 * slack_bias;

    // Time horizon: early in the stream, be more willing to open new bins
    // (cheap now, keeps flexibility); late in the stream, pack tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * tightness;

    // New-bin candidate: make it attractive only when current fits are poor
    // (large post_residual among alternatives) or stream is early.
    if bin_residual == bin_capacity {
        let early_bonus = 8.0 * (1.0 - progress);
        let poor_fit_penalty = 10.0 * tightness; // tightness == 0 for empty bin, so use mean
        score = 20.0 - early_bonus + (mean_residual / bin_capacity as f64) * 10.0 - poor_fit_penalty * 0.0;
        // If existing bins are mostly full (high mean residual), new bin is fine.
        // If existing bins have lots of room (low mean residual), discourage new bin.
        score += (bin_capacity as f64 - mean_residual) / bin_capacity as f64 * 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let r = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_r = r / cap;

    // Smooth polynomial coupling of post-residual with stream progress
    let mut score = r * (1.0 + 0.35 * progress * (1.0 - progress) * 4.0);

    // Penalize residual near awkward middle sizes (dead space) via smooth bump
    let mid = 0.5 * cap;
    let bump = ((norm_r - 0.5) * 6.0).powi(2);
    score += bump * r * 0.25;

    // Reward tight fits
    score -= (1.0 - norm_r) * item_size as f64 * 0.5;

    // Last-chance bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits the post-residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= r {
        score -= 10.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 5.0 * (next_item_size as f64 / cap);
    }

    // Mild dispersion penalty: keep bins balanced relative to mean residual
    score += ((r - mean_residual) / cap).abs() * 8.0;

    // New-bin candidate: keep it slightly unattractive unless residuals are tight
    if bin_residual == bin_capacity {
        score += 15.0 + 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover into modulo bands.
    // Residuals that are multiples of small harmonics (e.g. %10==0) are reusable.
    let pr = post_residual;
    if pr > 0 {
        if pr % 10 == 0 {
            score -= 6.0; // perfectly harmonic leftover, highly reusable
        } else if pr % 5 == 0 {
            score -= 3.0;
        } else if pr < 10 {
            score += 12.0; // dead space: nothing (min size 1..100 unknown, but tiny) fits well
        } else {
            score += 2.0;
        }
    }

    // Perfect fit is best possible.
    if pr == 0 {
        score -= 25.0;
    }

    // Does the lookahead item fit in the leftover? Strong reward if chainable.
    if next_item_size > 0 && pr >= next_item_size {
        score -= 8.0 + 0.05 * (pr as f64 - next_item_size as f64);
    } else if next_item_size > 0 && pr > 0 {
        // leftover too small for next item: penalize proportionally to wasted fraction
        score += 6.0 * (pr as f64 / cap);
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Penalty when many bins fit: competition means we can afford to be picky;
    // prefer the bin whose post_residual is smallest but still useful.
    if fitting_bins_count > 2 {
        score += 0.02 * (fitting_bins_count as f64);
    }

    // Deviation from mean residual: prefer bins that are already "low" (nearly full)
    // so mean residual shrinks and open bins get closed out.
    score += 0.15 * (post_residual as f64 - mean_residual);

    // Progress-based calibration: late in the stream, consolidate harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 4.0 * progress * (1.0 - post_residual as f64 / cap);

    // New-bin candidate handling: an empty bin has bin_residual == bin_capacity.
    // Give it a neutral-to-slightly-high score so real bins win when fits are decent,
    // but it becomes attractive when all open fits leave terrible dead space.
    if bin_residual == bin_capacity {
        let bad_open_fit = next_item_size > 0 && pr > next_item_size && pr < next_item_size + 5;
        let base = 20.0 + 0.1 * (open_bins_count as f64);
        score = if bad_open_fit { base - 5.0 } else { base };
        // Late in stream with many open bins, discourage spreading further.
        score += 0.05 * (open_bins_count as f64) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.90;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 500.0;
    } else {
        // Penalize small dead space (unusable slivers)
        if post_residual < 10 {
            score += 60.0;
        }
        // Reward tight fits relative to capacity
        score += (post_residual as f64 / bin_capacity as f64) * 30.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, strongly favor this bin
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual >= next_item_size {
            // next item fits, but penalize leftover after hypothetical placement
            let after_next = post_residual - next_item_size;
            score += after_next as f64 * 0.8;
            if after_next == 0 {
                score -= 150.0;
            }
        } else {
            // next item cannot follow here; mild penalty for wasting chain capacity
            score += 25.0;
        }
    }

    // Compare against mean residual: prefer bins tighter than average
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Last-chance bin: only bin that fits, avoid opening new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Penalize opening a new bin early in the stream when open bins exist
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste = bin_capacity as f64 - item_size as f64;
        score += waste * 2.0 + 100.0 * (1.0 - progress);
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score += 50.0; // splitting a pair across bins is bad
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: small post-residual is good (best-fit core).
    score += 0.35 * (post_residual as f64).powf(1.25);

    // Reward nearly-exact fills.
    if post_residual <= 3 {
        score -= 18.0;
    } else if post_residual <= 8 {
        score -= 8.0;
    }

    // Penalize dead space that can never fit a typical future item.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0; // unusable sliver
    }

    // Lookahead: if next item fits in post_residual, this is a great chain placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0 + 0.25 * (post_residual - next_item_size) as f64;
        } else {
            // Wasting residual the next item could have used elsewhere: mild penalty.
            score += 0.08 * (post_residual as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: default penalty, waived when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 30.0;
        // Early in the stream, opening bins is cheap; later, consolidate.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        // If many bins already fit the item, opening a new one is clearly bad.
        if fitting_bins_count > 2 {
            score += 20.0;
        }
        // If the item is huge relative to capacity, a fresh bin may be justified.
        if item_size as f64 > 0.7 * bin_capacity as f64 {
            score -= 15.0;
        }
        // If mean residual across open bins is low, open bins are nearly full anyway.
        if mean_residual < item_size as f64 {
            score -= 12.0;
        }
    }

    // Mild preference for filling bins below the mean residual (balance avoidance of
    // many half-empty bins) — favors bins with less room than average.
    score += 0.05 * (mean_residual - bin_residual as f64).max(0.0);

    // Slight time decay: later in the stream, prioritize compactness more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let prog2 = progress * progress;

    // Normalized post residual
    let pr = post_residual as f64 / cap;
    let pr2 = pr * pr;
    let pr3 = pr2 * pr;

    // Non-linear polynomial coupling of post_residual with progress:
    // early stream: prefer tight fits (penalize large post_residual quadratically/cubically)
    // late stream: dead space matters less, so damp the penalty
    let damp = 1.0 - 0.5 * prog2;
    score += (6.0 * pr2 + 4.0 * pr3) * cap * damp;

    // Perfect fit reward, amplified as stream progresses
    if post_residual == 0 {
        score -= 12.0 + 10.0 * progress;
    }

    // Small post residual that could still fit a future item is good; large unusable remainder penalized
    let next = next_item_size as f64;
    if next > 0.0 {
        if post_residual >= next_item_size {
            score -= 4.0 * progress * (1.0 - pr);
        } else {
            // creates dead space relative to the next item
            score += 3.0 * (next - post_residual as f64) * (0.5 + 0.5 * progress);
        }
    }

    // Last-chance bin: strongly prefer using it rather than opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Mild preference for bins with smaller residuals (tighter bins first)
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Prefer reusing bins when many are open (avoid bin proliferation)
    score += 0.4 * open_bins_count as f64 * pr2;

    // New-bin candidate: penalize unless current residual is very small (wasted bin otherwise)
    if bin_residual == bin_capacity {
        score += 8.0 - 6.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 and modulo 25
    let pr = post_residual;
    let r10 = (pr % 10) as f64;
    let r25 = (pr % 25) as f64;

    // Penalize awkward residue classes (dead space that rarely fills)
    score += 2.0 * (r10 / 10.0);
    score += 1.5 * (r25 / 25.0);

    // Perfect-fit harmonic bonus: post_residual in {0, 5, 10, 20, 25, 50}
    let harmonic = match pr { 0 => 30.0, 5 => 12.0, 10 => 10.0, 20 => 8.0, 25 => 8.0, 50 => 6.0, _ => 0.0 };
    score -= harmonic;

    // Integer-division thresholds on post_residual: small remainders are prime
    if pr > 0 && pr / 10 == 0 { score -= 5.0; }          // pr < 10: nearly full
    if pr >= 10 && pr / 10 == 1 { score -= 2.0; }        // 10..19: still useful
    if pr >= 40 { score += 1.0 * ((pr as f64) / cap); }  // large leftover: mild penalty

    // Lookahead coupling: does next item fit the post residual?
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if (next_item_size as u32) <= pr {
            // next fits: reward, stronger when it nearly fills the remainder
            let tight = 1.0 - ((pr as f64 - n) / cap).max(0.0);
            score -= 6.0 + 6.0 * tight;
            // harmonic match: next item size shares residue class with pr
            if pr % 10 == next_item_size % 10 { score -= 3.0; }
        } else {
            // next won't fit here: penalize proportionally to overflow
            score += 0.5 * ((next_item_size as u32 - pr) as f64 / cap);
        }
    } else {
        // last item: prefer tightest packing, ignore future concerns
        score -= 4.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: neutral baseline; only attractive when
    // no open bin offers a decent fit and residuals are globally large
    if bin_residual == bin_capacity {
        score = cap * 0.85
            + 5.0 * (mean_residual / cap)
            + (open_bins_count as f64).sqrt() * 2.0
            - if fitting_bins_count == 0 { 20.0 } else { 0.0 }
            + if next_item_size > 0 && next_item_size > item_size { 3.0 } else { 0.0 };
    }

    // Late-stream tightening: as stream progresses, prefer filling existing bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 4.0 * progress * (1.0 - (post_residual as f64) / cap);

    // Reward placing into bins below the mean residual (balancing residuals)
    score += 1.2 * ((post_residual as f64) - mean_residual) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for even the
    // smallest plausible item (<= 10) are pure waste; penalize them heavily.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual <= 25 {
        // "Awkward gap" zone: hard to fill with typical items.
        score += 25.0 * (1.0 - (post_residual as f64 - 10.0) / 15.0);
    }

    // Reward very tight fits (small post_residual relative to item).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor new-bin
    // candidate less and consolidation more.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost grows with number of open bins.
        score += 15.0 + 12.0 * pressure;
        // But if existing bins would leave big dead space, new bin is fine.
        if post_residual > 0 && bin_residual == bin_capacity {
            score -= 10.0 * pressure;
        }
        // Lookahead: if next item is large, a fresh bin is attractive.
        if next_item_size >= 60 {
            score -= 20.0;
        }
    } else {
        // Placing into an existing bin: slight reward under pressure.
        score -= 3.0 * pressure;
        // If next item fits exactly in the post-residual, big bonus (pairing).
        if next_item_size > 0 && next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0;
        } else if next_item_size > post_residual && post_residual < 10 {
            score += 15.0; // dead space blocks the lookahead item
        }
    }

    // Mean-residual coupling: if this bin's post-residual deviates badly from
    // the mean residual, penalize (keeps residuals homogeneous / usable).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Early in the stream, be more willing to open bins (better structure later).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to item size)
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * tightness;

    // Strong reward for exact fit
    if post_residual == 0 {
        score -= 60.0;
    }

    // 2-step lookahead: if next item fits exactly in the post residual, big reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual >= next_item_size {
            // next item fits but leaves more waste; mild reward scaled by fit quality
            let nxt_fit = next_item_size as f64 / post_residual as f64;
            score -= 15.0 * nxt_fit;
        } else if next_item_size <= bin_residual && post_residual > 0 {
            // next item can't use post residual but could have used residual: penalize
            score += 8.0;
        }
        // small bonus if next item fits the remaining post residual at all
        if post_residual >= next_item_size {
            score -= 5.0;
        }
    }

    // Penalize leaving dead space that likely can't be used (post_residual small but nonzero)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Relative to mean residual: prefer bins with more residual than average
    // (keeps tight bins free), unless this is a tight fit
    let mr = mean_residual;
    if bin_residual as f64 > mr {
        score -= 4.0;
    } else {
        score += 3.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize opening a new bin when plenty of open bins fit the item
    if bin_residual == bin_capacity {
        // new-bin candidate: baseline cost of a fresh bin
        score += 20.0;
        if fitting_bins_count == 0 {
            score -= 50.0; // no alternative
        } else if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0;
        }
        // early stream: opening bins is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
        // many open bins with high mean residual: discourage new bin
        if open_bins_count > 0 {
            score += (open_bins_count as f64).ln() * 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) with a nonlinear boost.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that cannot hold the next item (lookahead k=2).
    if next_item_size > 0 && post_residual > 0 {
        if post_residual < next_item_size {
            score += 0.35 * (next_item_size - post_residual) as f64;
        } else {
            // Residual can host the next item: reward it.
            score -= 0.25 * next_item_size as f64;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // When many bins are open, encourage consolidation into existing bins.
    let crowding = (open_bins_count as f64).ln().max(0.0);
    score += 1.5 * crowding * (post_residual as f64 / bin_capacity as f64);

    // Deviation from mean residual: prefer bins that keep residuals balanced
    // unless the fit is very tight.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.08 * dev * (1.0 - tightness);

    // Time horizon: early in the stream, be conservative (avoid near-empty
    // placements); late in the stream, be greedy about tight fits.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 6.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);
    score -= 8.0 * progress * tightness;

    // New-bin candidate: only attractive when current bin residuals are all
    // poor for the item (large post residual everywhere) or stream is early.
    if bin_residual == bin_capacity {
        let poor_fits = (mean_residual - item_size as f64).max(0.0);
        score = 30.0 + 0.4 * poor_fits - 20.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 40.0; // must open a new bin anyway
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr_norm = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Penalize large dead space more strongly as stream progresses (quadratic in residual)
    score += 25.0 * pr_norm * pr_norm * (0.5 + progress);

    // Reward tight fits: small post_residual relative to item size
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * tightness * tightness;

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 20.0 + 15.0 * progress;
    }

    // Lookahead: reward if next item fits the post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 8.0 * (1.0 - (pr - nxt) / cap);
        } else {
            score += 5.0 * (nxt - pr) / cap;
        }
    }

    // Mild pressure toward consolidating into few bins
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // Mean residual coupling: prefer bins below mean residual (tighter bins)
    score += 0.3 * (mean_residual - pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: bins whose leftover falls into
    // "useful" residue classes get rewarded.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: prefer minimal post residual, but with diminishing returns
    // (quadratic penalty on large leftovers).
    score = pr * 0.9 + (pr * pr) / (2.0 * cap);

    // Harmonic class bonus via modulo: leftover divisible by small units
    // (10, 20, 25) is more likely reusable by future items.
    if post_residual % 10 == 0 { score -= 4.0; }
    if post_residual % 20 == 0 { score -= 2.0; }
    if post_residual % 25 == 0 { score -= 2.5; }
    if post_residual % 50 == 0 { score -= 3.0; }

    // Integer-division thresholds: classify leftover into dead-space tiers.
    let tier = post_residual / 10; // 0..10
    match tier {
        0 => score -= 6.0,           // near-perfect fill
        1 => score -= 3.0,
        2 => score -= 1.5,
        3 | 4 => score += 1.0,       // awkward zone
        5 | 6 => score += 3.0,
        _ => score += 5.0,           // large waste
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 12.0;
        } else if next_item_size <= post_residual {
            // fraction of leftover consumed by next item
            let frac = next_item_size as f64 / pr.max(1.0);
            score -= 6.0 * frac;
            // harmonic match: next item leaves residue in a good class too
            if (post_residual - next_item_size) % 10 == 0 { score -= 2.0; }
        } else {
            // next item cannot use this leftover at all: penalize proportionally
            score += 2.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0;
    }

    // New-bin candidate handling: an empty bin has large residual; make it
    // attractive only when current bins would create bad leftovers or when
    // the item is large relative to capacity.
    if bin_residual == bin_capacity {
        let load_frac = item_size as f64 / cap;
        // Opening fresh is good for big items or when open bins are crowded.
        score -= 10.0 * load_frac;
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 3.0 * progress;
        if open_bins_count == 0 { score -= 5.0; }
        if mean_residual < item_size as f64 { score -= 4.0; }
        // discourage hoarding too many open bins
        score += (open_bins_count as f64).sqrt() * 1.5;
    } else {
        // Mild preference for using existing bins early in the stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 2.0 * (1.0 - progress);
        // Reward packing into bins with residuals below the mean (tightening).
        if (bin_residual as f64) < mean_residual {
            score -= 1.0;
        }
        // More competing bins => pickiness: penalize mediocre fits harder.
        score += (fitting_bins_count as f64).ln().max(0.0) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 + (10.0 - post_residual as f64) * 3.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 40.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Reward bins that can also fit the next item (lookahead coupling).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space relative to the next item's need.
        score += (next_item_size - post_residual) as f64 * 0.3;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones.
    let new_bin = bin_residual == bin_capacity;
    if new_bin {
        score += open_bins_count as f64 * 2.5;
        // Mid-stream new bins are extra costly.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 15.0;
    } else {
        // Favor tight bins (small residual before placement) mildly.
        score += (bin_residual as f64) * 0.05;
        // Prefer bins below mean residual (tighter than average).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward: zero post residual is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // matches the next item size exactly (chained perfect fit).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += gap * 0.8;
        if gap == 0.0 {
            score -= 400.0; // exact chained match
        }
        // Penalize post_residual that is small but cannot fit next item
        // (dead space that blocks the lookahead item).
        if post_residual > 0 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 1.5;
        }
    }

    // Compare against mean residual across open bins: bins tighter than
    // the mean are more valuable to fill now.
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 250.0;
    }

    // Mild penalty for creating very small unusable slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Slight preference to keep larger residuals available early in stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * progress * 0.1;

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let open_fit_quality = if fitting_bins_count > 0 { 0.0 } else { 500.0 };
        score += 120.0 - open_fit_quality;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness of the fit: reward near-full fills.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 18.0 * tightness * tightness;

    // Exact fill is ideal.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Penalize large dead space relative to typical item scale.
    let dead = post_residual as f64;
    if dead > 0.0 {
        score += 0.35 * (dead / 10.0).powi(2) * (1.0 - tightness);
    }

    // Lookahead: reward residuals that can still hold the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
            // Bonus when next item fills leftover nearly exactly.
            let gap = post_residual - next_item_size;
            score -= 10.0 * (1.0 - gap as f64 / bin_capacity as f64);
        } else {
            // Dead space the next item cannot use: penalize more late in stream.
            let t = step_index as f64 / (total_items.max(1) as f64);
            score += 6.0 * (1.0 - t) + 3.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: prefer it only when existing fits are poor or stream is early.
    if bin_residual == bin_capacity {
        let t = step_index as f64 / (total_items.max(1) as f64);
        let poor = (post_residual as f64 / bin_capacity as f64).min(1.0);
        score = 55.0 + 40.0 * t - 30.0 * (1.0 - poor) - 2.0 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score = -10.0; // must open a bin
        }
    }

    // Global state coupling: many open bins with high mean residual -> consolidate.
    if open_bins_count > 2 && mean_residual > item_size as f64 {
        score += 4.0 * (mean_residual / bin_capacity as f64);
    }

    // Mild time pressure: later in the stream, prefer tighter packing.
    let t = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * t * (item_size as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let base = post;
    let poly = norm_post * norm_post * (1.0 + progress);
    let cubic = norm_post.powi(3) * (1.0 - 0.5 * progress);

    let mut score = base + 20.0 * poly - 15.0 * cubic;

    // Reward tight fits, modulated by progress
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 10.0 * tightness * (0.5 + progress);

    // Penalize dead space relative to mean residual
    score += 0.3 * (post - mean_residual).abs();

    // Last-chance bonus
    if fitting_bins_count == 1 {
        score -= 8.0;
    }

    // Lookahead: favor bins that can also fit next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0;
    }

    // Mild pressure against bin proliferation early on
    score += 0.1 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: modulo-10 residue classes.
    // Residuals that are "dead" (small, hard to fill) get penalized.
    let pr = post_residual;
    let class = pr % 10;
    match class {
        0 => score -= 12.0,          // perfectly divisible residual: excellent
        1 | 2 => score += 8.0,       // tiny slivers: likely dead space
        3 | 4 => score += 3.0,       // poor
        5 => score -= 4.0,           // half-slot: pairs with size-5 items
        6 | 7 => score += 1.0,       // mediocre
        _ => score -= 2.0,           // 8/9: can absorb small items
    }

    // Integer-division thresholds: reward residuals in ranges that match
    // common item sizes (10..80).
    if pr >= 60 { score -= 6.0; }
    else if pr >= 40 { score -= 3.0; }
    else if pr >= 20 { score += 0.0; }
    else if pr > 0 { score += 5.0; } // near-dead space

    // Perfect fit: zero waste is always best.
    if pr == 0 { score -= 100.0; }

    // Lookahead coupling: if the next item fits exactly in post_residual,
    // strongly reward this bin (chained perfect packing).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size <= pr && (pr % next_item_size) == 0 {
            // next item divides residual evenly: harmonic bonus
            score -= 10.0;
        } else if next_item_size > pr {
            // next item won't fit here; penalize leaving a residual
            // that will strand this bin.
            score += (pr as f64) * 0.15;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 15.0;
        if pr <= 10 && pr > 0 { score += 10.0; } // unless it creates dead space
    }

    // Many open bins: prefer tightening existing bins over spreading.
    if open_bins_count > 4 {
        score += mean_residual * 0.05;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Only prefer a new bin when no open bin offers a good fit, i.e. the
    // item is large relative to typical residuals.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Baseline cost of a new bin; discount slightly late in the stream
        // when mean residuals are likely fragmented.
        let mut new_bin_cost = 55.0 - 10.0 * progress;
        if item_size > 70 { new_bin_cost -= 12.0; }   // huge items: fresh bin fine
        if item_size <= 20 { new_bin_cost += 20.0; }  // small items: use leftovers
        if next_item_size > 0 && next_item_size + item_size >= bin_capacity {
            new_bin_cost -= 8.0; // next item nearly fills the rest: good pairing
        }
        score += new_bin_cost;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps that can no longer fit
    // the minimum item (1..=10) are pure waste -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Gaps too small for the lookahead item are also likely dead space.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0;
    }

    // Reward near-perfect fits (small but usable leftovers are fine,
    // exact fills are ideal).
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Perfect lookahead pairing: leftover exactly fits next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Pressure: with many open bins, discourage opening new ones and
    // encourage consolidating into existing bins.
    score += open_bins_count as f64 * 0.5;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when open bins are plentiful
        // or residuals are still large on average.
        score += 45.0 + open_bins_count as f64 * 2.0 + mean_residual * 0.3;
    } else {
        // Reward filling bins that are already relatively full.
        let fullness = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= fullness * 10.0;
    }

    // Slight late-stream tightening: favor compact placements as the
    // stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact 2-step lookahead match: post_residual equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Reward near matches (next item would leave tiny waste).
    else if next_item_size > 0 && post_residual > next_item_size {
        let chain_waste = (post_residual - next_item_size) as f64;
        score -= 20.0 - chain_waste.min(20.0);
    }
    // Penalize placements that leave dead space too small for any item (1..10).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Penalize wasteful residual relative to mean residual of open bins.
    score += (post_residual as f64 - mean_residual) * 0.5;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Prefer filling already-open bins when many are open; new bin (residual==capacity)
    // gets a mild penalty unless it is the only candidate.
    if bin_residual == bin_capacity {
        score += 5.0 + (open_bins_count as f64) * 0.5;
    }

    // Late in stream: tighten packing, avoid leaving moderate residuals.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (low post-residual is good, but push it further).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize unusable dead space: if next item cannot fit in post-residual,
    // the leftover is likely wasted unless the bin is nearly full anyway.
    if next_item_size > 0 {
        if (post_residual as f64) < next_item_size as f64 {
            // Dead space penalty, softened when bin is almost exhausted.
            let waste = post_residual as f64 / bin_capacity as f64;
            score += 8.0 * waste;
        } else {
            // Reward bins that can also host the lookahead item.
            score -= 4.0;
            if (post_residual - next_item_size) as f64 >= 0.0 {
                let combo = (bin_residual - item_size - next_item_size) as f64 / bin_capacity as f64;
                if combo >= 0.0 {
                    score -= 3.0 * (1.0 - combo);
                }
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Many open bins: discourage fragmenting capacity further; prefer compacting.
    if open_bins_count > 2 {
        let crowding = (open_bins_count as f64).ln().max(0.0);
        score += 1.5 * crowding * (post_residual as f64 / bin_capacity as f64);
    }

    // Global residual context: bins far below the mean residual are good targets
    // for draining (reduce spread of residuals).
    score += 2.0 * ((bin_residual as f64 - mean_residual) / bin_capacity as f64);

    // Time horizon: early on, be selective (prefer very tight fits);
    // late in the stream, prioritize closing bins out.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 6.0 * progress * tightness;
    score += 3.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: a fresh bin should only win when the item
    // fits poorly everywhere else, or the stream is early and stockpiling
    // a clean bin is cheap.
    if bin_residual == bin_capacity {
        let is_last_chance_elsewhere = fitting_bins_count <= 1;
        let poor_fit = (post_residual as f64 / bin_capacity as f64) > 0.6;
        if is_last_chance_elsewhere || poor_fit || progress < 0.15 {
            score -= 20.0;
        } else {
            score += 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress.
    let mut score = pr * (1.0 + 0.6 * progress * progress);

    // Penalize tiny dead space quadratically (unusable slivers).
    if pr > 0.0 && pr < item_size as f64 {
        score += (item_size as f64 - pr) * (item_size as f64 - pr) / cap;
    }

    // Reward tight fits (low post residual) more strongly late in stream.
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * 20.0 * (0.3 + 0.7 * progress);

    // Last-chance bin: strong incentive to use it.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Prefer bins with residual close to mean residual (balanced packing).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += dev.abs() * 8.0;

    // Lookahead: if next item fits the post-residual, reward.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 6.0 + 8.0 * (1.0 - (post_residual as f64 - next_item_size as f64) / cap);
    }

    // New-bin candidate: mildly penalize early, allow late when residuals are fragmented.
    if bin_residual == bin_capacity {
        score += 12.0 * (1.0 - progress) - 10.0 * progress * (mean_residual / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual small relative to capacity.
    let frac = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * frac * frac; // convex penalty on leftover fraction

    // Harmonic class of post_residual: dead space below smallest item (1..10) is unusable-ish
    let small_class = post_residual % 10;
    if small_class > 0 && post_residual < 10 {
        score += 25.0; // residual smaller than any realistic item
    }

    // Modulo classes on post_residual: multiples of 5/10 are more reusable
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    } else if post_residual % 5 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    // Perfect fill
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size < post_residual {
            score -= 10.0 * (post_residual - next_item_size) as f64 / bin_capacity as f64;
        } else {
            // next item cannot fit here: residual is dead for next step
            score += 5.0;
        }
        // harmonic threshold: post_residual in [next, next+10) is a good slot
        if next_item_size <= post_residual && post_residual < next_item_size + 10 {
            score -= 12.0;
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New bin candidate: penalize opening a new bin unless current bins are crowded
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = (open_bins_count as f64) / (mean_residual / bin_capacity as f64 + 1.0);
        score = bin_capacity as f64 * 0.9 + 20.0 * (1.0 - progress) - 10.0 / (pressure + 1.0);
        // if the item is large and mean residual is small, new bin is attractive
        if item_size as f64 > mean_residual {
            score -= 25.0;
        }
    }

    // Slight preference for bins with residual below mean (consolidate waste)
    score += 0.05 * (bin_residual as f64 - mean_residual).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest plausible
    // future item are nearly worthless dead space. Penalize them heavily.
    let min_useful = 10u32; // smallest typical item footprint
    if post_residual > 0 && post_residual < min_useful {
        score += 60.0;
    } else if post_residual < min_useful * 2 {
        // marginally usable gap: moderate penalty scaled by tightness
        score += (min_useful * 2 - post_residual) as f64 * 1.5;
    }

    // Reward near-perfect fills (small but usable leftovers get a discount).
    if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 15 {
        score -= 10.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, strongly
    // prefer this bin (chain placements reduce bin count).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 - slack * 0.3;
        } else {
            // next item won't fit here: this residual may become dead space
            let gap = (next_item_size - post_residual) as f64;
            if post_residual < next_item_size && post_residual < min_useful {
                score += gap * 0.8;
            }
        }
    }

    // Open-bin pressure: with many open bins, discourage spreading into
    // additional bins; encourage tightening existing ones.
    score += open_bins_count as f64 * 0.5;

    // Last-chance bin: if this is the only bin that can fit the item, using it
    // avoids opening a new bin — reward that.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin has zero dead space, but opening
    // it when good fits exist wastes capacity. Make the empty bin attractive
    // only when the current bin would leave a large awkward gap or when many
    // bins are already open and residual is badly fragmented.
    if bin_residual == bin_capacity {
        // base competitiveness for a fresh bin
        let mut new_bin_score = 45.0 + open_bins_count as f64 * 0.5;
        // if the item is large, a fresh bin guarantees a clean fit
        if item_size > bin_capacity / 2 {
            new_bin_score -= 20.0;
        }
        // if mean residual across open bins is high, prefer using open bins
        new_bin_score += mean_residual * 0.3;
        // if no open bin fits well (this call is for the new bin), be available
        if fitting_bins_count == 0 {
            new_bin_score -= 35.0;
        }
        score = new_bin_score + post_residual as f64;
    }

    // Stream progression: late in the stream, be slightly more conservative
    // about creating small gaps since fewer items remain to fill them.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < min_useful {
        score += progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-exact fits: small post_residual is valuable dead-space-wise.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 300.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Aggressive 2-step lookahead: reward post_residual that matches next_item_size
    // exactly or closely (chain packing).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if gap == 0.0 {
            score -= 500.0; // perfect chain: next item fills this bin exactly
        } else if post_residual >= next_item_size {
            score -= 150.0 * (1.0 - gap / 100.0);
        } else {
            // post_residual too small for next item: penalize proportionally
            score += 80.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Compare against mean residual: bins already tight are better targets.
    let res = post_residual as f64;
    if res < mean_residual {
        score -= 0.5 * (mean_residual - res);
    } else {
        score += 0.3 * (res - mean_residual);
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // Discourage opening a new bin when a reasonable fit exists.
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline cost plus penalty for wasted capacity
        // relative to what a fitting open bin could offer.
        score += 120.0;
        score += 0.4 * (open_bins_count as f64);
        // If next item is large, a fresh bin is more attractive.
        if next_item_size > 0 && next_item_size >= post_residual.min(bin_capacity) {
            // keep default penalty
        } else if next_item_size > 0 {
            score += 0.3 * next_item_size as f64;
        }
    }

    // Slight preference for consolidating into fewer bins early in the stream.
    score += 0.05 * (open_bins_count as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize small post_residual nonlinearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits in the post residual, reward this placement.
    if next_item_size > 0 {
        if (post_residual as i64) >= (next_item_size as i64) {
            score -= 12.0;
        } else if (next_item_size as i64) > (bin_capacity as i64) - (post_residual as i64)
            && post_residual > 0
        {
            // next item cannot use leftover; penalize large useless leftovers mildly.
            score += (post_residual as f64) * 0.05;
        }
    }

    // Prefer bins with residual close to item_size (best-fit flavor).
    let diff = (bin_residual as f64 - item_size as f64).abs();
    score += diff * 0.15;

    // Global pressure: many open bins relative to progress -> discourage new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus penalty scaled by open bins and mean residual availability.
        score += 30.0 + 3.0 * open_bins_count as f64 + 20.0 * (mean_residual / bin_capacity as f64);
        // Late in stream, opening new bins is cheaper than fragmenting.
        score -= 25.0 * progress;
    } else {
        // Reward using existing bins more when many are open.
        score -= 2.0 * (open_bins_count as f64).ln().max(0.0);
    }

    // Mean residual coupling: if this bin is far below mean residual, slightly favor it (uses fragmented space).
    score -= 0.1 * (mean_residual - bin_residual as f64).abs().min(50.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: penalize leftover residual, with non-linear (quadratic) growth of dead-space cost.
    let norm_pr = pr / cap;
    let mut score = norm_pr * (1.0 + 1.8 * norm_pr) * cap;

    // Smooth coupling with stream progress: later in the stream, waste hurts more.
    score *= 1.0 + 0.9 * progress * norm_pr;

    // Reward tight fits (small post_residual) with a smooth inverse term.
    let tight = (1.0 - norm_pr).powi(3);
    score -= 12.0 * tight;

    // Perfect fit reward (post_residual == 0 handled naturally by quadratic term, add smooth bonus).
    if post_residual == 0 {
        score -= 20.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, reward strongly.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let slack = (pr - nx) / cap;
            score -= 15.0 * (1.0 - slack).powi(2);
        } else {
            // Next item won't fit here; mildly penalize leaving a residual close to but below nx.
            let gap = (nx - pr) / cap;
            score += 8.0 * (1.0 - gap).powi(2) * (1.0 - progress);
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item, heavily favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 + progress);
    }

    // New-bin candidate handling: empty bin should only win when it is genuinely attractive.
    if bin_residual == bin_capacity {
        // Penalize opening a new bin; stronger when many bins are open or mean residual is high.
        score += 30.0 + 2.0 * open_bins_count as f64 + 0.5 * mean_residual;
        // But late in the stream with a poor fit elsewhere, allow opening new bins more readily.
        score -= 20.0 * progress;
        // If next item is large, a fresh bin is more valuable.
        if next_item_size > 0 {
            score -= 0.15 * next_item_size as f64 * progress;
        }
    } else {
        // Reward using existing bins, especially ones below mean residual (consolidating waste).
        score -= 3.0;
        if mean_residual > 0.0 {
            let rel = pr / mean_residual;
            score += 5.0 * (rel - 1.0).powi(2) * 0.1;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residuals divisible by 10 are more reusable
    let pr = post_residual;
    if pr > 0 {
        if pr % 10 == 0 {
            score -= 6.0; // clean class, very reusable
        } else if pr % 5 == 0 {
            score -= 2.5;
        } else if pr <= 9 {
            score += 25.0; // tiny dead space
        } else {
            score += 4.0;
        }
    } else {
        score -= 12.0; // perfect fit
    }

    // Integer-division thresholds: does post_residual fit typical small items?
    if pr >= 10 && pr < 20 {
        score -= 3.0; // can host smallest class
    }

    // Lookahead coupling: harmonic match between next item and post_residual
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 8.0;
            // exact-ish modular match
            if pr % next_item_size == 0 {
                score -= 5.0;
            }
        } else {
            // next item won't fit here anyway; slight penalty for large leftover
            score += (next_item_size as f64 - pr as f64).min(20.0) * 0.1;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: neutral-ish, only chosen when open bins are bad
    if bin_residual == bin_capacity {
        score += 18.0 + 0.15 * (open_bins_count as f64);
    }

    // Slight preference for tighter bins overall
    score += (mean_residual - bin_residual as f64) * 0.05;

    // Late-stream pressure: consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to ever hold a
    // plausible future item (below the minimum item size of 1, and more
    // practically below the lookahead item) are heavily penalized.
    let dead_threshold = next_item_size.max(10) as f64;
    if (post_residual as f64) < dead_threshold {
        // Unusable gap: the smaller it is, the worse the waste ratio.
        let waste_ratio = 1.0 - (post_residual as f64) / bin_capacity as f64;
        score += 40.0 * waste_ratio * waste_ratio;
    }

    // Perfect or near-perfect fits are strongly rewarded.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post
    // residual, this placement chains beautifully.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if (post_residual as i64 - next_item_size as i64).abs() <= 3 {
            score -= 12.0;
        } else if post_residual < next_item_size && post_residual > 0 {
            // Gap just below next item: likely dead space for the lookahead.
            score += 8.0;
        }
    }

    // Last-chance pressure: if this is the only bin that fits, prefer using
    // it over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones
    // (the empty-bin candidate gets penalized via its huge residual handled
    // implicitly, but add explicit pressure proportional to open bins).
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus scaling with number of open bins.
        score += 10.0 + 2.5 * open_bins_count as f64;
        // But if no open bin fits at all, opening is forced anyway; soften.
        if fitting_bins_count == 0 {
            score -= 5.0;
        }
    } else {
        // Using an existing bin relieves open-bin pressure slightly.
        score -= 1.5 * open_bins_count as f64;
    }

    // Mean-residual coupling: when open bins are on average roomy, prefer
    // consolidating into them; when they are tight, avoid overfilling.
    if bin_residual != bin_capacity {
        let roominess = mean_residual - post_residual as f64;
        score += 0.05 * roominess;
    }

    // Stream progression: late in the stream, waste matters more since
    // fewer future items remain to fill leftover gaps.
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * (post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits snugly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            // Perfect 2-chain: extremely attractive.
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Fits, reward proportional to tightness of the second fit.
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 - slack * 0.8;
            // Bonus if the pair nearly fills the bin.
            let combined = (item_size + next_item_size) as f64 / bin_capacity as f64;
            if combined > 0.95 {
                score -= 25.0;
            } else if combined > 0.85 {
                score -= 10.0;
            }
        } else {
            // Next item won't fit here after placement: penalize leaving dead space
            // that is too small for the upcoming item.
            let waste = (post_residual as f64) / bin_capacity as f64;
            score += 15.0 * waste;
            if post_residual < next_item_size && post_residual < 10 {
                score += 20.0; // tiny unusable fragment
            }
        }
    } else {
        // Last item: just minimize residual.
        score += 5.0;
    }

    // Relative-to-mean coupling: prefer bins tighter than average when lookahead fails.
    if post_residual as f64 > mean_residual {
        score += 0.35 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.15 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0;
    }

    // New-bin candidate handling: keep it neutral-to-slightly-attractive only when
    // no good fit exists (large post_residual waste) or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Opening a new bin costs ~one bin of capacity; make its score track the
        // "virtual residual" so it wins only when all fits are terrible.
        score = 50.0 + 0.5 * (bin_capacity as f64) * (1.0 - progress) + 0.2 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0; // new bin can always host the next item
        }
    }

    // Mild pressure to close nearly-full bins.
    let fill = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 8.0 * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item nearly fills the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fill_ratio * fill_ratio;

    // Dead-space penalty: small post_residual that is still nonzero is fine,
    // but a mid-range leftover (hard to fill later) is penalized.
    if post_residual > 0 {
        let pr = post_residual as f64;
        let dead_zone = (pr >= 1.0 && pr < 10.0) as f64 * 6.0
            + (pr >= 10.0 && pr <= 30.0) as f64 * 14.0;
        score += dead_zone;
    } else {
        // Perfect fill.
        score -= 25.0;
    }

    // Lookahead coupling: reward if the next item fits into the post residual,
    // penalize if it cannot (leftover likely becomes dead space).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0 + 0.15 * next_item_size as f64;
        } else {
            let waste = next_item_size as f64 - post_residual as f64;
            score += 0.25 * waste.min(60.0);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 22.0;
    }

    // Global state: many open bins with high mean residual -> discourage
    // spreading; few open bins -> mild encouragement to reuse.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);
    score += 0.08 * (mean_residual - post_residual as f64);

    // New-bin candidate calibration: an empty bin has residual == capacity,
    // so its raw score is high; only beat it when the fit is genuinely tight.
    if bin_residual == bin_capacity {
        score += 12.0 + 0.1 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    // Base: prefer small post-residual (tight fit), smoothed non-linearly
    let mut score = post * (1.0 + 0.8 * norm_post * norm_post);

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - norm_post;
    score -= 12.0 * tightness * tightness * (0.5 + progress);

    // Non-linear coupling: post_residual interacting with item size
    score += 4.0 * norm_post * norm_item * (1.0 - norm_item);

    // Lookahead: penalize leaving residuals that don't fit the next item well
    if next_item_size > 0 {
        let fits_next = (post_residual as i64 - next_item_size as i64).max(0) as f64;
        let waste_next = 1.0 - (fits_next / cap);
        score += 6.0 * norm_post * waste_next * (0.3 + 0.7 * progress);
        // Bonus if post residual exactly accommodates next item
        if next_item_size <= post_residual {
            let snug = 1.0 - ((post_residual - next_item_size) as f64 / cap);
            score -= 5.0 * snug * snug * norm_next;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 + 10.0 * progress;
    }

    // Many fitting bins: mildly deprioritize (keep flexibility)
    if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Mean residual coupling: penalize bins far from the fleet mean
    score += 3.0 * ((post - mean_residual) / cap).abs();

    // New-bin candidate: penalize unless current residuals are badly fragmented
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let fragmentation = (mean_residual / cap) * (open_bins_count as f64).sqrt();
        let pressure = 1.0 - (fragmentation / (1.0 + fragmentation));
        score += 20.0 * (1.0 - progress) + 10.0 * pressure;
        // Allow new bin late in stream if mean residual is tiny (dead space everywhere)
        if mean_residual < norm_item * cap * 0.5 {
            score -= 18.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Harmonic class of the post-residual: bins whose leftover falls into
    // "small residue classes" (mod 10) are more likely reusable by future
    // small items, so reward them.
    let post_u = post_residual;
    let class = post_u % 10;
    if post_u > 0 {
        match class {
            0 => score -= 12.0,                    // exact decade residue: highly reusable
            1..=3 => score -= 6.0,                 // tight, likely fillable by 10..30 items
            4..=7 => score -= 2.0,                 // moderately useful
            8..=9 => score += 4.0,                 // awkward sliver class
            _ => {}
        }
    }

    // Integer-division threshold: post_residual <= cap/4 is premium dead-space
    // territory (bin nearly full) — reward strongly.
    if post_u <= bin_capacity / 4 {
        score -= 15.0;
    } else if post_u <= bin_capacity / 2 {
        score -= 5.0;
    } else {
        // Large leftover: bin stays very open; mild penalty relative to mean.
        score += (post - mean_residual).max(0.0) * 0.25;
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // this placement chains perfectly — big reward.
    if next_item_size > 0 {
        if next_item_size == post_u {
            score -= 25.0;
        } else if next_item_size < post_u {
            let nxt = next_item_size as f64;
            let nxt_class = (next_item_size % 10) as f64;
            // reward if next item's harmonic class aligns with post class
            if next_item_size % 10 == post_u % 10 && post_u > next_item_size {
                score -= 8.0;
            }
            // penalty proportional to wasted space the next item can't use
            score += (post - nxt).min(cap * 0.5) * 0.05 + nxt_class * 0.05;
        } else {
            // next item won't fit here regardless; slight bonus for tight fit now
            score -= 3.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate (empty bin): penalize unless current bin would leave
    // a large awkward residual while the stream is young (plenty of items left).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste_here = (bin_residual - item_size) as f64;
        // Opening a new bin is attractive early in the stream with big leftovers
        let open_bonus = (1.0 - progress) * waste_here * 0.35;
        score = cap as f64 - open_bonus - 10.0;
        if post_u % 10 == 0 {
            score -= 5.0; // fresh bin leaves a clean decade residual
        }
    }

    // Mild penalty for spreading across too many open bins.
    score += open_bins_count as f64 * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: any leftover gap that no future item (min size 1)
    // could be assumed to fill well is penalized. Gaps below 10 are near-unusable
    // for typical streams, but a gap of exactly 0 is a perfect fit -> reward it.
    if post_residual == 0 {
        score -= 60.0; // perfect closure, strongly favored
    } else if post_residual < 10 {
        score += 45.0; // unusable sliver: heavy dead-space penalty
    } else if post_residual < 25 {
        score += 8.0;  // marginal gap: mild penalty
    }

    // Last-chance pressure: if this is the ONLY open bin that fits the item,
    // using it avoids opening a new bin -> strong reward.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: mildly favor reusing existing bins over proliferation,
    // scaled by how crowded the bin pool already is.
    if bin_residual != bin_capacity {
        score -= 2.0 + (open_bins_count as f64).min(20.0) * 0.3;
    }

    // New-bin candidate (bin_residual == bin_capacity): discourage by default;
    // only attractive when the item is large enough that a fresh bin wastes little.
    if bin_residual == bin_capacity {
        let waste = (bin_capacity - item_size) as f64;
        score += 25.0 + waste * 0.5;
        // If the lookahead item is large, a fresh bin preserves flexibility: soften penalty.
        if next_item_size >= 50 {
            score -= 15.0;
        }
    }

    // Lookahead coupling: reward placements that leave room for the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // --- 2-step lookahead matching ---
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect match: next item exactly fills this bin -> strong reward
            score -= 45.0;
        } else if post_residual > next_item_size {
            // Next item can also fit here -> mild reward scaled by leftover slack
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 - slack * 0.08;
        } else {
            // Dead space for the next item: penalize proportionally to mismatch
            let mismatch = (next_item_size - post_residual) as f64;
            score += mismatch * 0.6;
            // Tiny residuals are nearly unusable dead space
            if post_residual < 10 {
                score += 25.0 + (10 - post_residual) as f64 * 2.0;
            }
        }
    } else {
        // Last item: any bin that fits is fine; prefer tightest fit
        score -= 30.0;
    }

    // --- Last-chance bin: if this is the only fitting bin, avoid opening a new bin ---
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when existing bins fit poorly
        // (large post_residual waste elsewhere) or few bins are open.
        let waste_pressure = (mean_residual - post_residual as f64).max(0.0);
        score += 35.0 - waste_pressure * 0.3 - (open_bins_count as f64) * 1.5;
        // Late in the stream, prefer consolidating into open bins
        score += progress * 15.0;
        // Large items early: starting fresh can be good
        if item_size >= 60 && open_bins_count <= 2 {
            score -= 10.0;
        }
    }

    // --- Relative to mean residual: prefer bins tighter than average ---
    score += (mean_residual - post_residual as f64) * 0.15;

    // Mild preference for filling nearly-full bins
    if post_residual as f64 <= mean_residual * 0.25 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Time horizon: early in the stream, be frugal; late, be flexible.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward near-perfect fits strongly (waste minimization).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0 + 2.0 * post_residual as f64;
    }

    // Lookahead: if this placement leaves room exactly (or nearly) for the next
    // item, this is a chained fit — reward it. If the leftover is just barely
    // too small for the next item, penalize slightly (dead space).
    if next_item_size > 0 {
        let post = post_residual as f64;
        let nxt = next_item_size as f64;
        if post >= nxt {
            let slack = post - nxt;
            if slack <= 5.0 {
                score -= 18.0 - slack; // near-perfect chain
            } else {
                score -= 6.0 * (1.0 - slack / bin_capacity as f64);
            }
        } else if post > 0.0 && post >= 10.0 {
            score += 8.0 * (1.0 - post / 40.0).max(0.0); // small dead pocket
        }
    }

    // Last-chance bin: if this is the ONLY bin that fits, using it avoids
    // opening a new bin — strong reward, scaled by how well it fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0 + 0.3 * item_size as f64;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Prefer opening a new bin only when the item fits poorly everywhere else
    // (large post_residual waste) or when few bins are open (early stream).
    if bin_residual == bin_capacity {
        let waste = post_residual as f64;
        let openness = 1.0 / (1.0 + open_bins_count as f64);
        let mean_gap = mean_residual - item_size as f64; // how much worse than average
        score += 30.0
            - 0.4 * waste
            - 40.0 * openness
            - 3.0 * mean_gap.max(0.0)
            + 15.0 * progress; // later in stream: reuse bins more aggressively
    } else {
        // Favor bins whose residual is close to the item (tight packing).
        let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
        score += 10.0 * tightness;
        // Slight preference for bins below-average residual (consolidate).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    // Mild global pressure: many open bins -> prefer filling existing ones.
    score += 0.5 * open_bins_count as f64 * (1.0 - progress);

    // Tiny tie-break noise-free deterministic jitter based on step parity.
    if step_index % 2 == 0 { score -= 0.01; }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr_norm = pr / cap;
    let fit = fitting_bins_count as f64;
    let open_c = open_bins_count as f64;

    // Base: prefer small post-residual (tight fit)
    let mut score = pr;

    // Smooth non-linear polynomial coupling with stream progress:
    // early on, tolerate larger residuals; later, penalize dead space quadratically.
    let coupling = pr_norm * pr_norm * (0.5 + 2.0 * progress) * cap;
    score += coupling;

    // Smooth cubic term: very small residuals are excellent (fill bins completely)
    score -= 20.0 * (1.0 - pr_norm).powi(3) * (0.5 + progress);

    // Scarcity bonus: if this is the only fitting bin, reward using it
    let scarcity = (1.0 / (fit + 1.0)).powf(1.5);
    score -= 15.0 * scarcity;

    // Lookahead: reward if next item fits the post-residual (smooth compatibility)
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let compat = (pr - ns).abs() / cap;
        score += 25.0 * compat * compat;
        // smooth bonus when next item exactly fits remaining space
        score -= 10.0 * (-compat * 10.0).exp();
    }

    // Mild penalty for spreading across many open bins when mean residual is high
    score += 0.5 * open_c * (mean_residual / cap).powi(2);

    // New-bin candidate: penalize opening a new bin unless item is large / late stream
    if bin_residual == bin_capacity {
        let size_frac = item_size as f64 / cap;
        score += 12.0 - 10.0 * size_frac - 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify dead space by mod-10 bands.
    let pr = post_residual;
    let class = match pr {
        0 => 0.0,                 // perfect fit: best possible
        1..=10 => 1.0,            // near-perfect sliver
        11..=20 => 2.0,           // small-item zone
        21..=50 => 3.0,           // medium dead zone
        _ => 4.0,                 // large residual, still reusable
    };
    score += class * 3.0;

    // Perfect fit bonus
    if pr == 0 {
        score -= 60.0;
    }

    // Lookahead: reward if next item fits into post_residual (chaining)
    if next_item_size > 0 && pr >= next_item_size {
        score -= 12.0 + (next_item_size as f64) * 0.15;
    } else if next_item_size > 0 && pr > 0 {
        // penalize residuals that block the next item, scaled by how close we came
        let miss = (next_item_size - pr) as f64;
        score += miss.min(40.0) * 0.6;
    }

    // Integer-division thresholds on post_residual (harmonic bands of cap/4)
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    if pr == quarter || pr == half || pr == 3 * quarter {
        score -= 5.0; // canonical reusable classes
    }
    if pr > 0 && pr < 10 {
        score += 8.0; // slivers are nearly dead space
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Prefer fuller bins among many open bins (mild pressure to close bins)
    let fill_frac = 1.0 - (bin_residual as f64) / cap;
    score -= fill_frac * 10.0;

    // Progress term: later in stream, be slightly more greedy about tight fits
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * (100.0 - post_residual as f64).min(60.0) * 0.1;

    // New-bin candidate: make it a mediocre default so it wins only over bad fits
    if bin_residual == bin_capacity {
        score = cap * 0.75 + (open_bins_count as f64) * 2.0;
        // allow fresh bin early when many bins already open and fit is poor is handled by others scoring high
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item
    // (size 1 in the general interface, conservatively < 10) are unusable waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    }

    // Perfect or near-perfect fits are heavily rewarded.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Reward bins whose residual after placement can still host the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Residual that blocks the next item but is not zero: mild penalty.
        score += 8.0;
    }

    // Open-bin pressure: discourage spreading across many bins,
    // but relax pressure when this bin is the last chance.
    if fitting_bins_count > 1 {
        score += open_bins_count as f64 * 0.7;
    } else {
        score -= 12.0; // last-chance bin: strongly prefer filling it
    }

    // Prefer bins tighter than the average residual (good fits).
    score += (mean_residual - bin_residual as f64) * 0.25;

    // New-bin candidate: it is only attractive if it avoids creating dead space
    // elsewhere; make the empty-bin baseline moderate so poor fits into open
    // bins with small residuals still win, but very poor fits open a new bin.
    if bin_residual == bin_capacity {
        score = 45.0 + open_bins_count as f64 * 0.3 - (post_residual as f64) * 0.1;
        if post_residual < 10 && post_residual > 0 {
            score += 20.0;
        }
    }

    // Late-stream consolidation: as the stream ends, favor tightening existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Is this a brand-new empty bin candidate?
    let is_new_bin = bin_residual == bin_capacity;

    // Progress through the stream (0..1)
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };

    // ---- 2-step lookahead core ----
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64 - nxt).abs() < 1.0 {
            // Perfect match: next item exactly fills this bin afterwards
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item can also fit here afterwards: reward, scaled by tightness
            let tight = 1.0 - (post_residual as f64 - nxt) / bin_capacity as f64;
            score -= 25.0 * tight;
        } else {
            // Dead space: next item cannot use the remainder; penalize proportionally
            let waste = (nxt - post_residual as f64) / bin_capacity as f64;
            score += 30.0 * waste;
        }
    } else {
        // Last item: just minimize leftover waste
        score += 10.0;
    }

    // ---- Relative-to-mean residual coupling ----
    // Prefer bins whose post residual deviates favorably from mean residual:
    // leaving less than the mean is good (tight packing).
    let pr = post_residual as f64;
    if pr < mean_residual {
        score -= 0.5 * (mean_residual - pr);
    } else {
        score += 0.3 * (pr - mean_residual);
    }

    // ---- Last-chance bin bonus ----
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 15.0 + 10.0 * progress;
    }

    // ---- New-bin candidate handling ----
    if is_new_bin {
        // Opening a new bin is only attractive when current item leaves
        // a large unusable remainder in existing bins, or many bins are open.
        let tight_fit_penalty = if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            20.0
        } else {
            0.0
        };
        score += 35.0                       // base reluctance to open new bin
                 + tight_fit_penalty
                 - 2.0 * open_bins_count as f64 * (1.0 - progress);
    }

    // Small tie-break: prefer fuller bins overall
    score -= 0.05 * (bin_residual - post_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic penalty on leftover space.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead coupling: reward leaving room exactly sized for the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual > next_item_size {
            // usable leftover for next item: mild reward proportional to slack match
            score -= 6.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // dead space relative to next item: penalty grows with wasted gap
            score += 4.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Time horizon: late in the stream, avoid opening new bins (waste matters more).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses and when open bins could fit.
        score += 30.0 * (0.5 + 0.5 * progress);
        if fitting_bins_count > 0 {
            score += 20.0;
        }
        score -= open_bins_count as f64 * 0.5; // slight encouragement to reuse when many bins open
    } else {
        // Prefer bins with residual below mean (denser bins) mildly.
        score += 0.05 * (mean_residual - bin_residual as f64);
    }

    // Crowding: when many bins can fit the item, prefer the tightest; add small tie-break noise-free offset.
    if fitting_bins_count > 1 {
        score += 0.1 * (fitting_bins_count as f64 - 1.0) * (post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with non-linear polynomial coupling to stream progress.
    let mut score = pr;

    // Quadratic/cubic dead-space shaping: large residuals matter more late in stream.
    score += 40.0 * norm_pr * norm_pr * (0.5 + progress);

    // Tight fits rewarded (post_residual small relative to item).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fit_ratio * fit_ratio;

    // Lookahead coupling: reward leaving space for the next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let slack = (pr - nx) / cap;
            score -= 18.0 * (1.0 - slack) * (1.0 - slack);
        } else {
            score += 12.0 * (nx - pr) / cap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Penalize scattering across many open bins mildly.
    score += 0.5 * (open_bins_count as f64).ln().max(0.0);

    // Deviation from mean residual: prefer bins near mean to keep balance.
    score += 3.0 * (pr - mean_residual).abs() / cap;

    // New-bin candidate: prefer only when residuals are fragmented or early stream.
    if bin_residual == bin_capacity {
        let new_bin_bonus = 20.0 * (1.0 - progress) + 10.0 * (mean_residual / cap).min(1.0);
        score += new_bin_bonus;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic decay of post_residual
    let pr = post_residual as f64;
    score -= 40.0 * ((bin_capacity as f64 - pr) / bin_capacity as f64).powi(3);

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 200.0;
    }

    // Harmonic class logic: classify post_residual into modulo classes of capacity
    let class = post_residual % (bin_capacity / 4).max(1);
    let class_penalty = match class {
        0 => -25.0,           // quarter-aligned residual: highly reusable
        1 | 2 | 3 => 15.0,    // tiny unusable slivers
        _ => 0.0,
    };
    score += class_penalty;

    // Integer-division thresholds on post_residual
    let quarters = post_residual / (bin_capacity / 4).max(1);
    score += match quarters {
        0 => 30.0,            // dead space < 25
        1 => 5.0,             // 25..49: usable for small items
        2 => -8.0,            // 50..74: very reusable
        _ => -12.0,           // large residual
    } as f64;

    // Lookahead coupling: does next item fit in post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 20.0; // chain placement enabled
            let slack = (post_residual - next_item_size) as f64;
            if slack < 10.0 {
                score -= 15.0; // near-perfect two-item packing
            }
        } else {
            score += 10.0; // this bin's remainder is wasted w.r.t. next item
        }
    }

    // Last-chance bin: strong preference to use the only fitting bin
    if fitting_bins_count == 1 {
        score -= 35.0;
    } else if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate: open a fresh bin only when fits are poor or many bins open
    if bin_residual == bin_capacity {
        let poor_fit = (pr / bin_capacity as f64) > 0.55;
        let crowded = open_bins_count as f64 > 6.0;
        if poor_fit || crowded {
            score -= 30.0;
        } else {
            score += 25.0; // prefer existing bins early on
        }
        // slight drift: encourage consolidation late in the stream
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * progress;
    }

    // Penalize bins whose residual is far below mean (fragmented bins)
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score += 0.15 * dev;
    } else {
        score -= 0.05 * (-dev);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any realistic item
    // (items are >= 1, but small gaps < 10 are near-unusable) are heavily penalized.
    if post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 3.0;
    } else if post_residual <= 25 {
        // Small-but-usable gaps: moderate penalty to avoid stranding capacity.
        score += (25 - post_residual) as f64 * 1.2;
    }

    // Reward tight fits: fraction of bin used by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= fill * 30.0;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // With multiple options, mild pressure toward tighter fits is already handled;
        // add slight preference against scattering across many bins.
        score += 2.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones
    // (a new-bin candidate has bin_residual == bin_capacity, so its post_residual
    // is large; add extra penalty so good fits win over new bins).
    if bin_residual == bin_capacity {
        score += 15.0 + open_bins_count as f64 * 1.5;
        // But if the item is large and would leave a big gap in existing bins anyway,
        // new bin becomes relatively more attractive (post_residual already large).
        if item_size >= 60 {
            score -= 10.0;
        }
    }

    // Lookahead: if next item would fit exactly in the post_residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        if slack < 10.0 {
            score -= 12.0; // next item nearly fills this bin perfectly
        } else {
            score -= 4.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Dead space that even the next item can't use.
        score += 6.0;
    }

    // Mean-residual coupling: if this bin's residual is far below average, it is
    // already "cramped" — prefer filling it rather than spreading load.
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score -= dev.min(50.0) * 0.3;
    }

    // Early in the stream, keep bins open a bit more aggressively (better packing later).
    if total_items > 0 && (step_index as f64) / (total_items as f64) < 0.2 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post-residual (best fit), slightly scaled.
    score = post_residual as f64 * 1.0;

    // Aggressive 2-step lookahead: if the next item fits the post-residual exactly,
    // strongly reward this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item fits, but leaves a further gap; reward proportionally less
            // the tighter the chain fit.
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= 30.0 - 0.5 * chain_waste.min(60.0);
        } else {
            // Next item cannot follow: penalize leaving medium dead space.
            let gap = post_residual as f64;
            if gap > 0.0 && gap < 10.0 {
                score += 15.0; // unusable sliver for typical items
            }
        }
    }

    // Relative-to-mean coupling: bins with residual far below mean are already
    // "tight"; placing here consolidates waste. Reward bins whose residual is
    // close to the item (tight fit) relative to the mean.
    let mean_gap = mean_residual - post_residual as f64;
    score += 0.3 * mean_gap.max(0.0);
    score -= 0.2 * (-mean_gap).max(0.0);

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it attractive only when no open bin fits decently.
    if bin_residual == bin_capacity {
        // Neutral base residual (100), but discourage when open bins exist and
        // the item fits well somewhere.
        score += if open_bins_count > 0 && fitting_bins_count > 0 {
            40.0
        } else {
            -10.0
        };
    }

    // Early stream: be slightly more willing to open bins to build diversity.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic bonus for very small post-residual.
    let tight = (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * (1.0 - tight) * (1.0 - tight) * (1.0 - tight);

    // Penalize wasting large residuals on small items (dead-space creation).
    let waste_ratio = (post_residual as f64) / (bin_residual.max(1) as f64);
    score += 25.0 * waste_ratio * waste_ratio;

    // Lookahead: reward if the next item fits exactly into post_residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 18.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            // Next item cannot follow here: mild penalty proportional to leftover.
            score += 6.0 * (post_residual as f64) / (bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin should only win when
    // no open bin offers a decent fit. Penalize empty-bin placement
    // unless the item is large relative to capacity.
    if bin_residual == bin_capacity {
        let size_frac = (item_size as f64) / (bin_capacity as f64);
        let mut new_bin_pen = 45.0 - 40.0 * size_frac;
        // Late in the stream, prefer closing out open bins rather than opening new ones.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        new_bin_pen += 20.0 * progress;
        // Many open bins with high mean residual: opening new bins is wasteful.
        new_bin_pen += (open_bins_count as f64).sqrt() * 3.0
            + 10.0 * (mean_residual / (bin_capacity as f64)).clamp(0.0, 1.0);
        score += new_bin_pen;
    } else {
        // Reward filling existing bins, more so as stream progresses.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * progress * (1.0 - (bin_residual as f64) / (bin_capacity as f64));
    }

    // Prefer bins whose residual is far below the mean (they are the "odd" ones
    // worth consolidating), but only mildly.
    if bin_residual != bin_capacity {
        let diff = (bin_residual as f64) - mean_residual;
        score += 0.05 * diff;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_post = post / cap;

    // Base: waste after placement
    let mut score = post;

    // Non-linear quadratic coupling of post residual with stream progress:
    // later in the stream, small residuals become increasingly useless -> penalize more
    score += 18.0 * norm_post * norm_post * (0.5 + progress);

    // Reward tight fits (small post residual) with smooth saturation
    score -= 12.0 * (1.0 - norm_post) * (1.0 - norm_post);

    // Interaction: residual relative to mean residual across open bins
    let mean_norm = mean_residual / cap;
    score += 8.0 * (norm_post - mean_norm) * (norm_post - mean_norm) * (1.0 + progress);

    // Lookahead coupling: favor bins whose post residual can host next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits_next = if post >= nxt { 1.0 } else { 0.0 };
        let gap = (post - nxt).abs() / cap;
        score -= 10.0 * fits_next * (1.0 - gap * gap);
        score += 6.0 * (1.0 - fits_next) * (nxt / cap);
    }

    // Last-chance bin: strong reward to use the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - norm_post);
    }

    // Penalize spreading across too many open bins when many fit
    score += 0.6 * (fitting_bins_count as f64).sqrt() * progress;

    // Mild reward for consolidating into fewer bins as stream progresses
    score -= 0.4 * (open_bins_count as f64).ln().max(0.0) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls on "nice"
    // fractions of capacity (0, 25, 50, 75) are more reusable.
    let pr = post_residual;
    if pr == 0 {
        score -= 40.0; // perfect fit is always best
    } else {
        let frac = pr as f64 / cap;
        // reward residuals near k/4 capacity fractions
        let k4 = (frac * 4.0).round();
        let dist = (frac * 4.0 - k4).abs();
        score -= (1.0 - dist) * 6.0 * (1.0 - frac);
        // modulo classes: residuals divisible by 10 are more likely to match
        // integer item sizes drawn from 1..=100
        if pr % 10 == 0 { score -= 4.0; }
        if pr % 25 == 0 { score -= 3.0; }
        // dead space: residual smaller than any plausible next item
        if pr < 10 { score += 25.0; }
    }

    // Lookahead coupling: can next item exactly fill this bin's post_residual?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 50.0; // chain fit: this placement enables a perfect follow-up
        } else if next_item_size < pr {
            let slack = (pr - next_item_size) as f64;
            // harmonic threshold classes on slack
            if slack <= 10.0 { score -= 8.0; }
            else if slack <= 25.0 { score -= 3.0; }
            else if slack > 60.0 { score += 4.0; } // too loose, wasteful pairing
        } else {
            // next item cannot use this bin's leftover at all
            score += 6.0;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only open a new bin when current fit is terrible
    // (large dead space) or no real alternative exists.
    if bin_residual == bin_capacity {
        score += 55.0; // base penalty for opening a new bin
        if post_residual < 20 && fitting_bins_count >= 1 {
            score += 20.0; // opening a bin for a big item wastes the rest
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
    }

    // Tight fit reward: prefer bins where the item fills most of the residual
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill * 12.0;

    // Mild consolidation pressure: fewer open bins is better late in stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.05 * (1.0 - progress);

    // Tie-break toward bins with residuals close to the mean (keeps balance)
    score += ((post_residual as f64 - mean_residual) / cap).abs() * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // even the smallest plausible item are pure waste -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual == 0 {
        // Perfect closure of a bin is ideal.
        score -= 40.0;
    }

    // Penalize gaps that cannot fit the lookahead item but could have.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // Reward tight fits: waste ratio relative to item size.
    score += (post_residual as f64) / (item_size.max(1) as f64) * 10.0;

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // over opening new bins; the new-bin candidate gets residual == capacity,
    // which we penalize progressively as open_bins_count grows.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 8.0 + 20.0;
        // Still allow opening when fitting options are scarce and this bin
        // would otherwise be a bad home.
        if fitting_bins_count <= 1 && post_residual >= 10 {
            score -= 30.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid proliferation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is the "driest" bin and best candidate to absorb the item.
    score -= (mean_residual - bin_residual as f64) * 0.5;

    // Early in the stream, be slightly more willing to open bins (future
    // flexibility); late in the stream, consolidate aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score -= (1.0 - progress) * 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is always best.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when the next item exactly fills the post-residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size <= post_residual {
            // next item fits: penalize proportionally to wasted slack after chaining
            let chained = post_residual - next_item_size;
            score += chained as f64 * 0.5;
        } else {
            // next item cannot use this residual: penalize dead space more harshly
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
    }

    // Prefer bins whose residual is below the mean residual (tighter bins absorb items better).
    score += (post_residual as f64 - mean_residual) * 0.6;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: keep it moderately attractive so it wins only when
    // open bins offer a genuinely bad fit (large post_residual).
    if bin_residual == bin_capacity {
        score += 40.0 + post_residual as f64 * 0.2;
    }

    // Late in the stream, consolidation matters more: penalize spreading slack.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * post_residual as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Reward tight fits: squashed post-residual.
    score -= (cap - post) * (cap - post) / cap;

    // Penalize dead space that cannot host the lookahead item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post < nxt {
            score += 18.0 * (1.0 - post / nxt);
        } else {
            score -= 6.0 * (post - nxt) / cap;
        }
    }

    // Last-chance bonus: avoid opening a new bin when this is the only fit.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when existing bins fit poorly.
    if bin_residual == bin_capacity {
        let fit_ratio = item_size as f64 / cap;
        let crowding = open_bins_count as f64 / (1.0 + mean_residual / cap);
        score = cap * (1.0 - 0.35 * fit_ratio) + 10.0 * crowding;
        if fitting_bins_count <= 1 {
            score -= 30.0; // no alternative anyway
        }
    }

    // Late in the stream, consolidate aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 12.0 * progress * (1.0 - post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr_norm = pr / cap;

    // Base: prefer tight fits (small post_residual), with non-linear emphasis.
    let mut score = pr + 40.0 * pr_norm * pr_norm * cap;

    // Stream progress coupling: later in the stream, dead space matters more.
    score += 30.0 * progress * pr_norm * (1.0 - pr_norm) * cap * 0.1;

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 100.0;
    } else if pr_norm < 0.1 {
        score -= 25.0 * (0.1 - pr_norm);
    }

    // Lookahead: penalize post_residual that can't fit the next item.
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr >= ns {
            score -= 10.0 * (1.0 - pr_norm) * (ns / cap);
        } else {
            score += 8.0 * (ns - pr) / cap;
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 + 10.0 * progress;
    }

    // New-bin candidate: penalize mildly, more when open bins fit well.
    if bin_residual == bin_capacity {
        score += 15.0 + 0.5 * open_bins_count as f64;
        if next_item_size > 0 && (next_item_size as f64) <= cap {
            score -= 5.0;
        }
    }

    // Mean residual context: avoid bins far from the fleet average when average is high.
    score += 0.05 * (mean_residual - pr).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits (0) and "harmonic" residuals
    // that divide capacity cleanly are golden; prime-ish / awkward residuals penalized.
    let pr = post_residual;
    if pr == 0 {
        score -= 400.0; // perfect fit: always excellent
    } else {
        // Harmonic divisor bonus: residuals like 50, 25, 20, 10, 5, 2 divide 100
        if bin_capacity % pr == 0 {
            score -= 120.0;
        }
        // Modulo classes on post_residual: multiples of 10 are "clean" zones
        let pr_mod = pr % 10;
        score -= match pr_mod {
            0 => 90.0,
            5 => 60.0,
            2 | 8 => 25.0,
            _ => 0.0,
        };
        // Integer-division threshold: small dead space (<20) is usually unusable
        if pr < 20 {
            score += (20 - pr) as f64 * 3.0;
        }
        // Mid-band residual (40..70) is the most reusable zone
        if pr >= 40 && pr <= 70 {
            score -= 70.0;
        }
    }

    // Lookahead coupling: does next_item_size fit harmonically into post_residual?
    if next_item_size > 0 {
        let n = next_item_size;
        if n <= pr {
            // exact or near-exact match with lookahead
            let gap = pr - n;
            if gap == 0 {
                score -= 300.0;
            } else if gap % 10 == 0 || bin_capacity % gap == 0 {
                score -= 90.0;
            } else {
                score -= 20.0;
            }
        } else {
            // lookahead cannot use this bin's residual: penalize proportionally
            score += (n - pr) as f64 * 0.8;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 {
        score -= 150.0;
    } else {
        // crowding bonus: prefer fuller bins among many candidates
        score -= (fitting_bins_count as f64).ln().max(0.0) * 10.0;
    }

    // Tightness relative to capacity: reward high fill ratio (harmonic fractions)
    let fill = (bin_capacity - pr) as f64 / cap_f;
    score -= fill * fill * 100.0;

    // New-bin candidate logic: only attractive early in the stream or when
    // open bins are nearly full on average and item is awkward.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let awkward = (item_size % 10 != 0) as f64;
        let open_pressure = mean_residual / cap_f;
        let new_bin_score = cap_f - 260.0 * (1.0 - progress)
            - 180.0 * awkward
            - 200.0 * (1.0 - open_pressure).max(0.0)
            + 120.0 * progress;
        // compare against real bins: only win if it beats them
        score = score.min(new_bin_score);
        // never open a new bin when a perfect fit exists elsewhere
        if post_residual == 0 && bin_residual == bin_capacity {
            score += 1000.0;
        }
    }

    // Mild preference to spread across bins when many are open
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the minimum item
    // (1..10) are pure waste; penalize them super-linearly.
    if post_residual < 10 && post_residual > 0 {
        score += (10 - post_residual) as f64 * 8.0;
    }
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 50.0;
    }

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 20.0;

    // Penalize bins whose residual is much larger than the item (wasteful placement).
    if bin_residual > item_size {
        let waste_ratio = (bin_residual - item_size) as f64 / bin_capacity as f64;
        score += waste_ratio * 15.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap < 10 {
            score -= 30.0; // chain fit possible
        } else {
            score -= 10.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual && next_item_size <= 10 {
        // Next item could have used this residual if we left more space.
        score += 12.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones
    // (make new-bin candidate less attractive); when few are open, mild penalty
    // for spreading items across bins.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus scaling with open bins count.
        score += 35.0 + (open_bins_count as f64).sqrt() * 10.0;
        // But if no open bin fits well, allow opening: handled by relative scores.
        if post_residual == bin_capacity {
            score -= 5.0; // fresh bin is clean
        }
    }

    // Stream progression: late in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= progress * 8.0;
    }

    // Mean residual coupling: penalize placing into bins deviating from mean
    // to keep residuals balanced (avoids many near-empty and one sparse bin).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Aggressive 2-step lookahead: reward when next item fits into post_residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 18.0 * (1.0 - slack / bin_capacity as f64);
        // Extra bonus for near-perfect chain fit.
        if slack < 10.0 {
            score -= 15.0;
        }
    } else if next_item_size > 0 {
        // Penalize post_residual that is too small for the lookahead item (dead space).
        score += 0.35 * post_residual as f64 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Penalize if this bin is not the mean-residual band (avoid fragmenting fat bins).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: keep it attractive only when no good fit exists.
    if bin_residual == bin_capacity {
        score = post_residual as f64 + 45.0 - 25.0 * tightness;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0;
        }
        // Early in stream, opening bins is cheap; late, discourage it.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tight fit reward: strongly prefer bins where the item nearly fills residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize large dead space that small items could still use (post_residual sweet spot).
    if post_residual > 0 {
        // dead space below the minimum plausible item is pure waste
        let waste = if post_residual < 10 { post_residual as f64 } else { 0.0 };
        score += 6.0 * waste;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 18.0 * (1.0 - progress);
        score -= 8.0 * progress;
    }

    // Many open bins: prefer consolidating into existing bins rather than spreading.
    score += 0.35 * open_bins_count as f64;

    // Mean residual coupling: if this bin's residual is far below the mean, it is
    // "small leftovers" — good to fill it now and keep large residuals elsewhere.
    let residual_gap = mean_residual - bin_residual as f64;
    score -= 0.25 * residual_gap;

    // Lookahead: if the next item fits exactly in the post residual, reward this placement;
    // if the next item would fit better elsewhere (post residual too small), penalize mildly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 15.0; // perfect pairing
        } else if post_residual >= next_item_size {
            score -= 4.0;  // next item still fits here
        } else {
            // next item won't fit here; penalize proportionally to leftover waste
            score += 0.15 * post_residual as f64;
        }
    }

    // New-bin candidate handling: an empty bin has high post_residual; make it less
    // attractive than a decent existing fit, but attractive when existing fits are bad.
    if bin_residual == bin_capacity {
        // base penalty for opening a new bin
        score += 10.0;
        // early in the stream, opening bins is cheaper (builds flexibility)
        score -= 14.0 * (1.0 - progress);
        // if many bins are already open, discourage more
        score += 0.6 * open_bins_count as f64;
        // if only one fitting bin exists and it's this new bin, it's necessary anyway
        if fitting_bins_count <= 1 {
            score -= 25.0;
        }
    }

    // Mild time-horizon shaping: late in the stream, minimize waste aggressively.
    score += progress * (post_residual as f64 / bin_capacity as f64) * 8.0;

    // Small tie-breaker noise-free deterministic jitter based on state to break ties
    // toward bins with rounder residuals (multiples of 10 pack well with 10..80 items).
    if bin_residual % 10 == 0 {
        score -= 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;
    // Smooth non-linear coupling of post_residual with stream progress
    let coupling = norm_pr * (1.0 + progress * norm_pr) * (2.0 - progress);
    score += 40.0 * coupling;
    // Penalize large dead space quadratically, modulated by progress
    score += 30.0 * norm_pr * norm_pr * (0.5 + progress);
    // Reward tight fits (small post_residual) exponentially
    score -= 25.0 * (-pr / 20.0).exp();
    // Last-chance bin bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }
    // Lookahead: reward if next item fits into resulting residual
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 15.0 * (1.0 - pr / cap);
    } else if next_item_size > 0 {
        score += 10.0 * (next_item_size as f64 - pr) / cap;
    }
    // Mean residual alignment: prefer bins near the mean residual
    let dev = (pr - mean_residual).abs();
    score += 8.0 * (dev / cap);
    // New-bin candidate: penalize mildly unless current bins are fragmented
    if bin_residual == bin_capacity {
        let fragmentation = open_bins_count as f64 / (1.0 + mean_residual / cap);
        score += 20.0 - 5.0 * fragmentation;
    }
    // Progress-driven smooth bias toward consolidation later in stream
    score -= 10.0 * (progress * std::f64::consts::PI).sin();
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into
    // capacity-fraction buckets. Small classes (near 0 or near capacity) are
    // valuable; mid-range leftovers are "dead" space.
    let frac = post_residual as f64 / bin_capacity as f64;
    let class = (frac * 4.0).floor() as i32; // 0,1,2,3 harmonic classes
    match class {
        0 => score -= 18.0,           // almost perfectly filled
        1 => score -= 4.0,            // decent leftover
        2 => score += 10.0,           // awkward mid leftover
        _ => score += 2.0,            // large leftover, still usable
    }

    // Integer-division threshold: does post_residual admit common small classes?
    // Residuals divisible into halves/quarters of capacity are reusable.
    if post_residual > 0 {
        if post_residual % 2 == 0 { score -= 1.5; }
        if post_residual % 5 == 0 { score -= 1.5; }
        if post_residual % 10 == 0 { score -= 2.5; }
        if post_residual % 25 == 0 { score -= 3.0; }
    } else {
        score -= 30.0; // perfect closure
    }

    // Lookahead coupling: reward when post_residual can host next_item_size
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
        // extra reward if post_residual is close to next_item_size (tight fit next)
        let slack = (post_residual - next_item_size) as f64;
        if slack < 5.0 { score -= 6.0; }
    } else if next_item_size > 0 {
        score += 3.0; // next item cannot reuse this bin
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // current fit is bad and the stream is early/mid.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // baseline cost of a fresh bin
        let mut new_bin_score = bin_capacity as f64 - 25.0 + 20.0 * progress;
        // if next item is large, a fresh bin is more attractive
        if next_item_size > bin_capacity / 2 { new_bin_score -= 8.0; }
        // many open bins: discourage opening yet another
        new_bin_score += open_bins_count as f64 * 1.5;
        // if this bin would leave terrible dead space, new bin looks better
        if post_residual > 0 && post_residual < 10 { new_bin_score += 15.0; }
        score = score.max(new_bin_score);
        return new_bin_score.min(score) - (new_bin_score - score).abs() * 0.0 + new_bin_score - score;
    }

    // Prefer bins with residuals below the mean (consolidate emptier space usage)
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev;

    // Mild pressure to keep open bin count low
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever
    // hold a meaningful item are unusable dead space -> heavy penalty.
    let dead_threshold = 10u32; // smallest plausible item size
    if post_residual > 0 && post_residual < dead_threshold {
        score += 40.0 * (dead_threshold - post_residual) as f64;
    }

    // Perfect fit reward: zero residual is ideal.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward tight fits (post_residual small relative to item size).
    let tightness = post_residual as f64 / (item_size.max(1) as f64);
    score += 25.0 * tightness;

    // Penalize leaving a gap that the lookahead item cannot use,
    // but reward when the next item exactly fills the post residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0; // lookahead can still be placed here
        } else if post_residual > 0 {
            score += 15.0; // gap likely wasted for the lookahead
        }
        if post_residual == next_item_size && next_item_size > 0 {
            score -= 25.0; // perfect two-item chain fit
        }
    }

    // Open-bin pressure: with many open bins, prefer consolidating
    // into existing bins rather than spreading; also make the new-bin
    // candidate (bin_residual == bin_capacity) less attractive unless
    // no good fit exists.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 1.5 * open_bins_count as f64 * (0.5 + progress);

    if bin_residual == bin_capacity && bin_capacity > 0 {
        // New empty bin: base cost of opening a bin, reduced when the
        // item fits poorly everywhere else (few fitting bins).
        let scarcity = if fitting_bins_count <= 1 { 0.0 } else { 45.0 };
        score += 55.0 + scarcity - 0.2 * mean_residual;
    }

    // Last-chance bin: if this is the only bin that fits, strongly
    // favor using it over opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Mild preference for bins below mean residual (balances load).
    score += 0.1 * ((bin_residual as f64) - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when post_residual closely matches next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= (bin_capacity as f64 - gap) * 0.5;
        // Perfect chain bonus: next item exactly fills this bin afterward.
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // Penalize leaving a dead sliver that neither fits next item well nor is useful.
        if post_residual < next_item_size && post_residual < 10 {
            score += 25.0;
        }
    } else {
        // Last item: just minimize waste.
        score -= bin_capacity as f64 * 0.5;
    }

    // Reward tight fits relative to mean residual across open bins.
    let tightness = (bin_capacity as f64 - item_size as f64) - post_residual as f64;
    score -= tightness * 0.3;

    // Penalize bins far below mean residual (fragmented space).
    score += (mean_residual - post_residual as f64).abs() * 0.2;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a bin unless item is huge relative to capacity.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        score += 60.0 * (1.0 - fill_ratio);
        // Allow new bin if current item nearly fills it.
        if fill_ratio > 0.85 {
            score -= 70.0;
        }
    }

    // Late in stream: be greedier, prefer closing bins out.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small to ever be useful
    // (below the minimum item size range), but only mildly.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // strongly reward this placement (perfect chaining).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size < post_residual {
            // next item still fits here afterwards: good
            score -= 6.0 * (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
        } else {
            // next item won't fit in this bin's remainder
            score += 4.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin should only win
    // when the fit into existing bins is poor. Base penalty for new bin.
    if bin_residual == bin_capacity {
        score += 15.0;
        // If many bins are open with lots of slack, discourage new bins more.
        score += 0.5 * open_bins_count as f64;
        // But if mean residual is small (bins nearly full), a new bin is fine.
        score -= 0.1 * mean_residual;
        // Late in the stream, opening fresh bins is less costly.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * progress;
    } else {
        // Prefer filling bins that are already heavily loaded
        // (keep a few large-residual bins alive for big future items).
        let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
        score -= 5.0 * fill_ratio;

        // Slight preference for bins whose residual is near the mean
        // (keeps residual distribution balanced).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    // Early in the stream, be a bit more conservative about cramming
    // (keep flexibility); later, pack greedily.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 3.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Non-linear coupling: quadratic penalty on post_residual scaled by progress
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    score += 12.0 * pr_norm * pr_norm * (0.5 + progress) * cap;

    // Reward tight fits: cubic reward when post_residual is small
    let tightness = 1.0 - pr_norm;
    score -= 30.0 * tightness * tightness * tightness * (1.0 - progress);

    // Lookahead coupling: penalize leaving residual that fits next item poorly
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if ni <= pr {
            let waste = pr - ni;
            score += 0.35 * waste;
            let exact = 1.0 - (waste / cap);
            score -= 8.0 * exact * exact;
        } else {
            score += 6.0;
        }
    }

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Mean residual deviation: penalize bins deviating from average residual
    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * dev.abs();

    // Open bin pressure: prefer filling existing bins when many are open
    score -= (open_bins_count as f64).ln().max(0.0) * 2.0 * (1.0 - pr_norm);

    // Smooth stream-progress polynomial modulation of residual penalty
    score += 4.0 * progress * (1.0 - progress) * pr_norm * cap * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual is divisible by
    // common item-size blocks (e.g. 10, 20, 25, 50) are more reusable.
    let pr = post_residual;
    if pr == 0 {
        score -= 1000.0; // perfect fit
    } else {
        // reward residuals that align with harmonic divisors
        if pr % 10 == 0 { score -= 12.0; }
        if pr % 20 == 0 { score -= 8.0; }
        if pr % 25 == 0 { score -= 6.0; }
        if pr % 50 == 0 { score -= 10.0; }
        // dead-space penalty for tiny unusable residuals
        if pr < 10 {
            score += 60.0;
        } else if pr < 20 {
            score += 18.0;
        }
        // integer-division threshold classes on residual
        let class = pr / 10; // 0..10 harmonic class
        score -= (class as f64) * 2.5; // larger residual = more flexible bin
    }

    // Lookahead coupling: does next item fit the post residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // reward if next item would leave another harmonic residual
            let nr = pr - next_item_size;
            if nr % 10 == 0 { score -= 15.0; }
            if nr == 0 { score -= 40.0; }
            score -= 10.0; // chain-ability bonus
        } else {
            score += 8.0; // this bin likely dies after this item
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        score = 35.0 + (post_residual as f64);
        // penalize opening bins when many are open with slack
        score += open_bins_count as f64 * 3.0;
        if fitting_bins_count > 0 && mean_residual > item_size as f64 + 10.0 {
            score += 40.0;
        }
    }

    // Mild pressure to consolidate when many bins are open
    score -= mean_residual * 0.05;
    score += (step_index as f64 / (total_items.max(1) as f64)) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: heavily favor small post_residual, especially perfect fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score -= 60.0;
    }

    // Strict dead-space avoidance: post_residual that cannot hold the next item
    // is unusable dead space; penalize it proportionally to its uselessness.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 0.9 * (post_residual as f64) + 25.0;
    } else if next_item_size > 0 {
        // Usable gap: mild reward proportional to how well next item fits.
        score -= 0.3 * (1.0 - (post_residual as f64 / bin_capacity as f64));
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // Open-bin pressure: discourage opening new bins when many are already open
    // and their average residual is large (consolidation pressure).
    if bin_residual == bin_capacity {
        // Candidate is a brand-new empty bin.
        score += 40.0 + 8.0 * (open_bins_count as f64);
        if mean_residual > item_size as f64 * 1.5 {
            score += 30.0; // existing bins have plenty of room; avoid new bin
        }
    } else {
        score -= 2.0 * (open_bins_count as f64).min(10.0);
    }

    // Prefer bins whose residual is close to the item (best-fit flavor),
    // scaled by stream progression.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let waste = (bin_residual as f64 - item_size as f64).max(0.0);
    score += (0.5 + 1.5 * progress) * waste;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect fit
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual exactly matches next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual >= next_item_size {
            // next item still fits after this placement -> mild reward
            score -= 40.0;
        } else {
            // next item won't fit here after placement -> penalty
            score += 60.0;
        }
        // combined exact chain: item + next fill the bin completely
        if item_size + next_item_size == bin_residual {
            score -= 250.0;
        }
    }

    // Penalize large dead space relative to mean residual
    let progress = step_index as f64 / total_items.max(1) as f64;
    let dead = post_residual as f64 - mean_residual;
    score += dead * (0.5 + progress);

    // Penalize very small unusable leftovers (below minimum plausible item size)
    if post_residual > 0 && post_residual < 10 {
        score += 120.0;
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // New-bin candidate: only attractive when no good fits exist
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 150.0;
        } else {
            // discourage opening new bin when others fit, unless fit is terrible
            let best_possible = 50.0; // rough threshold for acceptable slack
            if (bin_residual - item_size) as f64 > best_possible {
                score += 80.0;
            } else {
                score += 30.0;
            }
        }
    }

    // Mild preference to fill bins with low residual first (tight packing)
    score += (bin_residual as f64) * 0.05;

    // Slight load balancing late in stream
    score += open_bins_count as f64 * (1.0 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared dead-space penalty scaled by capacity.
    let t = post_residual as f64 / bin_capacity as f64;
    score += 3.0 * t * t * bin_capacity as f64;

    // Exact fit bonus (post_residual == 0).
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Lookahead coupling: if the next item fits into post_residual, reward.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0;
            // Extra reward when next item fills post_residual nearly exactly.
            let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
            score -= 6.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Penalize leaving a residual too small for the next item (dead space).
            let waste = next_item_size as f64 - post_residual as f64;
            score += 0.15 * waste.min(40.0);
        }
    }

    // Time horizon: early in the stream, be conservative (prefer filling existing bins);
    // late in the stream, allow more aggressive new-bin opening since tail waste matters less.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate score: base penalty + dynamic adjustment.
        score = bin_capacity as f64 * 0.9;
        score -= 10.0 * progress;
        // Open a new bin when existing bins are fragmented (mean residual small)
        // and item is large relative to mean residual.
        if (item_size as f64) > mean_residual + 5.0 {
            score -= 12.0;
        }
        // If many bins fit the item, opening new bin is less attractive.
        score += 4.0 * fitting_bins_count as f64;
        // When the next item is large, keep flexibility by opening a fresh bin.
        if next_item_size >= 60 {
            score -= 5.0;
        }
    } else {
        // Penalize placing into bins whose residual deviates badly from mean residual
        // (fragmentation control), weighted by stream progress.
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev * (1.0 - progress);
        // Slight preference for bins with more open competition (spread load evenly).
        score += 0.3 * (open_bins_count as f64).ln().max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: waste after placement (tight fits win naturally).
    let mut score = pr;

    // Non-linear waste penalty: superlinear cost of large dead space.
    let prn = pr / cap;
    score += 8.0 * prn * prn * (1.0 + progress);

    // Reward bins whose residual is "scarce" relative to mean open-bin residual
    // (prefer filling nearly-full bins to consolidate waste).
    let scarcity = (mean_residual - pr) / cap;
    score -= 3.0 * scarcity * scarcity.abs().sqrt().max(0.0);

    // Lookahead: strongly reward leaving room for the next item (k=2 lookahead).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let fit_margin = (pr - nxt) / cap;
            score -= 6.0 * (1.0 - fit_margin * fit_margin);
        } else {
            // Penalize placements that make the bin useless for the next item,
            // scaled by how far off it is (smooth quadratic).
            let gap = (nxt - pr) / cap;
            score += 4.0 * gap * gap;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 5.0 + 3.0 * progress;
    } else if fitting_bins_count > 1 {
        // Mild preference for tighter bins among many candidates (already in pr,
        // but add smooth tie-breaker coupling with bin count pressure).
        score += 0.05 * (fitting_bins_count as f64).ln() * prn;
    }

    // Late-stream consolidation: prefer existing bins more strongly as stream ends.
    score -= 2.0 * progress * (1.0 - prn);

    // New-bin candidate (empty bin): post_residual = capacity - item_size is large,
    // so the superlinear waste penalty plus this explicit smooth surcharge make it
    // lose unless all open fits are very poor.
    if bin_residual == bin_capacity {
        let openness = 1.0 - progress;
        score += 6.0 * openness * (0.5 + prn);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // ---- Harmonic class logic on post_residual ----
    // Reward post_residuals that land in "reusable" residue classes (multiples of 10),
    // penalize awkward residues that create dead space.
    let pr = post_residual;
    let residue_class = (pr % 10) as f64;
    score += (residue_class - 0.0).abs() * 0.6;          // exact decade class is best
    if pr % 20 >= 10 {
        score += 2.0; // odd half-decade classes are worse
    }

    // Integer-division thresholds: post_residual bucket value
    let bucket = pr / 10; // 0..=10
    score += bucket as f64 * 0.8; // prefer fuller bins (smaller leftover buckets)

    // ---- Tight fit reward ----
    if pr <= 5 {
        score -= 12.0; // near-perfect packing
    } else if pr <= 15 {
        score -= 5.0;
    }

    // ---- Lookahead (k=2) coupling ----
    if next_item_size > 0 {
        if next_item_size <= pr {
            // next item can chain into this bin's leftover
            let chain_fit = if pr % next_item_size.max(1) == 0 { 6.0 } else { 3.0 };
            score -= chain_fit;
        } else {
            score += 3.0; // leftover likely wasted
        }
    }

    // ---- Last-chance bonus: only open bin that fits ----
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 18.0;
    }

    // ---- New-bin candidate calibration ----
    if is_new_bin {
        // Base reluctance to open a new bin when others could fit
        let mut reluctance = 22.0;
        if fitting_bins_count > 1 {
            reluctance += 14.0 * (fitting_bins_count.min(5) as f64 - 1.0) * 0.5;
        }
        // Large items into a fresh bin are fine (avoids spreading across many bins)
        if item_size >= bin_capacity * 3 / 4 {
            reluctance -= 30.0;
        } else if item_size >= bin_capacity / 2 {
            reluctance -= 12.0;
        }
        // Late in the stream, opening bins is less costly relative to total
        let t = step_index as f64 / (total_items.max(1) as f64);
        reluctance -= t * 6.0;
        score += reluctance;
    }

    // ---- Mean residual coupling: prefer bins below mean residual (fill the emptiest-fit first) ----
    score += (mean_residual - post_residual as f64) * 0.08;

    // ---- Fractional capacity coupling on bin_residual ----
    let frac = bin_residual as f64 / bin_capacity as f64;
    score += (1.0 - frac) * 2.5;

    // Mild pressure toward consolidating open bins
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // typical future items are dead space; penalize them heavily.
    if post_residual > 0 {
        let dead = (post_residual < 10) as f64;
        score += dead * 60.0;
        // Smoother penalty: unusable gap relative to smallest plausible item
        if post_residual < 20 {
            score += (20 - post_residual) as f64 * 2.0;
        }
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits into the post residual,
    // reward this bin (chain packing).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }
    // Penalize if next item would be blocked by the post residual gap
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open bins pressure: with many open bins, prefer filling existing ones
    // over opening new bins (new-bin candidate has bin_residual == capacity).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (2.0 + 6.0 * progress);
    if bin_residual == bin_capacity {
        score += pressure + 15.0;
    } else {
        score -= pressure * 0.25;
    }

    // Prefer bins tighter than the mean residual (good consolidation).
    score += (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward post_residual that exactly hosts next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        // Perfect match bonus (post_residual == next_item_size)
        if post_residual as f64 == nxt {
            score -= 45.0;
        } else if post_residual >= next_item_size {
            // Next item fits: reward tighter fits
            score -= 25.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Next item does not fit: penalize wasted residual proportional to gap
            score += 0.35 * diff;
        }
    } else {
        // Last item: simply minimize residual
        score += 0.1 * post_residual as f64;
    }

    // Compare against mean residual across open bins: prefer bins with residual
    // close to the mean (balanced packing), penalize outliers.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize opening a brand-new bin when open bins could fit,
    // unless the item fits very snugly nowhere else (post_residual tiny).
    if bin_residual == bin_capacity {
        let snug = post_residual as f64 <= 5.0;
        if fitting_bins_count > 0 && !snug {
            score += 40.0;
        } else if fitting_bins_count > 0 {
            score += 10.0;
        }
        // New-bin bonus decays as stream progresses (commit to open bins later)
        score -= 10.0 * (1.0 - step_index as f64 / total_items.max(1) as f64);
    }

    // Slight preference for fuller bins overall.
    score -= 0.05 * (item_size as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to item size)
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= fit_ratio * 40.0;

    // Lookahead: if next item fits exactly in post_residual, strongly favor this bin
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // next item still fits here; mild bonus proportional to how snugly
            let snug = next_item_size as f64 / post_residual as f64;
            score -= snug * 15.0;
        } else {
            // next item cannot use the leftover: penalize dead space
            score += (post_residual as f64) * 0.25;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 {
        score -= 50.0;
    }

    // Penalize bins whose residual deviates badly from the mean (fragmentation signal)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    // Time horizon: early in the stream, keep bins openable (mild new-bin penalty);
    // late in the stream, consolidate into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 20.0 + 30.0 * (1.0 - progress);
        if post_residual > 0 && post_residual < 10 {
            score += 25.0; // opening a bin that will be nearly full is wasteful
        }
    } else {
        score -= 5.0 * progress;
    }

    // Prefer bins that leave residuals in a "usable" band (>= 10 or == 0)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }
    if post_residual == 0 {
        score -= 30.0; // perfect fill
    }

    // Spread pressure: many open bins -> prefer filling existing ones harder
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;

    // Base: waste after placement, softened as stream progresses.
    let mut score = pr * (1.0 - 0.35 * progress);

    // Smooth non-linear penalty on unusable residual (dead space), stronger late.
    let dead = norm_pr * norm_pr;
    score += 40.0 * dead * (0.5 + progress);

    // Reward tight fits via smooth decay of post_residual around small values.
    score -= 25.0 * (-norm_pr * 4.0).exp();

    // If a future item could exactly fill this residual, reward strongly (smooth coupling).
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs() / cap;
        score -= 30.0 * (-gap * 6.0).exp();
    } else {
        // Last item: heavily reward minimal residual.
        score -= 20.0 * (-norm_pr * 6.0).exp();
    }

    // Last-chance bin bonus (smooth in fitting_bins_count).
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - progress);
    }

    // Prefer bins with residual below mean residual (compact bins) via smooth term.
    let dev = (pr - mean_residual) / cap;
    score += 10.0 * dev * (1.0 - progress);

    // Mild penalty for spreading across many open bins early.
    score += 2.0 * (open_bins_count as f64).ln().max(0.0) * (1.0 - progress) * 0.5;

    // New-bin candidate: only attractive when current item is large relative to capacity
    // and no good fit likely; otherwise penalize opening new bins smoothly.
    if bin_residual == bin_capacity {
        let big = item_size as f64 / cap;
        score += 18.0 * (1.0 - big) * (1.0 + progress);
        if next_item_size > 0 {
            let pair = (item_size as f64 + next_item_size as f64) / cap;
            score += 15.0 * (pair - 1.0).max(0.0);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: modulo-10 classes
    let class = post_residual % 10;
    score += (class as f64) * 0.35;

    // Integer-division thresholds on post_residual
    let half = bin_capacity / 2;
    let quarter = bin_capacity / 4;
    if post_residual == 0 {
        score -= 60.0; // perfect fit
    } else if post_residual < 10 {
        score -= 40.0; // nearly-full bin, dead space minimal
    } else if post_residual <= quarter {
        score -= 15.0;
    } else if post_residual > half {
        score += 12.0; // leaves a big half-bin, poor packing
    }

    // Lookahead coupling: does next item fit the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Harmonic complement: next item's class matches residual
            let comp = post_residual % next_item_size.max(1);
            score -= 10.0 + (comp as f64) * 0.4;
        } else {
            score += 8.0; // residual unusable for next item
        }
        // Perfect harmonic pair: residual exactly equals next item
        if next_item_size == post_residual {
            score -= 25.0;
        }
    } else {
        // Last item: prefer tightest fill
        score -= 20.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 25.0 };
        score = cap * 0.9 + pressure + (open_bins_count as f64) * 1.5;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 6.0; // fresh bin pairs well with large following item
        }
    }

    // Mild stream-phase regularization
    score += (step_index as f64 / (total_items.max(1) as f64)) * 2.0
        - (mean_residual / cap) * 1.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that cannot fit even the smallest future item
    // (1..10) are pure waste; residuals that cannot fit the next item are risky.
    if post_residual < 10 {
        score += 60.0; // unusable dead space
    } else if next_item_size > 0 && post_residual < next_item_size {
        score += 25.0; // cannot host the lookahead item
    }

    // Reward tight fits: small post_residual relative to item size is good packing.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * tightness;

    // Lookahead synergy: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is tight.
    if open_bins_count > 3 {
        score += 2.0 * (open_bins_count as f64 - 3.0);
    }

    // Last-chance bin: strongly prefer using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: opening a new bin wastes existing mean residual.
    if bin_residual == bin_capacity {
        let waste = mean_residual * (open_bins_count as f64);
        score += 15.0 + waste * 0.5;
        // But if no open bin fits well, allow opening: relax when item is large.
        if item_size > 50 {
            score -= 30.0;
        }
    }

    // Prefer bins with below-average residual (denser bins first).
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post residual matches the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        let match_gap = (post - nxt).abs();
        if post >= nxt {
            // Next item fits perfectly in this bin after placement: strong reward
            score -= 45.0 * (1.0 - match_gap / bin_capacity as f64);
            if match_gap < 5.0 {
                score -= 30.0;
            }
        } else {
            // Next item cannot follow here: penalize leaving residual that wastes space
            score += 0.35 * (nxt - post).min(40.0);
        }
        // Coupling: if next item is large and this bin's post residual is small-but-unusable,
        // it's dead space; penalize proportionally
        if post < nxt {
            score += 0.5 * (post / 100.0) * (nxt / 100.0) * 20.0;
        }
    }

    // Relative-to-mean residual alignment: prefer bins whose resulting residual
    // moves residuals toward balance (avoids one very-full bin + many loose bins)
    let post_f = post_residual as f64;
    let dev = post_f - mean_residual;
    score += 0.12 * dev.abs();

    // Prefer tighter fits generally
    score += 0.25 * (post_f / bin_capacity as f64) * 10.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: keep it attractive only when fits are poor or stream is early
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit = post_residual as f64 > 55.0;
        if poor_fit || open_bins_count == 0 || (next_item_size > 0 && (next_item_size as f64) > post_f && post_f < 25.0) {
            score -= 20.0 + 30.0 * (1.0 - progress);
        } else {
            score += 15.0;
        }
    }

    // Mild penalty for very tiny residuals that likely become dead space
    if post_f > 0.0 && post_f < 10.0 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize relative fill of the bin.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fill_ratio;

    // Strong reward for perfect fit (zero waste).
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // heavily reward this placement (creates a perfect two-item bin).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here; mildly penalize leaving a large dead gap
            // that nothing may use.
            score += 0.15 * post_residual as f64;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when no
    // open bin offers a decent fit (poor fill ratios elsewhere).
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 {
            1.0
        } else {
            (mean_residual - item_size as f64).max(0.0) / bin_capacity as f64
        };
        // Base cost of a new bin, discounted by desperation.
        score += 55.0 * (1.0 - desperation.min(1.0));

        // Early in the stream, new bins are cheaper (horizon is long, structure
        // can still be exploited); late in the stream, avoid bin proliferation.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 25.0 * progress;
    } else {
        // Penalize placements into bins whose residual deviates from the mean
        // (keep residual distribution balanced, preserving future fit options).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.1 * dev;

        // Mild penalty for spreading across too many bins when many are open.
        score += 0.5 * open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    }

    // Small noise-free tie-breaker: prefer bins with slightly larger residual
    // (use small bins for small future items) via subtle curvature.
    score += 0.002 * (post_residual as f64 * post_residual as f64) / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity && item_size > 0;

    // Smooth non-linear coupling of post_residual with stream progress:
    // early on, prefer tight fills (low post_residual weighted more); later,
    // balance across bins becomes more valuable.
    let tightness = (pr / cap).powf(1.5 + 1.5 * progress);
    score += 30.0 * tightness;

    // Dead-space penalty: residuals too small for typical items are wasted.
    let dead = (1.0 - (pr / cap).min(1.0)).powi(3) * (pr / cap);
    score -= 20.0 * dead;

    // Reward fitting the item snugly relative to the bin's current residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fill_ratio * fill_ratio;

    // Penalize leaving a gap that exactly blocks a known next item poorly:
    if next_item_size > 0 && (pr as u32) < next_item_size && pr > 0 {
        score += 8.0 * (1.0 - pr / next_item_size as f64);
    } else if next_item_size > 0 && (pr as u32) >= next_item_size {
        // reward leaving room for the lookahead item
        score -= 6.0 * (1.0 - (pr - next_item_size as f64) / cap);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive if no open bin fits,
    // or if all open fits would be terribly loose.
    if is_new_bin {
        let loose_penalty = if fitting_bins_count > 0 {
            40.0 * (1.0 - (item_size as f64 / cap)).powi(2)
        } else {
            -10.0
        };
        score += loose_penalty;
        // Slightly discourage hoarding bins early when mean residual is large.
        score += 0.05 * mean_residual * (1.0 - progress);
    }

    // Mild preference for consolidating into fewer bins as stream progresses.
    score += 0.01 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base best-fit bias with mild capacity-fraction shaping
    let frac = post_residual as f64 / bin_capacity as f64;
    score += 12.0 * frac * frac; // penalize large leftover quadratically

    // Harmonic class of post_residual: dead space that few future sizes can fill
    // Class A: post_residual in {0} -> perfect fit, strong reward
    if post_residual == 0 {
        score -= 40.0;
    }
    // Class B: post_residual divisible by 10 -> many small items fit
    else if post_residual % 10 == 0 {
        score -= 6.0;
    }
    // Class C: post_residual in 1..10 -> very hard to fill (dead space)
    else if post_residual < 10 {
        score += 25.0;
    }
    // Class D: post_residual in 11..19 -> only tiny items fit; moderately bad
    else if post_residual < 20 {
        score += 10.0;
    }
    // Class E: post_residual in 20..50 -> decent chance of a medium item
    else if post_residual <= 50 {
        score -= 3.0;
    }
    // Class F: post_residual > 50 -> still roomy, fine
    else {
        score -= 5.0;
    }

    // Lookahead coupling: if next item fits the post residual exactly, big reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            // next item fits: residual stays usable
            let slack = post_residual - next_item_size;
            if slack < 10 {
                score -= 12.0; // near-perfect two-item chain
            } else {
                score -= 4.0;
            }
        } else {
            // next item won't fit here: residual becomes dead until later
            score += 5.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a bin is costly unless current bins fit poorly
    if bin_residual == bin_capacity {
        let open_pressure = if open_bins_count > 0 { open_bins_count as f64 } else { 1.0 };
        let mean_fit_quality = mean_residual / bin_capacity as f64;
        // penalty for opening new bin grows with number of open bins and their slack
        score = 55.0 + 4.0 * open_pressure + 30.0 * mean_fit_quality;
        // if item is large and mean residual is small, new bin is more attractive
        if item_size > 60 && mean_fit_quality < 0.2 {
            score -= 20.0;
        }
        // early in stream, keep bins consolidated
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * (1.0 - progress);
    }

    // Mild consolidation: prefer bins with less residual among similar classes
    score += 0.05 * (bin_residual as f64 - mean_residual).abs().signum()
        * (bin_residual as f64 - mean_residual).abs().min(20.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hardest.
    // A post_residual that is too small for the smallest possible item (1) is pure waste,
    // but gaps below ~10 (typical lower bound) are especially likely to become dead space.
    let pr = post_residual as f64;
    if post_residual > 0 {
        if post_residual < 10 {
            score += 40.0 * (10.0 - pr) / 10.0; // near-total dead space penalty
        } else if post_residual < 20 {
            score += 15.0 * (20.0 - pr) / 10.0; // risky gap
        }
        // Reward near-perfect fits strongly
        if post_residual <= 5 {
            score -= 25.0;
        } else if post_residual <= 10 {
            score -= 12.0;
        }
    } else {
        // Perfect fill: zero residual is ideal
        score -= 50.0;
    }

    // Lookahead: if the next item fits in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 + 0.25 * (next_item_size as f64);
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // gap too small for the known next item: extra dead-space penalty
        score += 8.0;
    }

    // Last-chance bin pressure: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: penalize opening new bins when many bins are already open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure that grows with open bins and stream progress.
        score += 35.0 + 3.0 * (open_bins_count as f64) + 20.0 * progress;
        // If no open bin fits at all, opening a new bin is necessary: soften the penalty.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        // If the next item is large and no open bin would hold it after this placement,
        // a fresh bin may still be preferable: small discount.
        if next_item_size > 0 && next_item_size > post_residual && fitting_bins_count == 1 {
            score -= 5.0;
        }
    } else {
        // Using an existing bin slightly reduces open-bin pressure.
        score -= 1.0 * (open_bins_count as f64).min(10.0) * 0.5;
    }

    // Mild preference for bins with residual close to the item (tight fits) relative to fleet mean.
    let diff = (bin_residual as f64 - item_size as f64) - mean_residual;
    score += 0.05 * diff;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual (tight fit), scaled against capacity.
    score = score * 1.5;

    // Aggressive 2-step lookahead: reward exact or near-exact match of
    // next_item_size into the post_residual gap.
    if next_item_size > 0 {
        let gap = post_residual as f64;
        let nxt = next_item_size as f64;
        if nxt <= gap {
            // Next item fits perfectly into leftover space -> strong reward.
            let match_quality = 1.0 - ((gap - nxt) / bin_capacity as f64);
            score -= 25.0 * match_quality * match_quality;
        } else {
            // Next item cannot follow -> penalize dead space creation,
            // worse when the overshoot is large.
            let overshoot = nxt - gap;
            score += 0.35 * overshoot;
        }
    }

    // Coupling with mean_residual: bins far below mean residual are
    // "wasted" bins; placing here consolidates fragmentation.
    let resid_f = bin_residual as f64;
    if resid_f > mean_residual {
        score += 0.20 * (resid_f - mean_residual);
    } else {
        score -= 0.10 * (mean_residual - resid_f);
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin for a mediocre fit.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is huge
    // relative to capacity (poor fit everywhere) or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let big_item = (item_size as f64 / bin_capacity as f64) > 0.6;
        score += 30.0;
        if big_item || progress < 0.05 {
            score -= 25.0;
        }
        // Early stream: opening bins is cheap and builds diversity.
        if progress < 0.2 {
            score -= 10.0 * (0.2 - progress) * 5.0;
        }
    }

    // Mild pressure against proliferating bins.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic bonus for small post_residual.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio) * (1.0 - fit_ratio) * 30.0;

    // Exact fill is perfect.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Dead space penalty: post_residual too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead coupling: reward if next item fits the post residual (chaining).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 20.0;
        } else {
            // Penalize creating residual that just barely fails the next item.
            let gap = (next_item_size - post_residual) as f64;
            if gap < 15.0 {
                score += gap * 1.2;
            }
        }
    }

    // Last chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalize bins whose residual deviates far below mean (fragmentation).
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score += dev * 0.3;
    }

    // Time horizon: early on, be conservative with new bins; later, more open.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // New-bin candidate handling: only attractive when open bins are crowded.
    if bin_residual == bin_capacity && item_size <= bin_capacity {
        let crowding = mean_residual / bin_capacity as f64;
        score = 60.0 + crowding * 40.0 - progress * 20.0;
        // If the item is large relative to capacity, opening fresh is better.
        if item_size as f64 / bin_capacity as f64 > 0.7 {
            score -= 15.0;
        }
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    // Mild penalty for spreading across too many bins.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr_norm = pr / cap;

    // Base: post-residual (minimize wasted space), smoothly modulated by progress
    let mut score = pr * (1.0 + 0.5 * progress * progress);

    // Non-linear polynomial coupling: quadratic-quartic shaping of post residual
    let q = pr_norm * pr_norm;
    score += 20.0 * q * (1.0 - q) * (1.0 + progress);

    // Reward tight fits: subtract when post_residual is small relative to item
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fit_ratio * fit_ratio;

    // Dead-space penalty: residual too small to be useful for typical items
    if pr < 10.0 {
        score -= 8.0 * (1.0 - pr / 10.0);
    }

    // Lookahead: favor bins whose post-residual matches next item
    if next_item_size > 0 && pr >= next_item_size as f64 {
        let gap = (pr - next_item_size as f64) / cap;
        score -= 12.0 * (1.0 - gap * 4.0).max(0.0);
    } else if next_item_size > 0 && pr < next_item_size as f64 {
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: penalize mildly early, more when open bins are scarce
    if bin_residual == bin_capacity {
        score += 10.0 + 5.0 * (1.0 - progress);
    }

    // Prefer bins with below-mean residual (consolidating waste)
    score -= 3.0 * ((mean_residual - pr) / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class logic: reward residuals that belong to "useful" classes.
    // Class 0 (perfect fit) is best; small residuals (< 10) are dead space.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space penalty for tiny unusable remainders (items >= 1 now allowed)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10 - post_residual) as f64;
    }

    // Harmonic class: residual divisible by common size strides is reusable
    let class_bonus = |r: u32| -> f64 {
        if r == 0 { return 80.0; }
        let mut b = 0.0;
        if r % 10 == 0 { b += 30.0; }
        if r % 20 == 0 { b += 15.0; }
        if r % 25 == 0 { b += 15.0; }
        if r % 50 == 0 { b += 20.0; }
        b
    };
    score -= class_bonus(post_residual);

    // Lookahead: reward if next item fits exactly in the post residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 250.0;
        } else if next_item_size <= post_residual {
            // pair fit quality: closer fit is better
            let gap = (post_residual - next_item_size) as f64;
            if gap < 10.0 {
                score -= 120.0 - 8.0 * gap;
            } else {
                score -= 40.0 * (1.0 - gap / cap);
            }
            // harmonic classes of the pair
            if (post_residual % 10 == 0 && next_item_size % 10 == 0) {
                score -= 20.0;
            }
        } else {
            // next item won't fit here: mild penalty proportional to overflow
            score += 15.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Prefer filling already-open bins when many are open (avoid bin proliferation)
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.05 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // New-bin candidate: make it attractive only when residuals across bins are poor
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // baseline cost of opening a bin, offset when mean residual is fragmented
        score += 70.0;
        score -= (mean_residual - pr).abs() * 0.3;
        if mean_residual < 25.0 {
            score -= 60.0; // open bins are nearly full -> new bin is good
        }
        if next_item_size > 0 && next_item_size >= 90 {
            score -= 30.0; // large next item benefits from a fresh bin
        }
    } else {
        // tighter fits in existing bins: reward low post residual non-linearly
        score -= 50.0 * (1.0 - pr / cap) * (1.0 - pr / cap);
    }

    // Slight tie-break noise-free harmonic jitter via integer division thresholds
    score -= ((post_residual / 10) % 3) as f64 * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that cannot fit the smallest
    // plausible item are pure waste; penalize them super-linearly.
    let min_item = 1u32;
    if post_residual < min_item {
        score += 1000.0; // exact fit is perfect, avoid overflow penalty path
    }
    // Dead-space curve: gap too small for next item is likely unusable.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 40.0 + 2.0 * (next_item_size - post_residual) as f64;
    }
    // Reward tight fits strongly (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Exact fit bonus.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few,
    // a new empty bin is a reasonable fallback baseline.
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline near mean residual pressure.
        score = 60.0 + 2.0 * open_bins_count as f64 - 0.1 * mean_residual;
        // If nothing fits well (many bins but only this candidate), allow it.
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    } else {
        // Slight preference for fuller bins among open ones.
        score += 0.05 * (mean_residual - post_residual as f64);
    }

    // Late in the stream, consolidate aggressively to avoid leftover gaps.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: huge reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward residuals that exactly match the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        score -= 60.0 * (1.0 - diff / 100.0).max(0.0);
        // Exact match for the next item is nearly as good as a perfect fit
        if post_residual as f64 == nxt {
            score -= 500.0;
        }
        // Penalize dead space: residual too small for the next item but nonzero
        if post_residual > 0 && (post_residual as u32) < next_item_size {
            score += 40.0 * (1.0 - post_residual as f64 / 20.0).max(0.0);
        }
    } else {
        // Last item: any residual is pure waste
        score += 50.0;
    }

    // Relative-to-mean coupling: prefer bins tighter than the mean residual
    score -= 2.0 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Penalize creating tiny unusable slivers (1..=9) that likely fit nothing
    if post_residual > 0 && post_residual < 10 {
        score += 80.0;
    }

    // New-bin candidate: make it attractive only when existing bins fit poorly
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score = 90.0;
        if next_item_size > 0 {
            let nxt = next_item_size as f64;
            // A fresh bin pairs perfectly if item + next item fills it
            if (item_size as f64 + nxt - bin_capacity as f64).abs() < 1.0 {
                score -= 400.0;
            }
        }
        // Late in the stream, avoid spreading out
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
        if fitting_bins_count == 1 {
            score += 200.0; // don't open a new bin when a last-chance bin exists
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward near-perfect fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 15 {
        score -= 60.0;
    }

    // Fraction of capacity wasted by this placement.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += waste_frac * 40.0;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: only attractive when current bin would leave a very
    // awkward residual that the next item cannot use, or when few bins fit.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let next_fits_gap = (post_residual as i64 - next_item_size as i64) >= 0;
        // Penalize opening a new bin normally.
        score += 120.0;
        if next_item_size > 0 && next_fits_gap {
            // A fresh bin can host the next item too — mild discount.
            score -= 60.0;
        }
        // Early in stream, opening bins builds flexibility.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 30.0;
        // If many open bins but mean residual is large, opening a new bin wastes potential.
        score += mean_residual * 0.3;
    } else {
        // Lookahead synergy: reward if the residual left can host the next item.
        if next_item_size > 0 {
            if post_residual == next_item_size {
                score -= 180.0; // perfect pairing
            } else if post_residual >= next_item_size {
                let slack = (post_residual - next_item_size) as f64;
                score -= 40.0 * (1.0 - slack / bin_capacity as f64);
            } else {
                // Residual too small for next item: dead space risk, scaled by how close it is.
                let gap = (next_item_size - post_residual) as f64;
                score += gap * 0.5;
            }
        }
        // Prefer using bins with smaller residuals overall (consolidate fullness).
        score += (mean_residual - bin_residual as f64).max(-50.0).min(50.0) * 0.4;
        // Late in the stream, tighten packing to avoid extra bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += (1.0 - progress) * 10.0;
    }

    // Mild penalty for spreading across many open bins.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: prefer small post-residual (tight fit), with non-linear shaping.
    let mut score = post / cap;

    // Smooth non-linear coupling: post_residual interacts with stream progress.
    // Late in the stream, dead space is more costly (less room to recover).
    score += 0.35 * (post / cap) * (post / cap) * (1.0 + progress);

    // Reward tight fits super-linearly when post residual is small.
    let tightness = 1.0 - post / cap;
    score -= 0.25 * tightness * tightness * tightness;

    // Penalize wasting a large existing residual on a small item.
    let fill_ratio = item / bin_residual.max(1) as f64;
    score -= 0.20 * fill_ratio * fill_ratio;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 1.5;
    }

    // New-bin candidate handling: penalize opening a new bin, more so when
    // existing fitting bins exist and mean residual could absorb the item.
    if bin_residual == bin_capacity {
        score += 0.8 + 0.4 * progress;
        if fitting_bins_count > 1 {
            score += 1.0;
        }
        // If the next item is small, this bin may still be useful; soften slightly.
        if next_item_size > 0 && (next_item_size as f64) <= post {
            score -= 0.3;
        }
    }

    // Lookahead: if the next item exactly fits this bin's post residual, reward.
    if next_item_size > 0 && (next_item_size as f64) == post {
        score -= 0.9;
    } else if next_item_size > 0 && (next_item_size as f64) < post {
        score -= 0.15 * (1.0 - post / cap);
    }

    // Mild preference to consolidate into fewer bins when many are open.
    score += 0.02 * (open_bins_count as f64).sqrt() * (post / cap);

    // Mean-residual coupling: if this bin is far below the mean residual,
    // it is already "used up"; placing here is cheap.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score -= 0.10 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Harmonic class of the leftover space: which capacity-fraction band does post_residual fall in?
    // Classes: (0,10], (10,20], (20,33], (33,50], (50,100)
    let class = if post_residual == 0 { 0u32 }
        else if post_residual <= 10 { 1 }
        else if post_residual <= 20 { 2 }
        else if post_residual <= 33 { 3 }
        else if post_residual <= 50 { 4 }
        else { 5 };

    // Reward tight fits (low classes), with non-linear per-class bonuses.
    let class_bonus: f64 = match class {
        0 => 60.0,
        1 => 40.0,
        2 => 22.0,
        3 => 10.0,
        4 => 3.0,
        _ => 0.0,
    };
    score -= class_bonus;

    // Modulo arithmetic on post_residual: leftovers that are "harmonic" with common
    // item sizes (multiples of 10 / 5) are more likely to be filled later -> reward.
    let pr = post_residual;
    if pr > 0 {
        if pr % 10 == 0 { score -= 8.0; }
        else if pr % 5 == 0 { score -= 4.0; }
        // Odd awkward remainders are dead space -> penalize mildly.
        if pr % 2 == 1 && pr < 10 { score += 6.0; }
    }

    // Lookahead coupling: does next_item_size fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 50.0; // perfect chained fit
        } else if next_item_size <= pr {
            // integer-division compatibility: how many next items could stack here
            let k = pr / next_item_size;
            score -= (k.min(4) as f64) * 6.0;
        } else {
            // next item cannot use this leftover; dead space penalty scaled by gap
            let gap = (next_item_size - pr) as f64;
            score += 0.3 * gap.min(40.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin has huge residual; make it a
    // middle-of-the-road fallback unless the item is large relative to capacity.
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / cap;
        // Prefer new bin for big items (would leave tiny unusable slivers elsewhere),
        // prefer existing bins for small items.
        score = 45.0 - 30.0 * frac;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // big stream incoming: fresh bin useful
        }
    }

    // Stream progression: early on, be conservative with open bins; late, pack hard.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * (class_bonus / 60.0);

    // Many open bins -> encourage consolidation into existing bins.
    score += 0.5 * (open_bins_count as f64).ln().max(0.0);

    // Deviation from mean residual: bins far below mean are "specialists",
    // bins above mean are wasteful; slight pull toward mean.
    score += 0.05 * ((post_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the smallest plausible item are dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Small-but-usable gaps are mildly penalized to prefer tight fits.
    if post_residual > 0 && post_residual < 20 {
        score += 15.0;
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones and
    // prefer consolidating into existing bins.
    let open_pressure = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to how many bins are open
        // and how much residual capacity is stranded on average.
        score += 25.0 + open_pressure * 2.0 + mean_residual * 0.3;
    } else {
        // Existing bin: reward filling it when bin count is high.
        score -= open_pressure * 0.5;
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item would fit into post_residual, reward this placement.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 12.0;
    }
    // If next item is large and would leave this bin with tiny dead space, mild penalty.
    if next_item_size > post_residual as u32 && post_residual > 0 && post_residual < 25 {
        score += 10.0;
    }

    // Early in stream: slight preference for opening bins to build structure.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity && progress < 0.2 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next_item_size -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Post residual can still fit the next item -> moderate reward, scaled by tightness.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 - slack * 0.2;
    } else if next_item_size > 0 {
        // Dead space: next item cannot fit here; penalize small unusable leftovers more.
        let dead = post_residual as f64;
        if dead < 10.0 {
            score += 15.0 - dead * 1.2; // tiny crumbs are worst
        }
    }

    // Relative to mean residual: bins tighter than average are good targets.
    let tightness = mean_residual - post_residual as f64;
    score += tightness * 0.15;

    // Last-chance bin: only one bin fits -> strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Many open bins: prefer consolidation into existing bins.
    if open_bins_count > 4 {
        score -= 3.0;
    }

    // Early in stream, be more willing to spread; late, pack tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 5.0;

    // Slight penalty for leaving exactly-fillable residuals wasted on a fresh bin.
    if bin_residual == bin_capacity {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic penalty on large post-residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 20.0;

    // Reward placements that leave room for the next item (lookahead).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 - slack * 0.08;
        } else {
            // Next item won't fit here; penalize if we strand a large dead space.
            score += (post_residual as f64) * 0.15;
        }
    } else {
        // Last item: prefer fullest possible packing.
        score -= item_size as f64 * 0.1;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when good fitting bins exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = mean_residual / bin_capacity as f64;
        // Open new bin only if open bins are mostly full or few alternatives.
        score += 30.0 * (1.0 - pressure) + 15.0 * progress;
        if fitting_bins_count > 0 && item_size <= 50 {
            score += 20.0; // small items should go into existing bins
        }
        if next_item_size > 0 && next_item_size >= item_size && fitting_bins_count <= 1 {
            score -= 35.0; // pair large items in fresh bins
        }
    } else {
        // Favor bins with residual close to mean (balance load slightly).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.05;

        // Prefer bins that would become "perfectly closed" (residual < min item ~1).
        if post_residual == 0 {
            score -= 40.0;
        } else if post_residual < 10 {
            score -= 12.0; // near-perfect closure, likely unusable dead space eliminated
        }

        // Slight preference for fewer open bins when many are open.
        score += open_bins_count as f64 * 0.3;
    }

    // Dynamic time horizon: late in stream, consolidate aggressively.
    let t = step_index as f64 / (total_items.max(1) as f64);
    score -= t * (bin_residual - post_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, prefer tight fills (small post_residual); late, tolerate
    // residuals that match the expected future demand.
    let curvature = 0.5 + 1.5 * progress * progress;
    score += curvature * pr_norm * pr_norm * cap * 0.2;

    // Reward bins whose post_residual closely matches the next item size
    // (smooth Gaussian-like affinity rather than a hard threshold).
    if next_item_size > 0 {
        let diff = pr - next_item_size as f64;
        score -= 12.0 * (-(diff * diff) / 900.0).exp();
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Penalize opening new bins when many bins fit the item (fragmentation risk).
    if bin_residual == bin_capacity {
        score += 8.0 + 4.0 * fitting_bins_count as f64;
    } else {
        // Slight reward for using bins that are already "loose" relative to mean.
        let dev = (mean_residual - bin_residual as f64) / cap;
        score += 5.0 * dev * dev;
    }

    // Mild pressure to consolidate as stream progresses.
    score -= 6.0 * progress * (item_size as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: quantize dead space into capacity fractions.
    let post = post_residual as f64;
    let frac = post / cap;
    // Penalize residuals that are too small to hold any plausible future item
    // (items 1..=100, so residual < 1 is impossible; residual < 10 is nearly dead).
    if post_residual == 0 {
        score -= 30.0; // perfect fit: excellent
    } else if post_residual < 10 {
        score += 25.0; // dead space penalty
    }

    // Modulo-class reward: residuals divisible into common item sizes (10s)
    // are more reusable.
    let mod10 = post_residual % 10;
    score += mod10 as f64 * 0.8;

    // Integer-division threshold classes on post_residual
    let class = post_residual / 10; // 0..=10
    match class {
        0 => score += 15.0,          // 0..9: nearly dead (unless 0 handled above)
        1..=3 => score += 8.0,       // small pockets, hard to fill
        4..=6 => score -= 2.0,       // mid pockets, moderately useful
        _ => score -= 6.0,           // large residual: flexible bin
    }

    // Coupling with lookahead item (k=2)
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // next item exactly fills this bin
        } else if next_item_size < post_residual {
            score -= 5.0; // next item can also go here
        } else {
            score += 4.0; // next item won't fit here
        }
        // Harmonic coupling: post_residual % next_item_size small => good reuse
        if next_item_size > 0 && post_residual % next_item_size <= 3 {
            score -= 3.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: neutral-ish baseline, but prefer it when
    // open bins are fragmented (low mean residual relative to item).
    if bin_residual == bin_capacity {
        let base = 55.0 + 0.3 * open_bins_count as f64;
        // If mean residual across open bins is large, keep using open bins.
        score = base + (mean_residual - item_size as f64).max(0.0) * 0.5;
        if fitting_bins_count == 0 {
            score -= 60.0; // no alternative: must open
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // pairing lookahead suggests fresh bin
        }
    }

    // Mild stream-progression term: early on, encourage consolidation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * mean_residual * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: small unusable gaps are heavily penalized.
    // A residual that is too small for the smallest plausible item (<= 12)
    // is essentially wasted capacity.
    if post_residual > 0 && post_residual < 12 {
        score += 60.0;
    } else if post_residual == 0 {
        // Perfect fit: reward strongly.
        score -= 45.0;
    } else {
        // Non-linear penalty on leftover space, emphasizing mid-range waste.
        let r = post_residual as f64;
        score += 0.35 * (r * r) / bin_capacity as f64;
    }

    // Reward using bins with already-low residual (tighten full bins first).
    let residual_ratio = bin_residual as f64 / bin_capacity as f64;
    score -= 20.0 * (1.0 - residual_ratio);

    // Open bins pressure: with many open bins, discourage spreading;
    // prefer filling existing bins over opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.8 * open_bins_count as f64 * (0.5 + progress);

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item fits
    // very poorly everywhere (post_residual here equals capacity - item).
    if bin_residual == bin_capacity {
        score += 25.0;
        // If item is large relative to capacity, new bin is less bad.
        score -= 15.0 * (item_size as f64 / bin_capacity as f64);
    }

    // Lookahead coupling: if next item could use this bin's post_residual,
    // reward leaving exactly that much space.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        if post_residual == next_item_size {
            score -= 10.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item won't fit in the gap: dead space penalty.
        score += 8.0;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual (tight fit).
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Strong tight-fit reward: subtract sharply for small post_residual.
    score -= (cap - post) / cap * 20.0;

    // 2-step lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            // Perfect chaining: this bin absorbs the next item completely.
            score -= 45.0;
        } else if next_item_size < post_residual {
            // Next item fits, but leaves a further gap; penalize by that future gap.
            let future_gap = (post_residual - next_item_size) as f64;
            score += future_gap * 0.4;
            // Small bonus if future gap stays small.
            score -= (1.0 - future_gap / cap) * 8.0;
        } else {
            // Next item won't fit here: mild penalty proportional to overshoot.
            let overshoot = (next_item_size - post_residual) as f64;
            score += overshoot * 0.15;
        }
    } else {
        // Last item: only tightness matters.
        score -= 15.0;
    }

    // Compare against mean residual: bins below mean residual are already tight;
    // placing here keeps fragmentation concentrated.
    if mean_residual > 0.0 {
        let rel = post / mean_residual;
        if rel < 1.0 {
            score -= (1.0 - rel) * 10.0;
        } else {
            score += (rel - 1.0) * 6.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalize leaving large dead space that few items could use.
    if post > 0 && post < 10.0 {
        score -= 5.0; // tiny gap is fine (near-perfect fill)
    }
    if post >= 10.0 && post < 30.0 {
        score += 3.0; // awkward mid-range gap
    }

    // Early in the stream, be slightly more willing to open fresh bins for large items.
    let early = 1.0 - progress;
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive if item is large and stream is young.
        score -= early * (item_size as f64 / cap) * 12.0;
        score -= (item_size as f64 / cap) * 6.0;
    } else {
        // Mildly prefer reusing existing bins as bins accumulate.
        score += (open_bins_count as f64).ln().max(0.0) * 1.5;
    }

    // Progression: later in stream, prioritize consolidation (tighter fits).
    score *= 1.0 + 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.89;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let x = pr / cap;

    // Base: prefer small post-residual, with smooth polynomial shaping
    let mut score = pr as f64;

    // Non-linear polynomial coupling of residual with stream progress:
    // early on, tolerate larger residuals; later, penalize them harder.
    let w = 1.0 + 3.0 * progress * progress;
    score += w * (x * x) * cap * 0.5;

    // Tight fit bonus (quadratic in fill fraction)
    let fill = item_size as f64 / cap;
    score -= 6.0 * fill * fill * cap;

    // Penalize residuals that are too small to matter (dead space), smoothly
    let dead = if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0);
        gap * gap / cap
    } else { 0.0 };
    score += 2.0 * dead;

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Mild penalty for spreading across many bins when mean residual is large
    score += 0.05 * open_bins_count as f64 * (mean_residual / cap).max(0.0);

    // Slight nudge toward existing bins vs new bin as stream matures
    if bin_residual != bin_capacity {
        score -= 1.0 + 2.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, but dampen raw residual preference.
    score = post_residual as f64 * 1.0 - (bin_capacity - post_residual) as f64 * 0.05;

    // Harmonic class of post_residual: capacity fractions (C/8, C/4, C/2).
    // Residuals near multiples of 25 are "reusable" by common item sizes (10..80).
    let mut reusability = 0.0;
    for k in 1..=4u32 {
        let target = bin_capacity * k / 4;
        let d = (post_residual as i64 - target as i64).abs() as f64;
        reusability += 1.0 / (1.0 + d);
    }
    score -= reusability * 6.0;

    // Dead-space penalty: residual that no item (min size 10) can ever use.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += (20 - post_residual) as f64 * 2.0;
    }

    // Modulo-10 alignment: items come in a 10..80 range; residuals that are
    // multiples of 10 tend to be perfectly consumable.
    let mod10 = post_residual % 10;
    if mod10 == 0 {
        score -= 8.0;
    } else {
        score += mod10 as f64 * 0.8;
    }

    // Integer-division threshold classes on post_residual.
    let class = post_residual / 20; // 0..5
    score += match class {
        0 => 15.0, // tiny leftover, near-dead
        1 => 4.0,
        2 => 0.0,  // sweet spot ~40-60
        3 => -2.0,
        _ => 3.0,  // nearly full bin barely used
    };

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size).min(30) as f64 * 0.5;
        } else {
            // Next item cannot use this bin's leftover: mild penalty for waste.
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid
    // opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin should only win when no open
    // bin offers a decent fit. Penalize it by default; relax penalty when
    // many bins are open but fits are poor (fragmented state).
    if bin_residual == bin_capacity {
        let base_new_bin_penalty = 30.0;
        let fragmentation = (mean_residual - post_residual as f64).abs();
        let relax = (fragmentation / 20.0).min(1.0) * 12.0
            + (open_bins_count as f64).ln().max(0.0) * 2.0;
        score += base_new_bin_penalty - relax;
    }

    // Stream progression: early on, prefer keeping residuals flexible
    // (large residuals); late, prefer closing bins tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * (post_residual as f64) * 0.15;

    // Slight preference to balance load across bins: avoid extreme residuals
    // vs the mean.
    score += (post_residual as f64 - mean_residual).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual gap is "dead" if it is smaller than the smallest plausible item (1..=100 range),
    // with a soft zone for slightly larger gaps.
    let dead_threshold = 10.0f64;
    if post_residual > 0 {
        let gap = post_residual as f64;
        if gap < dead_threshold {
            score += (dead_threshold - gap) * 6.0; // tiny leftover = wasted space
        } else {
            // Larger gaps are only mildly penalized; reward gaps that can host the lookahead item.
            if next_item_size > 0 && (next_item_size as f64) <= gap {
                score -= 8.0;
            } else if next_item_size > 0 {
                score += ((next_item_size as f64) - gap) * 0.5;
            }
        }
    }

    // Reward tight fits (low post_residual relative to item size).
    let tightness = item_size as f64 / (bin_residual as f64).max(1.0);
    score -= tightness * 10.0;

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins.
    let pressure = open_bins_count as f64 / (mean_residual / bin_capacity as f64).max(0.05);
    score += pressure * 2.0;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize opening a new bin when a reasonable existing fit exists,
    // but allow it if the current bin would leave a bad gap.
    if bin_residual == bin_capacity {
        let new_bin_penalty = 25.0 - tightness * 5.0;
        score += new_bin_penalty.max(0.0);
    }

    // Slight progression-awareness: late in the stream, consolidation matters more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (1.0 - progress) * 0.0 + progress * (post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 / (1.0 + diff);
        if post_residual == next_item_size {
            score -= 60.0;
        }
        // Penalize leaving residual slightly below next item (dead space for lookahead).
        if post_residual < next_item_size {
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: prefer tightest fit, reward using existing bins fully.
        score -= 50.0;
    }

    // Reward bins with residual below mean (tighter, more committed bins).
    score -= 0.6 * (mean_residual - post_residual as f64).max(0.0);
    // Penalize bins already far above mean residual (fragmented).
    score += 0.3 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: discourage opening a new bin unless all fits are poor.
    if bin_residual == bin_capacity {
        score += 45.0;
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
        // Opening new bin is more acceptable early in the stream.
        score -= 20.0 * (1.0 - step_index as f64 / total_items.max(1) as f64);
    }

    // Slight preference for filling larger bins first when many open.
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post_residual), with non-linear emphasis.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when existing bins fit poorly.
    if bin_residual == bin_capacity {
        let avg_fit_penalty = (mean_residual - item_size as f64).abs();
        if avg_fit_penalty > 15.0 {
            score -= 20.0; // opening a new bin may be better
        } else {
            score += 30.0; // prefer existing bins with decent fit
        }
        // Early in the stream, opening bins is cheaper; late, avoid it.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 25.0 * progress;
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap <= 5 {
            score -= 35.0; // perfect chaining
        } else {
            score -= 10.0 * (1.0 - gap as f64 / bin_capacity as f64);
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 8.0; // next item cannot chain here
    }

    // Bin-count pressure: many open bins -> consolidate into existing ones.
    if open_bins_count > 3 {
        score -= (open_bins_count.min(20) as f64) * 0.5;
    }

    // Global residual balance: prefer bins whose residual is near the mean
    // (keeps the pool of usable gaps homogeneous).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual

    // Base: quadratic waste penalty (dead space is bad)
    let mut score = x * x * cap;

    // Non-linear coupling with stream progress: early on tolerate slack,
    // later tighten bins aggressively (cubic interaction).
    let coupling = x * (1.0 - progress) * (1.0 - progress) - x * progress * progress;
    score += 40.0 * coupling;

    // Reward tight fits (small post_residual) more strongly as stream advances
    score -= (1.0 - x).powi(3) * (10.0 + 30.0 * progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    } else {
        // Many fitting bins: mild penalty to preserve diversity of residuals
        score += (fitting_bins_count as f64).ln() * 2.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let fit_quality = 1.0 - ((pr - nx) / cap);
            score -= 15.0 * fit_quality * fit_quality;
        } else {
            // post_residual too small for next item: penalize proportionally to wasted chunk
            score += 5.0 * (1.0 - (pr / nx));
        }
    }

    // Slight preference for bins already deviating from mean residual (consolidation)
    score += 0.05 * (pr - mean_residual).abs();

    // New empty bin candidate: only attractive if it yields a good future
    // (i.e., current item small relative to capacity) and few bins fit.
    if bin_residual == bin_capacity {
        score = cap * 0.8 - (1.0 - x) * 20.0 * (1.0 - progress)
            - if fitting_bins_count <= 1 { 30.0 } else { 0.0 };
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: bins whose leftover falls into
    // "small residue" classes (0..=10, 11..=20) waste little space; large
    // residues are fine only if they can host future items.
    let pr = post_residual;
    let class = pr / 10; // integer division: harmonic class 0..=10
    let class_penalty = match class {
        0 => -6.0,          // near-perfect fit, excellent
        1 => -3.0,          // small dead space
        2 => -1.0,
        3 | 4 | 5 => 0.0,   // mid residues: neutral
        6 | 7 => 1.5,       // awkward residues (~60-79)
        _ => 2.5,           // large residue left behind
    };
    score += class_penalty;

    // Reward exact or near-exact fits (waste <= 5).
    if pr <= 5 {
        score -= 8.0;
    } else if pr <= 10 {
        score -= 4.0;
    }

    // Lookahead coupling: strongly favor bins whose post-residual can host
    // the next item exactly (harmonic chaining).
    if next_item_size > 0 {
        if pr >= next_item_size {
            let slack = (pr - next_item_size) as f64;
            // exact match for next item is gold
            if slack == 0.0 {
                score -= 7.0;
            } else if slack <= 10.0 {
                score -= 3.0;
            } else {
                // penalize by how much slack would remain after next item
                score += slack * 0.05;
            }
        } else {
            // next item cannot fit here; mildly penalize big leftovers
            score += pr as f64 * 0.02;
        }
    }

    // Last-chance bin: if this is the only bin that fits, prefer it heavily
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 5.0 + (bin_residual - item_size).min(50) as f64 * 0.1;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Opening a new bin should only win when no open bin gives a good fit.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        let mut new_bin_score = cap * 0.35; // 35 units
        // cheaper to open when many items remain to fill it
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 1.0 };
        new_bin_score -= (1.0 - progress) * 10.0;
        // if open bins are crowded (few fit), opening is more attractive
        new_bin_score -= (fitting_bins_count as f64).recip() * 2.0;
        // if next item is large, a fresh bin is useful
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            new_bin_score -= 6.0;
        }
        return new_bin_score;
    }

    // Mild preference for filling bins that are already mostly full
    // (tighter packing first), scaled by fraction of capacity used.
    let used_frac = (bin_capacity - bin_residual) as f64 / cap;
    score -= used_frac * 4.0;

    // Mean-residual coupling: when open bins are on average roomy,
    // discourage leaving this bin with a large leftover.
    if mean_residual > cap * 0.5 && pr > 30 {
        score += 2.0;
    }

    // Tie-break noise-free small jitter by bin index proxy (open count)
    score += (open_bins_count as f64) * 0.001;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: extremely strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space avoidance: small unusable gaps are penalized hard.
    // A gap is "unusable" if it's smaller than the smallest plausible item (assume ~1..20 zone).
    if post_residual > 0 && post_residual <= 15 {
        score += 40.0 + (15 - post_residual) as f64 * 4.0;
    } else if post_residual <= 30 {
        // Medium-small gaps: moderate penalty scaled by gap tininess.
        score += (30 - post_residual) as f64 * 0.8;
    }

    // Reward bins whose residual was already small (tight packing pressure).
    let tightness = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= tightness * 10.0;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones.
    let open_pressure = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open bins count,
        // but allow when item is large and mean residual can't host it well.
        score += open_pressure * 5.0;
        if (mean_residual < item_size as f64) || (next_item_size > 0 && next_item_size > mean_residual) {
            score -= 15.0;
        }
    } else {
        // Placing into an existing bin relieves pressure slightly.
        score -= open_pressure.min(10.0);
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual == next_item_size {
            score -= 120.0;
        } else if post_residual - next_item_size <= 10 {
            score -= 30.0;
        }
    }

    // Early in stream: be slightly more exploratory (keep residuals flexible);
    // late in stream: prioritize closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * tightness;

    // Mild tie-break toward bins close to the mean residual (balanced packing).
    score -= (mean_residual - post_residual as f64).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual), with slight nonlinearity
    score += 0.15 * (post_residual as f64) * (post_residual as f64) / bin_capacity as f64;

    // Aggressive 2-step lookahead: reward when next item fits perfectly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect chain match
        } else if next_item_size <= post_residual {
            // partial match: reward proportional to how well next item uses leftover
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 25.0 * fill;
        } else {
            // next item cannot use leftover; penalize dead space relative to gap
            let gap = (next_item_size - post_residual) as f64;
            score += 0.5 * gap;
        }
        // reward residuals that pair well with typical upcoming sizes vs mean residual
        let next_f64 = next_item_size as f64;
        if post_residual as f64 >= next_f64 && (post_residual as f64 - next_f64) < mean_residual {
            score -= 8.0;
        }
    } else {
        // last item: simply minimize waste
        score += 0.5 * post_residual as f64;
    }

    // Compare post_residual against mean residual across open bins:
    // leaving below-average residual is good (tight packing)
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless item is huge
    if bin_residual == bin_capacity {
        let ratio = item_size as f64 / bin_capacity as f64;
        if ratio > 0.85 {
            score -= 30.0; // big item: fresh bin is fine
        } else {
            score += 25.0 + 20.0 * (1.0 - ratio); // otherwise discourage
        }
    }

    // Slight preference for consolidating into fewer bins early in stream
    let progress = step_index as f64 / total_items as f64;
    score -= 2.0 * (1.0 - progress) * (open_bins_count as f64).ln().max(0.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual, but treat very small residuals as dead space.
    let dead_threshold = 9.0;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 6.0; // dead space penalty
    } else {
        score -= post_residual as f64 * 0.35; // reward usable leftover
    }

    // Perfect-fit bonus
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: reward if next item fits into the post residual (chaining)
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 - slack * 0.15; // exact chain fit best
    } else if next_item_size > 0 {
        // penalize blocking the next item
        let gap = (next_item_size - post_residual) as f64;
        score += gap * 0.10;
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current bin fit is poor
    if bin_residual == bin_capacity {
        let fit_quality = (bin_residual - item_size) as f64; // residual that would remain if placed here (same as post_residual)
        let open_pressure = open_bins_count as f64;
        // Opening a new bin is penalized mildly, but less when existing bins would leave bad fits
        score = 60.0 + fit_quality * 0.5 - open_pressure * 1.5;
        if next_item_size > 0 && next_item_size >= item_size {
            // fresh bin can serve a big next item too
            score -= 8.0;
        }
        if post_residual < dead_threshold as u32 {
            score += 20.0; // would create dead space in fresh bin
        }
    }

    // Global state coupling: when many bins are open, tighten packing
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (open_bins_count as f64) * 0.4 * (1.0 - progress);

    // Mean residual coupling: prefer bins below mean residual (loose bins get filled first)
    score -= (mean_residual - bin_residual as f64) * 0.2;

    // Slight time decay toward greedy tight packing late in stream
    score *= 1.0 - 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let mut score = pr;
    // smooth polynomial coupling: post_residual weighted by progress
    score += 40.0 * norm_pr * norm_pr * (0.5 + progress);
    // reward tight fits (small post_residual) more strongly later in the stream
    score -= 30.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * progress;
    // penalty if post_residual can't fit the next item (dead space)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            score += 15.0 * (nx - pr) / cap * (0.5 + progress);
        } else {
            // reward leaving room exactly for next item
            score -= 10.0 * (1.0 - (pr - nx) / cap).abs() * 0.5;
        }
    }
    // last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }
    // penalize spreading across many open bins when residuals are large
    score += 0.5 * (open_bins_count as f64) * (mean_residual / cap).powi(2);
    // new-bin candidate: mild penalty so we prefer existing bins unless fit is bad
    if bin_residual == bin_capacity {
        score += 20.0 + 10.0 * (1.0 - progress);
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space in (0,10) is nearly unusable
    // (min item size 1..100, but small residuals waste capacity).
    let pr = post_residual;
    if pr == 0 {
        // Perfect fit: strongly reward.
        score -= 60.0;
    } else if pr < 10 {
        // Unusable dead space: penalize hard.
        score += 25.0 + (10 - pr) as f64;
    } else {
        // Harmonic (modulo) classes: residuals divisible by common item-size
        // classes are more likely to be filled later.
        let m = pr % 10;
        if m == 0 {
            score -= 6.0; // aligns with decade item sizes
        } else if m == 5 {
            score -= 3.0; // half-decade alignment
        }
        // Integer-division thresholds: residual >= 50 keeps half-bin utility.
        if pr >= 50 {
            score -= 4.0;
        } else if pr < 25 {
            score += 5.0;
        }
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size <= pr {
            // fits, but not perfectly: partial reward scaled by waste
            let waste = (pr - next_item_size) as f64;
            score -= 15.0 - 0.2 * waste;
        } else {
            // next item cannot use this residual: mild penalty proportional to gap
            score += 0.1 * ((next_item_size - pr) as f64).min(20.0);
        }
    }

    // Last chance bin: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 18.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the
    // item is large relative to capacity or existing residuals are poor.
    if bin_residual == bin_capacity {
        // Base competitiveness: empty bin has full residual, so raw score is
        // already high (post_residual = capacity). Adjust with context.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Late in stream, prefer consolidating into open bins.
        score += 8.0 * (1.0 - progress);
        // Many open bins with low mean residual => new bin is wasteful.
        if mean_residual > 30.0 {
            score += 10.0;
        }
        // Large items (>= 60) benefit from a fresh bin to avoid fragmentation.
        if item_size >= 60 {
            score -= 12.0;
        }
        // If no open bin can fit, new bin is the only option (fitting_bins_count
        // counts fitting open bins; for empty-bin call it equals that count).
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mild pressure to spread load when few bins are open.
    if open_bins_count > 0 {
        score -= 2.0 / open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space penalty: small unusable gaps (below min item size) are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 500.0;
    }

    // Tightness reward: prefer bins where the item fills a large fraction.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fill_ratio;

    // Penalize leaving residual that cannot fit the lookahead item if it could otherwise.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0; // residual stays useful for next item
        } else if post_residual > 0 {
            score += 30.0; // residual too small for next item
        }
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += 3.0 * open_bins_count as f64;

    // Prefer bins with residual near the mean (balanced packing).
    score += 0.5 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: strong reward to use it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: mildly discourage opening new bins unless current bins are poor fits.
    if bin_residual == bin_capacity {
        score += 150.0;
        // Allow new bin early in the stream when few bins are open.
        if open_bins_count == 0 {
            score -= 400.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect match: post_residual equals next item size -> strong reward.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 25.0 / (1.0 + diff * 0.35);
        // Exact match bonus scaled by tightness.
        if post_residual == next_item_size {
            score -= 12.0;
        }
        // Penalize leaving a residual that is too small for any future item
        // (dead space): residual below typical minimum item size.
        if next_item_size > post_residual {
            score += (next_item_size - post_residual) as f64 * 0.25;
        }
    } else {
        // Last item: prefer the fullest bin to avoid waste.
        score -= 5.0;
    }

    // Penalize creating unusable slivers (< 10 dead space).
    if post_residual < 10 && post_residual > 0 {
        score += (10 - post_residual) as f64 * 3.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // Compare against mean residual: placing into a below-average bin
    // balances the fleet.
    if mean_residual > 0.0 {
        score += (mean_residual - post_residual as f64) * 0.3;
    }

    // New-bin candidate: keep it neutral-ish, only attractive when no
    // good fit exists (many open bins with poor residuals).
    if bin_residual == bin_capacity {
        score = cap * 0.85 + open_bins_count as f64 * 0.5;
        if fitting_bins_count == 0 || next_item_size > post_residual {
            score -= 20.0;
        }
    }

    // Late in the stream, consolidate more aggressively.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score -= progress * (bin_residual - item_size) as f64 * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let is_new_bin = bin_residual == bin_capacity;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer tight fits (small post_residual).
    let mut score = post_residual as f64;

    // Reward perfect/near-perfect fills aggressively.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    }

    // Lookahead coupling: does the next item fit into the resulting gap?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Reward proportionally to how well the next item would fill the gap.
            let gap_use = next_item_size as f64 / post_residual as f64;
            score -= 10.0 * gap_use;
            if next_item_size == post_residual {
                score -= 8.0; // chain fill is ideal
            }
        } else {
            // The leftover gap is dead space for the next item: penalize
            // more strongly late in the stream when compaction matters.
            score += 4.0 + 6.0 * progress;
        }
    } else {
        // Last item: only absolute tightness matters.
        score -= 5.0;
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 20.0;
    }

    // Many open bins: encourage consolidation into existing bins.
    score -= (open_bins_count as f64).ln().max(0.0) * 1.5;

    // If this bin's residual is well below the mean residual, it's a good
    // compaction target; if far above mean, it's a poor home for the item.
    if !is_new_bin {
        let diff = bin_residual as f64 - mean_residual;
        score += 0.15 * diff;
    }

    // New-bin candidate pricing: expensive baseline so it only wins when
    // every open-bin fit is genuinely bad (large post_residual + penalties).
    if is_new_bin {
        score += 35.0 + 10.0 * (1.0 - progress);
        // Opening a bin when few are open is cheaper than fragmenting many.
        score -= (open_bins_count as f64) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit = fitting_bins_count as f64;

    // Base: penalize large post-residual, scaled non-linearly by progress
    let mut score = pr * (1.0 + 0.5 * progress * progress);

    // Tight fits rewarded more strongly as stream progresses
    let tightness = 1.0 - pr / cap;
    score -= tightness * tightness * (10.0 + 20.0 * progress);

    // Dead space penalty: small-but-nonzero residuals are worst
    let dead = pr / cap;
    score += dead * (1.0 - dead) * (1.0 - dead) * 15.0;

    // Last-chance bin: strong reward to use it
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }
    // Many alternatives: mild penalty to prefer best-fit discrimination
    score += (fit - 1.0).ln().max(0.0) * 2.0;

    // Lookahead coupling: reward residual that can host next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 8.0 * (1.0 - (pr - nx) / cap) * (0.5 + progress);
        } else {
            score += 4.0 * (nx - pr) / cap;
        }
    }

    // Mean-residual coupling: prefer bins near the mean (balanced packing)
    score += 0.3 * (pr - mean_residual).abs() * (1.0 - progress);

    // New-bin candidate: penalize slightly unless current bins are poor fits
    if bin_residual == bin_capacity {
        score = cap * (1.0 + progress) - if fitting_bins_count == 1 { 5.0 } else { 0.0 };
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residuals divisible by 10 are more reusable
    let pr = post_residual;
    let harmonic_bonus = match pr % 10 {
        0 => 6.0,
        5 => 3.0,
        _ => 0.0,
    };
    score -= harmonic_bonus;

    // Penalize awkward residuals in the "dead zone" (1..=9 after modulo effects)
    if pr > 0 && pr < 10 {
        score += 8.0;
    }

    // Integer-division thresholds: residual / item_size ratio classes
    if item_size > 0 {
        let fits_ratio = pr / item_size; // how many copies could still fit
        score -= 4.0 * fits_ratio as f64;
    }

    // Coupling with next item: reward residuals that exactly fit or nearly fit the lookahead
    if next_item_size > 0 {
        if pr == next_item_size {
            score -= 10.0;
        } else if pr > next_item_size && (pr - next_item_size) % 10 == 0 {
            score -= 5.0;
        } else if pr < next_item_size && pr > 0 {
            // dead space relative to lookahead item
            score += (next_item_size - pr) as f64 * 0.3;
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current bin fit is terrible
    if bin_residual == bin_capacity {
        // A fresh bin starts with full residual; make it competitive only if item is large
        score = (bin_capacity - item_size) as f64;
        if item_size >= 60 {
            score -= 3.0; // large items fine in fresh bins
        }
        if fitting_bins_count > 0 && item_size <= 40 {
            score += 15.0; // prefer existing bins for small items
        }
    }

    // Progress-based mean-residual coupling: spread load when many bins are open
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if post_residual as f64 > mean_residual {
        score -= 2.0 * (1.0 - progress);
    } else {
        score += 1.0 * progress;
    }

    // Slight pressure to keep number of open bins bounded
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = 0.0;

    // Tight fit reward: exact or near-exact fills are excellent.
    score += post_residual as f64 * 0.9;

    // Dead-space penalty: small gaps (1..10) are nearly unusable for items >= 10... but
    // item sizes can be as small as 1, so weight by how unusable the gap likely is.
    let dead = if post_residual == 0 {
        0.0
    } else if post_residual < 10 {
        6.0 // small gap, mildly reusable for tiny items but risky
    } else {
        0.0
    };
    score += dead;

    // Lookahead: if the next item fits exactly in the post residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 8.0 + 4.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here after placement: penalize proportionally to wasted residual.
        score += 2.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 5.0;
    }

    // Open-bin pressure: prefer using existing bins over opening new ones when many are open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.15 * (1.0 - progress);

    // New-bin candidate handling: empty bin gets a moderate default score so that
    // it is only chosen when open bins would create worse dead space.
    if bin_residual == bin_capacity {
        score += 12.0 + mean_residual * 0.05;
    } else {
        // Prefer bins whose residual is close to the item (best-fit coupling).
        let fit_quality = 1.0 - (bin_residual - item_size) as f64 / bin_capacity as f64;
        score -= 3.0 * fit_quality;
    }

    // Mean residual coupling: when mean residual across open bins is low, be greedy;
    // when high, spread items to consolidate.
    if bin_residual as f64 > mean_residual {
        score += 1.0;
    } else {
        score -= 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to item size)
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 30.0 * tightness;

    // 2-step lookahead: reward if next item fits the post residual exactly-ish
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 20.0 * (1.0 - slack / (bin_capacity as f64));
    }
    // Penalize leaving a residual too small for the next item (dead space)
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 0.6 * (next_item_size as f64 - post_residual as f64);
    }

    // Relative to mean residual: prefer bins with less room than average (pack fuller bins)
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Penalize opening a new bin unless existing fit is very poor
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let fit_quality = (post_residual as f64) / (bin_capacity as f64);
        score += 25.0 * (1.0 - fit_quality);
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0;
        }
        score += open_bins_count as f64 * 0.3;
    }

    // Late in stream: prefer closing bins tightly
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 0.1 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor placements that nearly fill the bin.
    let tightness = (item_size as f64 / bin_capacity as f64).powf(1.5);
    score -= 8.0 * tightness;

    // Perfect fit: exceptional reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: if the next item fits into the post-residual, reward this chain.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let chain_quality = next_item_size as f64 / post_residual as f64;
            score -= 6.0 * chain_quality;
        } else {
            // Dead space: post-residual too small for the next item.
            let waste = post_residual as f64 / bin_capacity as f64;
            score += 10.0 * waste;
        }
        // If next item would exactly fill post-residual, big chain bonus.
        if next_item_size == post_residual {
            score -= 15.0;
        }
    } else {
        // Last item: waste matters most.
        score += 2.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: if this is the only open bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: penalize opening a new bin when other bins fit,
    // scaled by how much residual capacity is already spread across open bins.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 1 {
            score += 25.0;
        }
        // Early in the stream, opening bins is cheaper (fewer open bins exist).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 * progress;
        // Many open bins with large mean residual: discourage adding another.
        score += 0.5 * open_bins_count as f64 * (mean_residual / bin_capacity as f64);
    } else {
        // Using an existing bin with large residual is good for consolidation.
        score -= 0.3 * (bin_residual as f64 / bin_capacity as f64);
    }

    // Late-stream pressure: consolidate more aggressively as the stream ends.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual != bin_capacity {
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: penalize post residual, with non-linear tightening over stream progress.
    let mut score = post * (1.0 + 0.8 * progress * progress);

    // Strong reward for tight fits (non-linear in fill ratio).
    let fill = 1.0 - post / cap;
    score -= 30.0 * fill * fill * fill;

    // Penalize residuals that are too small to hold the next item (dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0 + 0.25 * (next_item_size as f64 - post);
    }
    // Reward residuals that exactly anticipate the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 10.0;
    }

    // Last-chance bin bonus: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).ln().max(0.0);
    }

    // Coupling with mean residual: prefer bins below mean residual (denser bins).
    score += 0.15 * (post - mean_residual);

    // Discourage opening new bins early; allow it late when residuals are fragmented.
    let new_bin = (bin_residual as f64 == cap) as f64;
    let fragmentation = if open_bins_count > 0 { mean_residual / cap } else { 0.0 };
    score += new_bin * (8.0 - 10.0 * progress - 6.0 * fragmentation);

    // Mild non-linear penalty on very small leftover slivers.
    if post > 0.0 && post < 10.0 {
        score += (10.0 - post) * (10.0 - post) * 0.4;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fraction of capacity consumed by this placement.
    let fill_frac = item_size as f64 / bin_capacity as f64;

    // Reward high fill ratio (subtract proportional to how much of the bin is used).
    score -= 40.0 * fill_frac * fill_frac;

    // Harmonic class of post_residual: classify dead space by residue classes.
    // Residuals that are "useless" (very small, can't host typical items) are penalized.
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    } else if post_residual < 10 {
        // Dead space below the minimum item size — penalize heavily.
        score += 25.0;
    } else {
        // Harmonic class via integer division thresholds on post_residual.
        let class = post_residual / 10; // 1..=10
        // Favor residuals in classes that future items (10..80) can still use well.
        match class {
            1 => score -= 12.0, // 10-19: usable by small items
            2 => score -= 6.0,  // 20-29
            3 => score -= 2.0,  // 30-39
            4 => score += 0.0,
            5 => score += 1.0,
            6 => score += 2.0,
            7 => score += 3.0,
            8 => score += 2.0,
            9 => score += 1.0,
            _ => score -= 4.0,  // near-full leftover
        }
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / 50.0).max(0.0);
        } else {
            // Next item won't fit here: mild penalty proportional to overshoot class.
            let over = (next_item_size - post_residual) / 20;
            score += 3.0 * over as f64;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when existing bins are crowded
        // and the current fit is poor. Base cost of a fresh bin:
        score += 30.0;
        // Cheaper to open new bins early in the stream (amortization over many items).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 15.0 * (1.0 - progress);
        // If open bins have large mean residual, prefer them over a new bin.
        score += mean_residual * 0.3;
        // If many bins already fit the item, opening a new one is wasteful.
        if fitting_bins_count > 1 {
            score += 20.0;
        }
    } else {
        // Slight preference for bins tighter than the current mean residual
        // (keeps large residuals available for large future items).
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        } else {
            score += 2.0;
        }
    }

    // Mild pressure against hoarding many open bins.
    score += open_bins_count as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold even
    // the smallest plausible future item (<= 10) are pure waste.
    if post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 15.0;
    } else if post_residual < 30 {
        score -= 6.0;
    } else if post_residual < 50 {
        score -= 10.0;
    }

    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, encourage
    // tight fills; few open bins -> allow opening new bins more freely.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / 20.0);
    score += 0.35 * pressure;

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - slack / 50.0).max(0.0);
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item cannot use this residual: mild penalty proportional to gap.
        score += 0.08 * post_residual as f64;
    }

    // New-bin candidate: penalize opening a new bin, more so early in the
    // stream and when open bins already have plenty of room.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        score += 18.0 + 12.0 * (1.0 - progress) + 0.25 * mean_residual;
    }

    // Mild bonus for filling bins that are already mostly full.
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 8.0 * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: bin becomes exactly sized for the next item
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }

    // Post-residual too small for next item: dead space unless it's zero
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 0.5 * (next_item_size - post_residual) as f64;
    }

    // Post-residual slightly above next item: still good, mild bonus
    if next_item_size > 0 && post_residual > next_item_size && post_residual <= next_item_size + 10 {
        score -= 10.0;
    }

    // Compare bin residual against mean residual: prefer tighter-than-average bins
    score -= (mean_residual - bin_residual as f64) * 0.2;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Penalize wasting a fresh bin on a small item unless nothing fits well
    if bin_residual == bin_capacity {
        score += 15.0;
        if item_size >= 80 {
            score -= 25.0;
        }
    }

    // Late in the stream: consolidate, avoid leaving many fragmented bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress > 0.7 {
        score += post_residual as f64 * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fit_ratio * fit_ratio;

    // Penalize leaving awkward dead space (post_residual small but nonzero is bad).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item exactly well.
    if next_item_size > 0 && post_residual >= next_item_size {
        let pair_waste = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - pair_waste / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space that next item cannot use: mild penalty.
        score += 3.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate logic: only attractive when open bins are nearly full
    // or the item fits terribly everywhere.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_pressure = mean_residual / bin_capacity as f64;
        // Opening a bin is penalized more when few bins are open or early in stream.
        score += 15.0 + 10.0 * (1.0 - progress) + 5.0 * (1.0 - avg_pressure);
        // But if item is large and mean residual is small, opening is less bad.
        if (item_size as f64) > mean_residual {
            score -= 10.0;
        }
    }

    // Mild preference for bins with below-mean residual (consolidate fullness).
    score += 2.0 * ((bin_residual as f64 - mean_residual) / bin_capacity as f64);

    // Slight penalty for spreading across many open bins.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let r = post_residual as f64;
    let cap = bin_capacity as f64;
    let rn = r / cap;

    // Base: prefer tight fits (low post residual), with non-linear shaping
    let mut score = r * (1.0 + 0.5 * rn * rn);

    // Smooth polynomial coupling of post_residual with stream progress:
    // late in the stream, waste is penalized more heavily (quadratic in progress)
    let progress_waste = progress * progress * (r * r) / (cap * cap) * 40.0;
    score += progress_waste;

    // Early in stream: encourage packing into existing bins to limit bin count
    let early_bonus = (1.0 - progress).powi(2) * (open_bins_count as f64).ln_1p() * 2.0;
    score -= early_bonus;

    // Last-chance bin: strongly reward using it (avoid opening new bins)
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Dead-space penalty: residuals too small for typical items
    if rn > 0.0 && rn < 0.1 {
        score += (0.1 - rn) * 100.0 * (0.5 + progress);
    }

    // Lookahead: reward leaving space for the next item smoothly
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let gap = (r - ns).abs();
        let fit_next = if r >= ns { 1.0 } else { 0.0 };
        score -= fit_next * 8.0 * (1.0 - gap / cap);
        // penalize residual that neither fits next item nor is tiny
        if r < ns {
            score += (ns - r) * 0.15 * progress;
        }
    }

    // Mild preference for bins below mean residual (balance residuals smoothly)
    score += 0.05 * (r - mean_residual).abs() * (1.0 - progress);

    // New-bin candidate: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        let tightness = (item_size as f64 / cap).powi(2);
        score = cap - 5.0 * progress + 10.0 * (1.0 - tightness);
        if fitting_bins_count > 1 {
            score += 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: quantize dead space into capacity fractions.
    let post_frac = post_residual as f64 / cap;
    let class = (post_frac * 8.0).floor() as i64; // 8 harmonic classes of 12.5% capacity
    score += 3.0 * (class as f64 - (post_frac * 8.0));

    // Perfect / near-perfect fits strongly rewarded.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 2 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Penalize residuals that no future item (1..=100) can realistically use:
    // dead space smaller than the smallest plausible item is wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: reward if next item exactly fills the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            let gap = post_residual - next_item_size;
            score -= 15.0 * (1.0 - gap as f64 / cap);
        } else {
            // Next item cannot follow here; mildly penalize tight residuals it can't use.
            let overshoot = next_item_size - post_residual;
            if overshoot <= 10 {
                score += 5.0 + overshoot as f64;
            }
        }
    }

    // Modulo arithmetic on post_residual: multiples of common item sizes are reusable.
    let m = post_residual;
    if m > 0 && (m % 10 == 0 || m % 20 == 0 || m % 25 == 0 || m % 50 == 0) {
        score -= 12.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: default cost, relaxed when open bins are crowded.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowd = open_bins_count as f64 / (mean_residual.max(1.0) / cap + 1.0);
        score = cap * (0.9 - 0.2 * progress) + crowd;
        // Opening a new bin is fine if no existing bin has a decent fit.
        if bin_residual >= item_size * 2 {
            score += 10.0;
        }
    }

    // Prefer bins whose residual is close to the item (tight fit) over loose bins.
    let tightness = 1.0 - (bin_residual - item_size) as f64 / cap;
    score -= 10.0 * tightness;

    // Mild preference to fill older bins when many are open.
    score += 0.5 * open_bins_count as f64 * (1.0 - tightness);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize residuals that are too small to be
    // useful later (unusable gaps below the minimum item size ~ 1..100 range,
    // so treat gaps < 10 as pure dead space, and lightly penalize small gaps).
    if post_residual < 10 {
        score += 50.0;
    } else if post_residual < 25 {
        score += 12.0;
    } else if post_residual > 50 {
        // Reward leaving large, flexible residuals
        score -= 8.0;
    }

    // Perfect / near-perfect fits are highly desirable
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // strongly reward this placement (chained fit).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 40.0;
        } else if slack < 10 {
            score -= 15.0;
        } else {
            score -= 5.0;
        }
    }
    // If next item cannot use the post residual at all, the gap is likely dead
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidating into
    // existing bins; penalize opening new bins.
    let open_pressure = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are already open,
        // but allow it when existing bins would leave bad dead space.
        score += 20.0 + open_pressure * 2.0;
    } else {
        // Existing bin: reward using it, scaled by how full it already is.
        let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= 10.0 + fill_ratio * 15.0;
    }

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it's an outlier gap; prefer filling it to reduce fragmentation.
    let res = post_residual as f64;
    if res < mean_residual - 15.0 {
        score += 6.0;
    } else if res > mean_residual + 15.0 {
        score -= 4.0;
    }

    // Late in the stream, close out bins tightly (waste matters more).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly fits next item
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 * (1.0 - diff / bin_capacity as f64).max(0.0);
        if post_residual == next_item_size {
            score -= 100.0; // exact 2-item fill: bin closes after next item
        }
        // Post-residual too small for next item but nonzero = dead space
        if post_residual < next_item_size && post_residual > 0 {
            score += 0.5 * post_residual as f64;
        }
    } else {
        // Last item: prefer tightest fit
        score -= 50.0;
    }

    // Reward filling relative to mean residual across open bins
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Penalize opening a new bin when open bins can fit the item
    if bin_residual == bin_capacity {
        score += 25.0 + 2.0 * open_bins_count as f64;
    }

    // Late in stream: consolidate, avoid spreading across many bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 10.0 * (open_bins_count as f64 / (open_bins_count.max(1) as f64 + 5.0));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small to be useful later.
    if post_residual < 10 {
        score -= 25.0; // perfect closure is great
    } else if post_residual < 20 {
        score += 8.0; // awkward dead zone
    } else if post_residual > 50 {
        score += 10.0; // wasteful placement in a roomy bin
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Lookahead: reward leaving room for the next item if it fits in post_residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 18.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            // If next item can't fit here, slightly deprioritize using this bin
            // unless the fit is very tight anyway.
            score += 6.0;
        }
        // Chain-fit bonus: current item + next item fill the bin nicely.
        let combined = item_size as f64 + next_item_size as f64;
        if combined <= bin_residual as f64 && bin_residual as f64 - combined < 15.0 {
            score -= 15.0;
        }
    }

    // Global state coupling: with many open bins, encourage consolidation
    // (fill existing bins) rather than spreading items.
    let open_norm = open_bins_count as f64;
    score += 0.35 * open_norm * (1.0 - fit_ratio);

    // Mean residual coupling: if open bins are generally roomy (high mean
    // residual), tighten selection pressure toward best fits.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Time horizon: early in the stream, be more conservative (keep bins
    // flexible); late in the stream, close bins aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 12.0 * progress * fit_ratio;
    score += 6.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: an empty bin has huge residual; make it
    // attractive only when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        // Default: slightly worse than a good existing fit...
        score = 45.0 + desperation * 55.0;
        // ...but if existing fits are terrible (huge post_residual everywhere),
        // opening fresh can win because our base score for those is high.
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size {
            score -= 20.0; // next item pairs well with a fresh bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let fill = 1.0 - (post_residual as f64 / cap);

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, prefer filling bins tightly (quadratic in fill); later, dead space matters more.
    let poly = (1.0 - progress) * (fill * fill) * 6.0 + progress * (fill * fill * fill) * 10.0;
    score -= poly;

    // Penalize residual relative to mean residual across open bins (smooth cubic coupling)
    let dev = (post - mean_residual) / cap;
    score += dev * dev * dev * 4.0 + dev * 2.0;

    // Lookahead: reward leaving room for the next item (smooth quadratic interaction)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (post - nx) / cap;
        if gap >= 0.0 {
            score -= 5.0 * (1.0 - gap) * (1.0 - gap) * gap.abs().sqrt();
        } else {
            score += 3.0 * (-gap) * (-gap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 8.0 + 4.0 * fill;
    }

    // Mild penalty for spreading across many open bins
    score += (open_bins_count as f64).ln() * 0.3 * (1.0 - fill);

    // New-bin candidate: keep it neutral-ish unless fit is very tight
    if bin_residual == bin_capacity {
        score += 2.0 - 6.0 * fill;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 and integer-division bands
    let r = post_residual % 10;
    let band = post_residual / 10;

    // Penalize "dead" residuals that are hard to fill (small odd residues)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if r == 1 || r == 3 || r == 7 || r == 9 {
        score += 8.0;
    } else if r == 5 {
        score += 2.0;
    } else {
        score -= 3.0; // even / zero residues are friendlier
    }

    // Reward large usable bands (integer division thresholds)
    score -= (band as f64) * 2.0;

    // Perfect fits are gold
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead coupling: if next item fits the post residual, big reward
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        score -= 15.0 + slack as f64 * 0.3;
        // harmonic bonus when next_item lands on a friendly residue class
        let nr = next_item_size % 10;
        if nr == 0 || nr == 5 {
            score -= 5.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // next item cannot use this leftover: penalize proportionally
        score += 10.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin should only win when
    // current fit is terrible (large item, tiny residual)
    if bin_residual == bin_capacity {
        // baseline for a fresh bin: its post_residual is cap - item
        let fresh_band = post_residual / 10;
        score = (cap - post_residual as f64) + 30.0 - (fresh_band as f64) * 2.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
        // discourage opening bins when many are already open with room
        if mean_residual > item_size as f64 {
            score += 15.0;
        }
    }

    // Stream progression: late in the stream, consolidate aggressively
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 6.0 * (mean_residual / cap.max(1.0));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps heavily.
    // A residual gap is "dead" if it's too small for even the minimum item.
    let min_item = 1.0f64;
    if (post_residual as f64) < min_item {
        score += 1000.0; // should never happen, but hard guard
    }
    // Small non-zero residuals are wasteful: superlinear penalty below a threshold.
    if post_residual > 0 && post_residual <= 20 {
        score += (21 - post_residual as i32) as f64 * 8.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Open-bins pressure: penalize placements into bins when many bins are open,
    // encouraging consolidation; but reward when few bins are open.
    let obp = open_bins_count as f64;
    score += 0.5 * obp * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: only attractive if this bin's fit is bad (large post_residual)
    // and item is large. Otherwise penalize opening new bins.
    if bin_residual == bin_capacity {
        score += 250.0;
        score -= (item_size as f64 / bin_capacity as f64) * 100.0;
    }

    // Lookahead: if next item fits exactly in post_residual, reward this placement.
    if next_item_size > 0 && (next_item_size as u32) == post_residual {
        score -= 300.0;
    } else if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        score -= 30.0;
    }

    // Stream progression: as the stream advances, be slightly more conservative
    // with residual space (dead space matters more later).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64 * 0.3);

    // Mean residual coupling: if this bin's post_residual is far below the mean,
    // it's a tight fit — reward it; if far above, penalize.
    let diff = mean_residual - post_residual as f64;
    score -= diff * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    let is_new_bin = bin_residual == bin_capacity;

    // Last-chance bin: strongly prefer filling it rather than opening a new bin.
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Mild penalty for opening a new bin when existing bins could fit the item.
    if is_new_bin && fitting_bins_count > 0 {
        score += 5.0;
    }

    // Aggressive 2-step lookahead: couple post_residual with next_item_size.
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        if (pr - nr).abs() < 0.5 {
            // Perfect pair: next item exactly fills this bin's leftover.
            score -= 8.0;
        } else if pr > nr {
            // Next item can chain into this bin; reward snug chains.
            score -= 4.0 * (nr / pr).min(1.0);
        } else {
            // Dead space relative to the lookahead item.
            score += 0.35 * (nr - pr).min(40.0);
        }
    }

    // Prefer bins whose resulting residual is at or below the fleet average,
    // preserving slack-rich bins for future large items.
    score += 0.15 * (pr - mean_residual).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;

    // Tight-fit reward: low post_residual strongly favored.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Reward when the lookahead item also fits in the post residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 + 4.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
    }
    // Penalize leaving a residual the next item cannot use (dead space).
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 3.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a bin when existing bins can fit the item,
    // scaled by how many alternatives exist and how much residual is idle elsewhere.
    if is_new_bin {
        if fitting_bins_count > 0 {
            let idle = (mean_residual * open_bins_count as f64).max(0.0);
            score += 12.0 + 4.0 * fitting_bins_count as f64 + 0.05 * idle;
            // Late in the stream, closing out bins matters more; soften the penalty.
            score -= 8.0 * progress;
        } else {
            // No alternative: opening a new bin is necessary; slight reward.
            score -= 10.0;
        }
    }

    // Mild preference for filling bins with large residuals early (reduce fragmentation).
    score -= 0.05 * bin_residual as f64 * (1.0 - progress);

    // Tie-break toward consolidating among many open bins.
    score += 0.3 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / (total_items as f64 - 1.0) } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit_norm = pr / cap;

    // Base: penalize leftover space, but with a non-linear (quadratic) coupling
    // that punishes both large waste and awkward mid-range residuals.
    let mut score = pr + 8.0 * fit_norm * (1.0 - fit_norm) * cap * 0.5;

    // Stream-progress coupling: early on, prefer tight fills (reward low post_residual);
    // later, be more tolerant of residuals since distribution is known better.
    let tightness = 1.0 - fit_norm;
    score -= (1.0 - progress) * 6.0 * tightness * tightness * cap * 0.2;
    score += progress * 3.0 * fit_norm * fit_norm;

    // Lookahead coupling: reward residuals that still fit the next item,
    // penalize residuals that are too small to be useful.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 5.0 * (1.0 - (pr - nx) / cap) * (1.0 - progress * 0.5);
        } else {
            score += 4.0 * (nx - pr) / cap * (1.0 + progress);
        }
    } else {
        // Last item: strongly prefer zero residual.
        score += 10.0 * fit_norm;
    }

    // Scarcity: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 + progress);
    }

    // Mean-residual coupling: prefer bins whose post_residual is below the mean
    // (consolidating space into fewer bins).
    let dev = (pr as f64 - mean_residual) / cap;
    score += 5.0 * dev * (1.0 + 0.5 * (open_bins_count as f64).ln().max(0.0));

    // Smooth non-linear interaction: post_residual^2 vs capacity and progress.
    score += 0.0004 * pr * pr * (1.0 - progress);

    // New-bin candidate: mildly penalize opening a new bin unless item is large
    // relative to capacity.
    if bin_residual == bin_capacity {
        score += 6.0 - 4.0 * (item_size as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space quality classes.
    // Small residues (<10) are effectively "perfect closures" of the bin.
    if post_residual == 0 {
        score -= 60.0; // perfect fit
    } else if post_residual < 10 {
        score -= 40.0; // near-perfect closure, unusable space anyway
    }

    // Harmonic bucket: post_residual mod 10 captures fine-grain waste class
    let waste_class = post_residual % 10;
    score -= (10 - waste_class) as f64 * 0.8; // residues just above a multiple of 10 are less reusable

    // Coarse class: integer division of post_residual by item's "harmonic size"
    // Residuals that can host the next item are valuable.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // This bin can also host the lookahead item: strong reward
            score -= 25.0;
            // Extra reward if post_residual is a near-exact match for next item
            let slack = post_residual - next_item_size;
            if slack < 10 {
                score -= (10 - slack) as f64 * 2.0;
            }
        } else {
            // Cannot host next item: penalize proportionally to how much is stranded
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
        // If next item is large, prefer leaving big residuals intact
        if next_item_size > 50 && post_residual > next_item_size {
            score -= 8.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a bin is expensive.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin: high unless existing bins are badly fragmented
        let mut new_bin_score = 70.0;
        // If mean residual across open bins is small, open bins are nearly full:
        // opening a new bin is reasonable.
        if mean_residual < 15.0 {
            new_bin_score -= 45.0;
        } else {
            // Penalize opening new bins when open bins have plenty of room
            new_bin_score += (mean_residual - 15.0).min(60.0) * 1.2;
        }
        // Few open bins and many items left: consolidation matters more
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if open_bins_count > 3 && progress < 0.5 {
            new_bin_score += 10.0;
        }
        // If only this new bin can fit the item, it must be chosen
        if fitting_bins_count == 0 {
            new_bin_score -= 200.0;
        }
        return new_bin_score;
    }

    // Favor filling bins that are already large consumers (high item_size means
    // this bin's residual is precious); slight bias toward tighter fits overall.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 12.0;

    // Mild penalty for spreading across too many bins: prefer bins with below-mean residual
    if (bin_residual as f64) > mean_residual {
        score += 4.0;
    } else {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the smallest item (<=9)
    // are dead weight; penalize them heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Gaps that cannot fit the known next item are less useful.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 18.0;
    }
    // Reward tight fits (small post_residual relative to capacity).
    score -= (1.0 - post_residual as f64 / bin_capacity as f64) * 25.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is tight.
    score += open_bins_count as f64 * 1.5;

    // Mean residual coupling: if this bin's post-residual is far below the mean
    // residual of open bins, it is a good consolidation target.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: strongly favor using it instead of opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when no decent fit exists.
    if bin_residual == bin_capacity {
        score += 8.0 + open_bins_count as f64 * 0.5;
        if fitting_bins_count <= 1 {
            score -= 45.0;
        }
    }

    // Late in the stream, prefer closing bins tightly.
    let progress = step_index as f64 / total_items as f64;
    score += post_residual as f64 * progress * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward exact/near-exact matches
    // between post_residual and the next item's size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        let tight_fit = if post_residual as f64 >= next_item_size as f64 {
            gap
        } else {
            gap * 1.5 // next item can't fit here: penalize more
        };
        score += tight_fit * 0.8;
        // Bonus: post_residual exactly matches next item
        if post_residual == next_item_size {
            score -= 25.0;
        }
    }

    // Reward tight packing now: small post_residual is good
    score += (post_residual as f64 / bin_capacity as f64) * 30.0;

    // Penalize deviating from mean residual (avoid creating outlier dead space)
    score += (post_residual as f64 - mean_residual).abs() * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64;
        score += 10.0 - pressure * 0.5; // less penalty when many bins open
        if next_item_size > 0 && next_item_size as f64 >= bin_capacity as f64 * 0.9 {
            score -= 20.0; // big next item: fresh bin is valuable
        }
    }

    // Late in stream: prefer closing bins tightly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.4;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more aggressively as stream progresses.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (bin_capacity as f64 - post_residual as f64) * (0.4 + 0.6 * t);

    // Penalize dead space: post_residual too small to ever be useful (< typical min item 10).
    if post_residual < 10 {
        score += 25.0 * (1.0 - t);
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Lookahead: bonus if next item fits exactly in the post-residual (perfect chain).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // next item fits but leaves further residue: mild reward scaled by how snug.
            score -= 12.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // next item won't fit here: penalize creating unusable slivers.
            score += 6.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else {
        // More competing bins: slight penalty for spreading waste.
        score += (fitting_bins_count as f64).ln().max(0.0) * 2.0;
    }

    // New-bin candidate logic: opening a new bin is attractive when open bins are
    // already fragmented (high mean residual vs this bin's clean capacity) or when
    // too many bins are open relative to progress.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        let crowding = (open_bins_count as f64 / (10.0 + t * 20.0)).min(2.0);
        // Base cost of a fresh bin decreases with fragmentation of existing bins.
        score += 40.0 - 30.0 * fragmentation - 8.0 * crowding + 10.0 * t;
        // If next item is large, a fresh bin is valuable for it.
        if next_item_size >= 60 {
            score -= 15.0;
        }
    } else {
        // Favor bins whose residual is above mean (absorb slack where it's abundant).
        let slack = bin_residual as f64 - mean_residual;
        score -= 0.15 * slack;
    }

    // Global pressure: many open bins -> consolidate; few bins -> be flexible.
    let pressure = (open_bins_count as f64 / (t * 100.0 + 5.0)).min(3.0);
    score += 5.0 * pressure;

    // Small tie-break noise-free coupling with item size: prefer placing large items
    // into bins with proportionally small residual (avoid wasting big-item capacity).
    score -= 10.0 * (item_size as f64 / bin_capacity as f64) * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let r = bin_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit = (pr / cap).clamp(0.0, 1.0);

    // Base: penalize leftover space, with smooth non-linear shaping
    let mut score = pr * (1.0 + 0.8 * fit * fit);

    // Coupling of tightness with stream progress: late in stream, tight fits matter more
    score -= 12.0 * (1.0 - fit) * (1.0 - fit) * (0.3 + 0.7 * progress);

    // Penalize bins whose residual deviates from mean residual (smooth quadratic coupling)
    let dev = (r - mean_residual) / cap;
    score += 6.0 * dev * dev * (1.0 + progress);

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - fit);
    }

    // Lookahead: reward leaving space compatible with the next item
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr >= ns {
            score -= 10.0 * (1.0 - ((pr - ns) / cap).clamp(0.0, 1.0));
        } else {
            score += 5.0 * (ns - pr) / cap;
        }
    }

    // Mild penalty for bin proliferation relative to stream length
    score += (open_bins_count as f64) * 0.05 * (1.0 - progress);

    // New-bin candidate: penalize opening a new bin unless the item is large relative to it
    if bin_residual == bin_capacity {
        score += 8.0 + 20.0 * (1.0 - item_size as f64 / cap) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the resulting residual: capacity divided into 5 classes
    let class = (post_residual * 5) / bin_capacity; // 0..4
    // Reward landing in low-class (tight) residual buckets
    score -= (4 - class) as f64 * 3.0;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 60.0;
    }

    // Dead space penalty: residual too small for the smallest plausible item (<=10)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Modulo coupling: residual divisible by 8 pairs well with many item classes
    if post_residual % 8 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_post = post_residual - next_item_size;
        score -= 10.0;
        if next_post == 0 {
            score -= 20.0;
        }
        if next_post < 10 {
            score += 8.0; // avoid chaining dead space
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        score += 3.0; // this bin likely becomes dead after placement
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize mildly so it is chosen only when open bins are bad,
    // but reward it when open bins are crowded and mean residual is low.
    if bin_residual == bin_capacity {
        score += 12.0;
        if mean_residual < 20.0 && open_bins_count > 0 {
            score -= 10.0;
        }
        if post_residual > 60 {
            score -= 5.0; // roomy fresh bin for future big items
        }
    }

    // Stream progression: early on, prefer consolidation; late, allow spreading
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * (bin_residual as f64 - post_residual as f64) * 0.2;

    // Penalize bins far above mean residual (fragmentation spreading)
    score += ((bin_residual as f64 - mean_residual).abs()) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 18.0;
    } else if post_residual < 35 {
        score += 6.0;
    }

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Open-bin pressure: penalize spreading across many bins,
    // but relax pressure when this is the last fitting bin.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (1.0 - 0.5 * progress);
    if fitting_bins_count > 1 {
        score += pressure * 0.15;
    }

    // Last-chance bonus: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Prefer bins with below-average residual (tighter bins first).
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Lookahead: avoid blocking the next item in this bin.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0;
    }

    // New-bin candidate: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        score += 30.0 + pressure * 0.2;
        if fitting_bins_count <= 1 {
            score -= 55.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.18;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: square the post-residual penalty for large waste.
    score += 0.05 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 10.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 5.0;
        } else {
            // Next item cannot use leftover space: penalize proportional waste.
            score += 0.2 * (post_residual as f64);
        }
    }

    // Penalize opening a new bin when many open bins already fit the item.
    if bin_residual == bin_capacity {
        score += 30.0 + 2.0 * fitting_bins_count as f64;
        // Early in stream, new bins are cheaper; later, prefer consolidation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * (1.0 - progress);
    }

    // Prefer bins with residual below mean (consolidate small leftovers).
    score += 0.1 * (bin_residual as f64 - mean_residual);

    // Slight preference for filling fuller bins overall.
    score -= 0.05 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: tightest fit preferred, with smooth non-linear penalty on waste.
    let mut score = pr + (pr / cap).powi(3) * cap * 0.5;

    // Non-linear coupling of waste with stream progress: early on, waste is
    // cheaper (many items remain to fill gaps); late, waste is costly.
    let waste_weight = 0.5 + 2.5 * progress * progress;
    score += (pr / cap) * waste_weight * cap * 0.2;

    // Smooth interaction: post_residual vs mean residual — avoid bins whose
    // leftover diverges from the fleet average (keeps residuals homogeneous).
    let dev = (pr - mean_residual) / cap;
    score += dev.abs() * cap * 0.3 * (0.5 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (smoothly scaled by how tight the fit is).
    if fitting_bins_count == 1 {
        score -= cap * (0.6 + 0.4 * (1.0 - pr / cap));
    }

    // Lookahead coupling: if the next item fits the post-residual, reward;
    // smooth quadratic term when it almost fits.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 8.0 + (1.0 - (pr - nxt) / cap) * 12.0;
        } else {
            let gap = (nxt - pr) / cap;
            score += gap * gap * cap * 0.4;
        }
    }

    // Penalize opening a new empty bin, more so when good fitting bins exist
    // and late in the stream (fewer chances to consolidate).
    if bin_residual == bin_capacity && open_bins_count > 0 {
        let fit_pressure = if fitting_bins_count > 0 { 1.0 } else { 0.0 };
        score += cap * (0.8 + 0.6 * progress) * (0.5 + 0.5 * fit_pressure);
    }

    // Mild preference for bins with less residual before placement (tightness).
    score += (bin_residual as f64 / cap) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero is excellent.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 50.0;
    }

    // Harmonic classes: dead-space quality depends on post_residual class.
    // Residuals that can still host common item sizes are valuable.
    let usable = |r: u32, s: u32| r >= s;
    let small = 10u32.min(bin_capacity);
    // Can next item fit here after placement? Strong reward for chain fits.
    if next_item_size > 0 {
        if usable(post_residual, next_item_size) {
            // Perfect chain: post residual exactly absorbs next item.
            if post_residual == next_item_size {
                score -= 400.0;
            } else {
                score -= 60.0 + 2.0 * next_item_size as f64;
            }
        } else {
            // Next item cannot use this residual: penalize dead space,
            // scaled by how much of the capacity is wasted.
            let waste_frac = post_residual as f64 / bin_capacity as f64;
            score += 40.0 + 120.0 * waste_frac;
        }
    }

    // Harmonic class of post_residual via integer division thresholds:
    // classify residual into eighth-capacity buckets; odd classes (hard to fill) get penalty.
    let eighth = (bin_capacity / 8).max(1);
    let class = post_residual / eighth;
    match class {
        0 => score -= 30.0,           // tiny residual, near-perfect
        1 => score -= 10.0,
        2 | 3 => score += 5.0,        // mid residuals, mediocre
        4 | 5 => score += 15.0,
        _ => score += 25.0,           // large residual, weak signal anyway
    }

    // Modular arithmetic: residuals divisible by common item sizes are more reusable.
    let div_bonus = [20u32, 25, 40, 50]
        .iter()
        .filter(|&&d| d <= post_residual && post_residual % d == 0)
        .count() as f64;
    score -= 8.0 * div_bonus;

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 90.0;
    }

    // New-bin candidate handling: only open a new bin when item is huge relative
    // to mean residual or stream is late and bins are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = if open_bins_count > 0 { mean_residual / bin_capacity as f64 } else { 0.0 };
        // Prefer new bin if existing residuals are small (can't absorb future items well)
        let new_bin_bonus = 60.0 * (1.0 - fragmentation) + 40.0 * progress;
        score -= new_bin_bonus;
        // But if a perfectly tight fit exists elsewhere (post_residual small), don't open.
        if post_residual <= 10 {
            score += 200.0;
        }
    }

    // Late-stream pressure: consolidate to close bins faster.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Penalize bins with residual far from mean (outliers) mildly, to keep balance.
    score += 0.05 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the smallest plausible
    // future item are wasted space; penalize them super-linearly.
    if post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    } else if post_residual <= 20 {
        score += 12.0 * (20.0 - post_residual as f64);
    }

    // Reward tight fits relative to the item being placed.
    score -= 0.5 * (item_size as f64 / bin_capacity as f64) * (bin_residual as f64 - post_residual as f64);

    // Open-bin pressure: discourage spreading items across many bins unless
    // the fit is genuinely good.
    score += 0.6 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly prefer using the only bin that fits,
    // avoiding a new bin opening.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when the item is large and current
    // open bins have poor mean residual (fragmented space).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0
            - 0.4 * mean_residual
            - 10.0 * (item_size as f64 / 100.0)
            - 8.0 * progress;
    } else {
        // Existing bins with residual close to mean residual are "normal";
        // prefer bins whose residual is larger than average (consolidation).
        score -= 0.15 * (bin_residual as f64 - mean_residual);
    }

    // Lookahead: if next item can exactly use the post_residual, reward it.
    if next_item_size > 0 {
        if (next_item_size as i64 - post_residual as i64).abs() <= 2 {
            score -= 20.0;
        } else if post_residual > 0 && (next_item_size as u32) > post_residual {
            score += 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> strong reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    } else if next_item_size > 0 {
        // Partial lookahead match: how close is post_residual to fitting next item
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual >= next_item_size {
            // next item could still fit after this placement
            score -= 12.0 * (1.0 - gap / cap);
        } else {
            // dead space that next item cannot use: penalize proportionally
            score += 0.5 * gap;
        }
    }

    // Penalize very small unusable residuals (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Reward tight fits (small post_residual overall)
    score -= 20.0 * (1.0 - post_residual as f64 / cap);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize slightly so we prefer existing bins unless they are bad fits
    if bin_residual == bin_capacity {
        score += 18.0;
        // opening a new bin is more attractive late in stream with many open bins
        score += 5.0 * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));
    }

    // Mild normalization relative to mean residual: prefer bins tighter than average
    score -= 0.3 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item nearly fills the residual.
    let tight = (post_residual as f64) / (bin_capacity as f64);
    score += 40.0 * tight * tight;

    // Dead-space penalty for very small leftovers that few future items can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Lookahead: reward if the next item fits the post-residual (chaining placements).
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 15.0;
        } else {
            score += 10.0 * (next_item_size - post_residual.min(next_item_size)) as f64 / 100.0;
        }
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // existing bins fit poorly (large item vs residual) or few bins are open.
    if bin_residual == bin_capacity {
        let pressure = item_size as f64 / bin_capacity as f64;
        let scarcity = 1.0 / (1.0 + open_bins_count as f64);
        let early = 1.0 - (step_index as f64 / (total_items.max(1) as f64));
        score -= 30.0 * pressure * scarcity * (0.5 + 0.5 * early);
        // Penalize opening new bins when a decent fit already exists elsewhere.
        if fitting_bins_count > 0 {
            score += 20.0;
        }
    }

    // Global fragmentation: if mean residual is low, squeeze into existing bins harder.
    let frag = 1.0 - (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
    score -= 10.0 * frag * (bin_residual as f64 / bin_capacity as f64);

    // Late-stream consolidation: prefer filling existing bins as the stream ends.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 15.0 * progress * (bin_residual == bin_capacity) as i32 as f64;

    // Mild preference for bins with residual close to item size (waste minimization).
    let diff = (bin_residual as f64 - item_size as f64).abs();
    score += 0.2 * diff;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    let pr2 = pr_norm * pr_norm;
    let pr3 = pr2 * pr_norm;

    // Base: post residual, with smooth non-linear polynomial coupling to progress
    let mut score = pr * (1.0 + 0.6 * pr2) + 40.0 * pr3 * progress;

    // Penalize large dead space more as stream progresses (less time to recover)
    score += 25.0 * pr2 * progress;

    // Reward tight fits: small post residual relative to item size
    let item_f = item_size as f64;
    score -= 0.35 * item_f * (1.0 - pr_norm);

    // Lookahead: if next item fits the post residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 12.0 + 0.2 * next_item_size as f64;
    } else if next_item_size > 0 {
        // next item won't fit: penalize proportionally to wasted space
        score += 0.15 * (next_item_size as f64 - pr).max(0.0);
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 18.0 * (1.0 + progress);
    }

    // Mild penalty when many bins are open (encourage consolidation)
    score += 0.08 * open_bins_count as f64 * pr_norm;

    // Mean residual coupling: prefer bins below mean residual (fill emptier bins less)
    score += 0.1 * (mean_residual - pr);

    // New-bin candidate handling: make empty bin moderately attractive only for large items / poor fits
    if bin_residual == bin_capacity {
        let tightness = item_f / cap;
        score = 55.0 - 30.0 * tightness * (1.0 - progress) + 10.0 * progress;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "usable"
    // residue classes (multiples of common small sizes) are more valuable.
    let pr = post_residual;
    if pr > 0 {
        // class 0: perfectly filled bin -> strong reward
        if pr == 0 {
            score -= 1000.0;
        } else {
            // dead-space penalty grows when leftover cannot host typical items
            // harmonic class via integer division thresholds
            let class = pr / 10; // 0..=10 classes
            // leftovers in [1..9] are nearly dead; [10..19] marginal; >=20 usable
            score += match class {
                0 => 60.0,                       // 1..9 : dead space
                1 => 25.0,                       // 10..19
                2 => 8.0,                        // 20..29
                3 => 0.0,
                _ => -6.0,                       // >=30 : flexible residue
            };
            // modulo harmony: leftovers divisible by 10 pair well with 10-multiples
            if pr % 10 == 0 {
                score -= 12.0;
            } else if pr % 5 == 0 {
                score -= 5.0;
            }
        }
    } else {
        score -= 500.0; // exact fit is best
    }

    // Last-chance bonus: only bin that fits -> avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 80.0;
        } else if next_item_size < pr {
            let slack = pr - next_item_size;
            // harmonic class of the double-leftover
            if slack % 10 == 0 {
                score -= 15.0;
            }
            score += (slack as f64) * 0.3;
        } else {
            // next item cannot use this bin's leftover; slight penalty for
            // squandering space now
            score += 10.0;
        }
    }

    // New-bin candidate handling: empty bin gets a baseline cost so it is
    // chosen only when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score = 150.0 + (post_residual as f64) - (fitting_bins_count as f64) * 0.0;
        // late in stream, prefer reusing bins more strongly
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 20.0;
    }

    // Mild pressure toward consolidating into fewer bins
    score -= (open_bins_count as f64).ln().max(0.0) * 2.0;

    // Tie-break toward bins below mean residual (tighter bins first)
    score += (mean_residual - bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

