    // Pressure against proliferating open bins.
    score += open_bins_count as f64 * 1.5;

    // New-bin candidate: only attractive when item is large and no good fit exists.
    if bin_residual == bin_capacity {
        let tight_fit_exists = mean_residual >= item_size as f64 + 5.0;
        if tight_fit_exists && fitting_bins_count > 0 {
            score += 25.0; // keep using open bins
        } else {
            score -= 10.0; // opening fresh bin is reasonable
        }
    }

    // Mild phase adaptation: later in stream, favor compacting into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
