        if fitting_bins_count <= 1 {
            score -= 35.0;
        }
        if next_item_size > 0 && (post_residual as f64) < next_item_size as f64 {
            score += 5.0;
        }
        // Early in stream, keep bins open instead of proliferating.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * (1.0 - progress);
    }

    // Slight preference for bins tighter than the mean residual (fill crowded bins).
    score -= 0.10 * (mean_residual - bin_residual as f64);

    // Mild pressure against accumulating many open bins.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more aggressively as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (100.0 - post_residual as f64) * (0.5 + 0.5 * progress);

    // Penalize very small unusable leftovers (dead space), scaled by progress.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - progress);
    }
    if post_residual < item_size.min(20) && post_residual > 0 {
        score += 8.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // Next item won't fit here; mild penalty proportional to wasted potential.
            score += (next_item_size - post_residual) as f64 * 0.1;
        }
    }

    // New-bin candidate handling: empty bin should only win when residuals are
    // fragmented or the item is large relative to capacity.
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        let item_frac = item_size as f64 / bin_capacity as f64;
        // Penalize new bin normally...
        let mut new_bin_penalty = 20.0 + 30.0 * (1.0 - item_frac);
        // ...but reduce penalty when open bins are highly fragmented or few fit.
        new_bin_penalty -= 25.0 * fragmentation.max(0.0).min(1.0);
        if fitting_bins_count <= 1 {
            new_bin_penalty -= 15.0;
        }
        if open_bins_count == 0 {
            new_bin_penalty = -10.0;
        }
        score += new_bin_penalty;
    }

    // Mild global pressure: many open bins -> prefer reusing existing ones.
    score += open_bins_count as f64 * 0.05;
    // Prefer bins below mean residual (less-full bins) slightly, to balance.
    if bin_residual as f64 > mean_residual {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: prefer small post_residual, with a smooth polynomial shaping
    // (quadratic + quartic) that punishes large leftover space increasingly.
    let mut score = pr
        + 6.0 * norm_pr * norm_pr * cap
        + 12.0 * norm_pr.powi(4) * cap;

    // Smooth coupling with stream progress: late in the stream, leftover
    // space becomes more costly (fewer chances to fill it).
    score += 18.0 * progress * norm_pr * norm_pr * cap;

    // Reward tight fits: item filling a large fraction of the residual.
    let fill = if bin_residual > 0 { item_size as f64 / bin_residual as f64 } else { 0.0 };
    score -= 14.0 * fill * fill * norm_item;

    // Dead-space term: leftover that cannot fit a "typical" next item.
    if next_item_size > 0 {
        let wasted = ((pr - next_item_size as f64).max(0.0)) / cap;
        score += 10.0 * wasted * (1.0 + wasted);
    } else {
        // Last item: strongly prefer exact fills.
        score += 4.0 * norm_pr * cap;
    }

    // Penalize creating very small unusable slivers (smooth threshold via logistic).
    let sliver = 1.0 / (1.0 + (-8.0 * (norm_pr - 0.09)).exp());
    score += 9.0 * sliver * norm_pr * cap;

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity as u32 {
        score -= 30.0 * (1.0 + progress);
    }

    // New-bin candidate handling: empty bin gets a smooth adaptive penalty.
    let is_new = bin_residual == bin_capacity && item_size > 0;
    if is_new {
        let scarcity = 1.0 / (1.0 + (0.9 * (fitting_bins_count as f64 - 1.0)).exp());
        // Penalize opening new bins when good fits exist; relax late in stream
        // or when mean residual across open bins is low.
        let mean_r_norm = mean_residual / cap;
        let pressure = 1.0 / (1.0 + (10.0 * (mean_r_norm - 0.25)).exp());
        score = cap + 40.0 * scarcity * pressure * (1.0 - 0.5 * progress)
            - 10.0 * progress * norm_item;
        // A new bin fits perfectly; if no open bin fits at all, scarcity term
        // already drives score low enough via pressure.
    }

    // Mild regularization against bin-count explosion.
    score += 0.05 * open_bins_count as f64 * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits
    score -= 12.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Harmonic class of post_residual: bins whose residual falls into "reusable" classes
    // (multiples of common item sizes) are favored.
    let pr = post_residual;
    let mut harmonic_bonus = 0.0;
    for m in [10u32, 20, 25, 50].iter() {
        if pr >= *m && pr % m == 0 {
            harmonic_bonus += 6.0;
        }
    }
    // Residuals in awkward dead zones (1..=9) are heavily penalized.
    if pr > 0 && pr < 10 {
        score += 18.0;
    }
    score -= harmonic_bonus;

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size <= pr {
            // next item fits: residual after next placement matters
            let pr2 = pr - next_item_size;
            score -= 10.0;
            if pr2 < 10 { score += 8.0; }
        } else {
            // next item won't fit here: penalize leaving a large unusable residual
            score += 0.15 * pr as f64;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: neutral-ish, penalized when many open bins exist
    if bin_residual == bin_capacity {
        score += 20.0 + 2.0 * open_bins_count as f64;
        // but if current fit is very poor, opening a new bin is reasonable
        if item_size > 60 && bin_residual < bin_capacity {
            score -= 0.0;
        }
    }

    // Stream progression: early on, be more willing to open bins (explore);
    // later, pack tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 5.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Coupling with mean residual: if this bin is much emptier than average,
    // prefer filling it (balance residuals).
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Integer-division threshold on item_size: large items prefer small residuals
    if item_size / 10 >= 6 && post_residual < 10 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small leftover gaps (< 10, minimum item size) are unusable.
    if post_residual < 10 {
        score += 60.0; // strongly discourage leaving a sliver
    } else if post_residual <= 20 {
        // Medium-small gaps: usable but risky; penalize proportionally.
        score += (20.0 - post_residual as f64) * 2.5;
    } else {
        // Larger gaps: mild reward for keeping flexible space, scaled by tightness.
        score -= (post_residual as f64 - 20.0).min(60.0) * 0.15;
    }

    // Tight-fit reward: exact or near-exact fills are excellent.
    if post_residual == 0 {
        score -= 40.0;
    } else if item_size > 0 && post_residual <= 5 {
        score -= 15.0;
    }

    // Last-chance pressure: if this is the only fitting bin, prefer using it
    // to avoid opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
        if post_residual <= 20 {
            score -= 8.0;
        }
    }

    // Open-bin pressure: discourage opening new bins when few bins are open
    // relative to stream progress; encourage consolidation early.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let bin_pressure = (open_bins_count as f64).ln().max(1.0);
    score += bin_pressure * 2.0 * (1.0 - 0.3 * progress);

    // Lookahead coupling: if the next item can reuse this bin's post_residual,
    // reward the placement; otherwise penalize slightly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
        } else {
            score += 3.0;
        }
    }

    // Mean-residual alignment: prefer bins whose residual is near the mean
    // (keeps the bin population homogeneous and reusable).
    score += (bin_residual as f64 - mean_residual).abs() * 0.05;

    // New-bin candidate handling: a fresh empty bin has bin_residual == bin_capacity.
    // Only make it attractive when the item is large relative to typical residuals
    // or the fit into open bins would be very poor.
    if bin_residual == bin_capacity {
        // Baseline handicap so existing bins with decent fits win.
        score += 25.0;
        // Large items benefit from a fresh bin (avoid fragmenting open bins).
        if item_size >= 70 {
            score -= 30.0;
        } else if item_size >= 50 {
            score -= 10.0;
        }
        // If many bins are open and mean residual is low, consolidation is preferred.
        if mean_residual > item_size as f64 * 1.5 {
            score += 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual equals next item size -> strong reward.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 20.0 * (1.0 - diff / cap);
        // Exact match bonus
        if post_residual == next_item_size {
            score -= 15.0;
        }
        // post_residual too small for next item: dead-space penalty scaled by waste
        if post_residual < next_item_size {
            score += 0.5 * post_residual as f64;
        }
    } else {
        // Last item: prefer tightest fit
        score -= 10.0;
    }

    // Relative to mean residual: bins with more room than average are attractive.
    score -= 0.3 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin mildly, more when a good fit exists elsewhere.
    if bin_residual == bin_capacity {
        score += 30.0 + 0.4 * item_size as f64;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 20.0; // pairing next item in a fresh bin is fine
        }
    }

    // Late-stream tightening: as stream progresses, demand tighter fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64 / cap) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress ratio and its dynamic weighting.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Is this the brand-new empty bin candidate?
    let is_new_bin = bin_residual == bin_capacity;

    // Dead-space penalty: residual that is too small to be useful later.
    // Small post_residuals (< 10, minimum item size) are pure waste.
    if post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 3.0;
    }

    // Tight fit reward: prefer bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill_ratio * fill_ratio;

    // Perfect fit: item exactly fills the bin.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead coupling: if the next item can use the post_residual exactly,
    // strongly reward this placement; if it cannot use it at all, penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size > post_residual {
            score += (next_item_size - post_residual) as f64 * 0.35;
        } else {
            // next item fits, but leftover chaining quality
            score -= (post_residual - next_item_size) as f64 * 0.15;
        }
    }

    // Last-chance logic: if this is the only bin that fits, avoid opening a
    // new bin unless the fit is terrible.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 20.0 + 15.0 * progress;
    }

    // Global fragmentation pressure: many open bins with high mean residual
    // suggests we should consolidate into existing bins.
    let frag = mean_residual / bin_capacity as f64;
    if !is_new_bin {
        score -= 12.0 * frag;
    } else {
        score += 8.0 * frag;
    }

    // New-bin candidate scoring: base cost of opening a bin, discounted
    // late in the stream (opening bins early is fine, late wastes capacity).
    if is_new_bin {
        let base_cost = 55.0 + 45.0 * progress;
        // If no open bin fits well (post_residual would be large elsewhere),
        // opening a fresh bin is attractive; approximate via mean residual gap.
        let gap = (mean_residual - item_size as f64).abs();
        score = base_cost + gap * 0.3 - (bin_capacity - item_size) as f64 * 0.25;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 30.0; // fresh bin can absorb next item too
        }
        if fitting_bins_count == 0 {
            score -= 50.0; // no alternative anyway
        }
    }

    // Slight bias toward using fewer, fuller bins as the stream matures.
    score += 0.02 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: penalize leftover space, but non-linearly (dead space matters more when small)
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth polynomial coupling with stream progress:
    // early on, keep bins flexible (higher residual OK); late, pack tightly.
    let flex = 1.0 - progress * progress;
    score += flex * (pr * pr / cap) * 0.5;

    // Last-chance bonus: strongly reward using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * (1.0 - norm_pr);
    }

    // Lookahead: reward if next item fits the post-residual
    if next_item_size > 0 {
        if (post_residual as u64) >= (next_item_size as u64) {
            score -= 10.0 + 0.2 * next_item_size as f64;
        } else {
            // penalize residuals that waste space relative to next item
            let waste = pr - next_item_size as f64;
            score += 0.3 * waste.max(0.0);
        }
    }

    // Prefer bins tighter than the mean residual (good fits), smooth coupling
    let dev = mean_residual - bin_residual as f64;
    score += 0.15 * dev * (1.0 + progress);

    // Slight preference to reuse existing bins over opening new ones,
    // stronger as the stream progresses.
    if bin_residual == bin_capacity {
        score += 12.0 + 20.0 * progress;
    } else {
        score -= 2.0 * (1.0 - progress);
    }

    // Mild penalty for many open bins early (encourage consolidation)
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // Perfect fit reward
    if post_residual == 0 {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Harmonic class of post_residual: dead space in "hard to fill" classes is worse
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap;

    // Penalize residuals in awkward bands (e.g., 51..=60 leaves little room for medium items)
    let band = post_residual / 10;
    let band_penalty = match band {
        0 => 0.0,
        1 => 5.0,
        2 => 0.0,
        3 => 10.0,
        4 => 0.0,
        5 => 15.0,
        6 => 0.0,
        7 => 10.0,
        8 => 5.0,
        _ => 0.0,
    };
    score += band_penalty;

    // Modulo-4 harmonic class: residuals divisible by small powers favor future pairings
    if post_residual % 4 == 0 {
        score -= 10.0;
    }
    if post_residual % 10 == 0 {
        score -= 8.0;
    }

    // Lookahead coupling: does the next item fit the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 25.0;
        } else if next_item_size == post_residual {
            score -= 60.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin fit is bad
    if bin_residual == bin_capacity {
        // base cost of a fresh bin
        score += 90.0;
        // cheaper to open a new bin early in the stream (more future to amortize)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 40.0 * (1.0 - progress);
        // if item is large, fresh bin keeps big residual usable
        if item_size > bin_capacity / 2 {
            score -= 20.0;
        }
    }

    // Mild preference for bins with below-mean residual (compact usage)
    score += 0.15 * (mean_residual - bin_residual as f64).max(0.0);

    // Fractional coupling: penalize leaving residual in (0, 10) range more strongly
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for typical items
    // are "dead space". Penalize post_residual in the danger zone heavily.
    let gap = post_residual as f64;
    if gap > 0.0 {
        // Dead zone: gaps below the smallest plausible item become expensive.
        if gap < 10.0 {
            score += 120.0 * (10.0 - gap) / 10.0;
        }
        // Mid-size gaps that fit nothing common (e.g. 61..69 style holes)
        score += 0.6 * (gap * (1.0 - gap / 100.0)).ln().abs().min(4.0);
    } else {
        // Perfect fit: strong reward.
        score -= 150.0;
    }

    // Reward tight fits generally (small post_residual relative to item).
    score -= 2.0 * (item_size as f64) / (bin_residual as f64).max(1.0);

    // Open-bin pressure: discourage spreading when many bins are open,
    // but encourage using existing bins when few are open.
    score += 1.5 * (open_bins_count as f64).ln().max(0.0);

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count <= 1 {
        score -= 80.0;
    }

    // New-bin candidate handling: an empty bin has huge residual; make it
    // attractive only when current bin would leave a bad gap or no bins fit well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Baseline cost of opening a new bin, softened by stream position
        // and by how bad the alternative fits are.
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        let mut new_bin_score = 60.0 + 20.0 * progress;
        // If next item is large, a fresh bin is valuable.
        if next_item_size > 0 && (next_item_size as f64) > mean_residual {
            new_bin_score -= 40.0;
        }
        // If many bins are open with wasted space, avoid opening more.
        new_bin_score += 0.8 * (mean_residual - gap).max(0.0);
        score = new_bin_score;
    } else {
        // Lookahead: if next item fits in the post residual, reward this placement.
        if next_item_size > 0 && (next_item_size as u32) <= post_residual {
            score -= 25.0;
        } else if next_item_size > 0 && (next_item_size as u32) > post_residual {
            score += 8.0;
        }
        // Mild bonus for placing into bins below mean residual (balance keeping).
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead: post_residual exactly matches next item -> strong reward
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 * (1.0 - diff / bin_capacity as f64).max(0.0);
        // post_residual can hold next item exactly or leave near-zero waste afterwards
        if post_residual as i64 == next_item_size as i64 {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            score -= 5.0 * (next_item_size as f64 / bin_capacity as f64);
        }
    }

    // Reward tight fits: small post_residual relative to capacity
    score -= 20.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Penalize dead space: residual too small for any plausible item (min size 1)
    if post_residual < 10 {
        score += 8.0;
    }

    // Last chance bin: strongly favor to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Relative to mean residual: prefer bins that are already "committed" (below mean residual)
    score -= 0.5 * (mean_residual - post_residual as f64);

    // New-bin candidate: penalize slightly so we prefer reusing unless lookahead is bad
    if bin_residual == bin_capacity {
        score += 12.0;
        // But if no lookahead match exists anywhere, new bin is fine; soften with stream position
        score -= 6.0 * (step_index as f64 / total_items.max(1) as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize dead space that cannot fit the next item (lookahead waste)
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 1.5;
    }

    // Reward perfect or near-perfect fits
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Last-chance bonus: only one fitting bin, avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // Reward using tight residual space relative to mean residual
    let tightness = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score -= tightness * 8.0;

    // Penalize wasting a large empty bin on a small item early in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fill_ratio = item_size as f64 / bin_residual as f64;
    if fill_ratio < 0.4 && progress < 0.5 {
        score += (0.4 - fill_ratio) * 30.0 * (1.0 - progress);
    }

    // New-bin candidate handling: prefer new bin only when the item fits badly everywhere
    if bin_residual == bin_capacity {
        let waste = (bin_capacity - item_size) as f64;
        // Base cost of opening a new bin
        score = waste * 0.8;
        // If this is a last resort (no other fitting bins) or the fit is excellent, encourage new bin
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        if item_size >= bin_capacity * 8 / 10 {
            score -= 25.0;
        }
        // Early in stream, opening fresh bins is cheaper; late, prefer filling existing ones
        score += (1.0 - progress) * 10.0;
        // Many open bins with slack: discourage opening yet another
        if mean_residual > 30.0 && open_bins_count > 2 {
            score += 15.0;
        }
        // Lookahead: if next item is small, a fresh big bin is useful
        if next_item_size > 0 && next_item_size <= post_residual as u32 {
            score -= 12.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let r = post_residual as f64;
    let cap = bin_capacity as f64;
    let rn = r / cap;
    let fit = if fitting_bins_count > 0 { fitting_bins_count as f64 } else { 1.0 };

    // Base: prefer small post residual, with non-linear polynomial coupling
    let mut score = r * (1.0 + 0.8 * rn * rn);

    // Stream-progress coupling: as stream advances, tighten residual preference
    score *= 1.0 + 0.5 * progress * (1.0 - rn) * (1.0 - rn);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    } else {
        score += 2.0 * (fit - 1.0).ln().max(0.0);
    }

    // Penalty for leaving residual too small to be useful (dead space)
    let dead = (cap * 0.2 - r).max(0.0) / cap;
    score += 40.0 * dead * dead;

    // Lookahead: reward if next item fits the post-residual
    if next_item_size > 0 && (next_item_size as f64) <= r {
        score -= 6.0 * (1.0 - (next_item_size as f64 / r.max(1.0)).abs());
    }

    // Slight preference to keep mean residual balanced
    score += 0.05 * (mean_residual - r).abs();

    // New-bin candidate: mild penalty so it's only chosen when open bins fit poorly
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: multiples of 10 are "harmonic" slots
    // (many item sizes in 1..100 can reuse them), odd/tiny remainders are dead space.
    let cls = post_residual % 10;
    if post_residual > 0 {
        score += match cls {
            0 => -6.0,                     // perfectly harmonic leftover
            1..=3 => 14.0,                 // near-dead space
            4..=6 => 6.0,
            _ => 0.0,
        };
    } else {
        score -= 12.0;                     // exact fill is ideal
    }

    // Integer-division thresholds on post_residual
    let q = post_residual / 25;            // 0..4 quarter classes
    score += match q {
        0 => 10.0,                          // <25 left: mostly unusable
        1 => 2.0,
        2 => -1.0,
        _ => -3.0,
    };

    // Coupling with lookahead: reward bins whose leftover harmonically matches
    // the next item (next fits with small remainder), penalize mismatch.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) >= nxt {
            let gap = post_residual as f64 - nxt;
            score -= 4.0 * (1.0 - gap / cap);      // tight lookahead fit rewarded
            if (post_residual as u32) % next_item_size == 0 {
                score -= 5.0;                       // exact harmonic division
            }
        } else {
            score += 8.0;                           // next item won't fit here
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate (residual == capacity): only attractive when the item is
    // large (small post_residual) or current bins are badly fragmented.
    if bin_residual == bin_capacity {
        let frag = (mean_residual - post_residual as f64).max(0.0);
        score += 20.0 - 0.25 * post_residual as f64 + 0.05 * frag;
    }

    // Mild preference to consolidate into few bins as the stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.02 * open_bins_count as f64 * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the minimum item (1)
    // are pure waste; but residuals in the "hard to fill" band (1..=20) should
    // be strongly penalized since few future items fit them.
    if post_residual > 0 && post_residual < 20 {
        score += (20 - post_residual) as f64 * 3.0;
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward residuals that exactly match the lookahead item (chain packing).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }
    // Penalize if lookahead item cannot fit here (forces another bin for it).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += next_item_size as f64 * 0.5;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Open-bin pressure: many open bins -> prefer filling existing ones,
    // penalize opening new bins.
    if bin_residual == bin_capacity {
        score += 30.0 + 5.0 * open_bins_count as f64;
    } else {
        score -= 2.0 * open_bins_count as f64;
    }

    // Prefer bins tighter than the mean residual (well-packed bins first).
    let residual_f = bin_residual as f64;
    if residual_f < mean_residual {
        score -= (mean_residual - residual_f) * 0.5;
    } else {
        score += (residual_f - mean_residual) * 0.25;
    }

    // Early in stream: allow more aggressive bin creation for flexibility.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= (1.0 - progress) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: residual zero is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 800.0;
        } else if post_residual >= next_item_size {
            // Next item fits: reward proportionally to how snugly it fits.
            let slack = (post_residual - next_item_size) as f64;
            score -= 300.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item does NOT fit into this bin afterwards: penalize
            // proportionally to how much of next item is left stranded.
            let stranded = (next_item_size - post_residual) as f64;
            score += 4.0 * stranded;
        }

        // Two-item exact match: item + next fills the bin completely.
        if item_size + next_item_size == bin_residual {
            score -= 600.0;
        }
    }

    // Relative residual vs mean residual: prefer bins tighter than average.
    score += 1.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: if this is the only bin that fits, strongly favor it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate: penalize opening a new bin unless post_residual
    // would be nearly full capacity (i.e., item is huge).
    if bin_residual == bin_capacity {
        score += 120.0;
        // But allow new bin for very large items that would leave tiny residuals elsewhere.
        if item_size >= 80 {
            score -= 200.0;
        }
        // Early in stream, new bins are cheap; later, avoid fragmentation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 100.0 * progress;
    }

    // Penalize large dead space that only tiny items could use.
    if post_residual > 0 && post_residual < 10 {
        score -= 150.0; // near-perfect fit even if not exact zero
    }

    // Mild penalty for wasting space in bins with already small residuals.
    if (post_residual as f64) < mean_residual * 0.5 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 45.0 * tightness * tightness;

    // Penalize dead space: post_residual too small for the smallest possible future item
    if post_residual < 10 {
        score += 12.0; // nearly full bin, fine
    } else if post_residual < 20 {
        score += 6.0; // small dead zone
    }

    // Lookahead: if next item fits exactly in post_residual, big bonus
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
        let slack = (post_residual - next_item_size) as f64;
        score -= 6.0 * (1.0 - slack / (bin_capacity as f64));
    } else if next_item_size > post_residual {
        // next item won't fit here; slightly penalize leaving unusable-for-next space
        score += 3.0;
    }

    // Last chance: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // with many options, prefer the tightest (already rewarded), mild extra pressure
        score += (fitting_bins_count as f64).ln() * 2.0;
    }

    // New-bin candidate handling: empty bin gets residual == capacity (post_residual == capacity)
    if bin_residual == bin_capacity {
        // Opening a new bin is discouraged unless current bins have poor fit potential.
        // Reward opening when open bins are mostly full (low mean residual) or few options.
        let mean_r = mean_residual;
        let openness = mean_r / (bin_capacity as f64);
        // penalty scales with how much room open bins still have
        score += 30.0 * openness;
        // early in the stream, be more willing to open bins to build diversity
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - progress);
        // if many bins can fit, opening a new one is wasteful
        if fitting_bins_count > 1 {
            score += 20.0;
        }
        // exact-fit item into new bin is bad unless item is large
        score += 0.1 * (bin_capacity - item_size) as f64;
    }

    // Prefer filling bins that are already relatively full (consolidation)
    let fill = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
    score -= 10.0 * fill;

    // Mild penalty on score magnitude of post_residual dominance; keep post_residual as base signal
    score += 0.05 * (post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let x = pr / cap; // normalized post residual

    // Smooth polynomial base: reward tight fits (low post residual) with curvature
    let mut score = 40.0 * x * x - 20.0 * x * x * x + pr * 0.15;

    // Non-linear coupling of fit quality with stream progress:
    // early on, keep bins flexible; later, prefer tight packing more aggressively
    let tightness = 1.0 - x;
    score -= 30.0 * tightness * tightness * (progress * progress);

    // Penalize bins whose residual deviates from mean residual (non-linearly)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 12.0 * dev * dev;

    // Last-chance bonus when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 20.0 * tightness;
    }

    // Lookahead: reward leaving room for the next item, smoothly
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let slack = (pr - ns) / cap;
        if slack >= 0.0 {
            score -= 10.0 * (1.0 - slack) * (1.0 - slack);
        } else {
            score += 8.0 * slack * slack * 100.0;
        }
    }

    // Mild penalty for proliferation of open bins
    score += 0.05 * (open_bins_count as f64).ln().max(0.0);

    // New-bin candidate: penalize opening a new bin unless post residual is large
    if bin_residual == bin_capacity {
        score += 25.0 - 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the resulting residual: residues divisible by common
    // small item sizes (10, 20, 25, 50) are more reusable -> reward them.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fill
    } else if pr % 10 == 0 {
        score -= 25.0;
    } else if pr % 25 == 0 {
        score -= 20.0;
    } else if pr % 5 == 0 {
        score -= 10.0;
    } else {
        score += 8.0; // awkward residue
    }

    // Dead-space threshold: residual too small for the smallest plausible item.
    if pr > 0 && pr < 10 {
        score += 45.0;
    }

    // Tight-fit reward: item occupies most of the bin.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Lookahead coupling: does post_residual still admit the next item?
    if next_item_size > 0 {
        if pr >= next_item_size {
            score -= 12.0;
        } else {
            score += 18.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when open bins are crowded / poor fits.
    if bin_residual == bin_capacity {
        let crowd = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
        score -= 15.0 * crowd;
        if next_item_size > 0 && next_item_size > pr && pr < item_size {
            score -= 10.0; // new bin preserves room for big next item
        }
        if fitting_bins_count > 0 {
            score += 20.0; // discourage opening when a bin already fits
        }
    }

    // Mild stream-progression pressure to consolidate early.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * progress * (mean_residual / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps after placement.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 6.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Penalize leaving a gap that the next item cannot use.
    if next_item_size > 0 {
        if post_residual < next_item_size && post_residual > 0 {
            score += 8.0;
        } else if post_residual >= next_item_size {
            score -= 5.0;
        }
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // over opening new bins; make the empty-bin candidate less attractive.
    let pressure = open_bins_count as f64 * 0.35;
    if bin_residual == bin_capacity {
        score += 12.0 + pressure;
    } else {
        score -= pressure;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid forcing a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Mean residual coupling: bins far below the mean residual are "fresher";
    // prefer placing into bins with residuals near or above the mean.
    if (bin_residual as f64) < mean_residual {
        score += 2.0;
    } else {
        score -= 2.0;
    }

    // Late-stream tightening: as the stream progresses, be more conservative
    // about waste since fewer future items remain to fill gaps.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Lookahead: reward exact/near-exact match between post_residual and next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect fit for the next item is extremely desirable.
        if post_residual == next_item_size {
            score -= 60.0;
        } else {
            // Penalize proportionally to how badly the next item would NOT fit here.
            score += gap * 0.35;
            // If the next item cannot fit into post_residual, this creates dead space
            // unless post_residual is tiny (nearly full bin is fine).
            if next_item_size > post_residual {
                let waste = post_residual as f64;
                // Small leftover (< 10) is acceptable; larger unusable leftovers are bad.
                if waste > 10.0 {
                    score += (waste - 10.0) * 0.8;
                } else {
                    score -= 15.0; // near-tight packing, good
                }
            }
        }
    } else {
        // Last item: just pack as tightly as possible.
        score -= 10.0;
    }

    // Compare against mean residual: placing into a bin whose residual is far below
    // the mean (i.e., a tight bin) is efficient; bins with large residual relative
    // to mean should be slightly deprioritized to keep big holes for big items.
    let res = post_residual as f64;
    if mean_residual > 0.0 {
        let rel = res / mean_residual;
        if rel < 0.5 {
            score -= 8.0 * (0.5 - rel); // tighter than average: good
        } else if rel > 1.5 {
            score += 6.0 * (rel - 1.5); // much looser than average: mild penalty
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Only attractive when the current item is large relative to capacity or when
    // no open bin fits well; otherwise penalize opening new bins.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin while others exist.
        if open_bins_count > 0 {
            score += 30.0 + 10.0 * open_bins_count as f64;
            // Late in the stream, be more conservative about new bins.
            score += 20.0 * progress;
        }
        // Large items justify fresh bins.
        if item_size > bin_capacity / 2 {
            score -= 35.0;
        }
        // If the lookahead item is also large, a fresh bin gives a clean 2-item pairing.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity && item_size + next_item_size > bin_capacity * 3 / 4 {
            score -= 20.0;
        }
        // If no other bin can fit (fitting_bins_count counts this candidate too),
        // reduce the penalty so a new bin gets opened.
        if fitting_bins_count <= 1 {
            score -= 40.0;
        }
    } else {
        // Reward filling existing bins tightly: low post_residual is good, but
        // avoid creating tiny unusable slivers (1..=3) early when many bins are open.
        if post_residual >= 1 && post_residual <= 3 && open_bins_count > 3 && progress < 0.7 {
            score += 5.0;
        }
        // Perfect closure of a bin.
        if post_residual == 0 {
            score -= 50.0;
        }
    }

    // Mild global pressure to consolidate: more open bins -> prefer filling them.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Primary driver: reward tight fits (small waste relative to capacity)
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * waste_frac * waste_frac;

    // Lookahead: if the next item fits exactly in the post-residual, strongly reward
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Penalize leaving a residual too small for the lookahead item (dead space)
        score += 8.0 * (1.0 - post_residual as f64 / next_item_size.max(1) as f64);
    }

    // Last-chance bin: if this is the only bin that fits, heavily favor using it
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else {
        // Mild penalty when many bins compete, encouraging spread of large residuals
        score += 1.5 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // New-bin candidate handling: opening a new bin should be rare, only when
    // the item fits poorly everywhere else (large post_residual waste avoided elsewhere)
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        let mut new_bin_cost = 18.0;
        // Early in the stream, opening bins is cheaper (build flexibility)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        new_bin_cost -= 10.0 * (1.0 - progress);
        // If few open bins, cheaper to open another
        new_bin_cost -= 2.0 * (open_bins_count as f64).ln().max(0.0).min(3.0);
        // If the mean residual of open bins is too small to hold the item, new bin is good
        if (mean_residual as u32 as u32) < item_size {
            new_bin_cost -= 20.0;
        }
        // If the lookahead item would fit the fresh residual exactly, bonus
        if next_item_size > 0 && next_item_size <= post_residual {
            new_bin_cost -= 6.0;
        }
        score += new_bin_cost;
    }

    // Penalize creating tiny unusable residuals (< 10, minimum item size)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Reward perfect fits
    if post_residual == 0 {
        score -= 40.0;
    }

    // Global state coupling: when open bins have large mean residual, prefer
    // filling them rather than fragmenting
    if bin_residual != bin_capacity {
        score -= 3.0 * (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let size_norm = item_size as f64 / cap;

    // Base: post-residual, with smooth polynomial coupling to stream progress.
    let mut score = pr * (1.0 + 0.5 * progress * progress) - 0.3 * pr * (1.0 - progress);

    // Non-linear penalty on small dead space (wasted capacity), amplified late in stream.
    let dead = norm_pr * (1.0 - norm_pr);
    score += 40.0 * (1.0 - dead) * (0.5 + progress);

    // Reward tight fits: polynomial in size_norm.
    score -= 25.0 * size_norm * size_norm * (1.0 + progress);

    // Last-chance bin bonus (smooth via fitting count).
    let last_chance = if fitting_bins_count <= 1 { 1.0 } else { 1.0 / fitting_bins_count as f64 };
    score -= 15.0 * last_chance;

    // Lookahead: if next item fits post-residual, reward this bin.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        let nxt = next_item_size as f64 / cap;
        score -= 20.0 * nxt * (1.0 - progress);
    } else if next_item_size > 0 {
        score += 10.0 * (1.0 - progress);
    }

    // Penalize bins far from mean residual (imbalance), smooth quadratic.
    let dev = pr - mean_residual;
    score += 0.05 * dev * dev / cap;

    // Mild penalty for too many open bins.
    score += 2.0 * (open_bins_count as f64).ln().max(0.0) * progress;

    // New-bin candidate: neutral-ish baseline, penalized unless current bins are poor fits.
    if bin_residual == bin_capacity {
        score += 30.0 - 20.0 * size_norm - 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space in "wasted" bands gets penalized.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Classify post_residual into harmonic bands of capacity/4.
    let quarter = bin_capacity / 4;
    let band = post_residual / quarter; // 0..=4
    match band {
        0 => { score -= 6.0; }               // tiny dead space: excellent fit
        1 => { score += 2.0; }               // quarter leftover: mildly bad
        2 => { score -= 1.0; }               // half leftover: reusable
        3 => { score += 3.0; }               // three-quarter leftover: awkward
        _ => { score -= 0.5; }               // near-empty bin: fine
    }

    // Modulo-10 harmonic class: post_residuals divisible by 10 pair well with
    // common item sizes; reward them.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 2.5;
    }

    // Exact fill is perfect.
    if post_residual == 0 {
        score -= 20.0;
    }

    // Lookahead coupling: if the next item fits the post_residual, reward strongly.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
        // Extra reward when post_residual - next_item is a harmonic class value.
        let after = post_residual - next_item_size;
        if after % 10 == 0 {
            score -= 4.0;
        }
        if after < quarter {
            score -= 3.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here; penalize leaving this bin stranded.
        score += 4.0;
        if post_residual < 10 {
            score += 3.0; // dead space smaller than min item size
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // New-bin candidate handling: it should only win when open bins are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, discounted early in the stream
        // and when few bins are open.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 30.0 + 20.0 * (1.0 - progress) + 2.0 * open_bins_count as f64;
        // If the next item is large, a fresh bin is more attractive.
        if next_item_size > 50 {
            score -= 10.0;
        }
        // If many bins are open with high mean residual, opening new bins is wasteful.
        if mean_residual > 40.0 {
            score += 15.0;
        }
    } else {
        // Slight preference for tighter bins among open ones.
        score += (bin_residual as f64 - mean_residual) * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the minimum plausible
    // future item are worthless; penalize them heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward bins that can also host the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space that even the next item can't use.
        score += 8.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, encourage
    // filling existing ones; few open bins -> allow new bins more readily.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64) / (8.0 + 4.0 * progress);
    score += pressure * 3.0;

    // Prefer bins tighter than the mean residual (best-fit flavor).
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 0.0 } else { 15.0 };
        score += desperation + 5.0 + pressure * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    score = post_residual as f64 * 1.0;

    // Aggressive 2-step lookahead: reward bins whose post_residual exactly or nearly
    // matches the next item size (perfect chain placement).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual == next_item_size {
            score -= 40.0; // exact chain: post_residual consumed fully next step
        } else if post_residual >= next_item_size {
            score -= 12.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item can't fit here; dead space penalty grows with gap
            score += 0.25 * gap;
        }
    }

    // Compare post_residual against mean residual: avoid creating outliers
    // far below the mean (isolated unusable slivers) unless it closes the bin.
    let pr = post_residual as f64;
    if pr < mean_residual * 0.5 && pr > 0.0 {
        score += 6.0;
    } else if pr > mean_residual {
        score -= 2.0;
    }

    // Perfect closure bonus: bin fully consumed.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoids bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; reduced late in the stream is irrelevant,
        // so keep it constant but modulated by how tight existing fits would be.
        let mut new_bin_score = 55.0;
        if next_item_size > 0 {
            // A fresh bin gives full flexibility for the next item too.
            new_bin_score -= 3.0 * (next_item_size as f64 / bin_capacity as f64);
        }
        // If many bins already fit the item, opening a new one is wasteful.
        if fitting_bins_count > 2 {
            new_bin_score += 10.0 * (fitting_bins_count as f64 - 2.0).min(5.0);
        }
        // Early in stream, opening bins is cheaper (build parallel capacity).
        let progress = step_index as f64 / total_items.max(1) as f64;
        new_bin_score -= 8.0 * (1.0 - progress);
        score = score.max(new_bin_score);
        return score;
    }

    // Slight preference for bins with larger residuals among equal fits
    // (keeps small slivers for small future items).
    score -= 0.05 * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Primary fit quality: reward tight packing (small post_residual) non-linearly.
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += tightness * tightness * 60.0;

    // Lookahead: if the next item fits into the post residual, strongly reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack_after_next = post_residual - next_item_size;
        score -= 25.0 - (slack_after_next as f64) * 0.3;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < 10 {
        // Dead space too small for typical items: penalize.
        score += 12.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only open a new bin when the item is large
    // relative to residuals of open bins, or early in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let item_frac = item_size as f64 / bin_capacity as f64;
        // Prefer new bin for big items or when mean residual is too small to be useful.
        let mean_useful = mean_residual - item_size as f64;
        if item_frac > 0.6 || mean_useful < 5.0 {
            score -= 20.0 + 15.0 * (1.0 - progress);
        } else {
            // Late stream: discourage proliferation of open bins.
            score += 10.0 + (open_bins_count as f64) * 0.5;
        }
    }

    // Global state coupling: many open bins with high mean residual -> prefer
    // bins below the mean residual (consolidate waste into fuller bins).
    if bin_residual < bin_capacity {
        let dev = (bin_residual as f64 - mean_residual) / (bin_capacity as f64);
        score += dev * 20.0;
    }

    // Mild time-horizon shaping: early stream, be more exploratory (favor
    // spreading); late stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 8.0 * (bin_capacity - bin_residual) as f64 / bin_capacity as f64;

    // Exact fit celebration.
    if post_residual == 0 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: tight fits favored, with smooth non-linear shaping of residual
    let mut score = pr.powf(1.35);

    // Progress coupling: later in the stream, tolerate residual less (penalize waste more)
    let waste_penalty = norm_pr * norm_pr * (0.5 + 2.0 * progress);
    score += 40.0 * waste_penalty;

    // Reward near-perfect fits with a smooth bump around small residuals
    let tightness = (-norm_pr * 6.0).exp();
    score -= 25.0 * tightness * (0.6 + 0.4 * progress);

    // Lookahead: bonus if next item fits into post_residual (smooth logistic-like)
    if next_item_size > 0 {
        let fits_next = if (next_item_size as f64) <= pr { 1.0 } else { 0.0 };
        let margin = pr - next_item_size as f64;
        let smooth = 1.0 / (1.0 + (-margin / 15.0).exp());
        score -= 18.0 * fits_next * smooth;
    } else {
        // Last item: strongly prefer filling a bin as fully as possible
        score -= 30.0 * (1.0 - norm_pr);
    }

    // Last-chance bin: avoid opening new bins when this is the only fitting bin
    if fitting_bins_count <= 1 {
        score -= 22.0 * (1.0 - progress);
    }

    // Mild penalty for scattering across many open bins relative to mean residual
    score += 0.05 * (open_bins_count as f64).ln().max(0.0) * (mean_residual - pr).abs().sqrt();

    // New-bin candidate: keep neutral-ish, only attractive when fits are bad
    if bin_residual == bin_capacity {
        score = 60.0 + 80.0 * progress - 0.3 * mean_residual;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: which "modular band" does post_residual fall in?
    // Small leftovers (< 10) are dead space for items sized >= 10 in classic streams,
    // but items can be as small as 1 here, so weight by absolute leftover quality.
    let post = post_residual as f64;

    // Class A: perfect fit -> strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Class B: tiny leftover (<= 10): nearly dead space -> penalize proportionally.
    if post_residual > 0 && post_residual <= 10 {
        score += (11 - post_residual) as f64 * 8.0;
    }

    // Harmonic residue classes of post_residual mod 10: leftovers in
    // [11..30] can host small items; classes divisible by 5 are friendlier.
    let r = post_residual % 10;
    if post_residual > 10 {
        match r {
            0 => score -= 6.0,           // round leftover, reusable
            5 => score -= 3.0,           // half-friendly
            1 | 9 => score += 2.0,       // awkward slivers
            _ => {}
        }
    }

    // Integer-division threshold: leftover big enough for half a bin is valuable.
    if post_residual >= bin_capacity / 2 {
        score -= 12.0;
    } else if post_residual >= bin_capacity / 4 {
        score -= 5.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size < post_residual {
            // next item leaves another awkward sliver? mild penalty
            let next_post = post_residual - next_item_size;
            if next_post <= 3 && next_post > 0 {
                score += 4.0;
            } else {
                score -= (post_residual - next_item_size) as f64 * 0.15;
            }
        } else {
            // next item cannot fit here: leftover should be as large as possible
            score += 3.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: opening a new bin is only attractive when existing bins
    // are crowded (low mean residual) or this item is huge.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowding = 1.0 - (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        // Base cost of a fresh bin, discounted when stream is early or bins are crowded.
        score = post + 55.0 - 25.0 * crowding - 15.0 * (1.0 - progress);
        if item_size >= 60 {
            score -= 8.0; // huge items fit anywhere in a fresh bin
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 5.0; // fresh bin can host the pair
        }
    }

    // Mild global pressure: prefer tighter bins when many bins are open.
    score -= (open_bins_count as f64).ln().max(0.0) * (1.0 - post / bin_capacity as f64) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (1.0 - post_residual as f64 / 10.0);
    }
    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward bins that can also host the lookahead item (k=2 lookahead chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + next_item_size as f64 * 0.2;
    } else if next_item_size > 0 && next_item_size >= item_size {
        // Penalize creating a gap that blocks a larger upcoming item.
        score += 15.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: mildly discourage spreading across many bins.
    score += open_bins_count as f64 * 0.6;

    // Mean residual coupling: prefer bins tighter than the mean.
    score += (mean_residual - bin_residual as f64) * 0.4;

    // New-bin candidate: only attractive when no open bin fits well
    // (fresh bin keeps full flexibility; make it slightly worse than a decent fit).
    if bin_residual == bin_capacity {
        score += 8.0;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: perfect match with next item is extremely valuable.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Next item exactly fills this bin afterwards -> near-perfect chain.
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item can also go here: residual wasted across two placements.
            let two_step_waste = (post_residual - next_item_size) as f64;
            score -= 25.0 - two_step_waste * 0.35;
        } else {
            // Next item cannot fit here; leftover is a harder dead-space candidate.
            let dead = (post_residual as f64) / (next_item_size as f64);
            score += 10.0 * (1.0 - dead.min(1.0));
        }
    } else {
        // Last item: prefer fullest packing.
        score -= 8.0;
    }

    // Penalize small unusable post-residuals (dead space below typical min item).
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when no good fit exists among open bins
    // (i.e., this item would leave a lot of residual in every fitting bin).
    if bin_residual == bin_capacity {
        let avg_penalty = (mean_residual - post_residual as f64).max(0.0);
        score += 22.0 - avg_penalty * 0.5;
        // Early in stream, opening bins is cheap; later, discourage it.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 20.0;
    }

    // Prefer tighter fits relative to the mean residual of open bins.
    score -= (mean_residual - post_residual as f64) * 0.25;

    // Mild pressure to reduce number of open bins' fragmentation.
    score += (open_bins_count as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual)
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 20.0;

    // Penalize dead space that can't fit the smallest plausible item
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: reward bins whose post residual can still fit the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += 8.0;
        }
        // Bonus if post residual exactly matches next item (perfect chain)
        if post_residual == next_item_size {
            score -= 15.0;
        }
    }

    // Time horizon: early in stream, be conservative (favor new bins less);
    // late in stream, prefer filling existing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0 * fit_ratio;

    // Global state coupling: many open bins with high mean residual -> encourage consolidation
    if open_bins_count > 2 && mean_residual > 40.0 {
        score += (mean_residual - 40.0) * 0.3;
    }

    // New-bin candidate handling: penalize opening a new bin unless current item
    // is large and no open bin fits well
    if bin_residual == bin_capacity {
        let waste_penalty = (bin_capacity - item_size) as f64;
        score += 15.0 + waste_penalty * 0.5;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
        if item_size >= 70 {
            score -= 20.0; // large items fine in fresh bins
        }
    }

    // Mild preference for bins below mean residual (balance load)
    let diff = bin_residual as f64 - mean_residual;
    score += diff * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_post = pr / cap;
    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_post * norm_post * (1.0 - progress) + norm_post * progress * (1.0 - norm_post);
    score += 12.0 * poly;
    // Penalize large dead space late in the stream
    score += 8.0 * progress * norm_post * norm_post;
    // Reward tight fits (small post_residual) more strongly as stream advances
    score -= 6.0 * (1.0 - norm_post) * (1.0 - norm_post) * (0.5 + 0.5 * progress);
    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - progress);
    }
    // Lookahead coupling: reward residual that can host next item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            let slack = (pr - ni) / cap;
            score -= 5.0 * (1.0 - slack * slack) * (1.0 - progress);
        } else {
            score += 4.0 * (ni - pr) / cap;
        }
    }
    // Mean residual alignment
    score += 2.0 * (norm_post - mean_residual / cap).abs();
    // Mild preference for consolidating bins
    score += 0.3 * open_bins_count as f64 * norm_post;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual modulo capacity fractions
    let pr = post_residual;
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;

    // Penalize residuals that are "dead zones" (small, hard to fill)
    if pr > 0 && pr < eighth {
        score += 25.0;
    } else if pr >= eighth && pr < quarter {
        score += 8.0;
    } else if pr == 0 {
        score -= 60.0; // perfect fit
    }

    // Harmonic bonus: residual divisible by common item sizes
    if pr % 10 == 0 && pr > 0 {
        score -= 12.0;
    }
    if pr % 20 == 0 && pr > 0 {
        score -= 8.0;
    }

    // Lookahead coupling: next item fits exactly into post residual
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size < pr {
            score -= 6.0;
        } else {
            score += 10.0; // next item won't fit here anyway
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make it moderately attractive only when open bins are crowded
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowding = (mean_residual / cap) - 0.3;
        score = cap as f64 * 0.5 + crowding * 50.0 - progress * 10.0;
        if next_item_size > 0 && next_item_size >= bin_residual {
            score -= 20.0;
        }
    }

    // Mild preference for tighter bins overall
    score += (mean_residual - post_residual as f64) * 0.15;
    score -= (bin_residual - item_size) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: any leftover gap below the minimum item
    // size is essentially unusable — penalize it heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 4.0;
    }

    // Perfect fit: strongly reward complete fills.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits proportionally to how much of the bin was consumed.
    score -= (item_size as f64 / bin_capacity as f64) * 15.0;

    // Dead-space gradient: prefer bins where the leftover is a "round" usable
    // chunk (>= 10) over mid-range awkward gaps.
    if post_residual >= 10 {
        score -= 5.0;
    }

    // Last-chance pressure: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: mildly discourage spreading across many bins,
    // stronger early in the stream when consolidation matters most.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (1.5 - progress);

    // New-bin candidate handling: an empty bin should only win when the fit
    // into existing bins would leave a very awkward gap.
    if bin_residual == bin_capacity {
        score += 30.0;
        if post_residual >= 10 && post_residual <= 50 {
            score -= 20.0; // a fresh bin leaving a large usable gap is fine
        }
    }

    // Lookahead: if the next item could exactly use this bin's post_residual,
    // reward keeping that gap; if next item cannot fit the gap, penalize it.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size > post_residual && post_residual > 0 {
            score += 12.0;
        }
    }

    // Prefer bins with residuals below the mean (concentrate the waste).
    score += (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly (dead-space minimization).
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 120.0;
    } else if post_residual <= 15 {
        score -= 40.0;
    }

    // 2-step lookahead: bonus if next item exactly fills the new post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 90.0;
        } else if next_item_size < post_residual {
            // next item fits here afterward: mild reward proportional to tightness
            let slack_after_next = post_residual - next_item_size;
            if slack_after_next <= 10 {
                score -= 50.0;
            } else {
                score -= 15.0;
            }
        } else {
            // next item won't fit in residual: penalize leaving large unusable gaps
            let gap = post_residual as f64;
            if gap < next_item_size as f64 {
                score += 0.5 * (next_item_size as f64 - gap);
            }
        }
    }

    // Compare residual against mean residual: prefer bins that are already loaded.
    let mean_gap = mean_residual - post_residual as f64;
    score -= 0.35 * mean_gap;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // Penalize spreading across too many open bins when mean residual is large.
    if open_bins_count > 4 && mean_residual > 40.0 {
        score += 10.0;
    }

    // New-bin candidate: make it moderately attractive only when current fits are poor.
    if bin_residual == bin_capacity {
        // base penalty so filling existing bins is preferred on tight fits
        score += 25.0;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        if post_residual as f64 >= next_item_size as f64 && next_item_size > 0 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tightness: reward near-perfect fits superlinearly.
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 6.0 * tightness * tightness * cap * 0.1;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless the fit
    // here is very tight AND open bins would leave ugly dead space.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let waste_elsewhere = (mean_residual - item_size as f64).max(0.0);
        let mut new_bin_penalty = 18.0 + 20.0 * progress;
        if fitting_bins_count > 0 {
            new_bin_penalty += 10.0;
        }
        // If the next item is large, a fresh bin is more valuable.
        if next_item_size > 0 && (next_item_size as f64) > post_residual as f64 * 0.9 {
            new_bin_penalty -= 8.0;
        }
        // A fresh bin is attractive if the item barely fits anywhere else.
        if fitting_bins_count > 0 && post_residual < 5 {
            new_bin_penalty -= 15.0;
        }
        new_bin_penalty -= waste_elsewhere * 0.3;
        score += new_bin_penalty.max(-20.0);
    }

    // Lookahead: penalize placements that leave residual too small OR too
    // awkward for the next item (dead space that nothing will fill).
    if next_item_size > 0 && post_residual > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        if nxt > post {
            // dead space: next item cannot use it
            score += 0.15 * post;
        } else {
            // next item fits: reward good chaining
            score -= 0.25 * (1.0 - (post - nxt) / cap);
        }
    }

    // Fragmentation pressure: penalize leaving small useless residuals
    // relative to the minimum item size (1..100 unknown, use 10 as soft floor).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Mild diversity pressure: when many bins are open, prefer consolidating
    // into fuller bins (higher mean residual implies scattered space).
    if open_bins_count > 4 {
        score += 0.05 * (open_bins_count as f64).ln() * (post_residual as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with non-linear penalty on unusable space
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Smooth polynomial coupling with stream progress:
    // early on, prefer filling bins tightly; late, tolerate slack less strongly
    let coupling = progress * (1.0 - progress) * 4.0; // peaks at 1 mid-stream
    score -= coupling * (cap - pr) * 0.3;

    // Dead-space penalty: small post_residual is good, but zero-ish residual wasted on tiny items is neutral
    let dead = (pr / cap).powi(3);
    score += dead * 30.0;

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).ln();
    }

    // Lookahead: if next item fits exactly in post_residual, reward
    if next_item_size > 0 && (next_item_size as f64 - pr).abs() < 1e-9 {
        score -= 15.0;
    } else if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        score -= 5.0 * (next_item_size as f64 / pr.max(1.0));
    }

    // Mild preference for keeping open bins few
    score += 0.4 * open_bins_count as f64;

    // Deviation from mean residual: prefer bins near mean (balance)
    let dev = (pr - mean_residual).abs();
    score += 0.15 * dev;

    // New-bin candidate: penalize mildly so real bins win unless fit is terrible
    if bin_residual == bin_capacity {
        score += 8.0 + 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space by capacity fractions
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let quarter = cap / 4.0;
    let tenth = cap / 10.0;

    // Dead-space penalty: leftover in (0, 10) is nearly unusable
    if pr > 0.0 && pr < tenth {
        score += 60.0 * (tenth - pr) / tenth;
    }

    // Harmonic bonus: leftover exactly divisible into useful classes (multiples of 10, 20, 25, 50)
    if pr > 0.0 {
        let mut harmonic = 0.0;
        for m in [10u32, 20, 25, 50] {
            if post_residual % m == 0 {
                harmonic += (m as f64) / 50.0;
            }
        }
        score -= 12.0 * harmonic;
    }

    // Integer-division class of post_residual by quarter bins
    let q = (post_residual / 25).min(4);
    score -= 4.0 * q as f64;

    // Lookahead coupling: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // perfect class match: next item exactly fills a harmonic class
            if post_residual % next_item_size.max(1) == 0 {
                score -= 25.0;
            } else {
                score -= 10.0;
            }
        } else {
            // next item won't fit here; penalize slightly unless post_residual is dead space anyway
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Prefer tighter bins among many options
    score -= 8.0 * (1.0 - bin_residual as f64 / cap);

    // Late in stream: prefer filling existing bins over opening new ones
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize more as stream progresses and when other bins fit
        score += 15.0 + 40.0 * progress + 10.0 * (fitting_bins_count as f64).ln().max(0.0);
    } else {
        score -= 6.0 * progress;
    }

    // Spread awareness: if mean residual is high, opening new bins is less costly
    score += 3.0 * (mean_residual / cap - 0.5);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps heavily.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 40.0; // tiny dead space is worthless
        } else if post_residual < 20 {
            score += 18.0;
        } else if post_residual < 35 {
            score += 6.0;
        }
    } else {
        score -= 25.0; // perfect fit strongly rewarded
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        // extra reward for tight two-item packing
        if post_residual - next_item_size < 10 {
            score -= 8.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        score += 10.0; // post-residual cannot host next item: dead space risk
    }

    // Last-chance pressure: strongly favor the only fitting bin to avoid new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading to new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 0.35 * (0.5 + progress);

    // New-bin candidate: make empty bin unattractive unless residuals are all poor.
    if bin_residual == bin_capacity {
        score += 15.0 + mean_residual * 0.2;
    } else if (bin_residual as f64) < mean_residual - 5.0 {
        score -= 5.0; // prefer tighter-than-average bins
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward perfect 2-step match: post_residual equals next_item_size.
    if next_item_size > 0 {
        let diff = (post_residual as f64 - next_item_size as f64).abs();
        if diff < 1.0 {
            score -= 40.0; // exact 2-step match: pack next item too
        } else if next_item_size <= post_residual {
            // next item still fits here: mild reward proportional to tightness
            score -= 6.0 * (1.0 - diff / (bin_capacity as f64));
        } else {
            // next item won't fit after placement: penalize by wasted gap size
            score += 0.25 * (next_item_size as f64 - post_residual as f64).min(30.0);
        }
    }

    // Penalize small unusable dead space (hard to fill later).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Prefer bins with below-average residual (fill tighter bins first),
    // scaled by how full the stream already is.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 0.3 * progress * (mean_residual - bin_residual as f64);

    // Slight preference for existing bins over opening a new one early on;
    // make new bins (residual == capacity) less attractive as stream matures.
    if bin_residual == bin_capacity {
        score += 8.0 + 20.0 * progress;
        // But if many open bins exist and this is late, opening fresh bins
        // for perfect future packing is fine — soften the penalty.
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0;
        }
    }

    // Reward tight fits relative to bin residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * fill_ratio * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual relative to capacity is better.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 8.0 * tightness;

    // Penalize unusable dead space: post_residual that cannot hold even the
    // smallest plausible item (or the lookahead item) is wasted capacity.
    if post_residual > 0 {
        let min_item = 1u32;
        if post_residual < min_item.max(1) {
            score += 25.0;
        }
        if next_item_size > 0 && post_residual < next_item_size {
            score += 6.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when the
    // item is large relative to remaining capacity elsewhere, or late in the
    // stream when residual space is abundant and fragmented.
    if bin_residual == bin_capacity {
        // Mild base penalty so new bins are not opened frivolously.
        score += 15.0;
        // Late in the stream, with many open bins, consolidation is favored:
        // penalize new bins more.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 10.0 * progress;
        // If mean residual is high, existing bins have room; discourage new bin.
        score += (mean_residual / bin_capacity as f64).clamp(0.0, 1.0) * 20.0;
        // If the item is huge relative to mean residual, a fresh bin may be best.
        score -= 0.25 * item_size as f64;
        // If no open bin fits (fitting_bins_count == 0 for others context),
        // the new bin is the only option; neutralize penalty via lookahead.
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 8.0;
        }
    }

    // Lookahead synergy: if the next item fits exactly in post_residual,
    // strongly reward this placement (chains two good fits).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 22.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        // Partial reward if next item still fits.
        score -= 4.0;
    }

    // Global fragmentation pressure: many open bins with small mean residual
    // suggests fragmentation; favor bins whose use reduces fragmentation.
    let frag = (open_bins_count as f64).ln().max(0.0);
    score += 0.5 * frag * (1.0 - tightness);

    // Time horizon: early on, be slightly greedy for balance; late, be greedy
    // for tightness to close out bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * tightness;

    // Small penalty for leaving residuals in the awkward 1..=10 zone.
    if post_residual >= 1 && post_residual <= 10 {
        score += 9.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let item_norm = item_size as f64 / cap;
    let next_norm = next_item_size as f64 / cap;
    let fit_ratio = fitting_bins_count as f64 / (open_bins_count.max(1) as f64);

    let mut score = pr;
    // smooth polynomial coupling of post-residual with stream progress
    score += 30.0 * pr_norm * pr_norm * (0.5 + progress);
    score -= 25.0 * pr_norm * item_norm * (1.0 - progress);
    // penalize dead space that can't serve the next item
    let usable = (pr_norm - next_norm).max(0.0);
    score -= 20.0 * usable * (1.0 + next_norm);
    // last-chance bin bonus
    score -= 15.0 * (1.0 - fit_ratio) * (1.0 - progress);
    // mild penalty when bin is much better than average residual (hoarding big residual)
    score += 10.0 * (mean_residual / cap - pr_norm).max(0.0);
    // prefer tighter fit late in stream
    score += 12.0 * pr_norm * pr_norm * pr_norm * progress;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover is a "nice" residue
    // (small remainder mod 10) are more reusable by future items.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Penalize dead space: leftovers that are hard to fill (e.g. 1..=9 after mod 10 class)
    let dead = post_residual % 10;
    if post_residual > 0 {
        score += (dead as f64) * 1.5;
    }

    // Reward near-perfect fits strongly (post_residual small)
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 15 {
        score -= 8.0;
    }

    // Harmonic fraction of bin used: encourage filling bins past half
    let fill_frac = (cap - pr) / cap;
    score -= fill_frac * 20.0;

    // Lookahead coupling: if next item fits exactly in the post residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            let nres = post_residual - next_item_size;
            score -= 10.0;
            score += (nres % 10) as f64 * 0.8;
        } else {
            // next item cannot follow here: mild penalty scaled by gap
            score += ((next_item_size - post_residual) as f64) * 0.3;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits the item
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin, reduced when many items remain
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = 45.0 + 25.0 * progress;
        if fitting_bins_count == 0 {
            score -= 60.0; // must open a bin anyway
        }
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // a fresh bin can host the next item too
            score -= 5.0;
        }
    } else {
        // Prefer tighter bins among open ones: tie-break on residual distance to item
        score += (bin_residual as f64 - item_size as f64) * 0.2;
    }

    // Mean residual context: when open bins are already slack, discourage more slack
    score += (pr - mean_residual).max(-20.0).min(20.0) * 0.1;

    // Modulo-class threshold on post_residual: leftovers in [10,20) or [40,50)
    // are classic reusable classes; give them a small bonus.
    let class = post_residual / 10;
    if class == 1 || class == 4 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor placements leaving little space.
    let fit_ratio = (item_size as f64) / (bin_residual as f64);
    score -= fit_ratio * 30.0;

    // Dead-space penalty: post_residual too small to ever hold a future item
    // (items are >= 1, but gaps below next_item_size are risky).
    let min_future = if next_item_size > 0 { next_item_size } else { item_size };
    if post_residual > 0 && post_residual < min_future {
        score += (min_future - post_residual) as f64 * 2.5 + 15.0;
    }

    // Very small gaps are near-useless: hard penalty scaled by how close to zero.
    if post_residual < 10 {
        score += (10 - post_residual) as f64 * 3.0;
    }

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Open-bin pressure: prefer filling existing bins over opening new ones,
    // but relax pressure as stream progresses.
    let progress = (step_index as f64) / (total_items.max(1) as f64);
    score += (open_bins_count as f64) * (1.5 - progress);

    // Last-chance bin: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate bias: make empty bins moderately attractive only when
    // the item fits poorly everywhere (large item, high mean residual).
    if bin_residual == bin_capacity {
        let poor_fit = fit_ratio < 0.5;
        if poor_fit {
            score -= 12.0;
        } else {
            score += 25.0;
        }
    }

    // Prefer bins below mean residual (filling emptier bins to consolidate).
    score += (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness;

    // Aggressive 2-step lookahead: reward if next item exactly fills post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect 2-step chain
        } else if next_item_size < post_residual {
            // next item fits: reward proportionally to how well it fills
            let fill2 = 1.0 - (post_residual - next_item_size) as f64 / (bin_capacity as f64);
            score -= 25.0 * fill2;
        } else {
            // next item does not fit here: penalize leftover dead space
            let dead = (post_residual as f64) / (bin_capacity as f64);
            score += 20.0 * dead;
        }
    } else {
        // last item: strongly reward tight fit
        score -= 30.0 * tightness;
    }

    // Relative to mean residual: prefer bins with below-mean residual (tighter bins)
    score += 0.3 * ((post_residual as f64) - mean_residual);

    // Last-chance bin bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize opening a new bin when the item would fit well elsewhere
    if bin_residual == bin_capacity {
        // new-bin candidate: base penalty, reduced if item is large relative to capacity
        let large = (item_size as f64) / (bin_capacity as f64);
        score += 55.0 * (1.0 - large);
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
    }

    // Early in stream: mild preference to consolidate into fewer bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * (1.0 - progress) * (open_bins_count as f64).sqrt();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual gets extra discount.
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * (1.0 - tightness) * (1.0 - tightness);

    // Penalize dead space that can't fit the next item (lookahead coupling).
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += 0.6 * (next_item_size - post_residual) as f64;
        }
        // Reward leaving exactly enough room for the next item.
        if post_residual == next_item_size {
            score -= 8.0;
        }
    } else {
        // Last item: strongly prefer filling bins as fully as possible.
        score += 0.5 * post_residual as f64;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0 + 0.1 * item_size as f64;
    }

    // New-bin candidate: penalize opening a new bin, more so when decent fits exist
    // or many bins are already open (fragmentation risk).
    if bin_residual == bin_capacity {
        score += 15.0 + 1.5 * open_bins_count as f64;
        // But if item is large, opening fresh may be fine: soften penalty.
        score -= 0.08 * item_size as f64;
        // Early in the stream, new bins are cheaper to open.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 5.0 * (1.0 - progress);
    }

    // Encourage balancing against mean residual: prefer bins whose residual
    // is below the mean (keeps a spread of useful gaps).
    let resid_f = bin_residual as f64;
    if resid_f < mean_residual {
        score -= 1.5 * (mean_residual - resid_f) / bin_capacity as f64;
    } else {
        score += 1.0 * (resid_f - mean_residual) / bin_capacity as f64;
    }

    // Mild penalty for wasting a large bin residual on a small item.
    let waste = (bin_residual - item_size) as f64;
    if waste > 30.0 {
        score += 0.05 * (waste - 30.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer low post-residual, with smooth polynomial shaping.
    let mut score = pr
        + 20.0 * norm_pr * norm_pr
        + 15.0 * progress * norm_pr * norm_pr * norm_pr;

    // Perfect/near-perfect fit bonus (non-linear in progress).
    if post_residual == 0 {
        score -= 60.0 + 40.0 * progress;
    } else if post_residual < 5 {
        score -= 30.0 + 20.0 * progress;
    }

    // Last-chance bin: strong smooth reward scaled by tightness.
    if fitting_bins_count == 1 {
        score -= 25.0 + 35.0 * (1.0 - norm_pr) * (1.0 - norm_pr);
    }

    // Lookahead coupling: reward if next item fits the post-residual.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let fit_ratio = nx / pr.max(1.0);
            score -= 18.0 * fit_ratio * (1.0 - fit_ratio) * 4.0;
        } else {
            // Post-residual too small for next item: penalize dead space smoothly.
            let waste = nx - pr;
            score += 0.4 * waste * (0.5 + progress);
        }
    }

    // Dispersion from mean residual: penalize bins deviating from average state.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 12.0 * dev * dev;

    // Bin-count pressure: with many open bins, favor consolidation into existing bins.
    score += 2.0 * (open_bins_count as f64).ln().max(0.0) * norm_pr;

    // New-bin candidate: make it attractive only when the item is large relative
    // to capacity or residuals are scarce.
    if bin_residual == bin_capacity {
        let large = item_size as f64 / cap;
        score = pr - 10.0 * large * large + 30.0 * (1.0 - progress) * (1.0 - fitting_bins_count as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: maximal reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: classify dead space quality.
    // Residuals that can still host common small items are valuable.
    let small_hostable = if post_residual >= 10 { 1.0 } else { 0.0 };
    score -= 40.0 * small_hostable;

    // Modulo-10 class of post_residual: exact decade residuals are "clean"
    // and likely reusable by future items aligned to capacity fractions.
    let decade_align = (post_residual % 10) as f64;
    score += decade_align * 1.5;

    // Integer-division thresholds on post_residual: quartile bands of capacity.
    let q = post_residual / 25; // 0..=4
    match q {
        0 => score += 30.0,        // tiny dead space (<25) mostly unusable
        1 => score -= 5.0,
        2 => score -= 10.0,        // mid residuals flexible
        3 => score -= 15.0,
        _ => score -= 20.0,        // large residual still very usable
    }

    // Lookahead coupling: does the next item fit the post-residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item chains perfectly into this bin -> strong reward.
            score -= 60.0;
            // Exact harmonic match: post_residual is a multiple of next item.
            if next_item_size > 0 && post_residual % next_item_size == 0 {
                score -= 25.0;
            }
        } else {
            // Next item won't fit here; penalize slightly less if residual
            // is still in a useful harmonic class (>=10, decade-aligned).
            if post_residual < 10 {
                score += 25.0;
            }
            if next_item_size <= bin_residual {
                score += 8.0; // mild penalty: bin could have held next item too
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // New-bin candidate handling: empty bin gets a baseline cost that scales
    // with how many bins are already open and how bad the current fits are.
    if bin_residual == bin_capacity {
        // Opening a new bin is penalized; more so when many bins are open
        // or mean residual is still large (existing bins have room).
        score += 120.0 + 10.0 * open_bins_count as f64 + mean_residual * 0.8;
        // But late in the stream with fragmented bins, new bins are fine.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 60.0 * progress;
        // If next item is large, a fresh bin keeps room for it.
        if next_item_size > 50 {
            score -= 30.0;
        }
    }

    // Prefer tighter bins overall: closeness of residual to item size.
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score += tightness * 20.0;

    // Mild preference to balance load across bins when many are open.
    score += (mean_residual - post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no item (min size 1) can still use
    // are pure waste; gaps too small for the lookahead item are soft waste.
    if post_residual == 0 {
        score -= 60.0; // perfect fit is ideal
    } else if post_residual < 10 {
        score += 45.0; // unusable sliver: heavy penalty
    } else if next_item_size > 0 && post_residual < next_item_size {
        score += 12.0; // can't host the next item
    } else if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0; // exact fit for lookahead item
    }

    // Reward tight fits relative to item size (small items wasting big bins is bad).
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill_ratio * (1.0 - (post_residual as f64 / bin_capacity as f64));

    // Open-bin pressure: discourage spreading across many bins when a compact fit exists.
    score += 2.0 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: only attractive when no open bin offers a good home,
    // i.e. when mean residual is small relative to the item.
    if bin_residual == bin_capacity {
        let scarcity = (item_size as f64 - mean_residual).max(0.0);
        score = bin_capacity as f64 - 10.0 * fill_ratio - scarcity.clamp(0.0, 30.0);
        if fitting_bins_count == 0 {
            score -= 50.0; // forced new bin
        }
        if fitting_bins_count == 1 {
            score += 40.0; // an existing last-chance bin beats a fresh one
        }
    }

    // Late-stream consolidation: as the stream progresses, prefer filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 8.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: perfect match with next item is ideal.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        // Strong reward for exact match, decaying with distance.
        score -= 60.0 * (1.0 - diff / (bin_capacity as f64)).powi(3);
        // Penalize post_residual slightly larger than next item (dead space for k=2).
        if post_residual > next_item_size && post_residual < next_item_size + 10 {
            score += 25.0;
        }
    } else {
        // Last item: prefer tightest fit.
        score += 10.0;
    }

    // Reward bins tighter than the mean residual (better fills).
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Penalize leaving tiny unusable slivers (< 10) unless perfect lookahead match.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Early in stream: mildly prefer keeping large residuals for future big items.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 0.2 * post_residual as f64;

    // New-bin candidate: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        score += 30.0 + 5.0 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= item_size {
            score += 10.0; // opening fresh bin helps chain next item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer tight fits: reward small post_residual non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that no plausible future item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    } else if post_residual >= 10 && post_residual < 31 {
        score += 4.0; // partially usable
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot use this bin's leftover: mild penalty scaled by gap
            score += 0.15 * ((next_item_size - post_residual) as f64).min(60.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Crowding: when many bins are open, consolidate into fuller bins.
    let crowd = (open_bins_count as f64).ln().max(1.0);
    score += 3.0 * (bin_residual as f64 - mean_residual) / crowd;

    // Time horizon: early in stream, be more willing to open new bins
    // (long future amortizes); late in stream, prefer filling existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize late, reward early.
        score += 22.0 * progress - 8.0 * (1.0 - progress);
    } else {
        score -= 6.0 * progress;
    }

    // Bonus for bins already below mean residual (fill the emptier ones less,
    // keep balanced residuals to preserve flexibility) — inverted: prefer
    // placing into bins near mean residual to avoid fragmentation.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    // Exact fill is perfect.
    if post_residual == 0 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: penalize leftover space, with non-linear (quadratic/cubic) coupling
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth polynomial coupling of post_residual with stream progress:
    // early in the stream, tolerate larger residuals; later, punish them harder
    let progress_coupling = 1.0 + progress * (2.5 * norm_pr - 1.2 * norm_pr * norm_pr);
    score *= progress_coupling.max(0.25);

    // Lookahead: reward residual that can fit the next item (smooth kernel)
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if pr >= n {
            let fit_quality = (n / pr).min(1.0);
            score -= 12.0 * fit_quality * (1.0 - progress * 0.5);
        } else {
            let gap = (n - pr) / cap;
            score += 6.0 * gap * (1.0 + gap);
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    } else if fitting_bins_count > 1 {
        // mild competition pressure: prefer tighter bins among many options
        score += 1.5 * (fitting_bins_count as f64).ln();
    }

    // Penalize bins far from mean residual (prefer consistent fill levels)
    let dev = (pr - mean_residual) / cap;
    score += 3.0 * dev * dev * cap * 0.1;

    // Slight reward for high fill ratio achieved by this placement
    score -= 0.5 * (item_size as f64 / cap) * (1.0 + progress);

    // New-bin candidate handling: only attractive when nothing fits well
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 8.0 + 6.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues modulo 10 define "dead-space classes".
    let residue = (post_residual % 10) as f64;
    // Penalize residues that are awkward (1..=9 but not 0): dead space unlikely to be filled.
    if post_residual > 0 {
        score += (10.0 - residue) * 0.8;
    } else {
        // Perfect fit: strong reward.
        score -= 25.0;
    }

    // Integer-division thresholds on post_residual: classify usable slabs.
    let slab = post_residual / 20; // 0..5
    let slab_bonus = match slab {
        0 => 15.0,          // tiny leftover (<20): nearly dead space
        1 => 5.0,           // 20..39: only small items fit
        2 => -3.0,          // 40..59: decent
        3 => -6.0,          // 60..79: good
        _ => -10.0,         // 80+: very reusable
    };
    score += slab_bonus;

    // Lookahead coupling: harmonic class of next item size modulo 10 vs post_residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        // Next item fits exactly here: reward strongly.
        score -= 12.0 + (next_item_size as f64) * 0.1;
        // Extra reward if the fit is exact (harmonic residue match).
        if post_residual == next_item_size {
            score -= 18.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Next item cannot use this leftover: penalize proportional to dead fraction.
        score += (next_item_size as f64 - post_residual as f64).min(30.0) * 0.5;
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when the item
    // is large relative to capacity or all open bins fit poorly.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        // Base penalty so new bins are not opened casually.
        score += 45.0;
        // Large items justify fresh bins more as the stream progresses.
        score -= fill_ratio * 30.0 + progress * 10.0;
        // If many open bins exist with high mean residual, avoid adding more bins.
        score += (open_bins_count as f64) * 2.0 + mean_residual * 0.15;
        // If no other bin fits (fitting_bins_count==0 among open bins), the new bin is the only option;
        // reflect that with a discount.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += (open_bins_count as f64) * 0.3;

    // Small tie-breaker favoring tighter fits (larger item into smaller residual).
    score -= (item_size as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small to hold even the smallest
    // plausible item are wasted; punish them super-linearly.
    if post_residual < 10 && post_residual > 0 {
        score += (10.0 - post_residual as f64) * 8.0;
    }
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Reward tight fits: fraction of the residual consumed.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 15.0;

    // Lookahead: if the next item fits exactly in the post residual,
    // strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 20.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > post_residual && post_residual > 0 {
        // Post residual can't host next item: mild penalty scaled by gap.
        score += (next_item_size - post_residual) as f64 * 0.3;
    }

    // Last-chance pressure: if this is the only fitting bin, avoid
    // opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bins pressure: prefer reusing bins when many are open,
    // but allow new bins when few are open (early stream flexibility).
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive early, expensive later.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - progress);
        score += open_bins_count as f64 * 2.0;
        // Discard new-bin idea if a good fit exists elsewhere.
        if fill_ratio > 0.8 {
            score += 30.0;
        }
        // If next item is large, a fresh bin is valuable.
        if next_item_size > 60 {
            score -= 15.0;
        }
    } else {
        // Reusing an open bin reduces open_bins_count pressure.
        score -= open_bins_count as f64 * 0.5;
        // Prefer bins with residuals below the mean (consolidate waste).
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer tight fits: small post_residual is good, already in base score.

    // Aggressive 2-step lookahead: reward bins whose post_residual exactly
    // matches the next item size (perfect chain), penalize near-misses.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        if diff < 0.5 {
            score -= 25.0; // exact match: next item fills this bin perfectly
        } else if post_residual as f64 >= nxt {
            // next item fits here; reward proportionally to how well it fits
            score -= 8.0 * (1.0 - diff / (bin_capacity as f64));
        } else {
            // next item would NOT fit here: this bin becomes dead space
            score += 6.0 * (1.0 - post_residual as f64 / (bin_capacity as f64));
        }
    }

    // Compare against mean residual: bins far below mean are "tight" and
    // should be filled now; bins above mean have room to spare.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Penalize opening a new bin when the item fits well elsewhere.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        // new-bin candidate: only attractive if post_residual would be tiny
        // usable slack (i.e. item is huge relative to capacity)
        score += 10.0 * (post_residual as f64 / bin_capacity as f64);
        if next_item_size > 0 && (post_residual as f64 - next_item_size as f64).abs() < 0.5 {
            score -= 20.0; // fresh bin perfectly set up for next item
        }
    }

    // Late in the stream, consolidate: discourage new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 4.0 * progress;
    }

    // Small penalty on very small post_residual that can't hold the smallest
    // plausible item (dead space), scaled by how dead it is.
    if post_residual < 10 && post_residual > 0 {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero is good, but dead space
    // in a small residual band is the worst (unusable slivers).
    if post_residual > 0 {
        let fragility = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score += (post_residual as f64).powf(0.6) * (0.5 + 0.5 * fragility);
    } else {
        score -= 8.0; // perfect fit bonus
    }

    // Lookahead: if next item fits in post_residual, reward using this bin
    // (chained packing); if not, penalize slightly unless post_residual is tiny.
    if next_item_size > 0 {
        if (post_residual as f64) >= next_item_size as f64 {
            let chain_waste = post_residual as f64 - next_item_size as f64;
            score -= (10.0 - chain_waste.min(10.0)) * 0.8;
        } else {
            score += (next_item_size as f64 - post_residual as f64).min(20.0) * 0.3;
        }
    }

    // Last chance: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Global balance: prefer bins whose residual deviates from the mean
    // in the direction that consolidates space (fill low-residual bins first).
    let dev = bin_residual as f64 - mean_residual;
    score += dev * 0.15;

    // Time horizon: late in the stream, be more conservative with new bins
    // and more aggressive at filling existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 4.0 * (bin_residual as f64 / bin_capacity as f64);

    // Mild penalty for too many open bins: encourage consolidation.
    score += open_bins_count as f64 * 0.05;

    // New-bin candidate: only attractive when no good fit exists
    // (handled implicitly by large residual giving high base score,
    // but ensure empty bin isn't chosen for tiny items unnecessarily).
    if bin_residual == bin_capacity {
        score += 15.0 + item_size as f64 * 0.1;
        if fitting_bins_count == 0 {
            score -= 30.0; // must open a new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: penalize wasted space, non-linearly (quadratic dead-space growth)
    let mut score = pr * (1.0 + 0.8 * norm_pr);

    // Smooth stream-progress coupling: early on, tolerate waste (keep bins flexible);
    // late in the stream, strongly punish leftover space.
    let progress_weight = 0.6 * (1.0 - progress) * (1.0 - progress);
    let late_weight = 1.4 * progress * progress;
    score += (progress_weight - late_weight) * norm_pr * cap * 0.3;

    // Reward tight fits (post_residual near zero) with smooth coupling
    let tightness = 1.0 - norm_pr;
    score -= 8.0 * tightness * tightness * tightness;

    // Penalize deviation of post_residual from mean residual (fragmentation balancing)
    let dev = pr - mean_residual;
    score += 0.05 * dev * dev / (1.0 + mean_residual);

    // Last-chance bin: strong reward to use it instead of opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (1.0 + progress);
    }

    // New-bin candidate: penalize unless current bins are nearly full on average
    if bin_residual == bin_capacity {
        score += 12.0 + 10.0 * (1.0 - progress);
        let fullness = 1.0 - mean_residual / cap;
        score -= 14.0 * fullness * fullness;
    }

    // Lookahead: reward if post_residual exactly accommodates next item
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score -= 6.0 * (1.0 - gap / cap).max(0.0) * (1.0 - gap / cap);
        // Penalize leaving space just below next item (unusable sliver)
        if pr < next_item_size as f64 && pr > 0.0 {
            score += 3.0 * (1.0 - pr / next_item_size as f64);
        }
    }

    // Mild penalty for spreading across many open bins late in stream
    score += 0.3 * (open_bins_count as f64).ln().max(0.0) * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover lands on "usable" classes
    // (multiples of small denominators) are favored; dead-space classes penalized.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Class A: post_residual divisible by 10 -> clean harmonic slot (e.g. 50, 60, 20)
    if post_residual % 10 == 0 {
        score -= 12.0;
    }
    // Class B: divisible by 5 but not 10 -> half-harmonic
    else if post_residual % 5 == 0 {
        score -= 5.0;
    }
    // Class C: awkward leftovers (1..9 mod 10, non-multiples of 5) -> dead space
    else {
        score += 4.0;
    }

    // Integer-division thresholds: residual in low tiers is nearly unusable
    let tier = post_residual / 20; // 0..5 harmonic tiers
    score -= tier as f64 * 3.0;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead coupling: does the leftover harmonically fit the next item?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits exactly into a harmonic class of this bin
            if post_residual % next_item_size == 0 {
                score -= 15.0;
            } else {
                score -= 8.0;
            }
            // penalize wasting most of the leftover on a small next item
            let waste = (post_residual - next_item_size) as f64;
            score += 0.10 * waste;
        } else {
            // next item cannot use this bin's leftover: leftover likely dead
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: make it attractive only when this item is large relative
    // to capacity or all open residuals are harmonically poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let large_item = (item_size as f64) > 0.6 * cap;
        let poor_open = mean_residual < 0.25 * cap;
        if large_item || poor_open {
            score -= 25.0 + 10.0 * progress;
        } else {
            score += 18.0; // prefer packing into existing bins early
        }
    }

    // Mild pressure to consolidate when many bins are open
    score += 0.05 * open_bins_count as f64;

    // Fractional capacity alignment: reward residuals near half-capacity class
    let half = cap / 2.0;
    let dev = (post - half).abs();
    if dev < 10.0 {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) super-linearly.
    if post_residual <= 10 {
        score -= (11 - post_residual as i32) as f64 * 8.0;
    }
    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Penalize unusable dead space: gaps too small for the minimum item (1).
    // Gaps in 1..=3 are nearly dead; penalize them heavily.
    if post_residual >= 1 && post_residual <= 3 {
        score += 60.0;
    }

    // Lookahead synergy: if the next item fits exactly in the post residual,
    // reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 5 {
        score -= 25.0;
    }
    // If next item cannot fit in post residual but would fit elsewhere, mild penalty.
    if next_item_size > post_residual && next_item_size > 0 {
        score += 8.0;
    }

    // Open-bin pressure: when many bins are open, prefer filling existing bins
    // (penalize the new-bin candidate which has large residual).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).sqrt() * (2.0 + 4.0 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: base penalty scaled by open-bin pressure.
        score += 15.0 + pressure;
        // But if this bin is the last chance and the fit is poor, allow new bin.
        if fitting_bins_count == 1 && post_residual > 0 && post_residual <= 3 {
            score -= 80.0;
        }
    } else {
        // Existing bin: reward slightly, more when bins are crowded.
        score -= 2.0 + pressure * 0.3;
        // Last-chance bin: strongly favor using it to avoid opening a bin.
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
    }

    // Mean-residual coupling: if this bin's residual is far below the mean
    // (a nearly full bin), favor placing here to close it out.
    let residual_diff = mean_residual - bin_residual as f64;
    if residual_diff > 0.0 {
        score -= residual_diff * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize small post_residual more via nonlinearity.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize dead space: post_residual too small to ever be useful.
    if post_residual < 10 {
        score += 18.0;
    } else if post_residual > 50 {
        // Large leftover is flexible; mild reward.
        score -= 4.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            // Next item won't fit here; penalize slightly, more if it nearly fits.
            score += 3.0 * (next_item_size as f64 - post_residual as f64) / 10.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins are poor.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 15.0;
        // If no open bin fits well (high mean residual mismatch), allow new bin.
        if mean_residual < item_size as f64 {
            score -= 30.0;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Global state: many open bins with slack -> prefer reusing fuller bins.
    if open_bins_count > 3 {
        let residual_gap = mean_residual - post_residual as f64;
        score += 0.05 * residual_gap;
    }

    // Slight time-decay encouraging consolidation as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 3.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Smooth non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 + 3.0 * progress) - 2.0 * norm_pr * progress;
    score += 8.0 * poly;

    // Penalize dead space more as the stream matures
    score += progress * 6.0 * (norm_pr * norm_pr);

    // Reward tight fits smoothly (small post_residual)
    score -= 5.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (0.5 + 0.5 * progress);

    // Last-chance bin: reward strongly with smooth scaling
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - norm_pr) * (1.0 + progress);
    }

    // Lookahead coupling: if next item fits the post residual, reward
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 4.0 * (1.0 - (pr - nxt) / cap) * (1.0 + progress);
        } else {
            score += 3.0 * ((nxt - pr) / cap) * (1.0 - progress);
        }
    }

    // Mild penalty for spreading across many open bins when mean residual is high
    let openness = open_bins_count as f64;
    score += 0.5 * (mean_residual / cap) * (openness / (1.0 + openness)) * (1.0 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: bins whose leftover lies in
    // "usable" residue classes (multiples of small harmonics) are favored.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fraction of capacity left after placement.
    let frac = pr / cap;

    // Penalize residuals that are "almost but not exactly" nice fractions
    // (dead space). Exact harmonics: 0, 1/4, 1/2, 3/4 of capacity.
    let harmonics = [0.0f64, 0.25, 0.5, 0.75];
    let mut harm_bonus = 0.0f64;
    for h in harmonics.iter() {
        let d = (frac - h).abs();
        if d < 0.02 {
            harm_bonus -= 6.0 * (1.0 - d / 0.02);
        }
    }
    score += harm_bonus;

    // Integer-division threshold on post_residual: leftover >= 25 is reusable
    // for typical small items; leftover in (0, 10) is pure dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }
    if post_residual >= 25 {
        score -= 3.0;
    }

    // Modulo coupling: if next item fits exactly into post_residual (perfect
    // lookahead match), strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 15.0;
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            // reward tight lookahead fits, penalize sloppy ones
            score -= 5.0 * (1.0 - slack as f64 / cap);
        } else {
            // next item cannot use this residual: mild penalty scaled by waste
            let unusable = next_item_size - post_residual;
            score += 2.0 * (unusable as f64 / cap);
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate handling: only attractive when current bin fits are
    // all poor (large post-residual waste) or many bins are already open.
    if bin_residual == bin_capacity {
        let avg_waste = mean_residual / cap;
        score = 55.0 + 10.0 * avg_waste - 3.0 * (open_bins_count as f64).sqrt();
        if fitting_bins_count == 0 {
            score -= 40.0; // no alternative, must open
        }
    }

    // Tight fits (small post_residual relative to item) are generally best.
    score -= 4.0 * (1.0 - (item_size as f64) / cap);

    // Slight late-stream conservatism: prefer filling existing bins as the
    // stream nears its end.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 4.0 * progress * (pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: post_residual that is too small to ever be useful
    // (smaller than the minimum conceivable item) is pure waste.
    let min_item = 1.0f64;
    if (post_residual as f64) < min_item * 10.0 {
        score += 200.0;
    }

    // Tight fit reward: perfect or near-perfect packing is strongly preferred.
    if post_residual == 0 {
        score -= 300.0;
    } else if post_residual <= 5 {
        score -= 150.0;
    }

    // Non-linear dead-space curve: residuals in the "awkward gap" zone
    // (too small for typical items, too big to ignore) get extra penalty.
    let pr = post_residual as f64;
    if pr > 0.0 && pr <= 30.0 {
        score += (30.0 - pr) * 3.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // or when open-bin pressure is high. Penalize opening new bins mildly,
    // more so when few bins are open (consolidate early).
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 / (mean_residual / bin_capacity as f64 + 1.0);
        score += 60.0 + pressure * 5.0;
        // But if the next item is huge and residuals are fragmented, new bin helps.
        if next_item_size > 0 && (next_item_size as f64) > mean_residual {
            score -= 40.0;
        }
    }

    // Lookahead: if next item fits exactly in the post_residual, reward this bin.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 120.0;
    } else if next_item_size > 0 && next_item_size < post_residual {
        score -= 20.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // next item won't fit here anyway; residual becomes dead space
        score += 25.0;
    }

    // Open-bin pressure: mildly discourage spreading across many bins.
    score += open_bins_count as f64 * 0.5;

    // Stream progression: later in the stream, be more conservative with new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += progress * 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for a perfect fit.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if the next item fits exactly into the post residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Slack after the next placement drives the penalty.
            let slack2 = post_residual - next_item_size;
            score -= 60.0 - (slack2 as f64).min(60.0);
            if slack2 == 0 {
                score -= 250.0; // perfect two-item packing
            }
        } else {
            // Next item won't fit here; penalize wasted potential slightly.
            score += 15.0;
        }
    }

    // Compare residual to mean residual: prefer tighter-than-average bins.
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: only attractive when few fitting bins exist or residual is tight.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 1.0 / fitting_bins_count as f64 };
        score += 80.0;                 // base penalty for opening a new bin
        score -= pressure * 90.0;      // relief when no/poor alternatives exist
        if next_item_size > 0 && next_item_size > post_residual {
            score -= 20.0; // fresh bin can host the next item anyway
        }
    }

    // Slight preference to keep many bins from proliferating early in the stream.
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small dead space), with super-linear penalty.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * tightness * tightness;

    // Lookahead: if the next item fits exactly into the post residual, big reward;
    // if post residual is smaller than next item but still sizable, penalize dead space.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0; // perfect chain fit
        } else if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // post residual too small for next item: dead space likely
            let waste = post_residual as f64 / bin_capacity as f64;
            score += 12.0 * waste;
        }
    }

    // Last chance: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0 - 10.0 * tightness;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // (this call itself has post_residual == bin_capacity - item_size).
    if bin_residual == bin_capacity {
        // Opening a new bin: penalize mildly so it's chosen only when existing
        // bins would leave large residuals; scale with number of open bins.
        score += 5.0 + 0.5 * open_bins_count as f64;
        // Early in the stream, opening bins is cheap (builds a pool).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
    }

    // Global state coupling: prefer filling bins whose residual deviates
    // from the mean (consolidate slack into few bins).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Prefer placing into already-open bins over creating more when many open.
    if bin_residual != bin_capacity {
        score -= 0.1 * open_bins_count as f64;
    }

    // Exact fill is always best.
    if post_residual == 0 {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_post = post / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    let mut score = post;

    // Smooth polynomial coupling of post_residual with stream progress
    let p2 = progress * progress;
    let p3 = p2 * progress;
    score += 12.0 * norm_post * norm_post * (0.5 + p2);
    score -= 9.0 * norm_item * (1.0 - p3);

    // Reward tight fits, more strongly later in the stream
    let tight = 1.0 - norm_post;
    score -= 15.0 * tight * tight * tight * (0.4 + 0.6 * progress);

    // Penalize dead space that cannot fit the next item (smooth interaction)
    if next_item_size > 0 {
        let gap = (post - next_item_size as f64).max(0.0) / cap;
        score += 10.0 * gap * (1.0 + progress);
        // Reward leaving exactly room for next item
        let fit_next = if post >= norm_next * cap { 1.0 } else { 0.0 };
        score -= 6.0 * fit_next * (1.0 - (post - norm_next * cap).abs() / cap) * (1.0 - progress);
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 - 0.5 * progress);
    }

    // Mild pressure to reuse existing bins as open-bin count grows
    score -= 0.3 * (open_bins_count as f64).ln().max(0.0);
    score += 0.2 * (mean_residual - post).abs() / cap;

    // New-bin candidate: penalize mildly unless current bin leaves bad residue
    if bin_residual == bin_capacity {
        let bad = if post > 0.0 && post < 10.0 { 1.0 } else { 0.0 };
        score += 4.0 - 3.0 * bad;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: dead space in low classes is worse.
    let class = post_residual / 10; // 0..=10 harmonic bands
    match class {
        0 => score -= 40.0,          // perfect fit
        1 => score -= 25.0,          // near-perfect
        2 => score -= 12.0,
        3 => score -= 5.0,
        4 => score += 3.0,
        5 => score += 8.0,           // half-empty: mediocre
        6 => score += 12.0,
        7 => score += 16.0,
        8 => score += 20.0,
        9 => score += 24.0,
        _ => score += 10.0,          // empty-ish bin (new bin candidate)
    }

    // Lookahead coupling: penalize if next item cannot use the post residual.
    if next_item_size > 0 {
        if next_item_size > post_residual {
            score += (next_item_size - post_residual) as f64 * 0.5;
        } else {
            // next item fits in residual: reward, scaled by how snugly
            score -= (post_residual - next_item_size) as f64 * 0.3;
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Prefer tighter bins relative to the fleet average.
    score -= (mean_residual - bin_residual as f64) * 0.4;

    // Mild pressure to consolidate when many bins are open.
    score += open_bins_count as f64 * 0.05;

    // Slight preference to fill bins as the stream progresses.
    score -= (step_index as f64 / (total_items.max(1) as f64)) * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // Small leftover gaps (< 10) are essentially dead space: heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Gaps too small for the smallest plausible item (1) don't exist, but
    // gaps below 20 are at risk given unknown distribution: mild penalty.
    if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Reward perfect / near-perfect fills strongly.
    if post_residual == 0 {
        score -= 100.0;
    }

    // --- Fit quality relative to bin ---
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 15.0 * fill_ratio;

    // --- Last-chance pressure ---
    // If this is the only bin that fits, strongly prefer using it over
    // opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // --- Open bins count pressure ---
    // Keep the number of open bins in check: penalize adding to a
    // crowded pool slightly, but reward consolidating into existing bins.
    score += 0.5 * open_bins_count as f64;

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is fine when the current item is large
        // (large items pair well with future small items), but costly
        // when many bins are already open and mean residual is high.
        let open_pressure = (open_bins_count as f64 / 8.0).min(3.0);
        score += 25.0 + 10.0 * open_pressure - 20.0 * fill_ratio;
        // If mean residual across open bins is large, discourage new bins.
        if mean_residual > item_size as f64 {
            score += 15.0;
        }
        // Late in the stream, avoid opening bins for small leftovers.
        if post_residual == 0 {
            score -= 50.0;
        }
    }

    // --- Lookahead coupling ---
    // If the next item fits exactly in the post residual, reward this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual > next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            // Next item won't fit here: dead space risk increases.
            score += 10.0;
        }
    }

    // --- Stream progression ---
    // Late in the stream, closing bins tightly matters more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose leftover can host the next item exactly-ish.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect 2-chain
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot fit here; penalize proportionally to wasted lookahead
            let gap = (next_item_size - post_residual) as f64;
            score += 0.35 * gap;
        }
    } else {
        // last item: just minimize leftover
        score += 0.1 * post_residual as f64;
    }

    // Relative-to-mean coupling: prefer tighter-than-average bins
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Penalize dead space that is too small for typical items (unusable sliver)
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current bins are poor fits
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 - 20.0 * progress; // cheaper to open bins later? keep moderate penalty
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0; // fresh bin supports lookahead chain
        }
    }

    // Mild pressure to consolidate when many bins are open
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual small relative to capacity.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 12.0 * fit_ratio * fit_ratio;

    // Penalize leaving dead space that nothing (esp. lookahead) can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    }
    if next_item_size > 0 {
        if next_item_size > post_residual {
            score += 6.0; // lookahead item can't use leftover
        } else {
            score -= 8.0; // leftover is useful for next item
        }
        // Perfect two-item packing: item + next fills bin nearly exactly
        let gap = post_residual as i64 - next_item_size as i64;
        if gap >= 0 && gap <= 5 {
            score -= 14.0;
        }
    } else {
        score -= 5.0; // last item: prefer filling existing bins
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Fragmentation pressure: many open bins with high mean residual
    // -> favor consolidating into tight fits, discourage new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let frag = open_bins_count as f64 * mean_residual / bin_capacity as f64;
    score += 0.05 * frag;
    score -= 3.0 * progress; // later in stream: pack tighter, avoid new bins

    // New-bin candidate handling: empty bin should only win when fits are poor.
    if bin_residual == bin_capacity {
        let poor_fit = if fitting_bins_count > 0 {
            let best_possible = post_residual as f64;
            best_possible / bin_capacity as f64
        } else {
            1.0
        };
        // Base penalty so open bins usually win; relax if remaining bins are large.
        score += 30.0 - 25.0 * poor_fit;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // big item coming soon: a fresh bin is valuable
        }
        if progress > 0.8 {
            score += 8.0; // endgame: avoid stranding a nearly empty bin
        }
    }

    // Mild preference for bins with residuals close to item_size (exact-ish fit).
    let diff = bin_residual as f64 - item_size as f64;
    score += 0.15 * diff;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let mut score = pr as f64;
    // smooth polynomial coupling of post_residual with stream progress
    let t = progress;
    score += norm_pr * norm_pr * (40.0 + 60.0 * t) - norm_pr * (30.0 + 20.0 * t * t);
    // penalize dead space that no plausible future item can use
    let dead = (norm_pr - 0.1).max(0.0);
    score += dead * dead * 100.0 * (0.5 + 0.5 * t);
    // reward tight fits
    score -= norm_item * norm_item * 25.0;
    // last-chance bonus
    if fitting_bins_count == 1 { score -= 15.0; }
    // lookahead: prefer bins whose post-residual fits next item
    if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        score -= 10.0;
    } else if next_item_size > 0 {
        score += 5.0;
    }
    // mildly prefer consolidating into fewer bins early
    score += open_bins_count as f64 * 0.5 * (1.0 - t);
    // deviation from mean residual
    score += (pr - mean_residual).abs() * 0.3;
    // new-bin candidate: neutral-ish baseline with progress-dependent penalty
    if bin_residual == bin_capacity {
        score = cap * (0.9 + 0.6 * t);
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify by capacity fractions
    let frac = post_residual as f64 / cap;
    let mut class = 0u32;
    if frac == 0.0 { class = 0; }        // perfect fit
    else if frac <= 0.1 { class = 1; }   // dead space (fits almost nothing)
    else if frac <= 0.25 { class = 2; }  // small sliver
    else if frac <= 0.5 { class = 3; }
    else { class = 4; }

    // Penalize dead-space classes strongly
    score += match class {
        0 => -20.0,
        1 => 25.0,
        2 => 12.0,
        3 => 0.0,
        _ => -6.0,
    };

    // Lookahead: does next item fit into post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Reward chains where the next item still fits
            let chain_frac = next_item_size as f64 / post_residual as f64;
            score -= 8.0 + 6.0 * chain_frac;
        } else {
            // Post residual too small for next item: dead space penalty
            score += 6.0;
        }
    } else {
        // Last item: prefer tightest packing, no future concern
        score -= 5.0;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // Mild competition pressure: more candidates -> prefer tightest (already in score)
        score += 0.5 * (fitting_bins_count as f64).ln();
    }

    // Reward filling bins that are already partially used (close mean residual)
    let mean_dev = (mean_residual - post_residual as f64).abs();
    score += 0.05 * mean_dev;

    // Harmonic integer-division threshold: residuals divisible into nice chunks
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    // New-bin candidate: neutral base, but prefer it when open bins are crowded
    if bin_residual == bin_capacity {
        // Opening a new bin is expensive; make it slightly costly unless
        // current item is huge relative to capacity or few bins fit it.
        let item_frac = item_size as f64 / cap;
        let mut new_bin_score = 30.0;
        if item_frac > 0.5 { new_bin_score -= 10.0; }
        if fitting_bins_count <= 1 { new_bin_score += 20.0; } // never open when it's the only option anyway
        if next_item_size > 0 && next_item_size >= post_residual && post_residual == bin_capacity {
            // fresh bin keeps full flexibility for next item
            new_bin_score -= 4.0;
        }
        // Scale open-bin crowding: many open bins with large residuals -> opening ok
        if open_bins_count > 0 && mean_residual > 30.0 {
            new_bin_score -= 5.0;
        }
        score = score.min(new_bin_score + 10.0);
        score = new_bin_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are almost unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10 - post_residual) as f64; // heavy penalty for tiny gaps
    }
    // Perfect fit reward
    if post_residual == 0 {
        score -= 60.0;
    }
    // Moderately small gaps also risky (nothing in 1..=20 typically fits later)
    if post_residual >= 10 && post_residual <= 20 {
        score += 12.0;
    }

    // Last-chance bin: strongly prefer using the only bin that fits,
    // otherwise we pay for a fresh bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bins pressure: with many open bins, avoid spreading; prefer filling.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (1.0 + progress * 10.0);
    score += 0.8 * pressure;

    // Reward bins tighter than the mean residual (consolidation).
    score -= 0.5 * (mean_residual - post_residual as f64);

    // New-bin candidate: only attractive when the item is large and would
    // leave a big, reusable residual, or when placing here creates dead space.
    if bin_residual == bin_capacity {
        let new_bin_cost = 25.0
            - 0.3 * post_residual as f64
            + (if post_residual < 10 { 80.0 } else { 0.0 });
        score += new_bin_cost;
    }

    // Lookahead: if next item fits exactly in the post residual, bonus.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    }
    // If next item would NOT fit in post residual but fits elsewhere, mild penalty
    if next_item_size > post_residual && next_item_size <= bin_residual {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: strongly prefer bins that end exactly full.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: if the next item fits exactly in the post-residual,
    // this is a great chain placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 800.0;
        } else if post_residual > next_item_size {
            // Next item fits, but leaves more waste afterward: mild reward
            let chained_waste = (post_residual - next_item_size) as f64;
            score -= 150.0 - 0.5 * chained_waste;
        } else {
            // Next item cannot use this bin's leftover: penalize dead space
            score += 0.8 * (next_item_size - post_residual) as f64;
        }
    }

    // Relative-to-mean coupling: bins tighter than the mean are better targets.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 250.0;
    }

    // Penalize opening a new bin when decent fits exist (new-bin candidate signal).
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 120.0 + mean_residual * 0.3;
    }

    // Slight preference to fill older/tighter bins early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.2 * (1.0 - progress) * (post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are valuable: reward small post-residual non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that no plausible future item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // small unusable sliver
    }
    if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
        score += 8.0; // leftover can't host the lookahead item
    }
    // Reward leftover that exactly or nearly fits the next item (chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        score -= 15.0 * (1.0 - gap as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Time horizon: early in the stream, prefer packing into existing bins
    // less aggressively (keep flexibility); late, pack tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.5 * (1.0 - progress);

    // Many open bins: encourage consolidation into existing bins.
    score += 0.5 * open_bins_count as f64;

    // Deviation from mean residual: prefer bins whose residual is large
    // (big holes) unless the fit is very tight.
    score += 0.2 * (bin_residual as f64 - mean_residual);

    // New-bin candidate: default penalty so we prefer reusing bins,
    // but relax the penalty late in the stream or when this bin would
    // otherwise be the only fitting one (already rewarded above).
    if bin_residual == bin_capacity {
        score += 60.0;
        if next_item_size >= item_size && progress < 0.5 {
            score -= 10.0; // early stream: opening fresh bins can pay off
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear coupling of post_residual with stream progress:
    // early on, prefer tight fits (low post_residual) mildly; late, prefer them strongly.
    let pr_norm = pr / cap;
    let coupling = pr_norm * pr_norm * (0.5 + 2.5 * progress);
    score += coupling * cap;

    // Reward filling bins nearly completely, scaled by progress.
    let fill = 1.0 - pr_norm;
    score -= 12.0 * fill * fill * (0.3 + 0.7 * progress);

    // Penalize dead space: post_residual that is small but unusable.
    if next_item_size > 0 && post_residual > 0 {
        let nx = next_item_size as f64;
        if (post_residual as f64) < nx {
            let waste = nx - post_residual as f64;
            score += 6.0 * (waste / cap) * (1.0 + progress);
        } else {
            // Reward residuals that can exactly accommodate the lookahead item.
            let diff = post_residual as f64 - nx;
            score -= 4.0 * (1.0 - (diff / cap).min(1.0)) * (1.0 - progress);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0 * (1.0 + progress);
    }

    // Mild preference for consolidating into fewer bins as stream progresses.
    let openness = open_bins_count as f64 / (1.0 + open_bins_count as f64);
    score += 3.0 * openness * pr_norm * (1.0 - progress);

    // Smooth deviation from mean residual: prefer bins whose residual is near mean.
    let dev = (pr - mean_residual) / cap;
    score += 2.0 * dev * dev * cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let next = next_item_size as f64;

    // ---- Harmonic class of post_residual (mod-based dead-space classes) ----
    // Residuals in small classes are "dead space" magnets; penalize them.
    let mod10 = post_residual % 10;
    let mod20 = post_residual % 20;
    // Tiny unusable residues are worst (nothing 1..100 may come... but small items exist)
    if post_residual == 0 {
        score -= 40.0; // perfect fit: golden
    } else {
        // harmonic penalty: smaller residual classes are harder to fill
        let class_penalty = (10 - mod10.min(10 - (10 - mod10) % 10)) as f64; // distance to nearest decade multiple
        score += class_penalty * 0.8;
        if mod20 == 0 { score -= 6.0; } // round residuals pair well with mid items
    }

    // ---- Fraction-of-capacity harmonic bands ----
    let frac = post / cap;
    if frac < 0.1 { score += 12.0; }        // nearly-full bin, tiny residue risk
    else if frac < 0.3 { score += 4.0; }    // awkward band
    else if frac < 0.6 { score -= 3.0; }    // comfortable band
    else { score -= 1.0; }                  // roomy bin

    // ---- Lookahead coupling: does next item fit the post residual? ----
    if next > 0.0 {
        if next <= post {
            score -= 10.0; // chain fit: excellent
            // bonus if next exactly exhausts
            if next == post { score -= 8.0; }
        } else {
            // penalty scaled by how much next overshoots
            let over = (next - post) / cap;
            score += over * 15.0;
        }
    }

    // ---- Last-chance logic: this is the only fitting bin ----
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0; // strongly prefer using the only bin that fits
    }

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        // New bin is attractive only if item is large; opening a fresh bin for
        // large items preserves flexibility of open bins.
        let large = item / cap; // item fraction of capacity
        // Baseline: new bin has post_residual = cap - item, already in score.
        // Reward opening new bins when existing fits are tight/wasteful:
        if fitting_bins_count > 0 {
            // how wasteful would the best existing fit be? approximate via mean residual
            let waste = (mean_residual - item).max(0.0);
            if waste > 20.0 || item >= 50.0 {
                score -= 8.0 + 10.0 * large; // favor fresh bin
            } else {
                score += 6.0; // prefer reusing open bins for small items
            }
        } else {
            score -= 20.0; // no alternative: must open
        }
        // late in stream, consolidate rather than open
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 4.0;
    }

    // ---- Open-bin pressure: many open bins -> prefer filling existing ones ----
    if open_bins_count > 3 {
        score -= 1.5 * (open_bins_count.min(20) as f64).sqrt();
    }

    // ---- Mean-residual alignment: prefer bins near the mean (balanced filling) ----
    score -= 0.5 * (1.0 - ((post - mean_residual).abs() / cap).min(1.0));

    // ---- Integer-division threshold on item size (harmonic size classes) ----
    match item_size / 10 {
        0 => score += 2.0,   // tiny item: very flexible, mild penalty for spending a roomy bin
        1..=3 => score += 1.0,
        4..=6 => score -= 0.5,
        _ => {} // large items: neutral, they mostly define the bin
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is ideal
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A gap is "unusable" if smaller than the minimum conceivable item (1..~12).
    let dead_zone = 12.0f64;
    if post_residual > 0 && (post_residual as f64) < dead_zone {
        score += (dead_zone - post_residual as f64) * 8.0; // up to ~96 penalty
    }

    // Coupling: dead space is worse when few bins are open (less slack elsewhere)
    let pressure = 1.0 + (open_bins_count as f64).ln().max(0.0) * 0.15;
    score *= pressure;

    // Reward using a bin whose residual was already small (tight packing)
    let tightness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= tightness * 25.0;

    // Last chance bin: strongly favor using it instead of opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        let mean_gap = mean_residual - item_size as f64;
        // Penalize new bin when existing bins would leave similar or less waste
        if mean_gap >= 0.0 {
            score += 40.0 + mean_gap * 0.5;
        }
        // Early in stream, opening bins is cheap; late, prefer consolidation
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 30.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward it
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 90.0;
        } else if next_item_size > post_residual {
            // next item won't fit here; a small post_residual wastes it anyway
            score += (next_item_size - post_residual) as f64 * 0.1;
        }
    }

    // Mild preference to fill bins with larger mean residuals first
    score += (mean_residual - post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Near-match: small gap between post_residual and next item size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if gap > 0.0 {
            // Penalize unusable slivers: residual smaller than min item size is dead space.
            if post_residual < 10 {
                score += 25.0;
            }
            // Reward closeness to next item size (soft matching).
            score -= (20.0 / (1.0 + gap * 0.35)).min(18.0);
        }
    }

    // Compare against mean residual: prefer bins tighter than average.
    score -= (mean_residual - post_residual as f64) * 0.35;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when no good fit exists (large post_residual waste elsewhere).
    if bin_residual == bin_capacity {
        let waste_pressure = (mean_residual - (bin_capacity - item_size) as f64).max(0.0);
        score += 8.0 + waste_pressure * 0.5;
        if next_item_size > 0 && (bin_capacity - item_size) as i64 == next_item_size as i64 {
            score -= 55.0; // fresh bin perfectly fits the lookahead item too
        }
    }

    // Late in the stream: consolidate harder, penalize leaving many loose residuals.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (open_bins_count as f64).ln().max(0.0) * 0.4;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: fractional fill of the bin.
    let fill = item_size as f64 / bin_residual as f64;
    score -= fill * 12.0;

    // Penalize small unusable post-residuals (dead space), reward medium residuals
    // that can still host future items.
    if post_residual > 0 {
        let r = post_residual as f64;
        if r < 10.0 {
            score += (10.0 - r) * 2.5; // tiny dead slivers are wasted
        } else {
            score -= r * 0.15; // usable leftover is good
        }
    } else {
        score -= 30.0; // perfect closure of a bin is excellent
    }

    // Lookahead: if next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            let next_fit = next_item_size as f64 / post_residual as f64;
            score -= next_fit * 8.0;
        } else {
            // next item won't fit here; slight penalty if post_residual is small
            score += (next_item_size as f64 - post_residual as f64).min(20.0) * 0.3;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a fresh bin should only win when the
    // current item fits poorly everywhere. Penalize the fresh bin moderately,
    // scaled by how many open bins exist and how full the stream is.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 + open_bins_count as f64 * 1.5 + progress * 5.0;
        // But if the item is huge relative to mean residual space, opening a new
        // bin may be wise: relax the penalty.
        if item_size as f64 > mean_residual {
            score -= (item_size as f64 - mean_residual) * 0.4;
        }
    }

    // Prefer bins with below-mean residual (fill the emptier bins first),
    // keeping tight bins for later.
    score += (bin_residual as f64 - mean_residual) * 0.1;

    // Mild preference for using existing bins as stream progresses (consolidation).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= progress * 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Non-linear coupling: waste penalized more strongly as stream progresses
    let waste_penalty = norm_pr * norm_pr * (1.0 + 2.0 * progress) * cap * 0.5;
    score += waste_penalty;

    // Tight fits (small post_residual) rewarded with smooth cubic term
    let tight_reward = (1.0 - norm_pr).powi(3) * cap * (0.3 + 0.4 * progress);
    score -= tight_reward;

    // Last-chance bin: strongly favor using it (avoid opening new bin)
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= cap * (0.8 + 0.6 * progress);
    }

    // Lookahead: reward bins whose post-residual matches next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs();
        if pr >= nxt {
            score -= (1.0 - gap / cap).powi(2) * cap * 0.4;
        } else {
            score += gap * 0.1;
        }
    }

    // Deviation from mean residual: prefer bins near the mean (balance)
    let dev = (pr - mean_residual).abs() / cap;
    score += dev * dev * cap * 0.3;

    // Many open bins: mild penalty to avoid bin proliferation
    score += (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);

    // New-bin candidate: make it attractive only for large items / bad fits
    if bin_residual == bin_capacity {
        let big = item_size as f64 / cap;
        score = cap * (1.2 - 0.9 * big * big) - cap * 0.5 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: prefer residuals that lie in
    // "usable" classes (multiples of common item sizes) and penalize
    // awkward remainders via modulo arithmetic.
    let cap = bin_capacity as f64;

    // Fraction of capacity consumed by this placement.
    let fill_frac = item_size as f64 / cap;
    score -= 25.0 * fill_frac;

    // Dead-space penalty: small post-residuals that are too small for the
    // smallest plausible item (<= 10) are wasted; big residuals are fine.
    if post_residual < 10 && post_residual > 0 {
        score += 40.0; // unusable sliver
    }

    // Harmonic class reward: post_residual divisible by 10 (typical size quantum)
    let pr = post_residual as i64;
    if pr % 10 == 0 {
        score -= 6.0;
    } else if pr % 5 == 0 {
        score -= 2.0;
    } else {
        score += 3.0;
    }

    // Modulo-class coupling with next item: if the next item can exactly
    // fit the post-residual, this is a perfect harmonic pairing.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            // reward tight-but-feasible follow-ups, penalize large slack
            score -= 12.0 * (1.0 - slack as f64 / cap);
            if slack % 10 == 0 {
                score -= 4.0;
            }
        } else {
            // next item cannot follow into this bin: mild penalty scaled
            // by how much of the residual would be stranded
            score += 8.0 * (next_item_size - post_residual) as f64 / cap;
        }
    }

    // Integer-division thresholds on residual classes
    let residual_class = post_residual / 25; // 0..4 quartile class
    score += match residual_class {
        0 => -5.0,  // nearly full bin: excellent packing
        1 => 0.0,   // quarter left: neutral
        2 => 2.0,   // half left: slightly worse
        3 => 4.0,   // mostly empty
        _ => 6.0,   // untouched bin
    };

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive
    // when current item is large and mean residual across open bins is low.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mean_tightness = 1.0 - (mean_residual / cap);
        // Reward new bin when open bins are collectively tight and item is big
        score -= 20.0 * mean_tightness * fill_frac;
        // Penalize proliferation of open bins as stream progresses
        score += (open_bins_count as f64).sqrt() * 3.0 * (0.5 + 0.5 * progress);
    } else {
        // Mild pressure toward consolidation when many bins are open
        score += (open_bins_count as f64).sqrt() * 0.5;
    }

    // Early stream: be a bit greedy filling bins tightly; late stream: consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * (1.0 - progress) * (1.0 - post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (1..100)
    // are pure waste; penalize them super-linearly.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    }
    // Post-residuals that can still host the smallest items are "alive" space.
    if post_residual >= 10 {
        score -= 12.0;
        // Extra reward when the residual can still host the lookahead item.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 18.0;
        }
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Tightness coupling: reward filling a large fraction of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill_ratio * fill_ratio;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage opening a new one
    // and encourage consolidating into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline near capacity, penalized by pressure
        // unless the fit elsewhere would be terrible.
        score = bin_capacity as f64 - 5.0 + 10.0 * pressure;
        // Allow new bin late in the stream when mean residual is small.
        if mean_residual < 8.0 && fitting_bins_count <= 1 {
            score -= 25.0;
        }
    } else {
        score -= 3.0 * pressure.min(15.0);
    }

    // Prefer bins with below-average residual (denser bins first) mildly.
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact 2-step lookahead match: post_residual == next_item_size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 45.0;
    }

    // Reward near-matches with the lookahead item (soft coupling)
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 20.0 * (-slack / 12.0).exp();
    }

    // Penalize post_residual that is too small for the next item (dead space risk)
    if next_item_size > 0 && post_residual < next_item_size {
        score += 0.6 * (next_item_size - post_residual) as f64;
    }

    // Prefer bins tighter than the mean residual (compact packing)
    score -= 0.35 * (mean_residual - post_residual as f64);

    // Last-chance bonus: only one fitting bin -> strongly favor using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalize opening a new bin, unless it enables a perfect 2-step chain
    if bin_residual == bin_capacity {
        let perfect_chain = next_item_size > 0 && post_residual == next_item_size;
        if perfect_chain {
            score -= 30.0;
        } else {
            score += 18.0 + 2.0 * open_bins_count as f64;
        }
    }

    // Mild late-stream tightening: waste matters more as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * post_residual as f64 * 0.25;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: penalize large post-residual non-linearly.
    let frac_used = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * frac_used * frac_used;

    // Perfect / near-perfect fill bonus.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 30.0;
    }

    // Dead space penalty: small unusable leftovers.
    if post_residual > 0 && post_residual < item_size.min(20) {
        score += 12.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Lookahead: if next item fits in the post-residual, reward saving this bin's leftover.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
        } else {
            // leftover too small for the next item: penalize wasted space
            score += 8.0;
        }
    }

    // New-bin candidate handling: only attractive when open bins fit poorly.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let pressure = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
        let progress = step_index as f64 / total_items.max(1) as f64;
        let good_fit_exists = fitting_bins_count > 0 && post_residual == 0; // fresh bin: post_residual == capacity - item
        let mut nb = 25.0 * pressure + 20.0 * progress;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            nb -= 10.0;
        }
        if fitting_bins_count <= 1 && !good_fit_exists {
            nb -= 35.0;
        }
        score += nb;
    }

    // Prefer bins with below-average residual (fill fuller bins first, keep slack spread).
    let mean_gap = mean_residual - post_residual as f64;
    score += 0.15 * mean_gap;

    // Mild preference for bins whose residual is close to the item (best-fit flavor).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += 0.1 * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    let mut score = pr;

    // Non-linear coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * progress;
    score += 40.0 * poly;

    // Reward tight fits, more so late in the stream
    let tightness = 1.0 - norm_pr;
    score -= 60.0 * tightness * tightness * (0.5 + progress);

    // Penalize residual that is small but unusable by next item
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0 * (1.0 - progress);
    }
    // Reward residual that exactly accommodates the next item
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0 * (0.5 + progress);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: penalize unless current open bins are nearly full
    if bin_residual == bin_capacity {
        let crowding = open_bins_count as f64 / (1.0 + mean_residual);
        score += 15.0 + 20.0 / (1.0 + crowding);
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
    }

    // Mild preference for bins whose residual deviates from mean (consolidation)
    score += 0.05 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: how it splits into capacity fractions
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    let class = post_residual / eighth; // 0..8 integer division class

    // Reward small post-residuals strongly (tight fits)
    let class_reward: f64 = match class {
        0 => 40.0, // residual < 12.5: near-perfect fill
        1 => 22.0,
        2 => 10.0,
        3 => 2.0,
        4 => -6.0, // half-full leftover: versatile, mildly favored
        5 => -2.0,
        6 => 6.0,
        7 => 14.0,
        _ => 0.0,
    };
    score -= class_reward;

    // Modulo coupling: post_residual congruence with next_item_size.
    // If next item could exactly fill leftover, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain fill
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / cap);
        } else {
            // next item can't use this residual: penalize by wasted potential
            score += 8.0 * (next_item_size as f64 - post_residual as f64) / cap;
        }
        // harmonic congruence: residual mod next_item_size small => dense future packing
        if next_item_size > 0 && post_residual % next_item_size == 0 && post_residual > 0 {
            score -= 10.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize unless current bins are crowded or fit is bad
    if bin_residual == bin_capacity {
        let crowding = open_bins_count as f64;
        let mean_tightness = 1.0 - mean_residual / cap; // 0 = empty-ish bins, 1 = full bins
        let pressure = mean_tightness * crowding.sqrt();
        // default new bin is expensive; discount when pressure is high
        score += 35.0 - 20.0 * (pressure / (pressure + 3.0));
        // if item is large, new bin placement is more acceptable
        score -= (item_size as f64 / cap) * 12.0;
    }

    // Progress-based annealing: late in stream, prefer tighter fills / reuse
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (post_residual as f64) * 0.15;

    // Mean-residual coupling: if this bin's residual is below mean, it's a scarce slot
    let res_f = bin_residual as f64;
    if res_f < mean_residual {
        score -= 6.0 * (mean_residual - res_f) / cap;
    } else {
        score += 3.0 * (res_f - mean_residual) / cap;
    }

    // Penalize leaving dead space in the awkward 1..eighth band when no chain is possible
    if class == 0 && next_item_size > post_residual {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize dead space: small post_residual gaps that likely cannot fit future items.
    let min_item = 1.0f64;
    if (post_residual as f64) < min_item {
        score += 1000.0; // exact overflow guard (shouldn't happen)
    }

    // Strict dead-space avoidance: gaps too small to hold anything useful are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 25 {
        // Moderately bad: fits only tiny items.
        score += 25.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 80.0;
    }

    // Reward keeping residual usable for the lookahead item (k=2).
    if next_item_size > 0 {
        if post_residual >= next_item_size as f64 {
            score -= 15.0 + 0.25 * next_item_size as f64;
        } else if post_residual > 0 {
            // Gap cannot serve the next item: penalize proportionally to wasted potential.
            score += 0.35 * (post_residual as f64);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bins pressure: with many open bins, prefer consolidating into existing bins.
    let open_pressure = open_bins_count as f64;
    if bin_residual != bin_capacity {
        score -= 0.8 * open_pressure;
    } else {
        // New-bin candidate: penalize more as open bins grow, unless item is large.
        score += 5.0 + 0.5 * open_pressure - 0.05 * item_size as f64;
    }

    // Mean residual coupling: prefer bins whose residual is close to the item (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += 0.2 * tightness;

    // Prefer bins with residual below mean (more crowded bins absorb items well).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // Slight late-stream consolidation bias.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual != bin_capacity {
        score -= 10.0 * progress;
    } else {
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post residual exactly fits next item
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 200.0;
    }

    // Near match: next item fits with small leftover
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 60.0 - slack.min(60.0);
    }

    // Dead space: post residual too small for any future item (min size 1, typical small)
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        // unusable for the lookahead item -> penalize proportionally to wasted fraction
        score += 25.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Zero residual is perfect packing
    if post_residual == 0 {
        score -= 150.0;
    }

    // Last chance: only this bin can fit the item
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // New-bin candidate: only open it when no open bin offers a decent fit
    if bin_residual == bin_capacity {
        // prefer reusing bins unless this is a terrible fit situation
        score += 40.0;
        if next_item_size > 0 && item_size > bin_capacity / 2 {
            score -= 10.0;
        }
        if open_bins_count == 0 {
            score -= 500.0;
        }
    }

    // Compare against mean residual: bins with residual close to mean are average choices
    score += 0.1 * (bin_residual as f64 - mean_residual);

    // Slight preference late in the stream to close bins tightly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 3.0 * fill_ratio * fill_ratio * bin_residual as f64;

    // Penalize dead space that no plausible future item (min size 1, typical >=10) can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: reward bins whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.15 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        // Post-residual stranded relative to lookahead: penalize proportionally.
        score += 0.3 * post_residual as f64;
    }

    // Perfect-fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: if this is the only bin that fits, use it rather than open a new one
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0 + 0.2 * fill_ratio * 100.0;
    }

    // New-bin candidate handling: discourage opening a new bin when open bins fit well,
    // encourage it when open bins are fragmented.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let fragmentation = mean_residual / bin_capacity as f64;
        // New bin is attractive when mean residual is high (fragmented) or few bins open.
        score -= 20.0 * fragmentation + 5.0 * (1.0 - progress);
        // But if many bins are already open, prefer consolidating.
        score += 0.5 * open_bins_count as f64;
        // If next item is large and current bins are tight, new bin is good.
        if next_item_size > 60 && mean_residual < next_item_size as f64 {
            score -= 10.0;
        }
    }

    // Mild preference for bins below mean residual (consolidate emptier bins first).
    score += 0.1 * (mean_residual - bin_residual as f64).max(-30.0).min(30.0);

    // Late-stream pressure: as stream ends, avoid leaving many tiny residuals.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * 0.05 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    let mut score = pr;

    // Non-linear coupling: quadratic in normalized post residual modulated by stream progress
    score += 40.0 * norm_pr * norm_pr * (0.5 + 0.5 * progress);

    // Reward tight fits: cubic decay of post residual
    score -= 30.0 * (1.0 - norm_pr).powi(3) * (1.0 - progress);

    // Penalize post residual that cannot fit the next item (dead space)
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0 + 18.0 * (next_item_size as f64 - pr) / cap;
    }
    // Reward post residual that exactly or nearly fits next item
    if next_item_size > 0 && pr >= next_item_size as f64 {
        let diff = pr - next_item_size as f64;
        score -= 15.0 * (1.0 - diff / cap).powi(2);
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 10.0;
    } else if fitting_bins_count > 2 {
        score += 3.0 * (fitting_bins_count as f64 - 2.0).sqrt();
    }

    // Mean residual coupling: prefer bins deviating from mean residual smoothly
    score += 8.0 * (pr - mean_residual).abs() / cap * (0.5 + progress);

    // New-bin candidate: penalize mildly unless current bin would leave bad residue
    if bin_residual == bin_capacity {
        let waste = (cap - norm_item * cap) / cap;
        score = cap * (0.6 + 0.4 * progress) + 25.0 * waste * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post-residual: residue classes mod 10 ---
    // Residuals that are "nice" (multiples of common item sizes) are less dead.
    let class = post_residual % 10;
    let harmonic_bonus = match class {
        0 => 8.0,                 // perfect harmonic residual
        5 => 4.0,                 // half-class
        2 | 4 | 6 | 8 => 2.0,     // even class
        _ => 0.0,                 // odd, awkward class
    };
    score -= harmonic_bonus;

    // Integer-division threshold: how many "average" items (size ~25) still fit
    let fits_k = post_residual / 25;
    score -= fits_k as f64 * 6.0;

    // --- Lookahead coupling: does next_item_size fit exactly into post_residual? ---
    if next_item_size > 0 && next_item_size <= post_residual {
        // Exact match is gold: residual mod next_item_size == 0
        if post_residual % next_item_size == 0 {
            score -= 15.0;
        } else {
            score -= 5.0;
        }
        // Partial harmonic: next item leaves a multiple-of-10 remainder
        if (post_residual - next_item_size) % 10 == 0 {
            score -= 4.0;
        }
    } else if next_item_size > post_residual && next_item_size > 0 {
        // Next item won't fit here; residual becomes dead unless class is harmonic
        score += 3.0;
        if class != 0 {
            score += 2.0;
        }
    }

    // --- Last-chance bin: strongly favor using it to avoid opening a new bin ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Prefer new bin when current item would leave a badly non-harmonic residual
        // and existing bins are already tight (mean_residual low).
        let awkward = if class != 0 && post_residual < 10 { 25.0 } else if class != 0 { 10.0 } else { 0.0 };
        score += awkward;
        // Late in the stream, consolidate more: penalize opening new bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 12.0;
        // Many open bins already: discourage spreading
        score += open_bins_count as f64 * 0.5;
    }

    // --- Tight-fit reward: item fills most of the bin ---
    let fill = item_size as f64 / bin_capacity as f64;
    if fill > 0.7 {
        score -= 6.0 * fill;
    }

    // Deviation from mean residual: prefer bins whose residual is close to item size
    let dev = (bin_residual as f64 - item_size as f64 - mean_residual).abs();
    score += dev * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the lookahead item are wasted.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 40.0 + (next_item_size - post_residual) as f64 * 0.5;
    }

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward very tight fits (post_residual tiny relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 20.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: penalize opening a new bin, more so when many bins are open.
    if bin_residual == bin_capacity {
        score += 25.0 + open_bins_count as f64 * 1.5;
        // But if existing fits are all poor (high mean residual dispersion), new bin is fine.
        if mean_residual < 15.0 {
            score -= 20.0;
        }
    } else {
        // Mild reward for consolidating into existing bins early in the stream.
        score -= 5.0;
    }

    // Late in the stream, prefer closing out bins tightly (less future waste matters).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_capacity - post_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> huge reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    // Near-match lookahead: reward small gap between post_residual and next_item_size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 / (1.0 + gap);
        // If next item fits exactly into post residual region, extra bonus.
        if post_residual >= next_item_size {
            score -= 20.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        }
