    // Penalize dead space: post_residual too small to fit any plausible item (min size 1, typical 10).
    if post_residual < 10 && post_residual > 0 {
        score += 60.0;
    }

    // Penalize very large post_residual relative to mean residual (wasteful big-bin use).
    if post_residual as f64 > mean_residual * 1.5 {
        score += (post_residual as f64 - mean_residual) * 0.5;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize slightly so it is only chosen when open bins are truly poor.
    if bin_residual == bin_capacity {
        score += 30.0;
        // But if lookahead suggests a fresh bin helps (next item large, current item small), relax.
        if next_item_size > 0 && next_item_size + item_size > bin_capacity {
            score -= 45.0;
        }
    }

    // Late in stream: tighten packing, prefer tighter residuals.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: the smaller the post_residual relative to capacity, the better.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 2.0 * tightness * item_size as f64;

    // Penalize dead space that no future item (size >= 10) could ever use.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Lookahead: strongly reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0 + 0.25 * next_item_size as f64;
        } else {
            score += 8.0;
        }
        // Perfect pairing: item + next item exactly fills the bin.
        if post_residual == next_item_size {
            score -= 30.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Fragmentation penalty: leaving residuals far from mean residual wastes space
    // across the fleet; deviating upward creates outliers.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // When many bins are open, prefer consolidating into fuller bins to close them out.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
    score += 0.05 * pressure * (1.0 - tightness);

    // New-bin candidate handling: an empty bin is only attractive when no open bin
    // offers a decent fit (post_residual would be small) or fleet is saturated.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 60.0;
        // Reduce cost late in the stream (less future to fragment) or when open
        // bins are nearly full on average.
        score -= 40.0 * progress;
        score -= 0.3 * mean_residual;
        // If existing fits are terrible (large post_residual everywhere), opening
        // fresh becomes competitive: emulate by comparing against item fit quality.
        let bad_fit_threshold = bin_capacity as f64 * 0.6;
        if post_residual as f64 > bad_fit_threshold {
            score -= 45.0;
        }
        // Small items start new bins cheaply (they leave versatile residuals).
        if item_size <= 30 {
            score -= 10.0;
        }
    }

    // Mild bonus for filling more than half the bin in one shot.
    if item_size as f64 > 0.5 * bin_capacity as f64 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: penalize leftover residual, scaled non-linearly by stream progress.
    let mut score = pr * (1.0 + 0.75 * progress * progress);

    // Smooth polynomial coupling: large residuals matter more later in the stream.
    let quad = pr_norm * pr_norm * (0.5 + 2.0 * progress);
    score += quad * cap;

    // Reward tight fits (small post_residual) with a smooth saturating bonus.
    let tightness = 1.0 - pr_norm;
    score -= 12.0 * tightness * tightness * (1.0 + 0.5 * progress);

    // Penalize wasting a near-full bin on a small item when residual could serve later.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let wasted_fit = (nxt - pr).max(0.0) as f64;
        score += 0.35 * wasted_fit * (1.0 + progress);
        // Reward when post_residual exactly accommodates the next item.
        let gap = (pr - nxt).abs();
        score -= 8.0 * (1.0 - gap / cap).max(0.0) * (pr >= nxt) as i32 as f64;
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0 * (1.0 + progress);
    }

    // Many open bins: mild pressure to consolidate into existing bins.
    score -= 0.15 * open_bins_count as f64 * (1.0 - pr_norm);

    // New-bin candidate: make empty bins moderately attractive only for poor fits.
    if bin_residual == bin_capacity {
        score += 6.0 + 4.0 * progress - (item_size as f64 / cap) * 10.0;
    }

    // Mean-residual coupling: prefer bins deviating favorably from the mean.
    score += 0.1 * (mean_residual - pr).abs() * (pr < mean_residual) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover: leftover divisible by common item sizes is "reusable".
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else {
        // mod-10 class: leftover in {10,20,...} is friendly to 10-multiple streams
        let m10 = pr % 10;
        score += m10 as f64 * 1.5;
        // small dead space is bad: penalize leftovers that no item (>=1) of typical size fits well
        if pr < 10 {
            score += 40.0;
        }
        // leftover exactly matching next item is golden
        if next_item_size > 0 && next_item_size == pr {
            score -= 55.0;
        }
        // leftover can hold next item with small slack
        if next_item_size > 0 && pr >= next_item_size {
            let slack = pr - next_item_size;
            score -= 25.0;
            score += (slack % 10) as f64 * 0.8;
        }
        // integer-division thresholds: classify leftover by capacity fractions
        let half = bin_capacity / 2;
        let quarter = bin_capacity / 4;
        if pr >= half {
            score -= 15.0; // roomy bin, still flexible
        } else if pr >= quarter {
            score -= 5.0;
        } else {
            score += 8.0; // cramped
        }
        // harmonic class: leftover % 25 (capacity/4) structure
        let m25 = pr % 25;
        score += if m25 == 0 { -12.0 } else { m25 as f64 * 0.4 };
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when no good open fit exists
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // penalize opening new bins early / when many open bins exist
        score += 45.0;
        score += open_bins_count as f64 * 2.0;
        // but if item is huge and residual tightness elsewhere is high, allow it
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if item_size >= bin_capacity * 3 / 4 {
            score -= 20.0 * progress;
        }
        // if next item is also huge, a fresh bin is better than fragmenting
        if next_item_size >= bin_capacity * 3 / 4 && bin_residual - item_size < next_item_size {
            score -= 35.0;
        }
    }

    // tightness reward: prefer bins whose residual is close to item size (good fill)
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score += tightness * 20.0;

    // mean-residual coupling: if this bin is far below mean residual, it's a straggler — use it
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score -= dev * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no item can use are pure waste.
    // Items are >= 1, but typical small items ~10; treat gaps < 10 as dead unless tiny.
    let dead = if post_residual == 0 {
        0.0
    } else if post_residual < 10 {
        12.0 // unusable sliver
    } else {
        0.0
    };
    score += dead;

    // Reward near-exact fits (tight packing).
    if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 15 {
        score -= 8.0;
    }

    // Penalize creating gaps that can't fit the lookahead item (wasted for k=2).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0 + 0.25 * (post_residual as f64);
    }
    // Reward leaving exactly the lookahead size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, prefer filling existing.
    let pressure = (open_bins_count as f64).ln().max(0.0) * 4.0;
    if bin_residual != bin_capacity {
        score -= pressure * (item_size as f64 / bin_capacity as f64);
    } else {
        // New-bin candidate: make it attractive only when current bins are nearly full
        // or item is large and fits nowhere well.
        score += pressure;
        score += 10.0 * (mean_residual / bin_capacity as f64);
        if item_size > 60 {
            score -= 8.0;
        }
    }

    // Early in stream, be slightly more willing to open bins for large items.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity && progress < 0.2 && item_size > 50 {
        score -= 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }
    // Near match: next item fits into post_residual -> mild reward scaled by tightness.
    else if next_item_size > 0 && post_residual >= next_item_size {
        let tightness = next_item_size as f64 / post_residual as f64;
        score -= 25.0 * tightness;
    }
    // Next item cannot fit: post_residual becomes dead space -> penalty grows with wasted space.
    else if next_item_size > 0 {
        score += 0.5 * post_residual as f64;
    }

    // Reward bins tighter than the fleet mean (good fills), penalize loose bins.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Late in the stream, consolidation matters more.
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    score *= 1.0 + 0.2 * progress;

    // Never prefer a fresh bin when a decent fit exists in an open bin.
    if bin_residual == bin_capacity {
        score += 10.0 + 0.5 * item_size as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize residual that cannot hold typical items.
    if post_residual < 10 {
        score -= 60.0; // near-perfect fill
    } else if post_residual <= 20 {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly in the post-residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 90.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here; mildly penalize large post-residual
            score += 0.1 * (post_residual as f64 - next_item_size as f64).min(40.0);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 0.3 * item_size as f64;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing residuals are fragmented or the item is huge.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual - post_residual as f64).abs();
        let pressure = if open_bins_count > 0 {
            (open_bins_count as f64).ln().max(1.0)
        } else {
            1.0
        };
        // Base cost of a fresh bin; discount when item is large (hard to place)
        // or mean residual across bins is small (bins are nearly full anyway).
        let mut new_bin_cost = 45.0 + 10.0 * pressure - 0.25 * item_size as f64;
        new_bin_cost += 0.2 * mean_residual.min(80.0); // opening wastes mean_residual potential
        new_bin_cost -= 20.0 * progress; // late in stream, prefer consolidation less
        score += new_bin_cost.max(5.0);
        // If no other bin could even be fragmented better, slight nudge
        if fragmentation < 5.0 {
            score += 10.0;
        }
    } else {
        // Reusing an open bin: reward proportional to how much dead space is avoided
        // relative to current mean residual.
        let waste_vs_mean = mean_residual - post_residual as f64;
        if waste_vs_mean > 0.0 {
            score -= 0.35 * waste_vs_mean.min(50.0);
        }
    }

    // Penalize leaving residuals in the "dead zone" (11..=19) that few items fill.
    if post_residual >= 11 && post_residual <= 19 {
        score += 12.0;
    }

    // Small global-state coupling: many open bins -> favor consolidation.
    if open_bins_count > 4 && bin_residual != bin_capacity {
        score -= 0.5 * (open_bins_count as f64).min(20.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let pr = post_residual as f64 / bin_capacity as f64;
    let coupling = pr * pr * (0.5 + progress) * 40.0 + pr * (1.0 - progress) * 15.0;
    score += coupling;

    // Reward perfect/near-perfect fills (small post_residual) more aggressively later in stream.
    score -= (1.0 - pr) * (1.0 - pr) * (20.0 + 30.0 * progress);

    // Lookahead: strongly reward bins whose post_residual can fit the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let snug = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 25.0 * snug * (0.6 + 0.4 * progress);
    } else if next_item_size > 0 {
        // Penalize dead space that cannot fit the lookahead item, scaled by dead-space size.
        let dead = (post_residual.min(next_item_size.saturating_sub(1)).max(0)) as f64;
        score += 0.15 * dead * (1.0 + progress);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0 * (0.5 + 0.5 * progress);
    }

    // New-bin candidate: penalize opening a new bin unless it is genuinely better
    // (e.g., few fitting bins or current bin residual is a bad fit).
    if bin_residual == bin_capacity {
        let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
        let waste = (bin_residual - item_size) as f64 / bin_capacity as f64;
        score += 10.0 + 60.0 * (1.0 - scarcity) - 40.0 * waste * (0.3 + 0.7 * progress);
        // Late in the stream, prefer consolidating into open bins.
        score += 20.0 * progress;
    }

    // Mild preference toward bins deviating from mean residual (tighter bins first).
    score += 0.1 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues modulo 10 define "usable" classes.
    let r = post_residual % 10;
    // Residuals near multiples of 10 are more likely reusable (typical item sizes are
    // multiples of 10 or small); penalize awkward residues.
    let residue_penalty = match r {
        0 => -12.0,
        1 | 9 => 6.0,
        2 | 8 => 3.0,
        3 | 7 => 0.0,
        4 | 6 => -2.0,
        _ => 1.5,
    };
    score += residue_penalty;

    // Integer-division thresholds: how many "medium chunks" (size 25) still fit.
    let chunks = post_residual / 25;
    score -= chunks as f64 * 4.0;

    // Lookahead coupling: reward if the next item fits exactly into the post residual,
    // or into a harmonic class of it.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0; // perfect follow-up fit
        } else if next_item_size <= post_residual {
            let gap = post_residual - next_item_size;
            score -= 10.0 * (1.0 - gap as f64 / cap);
            // harmonic class match: next item leaves again a multiple-of-10 residue
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 8.0;
            }
        } else {
            // next item cannot use this bin's remainder: slight penalty scaled by waste
            score += (next_item_size - post_residual) as f64 * 0.05;
        }
    }

    // Fractional fill: prefer bins that become proportionally fuller.
    let fill = (bin_capacity - post_residual) as f64 / cap;
    score -= fill * fill * 10.0;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && post_residual <= bin_capacity / 2 {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin is a fresh harmonic canvas; only
    // prefer it when existing residuals are poorly classed (high mean residual
    // with bad residue) or late in the stream.
    if bin_residual == bin_capacity {
        let mean_bad = if mean_residual % 10.0 >= 5.0 { 1.0 } else { 0.0 };
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = cap * 0.5
            + mean_residual * 0.4
            + mean_bad * 10.0
            + open_bins_count as f64 * 2.0
            - progress * 5.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
    }

    // Slight preference for tighter bins among equals via mean residual coupling.
    if (post_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are the worst outcome.
    // A residual that is too small to hold even the minimum item (1) is pure loss,
    // and residuals below the lookahead item are semi-dead for the next step.
    if post_residual == 0 {
        // Perfect fit: strongly reward.
        score -= 1000.0;
    } else {
        let pr = post_residual as f64;
        // Dead-space curve: penalty peaks for tiny unusable gaps.
        if post_residual < next_item_size && next_item_size > 0 {
            score += 60.0 * (1.0 - pr / 100.0);
        }
        // Non-linear waste pressure: small residuals penalized super-linearly.
        score += 200.0 / (pr + 2.0);
    }

    // Reward bins whose residual is close to the item (tight fit quality).
    let tightness = 1.0 - (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score -= 30.0 * tightness * tightness;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Open-bin pressure: prefer filling existing bins when many are open.
    score += open_bins_count as f64 * 2.0;

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 150.0;
    }

    // Slight late-stream conservatism: fill bins more aggressively as stream ends.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 20.0 * progress;

    // New-bin candidate: penalize mildly so it's only chosen when fits are terrible.
    if bin_residual == bin_capacity {
        score += 40.0 + mean_residual * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core 2-step lookahead: reward bins whose post_residual exactly matches the next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match for next item is highly desirable
        if post_residual == next_item_size {
            score -= 45.0;
        } else {
            score += diff * 0.55;
        }
        // Penalize leaving a residual that the next item cannot fit into at all
        // but which is too small to be useful (dead space window)
        if post_residual > 0 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.35;
        }
        // Bonus: residual can hold next item AND still leave usable space
        if post_residual >= next_item_size + 10 {
            score -= 8.0;
        }
    } else {
        // Last item: prefer tightest fit only
        score += 0.0;
    }

    // Relative-to-mean coupling: bins with residual far below mean are "scarce space",
    // using them for a tight fit is good; opening them wastefully is bad.
    let res = post_residual as f64;
    let mean_gap = res - mean_residual;
    score += mean_gap * 0.30;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin should only win when no open bin
    // fits well. Penalize the fresh bin, but less when open bins are nearly full.
    if bin_residual == bin_capacity {
        let avg_open_fullness = (bin_capacity as f64 - mean_residual).max(0.0);
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Base penalty for opening a new bin
        let mut new_bin_penalty = 30.0;
        // If open bins are crowded (low mean residual), a new bin is more acceptable
        new_bin_penalty -= avg_open_fullness * 0.25;
        // Early in the stream, slightly prefer consolidating; late, accept new bins
        new_bin_penalty += (1.0 - progress) * 10.0;
        // If nothing else fits (fitting_bins_count == 0 among open bins), the new bin
        // must be chosen: remove the penalty.
        if fitting_bins_count == 0 {
            new_bin_penalty = -10.0;
        }
        score += new_bin_penalty;
    }

    // Mild penalty for leaving large awkward residuals that few items can use
    if post_residual > 0 && post_residual < 10 {
        score += 12.0; // tiny dead space is wasted capacity
    }

    // Slight preference for bins that are already well-filled (tight packing)
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= fill_ratio * 5.0;

    // Scale with open bins count: more open bins -> discourage spreading further
    if open_bins_count > 4 {
        score += (open_bins_count as f64 - 4.0) * 0.8;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward small post_residual nonlinearly.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 14.0 * tight * tight;

    // Penalize leaving dead space that no typical item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0; // tiny unusable sliver
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0; // hard-to-fill zone
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it attractive only when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so open bins are preferred unless fit is poor.
        score += 18.0;
        // If lookahead item is large and this bin would be left cramped, opening fresh is good.
        if next_item_size > 0 {
            let post = post_residual as f64;
            if post < next_item_size as f64 && post > 0.0 {
                score -= 22.0; // dead space for the next item => fresh bin better
            }
            if next_item_size as f64 >= post {
                score -= 6.0;
            }
        }
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
        // Many open bins with high mean residual => prefer reusing, penalize new bin.
        score += 0.4 * open_bins_count as f64;
        score += 0.15 * mean_residual;
    } else {
        // Reward consuming bins that are already mostly full (consolidation).
        let used_frac = 1.0 - (bin_residual as f64 / bin_capacity as f64);
        score -= 6.0 * used_frac;
        // Lookahead synergy: if next item fits the post residual exactly-ish, bonus.
        if next_item_size > 0 && post_residual >= next_item_size {
            let slack = (post_residual - next_item_size as u32) as f64;
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
        }
        // If placing here leaves dead space unusable by the next item, penalize.
        if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
            score += 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }

    // Mild global pressure: when few bins fit the item, prefer best fit even more.
    if fitting_bins_count <= 2 && !is_new_bin {
        score -= 4.0;
    }

    // Time-horizon modulation: late in stream, prioritize closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 3.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling: post_residual shaped by stream progress
    let pr_norm = pr / cap;
    let poly = pr_norm * pr_norm * (1.0 - progress) - pr_norm * progress;
    score += 18.0 * poly;

    // Perfect fit reward (smooth, quadratic in residual usage)
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Lookahead: penalize wasting space needed by next item
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += 0.08 * gap;
        if post_residual >= next_item_size {
            score -= 6.0 * (post_residual as f64 / cap) * (next_item_size as f64 / cap);
        }
    }

    // Last-chance bin reward
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Penalize bins far from mean residual (fragmentation pressure), scaled by open bins
    let dev = (pr - mean_residual).abs() / cap;
    score += 4.0 * dev * dev * (1.0 + open_bins_count as f64).ln();

    // Late stream: prefer tight packing (lower post_residual weighted more)
    score *= 1.0 + 0.5 * progress * pr_norm;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual into capacity fractions
    let frac = post_residual as f64 / bin_capacity as f64;
    // Penalize dead-space classes: residual in (0, 10) is nearly unusable
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual == 0 {
        score -= 40.0; // perfect fit reward
    } else {
        // Harmonic class by integer division: usable chunks of 10
        let class = post_residual / 10;
        // Prefer bins whose residual class matches the next item's class
        if next_item_size > 0 {
            let next_class = next_item_size / 10;
            if class >= next_class {
                score -= 8.0 + 2.0 * (class - next_class) as f64;
            } else {
                score += 6.0 + 3.0 * (next_class - class) as f64;
            }
            // exact match of next item into post residual
            if post_residual == next_item_size {
                score -= 30.0;
            }
        }
    }

    // Modulo-based texture: reward residuals that are multiples of 10 (easy to fill)
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 5.0;
    } else if post_residual % 5 == 0 {
        score -= 2.0;
    } else {
        score += 3.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Tight fit reward: fraction of bin filled by this item
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 10.0 * fill;

    // Penalize opening new bins early in the stream; allow it late when mean residual is low
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 12.0 + 20.0 * (1.0 - progress);
        if next_item_size > 0 && next_item_size >= item_size {
            score += 5.0;
        }
        if mean_residual < item_size as f64 {
            score -= 15.0; // all open bins are too tight, new bin is fine
        }
    }

    // Prefer denser bins (low mean residual relative to this bin)
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (<10) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 4.0;
    }
    // Medium dead space (10..=20) is only usable by very small items; mild penalty.
    if post_residual >= 10 && post_residual < 20 {
        score += 6.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward when residual after placement exactly accommodates the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }
    // Penalize if the leftover gap cannot fit the next item while being close to it.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: when many bins are open, avoid wasting residual capacity.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 0.35 * (0.5 + progress);

    // Prefer bins whose residual is close to the mean (balanced packing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // New-bin candidate: make empty bin mildly attractive only when the fit is poor
    // or the item is large; otherwise slightly disfavored vs. good existing fits.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        if tightness > 0.8 {
            score -= 10.0; // large items are fine in fresh bins
        } else {
            score += 12.0; // discourage wasting a fresh bin on small items
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit (small post_residual), scaled non-linearly.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * tightness * tightness;

    // --- 2-step lookahead matching ---
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect 2-chain: item + next item fill this bin exactly.
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item fits here too: reward proportional to how well it fills.
            let next_fill = next_item_size as f64 / post_residual as f64;
            score -= 45.0 * next_fill;
        } else {
            // Next item won't fit: penalize dead space left behind, worse when
            // the leftover is small-but-unusable (high fragmentation risk).
            let gap = (next_item_size - post_residual) as f64;
            let frag = gap / bin_capacity as f64;
            score += 25.0 * frag * (1.0 - frag);
        }
    }

    // --- Relative-to-mean-residual coupling ---
    // Placing into a bin whose residual is far above mean wastes big space;
    // prefer bins near or below the mean residual (already fragmented bins).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // --- Last-chance bonus ---
    if fitting_bins_count == 1 {
        // Only this bin can fit the item; opening a new bin would strand it.
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // Many alternatives: slight penalty for being greedy here.
        score += 2.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Fresh bin: attractive early when open bins are fragmented, but
        // discourage opening new bins when a decent fit exists elsewhere.
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mean_frag = mean_residual / bin_capacity as f64;
        let new_bonus = 55.0 * mean_frag * (1.0 - 0.5 * progress);
        score -= new_bonus;
        // Never prefer a new bin if this item fits some open bin tightly.
        if post_residual <= 10 {
            score -= 20.0;
        }
    }

    // --- Stream phase: early on, consolidate; late, allow more bins ---
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * (1.0 - progress);

    // Mild penalty for accumulating too many open bins.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more than linearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 8.0 * tightness * tightness;

    // Penalize large post_residual strongly (dead space).
    if post_residual > 0 {
        score += (post_residual as f64).sqrt() * 2.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            let nxt_waste = post_residual - next_item_size;
            score -= 12.0 * (1.0 - (nxt_waste as f64) / (bin_capacity as f64));
        } else {
            // next item can't fit here; mildly penalize leaving a gap next item can't use
            score += 5.0;
        }
    }

    // New-bin candidate handling: prefer new bin only when fits are poor and many bins open.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin.
        score += 20.0;
        // Cheaper to open a new bin when many bins already open (fragmentation likely).
        score -= (open_bins_count as f64).min(10.0) * 1.5;
        // Early in stream, opening bins is fine.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - progress) * 10.0;
        // If this bin is the only fitting option, opening a new bin is bad.
        if fitting_bins_count == 1 {
            score += 60.0;
        }
        // If mean residual is small, existing bins are well-packed; opening new bin is bad.
        if mean_residual < item_size as f64 * 1.2 {
            score += 40.0;
        }
    }

    // Prefer bins with residual close to item (best-fit flavor) among many options.
    if fitting_bins_count > 2 {
        score -= 3.0;
    }

    // Penalize leaving residuals in the awkward 20..40 zone (hard to fill).
    if post_residual >= 20 && post_residual <= 40 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual

    // Base: post residual, mildly non-linear in progress
    let mut score = pr * (1.0 + 0.6 * progress * progress);

    // Smooth polynomial coupling: penalize mid-range residuals more as stream progresses
    let coupling = 4.0 * x * (1.0 - x); // peaks at x=0.5
    score += 12.0 * coupling * (0.5 + progress);

    // Reward tight fits
    score -= 8.0 * (1.0 - x) * (1.0 - x) * (1.0 + progress);

    // Dead-space penalty: residual too small to be useful later
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            score += 6.0 * (nx - pr) / cap * (1.0 + progress);
        } else {
            // reward leaving space for the next item
            score -= 4.0 * (1.0 - ((pr - nx) / cap).abs() * 0.5);
        }
    }

    // Last-chance bonus: only bin that fits -> strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Prefer fuller bins when many bins are open
    score -= 5.0 * (1.0 - x) * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));

    // Mean residual interaction: avoid bins deviating far below mean residual
    score += 2.0 * ((mean_residual - pr) / cap).abs();

    // New-bin candidate: penalize slightly so we only open when open bins are poor fits
    if bin_residual == bin_capacity {
        score += 10.0 + 15.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is always ideal.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Harmonic class of the leftover space: classify post_residual by
    // integer division thresholds (coarse dead-space classes).
    let cls = post_residual / 10; // 0..=9 dead-space class
    let class_penalty = match cls {
        0 => 0.0,          // 1..=9: nearly full, great
        1 => 5.0,          // 10..=19: still fillable by small items
        2 => 12.0,
        3 => 20.0,
        4 => 30.0,
        5 => 45.0,
        6 => 60.0,
        7 => 80.0,
        8 => 100.0,
        _ => 120.0,        // 90..=99: nearly empty bin, wasteful placement
    };
    score += class_penalty;

    // Modulo arithmetic on post_residual: leftovers that are multiples of
    // common small item sizes are reusable, reward them.
    let reusable = |r: u32| -> f64 {
        let mut bonus = 0.0;
        for m in [10u32, 20, 25, 30, 40, 50].iter() {
            if r >= *m && r % m == 0 {
                bonus += 15.0;
            }
        }
        bonus
    };
    score -= reusable(post_residual);

    // Lookahead: does the next item fit in the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Chainability reward, stronger if next item exactly fills it.
            if next_item_size == post_residual {
                score -= 60.0;
            } else {
                score -= 25.0;
            }
        } else {
            // Next item cannot use leftover: penalize proportionally to gap.
            let gap = next_item_size - post_residual;
            score += gap as f64 * 0.5;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: neutral-ish baseline; only attractive when open
    // bins are nearly full on average or many bins already open.
    if bin_residual == bin_capacity {
        score = 100.0
            + mean_residual * 0.3
            + (open_bins_count as f64) * 2.0
            - (step_index as f64 / (total_items.max(1) as f64)) * 20.0;
        // A new bin is fine if the item is huge (little choice anyway).
        if item_size >= 60 {
            score -= 30.0;
        }
    }

    // Slight preference for tighter bins (smaller residual before placing).
    score += (bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftover gaps are nearly unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 18.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 120.0;
    }

    // Lookahead synergy: leftover space exactly fits the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 55.0;
    } else if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 10 {
        score -= 20.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 45.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, prefer filling.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64).ln().max(0.0) * 4.0 * (0.5 + 0.5 * progress);

    // Prefer bins tighter than the mean residual (fill the emptiest-risk bins last).
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // New-bin candidate: only attractive when nothing fits well or item is huge.
    if bin_residual == bin_capacity {
        let poor_fit = (fitting_bins_count == 0) || (item_size > 70 && post_residual < 10);
        if poor_fit {
            score -= 30.0;
        } else {
            score += 25.0 + 5.0 * (open_bins_count as f64).min(10.0);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: heavily reward near-zero post residual.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // Aggressive 2-step lookahead: reward bins where the NEXT item fits
    // exactly into the post residual (chained perfect fit).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Penalize leftover slack after the hypothetical next placement,
            // scaled harder when slack is small (near-chained fit).
            if slack <= 5.0 {
                score -= 120.0;
            } else {
                score += slack * 0.8;
            }
        } else {
            // Next item cannot fit here: the post residual becomes dead space
            // unless another item smaller than it arrives. Penalize dead space
            // relative to mean residual context.
            let dead = post_residual as f64;
            score += dead * 0.5;
            if dead > mean_residual {
                score += (dead - mean_residual) * 0.7;
            }
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // relative to capacity or current bins are badly fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Prefer new bin when existing bins are fragmented (high mean residual)
        // or the item is huge (poor fits likely elsewhere).
        let item_ratio = item_size as f64 / bin_capacity as f64;
        score = 60.0 - 40.0 * item_ratio - 30.0 * fragmentation - 10.0 * progress;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // A fresh bin can chain the next item too.
            if item_size + next_item_size <= bin_capacity {
                score -= 25.0;
            }
        }
    }

    // Mild global pressure: when many bins are open, prefer tightening fits.
    score += open_bins_count as f64 * 0.05;
    // Slight preference for fuller bins overall.
    score -= (bin_residual - post_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: perfect or near-perfect fits are heavily favored.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 200.0 - (post_residual as f64) * 10.0;
    }

    // Penalize leaving dead space relative to mean residual across open bins.
    let pr = post_residual as f64;
    score += 0.5 * (pr - mean_residual).max(0.0);
    score -= 0.25 * (mean_residual - pr).max(0.0);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Lookahead coupling: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 120.0; // exact two-item chain completion
        } else if post_residual >= next_item_size {
            score -= 30.0; // future still fits
        } else {
            // dead space the next item cannot use; penalize proportionally
            let waste = pr - next_item_size as f64;
            score += 0.8 * waste.max(0.0);
        }
    } else {
        // End of stream: closing bins fully matters most.
        score -= 0.5 * (bin_capacity as f64 - pr);
    }

    // Dynamic time horizon: early in stream, keep residuals large/flexible;
    // late in stream, commit to tight packing.
    let t = step_index as f64 / (total_items.max(1) as f64);
    let flexibility = (1.0 - t) * (1.0 - t);
    score += flexibility * pr * 0.6;
    score -= t * pr * 0.3;

    // Bin-count pressure: with many open bins, consolidation is valuable.
    if open_bins_count > 2 {
        score -= (open_bins_count as f64).ln() * 8.0 * (bin_residual as f64 / bin_capacity as f64);
    }

    // New-bin candidate: penalize opening a fresh bin unless nothing fits well.
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        score += 40.0 + 60.0 * scarcity + flexibility * 50.0;
        // If next item is large, a fresh bin is more acceptable.
        if next_item_size >= item_size {
            score -= 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let mut score = pr * (1.0 + 0.35 * progress * progress + 0.15 * (1.0 - progress) * progress);

    // Penalize large dead space non-linearly (cubic in normalized residual).
    score += 12.0 * norm_pr * norm_pr * norm_pr * cap * 0.1;

    // Reward tight fits (small post_residual) with a smooth decay.
    score -= 8.0 * (-pr / 12.0).exp();

    // Last-chance bonus: strongly favor this bin if it is the only fitting one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: reward leaving space for the next item, smoothly.
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score -= 6.0 * (-gap / 20.0).exp();
    }

    // Mild penalty for spreading across many open bins.
    score += 0.05 * open_bins_count as f64;

    // Alignment with mean residual: prefer residuals near the mean, smoothly.
    score += 0.02 * (pr - mean_residual).abs();

    // New-bin candidate: keep it slightly unattractive unless residuals are large.
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how it partitions the capacity.
    let cap_f = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap_f; // fraction of capacity left after placement

    // Penalize dead space that no plausible item can use.
    if post_residual > 0 {
        // Modulo classes: residuals divisible by common item sizes are reusable.
        let reusable = (post_residual % 10 == 0) as f64
            + (post_residual % 5 == 0) as f64 * 0.5
            + (post_residual % 20 == 0) as f64 * 0.5;
        score -= reusable * 4.0;
        // Tiny unusable slivers are dead space: penalize heavily.
        if post_residual < 10 {
            score += 25.0 * (1.0 - post / 10.0);
        }
    }

    // Perfect fill is best.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: reward if next item fits exactly or well in post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0; // perfect chained fill
        } else if next_item_size <= post_residual {
            // harmonic match: next item divides or is close to residual
            let diff = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - diff / cap_f);
            if post_residual % next_item_size.max(1) == 0 {
                score -= 6.0; // divisibility bonus
            }
        } else {
            // next item won't fit here: mild penalty proportional to waste
            score += 3.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Tightness reward: bins with small relative slack are attractive.
    score += 8.0 * (frac * frac); // quadratic penalty on large leftover fraction

    // Early stream: be slightly conservative, prefer tight fits; late stream: consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 2.0 * (mean_residual / cap_f);

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity && item_size <= bin_capacity {
        let base = 55.0 - 20.0 * (item_size as f64 / cap_f);
        // discourage new bin if decent fitting bins exist
        score = base + (fitting_bins_count as f64) * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let tiny_gap_threshold = 10.0_f64.min(bin_capacity as f64 * 0.1);
    if (post_residual as f64) > 0.0 && (post_residual as f64) < tiny_gap_threshold {
        score += (tiny_gap_threshold - post_residual as f64) * 6.0;
    }

    // Reward near-perfect fits (post_residual close to 0).
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Penalize creating gaps that cannot fit the next item if that next item
    // could have fit here instead (lookahead coupling).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size as f64 - post_residual as f64) * 0.5;
    }
    // Reward leaving exactly enough room for the next item.
    if next_item_size > 0 && post_residual == next_item_size as u32 {
        score -= 12.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, discourage spreading into
    // new/loosely-fitting bins; encourage filling existing ones.
    let bin_pressure = open_bins_count as f64 / (1.0 + progress.max(0.05));
    score += bin_pressure * 0.35;

    // New-bin candidate: only attractive when existing residuals are all poor
    // (mean residual large relative to item) or nothing fits well.
    if bin_residual == bin_capacity {
        let desperation = (mean_residual - item_size as f64).max(0.0);
        score += 40.0 - desperation.min(40.0);
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    // Mild preference for bins tighter than the average residual (denser bins).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact / near-exact fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Squared waste penalty: small residuals are cheap, large ones costly.
        score += (post_residual as f64).powi(2) / (bin_capacity as f64);
    }

    // 2-step lookahead: if the next item fits perfectly in the post residual,
    // this placement chains nicely — reward it.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if nxt <= pr {
            let chain_fit = (pr - nxt) / bin_capacity as f64;
            score -= 50.0 * (1.0 - chain_fit);
        } else {
            // Next item won't fit here after this placement: slight penalty
            // proportional to how badly it misses, unless residual is tiny anyway.
            let miss = (nxt - pr) / bin_capacity as f64;
            score += 20.0 * miss;
        }
    }

    // Relative to mean residual: prefer bins whose post residual stays
    // below/at the average (tight packing), penalize outliers.
    let pr = post_residual as f64;
    if mean_residual > 0.0 {
        let rel = (pr - mean_residual) / mean_residual;
        score += 10.0 * rel.max(-2.0);
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate (empty bin): make it attractive only when the item
    // is large relative to capacity (better to start fresh for big items)
    // or when the fit in existing bins would be very poor.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        // Base cost of opening a new bin, discounted for large items.
        score = 60.0 + 100.0 * (1.0 - fill_ratio);
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            // Room for the next item too in a fresh bin: mild discount.
            score -= 15.0;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 * progress;
    }

    // Mild preference for fewer open bins overall.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize low post-residual relative to capacity.
    let tightness = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 8.0 * tightness * tightness;

    // Penalize dead space that is too small for typical future items
    // (residual below the minimum item size is pure waste).
    if post_residual < item_size.min(80).max(1) {
        score += 6.0;
    } else if post_residual <= 12 {
        score += 3.0; // small usable window is risky
    }

    // Lookahead: if the next item fits exactly into the post-residual,
    // strongly favor this bin (chain packing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 12.0;
        } else if post_residual >= next_item_size {
            score -= 2.0 * (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
        } else {
            // next item won't fit here; slight penalty proportional to waste
            score += 1.5 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    // New-bin candidate handling: prefer existing bins when residual is
    // reasonably utilized; prefer new bin when open bins are nearly full
    // or the fit is very poor.
    if bin_residual == bin_capacity {
        // Fresh bin baseline: attractive when open bins are crowded or fit is bad.
        let avg_waste = mean_residual.max(0.0);
        score = post_residual as f64 + 4.0;
        if open_bins_count > 0 {
            score -= 0.05 * avg_waste;
            score += 0.3 * open_bins_count as f64;
        }
        // Early in the stream, opening bins is cheap and flexible.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 2.0 * (1.0 - progress);
        // If item barely fits anywhere, new bin is good.
        if item_size as f64 > bin_residual as f64 - 0.5 || tightness < 0.55 {
            score -= 3.0;
        }
    } else {
        // Existing bin: reward keeping mean residual low (compact global state).
        score += 0.02 * (mean_residual - post_residual as f64).abs();

        // Many open bins: encourage consolidation into emptier bins.
        if open_bins_count > 4 {
            score -= 0.1 * open_bins_count as f64 * (1.0 - tightness);
        }
    }

    // Time horizon: late in the stream, be conservative with new bins
    // and squeeze existing ones harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, non-linearly (quartic-ish smooth coupling)
    let mut score = norm_pr * norm_pr * cap;

    // Polynomial coupling with stream progress: later in the stream, waste is more costly
    let coupling = norm_pr * (1.0 + 2.0 * progress + 3.0 * progress * progress);
    score += coupling * cap * 0.5;

    // Reward tight fits: item fills most of the residual
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * fill_ratio * 12.0;

    // Penalize dead space that no future item can plausibly use
    let dead = norm_pr * (1.0 - norm_pr);
    score += dead * 8.0;

    // Last-chance bonus: only one fitting bin -> strongly favor using it
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        score += (fitting_bins_count as f64).ln() * 2.0;
    }

    // Lookahead: if next item fits exactly into post_residual, reward
    if next_item_size > 0 {
        let nd = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += (nd / cap) * 10.0;
        if next_item_size as u32 == post_residual {
            score -= 20.0;
        }
    }

    // Mild penalty for spreading across many open bins vs mean residual alignment
    score += ((bin_residual as f64) - mean_residual).abs() / cap * 4.0;

    // New-bin candidate: neutral-ish score scaled by progress (opening fresh bins early is fine)
    if bin_residual == bin_capacity {
        score = cap * (0.9 + 0.4 * progress) + 5.0 * (1.0 - fill_ratio);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: which "slot band" of the bin remains.
    let frac = post_residual as f64 / bin_capacity as f64;
    let class = (post_residual * 4) / bin_capacity; // 0..3 harmonic band (0,25,50,75)

    // Reward tight fits: small post_residual gets a big subtraction.
    if post_residual == 0 {
        score -= 100.0; // perfect fill
    } else if post_residual <= 10 {
        score -= 40.0;
    } else if post_residual <= 20 {
        score -= 20.0;
    } else if post_residual <= 30 {
        score -= 8.0;
    }

    // Penalize dead space: residuals that few future items can fill.
    // Items are 1..100, so small residuals (<10) are nearly dead unless 0.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // dead space penalty
    }

    // Modulo-style threshold on next_item_size: does the lookahead fit the post-residual?
    if next_item_size > 0 {
        if next_item_size > post_residual {
            // lookahead won't fit here; mildly penalize leaving awkward gap
            score += 5.0;
            // but if post_residual is a "harmonic" size (multiple of 25), it's still useful later
            if post_residual % 25 == 0 && post_residual > 0 {
                score -= 6.0;
            }
        } else if next_item_size == post_residual {
            score -= 60.0; // lookahead completes this bin perfectly
        } else {
            // lookahead fits: reward proportionally to how well it fills
            let fill2 = next_item_size as f64 / post_residual as f64;
            score -= 30.0 * fill2;
            // extra reward if residual after lookahead lands on a harmonic class boundary
            let pr2 = post_residual - next_item_size;
            if pr2 % 25 == 0 {
                score -= 5.0;
            }
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: keep new bins moderately attractive only when
    // existing fit would waste a lot. New bin has post_residual = capacity - item.
    if bin_residual == bin_capacity {
        // neutral base; discourage when many bins are open with large residuals
        score += 10.0 + 0.05 * open_bins_count as f64;
        // but if the item is large, a fresh bin is natural
        if item_size > bin_capacity / 2 {
            score -= 15.0;
        }
        // late in the stream, prefer consolidation into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Prefer filling bins that are already emptier than average (balance residuals).
    score -= 0.3 * (mean_residual - frac * bin_capacity as f64);

    // Many open bins: encourage closing them out (prefer bins with small residual).
    score += 0.1 * open_bins_count as f64 * frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Strict dead-space avoidance: gaps too small for any item (min size 1)
    // are pure waste; gaps too small for the NEXT item are likely waste too.
    if post_residual == 0 {
        score -= 40.0; // perfect fit: strongly rewarded
    } else if next_item_size > 0 && post_residual < next_item_size {
        // gap unusable by the lookahead item: penalize proportionally
        let waste = (next_item_size - post_residual) as f64;
        score += 1.5 * waste;
    }

    // Penalize tiny residual slivers (< 10) as dead space even without lookahead
    if post_residual < 10 && post_residual > 0 {
        score += 12.0;
    }

    // Reward tight fits relative to item size (small waste ratio)
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 8.0 * tightness;

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
        if post_residual > 0 && post_residual < 15 {
            score += 10.0; // but not if it creates a near-dead bin
        }
    }

    // New-bin candidate handling: empty bin gets a baseline cost that grows
    // with the number of open bins (avoid bin proliferation), but is
    // attractive when open bins have large residuals (poor fits available).
    if bin_residual == bin_capacity {
        score = cap - 20.0 + 4.0 * (open_bins_count as f64);
        // if existing bins fit badly, opening fresh is fine
        if mean_residual > 40.0 {
            score -= 15.0;
        }
        // early in the stream, opening bins is cheap
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - progress);
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0; // fresh bin can host the lookahead too
        }
    }

    // Mild pressure from number of open bins: fill existing bins rather than
    // spreading across many.
    score += 0.3 * (open_bins_count as f64);

    // Deviation from mean residual: prefer bins whose residual is close to
    // the item (balanced packing), penalize outliers.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact-fit bonus: prefer bins that become (near) full after placement.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: reward when next item exactly matches post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0; // perfect chain: item + next item fill bin exactly
        } else if next_item_size < post_residual {
            let leftover = (post_residual - next_item_size) as f64;
            // Penalize leftover after the chained placement (potential dead space).
            score += leftover * 1.5;
            // Small bonus if the chain leaves another small residual.
            if leftover <= 5.0 {
                score -= 60.0;
            }
        } else {
            // Next item won't fit here; penalize relative to the gap size.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.8;
        }
    }

    // Relative-to-mean coupling: bins with residual near the mean are "average";
    // prefer placing into bins whose residual is larger than mean (consolidate slack),
    // penalize placing into tight bins below the mean (waste of scarce space).
    let residual_f = bin_residual as f64;
    if mean_residual > 0.0 {
        let dev = (residual_f - mean_residual) / mean_residual;
        score -= dev * 30.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
        // But if the fit leaves a large unusable chunk and next item is big, soften.
        if post_residual > 40 && next_item_size > post_residual {
            score += 80.0;
        }
    }

    // New-bin candidate handling: an empty bin should only win when the fit into
    // open bins is poor (large post_residual dead space) or few bins fit.
    if bin_residual == bin_capacity {
        // Base penalty so empty bins are not chosen for trivially good fits.
        score += 150.0;
        // Reward opening a new bin when current fit is bad and many items remain.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if post_residual > 50 {
            score -= 100.0 * (post_residual as f64 / 100.0) * (1.0 - progress * 0.5);
        }
        if fitting_bins_count == 0 {
            score -= 300.0;
        }
        // Late in the stream, avoid opening new bins (waste).
        if progress > 0.9 {
            score += 100.0 * progress;
        }
    }

    // Mild pressure to prefer bins with tighter residual when many bins are open.
    if open_bins_count > 4 {
        score += (bin_residual as f64) * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) nonlinearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big bonus.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual > next_item_size {
            // next item fits but leaves more dead space; mild penalty proportional
            score -= 6.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item does not fit here; penalize bins wasting space next item could use
            score += 4.0;
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin is a poor fit.
    if bin_residual == bin_capacity {
        // A fresh bin is fine for big items or when the stream is early.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 55.0 - 10.0 * progress;
        if item_size >= 70 {
            score -= 20.0;
        }
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    // Global state: many open bins with high mean residual -> prefer filling existing bins.
    if open_bins_count > 2 {
        score -= 0.05 * open_bins_count as f64;
        score += 0.15 * (mean_residual - post_residual as f64).abs();
    }

    // Late in the stream, consolidation matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    let item_norm = item_size as f64 / cap;

    // Base: quadratic waste penalty on post residual
    let mut score = pr + 40.0 * pr_norm * pr_norm * cap;

    // Smooth coupling: prefer tight fits more strongly as stream progresses
    score -= 30.0 * (1.0 - pr_norm) * (0.5 + 0.5 * progress) * (1.0 - pr_norm);

    // Lookahead: reward leaving room close to next item size (smooth kernel)
    if next_item_size > 0 {
        let nxt = next_item_size as f64 / cap;
        let d = (pr_norm - nxt).abs();
        score -= 25.0 * (-6.0 * d * d).exp() * (0.4 + 0.6 * progress);
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0 * (1.0 + progress);
    }

    // Penalize bins far below mean residual (fragmentation avoidance), smooth
    let dev = (pr - mean_residual) / cap;
    score += 12.0 * dev * dev;

    // Mild pressure to consolidate into existing bins as open bins grow
    if bin_residual < bin_capacity {
        score -= (open_bins_count as f64).ln() * 2.0 * (1.0 - pr_norm);
    }

    // New-bin candidate: penalize slightly unless residuals elsewhere are hopeless
    if bin_residual == bin_capacity {
        score += 15.0 + 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    let mut score = post_residual as f64;

    // --- Tight-fit rewards (harmonic dead-space classes on post_residual) ---
    if post_residual == 0 {
        score -= 60.0; // perfect closure
    } else if post_residual < 10 {
        score -= 35.0; // residual below min item size -> bin effectively closed
    } else {
        // Harmonic class: penalize awkward residues (mod 10 far from 0)
        let pr_mod = (post_residual % 10) as f64;
        score += pr_mod * 0.4;
        // Integer-division class: residues in [10,30] are still usable by small items,
        // residues in [40,70] are prime waste zones
        let div_class = post_residual / 20; // 0,1,2,3,4
        score += div_class as f64 * 2.0;
    }

    // --- Prefer bins whose current residual closely matches the item (tight coupling) ---
    let target = item_size as f64 * 1.15;
    score += ((bin_residual as f64) - target).abs() * 0.08;

    // --- Lookahead (k=2) coupling ---
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // leftover space remains useful for the next item
            score -= 5.0;
            // extra bonus if next item fills leftover almost exactly (harmonic match)
            let gap = post_residual - next_item_size;
            if gap < 10 { score -= 6.0; }
        } else if post_residual >= 10 {
            // leftover becomes dead space for the upcoming item
            score += 4.0;
        }
    }

    // --- Last-chance bin: strongly favor using it before opening a new one ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // --- Prefer already-loaded bins (first-fit flavor), scaled by stream progress ---
    score -= (bin_capacity - bin_residual) as f64 * 0.12 * (0.5 + progress);

    // --- Mean-residual balancing: avoid extremes vs. fleet average ---
    score += ((bin_residual as f64) - mean_residual).abs() * 0.03;

    // --- New-bin candidate logic ---
    if bin_residual == bin_capacity {
        score += 55.0; // default: discourage opening new bins when fits exist
        if open_bins_count == 0 {
            score -= 200.0; // must open the first bin
        }
        // Open a fresh bin when the next item is large and current leftovers would fragment
        if next_item_size >= 60 {
            score -= 25.0;
        }
        // Late in the stream, new bins are cheaper than spreading waste
        if progress > 0.8 {
            score -= 8.0;
        }
        // Small items into a fresh bin waste capacity: penalize more
        if item_size < 30 {
            score += 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in the "unusable gap" band are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }

    // Reward very tight fits (waste <= 2) strongly.
    if post_residual <= 2 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post-residual, reward heavily.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }
    // Penalize if post-residual is small but cannot host the next item (dead space for lookahead).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 20.0;
    }

    // Open-bin pressure: discourage opening new bins when few bins are open,
    // encourage consolidation when many bins are open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when open bins count is low or early in stream.
        score += 25.0 + 15.0 * (1.0 - progress) + (open_bins_count as f64).max(1.0).ln() * 5.0;
        // But if no open bin fits well, opening may be fine: reduce penalty when mean residual is small.
        if mean_residual < item_size as f64 {
            score -= 30.0;
        }
    } else {
        // Existing bins: slight reward for consolidating when many bins are open.
        score -= (open_bins_count as f64).min(10.0) * 0.5;
    }

    // Prefer bins whose residual deviates positively from mean (use up larger residuals first).
    score += 0.1 * (bin_residual as f64 - mean_residual).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Perfect 2-step match: post_residual exactly equals next item -> huge reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-perfect match: next item fits with small slack
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 * (1.0 - slack / cap);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item cannot fit here -> penalize proportionally to leftover
        score += 10.0 * (next_item_size as f64 / cap);
    }

    // Penalize dead space relative to mean residual of open bins
    if post > mean_residual {
        score += 0.5 * (post - mean_residual);
    } else {
        score -= 0.25 * (mean_residual - post);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Mild pressure to close out nearly-full bins early in the stream
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (cap - post) * 0.1;

    // Slight penalty for opening new bins when many are already open
    if bin_residual == bin_capacity {
        score += 5.0 + 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward near-perfect fits.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    } else if post_residual < 10 {
        score -= 8.0;
    }

    // Penalize dead space relative to bin capacity: residual left that is
    // hard to reuse (too small for typical items) is costly.
    let dead_threshold = 15.0;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 1.5;
    }

    // Lookahead coupling: if the next item fits into the post residual,
    // leaving that space is valuable; otherwise leftover space risks waste.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 6.0; // space remains usable by lookahead item
        } else {
            // leftover space is dead for the next item; penalize proportionally
            score += (post_residual as f64) * 0.3;
            if next_item_size <= bin_residual {
                score += 2.0; // we could have kept space for it elsewhere
            }
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Early in the stream, prefer opening new bins to keep flexibility;
    // later, consolidate into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from open bin count.
        let mut new_bin_score = 25.0 + 2.0 * (open_bins_count as f64).sqrt();
        if progress > 0.7 {
            new_bin_score += 20.0; // late stream: discourage new bins
        }
        if next_item_size > 0 && next_item_size >= item_size && item_size >= 50 {
            new_bin_score -= 5.0; // large item early may deserve its own bin
        }
        return new_bin_score;
    }

    // Slight preference for bins already below mean residual (balance spreading).
    if (bin_residual as f64) < mean_residual {
        score -= 1.0;
    } else {
        score += 0.5;
    }

    // Reward filling larger fraction of bin.
    score -= (item_size as f64 / bin_capacity as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;

    // Smooth non-linear polynomial coupling of post_residual with progress:
    // early in the stream, larger post_residuals are tolerable; late in the
    // stream, dead space is heavily penalized via a cubic interaction.
    let progress_coupling = (pr / cap) * (pr / cap) * (0.5 + 1.5 * progress * progress);
    score += 20.0 * progress_coupling;

    // Reward tight fits: small post_residual relative to item size
    let tightness = 1.0 - (pr / (it + 1.0));
    if tightness > 0.0 {
        score -= 12.0 * tightness * (1.0 + progress);
    }

    // Penalize leaving residual that exactly matches nothing useful:
    // quadratic penalty when post_residual is small but nonzero (dead space)
    let dead = (pr / cap) * (1.0 - (pr / cap));
    score -= 5.0 * dead * dead * 100.0 * (1.0 - progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + 0.5 * progress);
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        let match_quality = 1.0 - gap / cap;
        score -= 8.0 * match_quality * match_quality;
    } else if next_item_size > post_residual && next_item_size > 0 {
        // next item cannot use this residual: mild penalty scaled by progress
        score += 4.0 * progress * (next_item_size as f64 / cap);
    }

    // Mean residual coupling: prefer bins whose residual is below mean
    // (concentrate filling), via smooth tanh-like polynomial
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 6.0 * dev * (1.0 + dev * dev * 0.5);

    // Slight preference for keeping number of open bins low late in stream
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod small moduli classify dead space quality
    let post = post_residual as i64;
    let cap = bin_capacity as f64;
    let frac = post as f64 / cap;

    // Perfect fit reward
    if post == 0 {
        score -= 1000.0;
    }

    // Harmonic dead-space penalty: residual that cannot fit typical small items (10..)
    // is nearly worthless. Class residuals by divisibility structure.
    if post > 0 && post < 10 {
        score += 60.0; // unusable sliver
    } else {
        // mod-10 classes: residuals divisible by 10 are "harmonic" and more reusable
        if post % 10 == 0 {
            score -= 12.0;
        }
        // mod-5 semi-harmonic
        else if post % 5 == 0 {
            score -= 5.0;
        }
        // odd residuals are worst (can't pair with even lookahead)
        if post % 2 == 1 {
            score += 4.0;
        }
    }

    // Lookahead coupling: strongly favor bins whose post_residual fits next item exactly
    if next_item_size > 0 && (post_residual as u64) >= (next_item_size as u64) {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 220.0; // chain fit: perfect two-item packing
        } else {
            // partial reward decaying with slack, harmonic in slack
            score -= 40.0 / (1.0 + slack as f64 / 10.0);
            if slack % 10 == 0 {
                score -= 6.0;
            }
        }
    } else if next_item_size > 0 && (next_item_size as u64) > (post_residual as u64) {
        // next item won't fit here: this residual becomes dead space for the lookahead
        score += 0.35 * (next_item_size as f64 - post as f64);
    }

    // Fractional-capacity harmonic thresholds on residual
    if frac > 0.4 && frac <= 0.5 {
        score -= 8.0; // half-capacity-like residual is valuable
    } else if frac > 0.5 {
        score -= 4.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: opening a new bin is expensive; make it unattractive unless
    // current bin would leave a bad residual and open bins are numerous.
    if bin_residual == bin_capacity {
        score += 90.0 + 5.0 * open_bins_count as f64;
        // allow new bin early in stream or when item is huge relative to capacity
        if item_size >= 70 {
            score -= 60.0;
        }
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 30.0 * (1.0 - progress);
    }

    // Mean-residual context: if mean residual is large, prefer tightening fullest bins
    score += 0.15 * (mean_residual - post as f64);

    // Prefer bins with tighter residual overall (best-fit flavor)
    score += 0.1 * (bin_residual as f64 - post as f64) * -1.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the minimum item size (1..100
    // unknown distribution, so treat gaps below a conservative threshold as dead).
    let dead_threshold = 12.0;
    if (post_residual as f64) < dead_threshold {
        score += 60.0 * (dead_threshold - post_residual as f64) / dead_threshold;
    }

    // Reward perfect / near-perfect fits strongly.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Tightness ratio: favor bins where the item fills a large fraction of residual.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio;

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size < post_residual {
            score -= 15.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item can't use this gap: penalize proportionally to wasted space
            score += 10.0 * ((post_residual as f64 - dead_threshold).max(0.0) / cap);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidating into existing
    // bins over opening new ones; when few bins are open, new bins are cheaper.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline cost, adjusted by pressure and stream position.
        score = cap * 0.6 + pressure * 8.0 + (step_index as f64 / total_items.max(1) as f64) * 10.0;
        // If mean residual is large and could still hold future items, penalize new bin.
        score += (mean_residual / cap) * 25.0;
    } else {
        // Existing-bin placements get a mild global discount scaled by open-bin pressure.
        score -= pressure * 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits: residual waste is quadratic-ish in dead space.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 60.0;
    }

    // Aggressive 2-step lookahead: strongly reward exact match of post_residual to next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual as i64 == next_item_size as i64 {
            score -= 200.0;
        } else if post_residual >= next_item_size {
            score -= 50.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Next item won't fit here: penalize proportionally to leftover gap.
            score += 0.5 * diff;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // Relative to mean residual: bins below-average residual (tighter) are better targets.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Slight preference for filling older/crowded bins to consolidate.
    score -= 0.1 * open_bins_count as f64;

    // Early in stream, be a bit more willing to open bins (spread risk); later, pack tight.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 2.0;

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let poor_fit = if next_item_size > 0 {
            (post_residual as i64 - next_item_size as i64).abs() as f64 > 20.0
        } else { false };
        if fitting_bins_count > 0 && !poor_fit {
            score += 250.0; // discourage opening new bin when a fit exists
        } else if fitting_bins_count > 0 && poor_fit {
            score += 30.0; // mild penalty; lookahead mismatch makes new bin tolerable
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic penalty on wasted space.
    score += (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: reward if the next item fits into post_residual (chaining).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0 + 0.25 * (next_item_size as f64);
        } else {
            // Penalize leaving residual that no plausible item can use.
            let gap = post_residual as f64;
            if gap > 0.0 && (next_item_size as f64) > gap {
                score += 0.15 * gap;
            }
        }
    }

    // Penalize new-bin candidate unless open bins fit poorly.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let tightness = (item_size as f64) / (bin_capacity as f64);
        // Open new bin mainly for large items or when no alternative exists.
        if pressure > 0.5 || tightness > 0.6 {
            score -= 20.0 + 10.0 * tightness;
        } else {
            score += 25.0 + 0.5 * (open_bins_count as f64);
        }
    }

    // Time horizon: early on, be conservative (prefer filling existing bins);
    // later, allow more aggressive consolidation.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 8.0 * progress * (mean_residual / (bin_capacity as f64));

    // Prefer bins with below-average residual (fill emptier bins first keeps
    // tight bins available), unless this is a very tight fit.
    let dev = mean_residual - bin_residual as f64;
    score += 0.1 * dev;

    // Slight preference for bins that fit with more competition (keep choice diversity).
    if fitting_bins_count > 2 {
        score += 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual (waste), smoothly warped by progress
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Non-linear coupling: penalize residual that is too small to be useful later
    let dead = (norm_pr - norm_pr * norm_pr) * cap;
    score += 0.35 * dead * (1.0 - progress);

    // Reward tight fits (small post residual) with smooth quadratic term
    score -= 0.5 * (cap - pr) * (cap - pr) / cap;

    // Lookahead coupling: penalize if post_residual can't fit next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = nxt - pr;
        if gap > 0.0 {
            score += 0.6 * gap * (1.0 + progress);
        } else {
            score -= 0.4 * (-gap) * (1.0 - progress);
        }
    }

    // Last-chance bin bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 + 0.5 * progress);
    }

    // Penalize opening new bins when many bins already fit the item
    if bin_residual == bin_capacity {
        score += 8.0 + 6.0 * (fitting_bins_count as f64).sqrt() * (1.0 - progress);
    }

    // Mean residual interaction: prefer bins below mean residual (tighter bins)
    score += 0.3 * (mean_residual - pr);

    // Open bins pressure: mild smoothing toward consolidation
    score += 0.1 * open_bins_count as f64 * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    if bin_residual == bin_capacity {
        // Brand-new empty bin candidate: prefer it for large items or when
        // open bins are scarce, penalize it for small items when good fits exist.
        score += 45.0 - 0.55 * item_size as f64;
        score += 12.0 * fitting_bins_count as f64;
        // Late in the stream, opening new bins is riskier (leftover items cluster).
        score += 15.0 * progress;
        // Harmonic class of the item: sizes in "awkward" residue classes
        // (e.g. 51..59 mod 50) waste space anywhere, so a fresh bin is fine.
        let r50 = item_size % 50;
        if r50 >= 10 && r50 <= 20 { score -= 8.0; }
    } else {
        // Existing bin: strong baseline bonus for reusing open capacity.
        score -= 18.0;

        // Dead-space penalty: tiny unusable leftovers.
        if post_residual > 0 && post_residual < 10 {
            score += 14.0;
        }
        // Harmonic class reward: post_residual in clean classes (multiples of 20)
        // is more likely reusable by future items.
        if post_residual % 20 == 0 && post_residual > 0 {
            score -= 7.0;
        } else if post_residual % 10 == 0 && post_residual > 0 {
            score -= 3.0;
        }

        // Lookahead: if the next item fits exactly or nearly in the leftover,
        // strongly favor this bin.
        if next_item_size > 0 {
            if next_item_size == post_residual {
                score -= 20.0;
            } else if next_item_size <= post_residual {
                score -= 9.0;
            } else if next_item_size > post_residual && next_item_size - post_residual <= 10 {
                score += 6.0; // next item will nearly overflow: bad chain
            }
        }

        // Last-chance bin: if this is the only bin that fits, avoid opening a new one.
        if fitting_bins_count == 1 {
            score -= 12.0;
        } else {
            score += 2.0 * (fitting_bins_count as f64 - 1.0);
        }

        // If this bin's residual is far below the mean, it's already fragmented;
        // prefer dumping items into fragmented bins to consolidate space.
        if (bin_residual as f64) < mean_residual - 15.0 {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no future item (min size 1..10)
    // can use are pure waste; penalize tiny unusable gaps harshly.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    if post_residual == 0 {
        // Perfect closure is ideal: strong reward.
        score -= 30.0;
    }

    // Lookahead coupling: if the next known item fits the post-residual,
    // this bin remains productive — reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.2 * next_item_size as f64;
    }
    // If next item would leave another dead gap in this bin, mild penalty.
    if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size < 10 {
        score += 10.0;
    }

    // Last-chance pressure: if this is the only bin that fits the item,
    // strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: many open bins -> discourage creating yet another one.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: base score is already high (100 - item_size);
        // add pressure proportional to open bins and stream progress so a
        // new bin is chosen only when all fits are truly poor.
        score += 15.0 + 2.0 * open_bins_count as f64 * (0.5 + progress);
    } else {
        // Reward filling existing bins more when many are open.
        score -= 0.5 * open_bins_count.min(20) as f64;
    }

    // Slight pull toward bins tighter than the mean residual (compactness).
    score += 0.3 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> huge reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-perfect match: next item fits with small slack left after it.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack_after_next = post_residual - next_item_size;
        score -= 30.0 * (1.0 - slack_after_next as f64 / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item won't fit here; penalize proportionally to the leftover gap.
        let gap = next_item_size - post_residual;
        score += 15.0 * (gap as f64 / bin_capacity as f64);
    }

    // Reward tight fits of the current item (small post_residual relative to capacity).
    score -= 20.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Penalize creating dead space below the minimum plausible item size.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Compare against mean residual: placing in a bin with below-average residual
    // (i.e., a fuller bin) is good; above-average residual is wasteful.
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when few bins fit the item or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 1.0 / fitting_bins_count as f64 };
        score += 45.0 - 50.0 * scarcity - 20.0 * progress;
    }

    // Slight preference to consolidate into fewer bins.
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (low post residual)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that can never be reused by typical items (post_residual < 10)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward if next item fits exactly in post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            score -= 8.0 * (next_item_size as f64) / (post_residual as f64).max(1.0);
        } else {
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Prefer filling bins with larger residuals when many bins are open (consolidation)
    if open_bins_count > 3 {
        score += 2.0 * ((bin_residual as f64) - mean_residual).max(-20.0).min(20.0) / 20.0;
    }

    // Time horizon: later in stream, prefer tighter packing, discourage new bins
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New bin candidate: penalize more as stream progresses or many bins open
        score += 12.0 + 20.0 * progress + (open_bins_count as f64).sqrt() * 3.0;
        if next_item_size > 0 && next_item_size >= item_size && next_item_size <= bin_capacity - item_size {
            score -= 5.0; // fresh bin good if next item may also go there
        }
    } else {
        score -= 4.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let item = item_size as f64;
    let fit_ratio = item / cap;
    let norm_pr = pr / cap;

    // Base: waste after placement, with smooth non-linear growth
    let mut score = pr as f64;

    // Non-linear coupling of post_residual with stream progress:
    // late in the stream, dead space is more costly (fewer chances to fill it)
    let waste_penalty = norm_pr * norm_pr * (1.0 + progress * 3.0) * cap * 0.05;
    score += waste_penalty;

    // Reward tight fits: subtract proportional to fill fraction, amplified smoothly
    let tight_reward = fit_ratio * fit_ratio * cap * (0.6 + 0.4 * progress);
    score -= tight_reward;

    // Perfect / near-perfect fit bonus (smooth exponential)
    if post_residual > 0 {
        score -= cap * 0.3 * (-norm_pr * 8.0).exp() * (0.5 + progress);
    } else {
        score -= cap * 0.5; // exact fill
    }

    // Lookahead coupling: penalize leaving residual too small OR awkwardly
    // mismatched for the next item (smooth interaction)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let usable = if pr >= nxt { 1.0 } else { 0.0 };
        let gap = (pr - nxt).abs() / cap;
        score += 0.35 * cap * (1.0 - usable) * (0.5 + progress)
               - 0.25 * cap * usable * (-gap * 6.0).exp() * (1.0 - progress * 0.5);
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= cap * 0.45 * (0.6 + 0.4 * progress);
    }

    // Context: many open bins with high mean residual -> favor consolidation
    let open_pressure = open_bins_count as f64 / (1.0 + mean_residual / cap);
    score += 0.15 * open_pressure * norm_pr;

    // New-bin candidate (empty bin): make it unattractive unless residuals are bad
    if bin_residual == bin_capacity {
        score += cap * (0.8 + 0.6 * progress)
               + 0.3 * mean_residual * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space quality via integer division.
    // Residuals in (0,10] are nearly useless; large residuals are valuable.
    let harmonic_class = post_residual / 10; // 0..=9 classes
    score += match harmonic_class {
        0 => 45.0,                    // tiny unusable sliver
        1 => 25.0,                    // 10-19: hard to fill
        2 => 12.0,                    // 20-29
        3 => 5.0,                     // 30-39
        4 => 0.0,                     // 40-49 neutral
        _ => -8.0,                    // >=50: roomy bin, good target
    };

    // Modulo-5 resonance: residual divisible by 5 pairs cleanly with many sizes.
    if post_residual % 5 == 0 { score -= 4.0; }
    if post_residual % 10 == 0 { score -= 4.0; }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            if gap == 0 { score -= 30.0; }               // perfect pair
            else if gap <= 5 { score -= 18.0; }          // near-perfect pair
            else { score -= (gap as f64).min(20.0) * 0.3; }
        } else {
            // next item cannot fit here; penalize leaving awkward space
            score += ((next_item_size - post_residual) as f64).min(25.0) * 0.4;
        }
    }

    // Tight fit reward: item fills most of the bin.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 25.0;

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive when current fit is terrible
    // or stream is early with few bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let waste = bin_residual as f64 - item_size as f64;
        // New bin is penalized by its leftover space, softened early in stream.
        score = 30.0 + waste * (0.6 - 0.35 * (1.0 - progress));
        if open_bins_count == 0 { score -= 100.0; } // must open first bin
        if next_item_size > 0 && waste > 60.0 { score -= 10.0; }
    }

    // Spread-aware: prefer bins near mean residual (keeps options balanced).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    }
    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward post_residuals that can still fit typical future items (>= next item or >= 10).
    if post_residual >= 10 {
        score -= 8.0;
    }
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }
    // Penalize if post_residual cannot fit the next item (dead space for lookahead).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += next_item_size as f64 * 0.5;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> favor consolidating into existing bins.
    score += open_bins_count as f64 * 1.5;

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 0.0 } else { 20.0 };
        score += desperation;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 5.0; // fresh bin can host current + next
        }
    }

    // Slight preference for bins tighter than average (fill the fullest first).
    score += (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> strong reward
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 * (1.0 - diff / bin_capacity as f64).max(0.0);
        // penalize leaving residual that is too small for anything useful
        if post_residual > 0 && post_residual < 10 {
            score += 25.0;
        }
    }

    // Exact fill reward
    if post_residual == 0 {
        score -= 60.0;
    }

    // Relative to mean residual: prefer bins that are already tight (below mean residual)
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Last chance bin: avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Penalize opening new bins early in the stream when fitting bins exist
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 + 20.0 * (1.0 - progress);
    }

    // Mild penalty for large leftover dead space relative to capacity
    score += 0.2 * (post_residual as f64 / bin_capacity as f64) * 100.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 1 {
        step_index as f64 / total_items as f64
    } else {
        0.0
    };

    // Fractional fill of this bin after placement: high fill = good
    let fill = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 20.0 * fill * fill; // reward tight packing super-linearly

    // Penalize dead space: post_residual that no typical item (>=1) can use
    if post_residual == 0 {
        score -= 15.0; // perfect fit, strongly favored
    } else if post_residual < 10 {
        score -= 8.0; // near-perfect fit
    } else {
        score += 0.05 * post_residual as f64; // mild linear dead-space penalty
    }

    // Lookahead: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item chains nicely here
            let chain_waste = post_residual - next_item_size;
            score -= 6.0 - 0.05 * chain_waste as f64;
        } else {
            // next item won't fit here; penalize proportionally to overshoot
            let overshoot = next_item_size - post_residual;
            score += 0.08 * overshoot as f64;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Many open bins: encourage filling existing ones rather than spreading
    if open_bins_count > 0 {
        score += 0.5 * open_bins_count as f64 * (1.0 - fill);
    }

    // Mean residual coupling: if this bin is below-average residual (tighter),
    // prefer placing here to consolidate small leftovers.
    let diff = mean_residual - bin_residual as f64;
    score -= 0.10 * diff;

    // New-bin candidate handling: empty bin starts at high baseline; only
    // attractive early in the stream or when no existing bin fits well.
    if bin_residual == bin_capacity {
        score += 25.0;
        // Early stream: opening bins is cheap; late stream: costly
        score += 30.0 * progress;
        // If many bins are open, discourage yet another one
        score += 1.5 * open_bins_count as f64;
        // If the next item is large and this bin is fresh, slightly encourage
        if next_item_size >= bin_capacity / 2 {
            score -= 5.0;
        }
    }

    // Time-horizon modulation: late in the stream, tighten up aggressively
    score *= 1.0 + 0.5 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fill * fill * fill;

    // Non-linear dead-space penalty: quadratic in post_residual, scaled by stream progress
    // (wasted space matters more later in the stream).
    let dead = post_residual as f64 / bin_capacity as f64;
    score += 25.0 * dead * dead * (0.5 + 0.5 * progress);

    // Lookahead coupling: reward leaving a residual that fits the next item exactly-ish.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Penalize leaving residual too small for the next item (unusable wedge).
        score += 8.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin, more so when open bins exist
    // and residuals are still usable.
    if bin_residual == bin_capacity {
        let avg_usable = mean_residual / bin_capacity as f64;
        score += 35.0 * (1.0 - progress) + 15.0 * avg_usable + 2.0 * open_bins_count as f64;
    }

    // Mild preference for placing into bins with smaller residual (best-fit flavor),
    // smoothly coupled with progress.
    score += 5.0 * (bin_residual as f64 / bin_capacity as f64) * (1.0 - 0.5 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Fractional fill of the bin after placement
    let fill = 1.0 - post / cap;

    // Reward high fill non-linearly (tight fits are valuable)
    score -= 60.0 * fill * fill;

    // Harmonic class logic: post_residual buckets via integer division
    // Dead space classes: post_residual in [1..10] tiny, [11..30] mid, [31..50] bad, >50 awful
    let post_i = post_residual;
    if post_i == 0 {
        score -= 25.0; // perfect fit
    } else if post_i <= 10 {
        score -= 12.0;
    } else if post_i <= 30 {
        score += 6.0;
    } else if post_i <= 50 {
        score += 18.0;
    } else {
        score += 30.0 + (post_i - 50) as f64 * 0.5;
    }

    // Modulo coupling: residuals near multiples of common item sizes are reusable
    let next = next_item_size as f64;
    if next > 0.0 && post_i > 0 {
        let rem = (post_i % next_item_size.max(1)) as f64;
        if rem == 0.0 {
            score -= 15.0; // next item exactly fills leftover
        } else {
            // penalty proportional to unusable slack after next item
            score += 0.3 * rem;
        }
        if next_item_size > post_i {
            score += 5.0; // lookahead can't use this residual anyway
        }
    }

    // Last-chance bin: strongly favor to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate: penalize unless current bins are nearly exhausted
    if bin_residual == bin_capacity {
        // Opening a new bin is expensive when few items remain or bins are empty-ish
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 55.0 - 30.0 * progress - 0.15 * open_bins_count as f64;
        // If item is large, new bin is more attractive
        score -= (item_size as f64) * 0.15;
    }

    // Slight preference for bins below mean residual (balance loads)
    score += 0.05 * (mean_residual - post).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps hard.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    }
    // Medium dead space (below typical small item sizes) also penalized softly.
    if post_residual >= 10 && post_residual < 20 {
        score += (20 - post_residual) as f64 * 1.5;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + next_item_size as f64 * 0.2;
    }
    // If next item almost fits (small miss), mild penalty for stranding space.
    if next_item_size > 0 && post_residual >= next_item_size.saturating_sub(3) && post_residual < next_item_size {
        score += 5.0;
    }

    // Open-bin pressure: discourage spreading across many bins slightly.
    score += open_bins_count as f64 * 0.3;

    // New-bin candidate: keep it neutral-ish baseline but encourage when
    // current open bins have large residuals (item fits poorly everywhere).
    if bin_residual == bin_capacity {
        score = 100.0 + post_residual as f64 - mean_residual * 0.4;
        // If this is the only fitting bin anyway, opening new bin is not needed.
        if fitting_bins_count == 1 {
            score += 60.0;
        }
        // Late in stream, prefer reusing bins.
        score += (step_index as f64 / total_items.max(1) as f64) * 15.0;
    }

    // Prefer bins whose residual is close to item (tight packing overall).
    score += (bin_residual as f64 - item_size as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect match: post_residual exactly equals next item size -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Next item fits in the leftover space -> reward proportionally.
    if next_item_size > 0 && post_residual >= next_item_size {
        let fit_ratio = next_item_size as f64 / post_residual as f64;
        score -= 25.0 * fit_ratio;
    } else if next_item_size > 0 {
        // Next item cannot use the leftover: penalize dead space.
        let waste = (next_item_size - post_residual) as f64;
        score += 0.3 * waste;
    }

    // Tight fit reward: small post_residual relative to capacity is good,
    // but only when it doesn't create a useless sliver.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * tightness * tightness;

    // Penalize tiny unusable slivers (0 < post_residual < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Reward placing into bins whose residual is above mean (balancing residuals),
    // penalize dipping far below mean residual.
    let dev = post_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: prefer keeping a fresh bin pristine unless
    // the fit here is excellent (post_residual near zero) or matches next item.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 40.0;
        // Early in the stream, opening bins is cheaper (more items remain to fill them).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 25.0 * (1.0 - progress);
        // If many open bins exist, discourage opening yet another.
        score += 2.0 * open_bins_count as f64;
        // If next item is large and this item is small, a new bin is attractive.
        if next_item_size > item_size + 30 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tight fit reward: fraction of bin consumed
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 40.0 * fill_ratio;

    // Penalize small dead space that nothing (>=10) can ever use,
    // but only mildly if a future item might fit it.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Lookahead: if next item fits exactly in the post-residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size <= post_residual {
            score -= 60.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // post-residual cannot host next item: penalize proportionally to wasted space
            score += 0.3 * post_residual as f64;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 500.0;
    }

    // New-bin candidate handling: opening a new bin is justified only when
    // this item fits poorly everywhere else. Penalize new bins when good fits exist.
    if bin_residual == bin_capacity {
        // Base penalty so open bins with decent fits win.
        score += 250.0;
        // But if many open bins exist and mean residual is small (fragmented),
        // a fresh bin is more attractive.
        score -= 2.0 * open_bins_count as f64;
        score += 1.5 * mean_residual;
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 200.0 * progress;
        // If next item is huge and this item is small, a fresh bin keeps flexibility.
        if next_item_size >= 60 && item_size <= 30 {
            score -= 120.0;
        }
    }

    // Global fragmentation pressure: when mean residual is high, prefer bins
    // below the mean (fill the emptier/larger ones less, keep balanced slack).
    if bin_residual as f64 > mean_residual + 1.0 {
        score -= 0.2 * (bin_residual as f64 - mean_residual);
    }

    // Time-dependent exploration: early on, slightly prefer tighter fits to
    // learn structure; late, aggressively minimize residual.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * 10.0 * fill_ratio;
    score += progress * 0.5 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let prn = pr / cap; // normalized post residual
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = 1.0 + 0.8 * progress - 1.6 * progress * progress + 1.8 * progress * progress * progress;
    score *= poly.max(0.2);

    // Penalize large dead space quadratically, more so late in the stream
    score += 12.0 * prn * prn * (0.5 + progress) * cap;

    // Reward tight fits (small post residual relative to item)
    let tightness = 1.0 - prn;
    score -= 10.0 * tightness * tightness * (1.0 + progress);

    // Lookahead: bonus if next item fits the post residual
    if next_item_size > 0 {
        if (next_item_size as f64) <= pr {
            score -= 15.0 * (1.0 - prn) * (1.0 + progress);
        } else {
            score += 8.0 * progress;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 * (1.0 + 2.0 * progress);
    }

    // Mild penalty when many bins are open and this fit is loose
    let open_f = open_bins_count as f64;
    score += 0.5 * open_f.sqrt() * prn * (0.3 + progress);

    // Deviation from mean residual: prefer bins near the mean (balance)
    let dev = (pr - mean_residual).abs() / cap;
    score += 6.0 * dev * dev;

    // New-bin candidate: keep it neutral-to-slightly-high unless residual is huge
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod 10 (capacity fractions)
    let post = post_residual as u32;
    let res_class = post % 10;
    // Dead-space penalty: post_residual classes that are hard to fill later
    // (small nonzero residues 1..9 are awkward; 0 or >= next typical item is fine)
    if post > 0 && post < 10 {
        score += 60.0;
    } else if post >= 10 && post < 20 {
        score += 12.0;
    } else {
        // reward exact fills and large residuals
        score -= (post as f64) * 0.35;
    }

    // Modulo coupling: if post_residual is an exact multiple of 10, it's a
    // "harmonic slot" that future items (often multiples of 5/10) can fill.
    if post % 5 == 0 {
        score -= 8.0;
    }
    if post % 10 == 0 && post > 0 {
        score -= 6.0;
    }

    // Perfect fit reward
    if post == 0 {
        score -= 500.0;
    }

    // Lookahead: if the next item fits exactly in the post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 400.0;
        } else if next_item_size < post {
            // harmonic class match: next item leaves a multiple-of-10 residual too
            let next_post = post - next_item_size;
            if next_post % 10 == 0 {
                score -= 25.0;
            }
            score -= 10.0;
        } else {
            // next item won't fit here: mild penalty for this bin
            score += 15.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: empty bin gets a base opening cost,
    // modulated by how badly current bins fit and stream progress.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut open_cost = 200.0 + 300.0 * (1.0 - progress);
        // If many bins already fit the item, opening a new one is wasteful
        if fitting_bins_count > 0 {
            open_cost += 80.0 * (fitting_bins_count as f64);
        }
        // If next item is large, keep some fresh capacity around
        if next_item_size > 50 {
            open_cost -= 60.0;
        }
        score += open_cost;
    }

    // Spread pressure: prefer bins whose residual deviates from the mean
    // in a "harmonic" direction (below mean residual = tighter bin, fill first)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 40.0 * dev;

    // Integer-division threshold on item_size: large items prefer tight bins
    if item_size / 20 >= 3 && post <= 20 {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual gap is "dead" if it cannot fit even the smallest plausible item (assume >= 1),
    // but the danger zone is gaps that are too small for the lookahead item too.
    if post_residual > 0 {
        let gap = post_residual as f64;
        // Dead-space curve: gaps in (0, 10] are almost certainly wasted.
        if gap <= 10.0 {
            score += 25.0 * (1.0 - gap / 10.0); // tiny gaps worst
        } else if next_item_size > 0 && (post_residual as u32) < next_item_size {
            // Gap too small for the known next item: penalize proportionally.
            score += 8.0 + 0.25 * (next_item_size as f64 - gap);
        }
        // Perfect fit bonus: zero-ish gap is ideal.
        if post_residual == 0 {
            score -= 15.0;
        }
    }

    // Reward tight fits relative to the bin residual (fill fraction of available space).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fit_ratio;

    // Open-bin pressure: with many open bins, prefer filling existing ones (avoid sprawl).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (1.0 + progress * 10.0);
    score += 0.15 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Mean residual coupling: bins with residual far below mean are "odd" —
    // filling them normalizes the fleet; bins above mean should absorb big items.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev * (item_size as f64 / 100.0);

    // Lookahead: if the next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 10.0;
    }

    // New-bin candidate handling: an empty bin is a fallback; make it moderately
    // attractive only when this placement would create severe dead space.
    if bin_residual == bin_capacity {
        // Neutral baseline slightly above good fits, below terrible fits.
        score = 45.0 - 0.2 * item_size as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post residual).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // 2-step lookahead: perfect if post_residual == next_item_size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        let lookahead_bonus = if gap == 0.0 {
            60.0
        } else if post_residual >= next_item_size {
            25.0 * (1.0 - gap / (bin_capacity as f64))
        } else {
            // next item won't fit here; penalize wasted space slightly
            -8.0 * (1.0 - gap / (bin_capacity as f64))
        };
        score -= lookahead_bonus;
    }

    // Relative to mean residual: prefer bins that are already low-residual
    // (concentrate usage) unless this bin is a last chance.
    let rel = (bin_residual as f64 - mean_residual) / (bin_capacity as f64);
    score += 12.0 * rel;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Penalize leaving large dead space that no small item can use.
    if post_residual > 0 && post_residual < 10 {
        score -= 15.0; // near-perfect fill
    }
    if post_residual > 50 {
        score += 6.0; // large dead space penalty
    }

    // Late in stream, be more conservative about spreading across bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * rel;

    // New-bin candidate: only choose it when no open bin fits well.
    if bin_residual == bin_capacity {
        let poor_fit_everywhere = fitting_bins_count <= 1
            || mean_residual < item_size as f64 * 0.5;
        if poor_fit_everywhere {
            score -= 20.0;
        } else {
            score += 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic bonus for small post-residual.
    let tight = (post_residual as f64 / bin_capacity as f64).powi(2);
    score += 12.0 * tight;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        // Dead space below minimum item size is essentially wasted.
        score -= 15.0;
    }

    // Penalize bins with large residual waste relative to mean state.
    if bin_residual as f64 > mean_residual + 1.0 {
        score += 0.35 * (bin_residual as f64 - mean_residual);
    } else {
        score -= 0.15 * (mean_residual - bin_residual as f64);
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward;
    // if next item would be blocked by post-residual, penalize slightly.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let gap = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - gap / bin_capacity as f64);
        } else if next_item_size <= bin_residual {
            // This bin could have served the next item better; mild penalty.
            score += 4.0;
        }
    }

    // Time horizon: early in stream, be more selective (penalize loose fits);
    // late in stream, prefer consolidation into open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 6.0 * tight;
    score -= progress * 3.0;

    // Many open bins: encourage filling existing ones to close bins out.
    if open_bins_count > 3 {
        score -= 0.8 * (open_bins_count as f64).ln();
    }

    // New-bin candidate: only attractive when item is huge relative to capacity
    // and fits poorly everywhere else.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        score = 45.0 - 30.0 * fill_ratio;
        if fitting_bins_count == 0 {
            score -= 50.0; // no alternative: must open new bin
        }
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 8.0; // room for lookahead item in fresh bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let x = post / cap; // normalized post residual in [0,1]
    let t = progress;
    // Smooth interaction: polynomial in x weighted by progress
    let poly = x * x * (1.0 - x) * (1.0 + t * 2.0) + x * (1.0 - t) * 0.5;
    score += poly * cap * 0.35;

    // Penalize large dead space more as stream progresses (quartic-ish term)
    score += (x * x * x * x) * cap * t * 0.8;

    // Reward tight fits (small post residual) especially mid-stream
    let tight = 1.0 - x;
    score -= tight * tight * cap * (0.5 + 0.5 * (1.0 - t)) * 0.3;

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= cap * 1.5;
    }

    // Lookahead: if next item fits in post residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 8.0 + next_item_size as f64 * 0.15;
    }

    // Mild penalty for proliferating open bins relative to mean residual
    score += (open_bins_count as f64).ln().max(0.0) * 0.5;

    // Nudge toward bins with below-mean residual (consolidation)
    score += (mean_residual - bin_residual as f64) * 0.05;

    // New-bin candidate: make it moderately unattractive unless everything else is bad
    if bin_residual == bin_capacity {
        score += cap * 0.6 + post * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into small
    // residue classes (mod 10) are near-perfect fits and get rewarded.
    let pr = post_residual;
    let class = pr % 10;
    if pr == 0 {
        score -= 60.0; // perfect closure
    } else if class == 0 {
        score -= 20.0; // round leftover, easy to reuse
    } else if class <= 3 {
        score -= 5.0;
    } else if class >= 7 {
        score += 6.0; // awkward large-ish leftover
    }

    // Dead-space penalty: leftover too small for the minimum item size (1)
    // but too small for typical items — penalize tiny unusable gaps.
    if pr > 0 && pr < 10 {
        score += 12.0;
    }

    // Integer-division threshold: how many "average next items" fit afterward.
    let lookahead = if next_item_size > 0 { next_item_size } else { 0 };
    if lookahead > 0 {
        let fits_next = (pr / lookahead.max(1)) as f64;
        if fits_next >= 1.0 {
            score -= 14.0 * fits_next.min(3.0); // room reserved for lookahead
        } else {
            score += 10.0; // next item cannot follow here
        }
        // Exact harmonic match: leftover equals next item size exactly
        if pr == lookahead {
            score -= 25.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize mildly unless current bins are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score += 45.0 - 30.0 * fragmentation / (bin_capacity as f64) - 10.0 * progress;
    }

    // Prefer filling fuller bins (small residual before placement).
    score += (bin_residual as f64 / bin_capacity as f64) * 8.0;

    // Coupling with mean residual: bins tighter than average are better targets.
    score += (mean_residual - bin_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small to be useful later
    // (below the minimum plausible item size) are heavily penalized,
    // but a perfect fit (post_residual == 0) is strongly rewarded.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score += (10 - post_residual) as f64 * 3.0;
    } else if post_residual >= 80 {
        // Large residual left behind: the item was small relative to bin,
        // mild penalty to prefer filling bins more fully.
        score += 5.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 5.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than opening new ones.
    score += open_bins_count as f64 * 0.5;

    // Mean residual coupling: if average residual is high, tighten selection
    // toward bins with low residual (tight fits).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    } else {
        score += 2.0;
    }

    // New-bin candidate: make it moderately attractive only when existing
    // bins would leave bad dead space, otherwise discourage it.
    if bin_residual == bin_capacity {
        score += 8.0;
        // If current item is large, a fresh bin is fine.
        if item_size >= 50 {
            score -= 6.0;
        }
        // If next item is large too, opening fresh bin is reasonable.
        if next_item_size >= 50 {
            score -= 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with a slight superlinear penalty
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 40.0;

    // Lookahead: reward if next item fits exactly into post_residual (perfect chaining)
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect 2-step match
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // reward proportionally to how well next item fills the remainder
            score -= 35.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item does NOT fit: the remaining space risks becoming dead space
            let gap = (next_item_size - post_residual) as f64;
            score += 15.0 * (gap / bin_capacity as f64);
        }
    } else {
        // last item: minimize residual as much as possible
        score -= 20.0;
    }

    // Compare post_residual against mean residual across open bins:
    // leaving this bin far below mean wastes capacity relative to others
    score += 0.6 * (mean_residual - post_residual as f64).max(0.0);
    // slight reward if we reduce an outlier-large residual (balance the pool)
    score -= 0.3 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // this item is large relative to capacity and few bins fit it.
    if bin_residual == bin_capacity {
        let is_new_bin = true;
        let _ = is_new_bin;
        // new bin always leaves residual = capacity - item_size, no waste yet
        score -= 10.0;
        // but penalize opening new bins when plenty of bins already fit the item
        if fitting_bins_count > 0 {
            score += 25.0 * (fitting_bins_count as f64).min(5.0);
        }
        // early in the stream, opening bins is cheaper (more future items to fill them)
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 30.0 * (1.0 - progress);
        // if next item is large and won't fit anywhere else, new bin is safer
        if next_item_size > 0 && next_item_size > bin_capacity.saturating_sub(item_size) {
            score -= 20.0;
        }
    }

    // Mild penalty when many bins are open and this placement leaves a tiny useless sliver
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize small post_residual quadratically.
    score -= (post_residual as f64).powi(2) / (bin_capacity as f64).powi(2) * 30.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Dead-space penalty: residual too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 5 {
        score += 20.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 3 {
        score += 3.0 * (fitting_bins_count as f64 - 3.0);
    }

    // Lookahead coupling: if the next item fits into post_residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
        // Extra reward for a near-exact chain fit.
        let chain_gap = post_residual as f64 - next_item_size as f64;
        score -= (10.0 - chain_gap.min(10.0)) * 0.8;
    }
    // If next item does NOT fit in post_residual, mild penalty for fragmenting.
    else if next_item_size > post_residual && next_item_size > 0 {
        score += 5.0;
    }

    // Global pressure: when many open bins exist, prefer consolidating into fuller bins.
    let fullness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    let bin_pressure = (open_bins_count as f64 / (open_bins_count as f64 + 4.0)).min(1.0);
    score -= fullness * 10.0 * bin_pressure;

    // Mean residual deviation: prefer bins whose residual is below the mean (fuller than average).
    score += (mean_residual - bin_residual as f64) * 0.15;

    // Time horizon: early in the stream, be more willing to open new bins (favor keeping
    // flexibility); late in the stream, pack aggressively to close out bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let new_bin_penalty = 20.0 * progress + 5.0;
    if bin_residual == bin_capacity {
        score += new_bin_penalty;
        // Opening a new bin is attractive only if current bin would leave a large odd gap
        // and there are already many bins open.
        if post_residual > 0 && post_residual < item_size as u32 / 2 {
            score -= 8.0;
        }
    }

    // Mild preference for placing large items into tight bins regardless of state.
    score -= (item_size as f64 / 100.0) * (100.0 - post_residual as f64).max(0.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let norm_pr = pr / cap; // 0..1
    let poly = norm_pr * norm_pr * (1.0 + 3.0 * progress) - norm_pr * (1.0 + progress);
    score += 20.0 * poly;

    // Penalize residuals that cannot fit the lookahead item
    if next_item_size > 0 {
        let gap = next_item_size as f64 - pr;
        if gap > 0.0 {
            score += 6.0 * (gap / cap).powi(2) * (1.0 + 2.0 * progress);
        } else {
            score -= 4.0 * (1.0 - (pr / cap)) * (1.0 - progress);
        }
    }

    // Reward tight fits, more strongly early in the stream
    let tightness = 1.0 - (pr / cap);
    score -= 8.0 * tightness * tightness * (1.0 - progress);

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Mild preference for reducing mean residual deviation
    score -= 0.3 * (mean_residual - pr).abs() / cap;

    // New-bin candidate: penalize slightly so it is chosen only when open bins fit poorly
    if bin_residual == bin_capacity {
        score += 3.0 + 4.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space value depends on which
    // "residue class" the leftover falls into (mod 10 granularity).
    let post = post_residual;
    let class = post % 10;
    // Residues 1..9 (small non-zero leftovers) are nearly unusable -> penalize.
    if post > 0 && post < 10 {
        score += 25.0 - 2.0 * class as f64;
    }
    // Perfect fit class: post == 0 is ideal.
    if post == 0 {
        score -= 60.0;
    }

    // Integer-division thresholds: leftover in [10, 30] can host mid items.
    if post >= 10 && post <= 30 {
        score -= 8.0;
    }
    // Large leftover in [31, 60]: moderate value.
    if post > 30 && post <= 60 {
        score -= 4.0;
    }

    // Capacity fraction coupling: how much of the bin the item consumes.
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill_frac;

    // Lookahead harmonic match: does next_item_size fit exactly in post_residual?
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 50.0; // perfect chained fit
        } else if next_item_size <= post {
            let next_class = (post - next_item_size) % 10;
            score -= 10.0 - next_class as f64; // tighter chain, better
        } else {
            score += 5.0; // next item cannot follow here
        }
    }

    // Last-chance bin: strongly prefer using it to avoid a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate: penalize moderately so it wins only when all
    // open bins would create severe dead space.
    if bin_residual == bin_capacity {
        score += 15.0;
        // Opening a new bin is attractive early in the stream or when
        // item is huge (would strand small residual bins anyway).
        let progress = step_index as f64 / total_items.max(1) as f64;
        if item_size >= 70 {
            score -= 12.0;
        }
        if progress < 0.2 {
            score -= 5.0;
        }
        if open_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
    }

    // Mean residual coupling: if this bin's residual is far below mean,
    // it is an outlier worth filling (consolidate fragmented space).
    let resid_f = bin_residual as f64;
    if resid_f < mean_residual - 15.0 {
        score -= 6.0;
    } else if resid_f > mean_residual + 25.0 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size (1..10)
    // are essentially dead space; penalize non-linearly.
    let dead_threshold = 10.0f64;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 12.0;
    }

    // Reward near-perfect fills strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Prefer bins whose post_residual can still accommodate a plausible future item
    // (either the lookahead item or typical small items).
    if post_residual >= next_item_size as u32 && next_item_size > 0 {
        score -= 8.0;
    }
    if post_residual >= 10 && post_residual < item_size {
        score -= 5.0; // gap still usable for small future items
    } else if post_residual > 0 && post_residual < 10 {
        score += 15.0; // awkward sliver
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, avoid spreading; with few, be lenient.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * 2.0;

    // Match against mean residual: bins already tight are better targets.
    let tightness = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += tightness * 20.0;

    // New-bin candidate baseline: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        score = 55.0 + pressure * 3.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // forced new bin
        } else if fitting_bins_count == 1 {
            score += 25.0; // keep the last-chance bin attractive instead
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 / (1.0 + diff);
        // exact match for next item
        if post_residual == next_item_size {
            score -= 120.0;
        }
        // next item won't fit here: mild penalty proportional to wasted lookahead
        if post_residual < next_item_size {
            score += 0.25 * next_item_size as f64;
        }
    }

    // Compare post_residual relative to mean residual across open bins
    score -= 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // Penalize opening a new bin when decent fits exist
    if bin_residual == bin_capacity {
        score += 40.0 + 0.3 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score += 10.0;
        }
    }

    // Penalize large dead space that can't fit typical items
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Early stream: be slightly greedy toward tight fits; later: consolidate
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * (1.0 - progress) / (1.0 + post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: penalize bins whose residual is close to item size.
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score -= 30.0 * (-tightness * 8.0).exp();

    // Dead-space penalty for large leftover gaps that few items can fill.
    if post_residual > 0 && post_residual < 10 {
        score -= 15.0; // near-perfect fill
    } else if post_residual >= 10 && post_residual < 20 {
        score += 5.0; // awkward gap zone
    } else if post_residual >= 60 {
        score += 10.0 * (post_residual as f64 - 60.0) / 40.0; // very wasteful
    }

    // Lookahead: reward if next item fits in the post residual (chaining).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 20.0 * (1.0 - (next_item_size as f64 / post_residual.max(1) as f64));
        } else {
            score += 6.0; // next item won't chain here
        }
    }

    // Last-chance bonus: only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Prefer filling bins when many bins are open (consolidation pressure).
    score -= (open_bins_count as f64).ln() * (item_size as f64 / bin_capacity as f64) * 10.0;

    // Global residual alignment: favor bins below mean residual (fill the emptier? no—fill the fuller).
    if (bin_residual as f64) < mean_residual {
        score -= 8.0; // this bin is fuller than average -> use it up
    } else {
        score += 4.0;
    }

    // Time horizon: early in the stream, be more exploratory (weaker tightness pull);
    // late in stream, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 15.0 * progress * (item_size as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive if no open bin fits well.
    if bin_residual == bin_capacity {
        let base_penalty = 12.0 + 18.0 * progress;
        if fitting_bins_count == 0 {
            score -= 40.0; // must open new bin
        } else {
            score += base_penalty; // discourage abandoning open bins
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items.max(1) as f64;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let item = item_size as f64;

    // Non-linear waste penalty: post_residual squared, amplified by stream progress
    score += (post * post / cap) * (0.4 + 1.2 * progress);

    // Smooth reward for tight fits (low post_residual relative to capacity)
    let tightness = 1.0 - post / cap;
    score -= 18.0 * tightness * tightness * tightness;

    // Penalize creating residual that is small but nonzero (dead space)
    let dead = (post / cap) * (1.0 - post / cap);
    score += 14.0 * dead * (1.0 - progress);

    // Lookahead: reward if next item fits into post_residual (smooth interaction)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit_ratio = if post >= nxt { (post - nxt) / cap } else { 0.0 };
        let miss = if post >= nxt { 0.0 } else { (nxt - post) / cap };
        score -= 10.0 * (1.0 - fit_ratio * 2.0).max(0.0) * (1.0 - progress);
        score += 12.0 * miss * miss * 4.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0 * (1.0 - 0.5 * progress);
    }

    // Prefer fuller bins among many open bins (mild crowding pressure)
    let mean_gap = (mean_residual - post).max(0.0) / cap;
    score += 6.0 * mean_gap * (0.5 + progress);

    // New-bin candidate: penalize opening a bin unless current bin would be very tight
    if bin_residual == bin_capacity && bin_capacity > 0 {
        score += 30.0 - 20.0 * tightness;
    }

    // Mild penalty on open-bin proliferation late in stream
    score += (open_bins_count as f64).ln().max(0.0) * progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual lies in "usable"
    // classes (multiples of common small item sizes) are rewarded.
    let pr = post_residual;
    let cap = bin_capacity as f64;
    let fill_ratio = 1.0 - (pr as f64) / cap;

    // Reward tight fits strongly
    score -= 12.0 * fill_ratio * fill_ratio;

    // Dead-space penalty: residual too small for any plausible item (1..100)
    if pr > 0 && pr < 10 {
        score += 25.0;
    }

    // Harmonic classes: residuals that are multiples of 10 or 25 pair well
    // with typical item sizes drawn from coarse grids.
    if pr % 10 == 0 && pr > 0 {
        score -= 6.0;
    }
    if pr % 25 == 0 && pr > 0 {
        score -= 4.0;
    }
    // Odd/prime-ish residuals are awkward
    if pr % 2 == 1 && pr > 0 {
        score += 2.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual,
    // this is a perfect chain -> big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size <= pr {
            let new_pr = pr - next_item_size;
            // penalize leaving a tiny unusable remainder after the next item
            if new_pr < 10 {
                score += 10.0;
            }
            score -= 8.0 * (1.0 - (new_pr as f64) / cap);
        } else {
            // next item won't fit here; leftover must be large enough to matter
            if pr < next_item_size && pr > 0 {
                score += 5.0 * (pr as f64) / cap;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when
    // current bin would be left with awkward residual and stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // waste of a fresh bin equals capacity - item_size
        let fresh_waste = (bin_capacity - item_size) as f64;
        score = fresh_waste + 20.0 * progress;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 10.0;
        }
        // late in stream, prefer closing out existing bins
        if progress > 0.8 {
            score += 15.0;
        }
    }

    // Mild pressure to prefer bins below mean residual (consolidate fuller bins)
    score += 0.3 * ((bin_residual as f64) - mean_residual).max(-20.0).min(20.0);

    // Many open bins -> consolidate
    if open_bins_count > 4 {
        score -= 0.5 * fill_ratio;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold the
    // smallest plausible item (<= 12) are essentially wasted, so penalize
    // them super-linearly.
    if post_residual < 12 {
        score += 40.0 * (12.0 - post_residual as f64);
    } else if post_residual < 25 {
        // "awkward gap" zone: mildly penalize proportionally.
        score += 8.0 * (25.0 - post_residual as f64) / 13.0;
    } else {
        // Large residual capacity is valuable; reward tight fits.
        score -= 6.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead (k=2): strongly favor bins where the next item also fits
    // in the resulting residual; penalize if next item would be stranded.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
        } else if post_residual < next_item_size {
            score += 5.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Last-chance bin: if this is the only bin that fits, heavily favor
    // using it over opening a new bin (unless post_residual is dead space).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> discourage opening new ones,
    // encourage consolidating into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (10.0 + 20.0 * progress);
    score += pressure * 4.0;

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Only allow opening a new bin when existing bins would leave bad
    // dead space or no bin fits (fitting_bins_count == 0 handled by caller,
    // but empty-bin call sees fitting_bins_count of real bins).
    if bin_residual == bin_capacity {
        // Base new-bin cost: prefer existing bins by default.
        score += 20.0;
        // But if open bins are fragmented (low mean residual relative to item),
        // a fresh bin becomes attractive.
        if mean_residual < item_size as f64 * 1.2 && open_bins_count > 2 {
            score -= 35.0;
        }
        // Late in the stream with few bins open, opening fresh bins is cheap.
        if open_bins_count <= 1 {
            score -= 15.0;
        }
    } else {
        // Mild preference for bins whose residual is close to the item
        // (best-fit flavor) beyond the raw post_residual term.
        score -= 3.0 * (1.0 - (post_residual as f64 / bin_residual.max(1) as f64));
    }

    // Tie-break toward bins with below-average residual (consolidate fuller bins).
    if bin_residual < bin_capacity {
        score += 0.05 * (bin_residual as f64 - mean_residual);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual equals next item size exactly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near match: next item still fits with small leftover.
    else if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 10 {
        score -= 25.0 - (post_residual - next_item_size) as f64;
    }
    // Next item cannot use the leftover: penalize dead space proportionally.
    else if next_item_size > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Compare leftover against mean residual across open bins.
    let mr = if mean_residual.is_finite() { mean_residual } else { bin_capacity as f64 };
    let dev = post_residual as f64 - mr;
    score += 0.15 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Reward filling bins tightly (small absolute leftover relative to item).
    score -= (item_size as f64 / bin_capacity as f64) * 20.0;

    // Late in the stream, prefer closing bins tightly (leaner packing).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64) * 0.3;

    // New-bin candidate: only attractive when current bins are crowded or fit is bad.
    if bin_residual == bin_capacity {
        let crowded = open_bins_count == 0
            || (fitting_bins_count <= 1)
            || (post_residual as f64) > mr + 30.0;
        if crowded {
            score -= 15.0 + 0.1 * open_bins_count as f64;
        } else {
            score += 50.0; // discourage opening new bins when a decent fit exists
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly (waste minimization).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // Tightness ratio: prefer bins where item fills a large fraction of residual.
    let fill = item_size as f64 / bin_residual as f64;
    score -= fill * 50.0;

    // Penalize dead space: residuals below the minimum item size are unusable.
    if post_residual < 10 {
        score += 60.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Lookahead: if the next item fits into the post-residual, reward; otherwise penalize.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0;
        } else if post_residual > 0 && next_item_size > post_residual {
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
        // If next item fits exactly after placement, extra reward.
        if post_residual == next_item_size {
            score -= 40.0;
        }
    }

    // Prefer fuller bins when many bins are open (consolidation pressure).
    score += mean_residual * 0.15;
    score -= (bin_residual as f64 - mean_residual) * 0.3;

    // New-bin candidate handling: make opening a new bin costly unless current
    // bin fits are all poor and many bins already exist.
    if bin_residual == bin_capacity {
        score += 150.0;
        // In early stream, opening bins is cheap and useful.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 100.0;
        // If open bins are already fragmented, discourage more bins.
        score += open_bins_count as f64 * 4.0;
        // If next item is large, a fresh bin has value.
        if next_item_size >= 50 {
            score -= 30.0;
        }
    }

    // Mild time-horizon term: late in the stream, be more conservative with new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let base = pr / cap;
    let progress = step_index as f64 / total_items as f64;

    let mut score = base;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // later in the stream, tight fits matter more (dead space penalized super-linearly).
    let tight = base * base;
    score += tight * (0.5 + 2.0 * progress);

    // Reward near-perfect fits (post_residual close to 0) with a smooth bump.
    let perfect = 1.0 - base;
    score -= perfect * perfect * perfect * 3.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 6.0 + 4.0 * perfect;
    }

    // Lookahead: if the next item would fit in the post-residual, reward leaving that gap.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let gap = (pr - nxt) / cap;
            score -= 2.0 * (1.0 - gap) * (1.0 - gap);
        } else {
            // next item cannot use this gap; penalize large leftover proportionally
            score += 1.5 * base * base;
        }
    }

    // Slight preference for keeping many open bins consolidated: penalize when
    // this bin's residual is far above the mean residual (hoarding space).
    let dev = (pr - mean_residual) / cap;
    score += 0.5 * dev * dev;

    // New-bin candidate: neutral-ish baseline; only chosen when open bins score poorly.
    if bin_residual == bin_capacity {
        score = 12.0 + 4.0 * progress - 2.0 * perfect;
        if fitting_bins_count == 0 {
            score -= 20.0; // must open a new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is unbeatable.
    if post_residual == 0 {
        return -10000.0;
    }

    // Harmonic class of the post-residual: bins whose leftover falls into
    // "small item friendly" classes (multiples of 10, or < 10) are more useful.
    let pr = post_residual;
    let class_bonus = if pr < 10 {
        6.0
    } else if pr % 10 == 0 {
        5.0
    } else if pr % 5 == 0 {
        2.5
    } else {
        0.0
    };
    score -= class_bonus;

    // Does the lookahead item fit exactly or nicely into post_residual?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0; // chain a perfect fit
        } else if next_item_size <= pr {
            let nr_post = pr - next_item_size;
            if nr_post % 10 == 0 || nr_post < 10 {
                score -= 12.0;
            } else {
                score -= 4.0;
            }
        } else {
            // lookahead cannot use this leftover: penalize proportionally
            score += (next_item_size - pr) as f64 * 0.3;
        }
    }

    // Dead-space penalty: residuals that no typical small item can use.
    if pr < 10 {
        score -= 8.0; // near-zero waste is fine
    } else if pr < 20 && pr % 10 != 0 {
        score += 6.0; // awkward wedge
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    // or this bin would leave a large awkward residual.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowded = open_bins_count as f64 / (1.0 + mean_residual / 20.0);
        // Prefer new bin late in the stream or when open bins have low mean residual
        let new_bin_penalty = 30.0 + 20.0 * (1.0 - progress) - crowded.min(15.0);
        // If current placement wastes a lot, new bin looks better
        let waste_pressure = if pr > 40 { (pr - 40) as f64 * 0.5 } else { 0.0 };
        score += new_bin_penalty - waste_pressure;
    }

    // Mild pressure to consolidate when many bins are open.
    score -= (open_bins_count as f64).ln().max(0.0) * 1.5;

    // Slight preference for bins tighter than average (fills fuller bins first).
    score += (mean_residual - bin_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for typical future items are wasted.
    // Penalize small but nonzero residuals harshly (nonlinear "gap tax").
    if post_residual > 0 {
        let gap = post_residual as f64;
        if gap < 10.0 {
            // tiny sliver: nearly certain dead space
            score += 60.0 * (10.0 - gap) / 10.0;
        } else if next_item_size > 0 && (post_residual as u32) < next_item_size {
            // gap can't hold the lookahead item: likely dead space
            score += 25.0 * (1.0 - gap / 100.0);
        }
    }

    // Reward exact / tight fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    } else {
        let tightness = item_size as f64 / bin_residual as f64;
        score -= 30.0 * tightness * tightness;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead synergy: if the next item fits exactly in the post-residual, reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins
    // and make the new-bin candidate unattractive.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.15 * open_bins_count as f64 * (1.0 - 0.5 * progress);

    // New-bin candidate: penalize relative to mean residual of open bins so that
    // a new bin is only opened when existing bins would create large dead space.
    if bin_residual == bin_capacity {
        score += 35.0 + mean_residual * 0.5 + 0.2 * open_bins_count as f64;
        // early in the stream, opening bins is cheap and useful
        score -= 40.0 * (1.0 - progress);
    }

    // Slight preference for bins with below-average residual (keeps big gaps available).
    if bin_residual as f64 > mean_residual {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact or near-exact fit.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0 + (5.0 - post_residual as f64) * 20.0;
    }

    // 2-step lookahead: reward when next item exactly fills post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            // Next item fits too: penalize leftover beyond next item.
            let leftover_after_next = post_residual - next_item_size;
            score += leftover_after_next as f64 * 1.5;
            if leftover_after_next <= 10 {
                score -= 50.0;
            }
        } else {
            // Next item won't fit here: penalize bins that leave big dead space.
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
    }

    // Compare post_residual against mean residual: prefer leaving residuals near mean.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 300.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless existing
    // fits are poor (large post_residual).
    if bin_residual == bin_capacity {
        score += 150.0;
        if item_size >= 80 {
            score -= 50.0; // big items fine in fresh bin
        }
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 40.0; // room for lookahead item in fresh bin
        }
    }

    // Late in stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 30.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Many open bins: prefer tightening existing ones.
    score += open_bins_count as f64 * 0.2 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 12.0 * fit_ratio * fit_ratio;

    // Penalize large wasted gap between item and residual (dead space).
    let gap = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 4.0 * gap * gap;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: reward if next item fits into post_residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            score += 3.0 * (next_item_size as f64 / bin_capacity as f64);
        }
    }

    // Prefer bins whose residual is below the mean residual (consolidating waste).
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 5.0 * dev;

    // Slight preference to fill bins with more residual (use fuller bins first).
    score -= 0.05 * (bin_residual as f64 / bin_capacity as f64) * (open_bins_count as f64).ln().max(1.0);

    // Early in stream: more willing to open new bins (exploration); late: consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses (favor consolidation),
        // but relax penalty if open bins are nearly full on average.
        let avg_fullness = 1.0 - mean_residual / bin_capacity as f64;
        score += 15.0 + 20.0 * progress - 12.0 * avg_fullness;
    }

    // Late stream: extra penalty for leaving awkward mid-range residuals.
    if progress > 0.7 && post_residual > 0 && post_residual < 10 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let norm_post = post_residual as f64 / bin_capacity as f64;
    let norm_item = item_size as f64 / bin_capacity as f64;

    // Smooth non-linear coupling: post_residual value discounted/amplified by progress
    let poly = norm_post * norm_post * (1.0 + progress) - norm_post * norm_item * (1.0 + 2.0 * progress);
    score += 40.0 * poly;

    // Perfect fit reward, stronger late in the stream
    if post_residual == 0 {
        score -= 60.0 + 80.0 * progress;
    }

    // Lookahead: reward if next item fits the post residual
    if next_item_size > 0 {
        let fits_next = (post_residual as u64 >= next_item_size as u64) as f64;
        let tightness = 1.0 - (next_item_size as f64 / bin_capacity as f64);
        score -= 25.0 * fits_next * (0.5 + 0.5 * progress) * (0.5 + 0.5 * tightness);
    } else {
        // Last item: strongly prefer tight fits
        score -= 50.0 * (1.0 - norm_post);
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Penalize bins far from mean residual (fragmentation), scaled by crowding
    let crowd = (open_bins_count as f64 / (open_bins_count as f64 + 5.0)).sqrt();
    score += 10.0 * crowd * ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs();

    // New-bin candidate: baseline penalty that grows with progress and existing bins
    if bin_residual == bin_capacity {
        score += 30.0 + 60.0 * progress + 2.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into
    // capacity-fraction buckets. Residuals that fall into small "dead" classes
    // (<= 20% of capacity) are excellent closures; large leftovers waste space.
    let frac = post_residual as f64 / cap;
    if frac <= 0.05 {
        score -= 25.0; // near-perfect closure
    } else if frac <= 0.20 {
        score -= 12.0;
    } else if frac <= 0.40 {
        score += 4.0;
    } else if frac <= 0.60 {
        score += 10.0;
    } else {
        score += 18.0; // more than half a bin wasted after placement
    }

    // Modulo-10 class coupling: if the next item exactly matches the post
    // residual (perfect follow-up fit), strongly reward this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            // reward proportionally to how tightly the next item fits
            let gap = post_residual - next_item_size;
            if gap <= 10 {
                score -= 15.0;
            } else if gap <= 25 {
                score -= 5.0;
            }
        } else {
            // next item cannot use the leftover at all: penalize dead space
            score += 6.0;
        }
    }

    // Integer division threshold on post_residual: leftover divisible into
    // common item-size classes (multiples of 10, 20, 25) is reusable.
    if post_residual > 0 && post_residual <= bin_capacity {
        let reusable = post_residual % 10 == 0 || post_residual % 25 == 0;
        if reusable && next_item_size > 0 && next_item_size <= post_residual {
            score -= 8.0;
        }
    }

    // Last-chance logic: if this is the only bin that fits, avoid opening a
    // new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        let tightness = item_size as f64 / bin_residual as f64;
        if tightness >= 0.6 {
            score -= 20.0;
        } else {
            score -= 5.0;
        }
    }

    // New-bin candidate handling: an empty bin is a fresh resource. Prefer it
    // only when no open bin offers a good fit (high mean residual spread or
    // many open bins with large residuals). Otherwise discourage it mildly.
    if bin_residual == bin_capacity {
        let avg_frac = mean_residual / cap;
        // If existing bins are already quite full on average, a new bin is fine.
        if avg_frac < 0.5 && open_bins_count > 0 {
            score += 15.0; // keep using existing space
        } else {
            score += 5.0;
        }
        // Late in the stream, opening bins freely is less costly.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
    }

    // Mild preference for fuller bins overall (best-fit flavor).
    score -= (item_size as f64 / bin_residual.max(1) as f64) * 5.0;

    // Slight penalty for spreading across many open bins.
    score += (open_bins_count as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps of 1..10 are almost unusable (min item is 1,
    // but tiny gaps rarely match future items) -> strong penalty scaled by gap smallness.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 6.0;
    }
    // Perfect fit: massive reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward leaving gaps that exactly fit the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        score -= 4.0; // gap still usable by next item
    } else if next_item_size > 0 && post_residual > 0 {
        score += 8.0; // gap too small for next item
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Tightness reward: fraction of bin consumed.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= fill * 15.0;

    // Open-bin pressure: mildly discourage opening new bins when many are open.
    let new_bin = bin_residual == bin_capacity;
    if new_bin {
        score += 12.0 + open_bins_count as f64 * 1.5;
        // Early in stream, opening bins is cheaper; late, conserve.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 8.0;
    } else {
        score -= open_bins_count as f64 * 0.3;
    }

    // Prefer bins below mean residual (consolidating slack).
    score += (mean_residual - bin_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0 + 0.5 * (post_residual as f64 - next_item_size as f64);
    }

    // Penalize dead space that is too small for any plausible item (items >= 1).
    if next_item_size > 0 && post_residual < next_item_size {
        score += 0.3 * post_residual as f64;
    }

    // Relative-to-mean coupling: prefer bins tighter than the mean residual.
    score += 0.4 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize opening new bins when open bins exist, scaled by stream progression.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 + 20.0 * progress;
        // New bin is acceptable if the item fits poorly everywhere else.
        if fitting_bins_count <= 1 {
            score -= 45.0;
        }
    }

    // Mild preference for filling existing bins densely.
    score += 0.1 * item_size as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits (low post residual) with a non-linear bonus.
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += tightness * tightness * 20.0;

    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Dead space penalty: residuals too small for the smallest item (1..=100 range, use 10 as soft floor)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: reward bins whose post residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += 6.0; // creating a gap that wastes the next item
        }
        // Bonus if post residual exactly or nearly matches next item
        let gap = (post_residual as i64 - next_item_size as i64).abs();
        score += gap as f64 * 0.3;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when current fits are poor.
    if bin_residual == bin_capacity {
        // Neutral base; penalize opening new bins when there are few open bins or early stream.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_bin_score = 30.0;
        new_bin_score -= progress * 10.0; // later in stream, new bins slightly more acceptable
        new_bin_score += (open_bins_count as f64) * 2.0; // many open bins => discourage opening more
        if next_item_size > 0 && next_item_size as f64 > mean_residual {
            new_bin_score -= 12.0; // next item won't fit typical residuals; fresh bin useful
        }
        if fitting_bins_count == 0 {
            new_bin_score -= 40.0; // no alternative
        }
        score += new_bin_score;
    }

    // Global state coupling: if mean residual is high, prefer bins below mean (consolidate small leftovers).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    // Mild time pressure: early stream, be conservative with big bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let next = next_item_size as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // later in the stream, tighter fits (small post_residual) are rewarded more strongly.
    let coupling = norm_pr * (1.0 + progress * (1.0 - norm_pr) * 4.0);
    score += coupling * 2.0;

    // Dead-space penalty if the next item cannot fit in the post residual.
    if next > 0.0 && next > pr {
        let waste = (next - pr) / cap;
        score += waste * (20.0 + 30.0 * progress) * (1.0 + norm_pr);
    } else if next > 0.0 && next <= pr {
        // Reward leaving room for the lookahead item, smoothly scaled.
        let snug = 1.0 - ((pr - next) / cap);
        score -= snug * 8.0 * (0.5 + 0.5 * progress);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 10.0 * progress;
    }

    // Penalize opening a new bin, especially early when open bins exist.
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        score += 25.0 * scarcity * (1.2 - progress)
            + 0.5 * open_bins_count as f64;
    } else {
        // Slight reward for using bins that keep residuals near the mean (balance).
        let dev = (pr - mean_residual).abs() / cap;
        score += dev * 5.0;
    }

    // Smooth non-linear term: quadratic in normalized residual, modulated by progress.
    score += (norm_pr * norm_pr) * 10.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals that form "nice" classes
    // (multiples of 10, or small enough to be near-dead) get class-based bonuses.
    let post = post_residual;
    let class = post % 10;

    // Reward residuals that align to decade boundaries (good for future packing).
    if post == 0 {
        score -= 40.0; // perfect fit
    } else if class == 0 {
        score -= 12.0;
    } else if class >= 7 {
        score += 8.0; // awkward large-but-unusable chunk
    }

    // Penalize tiny dead space that nothing (min size 1..10) can use well.
    if post > 0 && post < 10 {
        score += 15.0;
    }

    // Coupling with next item: if the next item fits exactly in post_residual,
    // strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 30.0;
        } else if next_item_size < post {
            let gap = post - next_item_size;
            if gap < 10 {
                score -= 10.0;
            } else {
                score += (gap as f64) * 0.1;
            }
        } else {
            // next item won't fit here; residual becomes dead weight
            score += (post as f64) * 0.15;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only open a new bin when current residuals
    // are too fragmented to be useful.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = mean_residual - (post as f64);
        // Penalize opening a new bin unless existing bins are badly fragmented.
        score += 20.0 - fragmentation * 0.3 - progress * 5.0;
        if open_bins_count == 0 {
            score -= 50.0; // must open first bin
        }
    }

    // Mild preference for tighter bins overall (below mean residual).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - (post_residual as f64) * 4.0; // gap 1 -> +56, gap 9 -> +24
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 40.0;
    } else if post_residual < 20 {
        score += 15.0 - (post_residual as f64) * 0.5;
    }

    // Reward tight fits relative to item size.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 10.0;

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead (k=2): penalize leaving a gap smaller than the next item,
    // reward leaving a gap that exactly or comfortably fits the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack == 0.0 {
                score -= 20.0; // next item fills bin perfectly
            } else if slack < 10.0 {
                score += 8.0; // near-perfect but leaves small dead space after next
            } else {
                score -= slack * 0.1;
            }
        } else if post_residual > 0 {
            score += (next_item_size as f64 - post_residual as f64) * 0.6;
        }
    }

    // Open-bin pressure: when many bins are open, discourage spreading;
    // when few bins are open, tolerate opening new bins less.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.3 + 0.7 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins already open,
        // but allow when mean residual across open bins is low (fragmented).
        score += 30.0 + pressure - mean_residual.min(50.0) * 0.4;
    } else {
        score -= pressure * 0.15;
    }

    // Mild preference for bins with lower residual among fitting bins
    // (best-fit style) scaled by stream progress.
    score += (bin_residual as f64 / bin_capacity as f64) * (5.0 + 10.0 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: reward exact chain fits (item then next item).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect two-item fill
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - slack / bin_capacity as f64); // tight chain fit
        } else {
            // next item cannot follow here: penalize proportional to dead space
            let dead = (next_item_size - post_residual) as f64;
            score += 0.8 * dead;
        }
    } else {
        // Last item: just minimize leftover
        score += 0.0;
    }

    // Compare post_residual against mean residual: leaving below-mean residual
    // means this bin is tighter than average -> good consolidation.
    score -= 0.5 * (mean_residual - post_residual as f64).max(0.0);
    score += 0.3 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin bonus: if this is the only fitting bin, strongly prefer it
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit wastes space.
    if bin_residual == bin_capacity {
        let waste = post_residual as f64;
        // Opening a fresh bin is good only if the item is large (little waste left)
        // and no good chain fit exists; otherwise prefer existing bins.
        score = waste + 40.0 - 0.5 * item_size as f64;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 35.0; // fresh bin allows a good chain too
        }
        // As stream progresses, opening bins becomes less attractive.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 * progress;
    }

    // Slight preference for filling bins among many open bins.
    score += 0.2 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero is good.
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += tightness * tightness * 40.0;

    // Penalize leaving dead space that cannot fit typical future items.
    if post_residual > 0 && post_residual < 10 {
        score -= 15.0; // tiny gap = essentially full, excellent
    } else if post_residual >= 10 && post_residual < 20 {
        score -= 5.0;
    } else if post_residual > 60 {
        score += 12.0; // large leftover = wasteful split
    }

    // Lookahead: bonus if post_residual exactly accommodates next item.
    if next_item_size > 0 {
        let gap = post_residual as i64 - next_item_size as i64;
        if gap == 0 {
            score -= 30.0; // perfect chain fill
        } else if gap > 0 && gap < 10 {
            score -= 18.0; // next item fits snugly afterwards
        } else if gap < 0 && (-gap) as u32 <= 10 {
            score += 10.0; // next item barely doesn't fit: bad
        }
    }

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 4 {
        score += 2.0 * (fitting_bins_count as f64 - 4.0); // many options: be pickier
    }

    // Time horizon: early in stream, be conservative with open bins;
    // late in stream, consolidate aggressively into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let consolidation_bonus = 10.0 * progress;
    if bin_residual != bin_capacity {
        score -= consolidation_bonus;
    }

    // New-bin candidate handling: opening a new bin is attractive when
    // mean residual across open bins is low (fragmented state) or when
    // the item is large relative to the bin.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / bin_capacity as f64).max(0.0);
        let item_pressure = item_size as f64 / bin_capacity as f64;
        // Penalize new bins generally; relax penalty when state is fragmented.
        score += 55.0 - 35.0 * fragmentation - 20.0 * item_pressure;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // fresh bin can serve the upcoming large item too
        }
    }

    // Mild preference for bins already below mean residual (balancing loads).
    if bin_residual != bin_capacity {
        let dev = bin_residual as f64 - mean_residual;
        score += 0.08 * dev;
    }

    // Slight noise-free tie-breaker toward fuller bins.
    score -= 0.05 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let residual_norm = post / cap;

    // Base: tight fits are good (low post_residual).
    let mut score = residual_norm;

    // Non-linear polynomial coupling of residual with stream progress:
    // late in the stream, waste matters more, so amplify small residuals.
    let progress_coupling = residual_norm * (1.0 + 2.0 * progress * (1.0 - residual_norm));
    score += 0.5 * progress_coupling * residual_norm;

    // Smooth quadratic penalty for mid-sized leftover space (dead zone).
    let mid_waste = residual_norm * (1.0 - residual_norm);
    score += 1.2 * mid_waste * mid_waste;

    // Reward filling a bin almost completely (smooth exponential bonus).
    score -= (1.0 - residual_norm).exp() * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 2.0 + 1.5 * progress;
    } else if fitting_bins_count > 1 {
        // Mild penalty when many alternatives exist, scaled by openness.
        score += 0.1 * (fitting_bins_count as f64).ln();
    }

    // Prefer bins whose residual is below the mean (already fragmented bins
    // should be drained first), smooth coupling with mean residual.
    let mean_norm = mean_residual / cap;
    score += 0.4 * (residual_norm - mean_norm);

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 0.8 * (1.0 - (next_item_size as f64 / post)).powi(2);
    } else if next_item_size > 0 {
        // Next item won't fit here: penalize leaving awkward gaps.
        score += 0.3 * residual_norm;
    }

    // New-bin candidate handling: an empty bin is a fresh resource.
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive when existing bins would waste a lot
        // or when few bins fit the item (avoid fragmenting scarce capacity).
        let waste_penalty = 1.5 * residual_norm + 0.5 * mid_waste;
        let scarcity_bonus = if fitting_bins_count <= 1 { 3.0 } else { 0.0 };
        let open_scale = (open_bins_count as f64).ln().max(1.0);
        score = waste_penalty + scarcity_bonus + 0.2 * open_scale + 0.5 * (1.0 - progress);
        // Early in the stream, opening fresh bins is cheap and keeps options.
        score -= 1.0 * (1.0 - progress) * (1.0 - progress);
    }

    // Penalize bins that are nearly full relative to open-bin count pressure.
    score += 0.05 * (open_bins_count as f64).sqrt() * residual_norm;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize dead space into capacity fractions.
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap;

    // Reward small post_residual (tight fits) super-linearly.
    score -= (1.0 - frac) * (1.0 - frac) * 20.0;

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Harmonic classes: post_residual divisible by common item sizes (10, 20, 25, 50)
    // leaves reusable "harmonic" chunks. Penalize otherwise.
    let harmonic = post_residual % 10 == 0 || post_residual % 25 == 0 || post_residual % 50 == 0;
    if harmonic {
        score -= 8.0;
    } else if post_residual > 0 {
        score += 6.0;
    }

    // Lookahead: if next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            let next_waste = post_residual - next_item_size;
            // Harmonic coupling: next item leaves a class-aligned remainder.
            if next_waste % 10 == 0 {
                score -= 10.0;
            }
            score += next_waste as f64 * 0.15;
        } else {
            // Next item won't fit here: this bin becomes dead space for the future.
            score += 12.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: neutral-ish baseline, but discourage opening new bins
    // when the item would leave a large residual in a fresh bin.
    if bin_residual == bin_capacity {
        score += 15.0;
        // Discourage new bin if open bins exist and item is small.
        if open_bins_count > 0 && item_size <= 50 {
            score += 10.0;
        }
        if next_item_size > 0 && next_item_size > item_size && item_size >= 50 {
            score -= 20.0; // big item then bigger item: fine to open fresh bin
        }
    }

    // Stream progression: early on, be conservative about fragmenting bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * frac * 10.0;

    // Coupling with mean residual: prefer bins near the mean (balance load),
    // penalize outliers that hoard space.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Integer-division threshold: penalize residuals in awkward bands (1..10, 11..20)
    // that rarely fit any item (items >= 10).
    if post_residual >= 1 && post_residual < 10 {
        score += 15.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable gaps (too small for typical items) are heavily penalized.
    // A residual gap is "dead" if it cannot fit even a small future item (assume min item ~1..10).
    if post_residual > 0 {
        let dead_threshold = 10.0f64;
        if (post_residual as f64) < dead_threshold {
            score += 60.0 * (dead_threshold - post_residual as f64) / dead_threshold;
        }
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = post_residual as f64 / (item_size.max(1) as f64);
    score += 25.0 * tightness;

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidating into existing bins
    // rather than opening new ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * (1.0 - progress) * 3.0;

    // New-bin candidate: an empty bin has full residual; make it attractive only when
    // placing here would create large dead space elsewhere or fits are poor.
    if bin_residual == bin_capacity {
        // Slight default penalty so existing good fits win; overridden when fits are bad.
        score += 15.0;
        // If no open bin fits well (post_residual large everywhere), opening a new bin
        // is reasonable: reduce penalty via lookahead compatibility.
        if next_item_size > 0 {
            // If next item would fit into post_residual of a new bin after placement, encourage.
            if next_item_size as f64 <= post_residual as f64 {
                score -= 10.0;
            }
        }
    }

    // Lookahead: if next item fits exactly in post_residual, reward this placement strongly.
    if next_item_size > 0 && (next_item_size as u32) == post_residual {
        score -= 30.0;
    }
    // Penalize if next item barely misses fitting into post_residual (wasted potential).
    if next_item_size > 0 && (next_item_size as u32) > post_residual && post_residual > 0 {
        score += 8.0;
    }

    // Mean residual coupling: prefer bins whose residual is near the mean (keeps spread even),
    // penalize outliers creating fragmented small gaps.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Mild preference for filling bins with larger residual (use space efficiently).
    score += 0.02 * (bin_capacity as f64 - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward when next item fits the post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post_residual as f64 {
            // exact 2-step fill bonus
            let gap = (post_residual as f64 - nxt).abs();
            score -= 200.0 * (1.0 - gap / cap);
            if (post_residual as i64 - next_item_size as i64) == 0 {
                score -= 500.0;
            }
        } else {
            // next item won't fit here: penalize dead space scaled to waste
            let waste = nxt - post_residual as f64;
            score += 0.5 * waste;
        }
    }

    // Compare post residual against mean residual: keep bins balanced
    score += 0.3 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin before opening a new one
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // Penalize opening new bins when open bins are underutilized
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let avg_use = mean_residual.max(0.0);
        if fitting_bins_count > 0 && avg_use < cap * 0.5 {
            score += 300.0;
        }
        // late in stream, prefer filling existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 100.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 22.0 * tightness * tightness;

    // Penalize small dead space band (hard-to-fill leftovers)
    if post_residual > 0 && post_residual < 10 {
        score += 14.0;
    }

    // Lookahead: if next item fits into post_residual, reward this bin
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 18.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        score += 6.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening new bin unless residuals are crowded
    if bin_residual == bin_capacity {
        let crowding = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        score += 12.0 + crowding;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 8.0; // fresh bin useful for upcoming large item
        }
    }

    // Time horizon: early stream, be conservative (favor new bins less); later, consolidate
    let t = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * t * (mean_residual - post_residual as f64) / bin_capacity as f64;

    // Favor bins with residual far below mean (consolidate emptier bins)
    score += 0.15 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let norm_pr = pr / cap;
    let poly = norm_pr * norm_pr * (1.0 + 2.0 * progress) + norm_pr * (1.0 - progress) * (1.0 - progress);
    score += 30.0 * poly;

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= 25.0 * tightness * tightness * (0.5 + progress);

    // Lookahead: favor bins whose post residual can host the next item
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if post_residual >= next_item_size {
            score -= 12.0 * (1.0 - (pr - n) / cap) * (0.6 + 0.4 * progress);
        } else {
            score += 8.0 * (n - pr) / cap * (1.0 - progress);
        }
    }

    // Last chance: strong discount to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 + 15.0 * progress;
    }

    // New-bin candidate: penalize mildly early, more late (prefer consolidation)
    if bin_residual == bin_capacity {
        score += 10.0 + 40.0 * progress * progress + 2.0 * open_bins_count as f64;
    } else {
        // Prefer bins with below-mean residual (compact the low-space bins)
        score += 5.0 * (pr - mean_residual) / cap;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues divisible by common item sizes
    // are more "usable" dead space, so reward them (subtract).
    let pr = post_residual;
    if pr > 0 {
        let mut harmony: f64 = 0.0;
        for d in [10u32, 20, 25, 40, 50, 80] {
            if pr % d == 0 {
                harmony += 6.0;
            }
        }
        // exact-fit classes are ideal
        if pr % 100 == 0 { harmony += 20.0; }
        score -= harmony;
    } else {
        // perfect closure of the bin
        score -= 60.0;
    }

    // Integer-division threshold: post_residual in a "dead zone" (1..10)
    // is nearly unusable -> penalize strongly.
    if pr > 0 && pr < 10 {
        score += 35.0;
    }

    // Fraction of capacity filled: reward high fill fraction non-linearly.
    let fill_frac = (bin_capacity - pr) as f64 / bin_capacity as f64;
    score -= 15.0 * fill_frac * fill_frac;

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size <= pr {
        if pr == next_item_size {
            score -= 40.0;
        } else if (pr - next_item_size) < 10 {
            score += 10.0; // would leave another dead zone
        } else {
            score -= 8.0;
        }
    } else if next_item_size > pr {
        // next item won't fit here anyway; slight penalty for hoarding space
        score += 5.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only prefer opening a new bin when no open bin
    // fits well (post_residual would be tiny) or stream is early with few bins.
    if bin_residual == bin_capacity {
        // base handicap so open bins with decent fits win
        score += 30.0;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if fitting_bins_count == 0 || (post_residual as f64) < 0.15 * bin_capacity as f64 {
            score -= 55.0;
        }
        if open_bins_count > 0 && progress < 0.2 {
            score -= 5.0;
        }
    }

    // Mild preference to consolidate into fewer bins when many are open.
    if bin_residual < bin_capacity {
        score -= 2.0 * (open_bins_count as f64).ln().max(0.0) * 0.5;
    }

    // Tie-break with mean residual: prefer bins below mean residual (tighter bins).
    if bin_residual as f64 > mean_residual {
        score += 3.0;
    } else {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: gaps too small to ever fit a plausible item are pure waste.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    }
    // Small-but-usable gaps: mild penalty scaled by how little fits.
    if post_residual > 0 && post_residual >= 10 && post_residual < 30 {
        score += 0.6 * (30.0 - post_residual as f64);
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }
    // If many bins fit, allow tighter competition on residual alone.

    // Open-bin pressure: with few open bins, avoid opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure; cheaper late in stream
        // when residual space is plentiful elsewhere.
        score = bin_capacity as f64 + 25.0 * pressure - 20.0 * (1.0 - progress);
        // Discourage opening a new bin when the item would fit snugly elsewhere
        if bin_residual - item_size <= 15 && fitting_bins_count > 0 {
            score += 80.0;
        }
    } else {
        // Mild penalty for leaving gaps much larger than the mean residual
        // (keeps a pool of large gaps for big future items).
        if post_residual as f64 > mean_residual * 1.5 {
            score += 0.3 * (post_residual as f64 - mean_residual * 1.5);
        }
    }

    // Lookahead: if the next item fits in post_residual, reward leaving it open.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 0.5 * next_item_size as f64;
    }
    // If next item would NOT fit here, slight penalty for tight leftovers.
    if next_item_size > post_residual && post_residual > 0 && post_residual < next_item_size {
        score += 0.2 * (next_item_size - post_residual) as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead: reward if next item exactly fills post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            score -= 30.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // next item cannot use leftover: penalize large dead space
            score += 0.5 * (next_item_size as f64 - post_residual as f64).min(50.0);
        }
    }

    // Favor bins with small residuals relative to mean
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // Penalize new bin when a decent fit exists
    if bin_residual == bin_capacity {
        score += 150.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score += 20.0;
        }
    }

    // Late in stream: tighten packing
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * tightness * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits into the post-residual, reward; otherwise penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 4.0 * (next_item_size as f64 / 100.0);
        } else {
            let waste = (post_residual as f64 - (post_residual as f64).min(next_item_size as f64)).abs();
            score += 2.0 * (1.0 - (waste / bin_capacity as f64).min(1.0));
        }
    }

    // Penalize leaving residuals too small for typical future items (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Time horizon: early in stream, prefer consolidating into open bins;
    // late in stream, residual waste matters less per-bin.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 3.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // Many open bins: discourage spreading, favor bins below mean residual (filler bins).
    if open_bins_count > 1 {
        if (bin_residual as f64) < mean_residual {
            score -= 2.0;
        } else {
            score += 1.5 * ((bin_residual as f64 - mean_residual) / bin_capacity as f64);
        }
    }

    // New empty bin candidate: penalize mildly so it only wins when fits are bad,
    // but reward it when the item is large and open-bin residuals are tight.
    if bin_residual == bin_capacity {
        let badness = if fitting_bins_count == 0 { 0.0 } else {
            (post_residual as f64 / bin_capacity as f64) // = 1.0 for empty bin
        };
        score += 12.0;
        if item_size >= 60 && mean_residual < item_size as f64 {
            score -= 10.0;
        }
        if next_item_size > 0 && next_item_size >= bin_residual {
            score -= 3.0; // empty bin still useful for next item
        }
        let _ = badness;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let post_norm = post / cap;

    // Base: prefer tight fits (low post residual), non-linearly weighted
    let mut score = post * (1.0 + 0.5 * post_norm * post_norm);

    // Smooth polynomial coupling of post_residual with stream progress:
    // later in the stream, dead space becomes more costly
    let coupling = post_norm * (1.0 - post_norm);
    score += 8.0 * coupling * (0.5 + progress);

    // Penalize residuals that cannot fit the lookahead item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post < nxt {
            score += 6.0 * (nxt - post) * (0.5 + progress);
        } else {
            score -= 3.0 * (post - nxt).min(20.0) / cap;
        }
    }

    // Reward scarce fitting opportunities (last-chance bin)
    if fitting_bins_count <= 1 {
        score -= 12.0;
    } else {
        score -= 2.0 / fitting_bins_count as f64;
    }

    // Mild penalty for spreading across many open bins
    score += 0.15 * open_bins_count as f64;

    // Prefer bins with residuals below the mean (tighter consolidation)
    score += 0.5 * (post - mean_residual);

    // New-bin candidate: discourage unless it's early or the fit elsewhere is bad
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - progress) * -1.0 + 25.0 * progress + post;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo-10 bucket -> dead-space quality
    let class = post_residual % 10;
    // Residuals in "harmonic" classes (0, 5) are more reusable
    if class == 0 {
        score -= 8.0;
    } else if class == 5 {
        score -= 4.0;
    } else {
        score += (10 - class) as f64 * 0.3;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: can next item fill the post_residual exactly or nearly?
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size < post_residual {
            let waste = post_residual - next_item_size;
            if waste <= 5 {
                score -= 10.0;
            } else {
                score += waste as f64 * 0.25;
            }
        } else {
            // next item too big for this residual: residual likely dead space
            score += 6.0;
        }
    }

    // Integer-division threshold on post_residual: large residuals are valuable
    let half = bin_capacity / 2;
    if post_residual >= half {
        score -= 5.0;
    } else if post_residual < bin_capacity / 10 {
        // tiny residual = dead space unless zero
        score += 4.0;
    }

    // Last-chance bin: strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: penalize opening a new bin when decent fits exist
    if bin_residual == bin_capacity {
        // Base penalty so it's only chosen when open bins score badly
        score += 15.0;
        // Early in stream, opening bins is fine; late, prefer consolidation
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += (1.0 - progress) * 10.0 - progress * 5.0;
        // If open bins are already fragmented (high mean residual), new bin ok
        score -= (mean_residual / bin_capacity as f64) * 10.0;
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mild pressure to balance load across bins
    score += ((bin_residual as f64) - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for even the smallest item (or next item) are wasted.
    let min_item = 1u32;
    let dead = if post_residual < min_item { 1.0 } else { 0.0 };
    score += dead * cap * 4.0;

    // Penalize residuals that cannot fit the lookahead item -> likely dead space.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 1.5;
    }

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / cap);
    score -= tightness * 20.0;

    // Perfect / near-perfect fit bonus.
    if post_residual <= 2 {
        score -= 50.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 0.5 * item_size as f64;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (2.0 + 4.0 * progress);

    // Prefer bins whose residual is below mean residual (consolidating fullest bins).
    score += (mean_residual - post_residual as f64) * 0.8;

    // New-bin candidate: make empty bin moderately attractive only when the fit
    // into open bins would leave large dead space; otherwise discourage.
    if bin_residual == bin_capacity {
        let would_be = cap - item_size as f64;
        score = cap * 0.6 + would_be * 0.5;
        if next_item_size > 0 && would_be < next_item_size as f64 {
            score -= 40.0; // new bin needed to host the next big item
        }
        if fitting_bins_count == 0 {
            score -= cap * 2.0; // nothing fits elsewhere -> must open
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact/near-exact 2-step lookahead matches.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 60.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item can't fit here; penalize wasted lookahead potential.
        score += 0.5 * (next_item_size as f64 - post_residual as f64);
    }

    // Reward tight fits relative to mean residual.
    let tightness = (item_size as f64) / (bin_residual as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize bins that deviate from mean residual (prefer balanced usage).
    score += 0.3 * ((post_residual as f64 - mean_residual).abs());

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize tiny dead space (<10) that can never be reused.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Empty new-bin candidate: mild penalty so it's chosen only when fits are bad.
    if bin_residual == bin_capacity {
        score += 15.0;
        // Early in stream, opening bins is cheap; later, discourage it.
        score += 20.0 * (step_index as f64 / total_items.max(1) as f64);
    }

    // Small bonus for consolidating when many bins are open.
    if open_bins_count > 4 && bin_residual < bin_capacity {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that no plausible item can fill (items >= 1).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead coupling: reward if next item fits into post_residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 6.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 3.0;
        }
    }

    // Last-chance bonus: only bin that fits the item.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: mildly penalize opening a new bin when
    // decent fits exist, but allow it when open bins are crowded.
    if bin_residual == bin_capacity {
        let crowded = if open_bins_count > 0 {
            mean_residual / bin_capacity as f64
        } else {
            1.0
        };
        // Open new bin more readily later in the stream / with many open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 - 10.0 * crowded - 6.0 * progress - 0.15 * open_bins_count as f64;
    }

    // Prefer bins with residual close to item_size (best-fit flavor).
    let gap = (bin_residual as i64 - item_size as i64) as f64;
    score += 0.05 * gap.abs();

    // Prefer using bins with lower residuals among open bins (consolidation).
    score += 0.02 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early in the stream: tolerate moderate residuals (bins stay flexible).
    // Late in the stream: aggressively prefer tight fits (small post_residual).
    let w_early = (1.0 - progress).powi(2);
    let w_late = progress.powi(2);

    // Quadratic dead-space penalty, amplified late in the stream.
    score += w_late * (norm_pr * norm_pr) * cap;

    // Early-stream smooth reward for keeping residuals near a balanced level
    // (target residual tracks the mean residual of open bins).
    let target = mean_residual.max(1.0);
    let dev = (pr - target) / cap;
    score -= w_early * 4.0 * (dev * dev) * cap;

    // Smooth cubic coupling: small residuals are extra valuable as stream ends.
    score -= w_late * (norm_pr.powi(3)) * cap;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 25.0 + 50.0 * progress;
    }

    // Lookahead: reward bins whose post_residual can still host the next item,
    // with a smooth bell-shaped preference for exact-ish matches.
    if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        let fit_quality = 1.0 - ((post_residual as i64 - next_item_size as i64).abs() as f64 / cap);
        score -= 10.0 + 15.0 * fit_quality * (1.0 - progress);
    } else if next_item_size > 0 {
        // Penalize residuals that are almost-but-not-quite large enough for next item.
        let gap = (next_item_size as i64 - post_residual as i64).max(0) as f64;
        score += w_late * gap * 0.3;
    }

    // Mild penalty for proliferating bins early on.
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * w_early;

    // Prefer placing into bins with small pre-residual (tighter bins first),
    // smoothly weighted.
    score += 0.15 * (bin_residual as f64 / cap) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: bucket post_residual into capacity fractions (mod-style classes).
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let class = (post_residual / (bin_capacity / 8).max(1)) as f64; // 8 harmonic classes
    score += class * 3.0; // prefer smaller residual class

    // Perfect / near-perfect fits get strong rewards.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 500.0;
    } else if post_residual <= 10 {
        score -= 200.0;
    }

    // Dead-space penalty for awkward residual classes (unusable slivers).
    if post_residual > 0 && post_residual < 10 {
        score += 80.0;
    }

    // Lookahead coupling: reward residuals that can host the next item exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual >= next_item_size {
            let slack = post_residual - next_item_size as f64;
            score -= (30.0 - (slack / 10.0)).max(-30.0);
            if (post_residual as u32 % next_item_size.max(1)) == 0 {
                score -= 60.0; // divisible class: future tiling potential
            }
        } else {
            score += 40.0; // next item won't fit here anyway
        }
    }

    // Last-chance bonus: only fitting bin -> strong incentive to use it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate handling: make empty bins attractive only when open bins are crowded.
    if bin_residual == bin_capacity {
        let crowding = mean_residual / cap;
        score = cap * 0.9 + (1.0 - crowding) * 200.0 - (open_bins_count as f64) * 0.5;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 50.0; // fresh bin useful for larger upcoming items
        }
    }

    // Mild time regularization toward tight packing late in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item are dead.
    let dead_threshold = 10u32.min(bin_capacity / 2);
    if post_residual > 0 && post_residual < dead_threshold {
        score += 60.0 + (dead_threshold - post_residual) as f64 * 4.0;
    }

    // Reward perfect / near-perfect fits strongly.
    if post_residual == 0 {
        score -= 120.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Tightness ratio: favor bins where item fills a large fraction of residual.
    let fill = item_size as f64 / bin_residual as f64;
    score -= fill * 30.0;

    // Last chance: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Next-item lookahead: if the next item fits exactly in the post residual,
    // this placement chains nicely; if post residual can't hold next item but
    // is large, mild penalty for wasting space.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual > next_item_size {
            score -= 5.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 8.0;
        }
    }

    // Open-bins pressure: when many bins are open, discourage opening new bins
    // (penalize the empty-bin candidate) and prefer consolidating into existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: base penalty growing with open bins and stream progress.
        score += 35.0 + open_bins_count as f64 * 6.0 + progress * 25.0;
        // But if residual is small and unusable everywhere, new bin is fine:
        if fitting_bins_count <= 1 && mean_residual < item_size as f64 * 1.2 {
            score -= 45.0;
        }
    } else {
        // Slight reward for reusing existing bins as open count grows.
        score -= open_bins_count as f64 * 0.5;
    }

    // Mild attraction toward bins with residual close to the item (best-fit core).
    score += (bin_residual as f64 - item_size as f64).abs() * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact/2-step lookahead matches: next item fills post_residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 60.0 * (1.0 - slack / bin_capacity as f64);
    }

    // Penalize post_residual slightly larger than next item (dead space trap).
    if next_item_size > 0 && post_residual < next_item_size {
        score += 0.15 * (next_item_size - post_residual) as f64;
    }

    // Prefer bins tighter than average residual.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin bonus: avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Penalize opening a new bin when open bins exist and fit is decent.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 25.0 + 20.0 * progress;
        if fitting_bins_count > 0 && post_residual >= next_item_size {
            score += 15.0;
        }
    }

    // Mild preference for fewer open bins when spread is wide.
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared penalty on wasted space.
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 60.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual < 10 {
        score -= 40.0;
    }

    // Penalize dead space that no future item (min size 1) can use well:
    // residual smaller than typical small items is wasted.
    if post_residual > 0 && post_residual < 25 {
        score += 30.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 120.0;
        } else if next_item_size <= post_residual {
            score -= 25.0;
        } else {
            // Next item won't fit here anyway; slight penalty for over-tightening.
            score += 10.0;
        }
    }

    // New-bin candidate handling: empty bin should only win when no good fit exists.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 90.0;
        // If many bins fit the item, opening a new bin is rarely needed.
        if fitting_bins_count > 2 {
            score += 60.0;
        }
        // Early in stream, opening bins is cheaper (more future items to fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 40.0;
        // If current mean residual is large, prefer existing bins.
        score += (mean_residual / bin_capacity as f64) * 50.0;
    }

    // Prefer bins with residual close to item (best-fit flavor) relative to mean.
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.5;

    // Mild pressure against accumulating too many open bins.
    score += open_bins_count as f64 * 1.5;

    // Reward using bins with larger residuals for larger items (avoid fragmenting small-residual bins).
    if item_size > 50 && bin_residual >= item_size {
        score -= (bin_residual as f64 - item_size as f64) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_rate = pr / cap;

    // Smooth non-linear waste term: penalize residual quadratically, scaled by stream progress
    let mut score = pr * (1.0 + 1.5 * progress * fit_rate * fit_rate)
        + 40.0 * progress * (pr / cap) * (pr / cap);

    // Reward tight fits smoothly (small post_residual relative to item)
    let tightness = 1.0 - (post_residual as f64 / (bin_residual.max(1) as f64));
    score -= 30.0 * tightness * tightness * (1.0 - progress);

    // Last-chance bonus when only this bin fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead coupling: reward if next item fits post-residual
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr as f64 {
            score -= 12.0 * (1.0 - (pr - nx) / cap) * (1.0 - progress);
        } else {
            score += 6.0 * ((nx - pr) / cap) * (1.0 - progress);
        }
    }

    // Mild pressure to consolidate when many bins are open
    score += 0.5 * open_bins_count as f64 * (1.0 - progress) * fit_rate;

    // New-bin candidate handling: penalize opening a new bin early, allow late
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - progress) * (1.0 - progress)
            - 10.0 * progress
            + 2.0 * (mean_residual / cap).max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space penalty: small non-zero residuals are hard to fill.
    if post_residual > 0 {
        let dead = if post_residual < 10 {
            60.0
        } else if post_residual < 20 {
            30.0
        } else if post_residual < 30 {
            12.0
        } else {
            0.0
        };
        score += dead;

        // Harmonic classes: reward residuals that fall into "usable" classes
        // (multiples of common item sizes 10..80 granularity).
        if post_residual % 10 == 0 {
            score -= 5.0;
        }
        if post_residual % 5 == 0 {
            score -= 2.0;
        }
    }

    // Lookahead: strongly favor bins where next item also fits (chained packing).
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0 + (next_item_size as f64) * 0.1;
        // Extra reward if next item nearly fills the bin after chaining.
        let chain_residual = post_residual - next_item_size;
        if chain_residual < 10 {
            score -= 20.0;
        }
    } else if next_item_size > 0 {
        // Next item won't fit here; slight penalty proportional to waste.
        score += 3.0;
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current
    // fit is poor or no good option exists.
    if bin_residual == bin_capacity {
        // Empty bin baseline: neutral-ish score, penalized if open bins fit well.
        score += 20.0;
        if post_residual >= 20 {
            score += 10.0; // opening fresh bins early wastes capacity potential
        }
        if open_bins_count == 0 {
            score -= 200.0; // must open first bin
        }
        // Late in stream, prefer consolidating into open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 * progress;
    }

    // Prefer filling bins that are already relatively full (below mean residual).
    if bin_residual != bin_capacity {
        let diff = mean_residual - post_residual as f64;
        score += 0.3 * diff; // filling below-average-residual bins is good
    }

    // Mild pressure to keep number of open bins low.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=9) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 12.0;
    }
    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward fits that leave room for the lookahead item if it fits.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.1 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        // Lookahead won't fit: penalize leaving a gap slightly larger than next item.
        score += 4.0;
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: prefer filling existing bins when many are open.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual < bin_capacity {
        score -= 2.0 * pressure;
    } else {
        // New bin candidate: penalize opening a new bin unless current bins are crowded.
        score += 15.0 + 3.0 * pressure - 0.05 * mean_residual;
    }

    // Late in the stream, tighten packing to avoid leftover fragments.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * progress * (bin_capacity - post_residual) as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect / near-perfect fits
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    }

    // Aggressive 2-step lookahead: reward if next item exactly fills post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 800.0;
        } else if next_item_size < post_residual {
            // next item fits in the leftover: mild reward proportional to fit quality
            let fit_ratio = next_item_size as f64 / post_residual as f64;
            score -= 200.0 * fit_ratio;
        } else {
            // next item cannot use the leftover: penalize dead space, worse for small leftovers
            let dead = post_residual as f64;
            let progress = step_index as f64 / total_items.max(1) as f64;
            score += dead * (0.5 + 0.5 * progress);
            // penalize leftovers too small for typical items (unusable dead space)
            if dead < 10.0 {
                score += 150.0;
            }
        }
    }

    // Relative to mean residual: prefer bins whose residual deviates favorably
    let dev = post_residual as f64 - mean_residual;
    score += 0.3 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // Many open bins: encourage consolidation into existing bins
    if open_bins_count > 3 {
        score -= 20.0;
    }

    // New-bin candidate should only win on poor fits elsewhere
    if bin_residual == bin_capacity {
        score += 400.0 + post_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: strongly favor small post_residual.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 20.0;
    } else if post_residual <= 5 {
        score -= 8.0;
    }

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 6.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here; slight penalty proportional to wasted potential.
            score += 3.0;
        }
    }

    // New-bin candidate handling: opening a bin is expensive.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 35.0;
        // Cheaper to open a new bin late in the stream (fewer future items to fill it).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 15.0 * progress;
        // If many bins are open with slack, discourage yet another bin.
        score += 2.0 * open_bins_count as f64;
        // If the item fits poorly in existing bins (large post_residual elsewhere),
        // opening fresh is more attractive: this call's post_residual equals capacity - item.
        let fill = item_size as f64 / bin_capacity as f64;
        score -= 20.0 * fill;
        // If next item is large, a fresh bin can host it after this one.
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0;
        }
    } else {
        // Favor bins whose residual is below the mean (consolidate emptier space usage).
        score += 0.15 * (mean_residual - bin_residual as f64).max(0.0);
        // Mild bonus for using bins with larger residual relative to item (big-gap bins).
        score -= 0.05 * (bin_residual as f64 - item_size as f64).max(0.0);
    }

    // Slight preference for fewer open bins overall (encourage closing out bins).
    if bin_residual != bin_capacity {
        score -= 0.5 * (bin_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post-residual in [0,1]

    // Base: quadratic waste penalty (favor tight fits), softened by stream progress.
    let mut score = pr * (1.0 + 0.6 * x) - 8.0 * progress * x * (1.0 - x);

    // Smooth cubic coupling: mid-range residuals get progressively worse late in stream.
    score += 12.0 * x * x * (0.5 + progress) * cap * 0.1;

    // Lookahead: reward bins whose post-residual can host the next item (smooth kernel).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let tightness = 1.0 - ((pr - nx) / cap).abs();
            score -= 10.0 * tightness;
        } else {
            // Penalize residuals that just barely fail to fit the next item (dead space).
            let gap = (pr - nx) / cap;
            score += 6.0 * (-gap * 20.0);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Mild reward when bin residual is below mean residual (consolidating waste).
    let mrx = (mean_residual / cap).clamp(0.0, 1.0);
    score -= 4.0 * (mrx - x).abs().min(1.0) * (1.0 - progress);

    // New-bin candidate: penalize opening a bin unless residual situation is bad,
    // with smooth dependence on progress and open-bin count.
    if bin_residual == bin_capacity {
        let openness = (open_bins_count as f64 / (1.0 + open_bins_count as f64)).sqrt();
        score = cap * (1.1 - 0.25 * progress) + 20.0 * openness + 0.5 * mean_residual;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual modulo capacity quarters
    let quarter = bin_capacity / 4;
    let class = post_residual % quarter;
    let class_norm = class as f64 / quarter as f64;
    // Reward residuals that land near "harmonic" fill levels (class close to 0 or quarter)
    let harmonic_bonus = if class_norm < 0.5 { class_norm } else { 1.0 - class_norm };
    score -= 8.0 * harmonic_bonus;

    // Integer-division threshold: post_residual bucketed into capacity/10 slots
    let slot = post_residual / (bin_capacity / 10);
    let slot_bonus = match slot {
        0 => 12.0, // nearly full bin: excellent
        1 => 6.0,
        2 => 2.0,
        3 => -3.0, // awkward mid-range dead space
        4 => -6.0,
        5 => -5.0,
        6 => -2.0,
        7 => 1.0,
        8 => 3.0,
        _ => 5.0, // nearly empty: fine for future items
    };
    score += slot_bonus;

    // Coupling with next item: does post_residual admit the lookahead item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Exact fit with lookahead is golden
            let gap = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Lookahead won't fit here: penalize proportionally to wasted potential
            let shortfall = (next_item_size - post_residual) as f64;
            score += 4.0 * shortfall / bin_capacity as f64;
        }
        // Harmonic class of (post_residual - next_item_size)
        if post_residual >= next_item_size {
            let rem2 = (post_residual - next_item_size) % quarter;
            score -= 3.0 * (rem2 as f64 / quarter as f64);
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else {
        // Prefer fuller bins when alternatives exist
        score += 5.0 * (1.0 - bin_residual as f64 / bin_capacity as f64);
    }

    // New-bin candidate handling: only attractive if open bins are congested
    if bin_residual == bin_capacity {
        let congestion = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
        let mean_tightness = 1.0 - (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score += 20.0 - 18.0 * congestion * mean_tightness;
        if fitting_bins_count <= 1 {
            score -= 10.0; // no good alternative: opening new bin is fine
        }
    }

    // Late-stream preference to consolidate into existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    // Small tie-breaker favoring tight fits
    score += 0.05 * (post_residual as f64 % 7.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small to fit typical items are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Reward tight fits (exact or near-exact packing).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Penalize large leftover space if it fragments badly relative to mean residual.
    if post_residual as f64 > mean_residual * 1.5 {
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, avoid spreading items; prefer filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.6 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // New-bin candidate handling: opening a fresh bin should only win if the fit here is poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; a good fit in an existing bin beats it.
        score += 35.0 + 0.3 * open_bins_count as f64;
        // Lookahead: a new bin reserves full capacity for the next item.
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 15.0;
        }
    }

    // Lookahead synergy: if next item fits exactly into the resulting residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        score -= 20.0;
    }

    // Small-item into big residual: wasteful spread.
    if item_size < 20 && post_residual > 50 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 800.0;
        } else if next_item_size <= post_residual {
            score -= 300.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; penalize small dead space less if post residual large
            score += 50.0;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score += (post_residual as f64 - mean_residual) * 0.5;

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // Penalize opening new bin when open bins could take it
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 200.0 + mean_residual * 0.3;
    }

    // Late in stream: avoid spreading across many bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize large dead space non-linearly (waste grows super-linearly).
    let frac = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * frac * frac;

    // Reward tight fits strongly.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0; // awkward gap zone
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if next item fits in the post residual, reward.
    if next_item_size > 0 && (next_item_size as f64) <= post_residual as f64 {
        score -= 12.0;
    }
    // If next item almost fits (small miss), slight penalty for blocking it.
    if next_item_size > 0 && (next_item_size as u32) > post_residual && (next_item_size as u32) - post_residual <= 5 {
        score += 6.0;
    }

    // Time horizon: early in stream, prefer keeping residuals flexible (mild penalty for low post_residual);
    // late in stream, prefer filling bins aggressively.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= t * 10.0 * (1.0 - frac);

    // Global state: many open bins -> consolidate (favor bins with residual near mean).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev * (open_bins_count as f64).sqrt();

    // New-bin candidate: make it moderately attractive only when fits are poor or no open bin fits well.
    if bin_residual == bin_capacity {
        let base_penalty = 18.0 + 10.0 * t;
        score += base_penalty;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        } else if fitting_bins_count == 1 {
            score -= 10.0; // last chance: only open new bin if still clearly better
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: prefer tight fits, but weight residual cost by stream progress
    let mut score = pr * (0.9 + 0.5 * progress * progress);

    // Non-linear penalty for awkward residuals (small but nonzero dead space)
    let awkward = (pr_norm * (1.0 - pr_norm)).sin();
    score += 12.0 * awkward * (0.5 + progress);

    // Reward nearly-full bins (small post residual) with smooth coupling
    score -= 8.0 * (-pr_norm * 6.0).exp() * (1.0 - progress);

    // Last-chance bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 + 15.0 * progress;
    }

    // New-bin candidate handling: open a new bin early or when item is large
    let is_new = bin_residual == bin_capacity;
    if is_new {
        // Penalize new bins unless lookahead is large or bin is tight elsewhere
        let lookahead_pressure = next_item_size as f64 / cap;
        let mean_pressure = mean_residual / cap;
        score += 10.0 + 25.0 * (1.0 - lookahead_pressure) * (1.0 - progress) * (1.0 - mean_pressure);
        score -= 15.0 * (1.0 - mean_pressure).max(0.0) * progress;
    }

    // Prefer bins with residuals close to item size (smooth quadratic coupling)
    let gap = (bin_residual as f64 - item_size as f64) / cap;
    score += 6.0 * gap * gap * (1.0 + progress);

    // Slight preference to balance open bins via mean residual
    score += 0.05 * (bin_residual as f64 - mean_residual).abs() / cap;

    // Lookahead: reward bins whose post residual fits next item
    if next_item_size > 0 {
        let fits_next = if post_residual >= next_item_size { 1.0 } else { 0.0 };
        let closeness = ((post_residual as i64 - next_item_size as i64) as f64 / cap).abs();
        score -= 10.0 * fits_next * (1.0 - closeness) * (0.5 + 0.5 * progress);
        score += 4.0 * (1.0 - fits_next) * (1.0 - progress) * (pr_norm);
    }

    // Mild penalty for too many open bins late in stream
    score += 0.5 * open_bins_count as f64 * progress * pr_norm;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: best-fit with dead-space penalty
    if post_residual == 0 {
        score -= 1000.0; // perfect fit
    } else {
        // Harmonic class of the post residual: capacity / 8 classes
        let class = post_residual / (bin_capacity / 8);
        let class_center = (class * (bin_capacity / 8) + bin_capacity / 16) as f64;
        // reward residuals close to a small class center (usable for small items)
        score -= 8.0 * ((bin_capacity as f64 / 2.0 - class_center).abs() / bin_capacity as f64);
        // penalize unusably small dead space (modulo class 1: leftover in (0, 12))
        if post_residual % (bin_capacity / 8) == 0 && post_residual < bin_capacity / 8 {
            score += 6.0;
        }
    }

    // Next-item lookahead: reward if next item fits in post_residual
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 4.0 + (post_residual - next_item_size) as f64 * 0.05;
        } else {
            score += 3.0;
        }
    }

    // Last-chance bonus: only bin that fits -> strongly favor using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: penalize opening a bin unless current fit is poor
    if bin_residual == bin_capacity {
        // empty bin: neutral-ish score; make it worse than a good fit, better than a terrible one
        score = bin_capacity as f64 * 0.35 + item_size as f64 * 0.1;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 2.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // nothing fits: must open
        }
    } else if bin_residual - item_size < bin_capacity / 10 {
        // very poor fit into an open bin: push toward new bin
        score += 5.0;
    }

    // Mild consolidation pressure as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 2.0 * progress * (mean_residual / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest plausible item are "dead space" -> heavy penalty.
    let dead_threshold = 10u32.min(bin_capacity);
    if post_residual > 0 && post_residual < dead_threshold {
        score += 40.0 + (dead_threshold - post_residual) as f64 * 2.0;
    }
    // Mid-size gaps that likely fit nothing useful are also penalized softly.
    if post_residual > 0 && post_residual < 20 {
        score += 8.0;
    }

    // Reward perfect / near-perfect fits.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= 15.0 * tightness * tightness;
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening another.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when open bins exist and stream is late.
        score += 30.0 + open_bins_count as f64 * 4.0 + 20.0 * progress;
        // But if no open bin fits well (large residual waste elsewhere), allow it.
        if fitting_bins_count == 0 {
            score -= 80.0;
        }
    } else {
        score -= open_bins_count as f64 * 0.5;
    }

    // Lookahead: favor bins whose post_residual matches the next item size.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 5.0;
        } else if post_residual > 0 {
            score += 5.0; // next item can't use this bin's gap
        }
    }

    // Slight preference for bins below mean residual (consolidating waste).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward perfect fits (post_residual == 0)
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual exactly matches next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            // next item could also fit here afterward; mildly reward small leftover
            score -= 0.5 * (post_residual as f64 - next_item_size as f64).min(30.0);
        } else {
            // next item won't fit in the leftover; penalize dead space
            score += 0.3 * (next_item_size as f64 - post_residual as f64).min(40.0);
        }
    }

    // Relative-to-mean residual: prefer bins with residual below mean (tighter bins)
    score -= (mean_residual - post_residual as f64) * 0.2;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: keep it neutral-to-slightly-high so it's only chosen
    // when open bins offer poor fits; slightly lower early in the stream.
    if bin_residual == bin_capacity {
        score += 50.0 - 30.0 * (step_index as f64 / total_items.max(1) as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post residual).
    score -= (item_size as f64 / bin_capacity as f64) * 12.0;

    // Penalize dead space that is too small to hold a typical item (hard to reuse).
    let dead = post_residual as f64;
    if dead > 0.0 && dead < 10.0 {
        score += 25.0 * (1.0 - dead / 10.0);
    } else if dead >= 10.0 && dead < 20.0 {
        score += 4.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // next item can't use this residual; slight penalty for wasted potential
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: make it unattractive unless current fits are poor.
    if bin_residual == bin_capacity {
        // Base penalty so open bins are preferred when reasonable.
        score += 15.0;
        // Late in the stream, prefer closing out bins tightly rather than opening new.
        let t = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * t;
        // If many bins are open with slack, discourage another bin.
        if mean_residual > item_size as f64 {
            score += 10.0;
        }
        // But if no other bin fits well (large item), opening a new bin is fine.
        if item_size > 60 {
            score -= 25.0;
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 10.0; // allows a paired placement in fresh bin
        }
    }

    // Prefer bins whose residual is already below average (consolidate fullness).
    let r = bin_residual as f64;
    if r < mean_residual {
        score -= (mean_residual - r).min(20.0) * 0.3;
    } else {
        score += (r - mean_residual).min(20.0) * 0.15;
    }

    // Mild preference for filling more-open bins when count is large.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Non-linear tight-fit reward: strongly favor small post residuals
    let norm_fit = pr / cap;
    score -= 40.0 * (1.0 - norm_fit) * (1.0 - norm_fit) * (1.0 - norm_fit);

    // Smooth polynomial coupling of post_residual with stream progress:
    // late in the stream, dead space is costlier
    let prog2 = progress * progress;
    score += 30.0 * norm_fit * norm_fit * (0.3 + 0.7 * prog2);

    // Exact fill bonus
    if post_residual == 0 {
        score -= 60.0;
    }

    // Penalize wasting space relative to the mean residual of open bins
    score += 0.25 * (pr - mean_residual).max(0.0);
    score -= 0.15 * (mean_residual - pr).max(0.0);

    // Lookahead: reward residual that can still host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 8.0 * progress;
    } else if next_item_size > 0 {
        // small penalty for killing lookahead potential
        score += 6.0 * (next_item_size as f64 - pr) / cap;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: penalize opening a new bin, more so early/mid stream
    if bin_residual == bin_capacity {
        let open_f = open_bins_count as f64;
        score = cap + 20.0 + 30.0 * (1.0 - progress) + 2.0 * open_f;
        // but if the item barely fits any open bin, ease the penalty
        if fitting_bins_count <= 1 {
            score -= 40.0;
        }
        // if next item is large and this item is small, a fresh bin is attractive
        if next_item_size > item_size && (bin_capacity as u32 - item_size) >= next_item_size {
            score -= 15.0;
        }
    }

    // Mild preference for bins with fewer open competitors (consolidation)
    score += 1.5 * (open_bins_count as f64).ln().max(0.0) * norm_fit;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "usable" is the leftover space.
    // Residuals near multiples of common item sizes (10, 20, 25, 50) are reusable.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base waste: dead space that no typical item can fill.
    // Small positive residuals (< 10) are near-dead; big residuals are valuable.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // dead space penalty
    }

    // Harmonic alignment: reward post_residual divisible by coarse classes.
    for &unit in &[10u32, 20, 25, 50] {
        if post_residual % unit == 0 && post_residual > 0 {
            score -= 8.0 + (unit as f64) * 0.3;
        }
    }

    // Fraction-of-capacity class of the item (harmonic bins: 1/2, 1/3, 1/4 fills).
    let item_frac = item_size as f64 / cap;
    if (item_frac - 0.5).abs() < 1e-6 || (item_frac - 1.0 / 3.0).abs() < 0.01
        || (item_frac - 0.25).abs() < 1e-6 {
        score -= 5.0; // harmonic items pair well; prefer placing them snugly
    }

    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.4;
        } else {
            score += 6.0; // next item won't fit here; residual likely wasted
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad
    // or many bins are open with low mean residual (fragmentation).
    if bin_residual == bin_capacity {
        score += 15.0;
        if post_residual > 50 { score -= 10.0; } // fresh bin is fine for big items
        if mean_residual < 20.0 && open_bins_count > 2 { score -= 8.0; }
    }

    // Mild preference for tighter bins early in the stream (best-fit bias).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (bin_capacity - bin_residual) as f64 * (0.3 - 0.15 * progress);

    // Penalize bins whose residual deviates far from mean residual (imbalance).
    score += ((pr - mean_residual) / cap).abs() * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit: reward strongly.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: post_residual in unusable small gap zone.
    // A residual that no future item (min size 1..100 unknown) can plausibly fill
    // is dead space. Penalize the "awkward gap" band nonlinearly.
    if post_residual > 0 && post_residual <= 12 {
        score += 40.0 + (12 - post_residual) as f64 * 4.0;
    }

    // Reward tight fits generally (small waste relative to item size).
    if item_size > 0 {
        score -= (item_size as f64 / post_residual.max(1) as f64) * 2.0;
    }

    // Last chance: if this is the only bin that can fit the item, strongly favor it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // open bins are crowded (mean residual low) or many bins already open.
    if bin_residual == bin_capacity {
        // Base penalty so we prefer using existing bins, unless they're nearly full.
        let pressure = (open_bins_count as f64 * 0.5) + (bin_capacity as f64 - mean_residual).max(0.0) * 0.8;
        score += 80.0 - pressure.min(150.0);
        // If the next item is large and current bins are tight, new bin less bad.
        if next_item_size > 0 && next_item_size as f64 > mean_residual {
            score -= 25.0;
        }
    } else {
        // Placing into an open bin: penalize if it leaves the bin too full for
        // the lookahead item when alternatives exist.
        if next_item_size > 0 && post_residual as f64 > 0.0 && (next_item_size as f64) > post_residual as f64 {
            score += 5.0;
        } else if next_item_size > 0 && (next_item_size as u32) == post_residual {
            // Lookahead fits exactly after this placement: big reward.
            score -= 80.0;
        }
    }

    // Mild open-bins pressure: prefer filling existing bins as their count grows.
    score += open_bins_count as f64 * 0.3;

    // Slight preference for bins whose residual is close to the item (best-fit coupling).
    score += ((bin_residual as f64 - item_size as f64) / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base tightness: prefer bins where the item fills a large fraction of residual.
    let residual = bin_residual as f64;
    let fill_ratio = item_size as f64 / residual.max(1.0);
    score -= 30.0 * fill_ratio;

    // Exact-fit bonus: leaving near-zero residual is ideal.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Aggressive 2-step lookahead: does next item fit the post_residual?
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let pr = post_residual as f64;
        if next <= pr {
            // Next item chains perfectly: strong reward, scaled by how well it fills.
            let chain_fill = next / pr.max(1.0);
            score -= 25.0 * chain_fill;
            if (pr - next).abs() <= 3.0 {
                score -= 30.0; // perfect chain
            }
        } else {
            // Next item won't fit here: penalize leaving residual close-but-below next
            // (dead space that tempts but fails), scaled by stream progress.
            let progress = step_index as f64 / total_items.max(1) as f64;
            let gap = next - pr;
            if gap <= 15.0 {
                score += 10.0 * (1.0 - gap / 15.0) * (0.5 + progress);
            }
        }
    }

    // Relative-to-mean coupling: bins tighter than average are more valuable to fill.
    let dev = residual - mean_residual.max(1.0);
    if dev < 0.0 {
        score -= 8.0 * (-dev / bin_capacity as f64);
    } else {
        score += 4.0 * (dev / bin_capacity as f64);
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: only open a new bin when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        let poor_fit_everywhere = fitting_bins_count == 0
            || (post_residual as f64 > 0.35 * bin_capacity as f64 && mean_residual > 0.5 * bin_capacity as f64);
        if poor_fit_everywhere {
            score -= 60.0; // fresh bin keeps large residual for future items
        } else {
            score += 120.0; // prefer reusing an existing reasonably-fitting bin
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score -= 2.0 * (open_bins_count as f64).ln().max(0.0) * (1.0 - fill_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: small post residual is good.
    score -= (post_residual as f64).powf(0.35) * 1.2;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Penalize dead space that is too small for typical items (1..=100 unknown).
    if post_residual >= 1 && post_residual < 12 {
        score += 8.0;
    }

    // Lookahead: reward leaving space for the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += (next_item_size as f64 - post_residual as f64) * 0.25;
        }
        // Coupling: exact next-item match is very valuable.
        if post_residual == next_item_size {
            score -= 15.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin wastes residual capacity
    // of open bins; penalize proportionally to mean residual unless item is
    // large relative to residuals.
    let is_new_bin = bin_residual == bin_capacity && bin_capacity > 0;
    if is_new_bin {
        let waste = mean_residual.max(0.0);
        let item_frac = item_size as f64 / bin_capacity as f64;
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Early stream: prefer filling open bins; late: allow new bins more freely.
        let open_penalty = waste * (0.6 + 0.8 * (1.0 - progress)) * (open_bins_count as f64).sqrt().min(3.0);
        score += open_penalty;
        // Large items that few bins fit justify a new bin.
        if fitting_bins_count <= 1 {
            score -= 25.0 * (1.0 - item_frac);
        }
        // Small item into a fresh bin is wasteful.
        if item_frac < 0.25 {
            score += 25.0;
        }
    } else {
        // Favor bins with residual close to item (best-fit flavor).
        let gap = (bin_residual as f64 - item_size as f64).abs();
        score += gap * 0.15;
        // Slight preference for bins below mean residual (consolidate emptier bins).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    // Mild exploration term: time-varying tilt to diversify placements.
    let phase = ((step_index as f64) * 0.37).sin();
    score += phase * 1.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, mildly damped by progress (waste matters more later)
    let mut score = pr * (0.8 + 0.4 * progress);

    // Smooth polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - norm_pr) * (1.0 - norm_pr);
    score -= 30.0 * poly * (1.0 + progress);

    // Penalize residuals that are slightly too small to hold the next item
    if next_item_size > 0 {
        let gap = next_item_size as f64 - pr;
        if gap > 0.0 && gap <= 40.0 {
            score += 12.0 * (1.0 - gap / 40.0) * (1.0 - gap / 40.0);
        }
        // Reward exact/near-exact fit for the lookahead item
        if gap == 0.0 {
            score -= 20.0;
        }
    }

    // Last-chance bin bonus (smooth in fitting_bins_count)
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - norm_pr);
    }

    // Mild penalty for hoarding many open bins with large mean residual
    score += 0.05 * open_bins_count as f64;
    score += 0.1 * (mean_residual - pr).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residual modulo capacity fractions
    let frac = post_residual as f64 / bin_capacity as f64;
    let cls = post_residual % (bin_capacity / 4).max(1); // quarter-capacity class
    score += (cls as f64) * 0.35;

    // Reward tight fits: post residual in small harmonic classes (near zero)
    if post_residual <= bin_capacity / 10 {
        score -= 12.0;
    } else if post_residual <= bin_capacity / 4 {
        score -= 4.0;
    }

    // Integer-division dead-space threshold: residual too small for the
    // smallest plausible follow-up item (1..100, min item = 1)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // nearly unusable sliver
    }

    // Lookahead coupling: does next item fit the post residual exactly / well?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0; // perfect harmonic match
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
            // modulo resonance between next item and post residual
            let r = post_residual % next_item_size.max(1);
            score -= (1.0 - r as f64 / next_item_size.max(1) as f64) * 3.0;
        } else {
            // next item cannot use this residual: penalize proportionally
            score += (next_item_size - post_residual) as f64 * 0.05;
        }
    }

    // Last-chance bin: strongly favor using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: prefer existing bins unless this bin is bad
    if bin_residual == bin_capacity {
        // empty bin: neutral-ish baseline; make it worse when a decent fit exists
        score = bin_capacity as f64 * 0.55;
        if fitting_bins_count > 0 && post_residual <= bin_capacity / 4 {
            score += 10.0;
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // pairing large items together in fresh bins
        }
    }

    // Late-stream consolidation: fewer open bins is better near the end
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64).ln().max(0.0) * progress * 2.0;

    // Mean residual coupling: penalize bins far below mean residual (wasteful)
    score += (mean_residual - bin_residual as f64).abs() * 0.05;

    // Fractional-capacity harmonic bonus for residuals that are exact divisors
    if post_residual > 0 && bin_capacity % post_residual == 0 {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // (below the minimum plausible item size) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 18.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Reward tight fits (small but usable post residual).
    let tightness = 1.0 - post_residual as f64 / bin_capacity as f64;
    score -= 25.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits into post_residual, reward;
    // otherwise penalize leaving a gap that the next item cannot use.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 10.0;
        }
    }

    // Open-bin pressure: with many open bins, discourage opening new ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = open_bins_count as f64 * (0.4 + 0.6 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: acceptable early or when nothing fits well,
        // but penalized under high open-bin pressure.
        score += 15.0 + pressure * 2.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open a bin
        }
    } else {
        // Existing bin: mild reward for consolidating when many bins are open.
        score -= pressure * 0.3;
        // Last-chance bin: strongly favor using it before it goes to waste.
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
    }

    // Slight preference for bins below mean residual (keeps residual spread tight).
    score -= 0.15 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when the next item fits exactly in the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            // mild reward proportional to how well next item nests
            let tight = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 60.0 * tight;
        } else {
            // next item cannot fit: post residual is dead space unless tiny
            if post_residual < 10 {
                score -= 20.0; // small crumbs are acceptable
            } else {
                let waste = (post_residual - 10).min(90) as f64;
                score += 0.8 * waste * (1.0 - step_index as f64 / total_items.max(1) as f64).max(0.3);
            }
        }
    }

    // Compare residual against mean residual across open bins.
    let dev = post_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Penalize wasting a nearly-full bin on a small item.
    if item_size < bin_residual / 3 {
        score += 40.0;
    }

    // New-bin candidate: keep it attractive early, discourage when many bins open.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 / (1.0 + mean_residual / 20.0);
        score += 120.0 + pressure;
        if fitting_bins_count == 0 {
            score -= 2000.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual relative to capacity is better.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 6.0 * tightness * tightness;

    // Penalize small unusable dead space (post_residual too small to be useful
    // for typical items, i.e. < 10): strong penalty to avoid wasting bins.
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Lookahead: if the next item fits into the post-residual, strongly reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let combo_quality = 1.0 - ((post_residual - next_item_size) as f64) / (bin_capacity as f64);
        score -= 12.0 * combo_quality;
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item cannot use leftover space: mild penalty scaled by wasted space.
        score += 0.15 * (post_residual as f64).sqrt();
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Many open bins: discourage spreading; prefer consolidating into existing bins.
    score += 0.4 * (open_bins_count as f64).ln().max(0.0);

    // Bin residual far from mean residual: slight penalty for abnormal bins,
    // favor bins whose residual is "typical" (helps balance).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Time horizon: early in the stream, be pickier about tight fits (long-term
    // efficiency matters); late in the stream, just close bins out.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (1.0 - progress) * 4.0 * tightness;
    score += progress * 0.02 * post_residual as f64;

    // New empty bin candidate: baseline penalty so it only wins when existing
    // bins have poor fits (high scores) or residual is already very fragmented.
    if bin_residual == bin_capacity {
        score += 18.0;
        // If item is large, opening a fresh bin is more attractive.
        score -= 0.1 * item_size as f64;
        // If many bins are open and mean residual is small, opening new bin is fine.
        if open_bins_count > 3 && mean_residual < 15.0 {
            score -= 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let pr = post_residual as f64 / bin_capacity as f64;
    let p2 = progress * progress;
    let p3 = p2 * progress;

    // Reward tight fits more aggressively as stream progresses (smooth polynomial)
    let tightness = (1.0 - pr).powi(2);
    score -= (0.5 + 2.5 * p2 + 2.0 * p3) * tightness * item_size as f64;

    // Penalize dead space polynomially, stronger late in the stream
    let dead = pr * pr;
    score += (10.0 + 40.0 * p2) * dead * (1.0 + 0.5 * p3);

    // Lookahead coupling: reward residuals that can hold the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= (1.0 + 3.0 * progress) * slack / bin_capacity as f64 * 10.0;
    } else if next_item_size > 0 {
        score += 5.0 + 10.0 * progress;
    }

    // Last-chance bonus: strongly favor this bin if it's the only fitting one
    if fitting_bins_count == 1 {
        score -= 8.0 + 6.0 * progress;
    }

    // Slight preference to spread load when many bins are open
    score += (open_bins_count as f64).ln().max(0.0) * mean_residual * 0.02 * (1.0 + progress);

    // New-bin candidate: penalize opening a new bin unless residuals are large
    if bin_residual == bin_capacity {
        let avg_waste = mean_residual / bin_capacity as f64;
        score += 6.0 + 12.0 * (1.0 - avg_waste.min(1.0)) * (0.5 + p2);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize dead space into capacity fractions.
    let frac = post_residual as f64 / bin_capacity as f64;
    let class = (frac * 10.0).floor() as i64; // 0..=10 harmonic class

    // Reward tight fits: lower class (small residual) gets a discount.
    score -= (10 - class.max(0)) as f64 * 4.0;

    // Dead-space penalty for awkward residuals that few future items can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0; // perfect chain
        } else if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            // next item won't fit here; residual becomes dead weight
            score += frac * 12.0;
        }
    }

    // Last-chance bonus: only bin that fits the item.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin starts neutral but gets pushed up
    // (penalized) unless current fit is poor or many bins are open.
    if bin_residual == bin_capacity {
        score += 15.0;
        if post_residual as f64 > mean_residual {
            score -= 10.0;
        }
        if open_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
    }

    // Modulo harmonic: residuals divisible by common item sizes are reusable.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 5.0;
    }
    if post_residual % 20 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    // Prefer filling bins below current mean residual (balance toward tighter bins).
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Late in the stream, be greedier: penalize leaving large residuals.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += frac * progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // plausible future item (items >= 1) are pure waste. Penalize hard.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 4.0;
    }
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    } else if post_residual <= 15 {
        // Tight fit is good but not perfect.
        score -= 15.0;
    }

    // Reward tightness relative to capacity (lower post_residual is better).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 10.0;

    // Open-bin pressure: when many bins are open, prefer consolidating into
    // existing bins rather than opening new ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = open_bins_count as f64 * (0.3 + 0.7 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize with open-bin pressure so a new bin is
        // only chosen when existing fits are truly bad.
        score += 25.0 + pressure * 2.0;
    } else {
        score -= pressure.min(8.0);
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly into the post_residual,
    // this placement is part of a perfect chain.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 35.0;
    } else if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        // Next item would leave dead space here; mild penalty.
        score += 8.0;
    }

    // Slight preference for bins with below-mean residual (use up emptier bins).
    if bin_residual != bin_capacity && (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // next item fits, but leave residual slack penalty proportional to leftover after next
            let after_next = post_residual - next_item_size;
            score -= 100.0 - after_next as f64 * 0.5;
        } else {
            // next item cannot use this bin's residual: penalize wasted space
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
    }

    // Penalize residual far below mean residual (creating dead space relative to fleet)
    score += (mean_residual - post_residual as f64).abs() * 0.1;

    // Last-chance bin bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: only attractive if no tight fit exists elsewhere; make it mediocre
    if bin_residual == bin_capacity {
        score += 50.0 + open_bins_count as f64 * 2.0;
    }

    // Late in stream, consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 20.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly penalize opening a brand-new bin when other bins could fit,
    // unless the fit is extremely poor elsewhere.
    if bin_residual == bin_capacity {
        score += 60.0 + 0.25 * (open_bins_count as f64);
    }

    // Reward near-perfect fits (low post residual) nonlinearly.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    } else {
        // Penalize dead space that no future item (>=1) can use well:
        // small residuals relative to typical item sizes are waste.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let dead_penalty = (post_residual as f64 / 100.0).powi(2) * 30.0;
        score += dead_penalty * (0.5 + 0.5 * progress);
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // heavily reward this placement.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score += slack * 0.15;
        } else {
            // Next item won't fit here; mild penalty for leaving big gap.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.05;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Global-state coupling: when open bins are on average full, prefer
    // spreading load (favor bins with residual below mean).
    let diff = (bin_residual as f64) - mean_residual;
    score += diff * 0.1;

    // Slight preference to fill earlier-opened bins as stream matures.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.6 * progress * progress);

    // Non-linear reward for tight fits, stronger later in the stream
    let tightness = 1.0 - norm_pr;
    score -= 12.0 * tightness.powf(3.0) * (0.5 + progress);

    // Penalize residuals that are dead space relative to plausible future items
    let next_f = next_item_size as f64;
    if next_item_size > 0 {
        let waste = (pr - next_f).max(0.0) as f64;
        score += 0.05 * waste * waste / cap;
        // Reward if next item fits exactly-ish
        let fit_gap = (pr - next_f).abs();
        score -= 4.0 * (-fit_gap / 10.0).exp();
    }

    // Last-chance bonus: avoid opening a new bin when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 - progress * 0.5);
    }

    // Mild pressure to consolidate when many bins are open
    score -= 0.3 * (open_bins_count as f64).ln() * tightness;

    // Keep new-bin candidate competitive only for large items
    if bin_residual == bin_capacity {
        score += 3.0 + 5.0 * (1.0 - item_size as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: overwhelming reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of the leftover space: classify post_residual into
    // capacity-fraction bands. Small leftovers (< capacity/10) are nearly
    // dead space; large leftovers are still useful.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // capacity fraction of leftover
    if frac < 0.10 {
        score += 40.0; // dead-space penalty
    } else if frac < 0.25 {
        score += 12.0;
    } else if frac < 0.50 {
        score -= 4.0;
    } else {
        score -= 8.0; // roomy leftover, still very usable
    }

    // Lookahead coupling: if the next item fits exactly into the leftover,
    // strongly favor this bin (chain fit). If next item cannot fit leftover
    // and this is the last fitting bin, mild penalty for wasting last chance.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size <= post_residual {
            // next item fits: leftover quality matters less
            score -= (post_residual - next_item_size) as f64 * 0.8;
        } else if fitting_bins_count == 1 {
            // last chance bin but next item won't chain: accept anyway but
            // penalize proportional waste so better-fitting bins win
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening
    // a new bin unless the leftover would be tiny dead space.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin has high raw score (residual=cap).
    // Prefer it only when open bins are crowded or leftover would be dead space.
    if bin_residual == bin_capacity {
        // neutralize the high base score so real bins compete
        score -= cap * 0.9;
        // cost of opening a new bin grows with number of open bins
        score += (open_bins_count as f64) * 1.5;
        // early in stream, opening bins is cheap; later, prefer consolidation
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 20.0;
        // if a big item is coming, a fresh bin is valuable
        if next_item_size > 50 {
            score -= 15.0;
        }
    } else {
        // reward filling already-open bins, more so when many bins are open
        score -= (bin_capacity - bin_residual) as f64 * 0.2;
    }

    // Mean residual coupling: when open bins are generally full (low mean
    // residual), opening a new bin is more acceptable; when mean residual is
    // high, strongly prefer using existing space.
    if bin_residual != bin_capacity {
        score -= (mean_residual - pr).max(0.0) * 0.5;
    }

    // Integer-division harmonic thresholds on post_residual: mod-10 classes
    // (typical item granularity) make leftovers reusable by common sizes.
    if post_residual >= 10 && post_residual % 10 == 0 {
        score -= 6.0;
    }
    // leftovers in [1..9] are near-useless for items >= 10
    if post_residual < 10 && post_residual > 0 {
        score += 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        let dead = if post_residual <= 10 {
            60.0 - 4.0 * post_residual as f64 // tiny gaps are near-wasted space
        } else if post_residual < 25 {
            15.0 - 0.3 * post_residual as f64 // moderately hard to refill
        } else {
            0.0
        };
        score += dead;
    } else {
        // Perfect fit: strong reward.
        score -= 80.0;
    }

    // Reward tight fits generally: fraction of bin consumed.
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= 12.0 * tightness;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Lookahead synergy: if next item fits into post_residual, reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 20.0 - 0.25 * slack; // prefer leaving just enough room
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here: mild penalty proportional to leftover gap.
        score += 0.15 * post_residual as f64;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few
    // bins, mildly favor consolidation into existing bins over new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (1.0 + progress * 4.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open or early stream.
        score += 30.0 + 2.0 * pressure + 20.0 * (1.0 - progress);
        // But if no existing bin fits well, allow opening (post_residual large means good future use).
        score -= 0.2 * post_residual as f64;
    } else {
        // Existing bin: slight reward to consolidate when bins are numerous.
        score -= 0.5 * pressure;
    }

    // Prefer bins whose residual is below mean (fill emptier-relative bins to
    // keep a spread of usable residuals).
    let diff = bin_residual as f64 - mean_residual;
    score += 0.1 * diff;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (small dead space).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 50.0 + (10 - post_residual) as f64 * 5.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if diff <= 5.0 {
            score -= 120.0 - diff * 15.0;
        } else if (post_residual as f64) < next_item_size as f64 {
            // post-residual too small for next item: penalize dead space
            score += 10.0 + (next_item_size as f64 - post_residual as f64) * 0.3;
        }
    }

    // Relative-to-mean coupling: bins with residual far below mean are already tight;
    // prefer using them if the fit is decent.
    score -= (mean_residual - bin_residual as f64) * 0.5;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: only attractive when current bin fits are bad.
    if bin_residual == bin_capacity {
        score += 30.0 + open_bins_count as f64 * 0.1;
    }

    // Late-stream consolidation: prefer filling existing bins as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits: post_residual close to 0 is ideal.
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score -= (1.0 - tightness) * (1.0 - tightness) * 12.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Penalize dead space that is too small for typical items (wasted slivers).
    if post_residual > 0 && post_residual < 20 {
        score += 10.0 - (post_residual as f64) * 0.4;
    }

    // Lookahead: if the next item fits exactly in the post-residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            // Next item won't fit here; slight penalty proportional to overflow gap.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.15;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin gets base identity = capacity.
    // Penalize opening a new bin when plenty of open bins exist, unless residuals are tight.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 2.0;
        // If open bins have large mean residual, opening new bin is wasteful.
        score += mean_residual * 0.3;
        // Late in stream, prefer consolidating into existing bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 10.0;
        // But if next item is huge and nothing fits, new bin is fine: mild discount.
        if next_item_size > 60 && mean_residual < next_item_size as f64 {
            score -= 15.0;
        }
    }

    // Slight preference for filling bins with larger residuals when many bins are open
    // (balance load, keep some bins flexible).
    score += (bin_residual as f64 - mean_residual) * 0.05;

    // Time-horizon modulation: early on, be conservative with slivers; later, accept them.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if post_residual > 0 && post_residual < 20 && progress < 0.5 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with non-linear polynomial shaping
    let mut score = pr
        + 40.0 * norm_pr * norm_pr
        + 60.0 * norm_pr * norm_pr * norm_pr;

    // Progress coupling: residual waste matters more later in the stream
    let prog_term = progress * (1.0 - progress) * 4.0; // peaks mid-stream at 1.0
    score += prog_term * 30.0 * norm_pr * norm_pr;

    // Tight fit reward: smooth bump near post_residual == 0
    let tightness = 1.0 - norm_pr;
    score -= 25.0 * tightness * tightness * tightness;

    // Last-chance bin: strong penalty to avoid opening new bins unnecessarily
    if fitting_bins_count == 1 {
        score -= 35.0 + 20.0 * progress;
    }

    // Lookahead: reward if next item fits the post residual smoothly
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        let fit_ratio = next_item_size as f64 / cap;
        score -= 15.0 * fit_ratio * (1.0 - fit_ratio) * 4.0;
    } else if next_item_size > 0 {
        score += 10.0 * (next_item_size as f64 - pr) / cap;
    }

    // Mean residual deviation: prefer bins near mean residual (balanced packing)
    let dev = (pr - mean_residual) / cap;
    score += 8.0 * dev * dev;

    // New-bin candidate: neutral-ish baseline, penalized unless current bins are bad
    if bin_residual == bin_capacity {
        score = cap + 20.0 * progress - 10.0 * (mean_residual / cap).min(1.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
