    // Harmonic classes: classify post_residual by capacity fraction bands.
    let frac = post_residual as f64 / bin_capacity as f64;
    // Penalize "awkward" residual classes that rarely refill:
    // tiny slivers (1..=5) are near-dead space; mid gaps (15..=30) are semi-usable.
    if post_residual > 0 && post_residual <= 5 {
        score += 60.0; // dead sliver
    } else if post_residual >= 15 && post_residual <= 30 {
        score += 15.0;
    } else if post_residual > 30 {
        score -= 10.0; // roomy residual likely reusable
    }

    // Modulo arithmetic on residual: residuals that are multiples of common
    // item-size classes (10, 20, 25, 50) are more likely to be filled later.
    let pr = post_residual;
    let harmonic_bonus = if pr % 10 == 0 { 12.0 }
    else if pr % 25 == 0 { 10.0 }
    else if pr % 5 == 0 { 5.0 }
    else { 0.0 };
    score -= harmonic_bonus;

    // Lookahead: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 250.0;
        } else if next_item_size <= pr && pr - next_item_size <= 5 {
            score -= 80.0;
        } else if next_item_size > pr {
            score += 8.0; // next item won't fit here; keep residual for later
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: opening a new bin should only win when
    // current bin would leave a very awkward residual.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, discounted early in the stream
        // and when many bins are already open (consolidation pressure).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_bin_score = 45.0 - 25.0 * progress;
        if open_bins_count > 4 { new_bin_score -= 10.0; }
        // If the item is large, a fresh bin is attractive (big residual left).
        if item_size >= bin_capacity / 2 { new_bin_score -= 15.0; }
        // If next item is huge, fresh bin preserves big residual for it.
        if next_item_size >= 60 { new_bin_score -= 20.0; }
        score = new_bin_score + post_residual as f64 * 0.1;
    }

    // Mild preference for fuller bins overall (align with mean residual).
    score += (mean_residual - post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // plausible items (<= 10) are pure waste; penalize them quadratically.
    if post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 8.0;
    }

    // "Awkward gap" band: residuals that few item sizes can use are risky.
    if post_residual > 0 && post_residual < 20 {
        score += 12.0;
    }

    // Reward tight fits (small post_residual) super-linearly.
    score -= (bin_residual - post_residual) as f64 * 0.15;

    // Exact fit is ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: favor bins whose post_residual can still hold the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 6.0;
    }

    // Open-bin pressure: with many bins open, prefer filling existing ones
    // and avoid opening new bins unless the fit is good.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Last-chance bin: strongly prefer using it over opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Mean-residual coupling: bins far below the mean residual are already
    // "full-ish"; finishing them is good, keeping them as candidates is bad.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    // New-bin candidate: make it moderately attractive only when no open bin
    // offers a tight fit; otherwise it should lose to existing bins.
    if bin_residual == bin_capacity {
        score += 15.0 + open_bins_count as f64 * 2.0;
        if post_residual >= 60 {
            score -= 20.0; // large item, fresh bin is natural
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more aggressively than linear.
    score -= 0.5 * (bin_capacity as f64 - post_residual as f64);

    // 2-step lookahead: strong reward if next item fits exactly in post_residual.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot fit here: penalize leaving a gap it could have used elsewhere
            score += 5.0;
        }
    }

    // Penalize post_residual that is too small to be useful (dead space, < 10).
    if post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Compare residual against mean residual across open bins.
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // New-bin candidate: penalize opening a new bin unless current fits are poor.
    if bin_residual == bin_capacity {
        score += 30.0;
        // But if lookahead matches a fresh bin perfectly, soften the penalty.
        if next_item_size > 0 && next_item_size == bin_capacity - item_size {
            score -= 20.0;
        }
    }

    // Late in the stream, prefer consolidating into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (open_bins_count as f64 / 10.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Convex penalty on leftover space: small leftovers are cheap, large ones expensive.
    score += 0.015 * pr * pr / cap;

    // Dead-space penalty: leftover that cannot host the lookahead item is wasted
    // unless it is near-zero (still useful for tiny future items).
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if pr < n && pr > 0.0 {
            score += 0.6 * (n - pr) * (1.0 + progress);
        } else if pr >= n {
            // reward bins that remain usable for the next item
            score -= 0.25 * n.min(pr) / cap * 10.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // Prefer bins whose residual is below the mean (filling fuller bins first),
    // keeping a healthy spread of residuals across open bins.
    score += 0.12 * (mean_residual - bin_residual as f64).max(-20.0);

    // Coupling: when many bins are open, be pickier about loose fits.
    score += 0.05 * open_bins_count as f64 * (pr / cap);

    // New-bin candidate handling: baseline score ~ the lookahead dead-space of a
    // fresh bin, so it beats only genuinely poor fits.
    if bin_residual == bin_capacity {
        let n = if next_item_size > 0 { next_item_size as f64 } else { 10.0 };
        score = n + 2.0 + 3.0 * (1.0 - progress);
        // Opening a bin when few are open is cheap; when many are open and a
        // last-chance bin exists, this stays high and loses.
        score += 0.02 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let prn = pr / cap; // normalized post residual
    let irn = item_size as f64 / cap;
    let mrn = mean_residual / cap;

    // Base: waste term, mildly convex in post_residual (dead space penalty)
    let mut score = pr + 8.0 * prn * prn * cap;

    // Smooth non-linear coupling with stream progress:
    // early on, prefer tight fits less aggressively; later, tighten hard.
    let progress_warp = (t * std::f64::consts::PI).sin(); // smooth 0->1->0 shape
    score -= 6.0 * prn * (1.0 + progress_warp) * cap * 0.1;

    // Quadratic interaction: residual vs progress (late items demand low waste)
    score += 20.0 * prn * prn * t * cap * 0.05;

    // Cubic coupling of item size with progress (big items late -> hoard space)
    score -= 15.0 * irn * irn * (1.0 - t) * t;

    // Mean residual alignment: prefer bins near the mean (smoothness term)
    let dev = (pr - mean_residual) / cap;
    score += 10.0 * dev * dev * (0.5 + 0.5 * t);

    // Last-chance bonus (smooth, not piecewise): fewer fitting bins -> stronger pull
    let scarcity = 1.0 / (fitting_bins_count as f64);
    score -= 25.0 * scarcity * (1.0 - prn);

    // Lookahead coupling: if next item fits in post residual, reward; else penalize
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fits = (post_residual as f64 - nx).max(0.0) / cap;
        let miss = (nx - post_residual as f64).max(0.0) / cap;
        score -= 12.0 * fits;
        score += 18.0 * miss * miss * cap * 0.05;
    }

    // Open bins pressure: many open bins -> discourage spreading, favor filling
    let obn = open_bins_count as f64;
    score += 0.3 * obn * prn * prn;

    // New-bin candidate: penalize empty-bin opening unless residual waste would be large
    if bin_residual == bin_capacity {
        score += 30.0 - 20.0 * irn * irn - 10.0 * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which capacity fraction band does it fall in?
    let cap = bin_capacity as f64;
    let post_f = post_residual as f64;
    let frac = post_f / cap; // residual as fraction of capacity

    // Integer-division harmonic classes on post_residual (mod arithmetic)
    let class16 = (post_residual % 16) as f64;
    let class8 = (post_residual % 8) as f64;
    let div4 = (post_residual / 4) as f64;

    // Reward residuals that are "harmonically clean" — divisible by common item sizes
    if post_residual == 0 {
        score -= 60.0; // perfect fill
    } else {
        if post_residual % 10 == 0 { score -= 8.0; }
        if post_residual % 20 == 0 { score -= 6.0; }
        if post_residual % 25 == 0 { score -= 5.0; }
        if post_residual % 50 == 0 { score -= 4.0; }
        // penalize awkward remainders (dead space classes)
        score += class16 * 0.35 + class8 * 0.15;
    }

    // Next-item lookahead: if next item fits exactly in the post residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            let left_after_next = (post_residual - next_item_size) as f64;
            score -= 12.0 - left_after_next * 0.12;
        } else {
            // next item won't fit here; penalize proportionally to wasted potential
            let overflow = (next_item_size - post_residual) as f64;
            score += overflow * 0.08;
        }
        // harmonic coupling: next item divides post residual evenly
        if post_residual > 0 && next_item_size > 0 && post_residual % next_item_size == 0 {
            score -= 10.0;
        }
    }

    // Tight fit reward: item nearly fills the bin
    let tightness = 1.0 - frac; // 1.0 when post_residual ~ 0
    score -= tightness * 15.0;

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when no open bin gives a good fit
    if bin_residual == bin_capacity {
        // penalize opening new bins mildly, scaled by stream progress and open bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = cap * 0.55 + progress * 10.0 + open_bins_count as f64 * 1.5;
        // if the item is large relative to capacity, opening a fresh bin is more reasonable
        score -= (item_size as f64 / cap) * 25.0;
        // but if mean residual across open bins is large, prefer reusing
        score += mean_residual * 0.25;
    }

    // Mild diversity pressure: keep residuals spread around mean
    score += (post_f - mean_residual).abs() * 0.05;

    // Small harmonic threshold bonus via integer division tiers
    if div4 <= 5.0 { score -= 3.0; }       // post_residual <= 20: compact
    else if div4 <= 12.0 { score -= 1.0; } // post_residual <= 48
    else { score += 1.5; }                 // large leftover

    // tiny progress-based tie-breaker jitter (deterministic)
    score += ((step_index % 7) as f64) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // Define "unusable" as a gap smaller than the smallest plausible item (1)
    // but practically: gaps below a threshold relative to typical item sizes.
    let dead_threshold = 8.0;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 6.0; // heavy penalty for tiny dead gaps
    }
    if post_residual == 0 {
        score -= 40.0; // perfect fit is excellent
    }

    // Reward tight fits: fraction of bin used by this placement.
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= fill_frac * 15.0;

    // Penalize creating a gap that the lookahead item cannot use but could
    // have used a slightly different gap. If next item fits exactly into
    // post_residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size > post_residual {
            // gap too small for next item: mild penalty proportional to gap size
            score += (post_residual as f64) * 0.3;
        } else {
            // gap leaves leftover after next item
            let after_next = post_residual - next_item_size;
            score += (after_next as f64) * 0.4;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin gets base neutral score plus
    // pressure from open bins count; opening new bins is penalized when many
    // bins are open, encouraging consolidation.
    if bin_residual == bin_capacity {
        // base cost of a new bin: high, modulated by open bin pressure
        score = bin_capacity as f64 * 1.1 + (open_bins_count as f64) * 4.0;
        // if no bin fits well anywhere (this call is the new-bin candidate),
        // fitting_bins_count counts open bins that fit; if few fit, new bin ok
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
        // early in stream, allow more bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - progress) * 25.0;
    } else {
        // open-bin pressure: when many bins are open, favor filling existing
        // ones (subtract more for using existing bins).
        score -= (open_bins_count as f64) * 0.5;

        // prefer bins with residual close to item (tightness)
        let tightness = 1.0 - (bin_residual - item_size) as f64 / bin_capacity as f64;
        score -= tightness * 10.0;
    }

    // Mild preference to place into bins below mean residual (balance avoidance
    // of many medium gaps): penalize bins whose post placement deviates high
    // from mean residual.
    let mean_post = mean_residual - item_size as f64;
    if post_residual as f64 > mean_post {
        score += (post_residual as f64 - mean_post) * 0.5;
    } else {
        score -= (mean_post - post_residual as f64) * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to bin capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Penalize dead space that is too small for typical items (unusable gap).
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Aggressive 2-step lookahead: reward when next item exactly matches post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chaining
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            // next item cannot fit here; penalize proportionally to overshoot
            let overshoot = (next_item_size - post_residual) as f64;
            score += 5.0 * (overshoot / (bin_capacity as f64));
        }
    }

    // Compare against mean residual: bins with residual near mean are neutral,
    // bins far below mean (very full) are preferred.
    score += 0.3 * ((bin_residual as f64) - mean_residual);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin is penalized unless the current
    // item fits very poorly everywhere. Empty-bin call has post_residual = capacity - item,
    // which is large, so base score is high; add extra penalty modulated by how well
    // the item would use a fresh bin.
    if bin_residual == bin_capacity {
        // A fresh bin wastes (capacity - item) immediately; penalize more when item is small.
        let waste = (bin_capacity - item_size) as f64;
        score += 15.0 + 0.2 * waste;
        // But if lookahead suggests a perfect chain into a fresh bin, soften penalty.
        if next_item_size > 0 && next_item_size == post_residual {
            score -= 50.0;
        }
        // Late in the stream, slightly discourage opening bins (fewer chances to fill).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
    }

    // Mild bonus for consolidating into already-open bins when many bins are open.
    if bin_residual != bin_capacity {
        score -= 0.5 * (open_bins_count as f64).ln().max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared penalty on leftover space (dead space is costly).
    let pr = post_residual as f64;
    score += 0.35 * pr * pr / bin_capacity as f64;

    // Lookahead: if the next item fits exactly in the post-residual, strongly favor this bin.
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if post_residual == next_item_size {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Next item fits but not perfectly: mild reward proportional to how snug it is.
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Placing here makes post-residual unusable for next item; penalize if waste is large.
            let waste = pr + ns;
            if waste > bin_capacity as f64 {
                score += 8.0;
            }
        }
    } else {
        // Last item: just minimize leftover.
        score += 5.0 * pr / bin_capacity as f64;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when current item
    // would leave a very poor residual in existing bins, or few bins fit the item.
    if bin_residual == bin_capacity {
        // Neutral base for a fresh bin: its post_residual is large, so the base score
        // already penalizes it; add a mild opening cost.
        score += 10.0;
        // But if the item is large relative to capacity and few bins fit, opening is fine.
        let big_item = item_size as f64 / bin_capacity as f64;
        if big_item > 0.6 {
            score -= 15.0 * (big_item - 0.6) / 0.4;
        }
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
        // Late in the stream, avoid proliferating bins with tiny leftovers elsewhere.
        let t = step_index as f64 / (total_items.max(1) as f64);
        if mean_residual < item_size as f64 * 0.5 && t > 0.5 {
            score -= 10.0 * t;
        }
    }

    // Global state: many open bins with high mean residual -> prefer consolidating into
    // bins whose residual is below average (reducing fragmentation).
    if bin_residual != bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score += 0.15 * diff;
        // Encourage closing out nearly-full bins to reduce open bin count.
        if post_residual <= 10 {
            score -= 8.0;
        }
        // If many bins fit the item, mildly prefer the emptiest (largest residual) to
        // consolidate load, unless post-residual would be tiny.
        if fitting_bins_count > 2 && post_residual > 20 {
            score -= 0.05 * bin_residual as f64;
        }
    }

    // Time horizon: early in the stream, be conservative about tight fits that strand
    // space; later, prioritize immediate compaction.
    let t = step_index as f64 / (total_items.max(1) as f64);
    score -= 6.0 * t * (1.0 - pr / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Smooth non-linear polynomial coupling of post_residual with stream progress
    let norm_pr = pr / cap;
    let t = progress;
    let coupling = norm_pr * norm_pr * (1.0 + 3.0 * t) - norm_pr * (0.5 + 2.0 * t * t);
    score += 20.0 * coupling;

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= 8.0 * tightness * tightness * (0.5 + t);

    // Penalize dead space relative to mean residual
    score += 0.3 * (pr - mean_residual);

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: favor bins whose post-residual fits the next item
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 6.0 * (1.0 - (next_item_size as f64) / cap) * (0.5 + t);
    }

    // Mild penalty for spreading across many bins early on
    score += 0.5 * (open_bins_count as f64) * (1.0 - t);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual), non-linear.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize "awkward" dead space: post_residual in bad harmonic classes.
    let pr = post_residual;
    if pr > 0 {
        // Dead space that no plausible item (1..=100) can use well.
        if pr < 10 {
            score += 8.0; // tiny unusable slivers
        } else if pr > 80 {
            score -= 4.0; // still roomy, flexible
        }
        // Modulo-10 harmonic classes: residuals divisible by 10 pair well
        // with the 10-multiple grid of many streams.
        if pr % 10 == 0 {
            score -= 3.0;
        } else if pr % 5 == 0 {
            score -= 1.5;
        } else {
            score += 1.0;
        }
        // Integer-division thresholds: post_residual bucketed by capacity fractions.
        let bucket = pr / 25; // 0..4
        score += match bucket {
            0 => 2.0,           // 0..24: risk of dead space
            1 => 0.0,           // 25..49: decent
            2 => -1.0,          // 50..74: good flexibility
            _ => -2.0,          // 75..100: very flexible
        };
    }

    // Last chance: this is the only bin that fits the item.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Lookahead coupling: reward if next item exactly fills post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0; // perfect chaining
        } else if next_item_size <= post_residual {
            score -= 6.0; // next item still fits here
        } else {
            // next item won't fit; small penalty proportional to overshoot class
            let over = (next_item_size - post_residual) / 20;
            score += 1.0 + over as f64;
        }
        // If post_residual too small for typical items, penalize more.
        if post_residual < next_item_size.min(10) {
            score += 5.0;
        }
    }

    // New-bin candidate handling: an empty bin is flexible but costs a bin.
    if bin_residual == bin_capacity {
        // Prefer new bin only when no open bin offers a decent fit,
        // or when the stream is early and many items remain.
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_open_fit = fitting_bins_count == 0 || post_residual < 15;
        if poor_open_fit {
            score -= 15.0;
        } else {
            // discourage opening new bins when existing ones suffice,
            // especially late in the stream.
            score += 10.0 + 20.0 * progress;
        }
        // Slight bias against hoarding too many open bins.
        score += (open_bins_count as f64).sqrt() * 0.5;
    }

    // Mild preference toward bins with low mean residual context
    // (pack fuller bins first when the fleet is generally full).
    if (post_residual as f64) < mean_residual {
        score -= 2.0;
    } else {
        score += 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space (gap < 10, or gap too small for typical next item)
    if post_residual > 0 {
        if post_residual < 10 {
            score += 40.0; // tiny gap is pure waste
        } else if next_item_size > 0 && post_residual < next_item_size {
            // gap can't fit the lookahead item — mild penalty scaled by gap smallness
            score += (post_residual as f64) * 0.3;
        } else if next_item_size > 0 && post_residual >= next_item_size {
            // gap usable by lookahead: reward tight-but-usable fit
            score -= 8.0;
        }
    } else {
        // perfect closure: strong reward
        score -= 25.0;
    }

    // Tight fit reward: item fills most of the residual
    let fill_ratio = item_size as f64 / bin_residual as f64;
    if fill_ratio > 0.85 {
        score -= 15.0 * fill_ratio;
    }

    // Last-chance bin bonus: only one bin fits, avoid opening new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Open bins pressure: many open bins favor consolidation into existing bins
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
    score += pressure * 0.5;

    // New-bin candidate handling: prefer opening a new bin only when fits are poor
    if bin_residual == bin_capacity {
        // neutral baseline; penalize when existing bins fit well (post_residual small)
        if post_residual > 0 && post_residual < 30 {
            score += 20.0; // existing bin would close tightly, don't open new
        }
        score += open_bins_count as f64 * 0.2;
        if fitting_bins_count == 1 {
            score += 30.0; // last chance: strongly prefer the existing bin
        }
    }

    // Late stream: slightly favor closing bins cleanly
    let progress = step_index as f64 / total_items as f64;
    if post_residual == 0 {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect fit (zero waste).
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual exactly matches the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0; // chain two items perfectly
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // penalize leftover after hypothetically placing next item
            score += slack * 0.8;
            if slack < 10.0 {
                score -= 50.0; // near-perfect chain
            }
        } else {
            // next item won't fit here; mild penalty scaled by gap
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.3;
        }
    }

    // Penalize small unusable dead space (wasted capacity).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // Prefer bins with below-mean residual (tighter bins get filled first).
    score += (mean_residual - bin_residual as f64) * 0.5;

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let bad_fit = if next_item_size > 0 && post_residual > 0 && post_residual < 10 { 1.0 } else { 0.0 };
        score += 120.0 - 200.0 * bad_fit + (open_bins_count as f64) * 2.0;
    }

    // Late in stream: consolidate harder, avoid opening new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 15.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 8.0;

    // Penalize leaving awkward dead space (small but nonzero post-residual).
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }
    if post_residual >= 10 && post_residual < 20 {
        score += 2.0;
    }

    // Lookahead: reward if the next item can exactly fill the post-residual,
    // penalize if next item is slightly larger than post-residual (wasted opportunity).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 12.0;
        } else if next_item_size > post_residual && next_item_size <= bin_residual {
            score += 3.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.15;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the
    // item is large and existing residuals are small/fragmented.
    if bin_residual == bin_capacity {
        let t = step_index as f64 / (total_items.max(1) as f64);
        let openness = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        // Penalize opening new bins when existing bins are roomy; allow it when
        // open bins are nearly full or fragmented.
        score += 14.0 * openness + 4.0 * (1.0 - t);
        if item_size > 60 {
            score -= 6.0; // large items fine in a fresh bin
        }
        if open_bins_count == 0 {
            score -= 20.0;
        }
    }

    // Slight preference for consolidating into bins with below-average residual
    // (keeps some bins large for future big items).
    if bin_residual < bin_capacity {
        if (bin_residual as f64) < mean_residual {
            score -= 1.5;
        } else {
            score += 1.5;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let r = post_residual as f64;
    let cap = bin_capacity as f64;
    let r_norm = r / cap;

    // Base: post residual, but weighted non-linearly by stream progress.
    // Late in the stream, small residuals matter more (wasted space is permanent).
    let mut score = r * (1.0 + 0.9 * progress * progress);

    // Non-linear penalty for awkward residuals: quadratic coupling of residual
    // with item size fraction. Residuals just below a plausible item size are dead space.
    let item_frac = item_size as f64 / cap;
    let awkward = (r_norm / (item_frac + 0.05)).sin().abs();
    score += 12.0 * awkward * (1.0 - progress);

    // Reward tight fits: subtract quadratically as post_residual -> 0.
    score -= 25.0 * (1.0 - r_norm).powi(6) * (1.0 + 0.5 * progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 40.0 * (1.0 + progress);
    }

    // Lookahead: reward if next item fits the post-residual (chaining).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= r {
            let slack_fit = 1.0 - ((r - nxt) / cap);
            score -= 10.0 * slack_fit * slack_fit;
        } else {
            // Next item won't fit here; penalize residuals that block it slightly.
            score += 4.0 * (nxt - r) / cap;
        }
    }

    // Mild pressure to consolidate: prefer bins with below-average residual
    // (fills fuller bins first), scaled non-linearly by open bin count.
    let density = (open_bins_count as f64).ln().max(1.0);
    score += 3.0 * density * (r_norm - mean_residual / cap).max(0.0);

    // New-bin candidate (empty bin): make it moderately attractive only when
    // current bins would leave very bad fits, and early in the stream.
    if bin_residual == bin_capacity {
        let early_bias = 1.0 - progress;
        score = r * (1.0 + 0.9 * progress * progress)
            + 8.0
            - 18.0 * early_bias * early_bias
            - 15.0 * item_frac;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "usable" the leftover space is.
    // Class 0: post_residual == 0 (perfect fit) -> big reward.
    // Class 1: post_residual <= 10 (tiny dead space) -> reward.
    // Class 2: post_residual in 11..=25 -> mildly useful.
    // Class 3: larger but still potentially fillable -> neutral.
    // Class 4: awkward large leftover -> penalize.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 35.0;
    } else if post_residual <= 25 {
        score -= 10.0;
    } else if post_residual <= 50 {
        score += 4.0;
    } else {
        score += 12.0;
    }

    // Integer-division thresholds: leftover divisible into plausible item sizes
    // (multiples of 10, 25, 50) is more likely to be filled later.
    let pr = post_residual;
    if pr >= 10 && (pr % 10 == 0 || pr % 25 == 0 || pr == 50 || pr == 75) {
        score -= 12.0;
    }
    // Residuals just below a harmonic class boundary (9, 24, 49) are dead space.
    if pr == 9 || pr == 24 || pr == 49 || pr == 74 {
        score += 10.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size <= pr {
            score -= 18.0 * (next_item_size as f64 / pr as f64);
        } else {
            // next item won't fit here; penalize proportionally to wasted opportunity
            score += 6.0 * ((next_item_size - pr) as f64 / cap);
        }
        // Harmonic pairing: next_item + item_size near capacity multiples
        let sum = item_size + next_item_size;
        if sum <= bin_capacity && (bin_capacity - sum) <= 10 {
            score -= 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }
    // Many fitting bins: mild penalty for wasting a scarce bin choice is not needed;
    // instead reward tight fits more when competition is high.
    if fitting_bins_count > 1 {
        score -= 5.0 * (1.0 - (post_residual as f64 / cap));
    }

    // Progress-based opening of fresh bins: early in stream, a new empty bin is cheap;
    // late in stream, prefer packing existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline slightly worse than a decent fit.
        score = cap * 0.55 - 15.0 * (1.0 - progress);
        // If item is large and no bin fits well, opening new bin is attractive.
        if item_size >= 50 {
            score -= 10.0;
        }
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Mean-residual coupling: if this bin is far below mean residual (already tight),
    // prefer filling it further (keeps residual distribution compact).
    let diff = mean_residual - bin_residual as f64;
    score += 0.15 * diff;

    // Small tie-break noise-free jitter via deterministic coupling on step parity.
    if step_index % 2 == 0 {
        score -= 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to be useful later
    // (but nonzero) are the worst outcome. Penalize them heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Reward very tight fits (almost-exact packing).
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead synergy: if the next item fits the post-residual, this placement
    // is doubly good.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
    }
    // If next item almost fits (off by a little), slight penalty for stranding it.
    if next_item_size > post_residual && next_item_size <= post_residual + 10 && next_item_size > 0 {
        score += 8.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing
    // bins rather than spreading; with few bins, new bins are cheaper.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln().max(0.0) * (2.0 + 3.0 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline is its post-residual (large). Nudge it down
        // when few bins are open (spreading is fine), push it up under pressure.
        score -= pressure * 0.5;
        score += mean_residual * 0.05;
    } else {
        score += pressure * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits (small dead space)
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // 2-step lookahead: reward if next item fits the post-residual exactly or well
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64 - nxt).abs() <= 2.0 {
            score -= 40.0;
        } else if post_residual as u32 >= next_item_size {
            score -= 12.0;
        } else {
            // next item won't fit here; penalize wasted residual
            score += 0.3 * (post_residual as f64 - nxt).abs();
        }
    }

    // Penalize large residual waste relative to mean residual of open bins
    score += 0.5 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Slight penalty for opening new bins when few bins are open
    if bin_residual == bin_capacity {
        score += 5.0 + 2.0 * open_bins_count as f64;
    }

    // Early-stream: be more willing to open bins (favor tight fits later)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (post_residual near zero is excellent).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // unusable sliver
    } else if post_residual >= 10 && post_residual < 25 {
        score += 2.0; // awkward mid-range gap
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here anyway; mildly prefer leaving usable space.
            score += 1.5;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: opening a bin is attractive only if current open bins
    // are crowded and we're early/mid stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowding = mean_residual / bin_capacity as f64;
        // High mean residual => existing bins roomy => discourage new bin.
        score += 25.0 * crowding;
        // Late in stream, prefer filling existing bins.
        score += 15.0 * progress;
        // Many open bins: discourage another.
        score += (open_bins_count as f64).ln().max(0.0) * 3.0;
        // Perfect-fit alternative absent: allow new bin when item is large.
        if item_size > bin_capacity / 2 {
            score -= 5.0;
        }
    }

    // Prefer bins whose residual is already below average (consolidate waste).
    if bin_residual < bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score -= 0.05 * diff;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let prn = pr / cap;
    let irn = item_size as f64 / cap;
    let mrn = mean_residual / cap;
    let nx = next_item_size as f64 / cap;

    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = prn * (1.0 - prn) * (0.5 + progress);
    score -= 40.0 * poly;
    score += 15.0 * prn * prn * (0.25 + 0.5 * progress);

    // Tight fits rewarded, scaled by progress
    let tight = 1.0 - (prn * 4.0).min(1.0);
    score -= 25.0 * tight * (0.4 + 0.6 * progress);

    // Lookahead: penalize if next item cannot use the leftover space
    if next_item_size > 0 {
        let gap = (nx - prn).abs();
        score += 12.0 * gap * (1.0 - progress);
        if nx <= prn && nx > 0.0 {
            score -= 10.0 * nx * (1.0 - prn);
        }
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 * (1.0 - prn);
    }

    // New-bin candidate: penalize mildly unless open bins are fragmented
    if bin_residual == bin_capacity {
        let frag = (mrn - prn).abs();
        score += 8.0 + 10.0 * (1.0 - progress) - 15.0 * frag;
    }

    // Spread pressure via mean residual divergence
    score += 5.0 * (prn - mrn).abs() * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: dead space in the "hard to fill"
    // small ranges is penalized more (sizes 1..100, capacity 100).
    let pr = post_residual;
    if pr > 0 {
        // Fractional capacity of leftover space.
        let frac = pr as f64 / cap;
        // Harmonic weighting: small residuals are expensive dead space.
        score += (1.0 / (frac + 0.05)) * 0.6;
        // Modulo classes: residuals that pair with common item sizes are good.
        // Reward residuals divisible by common granularities (10, 25, 50).
        if pr % 10 == 0 { score -= 3.0; }
        if pr % 25 == 0 { score -= 2.0; }
        if pr % 50 == 0 { score -= 2.0; }
        // Penalize awkward residual bands where few item sizes fit.
        if pr < 10 { score += 8.0; }        // nearly unusable
        else if pr < 20 { score += 4.0; }
        else if pr < 30 { score += 1.5; }
    } else {
        // Perfect fill: strongly favored.
        score -= 25.0;
    }

    // Exact fit of current item (post_residual == 0 handled above); near-exact fits.
    if post_residual > 0 && post_residual <= 5 {
        score -= 6.0;
    }

    // Lookahead: does the next item fit into the post-residual?
    if next_item_size > 0 && next_item_size <= pr {
        score -= 5.0;
        // Extra reward if next item fills the remainder almost exactly.
        let gap = pr - next_item_size;
        if gap <= 5 { score -= 4.0; }
    } else if next_item_size > pr && next_item_size > 0 {
        // Next item won't fit here: leftover is dead unless tiny.
        score += 2.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: opening a new bin should be a deliberate choice.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin grows with how many bins are already open.
        score += 18.0 + 0.5 * open_bins_count as f64;
        // But if item is large and would leave a well-structured residual, allow it.
        if item_size >= 50 { score -= 6.0; }
        // Late in the stream, avoid proliferation of bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 6.0;
    }

    // Prefer tighter bins overall: deviation from mean residual.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.3 * dev;

    // Mild preference for fuller bins as stream progresses.
    let fill = 1.0 - (bin_residual as f64 / cap);
    score -= fill * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable small gaps (dead space below the smallest possible item)
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    }

    // Reward tight fits: small post_residual relative to item size
    score -= item_size as f64 * 0.35;

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Pressure from number of open bins: discourage spreading when many bins open
    score += open_bins_count as f64 * 0.6;

    // New-bin candidate: penalize opening a new bin unless current fit is bad
    if bin_residual == bin_capacity {
        score += 18.0;
        // More open bins -> new bin more attractive relative to worsening crowding
        score -= open_bins_count as f64 * 0.25;
        // Avoid opening new bin for tiny items
        if item_size < 30 {
            score += 10.0;
        }
    }

    // Lookahead: if next item fits into post_residual, reward this placement
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
    }
    // If next item nearly fits, slight penalty for blocking it
    else if next_item_size > 0 && next_item_size <= bin_residual && next_item_size > post_residual {
        score += 3.0;
    }

    // Alignment with mean residual: prefer bins whose residual is near the mean (keeps bin profile uniform)
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 4.0;

    // Progress-based tuning: later in the stream, be more conservative (favor tighter packing)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item nearly fills the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 6.0 * fit_ratio * fit_ratio;

    // Penalize dead space: residuals too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 2.0;
    }

    // Lookahead: if the next item fits perfectly into post_residual, big bonus.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 12.0;
        } else if post_residual >= next_item_size {
            score -= 3.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item cannot use the leftover; penalize proportionally
            score += 1.5 * (1.0 - post_residual as f64 / (next_item_size as f64 + 1.0)).max(0.0);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // New-bin candidate handling: an empty bin should only win when open bins
    // offer poor fits. Base cost for opening a new bin.
    if bin_residual == bin_capacity {
        score += 15.0;
        // If many bins are open and mean residual is large, opening new bins is wasteful.
        score += 0.3 * open_bins_count as f64;
        if mean_residual > item_size as f64 * 1.5 {
            score += 10.0;
        }
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 8.0 * (1.0 - progress);
    }

    // Mild preference for filling bins that are already partially full relative
    // to the fleet average (balance consolidation).
    if bin_residual != bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score += 0.05 * diff;
    }

    // Late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 4.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let nz = post_residual as f64 / cap;

    // Base: post residual, but with non-linear discount for tight fits
    let mut score = pr;

    // Smooth non-linear coupling: tightness reward grows quadratically with progress
    let tightness = 1.0 - nz; // 0..1, near 1 = tight fit
    score -= 35.0 * tightness * tightness * (0.5 + progress);

    // Cubic dead-space penalty: residuals too small to be useful are punished smoothly
    let dead = (nz - 0.2).max(0.0);
    score += 25.0 * (1.0 - dead / 0.8) * (1.0 - dead / 0.8) * (1.0 - progress);

    // Lookahead coupling: smooth interaction between post_residual and next item
    let nxt = next_item_size as f64;
    if nxt > 0.0 {
        let gap = pr - nxt;
        let s = 1.0 / (1.0 + (-gap / 15.0).exp());
        // sigmoid: reward when next item fits in post residual
        score -= 18.0 * s * (0.4 + 0.6 * progress);
        // penalize exact-tight-then-blocked scenario smoothly
        score += 10.0 * (1.0 - s) * (nz / (1.0 + nz));
    }

    // Last-chance bin: smooth urgency bonus
    if fitting_bins_count == 1 {
        score -= 22.0 * (1.0 - 0.5 * progress);
    }

    // Open bins pressure: mild pull toward consolidation, damped over time
    let pressure = (open_bins_count as f64).ln() / (1.0 + (open_bins_count as f64).ln());
    score += 6.0 * pressure * (1.0 - progress) * (nz / (1.0 + nz));

    // Mean residual alignment: favor bins near the mean residual (smooth Gaussian-like)
    let dev = (pr - mean_residual) / cap;
    score += 8.0 * dev * dev * (1.0 - progress);

    // New-bin candidate handling: smooth penalty so empty bins are chosen only when fits are bad
    if bin_residual == bin_capacity {
        score += 30.0 * (1.0 - tightness) * (1.2 - 0.7 * progress);
        score += 4.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues that are "usable" get rewarded.
    let pr = post_residual;
    let class = pr % 10;
    // Residuals that are multiples of common item sizes (10,20,25,50) are reusable.
    let harmonic_bonus: f64 = match pr {
        0 => -60.0,                       // perfect fit
        _ if pr % 50 == 0 => -25.0,
        _ if pr % 25 == 0 => -18.0,
        _ if pr % 10 == 0 => -12.0,
        _ => 0.0,
    };
    score += harmonic_bonus;

    // Small awkward residues (1..9) are dead space: penalize via modulo class.
    if pr > 0 && pr < 10 {
        score += 30.0 + (10 - pr) as f64 * 2.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if next_item_size == pr {
            score -= 80.0;
        } else if next_item_size < pr {
            let fill = nx / pr as f64;
            score -= 20.0 * fill;
            // harmonic: next item leaves a multiple-of-10 residue again
            if (pr - next_item_size) % 10 == 0 {
                score -= 10.0;
            }
        } else {
            score += 8.0; // next item won't fit here
        }
    }

    // Last-chance bin: strongly prefer using it rather than opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    // or the fit here is terrible.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowded = open_bins_count as f64 / 20.0;
        let poor_fit = (item_size as f64 / cap) < 0.35 && mean_residual < 25.0;
        score += 35.0 - 15.0 * progress + crowded * 10.0;
        if poor_fit { score -= 30.0; }
        if fitting_bins_count == 0 { score -= 40.0; }
    } else {
        // Prefer bins whose residual is close to the item (tight packing).
        let tight = 1.0 - (bin_residual - item_size) as f64 / cap;
        score -= 10.0 * tight;
    }

    // Mild pressure to consolidate when many bins are open.
    score -= 0.05 * open_bins_count as f64;
    // Slight preference toward bins below mean residual (fill emptier-first balancing).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // plausible item are dead weight. Penalize them quadratically.
    let dead_threshold = 9u32; // below min item size
    if post_residual > 0 && post_residual <= dead_threshold {
        score += 3.0 * (dead_threshold - post_residual + 1) as f64;
    }

    // Penalize "awkward" gaps: too small for the next item but nonzero.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 2.5 * (next_item_size - post_residual) as f64;
    }

    // Reward exact or near-exact fits.
    if post_residual == 0 {
        score -= 40.0;
    } else if item_size > 0 && bin_residual >= item_size {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        if fill_ratio > 0.9 {
            score -= 15.0 * fill_ratio;
        }
    }

    // Reward using bins whose residual is close to the item (best-fit core).
    let gap = (bin_residual as i64 - item_size as i64).max(0) as f64;
    score += gap * 0.5;

    // Last-chance pressure: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into
    // fresh bins; consolidate.
    let open_pressure = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost grows with number of open bins.
        score += 10.0 + 25.0 * open_pressure;
        // Opening a bin is fine if no open bin fits well (gap large).
        if gap > item_size as f64 {
            score -= 12.0;
        }
        // Late in the stream, prefer closing out existing bins.
        if total_items > 0 {
            let progress = step_index as f64 / total_items as f64;
            score += 15.0 * progress;
        }
    } else {
        // Reward placing into bins with below-average residual (tightly
        // packed bins), encouraging consolidation.
        if (bin_residual as f64) < mean_residual {
            score -= 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
