pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual relative to item size is better.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead: strongly favor bins whose leftover can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0 + 0.15 * next_item_size as f64;
        } else if post_residual > 0 {
            // Dead space that the next item cannot use: penalize.
            score += 0.3 * post_residual as f64;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Opening a new bin is only attractive when existing bins fit poorly
    // (large post_residual or many nearly-full bins).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, discounted when many bins are open
        // and mean residual is small (existing bins are congested).
        let congestion = 1.0 - (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score += 20.0 - 15.0 * congestion;
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Global pressure: when few bins fit the item, mildly favor any fitting bin
    // to avoid wasted capacity elsewhere.
    if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).ln().max(0.0);
    }

    // Slight preference for placing into bins below mean residual (balance load,
    // preserving large residuals for large future items).
    if (bin_residual as f64) > mean_residual && bin_residual < bin_capacity {
        score += 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let item = item_size as f64;

    // Base: prefer small post-residual (tight fit), scaled non-linearly.
    let mut score = post * (1.0 + 0.8 * progress * progress);

    // Reward tight fits with a smooth quadratic bonus for near-zero waste.
    let fit_quality = 1.0 - (post / cap).clamp(0.0, 1.0);
    score -= 30.0 * fit_quality * fit_quality * (0.5 + 0.5 * progress);

    // Penalize dead space that is too small to be useful for future items
    // (smooth logistic-style term around small residuals).
    let dead = (post / 20.0).exp() - 1.0;
    score += 4.0 * dead * (1.0 - fit_quality);

    // Lookahead coupling: if the next item fits into post_residual, reward it.
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 12.0 * (1.0 - progress) * (1.0 - post / cap);
    } else if next_item_size > 0 {
        // Next item won't fit: penalize wasting space if post-residual is large.
        score += 6.0 * (post / cap) * (1.0 - progress);
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // New-bin candidate: make it attractive only when open bins are fragmented
    // or the fit is poor; otherwise discourage opening new bins.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).clamp(0.0, 1.0);
        let openness = (open_bins_count as f64).ln() + 1.0;
        score += 8.0 * openness * (1.0 - fragmentation) * (0.3 + 0.7 * progress);
        score -= 5.0 * fragmentation * (1.0 - fit_quality);
    } else {
        // Mild preference for filling already-open bins as the stream progresses.
        score -= 2.0 * progress * (item / cap);
    }

    // Smooth global coupling: bins far from the mean residual get a nudge
    // toward normalization (keeps residual distribution tight).
    let dev = (post - mean_residual) / cap;
    score += 3.0 * dev * dev * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify dead space into capacity fractions.
    let frac = (post_residual as f64) / (bin_capacity as f64);
    let class = (frac * 4.0).floor() as u32; // 0..3 harmonic classes

    // Reward tight fits: post_residual near 0 is ideal.
    if post_residual == 0 {
        score -= 1000.0; // perfect closure
    } else if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 20.0;
    }

    // Penalize residuals in "dead zone" classes where few future items fit.
    // Items 1..100: residual < 10 is nearly dead; residual in (50,60] holds fewer item classes.
    if post_residual < 10 {
        score -= 30.0; // dead space but bin nearly full -> fine
    } else if post_residual <= 20 {
        score += 5.0 * class as f64;
    }

    // Modulo arithmetic on post_residual: multiples of 10 are "harmonic" slots
    // (common item sizes are multiples of 10 in many streams).
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }
    // Odd residuals are less reusable.
    if post_residual % 2 == 1 {
        score += 3.0;
    }

    // Lookahead coupling: does next item fit in post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Great: chain placement possible; reward proportionally.
            score -= 12.0 + 0.15 * (next_item_size as f64);
        } else {
            // Next item won't fit: this bin becomes dead for the lookahead.
            score += 0.25 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin should lose unless current fits are bad.
    if bin_residual == bin_capacity {
        // Fresh bin: neutral-ish baseline; penalize slightly so tight fits win,
        // but reward when no good open bin exists.
        score += 15.0;
        if fitting_bins_count <= 1 {
            score -= 20.0; // few alternatives -> opening new bin is fine
        }
        if mean_residual < (item_size as f64) * 0.5 {
            score -= 15.0; // open bins are too empty-mean to be useful
        }
    } else {
        // Prefer bins whose residual is close to item size (best fit signal).
        let waste = (bin_residual - item_size) as f64;
        score += 0.1 * waste;
    }

    // Stream progression: late in the stream, consolidate aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - frac);

    // Many open bins: encourage filling existing ones rather than spreading.
    score += 0.5 * (open_bins_count as f64).ln().max(0.0) * frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small to hold the next (or any) item are wasted.
    let progress = (step_index as f64) / (total_items.max(1) as f64);
    let dead_threshold = 9.0; // items are >=1 but small gaps rarely reusable
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 6.0; // harsh penalty on unusable slivers
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Reward residuals that can still hold the next item (keeps bins usable).
    if next_item_size > 0 {
        if (post_residual as u64) >= (next_item_size as u64) {
            score -= 10.0;
        } else {
            score += 8.0; // this bin becomes dead after this placement
        }
        // Bonus if the next item exactly fills the post residual.
        if next_item_size == post_residual {
            score -= 45.0;
        }
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0 + 20.0 * progress;
    }

    // New-bin candidate handling: only attractive when open bins are congested or mean residual is tiny.
    if bin_residual == bin_capacity {
        let congestion = (open_bins_count as f64) * 0.8;
        let mean_pressure = 30.0 - mean_residual.min(30.0);
        score += 15.0 + congestion + mean_pressure - 30.0 * progress;
    } else {
        // Open-bin pressure: with many open bins, prefer consolidating into existing ones.
        score -= (open_bins_count as f64).min(10.0) * 1.5;
    }

    // Slight preference for bins below mean residual (balancing, keeps large gaps distributed).
    if bin_residual != bin_capacity {
        score += (bin_residual as f64 - mean_residual) * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: penalize large post_residual relative to capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * tightness * tightness;

    // 2-step lookahead: reward exact match of next_item_size into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect two-item fill
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot use this residual: dead space risk
            let waste = (next_item_size - post_residual) as f64;
            score += 8.0 * (waste / bin_capacity as f64);
        }
    }

    // Relative residual coupling with mean residual.
    let res = post_residual as f64;
    let diff = res - mean_residual;
    score += 0.35 * diff;

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make it moderately attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 15.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score += 10.0;
        }
    }

    // Late in stream: consolidate, discourage opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 20.0 * progress;
    } else {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic penalty on wasted space.
    let waste_frac = post_residual as f64 / cap;
    score += 40.0 * waste_frac * waste_frac;

    // Lookahead: strongly reward bins where the next item fits the post residual.
    if next_item_size > 0 && (next_item_size as f64) <= post_residual as f64 {
        score -= 25.0;
        // Extra reward if next item fills the bin almost completely afterwards.
        let post2 = post_residual as f64 - next_item_size as f64;
        score -= 15.0 * (1.0 - post2 / cap);
    } else if next_item_size > 0 {
        // Penalize leaving a gap the next item cannot use (dead space risk).
        score += 8.0 * (next_item_size as f64 / cap);
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: penalize opening a new bin, unless the item
    // is large and no open bin fits well (high mean residual, many fittings).
    if bin_residual == bin_capacity {
        let mut penalty = 20.0;
        // If many bins fit, definitely use an existing one.
        penalty += 5.0 * fitting_bins_count as f64;
        // Late in the stream, avoid bin proliferation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        penalty += 10.0 * progress;
        // If item is large relative to capacity, a fresh bin may be fine.
        penalty -= 0.15 * item_size as f64;
        // If existing bins are crowded, new bin more attractive.
        penalty -= 0.1 * mean_residual;
        score += penalty.max(-15.0);
    }

    // Prefer filling bins that are already low (consolidation).
    score -= 0.05 * (cap - bin_residual as f64);

    // Mild penalty on open bin count to discourage fragmentation.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    // Base: wasted space, weighted more strongly as stream progresses
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Smooth non-linear coupling: small post-residuals are valuable dead-space sinks
    score -= 25.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 - norm_item);

    // Penalize residuals that are awkwardly mid-sized (poor fit for typical items)
    let awkward = 4.0 * norm_pr * (1.0 - norm_pr);
    score += 15.0 * awkward * progress;

    // Reward tight fits more aggressively late in the stream
    score -= 10.0 * (1.0 - norm_pr) * progress;

    // Lookahead: bonus if next item fits the post-residual (smooth kernel)
    if next_item_size > 0 {
        let gap = (pr - norm_next * cap).abs() / cap;
        score -= 12.0 * (-8.0 * gap * gap).exp();
        // Slight penalty if post-residual can't hold next item
        if pr < next_item_size as f64 {
            score += 6.0 * progress;
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 - 0.5 * progress);
    }

    // Encourage consolidation when many bins are open
    let open_norm = open_bins_count as f64 / (open_bins_count as f64 + 10.0);
    score -= 8.0 * open_norm * (1.0 - norm_pr);

    // New-bin candidate: make empty bins mildly attractive only for large items
    if bin_residual == bin_capacity {
        score = cap * (1.0 - norm_item) * (0.9 - 0.3 * progress) + 20.0 * (1.0 - norm_item);
    }

    // Mild pull toward mean residual state (smooth regularization)
    score += 0.05 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals divisible by 10 are
    // "friendly" slots for typical item sizes; odd/prime-ish residuals are dead space.
    let pr = post_residual;
    let class_penalty: f64 = if pr == 0 {
        -60.0 // perfect fit
    } else if pr % 10 == 0 {
        -25.0
    } else if pr % 5 == 0 {
        -10.0
    } else if pr < 10 {
        30.0 // tiny unusable sliver
    } else {
        5.0
    };
    score += class_penalty;

    // Fraction-of-capacity thresholds on post_residual
    let frac = pr as f64 / cap;
    if frac < 0.05 { score -= 20.0; }
    else if frac > 0.5 { score -= 8.0; } // roomy bin, keep flexible
    else if frac < 0.2 { score += 10.0; } // awkward mid-small residual

    // Lookahead coupling: does post_residual exactly or closely fit next item?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 80.0; // chains perfectly
        } else if next_item_size <= pr {
            let gap = pr - next_item_size;
            score -= 30.0 * (1.0 - gap as f64 / cap);
            if gap % 10 == 0 { score -= 10.0; }
        } else {
            score += 15.0; // next item cannot use this residual
        }
    } else {
        // last item: minimize waste directly
        score += 20.0 * frac;
    }

    // Last-chance bin: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        score += 4.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate handling: opening a bin is a fallback; prefer reuse
    // unless current bin would waste a lot and next item is small.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 45.0;
        if next_item_size > 0 && next_item_size >= bin_residual as u32 - item_size {
            score -= 30.0; // fresh bin serves the lookahead well
        }
        if post_residual as f64 > 0.6 * cap {
            score -= 10.0;
        }
    }

    // Stream progression: late in the stream, tighten packing (avoid leftovers)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 12.0 * progress * (post_residual as f64 / cap);

    // Mean-residual coupling: if this bin is far from the mean residual,
    // mildly normalize; keeps residual diversity low for future fits.
    score += 0.15 * (post_residual as f64 - mean_residual).abs();

    // Many open bins: discourage spreading, reward tight fits
    if open_bins_count > 8 {
        score += 0.5 * open_bins_count as f64 * (post_residual as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        // Gap too small for any item (min size 1 => only 0 is truly dead, but
        // tiny gaps are near-dead): penalize disproportionately.
        if post_residual < 10 {
            score += (10 - post_residual) as f64 * 12.0;
        }
        // Gap unusable by the lookahead item: penalize the wasted slack.
        if next_item_size > 0 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 4.0;
        }
    } else {
        // Perfect fill: strong reward.
        score -= 30.0;
    }

    // Tight fit reward: small post_residual relative to item size is good.
    score -= (item_size as f64) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bins pressure: when many bins are open, discourage opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as open bins grow and stream progresses.
        score += 15.0 + open_bins_count as f64 * 3.0 + progress * 20.0;
        // But if nothing fits elsewhere, new bin is fine (handled by comparison).
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    } else {
        // Existing bin: mild reward to keep open-bin count pressure effective.
        score -= open_bins_count as f64 * 0.5;
        // Favor bins with residual below mean (consolidating fuller bins).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact/near-exact matches with the next item.
    if next_item_size > 0 {
        let slack = post_residual as f64 - next_item_size as f64;
        if slack == 0.0 {
            // Perfect two-item pairing: strongly favor this bin.
            score -= 60.0;
        } else if slack > 0.0 && slack <= 20.0 {
            // Next item likely still fits after this placement.
            score -= 20.0 * (1.0 - slack / 20.0);
        } else if slack < 0.0 {
            // Next item would not fit here; penalize proportionally to the shortfall.
            score += (-slack).min(50.0) * 0.5;
        }
    }

    // Compare post_residual against the mean residual of open bins.
    let mr = mean_residual.max(1.0);
    let rel = post_residual as f64 / mr;
    if rel < 0.5 {
        // Leaves much less residual than average: tight, efficient fit.
        score -= 10.0 * (0.5 - rel);
    } else if rel > 1.5 {
        // Leaves much more residual than average: wasteful placement.
        score += 8.0 * (rel - 1.5).min(2.0);
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize new-bin opening unless the fit into existing bins is poor.
    if bin_residual == bin_capacity {
        let tightness = post_residual as f64 / bin_capacity as f64;
        // New bin is attractive only if the item is large (small post_residual).
        score += 25.0 * (1.0 - tightness) + 10.0;
        if next_item_size > 0 && post_residual as f64 >= next_item_size as f64 {
            score -= 12.0; // fresh bin can also host the next item
        }
    }

    // Late in the stream, prefer closing bins tightly (fewer wasted residuals).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 3.0 * (post_residual as f64 / 100.0);

    // Slight penalty scaled by number of open bins to encourage consolidation.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item nearly fills the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize dead space: residuals too small for the smallest plausible item (<=10).
    if post_residual < 10 {
        score += 12.0; // perfect fill, great
        if post_residual == 0 { score -= 10.0; }
    } else if post_residual < 20 {
        score += 6.0; // risky sliver
    }

    // Lookahead: reward bins whose post-residual can host the next item exactly well.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let next_fit = next_item_size as f64 / post_residual as f64;
            score -= 8.0 * next_fit;
        } else {
            // next item won't fit here; slight penalty if we waste large residual anyway
            score += 2.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0 + 6.0 * fit_ratio;
    }

    // New-bin candidate handling: empty bin. Prefer it only when no good fit exists
    // or when open bins are already crowded.
    if bin_residual == bin_capacity {
        let crowding = mean_residual / bin_capacity as f64;
        let pressure = (open_bins_count as f64).ln().max(1.0);
        // Cost of a fresh bin decreases as stream progresses (sunk bins less recoverable)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 22.0 - 14.0 * crowding - 4.0 * progress + 2.0 * pressure;
        // If next item is large, a fresh bin gives flexibility
        if next_item_size >= 50 { score -= 5.0; }
    } else {
        // Mild preference for filling bins that deviate above mean residual
        // (balance residuals, keep small residual bins for small items).
        let dev = bin_residual as f64 - mean_residual;
        score += 0.05 * dev;
    }

    // Late-stream consolidation: as stream ends, push toward closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * progress * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    let item_norm = item_size as f64 / cap;

    // Base: post residual (lower is better fit), non-linearly warped.
    let base = pr * (1.0 + 0.9 * pr_norm * pr_norm);

    // Smooth coupling: residual waste penalty grows with stream progress.
    let progress_coupling = 12.0 * pr_norm * pr_norm * (0.3 + progress);

    // Tight-fit reward: subtract when post_residual is small, amplified late in stream.
    let tightness = -8.0 * (1.0 - pr_norm) * (1.0 - pr_norm) * (0.5 + 0.5 * progress);

    // Penalize bins whose residual deviates badly from mean (fragmentation spreading).
    let mean_dev = (pr - mean_residual) / cap;
    let dev_penalty = 3.0 * mean_dev * mean_dev;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    let last_chance = if fitting_bins_count == 1 { -15.0 } else { 0.0 };

    // Lookahead: reward if next item fits in post residual (smooth logistic-like).
    let lookahead = if next_item_size > 0 {
        let fits = (next_item_size as f64 <= pr) as i32 as f64;
        let slack = (pr - next_item_size as f64) / cap;
        -6.0 * fits * (1.0 - slack * slack).max(0.0)
    } else { 0.0 };

    // Mild pressure to reuse open bins when many are open (smooth in open_bins_count).
    let open_pressure = -0.15 * (open_bins_count as f64).ln().max(0.0) * (1.0 - item_norm);

    // New-bin candidate: make it less attractive unless residual is near full capacity
    // and item is large (smooth quadratic gate instead of piecewise rule).
    let is_new = (bin_residual == bin_capacity) as i32 as f64;
    let new_bin_gate = is_new * (4.0 + 18.0 * (1.0 - item_norm) * (1.0 - item_norm) + 10.0 * (1.0 - progress));

    base + progress_coupling + tightness + dev_penalty + last_chance + lookahead + open_pressure + new_bin_gate
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "reusable"
    // residue classes (multiples of 10, or large enough halves) are more valuable.
    let pr = post_residual;
    let class = pr / 10; // integer division threshold class
    let residue = pr % 10;

    // Reward residuals that sit on nice harmonic boundaries (residue 0).
    if residue == 0 {
        score -= 6.0;
    } else {
        score += residue as f64 * 0.35; // penalize off-class dead space
    }

    // Non-linear coupling: post_residual vs next_item_size compatibility.
    if next_item_size > 0 {
        if next_item_size <= pr {
            // next item fits exactly or with perfect class match
            if pr % next_item_size == 0 {
                score -= 10.0;
            } else {
                score -= 4.0;
            }
            // harmonic fraction: next item consumes a clean fraction of residual
            let frac = next_item_size as f64 / pr as f64;
            if (frac * 2.0).round() / 2.0 == frac {
                score -= 2.0;
            }
        } else {
            // next item cannot use this residual: penalize proportionally
            score += (next_item_size - pr) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening fresh bins unless current placement
    // would create terrible dead space or we are early in the stream.
    if bin_residual == bin_capacity {
        score += 25.0;
        if pr >= 60 {
            score -= 10.0; // big item into fresh bin is fine
        }
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (1.0 - progress) * 5.0;
    }

    // Prefer filling bins below the mean residual (tighter bins first).
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.2;
    score -= (bin_residual as f64 - mean_residual).max(0.0) * 0.1;

    // Slight pressure to consolidate when many bins are open.
    score += open_bins_count as f64 * 0.05;

    // Class-based smooth shaping of post_residual.
    score -= class as f64 * 0.4;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64);
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0 * (20.0 - post_residual as f64) / 10.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last chance: if this is the only bin that fits, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin when open bins could fit,
    // with pressure scaling by number of open bins; relax slightly late in stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 + 3.0 * open_bins_count as f64 * (1.0 - 0.3 * progress);
        // If the next item is small, a fresh bin with large residual is more useful.
        if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
            score -= 15.0;
        }
    }

    // Prefer bins whose residual is close to the mean (avoid fragmenting outliers),
    // but only mildly so tight fits still dominate.
    score += 0.15 * ((post_residual as f64) - mean_residual).abs();

    // Slight preference for filling bins with less residual (best-fit flavor).
    score += 0.1 * bin_residual as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly (small post_residual).
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap;
    score -= 40.0 * (1.0 - frac).powi(3);

    // Aggressive 2-step lookahead: bonus if next item exactly fills post_residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64 - nxt).abs() < 1.0 {
            score -= 60.0; // perfect chain fit
        } else if nxt <= post_residual as f64 {
            // next item fits into the residual: reward tighter leftover after chain
            let chain_left = post_residual as f64 - nxt;
            score -= 30.0 * (1.0 - chain_left / cap);
        } else {
            // next item cannot use this residual: penalize proportional dead space
            score += 0.3 * post_residual as f64;
        }
    }

    // Compare residual against mean residual across open bins.
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Prefer filling bins with small residuals; discourage wasting a nearly-empty bin.
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when no open bin fits well.
        score += 15.0 + mean_residual * 0.1;
    }

    // Early in stream, be slightly more willing to open bins for good structure.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 10.0 * (1.0 - progress) * frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward small post_residual non-linearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio) * (1.0 - fit_ratio) * 30.0;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Exact fit is gold.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: if the next item fits in the post residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0 + next_item_size as f64 * 0.2;
    } else if next_item_size > post_residual {
        score += 6.0;
    }

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    // or the fit here is terrible.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowded = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
        let poor_fit = (item_size as f64 / bin_capacity as f64) < 0.5;
        let mut penalty = 20.0 + crowded * 30.0 * (1.0 - progress * 0.5);
        if poor_fit {
            penalty -= 15.0;
        }
        if fitting_bins_count == 0 {
            penalty = -50.0; // must open a new bin
        }
        score += penalty;
    } else {
        // Mild preference to fill bins below the mean residual (balance avoidance).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        } else {
            score += 2.0;
        }
    }

    // Late in the stream, consolidate aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0 * (1.0 - fit_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Smooth non-linear base: quadratic coupling of post residual with stream progress.
    // Late in the stream, waste is penalized more heavily (dead space matters more
    // when fewer items remain to fill it).
    let mut score = x * (1.0 + 2.0 * progress) + 1.5 * x * x * (0.5 + progress);

    // Reward tight fits: subtract a smooth bump centered at small post_residual.
    let tightness = (1.0 - x).powi(3);
    score -= 4.0 * tightness * (1.0 - progress * 0.5);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 6.0 + 4.0 * progress;
    }

    // Penalize bins far below mean residual (fragmentation of well-filled bins)
    // with a smooth cubic interaction with progress.
    let dev = (mean_residual - pr) / cap;
    score += 1.2 * dev * dev * dev * (1.0 + progress);

    // Lookahead: if the next item exactly fits the post residual, reward this bin.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let gap = (pr - nx) / cap;
            score -= 3.0 * (1.0 - gap) * (1.0 - progress * 0.3);
        } else {
            // Next item cannot fit here: mild penalty, smooth in overshoot.
            score += 0.8 * ((nx - pr) / cap) * (1.0 + progress);
        }
    }

    // Mild penalty for spreading across too many open bins late in the stream.
    score += 0.05 * open_bins_count as f64 * progress;

    // New-bin candidate (empty bin): base score near capacity minus a smooth
    // exploration discount that decays as the stream progresses.
    if bin_residual == bin_capacity {
        score = cap * (0.9 + 0.1 * progress) - 3.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: classify post_residual into
    // capacity-fraction buckets (dead-space harmonics).
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let harmonic = (post / cap * 8.0).floor(); // 8 classes of capacity fractions

    // Reward placements landing exactly on "useful" harmonic boundaries:
    // post_residual divisible by common item sizes (10, 20, 25, 50) leaves
    // re-usable chunks.
    if post_residual > 0 {
        if post_residual % 50 == 0 { score -= 12.0; }
        else if post_residual % 25 == 0 { score -= 8.0; }
        else if post_residual % 20 == 0 { score -= 6.0; }
        else if post_residual % 10 == 0 { score -= 4.0; }
        else {
            // Irregular leftover: penalize proportionally to how non-harmonic it is
            let off = (post_residual % 10) as f64;
            score += off * 0.8;
        }
    } else {
        // Perfect fill is the best outcome
        score -= 30.0;
    }

    // Dead-space penalty: tiny unusable leftovers (below smallest item class)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead coupling: reward if next item fits the post residual
    // (integer-division threshold on next_item_size vs post_residual).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0;
            // extra bonus when next item lands on a harmonic class too
            if post_residual % next_item_size.max(1) == 0 {
                score -= 6.0;
            }
        } else {
            // next item won't fit here anyway; slightly penalize wasting space
            score += (next_item_size - post_residual) as f64 * 0.05;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: keep empty bins competitive only when
    // current bin would leave a bad harmonic class.
    if bin_residual == bin_capacity {
        // neutral baseline slightly above a good-fit existing bin
        score = cap * 0.55 + harmonic * 2.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 8.0; // new bin preserves room for large follow-ups
        }
        if open_bins_count == 0 {
            score -= 100.0; // must open first bin
        }
    }

    // Stream progression: tighten packing early, allow slack later
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (mean_residual - post) * (0.3 - 0.2 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for the smallest
    // plausible item are effectively wasted capacity.
    let dead_threshold = 10u32.min(bin_residual);
    if post_residual > 0 && post_residual < dead_threshold {
        score += 40.0 + (dead_threshold - post_residual) as f64 * 6.0;
    }

    // Perfect / near-perfect fits are highly desirable.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Reward leaving a gap that exactly accommodates the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 45.0;
    }
    if next_item_size > 0 && post_residual > next_item_size && post_residual < next_item_size + 10 {
        score += 10.0; // gap slightly above next item: likely to become dead space
    }

    // Last-chance bonus: only one open bin fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Pressure from number of open bins: discourage spreading across many bins
    // unless the fit is genuinely good.
    let open_pressure = (open_bins_count as f64).ln().max(0.0) * 3.0;
    score += open_pressure * (post_residual as f64 / bin_capacity as f64);

    // Prefer tight fits relative to current mean residual.
    score += 0.3 * (post_residual as f64 - mean_residual).max(0.0);

    // Early in the stream, keep bins flexible (avoid tiny residuals early).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.3 && post_residual > 0 && post_residual < 20 {
        score += 15.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fit
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if post_residual == 0 {
        score -= 1000.0; // perfect fill
    } else if post_residual < 10 {
        score -= 500.0; // near-perfect, dead space unusable anyway
    } else if fit_ratio > 0.85 {
        score -= 200.0 * fit_ratio;
    }

    // 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual as i64 >= next_item_size as i64 {
            // next item fits exactly-ish after this placement
            score -= 300.0 / (1.0 + diff / 20.0);
            if diff == 0.0 {
                score -= 400.0; // perfect 2-chain
            }
        } else {
            // next item would NOT fit: penalize proportionally to wasted space
            score += 50.0 + diff * 0.5;
        }
        // very small post_residual can't host anything next: mild penalty unless near-zero
        if post_residual < 10 && post_residual > 0 {
            score -= 100.0; // dead space < min item size is acceptable
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 250.0;
    }

    // Prefer bins tighter than the mean residual (compact packing)
    score += (bin_residual as f64 - mean_residual) * 0.8;

    // Slight preference for already-open bins over opening new ones early in stream
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize more when many bins open or early stream
        score += 150.0 + 100.0 * (1.0 - progress) + 10.0 * open_bins_count as f64;
    } else {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is always excellent.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space penalty: residuals too small for the smallest item (1) are pure waste,
    // but residuals < 10 can never be reused by any item in typical streams.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Chain bonus scaled by how snugly the next item fits.
            let chain_tight = (post_residual - next_item_size) as f64;
            score -= 25.0 + 20.0 * (1.0 - chain_tight / bin_capacity as f64);
        } else {
            // Post-residual unusable for the upcoming item: mild penalty.
            score += 8.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Crowding effect: many open bins -> prefer consolidating into existing ones.
    let crowding = (open_bins_count as f64) / ((total_items.max(1) as f64).sqrt() + 1.0);
    if bin_residual != bin_capacity {
        score -= 6.0 * crowding.min(3.0);
    } else {
        // New-bin candidate: penalize when many bins are already open and mean
        // residual is large enough to absorb the item.
        score += 10.0 + 8.0 * crowding.min(4.0);
        if (mean_residual >= item_size as f64) && bin_residual == bin_capacity {
            score += 30.0;
        }
    }

    // Time horizon: late in the stream, avoid opening new bins (waste at the tail);
    // early on, allow exploration of new bins for large items.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 40.0 * progress * progress;
        // Large items fit best in a fresh bin early on.
        if item_size > bin_capacity / 2 && progress < 0.5 {
            score -= 15.0;
        }
    } else {
        score -= 12.0 * progress;
    }

    // Tightness reward: prefer bins where the item fills a large fraction of residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill_ratio * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    let mut score = pr;

    // Smooth non-linear coupling: quadratic/cubic terms of x modulated by progress.
    // Favor very small post residuals (tight fits) increasingly as stream progresses.
    score -= progress * (x * x * cap) * 0.9;
    score -= (1.0 - progress) * (x * x * x * cap) * 0.4;

    // Penalize dead space that cannot fit the next item (smooth interaction).
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let gap = x - nx;
        if gap > 0.0 {
            score += gap * gap * cap * (0.5 + 0.5 * progress);
        } else {
            // next item fits comfortably: slight reward
            score -= (-gap) * cap * 0.15;
        }
    }

    // Last-chance bonus: only one fitting bin -> strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    } else {
        // mild dispersion penalty when many bins fit
        score += (fitting_bins_count as f64).ln() * 2.0;
    }

    // Nudge toward bins below mean residual (consolidate fragmented space).
    score += (mean_residual - pr) * 0.3;

    // New-bin candidate: penalize opening a new bin unless residual is large.
    if bin_residual == bin_capacity {
        score += 8.0 + 30.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo arithmetic on capacity fractions
    let cap = bin_capacity as f64;
    let pr = post_residual;
    let prf = pr as f64;

    // Perfect-fit reward
    if pr == 0 {
        score -= 1000.0;
    }

    // Dead-space penalty: residual too small for any plausible item (<=10)
    if pr > 0 && pr < 10 {
        score += 40.0;
    }

    // Harmonic classes: residual divisible into nice chunks (capacity fractions)
    // Class 0: residual is a multiple of 25 (harmonic quarter classes) -> very reusable
    if pr % 25 == 0 && pr > 0 {
        score -= 15.0;
    }
    // Class 1: residual is a multiple of 10 -> decent
    if pr % 10 == 0 && pr > 0 {
        score -= 8.0;
    }
    // Class 2: residual in awkward band (11..19) -> likely dead space
    if pr >= 11 && pr < 20 {
        score += 10.0;
    }

    // Integer-division threshold coupling with next item
    if next_item_size > 0 {
        if next_item_size <= pr {
            // next item fits here: reward proportional to snugness
            let snug = (pr - next_item_size) as f64;
            score -= 20.0 - snug * 0.3;
            if pr == next_item_size {
                score -= 50.0; // exact two-item fill
            }
        } else {
            // next item won't fit: penalize leaving moderately large but unusable-for-next residual
            score += 6.0;
            if pr > next_item_size * 2 {
                score += 4.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Many open bins: encourage consolidation (tighter residual = better)
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += mean_residual * 0.05 * (open_bins_count as f64 / 10.0).min(1.0);
    score -= (bin_residual as f64 / cap) * 5.0 * (1.0 - progress);

    // New-bin candidate: penalize slightly so it wins only when open bins are bad
    if bin_residual == bin_capacity {
        score += 12.0 + mean_residual * 0.3;
        if fitting_bins_count == 0 {
            score -= 100.0; // no open bin fits: must open
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are tiny (unusable for
    // typical items) are heavily penalized so we prefer filling bins tight.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 + (10 - post_residual) as f64 * 2.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 6.0;
    }

    // Reward exact / near-exact fits.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead: if the next item can also fit in the leftover space,
    // this bin is extra valuable.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 4.0 + next_item_size as f64 * 0.1;
    }

    // Open-bins pressure: mildly penalize bins whose leftover contributes
    // to fragmentation relative to the mean residual of open bins.
    let frag = (post_residual as f64 - mean_residual).abs();
    score += 0.05 * open_bins_count as f64 * (frag / bin_capacity as f64);

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: make opening a new bin slightly less attractive
    // unless its post_residual is genuinely small relative to capacity.
    if bin_residual == bin_capacity {
        score += 2.0 + 0.05 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual with next item size.
    if next_item_size > 0 {
        let look = next_item_size as f64;
        let diff = (post_residual as f64 - look).abs();
        if post_residual as u32 == next_item_size {
            score -= 60.0; // perfect 2-step packing
        } else if post_residual as u32 >= next_item_size {
            score -= (20.0 * (1.0 - diff / bin_capacity as f64)).max(0.0);
        } else {
            // dead space the next item cannot use
            score += 15.0 + diff * 0.3;
        }
        // if next item fits nowhere else and this bin can chain it, favor it
        if post_residual as u32 >= next_item_size && fitting_bins_count == 1 {
            score -= 10.0;
        }
    }

    // Penalize tiny unusable residuals relative to the item-size floor
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Last-chance bonus: only bin that fits the item
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Relative to mean residual: prefer tighter-than-average bins
    score -= (mean_residual - post_residual as f64) * 0.2;

    // Mild preference for reusing bins over opening new ones as stream progresses
    if bin_residual == bin_capacity {
        score += 8.0 + 12.0 * (step_index as f64 / total_items.max(1) as f64);
    }

    // Prefer filling more of the bin now
    score -= (item_size as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but punish leaving
    // tiny dead space (< 10) that no future item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Perfect fill is excellent.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead: reward bins whose leftover can host the next item,
    // punish leftovers that are just barely too small for it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 8.0;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Penalize spreading across many open bins when residuals are large;
    // encourage consolidating into already-open bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let consolidation_pressure = open_bins_count as f64 * (mean_residual / bin_capacity as f64);
    score += 0.05 * consolidation_pressure * (1.0 - progress);

    // New-bin candidate (empty bin): make it attractive only when the item
    // fits poorly in existing bins (large post_residual) or few bins fit.
    if bin_residual == bin_capacity {
        let fit_quality = post_residual as f64 / bin_capacity as f64;
        score -= 15.0 * fit_quality;
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
        // Late in the stream, prefer closing out existing bins.
        score += 10.0 * progress;
    }

    // Mild preference for filling bins with larger residual capacity
    // (keep small residuals available for small items).
    score += 0.1 * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_post = pr / cap;
    let fit = fitting_bins_count as f64;

    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_post * norm_post * (1.0 - progress) + norm_post * progress;
    score += 8.0 * poly;

    // Penalize tiny dead space that is hard to reuse (smooth ramp near zero)
    let dead = (1.0 - norm_post).powi(3);
    score += 12.0 * dead * (1.0 - progress);

    // Reward tight fits more strongly late in the stream
    score -= 15.0 * progress * (1.0 - norm_post) * (1.0 - norm_post);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else {
        score += 2.0 * (fit - 1.0);
    }

    // Lookahead: reward leaving space for the next item
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr >= ns {
            score -= 10.0 * (1.0 - ((pr - ns) / cap).abs());
        } else {
            score += 6.0 * (ns - pr) / cap;
        }
    }

    // Mild penalty for spreading across many open bins
    score += 0.5 * (open_bins_count as f64).ln();

    // Deviation from mean residual: prefer bins near the mean to keep balance
    score += 0.3 * (pr - mean_residual).abs() / cap;

    // New-bin candidate: penalize slightly so we prefer good existing fits
    if bin_residual == bin_capacity {
        score += 6.0 - 4.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space is worse in some residue classes.
    // Residuals in (0,10] are nearly unusable (min item size 10) -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Class residual by capacity fractions (harmonic bins of C=100).
    let frac = post_residual as f64 / bin_capacity as f64;
    let class = (frac * 10.0).floor() as i64; // 0..9 harmonic class
    // Reward low classes (tight fits), mildly penalize the awkward middle classes 3-5.
    match class {
        0 => score -= 25.0,
        1 => score -= 12.0,
        2 => score -= 5.0,
        3 | 4 => score += 8.0,
        5 => score += 4.0,
        _ => {}
    }

    // Integer-division threshold: residual divisible into halves/quarters is reusable.
    if post_residual % 2 == 0 { score -= 2.0; }
    if post_residual % 5 == 0 { score -= 3.0; }
    if post_residual % 10 == 0 && post_residual > 0 { score -= 6.0; }

    // Lookahead coupling: reward if next item fits into post_residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            // Perfect chain fit is excellent.
            score -= 20.0 + (slack as f64).min(10.0);
        } else {
            // Next item won't chain here; penalize proportionally to overshoot class.
            let over = next_item_size - post_residual;
            score += (over as f64) * 0.5;
        }
        // Harmonic pairing: residual exactly complementary to next item size.
        if post_residual == next_item_size {
            score -= 15.0;
        }
    } else {
        // Last item: prefer tightest fit, ignore future.
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: keep fresh bins attractive only when nothing fits well.
    if bin_residual == bin_capacity {
        score += 55.0 + 0.1 * open_bins_count as f64;
        // But if stream is early, opening bins is cheap.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
    }

    // Prefer bins below mean residual (pack big residuals together, keep tight bins).
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Slight preference for fewer open bins when this placement keeps things tight.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space strongly (non-linear).
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    }

    // Reward tight fits.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * 8.0;

    // Penalty for opening a new bin when open bins could fit.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 25.0 + open_bins_count as f64 * 2.0;
        // If this bin is the last chance, strongly discourage new bin.
        if fitting_bins_count == 1 {
            score += 40.0;
        }
    } else {
        // Last-chance fitting bonus to avoid wasting this bin's uniqueness.
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
    }

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 6.0;
    } else if next_item_size > 0 && post_residual > 0 && (next_item_size as f64) > post_residual as f64 {
        score += (next_item_size as f64 - post_residual as f64) * 0.5;
    }

    // Open bins pressure: more open bins -> prefer consolidating into existing bins.
    score += open_bins_count as f64 * 1.5 * (1.0 - fill_ratio);

    // Slight progression awareness: later in stream, tighten packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect or near-perfect fits strongly (non-linear).
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 3 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 60.0;
    }

    // Aggressive 2-step lookahead: if the next item exactly matches the
    // post-residual, this placement sets up a perfect follow-up.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size < post_residual {
            let leftover2 = post_residual - next_item_size;
            // Reward chains that leave small secondary dead space.
            score -= (20.0 - leftover2.min(20) as f64) * 3.0;
        } else {
            // Next item won't fit here; penalize leaving a gap the next
            // item cannot use (dead space risk).
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 1.5;
        }
    }

    // Relative-to-mean residual coupling: prefer bins whose residual after
    // placement is far below the mean (tight packing of loose bins).
    score += (post_residual as f64 - mean_residual).max(-50.0) * 0.8;

    // Last-chance bonus: if this is the only bin that fits, using it avoids
    // opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: make a fresh bin attractive only when the
    // current item is large or open bins are already tight.
    if bin_residual == bin_capacity {
        let tight = mean_residual < item_size as f64;
        if tight || item_size > 60 {
            score -= 80.0;
        } else {
            // Discard fresh bins when good fits exist elsewhere.
            score += 150.0;
        }
        // Lookahead: opening a new bin is good if the next item is small
        // (it can top off the leftover of the current bin choice).
        if next_item_size > 0 && next_item_size <= 30 {
            score += 40.0;
        }
    }

    // Late in the stream, be more conservative: prefer filling existing bins
    // rather than leaving many partially-filled bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * post_residual as f64 * 0.5;

    // Mild penalty scaled by number of open bins to discourage bin sprawl.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post_residual) more aggressively as stream progresses.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (bin_capacity as f64 - post_residual as f64) * (0.5 + 1.5 * progress);

    // Penalize dead space: small post_residual that no plausible item can fill.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - progress);
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += 6.0;
        }
    }

    // Prefer bins below mean residual (consolidate waste into few bins).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 0.0 } else {
            (fitting_bins_count as f64).ln() * 15.0
        };
        score += 20.0 + desperation + 30.0 * progress;
        // Opening a new bin is good if next item is large and would fit fresh capacity.
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 10.0;
        }
    }

    // Mild penalty for spreading across many open bins.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let p2 = progress * progress;
    let p3 = p2 * progress;
    let coupling = norm_pr * (1.0 + 0.6 * progress + 0.8 * p2 + 0.5 * p3);

    let mut score = pr * (1.0 + 0.9 * progress) + 12.0 * coupling;

    // Penalize dead space more as stream progresses (less chance to reuse)
    let dead = if pr > 0.0 { norm_pr * norm_pr } else { 0.0 };
    score += 40.0 * dead * (0.3 + 0.7 * progress);

    // Reward near-perfect fits
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0 * (1.0 + progress);
    }

    // Last-chance bin: avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (1.0 + progress);
    }

    // Lookahead: small penalty if next item fits well in the residual left behind
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if n <= pr {
            let slack = (pr - n) / cap;
            score -= 10.0 * (1.0 - slack) * (1.0 - progress);
        } else {
            score += 6.0 * progress;
        }
    }

    // Mild pressure to prefer filling bins over opening new ones
    if bin_residual == bin_capacity {
        score += 8.0 + 20.0 * (1.0 - progress);
    }

    score += 0.05 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits (residual in {0}) heavily rewarded.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Dead-space penalty grows when post_residual is small but unusable
        // (smaller than the smallest plausible item). Harmonic classes:
        // residual mod 10 classes indicate how "reusable" the leftover is.
        let class = post_residual % 10;
        let div_class = post_residual / 10; // integer division threshold bucket

        // Small unusable leftovers are bad; mid leftovers (30..60) are reusable.
        if post_residual < 10 {
            score += 200.0;
        } else if post_residual <= 60 {
            score -= (div_class as f64) * 8.0;
        } else {
            score += (post_residual as f64 - 60.0) * 1.5;
        }

        // Penalize awkward classes (residuals like 1..9 mod 10 leave slivers).
        if class != 0 && post_residual < 20 {
            score += 30.0;
        }
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // this bin is extremely valuable (chain of perfect fits).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            let leftover2 = post_residual - next_item_size;
            if leftover2 == 0 {
                score -= 400.0;
            } else if leftover2 <= 10 {
                score -= 50.0;
            } else {
                score += (leftover2 as f64) * 0.3;
            }
        } else {
            // Next item cannot follow here: slight penalty, worse if residual tiny.
            if post_residual < next_item_size && post_residual < 20 {
                score += 40.0;
            }
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: an empty bin is a fallback; prefer it only when
    // no open bin offers a decent fit. Give it a mild baseline so tight fits win.
    if bin_residual == bin_capacity {
        score += 90.0;
        // Early in the stream, opening bins is cheaper.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - progress) * 40.0;
        // If many open bins are already fragmented, a fresh bin is more attractive.
        if (mean_residual / bin_capacity as f64) < 0.25 {
            score -= 30.0;
        }
    } else {
        // Prefer bins whose residual is close to item_size (tight packing).
        let tightness = (bin_residual - item_size) as f64;
        score += tightness * 0.1;

        // Slight preference for bins below mean residual (balancing fragmentation).
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        }
    }

    // Late-stream consolidation: fewer open bins preferred as stream ends.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64) * progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: any nonzero leftover below the smallest
    // conceivable item (1) is impossible, but tiny gaps (< 10) are nearly
    // unusable dead space; penalize them super-linearly.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    }
    // Perfect fit: reward strongly.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Penalize bins whose residual is already tight relative to the item
    // (wasting a nearly-full bin's remaining flexibility is fine, but
    // spreading items thin is not): reward using bins with low residual.
    let tightness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= tightness * 15.0;

    // Open-bin pressure: when many bins are open, discourage opening new
    // ones; the new-bin candidate (bin_residual == bin_capacity) gets this
    // penalty, making it lose unless every alternative creates dead space.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 30.0 + open_bins_count as f64 * 3.0 + progress * 20.0;
        // Early in the stream a fresh bin is cheaper.
        score -= (1.0 - progress) * 15.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: reward if the next item can also fit the post residual,
    // penalize if the leftover would be just barely too small for it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            score += 6.0;
        }
    }

    // Mild pull toward bins whose residual is below the mean residual
    // (compact bins first, keep large gaps available for big items).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact/near-exact fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score -= 200.0;
    }

    // 2-step lookahead: if the next item fits into the post-residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 100.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here: penalize proportional to leftover mismatch.
            let overshoot = (next_item_size - post_residual) as f64;
            score += 0.5 * overshoot;
        }
    }

    // Penalize large dead space relative to mean residual of open bins.
    score += 0.3 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Late in the stream, prefer compacting into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.2 * progress;

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 40.0;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post residual)
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += tightness * tightness * 40.0;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Lookahead: reward if next item can fit in the post residual
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            // chain fit quality
            score -= (next_item_size as f64 / (post_residual as f64)) * 8.0;
        } else {
            // penalize dead space the next item cannot use
            score += (post_residual as f64 - (next_item_size as f64 - 1.0).min(post_residual as f64)) * 0.3;
            score += 5.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the item fits poorly everywhere (large post residual here) or bins are scarce.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // base penalty for opening a new bin
        score += 55.0;
        // more attractive late in the stream? no — penalize more late to consolidate
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 10.0;
        // if many bins are open with large residuals, opening new bins is wasteful
        score += (open_bins_count as f64).sqrt() * 3.0;
        // but if the item would leave a big unusable remainder in an existing bin,
        // new bin becomes competitive
        if post_residual == 0 {
            score -= 60.0;
        }
    }

    // Prefer bins with below-average residual (consolidate emptier space usage)
    score -= (mean_residual - bin_residual as f64) * 0.2;

    // Mild penalty for very large leftovers that few items can fill
    if post_residual > 0 && post_residual < item_size {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, but weighted by stream progress
    let mut score = pr * (0.7 + 0.6 * progress);

    // Non-linear polynomial coupling of normalized post-residual with progress
    let poly = norm_pr * norm_pr * (1.0 - norm_pr) * (1.0 - norm_pr);
    score -= 40.0 * poly * (1.0 - progress);

    // Penalize large dead space late in the stream (quadratic in residual)
    score += 8.0 * norm_pr * norm_pr * progress;

    // Reward tight fits (small post residual) with smooth exponential term
    score -= 15.0 * (-(pr / cap) * 4.0).exp() * (0.5 + 0.5 * progress);

    // Last-chance bonus: only bin that fits
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Lookahead: if next item fits exactly in post residual, reward
    if next_item_size > 0 && next_item_size as f64 == pr {
        score -= 25.0;
    } else if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        score -= 10.0 * (1.0 - ((pr - next_item_size as f64) / cap).abs());
    }

    // Mild penalty for spreading across many open bins
    score += (open_bins_count as f64).ln() * 0.5;

    // Deviation from mean residual: prefer bins near the mean (balance)
    score += 0.3 * (pr - mean_residual).abs();

    // New-bin candidate: penalize slightly so it only wins when fits are terrible
    if bin_residual == bin_capacity {
        score += 6.0 + 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residuals divisible by common item sizes
    // (small modulo classes) are more reusable, so reward them.
    let pr = post_residual;
    if pr > 0 {
        let mut reuse_bonus = 0.0;
        for m in [5u32, 10, 20, 25, 50].iter() {
            if pr % m == 0 {
                reuse_bonus += 6.0;
            }
        }
        // exact fit is perfect
        if pr == 0 {
            reuse_bonus += 40.0;
        }
        score -= reuse_bonus;
    } else {
        score -= 50.0; // perfect fill
    }

    // Penalize dead space: post_residual smaller than the minimum plausible item
    // is wasted capacity.
    if pr > 0 && pr < 10 {
        score += 25.0;
    }

    // Integer-division threshold: how many "average items" still fit.
    let avg_item = 40.0f64;
    let fills = (pr as f64 / avg_item).floor();
    score -= fills * 4.0;

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 35.0;
        } else if next_item_size <= pr {
            score -= 8.0 + (pr - next_item_size) as f64 * 0.15;
        } else {
            score += 5.0; // next item won't fit here; bin will be closed anyway
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bins are only attractive when no open bin
    // fits well (large item relative to mean residual) or late in the stream
    // with many open bins (spread load).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let tight = (item_size as f64) > mean_residual * 0.85;
        if tight || fitting_bins_count == 0 {
            score -= 15.0;
        } else {
            score += 18.0 + open_bins_count as f64 * 0.5 - progress * 5.0;
        }
    }

    // Mild preference for tighter bins among equals.
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Hard reward for perfect fit
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Penalize small unusable dead space: gaps below the minimum item size (1..=10)
    // are almost certainly waste; gaps of 10-30 are risky.
    let gap = post_residual as f64;
    if gap > 0.0 && gap < 10.0 {
        score += 200.0; // dead space, unusable for any item
    } else if gap < 30.0 {
        score += 60.0 * (1.0 - gap / 30.0); // risky small gap
    }

    // Lookahead: reward if the next item fits exactly into the post residual,
    // penalize if the next item cannot fit (this bin becomes dead for the next step).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual < next_item_size {
            score += 80.0;
        } else {
            // next item fits: reward tight chain
            score -= (post_residual - next_item_size) as f64 * 0.5;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading to new bins;
    // with few open bins, opening a new bin is cheaper.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let bin_pressure = open_bins_count as f64 * (1.0 + progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: base score should be competitive only when
        // existing bins are fragmented (high mean residual) or item is large.
        score += bin_pressure * 0.3;
        score -= mean_residual * 0.4;
        score -= item_size as f64 * 0.2;
    } else {
        // Reward using existing bins more when many are open
        score -= bin_pressure * 0.15;
    }

    // Mild preference for filling bins that are already mostly full
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= fill_ratio * 25.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post_residual nonlinearly.
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 60.0;

    // Exact fit is highly desirable.
    if post_residual == 0 {
        score -= 100.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item well.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let post = post_residual as f64;
        if post >= next {
            // Next item can also fit here: reward closeness of match.
            score -= 25.0 * (1.0 - ((post - next) / bin_capacity as f64));
        } else {
            // Next item won't fit: penalize dead space relative to next item.
            score += 0.5 * (next - post).min(50.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Penalize bins with unusually large residuals (hoarding space).
    if (bin_residual as f64) > mean_residual * 1.5 {
        score += 8.0;
    }

    // Slight preference for reusing open bins over opening new ones early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize mildly, more so later in the stream.
        score += 5.0 + 15.0 * progress;
    } else {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize dead space: small post_residual is good, but a tiny residual
    // (< 10, unusable for typical items) is actually excellent — reward it.
    if post_residual < 10 {
        score -= 8.0;
    } else if post_residual > 50 {
        score += 4.0; // leaving large awkward gaps is wasteful
    }

    // Lookahead: reward if the next item fits exactly into post_residual,
    // penalize if next item cannot fit post_residual (dead space likely).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 15.0;
        } else if next_item_size > post_residual {
            score += 0.05 * (next_item_size - post_residual) as f64;
        } else {
            score -= 0.02 * (post_residual - next_item_size) as f64;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: make empty bins less attractive unless the
    // item is large or no good fit exists.
    if bin_residual == bin_capacity {
        score += 6.0;
        if item_size >= 70 {
            score -= 10.0; // large items are fine starting a fresh bin
        }
        if fitting_bins_count == 0 {
            score -= 20.0; // nothing else fits: new bin is correct
        }
    }

    // Global state: when many bins are open with high mean residual,
    // prefer consolidating into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.02 * mean_residual * (1.0 - progress);
    score -= 0.5 * open_bins_count as f64 * (1.0 - progress);

    // Mild time-horizon scaling: early on, be greedy about tight fits;
    // late, avoid opening bins at all costs.
    if progress > 0.8 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress in (0,1]
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Normalized post-residual
    let pr = post_residual as f64 / bin_capacity as f64;

    // Non-linear polynomial coupling of post_residual with progress:
    // late in the stream, tight fits (small post-residual) are rewarded more aggressively.
    let coupling = pr * pr * (1.0 - progress) + pr * pr * pr * progress;
    score += coupling * 30.0;

    // Reward tight fits generally (subtract for small post_residual)
    score -= (1.0 - pr) * (1.0 - pr) * 8.0;

    // Penalize dead space: post residual that is too small to hold anything useful
    // smooth sigmoid-like gate around residual = 10 (min item size)
    let dead = (10.0 - post_residual as f64).max(0.0);
    score += dead * dead * 0.5;

    // Last-chance bonus: strongly prefer using the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Lookahead: if next item fits exactly into post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        let fit_quality = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 6.0 * fit_quality * fit_quality;
    }
    // Penalize leaving a residual slightly smaller than next item (blocking)
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 4.0 * (1.0 - post_residual as f64 / next_item_size as f64);
    }

    // Prefer bins whose residual is close to the mean (balanced packing),
    // smoothly scaled by progress
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05 * (0.5 + progress);

    // Mild penalty for opening new bins when many bins already open
    if bin_residual == bin_capacity {
        let crowding = open_bins_count as f64 / (1.0 + mean_residual.max(1.0));
        score += 3.0 + crowding * 0.3 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual mod 10 buckets.
    // Residuals that are "harmonically aligned" with common item sizes (multiples of 10)
    // are more reusable; odd residues create dead space.
    let residue_class = post_residual % 10;
    score += (residue_class as f64) * 1.5;

    // Harmonic bonus: post_residual divisible by small item sizes (usable wedges)
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 8.0; }
        else if post_residual % 5 == 0 { score -= 3.0; }
        if post_residual < 10 { score += 12.0; } // nearly dead bin
    }

    // Perfect fit reward
    if post_residual == 0 { score -= 60.0; }

    // Tight fit: fraction of capacity consumed
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= fill_frac * 15.0;

    // Lookahead harmony: does next_item_size fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Harmonic pairing: next item exactly fills, or leaves aligned residue
            let pair_res = post_residual - next_item_size;
            score -= 10.0;
            if pair_res % 10 == 0 { score -= 6.0; }
        } else if next_item_size > bin_residual {
            // This bin cannot take the next item anyway; mild bonus for stacking here
            score -= 2.0;
        } else {
            score += 4.0; // next item would leave awkward remainder here
        }
    }

    // Last-chance bin: only one open bin fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: fresh empty bin
    if bin_residual == bin_capacity {
        // Penalize opening a new bin unless current item is large and would
        // otherwise create heavy fragmentation
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_bin_score = 30.0 + progress * 10.0;
        // Large items start fresh bins happily (classic First-Fit-Descending flavor)
        if item_size > bin_capacity / 2 { new_bin_score -= 35.0; }
        // If many bins are open and mean residual is high, prefer reusing
        if mean_residual > item_size as f64 * 1.5 { new_bin_score += 15.0; }
        // Next item pairs well with this item in a fresh bin
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity
            && next_item_size + item_size + 10 > bin_capacity {
            new_bin_score -= 20.0;
        }
        score += new_bin_score;
    }

    // Spread penalty: discourage scattering across many open bins
    score += (open_bins_count as f64).ln().max(0.0) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for likely
    // future items (minimum item size 1, but practically small gaps < ~15)
    // are hard-penalized as unusable dead space.
    if post_residual > 0 && post_residual < 15 {
        score += 60.0;
    }
    if post_residual >= 15 && post_residual < 30 {
        score += 15.0;
    }

    // Reward tight fits (low post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing bins
    // over opening new ones; with few open bins, allow spreading.
    let pressure = open_bins_count as f64 / 8.0;
    score += pressure * post_residual as f64 * 0.05;

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Mean residual coupling: if average residual is large, we have slack
    // elsewhere, so we can be pickier about tight fits here.
    score += (mean_residual - post_residual as f64).abs() * 0.1;

    // Lookahead: if the next item fits exactly in the post-residual, reward
    // this placement strongly (chain fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            // Next item cannot use the leftover: dead space penalty grows.
            score += (post_residual as f64) * 0.15;
        }
    }

    // Late in the stream, closing out bins cleanly matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 45.0;
        // But if open bins are crowded (high mean residual), a fresh bin is fine.
        score -= mean_residual * 0.3;
        // Late stream: opening new bins is cheaper than fragmenting.
        score -= progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- 2-step lookahead: exact match of post_residual with next item is gold ---
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        let diff = (pr - nxt).abs();
        if diff < 0.5 {
            score -= 60.0; // perfect chain: next item fills this bin exactly
        } else if pr >= nxt {
            // next item fits: reward proportionally to tightness of the chain
            score -= 25.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // next item will NOT fit here -> this residual risks becoming dead space
            score += 8.0 + 20.0 * (nxt - pr) / bin_capacity as f64;
        }
    } else {
        // last item of stream: minimize residual strictly
        score += 0.0;
    }

    // --- dead-space penalty: tiny residuals are hard to reuse ---
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // --- reward filling a bin almost completely ---
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill_ratio * fill_ratio;

    // --- relative-to-mean coupling: prefer bins whose post-residual stays near mean ---
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // --- last-chance bin: if this is the only fitting bin, strongly prefer using it ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // --- new-bin candidate handling: only attractive early in the stream or when
    //     no open bin gives a good fit ---
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // baseline cost of opening a bin; grows with stream progress (waste matters more later)
        score = 45.0 + 55.0 * progress;
        if next_item_size > 0 && (next_item_size as f64 / bin_capacity as f64) > 0.6 {
            score -= 10.0; // big next item makes a fresh bin useful
        }
    }

    // --- slight preference for bins with larger residual before placement (better fits) ---
    score -= 0.05 * bin_residual as f64;

    // --- tiny tie-break toward fewer open bins ---
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    } else {
        // Penalize dead space quadratically, scaled by fraction of capacity wasted.
        let waste_frac = post_residual as f64 / bin_capacity as f64;
        score += 25.0 * waste_frac * waste_frac * (bin_capacity as f64);
    }

    // Lookahead: if next item fits exactly in the post residual, strongly favor this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 5.0;
        } else {
            // Next item won't fit here after placement; penalize mildly unless it's a perfect fit now.
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Global pressure: many open bins -> prefer filling existing ones (penalize new bins).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as open bins grow and as stream progresses.
        score += 10.0 + 2.0 * open_bins_count as f64 + 20.0 * progress;
    } else {
        // Existing bin: reward slightly more when many bins are open.
        score -= (open_bins_count as f64).min(10.0) * 0.5;
    }

    // Mean residual coupling: prefer bins whose residual deviates favorably from the mean
    // (below mean residual = tighter bin = use it before it becomes dead space).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Early in stream: be slightly more exploratory (favor new bins a bit less penalized).
    score -= 8.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let pr = post_residual as f64;
    let prn = pr / bin_capacity as f64;
    let p1 = progress;
    let p2 = progress * progress;
    let coupling = prn * prn * (0.5 + p1) - prn * (0.3 + 0.8 * p2);
    score += 8.0 * coupling;

    // Tight fits are rewarded more strongly later in the stream
    let tightness = 1.0 - prn;
    score -= (1.0 + 2.0 * p1) * tightness * tightness * 6.0;

    // Penalize dead space: residuals too small for likely future items
    let min_item = 1.0;
    if pr < min_item {
        score += 50.0;
    }

    // Last-chance bonus: only bin that fits, avoid opening new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 5.0 + 10.0 * (1.0 - p1);
    }

    // Lookahead: if next item fits post_residual, reward; else mild penalty
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 3.0 * (post_residual - next_item_size) as f64 / bin_capacity as f64;
        } else {
            score += 2.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Mean residual interaction: prefer bins deviating favorably from mean
    score += 0.5 * (pr - mean_residual) * (1.0 + p2);

    // New-bin candidate: mild penalty unless residual is huge and fit is poor
    if bin_residual == bin_capacity {
        let poor_fit = (bin_capacity as f64 - item_size as f64) / bin_capacity as f64;
        score += 12.0 - 10.0 * poor_fit * (1.0 - p1);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: items 1..=100, capacity 100.
    // Perfect fits (0) are gold; tiny residuals (1..=5) are near-dead space.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 20.0;
    }

    // Modulo-10 harmonic class: residuals divisible by 10 remain "usable"
    // by the integer-sized item distribution; odd/prime-ish residues are worse.
    let r10 = post_residual % 10;
    if r10 == 0 {
        score -= 15.0;
    } else if r10 == 5 {
        score -= 5.0;
    } else {
        score += (10 - r10) as f64 * 0.8;
    }

    // Integer-division threshold classes on post_residual.
    let class = post_residual / 20; // 0..=5
    score += class as f64 * 6.0;

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0;
        } else if next_item_size <= post_residual {
            // Reward proportional to how well the next item fills the leftover.
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 30.0 * fill;
            // Harmonic check: does post_residual - next_item_size land on a nice class?
            let nr = post_residual - next_item_size;
            if nr % 10 == 0 {
                score -= 10.0;
            }
        } else {
            // Next item cannot use this residual: penalize large dead leftovers more
            // late in the stream when consolidation matters.
            let progress = step_index as f64 / total_items.max(1) as f64;
            score += (post_residual as f64 / 100.0) * (10.0 + 30.0 * progress);
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins are crowded.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        // If mean residual across open bins is small, opening fresh is reasonable.
        score = 40.0 + 60.0 * pressure;
        if open_bins_count == 0 {
            score = -500.0; // must open the first bin
        }
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 100.0; // next item needs a fresh bin anyway
        }
    }

    // Mild global balance: prefer bins whose residual is below the mean (tighter packs).
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Slight preference for fewer open bins overall.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: small gaps that likely cannot host future items.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    }

    // Reward tight fits.
    score -= 8.0 * (item_size as f64 / bin_residual as f64);

    // Last-chance bin: strong bonus to use it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive if it enables a good fit for the lookahead item.
    if bin_residual == bin_capacity {
        let lookahead_penalty = if next_item_size > 0 && next_item_size > post_residual.min(bin_capacity) {
            0.0
        } else {
            20.0
        };
        score += 10.0 + open_bins_count as f64 * 1.5 + lookahead_penalty;
        // Early in the stream, opening new bins is cheaper.
        score -= 15.0 * (1.0 - step_index as f64 / total_items.max(1) as f64);
    }

    // Pressure from many open bins: favor consolidating into existing bins.
    score += open_bins_count as f64 * 0.8;

    // If the next item fits exactly in the post-residual, reward this placement strongly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here anyway; mildly prefer filling this bin now.
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly (small post_residual).
    score -= (bin_capacity as f64 / (post_residual as f64 + 1.0)) * 2.0;

    // 2-step lookahead: if next item exactly fills post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Next item fits: reward proportional to how well it fills the remainder.
            score -= (next_item_size as f64 / post_residual as f64) * 25.0;
        } else {
            // Next item does NOT fit: penalize leaving a gap next item can't use.
            let gap_waste = post_residual as f64 / next_item_size as f64;
            score += gap_waste * 15.0;
        }
    } else {
        // Last item: minimize post_residual as much as possible.
        score += post_residual as f64 * 0.5;
    }

    // Penalize creating dead space relative to mean residual across open bins.
    if (post_residual as f64) > mean_residual * 1.2 {
        score += (post_residual as f64 - mean_residual) * 0.8;
    }

    // Last-chance bin: if this is the only bin that can fit, strongly favor using it
    // over opening a new bin (avoid wasting this bin's residual).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Discourage opening a new bin when existing bins give a decent fit.
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline penalty, reduced when item is huge relative to capacity.
        let huge = (item_size as f64 / bin_capacity as f64) > 0.7;
        if huge {
            score += 5.0; // fresh bin fine for huge items
        } else {
            score += 35.0;
        }
    }

    // Early in stream: be slightly more willing to open bins for flexibility.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 3.0;

    // Mild penalty tied to number of open bins to limit bin proliferation.
    score += open_bins_count as f64 * 0.4;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 60.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful later (items >= 1).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 18.0;
        } else {
            score += 8.0;
        }
        // Extra reward if post_residual exactly chains well with next item.
        if post_residual >= next_item_size && post_residual - next_item_size < 10 {
            score -= 12.0;
        }
    }

    // New-bin candidate handling: neutral-ish score; open new bin only when
    // fits are poor or many bins already exist with slack.
    if bin_residual == bin_capacity {
        let avg_slack = mean_residual;
        let poor_fits = (fitting_bins_count as f64) <= 1.0
            || avg_slack < item_size as f64 * 0.5;
        let pressure = open_bins_count as f64 / (step_index as f64 + 1.0).max(1.0);
        if poor_fits {
            score -= 30.0 + 10.0 * pressure;
        } else {
            score += 35.0 - 15.0 * pressure;
        }
    }

    // Mild time-horizon scaling: early on, be greedy toward tight fits;
    // later, weight global slack more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (1.0 - progress) * 5.0 * tightness;
    score += progress * 0.05 * (open_bins_count as f64);

    // Prefer bins with residual above the mean (keep mean slack balanced).
    if bin_residual < bin_capacity {
        score += 0.15 * (mean_residual - bin_residual as f64).max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let progress_sq = progress * progress;

    // Normalized post-residual
    let pr = post_residual as f64 / cap;
    let pr_sq = pr * pr;

    // Non-linear coupling: prefer small post-residual, reward tight fits more strongly later in the stream
    score -= 18.0 * pr * (1.0 - pr) * (1.0 + progress);
    score -= 10.0 * pr_sq * progress_sq;

    // Penalize dead space (very small unusable residual) with a smooth bump
    let dead = (pr - 0.08).abs();
    score += 12.0 * (-dead * dead / 0.01).exp() * (1.0 - progress);

    // Last-chance bonus: this is the only bin that fits
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead coupling: reward if next item can use the post-residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post_residual as f64 {
            let slack = (post_residual as f64 - nxt) / cap;
            score -= 14.0 * (1.0 - slack) * (1.0 + progress_sq);
        } else {
            // post-residual too small for next item: penalize proportionally
            score += 8.0 * (1.0 - progress) * (pr - nxt / cap).abs().min(1.0);
        }
    }

    // Mean residual divergence penalty: avoid creating outliers vs. mean residual
    score += 3.0 * ((post_residual as f64 - mean_residual) / cap).abs();

    // New-bin candidate handling: mildly discourage opening a new bin early,
    // encourage it late in the stream or when the item is large
    if bin_residual == bin_capacity {
        let openness = 0.6 + 0.8 * progress + 0.4 * (item_size as f64 / cap);
        score += 20.0 * openness;
        if open_bins_count == 0 {
            score -= 100.0; // must open first bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of post_residual: residues that pair well with
    // common item sizes (multiples of 5, 10, 20) are more reusable.
    let pr = post_residual;
    if pr == 0 {
        // Perfect fit is ideal: strong reward.
        score -= 1000.0;
    } else {
        // Dead-space penalty grows when post_residual falls into "awkward"
        // harmonic classes: too small to host typical items (1..10).
        if pr < 10 {
            score += 60.0 + (10 - pr) as f64 * 4.0; // unusable sliver
        } else if pr % 10 == 0 {
            score -= 15.0; // clean decade residual, easy to fill
        } else if pr % 5 == 0 {
            score -= 7.0; // half-decade residual still friendly
        } else {
            // Odd residue: penalize by distance to nearest multiple of 5.
            let d = (pr % 5) as f64;
            score += d * 2.0;
        }

        // Integer-division thresholds: residual in [20, 40] is a sweet spot
        // for mid-size items; reward it mildly.
        if pr / 20 == 1 {
            score -= 10.0;
        } else if pr / 20 >= 3 {
            // Large leftover: fine for a new bin, but wasteful if bin was big.
            score += 5.0;
        }
    }

    // --- Lookahead coupling: does the residual fit the next item exactly?
    if next_item_size > 0 {
        if next_item_size <= pr {
            let next_gap = pr - next_item_size;
            if next_gap == 0 {
                score -= 80.0; // sets up a perfect follow-up fit
            } else if next_gap < 10 {
                score -= 20.0;
            } else {
                score -= 10.0;
            }
        } else {
            // Next item cannot use this residual: residual becomes dead
            // unless another item later fits; mild penalty scaled by
            // how much is stranded.
            score += (pr as f64) * 0.05;
        }
    }

    // --- Last-chance logic: if this is the only fitting bin, strongly
    // prefer using it over opening a new bin (unless post_residual < 10).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        if pr >= 10 {
            score -= 50.0;
        } else {
            score -= 10.0;
        }
    }

    // --- New-bin candidate handling: empty bin should only win when the
    // item fits no open bin well. Penalize the fresh bin by its capacity
    // fraction so it loses against decent fits, but wins against terrible
    // ones (which carry big dead-space penalties above).
    if bin_residual == bin_capacity {
        score += 120.0 + 0.5 * (bin_capacity as f64);
        // Late in the stream, opening fresh bins is cheaper (less time
        // to benefit from reuse); relax the penalty.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 60.0 * progress;
    }

    // --- Crowding: with many open bins, prefer tightening existing ones
    // rather than spreading out; add small pressure proportional to
    // open_bins_count relative to mean residual.
    if open_bins_count > 1 {
        let spread = (bin_residual as f64 - mean_residual).abs();
        score += spread * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero gaps are almost unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 + 5.0 * (10 - post_residual) as f64;
    }
    // Perfect fit heavily rewarded.
    if post_residual == 0 {
        score -= 40.0;
    } else {
        // Reward tight fits (small residual is good, but keep dead-space penalty).
        score -= (item_size as f64 / bin_capacity as f64) * 10.0;
    }

    // If next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 60.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here: penalize leaving a gap that blocks lookahead.
        score += 8.0;
    }

    // Last chance bin: avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Pressure from many open bins: favor filling existing bins over spreading.
    score += open_bins_count as f64 * 1.5;

    // Penalize bins far below mean residual (keeps packing balanced, avoids fragmentation).
    score += ((bin_residual as f64) - mean_residual).max(0.0) * 0.3;

    // New empty bin candidate: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        score += 55.0 + open_bins_count as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: reward tight fits (small post_residual) with a superlinear penalty.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // 2-step lookahead: if next item fits exactly into post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0; // perfect two-item fill
        } else if post_residual > next_item_size {
            let leftover = post_residual - next_item_size;
            // reward proportionally to how full the bin becomes after both items
            let combined_fill = 1.0 - (leftover as f64) / (bin_capacity as f64);
            score -= 18.0 * combined_fill * combined_fill;
        } else {
            // next item cannot follow here; penalize mildly
            score += 6.0;
        }
    } else {
        // last item: just prefer minimal post_residual
        score -= 5.0;
    }

    // Relative to mean residual: prefer bins that are already more filled than average
    // (i.e., residual below mean), but avoid extreme fragmentation.
    let resid = bin_residual as f64;
    if resid < mean_residual {
        score -= 4.0 * (mean_residual - resid) / bin_capacity as f64;
    } else {
        score += 3.0 * (resid - mean_residual) / bin_capacity as f64;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: make it attractive only when item is large relative to typical
    // residuals and open bins are mostly fragmented; otherwise penalize opening new bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        let fragmentation = mean_residual / bin_capacity as f64;
        // new bin is good if item is big (leaves little waste) and existing bins are fragmented
        let big_item = (item_size as f64) / (bin_capacity as f64);
        if big_item > 0.7 && fragmentation > 0.5 {
            score -= 10.0 * big_item * progress.max(0.2);
        } else {
            score += 15.0 + 10.0 * (1.0 - big_item);
        }
    }

    // Mild penalty for dead space that is too small to ever be useful (< 10)
    if post_residual < 10 {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: quadratic decay for small post-residual (dead-space shaping).
    let tightness = (post_residual as f64 / bin_capacity as f64).powi(2);
    score += 8.0 * tightness;

    // Perfect / near-perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Lookahead (k=2): reward bins whose post-residual can host the next item,
    // penalize when the next item is large and this bin would waste space.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            // Wasted residual the next item cannot use.
            score += 4.0 * (post_residual as f64 / bin_capacity as f64)
                * (next_item_size as f64 / bin_capacity as f64);
        }
    }

    // New-bin candidate handling: opening a new bin is costly early on;
    // late in the stream or when residuals are fragmented, allow it.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual - post_residual as f64).abs() / bin_capacity as f64;
        let mut new_bin_penalty = 20.0;
        // As stream progresses, new bins become cheaper to open.
        new_bin_penalty -= 10.0 * progress;
        // If existing bins are fragmented (mean residual far from fresh capacity), soften penalty.
        new_bin_penalty -= 6.0 * fragmentation;
        // If many bins can fit the item, opening a new bin is wasteful.
        if fitting_bins_count > 2 {
            new_bin_penalty += 10.0;
        }
        score += new_bin_penalty.max(-4.0);
    }

    // Mild preference for filling bins below mean residual (balance avoidance of hoarding space).
    score -= 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer larger post-residual (less dead space), with non-linear shaping.
    let mut score = pr * (1.0 + 0.35 * progress);

    // Non-linear coupling: post_residual normalized by capacity, polynomial terms.
    let x = pr / cap;
    score += 18.0 * x * (1.0 - x) * (1.0 - progress); // reward mid-range residuals early
    score -= 14.0 * x * x * progress;                 // late stream: tolerate small residuals

    // Tight fit bonus (smooth): quadratic decay of bonus as slack grows.
    let tightness = 1.0 - (item / bin_residual.max(1) as f64).min(1.0);
    score -= (1.0 - tightness) * (1.0 - tightness) * 22.0;

    // Last-chance bin: strong reward if this is the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 * (1.0 - progress * 0.5);
    }

    // Lookahead: penalize if next item could have used this residual better.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            // next item fits exactly-ish in post residual: mild penalty for wasting pair opportunity
            let waste = (pr - nxt).abs();
            score += 0.25 * waste * (0.5 + 0.5 * progress);
        } else if nxt > bin_residual {
            // next item won't fit here regardless; slight reward for using residual now
            score -= 6.0 * (1.0 - x);
        }
    }

    // New-bin candidate handling: empty bin should only win when open bins are poor fits.
    if bin_residual == bin_capacity {
        // Penalize opening new bin mildly; penalty shrinks when open bins are crowded.
        score += 12.0 + 8.0 * (1.0 - (open_bins_count as f64 / (open_bins_count as f64 + 3.0)));
        score -= 10.0 * (1.0 - (mean_residual / cap).min(1.0)).powi(2);
    } else {
        // Slight reward for draining bins with large mean residual pressure.
        score -= 4.0 * (mean_residual / cap).min(1.0);
    }

    // Interaction: small residuals late are valuable; big residuals early are fine.
    score += 10.0 * (1.0 - x).powi(3) * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect fit
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: residues that are "dead space" classes
    let pr = post_residual;
    let res_class = pr % 10;
    // Small residues (1..3) are nearly perfect; large residues near capacity are dead space
    score -= (10 - res_class as f64) * 2.0; // reward residues close to multiples of 10 alignment
    if pr > 0 && pr < 5 {
        score -= 50.0; // tiny dead space is excellent
    }
    if pr >= 50 {
        // half-empty bin: still very usable, mild penalty relative to post_residual already large
        score += 10.0;
    }

    // New-bin candidate handling: only open a new bin when the item is large
    // or the fit is exceptional, otherwise prefer existing bins.
    if bin_residual == bin_capacity {
        // Base penalty to discourage opening new bins casually
        score += 120.0;
        // Large items justify fresh bins (item_size in upper harmonic classes)
        if item_size >= bin_capacity / 2 {
            score -= 150.0;
        }
        // If no existing bin fits well (this is the only fitting option and it's new),
        // opening is fine: penalty already applied, reduce when item large.
        if item_size > (bin_capacity * 3) / 4 {
            score -= 60.0;
        }
        // Late in stream, opening new bins is less costly than dead space
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= progress * 40.0;
    } else {
        // Existing bin: reward being the last chance before opening a new bin
        if fitting_bins_count == 1 {
            score -= 80.0;
        }
        // Reward using bins whose residual matches item size class (integer division)
        if bin_residual / 10 == (item_size + post_residual) / 10 {
            score -= 5.0;
        }
    }

    // Lookahead coupling: if next item can fit into post_residual, this placement is great
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 25.0;
        // extra reward if next item exactly fills remaining space
        if next_item_size == post_residual {
            score -= 50.0;
        }
    } else if next_item_size > post_residual && next_item_size > 0 {
        // next item won't fit here regardless; slight penalty if post_residual is an
        // awkward class that no typical item (>=10) can use
        if post_residual < 10 {
            score += 20.0;
        }
    }

    // Coupling with mean residual: prefer bins below mean residual (tighter bins)
    score += (mean_residual - bin_residual as f64).max(-50.0).min(50.0) * 0.3;

    // Modulo harmonic bonus: post_residual in "friendly" classes (multiples of 5)
    if pr % 5 == 0 && pr > 0 {
        score -= 8.0;
    }

    // Penalize very large post_residual when item is small (wasting space)
    if post_residual > bin_capacity / 2 && item_size < bin_capacity / 4 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are highly undesirable.
    // Treat residuals in (0, 10) as pure dead space and penalize heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    }
    // Perfect fit is extremely rewarded.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Reward tight fits relative to bin residual: waste ratio penalty.
    let waste_ratio = post_residual as f64 / bin_residual.max(1) as f64;
    score += 30.0 * waste_ratio;

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open bins pressure: with many open bins, prefer filling existing ones;
    // with few open bins, opening a new one is less costly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    score += pressure * 2.0;

    // Lookahead: if next item fits in the post-residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0;
        // Extra reward if next item fills the bin almost completely after placement.
        let after_next = post_residual as f64 - next_item_size as f64;
        if after_next < 10.0 {
            score -= 10.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 && post_residual < next_item_size {
        // Post-residual too small for next item: penalize small gaps further.
        score += 8.0;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins).
    score += 0.3 * (mean_residual - post_residual as f64);

    // New-bin candidate: prefer opening a new bin only when current bin fit is bad
    // and there is room to accumulate future items. Base new-bin score ~ item_size
    // residual (item_size), so it competes naturally; add mild penalty to avoid
    // bin proliferation, scaled by open bins count.
    if bin_residual == bin_capacity {
        score += 5.0 + 1.5 * open_bins_count as f64;
        // But if the item is large, a fresh bin is attractive (large items pair poorly).
        if item_size >= 50 {
            score -= 12.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: extremely desirable
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Two-step lookahead: post_residual exactly matches next item -> chain fit
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 400.0;
    }
    // Next item fits in the post-residual (soft lookahead bonus)
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 0.5 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space relative to the next item's size
        let waste = next_item_size as f64 - post_residual as f64;
        score += 0.8 * waste;
    }

    // Penalize small unusable residuals (below minimum item size 1..100 range heuristics)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Compare against mean residual: bins with residual far below mean are tighter fits
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: avoid opening a new bin if this is the only fitting one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: only attractive when open bins are crowded
    if bin_residual == bin_capacity {
        let crowded = (mean_residual < item_size as f64 * 1.2) as i32 as f64;
        let late = (step_index as f64 / total_items.max(1) as f64);
        score -= 10.0 + 120.0 * crowded * (0.3 + late);
    } else {
        // Prefer reusing bins; the more open bins exist, the more we favor filling them
        score -= 2.0 * (open_bins_count.min(20) as f64);
    }

    // Early stream: be more conservative, prefer tight fits to keep options open
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 50.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that no plausible item can use (items <= 100,
    // so residuals >= 100 are fine; small residuals are wasteful).
    if post_residual > 0 {
        let dead = 1.0 - (post_residual as f64 / 100.0).min(1.0);
        score += 12.0 * dead * dead;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // Mild penalty when many alternatives exist; prefer best fit among them.
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Lookahead coupling: if the next item fits into the post-residual,
    // reward this placement (chaining).
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain_fit = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 18.0 * chain_fit;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Post-residual likely wasted with respect to lookahead item.
        score += 6.0;
    }

    // Time horizon: early in the stream, prefer keeping residuals flexible
    // (penalize very small residuals); late in the stream, squeeze bins hard.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * (post_residual as f64) * 0.15;
    score -= progress * tightness * 20.0;

    // Global state: many open bins with high mean residual -> encourage
    // filling existing bins rather than opening new ones.
    if bin_residual < bin_capacity {
        score -= 0.05 * mean_residual;
        score -= 1.5 * open_bins_count as f64;
    }

    // New-bin candidate: penalize opening a new bin unless current item is
    // large and nothing fits well.
    if bin_residual == bin_capacity {
        let base_penalty = 40.0;
        let scarcity = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        let large_item = (item_size as f64 / bin_capacity as f64) > 0.6;
        score += base_penalty * scarcity
            + (1.0 - progress) * 15.0
            - if large_item { 10.0 } else { 0.0 };
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr_norm = pr / cap;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early: prefer tight fills (small post_residual) less aggressively,
    // Late: penalize large post_residual super-linearly to squeeze bins.
    let poly = pr_norm * pr_norm * (1.0 - pr_norm);
    score += 30.0 * poly * (0.5 + progress);

    // Smooth cubic damping of residual as stream progresses.
    score += 12.0 * pr_norm * pr_norm * pr_norm * progress * progress;

    // Reward filling bins that are the last chance to fit this item.
    if fitting_bins_count == 1 {
        score -= 8.0 + 10.0 * progress;
    }

    // Lookahead: penalize if post_residual can't accommodate next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let fit_quality = 1.0 - (pr - nx) / cap;
            score -= 6.0 * fit_quality * fit_quality;
        } else {
            score += 4.0 * (nx - pr) / cap;
        }
    }

    // Slight preference for bins below mean residual (consolidate slack).
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Mild penalty for opening new bins early in the stream.
    if bin_residual == bin_capacity {
        score += 3.0 + 15.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero is best.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 10 {
        score -= 20.0;
    }

    // Harmonic class penalty: dead space that cannot fit the smallest
    // plausible item (sizes >= 1, but small items are common) is dead weight.
    if post_residual > 0 {
        let class = post_residual % 10;
        // Residuals in awkward classes (1..9 mod 10) are less reusable.
        score += class as f64 * 0.8;
        if post_residual < 10 {
            score += 15.0; // nearly unusable sliver
        }
    }

    // Lookahead: if the next item fits exactly in the post-residual,
    // strongly favor this bin (perfect chain).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            // Next item won't fit here: slight penalty for breaking chains.
            score += 3.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when existing
    // residuals are large and mean residual suggests poor consolidation.
    if bin_residual == bin_capacity {
        // Base penalty so new bins are not opened casually.
        score += cap * 0.6;
        // But if open bins are mostly full (mean residual small), a new
        // bin is fine and even desirable.
        if open_bins_count > 0 {
            score -= mean_residual * 0.9;
        }
        // Late in the stream, slightly prefer consolidating.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Mild preference for filling fuller bins (lower residual => lower score already),
    // plus a tie-breaker on bin scarcity.
    score += (bin_residual as f64 / cap) * 5.0;
    score -= open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: eliminate dead space entirely.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Strict dead-space avoidance: small nonzero gaps (1..=10) are
    // nearly unusable for future items -> heavy penalty.
    if post_residual >= 1 && post_residual <= 10 {
        score += 60.0;
    } else if post_residual <= 20 {
        // Moderately risky gap: mild penalty.
        score += 15.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: baseline handicap so it only wins when all
    // open fits are poor (their score exceeded this).
    if bin_residual == bin_capacity {
        score += 30.0;
        // Early in the stream, opening bins is cheap; late in the
        // stream, prefer consolidating into existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * (1.0 - progress);
    }

    // Open-bin pressure: many open bins -> discourage spreading
    // residual thin; encourage tighter packing.
    score += 0.5 * open_bins_count as f64;

    // Lookahead: if the next item would fit exactly in the resulting
    // residual, reward this placement.
    if next_item_size > 0 && post_residual > 0 && next_item_size == post_residual {
        score -= 80.0;
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        // Next item cannot use this residual: residual becomes dead
        // space, mild penalty scaled by gap smallness.
        if post_residual < next_item_size && post_residual <= 15 {
            score += 25.0;
        }
    }

    // Deviation from mean residual: prefer bins whose residual is
    // already small (large items into nearly-full bins).
    score += 0.3 * (mean_residual - bin_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post-residual can
    // accommodate the next item (ideally snugly).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Slack after hypothetically placing the next item too:
            // small slack => near-perfect 2-item packing => big reward.
            let two_step_slack = (post_residual - next_item_size) as f64;
            score -= 40.0 - 0.5 * two_step_slack;
        } else {
            // Next item cannot follow into this bin: penalize proportionally
            // to how much dead space is stranded.
            let stranded = next_item_size - post_residual;
            score += 0.35 * stranded as f64;
        }
    }

    // Perfect fit bonus: leaving almost nothing behind is excellent.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Compare against mean residual: a bin whose residual is far below the
    // mean is a "small hole" — using it keeps big holes open for big items.
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    } else {
        score += 0.10 * (bin_residual as f64 - mean_residual);
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: opening a fresh bin is only attractive when the
    // current item is large or no good fit exists; make empty bins slightly
    // less appealing by default.
    if bin_residual == bin_capacity {
        score += 15.0;
        // But if the item is huge relative to capacity, a fresh bin is fine.
        if item_size * 2 >= bin_capacity {
            score -= 20.0;
        }
    }

    // Late in the stream, tighten packing (less room for waste).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 8.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear bonus.
    let cap = bin_capacity as f64;
    let tightness = 1.0 - (post_residual as f64 / cap);
    score -= 8.0 * tightness * tightness;

    // Lookahead coupling: if the next item fits the post-residual well,
    // strongly reward this placement (chaining good fits).
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain_waste = (post_residual - next_item_size) as f64;
        score -= 6.0 * (1.0 - chain_waste / cap);
    } else if next_item_size > post_residual {
        // Next item won't fit here anyway; slight penalty for leaving
        // awkward residue that neither chains nor is large.
        score += 2.0;
    }

    // Last-chance bin: strongly prefer using the only bin that fits,
    // avoiding a new bin opening.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Penalize opening a new bin when plenty of open bins exist
    // (encourage consolidation early/mid stream).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let open_pressure = (open_bins_count as f64).ln().max(0.0);
        score += 4.0 + 10.0 * open_pressure * (1.0 - 0.5 * progress);
    }

    // Penalize bins whose residual deviates from the mean residual
    // (favor balanced residual distribution across open bins).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Prefer bins with larger residual when many bins are open
    // (fill fuller bins less, keep small residuals for small items).
    if open_bins_count > 1 {
        let rel_fill = (bin_residual as f64 / cap) - (item_size as f64 / cap);
        score -= 1.5 * rel_fill;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: penalize leftover space, with non-linear (quadratic/cubic) shaping
    let mut score = pr
        - 12.0 * norm_pr * (1.0 - norm_pr) * cap
        + 20.0 * norm_pr * norm_pr;

    // Smooth coupling: tight fits become more valuable as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= 30.0 * tightness * tightness * (0.3 + 0.7 * progress);

    // Penalize dead space relative to mean residual (smooth interaction)
    let mr = mean_residual / cap;
    score += 15.0 * (norm_pr - mr) * (norm_pr - mr) * (1.0 - progress);

    // Lookahead: reward if next item fits in post_residual (smooth term)
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let fits_next = (pr - ns).max(0.0) / cap;
        score += 10.0 * fits_next * fits_next;
        score -= 8.0 * (1.0 - (ns / cap)) * tightness * progress;
    }

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (0.5 + 0.5 * progress);
    }

    // Mild penalty for spreading across many bins early
    score += 2.0 * (open_bins_count as f64).ln() * (1.0 - progress);

    // Slight preference for fuller bins overall
    score -= 5.0 * item_size as f64 / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual modulo capacity fractions
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Penalize residuals in awkward harmonic classes (dead space hard to fill)
    let quarter = (post_residual % (bin_capacity / 4)).max(1) as f64;
    score += 0.5 * (quarter / (bin_capacity as f64 / 4.0)).ln().abs();

    // Integer division threshold: small post_residual is dead space
    if post_residual > 0 && post_residual <= 10 {
        score += 40.0;
    } else if post_residual <= 20 {
        score += 10.0;
    }

    // Lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size <= post_residual {
            score -= 0.8 * (post_residual - next_item_size) as f64;
        } else {
            // next item won't fit here; penalize proportionally to wasted potential
            score += 0.3 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // Many open bins with high mean residual: prefer filling existing bins
    if open_bins_count > 2 {
        score -= 0.2 * (open_bins_count as f64).ln() * (item_size as f64 / cap);
    }

    // Slight preference for larger fills relative to bin size
    score -= 0.5 * (item_size as f64 / cap) * 10.0;

    // New-bin candidate: make it unattractive unless residual is large and item small
    if bin_residual == bin_capacity {
        score += 25.0 + 0.5 * item_size as f64;
        if next_item_size > 0 && next_item_size >= item_size {
            score += 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fill_ratio * fill_ratio;

    // Penalize small unusable dead space (gaps too small for typical items).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    }

    // Dead space that cannot fit the lookahead item is extra wasteful.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Reward leaving room for the next item (chained fit).
        score -= 10.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (0.5 + 0.5 * progress);

    // New-bin candidate handling: an empty bin is a fallback; make it costly unless
    // the current bin would leave a very poor gap or is already very full.
    if bin_residual == bin_capacity {
        let poor_fit = fill_ratio < 0.5 && post_residual > 20;
        if poor_fit {
            score -= 45.0; // allow opening a new bin for a large item
        } else {
            score += 35.0 + 8.0 * open_bins_count as f64;
        }
    }

    // Slight preference for bins below mean residual (spread waste evenly).
    if (bin_residual as f64) < mean_residual {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact 2-step lookahead fit: post_residual == next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs();
        if diff == 0 {
            score -= 60.0;
        } else {
            // penalize deviation from a perfect next-item fit, scaled by item size
            score += (diff as f64) * 0.8;
            // if next item cannot fit here at all, mild penalty
            if post_residual < next_item_size {
                score += 5.0;
            }
        }
    }

    // Penalize unusable dead space (small residuals that likely waste capacity)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Relative to mean residual: prefer bins with more residual than average
    // (use tight bins first, keep loose bins flexible)
    score -= (bin_residual as f64 - mean_residual) * 0.3;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible
    if bin_residual == bin_capacity {
        let base = 30.0 + 0.5 * (bin_capacity as f64 - item_size as f64);
        // during early stream, allow opening bins more freely
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = base + progress * 20.0;
        // lookahead: opening new bin is good if item + next item pack perfectly
        if next_item_size > 0 && item_size + next_item_size == bin_capacity {
            score -= 80.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but keep a reserve
    // so bins aren't shredded into dead space too early.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize leaving residuals that are small but larger than typical
    // upcoming items can use (dead space zones).
    if post_residual > 0 {
        let dead = post_residual as f64 / bin_capacity as f64;
        if post_residual < 10 {
            score += 25.0 * (10 - post_residual) as f64; // tiny unusable slivers
        } else if dead < 0.35 {
            score += 8.0 * dead; // moderate awkward residual
        }
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        score -= 10.0 * (1.0 - gap as f64 / bin_capacity as f64);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here anyway; slight penalty if we strand space.
        score += 2.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
        if post_residual < 10 {
            score += 12.0; // but don't shred the last fitting bin
        }
    }

    // New-bin candidate handling: empty bin should only win when no open
    // bin offers a decent fit, or when the stream is young and spreading
    // capacity is cheap.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let spread_value = (1.0 - progress) * 10.0 / (open_bins_count as f64 + 1.0);
        score = bin_capacity as f64 + 30.0 - spread_value;
        if next_item_size > 0 && next_item_size <= bin_capacity / 2 {
            score -= 5.0; // fresh bin accommodates medium next items
        }
        if item_size > 80 {
            score -= 20.0; // huge items prefer fresh capacity
        }
    }

    // Global state coupling: prefer placing into bins whose residual is
    // below the mean (consolidate fragmentation toward fuller bins).
    let dev = mean_residual - bin_residual as f64;
    score += 0.05 * dev;

    // Time horizon: late in the stream, be conservative — prefer filling
    // existing bins tightly rather than spreading.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * progress * tightness;

    // Mild penalty for using very full bins on tiny items.
    if item_size < 20 && bin_residual < 40 && bin_residual < bin_capacity {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: prefer tight fits (low post residual), smoothed polynomial coupling with progress.
    let mut score = pr as f64;

    // Non-linear interaction: waste penalty grows as stream progresses (exploit vs explore).
    let waste_penalty = x * x * (1.0 + 3.0 * progress) * cap;
    score += waste_penalty;

    // Reward near-perfect fits more strongly later in the stream.
    let tight_bonus = (1.0 - x) * (1.0 - x) * (10.0 + 40.0 * progress);
    score -= tight_bonus;

    // Dead-space avoidance: residual too small for any plausible item (items >= 1, typical >= 10).
    if pr > 0 && pr < 10 {
        score += 25.0 * (1.0 - pr as f64 / 10.0) * (0.5 + progress);
    }

    // Lookahead coupling: if next item fits exactly into post_residual, reward strongly.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let fit_quality = 1.0 - ((pr - nx) / cap).abs();
            score -= 15.0 * fit_quality * fit_quality;
        } else {
            score += 8.0 * ((nx - pr) / cap);
        }
    }

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Mild penalty when this bin is far below mean residual (unbalanced bins).
    score += 0.1 * (mean_residual - bin_residual as f64).abs();

    // New-bin candidate: encourage opening fresh bins early, discourage when many bins exist and fit is decent.
    if bin_residual == bin_capacity {
        let open_penalty = (open_bins_count as f64).ln() + 1.0;
        score += 20.0 + 15.0 * (1.0 - progress) * open_penalty - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues divisible by small
    // denominators are more likely to be filled by future items.
    let pr = post_residual;
    if pr > 0 {
        let mut harmony = 0.0;
        for d in [2u32, 4, 5, 10, 20, 25, 50] {
            if pr % d == 0 {
                harmony += 1.0 / (d as f64);
            }
        }
        score -= harmony * 4.0;
    } else {
        // Perfect fit: strongest reward.
        score -= 60.0;
    }

    // Dead-space penalty: residuals too small for any plausible item
    // (items >= 1, but tiny slivers under ~10 are nearly unusable).
    if pr > 0 && pr < 10 {
        score += 25.0;
    }

    // Lookahead coupling: reward when post_residual exactly matches the
    // next item (chain fit), penalize when next item barely misses.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 35.0;
        } else if next_item_size <= pr {
            score -= 10.0 * (1.0 - (pr - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item cannot use this residual at all.
            score += 8.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: make it attractive only when current bin fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; offset by how bad existing options are.
        let pressure = if fitting_bins_count == 0 {
            -40.0
        } else {
            let tightness = 1.0 - (item_size as f64 / bin_capacity as f64);
            -5.0 * tightness
        };
        score = bin_capacity as f64 + pressure;
        // Late in the stream, avoid opening bins that will strand capacity.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress > 0.9 {
            score += 30.0 * progress;
        }
    }

    // Mild preference for fuller bins overall (tight packing).
    score -= (bin_capacity - bin_residual) as f64 / bin_capacity as f64 * 3.0;

    // Tie-break: spread load when many bins are open and mean residual is high.
    if open_bins_count > 4 && mean_residual > (bin_capacity as f64 * 0.5) {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // even the smallest plausible item are pure waste -> heavy penalty.
    let min_item = 1u32;
    if post_residual < min_item {
        score -= 50.0; // perfect fit, zero waste
    } else if post_residual <= 10 {
        // small unusable-ish gap: penalize extra
        score += 12.0;
    }

    // Reward tight fits relative to bin capacity.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill_ratio;

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than spawning new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.35 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // New-bin candidate: only attractive if the item barely fits any open bin
    // or would leave a bad gap everywhere. Make empty bin moderately costly.
    if bin_residual == bin_capacity {
        score += 25.0 + 3.0 * open_bins_count as f64;
        // lookahead: if next item is large and this item is small, a fresh
        // bin can be valuable to preserve tight bins for big items.
        if next_item_size > 0 && next_item_size > item_size.saturating_mul(2) {
            score -= 18.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Prefer bins whose residual deviates favorably from the mean:
    // placing into a below-average-residual bin consolidates fullness.
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Lookahead synergy: if the post-residual exactly accommodates the next
    // item, this placement is excellent.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 10.0; // creates dead space relative to lookahead
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // closely matches the next item's size (perfect chain fit).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        let gap = (pr - nxt).abs();
        if pr >= nxt {
            // Next item can chain into this bin: reward tight matches.
            score -= 25.0 * (1.0 - gap / bin_capacity as f64);
            // Exact chain fit (post_residual == next_item_size) is ideal.
            if gap < 1.0 {
                score -= 30.0;
            }
        } else {
            // Next item cannot fit: penalize proportionally to dead space.
            score += 8.0 + 0.15 * (nxt - pr);
        }
    }

    // Penalize residual far above the mean residual (wasteful bin choice)
    // unless it's a tight fit.
    let mean_gap = post_residual as f64 - mean_residual;
    if mean_gap > 0.0 {
        score += 0.10 * mean_gap;
    } else {
        score += 0.05 * mean_gap; // small reward for tighter-than-average fit
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Prefer filling bins tightly overall: reward small post_residual nonlinearly.
    score -= 10.0 * (1.0 - (post_residual as f64 / bin_capacity as f64)).powi(3);

    // Late in the stream, consolidate: favor existing bins over new ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses and when
        // open bins could still absorb the item.
        score += 12.0 + 20.0 * progress + 2.0 * open_bins_count as f64;
        if next_item_size > 0 && (next_item_size as f64) <= 100.0 {
            score += 5.0; // fresh bin is attractive only via lookahead, keep some penalty
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space: residuals too small to hold even the smallest item are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item (chaining),
    // penalize bins that leave exactly-incompatible space.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 6.0;
        }
    }

    // New-bin candidate handling: opening a bin is expensive; discourage unless
    // no good alternative exists (few fitting bins) or the item is large.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 1.0 / fitting_bins_count as f64 };
        // Base cost of a fresh bin scales with how many bins are already open.
        score += 40.0 + 3.0 * (open_bins_count as f64).sqrt();
        // Late in the stream, avoid opening bins for small items (poor long-term use).
        if item_size < 40 && progress > 0.5 {
            score += 20.0;
        }
        // If this is the only fitting bin, opening is nearly acceptable.
        score -= 35.0 * pressure;
        // Large items fragment bins less when placed fresh.
        score -= (item_size as f64) * 0.15;
    } else {
        // Reward using existing bins, especially when alternatives are scarce.
        if fitting_bins_count == 1 {
            score -= 15.0; // last-chance bin: use it before opening a new one
        }
        // Prefer bins with residual close to the mean (balanced packing),
        // but mildly prefer below-mean bins to consolidate space.
        let dev = bin_residual as f64 - mean_residual;
        score += 0.05 * dev.abs();
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
        // Early stream: keep bins balanced to preserve flexibility.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if progress < 0.3 {
            score += 0.08 * dev.abs();
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let prn = pr / cap;

    // Base: prefer small post_residual, with non-linear (quadratic/cubic) shaping
    let mut score = pr + 40.0 * prn * prn * (1.0 + progress);

    // Non-linear coupling of post_residual with stream progress:
    // early on, tolerate larger residuals (keep bins flexible);
    // later, penalize them more aggressively (polynomial ramp).
    let coupling = (prn * (1.0 - progress)).powi(3);
    score += 120.0 * coupling;

    // Reward tight fits (near-zero post residual) increasingly over time
    let tightness = (1.0 - prn).powi(2);
    score -= 25.0 * tightness * (0.5 + progress);

    // Last-chance bonus: strongly favor the only bin that can fit
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Lookahead: penalize leaving a residual that cannot fit the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += 15.0 * (1.0 - pr / nxt) * (0.5 + progress);
        } else {
            score -= 8.0 * (1.0 - (pr - nxt) / cap);
        }
    }

    // New-bin candidate: keep it competitive early, discourage late
    if bin_residual == bin_capacity {
        score = cap - 40.0 * (1.0 - progress) + 30.0 * progress
            + 10.0 * (open_bins_count as f64 / (1.0 + total_items as f64));
    }

    // Mild penalty when bin residual deviates from mean residual (fragmentation)
    score += 0.05 * ((pr - mean_residual) / cap).abs() * cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into small
    // "dead zones" (<= 10) are perfectly sealed; reward them strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 40.0;
    } else {
        // Penalize residuals in awkward mid-range bands using integer division.
        let band = post_residual / 15; // 0..=6 harmonic band
        score += band as f64 * 6.0;
    }

    // Lookahead: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Perfect harmonic match: reward, stronger when residual is tight.
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 - slack * 0.5;
        } else {
            // Next item cannot follow: penalize proportionally to overshoot.
            let over = (next_item_size - post_residual) as f64;
            score += over * 0.8;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so new bins are not opened casually.
        score += 20.0;
        // If current bin is the only fitting one, make new bin unattractive.
        if fitting_bins_count <= 1 {
            score += 40.0;
        }
        // If mean residual across open bins is large, opening a new bin is fine.
        if mean_residual > 60.0 {
            score -= 15.0;
        }
        // Late in the stream, prefer closing out existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Mild preference for tighter existing bins (lower residual before placing).
    score += (bin_residual as f64) * 0.05;

    // Slight penalty when many bins are open, to encourage consolidation.
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins with small post_residual
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tight * tight;

    // Penalize unusable dead space: post_residual too small for the smallest plausible item
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 100.0;
    }

    // Open-bin pressure: discourage opening new bins when open bins can fit
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 25.0 + 2.0 * open_bins_count as f64;
        if fitting_bins_count > 0 {
            score += 15.0;
        }
    } else if fitting_bins_count == 1 {
        // last-chance bin: strongly favor using it
        score -= 30.0;
    }

    // Lookahead: if next item fits exactly into post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap < 10 {
            score -= 50.0;
        } else {
            score -= 10.0 * (1.0 - gap as f64 / bin_capacity as f64);
        }
    }

    // Mild preference for filling bins with larger residuals (consolidate space)
    score -= 0.05 * bin_residual as f64 * (1.0 - (post_residual as f64 / bin_capacity as f64));

    // Mean-residual coupling: prefer bins deviating favorably from mean residual
    score += 0.1 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score += (1.0 - fit_ratio) * 20.0;

    // 2-step lookahead: reward bins whose post_residual can host the next item exactly-ish.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        // Perfect chain (post_residual == next_item_size) gets a big bonus.
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item cannot fit here: this dead space is likely wasted; penalize
        // proportionally to how close we came (near-miss is worst).
        let miss = (next_item_size - post_residual) as f64;
        score += 8.0 * (1.0 - miss / bin_capacity as f64);
    }

    // Penalize leaving residuals that are small and unusable relative to mean residual.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }
    score += (post_residual as f64 - mean_residual).abs() * 0.1;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: neutral-ish baseline, slightly worse than a good fit
    // but better than a poor fit. Scale with stream progress (late stream:
    // consolidate more aggressively).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score = 45.0 - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream: early on, be conservative; late, fill greedily.
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Reward tight fits: dead space below a threshold is penalized super-linearly.
    let dead = post_residual as f64;
    if dead > 0.0 {
        score += 0.35 * (dead / 10.0).powf(1.6);
    } else {
        score -= 25.0; // perfect fit bonus
    }

    // Lookahead: if next item fits exactly in the post residual, strong reward.
    if next_item_size > 0 {
        if (post_residual as u32) == next_item_size {
            score -= 18.0;
        } else if post_residual >= next_item_size {
            score -= 6.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize small post residuals more as stream progresses.
            score += 4.0 + 8.0 * progress;
        }
    } else {
        // Last item: just minimize waste.
        score = post_residual as f64;
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Coupling with global state: many open bins with high mean residual -> prefer
    // consolidating into bins with below-average residual (fill the emptiest-feeling bins).
    if bin_residual as f64 > mean_residual {
        score += 0.08 * (bin_residual as f64 - mean_residual);
    } else {
        score -= 0.05 * (mean_residual - bin_residual as f64);
    }

    // When many bins are open, discourage opening new bins unless this one is empty.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // New bin attractive when open bins are crowded or residual is tiny.
        score += (open_bins_count as f64) * 1.2 - 0.15 * mean_residual;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // new bin reserves space for a big next item
        }
    } else {
        score -= 2.0; // mild preference for reusing open bins
    }

    // Late-stream urgency: squeeze items into existing bins.
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    let fit = item_size as f64 / cap;
    let nxt = next_item_size as f64 / cap;

    let mut score = pr;

    // smooth non-linear coupling of post_residual with stream progress
    let coupling = pr_norm * pr_norm * (1.0 + progress);
    score += 40.0 * coupling;

    // reward tight fits, stronger later in the stream
    score -= 25.0 * (1.0 - pr_norm) * (1.0 - pr_norm) * (0.5 + progress);

    // penalize dead space relative to mean residual
    score += 0.3 * (pr - mean_residual).abs() * (1.0 + progress);

    // lookahead: reward bins whose post residual can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 * nxt * (1.0 - pr_norm);
    } else if next_item_size > 0 {
        score += 10.0 * nxt;
    }

    // last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0 + 30.0 * progress;
    }

    // mild preference for consolidating into fewer bins
    score -= 2.0 / (1.0 + open_bins_count as f64);

    // new-bin candidate: penalize slightly unless current bins are very fragmented
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * (1.0 - progress) - 8.0 * (mean_residual / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual after placement: bins whose post_residual
    // falls into "usable" classes (multiples of small harmonics) are preferred.
    let pr = post_residual;
    if pr == 0 {
        // Perfect fit: strongly reward.
        score -= 60.0;
    } else if pr % 10 == 0 {
        // Residual in the same harmonic class as typical item sizes -> reusable.
        score -= 12.0;
    } else if pr % 5 == 0 {
        score -= 6.0;
    } else if pr < 10 {
        // Dead space below the minimum item size: penalize hard.
        score += 25.0;
    }

    // Integer-division threshold: classify post_residual into capacity fractions.
    let quarter = bin_capacity / 4; // 25
    let half = bin_capacity / 2;    // 50
    if pr >= half {
        score -= 8.0; // plenty of room left, keep bin attractive
    } else if pr >= quarter {
        score += 0.0;
    } else if pr > 0 {
        score += 5.0; // cramped bin, mildly penalize
    }

    // Lookahead coupling: if the next item fits exactly into the post_residual,
    // reward strongly (harmonic pairing of consecutive items).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size <= pr {
            // Next item fits; reward proportional to how snugly.
            score -= 10.0 * (next_item_size as f64 / pr.max(1) as f64);
        } else {
            // Next item won't fit here: penalize small residuals a bit more.
            score += 4.0 * (pr as f64 / bin_capacity as f64);
        }
    }

    // Last-chance logic: if this is the only bin that fits, prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when no
    // open bin fits well, or the stream is early and we want many bins.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 20.0;
        // Early in the stream, opening bins is cheaper (builds flexibility).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 18.0 * (1.0 - progress);
        // If many bins already fit the item, discourage a new one.
        if fitting_bins_count > 2 {
            score += 10.0 * (fitting_bins_count as f64 - 2.0);
        }
        // If the current item would leave a bad residual elsewhere, a fresh
        // bin is fine (its post_residual = capacity - item_size is clean).
        if item_size % 10 == 0 {
            score -= 6.0;
        }
    }

    // Slight preference for bins tighter than the mean residual (good packing).
    score += 0.05 * (mean_residual - bin_residual as f64);

    // Mild pressure against accumulating many open bins.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps of 1..=9 are almost unusable (min item ~10)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // heavy penalty for creating unusable slivers
    }
    // Moderate penalty for medium-waste gaps that next item likely can't use
    if post_residual >= 10 && next_item_size > 0 && post_residual < next_item_size {
        score += 12.0;
    }

    // Reward exact / near-perfect fits
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits into the resulting residual, reward it
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 8.0 + 0.1 * slack;
    }

    // Last-chance pressure: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor tight packing
    score += 0.35 * open_bins_count as f64;

    // Prefer bins tighter than average (below-mean residual = fuller bin)
    score += 0.25 * (mean_residual - bin_residual as f64);

    // New-bin candidate handling: opening a fresh bin should generally lose
    // unless it produces a large usable residual while existing fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, decaying as stream progresses
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 45.0 - 15.0 * progress;
        // If no existing bin can take the item, new bin is fine
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
        // If next item is large, a fresh bin with big residual is valuable
        if next_item_size > 0 && post_residual >= next_item_size + 20 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong penalty for large dead space: post_residual that can never be filled
    // by typical items (>= 10) is nearly unusable.
    if post_residual < 10 && post_residual > 0 {
        score += 40.0;
    }

    // 2-step lookahead: reward perfect chaining with the next item.
    if next_item_size > 0 {
        let look = next_item_size as f64;
        if (post_residual as f64 - look).abs() < 0.5 {
            // Exact fit for the next item: excellent.
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item still fits after this placement.
            score -= 15.0;
        } else {
            // Next item won't fit here: dead space risk grows with gap.
            let gap = (post_residual as f64 - look).abs();
            score += 0.8 * gap;
        }
    }

    // Reward tight fits of the current item.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 10.0 * tightness;

    // Prefer bins with residuals below the mean (compact bins get filled first),
    // penalize wasting high-residual bins when others exist.
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate: make it unattractive early on, more acceptable when many
    // bins are open and fits are poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = bin_capacity as f64 * (1.0 + 0.5 * (1.0 - progress)) - 5.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward low post_residual non-linearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 6.0 * fit_ratio * fit_ratio;

    // Penalize post_residual that is small but unusable (dead space below min item size ~1..100 unknown, assume ~10).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly in post_residual, reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual >= next_item_size {
            score -= 12.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; slight penalty for wasting post_residual
            score += 4.0 * next_item_size as f64 / bin_capacity as f64;
        }
    }

    // Prefer fuller bins when many bins are open (consolidation pressure).
    score -= (bin_residual as f64 / bin_capacity as f64) * (open_bins_count as f64).ln().max(0.0) * 3.0;

    // Global mean residual coupling: if this bin's residual is far below mean, it's an outlier worth filling.
    let dev = mean_residual - bin_residual as f64;
    score += 0.15 * dev;

    // Time horizon: early in stream, be more willing to open new bins (penalize tight fills less);
    // late in stream, consolidate aggressively.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= t * 5.0 * (1.0 - fit_ratio);

    // Slight penalty for opening a brand-new bin when decent alternatives exist.
    if bin_residual == bin_capacity {
        score += 8.0 + 0.05 * open_bins_count as f64;
        // but if next item is large and no bin will fit both, opening may be wise: soften penalty
        if next_item_size > 0 && bin_residual >= item_size + next_item_size {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post residual (tight fit), with smooth non-linear shaping
    let mut score = pr + 40.0 * norm_pr * norm_pr;

    // Late in the stream, dead space becomes more costly: amplify tightness reward
    score -= 25.0 * (1.0 - norm_pr) * progress * progress;

    // Perfect-fit bonus (post_residual near zero), smooth via Gaussian-like term
    score -= 30.0 * (-(pr * pr) / 60.0).exp();

    // Penalize bins whose residual is far from mean residual (fragmentation avoidance)
    let dev = (pr - mean_residual) / cap;
    score += 20.0 * dev * dev;

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: reward residual that can host the next item exactly or well
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr >= ns {
            let gap = pr - ns;
            score -= 18.0 * (-(gap * gap) / 80.0).exp();
        } else {
            score += 6.0 * (ns - pr) / cap;
        }
    }

    // Mild penalty when many bins are open (encourage consolidation)
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals in fine-grained
    // classes (small modulo buckets) are more likely reusable later.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Penalize dead space in coarse classes (harmonic thirds / quarters).
    let third = post_residual % (bin_capacity / 3);
    let quarter = post_residual % (bin_capacity / 4);
    score += (third as f64) * 0.15 + (quarter as f64) * 0.10;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 30.0;
    }

    // Harmonic class via integer division: small quotient buckets of 10.
    let bucket = post_residual / 10;
    score += bucket as f64 * 2.0;

    // Lookahead: reward if next item fits the post residual exactly or well.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= (10.0 - (slack as f64).min(10.0)) * 3.0;
            // Perfect chain fit bonus
            if slack == 0 { score -= 40.0; }
        } else {
            // Next item cannot use leftover: penalize proportionally.
            score += (next_item_size as f64) * 0.2;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // New-bin candidate: only attractive when current bins are tight/crowded.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = mean_residual / cap;
        score += 120.0;
        score -= pressure * 150.0;
        score -= (open_bins_count as f64) * 1.5;
        score += progress * 20.0;
        // If the item is large, a fresh bin is more attractive.
        score -= (item_size as f64) * 0.3;
    }

    // Mild preference for filling bins with larger residual (waste less).
    score -= (bin_residual as f64) * 0.05;

    // Tight-fit reward: item fills most of the bin.
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill * 15.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10) are heavily penalized
    let dead_threshold = 9u32;
    if post_residual > 0 && post_residual < dead_threshold {
        score += 60.0 * (dead_threshold - post_residual) as f64;
    }
    if post_residual == 0 {
        // perfect fit: strong reward
        score -= 40.0;
    }

    // Reward tight fits relative to bin residual
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill_ratio;

    // Penalize bins whose residual is much larger than the item (wasteful placement)
    if bin_residual > item_size + dead_threshold {
        score += 0.35 * (bin_residual - item_size - dead_threshold) as f64;
    }

    // Open-bin pressure: more open bins -> prefer consolidating into existing bins
    score += 0.8 * open_bins_count as f64;

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when item barely fits any open bin
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.35 * (1.0 - fill_ratio) };
        score -= 55.0 * pressure;
        // late in stream, opening new bins is costlier
        score += 10.0 * (step_index as f64 / total_items.max(1) as f64);
    }

    // Lookahead: favor bins whose post-residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 8.0;
        }
    }

    // Mean-residual coupling: bins far below mean residual are already tight; prefer them
    score += 0.25 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit bonus: reward tight packing heavily.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // 2-step lookahead: if the next item fits exactly into the post-residual,
    // this bin becomes perfect after two placements — strongly reward.
    if next_item_size > 0 && post_residual > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs();
        if diff == 0 {
            score -= 55.0;
        } else if diff <= 5 {
            score -= 20.0;
        } else {
            // penalize leaving residue that the next item cannot use well
            score += diff as f64 * 0.35;
        }
        // Bonus if next item is small relative to post-residual (still usable)
        if next_item_size < post_residual {
            score -= 3.0;
        }
    }

    // Relative to mean residual: prefer bins with residual below mean (tighter bins)
    score += (post_residual as f64 - mean_residual) * 0.5;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when no
    // open bin fits well. Penalize new bins mildly so existing good fits win,
    // but if the item is large relative to mean residual, allow it.
    if bin_residual == bin_capacity {
        let waste = (bin_capacity - item_size) as f64;
        let mut nb = waste * 0.4;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            nb -= 10.0; // next item can also go into the fresh bin
        }
        if fitting_bins_count == 0 {
            nb -= 40.0; // nothing fits elsewhere; new bin is fine
        } else {
            nb += 15.0; // discourage abandoning open bins that fit
        }
        // Late in the stream, prefer closing out bins rather than opening new
        let progress = step_index as f64 / total_items.max(1) as f64;
        nb += progress * 8.0;
        score += nb;
    }

    // Small general penalty for large leftover space (dead space creation)
    score += (post_residual as f64).powi(2) * 0.002;

    // Mild preference to fill bins that are already quite full
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= fill_ratio * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post-residual) with a nonlinear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful for typical items,
    // but allow small residuals that could pair with small lookahead items.
    if post_residual > 0 {
        let dead = post_residual as f64;
        let useful = if next_item_size > 0 {
            (next_item_size as f64 <= dead) as f64
        } else { 0.0 };
        if useful < 0.5 && dead < 25.0 {
            score += 12.0 * (25.0 - dead) / 25.0;
        }
    }

    // Lookahead coupling: if the next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > post_residual && next_item_size > 0 {
        score += 6.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        // With multiple options, mild penalty to keep discrimination sharp.
        score += 1.5 * (fitting_bins_count as f64 - 1.0).ln().max(0.0);
    }

    // New-bin candidate handling: opening a bin is only attractive when open bins
    // are heavily fragmented or this is a huge item with poor fits elsewhere.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual - bin_residual as f64).abs();
        // Prefer new bin when mean residual is large (open bins are full-ish)
        // and item is large; penalize early-stream new bins.
        score += 10.0 + 25.0 * (1.0 - progress) - 0.15 * mean_residual
                 + 0.2 * item_size as f64 - 2.0 * fragmentation.min(50.0);
        if open_bins_count == 0 {
            score -= 100.0; // must open the very first bin
        }
    }

    // Mild global pressure: many open bins -> consolidate, favor using existing space.
    score += 0.05 * open_bins_count as f64;

    // Time-horizon modulation: late in the stream, squeeze harder.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 8.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    // smooth non-linear polynomial coupling of post_residual with stream progress
    let pn = pr / cap;
    let poly = pn * pn * (1.0 - progress) + pn * progress * progress;
    score -= 12.0 * poly;
    // penalize large dead space more strongly as stream progresses
    score += 0.05 * pr * pr / cap * (0.5 + progress);
    // reward tight fits (small post residual)
    if post_residual < item_size {
        score -= 6.0 * (1.0 - pr / cap);
    }
    // last chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }
    // lookahead: favor bins whose leftover can hold next item
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 4.0 * (next_item_size as f64 / cap);
    }
    // discourage opening new bins when open bins are mostly empty
    if bin_residual == bin_capacity {
        score += 5.0 * (mean_residual / cap) + 0.02 * open_bins_count as f64;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: bins whose post_residual falls in
    // "usable" residue classes (multiples of 10, small residues) are preferred.
    let cls = (post_residual % 10) as f64;
    score += cls * 0.8; // penalize off-class residue (dead space granularity)

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Small leftovers that can still host typical small items are valuable.
    if post_residual >= 1 && post_residual <= 10 {
        score -= 12.0;
    }

    // Integer-division thresholds on post_residual: leftovers below 20 are
    // nearly dead space for items >= 20; penalize mildly, but keep tiny ones.
    if post_residual > 10 && post_residual < 20 {
        score += 8.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            score -= 15.0;
        } else {
            // next item cannot use this bin; leftover is more likely dead
            score += 6.0;
            // harmonic class match between leftover and next item size
            if next_item_size % 10 == post_residual % 10 && post_residual > 0 {
                score -= 5.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: prefer it only when it beats all open bins' waste.
    if bin_residual == bin_capacity {
        score = (bin_capacity as f64) * 0.5
            + (open_bins_count as f64) * 0.3
            - (next_item_size as f64) * 0.1;
        if fitting_bins_count == 1 {
            score += 40.0; // don't open new bin if an open bin is last chance
        }
        if post_residual == bin_capacity && next_item_size > 0 && next_item_size >= 60 {
            score -= 10.0; // big item: fresh bin is fine
        }
    }

    // Stream progression: late in stream, consolidate more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (mean_residual - post_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // for typical items are heavily penalized dead space.
    if post_residual > 0 {
        if post_residual < 10 {
            // Unusable sliver: near-total waste of this bin.
            score += 60.0;
        } else if post_residual < 20 {
            score += 25.0;
        } else if post_residual < 30 {
            score += 8.0;
        }
    } else {
        // Perfect fit: close the bin, no dead space at all.
        score -= 40.0;
    }

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 15.0 * tightness * tightness;

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bins pressure: with many open bins, prefer consolidating into
    // existing bins rather than spreading out.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.05 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Lookahead: if the next item fits exactly into the post_residual,
    // reward this placement strongly (chained fit).
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap < 10 {
            score -= 25.0;
        } else {
            score -= 8.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Post-residual cannot host the next item: mild dead-space penalty.
        score += 5.0;
    }

    // New-bin candidate: only attractive when current bins have large
    // unusable residuals or the item would leave heavy dead space.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 35.0;
        // More attractive when existing bins are cluttered (high mean residual
        // means poor consolidation potential).
        score -= 0.2 * mean_residual;
        // Attractive early when few bins are open and item is large.
        if open_bins_count <= 2 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual), with a mild non-linear penalty
    // on very small residuals that are likely unusable dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 4.0; // tiny unusable slivers are wasted capacity
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect chaining: residual exactly matches next item -> strong reward.
            let gap = post_residual - next_item_size;
            score -= 8.0;
            score -= (gap == 0) as i32 as f64 * 6.0;
            // smoother coupling: closer match is better
            score -= 4.0 * (1.0 - gap as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize proportionally to the overshoot,
            // scaled by stream progress (late in stream, dead space hurts more).
            let overshoot = (next_item_size - post_residual) as f64;
            let progress = step_index as f64 / total_items.max(1) as f64;
            score += 0.08 * overshoot * (0.5 + progress);
        }
    }

    // Relative-to-mean coupling: bins with residual far below mean are already
    // "cramped"; placing here concentrates packing and is generally good,
    // but leaving a bin near-empty while others are cramped is bad.
    let residual_f = bin_residual as f64;
    if mean_residual > 0.0 {
        let rel = residual_f / mean_residual;
        if rel > 1.5 {
            score += 2.0 * (rel - 1.5).min(2.0); // avoid spreading into fat bins when others are tight
        } else if rel < 0.7 {
            score -= 2.0 * (0.7 - rel); // favor filling the tightest bins
        }
    }

    // Last-chance bonus: if this is the ONLY bin that fits, strongly prefer it
    // over opening a new bin (unless the new-bin candidate is genuinely better).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 5.0;
        // Extra urgency late in the stream: fewer new bins desired.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 3.0 * progress;
    }

    // New-bin candidate handling: penalize opening a new bin unless the item is
    // large and current bins would be left with tiny unusable residuals.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin: its full future value.
        score += 12.0;
        // Large items pack better in fresh bins.
        score -= (item_size as f64 / 100.0) * 10.0;
        // If no existing bin fits well (many fitting bins means alternatives exist),
        // opening a new bin is more acceptable when alternatives are scarce.
        if fitting_bins_count == 0 {
            score -= 6.0;
        }
        // Early in the stream, opening bins is cheaper (more items to fill them).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 8.0 * (1.0 - progress);
        // Lookahead: if next item is large too, a fresh bin enables pairing.
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 4.0;
        }
    }

    // Mild preference for keeping the number of open bins low.
    score += (open_bins_count as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, penalize dead space relative to smallest item scale
    let min_scale = 1.0f64;
    score += (post_residual as f64 / (bin_capacity as f64)).powi(3) * 40.0;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual < 10 {
        score -= 60.0;
    }

    // Lookahead: reward if next item fits the post-residual exactly-ish
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize leaving large unusable gaps
            score += 15.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: only attractive when open bins are fragmented
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual - post_residual as f64).abs();
        // open a new bin if mean residual is small (open bins are nearly full)
        // or late in the stream where tight packing matters
        score += 25.0 + mean_residual * 0.5 + fragmentation * 0.3 - progress * 20.0;
        if open_bins_count == 0 {
            score -= 1000.0; // must use a bin
        }
    } else {
        // Prefer fuller bins among open ones
        score -= (bin_capacity - bin_residual) as f64 * 0.6;
        // Slight penalty for spreading across many bins when mean residual is high
        score += open_bins_count as f64 * 0.15;
    }

    // Global state coupling: when mean residual is low, conserve remaining space
    score += mean_residual * 0.2 * (post_residual as f64 / bin_capacity as f64);

    // Time horizon: early stream, be flexible; late stream, pack tight
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * (1.0 - progress);

    let _ = min_scale;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    let item_norm = item_size as f64 / cap;

    // Smooth polynomial coupling of post_residual with stream progress.
    let mut score = pr
        + 18.0 * pr_norm * pr_norm * (1.0 + progress)
        - 10.0 * item_norm * (1.0 - progress) * (1.0 - pr_norm)
        + 8.0 * (pr_norm - 0.3) * (pr_norm - 0.3) * progress;

    // Reward tight fits more strongly as the stream progresses.
    score -= (1.0 - pr_norm) * (1.0 - pr_norm) * 25.0 * (0.4 + 0.6 * progress);

    // Last-chance bin bonus.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Penalize wasted residual relative to mean residual (dead space).
    score += 6.0 * (pr - mean_residual) / cap * (1.0 + progress);

    // Lookahead: favor bins whose post_residual can host the next item.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 5.0 * (1.0 - (pr - next_item_size as f64) / cap);
    } else if next_item_size > 0 {
        score += 3.0;
    }

    // Mild penalty for spreading across too many open bins early on.
    score += (open_bins_count as f64).ln() * 2.0 * (1.0 - progress);

    // New-bin candidate: penalize mildly unless current residual is large.
    if bin_residual == bin_capacity {
        score += 20.0 - 15.0 * pr_norm;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: residues modulo 10 / 16 / 32
    let r = post_residual;
    if r > 0 {
        // Dead-space penalty: residual too small for typical items (1..100, mean ~50)
        if r < 10 {
            score += 60.0; // unusable sliver
        } else if r < 25 {
            score += 25.0;
        }
        // Modulo-16 classes: residuals in [16,32) are semi-usable
        let class = (r / 16) as f64;
        score -= class * 4.0;

        // Modulo-32 harmonic: reward residuals that are multiples of 16
        if r % 16 == 0 && r > 0 {
            score -= 12.0;
        }
        if r % 32 == 0 && r > 0 {
            score -= 8.0;
        }
    }

    // Pairing with lookahead item (k=2): reward exact or near fit for next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual > next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            if gap < 10.0 {
                score -= 80.0;
            } else if gap < 25.0 {
                score -= 30.0;
            }
            // fraction of next item absorbed by this bin's future residual
            score -= (next_item_size as f64 / post_residual as f64) * 20.0;
        } else {
            // next item cannot fit here; residual will be dead-ish
            score += 15.0;
        }
    } else {
        // Last item: minimize residual maximally
        score -= 50.0;
    }

    // Last-chance bin: strong penalty for opening a new bin when only this fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: only prefer fresh bin when open bins are crowded
    if bin_residual == bin_capacity {
        let crowded = mean_residual / bin_capacity as f64;
        if fitting_bins_count > 0 && crowded < 0.35 {
            score += 120.0; // open bins still roomy -> discourage new bin
        } else if crowded < 0.15 {
            score += 60.0;
        } else {
            score -= 20.0; // crowded stream -> fresh bin is fine
        }
    }

    // Mild stream-phase modulation
    let phase = step_index as f64 / (total_items.max(1) as f64);
    score -= phase * 5.0;

    // Tie-break: prefer bins with below-mean residual (denser bins)
    score += (bin_residual as f64 - mean_residual) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=9) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 - 2.0 * post_residual as f64;
    }
    // Perfect or near-perfect fits are strongly rewarded.
    if post_residual == 0 {
        score -= 20.0;
    } else if post_residual <= 5 {
        score -= 5.0;
    }

    // Coupling with lookahead: if the next item fits exactly in the post_residual,
    // this placement sets up a perfect follow-up.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 15.0;
        } else if post_residual > next_item_size && post_residual - next_item_size < 10 {
            score -= 6.0;
        } else if post_residual > 0 && next_item_size > post_residual {
            // next item cannot use this gap: dead space is locked in
            score += 8.0 + 0.3 * post_residual as f64;
        }
    }

    // Open-bin pressure: prefer filling existing bins when many are open.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.4 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Mean-residual alignment: bins far below mean residual are wasteful to top up lightly.
    let dev = mean_residual - post_residual as f64;
    if dev > 0.0 {
        score += 0.15 * dev;
    }

    // New-bin candidate calibration: only allow opening a new bin when the current
    // bin would leave a large locked gap and many bins are already open.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.55 + 0.3 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * fit_ratio * fit_ratio;

    // 2-step lookahead: reward when next item fits the post residual exactly-ish.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // Perfect chain (post_residual == next_item_size) is ideal.
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
            score -= 10.0 * slack / bin_capacity as f64; // still mild reward for any chain
        } else {
            // Next item won't fit here: penalize dead space.
            score += 12.0;
        }
    } else {
        // Last item: just minimize post residual.
        score += 5.0 * fit_ratio;
    }

    // Compare post_residual against mean residual: avoid leaving more than average
    // unless it's a very tight fit.
    if post_residual as f64 > mean_residual {
        score += 0.5 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.3 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the
    // current item would leave a large unusable gap in every existing bin.
    if bin_residual == bin_capacity {
        // Neutral base for a fresh bin; slightly worse than a decent existing fit.
        score = bin_capacity as f64 * 0.75;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            // Room for the next item in a fresh bin: make it competitive.
            score -= 15.0;
        }
        if fitting_bins_count <= 1 {
            // No real alternative: new bin is fine.
            score -= 35.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post-residual) non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that no plausible future item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0; // tiny unusable slivers
    }

    // Lookahead coupling: bonus if next item fits exactly into post-residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot follow here: mild penalty scaled by overflow
            let over = (next_item_size - post_residual) as f64;
            score += 0.15 * over;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Time horizon: early in the stream, be pickier (keep bins flexible);
    // late in the stream, prioritize closing bins out.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 8.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    // Global state: when many bins are open, discourage opening new ones.
    let new_bin = (bin_residual == bin_capacity) as i32 as f64;
    score += new_bin * (6.0 + 1.5 * open_bins_count as f64);

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it's a laggard bin — prefer filling it to consolidate.
    let dev = mean_residual - bin_residual as f64;
    score += 0.08 * dev;

    // Small jitter-free tiebreak on exact fills.
    if post_residual == 0 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit_frac = it / cap;

    // Base: prefer tight fits (low post_residual), scaled non-linearly
    let mut score = pr * (1.0 + 0.8 * fit_frac * fit_frac);

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, waste tolerance is higher; later, punish residuals harder.
    let p2 = progress * progress;
    let p3 = p2 * progress;
    score += pr * (0.5 * p2 + 1.2 * p3);

    // Penalize residuals that are too small to be useful (dead space),
    // smoothly via a quadratic bump around small residuals.
    let dead = (cap * 0.15 - pr).max(0.0);
    score += 2.0 * dead * dead / cap;

    // Last-chance bonus: strongly reward using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 6.0 + 10.0 * (1.0 - fit_frac);
    }

    // Lookahead: if next item fits the post residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 3.0;
    } else if next_item_size > 0 {
        // Next item won't fit here: mild penalty proportional to overshoot.
        let over = (next_item_size as f64 - pr) / cap;
        score += 1.5 * over;
    }

    // Slight preference for bins already diverging from mean residual
    // (consolidate waste): reward bins with residual below mean.
    let dev = mean_residual - pr;
    score -= 0.05 * dev;

    // New-bin candidate handling: make empty bin attractive only when
    // current item is large or stream is early.
    if bin_residual == bin_capacity {
        score = cap - it + 4.0 * p2 * cap;
        if fitting_bins_count == 1 {
            score += 8.0; // discourage opening new bin when one bin fits
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: prefer residuals that other items can fill.
    // Class A: post_residual divisible by small sizes (10/20/25/50) -> very reusable.
    let pr = post_residual;
    let mut bonus = 0.0;

    if pr == 0 {
        bonus -= 60.0; // perfect fit
    } else if pr <= 10 {
        bonus -= 40.0; // nearly perfect, minimal dead space
    } else {
        // modularity of residual with common item sizes
        if pr % 10 == 0 { bonus -= 25.0; }
        if pr % 20 == 0 { bonus -= 15.0; }
        if pr % 25 == 0 { bonus -= 15.0; }
        if pr % 50 == 0 { bonus -= 10.0; }

        // integer-division thresholds on residual size classes
        let q = pr / 10; // harmonic band 0..10
        match q {
            1 => bonus -= 12.0,           // 10..19: fillable by small items
            2 => bonus -= 6.0,            // 20..29
            3 | 4 => bonus -= 2.0,        // 30..49: moderate
            5 | 6 => bonus += 8.0,        // 50..69: awkward mid residual
            7 | 8 => bonus += 14.0,       // 70..89: large residual, prefer new item elsewhere
            _ => bonus += 20.0,           // 90..99: nearly empty bin
        }
    }

    // Lookahead: if next item fits in post_residual, reward strongly.
    if next_item_size > 0 && next_item_size <= pr {
        let tight = (pr - next_item_size) as f64;
        bonus -= 18.0 + 12.0 * (1.0 - tight / bin_capacity as f64);
    }
    // Penalize if next item just barely misses (dead space trap)
    if next_item_size > pr && next_item_size > 0 && next_item_size <= bin_residual {
        bonus += 6.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        bonus -= 30.0;
    } else if fitting_bins_count > 1 {
        // competition: mildly favor tighter fits among many candidates (already via post_residual)
        bonus += 2.0 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate handling: only open a new bin when current residuals are poor.
    if bin_residual == bin_capacity {
        // base cost of opening a bin
        score += 55.0;
        // open new bin early in stream or when mean residual is fragmented
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
        if mean_residual < 25.0 { score -= 15.0; } // open bins are nearly full anyway
        if pr >= bin_capacity - 1 { score -= 5.0; } // empty bin is the natural place for big items
    }

    // Slight preference for fuller bins overall (best-fit baseline sharpening)
    score -= 0.05 * (bin_residual as f64);

    score -= bonus;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that can't fit any future item
    // (sizes 1..=100) are pure waste. Penalize small unusable gaps hard.
    if post_residual > 0 && post_residual < 10 {
        score += 200.0;
    } else if post_residual == 0 {
        // Perfect fit: strongly reward closing the bin.
        score -= 150.0;
    } else {
        // Penalize residual that cannot accommodate the lookahead item.
        if next_item_size > 0 && post_residual < next_item_size {
            score += 40.0 + (next_item_size - post_residual) as f64;
        } else if next_item_size > 0 && post_residual == next_item_size {
            score -= 30.0;
        }
    }

    // Reward tight fits (post_residual small relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 60.0 * tightness * tightness;

    // Last-chance bin: using it avoids opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidation
    // into existing bins over opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln() * (1.0 + progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open-bin pressure.
        score += 25.0 + 15.0 * pressure;
    } else {
        score -= 5.0 * pressure.min(8.0);
    }

    // Mild alignment with mean residual: bins below mean residual are
    // "fuller" and should be filled first to compact the waste.
    score += 0.15 * (mean_residual - bin_residual as f64).max(-50.0).min(50.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual)
    score -= (bin_capacity as f64 - post_residual as f64) * 0.5;

    // 2-step lookahead: if next item exactly fits post_residual, strongly reward
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    }
    // Next item fits into post_residual: mild reward
    else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
    }
    // Next item cannot fit into post_residual: penalize wasted space
    else if next_item_size > 0 {
        score += (next_item_size as f64 - post_residual as f64).min(20.0);
    }

    // Relative to mean residual: prefer bins with below-average residual (tighter bins)
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize creating tiny unusable dead space (< 10, min item size)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // New-bin candidate: penalize opening new bins unless current bin is a poor fit
    if bin_residual == bin_capacity {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual gets squared bonus)
    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tight * tight;

    // Penalize creating dead space that cannot fit the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if (post_residual as f64) < nx {
            // dead space for the lookahead item
            score += 12.0 + 0.25 * nx;
        } else {
            // residual can host the next item: reward proportionally
            score -= 8.0 * (1.0 - (post_residual as f64 - nx) / (bin_capacity as f64));
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Time-horizon modulation: early on, be more exploratory (favor new bins less);
    // late in the stream, prefer compacting into existing bins
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.5 * progress;

    // Global state coupling: many open bins with high mean residual -> discourage new bins
    if bin_residual == bin_capacity {
        // brand-new bin candidate
        let pressure = open_bins_count as f64 / (10.0 + mean_residual.max(0.0));
        score += 15.0 + 5.0 * pressure - 10.0 * progress;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 6.0; // new bin is good if a bigger item follows
        }
    } else {
        // prefer bins whose residual is close to the mean (balanced packing)
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.08 * dev;
    }

    // Mild penalty for very large items going into nearly full bins (fragmentation risk)
    if item_size > 60 && bin_residual < bin_capacity {
        score += 3.0 * (item_size as f64 / 80.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * (0.5 + 0.5 * progress);
    let mut score = pr + 20.0 * poly;
    // Penalize large dead space more strongly as stream progresses
    score += progress * 30.0 * norm_pr * norm_pr;
    // Reward tight fits
    score -= 15.0 * (1.0 - norm_pr);
    // Last-chance bin bonus: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }
    // Lookahead: penalize if next item cannot use the post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += 10.0 * (1.0 - pr / nxt.max(1.0));
        } else {
            score -= 5.0 * (pr - nxt) / cap;
        }
    }
    // Mild pressure against hoarding many open bins with large residuals
    score += (open_bins_count as f64).ln() * mean_residual * 0.05 * progress;
    // New-bin candidate handling: make empty bin moderately attractive only when
    // no open bin is a tight fit or it's early in the stream
    if bin_residual == bin_capacity {
        let early = 1.0 - progress;
        score = pr - 25.0 * early + 10.0 * progress;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: capacity fractions (eighths)
    let frac = (item_size * 8 + bin_capacity - 1) / bin_capacity; // ceil(item/C*8), 1..=8
    let next_frac = if next_item_size == 0 { 0 } else { (next_item_size * 8 + bin_capacity - 1) / bin_capacity };

    // Reward near-perfect fits strongly (best-fit core)
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 30.0;
    }

    // Dead-space penalty: residual too small for the smallest plausible item class
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item {
        score += 500.0;
    }

    // Harmonic pairing: reward when next item's class complements post_residual well
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            if gap == 0 {
                score -= 90.0;
            } else if gap <= 10 {
                score -= 25.0;
            } else {
                score += gap as f64 * 0.15;
            }
        } else {
            // next item won't fit here; penalize proportionally to wasted complementarity
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
        // modulo coupling: same harmonic class twice tends to tile perfectly
        if frac == next_frac && post_residual >= next_item_size {
            score -= 15.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else {
        // crowding: mild penalty when many bins compete
        score += fitting_bins_count as f64 * 1.5;
    }

    // New-bin candidate handling: only prefer fresh bin when existing fits are terrible
    if bin_residual == bin_capacity {
        // neutral base: fresh bin has full residual, so post_residual == capacity
        // subtract a small bonus so it loses against decent fits but wins over bad ones
        score -= 20.0;
        // late in stream, avoid spawning too many bins
        if open_bins_count > 4 {
            score += 25.0;
        }
    } else {
        // established bin: slight preference to keep using it
        score -= 5.0;
    }

    // Integer-division thresholds on post_residual: classify leftover sludge
    let leftover_class = post_residual / 10; // 0..=10 decile
    score += match leftover_class {
        0 => -10.0,          // 0-9: nearly full
        1 => 0.0,            // 10-19: usable
        2 => 5.0,
        3 => 10.0,
        _ => 15.0,           // large leftover: wasteful
    };

    // Mean residual coupling: if this bin is far below mean residual, it's the "junk" bin — use it
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score -= dev * 0.5;
    }

    // Stream progression: early on be conservative with new bins (handled above);
    // late stream, pack tighter
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // Any gap below the minimum item size (1) is dead by definition; gaps in
    // the 1..=12 range are likely dead for typical item sizes.
    if post_residual > 0 && post_residual <= 12 {
        score += 40.0 + (13 - post_residual as f64) * 3.0;
    }
    // Mid-range awkward gaps (13..=24) get a mild penalty.
    else if post_residual > 12 && post_residual <= 24 {
        score += 8.0;
    }

    // Perfect fits get a strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward leaving room for the lookahead item (k=2) if it would fit.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Gap is dead with respect to the next item: penalize extra.
        score += 10.0;
    }

    // New-bin candidate: penalize slightly so we prefer filling existing bins,
    // unless this is a last-chance situation (no other bin fits).
    if bin_residual == bin_capacity {
        if fitting_bins_count > 1 {
            score += 15.0;
        } else {
            score -= 5.0;
        }
    }

    // Open-bins pressure: when many bins are open, prefer consolidating into
    // bins with small residuals (tight packing); when few bins are open, be
    // more tolerant of spreading.
    let pressure = (open_bins_count as f64).ln().max(0.0) * 2.0;
    score += pressure * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins whose residual is already below average (they are the
    // tightest); slightly deprioritize bins far above mean residual.
    if (bin_residual as f64) > mean_residual + 20.0 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for a tight fit (small post residual).
    score += (post_residual as f64 / bin_capacity as f64) * 15.0;

    // 2-step lookahead: reward if the next item exactly fills the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chaining
        } else if next_item_size <= post_residual {
            // reward proportional to how well next item uses remaining space
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 25.0 * fill;
        } else {
            // next item cannot fit here; penalize large dead space
            score += 10.0 * (1.0 - (next_item_size - post_residual) as f64 / bin_capacity as f64);
        }
    }

    // Relative to mean residual: prefer bins with residual close to (or below) mean,
    // i.e. avoid wasting space in already-tight bins while draining loose bins.
    if post_residual as f64 > mean_residual {
        score += 0.5 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.3 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is huge
    // and would leave open bins too fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        let pressure = step_index as f64 / total_items.max(1) as f64;
        // open new bin if item is large and existing residuals are small/fragmented
        if item_size as f64 > 0.6 * bin_capacity as f64 && fragmentation < 0.35 {
            score -= 12.0 * pressure;
        } else {
            score += 25.0;
        }
    }

    // Mild penalty for too many open bins relative to progress.
    score += 0.05 * open_bins_count as f64 * (1.0 - step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer tight fits: reward small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // Next item won't fit here; penalize proportionally to wasted space.
            score += 0.3 * (next_item_size as f64 - post_residual as f64).min(40.0);
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits, to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        // With many options, prefer the tightest — mild extra pressure.
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate handling: empty bins get a moderate default so only
    // clearly bad fits in existing bins trigger opening a new bin.
    if bin_residual == bin_capacity {
        score += 15.0;
        // Late in the stream, be more willing to open new bins since
        // open bins' residuals are less likely to be useful later.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
    }

    // Global residual state: if mean residual across open bins is large,
    // there is slack available; prefer using existing bins more aggressively.
    score -= 0.15 * mean_residual;

    // Penalize proliferation of open bins slightly to consolidate packing.
    score += 0.5 * open_bins_count as f64;

    // Exact fill is perfect.
    if post_residual == 0 {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

