    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let residual_f = bin_residual as f64;
    let post_f = post_residual as f64;
    let item_f = item_size as f64;
    let next_f = next_item_size as f64;

    // Tightness reward: smooth quadratic coupling of post_residual (smaller is better).
    let tightness = (1.0 - post_f / cap).powi(3);
    score -= 18.0 * tightness;

    // Perfect-fit style reward when post_residual is near zero.
    score -= 25.0 * (-post_f * 0.35).exp();

