        score += 6.0 * (0.3 + 0.7 * progress);
    }

    // Last-chance bonus: this is the only bin that fits the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: encourage opening a new bin early or when
    // open bins are heavily fragmented (high mean residual).
    if bin_residual == bin_capacity {
        let fragmentation = if open_bins_count > 0 { mean_residual / cap } else { 0.0 };
        score -= 10.0 * fragmentation * fragmentation;
        score -= 15.0 * (1.0 - progress);
        // Discard the generic tightness term effect for empty bins: post == cap
        // so add back a neutral offset to keep it competitive.
        score += 18.0;
    } else {
        // Prefer bins below the mean residual (filling the emptiest bins first
        // is bad; filling tight bins keeps large residuals usable).
        if residual_f > mean_residual {
            score += 4.0 * (residual_f - mean_residual) / cap;
        }
    }

    // Mild pressure to consolidate as the stream nears its end.
    score -= 5.0 * progress * (1.0 - post_f / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic bonus for small post_residual
    if post_residual <= 10 {
        score -= 40.0;
    } else if post_residual <= 20 {
        score -= 20.0;
    }

    // Perfect fill
    if post_residual == 0 {
        score -= 60.0;
    }

    // Dead-space penalty: post residual too small for typical future items
    if post_residual > 0 && post_residual < 10 {
        score += 35.0;
    }

    // Harmonic classes: modulo structure on post_residual
    let pr_class = post_residual % 10;
    score -= match pr_class {
        0 => 12.0, // round residual, easy to pair later
        5 => 6.0,
        _ => 0.0,
    };

    // Integer-division thresholds: can next item fit here?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // lookahead fits: reward proportionally, stronger if exact
            score -= 8.0 + (post_residual - next_item_size) as f64 * 0.15;
            if post_residual == next_item_size {
                score -= 25.0; // chain of perfect fits
            }
        } else {
            // lookahead won't fit here: penalize wasting capacity on big holes
            score += (post_residual as f64) * 0.25;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Prefer fuller bins relative to mean residual (best-fit flavor)
    score += (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate: penalize mildly so it's chosen only when open bins are bad
    if bin_residual == bin_capacity {
        score += 15.0 + open_bins_count as f64 * 2.0;
        // but late in the stream, opening fresh is safer
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress > 0.8 {
            score -= 10.0;
        }
    }

    // Large item: prefer bin with residual close to item (avoid splitting capacity)
    if item_size >= bin_capacity / 2 {
        score += ((bin_residual as i64 - item_size as i64).unsigned_abs()) as f64 * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps hard.
    if post_residual > 0 {
        let gap = post_residual as f64;
        // Smallest possible future item is 1; treat gaps below a threshold as dead.
        // Non-linear: gap^2 scaled so tiny gaps are heavily punished relative to
        // a linear base, but perfect fits (gap == 0) stay at 0.
        score += (gap * gap) / (bin_capacity as f64 * 2.0);
        // Extra harsh penalty for "nearly full" bins left with a tiny sliver
        // that nothing can realistically use.
        if gap < 10.0 {
            score += 25.0 * (10.0 - gap);
        }
    }

    // Reward tight fits: item fills most of the bin.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Open-bins pressure: with many open bins, prefer consolidating into
    // existing bins rather than opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 / (mean_residual.max(1.0) / 10.0 + 1.0);
    score += 0.05 * pressure * (0.5 + progress);

    // New-bin candidate: empty bin must lose unless existing bins fit poorly.
    if bin_residual == bin_capacity {
        score += 15.0 + 0.3 * open_bins_count as f64;
        // If no open bin can fit except this one... new bin is the fallback anyway.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward
    // reserving that space (this placement keeps a useful gap).
    if next_item_size > 0 {
        if post_residual as u32 == next_item_size {
            score -= 18.0;
        } else if (post_residual as u32) < next_item_size && post_residual > 0 {
            // gap cannot host next item: penalize slightly more.
            score += 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 200.0;
    }
    // Near match: next item fits with small leftover
    if next_item_size > 0 && post_residual > next_item_size {
        let next_leftover = post_residual - next_item_size;
        if next_leftover <= 10 {
            score -= 80.0;
        } else if next_leftover <= 25 {
            score -= 30.0;
        }
    }
    // Penalize post_residual that cannot fit the next item (dead space for lookahead)
    if next_item_size > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // Dead space penalty: tiny unusable residuals
    if post_residual < 10 {
        score += 40.0;
    }

    // Last-chance bin bonus: only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Prefer bins tighter than average residual (good fill)
    score += (mean_residual - bin_residual as f64) * 0.5;

    // New-bin candidate: penalize mildly so we only open when open bins fit poorly
    if bin_residual == bin_capacity {
        score += 25.0 + 0.1 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: the smaller the post_residual relative to capacity, the better.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 2.5 * tightness * tightness * (item_size as f64);

    // Penalize small unusable dead space (< next_item_size) more strongly.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 0.6 * (next_item_size - post_residual) as f64;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 1.5;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: penalize opening a new bin, scaled by how well
    // existing bins could take the item and how fragmented the state is.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let fragmentation = if open_bins_count > 0 {
            mean_residual / bin_capacity as f64
        } else {
            0.0
        };
        // Opening a new bin is worse when existing residuals are large (item fits easily)
        score += 10.0 + 8.0 * fragmentation + 5.0 * (1.0 - progress);
        // But if the item is large relative to mean residual, opening a fresh bin is less bad.
        let size_ratio = item_size as f64 / bin_capacity as f64;
        score -= 6.0 * size_ratio * size_ratio;
        // If no other bin fits, opening a new bin is the only option: soften penalty.
        if fitting_bins_count == 0 {
            score -= 9.0;
        }
    }

    // Mild preference to fill bins with larger residual when many bins are open.
    score += 0.02 * (open_bins_count as f64) * (bin_residual as f64 / bin_capacity as f64);

    // Slight time-horizon coupling: later in the stream, be greedier about tight fits.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 3.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr_norm = pr / cap;
    let item_norm = item_size as f64 / cap;
    let next_norm = next_item_size as f64 / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let prog2 = progress * progress;
    let prog3 = prog2 * progress;
    let pr2 = pr_norm * pr_norm;
    let pr3 = pr2 * pr_norm;

    // Smooth interaction: tight fits rewarded more as stream progresses
    let tight = (1.0 - pr_norm).powi(3);
    score -= 30.0 * tight * (0.5 + prog2);

    // Penalize large dead space with cubic term, stronger early
    score += 40.0 * pr3 * (1.0 - 0.5 * prog3);

    // Cross term: post_residual vs item size coupling
    score += 8.0 * pr_norm * item_norm * (1.0 + progress);

    // Lookahead: reward if next item fits post residual (smooth via product)
    if next_item_size > 0 {
        let fits = (pr_norm - next_norm).max(0.0) / (1.0 + next_norm);
        score -= 15.0 * fits * fits * (0.3 + prog2);
        let gap = (pr_norm - next_norm).abs();
        score += 10.0 * gap * gap * (1.0 - progress);
    }

    // Mean residual deviation penalty (smooth quadratic)
    let dev = (pr - mean_residual) / cap;
    score += 12.0 * dev * dev;

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 + progress);
    }

    // Mild preference for filling existing bins over opening new ones
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * progress;
    } else {
        score -= 3.0 / (1.0 + open_bins_count as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fill_ratio * fill_ratio;

    // Dead-space penalty: residual after placement that is too small to hold
    // anything useful (harmonic classes: post_residual < 10-ish is dead space).
    let harmonic_class = post_residual / 10; // 0 = dead, 1 = tiny, ... capacity/10 classes
    if harmonic_class == 0 && post_residual > 0 {
        score += 25.0; // unusable sliver
    } else {
        // Reward post_residuals that align with common item-size classes (multiples of 10).
        if post_residual % 10 == 0 && post_residual > 0 {
            score -= 6.0;
        }
    }

    // Lookahead coupling: reward if next item fits exactly or well into post_residual.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 30.0; // perfect follow-up fit
        } else if next_item_size <= post_residual {
            let next_fit_ratio = next_item_size as f64 / post_residual as f64;
            score -= 12.0 * next_fit_ratio;
        } else {
            // Next item won't fit here; slightly penalize leaving large gaps that
            // encourage fragmentation.
            score += 4.0;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Only prefer it when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        // Penalize opening a new bin; escalate penalty as open bins grow.
        score += 15.0 + 2.0 * open_bins_count as f64;
        // But if the item is huge relative to mean residual space, new bin is fine.
        let mean_fill_gap = mean_residual - item_size as f64;
        if mean_fill_gap < 0.0 {
            score -= 25.0;
        }
    }

    // Mild pressure to consolidate into fewer bins as the stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 3.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        // A residual that cannot fit the smallest plausible item is pure waste.
        if post_residual < 10 {
            score += 40.0;
        } else if post_residual < 20 {
            score += 18.0;
        } else if post_residual < 30 {
            score += 6.0;
        } else {
            // Larger residuals are useful; reward them mildly.
            score -= 4.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }
    // If next item cannot fit here and residual is small, penalize.
    if next_item_size > 0 && post_residual < next_item_size && post_residual < 20 {
        score += 10.0;
    }

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let new_bin_bias = (open_bins_count as f64) * (0.5 + 0.5 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline offset so it only wins when fits are bad.
        score += 12.0 + new_bin_bias;
    }

    // Prefer bins tighter than the mean residual (better packing).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness;

    // Aggressive 2-step lookahead: strongly reward bins whose post_residual
    // can exactly or closely host the next item.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let gap = (post_residual - next_item_size) as f64;
            // Perfect chain (gap 0) is ideal: post_residual == next_item_size.
            score -= 25.0 * (1.0 - gap / bin_capacity as f64);
            if gap == 0.0 {
                score -= 15.0;
            }
        } else {
            // Next item won't fit here: penalize leaving a "trap" residual
            // that is too small for the next item but large enough to waste.
            let overflow = (next_item_size - post_residual) as f64;
            score += 0.35 * overflow;
        }
    } else {
        // Last item: just minimize post_residual.
        score -= 20.0;
    }

    // Compare against mean residual: placing into a bin with residual well
    // above mean balances the fleet; bins below mean are precious, protect them.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // no open bin offers a good fit (large post_residual / poor lookahead).
    if bin_residual == bin_capacity {
        let open_pressure = open_bins_count as f64;
        // Mild penalty so existing decent fits win; reduced late in the stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 18.0 - 6.0 * progress + 0.02 * open_pressure;
        // If the next item also fits perfectly in a fresh bin chain (item+next <= C),
        // make the new bin slightly more attractive.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity && post_residual == bin_capacity - item_size {
            score -= 5.0;
        }
    }

    // Dead-space penalty: residuals that are tiny (unusable) are fine,
    // mid-range residuals (e.g. 30-60) are the most wasteful.
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 25.0 {
        score -= 10.0 * (1.0 - pr / 25.0);
    } else if pr >= 25.0 && pr <= 60.0 {
        score += 8.0 * (1.0 - ((pr - 42.5).abs() / 17.5));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize (subtract) when post_residual is small relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Dead space penalty: residuals too small for the smallest plausible item are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Lookahead coupling: if the next item could fit exactly into the post-residual,
    // strongly reward this placement (chain fit).
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - chain / bin_capacity as f64);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot follow here; penalize mildly proportionally to wasted potential.
        score += 4.0 * (next_item_size as f64 / bin_capacity as f64);
    }

    // Last-chance bonus: only one bin can fit this item; avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Crowding pressure: when many bins are open, prefer consolidating into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let crowd = (open_bins_count as f64 / (1.0 + mean_residual.max(1.0) / 10.0)).min(10.0);
    score += 0.6 * crowd * (1.0 - progress);

    // Mean residual alignment: prefer bins whose residual is close to the mean (balanced use).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // New-bin candidate handling: an empty bin should only win when no open bin offers
    // a decent fit. Penalize opening a new bin, scaled by available alternatives.
    if bin_residual == bin_capacity {
        let alternatives = if fitting_bins_count > 1 { fitting_bins_count as f64 } else { 0.0 };
        let escape = if fitting_bins_count == 1 { 30.0 } else { 0.0 };
        score += 35.0 + 5.0 * alternatives - escape;
    }

    // Late-stream consolidation: as the stream ends, avoid opening bins.
    score += 8.0 * progress * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    // Base: post residual, mildly super-linear to punish dead space growth.
    let mut score = pr * (1.0 + 0.35 * norm_pr * norm_pr);

    // Smooth interaction: tight fits (small post_residual) are more valuable as stream progresses.
    let tightness = 1.0 - norm_pr;
    score -= 12.0 * tightness * tightness * (0.5 + progress);

    // Reward bins whose leftover can plausibly host the next item (smooth coupling).
    let next_fit = if norm_next > 0.0 { (norm_pr - norm_next).abs() } else { 0.0 };
    score -= 6.0 * (-next_fit * next_fit * 8.0).exp();

    // Penalize wasting a scarce bin when few bins can fit the item.
    let scarcity = 1.0 / (fitting_bins_count as f64);
    score -= 9.0 * scarcity * (0.4 + 0.6 * progress);

    // Dampen preference for bins close to mean residual (avoid herd behavior), smooth term.
    let dev = (mean_residual - pr) / cap;
    score += 3.0 * dev * dev;

    // Late-stream consolidation: favor filling existing bins over opening new ones.
    score += (1.0 - progress) * 4.0 * norm_pr - progress * 2.0 * tightness;

    // New-bin candidate penalty: opening a bin should be discouraged unless residual is huge.
    if bin_residual == bin_capacity {
        score += 10.0 + 15.0 * progress - 5.0 * norm_item;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: how well it decomposes into
    // common small item sizes (1..=100 stream). Residuals that are multiples
    // of common class sizes are more reusable.
    let r = post_residual;
    let class = |x: u32| -> f64 {
        if x == 0 { return -50.0; } // perfect fit, best possible
        // count divisibility by harmonic anchors
        let anchors: [u32; 6] = [10, 20, 25, 30, 40, 50];
        let mut h = 0.0;
        for (i, &a) in anchors.iter().enumerate() {
            if x % a == 0 {
                h += 6.0 - i as f64; // smaller anchors worth more (more items fit)
            }
        }
        h
    };
    score -= class(r);

    // Dead-space penalty: residual too small to fit anything typical
    if r > 0 && r < 10 {
        score += 40.0;
    }

    // Next-item lookahead coupling: reward residuals that leave room for
    // the known next item (k=2 lookahead).
    if next_item_size > 0 {
        if r >= next_item_size {
            score -= 12.0;
            // exact modularity: post_residual exactly divisible into next item
            if r % next_item_size == 0 {
                score -= 8.0;
            }
        } else {
            score += 10.0;
        }
    }

    // Integer-division threshold on post_residual: bucketize
    let bucket = r / 10;
    score += match bucket {
        0 => 15.0,   // 0..9 unusable
        1 => 2.0,    // 10..19 marginal
        2 => -2.0,
        3 => -4.0,
        4 => -5.0,
        5 => -3.0,   // 50..99 half-full: less valuable than tighter fills
        _ => 0.0,
    };

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        score += 8.0; // mild penalty so open bins usually win
        if fitting_bins_count == 0 {
            score -= 60.0; // forced open
        } else if post_residual > 30 && fitting_bins_count <= 2 {
            score -= 25.0; // poor fits elsewhere: fresh bin fine
        }
    }

    // Progress-adaptive tightness: late in stream, pack tighter
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (100.0 - post_residual as f64) * 0.3 * progress;

    // Crowding: many open bins -> prefer filling existing ones
    score += open_bins_count as f64 * 0.4;

    // Mean-residual coupling: if this bin's residual is far below mean,
    // it's already tight; reward closing it down further.
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        let dead = (post_residual as f64) / 10.0;
        score += dead * dead;
    }

    // Perfect fits are strongly rewarded.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Penalize leaving a gap that is too small for the next item if it could otherwise fit.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }
    // Reward leaving a gap that exactly accommodates the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 10.0;
    }

    // Last-chance bin pressure: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 0.5;

    // Progress-scaled tightness bonus: as stream progresses, prefer tighter fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (bin_residual - post_residual) as f64 * (0.1 + 0.2 * progress);

    // Mean-residual coupling: prefer bins below mean residual (tighter than average).
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size
    if next_item_size > 0 && post_residual >= next_item_size {
        let match_quality = 1.0 - (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
        score -= 30.0 * match_quality;
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space penalty scaled by how much of next item is blocked
        let blocked = (next_item_size - post_residual) as f64;
        score += 0.5 * blocked;
    }

    // Relative to mean residual: prefer bins tighter than average
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Penalize creating tiny unusable residuals
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // New-bin candidate: penalize mildly unless open bins are poor fits
    if bin_residual == bin_capacity {
        score += 25.0;
        // If lookahead won't fit anywhere else, opening new bin is fine
        if next_item_size > 0 && bin_capacity - item_size >= next_item_size {
            score -= 10.0;
        }
    }

    // Late-stream consolidation: prefer tight fits as stream ends
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post-residual) more aggressively.
    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 8.0 * tight * tight;

    // Penalize dead space that can never hold a typical next item.
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += 6.0 + 0.25 * (post_residual as f64);
        }
        // Reward bins whose post-residual exactly matches the lookahead item.
        if post_residual == next_item_size {
            score -= 5.0;
        }
    }

    // Last-chance bonus: only one fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: penalize opening a new bin unless nothing fits well.
    if bin_residual == bin_capacity {
        let waste = (bin_capacity - item_size) as f64;
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        score += 15.0 * pressure + 0.3 * waste;
        if next_item_size > 0 && bin_capacity - item_size >= next_item_size && pressure > 0.0 {
            score += 4.0;
        }
    }

    // Global state coupling: many open bins with high mean residual -> prefer reusing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let openness = open_bins_count as f64 / (total_items.max(1) as f64).sqrt().max(1.0);
    score -= 0.4 * mean_residual * (0.5 + 0.5 * openness);
    score -= 3.0 * (1.0 - progress) * tight;

    // Prefer filling bins with small residual relative to mean.
    if (post_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let capacity_f = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_post = post / capacity_f;

    // Base: waste after placement
    let mut score = post;

    // Smooth non-linear penalty on large leftover space (quartic shaping):
    // moderate residuals are fine, large ones wasteful.
    score += 40.0 * norm_post * norm_post * norm_post * norm_post * capacity_f;

    // Coupling with stream progress: late in the stream, tight fits matter more.
    let tightness = 1.0 - norm_post;
    score -= 25.0 * progress * tightness * tightness;

    // Reward bins that also fit the lookahead item smoothly.
    let next_fits = if (next_item_size as f64) <= post { 1.0 } else { 0.0 };
    score -= 15.0 * next_fits * (post / capacity_f);

    // Last-chance bin bonus: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // Mild penalty for scattering across many open bins when mean residual is low.
    score += 0.05 * open_bins_count as f64 * (mean_residual / capacity_f).max(0.0);

    // New-bin candidate: neutral-ish but penalize slightly so we prefer reuse
    // unless the fit is poor; scale with progress (late stream, avoid new bins).
    if bin_residual == bin_capacity {
        score += 10.0 + 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: prefer residuals that are "perfect fits"
    // for common item sizes (divisible into small classes).
    let post = post_residual as u32;
    if post == 0 {
        score -= 1000.0; // perfect fill
    } else if post <= 10 {
        score -= 80.0; // nearly-perfect class
    } else if post % 10 == 0 {
        score -= 20.0; // decile class: reusable by decile-sized items
    } else if post < 20 {
        score += 40.0; // small dead-space class
    }

    // Harmonic coupling with next item: reward residuals that exactly or
    // nearly absorb the lookahead item.
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 150.0;
        } else if next_item_size < post {
            let gap = post - next_item_size;
            if gap <= 10 {
                score -= 60.0;
            } else {
                score -= 20.0 * (1.0 - gap as f64 / bin_capacity as f64);
            }
        } else {
            // next item cannot fit here: penalize proportionally to wasted class
            score += 30.0;
        }
    }

    // Integer-division threshold classes on bin_residual.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    if bin_residual > half + quarter {
        score -= 10.0; // roomy bin: good to fill
    } else if bin_residual < quarter {
        score += 15.0; // nearly full: fragile placement
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 200.0;
        } else if fitting_bins_count == 1 {
            score -= 60.0;
        } else {
            score += 50.0 * (fitting_bins_count as f64).ln();
        }
        // early stream: opening bins is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 30.0 * (1.0 - progress);
    }

    // Spread load when mean residual is high relative to item needs.
    if mean_residual > (2.0 * item_size as f64) && bin_residual as f64 >= mean_residual {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftovers are unusable for future items (>=1).
    if post_residual > 0 {
        // Perfect fit: massive reward.
        if post_residual == 0 {
            score -= 1000.0;
        }
        // Penalize dead space that cannot hold even the smallest plausible item.
        if post_residual < 10 {
            score += 60.0; // unusable sliver
        } else if post_residual < 20 {
            score += 25.0; // very hard to fill
        } else if post_residual < 35 {
            score += 8.0; // marginal gap
        }
    } else {
        score -= 500.0; // exact fill is ideal
    }

    // Tightness reward: fraction of bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 40.0 * fill_ratio;

    // Lookahead: reward if next item fits exactly in post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0;
        } else if next_item_size < post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else if post_residual > 0 && next_item_size > post_residual {
            score += 15.0; // this bin would be closed with dead space anyway
        }
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Open-bins pressure: with many open bins, favor consolidating into existing bins;
    // with few open bins, allow opening a new one for better future packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let bin_pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: acceptable early or when open bins are fragmented,
        // penalized when open bins are few or residuals are large.
        score += 30.0 + 6.0 * bin_pressure;
        if mean_residual > 40.0 {
            score -= 20.0; // existing bins are roomy; opening fresh bin is fine
        }
    } else {
        // Existing bin: small bonus for keeping bin count down.
        score -= 5.0 + 0.5 * bin_pressure.min(10.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact or near-exact fits (minimal dead space).
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 50.0;
    } else if post_residual <= 15 {
        score -= 20.0;
    }

    // 2-step lookahead: reward bins where the leftover can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // The next item fits here after this placement: big reward,
            // scaled by how snugly it fits (small gap is better).
            let gap = post_residual - next_item_size;
            score -= 30.0 - (gap as f64).min(30.0);
        } else {
            // Next item cannot follow into this bin: penalize dead space.
            score += (post_residual as f64).min(40.0) * 0.5;
        }
    }

    // Relative residual context: prefer bins with residuals below mean
    // (tighten crowded bins) but avoid creating extreme outliers.
    let diff = post_residual as f64 - mean_residual;
    if diff < 0.0 {
        score += diff * 0.3; // tighter than average: mild reward (diff negative)
    } else {
        score += diff * 0.2; // looser than average: mild penalty
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current item is
    // large and no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64;
        score += 60.0 + pressure * 0.5;
        if item_size > bin_capacity / 2 && post_residual < item_size / 2 {
            score -= 30.0;
        }
    }

    // Mild late-stream tightening: as the stream progresses, prefer
    // consolidating into fewer bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic bonus for small leftover space.
    score -= 0.35 * ((cap - post_residual as f64) / cap) * (post_residual as f64);

    // Penalize dead space that no future item can plausibly use.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0; // tiny unusable sliver
    }

    // Lookahead: if the next item fits into the post residual, reward this bin.
    if next_item_size > 0 && (next_item_size as f64) <= post_residual as f64 {
        score -= 8.0 + 0.25 * (next_item_size as f64);
    } else if next_item_size > 0 {
        // Next item won't fit here; penalize proportionally to wasted potential.
        score += 0.15 * (next_item_size as f64 - post_residual as f64).min(40.0);
    }

    // Last-chance bin: strongly prefer using the only bin that fits, to avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when existing bins are fragmented
    // or this is a huge item best isolated.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Discourage opening new bins early or when open bins are healthy.
        score += 25.0 + 20.0 * (1.0 - progress) + 0.1 * open_bins_count as f64;
        // Allow new bin when mean residual is small (bins are nearly full anyway).
        score -= 0.3 * mean_residual;
        // Isolate very large items into a fresh bin if they'd leave awkward residue.
        if item_size as f64 > 0.7 * cap {
            score -= 18.0;
        }
        let _ = fragmentation;
    }

    // Mild preference for filling bins that are already below-average residual
    // (consolidate occupancy).
    if bin_residual < bin_capacity && (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress.
    let mut score = pr_norm * (1.0 + 1.5 * progress * progress);

    // Penalize tight-but-wasteful fits: quadratic dead-space term.
    score += 0.8 * pr_norm * pr_norm;

    // Reward filling bins tightly as stream progresses (subtract fit quality).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 2.0 * fit_ratio * (1.0 + progress);

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 3.0 * (1.0 + progress);
    }

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 1.2 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 0.5 * (next_item_size as f64 / cap) * pr_norm;
    }

    // Deter spreading across too many open bins when mean residual is low.
    score += 0.3 * ((open_bins_count as f64) / (1.0 + mean_residual / cap)) * pr_norm;

    // New-bin candidate: neutral baseline with mild progress-dependent preference.
    if bin_residual == bin_capacity {
        score += 0.6 + 0.4 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit dominates everything.
    if post_residual == 0 {
        return -10000.0;
    }

    // Harmonic class of the leftover space: how "usable" is post_residual
    // as a multiple of small item sizes (1..=10)?
    let pr = post_residual;
    let mut harmony: f64 = 0.0;
    for k in 1..=10u32 {
        if pr >= k {
            // leftover divisible by small sizes is more likely reusable
            let rem = pr % k;
            if rem == 0 {
                harmony += 1.0 / (k as f64);
            }
        }
    }
    score -= harmony * 8.0;

    // Dead-space penalty: leftover too small to hold even the smallest item.
    if pr < 10 {
        score += 60.0 + (10 - pr) as f64;
    } else if pr <= 20 {
        score += 8.0;
    }

    // Reward tight fits: post_residual close to zero relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= tightness * 30.0;

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: only open a new bin when the current bin
    // would leave a large, awkward residual and the next item could use a
    // fresh bin's full capacity better.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a bin: penalize so it only wins when fits are bad.
        score += 50.0;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Lookahead: if next item is large and this fit is loose, fresh bin is good.
        let loose = (post_residual as f64) > 0.45 * (bin_capacity as f64);
        if next_item_size > 0 && next_item_size >= 50 && loose {
            score -= 55.0 * (0.4 + 0.6 * progress);
        }
        // Late in stream, prefer consolidating into open bins.
        if progress > 0.7 {
            score += 20.0 * progress;
        }
        // Many open bins: discourage opening yet another.
        score += 2.0 * (open_bins_count as f64).sqrt();
    } else {
        // Reward using bins whose residual is below mean (balancing residuals).
        let dev = mean_residual - bin_residual as f64;
        if dev > 0.0 {
            score -= dev * 0.5;
        } else {
            score += (-dev) * 0.25;
        }
    }

    // Lookahead synergy: if next item exactly fits the post_residual,
    // this placement is excellent (chained perfect fit).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 80.0;
    } else if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        // next item would nearly close the bin
        score -= 25.0;
    } else if next_item_size > post_residual && post_residual < 10 {
        // dead space not usable by next item: extra penalty
        score += 30.0;
    }

    // Integer-division threshold: prefer post_residual in "good" harmonic
    // classes (multiples of 10, 25, 50) which many item sizes partition well.
    if pr % 10 == 0 {
        score -= 6.0;
    }
    if pr % 25 == 0 {
        score -= 4.0;
    }
    if pr % 50 == 0 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold the minimum
    // item (1..=100 range, but small gaps < 10 are pure waste) are heavily
    // penalized, especially near-tight fits leaving 1..9 unusable units.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    } else if post_residual == 0 {
        // Perfect fit is ideal: reward strongly.
        score -= 100.0;
    } else {
        // Smooth preference for smaller usable leftovers.
        score += 0.35 * post_residual as f64;
    }

    // Reward tight fits relative to bin residual (fill ratio).
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fill * fill;

    // Pressure from number of open bins: discourage opening new bins when
    // many are already open, encourage consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins open or late in stream.
        score += 25.0 + 2.0 * open_bins_count as f64 * (0.5 + progress);
    } else {
        // Existing bin: small reward to prefer reusing open bins.
        score -= 3.0 + 0.5 * open_bins_count as f64;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // to avoid opening a new bin for an item that already fits here.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward;
    // if the next item would not fit in post residual but fits elsewhere,
    // mild penalty for hogging space.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 50.0;
        } else if next_item_size > post_residual && next_item_size <= bin_residual {
            score += 10.0;
        }
    }

    // Prefer bins whose residual deviates favorably from the mean residual:
    // target the bin with the smallest residual that still fits (best fit).
    if bin_residual != bin_capacity {
        score += 0.2 * (mean_residual - bin_residual as f64).max(-50.0).min(50.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-exact fit (small dead space).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // 2-step lookahead: if next item exactly matches the post residual,
    // this placement chains perfectly -> huge reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 900.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size <= 5 {
            score -= 400.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size <= 15 {
            score -= 120.0;
        } else if post_residual < next_item_size && post_residual > 0 {
            // dead space the next item can't use
            score += (next_item_size as f64 - post_residual as f64) * 0.5;
        }
        // Next item fits well into mean residual elsewhere: mild penalty for hoarding
        if mean_residual >= next_item_size as f64 && post_residual >= next_item_size as f64 {
            score += 10.0;
        }
    }

    // Penalize creating small unusable slivers relative to capacity.
    let frac = post_residual as f64 / bin_capacity as f64;
    if frac > 0.0 && frac < 0.10 {
        score += 60.0 * (0.10 - frac) * 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: only attractive when all open bins fit poorly.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 300.0;
        // but if current bin would leave a very awkward remainder, opening new is fine
        if post_residual > 0 && (bin_residual as f64 - post_residual as f64) > 0.0 {
            // keep base cost; adjust by how many bins fit the item
            if fitting_bins_count == 0 {
                score -= 500.0;
            } else if fitting_bins_count == 1 {
                score -= 250.0;
            }
        }
        // late in stream, prefer consolidating
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 100.0 * progress;
    }

    // Slight tie-break toward filling more congested bins (lower residual than mean).
    if (bin_residual as f64) < mean_residual {
        score -= 15.0;
    } else if (bin_residual as f64) > mean_residual {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual)
    score -= (bin_capacity as f64 - post_residual as f64).powi(2) / (bin_capacity as f64 * bin_capacity as f64) * 30.0;

    // Penalize dead space that no plausible item can use
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Lookahead coupling: if next item fits into post_residual, reward strongly
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let snug = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 15.0 + 20.0 * snug;
        } else {
            // next item won't chain here; mild penalty scaled by gap
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        // spread preference: prefer bins with less competition? slight penalty for abundance
        score += (fitting_bins_count as f64 - 1.0) * 1.5;
    }

    // Global state: many open bins with high mean residual -> prefer filling existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if mean_residual > (item_size as f64) * 1.5 && open_bins_count > 2 {
        score -= 8.0 * (mean_residual / bin_capacity as f64);
    }

    // Early stream: allow opening new bins for better long-term structure
    if progress < 0.25 && bin_residual == bin_capacity {
        score -= 10.0;
    } else if progress > 0.6 && bin_residual == bin_capacity {
        // late stream: opening new bins is costly
        score += 20.0 * progress;
    }

    // Mild bonus for using bins with larger residuals (consolidate waste)
    score -= (bin_residual as f64 / bin_capacity as f64) * 5.0;

    // Prefer exact-ish fills near capacity
    if post_residual == 0 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fill = 1.0 - pr / cap;

    // Base: prefer low post_residual, with smooth polynomial shaping
    let mut score = pr * (1.0 + 0.35 * fill * fill);

    // Stream-progress coupling: as stream progresses, tighten residual preference quadratically
    let tighten = 0.5 * progress * progress;
    score += tighten * pr * (1.0 - fill);

    // Smooth penalty for residual near the awkward mid-range (dead space) via sinusoid-free polynomial
    let x = pr / cap;
    let dead = x * (1.0 - x) * 4.0; // peaks at x=0.5
    score += 6.0 * dead * (0.5 + 0.5 * progress);

    // Last-chance bonus: smooth reward when few fitting bins
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 - 0.5 * progress);
    }

    // Lookahead coupling: reward if next item fits smoothly into post_residual
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let fit_q = 1.0 - ((pr - nx) / cap).powi(2);
            score -= 4.0 * fit_q * (0.4 + 0.6 * progress);
        } else {
            // smooth penalty scaled by overflow magnitude
            score += 3.0 * ((nx - pr) / cap).min(1.0);
        }
    }

    // Mild dispersion coupling: prefer bins close to mean residual (balance load)
    let dev = (pr as f64 - mean_residual).abs() / cap;
    score += 2.0 * dev * dev;

    // New-bin candidate: penalize opening a bin when open bins exist and fit is decent
    if bin_residual == bin_capacity && open_bins_count > 0 {
        let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
        score += 5.0 + 10.0 * scarcity * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space in "waste classes"
    let classes: [u32; 6] = [1, 2, 3, 5, 7, 11];
    let mut waste_penalty = 0.0;
    for &c in &classes {
        if post_residual % c == 0 && post_residual > 0 {
            waste_penalty += 2.0 / c as f64;
        }
    }
    score += waste_penalty;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 100.0;
    }

    // Small post_residual is good, but avoid leaving residue that nothing can use
    if post_residual > 0 && post_residual < 10 {
        score -= 5.0;
    }

    // Last chance bin: strong bonus to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Penalize new-bin candidate unless item is large or fits are poor
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64) / (1.0 + mean_residual / bin_capacity as f64);
        if next_item_size > 0 && next_item_size <= post_residual {
            score += 40.0; // existing bins could hold the next item too
        } else {
            score -= 10.0 * pressure.min(10.0);
        }
    }

    // Lookahead: reward bins where the next item also fits (chaining)
    if next_item_size > 0 && next_item_size <= post_residual && bin_residual < bin_capacity {
        score -= 8.0;
    }
    // Penalize leaving a residue just barely too small for the next item (dead space)
    if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual && post_residual < 15 {
        score += 6.0;
    }

    // Threshold on integer division of residual by item size (coupling)
    if item_size > 0 {
        let div = bin_residual / item_size;
        if div >= 2 {
            score -= 4.0; // bin can hold multiple such items: keep it flexible
        }
    }

    // Late in stream: tighten packing, prefer tight fits more aggressively
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: prefer bins below mean residual (tighter bins) for big items
    if (item_size as f64) > mean_residual {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Two-step lookahead: perfect match for the next item is excellent.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Dead space: post_residual > 0 but next item cannot use it.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0;
    }

    // Post residual larger than next item but small enough to be wasteful.
    if next_item_size > 0 && post_residual > next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 15.0 / (1.0 + gap / 20.0);
    }

    // Favor tight fills relative to capacity.
    score += 0.3 * (post_residual as f64 / bin_capacity as f64) * (post_residual as f64);

    // Last chance bin: strong reward to use it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Penalize spreading across many open bins; prefer compacting.
    score += 2.0 * (open_bins_count as f64).sqrt();

    // Prefer bins with residual below the mean residual (tighter bins first).
    score -= 0.5 * (mean_residual - post_residual as f64);

    // New-bin candidate: penalize slightly so it only wins when fits are bad,
    // but reward it late in the stream or when item is large.
    if bin_residual == bin_capacity {
        score += 30.0;
        if item_size >= 60 {
            score -= 20.0;
        }
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: strongly prefer bins where post_residual is small.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 8.0;

    // Penalize dead space that is too small to be useful later (unusable gap).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: if this is the only fitting bin, prefer it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // With multiple options, mild penalty to encourage discriminating among them.
        score += (fitting_bins_count as f64 - 1.0) * 2.0;
    }

    // Lookahead coupling: if the next item can use this bin's post_residual, reward it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 + (next_item_size as f64 / 10.0);
        } else {
            // Penalize leaving residual that wastes the bin for the next item.
            score += 4.0;
        }
        // If next item would perfectly fill post_residual, strong bonus.
        if post_residual == next_item_size {
            score -= 20.0;
        }
    }

    // Time horizon: early in the stream, be more willing to open new bins (explore);
    // late in the stream, consolidate into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * 5.0;

    // Global state: many open bins with high mean residual -> discourage opening more bins,
    // encourage filling underused ones.
    let residual_gap = bin_residual as f64 - mean_residual;
    score -= residual_gap * 0.05 * (1.0 - progress);

    // New-bin candidate handling: an empty bin gets a baseline that must be beaten
    // by genuinely good fits in existing bins.
    if bin_residual == bin_capacity {
        score += 30.0;
        // Late in the stream, opening new bins is more costly.
        score += progress * 20.0;
        // If only one bin fits, avoid opening a new bin.
        if fitting_bins_count == 1 {
            score += 25.0;
        }
    }

    // Mild preference toward filling bins that are already quite full.
    let fill_level = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= fill_level * 6.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, smoothly warped
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Non-linear coupling of post-residual with stream progress:
    // early on, tolerate larger residuals; late, penalize them harder
    score += 30.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits smoothly (small post_residual relative to item)
    let tightness = 1.0 - norm_pr;
    score -= 15.0 * tightness * tightness * (1.0 - progress);

    // Lookahead: if next item fits the post-residual, reward this placement
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if ns <= pr {
            score -= 10.0 * (1.0 - ns / cap);
        } else {
            score += 8.0 * ((ns - pr) / cap);
        }
    }

    // Last-chance bin bonus: avoid opening new bins unnecessarily
    if fitting_bins_count == 1 {
        score -= 12.0 * (0.5 + progress);
    }

    // Mild preference for bins with residuals near the mean (balance)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // Slight openness penalty to consolidate bins when many are open
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify dead space by capacity fraction.
    let cap = bin_capacity as f64;
    let post_f = post_residual as f64;
    let frac = post_f / cap;

    // Class boundaries: unusable slivers (<10) are dead space -> penalize.
    if post_residual == 0 {
        score -= 60.0; // perfect fit
    } else if post_residual < 10 {
        score += 25.0; // dead sliver
    } else {
        // Harmonic divisibility: residual that can host common small classes is good.
        let classes: [u32; 4] = [10, 20, 25, 50];
        let mut harmony = 0.0;
        for (i, &c) in classes.iter().enumerate() {
            if post_residual % c == 0 {
                harmony += 8.0 + i as f64 * 3.0;
            }
        }
        // Integer-division threshold: how many size-10 units fit (granularity).
        let units = post_residual / 10;
        score -= (units as f64).min(5.0) * 2.0;
        score -= harmony;

        // Fractional band reward: residuals in [10, 30] are "second-class" usable space.
        if frac <= 0.3 {
            score += 6.0 * (0.3 - frac) / 0.3;
        }
    }

    // Lookahead coupling: if the next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            let gap = post_residual - next_item_size;
            score -= 15.0 - (gap as f64).min(15.0);
            if gap < 10 {
                score += 12.0; // would create a sliver
            }
        }
    }

    // Last chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current placement is bad.
    if bin_residual == bin_capacity {
        score += 20.0
            - (mean_residual / cap).min(1.0) * 30.0
            + (open_bins_count as f64).max(1.0).recip() * 5.0;
        if next_item_size > 0 && next_item_size > item_size {
            score -= 10.0; // save space for a bigger future item
        }
    }

    // Mild stream-progression damping: early on, be more conservative with tight fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.15 * (1.0 - progress);

    // Tie-breaker: tighter bins slightly preferred.
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small gaps (< smallest plausible item) are nearly unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual <= 20 {
        // Moderately poor gap: penalize proportionally to how "awkward" it is.
        score += 18.0 * (1.0 - (post_residual as f64 - 10.0) / 10.0);
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage opening new bins when few bins exist;
    // encourage consolidation when many bins are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: base penalty plus pressure, eased late in stream.
        score += 30.0 + pressure * 6.0 - 15.0 * progress;
    } else {
        score -= 4.0 + pressure * 0.5;
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            // Next item won't fit here; slightly penalize leaving a medium gap.
            score += 3.0;
        }
    }

    // Prefer bins tighter than the mean residual (consolidate fullness).
    score += (mean_residual - bin_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
