pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linearly).
    let tightness = (bin_residual - post_residual) as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * tightness * tightness;

    // Penalize tiny dead space that nothing can use (waste threshold ~ item_size of next item).
    if post_residual > 0 && post_residual < item_size.min(20) {
        score += 6.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Lookahead: bonus if next item fits exactly in the post residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 5.0 * (post_residual as f64 / (post_residual + next_item_size) as f64);
        } else {
            // Next item cannot follow here; penalize proportionally to leftover unusability.
            score += 3.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Global state coupling: many open bins with high mean residual -> favor consolidation.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let consolidation = (mean_residual - post_residual as f64).abs();
    score += 0.05 * consolidation * (open_bins_count as f64).ln().max(1.0);

    // Early in the stream, prefer keeping residuals flexible (larger post residual ok);
    // late in the stream, punish large residuals harder.
    score += progress * (post_residual as f64 / bin_capacity as f64) * 8.0;

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let escape_bonus = if fitting_bins_count == 0 { -8.0 } else { 25.0 + 20.0 * (1.0 - progress) };
        score += escape_bonus;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let x = pr / cap; // normalized post-residual

    // Smooth polynomial coupling of post-residual with stream progress
    let mut score = pr as f64;
    score += 12.0 * x * x * (1.0 + progress);
    score += 8.0 * x * x * x * (1.0 - progress);
    score -= 10.0 * x * (1.0 - x) * (1.0 + progress);

    // Penalize tight fits slightly when they strand small residuals, reward mid fits
    let tight = 1.0 - (x - 0.05).abs().min(0.5) * 2.0;
    score -= 6.0 * tight.max(0.0) * (1.0 - progress);

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: reward if next item fits the post-residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr as f64 {
            score -= 8.0 * (1.0 - (nxt / cap));
        } else {
            score += 4.0 * ((nxt - pr as f64) / cap);
        }
    }

    // Prefer filling bins with low residual relative to mean
    score += 3.0 * (mean_residual - pr as f64).abs() / cap;

    // New-bin candidate: mild penalty so it's chosen only when clearly better
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "small"
    // residue classes are more likely to be filled by future items.
    let cap = bin_capacity as f64;

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space penalty: leftover too small for the minimum item (size 1..=100
    // unknown distribution, assume items >= 10 typical, but guard generally).
    let min_item = 10u32;
    if post_residual > 0 && post_residual < min_item {
        score += 60.0; // unusable sliver
    }

    // Harmonic class: leftover divisible by common item sizes is reusable.
    let pr = post_residual;
    let mut reusable = 0.0;
    for d in [10u32, 20, 25, 50] {
        if pr % d == 0 && pr > 0 {
            reusable += 12.0;
        }
    }
    score -= reusable;

    // Classify post_residual by capacity fraction (integer division thresholds).
    let frac = pr as f64 / cap;
    if frac < 0.1 {
        score -= 8.0; // nearly full bin: good compaction
    } else if frac > 0.5 {
        score += 15.0; // leaving more than half empty is wasteful
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 120.0;
        } else if next_item_size <= pr {
            score -= 25.0;
        } else {
            score += 10.0; // next item won't fit here; deprioritize this bin
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin should only win when it
    // avoids a very poor fit. Penalize fresh-bin slightly so it's a fallback,
    // but less when current open bins are fragmented (high mean residual).
    if bin_residual == bin_capacity {
        score += 30.0 + 0.2 * open_bins_count as f64;
        if mean_residual > 0.4 * cap {
            score -= 20.0; // fragmentation: new bin attractive
        }
    }

    // Mild pressure toward compacting many open bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small to fit any plausible
    // future item are wasted. Penalize small nonzero post_residuals strongly.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // unusable gap
        } else if post_residual < 20 {
            score += 25.0;
        } else if post_residual < 35 {
            score += 8.0;
        }
    } else {
        // Perfect fit: strong reward
        score -= 100.0;
    }

    // Reward filling a bin that is the only fitting candidate (last chance)
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, prefer reusing existing bins
    // over opening new ones; scale with number of open bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln() * (1.0 + progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize opening a new bin, more so when many
        // bins are open, unless the item is large relative to residuals.
        score += 30.0 + 10.0 * pressure;
        // If item barely fits anywhere else (tight fit), new bin is fine
        if item_size as f64 > mean_residual {
            score -= 45.0;
        }
    } else {
        // Reusing an open bin: reward scaled by how well it uses space
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= 15.0 * fill_ratio;
    }

    // Lookahead: if next item fits in the post-residual, reward this placement
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 20.0;
    }
    // If next item cannot fit post-residual but could fit a fresh bin,
    // slightly penalize leaving an awkward gap.
    if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact or near-exact fits (low post_residual)
    let tight_fit_bonus = if post_residual == 0 {
        60.0
    } else if post_residual <= 5 {
        35.0
    } else if post_residual <= 10 {
        20.0
    } else {
        0.0
    };
    score -= tight_fit_bonus;

    // 2-step lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // next item fits exactly or nearly exactly after this placement
            let slack = post_residual - next_item_size;
            if slack == 0 {
                score -= 55.0;
            } else if slack <= 5 {
                score -= 30.0;
            } else {
                score -= 12.0;
            }
        } else {
            // next item won't fit here: penalize, but less if post_residual is tiny (dead space)
            let dead = post_residual as f64;
            score += dead * 0.6;
        }
    }

    // Compare post_residual against mean residual: prefer bins that become tighter than average
    score -= (mean_residual - post_residual as f64) * 0.4;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Penalize wasting a large bin residual on a small item (bad fill ratio)
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fill_ratio < 0.4 {
        score += (0.4 - fill_ratio) * 80.0;
    }

    // New-bin candidate: penalize moderately so it's chosen only when open bins fit poorly.
    // Scale with stream progress: later in stream, prefer consolidating into open bins more.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 + 30.0 * progress;
    }

    // Mild penalty for opening many bins when alternatives exist
    if open_bins_count > 5 && bin_residual != bin_capacity {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item nearly fills the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fill_ratio * fill_ratio;

    // Penalize large leftover slivers that are hard to reuse (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // tiny unusable sliver
    } else if post_residual >= 10 && post_residual <= 25 {
        score -= 3.0; // still useful for small items
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let snug = (post_residual - next_item_size) as f64;
        score -= 6.0 * (1.0 - snug / bin_capacity as f64);
    } else if next_item_size > 0 {
        score += 2.0; // next item won't fit here
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 9.0 + 4.0 * fill_ratio;
    }

    // Penalize spreading across many open bins; encourage consolidation
    // when open bins are mostly empty (high mean residual).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score += 0.15 * open_bins_count as f64 * (0.5 + 0.5 * progress);
        score += 0.02 * (mean_residual - bin_residual as f64);
    }

    // New-bin candidate: make it attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        let base = bin_capacity as f64 * 0.55;
        score = score.max(base) + 10.0 * (1.0 - fill_ratio);
        if fitting_bins_count == 0 {
            score -= 40.0; // forced new bin
        } else if fitting_bins_count == 1 {
            score += 15.0; // an open bin fits; prefer it
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = x * x * (1.0 - x) * (1.0 - x); // peaks mid-range residuals
    score -= 12.0 * poly * (0.5 + progress);

    // Penalize large dead space increasingly as stream progresses
    score += 0.8 * progress * x * x * cap * 0.01;

    // Reward tight fits (small post residual) with smooth decay
    score -= 10.0 * (-x * 8.0).exp() * (1.0 - progress);

    // Last-chance bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - x);
    }

    // Lookahead: reward leaving room for the next item, penalize near-misses
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if pr >= n {
            let slack = (pr - n) / cap;
            score -= 6.0 * (-slack * 6.0).exp();
        } else {
            let miss = (n - pr) / cap;
            score += 5.0 * (-miss * 5.0).exp();
        }
    }

    // Coupling with mean residual: prefer bins deviating favorably from the mean
    let dev = (pr - mean_residual) / cap;
    score -= 3.0 * dev * (1.0 - progress);

    // Mild pressure to consolidate when many bins are open
    score += 0.02 * open_bins_count as f64 * x;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 500.0;
    }

    // Harmonic class of post_residual: dead space classes are bad
    let c = bin_capacity as f64;
    let pr = post_residual as f64;

    // Penalize residuals in "awkward" classes (small, unusable slivers)
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0;
    }

    // Modulo-10 class logic: residuals divisible by 10 pair well with items 10..80
    if post_residual % 10 == 0 {
        score -= 25.0;
    }

    // Lookahead coupling: if next item fits post_residual, big reward
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 40.0 + 0.5 * (post_residual - next_item_size) as f64;
    } else if next_item_size > 0 {
        // next item cannot use the leftover: penalize proportional to leftover size
        score += 0.3 * pr;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: prefer new bin only when it offers more room
    // than any sensible reuse, and when current bins are crowded
    if bin_residual == bin_capacity {
        // mild preference against opening new bins by default
        score += 30.0 + 2.0 * open_bins_count as f64;
        // but if mean residual is small (bins nearly full), opening is fine
        score -= 1.5 * mean_residual;
        // late in stream, avoid proliferation
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Tightness reward: leaving small but useful residual is good
    if post_residual >= 10 && post_residual <= 30 {
        score -= 15.0;
    }

    // Fraction-of-capacity class: residual near half capacity is very reusable
    let half = c / 2.0;
    score -= 20.0 * (1.0 - (pr - half).abs() / half);

    // Prefer bins whose residual is close to what's being consumed
    score -= 0.1 * (bin_residual as f64 - item_size as f64).abs().max(0.0).min(50.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps (1..=10) are nearly unusable
    // for future items (sizes >= 1 but typically much larger), so penalize heavily.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0 * (1.0 - post_residual as f64 / 10.0);
    } else if post_residual > 10 && post_residual <= 20 {
        score += 15.0;
    }

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Tight fit reward: fraction of bin used by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill;

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless post_residual would be tiny dead space).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: penalize opening new bins when many are already open.
    if bin_residual == bin_capacity {
        score += 10.0 + 2.0 * open_bins_count as f64;
        // But allow a new bin if it would create a clean large residual while
        // the best existing fit leaves dead space.
        if post_residual >= 20 && fitting_bins_count <= 2 {
            score -= 25.0;
        }
    }

    // Lookahead: if next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack <= 5.0 {
            score -= 25.0;
        } else {
            score -= 8.0;
        }
    }

    // Mean-residual coupling: prefer bins whose residual is below mean (tighter bins),
    // keeping large-residual bins flexible for big future items.
    if bin_residual as f64 > mean_residual {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact / tight fits strongly.
    let tightness = (bin_capacity as f64 - (bin_residual as f64 - post_residual as f64)) / bin_capacity as f64;
    if post_residual == 0 {
        score -= 60.0; // perfect fill
    } else if post_residual < 10 {
        score -= 40.0; // near-perfect fill, dead space almost unusable anyway
    }

    // 2-step lookahead: does the next item fit in the leftover space?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Great: chain placement possible. Reward proportional to how well
            // the next item fills the leftover (leaving minimal new dead space).
            let next_left = post_residual - next_item_size;
            score -= 25.0 + (next_left as f64).min(30.0) * -0.5;
            if next_left == 0 {
                score -= 20.0; // two consecutive perfect fills
            }
        } else {
            // Next item won't fit here; penalize leftover dead space that is
            // too small to be useful relative to the next item.
            let waste = next_item_size - post_residual;
            score += (waste as f64) * 0.6;
        }
    }

    // Penalize creating small unusable gaps relative to the minimum item size (1..100 unknown,
    // use conservative threshold): gaps < 10 are usually dead.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make it moderately attractive only when open bins have poor fits
    // (post_residual here equals capacity, so baseline score is high; add context terms).
    if bin_residual == bin_capacity {
        // Slight penalty so tight fits in existing bins win, but allow new bin when
        // existing residuals are large and fragmented.
        score += 10.0;
        if mean_residual > 40.0 {
            score -= 8.0; // existing bins are roomy; opening new bin is fine
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // next item is big; fresh bin gives flexibility
        }
    }

    // Mild penalty for spreading across many open bins when residuals are similar
    // (encourage consolidation into bins below the mean residual).
    if open_bins_count > 0 && (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    // Stream progression: late in the stream, prefer squeezing into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= progress * 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) with a nonlinear bonus.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tight * tight;

    // Penalize creating dead space that no plausible future item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 18.0; // tiny unusable slivers
    } else if post_residual >= 10 {
        // If the next item fits the post residual, reward strongly.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0 + (post_residual as f64 - next_item_size as f64).min(20.0);
        } else if next_item_size > post_residual {
            score += 6.0; // lookahead blocked
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: make empty bins moderately attractive only
    // when existing bins would leave bad fits.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, decaying over the stream.
        let t = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 - 8.0 * t;
        // If many bins already fit, opening a new one is wasteful.
        if fitting_bins_count > 0 {
            score += 14.0 + 3.0 * fitting_bins_count as f64;
        }
        // Large items favor fresh bins.
        if item_size > bin_capacity / 2 {
            score -= 10.0;
        }
    }

    // Global state coupling: prefer filling bins when mean residual is high
    // (fragmentation pressure), so we consolidate.
    if bin_residual < bin_capacity {
        let frag = (mean_residual - post_residual as f64).abs();
        score += 0.05 * frag;
        // Mild preference for fuller bins among open bins.
        score += 0.08 * (bin_capacity as f64 - bin_residual as f64).max(0.0) / bin_capacity as f64 * 10.0;
    }

    // Few fitting bins overall -> conserve them by penalizing alternatives less.
    if fitting_bins_count <= 2 && bin_residual < bin_capacity {
        score -= 5.0;
    }

    // Time horizon: late in the stream, be more aggressive about packing tight.
    let t = step_index as f64 / (total_items.max(1) as f64);
    score -= 6.0 * t * tight;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Base: prefer tight fits (small post_residual), with convex penalty on waste.
    let mut score = post * post / cap;

    // Smooth stream-progress coupling: waste penalized more as stream matures.
    score += 8.0 * progress * (post / cap).powi(3) * cap;

    // Interaction: post_residual vs mean residual — avoid bins far from fleet average.
    let dev = post - mean_residual;
    score += 0.15 * dev * dev / cap;

    // Last-chance bonus: if this is the only fitting bin, strongly reward using it.
    if fitting_bins_count == 1 {
        score -= 25.0 + 10.0 * progress;
    } else {
        // Mild crowding penalty: many open bins favor consolidation.
        score += 0.5 * (open_bins_count as f64).ln();
    }

    // Lookahead coupling: reward leaving space the next item can use.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= 6.0 * (1.0 - (post - nxt) / cap);
        } else {
            score += 3.0 * (nxt - post) / cap;
        }
    }

    // New-bin candidate: neutral-ish baseline with progress-dependent reluctance.
    if bin_residual == bin_capacity {
        score = cap * 0.6 + 20.0 * progress - 0.3 * mean_residual;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward (harmonic class 0)
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 35.0;
    } else if post_residual <= 10 {
        score -= 20.0;
    }

    // Harmonic class penalty: dead space in coarse buckets of 10
    let dead_class = post_residual / 10;
    score += dead_class as f64 * 3.0;

    // Odd residual (non-multiple of 10) is harder to fill later
    if post_residual % 10 != 0 {
        score += 2.0;
    }

    // Last chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: reward if next item fits snugly into the post residual
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_gap = post_residual - next_item_size;
        if next_gap <= 5 {
            score -= 15.0;
        } else if next_gap <= 10 {
            score -= 8.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item cannot use this leftover space -> mild penalty
        score += 4.0;
    }

    // Prefer placing large items into bins with large residual (fill fat bins first)
    score += (bin_residual as f64 - item_size as f64) * 0.15;

    // Coupling with mean residual: placing here when this bin is above-average residual
    // helps rebalance open bins
    score += (mean_residual - post_residual as f64) * 0.05;

    // Slight preference to act early in the stream when many bins are open
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 0.05 * (1.0 - progress);

    // New-bin candidate: only attractive when the item is large relative to capacity
    // (poor fits elsewhere) — otherwise keep it expensive
    if bin_residual == bin_capacity {
        score = 45.0 + (bin_capacity - item_size) as f64 * 0.4;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // pairing large items together in a fresh bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        // A gap is "dead" if it cannot fit a typical small item (min size 1..~10)
        // and is small relative to capacity. Penalize gaps in the danger zone.
        let gap = post_residual as f64;
        if gap < 10.0 {
            // Completely wasted space: strong penalty proportional to wasted gap.
            score += 40.0 * (10.0 - gap) / 10.0;
        } else if gap < 30.0 {
            // Risky zone: may only fit small future items.
            score += 8.0 * (30.0 - gap) / 30.0;
        }
    } else {
        // Perfect fit: big reward.
        score -= 60.0;
    }

    // Reward tight fits generally: smaller post_residual relative to capacity is better.
    score -= 30.0 * (1.0 - (post_residual as f64) / (bin_capacity as f64));

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bins pressure: discourage spreading across too many open bins.
    score += (open_bins_count as f64) * 0.15;

    // New-bin candidate handling: opening a new bin wastes the mean residual
    // accumulated elsewhere. Penalize the empty bin by the average stranded space,
    // but relax late in the stream when future compaction matters less.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += mean_residual * 0.5 + 10.0 * (1.0 - progress);
        // If the new bin would be an exact/near-exact fit for a large item, allow it.
        if bin_capacity - item_size <= 2 {
            score -= 45.0;
        }
    }

    // Lookahead: if the next item fits exactly into the post_residual, reward strongly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 55.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot use this residual: mildly penalize large leftover gaps.
        score += (post_residual as f64) * 0.1;
    }

    // Mild preference for filling bins with larger residual (consolidation).
    score -= (bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact or near-exact fits (small post_residual)
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    }

    // 2-step lookahead: if the next item fits exactly into post_residual, big bonus
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            // next item fits: good, but penalize leftover after the pair
            let leftover2 = post_residual - next_item_size;
            score -= 150.0 - (leftover2 as f64).min(150.0);
        } else {
            // next item does not fit here: penalize dead space scaled by gap
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.5;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin before opening a new bin: strong bonus
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // New empty bin candidate: penalize unless current item is large or few fitting bins
    if bin_residual == bin_capacity && bin_capacity > 0 {
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 1.0 / fitting_bins_count as f64 };
        score += 120.0 - 120.0 * scarcity;
        // favor new bin for big items
        score -= (item_size as f64 / 100.0) * 40.0;
    }

    // Late in the stream, consolidate: prefer filling existing bins over opening new ones
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 50.0;
    }

    // Mild penalty for very small residuals that become unusable (below min item size ~1)
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
