pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on, prefer filling existing bins (penalize leftover space mildly);
    // later, dead space becomes more costly as stream ends, so weight grows.
    let progress_weight = 0.5 + 1.5 * progress * progress;
    score += progress_weight * (pr * pr) / cap;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (pr / cap);
    score -= 8.0 * tightness * tightness * tightness;

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let slack_after_next = pr - next_item_size as f64;
        score -= 4.0 * (1.0 - slack_after_next / cap);
    } else if next_item_size > 0 {
        // Next item won't fit: penalize proportionally to wasted potential.
        score += 3.0 * (next_item_size as f64 - pr) / cap;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Prefer bins below mean residual (keeps residuals balanced, avoids
    // fragmenting the fullest bins needed for large future items).
    score += 2.0 * (pr - mean_residual) / cap;

    // New empty bin candidate: only attractive when it's genuinely better,
    // i.e., penalize mildly so open bins win unless fit is poor.
    if bin_residual == bin_capacity {
        score += 6.0 + 4.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual by capacity fractions (1/4, 1/3, 1/2 of C)
    let quarter = bin_capacity / 4;
    let third = bin_capacity / 3;
    let half = bin_capacity / 2;

    // Dead-space penalty grows super-linearly for tiny but nonzero residuals
    if post_residual > 0 && post_residual < quarter {
        score += (quarter - post_residual) as f64 * 1.7;
    }

    // Perfect fit: strong reward
    if post_residual == 0 {
        score -= 60.0;
    }

    // Harmonic sweet spots: post_residual that can host a "class" of typical items
    // (multiples of 10, and the half/third/quarter classes)
    let classes: [u32; 7] = [quarter, third, half, 3 * quarter, 10, 20, 30];
    let mut harmonic_bonus = 0.0;
    for c in classes.iter() {
        if post_residual >= *c && post_residual - *c < 10 {
            harmonic_bonus += 12.0;
        }
    }
    score -= harmonic_bonus;

    // Modulo-class logic on post_residual: residuals divisible by common item granularities
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }
    if post_residual % 5 == 0 && post_residual > 0 {
        score -= 3.0;
    }
    // Odd, awkward residuals get penalized
    if post_residual % 2 == 1 && post_residual < half {
        score += 4.0;
    }

    // Lookahead coupling: does next item fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size < post_residual {
            let gap = post_residual - next_item_size;
            if gap < quarter {
                score -= 20.0 - gap as f64 * 0.25;
            } else {
                score += gap as f64 * 0.08;
            }
        } else {
            // next item cannot fit here; slight penalty proportional to overflow
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    } else {
        // Last item: prefer tightest fit, ignore future
        score -= 15.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins are crowded
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowd = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
        score += 30.0 + crowd * 4.0 + progress * 10.0;
        // but if next item is huge and no open bin will hold both, new bin is fine
        if next_item_size > half && item_size > half {
            score -= 35.0;
        }
    }

    // Mean-residual alignment: prefer bins close to the mean residual (balanced packing)
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Late-stream tightening: waste matters more as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * progress * 0.3;

    // Integer-division threshold: penalize residuals in "unusable" division bands
    let band = post_residual / 10;
    if band == 1 && post_residual != 10 {
        score += 6.0; // 11..19 dead zone
    }
    if band == 4 {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (1..10)
    // or awkward mid-range gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable dead space
    } else if post_residual >= 10 && post_residual < 30 {
        score += 12.0; // awkward gap, only fits small items
    }

    // Reward tight fits strongly (near-exact packing).
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Reward bins whose residual closely matches the item (good fit ratio).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fit_ratio;

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // and avoid opening new bins unnecessarily.
    score += 0.6 * open_bins_count as f64;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // or open-bin count pressure is low.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 / (1.0 + mean_residual / 20.0);
        score += 30.0 + 8.0 * pressure;
        // If lookahead item is large, a fresh bin is more valuable.
        if next_item_size > 60 {
            score -= 15.0;
        }
    }

    // Prefer keeping residuals that can still host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Late in the stream, consolidate into fewer bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits exactly into post_residual
    if next_item_size > 0 {
        let diff = post_residual as i64 - next_item_size as i64;
        if diff == 0 {
            score -= 60.0; // perfect 2-step match
        } else if diff > 0 {
            score -= 25.0 * (1.0 - (diff as f64 / bin_capacity as f64)).max(0.0);
        } else {
            // next item won't fit here; penalize wasted post_residual more strongly
            score += (post_residual as f64) * 0.5;
        }
    }

    // Reward tight fits relative to mean residual
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 10.0 * tightness;

    // Penalize bins whose residual is far above mean (poor utilization) unless last-chance
    if post_residual as f64 > mean_residual {
        score += 0.6 * (post_residual as f64 - mean_residual);
    }

    // Last-chance bin: strong bonus to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate: penalize unless current open bins would leave large dead space
    if bin_residual == bin_capacity {
        if next_item_size > 0 && post_residual as f64 > mean_residual + 5.0 {
            score += 15.0;
        } else {
            score += 5.0;
        }
    }

    // Late-stream: prefer closing out bins tightly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 8.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Is this the brand-new empty bin candidate?
    let is_new_bin = bin_residual == bin_capacity;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Perfect fit gets a strong reward (non-linear: reward grows as post_residual shrinks)
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio) * (1.0 - fit_ratio) * 30.0;

    // Lookahead: if the next item fits exactly into post_residual, reward heavily
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            let next_fit = next_item_size as f64 / post_residual as f64;
            score -= next_fit * 12.0;
        } else {
            // next item cannot use this leftover space: penalize large dead space a bit
            score += (post_residual as f64 - 0.0) * 0.05;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 20.0;
    }

    // Penalize creating very small unusable residuals (< typical small item size 10)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // New-bin candidate handling: give it a handicap so it only wins when open bins fit poorly.
    if is_new_bin {
        // Base handicap scaled by how "crowded" existing bins are
        let crowd = if open_bins_count > 0 { mean_residual / bin_capacity as f64 } else { 0.0 };
        score += 35.0 + crowd * 20.0;
        // Early in the stream, opening new bins is cheaper (more future items to fill them)
        score -= (1.0 - progress) * 15.0;
        // If many bins are open, discourage spreading
        score += open_bins_count as f64 * 1.5;
    } else {
        // Reward using existing bins more when many bins are open (consolidation pressure)
        score -= (open_bins_count as f64).ln().max(0.0) * 2.0;
    }

    // Global mean residual coupling: prefer bins whose residual is near the mean (typical bins)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Mild preference for tighter bins as stream progresses
    score -= progress * (bin_residual as f64 - post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;

    // Smooth non-linear coupling: quadratic/quartic shaping of post_residual vs progress.
    let prog2 = progress * progress;
    score += 4.0 * prog2 * (pr * pr) / cap;

    // Reward tight fits more aggressively as the stream progresses.
    let tightness = 1.0 - pr / cap;
    score -= 6.0 * progress * tightness * tightness;

    // Penalize dead space that cannot fit the next item (smooth interaction).
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0);
        score += 0.8 * (gap / cap) * (1.0 + progress);
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Mild penalty for spreading across many bins; mean residual coupling.
    score += 0.05 * (open_bins_count as f64) * (1.0 - progress);
    score += 0.3 * (mean_residual - pr) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class logic: classify post_residual into residue classes mod 10.
    // Small post_residuals (tight fits) are rewarded heavily; large ones penalized.
    let pr = post_residual;
    let class = (pr % 10) as f64;
    let bucket = pr / 10; // integer division bucket (0..10)

    // Dead-space penalty grows superlinearly with bucket, modulated by residue class.
    score += (bucket as f64).powf(1.7) * (1.0 + class / 45.0);

    // Harmonic reward: post_residuals in classes divisible by 5 or 10 are more
    // likely to be filled by future items (sizes 1..100 unknown distribution).
    if pr > 0 {
        if pr % 10 == 0 {
            score -= 6.0;
        } else if pr % 5 == 0 {
            score -= 3.0;
        } else {
            score += class * 0.15; // awkward residues are harder to reuse
        }
    }

    // Perfect fit is ideal.
    if pr == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size <= pr {
            // partial reward scaled by how well it fits
            score -= 12.0 * (next_item_size as f64 / pr.max(1) as f64);
        } else {
            // post_residual too small for next item: penalize more if very small
            if pr < 10 {
                score += 8.0;
            }
        }
    }

    // New-bin candidate handling: opening a new bin wastes residual capacity
    // elsewhere; penalize unless existing bins are all poor fits.
    if bin_residual == bin_capacity {
        let spread = (mean_residual - (bin_capacity as f64 - item_size as f64)).abs();
        // base penalty so new bins are only chosen when open bins are bad
        score += 15.0 + spread * 0.2;
        // late in stream, prefer reusing bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
        // many open bins with small residuals => reusing is better
        if mean_residual < item_size as f64 * 1.5 {
            score += 20.0;
        }
    }

    // Slight preference for tighter existing bins relative to mean residual.
    score += (mean_residual - bin_residual as f64) * 0.1;

    // Mild pressure against accumulating many open bins.
    score += (open_bins_count as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps (below the smallest
    // plausible item) are unusable "dead space" -> heavy penalty.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item.max(1) * 10 {
        score += 60.0; // dead space zone (tiny gap nothing can use)
    }
    // Penalize moderately small gaps harder as they waste capacity.
    if post_residual > 0 && post_residual <= 15 {
        score += 25.0 * (1.0 - post_residual as f64 / 15.0);
    }

    // Reward perfect / near-perfect fits (low post residual relative to item).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fit_ratio * fit_ratio;

    // Open-bin pressure: prefer consolidating when many bins are open,
    // discourage opening new bins unnecessarily.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when existing bins fit poorly
        // or none fit well (high mean residual waste or few fitting bins).
        let poor_fits = (mean_residual - item_size as f64).abs();
        score += 40.0 + 10.0 * (1.0 - progress);
        score -= (poor_fits / bin_capacity as f64) * 30.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: new bin is fine
        }
        if fitting_bins_count == 1 {
            score += 15.0; // keep last-chance bins for worse cases
        }
    } else {
        // Last-chance bin: strongly favor using it to avoid opening a new bin.
        if fitting_bins_count == 1 {
            score -= 35.0;
        }
        // Prefer bins whose residual is close to item (tight packing).
        let tightness = 1.0 - (bin_residual - item_size) as f64 / bin_capacity as f64;
        score -= 10.0 * tightness;

        // Lookahead: if the next item fits the post residual, reward this placement.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 12.0;
        } else if next_item_size > 0 {
            score += 6.0; // next item won't fit here -> mild penalty
        }

        // Mild pressure to fill fuller bins first when many bins are open.
        score -= 2.0 * (open_bins_count as f64).ln().max(0.0) * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead matching
    if next_item_size > 0 {
        // Perfect match: next item exactly fills the bin -> huge reward
        if post_residual == next_item_size {
            score -= 1000.0;
        }
        // Next item fits perfectly into post_residual region after another placement
        else if post_residual >= next_item_size {
            let two_step_residual = post_residual - next_item_size;
            // Reward tight two-step packing: small leftover after both placements
            score -= 2.0 * (next_item_size as f64) - 0.5 * (two_step_residual as f64);
            if two_step_residual == 0 {
                score -= 500.0;
            }
        } else {
            // Next item cannot follow into this bin: penalize dead space relative to next item
            score += 0.3 * (next_item_size as f64);
        }
    }

    // Penalize leaving dead space below minimum item size (unusable gap)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // Prefer bins tighter than the mean residual (best-fit flavor)
    score -= 0.4 * (mean_residual - post_residual as f64);

    // Slight preference for consolidating into few bins as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * progress * (open_bins_count as f64).sqrt();

    // Brand-new bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        score += 40.0 + 0.5 * (item_size as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let mut score = post_residual as f64;
    let pr = post_residual as f64;
    score += 12.0 * (pr / bin_capacity as f64) * (pr / bin_capacity as f64) * (0.4 + 0.6 * progress);
    if fitting_bins_count == 1 {
        score -= 8.0;
    }
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 3.0 * (next_item_size as f64 / bin_capacity as f64);
    } else if next_item_size > 0 {
        score += 2.0 * (1.0 - (pr / next_item_size as f64).min(1.0));
    }
    score += 0.05 * (mean_residual - pr).abs();
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues divisible by small classes are reusable.
    let pr = post_residual;
    let mut bonus = 0.0;
    if pr == 0 {
        bonus -= 40.0; // perfect fit
    } else {
        if pr % 10 == 0 { bonus -= 8.0; }
        if pr % 5 == 0 { bonus -= 4.0; }
        if pr % 20 == 0 { bonus -= 3.0; }
        // dead-space penalty for tiny unusable residues
        if pr < 10 { bonus += 25.0; }
        else if pr < 20 { bonus += 10.0; }
    }
    score += bonus;

    // Lookahead: reward if next item fits the post residual
    if next_item_size > 0 && next_item_size <= pr {
        score -= 12.0;
        let slack = (pr - next_item_size) as f64;
        score -= 6.0 * (1.0 - slack / cap);
    } else if next_item_size > pr {
        score += 6.0;
    }

    // Tightness reward: fraction of bin consumed by this item
    let fill = item_size as f64 / cap;
    score -= 15.0 * fill * fill;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate: only attractive when no good open option exists
    if bin_residual == bin_capacity {
        score = cap * 0.75 + mean_residual * 0.3 + (open_bins_count as f64) * 2.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 8.0; // fresh bin good for upcoming large item too
        }
        if fitting_bins_count <= 1 {
            score -= 30.0;
        }
    }

    // Mild time decay: later in stream, consolidate more aggressively
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * t * (mean_residual / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny gaps are unusable -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 + (10 - post_residual) as f64 * 3.0;
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward leaving a gap that can still fit the next item (lookahead synergy).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            score += 4.0;
        }
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 1.5;

    // Mean residual coupling: prefer bins deviating below mean (tighter bins).
    score += (mean_residual - bin_residual as f64).max(-20.0).min(20.0) * 0.3;

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: neutral baseline, slightly favored early, penalized
    // when the item fits well somewhere else (post_residual == residual - item
    // equals capacity - item for a fresh bin, i.e. large leftover).
    if bin_residual == bin_capacity {
        score += 6.0 + (item_size as f64 / bin_capacity as f64) * 4.0;
    }

    // Mild progression term: later in the stream, be more conservative.
    if total_items > 0 {
        score += (step_index as f64 / total_items as f64) * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: tighter fit (small post_residual) is good.
    // Penalize "awkward" residuals that are too small to be useful later.
    let min_useful = 10.0; // smallest expected future item
    if (post_residual as f64) < min_useful && post_residual > 0 {
        score += 25.0; // dead space penalty
    }

    // Aggressive 2-step lookahead: reward bins whose residual after placement
    // can still accommodate the next item exactly or well.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let post = post_residual as f64;
        if next <= post {
            let fit_quality = 1.0 - (post - next) / bin_capacity as f64;
            // Strong reward if next item fits snugly after this placement.
            score -= 40.0 * fit_quality;
            // Extra bonus for perfect chain (post_residual == next_item_size).
            if post_residual as f64 == next {
                score -= 30.0;
            }
        } else {
            // Next item won't fit here afterwards; mild penalty scaled by overflow.
            let overflow = next - post;
            score += 0.15 * overflow;
        }
    }

    // Relative-to-mean-residual term: prefer bins with residual below the mean
    // (fill up the "nearly full" bins first, keep large gaps open).
    let post_f = post_residual as f64;
    if mean_residual > 0.0 {
        score += 0.6 * (post_f - mean_residual);
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: make opening a new bin unattractive unless
    // current fits are terrible. New empty bin has post_residual = capacity - item,
    // which is large, so it naturally scores high; add extra penalty that decays
    // as the stream progresses (early on, opening bins is cheaper).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 20.0 + 30.0 * progress;
    }

    // Slight preference to keep the number of open bins from exploding.
    score += 0.5 * open_bins_count as f64;

    // Prefer using bins whose current residual was already tight.
    score += 0.2 * (bin_residual as f64 - item_size as f64 - post_f).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual relative to capacity is good.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: post_residual too small for any plausible future item (1..100).
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    }

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 20.0;
    }

    // Lookahead: if the next item fits exactly in the post_residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // Next item fits but leaves waste; mild reward proportional to leftover after next.
            let after_next = post_residual - next_item_size;
            score -= 6.0 * (1.0 - after_next as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; slight penalty scaled by how much it overflows.
            let overflow = (next_item_size - post_residual) as f64;
            score += 0.05 * overflow;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Many open bins: encourage consolidation (favor existing bins over new ones).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.02 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Compare against mean residual: bins with less residual than average are better targets.
    score += 0.15 * (mean_residual - bin_residual as f64);

    // New-bin candidate handling: make it attractive only when no open bin is a good fit.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, reduced late in the stream or with many open bins.
        let base_cost = 30.0 - 10.0 * progress;
        // If the item is large relative to capacity, opening fresh is more reasonable.
        let large_item_relief = (item_size as f64 / bin_capacity as f64) * 15.0;
        // If few bins fit the item, new bin is more acceptable.
        let scarcity_relief = if fitting_bins_count <= 1 { 10.0 } else { 0.0 };
        score += base_cost - large_item_relief - scarcity_relief;
        // Lookahead synergy: fresh bin can host both current and next item.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 12.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer minimal post-residual, with non-linear polynomial shaping.
    let mut score = pr + 0.35 * (pr * pr / cap);

    // Smooth coupling: as stream progresses, dead space matters more (fewer future chances to fill).
    score += 0.9 * progress * (pr * pr / cap);

    // Tight fit reward: polynomial in fill ratio.
    let fill = it / cap;
    score -= 30.0 * fill * fill;

    // Last-chance bonus: strongly favor the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // Lookahead: reward residual that can still fit the next item (smooth polynomial).
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        let nxt = next_item_size as f64;
        score -= 8.0 * (nxt / cap) * (1.0 - pr / cap);
    } else if next_item_size > 0 {
        // Penalize residuals that block the next item, scaled by how close it was.
        let gap = (next_item_size as f64 - pr).max(0.0);
        score += 4.0 + 0.1 * gap;
    }

    // New-bin candidate: opening a bin is only attractive when current bins are crowded.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let crowding = mean_residual / cap;
        score = 45.0 + 40.0 * (1.0 - crowding) + 20.0 * progress
            - 30.0 * (crowding * crowding);
        // Slight preference for new bin when item is large relative to mean residual.
        score -= 10.0 * (it / cap);
    } else {
        // Mild penalty for bins far from the mean residual (spread control).
        let dev = (pr - mean_residual).abs() / cap;
        score += 6.0 * dev * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: prefer tight fits (low post_residual).
    let mut score = post;

    // Harmonic class of post_residual: dead-space buckets.
    // Residuals that are "useful" (>= next typical sizes) get a discount;
    // tiny unusable slivers get a penalty.
    let next = next_item_size as f64;
    if next > 0.0 {
        if post >= next {
            // This bin can also host the lookahead item: strong reward.
            score -= 12.0 + (post - next) * 0.15;
        } else {
            // Dead space relative to lookahead: penalize the sliver.
            score += (next - post) * 0.35;
        }
    }

    // Modular harmonic classes on post_residual (cap=100): classify
    // residuals by divisibility into useful chunk sizes.
    let pr = post_residual;
    if pr == 0 {
        score -= 20.0; // perfect closure
    } else {
        let mut class_bonus = 0.0;
        if pr % 10 == 0 { class_bonus += 4.0; }
        if pr % 20 == 0 { class_bonus += 3.0; }
        if pr % 25 == 0 { class_bonus += 3.0; }
        if pr % 50 == 0 { class_bonus += 4.0; }
        if pr >= 80 { class_bonus += 2.0; }        // near-empty leftover still flexible
        if pr < 10 { class_bonus -= 6.0; }         // unusable sliver
        score -= class_bonus;
    }

    // Integer-division threshold: post_residual / item_size ratio
    // penalize bins where the item barely fits (wasteful split).
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    if tightness > 0.9 {
        score += 3.0 * (tightness - 0.9) * 10.0;
    } else if tightness > 0.6 {
        score -= 2.0; // sweet spot: item fills most of the bin
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (unless the fit is horrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: make it attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        // Opening cost grows with stream progress and number of open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 25.0 + 10.0 * progress + 0.5 * open_bins_count as f64;
        // But if the lookahead item is large, a fresh bin is more valuable.
        if next >= 50.0 {
            score -= 18.0;
        }
    }

    // Mean residual coupling: when open bins are already slack, avoid
    // spreading items thin; prefer bins below mean residual (tighter bins).
    if bin_residual as f64 > mean_residual {
        score += 1.5;
    } else {
        score -= 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
