        // new-bin candidate: base cost of a fresh bin
        score += 15.0;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let avg_item = item_size as f64;
        // prefer new bin if open bins are fragmented (mean residual low relative to item)
        if mean_residual < avg_item * 0.5 && open_bins_count > 2 {
            score -= 20.0;
        }
        // late in stream, prefer filling existing bins
        score += 10.0 * progress;
        // many open bins => consolidation pressure
        score += (open_bins_count as f64).ln().max(0.0) * 2.0;
    }

    // Slight preference for bins with below-average residual (concentrate filling)
    if (bin_residual as f64) < mean_residual {
        score -= 1.0;
    } else {
        score += 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    let item = item_size as f64;
    let next = next_item_size as f64;

    // Base: post residual, with non-linear polynomial shaping
    let mut score = pr
        + 40.0 * pr_norm * pr_norm
        - 60.0 * pr_norm * pr_norm * pr_norm;

    // Coupling with stream progress: late in stream, prefer tighter fits more strongly
    score += 50.0 * progress * pr_norm * (1.0 - pr_norm);

    // Lookahead: reward if next item fits the post residual (smooth interaction)
    if next > 0.0 {
        let fits = (1.0 - (next - pr).abs() / cap).max(0.0);
        score -= 25.0 * fits * fits * (1.0 - progress);
        // penalize when next item nearly but not quite fits (dead space risk)
        let gap = (pr - next) / cap;
        if gap > 0.0 && gap < 0.2 {
            score += 30.0 * (0.2 - gap) * (1.0 - progress);
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 35.0 * (1.0 - pr_norm);
    }

    // Mild penalty for spreading across many open bins
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * pr_norm;

    // Encourage placing large items into bins with large residual
    score -= 10.0 * (item / cap) * (bin_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize dead space into capacity fractions.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap; // 0..1

    // Penalize residuals in "dead zones" that few item sizes (1..100) can ever fill.
    // Class boundaries via integer division thresholds: classes of size 10.
    let class = post_residual / 10;
    let class_penalty = match class {
        0 => -30.0,           // near-perfect fit
        1 => 5.0,             // 10..19: only tiny items fit
        2 => 2.0,             // 20..29
        3 => 0.0,
        4 => 0.0,
        5 => 1.0,
        6 => 2.0,
        7 => 3.0,
        8 => 4.0,
        9 => 6.0,             // 90..99: nearly empty bin
        _ => 0.0,
    };
    score += class_penalty;

    // Modulo-arithmetic harmony: reward residuals that are multiples of common item sizes.
    if post_residual > 0 {
        let mut harmony = 0.0;
        for m in [10u32, 20, 25, 50] {
            if post_residual % m == 0 {
                harmony += 6.0;
            }
        }
        score -= harmony;
    } else {
        score -= 40.0; // perfect fill
    }

    // Lookahead: if next item fits exactly into post_residual, strongly reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if post_residual - next_item_size <= 10 {
            score -= 20.0;
        } else {
            score -= 8.0;
        }
    }
    // If next item cannot fit this bin anyway, mild penalty for wasting good space now.
    if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
        score += 10.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: keep empty-bin score anchored above decent fits.
    if bin_residual == bin_capacity {
        score = cap - post; // = 0 baseline
        score += 25.0;      // cost of opening a new bin
        // Open a new bin early when many bins are open and mean residual is fragmented.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 15.0 * (1.0 - progress) * (mean_residual / cap).min(1.0);
        if next_item_size > 0 && next_item_size <= bin_residual {
            score -= 10.0;
        }
    }

    // Mild pressure to prefer fuller bins when many bins are open.
    score += (open_bins_count as f64).ln().max(0.0) * frac * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any future item
    // (items are >= 1, but practically anything below ~10 is hard to reuse) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Post-residuals that exactly match the lookahead item are extremely desirable.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }
    // Post-residual that can still fit the next item is mildly rewarded.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 20.0;
    }

    // Tightness reward: the larger the fraction of the bin used, the better.
    let tightness = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 15.0 * tightness;

    // Open-bins pressure: with many open bins, prefer filling existing ones;
    // with few open bins, allow opening new ones more freely.
    let pressure = open_bins_count as f64 / (total_items.max(1) as f64).sqrt();
    score += 4.0 * pressure;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: a fresh empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Prefer a new bin only if current bins are quite full on average and
        // the item would leave a poor fit elsewhere.
        let mean_tightness = 1.0 - (mean_residual / bin_capacity as f64);
        let would_be_tight = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
        if mean_tightness > 0.75 && would_be_tight < 0.5 {
            score -= 18.0;
        } else {
            score += 22.0;
        }
    }

    // Mean-residual coupling: penalize bins far above the mean residual (they waste space),
    // reward bins below the mean (they are the fullest).
    if bin_residual as f64 > mean_residual {
        score += 3.0;
    } else {
        score -= 3.0;
    }

    // Late in the stream, consolidate aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead: bin residual after this item exactly matches next item
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Next item fits in the post residual
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0 + 15.0 * (next_item_size as f64 / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space: post residual too small for next item
        let waste = post_residual as f64;
        score += 10.0 + 0.5 * waste;
    }

    // Tight fit reward (small post residual overall)
    score -= 20.0 * (1.0 - post_residual as f64 / bin_capacity as f64).powi(6);

    // Last chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: penalize opening a new bin unless current residual is unusable
    if bin_residual == bin_capacity {
        let pressure = if next_item_size > 0 && post_residual >= next_item_size { 1.0 } else { 0.0 };
        score += 55.0 - 40.0 * pressure;
        if mean_residual < item_size as f64 && mean_residual > 0.0 {
            score -= 30.0; // existing bins are too full
        }
    }

    // Slight preference for filling emptier bins early
    if bin_residual as f64 > mean_residual + 5.0 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 45.0 * tightness * tightness;

    // Penalize dead space that cannot fit the next item (lookahead-aware waste).
    if next_item_size > 0 {
        if post_residual < next_item_size {
            let waste = (next_item_size - post_residual) as f64;
            score += 0.9 * waste;
        } else {
            // Reward bins whose leftover can still host the next item.
            score -= 8.0;
        }
        // Bonus if next item exactly fills the post residual.
        if post_residual == next_item_size {
            score -= 25.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Penalize spreading across many open bins when residuals are large.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if open_bins_count > 2 {
        score += 0.5 * (open_bins_count as f64).ln() * (1.0 - progress);
    }

    // Coupling with mean residual: prefer bins close to the mean (balance), but
    // reward going below mean late in the stream to close out bins.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.25 * dev;
    if progress > 0.7 && (bin_residual as f64) < mean_residual {
        score -= 10.0 * (1.0 - progress);
    }

    // New-bin candidate: penalize opening a new bin unless current bin leaves
    // unusable fragments or fitting bins are scarce.
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let frag = if next_item_size > 0 && post_residual < next_item_size { 1.0 } else { 0.0 };
        score += 60.0 - 40.0 * (scarcity + frag).min(1.0);
        if open_bins_count == 0 {
            score -= 100.0; // must open first bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;
    let norm_item = item_size as f64 / cap;

    // Base: quadratic penalty on wasted space, modulated by stream progress.
    let mut score = post * (1.0 + 1.5 * norm_post * norm_post);

    // Smooth coupling: later in the stream, tight fills matter more.
    score -= 20.0 * progress * (1.0 - norm_post) * (1.0 - norm_post);

    // Reward filling bins tightly relative to mean residual (smooth cubic).
    let mean_gap = (mean_residual - post) / cap;
    score -= 8.0 * mean_gap * mean_gap * mean_gap;

    // Last-chance bonus: strongly prefer the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Slight pressure against accumulating too many open bins.
    score += 0.3 * (open_bins_count as f64).ln().max(0.0);

    // Lookahead: if next item fits exactly into post_residual, reward heavily (smooth).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let fit_quality = 1.0 - (post - nxt) / cap;
            score -= 12.0 * fit_quality * fit_quality;
        } else {
            score += 3.0 * (nxt - post) / cap;
        }
    }

    // Discard trivially tiny residuals smoothly (dead-space aversion).
    score -= 6.0 * (-norm_post * 8.0).exp();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: which capacity fraction band it belongs to.
    let item_class = (item_size * 4) / bin_capacity; // 0..3
    let next_class = if next_item_size == 0 { 0 } else { (next_item_size * 4) / bin_capacity };

    // Reward tight fits: post_residual in low harmonic band gets discounted.
    let tight = ((post_residual * 4) / bin_capacity) as f64;
    score -= tight * 6.0;

    // Penalize dead space below the smallest item (unusable residual).
    let min_item = 1u32;
    if post_residual < min_item {
        score += 1000.0;
    } else {
        // Small but usable residual is fine; large residual wastes a bin slot.
        if post_residual > bin_capacity / 2 {
            score += (post_residual - bin_capacity / 2) as f64 * 0.8;
        }
    }

    // Modulo-arithmetic compatibility: reward when next item's class complements
    // the post residual class (their harmonic sum fits capacity).
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
        // Extra reward for harmonic class match (both small or both large).
        if item_class == next_class {
            score -= 4.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Post residual cannot host next item: mild penalty scaled by class gap.
        let gap = if next_class > item_class { next_class - item_class } else { item_class - next_class };
        score += gap as f64 * 2.5;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening fresh bins unless current bins are crowded.
    if bin_residual == bin_capacity {
        score += 55.0;
        if open_bins_count == 0 {
            score -= 100.0; // must open the first bin
        }
        // Early in the stream, opening bins is cheaper (more future flexibility).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 20.0;
    }

    // Prefer bins whose residual deviates favorably from the mean residual:
    // placing into a below-mean bin balances residuals across bins.
    let diff = mean_residual - bin_residual as f64;
    score -= diff * 0.15;

    // Late in the stream, be greedy: minimize post residual aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_capacity - post_residual) as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny gaps (< 10, minimum item size) are pure waste.
    if post_residual < 10 {
        score -= 50.0; // perfect/near-perfect fit is excellent
    } else if post_residual <= 20 {
        // Gaps of 10..20 are usable only by small items; mild penalty relative to baseline
        score += 5.0;
    } else if post_residual <= 40 {
        score += 12.0; // moderately awkward dead space
    }

    // Reward exact fit strongly
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        if gap < 10.0 {
            score -= 40.0; // chain of near-perfect fits
        } else {
            score -= 10.0 * (1.0 - gap / post_residual as f64);
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Dead space that the next item cannot use at all
        score += 15.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor tight fills.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual.max(1.0) / 20.0);
    score += pressure * 2.0;

    // New-bin candidate handling: opening a new bin is only attractive when this bin's
    // fit would leave a large unusable gap or when the current bin is already tight.
    if bin_residual == bin_capacity {
        // New empty bin: post_residual == 100 - item_size, large residual = flexible.
        score -= 8.0; // slight bonus so new bins compete when fits are bad
        if item_size >= 50 {
            score -= 10.0; // big items into fresh bins is fine
        }
    }

    // Progress: late in the stream, be extra greedy about dead space.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    // Alignment with mean residual: prefer bins whose residual deviates usefully.
    score += 0.1 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // matches the next item size well (perfect two-item packing).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if pr >= nxt && pr - nxt <= 10.0 {
            // next item fits almost perfectly afterwards -> strong reward
            score -= 30.0 + 0.5 * nxt;
        } else if pr >= nxt {
            // next item fits but leaves slack -> mild reward
            score -= 8.0 - 0.05 * (pr - nxt);
        } else {
            // next item cannot use the leftover -> penalize dead space
            let waste = nxt - pr;
            score += 0.3 * waste.min(40.0);
        }
        // Bonus if item + next item exactly fill the bin
        if post_residual as u32 == next_item_size {
            score -= 25.0;
        }
    }

    // Relative-to-mean coupling: prefer bins with residual below the mean
    // (tighter bins get emptied first, keeping loose bins flexible).
    score -= 0.4 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 {
        score -= 15.0 + 0.2 * item_size as f64;
    }

    // Penalize creating very small unusable residuals (dead space < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 20.0;
    }

    // Mild preference for keeping few open bins when the stream is young.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate: only attractive when the fit here is poor.
    if bin_residual == bin_capacity {
        score += 5.0 + 0.1 * item_size as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to item size.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize dead space: post_residual too small to be useful for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    } else if post_residual >= 10 && post_residual < 25 {
        score += 8.0;
    }

    // Exact fill is ideal.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits the post-residual, reward this bin.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
            // Extra reward if next item fills bin completely after placement.
            if post_residual == next_item_size {
                score -= 15.0;
            }
        } else if post_residual > 0 && post_residual < next_item_size {
            // Dead space relative to the known next item.
            score += 4.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 18.0;
    }

    // Global state: many open bins with high mean residual -> discourage
    // spreading; prefer consolidating into bins with below-mean residual.
    let diff = mean_residual - bin_residual as f64;
    score += 0.05 * diff;

    // Time horizon: early in the stream, be more willing to open new bins
    // (plenty of future items to fill them); late in stream, prefer existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses, and when
        // open bins are underutilized.
        score += 10.0 * progress;
        score += 0.08 * open_bins_count as f64;
        if mean_residual > bin_capacity as f64 * 0.5 {
            score += 15.0;
        }
    } else {
        // Existing bins get slightly more attractive late in the stream.
        score -= 3.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let x = post / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = x * x * (1.0 + 3.0 * progress) + x * (1.0 - progress);

    // Penalize dead space that no plausible item can use
    let waste = x * x * x * cap;
    score += 0.35 * waste;

    // Reward tight fits, more so early in the stream
    score -= 6.0 * (1.0 - progress) * (x * (1.0 - x));

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 4.0;
    }

    // Lookahead: favor bins leaving room for the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 2.0 * (1.0 - (post - nxt) / cap);
        } else {
            score += 1.5 * (nxt - post) / cap;
        }
    }

    // Mild preference for consolidating into fewer bins
    score += 0.02 * open_bins_count as f64 * x;

    // Divergence from mean residual: prefer atypical good fits
    score += 0.1 * (post - mean_residual).abs() / cap * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: small dead space is bad unless tiny
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // fraction of capacity wasted

    // Penalize dead space quadratically, but reward small usable residuals
    if post_residual > 0 {
        let usable = if post_residual >= 10 { 0.0 } else { 40.0 };
        score += frac * frac * 120.0 + usable;
    }

    // Modulo classes on post_residual: residuals that are multiples of common
    // item sizes (10, 20, 25, 50) are reusable -> reward
    let pr32 = post_residual;
    if pr32 > 0 && (pr32 % 10 == 0 || pr32 % 25 == 0) {
        score -= 12.0;
    }
    if pr32 >= 50 {
        score -= 8.0; // half-capacity residual is very reusable
    }

    // Lookahead: if next item fits in post_residual, big reward
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 25.0;
        // even better if next item exactly fills the future residual
        if next_item_size == post_residual {
            score -= 30.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item won't fit here; mild penalty for trapping space
        score += 6.0;
    }

    // Last-chance bin: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins fit poorly
    if bin_residual == bin_capacity {
        // baseline cost of opening a new bin
        score = cap * 0.62;
        if open_bins_count == 0 {
            score = 0.0; // must open first bin
        } else if next_item_size > 0 && next_item_size > mean_residual {
            // open bins can't accommodate the near future well -> new bin more attractive
            score -= 15.0;
        }
        if fitting_bins_count == 0 {
            score = -50.0;
        }
    }

    // Stream progression: early on, be more willing to open bins (spread items)
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= (1.0 - progress) * 10.0;
    }

    // Prefer filling bins with larger residual when many bins open (consolidation)
    score += (open_bins_count as f64) * 0.15;

    // Tie-break: tighter fit (smaller residual gap to item) preferred
    score += (bin_residual - item_size) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are the worst outcome.
    if post_residual > 0 {
        // Penalize tiny unusable gaps heavily (below typical minimum item size).
        if post_residual < 10 {
            score += 60.0 * (10.0 - post_residual as f64);
        } else {
            // Smooth penalty for small gaps relative to capacity.
            let gap_frac = post_residual as f64 / bin_capacity as f64;
            score += 25.0 * gap_frac * (1.0 - gap_frac);
        }
    } else {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Reward bins whose residual tightly matches the item (good fit).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fit_ratio;

    // Open-bin pressure: discourage proliferation of bins when many are open.
    score += 3.0 * open_bins_count as f64;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: make it unattractive unless no good open bin exists.
    if bin_residual == bin_capacity {
        score += 30.0 + 5.0 * open_bins_count as f64;
        // But if the next item is large and this item is small, opening a fresh
        // bin may preserve big residuals for it; slightly soften the penalty.
        if next_item_size > 60 && item_size < 40 {
            score -= 25.0;
        }
    }

    // Lookahead coupling: if next item fits exactly into the post residual,
    // reward this placement strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack < 10 {
            score -= 30.0;
        } else {
            score -= 10.0;
        }
    }

    // Mean residual context: prefer bins below mean residual (tighter bins).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size well.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            // Perfect match (gap 0) gets the biggest bonus.
            score -= 60.0 * (1.0 - gap / bin_capacity as f64);
            // Extra reward if the NEXT item exactly fills the bin afterwards.
            if post_residual == next_item_size {
                score -= 40.0;
            }
        } else {
            // Next item cannot follow into this bin: penalize small leftover dead space.
            let dead = post_residual as f64;
            if dead < 10.0 {
                score += 25.0 + (10.0 - dead) * 2.0;
            }
        }
    }

    // Relative-to-mean-residual term: prefer bins with below-average residual
    // (tighter bins first), keeping large residuals for future big items.
    score -= (mean_residual - bin_residual as f64) * 0.8;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize opening new bins when existing bins give a reasonable fit.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let waste = bin_capacity as f64 - item_size as f64;
        score += 15.0 + waste * 0.5 + progress * 10.0;
        // If lookahead can chain into the fresh bin, soften the penalty.
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 5 {
            score -= 35.0;
        }
    }

    // Mild preference for filling bins almost exactly regardless of lookahead.
    if post_residual <= 2 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual) with diminishing returns.
    let cap = bin_capacity as f64;
    let fit_ratio = 1.0 - (post_residual as f64) / cap; // 1 = perfect fill
    score -= 30.0 * fit_ratio * fit_ratio;

    // Perfect fill is a jackpot.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // chain fill: next item completes this bin
        } else if next_item_size <= post_residual {
            // next item still fits: mild reward, scaled by how much would remain
            let rem = post_residual - next_item_size;
            score -= 10.0 * (1.0 - (rem as f64) / cap);
        } else {
            // next item cannot use the leftover: penalize dead space creation
            score += 5.0 + 0.2 * (post_residual as f64);
        }
    }

    // Dead-space penalty: leftovers too small for the minimum plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin should only win when no open bin
    // gives a decent fit, or when open bins are already crowded/fragmented.
    if bin_residual == bin_capacity {
        // Opening a new bin is cheap early, expensive late / with many bins open.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 25.0 + 10.0 * progress + 0.5 * open_bins_count as f64;
        // If the mean residual across open bins is small, open bins are nearly
        // full anyway -> opening a new bin is more acceptable.
        score -= 0.3 * mean_residual;
        // If next item is huge and this fresh bin could chain it, soften penalty.
        if next_item_size >= 70 {
            score -= 8.0;
        }
    }

    // Global fragmentation pressure: when many open bins exist with large mean
    // residual, prefer consolidating into existing bins (avoid bin sprawl).
    if mean_residual > 40.0 && open_bins_count > 3 && bin_residual != bin_capacity {
        score -= 3.0;
    }

    // Late-stream tightening: as the stream progresses, waste matters more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let tightness = 1.0 - pr / cap; // how full bin becomes
    let nx = next_item_size as f64 / cap;

    let mut score = pr;

    // Smooth non-linear coupling: prefer small post_residual, weighted by progress
    score -= (pr / cap).powf(1.5) * 12.0 * (0.5 + progress);

    // Reward tight fits with smooth saturation
    score -= (tightness * tightness) * 10.0;

    // Penalize post-residual that is too small to matter (dead space) smoothly
    let dead = (1.0 - (pr / cap) * 4.0).max(0.0);
    score += dead * dead * 8.0;

    // Lookahead: reward if next item fits the post-residual (smooth)
    if nx > 0.0 {
        let fit_next = (pr - nx * cap) / cap;
        if fit_next >= 0.0 {
            score -= fit_next * fit_next * 6.0;
        } else {
            score += (-fit_next) * 5.0;
        }
    }

    // Last-chance bin bonus (smooth ramp via fitting_bins_count)
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - progress * 0.5);
    }

    // Mild penalty for spreading across many open bins
    score += (open_bins_count as f64).ln() * 1.5;

    // Encourage balancing residuals toward mean early on
    score += ((pr - mean_residual) / cap).abs() * 2.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: bins whose leftover falls into
    // "nice" classes (multiples of 10, or small enough to be near-dead) are preferred.
    let nice_class = (post_residual % 10 == 0) as f64 * 6.0;
    score -= nice_class;

    // Dead-space penalty: residuals that are too small to hold even the smallest
    // plausible future item are worthless; push score up so they lose.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post-residual,
    // this bin becomes a two-item chain -> big reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 35.0;
    }
    if next_item_size > 0 && post_residual >= next_item_size {
        // reward proportional to how tightly the next item would fit
        let slack = (post_residual - next_item_size) as f64;
        if slack <= 10.0 {
            score -= 12.0 - slack * 0.6;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: an empty bin is a costly resource. Penalize it
    // mildly so it only wins when open bins are genuinely bad fits.
    if bin_residual == bin_capacity {
        score += 30.0;
        // But late in the stream, opening fresh bins with full flexibility is fine.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 15.0;
        // If next item is large and this bin would be fresh, slight bonus.
        if next_item_size >= item_size {
            score -= 5.0;
        }
    }

    // Prefer filling bins that are already relatively full (tight packing):
    // compare bin_residual against mean residual of open bins.
    if bin_residual != bin_capacity {
        let tightness = (bin_residual as f64 - mean_residual).max(0.0);
        score -= tightness * 0.15;
    }

    // Integer-division threshold: residuals in [10, 25] can host a mid item;
    // treat them as moderately valuable, larger residuals less urgent.
    let div_class = post_residual / 25; // 0,1,2,3,4 classes
    score += div_class as f64 * 2.0;

    // Modulo harmony: residual sharing a common divisor class with the item size
    // hints at repeatable packing patterns.
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    // Many open bins -> encourage consolidation into existing bins.
    if open_bins_count > 4 && bin_residual != bin_capacity {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // minimum plausible item (1..100 range, but typical items >= 10) are
    // nearly worthless. Penalize hard when post_residual falls into a
    // "dead zone" (1..10) since almost nothing fits there.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + 4.0 * (10 - post_residual) as f64;
    }

    // Penalize mid-range gaps that can't fit the lookahead item when the
    // lookahead exists: dead space relative to what's coming next.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0 + 0.25 * (next_item_size - post_residual) as f64;
    }

    // Reward tight fits (small post_residual) extra.
    if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 15 {
        score -= 10.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance pressure: if this is the only bin that fits, strongly
    // prefer using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new bins
    // (handled implicitly since new bin has post_residual == capacity);
    // add slight penalty proportional to open_bins_count for spreading out.
    score += 0.15 * open_bins_count as f64;

    // New-bin candidate: penalize opening a fresh bin unless current item
    // is large or residuals across bins are small (poor fits elsewhere).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let large_item = item_size as f64 > 0.6 * bin_capacity as f64;
        if !large_item && mean_residual >= item_size as f64 {
            score += 25.0 + 20.0 * (1.0 - progress);
        } else {
            score += 5.0;
        }
    }

    // Slight preference for bins whose residual is close to mean (balance).
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Lookahead: perfect 2-step match is highly desirable.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 200.0; // exact fill of both items
        } else if post_residual >= next_item_size {
            // next item still fits; prefer small leftover after both placements
            let after_next = post_residual - next_item_size;
            score += after_next as f64 * 0.5;
            score -= 30.0;
        } else {
            // next item cannot use the leftover: dead space risk
            let waste = next_item_size - post_residual;
            score += waste as f64 * 0.8;
        }
    } else {
        // last item: minimize leftover directly
        score += 5.0;
    }

    // Penalize tiny unusable residuals (dead space) strongly.
    if post_residual < 10 {
        score += 40.0;
    }

    // Compare against mean residual: closing a below-average bin is good
    // (keeps large-residual bins flexible).
    if (post_residual as f64) < mean_residual {
        score -= 15.0;
    } else {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: should only win when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 120.0;
        // cheaper to open a bin early in the stream (more future use)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 40.0;
        // if many bins are open, prefer consolidating instead
        score += open_bins_count as f64 * 3.0;
        // if the next item is large, a fresh bin is more attractive
        if next_item_size >= 50 {
            score -= 25.0;
        }
    }

    // Mild preference for tighter bins overall.
    score += (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: residuals too small for the smallest item.
    if post_residual < 10 {
        score += 25.0 - 0.25 * post_residual as f64;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * tightness;

    // Lookahead: bonus if the next item fits well into post_residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_waste = (post_residual - next_item_size) as f64;
        score -= 6.0 * (1.0 - next_waste / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item won't fit here; penalize slightly if we leave a stub.
        score += 3.0;
    }

    // Last chance: strongly favor using the only bin that fits to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Time horizon: late in the stream, consolidate; early, keep flexibility.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.3 * progress;

    // Global state: many open bins with high mean residual -> favor filling existing bins.
    if open_bins_count > 0 {
        let fill_pressure = mean_residual / bin_capacity as f64;
        if bin_residual as f64 <= mean_residual {
            score -= 2.0 * fill_pressure;
        } else {
            score += 2.0 * fill_pressure;
        }
    }

    // New-bin candidate handling: only attractive for large items or no good fits.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        if large_item > 0.7 || (fitting_bins_count <= 1 && next_item_size > 0 && next_item_size >= post_residual.min(bin_capacity)) {
            score -= 9.0;
        } else {
            score += 6.0 + 4.0 * (1.0 - large_item);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_post = post / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    let mut score = post;

    // Smooth non-linear coupling: waste grows quadratically as post-residual shrinks
    score += 18.0 * (1.0 - norm_post) * (1.0 - norm_post) * norm_item * cap;

    // Progress-dependent tightness reward: late in the stream, prefer tight fits more strongly
    score -= (12.0 + 26.0 * progress) * (1.0 - norm_post) * (1.0 - norm_post) * cap;

    // Dead-space penalty: residual too small to fit typical items (smooth sigmoid-like term)
    let dead = 1.0 / (1.0 + (norm_post * 12.0 - 4.0).exp());
    score += 22.0 * dead * cap * (0.3 + 0.7 * progress);

    // Lookahead coupling: reward if next item fits post-residual, penalize near-miss
    if next_item_size > 0 {
        let fits_next = (post_residual as f64 - next_item_size as f64) / cap;
        let smooth = 1.0 / (1.0 + (-fits_next * 20.0).exp());
        score -= 14.0 * smooth * cap;
        score += 6.0 * (1.0 - smooth) * norm_next * cap;
    }

    // Last-chance bonus: only one fitting bin left, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Mild penalty for spreading across many bins when mean residual is high
    score += 0.35 * (open_bins_count as f64).ln().max(0.0) * (mean_residual / cap - norm_post).abs() * cap;

    // Slight new-bin aversion that decays with progress
    if bin_residual == bin_capacity {
        score += 6.0 * (1.0 - progress) + 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

