        score -= 15.0;
    } else {
        // Harmonic penalty on wasted fraction of capacity.
        score += 30.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward tight fits relative to item size (harmonic coupling).
    if item_size > 0 {
        score -= 20.0 / (1.0 + post_residual as f64 / item_size as f64);
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: penalize opening a new bin when fitting bins exist.
    if bin_residual == bin_capacity {
        score += 80.0 * (1.0 - 1.0 / (open_bins_count as f64 + 1.0));
        // Early in the stream, opening bins is cheaper.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 40.0 * (1.0 - progress);
    }

    // Lookahead: reward bins whose post_residual accommodates the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0;
        } else if post_residual > 0 {
            score += 10.0;
        }
    }

    // Prefer filling bins with larger mean residual less (they have more room elsewhere).
    score += 0.05 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let item = item_size as f64;
    let residual = bin_residual as f64;
    let post = post_residual as f64;
    let next = next_item_size as f64;
    let open = open_bins_count as f64;
    let fitting = fitting_bins_count as f64;
    let progress = if total_items > 0 {
        step_index as f64 / total_items as f64
    } else {
        0.0
    };

    let is_new_bin = bin_residual == bin_capacity;
    let open_pressure = open / (open + 4.0);
    let item_ratio = item / cap;
    let next_likely_elsewhere = next > 0.0
        && open_bins_count > 1
        && mean_residual + 0.5 >= next;

    let mut score = post;

    if post <= 0.0 {
        score -= cap * (0.55 + 0.40 * open_pressure + 0.15 * item_ratio);
    } else if next > 0.0 {
        let next_fits_leftover = post + 0.5 >= next;
        let next_could_use_this_bin = residual + 0.5 >= next;
        let blocks_next = !next_fits_leftover && next_could_use_this_bin;
        let gap_limit = (cap * 0.14).max(1.0);

        if post < gap_limit {
            let severity = (1.0 - post / gap_limit).powi(2);
            let mut dead_space = cap
                * (0.55 + 0.45 * open_pressure + 0.25 * progress)
                * severity;

            dead_space *= (1.15 - 0.35 * item_ratio).max(0.70);

            if next_fits_leftover {
                dead_space *= 0.30;
            }

            if blocks_next {
                dead_space *= if next_likely_elsewhere { 0.80 } else { 1.70 };
            }

            score += dead_space;
        }

        if next_fits_leftover {
            let over = (post - next) / cap;
            let tightness = 1.0 - over.min(1.0).max(0.0);
            score -= cap * (0.15 + 0.15 * open_pressure) * tightness;
        } else {
            let miss = ((next - post) / cap).max(0.0).sqrt();
            score += cap * (0.20 + 0.20 * progress) * miss;

            if blocks_next {
                let block_penalty = cap
                    * (0.40 + 0.35 * open_pressure + 0.10 * progress);
                score += block_penalty * if next_likely_elsewhere { 0.45 } else { 1.0 };
            }
        }
    }

    if !is_new_bin {
        if fitting_bins_count == 1 {
            let safe_for_next = next == 0.0
                || post <= 0.0
                || post + 0.5 >= next;

            let last_chance_bonus = if safe_for_next {
                cap * (0.28 + 0.22 * progress + 0.20 * open_pressure)
            } else {
                cap * 0.03
            };

            score -= last_chance_bonus;
        }

        score -= cap * 0.015;
    } else if fitting_bins_count == 0 {
        score -= cap * 0.20;
    } else {
        let mut new_bin_penalty = cap
            * (0.26 + 0.50 * open_pressure + 0.012 * open)
            * (0.85 + 0.35 * progress);

        new_bin_penalty += cap * 0.05 * fitting.min(5.0);
        new_bin_penalty += cap * 0.12 * (1.0 - item_ratio) * (1.0 - progress);

        if mean_residual > post {
            new_bin_penalty += (mean_residual - post)
                * (0.15 + 0.20 * open_pressure);
        }

        if next == 0.0 {
            new_bin_penalty += cap * 8.0;
        } else if post + 0.5 >= next {
            score -= cap * (0.10 + 0.10 * open_pressure);
        } else if next_likely_elsewhere {
            new_bin_penalty += cap * 0.55;
        } else if mean_residual + 0.5 >= next {
            new_bin_penalty -= cap * 0.10;
        } else {
            let miss = ((next - post) / cap).max(0.0).sqrt();
            score += cap * 0.08 * miss;
        }

        if new_bin_penalty < cap * 0.05 {
            new_bin_penalty = cap * 0.05;
        }

        score += new_bin_penalty;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), but penalize leaving
    // dead space that nothing else can use.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score += (1.0 - fit_ratio) * 10.0;

    // Aggressive 2-step lookahead: reward bins where post_residual exactly
    // or closely matches the next item size.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            // Perfect chain match: strong reward.
            if gap == 0.0 {
                score -= 60.0;
            } else if gap <= 10.0 {
                score -= 45.0 - gap * 2.0;
            } else if gap <= 25.0 {
                score -= 20.0 - gap * 0.5;
            } else {
                // Next item fits but leaves lots of slack: mild reward only.
                score -= 5.0;
            }
        } else {
            // Next item cannot fit here after this placement: penalize
            // proportionally to how far off it is (creates a forced split).
            let miss = (next_item_size - post_residual) as f64;
            score += miss * 1.5;
        }
    }

    // Relative-to-mean coupling: bins with residual far below the mean are
    // "almost full" — placing here consolidates waste.
    let dev = mean_residual - post_residual as f64;
    score -= dev * 0.3;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 {
        score -= 25.0 + fit_ratio * 20.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // It should only win when no open bin offers a decent (lookahead-aware) fit.
    if bin_residual == bin_capacity {
        // Penalize opening new bins mildly; grows with stream progress and
        // number of already-open bins.
        score += 40.0 + (open_bins_count as f64) * 5.0
            + (step_index as f64 / total_items.max(1) as f64) * 15.0;
        // But if the next item is huge, an empty bin gives flexibility.
        if next_item_size >= 60 && post_residual >= next_item_size {
            score -= 30.0;
        }
    }

    // Slight preference for placing into bins early in the open-bin order
    // effect: more open bins => encourage closing them out (filling near-full
    // bins) to reduce fragmentation.
    score += (open_bins_count as f64).ln().max(0.0) * (post_residual as f64 / bin_capacity as f64) * 8.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on, large post-residuals are acceptable (bins stay flexible);
    // late in the stream, waste is penalized super-linearly.
    let waste_weight = 0.4 + 2.2 * progress * progress;
    score += waste_weight * (pr / cap) * (pr / cap) * cap * 0.1;

    // Perfect fit reward, amplified by progress.
    if post_residual == 0 {
        score -= 40.0 + 60.0 * progress;
    }

    // Lookahead coupling: reward residual that can host the next item,
    // penalize residual that almost-but-not-quite fits it.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 6.0 + 10.0 * (1.0 - (pr - nx) / cap);
        } else {
            score += 8.0 * (nx - pr) / cap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 20.0 * progress;
    }

    // New-bin candidate: penalize unless current residuals are badly fragmented.
    if bin_residual == bin_capacity {
        let frag = (mean_residual / cap).clamp(0.0, 1.0);
        let openness = (open_bins_count as f64).ln().max(1.0);
        score += 30.0 - 25.0 * frag * frag - 4.0 * openness;
    }

    // Slight preference for bins tighter than average.
    score -= (mean_residual - pr) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual: coarse-grained waste classes.
    // Class 0: post_residual == 0 (perfect fill) -> strong reward.
    // Class 1: tiny remainder (1..=5) -> nearly perfect.
    // Class 2: medium remainder -> mild penalty.
    let class = if post_residual == 0 {
        0
    } else if post_residual <= 5 {
        1
    } else if post_residual <= 15 {
        2
    } else {
        3
    };

    match class {
        0 => score -= 40.0,
        1 => score -= 20.0,
        2 => score += 5.0,
        _ => {}
    }

    // Modulo arithmetic on post_residual: residues that align with common
    // item-size remainders (mod 10) are more likely reusable later.
    let residue = post_residual % 10;
    if post_residual > 0 {
        if residue == 0 {
            score -= 8.0; // round residual, easy to fill with 10-multiples
        } else if residue >= 7 {
            score += 3.0; // awkward residue, likely dead space
        }
    }

    // Lookahead: if the next item fits exactly into the post_residual,
    // this placement chains perfectly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // Next item still fits: bonus proportional to how well it fills.
            let chain_waste = post_residual - next_item_size;
            if chain_waste <= 5 {
                score -= 12.0;
            } else {
                score -= 4.0;
            }
        } else {
            // Next item cannot fit in the post residual: mild penalty scaled
            // by how badly it misses.
            let miss = next_item_size - post_residual;
            score += (miss as f64).min(20.0) * 0.5;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless the current
    // placement would leave large unusable waste in an existing bin.
    if bin_residual == bin_capacity {
        let waste_elsewhere = if fitting_bins_count > 0 {
            (post_residual as f64).min(60.0)
        } else {
            0.0
        };
        // Prefer a new bin only when no bin fits or every fit is terrible.
        if fitting_bins_count == 0 {
            score -= 100.0;
        } else {
            score += 30.0 + waste_elsewhere * 0.2;
        }
    }

    // Prefer tighter bins: closeness of item to residual (good fit ratio).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 10.0;

    // Mild pressure to consolidate when many bins are open.
    score += open_bins_count as f64 * 0.3;

    // Progress-aware: early in the stream, be slightly more willing to
    // open bins (flexibility); late, consolidate tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= (1.0 - progress) * 5.0;
    } else {
        score += progress * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize dead space: small unusable gaps after placement.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Reward tight fits (low post residual relative to item size).
    score -= (item_size as f64) * 0.5;

    // Penalize leaving a gap just below the next item (wasted space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size as f64 {
        score += (next_item_size as f64 - post_residual as f64) * 0.8;
    }
    // Reward leaving a gap that fits the next item.
    if next_item_size > 0 && post_residual >= next_item_size as f64 {
        score -= 6.0;
    }

    // Last-chance bonus: only one bin fits; strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Pressure from number of open bins: prefer filling existing bins when many are open.
    score += open_bins_count as f64 * 0.6;

    // New-bin candidate: mild penalty so it's chosen only when open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 4.0 + mean_residual * 0.15;
    }

    // Late in stream, avoid spreading residual across many bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near match: next item still fits snugly into the post residual.
    else if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 * (1.0 - slack / bin_capacity as f64);
    }
    // Next item cannot use the post residual: dead space penalty grows with tightness.
    else if next_item_size > post_residual {
        let waste = post_residual as f64;
        score += 15.0 * (waste / bin_capacity as f64);
    }

    // Reward tight fits relative to current bin residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill_ratio;

    // Penalize leaving very small unusable residuals (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Coupling with mean residual: prefer bins below-average residual (tighter bins),
    // but only when the fit is decent.
    if post_residual <= item_size {
        score -= mean_residual * 0.1;
    } else {
        score += (mean_residual - post_residual as f64).abs() * 0.05;
    }

    // New-bin candidate: only attractive when the current bin fit is poor
    // (large post residual that the next item cannot use).
    if bin_residual == bin_capacity {
        let poor_fit_bonus = if next_item_size > 0 && next_item_size > post_residual {
            35.0
        } else {
            0.0
        };
        score += 10.0 + poor_fit_bonus;
    }

    // Late in the stream, consolidate aggressively into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward small post_residual non-linearly.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize leaving dead space that the known next item cannot use.
    if next_item_size > 0 && post_residual > 0 {
        if post_residual < next_item_size {
            score += 0.9 * (next_item_size - post_residual) as f64;
        } else if post_residual >= next_item_size {
            // Good: next item can fit here; reward proportionally.
            score -= 0.35 * (post_residual as f64).min(next_item_size as f64);
        }
    } else if next_item_size == 0 && post_residual > 0 {
        // Last item: any residual is pure waste.
        score += 0.5 * post_residual as f64;
    }

    // Last-chance bin before opening a new bin: strong reward.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when it enables a great future packing
    // (large item now, and the open bins' mean residual is too small to be useful).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let tight_now = fit_ratio >= 0.9;
        let open_bins_useless = mean_residual < item_size as f64 * 0.95;
        if tight_now && open_bins_useless && open_bins_count > 0 {
            score -= 8.0 + 4.0 * (1.0 - progress);
        } else {
            score += 20.0 + 2.0 * open_bins_count as f64;
        }
    }

    // Mild penalty for spreading across many open bins when residuals are large.
    if mean_residual > 40.0 && bin_residual < bin_capacity {
        score += 0.05 * open_bins_count as f64;
    }

    // Late in the stream, consolidate harder: penalize any residual waste.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 0.15 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: quadratic coupling of post_residual with stream progress.
    // Early on, prefer tight fits (low post_residual); late in the stream,
    // dead space is more costly since fewer items remain to fill it.
    let mut score = pr * (1.0 + 1.5 * progress * progress);

    // Cubic smooth penalty on normalized dead space, growing with progress.
    score += 40.0 * pr_norm * pr_norm * pr_norm * (0.3 + progress);

    // Reward near-perfect fits smoothly (post_residual close to 0).
    score -= 12.0 * (-pr / 6.0).exp();

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Lookahead coupling: reward if next item fits the post residual.
    if next_item_size > 0 {
        let fits_next = (next_item_size as f64) <= pr;
        if fits_next {
            score -= 8.0 + 6.0 * (next_item_size as f64 / cap);
        } else {
            // Penalize residuals that are too small for the next item,
            // scaled by how close the leftover is to being useful.
            let gap = pr / (next_item_size as f64).max(1.0);
            score += 5.0 * (1.0 - gap.min(1.0));
        }
    }

    // Mild pressure toward consolidating bins: prefer bins whose residual
    // deviates below the mean (tighter bins), smoothly.
    score += 0.5 * (pr - mean_residual).max(0.0) * (0.5 + progress);

    // Slight preference for keeping the number of open bins low late in stream.
    score += (open_bins_count as f64) * 0.05 * progress;

    // New-bin candidate: empty bin gets a smooth baseline penalty so it is
    // chosen only when all open bins score badly.
    if bin_residual == bin_capacity {
        score = 60.0 + 30.0 * progress + 0.3 * (fitting_bins_count as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues near multiples of 25 are
    // "usable slots" for typical mid-size items; odd/dead residues are penalized.
    let quarter = bin_capacity / 4; // 25
    let class = post_residual % quarter;
    let half = bin_capacity / 2;    // 50
    let tier = post_residual / quarter;

    match tier {
        0 => {
            // Very small post-residual: tight fit is excellent.
            score -= 18.0;
            if class <= 4 { score -= 6.0; }
        }
        1 => {
            // Post-residual in (25, 50]: still reusable by mid items.
            score -= 10.0;
            if class >= quarter - 5 { score -= 4.0; }
        }
        2 => {
            // Post-residual in (50, 75]: good, but avoid wasting large residual.
            score -= 4.0;
        }
        _ => {
            // Post-residual > 75: item was small; wasteful unless bin was fresh.
            score += 8.0;
        }
    }

    // Dead-space penalty: residual that no item in [1, 100] would nicely fill.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0; // unusable sliver
    }

    // Lookahead coupling: if the next item fits the post-residual exactly-ish,
    // strongly reward this bin (chained packing).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            if slack <= 5 {
                score -= 20.0;
            } else if slack <= 20 {
                score -= 8.0;
            } else {
                score -= 2.0;
            }
        } else {
            // Next item won't fit here; mild penalty proportional to overflow.
            score += ((next_item_size - post_residual) as f64) * 0.15;
        }
    }

    // Last-chance bonus: only this bin can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Mean-residual coupling: prefer bins below the mean residual (fill fuller
    // bins first), scaled by stream progress.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (mean_residual - bin_residual as f64) * (0.3 + 0.4 * progress);

    // Fresh-bin candidate handling: opening a new bin is only attractive when
    // the item is large and no open bin offers a good fit.
    if bin_residual == bin_capacity {
        let large = item_size > bin_capacity * 3 / 4;
        let poor_fit = fitting_bins_count == 0 || (fitting_bins_count == 1 && bin_residual - item_size < 10);
        if large || poor_fit {
            score -= 6.0;
        } else {
            score += 15.0 + 0.2 * (open_bins_count as f64);
        }
        // Opening a bin for a huge item with near-perfect fit is great.
        let waste = bin_capacity - item_size;
        if waste <= 10 { score -= 10.0; }
    }

    // Slight preference for bins whose residual shares harmonic class with item.
    if bin_residual % quarter == item_size % quarter {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero gaps are nearly unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Perfect fit strongly rewarded.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bin: avoid opening a new bin if this is the only fit.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Pressure from many open bins: favor consolidating into existing bins.
    score += (open_bins_count as f64) * 1.5;

    // If this is the empty new-bin candidate, penalize unless current bins are crowded.
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64) * 2.0 + mean_residual / 10.0;
        score += 30.0 + pressure;
    }

    // Lookahead: if next item fits in the post residual, reward this placement.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 8.0;
    } else if next_item_size > 0 && (post_residual as u32) > 0 && (post_residual as u32) < next_item_size {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let next = next_item_size as f64;

    // Base: prefer tight fills (small post_residual).
    let mut score = post;

    // Aggressive 2-step lookahead: reward when next item exactly matches the leftover.
    if next > 0.0 {
        let gap = (post - next).abs();
        // Perfect 2-step match: strong reward.
        if gap < 0.5 {
            score -= 25.0;
        } else if post >= next {
            // Next item fits: reward proportional to how snugly it fits.
            score -= 18.0 * (1.0 - gap / cap).max(0.0);
        } else {
            // Next item does NOT fit the leftover: penalize dead space,
            // worse when the waste is small-but-unusable.
            let waste = next - post;
            score += 6.0 + 0.35 * waste.min(cap);
        }
    }

    // Penalize leaving residuals too small for typical items (dead space).
    if post > 0.0 && post < 10.0 {
        score += 12.0 * (1.0 - post / 10.0);
    }

    // Prefer bins already below mean residual (consolidating slack).
    score += 0.15 * (mean_residual - post).max(0.0);

    // Last-chance bin: strong incentive to use it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Late in the stream, be extra conservative about wasting space.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.25 * progress;

    // Slight preference for keeping the number of open bins bounded.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize small post_residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio;

    // Penalize dead space relative to capacity, especially for large leftovers.
    let dead = post_residual as f64 / bin_capacity as f64;
    score += 6.0 * dead * dead;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else {
        // Mild penalty when many alternatives exist to encourage spreading.
        score += 0.3 * (fitting_bins_count as f64).min(10.0);
    }

    // Lookahead: if the next item could also fit in the post residual,
    // reward this bin (chain packing). Otherwise penalize slightly.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 8.0;
        } else {
            score += 4.0;
        }
    }

    // Global state: high mean residual means bins are loose; prefer filling
    // existing bins then. Low mean residual (tight bins) makes new bin cheaper.
    score += 0.05 * (mean_residual - post_residual as f64);

    // Time horizon: late in the stream, avoid opening new bins more strongly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress;

    // New-bin candidate: make opening a new bin costly unless item is large
    // and no tight option exists.
    if bin_residual == bin_capacity {
        score += 15.0 + 20.0 * (1.0 - fit_ratio);
        if fitting_bins_count == 0 {
            score -= 40.0; // must open a bin anyway
        }
    }

    // Slight preference for bins with residual close to item (perfect match).
    let diff = (bin_residual as f64 - item_size as f64);
    score += 0.02 * diff * diff / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let base = pr / cap;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr as f64;

    // Polynomial interaction: quadratic + cubic in normalized residual, modulated by progress
    let quad = base * base * (1.0 - progress);
    let cubic = base * base * base * progress;
    score += 40.0 * (quad - cubic);

    // Reward tight fits (small post_residual) more strongly as stream progresses
    score -= 30.0 * (1.0 - base) * (1.0 - base) * (0.5 + progress);

    // Penalize residual that cannot fit the next item (dead space coupling)
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr < ni {
            score += 15.0 * (ni - pr) / cap * (1.0 + progress);
        } else {
            // smooth reward when next item fits perfectly into the post-residual
            let fit_gap = (pr - ni) / cap;
            score -= 10.0 * (1.0 - fit_gap).max(0.0) * (1.0 - fit_gap);
        }
    }

    // Last-chance bonus: strongly favor the only bin that can fit the item
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Mild pressure to consolidate into bins with low residuals relative to mean
    score += 5.0 * (mean_residual - pr) / cap;

    // New-bin candidate: penalize opening a new bin early, allow it late or when crowded
    let is_new = (bin_residual as f64 - cap).abs() < 1e-6;
    if is_new {
        let crowd = open_bins_count as f64 / (1.0 + open_bins_count as f64);
        score += 20.0 * (1.0 - progress) * (1.0 - crowd) + 8.0 * (1.0 - base);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "usable" the leftover space is
    // modulo capacity fractions (25 / 50 / 33 classes).
    let cap = bin_capacity as f64;
    let pr = post_residual;
    let prf = pr as f64;

    // Exact-fit reward: zero post residual is perfect.
    if pr == 0 {
        score -= 60.0;
    }

    // Small leftovers are efficient; big leftovers waste capacity.
    score -= (cap - prf) * 0.05;

    // Harmonic class bonus: leftover divisible into nice chunks (multiples of 10/20/25)
    if pr % 10 == 0 && pr > 0 {
        score -= 8.0;
    }
    if pr % 20 == 0 && pr > 0 {
        score -= 6.0;
    }
    if pr % 25 == 0 && pr > 0 {
        score -= 5.0;
    }

    // Integer division threshold: leftover >= next item means lookahead fits.
    if next_item_size > 0 {
        if pr >= next_item_size {
            // Reward chains where next item also fits (harmonic pairing).
            let pair = pr as f64 - next_item_size as f64;
            score -= 10.0 + pair * 0.08;
            // Extra reward if post residual exactly equals next item size.
            if pr == next_item_size {
                score -= 25.0;
            }
            // Class coupling: leftover after hypothetical next placement in a good class.
            let post2 = pr - next_item_size;
            if post2 % 10 == 0 {
                score -= 4.0;
            }
        } else {
            // Penalize creating dead space that the lookahead cannot use.
            score += 12.0;
        }
    } else {
        // Last item: just minimize leftover.
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Penalize opening a new bin when many open bins exist (consolidation pressure).
    if bin_residual == bin_capacity {
        score += open_bins_count as f64 * 3.0;
        // But if mean residual across open bins is small (they are nearly full),
        // a new bin is reasonable: soften penalty.
        score -= mean_residual * 0.15;
        // Lookahead: if next item is large, a fresh bin is more attractive.
        if next_item_size > 50 {
            score -= 10.0;
        }
    }

    // Stream progression: later in the stream, prefer tighter packing (harsher waste penalty).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += prf * 0.10 * progress;

    // Dead-space cliff: leftover in (0..10) is nearly unusable for items >=10... but
    // sizes can be 1..100, so treat tiny leftovers as near-perfect fits instead.
    if pr > 0 && pr < 5 {
        score -= 12.0;
    }

    // Harmonic modulo bucket on bin residual: bins whose residual is in the
    // 10..30 band are prime targets for small-medium items.
    let band = bin_residual / 10;
    match band {
        1 | 2 => score -= 6.0,
        3 | 4 => score -= 3.0,
        _ => {}
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no realistic item (>=1) can
    // meaningfully use are pure waste. Penalize very small gaps quadratically.
    if post_residual > 0 {
        let pr = post_residual as f64;
        if post_residual < 10 {
            score += (10.0 - pr) * (10.0 - pr) * 1.5;
        } else if post_residual > 80 {
            // Large leftover: fine only if a future item can use it; penalize mildly
            // since capacity is being under-used relative to mean residual pressure.
            score += (pr - 80.0) * 0.8;
        }
    } else {
        // Perfect fill: strongly reward.
        score -= 60.0;
    }

    // Tight fit reward: fraction of bin used by this item.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= fill * 25.0;

    // Lookahead (k=2): if the next item fits exactly in the post_residual,
    // this placement chains nicely; reward it.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            // Next item still fits: mild reward proportional to closeness.
            let slack = (post_residual - next_item_size) as f64;
            score -= (1.0 - slack / bin_capacity as f64) * 15.0;
        } else {
            // Next item cannot use this bin's remainder: penalize if remainder
            // is small (dead space) relative to next item.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.3;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0 + (bin_residual - item_size) as f64 * 0.1;
    }

    // Open-bins pressure: with many open bins, prefer consolidating into
    // existing bins over opening new ones; penalize the new-bin candidate.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from open bin count and
        // mean residual dispersion (large mean residual => existing bins have room).
        score += 30.0 + open_bins_count as f64 * 2.0 + mean_residual * 0.5;
        // Late in the stream, opening bins is cheaper than fragmenting? No:
        // keep pressure constant; slight early-stream tolerance.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 5.0;
    } else {
        // Existing bin: reward using it, scaled by how many alternatives exist.
        score -= open_bins_count as f64 * 0.3;
    }

    // Mean residual coupling: prefer bins whose residual is below the mean
    // (i.e., filling the emptiest-relative bins last keeps spread tight).
    let res = bin_residual as f64;
    if res < mean_residual {
        score -= (mean_residual - res) * 0.2;
    } else {
        score += (res - mean_residual) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: neutral baseline, mildly penalized so only chosen when open bins are truly bad.
    if bin_residual == bin_capacity {
        return 100.0 + 0.15 * mean_residual + 0.5 * open_bins_count as f64;
    }

    let progress = step_index as f64 / total_items.max(1) as f64;

    // Aggressive 2-step lookahead: perfect match of leftover with next item is excellent.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        score -= 60.0 / (1.0 + diff); // strong reward as leftover approaches next item size
        // Exact match: near-zero leftover after next item => best case.
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // Leftover too small for next item: dead space penalty scaled by tightness.
        if post_residual < next_item_size {
            score += 0.6 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: minimize leftover directly (already the base term).
        score -= 10.0;
    }

    // Reward filling bins that are already tight relative to mean residual.
    let tightness = (mean_residual - post_residual as f64).max(0.0);
    score -= 0.3 * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - 0.5 * progress);
    }

    // Penalize very small unusable leftovers (dead space < 10).
    if post_residual < 10 {
        score += 15.0 - post_residual as f64;
    }

    // Mild preference for keeping the number of open bins low early in the stream.
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Dead space if next item can't use the leftover.
            score += 0.10 * post_residual as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize opening new bins when many bins already open and mean residual is ample.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let t = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 + 20.0 * t;
        if mean_residual >= item_size as f64 {
            score += 8.0;
        }
        if open_bins_count > 0 && fitting_bins_count > 0 {
            score += 5.0;
        }
    }

    // Mild preference for bins with below-average residual (keeps big holes free).
    score += 0.05 * ((bin_residual as f64) - mean_residual).max(0.0);

    // Early stream: encourage filling bins greedily to keep open bin count low.
    let t = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - t) * 0.03 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;

    // Smooth polynomial coupling of post_residual with stream progress
    let pr_norm = pr / cap;
    let poly = pr_norm * pr_norm * (1.0 + progress) + pr_norm * (0.5 * progress + 0.25);

    let mut score = pr + poly * 20.0;

    // Reward tight fits smoothly
    score -= 25.0 * fit_ratio * fit_ratio * (1.0 - progress * 0.5);

    // Last-chance bonus
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - fit_ratio);
    }

    // Lookahead: reward leaving room for next item (smooth gaussian-like term)
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score -= 12.0 * (-gap * gap / 400.0);
    }

    // Penalize bins much emptier than mean (encourage filling fuller bins)
    score += 0.3 * (pr - mean_residual) * (1.0 + 0.5 * progress);

    // Mild pressure on new bins late in stream
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * progress + 2.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // ---- Harmonic class of the post-residual (mod arithmetic on capacity) ----
    // Class 0: post_residual % 10 == 0  -> perfectly reusable slot, reward strongly.
    // Class 1: post_residual % 10 == 1..3 -> near-aligned, small reward.
    // Class 2: post_residual % 10 >= 7 -> ragged dead space, penalize.
    let pr = post_residual;
    let class = pr % 10;
    if class == 0 {
        score -= 12.0;
    } else if class <= 3 {
        score -= 4.0;
    } else if class >= 7 {
        score += 6.0;
    }

    // Integer-division thresholds on post_residual: how many "small items" (<=10)
    // could still fit; more divisibility = more flexible bin.
    let slots10 = pr / 10;
    score -= (slots10 as f64) * 2.5;

    // ---- Exact-fill reward ----
    if pr == 0 {
        score -= 40.0;
    }

    // ---- Tight fit reward: item nearly fills the bin ----
    let fill_frac = item_size as f64 / bin_capacity as f64;
    if fill_frac > 0.8 {
        score -= 10.0;
    }

    // ---- Lookahead coupling with next_item_size ----
    // If the next item fits exactly in the post-residual, strongly favor this bin.
    if next_item_size > 0 && next_item_size <= pr {
        if pr == next_item_size {
            score -= 25.0;
        } else {
            // next item leaves another aligned residual?
            let next_post = pr - next_item_size;
            if next_post % 10 == 0 {
                score -= 8.0;
            }
            score -= (next_item_size as f64) * 0.05;
        }
    }
    // If next item does NOT fit here, mild penalty for wasting a big slot.
    if next_item_size > 0 && next_item_size > pr && pr > 0 {
        score += (pr as f64) * 0.03;
    }

    // ---- Last-chance bin logic ----
    if fitting_bins_count == 1 && bin_residual >= item_size {
        // Only this bin fits; opening a new bin wastes residual here.
        score -= 15.0;
    }

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        // Fresh bin: baseline score = capacity (worst residual). Adjust so it is
        // chosen only when no open bin offers a good (aligned / tight) fit.
        score = bin_capacity as f64 * 0.9;
        if next_item_size > 0 {
            // fresh bin always accommodates next item perfectly after this one
            score -= 5.0;
        }
        if fitting_bins_count == 0 {
            score -= 30.0; // nothing fits: must open
        }
    }

    // ---- Congestion / stream progression modulation ----
    let progress = step_index as f64 / (total_items.max(1) as f64);
    // Late in the stream, prefer closing bins (tight placements) more aggressively.
    score *= 1.0 + 0.15 * progress;

    // Prefer bins whose residual deviates from the mean in a "cleanable" way.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Slight penalty when many bins are open: encourage consolidation.
    score += (open_bins_count as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    } else if post_residual == 0 {
        score -= 25.0; // perfect fit
    }

    // Reward tight fits (small waste relative to capacity).
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += waste_frac * waste_frac * 20.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Open-bin pressure: many open bins -> prefer filling existing ones,
    // penalize opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.6 * (0.5 + 0.5 * progress);

    // New-bin candidate: only attractive if it enables a good pairing with
    // the next item, otherwise discourage.
    if bin_residual == bin_capacity {
        if next_item_size > 0 && post_residual >= next_item_size && (post_residual - next_item_size) < 10 {
            score -= 30.0; // new bin will pair perfectly with next item
        } else if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0;
        } else {
            score += 12.0; // would create dead space immediately
        }
    }

    // Lookahead: if this placement leaves room exactly for the next item, reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 10.0;
    }

    // Slight pull toward bins with below-average residual (keep big gaps
    // consolidated for future large items).
    let gap = mean_residual - bin_residual as f64;
    score += gap * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact/near-exact match of next item into post_residual.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual >= next_item_size {
            // Next item fits here: strongly reward tight chains.
            score -= 40.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Dead space relative to next item: penalize.
            score += 10.0 * gap / bin_capacity as f64;
        }
    } else {
        // Last item: reward zero waste heavily.
        score -= 60.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Compare post_residual against mean residual: avoid creating outlier residuals.
    score += 0.5 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: if this is the only bin that fits, prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Prefer filling bins tightly overall.
    score -= 0.3 * (bin_residual as f64 / bin_capacity as f64) * item_size as f64;

    // Penalize opening new bins early in the stream; allow later when crowded.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowding = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        score += 30.0 * (1.0 - progress) + 5.0 * crowding;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress ratio for dynamic horizon
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Tightness: reward small post residual nonlinearly
    let tight_bonus = ((bin_capacity as f64 - post_residual as f64) / bin_capacity as f64).powi(3) * 30.0;
    score -= tight_bonus;

    // Penalize dead space: post residual too small to fit any future item (min size 1..~10)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Lookahead: if next item fits exactly into post residual, strong reward
    if next_item_size > 0 && post_residual >= next_item_size {
        let fit_quality = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 20.0 * fit_quality;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item won't fit here anyway; mild penalty for wasting capacity
        score += 5.0 * (1.0 - progress);
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Global state: many open bins -> prefer filling existing ones, discourage new bins
    let crowding = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    score += crowding * 15.0;

    // Mean residual coupling: if this bin's residual is far below mean, it's "ragged"; prefer balanced bins
    let dev = bin_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // New-bin candidate handling: empty bin gets baseline penalty that shrinks late in stream
    if bin_residual == bin_capacity {
        score += 35.0 * (1.0 - 0.5 * progress);
        // allow new bin if no open bin fits well (post_residual large = bad fit elsewhere)
        if post_residual == 0 {
            score -= 20.0;
        }
    }

    // Exact fill reward
    if post_residual == 0 {
        score -= 50.0;
    }

    // Small time-dependent jitter-free exploration term
    score -= 3.0 * (progress * std::f64::consts::PI).sin();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: waste after placement
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress:
    // late in the stream, tight residuals matter more (penalize large leftover),
    // early on, larger residuals are more acceptable.
    let poly = norm_pr * norm_pr * (0.5 + progress) - norm_pr * progress;
    score += 40.0 * poly;

    // Perfect fit reward, stronger as stream progresses
    if post_residual == 0 {
        score -= 30.0 + 40.0 * progress;
    } else if post_residual <= 10 {
        score -= 10.0 + 15.0 * progress;
    }

    // Lookahead: reward if next item fits the post-residual
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 12.0 * (next_item_size as f64 / cap) * (1.0 - progress);
    }

    // Last-chance bin: strongly favor using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: mild penalty so we prefer existing bins unless fit is poor
    if bin_residual == bin_capacity {
        score += 15.0 + 20.0 * progress - 0.05 * open_bins_count as f64;
    }

    // Penalize bins far from mean residual (fragmentation signal)
    score += 0.15 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of post_residual (capacity fractions) ---
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;

    // Dead-space penalty: residuals in (0, 10] are nearly unusable.
    if post_residual > 0 && post_residual <= 10 {
        score += 25.0;
    }
    // Harmonic residue classes: perfect fits (0), quarter/half classes are valuable.
    match post_residual {
        0 => score -= 40.0,
        x if x == quarter => score -= 12.0,
        x if x == 2 * quarter => score -= 15.0,
        x if x == eighth || x == 3 * eighth || x == 5 * eighth || x == 7 * eighth => score -= 5.0,
        _ => {}
    }

    // Lookahead: does next_item_size fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Reward exact or near-exact follow-up fits (harmonic pairing).
            let slack = post_residual - next_item_size;
            score -= 10.0 + (slack as f64).min(15.0) * 0.4;
            if slack == 0 { score -= 15.0; }
        } else {
            // Next item cannot use this residual: penalize proportionally to waste.
            score += (next_item_size as f64 - pr).min(30.0) * 0.5;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when item is large relative
    // to capacity or all open bins fit poorly.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / c;
        // Fresh bin: score = leftover space, reward large fills.
        score = (c - item_size as f64) * 0.9 - fill_ratio * 20.0;
        // Discourage opening new bins when many bins already fit the item.
        if fitting_bins_count > 0 {
            score += (fitting_bins_count as f64) * 8.0;
        }
        // Late in stream, prefer consolidation into open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 10.0;
    }

    // Mild pull toward bins whose residual is close to the item (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64) / c;
    score += tightness * 8.0;

    // Coupling with mean residual: prefer bins below-average residual
    // (concentrate small leftovers, keep large residuals for future items).
    if bin_residual as f64 > mean_residual {
        score += 4.0;
    } else {
        score -= 2.0;
    }

    // Integer-division threshold on post_residual: bucketize waste.
    let waste_class = post_residual / 20; // 0..5 harmonic buckets
    score += waste_class as f64 * 1.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // Define "unusable" as a gap smaller than the smallest plausible item (1..100
    // interface) scaled by stream knowledge; treat gaps < 10 as dead space,
    // and gaps < next_item_size (when lookahead exists) as risky dead space.
    let dead_threshold = if next_item_size > 0 { next_item_size } else { 10 };
    if post_residual < dead_threshold {
        // Quadratic penalty for creating tiny unusable slivers.
        let slack = (dead_threshold - post_residual) as f64;
        score += 40.0 + 2.0 * slack * slack;
    }

    // Reward tight fits (post_residual near zero but not dead): perfect closure.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance pressure: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open-bin pressure: discourage proliferating bins; prefer filling existing
    // bins when many are open.
    score += (open_bins_count as f64) * 0.5;

    // Prefer bins whose residual is above the mean residual (fill emptier bins
    // less aggressively keeps large gaps available for large items).
    if (bin_residual as f64) < mean_residual {
        score += 8.0;
    } else {
        score -= 4.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post_residual,
    // this placement sets up a perfect follow-up placement.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }
    // If next item cannot fit in post_residual but fits in bin_residual, mild
    // penalty for blocking the lookahead.
    if next_item_size > 0 && next_item_size > post_residual && next_item_size <= item_size {
        score += 5.0;
    }

    // New-bin candidate handling: an empty bin is a fallback; make it slightly
    // less attractive than a good fit but more attractive than a dead-space fit.
    if bin_residual == bin_capacity {
        score += 12.0;
    }

    // Mild stream-progression term: early on, be conservative; late, pack hard.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact fit (no dead space).
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if post_residual exactly matches next item size.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 800.0;
        } else {
            let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
            // Penalize residuals that are too small to fit the next item (dead space),
            // but mildly reward residuals slightly larger than next item.
            if (post_residual as i64) < (next_item_size as i64) {
                score += diff * 1.5;
            } else {
                score -= diff * 0.5;
            }
        }
    }

    // Compare against mean residual: prefer bins whose post_residual stays near mean
    // (keeps flexibility), penalize creating extreme outliers.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 500.0;
    }

    // Penalize very small residuals (wasted slivers) non-linearly.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Late in the stream, be more conservative: prefer tight fills.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * (bin_capacity as f64 - post_residual as f64) * 0.2;

    // Mild penalty when many bins are open already (encourage consolidation).
    score += open_bins_count as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: normalize post_residual by capacity.
    let tight = post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * (1.0 - tight) * (1.0 - tight);

    // Penalize dead space that cannot fit typical future items (post_residual < next_item_size).
    if next_item_size > 0 && post_residual < next_item_size {
        score += 12.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Reward bins that can also host the lookahead item.
        score -= 6.0 * (next_item_size as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is poor
    // and there are many open bins (fragmentation control).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit = (post_residual as f64) < 0.35 * bin_capacity as f64;
        if poor_fit && open_bins_count > 3 {
            score -= 10.0 + 20.0 * (1.0 - progress);
        } else {
            score += 25.0;
        }
    }

    // Prefer bins whose residual is below the mean (consolidate small leftovers).
    let dev = mean_residual - post_residual as f64;
    score += 0.15 * dev;

    // Mild penalty for very small unusable leftovers.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: post residual (waste), scaled
    let mut score = pr;

    // Smooth non-linear coupling: residual squared term, weighted by stream progress
    // Late in the stream, dead space matters more (less chance to fill it).
    score += norm_pr * norm_pr * cap * (0.5 + 1.5 * progress);

    // Perfect fit reward: subtract strongly when post_residual is small
    let fit_quality = 1.0 - norm_pr;
    score -= fit_quality * fit_quality * item_size as f64;

    // Lookahead: penalize if next item could have used this residual better
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let waste = (pr - nxt).max(0.0);
        score += waste * 0.3 * (1.0 - progress);
    }

    // Last-chance bin bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 25.0 * progress;
    }

    // Mild penalty for spreading across too many open bins relative to residual mean
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;
    score += (norm_pr - mean_residual / cap).abs() * cap * 0.2;

    // New-bin candidate adjustment: empty bin should only win for large items
    if bin_residual == bin_capacity {
        score += 15.0 + 20.0 * (1.0 - item_size as f64 / cap) + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: dead space is worse when it falls in
    // "awkward" classes (small but unusable slivers).
    let pr = post_residual as f64;
    let c = bin_capacity as f64;
    let frac = pr / c;

    // Penalize tiny residuals that likely become dead space
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0;
    }
    // Modulo classes on post_residual (harmonic buckets of 10)
    let class = post_residual / 10;
    score -= (class % 3) as f64 * 4.0; // mild class-based preference

    // Lookahead: reward bins whose post_residual fits the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        score -= 40.0;
        // even better if next placement also lands in a good class
        if slack <= 10 { score -= 20.0; }
        if (slack / 10) % 2 == 0 { score -= 5.0; }
    } else if next_item_size > 0 {
        // penalize creating residual that can't host next item
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: discourage opening new bins unless
    // current fit is poor or stream is early with few bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 120.0;
        // early stream: new bins are cheap-ish
        score -= 60.0 * (1.0 - progress);
        if open_bins_count == 0 { score -= 150.0; }
        // if item nearly fills a fresh bin, new bin is attractive
        if item_size as f64 >= 0.8 * c { score -= 70.0; }
        if next_item_size > 0 && next_item_size <= post_residual { score -= 15.0; }
    }

    // Tight fit reward: residual close to item size means good packing
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * tightness;

    // Mean residual coupling: prefer bins near the mean residual (keeps spread low)
    score += (pr - mean_residual).abs() * 0.5;

    // Integer-division threshold: bins with residual divisible nicely by common sizes
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 8.0;
    }
    if post_residual % 20 == 0 && post_residual > 0 {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no realistic item can use
    // (below the minimum item size of 1, or awkwardly small gaps) are heavily penalized.
    if post_residual > 0 {
        // Dead space severity: residual too small to be useful later
        let dead_threshold = 10.0f64;
        if (post_residual as f64) < dead_threshold {
            score += (dead_threshold - post_residual as f64) * 8.0;
        }
        // Non-linear penalty for medium awkward gaps
        if post_residual >= 10 && post_residual <= 20 {
            score += (20 - post_residual) as f64 * 1.5;
        }
    } else {
        // Perfect fit: strong reward
        score -= 60.0;
    }

    // Reward tight fits relative to the item size
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 25.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, big reward
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 50.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing residuals are large (bins are mostly full) or many bins are open.
    if bin_residual == bin_capacity {
        // Base reluctance to open a new bin
        score += 45.0;
        // Pressure grows with number of open bins (consolidate when many open)
        score += open_bins_count as f64 * 2.0;
        // If mean residual across open bins is small, opening fresh is fine
        score -= mean_residual * 0.6;
        // If no existing bin can fit, this call is the only choice
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
        // Late in the stream, prefer opening fresh bins over squeezing
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 5.0;
    } else {
        // Open-bin pressure: with many open bins, prefer consolidating into fewer
        score += open_bins_count as f64 * 0.5;
    }

    // Prefer bins whose residual is close to the item (tightest fit)
    let slack = (bin_residual as f64 - item_size as f64).abs();
    score += slack * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 900.0; // perfect chaining
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 150.0 * (1.0 - slack / 100.0); // good chain, tighter = better
            if slack <= 5.0 {
                score -= 100.0;
            }
        } else {
            // next item cannot fit here: penalize wasted potential
            let over = (next_item_size - post_residual) as f64;
            score += 0.8 * over.min(50.0);
        }
    }

    // Relative to mean residual: prefer bins with less residual (tighter bins)
    score += 0.5 * (mean_residual - bin_residual as f64).max(0.0);
    score -= 0.3 * (bin_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: penalize unless current fit is bad and lookahead suggests it
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 > 40.0
            && (next_item_size == 0 || next_item_size > post_residual);
        if poor_fit {
            score -= 60.0; // allow opening a new bin for poor fits
        } else {
            score += 150.0; // discourage opening new bins for decent fits
        }
        // Early in stream, keep bins open longer
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 100.0 * (1.0 - progress);
    }

    // Penalize creating large unusable dead space
    if post_residual > 0 && post_residual < 10 {
        score -= 50.0; // small dead space is fine (already near-perfect)
    }
    if post_residual > 60 {
        score += 10.0; // very loose bins are low priority targets
    }

    // Slight preference to consolidate among fewer bins
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Last-chance bin: strongly favor the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 500.0;
    }

    // Lookahead: reward if next item fits into post residual (chain fit)
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 60.0;
        } else if post_residual > 0 && next_item_size > post_residual {
            // penalize creating residual that just barely blocks next item
            let waste = post_residual as f64;
            score += waste * 0.5;
        }
        // if next item would exactly fill post residual, big bonus
        if next_item_size == post_residual {
            score -= 150.0;
        }
    } else {
        // near the end, minimize residual waste aggressively
        score += post_residual as f64 * 0.3;
    }

    // Prefer bins with smaller residual (best-fit style) scaled by progress
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (bin_residual as f64 - item_size as f64) * (0.2 + 0.5 * progress);

    // Penalize tight fits that leave tiny unusable residuals
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Discourage opening new bins early when fitting bins exist
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64) * 8.0 + mean_residual * 2.0;
        score += 200.0 + pressure;
        // allow new bin late in stream if mean residual is low
        if mean_residual < 15.0 && progress > 0.7 {
            score -= 150.0;
        }
    }

    // Slight preference for bins below mean residual (balance load)
    score += (bin_residual as f64 - mean_residual) * 0.1;

    // Mild time-dependent exploration term
    score += ((step_index % 7) as f64) * 0.5 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress in [0,1]
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let prog_sq = progress * progress;

    // Tightness reward: strong preference for small post_residual, non-linear
    let norm_fit = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * norm_fit * norm_fit;

    // Penalize post_residual quadratic waste (dead space grows super-linearly)
    let pr = post_residual as f64;
    score += 0.02 * pr * pr / (1.0 + progress);

    // Lookahead: reward if next item fits into the resulting residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0 + 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // residual too small for next item: penalize more as stream progresses
            score += 6.0 + 10.0 * progress;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Coupling with mean residual: prefer bins close to the mean residual
    // (keeps residual distribution balanced), weighted by progress
    let dev = (pr - mean_residual).abs();
    score += 0.15 * dev * (0.5 + prog_sq);

    // New-bin candidate: penalize mildly when other bins exist and fit,
    // but allow opening when open bins are nearly full on average
    if bin_residual == bin_capacity && open_bins_count > 0 {
        let avg_fullness = 1.0 - mean_residual / bin_capacity as f64;
        score += 8.0 * (1.0 - avg_fullness) * (1.0 - avg_fullness);
    }

    // Late-stream consolidation: favor filling existing bins more aggressively
    score -= 20.0 * prog_sq * (1.0 - pr / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover: quantize post_residual into capacity/10 buckets
    let bucket = (post_residual * 10) / bin_capacity; // 0..10
    let dead_penalty: f64 = match bucket {
        0 => -40.0,           // perfect fit
        1..=3 => -10.0,       // tight leftover, likely reusable by small items
        4..=6 => 6.0,         // mid dead zone
        _ => (bucket as f64) * 2.5, // large leftover is fine (bin still flexible)
    };
    score += dead_penalty;

    // Fractional harmonic term: sin-like coupling via integer division thresholds
    let frac = post_residual as f64 / cap;
    if frac > 0.0 && frac < 0.2 {
        score -= 5.0 * (1.0 - frac / 0.2);
    }

    // Lookahead coupling: reward if next item fits into post_residual exactly or well
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let next_left = post_residual - next_item_size;
            if next_left == 0 { score -= 30.0; }
            else if next_left < 10 { score -= 18.0; }
            else { score -= 4.0; }
        } else {
            // next item won't fit here: penalize if we waste a near-perfect residual now
            score += 8.0;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin gets neutral baseline, discourage unless
    // no open bin fits well (post_residual small) or stream is early
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 55.0 - 15.0 * (1.0 - progress) - (open_bins_count as f64).min(10.0);
        if next_item_size > 0 && next_item_size > cap * 0.5 {
            score += 10.0; // big next item: fresh bin useful
        }
    }

    // Prefer filling bins when many bins are open (consolidation pressure)
    score += (open_bins_count as f64).sqrt() * 1.5;

    // Nudge toward bins with residual close to mean (balance preservation)
    score += (bin_residual as f64 - mean_residual).abs() * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize dead space: small unusable gaps after placement.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable slivers are pure waste
    }

    // Reward tight fits: residual near zero relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 20.0;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, encourage filling.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64) * (1.0 - progress) * 0.5;
    score += pressure;

    // Lookahead: favor bins whose leftover can fit the next item (or empty after use).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 6.0; // leftover blocks the next item
        }
    }

    // Prefer bins below mean residual (pack into emptier-feeling bins evenly),
    // but only mildly so tightness dominates.
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let default_penalty = 12.0 + pressure;
        score += default_penalty;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: open new bin
        } else if mean_residual < item_size as f64 * 0.5 {
            // existing bins are half-empty-ish; discourage opening a new one
            score += 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: reward exact match of post_residual to next item size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 * (1.0 - diff / bin_capacity as f64).max(0.0);
        // Perfect 2-step fit: massive reward
        if post_residual == next_item_size {
            score -= 200.0;
        }
        // Penalize leaving residual that neither fits next item nor is reusable
        if post_residual < next_item_size && post_residual > 0 && post_residual < 10 {
            score += 40.0; // tiny dead space
        }
    }

    // Reward tight fits relative to mean residual across open bins
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Penalize opening a new bin when good alternatives exist
    if bin_residual == bin_capacity {
        score += 80.0;
        // But allow new bin if no existing bin fits well (post_residual very small waste anyway)
        if post_residual == 0 {
            score -= 60.0;
        }
    }

    // Prefer filling bins more completely as stream progresses
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    score -= progress * (bin_capacity as f64 - post_residual as f64) * 0.3;

    // Slight penalty for wasting large residual capacity
    if post_residual > item_size as u32 {
        score += 0.2 * (post_residual as f64 - item_size as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tight fit reward: fraction of bin used by this placement
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill_frac;

    // Penalize large dead space relative to smallest possible item (1..100 unknown, use small anchor)
    let waste = post_residual as f64;
    score += 0.15 * (waste * waste) / bin_capacity as f64;

    // Lookahead: reward if next item fits in the post residual (chaining)
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 25.0 + 0.2 * next_item_size as f64;
        } else {
            // Penalize creating residual that nothing can use well
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: prefer new bin only when open bins have poor residuals
    if bin_residual == bin_capacity {
        // Base cost of opening a bin, modulated by global state
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 70.0 + 40.0 * (1.0 - progress) - 10.0 * mean_residual / bin_capacity as f64;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score += 0.0;
        }
        // If this item leaves a huge residual anyway, new bin is attractive
        if post_residual > 60 {
            score -= 20.0;
        }
    }

    // Crowding: if many bins open, prefer consolidating into existing ones
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: if mean residual is small, existing bins are tight; keep them for small items
    if item_size as f64 > mean_residual {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr_norm = pr / cap;

    // Base: post residual, mildly discounted early (fill bins greedily early)
    let mut score = pr * (1.0 - 0.35 * (1.0 - progress) * (1.0 - progress));

    // Smooth polynomial penalty for mid-range dead space (worst residuals ~ half empty)
    let dead = pr_norm * (1.0 - pr_norm);
    score += 18.0 * dead * dead * 4.0;

    // Reward tight fits (small post residual) with smooth exponential-like polynomial
    let tight = (1.0 - pr_norm).powi(6);
    score -= 12.0 * tight;

    // Lookahead: bonus if next item fits the post residual exactly-ish
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if ni <= pr {
            let slack = (pr - ni) / cap;
            score -= 8.0 * (1.0 - slack) * (1.0 - slack);
        } else {
            score += 4.0 * ((ni - pr) / cap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Prefer bins below mean residual (consolidate large holes)
    score += 0.3 * (mean_residual - pr);

    // Mild penalty when many bins open and this is the empty new-bin candidate
    if bin_residual == bin_capacity {
        score += 3.0 + 0.5 * open_bins_count as f64 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic classes: post_residual bucketed by integer division thresholds
    let pr = post_residual;
    let quarter = bin_capacity / 4;
    let tenth = bin_capacity / 10;

    // Reward tight fits (small post_residual) non-linearly
    if pr < tenth {
        score -= 12.0;
    } else if pr < quarter / 2 {
        score -= 6.0;
    } else if pr < quarter {
        score += 4.0;
    } else if pr < bin_capacity / 2 {
        score += 8.0;
    } else {
        score += 15.0;
    }

    // Modulo arithmetic on post_residual: residuals divisible by common item
    // granularities (5, 10) are more reusable by future items.
    if pr % 10 == 0 && pr > 0 {
        score -= 5.0;
    } else if pr % 5 == 0 && pr > 0 {
        score -= 2.5;
    }

    // Lookahead coupling: does the next item fit into the post_residual?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 20.0; // perfect follow-up
        } else if next_item_size < pr {
            let slack = pr - next_item_size;
            score -= 8.0 * (1.0 - slack as f64 / cap);
            // harmonic class match: post_residual and next item share a divisor class
            if pr % 10 == next_item_size % 10 {
                score -= 3.0;
            }
        } else {
            // next item won't fit here; penalize proportionally to overflow
            score += 4.0 + (next_item_size - pr) as f64 * 0.15;
        }
    }

    // Last-chance bin before opening a new one: strong reward if fit is decent
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
        if pr < quarter {
            score -= 8.0;
        }
    }

    // New-bin candidate handling: prefer it only when open bins are congested
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let congestion = open_bins_count as f64 / (1.0 + mean_residual / cap);
        score = cap * 0.75 + congestion * 4.0 - progress * 5.0;
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 30.0; // next item needs a fresh bin anyway
        }
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    // Slight preference for fuller bins overall
    score -= (bin_residual as f64 / cap) * 2.0;

    // Tie-break via mean residual alignment
    score += (mean_residual - post_residual as f64) * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that nothing can use are heavily penalized.
    let min_item = 1u32;
    let dead = if post_residual < min_item {
        0.0
    } else if post_residual < next_item_size.max(min_item) {
        // unusable for the known next item
        40.0 + post_residual as f64
    } else if post_residual < 10 {
        // unusable for the smallest possible item
        60.0 + post_residual as f64
    } else {
        0.0
    };
    score += dead;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 100.0;
    }

    // Tight fit reward: residual almost consumed
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio;

    // Last-chance bonus: only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidating into existing ones;
    // when few are open, allow spreading (new bins) to keep flexibility.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 - progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: accept early or when current bin fits poorly.
        score += 15.0 + 8.0 * pressure - 10.0 * (1.0 - fill_ratio.min(1.0));
        // penalize new bin if existing bin would be near-perfectly filled
        if fill_ratio > 0.9 { score += 50.0; }
    } else {
        score -= 5.0 * pressure;
    }

    // Prefer bins with residual close to item (best-fit flavor)
    score += (bin_residual as f64 - item_size as f64).abs() * 0.3;

    // Slight preference toward bins below mean residual (balance residuals)
    score += (bin_residual as f64 - mean_residual) * 0.05;

    // Lookahead: if next item fits exactly in post_residual, reward strongly
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 45.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual, but scale relative to capacity.
    score = post_residual as f64 * (bin_capacity as f64 / 100.0);

    // Aggressive 2-step lookahead: reward exact match between post_residual
    // and the next item's size (perfect chaining).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if pr >= nxt {
            let diff = pr - nxt;
            // Reward closeness of post_residual to next_item_size.
            score -= (1.0 - diff / bin_capacity as f64) * 12.0;
            // Extra bonus for near-exact match.
            if diff <= 3.0 {
                score -= 15.0;
            }
        } else {
            // post_residual smaller than next item: penalize dead space,
            // worse when the gap is large relative to next item.
            let gap = nxt - pr;
            score += gap * 0.8;
        }
    }

    // Relative to mean residual: prefer bins whose residual deviates
    // favorably (smaller than average -> tighter packing).
    let pr = post_residual as f64;
    if mean_residual > 0.0 {
        let rel = (pr - mean_residual) / mean_residual;
        score += rel * 6.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Penalize creating very small unusable residuals (dead space < 10,
    // the minimum plausible item size).
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    }

    // Early in the stream, be more willing to open new bins to build
    // a diverse pool of residuals.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline slightly above tight fits,
        // cheaper late in the stream when consolidation matters.
        score = bin_capacity as f64 - progress * 15.0;
        if next_item_size > 0 && next_item_size as f64 >= bin_capacity as f64 * 0.5 {
            score -= 5.0;
        }
    } else if progress < 0.3 {
        // Early: mild penalty for filling bins too eagerly.
        score += 4.0 * (1.0 - progress / 0.3);
    }

    // Many open bins: encourage closing them out (prefer smallest residual).
    if open_bins_count > 8 {
        score += pr * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer tight fits: penalize large post-residual nonlinearly.
    let pr = post_residual as f64;
    score += 0.35 * pr * pr / bin_capacity as f64;

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0 + 0.25 * next_item_size as f64;
    }
    // Penalize leaving a small dead zone that the next item cannot use.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 0.6 * (next_item_size as f64 - pr);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Reward filling bins close to capacity (small residual relative to mean).
    score -= 0.15 * (bin_capacity as f64 - pr - mean_residual);

    // Time horizon: early on, be conservative about new bins; late, pack tight.
    let t = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus penalty scaled by how many bins are open.
        score = 0.85 * bin_capacity as f64 + 8.0 * (open_bins_count as f64).sqrt() + 20.0 * (1.0 - t);
        // A new bin is more attractive if existing residuals are large and unusable.
        if next_item_size > 0 && mean_residual < next_item_size as f64 {
            score -= 15.0;
        }
    } else {
        // Slight preference for bins above mean residual (use emptier bins when loose).
        if pr as f64 > mean_residual {
            score -= 3.0 * t;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base: penalize leftover space, scaled non-linearly by progress.
    let mut score = post * (1.0 + 0.5 * progress * progress);

    // Non-linear coupling: squared normalized post-residual (dead space emphasis).
    let norm_post = post / cap;
    score += 20.0 * norm_post * norm_post;

    // Perfect fit reward (smooth via exponential-like polynomial falloff).
    let fit_quality = 1.0 - norm_post;
    score -= 15.0 * fit_quality * fit_quality * fit_quality;

    // Lookahead: reward leaving space the next item can use.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        let usable = next_item_size as f64 / cap;
        score -= 8.0 * usable * (1.0 - progress);
    } else if next_item_size > 0 {
        // Next item cannot use the leftover: penalize.
        score += 6.0 * norm_post * (1.0 - progress);
    }

    // Last-chance bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 25.0;
    }

    // New-bin candidate: mild penalty early (prefer consolidation), reduced late.
    if is_new_bin {
        score += 5.0 + 10.0 * (1.0 - progress) + (open_bins_count as f64).sqrt();
    } else {
        // Slight reward for reducing bin count pressure.
        score -= 1.0 / (1.0 + open_bins_count as f64);
    }

    // Mean-residual deviation: prefer bins whose residual is near the mean (balanced use).
    let dev = (post - mean_residual) / cap;
    score += 4.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // ---- Harmonic class of the post-residual (integer division thresholds) ----
    // Residual classes: dead space buckets. Small post-residuals are gold.
    let cls = post_residual / 13; // ~8 harmonic classes (0..=7)
    score += match cls {
        0 => -18.0,                       // near-perfect fit
        1 => -10.0,
        2 => -4.0,
        3 => 0.0,
        4 => 3.0,
        5 => 6.0,
        6 => 9.0,
        _ => 12.0,                        // large dead space
    };

    // ---- Modulo coupling: post_residual mod 10 ----
    // Residuals that are "round" numbers are more reusable by typical item sizes.
    let m = post_residual % 10;
    if m == 0 {
        score -= 4.0;
    } else if m >= 7 {
        score += 2.0;
    }

    // ---- Lookahead (k=2): does the next item fit the post-residual? ----
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Great: this bin remains useful for the next item.
            let slack = (post_residual - next_item_size) as f64;
            score -= 14.0 - slack * 0.08; // prefer next-item fit with small leftover
        } else {
            // Next item cannot use the leftover; penalize proportionally.
            score += (next_item_size as f64 - post_residual as f64) * 0.12;
        }
    } else {
        // Last item of the stream: only tightness matters.
        score -= 6.0;
    }

    // ---- Last-chance bin: avoid opening a new bin unnecessarily ----
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // ---- Crowding pressure: many open bins -> consolidate ----
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 0.35 * (0.5 + progress);

    // ---- Mean-residual alignment: prefer bins near the mean residual ----
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin: slightly worse than a decent existing fit,
        // but better than a terrible one. Scale with stream progress and crowding.
        score = cap - 8.0 - 10.0 * progress + open_bins_count as f64 * 0.2;
        if next_item_size > 0 && next_item_size <= item_size {
            score -= 3.0; // fresh bin can host next item comfortably
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, prefer tight fills;
    // few open bins -> tolerate new bins.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * 2.0 * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when no open bin gives a good fit
    // (i.e., this call itself is the empty bin and item barely fits elsewhere poorly).
    if bin_residual == bin_capacity {
        // Baseline cost of opening a bin, softened when stream is early or many bins open.
        score = 0.5 * bin_capacity as f64 + pressure * 3.0;
        if post_residual as f64 >= mean_residual {
            score -= 5.0;
        }
    }

    // Lookahead: if next item fits exactly in post_residual, reward this placement.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        score += 8.0; // would leave a dead gap for the next item
    }

    // Prefer bins whose residual is already below mean (consolidating fullness).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact/near-exact fits strongly (non-linear).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    } else if post_residual <= 20 {
        score -= 8.0;
    }

    // 2-step lookahead: if the next item fits exactly into the post-residual,
    // this placement is excellent; reward it.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            // Slack left after also placing next item.
            let slack2 = post_residual - next_item_size;
            score -= 20.0 - (slack2 as f64) * 0.3;
        } else {
            // Next item won't fit here after placement: penalize if the leftover
            // is small (dead space) relative to next item.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.15;
        }
    }

    // Compare against mean residual: bins tighter than average are better targets.
    score += (post_residual as f64 - mean_residual) * 0.25;

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // relative to residual (i.e. current bins are very tight).
    if bin_residual == bin_capacity {
        let tightness = mean_residual / bin_capacity as f64;
        // If mean residual is small (bins nearly full), opening new bin is fine.
        score += 20.0 + 40.0 * (1.0 - tightness);
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0; // a fresh bin can absorb future items
        }
    }

    // Mild late-stream conservatism: waste less as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: fraction of bin consumed by this item.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill;

    // Penalize dead space that no plausible item (min size 1, typical >=10) can use.
    if post_residual > 0 {
        let waste = (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64);
        score += 0.6 * waste;
    }

    // Lookahead: if post_residual exactly or nearly fits the next item, reward strongly.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if (post_residual as f64) >= nx {
            let slack = post_residual as f64 - nx;
            if slack < 5.0 {
                score -= 25.0; // near-perfect chain
            } else {
                score -= 12.0 * (1.0 - slack / bin_capacity as f64);
            }
        } else {
            // post_residual too small for next item: penalize proportionally to wasted potential
            score += 0.4 * (nx - post_residual as f64).min(40.0);
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Many open bins: encourage closing them out (prefer bins with small residual).
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if open_bins_count > 4 {
        let close_bonus = 8.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        score -= close_bonus * (0.5 + 0.5 * t);
    }

    // Compare against mean residual: prefer bins below mean residual (tighter bins) to
    // consolidate space, keeping large-residual bins flexible for future big items.
    score += 0.15 * (mean_residual - post_residual as f64);

    // New-bin candidate handling: an empty bin has bin_residual == bin_capacity.
    // Only attractive when no open bin fits well or stream is early with big items coming.
    if bin_residual == bin_capacity {
        // Base penalty so open bins are usually preferred.
        score += 35.0;
        // But if this is the only fitting option, new bin is necessary: soften.
        if fitting_bins_count == 0 {
            score -= 100.0;
        } else if fitting_bins_count == 1 {
            // Last open bin fits poorly? Check its implied fit quality via item vs residual.
            let fit_quality = item_size as f64 / bin_residual as f64;
            if fit_quality < 0.6 {
                score -= 25.0; // poor fit in the sole bin -> new bin competitive
            }
        }
        // Early in the stream, keep flexibility: mildly favor new bins.
        score -= 10.0 * (1.0 - t);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_next = next_item_size as f64 / cap;

    // Base: post residual, scaled by progress (waste matters more later)
    let mut score = pr * (0.7 + 0.6 * progress);

    // Non-linear polynomial coupling of post_residual with progress
    let t = norm_pr * (1.0 - progress);
    score -= 40.0 * t * (1.0 - t);

    // Reward tight fits smoothly (quadratic decay of reward with residual)
    let tightness = 1.0 - norm_pr;
    score -= 30.0 * tightness * tightness * (0.5 + 0.5 * progress);

    // If next item fits in post residual, reward (lookahead coupling, smooth)
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let gap = (pr - next_item_size as f64) / cap;
        score -= 15.0 * (1.0 - gap) * (1.0 - gap);
    } else if next_item_size > 0 {
        // penalize leaving space that next item can't use, smoothly
        let miss = norm_next.min(1.0);
        score += 10.0 * miss * (1.0 - progress);
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Mild penalty when many bins already open
    score += open_bins_count as f64 * 0.3;

    // Smooth attraction toward mean residual state
    score += 0.1 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: reward tight fits (low post_residual), but with diminishing returns.
    let fill = (bin_residual as f64) / (bin_capacity as f64);
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness * fill;

    // Harmonic class logic: classify post_residual by integer-division thresholds.
    // Classes of residual: [0..9] perfect, [10..19] excellent, [20..34] ok, [35..54] poor, [55+] dead.
    let cls = post_residual / 15;
    let class_penalty = match cls {
        0 => -20.0,
        1 => -10.0,
        2 => 0.0,
        3 => 8.0,
        _ => 18.0,
    };
    score += class_penalty;

    // Modulo coupling: post_residual divisible by small integers pairs well with
    // common item sizes (10..80 multiples of 5/10). Reward residuals that are
    // "reusable" by next_item_size.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item fits: excellent, reward proportionally to how well it fills.
            let next_fill = (next_item_size as f64) / (post_residual as f64);
            score -= 25.0 * next_fill;
        } else {
            // Next item cannot fit here: penalize if residual is stranded.
            score += 6.0;
        }
        // Harmonic pairing: post_residual % next_item_size near 0 means near-perfect
        // future packing chain.
        if post_residual > 0 && next_item_size <= post_residual {
            let m = post_residual % next_item_size;
            let mfrac = (m as f64) / (next_item_size as f64);
            score -= 12.0 * (1.0 - mfrac);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Many fitting bins: competition is high, prefer the tightest (already via post_residual),
    // but slightly penalize leaving many near-full bins idle.
    if fitting_bins_count > 1 {
        score += 2.0 * ((fitting_bins_count as f64).ln());
    }

    // Mean-residual coupling: prefer bins whose residual is close to the mean
    // (balanced depletion), penalize outliers.
    let dev = ((post_residual as f64) - mean_residual).abs();
    score += 0.15 * dev;

    // New-bin candidate handling: a fresh bin should only win when no open bin
    // gives a good fit, or when open bins are nearly full.
    if bin_residual == bin_capacity {
        // Fresh bin baseline: penalize mildly so it only wins for bad fits.
        score += 15.0;
        // If the item is large relative to capacity, a fresh bin is more attractive.
        let item_frac = (item_size as f64) / (bin_capacity as f64);
        score -= 10.0 * item_frac * item_frac;
        // Early in the stream, opening bins is cheaper.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
        // Few open bins -> new bin less costly.
        score -= 3.0 / (1.0 + open_bins_count as f64);
    } else {
        // Slight bonus for using open bins generally.
        score -= 1.0;
    }

    // Harmonic modulo thresholds on post_residual: reward residuals in
    // multiples of 10 (align with typical item granularity).
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps.
    // Gaps that are too small for the smallest plausible item are pure waste.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // unusable dead space
        } else if post_residual < item_size.min(20) {
            score += 15.0; // likely unusable for future items
        }
    } else {
        // Perfect fit: strong reward
        score -= 40.0;
    }

    // Reward exact match of post_residual to next item (lookahead synergy)
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0; // gap still usable by next item
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only prefer opening a new bin when the
    // current bin would leave a large-ish awkward residual and open-bin
    // pressure is low.
    if bin_residual == bin_capacity {
        // brand-new bin: baseline score = item_size; adjust by stream progress
        score = item_size as f64 + 10.0 * (step_index as f64 / total_items.max(1) as f64);
        if open_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    } else {
        // Open-bin pressure: penalize spreading across many bins
        score += open_bins_count as f64 * 0.5;
        // Slight preference for bins with residuals below mean (tighten tight bins)
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward if the next item fits perfectly into the post-residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 - slack.min(40.0); // perfect match (slack 0) gets -40
    }

    // Penalize leaving residual that no plausible item can use (dead space).
    if post_residual > 0 && (next_item_size == 0 || next_item_size > post_residual) {
        // dead space grows in cost as it approaches small unusable slivers
        let dead = post_residual as f64;
        score += 0.6 * dead;
    }

    // Last chance: this is the only bin that fits; avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Reward tightening bins relative to the mean residual (best-fit coupling).
    let mean_gap = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * mean_gap;

    // Slight preference for fuller bins (smaller bin_residual).
    score += 0.1 * bin_residual as f64;

    // New-bin candidate: only attractive when no open bin fits well,
    // i.e., when open bins are crowded or this would be a fresh start.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = 60.0;
        // If many bins fit, discourage opening a new one.
        if fitting_bins_count > 1 {
            score += 30.0;
        }
        // If this is the last-fitting bin situation, strongly discourage new bin.
        if fitting_bins_count == 1 {
            score += 60.0;
        }
        // Early in stream, new bins are cheaper to open.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - progress);
    }

    // Mild pressure with number of open bins: prefer consolidating.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: penalize large post residual nonlinearly
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    score += 0.35 * (post * post) / cap;

    // Reward near-perfect fits strongly
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Last-chance bin: strong reward to use it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly in post residual, big reward
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as i64) == (next_item_size as i64) {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            // next item fits here: reward proportional to how well it uses leftover
            score -= 12.0 * (nxt / (post + 1.0));
        } else {
            // leftover too small for next item: penalize dead space
            score += 8.0 * (1.0 - post / cap);
        }
    }

    // Global state: when many bins are open with high mean residual,
    // prefer consolidating into existing bins over opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let new_bin_bonus = (mean_residual / cap) * (1.0 + 2.0 * progress) * 10.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize when open bins are roomy; slight reward early on
        score += new_bin_bonus - 3.0 * (1.0 - progress);
        // Avoid opening new bins when plenty fit
        if fitting_bins_count > 2 {
            score += 15.0;
        }
    } else {
        // Existing bin: reward using bins with residuals near the mean (balance)
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.15 * dev;
    }

    // Prefer fuller bins (smaller residual before placement)
    score += 0.1 * (bin_residual as f64 - item_size as f64) / cap;

    // Mild exploration term coupling open bins count and progress
    score += 0.02 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer small post-residual (tight fit), with smooth non-linear shaping.
    let norm_post = post / cap; // 0..1
    let mut score = post * (1.0 + 0.8 * norm_post * norm_post);

    // Dead-space penalty: residuals too small for any plausible future item are wasted.
    let dead = (1.0 - norm_post).powi(3);
    score += 30.0 * dead;

    // Stream-progress coupling: late in the stream, tighten preference for tight fits.
    score *= 1.0 + 0.5 * progress * (1.0 - norm_post);

    // Lookahead: bonus if next item fits the post-residual (good chaining).
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 12.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 6.0 * (1.0 - post / cap.max(1.0));
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Mean-residual coupling: if this bin's residual is far below average, it's a good absorber.
    score -= 0.3 * (mean_residual - post).clamp(-cap, cap) * 0.1;

    // New-bin candidate: neutral-ish score so it wins only over poor fits.
    if bin_residual == bin_capacity {
        score = cap * 0.85 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals divisible by small
    // denominators are more likely to be filled by future items.
    let pr = post_residual;
    let harmonic_bonus = if pr == 0 {
        -40.0 // perfect fit, strongly favored
    } else if pr % 10 == 0 {
        -12.0
    } else if pr % 5 == 0 {
        -6.0
    } else if pr % 25 == 0 {
        -9.0
    } else {
        0.0
    };
    score += harmonic_bonus;

    // Dead-space penalty: tiny unusable residuals.
    if pr > 0 && pr < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post
    // residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size <= pr {
            score -= 8.0;
        } else {
            // next item won't fit here; mildly penalize wasting large residual
            score += (pr as f64) * 0.05;
        }
    }

    // Last-chance logic: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize so it's chosen only when no open bin
    // offers a decent fit (residual stays high = 100 baseline).
    if bin_residual == bin_capacity {
        score += 20.0 - 0.1 * open_bins_count as f64;
    }

    // Prefer packing into bins with low mean residual (tighten nearly full bins).
    score += 0.15 * (mean_residual - post_residual as f64);

    // Early stream: be slightly more open to new bins; later, consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 100.0;
    }

    // Reward good fill ratio of the bin.
    score -= (item_size as f64 / bin_capacity as f64) * 20.0;

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            score -= 15.0;
        } else if post_residual > 0 && next_item_size > post_residual {
            // Dead space for the known next item.
            score += 10.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: penalize opening a new bin, more so with many open bins.
    if bin_residual == bin_capacity {
        score += 40.0 + 5.0 * open_bins_count as f64;
        // But if no other bin fits well (this is the only fitting candidate), allow it.
        if fitting_bins_count == 1 {
            score -= 60.0;
        }
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones.
    score += (open_bins_count as f64).ln().max(0.0) * 3.0;

    // Prefer bins whose residual is close to the item (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 30.0;

    // Mean residual coupling: if bin residual deviates far from mean, mild penalty.
    score += ((bin_residual as f64 - mean_residual).abs() / bin_capacity as f64) * 5.0;

    // Late in stream: prioritize closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits the post residual exactly or well.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 >= nxt {
            // Perfect 2-step fill: post residual matches next item exactly
            let gap = (post_residual as u32).wrapping_sub(next_item_size) as f64;
            score -= 30.0 * (1.0 - gap / bin_capacity as f64);
            if gap == 0.0 {
                score -= 60.0; // exact two-item fill => bin closed perfectly
            }
        } else {
            // Next item cannot fit: post residual becomes pure dead space
            score += 0.6 * (post_residual as f64 - nxt).abs().max(0.0);
            score += 10.0;
        }
    } else {
        // Last item: prefer minimal post residual
        score += 0.3 * post_residual as f64;
    }

    // Relative-to-mean coupling: bins tighter than mean are good targets
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bonus: only bin that fits the item
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalize opening a new bin when fitting bins exist with good fit
    if bin_residual == bin_capacity {
        // New bin candidate: residual stays large, penalize unless item is huge
        score += 40.0 - 0.3 * item_size as f64;
        // But if no open bin can fit and this is the new-bin call, fitting_bins_count includes it
        if fitting_bins_count <= 1 {
            score -= 55.0;
        }
    }

    // Early stream: be slightly more aggressive in reusing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 - 0.1 * progress;

    // Small penalty for very tight fits that leave unusable slivers
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize wasted fraction relative to capacity.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fit_ratio;

    // Penalize leaving awkward dead space (small post-residual that likely can't fit future items).
    if post_residual > 0 {
        let dead = (post_residual as f64) * (1.0 - post_residual as f64 / bin_capacity as f64);
        score += 0.35 * dead;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strongly reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let lookahead_tightness = next_item_size as f64 / post_residual.max(1) as f64;
        score -= 15.0 * lookahead_tightness;
    }
    // If next item doesn't fit and post_residual is small, mildly penalize hoarding space.
    if next_item_size > post_residual && post_residual < 10 {
        score += 6.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when existing residuals are poorly matching.
    if bin_residual == bin_capacity {
        let mismatch = (mean_residual - item_size as f64).abs();
        score = 45.0 + 0.6 * mismatch - 8.0 * (open_bins_count as f64).ln().max(0.0);
        // Early in stream, opening bins is cheap; late, avoid bin proliferation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
    }

    // Mildly prefer bins below mean residual (consolidate large residuals).
    score += 0.08 * (bin_residual as f64 - mean_residual);

    // Crowding: with many open bins, prefer filling existing ones.
    score -= 0.15 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress
    let prn = pr / cap; // normalized post residual in [0,1]
    let w = 1.0 + 0.6 * progress;
    score += w * (prn * prn) * cap * 0.5;

    // Penalize dead space more as stream progresses (fewer chances to fill)
    score += progress * prn * prn * prn * cap;

    // Reward tight fits (small post residual) smoothly
    score -= (1.0 - prn) * (1.0 - prn) * 8.0;

    // Lookahead: if next item fits exactly in post residual, reward strongly
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let fill = nx / pr.max(1.0);
            score -= 12.0 * fill * fill;
        } else {
            // next item won't fit: penalize wasted residual smoothly
            score += 4.0 * (nx - pr) / cap;
        }
    }

    // Last-chance bonus: only bin that fits -> strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Prefer bins below mean residual (more packed bins) smoothly
    score += 0.3 * (pr - mean_residual);

    // Mild preference for consolidating into fewer bins when many open
    score += 0.1 * open_bins_count as f64 * prn;

    // New-bin candidate: make it attractive only when no tight option exists
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * progress;
        if next_item_size > 0 && (next_item_size as f64) <= mean_residual {
            score -= 15.0; // an open bin likely serves next item too
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod 10 and integer-division thresholds.
    let post = post_residual;
    let post_class = post / 10; // coarse harmonic class (0..=9)
    let post_residue = post % 10;

    // Penalize dead space: residuals that cannot accommodate common small items.
    if post > 0 && post < 10 {
        score += 25.0; // unusable sliver
    }

    // Reward post-residuals that can exactly host the lookahead item (perfect pairing).
    if next_item_size > 0 {
        if post == next_item_size {
            score -= 30.0;
        } else if post >= next_item_size {
            // Slack after also placing next item: penalize leftover of next placement.
            let next_left = post - next_item_size;
            score += (next_left as f64) * 0.4;
            // Harmonic bonus: next_left divisible by 10 is reusable space.
            if next_left % 10 == 0 && next_left > 0 {
                score -= 6.0;
            }
        } else {
            // Next item cannot follow in this bin: penalize mildly unless bin nearly full.
            score += 5.0;
        }
    }

    // Class-based desirability of the leftover residual: classes 0 and 5 (multiples of 10/20)
    // are the most reusable; odd residues are worst.
    let class_bonus = match post_class {
        0 => 8.0,                       // bin closed perfectly
        1 => 2.0,                       // 10-19: fits small items
        2 | 3 => 4.0,                   // 20-39: flexible
        4..=6 => 5.0,                   // 40-69: very flexible
        _ => 1.0,                       // 70+: mostly-empty bin, wasteful use
    };
    score -= class_bonus;

    // Odd residue penalty (harmonic dissonance).
    if post_residue % 2 == 1 {
        score += (post_residue as f64) * 0.15;
    }
    // Residues 1..9 mod 10 that are prime (7,3) are especially awkward.
    if post_residue == 7 || post_residue == 3 {
        score += 3.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive early in the
    // stream or when the item is huge and fits nothing well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64).max(1.0);
        let huge = item_size >= 70;
        let poor_alternatives = fitting_bins_count == 0;
        // Penalize new bins more as stream progresses (commitment to consolidation),
        // unless item is huge or no open bin fits.
        let mut new_bin_score = 55.0 + progress * 30.0 - (item_size as f64) * 0.2;
        if huge { new_bin_score -= 15.0; }
        if poor_alternatives { new_bin_score -= 60.0; }
        score = new_bin_score;
        return score;
    }

    // Prefer tighter fits overall: scale by fullness fraction of the bin.
    let fullness = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fullness * 8.0;

    // Mild pressure toward consolidation when many bins are open.
    if open_bins_count > 4 {
        score -= 2.0;
    }

    // Coupling with mean residual: placing into a bin far below mean residual
    // (i.e., consuming a large chunk) is good; avoid draining already-tight bins.
    if (post_residual as f64) < mean_residual {
        score -= 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps (< 10) are pure waste.
    if post_residual < 10 {
        score -= 60.0; // perfect or near-perfect fill is excellent
    } else if post_residual <= 20 {
        // Gaps of 10..20 can still fit a minimum item — mild dead-space penalty
        score += (20 - post_residual) as f64 * 0.8;
    } else if post_residual <= 35 {
        // Danger zone: gap too small for many items — strong penalty
        score += (35 - post_residual) as f64 * 2.0;
    }

    // Reward using tight fits: how well the item fills the bin relative to residual
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 25.0;

    // Open-bins pressure: discourage spreading across many open bins
    score += open_bins_count as f64 * 1.5;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    // or the fit into existing bins would create dead space.
    if bin_residual == bin_capacity {
        // Base new-bin cost: opening a bin is expensive
        score += 30.0;
        // But cheaper when many bins are open (parallelism already high)
        score -= (open_bins_count as f64).min(20.0) * 0.5;
        // Expensive if an existing bin fits nearly perfectly
        if post_residual < 10 && bin_residual != bin_capacity {
            score += 50.0; // never open new bin when a perfect fit exists
        }
        // Lookahead: if next item is small, leftover space in a new bin is fine
        if next_item_size > 0 && next_item_size <= 20 {
            score -= 10.0;
        }
        // Early in stream: opening bins is cheaper (need bins anyway)
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - progress) * 15.0;
    } else {
        // Existing bin: reward leaving space usable by the next item
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 12.0; // this bin can also host the next item — chain bonus
        } else if next_item_size > 0 {
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
        // Penalize bins whose residual deviates badly from mean (fragmentation)
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.15;
        // Late in stream: prefer closing out bins tightly
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= progress * (100.0 - post_residual as f64) * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match between post_residual and next item
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 / (1.0 + diff);
        // Perfect chain: next item exactly fills the bin
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // Penalize leaving residual that neither fits next item nor is tiny
        if next_item_size > post_residual && post_residual > 0 {
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    } else {
        // Last item: strongly prefer tightest fill
        score += 10.0;
    }

    // Penalize large dead space relative to mean residual of open bins
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.3;
    } else {
        score -= (mean_residual - post_residual as f64) * 0.1;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Reward tight fits (small post_residual) with a non-linear bonus
    score -= 20.0 * (-post_residual as f64 / 15.0).exp();

    // New-bin candidate handling: only open a new bin if item is large relative
    // to capacity and no good fit exists; otherwise penalize opening new bins
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        score += 15.0 - 20.0 * tightness;
        if fitting_bins_count > 0 && next_item_size > 0 && next_item_size <= post_residual {
            score += 30.0; // an open bin can chain with next item; avoid new bin
        }
    }

    // Late in stream: prefer closing bins tightly, discourage spreading
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * post_residual as f64 * 0.2;

    // Prefer bins that are already partially filled (reduce bin count pressure)
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    // Mild penalty scaled by number of open bins to encourage consolidation
    score += open_bins_count as f64 * 0.02 * post_residual as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tightness: reward small post_residual relative to capacity
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * 60.0;

    // Penalize large dead space unless it fits the lookahead item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Lookahead fit: strong reward proportional to how snugly next item fits
            let lookahead_waste = (post_residual - next_item_size) as f64;
            score -= 45.0 - (lookahead_waste / bin_capacity as f64) * 40.0;
        } else {
            // Dead space that next item can't use
            score += (post_residual as f64) * 0.8;
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New bin candidate logic: penalize opening a new bin when open bins exist with decent residuals,
    // unless the item is large relative to residual and mean residual is low.
    if bin_residual == bin_capacity {
        // base cost of a fresh bin
        score += 55.0;
        // If existing bins fit the item, discourage new bin
        if fitting_bins_count > 0 {
            score += 25.0;
        }
        // Late in the stream, opening new bins is more acceptable (spill-over)
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= progress * 20.0;
        // If mean residual is small (bins nearly full), a new bin is natural
        score += mean_residual * 0.15;
        // Large items pack better in a fresh bin
        if item_size > bin_capacity / 2 {
            score -= 18.0;
        }
    } else {
        // Reward using existing bins more when many bins are open (consolidation pressure)
        score -= (open_bins_count as f64).ln().max(0.0) * 6.0;
    }

    // Prefer bins whose residual is close to mean residual (balance)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.25;

    // Slight preference for bins with larger residual when item is large
    score -= (bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let progress_sq = progress * progress;

    // Tightness: fraction of bin filled by this placement
    let fill = item_size as f64 / cap;
    let post_frac = post_residual as f64 / cap;

    // Reward tight fits: non-linear coupling of fill with progress
    score -= 12.0 * fill * fill * (0.5 + progress);

    // Penalize dead space quadratically, stronger later in stream
    score += 0.8 * post_frac * post_frac * (1.0 + 2.0 * progress_sq) * cap;

    // Perfect fit reward (post_residual near zero)
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 15.0 * (1.0 - post_frac);
    }

    // Lookahead coupling: if next item fits in post_residual, reward; else penalize
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (next_item_size as u32) <= post_residual {
            score -= 6.0 * (1.0 - (nxt / cap)) * (0.5 + progress);
        } else {
            score += 4.0 * (nxt / cap) * (1.0 + progress_sq);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0 * (1.0 - progress_sq);
    }

    // New-bin candidate: prefer opening a new bin early in stream or when mean
    // residual of open bins is large (fragmented bins); penalize otherwise.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).clamp(0.0, 1.0);
        score = 55.0 + 40.0 * fragmentation - 25.0 * (1.0 - progress);
        if open_bins_count == 0 {
            score = 0.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover is "dead space"
    // (below the minimum item size) are heavily penalized unless zero.
    let min_item = 1u32;
    if post_residual == 0 {
        score -= 60.0; // perfect fit: strongly favored
    } else if post_residual < min_item {
        score += 200.0; // unreachable dead space (should not occur, safety)
    } else {
        // Classify leftover by capacity fractions (harmonic classes 1/2, 1/3, 1/4)
        let c = bin_capacity as f64;
        let half = c / 2.0;
        let third = c / 3.0;
        let quarter = c / 4.0;
        let pr = post_residual as f64;
        if pr < quarter {
            score += 6.0; // small leftover: nearly full bin, mildly good
        } else if pr < third {
            score += 2.0;
        } else if pr < half {
            score -= 3.0; // medium leftover: still reusable
        } else {
            score += 4.0; // large leftover: wasteful placement
        }
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            // reward proportionally to how tightly next item fits
            let tight = (post_residual - next_item_size) as f64;
            score -= 20.0 - tight * 0.15;
        } else {
            // next item cannot use this bin's leftover; penalize large leftovers
            score += (post_residual as f64) * 0.1;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin, more so when many bins open
    if bin_residual == bin_capacity {
        score += 30.0 + 5.0 * (open_bins_count as f64).sqrt();
        // but allow fresh bin if current placement would strand a huge residual
        if post_residual > bin_capacity / 2 && next_item_size > post_residual {
            score -= 35.0;
        }
    }

    // Prefer bins whose residual is below the mean (tighter bins first)
    score -= (mean_residual - post_residual as f64) * 0.05;

    // Slight preference for tighter fits overall
    score += (bin_residual - item_size) as f64 * 0.02;

    // Late in stream: favor closing bins (perfect fits) more aggressively
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if post_residual == 0 {
        score -= 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small to hold even the
    // smallest plausible future item are pure waste. Penalize them hard,
    // with a smooth non-linear escalation as the gap shrinks.
    let pr = post_residual as f64;
    if post_residual > 0 {
        let tightness = 1.0 - (pr / bin_capacity as f64);
        score += 6.0 * tightness * tightness * (1.0 + pr / 20.0);
    }

    // Perfect fit reward: leaving exactly zero waste is ideal.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Small-gap dead zone: if the post residual can't fit the lookahead item
    // (or any typical small item), it's likely unusable — extra penalty.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0 + 0.15 * (next_item_size as f64 - pr);
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Open-bin pressure: discourage opening new bins when few are open,
    // reward consolidation when many bins are already open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open or late in stream.
        score += 18.0 + 4.0 * pressure + 10.0 * progress;
    } else {
        score -= 2.0 + pressure * 0.5;
    }

    // Prefer bins whose residual is already below average (consolidating
    // fragmented space into already-small bins keeps large gaps open).
    if bin_residual != bin_capacity {
        let diff = bin_residual as f64 - mean_residual;
        score += 0.08 * diff;
    }

    // Reward leaving a gap that exactly fits the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for a perfect (or near-perfect) fit.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 3 {
        score -= 300.0;
    } else if post_residual <= 10 {
        score -= 120.0;
    }

    // 2-step lookahead: reward when the next item fits the post residual exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual >= next_item_size {
            let leftover2 = post_residual - next_item_size;
            score -= 150.0 - (leftover2 as f64) * 1.5;
        } else {
            // Next item won't fit here; penalize wasted residual relative to mean.
            let waste = post_residual as f64;
            score += waste * 0.6 * (1.0 + waste / (mean_residual.max(1.0)));
        }
    }

    // Compare post residual against the mean residual of open bins:
    // favor bins whose residual stays close to (or below) the average.
    score += (post_residual as f64 - mean_residual) * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Penalize opening a brand-new bin when good fits exist elsewhere.
    if bin_residual == bin_capacity {
        score += 250.0;
        // Early in the stream, new bins are cheaper; late, prefer consolidation.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 150.0;
        // If next item is large, a fresh bin may be justified.
        if next_item_size > 0 && next_item_size as f64 > mean_residual {
            score -= 180.0;
        }
    }

    // Mild preference for tighter bins overall.
    score += (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: prefer bins where post_residual is small relative to capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * (1.0 - tightness * tightness);

    // Penalize creating dead space that no plausible item can fill.
    if post_residual > 0 {
        // If post_residual is smaller than the smallest plausible item, it is dead space.
        if post_residual < 10 {
            score += 8.0;
        }
        // If lookahead item fits exactly into post_residual, big reward.
        if next_item_size > 0 && next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size > 0 && next_item_size <= post_residual {
            score -= 6.0;
        } else if next_item_size > 0 {
            // Lookahead cannot use this residual: penalize proportionally.
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: brand-new empty bin (bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        // Opening a new bin is costly when existing bins fit reasonably well.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Penalize new bins more early in the stream (amortize open bins longer).
        score += 20.0 + 15.0 * (1.0 - progress);
        // If many open bins already, discourage fragmentation further.
        score += (open_bins_count as f64).sqrt() * 2.0;
        // If mean residual across open bins is small, a new bin may be warranted:
        // soften the penalty.
        if mean_residual < item_size as f64 {
            score -= 10.0;
        }
    }

    // Mild preference for bins whose residual is close to the mean (balance load),
    // avoiding extreme outliers.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Slight time-dependent exploration: later in stream, favor tighter packing more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (1.0 - tightness);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    let mut score = pr;

    // Non-linear coupling: post_residual weighted by smooth progress polynomial
    let prog2 = progress * progress;
    let prog3 = prog2 * progress;
    let shape = 0.5 + 0.5 * prog2 - 0.25 * prog3;
    score += 3.0 * shape * norm_pr * norm_pr * cap;

    // Penalize residuals that are too small to matter (dead space) via smooth ramp
    let dead = (1.0 - norm_pr).clamp(0.0, 1.0);
    score += 5.0 * dead * dead * dead * (1.0 - progress);

    // Reward tight fits: subtract when post_residual is small relative to capacity
    score -= 8.0 * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Lookahead: if next item fits into post_residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let fit_quality = 1.0 - ((pr - next_item_size as f64) / cap);
        score -= 6.0 * fit_quality * (0.5 + 0.5 * progress);
    } else if next_item_size > 0 {
        score += 2.0 * (1.0 - progress);
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 10.0 * (1.0 + progress);
    }

    // Mean residual alignment: prefer bins whose resulting residual is near the mean
    let dev = (pr - mean_residual).abs() / cap;
    score += 2.0 * dev * dev;

    // New-bin candidate handling: penalize opening a new bin early/mid stream,
    // slightly relax late when open bins are fragmented
    if bin_residual == bin_capacity {
        let fragmentation = (open_bins_count as f64 / (1.0 + mean_residual / 20.0)).min(3.0);
        score += 15.0 * (1.0 - 0.3 * progress) - 3.0 * fragmentation;
    }

    // Mild penalty for too many open bins
    score += 0.3 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base best-fit: prefer small post_residual.
    // Harmonic class of post_residual: dead space is more acceptable when it
    // falls in a "usable" class (divisible by small common item sizes).
    let pr = post_residual;
    // Reward post_residuals that are multiples of 10 (harmonic with typical sizes)
    if pr % 10 == 0 {
        score -= 6.0;
    }
    if pr % 5 == 0 {
        score -= 2.0;
    }
    // Perfect fill
    if pr == 0 {
        score -= 40.0;
    }

    // Penalize tiny dead space (5..15) that is hard to fill: awkward zone.
    if pr > 0 && pr < 15 {
        score += 8.0;
    }

    // Lookahead: if next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size < pr {
            // next item fits: residual remains usable, mild reward scaled by fit tightness
            score -= 5.0 * (next_item_size as f64 / pr.max(1) as f64);
        } else {
            // next item cannot use this bin's residual: penalize proportional to waste
            score += 3.0 * (next_item_size as f64 / bin_capacity as f64) * 10.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    // or the fit here is terrible.
    if bin_residual == bin_capacity {
        // new bin baseline: post_residual == capacity - item_size, but discourage
        // opening new bins when existing bins fit reasonably.
        score += 20.0;
        if open_bins_count == 0 {
            score -= 100.0; // must open first bin
        }
        // early in stream, opening fresh bins is fine
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - progress);
    }

    // Prefer filling bins with larger residuals when many bins are open
    // (consolidation): score relative to mean residual.
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Integer-division thresholds on post_residual classes:
    // large residual (>50) bins should be deprioritized for small items to
    // preserve big space for big items.
    if pr > 50 && item_size < 40 {
        score += 6.0;
    }
    // Modulo coupling: if item and residual share class, tighter fit
    if pr > 0 && bin_residual % (item_size.max(1)) == 0 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // even a minimum item are pure waste; penalize them extra hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        // Small gaps are only valuable if the next item can use them.
        if next_item_size == 0 || next_item_size > post_residual {
            score += 25.0 + (20.0 - post_residual as f64) * 1.5;
        } else {
            score -= 15.0; // lookahead item fits the gap exactly-ish: reward
        }
    } else {
        // Medium/large gaps: reward when next item can consume the gap well.
        if next_item_size > 0 && next_item_size <= post_residual {
            let waste = (post_residual - next_item_size) as f64;
            score -= 10.0 - waste * 0.3;
        }
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Near-perfect fit: leaving a gap smaller than the smallest item is bad,
    // but a gap just above a plausible item size is good.
    let gap = post_residual as f64;
    score += 0.35 * (gap - mean_residual).abs();

    // Open-bin pressure: with many open bins, discourage spreading; prefer
    // filling existing bins rather than opening new ones.
    score += open_bins_count as f64 * 0.8;

    // New-bin candidate handling: an empty bin should only win when no
    // existing bin offers a decent fit, or when this is the last chance bin
    // and the fit is poor.
    if bin_residual == bin_capacity {
        // Opening a new bin is costly; add pressure that grows with open bins
        // and stream progression.
        score += 45.0 + open_bins_count as f64 * 1.2
            + (step_index as f64 / total_items.max(1) as f64) * 20.0;
        // But if no open bin fits at all, opening is inevitable: soften cost.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
        if post_residual < 10 {
            score += 35.0; // ...but not if it creates dead space
        }
    }

    // Early stream: be slightly more willing to open bins to build flexibility.
    if step_index < total_items / 10 {
        if bin_residual == bin_capacity {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong lookahead: reward when next item exactly matches post residual.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 2.5 * (bin_capacity as f64 - diff).max(0.0);
        // Perfect match bonus
        if post_residual == next_item_size {
            score -= 60.0;
        }
        // Penalize leaving space the next item can't use at all
        if next_item_size > post_residual && post_residual > 0 {
            score += 0.5 * post_residual as f64;
        }
    }

    // Relative-to-mean residual shaping: prefer bins tighter than the average.
    score += 0.8 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: neutral-ish baseline, penalize mildly so it's chosen
    // only when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 30.0;
    }

    // Late in the stream, prefer closing bins tightly (less fragmentation).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.5 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness: reward small post_residual relative to capacity
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * 30.0;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 40.0;
    }

    // Lookahead: penalize if next item could have used this residual better
    if next_item_size > 0 {
        let next_fits_now = (next_item_size as u32) <= post_residual;
        let next_fits_after = (next_item_size as u32) <= bin_residual;
        if next_fits_now {
            score += 15.0; // this residual might serve the next item; slight penalty
        }
        if !next_fits_after {
            score -= 10.0; // next item can't use this bin anyway; free to use it
        }
        // residual close to next item size is valuable
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += gap * 0.3;
    }

    // Last chance: strongly favor using the only bin that fits
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // Mean residual coupling: avoid dumping into already-fragmented bins
    score += (mean_residual - post_residual as f64) * 0.2;

    // New bin candidate logic: only attractive when open bins are crowded
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowd = open_bins_count as f64;
        let pressure = crowd * (1.0 - tightness) + progress * 10.0;
        score = 25.0 + pressure; // baseline so it loses to decent fits
        if next_item_size > 0 && (next_item_size as u32) <= bin_capacity {
            score -= 5.0;
        }
    }

    // Fragmentation penalty: large unusable residuals
    if post_residual > 0 && post_residual < item_size {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with non-linear polynomial shaping
    let mut score = pr
        + 20.0 * norm_pr * norm_pr
        + 40.0 * norm_pr * norm_pr * norm_pr;

    // Smooth interaction: residual quality vs stream progress
    // Early: prefer tight fills (low post_residual); late: tolerate spreading
    let progress_coupling = progress * (1.0 - progress) * 4.0; // peaks mid-stream
    score -= 15.0 * progress_coupling * norm_pr * (1.0 - norm_pr);

    // Penalize dead space relative to mean residual (smooth quadratic coupling)
    let mean_gap = norm_pr - mean_residual / cap;
    score += 10.0 * mean_gap * mean_gap * cap * (0.5 + progress);

    // Lookahead: reward leaving space exactly usable by next item (smooth kernel)
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        let kernel = (gap / 20.0) * (gap / 20.0);
        score -= 12.0 * (-kernel) * (pr >= next_item_size as f64) as i32 as f64;
    }

    // Last-chance bin: strong smooth reward scaled by scarcity
    let scarcity = (fitting_bins_count as f64).recip();
    score -= 25.0 * scarcity * (1.0 + progress);

    // Mild penalty for too many open bins (smooth saturating term)
    score += 3.0 * (open_bins_count as f64 / (1.0 + open_bins_count as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: which capacity-fraction band does the leftover fall in?
    let post_class = (post_residual * 4) / bin_capacity; // 0..=3 integer division band
    let next_class = (next_item_size * 4) / bin_capacity;

    // Reward when next item fits exactly into the post-residual harmonic class band
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - gap / cap_f);
        // exact modular match bonus: post_residual == next_item_size
        if post_residual == next_item_size {
            score -= 15.0;
        }
        // modulo coupling: post_residual % next_item_size small => chainable
        if next_item_size > 0 {
            let m = post_residual % next_item_size;
            score -= 6.0 * (1.0 - m as f64 / next_item_size as f64);
        }
    } else if next_item_size > post_residual && next_item_size > 0 {
        // next item won't fit here: penalize small post_residuals that become dead space
        score += 8.0 * (1.0 - post_residual as f64 / cap_f);
    }

    // Penalize tiny dead space (< 10) that nothing can use
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Prefer tight fits: post_residual small relative to item
    score -= 10.0 * (item_size as f64 / cap_f) * (1.0 - post_residual as f64 / cap_f);

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 14.0;
    }

    // New-bin candidate handling: penalize opening a new bin when decent fits exist,
    // but allow it when post_residual of this empty bin is large and item is big.
    if bin_residual == bin_capacity {
        score = cap_f - item_size as f64; // baseline = post_residual for empty bin
        if fitting_bins_count > 1 {
            score += 10.0;
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 5.0; // room for lookahead pairing
        }
    }

    // Late-stream consolidation: prefer reusing bins as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 4.0 * progress * (bin_residual as f64 / cap_f);

    // Prefer bins with below-mean residual (tighter bins first)
    score += 3.0 * (post_residual as f64 - mean_residual) / cap_f;

    // Harmonic class penalty: leaving residual in awkward middle band (25-50%)
    if post_class == 1 && next_class != 1 {
        score += 5.0;
    }
    if post_class == 3 {
        score -= 3.0; // large leftover is flexible
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that can never fit a future item
    // (small gaps) are heavily penalized, scaled by stream progression.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let dead_threshold = 12.0;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * (6.0 + 6.0 * progress);
    }

    // Perfect fit bonus: reward using the bin exactly.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward leaving room for the known next item (lookahead k=2).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.1 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Creating a gap smaller than the next item: penalize extra.
        score += 5.0;
    }

    // Open-bin pressure: discourage spreading across many bins; discourage
    // opening a new bin unless it's near the end of the stream or unavoidable.
    score += 2.0 * (open_bins_count as f64).ln().max(0.0);

    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when nothing fits well
        // (post_residual == capacity - item_size is large) or few bins open.
        let waste = post_residual as f64;
        score += waste * 0.5;
        score -= 10.0 / (open_bins_count as f64 + 1.0);
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    } else if fitting_bins_count == 1 {
        // Last-chance bin: strongly favor using it over opening a new bin.
        score -= 30.0;
    }

    // Slight preference for bins already below mean residual (consolidation).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Mild preference for tighter fits overall.
    score += 0.1 * (bin_residual - item_size) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: heavily reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when next item exactly fills post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // Next item fits: mild reward proportional to how well it fits after.
            let next_post = post_residual - next_item_size;
            score -= 100.0 - next_post as f64;
        } else {
            // Next item won't fit in this bin's leftover: penalize small leftovers.
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Compare post_residual to mean residual: avoid creating tiny dead space
    // relative to the fleet average.
    score += (post_residual as f64 - mean_residual).abs() * 0.3;

    // Last chance bin: strong reward to use it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: neutral-ish baseline, penalized so we prefer reusing
    // bins unless the fit is genuinely bad (score > ~0 relative to others).
    if bin_residual == bin_capacity {
        score += 150.0;
    }

    // Slight preference for tighter bins early, spreading later in stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (post_residual as f64) * (0.1 + 0.4 * (1.0 - progress));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit (low post_residual), with non-linear emphasis.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * tightness * tightness;

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: reward leaving space that exactly fits the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 55.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score += 0.15 * slack;
        } else {
            // Dead space relative to next item: penalize proportionally.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.05 * waste;
        }
    }

    // Last chance: strongly prefer using the only bin that fits, avoiding a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 45.0;
    }

    // Many open bins: discourage spreading; encourage filling existing bins.
    let crowding = open_bins_count as f64;
    score += 0.02 * crowding * tightness * 100.0;

    // Mean residual coupling: placing into a bin above-mean residual reduces fragmentation.
    if (bin_residual as f64) > mean_residual {
        score -= 6.0;
    } else {
        score += 3.0;
    }

    // Time horizon: early in stream, be pickier (penalize mediocre fits more);
    // late in stream, just close bins out.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 0.8 + 0.4 * progress;

    // New-bin candidate: only attractive when nothing fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Penalize opening a new bin; the penalty shrinks if current fits are bad.
        let best_possible_waste = if next_item_size > 0 {
            (post_residual as f64 - next_item_size as f64).abs()
        } else {
            post_residual as f64
        };
        let poor_fits = fitting_bins_count == 0
            || (post_residual as f64) > 0.5 * bin_capacity as f64;
        if poor_fits {
            score -= 25.0 + 0.1 * best_possible_waste;
        } else {
            score += 70.0 + 0.5 * crowding;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with non-linear polynomial shaping
    let mut score = pr
        + 12.0 * norm_pr * norm_pr * cap
        - 8.0 * norm_pr * norm_pr * norm_pr * cap;

    // Stream-progress coupling: later in the stream, penalize large residuals more
    let progress_coupling = 20.0 * progress * norm_pr * norm_pr * cap;
    score += progress_coupling;

    // Perfect / near-perfect fit reward (subtract)
    if pr == 0 {
        score -= 50.0;
    } else {
        score -= 30.0 * (-norm_pr * 10.0).exp();
    }

    // Lookahead: reward if next item fits the post residual
    if next_item_size > 0 {
        if (next_item_size as f64) <= pr {
            score -= 15.0 * (1.0 - (next_item_size as f64) / cap);
        } else {
            score += 5.0 * ((next_item_size as f64) - pr) / cap;
        }
    }

    // Last-chance bin reward
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Mean residual coupling: prefer bins deviating from mean residual to keep diversity
    score += 2.0 * (pr - mean_residual).abs() / cap;

    // Crowding penalty: many open bins, favor filling existing ones
    score -= 1.5 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: mod-25 classes on capacity 100.
    let class = post_residual % 25;
    // Penalize residuals in awkward classes (small nonzero remainders are dead space).
    if post_residual > 0 {
        score += match class {
            0 => -40.0,                      // perfect quarter fill: great
            10 | 20 => -15.0,                // divisible by 10: good
            5 | 15 => 5.0,                   // half-class: mediocre
            _ => 12.0,                       // awkward remainder
        };
    } else {
        score -= 100.0; // exact fit
    }

    // Integer-division threshold: residual buckets by post_residual / 25
    let bucket = post_residual / 25;
    score += bucket as f64 * 6.0;

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.5;
            // harmonic class match between next item and post residual
            if post_residual % next_item_size.max(1) == 0 {
                score -= 20.0;
            }
        } else {
            // next item cannot use this residual: penalize proportional to waste
            score += (next_item_size.min(post_residual.max(1)).min(30)) as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 45.0;
    }

    // New-bin candidate: reserve it for when fit is truly bad.
    if bin_residual == bin_capacity {
        // Opening a new bin costs ~1 bin; make it attractive only if this placement
        // would leave large waste elsewhere. Base cost:
        score += 55.0;
        // More open bins -> prefer packing into existing ones, so new bin costlier.
        score += open_bins_count as f64 * 2.0;
        // Early in stream, new bins are fine (many items still coming).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 20.0;
        // If the item would fill a fresh bin nearly exactly, new bin is great.
        if item_size % 25 == 0 {
            score -= 25.0;
        }
    }

    // Mean residual context: bins far from mean residual are less attractive targets
    // (keep a diverse residual portfolio).
    score += ((post_residual as f64 - mean_residual).abs()) * 0.15;

    // Tight-fit bonus: small post_residual relative to item size means dense packing.
    if item_size > 0 {
        let density = item_size as f64 / bin_capacity as f64;
        score -= density * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are nearly unusable
    // since future items are >= 1 and typically larger; penalize gaps that
    // fall in the "dead zone" (too small to be useful).
    let dead_threshold = 15.0f64;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 4.0;
    }

    // Reward tight fits (small post_residual) nonlinearly.
    score -= 30.0 * (-post_residual as f64 / 10.0).exp();

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Penalize leaving a gap that exactly matches nothing useful:
    // if next item can fit into post_residual, reward (lookahead synergy).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.2 * (post_residual - next_item_size) as f64;
    } else if next_item_size > 0 {
        // next item cannot use this gap: penalize proportional to gap size
        score += 0.15 * post_residual as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, prefer filling existing
    // bins over opening new ones; when few bins are open, new bins are cheap.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln() * (1.0 + progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline plus pressure penalty, plus
        // wasted-capacity accounting relative to mean residual.
        score = bin_capacity as f64 * 0.5 + pressure * 6.0 + mean_residual * 0.3;
        // Late in the stream, new bins are especially costly.
        score += progress * 20.0;
    } else {
        // Existing bin: mild bonus scaled by how full it already is.
        score -= (bin_capacity - bin_residual) as f64 * 0.1;
        // Prefer bins whose residual is below mean (consolidating fullness).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
        score -= pressure * 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fill is perfect.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        score -= 3.0 * (1.0 - gap / bin_capacity as f64).max(0.0) * 10.0;
        // Perfect 2-chain: item + next item exactly fills the bin.
        if post_residual == next_item_size {
            score -= 200.0;
        }
        // Penalize leaving a residual too small for anything useful later.
        if post_residual > 0 && post_residual < 10 {
            score += 50.0;
        }
    } else {
        // Last item: prefer tightest fit.
        score -= 100.0;
    }

    // Compare against mean residual: bins already tighter than average are
    // better targets; loose bins should absorb this item.
    if post_residual as f64 > mean_residual {
        score += 5.0;
    } else {
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (post_residual would be large dead space) or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let waste = (bin_capacity - item_size) as f64;
        // Opening a new bin is penalized by the waste it creates, softened
        // when many bins are open and the fit elsewhere is poor.
        score = waste - 150.0 * (1.0 - progress) - 0.5 * open_bins_count as f64;
        if item_size >= 80 {
            score -= 100.0; // big items: fresh bin is great
        }
        if post_residual as f64 > mean_residual + 20.0 && fitting_bins_count > 1 {
            score += 60.0; // other bins fit acceptably; don't open a new one
        }
    }

    // Mild preference for keeping many open bins busy.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Penalize large post-residual, more strongly as stream progresses
    // (dead space matters more when few items remain to fill it).
    score += (post_residual as f64 / bin_capacity as f64).powf(1.8) * 40.0 * (0.5 + progress);

    // Reward tight fits: small post_residual relative to item size.
    if item_size > 0 {
        let tightness = post_residual as f64 / item_size as f64;
        score -= 12.0 / (1.0 + tightness);
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // Reward proportional leftover after a hypothetical next placement.
            let chain_left = post_residual - next_item_size;
            score -= 15.0 - 0.15 * chain_left as f64;
        } else {
            // Next item won't fit here: penalize wasted residual relative to next item.
            score += 0.08 * (next_item_size as f64 - post_residual as f64).max(0.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Global state: when many bins are open, prefer consolidating into
    // bins whose residual is near the mean (balance residuals).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // When few bins are open early on, mildly discourage spreading to new bins.
    if open_bins_count <= 2 && bin_residual == bin_capacity {
        score += 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // relative to capacity or existing residuals are all small.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        let mean_fill = mean_residual / bin_capacity as f64;
        // Opening a new bin is attractive if it will end up nearly full
        // while existing bins have small residuals that can't help.
        score += 45.0 - 60.0 * fill_ratio * (1.0 - mean_fill) - 20.0 * progress;
    }

    // Slight preference for bins with smaller residual overall (best-fit bias).
    score += 0.03 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    // Progress-weighted dead-space penalty: grows non-linearly as stream advances
    let poly = x * x * (1.0 + progress) + x * progress * progress;
    score += 20.0 * poly;

    // Reward tight fits, more strongly later in the stream
    let tightness = 1.0 - x;
    score -= 15.0 * tightness * tightness * (0.5 + progress);

    // Penalize residuals that cannot fit the lookahead item (smooth coupling)
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let fit_gap = (x - nx).max(0.0);
        score -= 8.0 * fit_gap * (1.0 - fit_gap) * (1.0 + progress);
        let waste = (nx - x).max(0.0);
        score += 12.0 * waste * waste;
    }

    // Last-chance bin bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0 * (1.0 + progress);
    }

    // Mild penalty for spreading across many open bins
    score += (open_bins_count as f64).sqrt() * 0.5 * x;

    // Pull score toward mean residual alignment (smooth quadratic)
    score += 0.1 * (pr - mean_residual) * (pr - mean_residual) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls on "nice"
    // modular classes (multiples of small divisors) are more reusable.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Reward post-residuals divisible by common small sizes (harmonic classes mod 10/20/25).
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 6.0; }
        if post_residual % 20 == 0 { score -= 4.0; }
        if post_residual % 25 == 0 { score -= 3.0; }
        if post_residual % 50 == 0 { score -= 2.0; }
    } else {
        // Perfect fit is always excellent.
        score -= 40.0;
    }

    // Penalize tiny dead space (unusable fragments): post_residual in awkward classes.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            score -= 8.0 * (1.0 - slack as f64 / cap);
            if slack % 10 == 0 { score -= 3.0; }
        } else {
            // Next item won't fit here: mild penalty scaled by how much it overshoots.
            let over = (next_item_size - post_residual) as f64;
            score += 0.05 * over;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin, reduced late in the stream or with many open bins.
        score += 18.0 - 4.0 * (open_bins_count as f64).ln().max(0.0);
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 6.0 * (1.0 - progress);
        // If next item is large, a fresh bin is more attractive.
        if next_item_size > 0 && next_item_size > post_residual {
            score -= 5.0;
        }
    }

    // Tightness reward: bins that become nearly full are good placements.
    let fill = (cap - pr) / cap;
    score -= 10.0 * fill * fill;

    // Mean-residual coupling: prefer bins deviating below the mean residual
    // (i.e., fuller than average) to consolidate space.
    score += 0.10 * (pr - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harder than proportionally.
    let dead_threshold = 12.0f64;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 4.0;
    }
    // Perfect fit bonus
    if post_residual == 0 {
        score -= 20.0;
    }

    // Reward bins whose residual closely matches the item (tight fit)
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.3;

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: penalize opening new bins when many bins are open
    if bin_residual == bin_capacity {
        score += 10.0 + 2.0 * open_bins_count as f64;
    }

    // Lookahead: if next item fits into post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }
    // Penalize if post_residual is nonzero but too small for the next item
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 5.0;
    }

    // Mean residual coupling: prefer bins below mean residual (more filled bins)
    score += (mean_residual - bin_residual as f64) * 0.2;

    // Stream progression: early on, be more willing to open bins; later, consolidate
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: strongly reward bins where the next item also fits
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // chain fit: reward proportional to how snugly next item fits
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 + 2.0 * next_item_size as f64 - 0.3 * slack;
        } else {
            // next item won't fit here; penalize slightly by leftover dead space
            score += 0.5 * post_residual as f64;
        }
    }

    // Relative to mean residual: prefer filling below-average-residual bins tighter
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: only attractive when existing fits are poor
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 45.0;
        // more attractive late in stream or when few bins fit
        if fitting_bins_count > 0 {
            score += 20.0 * (fitting_bins_count as f64).ln().max(0.0);
        }
        // if lookahead item is large, a fresh bin is fine
        if next_item_size > 0 && next_item_size > item_size {
            score -= 15.0;
        }
        // early stream: fresh bins are cheap
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        score -= 20.0 * (1.0 - progress);
    }

    // Penalize leaving tiny unusable slivers (dead space) unless it's a perfect fit
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer minimal waste, with a mild non-linear penalty on large residuals
    score = score * (1.0 + 0.003 * post_residual as f64);

    // Perfect fit bonus: residual 0 is ideal
    if post_residual == 0 {
        score -= 50.0;
    } else {
        // Penalize dead space that nothing can use (min item size 1)
        // small residuals (< ~15) are hard to reuse
        let dead = (15.0 - post_residual as f64).max(0.0);
        score += 0.8 * dead;
    }

    // Lookahead: reward leaving space for the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            // Extra reward for near-exact pairing: post_residual close to next size
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / 50.0).max(0.0);
        } else if post_residual > 0 {
            // Penalize creating space the next item cannot use
            score += 6.0 * (1.0 - progress);
        }
    } else {
        // Last item: just minimize waste
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Many open bins: encourage consolidation into existing bins
    if open_bins_count > 3 {
        score -= 0.5 * open_bins_count as f64;
        // Align with mean residual: prefer bins whose residual is near the mean (keep balance)
        let diff = (bin_residual as f64 - mean_residual).abs();
        score += 0.15 * diff;
    } else {
        // Few open bins: allow spreading; slight penalty for tight fits
        score += 2.0;
    }

    // New-bin candidate handling: opening a fresh bin should only win when the
    // fit into existing bins is poor. Make the empty-bin call (bin_residual == capacity)
    // unattractive unless the item is large and late in the stream.
    if bin_residual == bin_capacity {
        let base_penalty = 30.0;
        let large_item_bonus = if item_size > bin_capacity / 2 { 10.0 } else { 0.0 };
        let late_bonus = 15.0 * progress;
        score += base_penalty + large_item_bonus + late_bonus;
        // If next item is also large, a fresh bin may pair well with the current item
        if next_item_size > 0 && item_size as f64 + next_item_size as f64 <= bin_capacity as f64 {
            score -= 8.0;
        }
    }

    // Global residual pressure: if mean residual across bins is low, hoard space carefully
    if mean_residual < item_size as f64 && bin_residual != bin_capacity {
        score += 5.0;
    }

    // Mild time-dependent scaling: early stream, be greedy about tight fits; late, consolidate
    score *= 1.0 + 0.2 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let t = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let is_new_bin = (bin_residual as f64 - cap).abs() < 0.5;

    // Smooth normalized fit quality: how well the item fills the residual.
    let fill = 1.0 - pr / cap;
    let fill2 = fill * fill;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on tolerate loose fits; late in stream penalize dead space quadratically.
    score += pr * pr / cap * (0.3 + 0.7 * t);

    // Reward tight fits (small post_residual relative to capacity), amplified over time.
    score -= fill2 * cap * (0.2 + 0.8 * t);

    // Lookahead coupling: bonus if the next item fits exactly into post_residual.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let gap = pr - nx;
            score -= (1.0 - gap / cap) * 8.0 * (0.5 + 0.5 * t);
        } else {
            score += (nx - pr) / cap * 4.0;
        }
    }

    // Last-chance bonus: this is the only bin that fits; strongly prefer it over new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 15.0 + 10.0 * t;
    }

    // Penalize opening a new bin when open bins could fit, especially mid/late stream.
    if is_new_bin {
        score += 6.0 + 8.0 * t * (1.0 - 1.0 / (open_bins_count as f64 + 1.0));
    }

    // Mild preference for bins below mean residual (balance residuals smoothly).
    score += (mean_residual - bin_residual as f64) * 0.05 * t;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover: leftovers divisible into nice chunks are less bad.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Penalize dead space that cannot be re-used by "harmonic" classes.
    // Class 0: leftover 0 (perfect fit) -> big reward.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Modulo classes on post_residual: multiples of 10 and 25 are highly reusable.
        let m10 = post_residual % 10;
        let m25 = post_residual % 25;
        let m5 = post_residual % 5;
        score += (m10 as f64) * 0.8 + (m5 as f64) * 0.5;
        if m25 == 0 {
            score -= 12.0;
        }
        // Integer-division thresholds: leftover that can hold a whole "half" or "quarter".
        if post_residual >= bin_capacity / 2 {
            score += 8.0; // wasting a half bin on this item is bad
        } else if post_residual >= bin_capacity / 4 {
            score += 2.0;
        }
    }

    // Reward tight fits relative to bin capacity fraction.
    let fill_fraction = item_size as f64 / cap;
    score -= fill_fraction * 10.0;

    // Lookahead coupling: if next item fits exactly in post_residual (harmonic match), reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            // next item fits: leftover remains, but modulable
            let nm = post_residual % next_item_size.max(1);
            score -= 5.0 - (nm as f64) * 0.3;
        } else {
            // next item cannot fit here: mild penalty scaled by excess
            let excess = (next_item_size - post_residual) as f64;
            score += (excess / cap) * 6.0;
        }
    } else {
        // Last item: prefer closing bins completely.
        score += pr * 0.2;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: keep it neutral-ish, slightly penalized so it's
    // chosen only when all open bins are poor fits.
    if bin_residual == bin_capacity {
        score += 20.0 + (open_bins_count as f64).sqrt() * 2.0;
        // But if stream is nearly done and mean residual is small, new bin is fine.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if mean_residual < item_size as f64 {
            score -= 25.0;
        }
        let _ = progress;
    }

    // Spread-awareness: many open bins with high mean residual -> prefer consolidating.
    score += (mean_residual - pr) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps (< next plausible item minimum ~10)
    // are nearly useless; penalize them quadratically, but reward zero residual perfectly.
    let pr = post_residual as f64;
    if post_residual == 0 {
        score -= 60.0; // perfect fit, strongly favored
    } else if post_residual < 10 {
        score += (10.0 - pr) * (10.0 - pr) * 4.0; // unusable sliver -> heavy penalty
    } else {
        // Usable leftover: mild reward proportional to how well it could host future items
        score -= pr * 0.15;
    }

    // Reward bins whose residual was already small (tight packing pressure)
    score -= (bin_capacity as f64 - bin_residual as f64) * 0.3;

    // Open-bin pressure: discourage spreading across many bins
    score += open_bins_count as f64 * 0.5;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless post_residual would be a dead sliver).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
    }

    // New-bin candidate (bin_residual == bin_capacity): its base score is 100 - item_size,
    // which is large; add mild penalty so it only wins when fits are genuinely bad,
    // but subtract slightly late in the stream to consolidate.
    if bin_residual == bin_capacity {
        score += 20.0 - (step_index as f64 / total_items.max(1) as f64) * 10.0;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter than average)
    score -= (mean_residual - bin_residual as f64).max(-50.0).min(50.0) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core archetype: 2-step lookahead matching.
    // Reward exact-ish match of post_residual with next_item_size (perfect 2-item fill).
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 12.0 * (1.0 - diff / (bin_capacity as f64)) * (next_item_size as f64 / 100.0);
        // Strong bonus for exact match
        if post_residual == next_item_size {
            score -= 8.0;
        }
        // Penalize dead space that next item cannot use
        if post_residual < next_item_size {
            score += 0.35 * post_residual as f64;
        }
    } else {
        // Last item: prefer tightest fill
        score += 5.0 * post_residual as f64 / bin_capacity as f64;
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Penalize creating small unusable slivers (dead space below min item size ~1..100 unknown; use 10 heuristic floor)
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 7.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    if bin_residual == bin_capacity {
        let crowding = mean_residual / bin_capacity as f64;
        score += 18.0 * (1.0 - crowding);
        if open_bins_count == 0 {
            score -= 25.0;
        }
        // Late in stream, prefer reusing bins
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 6.0 * progress;
    }

    // Slight penalty when many bins compete (prefer consolidation)
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.10;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let prn = pr / cap; // normalized post residual [0,1]
    let p = progress;
    let coupling = prn * prn * (1.0 - p) + prn * p * p - 2.0 * prn * prn * p * (1.0 - p);
    score += 12.0 * coupling;

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - prn;
    score -= tightness * tightness * (1.0 + 3.0 * p) * 6.0;

    // Penalize wasted space relative to mean residual of open bins
    score += 0.35 * (pr - mean_residual).abs();

    // Lookahead: bonus if next item fits the post residual
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 4.0 + 5.0 * p;
    } else if next_item_size > 0 {
        score += 1.5 * (next_item_size as f64 - pr) / cap;
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0 * (1.0 + p);
    }

    // Mild penalty for many open bins to encourage consolidation
    score += 0.05 * open_bins_count as f64 * (0.5 + p);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: which capacity-fraction band does the leftover fall in?
    let post_class = (post_residual * 4) / bin_capacity; // 0..3 bands: tiny, small, half, large
    match post_class {
        0 => score -= 12.0,              // near-perfect fit, tiny dead space
        1 => score -= 4.0,               // good fit
        2 => score += 3.0,               // half-ish leftover, moderate value
        _ => score += 8.0,               // large leftover wasted on a big item
    }

    // Exact-fill bonus (post_residual == 0) is very desirable
    if post_residual == 0 {
        score -= 25.0;
    }

    // Modulo arithmetic on post_residual: leftovers that are multiples of common
    // item sizes (10, 20, 25, 50) are reusable "harmonic" residuals.
    let harmonic = post_residual % 10 == 0 || post_residual % 20 == 0
        || post_residual % 25 == 0 || post_residual % 50 == 0;
    if harmonic {
        score -= 6.0;
    }

    // Lookahead coupling: if next item fits the post residual, this placement
    // chains nicely.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_class = ((post_residual - next_item_size) * 4) / bin_capacity;
        match chain_class {
            0 => score -= 10.0,
            1 => score -= 5.0,
            _ => score -= 2.0,
        }
        // exact chain fill
        if post_residual == next_item_size {
            score -= 8.0;
        }
    } else if next_item_size > 0 {
        // next item cannot use leftover: penalize proportionally to dead space
        score += 0.05 * (next_item_size as f64);
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // base penalty for opening a bin, reduced when many bins are open and
        // residuals are fragmented
        let mut penalty = 30.0;
        if fitting_bins_count == 0 {
            penalty -= 30.0; // nothing fits anywhere: must open
        } else if fitting_bins_count <= 2 {
            penalty += 5.0;
        }
        // if mean residual across open bins is small, opening fresh is fine
        if mean_residual < 20.0 {
            penalty -= 10.0;
        }
        // early in stream, opening bins is cheaper
        let progress = step_index as f64 / (total_items.max(1) as f64);
        penalty -= 5.0 * (1.0 - progress);
        score += penalty;
    }

    // Slight preference to fill fuller bins (tighter packing) via mean residual
    score += 0.02 * mean_residual;

    // Integer-division threshold: bins whose residual after placement is below
    // the smallest possible item (1) are perfectly closed; below 10 also great.
    if post_residual < 10 && post_residual > 0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: gaps that are unusable (too small for typical items)
    // are worse than moderately sized gaps. Treat gaps < 20 as near-dead.
    if post_residual > 0 {
        let gap = post_residual as f64;
        if gap < 20.0 {
            // steep quadratic penalty for tiny unusable gaps
            score += (20.0 - gap) * (20.0 - gap) * 0.8;
        } else if gap == 0.0 {
            // perfect fit: strong reward
            score -= 60.0;
        } else {
            // moderate gaps are fine; slight reward for larger usable leftovers
            score -= 10.0;
        }
    } else {
        // exact fill handled above when post_residual == 0
        score -= 60.0;
    }

    // Reward tight fits: fraction of residual consumed
    let tightness = if bin_residual > 0 {
        item_size as f64 / bin_residual as f64
    } else {
        1.0
    };
    score -= tightness * 25.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones
    // (the new-bin candidate has bin_residual == bin_capacity, so it gets penalized here)
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // new-bin candidate: base cost plus pressure scaled by open bins
        score += 30.0 + open_bins_count as f64 * 6.0 * (1.0 - 0.5 * progress);
    } else {
        // using an existing bin relieves pressure slightly
        score -= open_bins_count as f64 * 1.5;
    }

    // Lookahead: if the next item fits into the post residual, reward leaving
    // exactly that space (chain packing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // leftover too small for next item: mild penalty
            score += 6.0;
        }
    }

    // Mean residual coupling: prefer bins whose residual is near the mean
    // (keeps the bin pool homogeneous and predictable).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect 2-item packing
        } else if next_item_size <= post_residual {
            // next item fits; favor small leftover after that
            let after2 = post_residual - next_item_size;
            score -= 15.0 - 0.3 * after2 as f64;
        } else {
            // next item cannot use this residual: penalize proportional waste
            let waste = (next_item_size - post_residual) as f64;
            score += 0.4 * waste;
        }
    }

    // Reward residual closeness to mean (keeps bins balanced)
    score += 0.15 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize creating tiny dead space (unusable slivers)
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Prefer tighter fits as the stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    // New-bin candidate: neutral baseline, mildly discouraged unless residuals are large
    if bin_residual == bin_capacity {
        score += 10.0 + 0.2 * mean_residual;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Reward tight fits: fraction of bin consumed by this placement
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= 8.0 * fill_frac;

    // Penalize small dead space that no typical item can use
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // next item fits: mildly reward leaving usable space
            score -= 0.4 * (post_residual as f64 - next_item_size as f64).sqrt();
        } else {
            // next item won't fit here: penalize leaving awkward large-ish residual
            score += 0.25 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Global state: many open bins -> prefer filling existing ones, discourage new bins
    if bin_residual == bin_capacity {
        // new-bin candidate
        score += 30.0 + 3.0 * open_bins_count as f64;
        // but early in stream, new bins are cheap
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 35.0 * (1.0 - progress);
        // if no open bin fits well, new bin is fine
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    // Prefer bins whose residual is close to the mean residual (balance fragmentation)
    score += 0.15 * (bin_residual as f64 - mean_residual).abs();

    // Slight preference for fuller bins (smaller residual) overall
    score += 0.05 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let item = item_size as f64 / cap;

    // Base: prefer low post-residual, with non-linear polynomial coupling to progress.
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Smooth quadratic penalty on tiny unusable leftovers (dead space).
    let dead = (norm_pr - 0.10).max(0.0);
    score += 25.0 * dead * dead * cap;

    // Reward tight fits (small post_residual relative to item size) more as stream advances.
    score -= 40.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * item * (0.5 + progress);

    // Lookahead: bonus if next item fits the resulting residual smoothly.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let snug = 1.0 - (pr - next_item_size as f64) / cap;
        score -= 12.0 * snug * (0.5 + progress);
    } else if next_item_size > 0 {
        // Penalize if post-residual can't host next item, scaled by how far off.
        let gap = (next_item_size as f64 - pr) / cap;
        score += 8.0 * gap * gap * cap;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Mild penalty when many bins are open and residual deviates from mean (fragmentation).
    let dev = pr as f64 - mean_residual;
    score += 0.05 * dev * dev / cap;

    // New-bin candidate: neutral-ish baseline, slightly discouraged late in stream
    // unless it would be a near-perfect fresh start for large items.
    if bin_residual == bin_capacity {
        score = 60.0 - 20.0 * progress + 30.0 * item * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: split into residue classes mod 10 and capacity fractions
    let cap = bin_capacity as f64;
    let post_f = post_residual as f64;
    let frac = post_f / cap; // fraction of capacity left after placement

    // Penalize dead space: residuals that no item (min size 10) can use are worthless
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Harmonic class bonus: residuals that are exact capacity fractions are highly reusable
    let harmonic_classes: [u32; 12] = [0, 10, 20, 25, 30, 40, 50, 60, 70, 75, 80, 90];
    let mut harmonic = false;
    for &h in harmonic_classes.iter() {
        if post_residual == h {
            harmonic = true;
            break;
        }
    }
    if harmonic {
        score -= 12.0;
    }

    // Modulo-10 class coupling: residual divisible by 10 pairs well with typical item grids
    if post_residual % 10 == 0 {
        score -= 4.0;
    } else if post_residual % 5 == 0 {
        score -= 2.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
            // exact division: next item would fill bin perfectly
            if post_residual % next_item_size == 0 {
                score -= 6.0;
            }
        } else {
            // next item won't fit here: this residual becomes dead space for the lookahead
            // penalize proportionally to how much residual is wasted
            if post_residual < next_item_size {
                score += (next_item_size - post_residual) as f64 * 0.5;
            }
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only prefer a fresh bin if current bin would leave a large unusable gap
    if bin_residual == bin_capacity {
        // base new-bin score: capacity minus expected fill; discourage unless others score badly
        score = cap * 0.75;
        if next_item_size > 0 && next_item_size > item_size {
            // if next item is big, a fresh bin is more attractive
            score -= (next_item_size as f64) * 0.15;
        }
        // as stream progresses, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 15.0;
        // many open bins: discourage opening another
        score += open_bins_count as f64 * 1.5;
    }

    // Tight fit reward: item fills most of the bin
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fill_ratio > 0.9 {
        score -= 10.0;
    } else if fill_ratio > 0.7 {
        score -= 5.0;
    }

    // Prefer bins below mean residual (keeps residuals balanced / large bins for big items)
    if post_f < mean_residual {
        score -= 2.0;
    } else {
        score += 1.0;
    }

    // Integer division threshold: large post_residual chunks (>= half capacity) are valuable
    if post_residual >= bin_capacity / 2 {
        score -= 5.0;
    } else if post_residual >= bin_capacity / 4 {
        score -= 2.0;
    }

    // Small global regularization by fraction
    score += (1.0 - frac) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the minimum item
    // (1..10) are nearly worthless, penalize them hard.
    if post_residual < 10 {
        score += 60.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward placements that still leave room for the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Leaves a gap the next item cannot use: dead space risk.
        score += 8.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage new bins when many bins are open.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 15.0 + 2.0 * open_bins_count as f64;
        // But a new bin is fine if the item fits poorly everywhere else
        // (large item, tight stream).
        if item_size > 60 {
            score -= 10.0;
        }
        // Early in the stream, opening bins is cheaper.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - progress);
    }

    // Prefer bins whose residual deviates downward from the mean
    // (consolidate space into fewer, fuller bins).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Slight preference for filling larger-residual bins when item is small.
    if item_size <= 20 {
        score -= 0.2 * (bin_residual as f64 - mean_residual);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item -> huge reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near match: next item fits with small leftover.
    else if next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 / (1.0 + slack / 10.0);
    }
    // Next item does NOT fit in post_residual: penalize proportionally to wasted potential,
    // but less harsh if post_residual is tiny (dead space is small anyway).
    else if next_item_size > 0 {
        let dead = post_residual as f64;
        score += dead * 0.5;
    }

    // Reward bins tighter than the mean residual (filling crowded bins first).
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate (empty bin): only attractive if current fit is bad.
    if bin_residual == bin_capacity {
        let bad_fit = if next_item_size > 0 && post_residual >= next_item_size { 0.0 } else { 1.0 };
        score += 15.0 - 30.0 * bad_fit;
    }

    // Mild late-stream conservatism: keep residuals usable as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (post_residual near 0).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that is too small to host typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Lookahead: if next item fits the post-residual exactly or well, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            let fit_ratio = next_item_size as f64 / post_residual as f64;
            if fit_ratio > 0.7 {
                score -= 10.0 * fit_ratio;
            } else {
                score += 3.0 * (1.0 - fit_ratio);
            }
        } else {
            // next item won't fit here: mild penalty proportional to wasted potential
            score += 2.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 {
        score -= 15.0;
        if post_residual > 0 && post_residual < 10 {
            score -= 8.0; // still worth consuming tiny residual to avoid new bin
        }
    }

    // Global pressure: many open bins -> consolidate; few open bins -> allow new bins.
    let pressure = (open_bins_count as f64) / (1.0 + (total_items as f64) * 0.05);
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive when few bins open or mean residuals are low.
        let mut new_bin_score = 0.0;
        new_bin_score += pressure * 20.0;
        if mean_residual < item_size as f64 {
            new_bin_score -= 8.0;
        }
        // Slightly penalize new bins early in stream to encourage consolidation.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        new_bin_score += 5.0 * (1.0 - progress);
        // If item fits an open bin with good tightness, discourage new bin.
        if post_residual == 0 {
            new_bin_score += 30.0;
        }
        score += new_bin_score;
    } else {
        // Existing bin: prefer bins with residual close to item size (minimize waste).
        let waste = (bin_residual - item_size) as f64;
        score += 0.05 * waste;
        // Prefer bins below mean residual (fill the emptiest-but-fitting bins).
        if (bin_residual as f64) > mean_residual {
            score += 2.0;
        } else {
            score -= 1.5;
        }
    }

    // Time horizon: late in the stream, be greedier about tight fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 6.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    let mut score = pr;

    // Smooth non-linear coupling: reward tight fits quadratically.
    let tightness = 1.0 - pr / cap; // 1.0 = perfect fit
    score -= 2.5 * tightness * tightness * (1.0 + progress);

    // Penalize residuals that are small-but-unusable (dead space) via cubic term.
    let dead = (pr / cap).powf(3.0);
    score += 1.8 * dead * (1.0 - 0.5 * progress);

    // Last-chance bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // Lookahead: reward leaving space that the next item can use.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let usable = if pr >= nxt { 1.0 - (pr - nxt) / cap } else { 0.0 };
        score -= 1.5 * usable * usable;
        // Penalize leaving a residual just barely below the next item's size.
        if pr > 0.0 && pr < nxt {
            score += 1.2 * (1.0 - pr / nxt);
        }
    }

    // New-bin candidate handling: only open a new bin when existing fits are poor.
    if bin_residual == bin_capacity {
        let congestion = open_bins_count as f64;
        score += 4.0 + 0.3 * congestion + 3.0 * (1.0 - progress);
        // If this bin is the only fitting option, opening a new bin is natural.
        if fitting_bins_count == 1 {
            score -= 5.0;
        }
    } else {
        // Mild preference for fuller bins over emptier ones among open bins.
        score += 0.5 * (mean_residual - pr).abs() / cap;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: reward tight fits (low post_residual).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 25.0 * fit_ratio * fit_ratio;

    // Harmonic class of the post residual: dead space that is a small
    // remainder modulo common item sizes is more likely to be reusable.
    let mut class_penalty = 0.0;
    for &m in &[10u32, 20, 25, 33, 50] {
        let r = post_residual % m;
        if r == 0 && post_residual > 0 {
            class_penalty -= 6.0; // exact multiple: likely fillable later
        } else if r < 10 && r > 0 {
            class_penalty += 4.0; // tiny unusable sliver
        }
    }
    score += class_penalty;

    // Lookahead: if the next item fits exactly in the post residual, strongly favor.
    if next_item_size > 0 && next_item_size <= post_residual {
        if next_item_size == post_residual {
            score -= 30.0;
        } else {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        }
    } else if next_item_size > post_residual && post_residual < 10 {
        // dead space created that nothing (min size 10... but sizes >=1) can use
        score += 8.0;
    }

    // Last chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the current fit is poor and many bins are open with slack.
    if bin_residual == bin_capacity {
        // neutral baseline; penalize opening new bins early or when mean residual is high
        score += 12.0 * (mean_residual / bin_capacity as f64);
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - progress) * (open_bins_count as f64).ln().max(0.0);
        // a new bin is great if the item is huge relative to remaining capacity needs
        if item_size * 2 >= bin_capacity {
            score -= 5.0;
        }
    }

    // Mild pressure to consolidate: fewer open bins -> prefer existing bins.
    score += (open_bins_count as f64).ln() * 0.5;

    // Prefer placing into bins whose residual is below mean (filling laggards).
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64) * 5.0;

    // Integer-division threshold: bins whose residual / 10 class is small get priority.
    let decile = post_residual / 10;
    score -= match decile {
        0 => 10.0,
        1 => 6.0,
        2 => 3.0,
        _ => 0.0,
    };

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftover gaps (unusable by typical items) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 6.0;
    }
    // Perfect fit gets a big reward.
    if post_residual == 0 {
        score -= 25.0;
    }
    // Reward tight fits relative to bin size.
    score -= (item_size as f64 / bin_capacity as f64) * 8.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is good.
    score += open_bins_count as f64 * 0.4;

    // Lookahead: if next item fits into the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    }
    // If post-residual is just barely below the next item, penalize (near-miss dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 4.0;
    }

    // New-bin candidate: attractive early in the stream or when mean residual is small;
    // discouraged when existing bins already have large residuals that could absorb the item.
    if bin_residual == bin_capacity {
        score -= 5.0 * (1.0 - step_index as f64 / total_items.max(1) as f64);
        score -= (mean_residual / bin_capacity as f64) * -3.0;
        score += 10.0;
        // If no other bin fits, opening a new bin is fine.
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    // Mean residual coupling: prefer bins deviating below the mean residual (fill the fullest bins).
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-exact fits (small dead space)
    if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.3 * (next_item_size as f64);
        // Extra reward when post_residual minus next item is tiny (chained exact fit)
        let chained = post_residual - next_item_size;
        if chained <= 5 {
            score -= 20.0;
        }
    } else if next_item_size > 0 {
        // Penalize leaving dead space that next item can't use
        score += 8.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));
    }

    // Penalize deviating far from mean residual (keep residual profile balanced)
    score += 0.5 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: strong bonus to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin is a good fit
    if bin_residual == bin_capacity {
        score += 18.0;
        if post_residual as f64 > mean_residual {
            score += 10.0;
        }
    }

    // Late in stream, be more conservative: prefer filling existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 20.0 * progress;
    } else {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero is good; penalize medium dead space.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    if post_residual == 0 {
        score -= 60.0; // perfect fit
    } else if post_residual < 10 {
        score -= 30.0;
    } else {
        // penalize residuals that are unlikely to be usable later (typical item sizes)
        let waste_risk = (post / cap).powi(2) * 40.0;
        score += waste_risk;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
        if post_residual > 50 {
            score += 25.0; // terrible fit: maybe better to open new bin
        }
    }

    // New-bin candidate handling: empty bin should only win when fits are poor.
    if bin_residual == bin_capacity {
        score += 70.0;
        if post_residual > 40 {
            score -= 20.0; // large item: new bin is natural
        }
        // late in stream, fewer open bins => consolidation preferred
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += (1.0 - progress) * 15.0;
    }

    // Lookahead: does the next item fit in the post residual?
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if next_item_size <= post_residual {
            // next item fits exactly-ish: reward leaving a matching gap
            let gap_match = 1.0 - ((post - nx) / cap).abs();
            score -= 12.0 + 10.0 * gap_match;
        } else {
            // next item won't fit here; mildly penalize hogging space
            score += 5.0 * (nx / cap);
        }
    }

    // Global state coupling: many open bins with low mean residual => consolidate.
    if open_bins_count > 2 {
        let consolidation = (mean_residual / cap) * (open_bins_count as f64).ln();
        score -= consolidation * 6.0;
    }

    // Prefer bins whose residual is close to item size (best-fit flavor).
    let tightness = (bin_residual as f64 - item_size as f64) / cap;
    score += tightness * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early: mild tightening (favor tight fits). Late: strong tightening since
    // residual dead space late in the stream is less recoverable.
    let pr_norm = pr / cap;
    let poly = pr_norm * pr_norm * (1.0 - progress) + pr_norm * pr_norm * pr_norm * progress;
    score += 12.0 * poly;

    // Reward near-perfect fits (post_residual small) with smooth decay.
    let tightness = (1.0 - pr_norm).powi(3);
    score -= 8.0 * tightness;

    // Lookahead: penalize residuals that neither fit nor nearly fit next item.
    if next_item_size > 0 && post_residual > 0 {
        let ns = next_item_size as f64;
        if pr >= ns {
            let slack = (pr - ns) / cap;
            score -= 4.0 * (1.0 - slack * slack);
        } else {
            let gap = (ns - pr) / cap;
            score += 6.0 * gap * gap;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (1.0 - pr_norm);
    }

    // New-bin candidate: penalize, scaled by how many open bins exist and progress.
    if bin_residual == bin_capacity {
        score += 10.0 + 0.5 * open_bins_count as f64 + 8.0 * progress;
    }

    // Slight penalty when this bin's residual deviates from the mean (fragmentation).
    score += 0.05 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into capacity fractions.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap; // 0..1

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize "dead" residuals that no plausible item (1..=100) can use well.
        // Residual classes: tiny (<=5) is nearly dead; mid residuals (30..70) are reusable.
        if post_residual <= 5 {
            score += 20.0; // small dead space, but at least bin is nearly full
        } else if post_residual <= 20 {
            score += 5.0;
        } else if post_residual <= 50 {
            score -= 10.0; // highly reusable band
        } else {
            score += 8.0; // large leftover = wasteful placement
        }

        // Modulo-10 harmonic class: residuals that are multiples of 10 align with
        // typical integer item sizes, making them more usable.
        if post_residual % 10 == 0 {
            score -= 6.0;
        } else if post_residual % 5 == 0 {
            score -= 3.0;
        }

        // Lookahead coupling: reward if next item fits exactly or well in post_residual.
        if next_item_size > 0 {
            if next_item_size == post_residual {
                score -= 200.0; // perfect chaining
            } else if next_item_size < post_residual {
                let nxt_frac = next_item_size as f64 / post;
                if nxt_frac > 0.8 {
                    score -= 40.0; // near-perfect chain
                } else if nxt_frac > 0.4 {
                    score -= 15.0;
                }
            } else {
                // next item cannot fit here: leftover becomes single-item dead space risk
                score += 12.0;
            }
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0 + 0.5 * post;
    }

    // New-bin candidate handling: neutral baseline with slight preference when
    // open bins are collectively full or the fit here is bad.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = 55.0;
        // Cheaper to open a new bin early in the stream (more items to come,
        // better long-run packing) and when few bins are open.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 25.0 * (1.0 - progress);
        score -= 2.0 * (open_bins_count.min(20) as f64);
        // If mean residual across open bins is small, open bins are congested:
        // opening a fresh bin is more attractive.
        score -= (mean_residual / cap).max(0.0) * 20.0;
        // If next item is large and this item leaves a bad residual, new bin helps.
        if next_item_size >= 60 && post_residual < next_item_size as u32 {
            score -= 15.0;
        }
    }

    // Mild global regularization toward tighter bins overall.
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps after placement.
    // A residual gap is "dead" if it is too small to hold any plausible future item
    // (min item size 1, but practically gaps below ~10 are nearly useless).
    if post_residual > 0 {
        let gap = post_residual as f64;
        if gap < 10.0 {
            score += (10.0 - gap) * 6.0; // tiny slivers are heavily penalized
        } else if gap < 20.0 {
            score += (20.0 - gap) * 2.0;
        }
        // Perfect fit bonus: zero post residual is ideal.
        if post_residual == 0 {
            score -= 15.0;
        }
    } else {
        score -= 15.0;
    }

    // Lookahead coupling: reward if the post residual exactly accommodates the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 12.0;
        } else if post_residual < next_item_size && post_residual > 0 {
            score += (next_item_size as f64 - post_residual as f64) * 1.5;
        }
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // Open-bin pressure: discourage spreading across many open bins when
    // open_bins_count is high; encourage filling existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.4 + 0.6 * progress);
    score += pressure * (post_residual as f64 / bin_capacity as f64);

    // Deviation from mean residual: prefer bins whose residual is below average
    // (i.e., tighter bins) to consolidate space.
    score += (post_residual as f64 - mean_residual).max(0.0) * 0.8;

    // New-bin candidate handling: only prefer a fresh bin when no open bin gives
    // a good fit (post_residual small). Empty-bin candidate gets a base penalty
    // that grows with open_bins_count.
    if bin_residual == bin_capacity {
        score += 5.0 + open_bins_count as f64 * 1.2;
        // But if item is large relative to capacity, opening fresh is less bad.
        score -= (item_size as f64 / bin_capacity as f64) * 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit relative to bin capacity
    score += (post_residual as f64 / bin_capacity as f64) * 30.0;

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 100.0; // perfect chain: next item closes this bin
        } else if next_item_size <= post_residual {
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - chain_waste / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize residual that is too small to be useful
            let dead = (next_item_size - post_residual) as f64;
            score += 0.5 * dead;
        }
    }

    // Reward residual close to mean_residual (keep bins homogeneous, easier future packing)
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count > 0 { 1.0 } else { 0.0 };
        score += 60.0 * pressure;
        // late in stream, avoid opening unnecessary bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
    }

    // Slight penalty when many bins open: encourage consolidation
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual == 0 is perfect.
    if post_residual == 0 {
        score -= 50.0;
    } else {
        // Penalize residual that is small-but-unusable relative to future items.
        let tightness = (post_residual as f64) / (bin_capacity as f64);
        score += tightness * tightness * 20.0;
    }

    // Lookahead: if next item fits exactly in the post-residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 - slack * 0.3;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Dead space for the lookahead item: penalize.
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Prefer fuller bins when many bins are open (consolidation pressure).
    let fill_ratio = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
    score -= fill_ratio * 10.0 * (open_bins_count.min(50) as f64 / 50.0);

    // Early in stream: be pickier about creating fragmented residuals.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * (post_residual as f64) * 0.15;

    // Compare against mean residual: bins with much more space than average
    // should be saved for larger items.
    if (bin_residual as f64) > mean_residual + 25.0 {
        score += 6.0;
    } else if (bin_residual as f64) < mean_residual - 10.0 {
        score -= 4.0;
    }

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 0.0 } else { (post_residual as f64) + 40.0 };
        score = 100.0 + desperation - (1.0 - progress) * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let pr = post / cap;

    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, tolerate slack (favor filling many bins); later, punish slack.
    let slack_weight = 0.35 + 1.65 * progress * progress;
    score += slack_weight * pr * cap * (0.5 + 0.5 * pr);

    // Dead-space penalty: post residuals too small for typical items are worthless.
    let dead = (post_residual < 10) as i32 as f64;
    score += dead * (18.0 + 22.0 * progress);

    // Lookahead coupling: reward residual that can host the next item,
    // penalize residuals that waste space next_item_size cannot use.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if post_residual >= next_item_size {
            score -= (n / cap) * (12.0 + 18.0 * (1.0 - progress));
        } else {
            score += (n / cap) * (8.0 + 14.0 * progress);
        }
    }

    // Last-chance bonus: sole fitting bin should be strongly preferred.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0 + 20.0 * progress;
    }

    // Contextual terms: many open bins with high mean residual -> prefer
    // consolidating into bins below the mean residual (tighter bins).
    let tightness = (mean_residual - post) / cap.max(1.0);
    score -= tightness * (10.0 + 10.0 * open_bins_count as f64 / (open_bins_count as f64 + 4.0));

    // New-bin candidate: make empty-bin opening moderately unattractive
    // unless residual accounting already favors it.
    if bin_residual == bin_capacity {
        score += 6.0 + 30.0 * progress * (1.0 - 1.0 / (1.0 + open_bins_count as f64 * 0.1));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into small
    // "dead" classes (residual < smallest item) are wasted; penalize strongly.
    let small_item_floor = 10u32.min(bin_capacity);
    if post_residual < small_item_floor {
        score += 40.0; // unusable dead space
    }

    // Perfect fit reward: harmonic class 0 (post_residual % 10 == 0)
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 12.0;
    } else if post_residual % 5 == 0 && post_residual > 0 {
        score -= 5.0;
    }

    // Integer-division threshold classes on post_residual relative to capacity
    let frac = post_residual as f64 / cap;
    if frac < 0.2 {
        score += 8.0; // nearly-full bin: good, keep it low-ish but dead-space risk
    } else if frac < 0.5 {
        score -= 3.0; // sweet-spot residual
    } else if frac > 0.85 {
        score += 4.0; // barely used bin: wasteful placement
    }

    // Lookahead coupling: can next item also fit here afterwards?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // harmonic match: next item's class aligns with remaining residual
            if post_residual % next_item_size.max(1) == 0 {
                score -= 15.0;
            } else {
                score -= 6.0;
            }
        } else {
            // next item won't fit: this bin becomes dead for lookahead
            score += 10.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it moderately attractive only when open bins are
    // fragmented (high mean residual spread) or few bins exist.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = cap * 0.45 + fragmentation * 0.3 - progress * 5.0 + open_bins_count as f64 * 0.2;
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 20.0; // next item huge: fresh bin sensible
        }
    }

    // Mild pressure toward tightly packed bins as stream progresses
    score -= (1.0 - frac) * (step_index as f64 / total_items.max(1) as f64) * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space (gaps too small for the smallest plausible item).
    let min_item = 1.0f64;
    if post_residual > 0 && (post_residual as f64) < min_item * 8.0 {
        score += 40.0;
    }

    // Reward tight fits (small post_residual relative to item).
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * tightness * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Pressure against opening new bins when many are already open.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 10.0 + 3.0 * open_bins_count as f64;
    }

    // Lookahead: prefer bins whose post_residual can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 15.0;
        }
    }

    // Mild preference for bins with below-average residual (concentrate filling).
    if !is_new_bin {
        score += 0.15 * ((bin_residual as f64) - mean_residual);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits snugly after this one
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack_after_next = post_residual - next_item_size;
        // Reward tight two-item packing
        score -= (post_residual as f64) * 0.5
            - (slack_after_next as f64) * 0.3;
        // Extra reward for near-perfect 2-item fill
        if slack_after_next <= 5 {
            score -= 10.0;
        }
    } else if next_item_size > post_residual {
        // Next item won't fit here after placement: penalize dead space
        score += (post_residual as f64) * 0.2;
    }

    // Penalize large post_residual relative to mean residual (wasteful placement)
    score += (post_residual as f64 - mean_residual).max(0.0) * 0.4;
    // Reward bins that are tighter than average
    score -= (mean_residual - post_residual as f64).max(0.0) * 0.1;

    // Last-chance bonus: if this is the only bin that can fit the item, use it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are poorly usable
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 8.0
            + progress * 4.0
            + (open_bins_count as f64) * 0.5;
        // If next item is large and won't combine with item here, new bin less attractive
        if next_item_size > 0 && item_size + next_item_size > bin_capacity {
            score += 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more than linearly.
    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tight * tight;

    // Penalize dead space that cannot fit the next item (lookahead-aware).
    if next_item_size > 0 && post_residual < next_item_size {
        score += 8.0 + 0.15 * (next_item_size - post_residual) as f64;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Bonus: this bin can also host the next item.
        score -= 6.0;
    }

    // Last-chance bonus: only one fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // Time-dependent aggressiveness: early on, prefer filling existing bins
    // loosely to keep options; late, maximize packing density.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * t * tight;

    // Global state coupling: many open bins with high mean residual
    // -> favor consolidating into existing bins.
    if open_bins_count > 0 {
        let pressure = mean_residual / (bin_capacity as f64);
        score -= 4.0 * pressure * (open_bins_count as f64).ln();
    }

    // New-bin candidate handling: make empty bins slightly unattractive
    // unless residual space of open bins is truly unusable.
    if bin_residual == bin_capacity {
        score += 14.0 + 3.0 * (open_bins_count as f64).sqrt();
        // If no other bin fits well (large item), allow new bin more readily.
        if fitting_bins_count <= 1 {
            score -= 18.0;
        }
    }

    // Slight penalty for leaving residuals in the awkward 1..=9 dead zone.
    if post_residual >= 1 && post_residual <= 9 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Smooth non-linear coupling of post_residual with stream progress
    let mut score = pr_norm * (1.0 + progress * pr_norm);

    // Polynomial shaping of dead-space penalty: small residuals are wasteful
    let dead = pr_norm * pr_norm * pr_norm;
    score += dead * (0.5 + 0.5 * progress);

    // Reward tight fits (low post residual) more strongly as stream progresses
    score -= (1.0 - pr_norm).powi(3) * (1.0 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 2.0;
    }

    // Lookahead: if next item fits the post residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 0.5 * (1.0 - pr / cap);
    } else if next_item_size > 0 && (next_item_size as f64) > pr {
        score += 0.3 * progress;
    }

    // Penalize bins far from mean residual (prefer balanced residual distribution)
    let dev = (pr - mean_residual) / cap;
    score += 0.25 * dev * dev;

    // Mild penalty for opening new bins when many bins are already open
    if bin_residual == bin_capacity {
        score += 0.8 + 0.5 * (open_bins_count as f64).ln();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual mod capacity fraction bands.
    let frac = post_residual as f64 / bin_capacity as f64;
    let class = (post_residual / 10) % 10; // decile class 0..9

    // Penalize awkward residual classes (dead space zones).
    match class {
        1 | 2 => score += 12.0,   // tiny unusable slivers
        3 => score += 4.0,
        4 | 5 | 6 => score -= 3.0, // mid zone usable by mid items
        7 | 8 => score -= 6.0,     // large usable space, good
        _ => {}
    }

    // Tight fit reward: post_residual small but not sliver-like.
    if post_residual > 0 && post_residual <= 8 {
        score -= 8.0;
    }

    // Lookahead coupling: if next item fits post_residual, reward strongly.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0 + (post_residual - next_item_size) as f64 * 0.15;
        // harmonic alignment: next item leaves another good class
        let nres = post_residual - next_item_size;
        if (nres / 10) % 10 >= 7 || nres == 0 {
            score -= 4.0;
        }
    } else if next_item_size > 0 {
        // next item won't fit here: slight penalty for blocking
        score += 2.0;
        if post_residual < 10 {
            score += 3.0; // creates dead space for the lookahead
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate handling: fresh empty bin gets neutral baseline.
    if bin_residual == bin_capacity {
        score = 55.0
            + (open_bins_count as f64) * 1.5
            - (step_index as f64 / total_items.max(1) as f64) * 5.0
            - mean_residual * 0.1;
        // open new bin if item is large and no tight fit exists
        if item_size >= 50 && mean_residual < item_size as f64 {
            score -= 8.0;
        }
    }

    // Mild preference for filling fuller bins as stream progresses.
    score -= frac * 5.0;
    score -= (mean_residual - post_residual as f64).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // tiny dead space is nearly worthless
    } else if post_residual == 0 {
        score -= 25.0; // perfect fit: zero waste
    }

    // Reward filling bins tightly relative to their current residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio;

    // Open-bin pressure: prefer reusing bins when many are open,
    // but allow opening new bins early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (1.0 - 0.5 * progress);
    if bin_residual != bin_capacity {
        score -= 4.0 * pressure.min(20.0);
    } else {
        // New-bin candidate: only attractive when current bin fits are poor.
        score += 15.0 + mean_residual * 0.2;
        // Lookahead: opening a new bin is good if next item also needs space
        if next_item_size > 0 && next_item_size > post_residual.min(100) as u32 {
            score -= 10.0;
        }
    }

    // Last-chance bin: strongly favor it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Penalize leaving a gap that exactly misses the next item slightly.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0; // gap remains usable for the lookahead item
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: strongly reward leaving zero residual
    if post_residual == 0 {
        score -= 60.0;
    }

    // 2-step lookahead: if next item exactly fits the post residual, big bonus
    if next_item_size > 0 && post_residual > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += diff * 0.9;
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // Penalize if next item cannot fit into post residual (dead space chain)
        if next_item_size > post_residual {
            score += (next_item_size - post_residual) as f64 * 0.35;
        }
    }

    // Tight-fit reward relative to item size
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= tightness * 8.0;

    // Compare residual against mean residual across open bins
    score += (bin_residual as f64 - mean_residual) * 0.25;

    // Last chance bin: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fits are poor
    if bin_residual == bin_capacity {
        score += 15.0;
        // But if lookahead matches a fresh bin well, soften the penalty
        if next_item_size > 0 && (bin_capacity as i64 - next_item_size as i64).abs() <= 5 {
            score -= 20.0;
        }
        // Late in stream, prefer closing out open bins over opening new ones
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Penalize creating small unusable residuals (below min item size 1 handled generically)
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: post_residual near zero is ideal.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 45.0 * tightness * tightness;

    // Penalize dead space that no plausible future item can use.
    if post_residual > 0 {
        let dead = (post_residual as f64 / bin_capacity as f64).powf(2.2);
        score += 30.0 * dead;
    }

    // Lookahead coupling: reward if next item fits the post residual well.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack_after_next = post_residual - next_item_size;
            score -= 18.0 * (1.0 - slack_after_next as f64 / bin_capacity as f64);
        } else {
            score += 12.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Many fitting bins: mild penalty to avoid fragmentation across bins.
    if fitting_bins_count > 1 {
        score += 2.5 * (fitting_bins_count as f64 - 1.0).sqrt();
    }

    // Time horizon: early in stream, be pickier about low post residuals;
    // late in stream, just pack tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * tightness;

    // Global state coupling: if mean residual is high, tolerate looser fits
    // to consolidate; if mean residual is low, be frugal.
    let mr = mean_residual / bin_capacity as f64;
    score += 8.0 * (mr - tightness).abs();

    // New-bin candidate: opening a bin is only attractive when open bins are
    // very full on average or the item is large with no good alternative.
    if bin_residual == bin_capacity && bin_capacity > 0 {
        let avg_fullness = 1.0 - mr;
        let pressure = avg_fullness * (open_bins_count as f64).ln_1p();
        let big_item = item_size as f64 / bin_capacity as f64;
        score += 40.0 - 22.0 * pressure - 15.0 * big_item;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
    }

    // Slight bonus for bins already partially used (avoid bin sprawl).
    if bin_residual < bin_capacity {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let norm_pr = pr / cap;

    // Base: raw post residual (prefer tight fits)
    let mut score = pr;

    // Smooth polynomial coupling of post residual with stream progress:
    // early on, tolerate residual waste; late in stream, penalize it more.
    let progress_weight = 1.0 + 2.0 * progress * (1.0 - 0.5 * progress);
    score += progress_weight * 8.0 * norm_pr * norm_pr;

    // Non-linear interaction: residual squared vs mean residual (relative crowding)
    let mean_norm = mean_residual / cap;
    score += 6.0 * norm_pr * (1.0 - mean_norm) * (1.0 - mean_norm);

    // Reward tightness smoothly: small post residual gets extra discount
    let tightness = (1.0 - norm_pr).powi(3);
    score -= 10.0 * tightness;

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // mild penalty scaled by number of alternatives, smooth
        score += 2.0 * ((fitting_bins_count as f64).ln().max(0.0));
    }

    // Lookahead coupling: if next item fits in post residual, reward; else penalize
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if next <= pr {
            let fit_quality = 1.0 - (pr - next) / cap;
            score -= 5.0 * fit_quality * fit_quality;
        } else {
            let gap = (next - pr) / cap;
            score += 4.0 * gap * gap;
        }
    }

    // Prefer using existing bins over opening new ones, smoothly with open count
    if bin_residual as f64 == cap {
        score += 15.0 + 1.5 * (open_bins_count as f64).sqrt();
    } else {
        score -= 3.0;
    }

    // New-bin candidate penalty grows smoothly with progress
    if bin_residual as f64 == cap {
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod 10 and integer-division tiers.
    let residue = (post_residual % 10) as f64;
    let tier = (post_residual / 10) as f64; // integer division: 0..10 tiers

    // Small residues are good (near-perfect fill) -> reward.
    score -= 12.0 * (1.0 - residue / 10.0);

    // Tier reward: lower tier (less leftover) is better, but very low tier (<2)
    // dead space is heavily penalized since few items can use it.
    score += 2.0 * tier;
    if post_residual < 10 {
        score += 15.0; // unusable dead space
    } else if post_residual <= 20 {
        score += 4.0;
    }

    // Harmonic coupling: does next_item_size harmonize with post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits here exactly or with small remainder -> strong reward
            let next_res = post_residual - next_item_size;
            score -= 18.0 * (next_res as f64) / 100.0;
            if next_res % 10 == 0 {
                score -= 10.0; // perfect harmonic class match
            }
        } else {
            // next item cannot follow into this bin's remainder
            score += 6.0 + (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: avoid opening a new bin when this is the only fit.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: prefer new bin only when open bins are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Penalize new bin mildly; escalate if mean residual shows fragmentation.
        score = 55.0 + 20.0 * (1.0 - progress) + (mean_residual / bin_capacity as f64) * 25.0;
        if open_bins_count == 0 {
            score = 0.0; // must open first bin
        }
        // If next item is large, a fresh bin is attractive.
        if next_item_size > 60 {
            score -= 15.0;
        }
    }

    // Slight preference for tighter bins when many are open.
    score += (open_bins_count as f64) * (post_residual as f64) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space (post_residual in [1..=9])
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Perfect fit bonus
    if post_residual == 0 {
        score -= 40.0;
    }

    // Favor bins whose residual exactly accommodates the lookahead item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 6.0;
    }

    // Last-chance bin: strong preference to use it before opening new bins
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, avoid wasting capacity on tight fits
    let pressure = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
    score += pressure * (post_residual as f64 / bin_capacity as f64) * 20.0;

    // Prefer filling bins with larger residual early in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * (bin_residual as f64 - item_size as f64) * 0.1;

    // New-bin candidate: penalize mildly so it's chosen only when fits are bad
    if bin_residual == bin_capacity {
        score += 30.0 + mean_residual * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step chain: this item leaves exactly the space the next item needs.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Next item fits into the resulting residual with some slack: still good.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + (next_item_size as f64 / post_residual as f64) * 8.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space: residual too small for the next item.
        let waste = (next_item_size - post_residual) as f64;
        score += waste * 0.35;
    }

    // Tight fit now is valuable when few alternatives exist (last-chance bin).
    if fitting_bins_count <= 1 && bin_residual >= item_size {
        score -= 18.0;
    }
    // Penalize opening a new bin when decent open bins exist.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { (fitting_bins_count as f64).min(4.0) };
        score += 25.0 / pressure;
        // Early in the stream, opening bins is cheaper (many items to come).
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        score += (1.0 - progress) * 10.0;
    } else {
        // Prefer bins already below mean residual (consolidating space).
        score += (mean_residual - post_residual as f64) * 0.15;
    }

    // Mild bonus for very tight fits overall.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= tightness * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward small post-residual non-linearly.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small to be useful for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item exactly or well.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0; // perfect chaining
        } else if post_residual >= next_item_size {
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            score += 8.0; // next item won't fit here
        }
    } else {
        // Last item: just fill as much as possible.
        score -= 20.0 * fit_ratio;
    }

    // Last-chance bin: avoid opening a new bin when this is the only fitting one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: only attractive when open bins would waste heavily.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let waste_here = (bin_capacity - item_size) as f64;
        // Penalize new bin normally; relax late in the stream or when mean residual is low.
        let mut new_bin_penalty = 45.0 - 25.0 * progress;
        if mean_residual < item_size as f64 * 1.2 && !fitting_bins_count_gt0(fitting_bins_count) {
            new_bin_penalty -= 30.0;
        }
        score += new_bin_penalty + 0.15 * waste_here;
    } else {
        // Mild bonus for filling fuller bins first (best-fit bias).
        score -= 5.0 * (1.0 - bin_residual as f64 / bin_capacity as f64);
    }

    // Global pressure: many open bins with high mean residual -> prefer consolidation.
    if open_bins_count > 3 && mean_residual > 40.0 {
        score -= 6.0;
    }

    score
}

#[inline]
fn fitting_bins_count_gt0(n: usize) -> bool { n > 1 }

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post_residual, with a non-linear penalty for tiny dead space
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Smooth polynomial coupling with stream progress: later in stream, punish waste harder
    let waste_coupling = norm_pr * (1.0 - progress) - norm_pr * norm_pr * progress;
    score += 20.0 * waste_coupling;

    // Last-chance bonus: if this is the only fitting bin, reward using it
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - norm_pr);
    }

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 8.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        // smooth penalty growing as next item fails to fit
        let gap = (next_item_size as f64 - pr) / cap;
        score += 6.0 * gap * gap;
    }

    // Slight preference for bins with residuals below mean (consolidate waste)
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // New-bin candidate: mild penalty so it's chosen only when open bins fit poorly
    if (bin_residual as u32) == bin_capacity {
        score += 10.0 + 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward: fill the bin exactly.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual modulo 10: small dead space classes
    // (1..9) are unusable for typical items; penalize tiny leftovers,
    // reward leftovers that sit in "usable" harmonic buckets.
    let cls = post_residual % 10;
    score -= match cls {
        0 => 30.0,               // round bucket: very reusable
        1..=4 => -6.0,           // near-round, moderately reusable
        5 => 5.0,                // half bucket
        _ => 8.0,                // awkward leftover
    };

    // Integer-division thresholds: leftover >= 50 can host any item;
    // leftover < 10 is near-dead space.
    if post_residual >= 50 {
        score -= 20.0;
    } else if post_residual < 10 && post_residual > 0 {
        score += 15.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly favor this bin (chain harmonic classes).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // next item cannot follow here; penalize more if leftover becomes dead
            score += (next_item_size - post_residual) as f64 * 0.2;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: prefer existing bins unless the item fits
    // very poorly everywhere. A fresh bin has full residual; make it mildly
    // unattractive so fragmentation is avoided first.
    if bin_residual == bin_capacity {
        score += 25.0;
        // But if current bin would leave huge dead space, new bin is fine:
        if post_residual > 40 {
            score -= 35.0;
        }
        // Late in the stream, opening fresh bins is cheap.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 10.0;
    }

    // Prefer tighter bins overall: deviate from mean residual.
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Slight preference for bins that are already well-filled.
    score -= (bin_capacity - bin_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    }

    // Reward tight fits (post_residual below next typical item size is dead space).
    if next_item_size > 0 {
        let gap = post_residual as f64 - next_item_size as f64;
        if gap < 0.0 && post_residual > 0 {
            score += 25.0 + gap.abs();
        } else if gap >= 0.0 {
            // residual can host the next item: reward proportionally
            score -= 10.0 * (1.0 - gap / bin_capacity as f64);
        }
    } else {
        // Last item: perfect fit is best.
        score -= 20.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: more open bins -> prefer filling existing ones.
    score += 0.5 * open_bins_count as f64;

    // New-bin candidate: only attractive when no good fit exists
    // (residual would be full capacity) or open bins are highly fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = open_bins_count as f64 * 0.5;
        let poor_fit = if post_residual > 0 && post_residual < 10 { 80.0 } else { 0.0 };
        score += 30.0 + fragmentation - poor_fit;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
    }

    // Prefer bins with below-average residual (fill fuller bins first).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Slight progression term: later in stream, be greedier about tight fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Lookahead: perfect match — bin closes exactly for the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            // Leftover after next item would be post_residual - next_item_size
            let after = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - after / bin_capacity as f64);
        } else {
            // Dead space: next item cannot fit in the remainder.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.8 * waste;
        }
    }

    // Reward tight fits overall.
    let tightness = 1.0 - post_residual as f64 / bin_capacity as f64;
    score -= 10.0 * tightness * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Prefer bins with residual below the mean (consolidate fullness).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Late in the stream, be greedy about closing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 15.0 * progress * tightness;

    // New empty bin: penalize mildly so it's chosen only when open bins fit badly.
    if bin_residual == bin_capacity {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize small post_residual quadratically.
    score -= (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Penalize dead space that no plausible item can fill.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual >= next_item_size {
            score -= 30.0;
        } else {
            // Next item won't fit here; slight penalty for wasting capacity.
            score += (next_item_size - post_residual) as f64 * 0.2;
        }
    }

    // New-bin candidate handling: make empty bins less attractive unless
    // open bins have poor residuals relative to the item.
    if bin_residual == bin_capacity {
        // Prefer reusing open bins when they fit reasonably well.
        let tightness = (item_size as f64) / (bin_capacity as f64);
        score += 120.0 - 60.0 * tightness;
        // Early in the stream, opening bins is cheaper (more future use).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 80.0 * (1.0 - progress);
        // If many open bins exist, opening another is worse.
        score += (open_bins_count as f64) * 3.0;
    } else {
        // Favor bins with residuals near mean (keep balance), slight effect.
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.1;
    }

    // Slight preference for fuller bins overall.
    score -= (bin_capacity - bin_residual) as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Smooth polynomial coupling of post_residual with stream progress.
    let pr = post_residual as f64;
    let pr_norm = pr / bin_capacity as f64;
    let coupling = pr_norm * pr_norm * (progress * (1.0 - progress) * 4.0);
    score += 12.0 * coupling;

    // Penalize large dead space late in the stream.
    score += (pr_norm * pr_norm * pr_norm) * (progress * 40.0);

    // Reward tight fits mildly, scaled by fitting scarcity.
    let tightness = 1.0 - pr_norm;
    score -= tightness * (1.0 + fitting_bins_count as f64).ln() * 3.0;

    // Last-chance bin bonus.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: prefer bins whose post_residual fits next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    } else if next_item_size > 0 {
        score += 4.0;
    }

    // Slight preference for bins below mean residual (consolidating space).
    score += (mean_residual - bin_residual as f64) * 0.05;

    // New-bin candidate: mild penalty so open bins are preferred unless fit is poor.
    if bin_residual == bin_capacity {
        score += 5.0 + pr_norm * 10.0 - progress * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Perfect fill: strong reward
    if post_residual == 0 {
        score -= 60.0;
    }

    // Harmonic class of post_residual: residues near multiples of 10 are
    // reusable dead-space sinks; tiny residues (<10) are unusable fragments.
    let residue_class = post_residual % 10;
    if post_residual > 0 {
        score += match residue_class {
            0 => -8.0,
            1..=9 => (residue_class as f64) * 0.4, // awkward fragments penalized
            _ => 0.0,
        };
    }

    // Lookahead: reward bins whose post_residual can host the next item,
    // scaled by how snugly the next item nests.
    if next_item_size > 0 && post_residual >= next_item_size {
        let snug = 1.0 - ((post_residual - next_item_size) as f64) / cap;
        score -= 10.0 + 12.0 * snug;
    } else if next_item_size > 0 {
        // next item cannot fit here: penalize proportionally to wasted potential
        score += 4.0 * (1.0 - post / cap);
    }

    // Last-chance bin before opening a new bin: strong reward if fit is decent
    if fitting_bins_count == 1 {
        score -= 15.0 + 0.3 * (post_residual as f64);
    }

    // New-bin candidate: penalize so it only wins when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 18.0 + 0.25 * (item_size as f64);
        // Exception: very large items deserve a fresh bin to avoid stranding
        if item_size * 2 > bin_capacity {
            score -= 22.0;
        }
        // Late in the stream, prefer closing out existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Coupling with global state: if mean residual is high, prefer bins that
    // reduce fragmentation (i.e., low post_residual overall).
    if mean_residual > 0.5 * cap {
        score += 0.05 * (mean_residual - 0.5 * cap);
    }

    // Prefer filling bins with many siblings already open (bin consolidation)
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in a small unusable gap is very costly.
    // Anything that can't fit the smallest plausible next item (<= 10) is dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Partially usable small gaps get a graded penalty.
    if post_residual >= 10 && post_residual < 25 {
        score += 12.0;
    }

    // Reward very tight fits (post_residual near zero) strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Perfect-fit lookahead: if the next item exactly fills post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 45.0;
    }
    // If next item fits in the residual, mild reward for keeping usable space.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 6.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // (penalize the new-bin candidate implicitly by rewarding existing bins).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual != bin_capacity {
        // existing bin: reward scaled by open-bin pressure and stream progress
        score -= (open_bins_count as f64 * 0.8 + 10.0 * progress).min(20.0);
    } else {
        // new-bin candidate: penalize more when many bins are already open
        score += (open_bins_count as f64 * 1.5).min(25.0);
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Prefer bins whose residual is already below average (consolidate waste).
    if bin_residual != bin_capacity {
        let dev = mean_residual - bin_residual as f64;
        score += 0.3 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: strongly prefer bins that end (near-)empty.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 3 {
        score -= 200.0;
    }

    // 2-step lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            // next item fits, penalize leftover after that hypothetical placement
            let after_next = post_residual - next_item_size;
            score -= 50.0;
            score += after_next as f64 * 1.5;
        } else {
            // next item won't fit here: penalize proportionally to overshoot
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
    }

    // Relative to mean residual: prefer bins tighter than average (compactness).
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 0.2 * item_size as f64;
    }

    // New-bin candidate: penalize opening a new bin unless item is large and
    // no good compact fit exists; discourage wasteful new bins early in stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 80.0
            - 0.5 * item_size as f64
            - 40.0 * progress
            - if fitting_bins_count == 0 { 60.0 } else { 0.0 };
        // opening a new bin is fine if next item pairs with a fresh large residual
        if next_item_size > 0 && (100 - item_size as u32) >= next_item_size {
            score -= 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual) more aggressively than linear.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item can still fit in the post-residual, reward;
    // if placing here blocks the next item while another bin could take it, penalize.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += 8.0;
            // Extra penalty if this bin would become nearly useless for the next item.
            if post_residual < next_item_size / 2 {
                score += 6.0;
            }
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin.
        score += 55.0;
        // More open bins -> cheaper to open another? No: keep bin count low,
        // but if open bins are all crowded (low mean residual), opening is fine.
        let crowdedness = 1.0 - mean_residual / (bin_capacity as f64);
        score -= 40.0 * crowdedness;
        // Late in the stream, prefer consolidating rather than opening bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 25.0 * progress;
        // If item is large relative to residual of typical bins, opening is safer.
        if item_size > 60 {
            score -= 15.0;
        }
    } else {
        // Prefer bins whose residual is close to the item (minimal waste ratio).
        let waste_ratio = (bin_residual - item_size) as f64 / bin_residual.max(1) as f64;
        score += 10.0 * waste_ratio;
    }

    // Mild preference to spread load when many bins are open and mean residual is high.
    if !is_new_bin && mean_residual > (bin_capacity as f64) * 0.5 && post_residual > 40 {
        score += 5.0;
    }

    // Early stream: allow slightly more exploration of new bins.
    if step_index < total_items / 10 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr;

    // Tight fits (small post_residual) are rewarded more strongly as the stream advances
    let tightness = 1.0 - pr / cap; // in (0,1], larger = tighter fit
    score -= tightness * tightness * (1.0 + 40.0 * progress);

    // Penalize large dead space super-linearly, growing with progress
    let waste = pr / cap;
    score += waste * waste * waste * (60.0 + 120.0 * progress);

    // Last-chance bin bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 30.0 * progress;
    }

    // Lookahead coupling: reward bins whose post-residual can still host the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack_fit = 1.0 - (pr - nxt) / cap;
            score -= 10.0 * slack_fit * slack_fit;
        } else {
            // post-residual too small for next item: penalize dead space
            score += 8.0 * (1.0 - pr / cap);
        }
    }

    // Mild preference for bins deviating from mean residual (consolidate fullness)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 6.0 * dev * dev * (1.0 - progress);

    // New-bin candidate: keep it competitive only when open bins are very full
    if bin_residual as f64 == cap {
        score = pr + 45.0 - 55.0 * progress - 0.3 * mean_residual;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into "dead zone"
    // classes (small non-reusable slivers) are penalized.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let item = item_size as f64;

    // Perfect fit reward: exact fill is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic residue classes on post_residual (mod 10): residuals that are
    // multiples of 10 remain reusable by the smallest items (sizes >= 1).
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 25.0;
    }

    // Dead-space class: residual in (0, 10) is unusable waste -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Fractional capacity classes: post_residual as fraction of capacity.
    let frac = pr / cap;
    if frac < 0.1 {
        score += 30.0 * (0.1 - frac);
    } else if frac > 0.5 {
        score -= 15.0 * (frac - 0.5);
    }

    // Integer-division threshold: how many mid-size items (>= 10) still fit.
    let fits_count = post_residual / 10;
    score -= 8.0 * fits_count as f64;

    // Lookahead coupling: reward residual that can host the next item exactly
    // or comfortably; penalize residual just barely too small for next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack == 0 {
                score -= 120.0; // perfect lookahead fit
            } else if slack < 10 {
                score -= 40.0;  // near-perfect next fit
            } else {
                score -= 15.0;  // can host next item
            }
        } else {
            // residual cannot host next item: penalize proportionally to closeness
            let gap = (next_item_size - post_residual) as f64;
            score += 20.0 + 0.5 * gap;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 45.0;
    }

    // New-bin candidate handling: an empty bin is a fallback; make it attractive
    // only when current bin would leave large waste relative to mean residual.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 40.0;
        // more attractive late in the stream or when open bins are already tight
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 30.0 * progress;
        score -= 5.0 * open_bins_count as f64;
        // if mean residual across open bins is small, opening fresh bin is good
        if mean_residual < item {
            score -= 50.0;
        }
    }

    // Tightness bonus: prefer bins where the item fills a large share of residual.
    if bin_residual > 0 {
        let fill_ratio = item / bin_residual as f64;
        score -= 30.0 * fill_ratio;
    }

    // Mild penalty for spreading across many open bins when residuals are large.
    if mean_residual > 0.6 * cap && open_bins_count > 2 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A gap is "dead" if it is smaller than the smallest plausible item (1) but
    // practically we treat gaps below ~10% of capacity as near-dead, and gaps
    // that cannot fit the lookahead item as wasted if next item is large.
    let gap = post_residual as f64;
    if gap > 0.0 {
        // quadratic dead-space penalty for small gaps
        score += (bin_capacity as f64 / (gap + 1.0)).sqrt() * 6.0;
        // hard penalty band: gaps 1..=10 are almost unusable
        if post_residual <= 10 {
            score += 40.0;
        } else if post_residual <= 20 {
            score += 12.0;
        }
    } else {
        // perfect fit: strongly reward
        score -= 25.0;
    }

    // Reward tight fits: fraction of bin used by this placement.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 18.0;

    // Open bins pressure: with many open bins, prefer filling existing ones.
    let pressure = (open_bins_count as f64 / 10.0).min(3.0);
    score += pressure * (post_residual as f64 / bin_capacity as f64) * 8.0;

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + item_size as f64 * 0.1;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // reward; if post residual is too small for the next item but nonzero, penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size > post_residual && post_residual > 0 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.4;
        }
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Make it moderately attractive only when current bins have poor fits.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin, reduced under pressure of many items left
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = bin_capacity as f64 * 0.55 - pressure * 4.0 - (1.0 - progress) * 2.0;
        // if the only alternative is a bad fit, new bin looks better
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Mild mean-residual coupling: prefer bins whose residual deviates from mean
    // toward being consumed (residual below mean => more filled bin).
    if bin_residual as f64 > mean_residual {
        score += 3.0;
    } else {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when next item exactly matches post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            // next item fits here: mild reward proportional to how well it fills
            score -= 100.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item cannot use post_residual: penalize large dead space
            score += 0.5 * post_residual as f64;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= 0.3 * (mean_residual - bin_residual as f64);

    // Last-chance bin before opening a new bin: strong reward
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // New-bin candidate: penalize opening a new bin unless it's early,
    // the item is large, or all existing fits are poor
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fits = fitting_bins_count == 0
            || (fitting_bins_count == 1 && (bin_residual - item_size) as f64 > 0.6 * bin_capacity as f64);
        if poor_fits || progress < 0.05 || item_size > 60 {
            score -= 150.0;
        } else {
            score += 300.0;
        }
    }

    // Prefer using nearly-full bins
    score -= 0.5 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post-residual preferred).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 60.0 * tightness * tightness;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the new-bin fit is perfect).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Lookahead: reward leaving space exactly matching the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual > next_item_size {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; slight penalty unless residual is tiny.
            score += 6.0;
        }
    }

    // Prefer filling bins when many bins are open (consolidation pressure).
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score -= 3.0 * pressure * tightness;

    // Prefer bins with residual above the mean (balance across bins).
    let res = bin_residual as f64;
    if res > mean_residual {
        score -= 0.15 * (res - mean_residual);
    } else {
        score += 0.15 * (mean_residual - res);
    }

    // Early in the stream, be more willing to open new bins for large items;
    // later, squeeze into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive only for large items or perfect fits later on.
        let item_frac = item_size as f64 / bin_capacity as f64;
        score -= 10.0 + 40.0 * item_frac * (1.0 - progress);
        if item_size >= 60 {
            score -= 15.0 * progress;
        }
    } else {
        // Existing bin: slightly favored as stream progresses.
        score -= 8.0 * progress;
    }

    // Mild penalty for wasting a nearly-full bin's potential on a tiny item.
    if item_size < 20 && bin_residual <= 30 && post_residual > 0 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = x * x * (1.0 - x) * (1.0 - x);
    let coupling = poly * (1.0 + 3.0 * progress);

    let mut score = pr;

    // Reward tight fits more aggressively as the stream progresses
    score -= 40.0 * coupling;

    // Penalize dead space (post_residual too small to ever be useful) smoothly
    let dead = (1.0 - x).powi(3);
    score += 15.0 * dead * (1.0 - progress);

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 30.0 * progress;
    }

    // Lookahead: reward if next item fits in post_residual
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let fit_frac = next_item_size as f64 / pr;
        score -= 12.0 * (1.0 - (fit_frac - 0.5).powi(2));
    } else if next_item_size > 0 {
        score += 8.0 * (next_item_size as f64 - pr) / cap;
    }

    // Mild preference for filling bins with large residuals relative to mean
    score -= 5.0 * (bin_residual as f64 - mean_residual) / cap;

    // Slight new-bin aversion that grows with open bins
    if bin_residual as u64 == bin_capacity as u64 {
        score += 10.0 + 2.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into capacity fractions
    let cap = bin_capacity as f64;
    let post_frac = post_residual as f64 / cap;

    // Penalize residuals that fall into "dead zone" classes: too small to be useful
    // Classes via integer division thresholds on post_residual
    let class = post_residual / 10; // 0..10 harmonic classes
    match class {
        0 => score += 30.0,                 // 0..9: nearly full, excellent
        1 => score += 12.0,                 // 10..19: decent
        2 | 3 => score += 0.0,              // 20..39: neutral
        4 | 5 => score -= 3.0,              // 40..59: roomy, ok
        _ => score += 8.0,                  // 60..100: wasteful large leftover
    }

    // Modulo arithmetic: residuals that are multiples of common item sizes are reusable
    let pr = post_residual;
    if pr > 0 {
        let mut reusable = 0.0;
        for m in [10u32, 20, 25, 30, 40, 50] {
            if pr % m == 0 { reusable += 2.0; }
        }
        score -= reusable;
    }

    // Lookahead coupling: reward exact fit for next item into post residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / cap);
        } else {
            score += 6.0; // next item can't fit here
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current fit is poor
    if bin_residual == bin_capacity {
        // new bin baseline: post_residual will be cap - item_size
        score += 10.0 * (1.0 - post_frac);
        if open_bins_count > 0 && fitting_bins_count > 0 {
            score += 5.0; // discourage opening when alternatives exist
        }
    }

    // Progress-aware mild pressure to close bins early in stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 4.0 * progress * (1.0 - post_frac);

    // Mean residual context: if this bin is far below mean residual, it's a good aggregator
    score -= 0.05 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever be
    // useful (below the minimum item size of 1..100 range, use a practical
    // "unusable gap" threshold) are heavily penalized.
    let dead_threshold = 9.0f64;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += 40.0 + (dead_threshold - post_residual as f64) * 6.0;
    }

    // Tight fit reward: subtract proportional to fill fraction.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill * fill;

    // Penalize bins whose residual is far from the item (poor coupling).
    let mismatch = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 12.0 * mismatch;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the item fits poorly everywhere else or open bins are very full.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 55.0;
        // Discount if open bins are congested (high count, low mean residual).
        let congestion = open_bins_count as f64 / (1.0 + mean_residual / 20.0);
        score -= congestion.min(45.0);
        // Perfect fit of item + lookahead into a fresh bin is attractive.
        if next_item_size > 0 && (item_size + next_item_size) as f64 <= bin_capacity as f64 {
            score -= 18.0;
        }
    }

    // Prefer reusing bins that can also host the next item afterwards.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 8.0;
    }

    // Mild open-bin pressure: with many open bins, discourage spreading.
    score += 0.4 * open_bins_count as f64;

    // Late-stream consolidation: as the stream progresses, favor filling
    // existing bins over opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 25.0 * progress;
    } else {
        score -= 8.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward leaving exactly zero residual.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if the next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 800.0; // perfect chain
        } else if next_item_size <= post_residual {
            // reward proportional to how much of the leftover the next item consumes
            let fill_ratio = next_item_size as f64 / post_residual as f64;
            score -= 300.0 * fill_ratio;
            // extra bonus if the chain completes the bin too
            if post_residual - next_item_size == 0 {
                score -= 200.0;
            }
        } else {
            // next item cannot use this leftover: penalize large dead space
            let dead = post_residual as f64;
            score += 0.5 * dead;
            // harsher penalty if the dead space is small-but-unusable (worst kind)
            if dead < 10.0 {
                score += 150.0;
            }
        }
    }

    // Last chance: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin — unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        let waste_ratio = post_residual as f64 / bin_capacity as f64;
        if waste_ratio < 0.5 {
            score -= 250.0 * (1.0 - waste_ratio);
        } else {
            score += 100.0 * (waste_ratio - 0.5) * 2.0;
        }
    }

    // New-bin candidate: penalize opening a new bin, but less when the item is
    // large (hard to place later) or many bins are already open and fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let large_item_bonus = (item_size as f64 / 100.0) * 120.0;
        score += 400.0 - large_item_bonus - 50.0 * progress;
        // discourage new bins when open bins are on average quite empty
        if mean_residual > item_size as f64 * 1.5 {
            score += 100.0;
        }
    }

    // Prefer tighter bins relative to the fleet mean residual (best-fit flavor).
    let mean_gap = (bin_residual as f64 - mean_residual).abs();
    score -= 0.3 * mean_residual - 0.3 * mean_gap;

    // Slight preference for bins that are already partially filled.
    let fill = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 40.0 * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize proportionally to fill ratio achieved.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Penalize dead space that can never be used by typical future items.
    if post_residual < 10 {
        score -= 15.0; // near-perfect closure
    } else if post_residual < next_item_size.max(1) as f64 {
        score += 8.0; // leftover too small for the next item
    }

    // Lookahead coupling: reward if the next item fits exactly into post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Global pressure: when many bins are open, prefer consolidation into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 / (total_items.max(1) as f64).sqrt();
    score -= pressure * 3.0 * (1.0 - progress * 0.5);

    // Mean residual coupling: prefer bins below mean residual (tighter bins) when mean is high.
    if (bin_residual as f64) < mean_residual {
        score -= 6.0 * (mean_residual - bin_residual as f64) / bin_capacity as f64;
    } else {
        score += 4.0 * ((bin_residual as f64) - mean_residual) / bin_capacity as f64;
    }

    // New empty bin candidate: only attractive when no good fit exists
    // (large dead space would be created elsewhere) or stream is early.
    if bin_residual == bin_capacity {
        let waste_elsewhere = (bin_residual - item_size) as f64;
        if fitting_bins_count == 0 || (waste_elsewhere > 40.0 && progress < 0.5) {
            score -= 12.0;
        } else {
            score += 25.0; // discourage opening new bins when decent fits exist
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: prefer small post-residual, with smooth non-linear polynomial coupling
    let mut score = post * (1.0 + 0.5 * norm_post * norm_post);

    // Smooth stream-progress coupling: tighten packing later in the stream
    score += 12.0 * progress * norm_post * (1.0 - norm_post);

    // Penalize dead space relative to mean residual across open bins
    score += 0.05 * (post - mean_residual).abs();

    // Lookahead: reward leaving room for the next item (smooth kernel)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post - nxt) / cap;
        let kernel = (-gap * gap).exp();
        score -= 6.0 * kernel;
        // Penalize wasting space if next item cannot use the remainder
        if post < nxt {
            score += 4.0 * (nxt - post) / cap;
        }
    }

    // Last-chance bonus: only one bin fits, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Mild penalty for spreading across many open bins
    score += 0.05 * open_bins_count as f64 * norm_post;

    // New-bin candidate: neutral-ish baseline, penalize opening new bins
    // unless residual would be nearly zero
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - (item_size as f64 / cap));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: integer division into capacity-fraction classes
    let quarter = bin_capacity / 4;
    let class = post_residual / quarter; // 0..4 harmonic class
    // Dead space penalty: residuals that are too small to fit likely future items
    if post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 15.0;
    }

    // Reward tight fits (small post_residual in a good class)
    score -= (bin_capacity - post_residual.min(bin_capacity)) as f64 * 0.15;

    // Lookahead: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        if slack < 10 {
            score -= 25.0;
        } else {
            score -= 8.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // next item cannot use this residual: penalize proportionally
        score += (next_item_size - post_residual) as f64 * 0.3;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Modulo arithmetic on post_residual: residuals divisible by common sizes are reusable
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 5.0;
    }

    // New-bin candidate handling: neutral baseline, slightly worse than a decent fit
    if bin_residual == bin_capacity {
        score += 12.0 + open_bins_count as f64 * 0.5;
        // opening a new bin is good late in stream if open bins are fragmented
        if mean_residual < item_size as f64 {
            score -= 20.0;
        }
    }

    // Stream progression: early on, prefer consolidation; late, prefer new bins for balance
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += class as f64 * 2.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no item (min size 10) can use are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + 4.0 * (10 - post_residual) as f64;
    }
    // Near-miss gaps that only tiny items can use are also risky.
    if post_residual >= 10 && post_residual <= 20 {
        score += 8.0;
    }

    // Reward very tight fits (post_residual small but usable).
    if post_residual > 0 {
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= 12.0 * tightness * tightness;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: penalize spreading across many bins slightly,
    // but only when the fit is mediocre.
    if post_residual as f64 > mean_residual * 0.5 {
        score += 0.35 * open_bins_count as f64;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let leftover = post_residual - next_item_size;
        if leftover < 10 {
            score -= 10.0; // sets up a perfect two-item packing
        } else {
            score -= 3.0;
        }
    }

    // New-bin candidate: empty bin has no dead space yet, but opening it is costly
    // when good fits exist in open bins. Make it attractive only when this bin
    // would be a poor host (large post-residual dead space).
    if bin_residual == bin_capacity {
        score = 45.0 + 0.2 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 50.0; // no alternative: new bin is correct
        }
        // Late in the stream, avoid opening bins for small items.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if item_size < 40 && progress > 0.7 {
            score += 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: strongly reward exact match with next item size
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if gap == 0.0 {
            score -= 60.0; // perfect two-item fill
        } else if post_residual >= next_item_size {
            score -= 25.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // dead space that next item cannot use
            score += 8.0 * gap / bin_capacity as f64;
        }
    }

    // penalize very small unusable residuals (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }
    if post_residual == 0 {
        score -= 20.0; // perfect closure
    }

    // relative to mean residual: prefer bins tighter than average
    score -= 0.5 * (mean_residual - post_residual as f64);

    // last-chance bin bonus: avoid opening new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // new-bin candidate: mildly discouraged unless current bins would leave big waste
    if bin_residual == bin_capacity {
        score += 10.0 + 0.1 * open_bins_count as f64;
    }

    // early stream: slightly prefer reusing bins to build tight packs
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.05 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (minimize wasted space).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize small but awkward residuals (dead space that rarely fits anything).
    if post_residual > 0 && post_residual < item_size.min(50) {
        score += 6.0 * (1.0 - post_residual as f64 / 50.0);
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0;
            // Perfect chain: next item exactly fills leftover space.
            if next_item_size == post_residual {
                score -= 12.0;
            }
        } else {
            // Penalize leaving a residual too small for the upcoming item.
            let waste_gap = (post_residual as f64).max(0.0);
            if next_item_size > post_residual && post_residual < next_item_size.min(60) {
                score += 4.0 * (1.0 - post_residual as f64 / 60.0);
            }
            let _ = waste_gap;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate logic: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin; decays as stream progresses (sunk bins matter less late).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = 25.0 + 20.0 * (1.0 - progress);
        // If many bins fit, discourage opening a new one.
        score += 5.0 * fitting_bins_count as f64;
        // If current item is large, opening fresh bin is more reasonable.
        score -= (item_size as f64 / 100.0) * 10.0;
        // If open bins are heavily fragmented (high mean residual), new bin is fine.
        score -= (mean_residual / bin_capacity as f64) * 8.0;
    }

    // Mild penalty for using bins when many are open (encourage consolidation).
    score += 0.15 * open_bins_count as f64;

    // Small reward for filling bins closer to capacity overall.
    score -= 0.1 * (item_size as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear coupling: post_residual penalized more as stream progresses
    // (late dead space is costlier since fewer chances remain to fill it).
    let pr_norm = pr / cap;
    score += pr * pr_norm * (0.5 + progress);

    // Tight fits (small post_residual) rewarded, with smooth polynomial shaping.
    score -= (pr_norm * (1.0 - pr_norm)).sqrt() * 12.0;

    // Last-chance bonus: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 8.0 + 10.0 * (1.0 - progress);
    }

    // Lookahead: reward if next item fits into the post-residual (smooth gate).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = pr - nxt;
        if gap >= 0.0 {
            let g = gap / cap;
            score -= 6.0 * (g * (1.0 - g) * 4.0).sqrt();
        } else {
            // Smooth penalty for leaving a gap that blocks the next item.
            let g = (-gap / cap).min(1.0);
            score += 5.0 * g * g;
        }
    }

    // Discourage spreading residual far above the mean (fragmentation).
    let dev = pr - mean_residual;
    score += 0.15 * dev * dev / cap;

    // Mild pressure to reuse bins vs opening new ones, easing as stream progresses.
    score += (open_bins_count as f64).ln() * (1.5 - progress);

    // New-bin candidate: neutral-ish baseline with slight progress-dependent bias.
    if bin_residual == bin_capacity {
        score = cap * (0.9 + 0.3 * progress) + 0.15 * dev * dev / cap + (open_bins_count as f64).ln() * (1.5 - progress);
        if next_item_size > 0 && (next_item_size as f64) <= cap {
            score -= 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues near multiples of small
    // denominators (25, 20, 50) are more reusable by future items.
    let pr = post_residual;
    let mut bonus = 0.0;

    if pr == 0 {
        bonus -= 60.0; // perfect fit, best possible outcome
    } else if pr % 50 == 0 {
        bonus -= 30.0;
    } else if pr % 25 == 0 {
        bonus -= 18.0;
    } else if pr % 20 == 0 {
        bonus -= 12.0;
    } else if pr % 10 == 0 {
        bonus -= 8.0;
    }

    // Penalize awkward dead space: small unusable residues
    if pr > 0 && pr < 10 {
        bonus += 45.0; // dead space zone
    } else if pr < 20 {
        bonus += 15.0;
    }

    // Integer-division threshold on post_residual: classify into usable bands
    let band = pr / 10; // 0..10 band index
    bonus -= (band as f64) * 1.5; // larger usable residual is slightly better

    // Lookahead: does next item fit in post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // exact harmonic match is ideal
            if pr % next_item_size.max(1) == 0 {
                bonus -= 25.0;
            } else {
                bonus -= 12.0;
            }
            // penalize wasteful near-misses
            let gap = pr - next_item_size;
            if gap < 10 {
                bonus += 10.0;
            }
        } else {
            bonus += 20.0; // next item won't fit here anyway
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        bonus -= 35.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when current
    // placement creates severe dead space.
    if bin_residual == bin_capacity {
        // neutral base: fresh bin has full residual, post_residual = capacity
        // already gives large score; adjust to make it competitive but not dominant
        bonus += 5.0;
        if item_size >= bin_capacity / 2 {
            bonus -= 10.0; // big items start fresh bins reasonably
        }
    }

    // Late in stream, tighten packing (less tolerance for slack)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    bonus -= progress * 8.0;

    // Many open bins: discourage spreading, favor tight fits
    if open_bins_count > 4 {
        bonus += (open_bins_count as f64).ln() * 2.0 * (mean_residual / bin_capacity as f64);
    }

    score += bonus;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual that cannot hold even the smallest item (1) is pure waste;
    // residuals below ~20 are rarely fillable by typical items.
    if post_residual == 0 {
        score -= 60.0; // perfect fit is ideal
    } else if post_residual < 10 {
        score += 40.0; // near-dead space: very bad
    } else if post_residual < 20 {
        score += 15.0;
    } else if post_residual < 30 {
        score += 5.0;
    }

    // Reward keeping residual large enough to host the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        // Extra reward when post residual exactly accommodates next item.
        if post_residual == next_item_size {
            score -= 10.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item won't fit here; mild penalty proportional to gap size.
        score += 3.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64) * (1.5 + 2.0 * progress);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Mean residual coupling: prefer bins whose residual is below average
    // (i.e., already partly filled) to consolidate load.
    score -= (mean_residual - post_residual as f64) * 0.5;

    // New-bin candidate handling: neutral-ish baseline, but only attractive
    // when current item is large relative to capacity or open bins are many.
    if bin_residual == bin_capacity {
        score = 55.0 + (open_bins_count as f64) * 2.0 - (item_size as f64) * 0.3;
        // Opening a new bin is fine if the next item is huge and would waste
        // space in any existing bin.
        if next_item_size >= 60 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact or near-exact fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize dead space that is too small to ever be useful (min item size 1, but
        // small residuals below a threshold are hard to fill).
        let dead = post_residual as f64;
        if dead < 10.0 {
            score += (10.0 - dead) * 8.0;
        }
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item exactly,
    // penalize those that leave post_residual incompatible with next_item_size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as u32) == next_item_size {
            score -= 400.0; // perfect chain: residual consumed fully next step
        } else if post_residual >= next_item_size {
            score -= 120.0; // next item still fits here
        } else {
            score += 60.0 + (next_item_size - post_residual) as f64; // chain broken
        }
        // Bonus if post_residual - next_item_size is itself a nice round residual (e.g. 0 or >= 10)
        if post_residual >= next_item_size {
            let two_step = post_residual - next_item_size as u32;
            if two_step == 0 {
                score -= 250.0;
            } else if two_step >= 10 {
                score -= 30.0;
            } else {
                score += (10 - two_step) as f64 * 5.0;
            }
        }
    } else {
        // Last item: strongly prefer closing bins completely.
        score -= 500.0;
    }

    // Relative-to-mean coupling: prefer bins tighter than average.
    let res_f = bin_residual as f64;
    if mean_residual > 0.0 {
        score += (res_f - mean_residual) * 0.8;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: make it attractive only when fits are poor or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = post_residual as f64 > 40.0;
        if poor_fit && progress < 0.9 {
            score -= 80.0;
        } else {
            score += 200.0; // discourage spreading across bins when a decent fit exists
        }
    }

    // Mild preference to fill older/more-open-bin situations efficiently.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly prefer bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize leaving small, hard-to-use dead space (post_residual in awkward zone).
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 10.0 {
        score += 25.0; // tiny slivers are nearly dead space
    } else if pr >= 10.0 && pr <= 30.0 {
        score += 6.0 * (1.0 - pr / 30.0);
    }

    // Lookahead coupling: if the next item fits exactly into the resulting residual, reward heavily.
    if next_item_size > 0 {
        let nd = next_item_size as f64;
        if (nd - pr).abs() < 0.5 {
            score -= 40.0;
        } else if nd <= pr {
            score -= 10.0 * (1.0 - (pr - nd) / bin_capacity as f64);
        } else {
            score += 4.0 * (nd - pr) / bin_capacity as f64;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate logic: opening a new bin is only attractive when the item is large
    // relative to capacity and existing bins are fairly full (low mean residual).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let size_frac = item_size as f64 / bin_capacity as f64;
        let openness = mean_residual / bin_capacity as f64;
        // Prefer new bin when item is big and open bins are tight; penalize otherwise.
        let new_bin_bias = 20.0 * size_frac + 15.0 * (1.0 - openness) + 5.0 * progress;
        score += 35.0 - new_bin_bias;
        // Never open a new bin for tiny items when any bin fits.
        if size_frac < 0.35 {
            score += 30.0;
        }
    }

    // Mild preference for keeping the number of open bins bounded late in the stream.
    score += 0.5 * open_bins_count as f64 * (1.0 - step_index as f64 / (total_items.max(1) as f64));

    // Slight reward for using bins whose residual is below the mean (consolidation).
    if (bin_residual as f64) < mean_residual && bin_residual != bin_capacity {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    let mut score = pr as f64;

    // Smooth non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * (1.0 - norm_pr);
    score += 12.0 * poly * cap / 100.0;

    // Penalize dead space more as stream progresses (less time to fill leftovers)
    score += 20.0 * norm_pr * norm_pr * progress;

    // Reward tight fits (small post_residual) with a smooth saturating term
    score -= 8.0 * (1.0 - norm_pr).powi(3);

    // Last-chance bin: strong bonus to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Lookahead: if next item fits into the post-residual, reward this placement
    if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        score -= 6.0;
    } else if next_item_size > 0 && (next_item_size as u32) > post_residual {
        // next item cannot use this leftover: penalize wasted residual smoothly
        score += 5.0 * norm_pr;
    }

    // Mild penalty when many bins are open relative to progress (encourage consolidation)
    let bin_pressure = open_bins_count as f64 / (1.0 + total_items as f64 * progress);
    score += 2.0 * bin_pressure * (0.5 + progress);

    // Keep new-bin candidate slightly penalized unless residual is tiny
    if bin_residual == bin_capacity {
        score += 3.0 + 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: capacity fractions create "sweet spots".
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Penalize dead space that is too small to be useful later (items >= 10 by
    // contract, but interface allows 1..=100, so use next_item_size-aware logic).
    let min_useful = if next_item_size > 0 { next_item_size.min(100) } else { 20 } as f64;
    if post > 0.0 && post < min_useful {
        score += (min_useful - post) * 2.5; // unusable sliver penalty
    }

    // Reward residuals that are harmonic class multiples: post_residual near
    // multiples of capacity fractions (cap/4, cap/2) are reusable.
    let quarter = cap / 4.0;
    let half = cap / 2.0;
    for unit in [quarter, half] {
        let dist = (post - (post / unit).round() * unit).abs();
        if dist < 5.0 {
            score -= (5.0 - dist) * 1.2; // harmonic alignment bonus
        }
    }

    // Integer-division threshold on post_residual: coarse classes.
    let class = post_residual / 10; // decade class
    score -= (class as f64) * 0.8; // bigger coarse class = more reusable

    // Modulo logic: residuals congruent to 0 mod 10 pack integer items cleanly.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: penalize opening a new bin when stream is late and
    // open bins exist, unless the item is huge relative to residual.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let tight_fit = (item_size as f64) / (bin_residual as f64);
        score += 12.0 - 10.0 * progress; // new bins get cheaper later? no: keep closed early
        if tight_fit > 0.8 {
            score -= 15.0; // huge item: fresh bin is fine
        }
        if open_bins_count == 0 {
            score -= 20.0; // must open
        }
    }

    // Lookahead: if next item fits exactly in post_residual, big bonus.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 10.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 2.0;
    }

    // Prefer bins tighter than average (waste minimization).
    score -= (mean_residual - post) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small for any future item
    // (items >= 1, but realistically small gaps < ~15 are wasteful).
    if post_residual > 0 && post_residual < 15 {
        score += (15 - post_residual) as f64 * 4.0;
    }
    if post_residual == 0 {
        // Perfect fit: strong reward
        score -= 30.0;
    }

    // Reward tight fits relative to bin residual
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * 12.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.6 + 0.8 * progress);

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 + next_item_size as f64 * 0.1;
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 5.0;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins)
    score += (mean_residual - bin_residual as f64) * 0.15;

    // New-bin candidate: make it attractive only when existing fits are bad.
    // Base new-bin score is moderate post_residual (=capacity) plus a fixed
    // premium so poor fits in open bins lose to it.
    if bin_residual == bin_capacity {
        score += 8.0 + open_bins_count as f64 * 0.5;
        // If the item is large relative to capacity, opening fresh is fine
        score -= item_size as f64 * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual equals next item size -> ideal packing.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    // Next item fits into post_residual: strong reward, scaled by tightness of the chain.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 50.0 + (next_item_size as f64 / 100.0) * 30.0;
        // Bonus if the bin can also absorb the next item almost exactly.
        let chain_gap = post_residual - next_item_size;
        score -= (20 - chain_gap.min(20)) as f64 * 2.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item won't fit: penalize creating near-dead space.
        let dead = post_residual as f64;
        if dead < next_item_size as f64 {
            score += (next_item_size as f64 - dead) * 1.5;
        }
    }

    // Penalize small but nonzero post_residual (unusable slivers).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Reward very tight fits relative to capacity.
    score -= (bin_capacity - post_residual) as f64 / bin_capacity as f64 * 10.0;

    // Last-chance bin before opening a new bin: strong reward to use it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Prefer bins tighter than the mean residual (better fits).
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Early in the stream, be more willing to open new bins to build a good pool.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline cost plus a discount early on.
        score = bin_capacity as f64 - 30.0 * (1.0 - progress) + 30.0 * progress;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly favor tight fits: quadratic penalty on wasted space.
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 40.0;

    // Exact fit is a perfect placement.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Dead-space penalty: residuals too small for the minimum item size.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: reward if the next item fits into the post-residual (chaining).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0 + 0.2 * next_item_size as f64;
        } else {
            // Penalize leaving a gap the next item can't use.
            score += 8.0;
        }
    }

    // Global state coupling: prefer filling bins when mean residual is high (many scattered gaps).
    let mean_gap = (mean_residual - post_residual as f64).abs();
    score += mean_gap * 0.3;

    // Time horizon: early in the stream, be more willing to open bins (explore);
    // late in the stream, consolidate into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses.
        score += 20.0 + 60.0 * progress;
        // But early on, opening bins is cheap.
        score -= 25.0 * (1.0 - progress);
        // Don't open a new bin if an existing bin fits nearly perfectly.
        if post_residual <= 15 && fitting_bins_count >= 1 {
            score += 50.0;
        }
    } else {
        // Reward using existing bins more strongly late in the stream.
        score -= 10.0 * progress;
    }

    // Many open bins: encourage consolidation.
    score += open_bins_count as f64 * 0.5;

    // Prefer bins whose residual is close to the item size (minimal waste).
    score += (bin_residual - item_size) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit = fitting_bins_count as f64;
    let mean_r = mean_residual.max(0.0);

    // Base: penalize wasted post residual, non-linearly (quadratic dead space).
    let mut score = post * post / cap;

    // Smooth interaction: dead space matters more as the stream progresses.
    score += 6.0 * (post / cap) * (post / cap) * progress * (1.0 + progress);

    // Reward tight fits (small post residual) more strongly late in the stream.
    score -= (1.0 - post / cap) * (1.0 - post / cap) * 4.0 * (0.5 + progress);

    // Last-chance bonus: strongly favor the only bin that fits (smooth in fit count).
    score -= 12.0 / fit;

    // Penalize bins whose residual deviates from the mean residual (fragmentation),
    // with a smooth quadratic coupling.
    let dev = (post - mean_r) / cap;
    score += 3.0 * dev * dev * (1.0 + progress);

    // Lookahead coupling: reward if the next item fits the post residual smoothly.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let room = post - nx;
        if room >= 0.0 {
            score -= 2.0 * (1.0 - (room / cap).abs()) * progress;
        } else {
            score += 1.5 * (-room / cap) * (1.0 + progress);
        }
    }

    // Mild penalty for spreading across many open bins (encourage consolidation),
    // smoothly scaled with stream progress.
    score += 0.05 * open_bins_count as f64 * progress;

    // New-bin candidate adjustment: empty bin has full residual; make it attractive
    // only when the current item would leave a large awkward residual elsewhere.
    if bin_residual == bin_capacity {
        let awkwardness = (post_residual as f64) / cap;
        score = 25.0 + 10.0 * (1.0 - awkwardness) - 8.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues mod 10 create "dead zones"
    let post_class = (post_residual % 10) as f64;
    score += post_class * 0.8;

    // Perfect or near-perfect fit rewards (integer division thresholds)
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 3 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // Dead-space penalty: post residual too small for the smallest future item (1..100, min realistic 10)
    if post_residual > 0 && post_residual < 10 {
        score += 35.0;
    }

    // Compatibility with lookahead item: can next item fit exactly into post residual?
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_fit = post_residual - next_item_size;
        // harmonic class match: next item lands on a "nice" boundary
        let next_class = (next_fit % 10) as f64;
        score -= 18.0 - next_class * 0.5;
        if next_fit == 0 {
            score -= 30.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // post residual too small for next item -> likely dead space
        score += 12.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fits are poor
    if bin_residual == bin_capacity {
        score += 30.0;
        // allow new bin if best existing option would leave large waste
        if post_residual >= bin_capacity - item_size && item_size <= 20 {
            score -= 15.0;
        }
        // fewer open bins -> opening is cheaper
        score -= open_bins_count as f64 * 0.5;
    }

    // Fraction of capacity used: reward high utilization
    let used_frac = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= used_frac * 8.0;

    // Late in stream: consolidation matters more
    let progress = step_index as f64 / total_items as f64;
    score *= 1.0 + 0.25 * progress;

    // Mean residual coupling: prefer bins below mean residual (tighter packing)
    score += (mean_residual - post_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable gaps strongly (dead space avoidance)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Reward near-perfect fits
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward bins that can also fit the next item after placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: when many bins are open, prefer filling existing ones
    let pressure = open_bins_count as f64 / 8.0;
    score += pressure * 5.0;

    // Slight bias against opening a new bin mid-stream
    if bin_residual == bin_capacity {
        score += 15.0 + step_index as f64 * 0.05;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins)
    score += (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), but weight by waste ratio.
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * waste_ratio * waste_ratio;

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0;
            // Extra reward if the pair nearly fills the bin (perfect 2-item packing).
            let pair_fill = (item_size + next_item_size) as f64 / bin_capacity as f64;
            if pair_fill > 0.9 {
                score -= 20.0;
            } else if pair_fill > 0.7 {
                score -= 8.0;
            }
        } else {
            // Dead space relative to the next item: penalize proportionally.
            let gap = (post_residual - next_item_size.saturating_sub(1)) as f64;
            score += 0.5 * gap.min(post_residual as f64);
            // If next item exactly matches post_residual in a future bin, don't over-penalize here.
            if post_residual < next_item_size && post_residual <= 10 {
                score += 5.0; // tiny dead space is bad
            }
        }
    }

    // Compare against mean residual: bins below mean are already tight; favor them less waste.
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 2.0 * ((bin_residual as f64 - mean_residual) / bin_capacity as f64).min(1.0);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // New-bin candidate handling: make empty bins unattractive unless the fit is hopeless.
    if bin_residual == bin_capacity {
        score += 45.0;
        // But if this is the only option (no open bin fits), opening is fine.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        // Late in the stream, opening fresh bins can be cleaner for lookahead chains.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if next_item_size > 0 && post_residual >= next_item_size && post_residual as f64 > mean_residual * 1.5 {
            score -= 10.0 * progress;
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.15 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item nearly fills the residual.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Penalize large dead space relative to the smallest possible future item.
    if post_residual > 0 {
        let waste = post_residual as f64 / bin_capacity as f64;
        score += 20.0 * waste * waste;
    }

    // Perfect fit is golden.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_fit = next_item_size as f64 / post_residual as f64;
        score -= 25.0 * next_fit;
        if post_residual == next_item_size {
            score -= 40.0;
        }
    } else if next_item_size > 0 && next_item_size <= item_size.max(1) {
        // Next item can't use the leftover; penalize leftover proportional to next item size.
        score += 5.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate logic: opening a new bin should only win when current fits are poor.
    if bin_residual == bin_capacity {
        // Baseline cost of a fresh bin: its "waste" is capacity - item_size.
        score = (bin_capacity - item_size) as f64 + 10.0;
        // Early in the stream, opening bins is cheaper (exploration).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 15.0 * (1.0 - progress);
        // Few open bins -> favor consolidation instead; penalize new bin.
        score += 3.0 * open_bins_count as f64;
        // If mean residual across open bins is small (all bins nearly full), new bin is attractive.
        score -= 0.5 * (bin_capacity as f64 - mean_residual).max(0.0);
        // If next item is large, a fresh bin with room is valuable.
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 20.0;
        }
    }

    // Time horizon: late in the stream, be conservative — favor tight existing fits more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.3 * progress;

    // Mild penalty for spreading across many bins when mean residual is high (fragmentation).
    if mean_residual > 30.0 && post_residual > 0 && bin_residual < bin_capacity {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress:
    // residual waste matters more as the stream matures.
    let prn = pr / cap;
    score += prn * prn * (1.0 + progress) * 30.0;
    score -= prn * prn * prn * (1.0 - progress) * 10.0;

    // Last-chance bonus: if this is the only bin that fits, strongly favor it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0 + 30.0 * progress;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let tight = 1.0 - ((pr - nxt) / cap).abs();
            score -= 15.0 * tight * (1.0 - progress * 0.5);
        } else {
            score += 8.0 * (1.0 - pr / cap);
        }
    }

    // Penalize deviation from mean residual (prefer balanced bins early, tight fits late).
    let dev = (pr - mean_residual).abs() / cap;
    score += dev * (20.0 - 10.0 * progress);

    // New-bin candidate: prefer opening a new bin only when it is early in the stream
    // or post-residual of placing here would be very tight/dead space.
    if bin_residual == bin_capacity {
        let dead = prn * prn * 50.0;
        score += 5.0 + 25.0 * progress - dead;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: dead space is worse when it falls into
    // "awkward" classes relative to typical item sizes (multiples of 10).
    let class = post_residual % 10;
    score += (class as f64) * 1.7;

    // Reward residuals that remain usable by common item sizes (>= 10).
    if post_residual < 10 && post_residual > 0 {
        score += 25.0; // tiny dead space
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // relative to residual and current bins are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score += 90.0
            - 45.0 * (item_size as f64 / bin_capacity as f64)
            - 20.0 * fragmentation / bin_capacity as f64
            - 15.0 * progress;
    } else {
        // Prefer bins whose residual tightly matches the item (waste penalty).
        let waste = (bin_residual - item_size) as f64;
        score += waste * 0.15;
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // reward this placement (chains well).
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_fit = post_residual - next_item_size;
        score -= (next_fit == 0) as i32 as f64 * 40.0;
        score -= (next_fit % 10 == 0) as i32 as f64 * 12.0;
    }
    // Penalize if next item cannot fit anywhere after this placement.
    if next_item_size > post_residual && fitting_bins_count <= 1 {
        score += 10.0;
    }

    // Harmonic modulo threshold on post_residual: multiples of 25 are
    // attractive residual states (quarter-capacity classes).
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 8.0;
    }

    // Mild pressure to consolidate when many bins are open.
    score += (open_bins_count as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let cap_safe = if cap_f > 0.0 { cap_f } else { 1.0 };
    let item = item_size as f64;
    let post = post_residual as f64;
    let next = next_item_size as f64;
    let open = open_bins_count as f64;
    let fitting = fitting_bins_count as f64;

    let progress = if total_items == 0 {
        0.0
    } else {
        (step_index as f64 / total_items as f64).clamp(0.0, 1.0)
    };
    let mean_frac = (mean_residual / cap_safe).clamp(0.0, 1.0);
    let is_new_bin = bin_residual == bin_capacity;

    // Convex dead-space base: smaller leftovers are strongly preferred.
    let mut score = post * (post + 8.0) / cap_safe;

    // Closing a bin exactly is highly desirable, especially when many bins are open.
    if post_residual == 0 {
        score -= 30.0 + 0.30 * open + 8.0 * mean_frac;
    }

    // Practical unusable-gap threshold; the lookahead item can relax it when it is tiny.
    let absolute_floor = 10.0 + 3.0 * mean_frac;
    let dead_floor = if next_item_size > 0 {
        absolute_floor.min(next).max(1.0)
    } else {
        absolute_floor
    };

    if post_residual > 0 && post < dead_floor {
        let depth = dead_floor - post;
        score += 28.0 + 3.5 * depth + 8.0 * mean_frac;
    }

    // Lookahead coupling: reward bins whose residual remains useful for the next item.
    if next > 0.0 {
        if post_residual > 0 {
            if post + 0.5 < next {
                score += 7.0 + 0.45 * (next - post).min(cap_safe);
            } else if (post - next).abs() <= 0.5 {
                score -= 24.0 + 5.0 * mean_frac + 0.15 * open;
            } else {
                score -= 3.0 + 0.04 * next;
            }
        }
    } else if is_new_bin && fitting_bins_count > 0 {
        // On the final item, never prefer a new bin when an open bin can fit.
        score += 500.0 + 10.0 * open;
    } else if !is_new_bin {
        score -= 120.0;
    }

    // Last-chance consolidation, unless the created gap is dead or breaks the lookahead.
    if !is_new_bin && fitting_bins_count == 1 {
        let preserves_lookahead = next_item_size == 0
            || post_residual == 0
            || post + 0.5 >= next;

        if preserves_lookahead {
            score -= 22.0 + 1.1 * open + 8.0 * progress;
        } else if post >= dead_floor {
            score -= 6.0;
        } else {
            score -= 3.0;
        }
    }

    // Opening pressure: discourage a new bin when many bins are already open,
    // when open bins have ample residual, or when the stream is near its end.
    if is_new_bin {
        if fitting_bins_count > 0 {
            score += 14.0
                + 1.5 * open
                + 2.0 * fitting.min(8.0)
                + 14.0 * mean_frac
                + 10.0 * progress;

            if next > 0.0 && post + 0.5 >= next {
                score -= 6.0;
            }
        } else {
            score -= 25.0;
        }
    } else {
        score -= 0.05 * open + 0.02 * item;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size exactly
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual >= next_item_size {
            // next item fits exactly or nearly: strong reward
            if gap == 0.0 {
                score -= 800.0;
            } else {
                score -= 200.0 / (1.0 + gap);
            }
        } else {
            // next item will NOT fit in this residual: penalize leaving such awkward space
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Penalize wasting large residuals on small items (dead space creation)
    if post_residual > 0 && post_residual < 10 {
        score -= 50.0; // tiny dead space is fine, it's unusable anyway
    } else if post_residual >= 10 && post_residual < 25 {
        score += 20.0; // awkward mid-range dead space
    }

    // New-bin candidate: penalize opening a new bin unless residuals are all tight
    if bin_residual == bin_capacity {
        let avg_tightness = mean_residual / bin_capacity as f64;
        score += 80.0 * (1.0 - avg_tightness);
        if fitting_bins_count == 0 {
            score -= 500.0; // nothing fits, must open
        }
    }

    // Late in stream: consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 30.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits: small post_residual is valuable dead-space avoidance.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize unusable small leftover space (below typical minimum item size ~ 10).
    if post_residual < 10 {
        score += 12.0 * (10 - post_residual) as f64;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let next_tight = 1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64);
            score -= 10.0 * next_tight;
        } else if post_residual > 0 {
            // Next item cannot use this leftover space -> mild penalty proportional to leftover.
            score += 0.08 * post_residual as f64;
        }
    }

    // Last chance: if this is the only fitting bin, strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Prefer bins below mean residual (use the "less crowded" space first) when many bins open.
    if open_bins_count > 1 {
        let diff = mean_residual - bin_residual as f64;
        score += 0.05 * diff;
        // Mild pressure to consolidate when too many bins are open.
        score -= 0.02 * open_bins_count as f64 * tightness;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive for large items
    // late-ish in the stream or when it enables a perfect future pairing.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let base = 20.0 - 10.0 * progress;
        let pair_bonus = if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            6.0 * (1.0 - ((item_size + next_item_size) as f64 / bin_capacity as f64))
        } else {
            0.0
        };
        score += base - pair_bonus;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let prn = pr / cap;

    // Smoothly increasing penalty for large post-residuals as stream advances.
    let progress_coupling = prn * prn * (0.5 + progress) * cap;
    score += 0.35 * progress_coupling;

    // Reward tight fits with a smooth cubic term.
    let tightness = 1.0 - prn;
    score -= 12.0 * tightness * tightness * tightness * (1.0 + progress);

    // Penalize creating dead space that cannot fit the next item (smooth interaction).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).max(0) as f64;
        let gapn = gap / cap;
        score += 8.0 * gapn * gapn * (0.5 + progress);
    }

    // Last-chance bonus: strongly prefer using a bin when alternatives are scarce.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - prn);
    }

    // Mild penalty for opening new bins late in the stream.
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * progress;
    }

    // Coupling with mean residual: prefer bins deviating smoothly from the mean.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 3.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: how "reusable" is post_residual?
    // Residuals divisible by small item sizes (10..=25) are highly reusable.
    let pr = post_residual;
    let mut reusability = 0.0;
    for m in [10u32, 20, 25, 50] {
        if m > 0 && pr % m == 0 && pr > 0 {
            reusability += 12.0;
        }
    }
    // Class based on integer division: which small item still fits exactly?
    let class_bucket = pr / 10; // 0..10 harmonic decade
    score -= reusability;
    score -= (class_bucket as f64) * 0.5;

    // Penalize dead space: tiny unusable residuals (1..10) are worst.
    if pr > 0 && pr < 10 {
        score += 25.0;
    }

    // Perfect fit reward.
    if pr == 0 {
        score -= 100.0;
    }

    // Last-chance bin: strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 60.0;
        } else if next_item_size <= pr {
            score -= 5.0;
        } else {
            // Next item won't fit here; mildly penalize wasting this bin's space.
            score += 3.0;
        }
    }

    // New-bin candidate: only attractive when current bin fit is poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin; offset by how many bins it may serve.
        score += 30.0;
        if open_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
        // If mean residual across open bins is large, prefer reusing them.
        score += (mean_residual / bin_capacity as f64) * 60.0;
        // Late in the stream, opening fresh bins is cheaper (fewer future items).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 15.0;
    }

    // Prefer tighter bins generally (small residual before placement).
    score += (bin_residual as f64) * 0.05;

    // Harmonic modulo penalty on item class vs residual class mismatch.
    if (item_size % 10) != (bin_residual % 10) && bin_residual != bin_capacity {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space more aggressively than large residuals.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 25 {
        score += 15.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward tight fits relative to residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fit_ratio;

    // Pressure from number of open bins: prefer reusing bins when many are open.
    score += 2.5 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 45.0;
    }
    // Penalize leaving a residual that neither fits the next item usefully nor is zero.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 30.0;
    }

    // New-bin candidate: make it moderately attractive only when fits are poor.
    if bin_residual == bin_capacity {
        // Base new-bin score: slightly above a good fit, below a bad fit.
        score = 70.0 + 0.3 * mean_residual;
        if fitting_bins_count == 1 {
            // Opening a new bin when only one bin fits is usually wasteful.
            score += 80.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize dead space that is too small to be useful (below min item size ~1..100 unknown, use 10 as safe floor but scale).
    let dead_threshold = 10.0;
    if (post_residual as f64) < dead_threshold {
        score += 50.0;
    } else {
        // Mild superlinear penalty on wasted residual
        score += (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64);
    }

    // 2-step lookahead: strongly reward bins whose post_residual exactly or nearly fits next_item_size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) >= nxt {
            let gap = (post_residual as f64) - nxt;
            // Perfect match for next item: big reward
            score -= 40.0 * (1.0 - gap / bin_capacity as f64);
            if gap == 0.0 {
                score -= 30.0;
            }
        } else {
            // Next item won't fit here; penalize proportionally to shortfall
            score += 0.5 * (nxt - post_residual as f64);
        }
    }

    // Compare against mean residual: bins tighter than average are precious.
    if (bin_residual as f64) < mean_residual {
        score += 8.0;
    } else {
        score -= 4.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Late in stream: consolidate, avoid opening new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses
        score += 15.0 + 40.0 * progress;
    } else {
        score -= 10.0 * progress;
    }

    // Prefer packing into nearly-full bins (best-fit reinforcement)
    score -= (bin_capacity as f64 - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits: small post_residual is good, but
    // residuals below 10 are dead space (min item is 10 in classic streams;
    // for general 1..100 streams, treat <5 as dead).
    let dead_threshold = 5.0;
    if (post_residual as f64) < dead_threshold {
        score += 25.0; // penalize creating unusable sliver
    } else {
        // reward near-perfect fills
        score -= (bin_capacity as f64 - post_residual as f64) * 0.35;
    }

    // Perfect fill bonus
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin wastes the residual
    // of this bin. Penalize new bins more when existing residual is large.
    if bin_residual == bin_capacity {
        score += 40.0 + mean_residual * 0.6;
        // early in the stream, opening bins is cheaper (more items to come
        // that may fill them)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 20.0;
        // if the next item is large, a fresh bin is more valuable
        score -= (next_item_size as f64 / bin_capacity as f64) * 15.0;
    }

    // Lookahead synergy: if next item fits exactly in post_residual,
    // this placement is excellent.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 50.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // partial synergy: prefer leaving space usable by the next item
        score -= 8.0;
    } else if next_item_size > post_residual {
        // next item won't fit here anyway; slight penalty for wasting space
        score += 5.0;
    }

    // Prefer bins with residual far from mean (spread out fills) mildly
    score += (bin_residual as f64 - mean_residual).abs() * 0.05;

    // Many open bins: encourage consolidating into existing bins
    score += open_bins_count as f64 * 0.3;

    // Mild preference for filling fuller bins first (best-fit style)
    score += (bin_capacity as f64 - bin_residual as f64).abs() * 0.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (low post residual), with smooth non-linear shaping.
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Polynomial coupling with stream progress: late in the stream, dead space hurts more.
    let progress_coupling = norm_pr * (1.0 - norm_pr);
    score -= 12.0 * progress * progress_coupling;
    score += 20.0 * progress * norm_pr * norm_pr * norm_pr;

    // Penalize bins whose residual drifts far from the mean (fragmentation signal).
    let drift = (pr - mean_residual).abs() / cap;
    score += 10.0 * drift * drift * (0.5 + progress);

    // Lookahead: reward leaving room for the next item; penalize if next item won't fit.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 8.0 * (1.0 - (pr - nxt) / cap);
        } else {
            score += 6.0 * (nxt - pr) / cap;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - progress * 0.5);
    }

    // Mild penalty for spreading across many open bins when plenty of room exists.
    let open_norm = open_bins_count as f64 / (1.0 + open_bins_count as f64);
    score += 3.0 * open_norm * norm_pr;

    // New-bin candidate: make empty bins attractive only when current fit is poor.
    if bin_residual == bin_capacity {
        score = pr + 18.0 - 25.0 * (1.0 - norm_pr) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues modulo 10 create
    // "compatibility classes" with future small items (sizes 1..100).
    let post_class = (post_residual % 10) as f64;
    let next_class = (next_item_size % 10) as f64;

    // Reward exact harmonic match: post residual whose class equals the
    // next item's class means the next item could perfectly fill the gap
    // (mod 10 alignment correlates with tight future packing).
    if next_item_size > 0 && post_residual >= next_item_size {
        let class_match = 10.0 - (post_class - next_class).abs();
        score -= 1.5 * class_match;
        // Perfect fill: next item exactly consumes the residual.
        if post_residual == next_item_size {
            score -= 30.0;
        }
    }

    // Penalize dead space that no plausible item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Integer-division thresholds on post_residual: coarse capacity fractions.
    let quarters = post_residual / (bin_capacity / 4);
    score -= 2.0 * quarters as f64;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: keep it neutral-to-slightly-expensive so it only
    // wins when open bins would create bad dead space.
    if bin_residual == bin_capacity {
        score += 8.0;
        // Early in the stream, having fresh bins is cheap; later, prefer reuse.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * (1.0 - progress);
        // If the next item is large and this bin would be fresh, a fresh bin
        // gives flexibility for the lookahead.
        if next_item_size > bin_capacity / 2 {
            score -= 10.0;
        }
    }

    // Prefer bins whose residual deviates favorably from the mean
    // (tighter-than-average bins get used first, consolidating space).
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Small bonus for closing a bin nearly perfectly (residual in a
    // low-value harmonic band: 1..9 unusable slivers already penalized;
    // here reward near-full fills).
    if post_residual <= 5 {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64) / 10.0;
    }
    // Perfect fit is strongly rewarded
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward bins whose residual exactly accommodates the item (tight fit)
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.1;

    // Lookahead coupling: if the next item fits the post-residual, reward
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // next item cannot use the leftover gap -> dead space likely
        score += 8.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones;
    // a new bin candidate (residual == capacity) gets penalized more.
    if bin_residual == bin_capacity {
        score += 5.0 + 2.0 * open_bins_count as f64;
    } else {
        score -= 0.5 * open_bins_count as f64;
    }

    // Prefer bins with below-mean residual (consolidate fullness)
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Slight progression term: later in stream, be more conservative about new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // Aggressive 2-step lookahead: if next item fits exactly in post_residual, huge reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 900.0;
        } else if next_item_size < post_residual {
            let leftover = post_residual - next_item_size;
            if leftover <= 10 {
                score -= 250.0;
            } else {
                score -= 60.0 * (1.0 - leftover as f64 / bin_capacity as f64);
            }
        } else {
            // Next item won't fit here; penalize wasting a large bin on a small item.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.5 * waste;
        }
    }

    // Relative to mean residual: prefer bins tighter than average.
    score += 0.6 * (mean_residual - bin_residual as f64).max(-50.0);

    // Last-chance bonus: only bin that fits the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 400.0;
    }

    // Penalize opening a new bin unless it enables a great lookahead pairing.
    if bin_residual == bin_capacity {
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            let pair_left = bin_capacity - item_size - next_item_size;
            if pair_left <= 10 {
                score -= 300.0;
            }
        }
        score += 50.0;
    }

    // Late in stream: consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 30.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins whose post residual is small.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio).powi(3) * 30.0;

    // Penalize dead space that can never be filled by typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    }

    // Lookahead coupling: reward bins whose post residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 * (next_item_size as f64 / 100.0 + 0.5);
        } else {
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when the item is large
    // relative to capacity or the current bin would leave big waste.
    if bin_residual == bin_capacity {
        let waste_here = (bin_capacity - item_size) as f64;
        let best_open_waste = if fitting_bins_count > 0 {
            (bin_residual - item_size) as f64
        } else {
            waste_here
        };
        // Prefer new bin when opening it wastes less than squeezing into an open bin
        // would, or when open bins are already fragmented (high mean residual spread).
        let fragmentation = (mean_residual - (bin_residual as f64)).abs();
        score += 15.0; // base penalty for opening a new bin
        score -= waste_here * 0.25; // large items leave less waste in fresh bin
        if best_open_waste > waste_here + 10.0 {
            score -= 18.0; // open bins would waste much more
        }
        if fragmentation > 20.0 {
            score -= 5.0;
        }
    }

    // Time horizon: early in the stream, be conservative (favor new bins less);
    // late in the stream, squeeze harder into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 6.0 * (1.0 - fit_ratio);
    score += (1.0 - progress) * 4.0 * (open_bins_count as f64 / (total_items.max(1) as f64)).min(1.0);

    // Mild penalty for using bins whose residual deviates far from mean (keeps pool balanced).
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let pr = post_residual as f64;
    let pr_norm = pr / bin_capacity as f64;
    let coupling = pr_norm * pr_norm * (0.5 + progress) + pr_norm * progress * progress;
    score += 30.0 * coupling;

    // Reward tight fits more strongly as the stream progresses.
    let fit_quality = 1.0 - pr_norm;
    score -= fit_quality * fit_quality * (10.0 + 20.0 * progress);

    // Penalize dead space that cannot fit the next item (lookahead coupling).
    if next_item_size > 0 && post_residual > 0 {
        let ni = next_item_size as f64;
        if pr < ni {
            let waste = (ni - pr) / bin_capacity as f64;
            score += 25.0 * waste * (1.0 + progress);
        } else {
            let snug = (ni / pr).min(1.0);
            score -= 8.0 * snug * snug;
        }
    }

    // Last-chance bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    } else {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Mild penalty for scattering across many open bins relative to mean residual.
    score += 0.05 * (open_bins_count as f64) * ((pr - mean_residual).abs() / bin_capacity as f64);

    // New-bin candidate: make it attractive only when open bins fit poorly.
    if bin_residual == bin_capacity {
        let poor_fit = fitting_bins_count == 0;
        let pressure = if poor_fit { 1.0 } else { (pr_norm * 0.5) };
        score = bin_capacity as f64 - 20.0 * pressure - 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: bins whose post_residual falls into
    // "dead zones" (too small for typical small items) are heavily penalized.
    let cap_f = bin_capacity as f64;
    let post_f = post_residual as f64;

    // Class by integer division on post_residual: 0..10 unusable, 10..25 poor, etc.
    let class = post_residual / 10; // 0..=10 harmonic buckets
    match class {
        0 => score += 60.0,               // nearly full: great, but reward below
        1 => score += 25.0,               // dead space 10..19: hard to fill
        2 => score += 12.0,               // 20..29
        3 => score += 5.0,
        4 => score += 0.0,
        _ => score -= 4.0,                // roomy leftovers stay attractive
    }

    // Perfect / near-perfect fits get a strong pull.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 50.0;
    } else if post_residual <= 10 {
        score -= 20.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // reward heavily; if next item cannot fit anywhere else, this bin matters.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size < post_residual && post_residual - next_item_size <= 10 {
            score -= 30.0;
        } else if next_item_size > post_residual && next_item_size <= bin_residual {
            // next item fits current residual but not post: placing here kills that option
            score += 15.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0 + post_f / cap_f * 20.0;
    }

    // New-bin candidate: prefer keeping it closed unless open bins are fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_f).abs();
        score += 30.0 + fragmentation * 0.5;
        // Early in the stream a fresh bin is cheap; late, consolidation wins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (1.0 - progress) * 10.0 - progress * 5.0;
    }

    // Mild pressure toward bins tighter than the mean residual (best-fit flavor).
    score += (post_f - mean_residual) * 0.3;

    // Modulo harmonic: leftovers that are multiples of common small items (10, 20, 25)
    // are more reusable.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps below the smallest plausible item (<=12)
    // are essentially unusable; penalize them quadratically.
    if post_residual < 12 {
        score += (12.0 - post_residual as f64) * (12.0 - post_residual as f64) * 4.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 6 {
        score -= 25.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, reward heavily.
    if next_item_size > 0 && post_residual > 0 && next_item_size == post_residual {
        score -= 45.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // next item fits: mild reward proportional to how well it uses the gap
        score -= 10.0 * (next_item_size as f64 / post_residual as f64);
    } else if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
        // next item cannot use the leftover: penalize large dead space
        score += 8.0 * (next_item_size as f64 - post_residual as f64).min(30.0);
    }

    // Open-bin pressure: discourage proliferating bins when residual space is ample.
    if bin_residual != bin_capacity {
        score -= open_bins_count as f64 * 0.8;
        // Prefer bins below mean residual (fill emptier bins first) mildly.
        score += (mean_residual - bin_residual as f64) * 0.15;
    } else {
        // New-bin candidate: penalize slightly so it only wins on bad fits,
        // but relax the penalty as stream progresses (early bins cheap to open).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 - 6.0 * progress;
        // If many bins are open, prefer reusing them over a new bin.
        score += open_bins_count as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact/next-item matches.
    if next_item_size > 0 && next_item_size <= post_residual {
        // Next item fits perfectly into the post residual -> strong reward.
        let perfect = (post_residual as f64 - next_item_size as f64).abs();
        score -= 30.0 - perfect.min(30.0);
        // Reward proportional to how much of the bin the pair consumes.
        let pair_fill = (item_size + next_item_size) as f64 / bin_capacity as f64;
        score -= 20.0 * pair_fill;
    } else if next_item_size > 0 {
        // Next item cannot follow: penalize wasted potential.
        let waste = next_item_size as f64 - post_residual as f64;
        score += 8.0 * (waste / bin_capacity as f64).min(1.0);
    } else {
        // Last item: prefer tightest fit.
        score -= 15.0;
    }

    // Reward using bins with small residual relative to mean (consolidation).
    let mean_gap = mean_residual - bin_residual as f64;
    score += 0.15 * mean_gap;

    // Last-chance bin bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when open bins could fit reasonably well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 35.0 - 10.0 * progress;
        if fitting_bins_count > 0 {
            score += 20.0;
        }
    }

    // Mild penalty for leaving tiny unusable dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Slight normalization of post residual by capacity.
    score += 0.05 * (post_residual as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual, non-linear).
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    score += 0.35 * (post / cap) * (1.0 - post / cap) * cap; // hump: mid residuals penalized most

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 + 0.05 * next_item_size as f64;
        } else {
            // Dead space relative to the next item.
            score += 0.15 * (next_item_size as f64 - post as f64).max(0.0);
        }
    } else {
        // Last item: prefer exact closure.
        score += 0.5 * post;
    }

    // Last chance: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Crowding: when many bins are open, prefer filling existing ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 0.4 * (open_bins_count as f64).ln().max(0.0) * (1.0 - progress);

    // Prefer bins with residual below the current mean (consolidate small gaps).
    score += 0.2 * (bin_residual as f64 - mean_residual);

    // New-bin candidate: only attractive when the item is large or fits are scarce.
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 1.0 / (fitting_bins_count as f64) };
        let largeness = item_size as f64 / cap;
        let new_bin_score = cap - item_size as f64 - 18.0 * largeness - 10.0 * scarcity - 8.0 * progress;
        // Blend: make new bin competitive only when its natural score is low.
        score = score.min(new_bin_score + 4.0 * (1.0 - largeness));
        if fitting_bins_count > 0 && largeness < 0.5 {
            score += 8.0; // discourage opening new bins for small items when alternatives exist
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic penalty on wasted space, amplified by stream progress.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let waste = post_residual as f64 / cap;
    score += waste * waste * cap * (0.5 + progress);

    // Reward near-perfect fills strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Lookahead: penalize leaving a gap that neither fits the next item nor is tiny.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) >= nxt {
            // gap usable by next item: mild reward, scaled by how snugly it fits
            let snug = 1.0 - ((post_residual as f64 - nxt) / cap);
            score -= 8.0 + 12.0 * snug * snug;
        } else {
            // dead space for the known next item
            score += 10.0 + 15.0 * (1.0 - progress);
        }
    } else {
        // last item: strongly prefer filling existing bins completely
        score -= 30.0;
    }

    // Last-chance bin: if this is the only fitting bin, discourage opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Prefer bins with residuals below the mean (compact fragmentation),
    // penalize dipping into large-residual bins unnecessarily.
    if bin_residual < bin_capacity {
        let dev = mean_residual - bin_residual as f64;
        score += 0.05 * dev;
    }

    // Mild pressure toward consolidating into fewer bins as stream progresses.
    score += progress * (open_bins_count as f64) * 0.15;

    // New-bin candidate: make it attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        let poor_fit_elsewhere = fitting_bins_count == 0
            || (post_residual as f64) < (next_item_size as f64) * 0.5;
        if poor_fit_elsewhere {
            score -= 15.0;
        } else {
            score += 40.0 + 30.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: which "slot band" the leftover falls into.
    // Capacity 100 -> classes of 10. Small class index = tight fit = good.
    let class = (post_residual / 10) as f64;

    // Reward tight fits strongly (non-linear in class).
    score -= 60.0 / (1.0 + class * class);

    // Penalize dead space that is too small to be useful for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0; // perfect chained fit
        } else if next_item_size <= post_residual {
            let next_left = post_residual - next_item_size;
            // harmonic class of the residual after the next item
            let nclass = (next_left / 10) as f64;
            score -= 40.0 / (1.0 + nclass * nclass);
            if next_left < 10 {
                score += 15.0; // tiny unusable crumb after chaining
            }
        } else {
            // next item won't fit here; mild penalty proportional to overshoot class
            let over = (next_item_size - post_residual) / 10;
            score += over as f64 * 6.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 55.0;
    }

    // New-bin candidate: neutral-ish baseline, but discourage when a decent fit exists.
    if bin_residual == bin_capacity {
        // opening new bin is fine early or when many bins are open and this is a big item
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 - 20.0 * progress;
        if item_size >= bin_capacity / 2 {
            score -= 15.0; // big items pair well in a fresh bin
        }
    }

    // Prefer bins whose residual deviates from the mean less (keeps bin states uniform).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Mild penalty for spreading across too many open bins.
    score += (open_bins_count as f64) * 0.3;

    // Fraction-of-capacity harmonic term on item size (integer division thresholds).
    let size_class = item_size / 25; // 0..3
    score -= size_class as f64 * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that can never host the smallest item (1..10)
    // are pure waste; penalize them quadratically.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + 8.0 * (10 - post_residual) as f64;
    }

    // Reward tight fits (small but usable post_residual).
    if post_residual >= 10 && post_residual <= 25 {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // rather than spreading; makes new-bin candidate less attractive.
    score += 2.5 * open_bins_count as f64;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (avoids wasting the remaining space).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when mean residual of open bins is
    // too small to host the upcoming item; otherwise penalize opening.
    if bin_residual == bin_capacity {
        score += 25.0;
        if mean_residual < next_item_size as f64 && next_item_size > 0 {
            score -= 20.0;
        }
        if open_bins_count == 0 {
            score -= 100.0; // must open first bin
        }
    }

    // Lookahead: if next item would fit exactly in the post residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: dead space zero is ideal.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Aggressive 2-step lookahead: if next item exactly fills the post residual,
    // this placement is excellent.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 80.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Next item can still fit here: mild reward proportional to leftover.
        score -= 10.0;
    } else if next_item_size > 0 {
        // Next item cannot fit: penalize proportional to wasted potential.
        score += (next_item_size as f64 - post_residual as f64) * 0.5;
    }

    // Compare post_residual against mean residual: leaving near-mean residual
    // keeps the bin pool flexible.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize opening a new bin early when good open bins exist; encourage it
    // late in the stream or when few bins fit (poor fits elsewhere).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * (1.0 - progress);
        if fitting_bins_count > 2 {
            score += 25.0;
        }
    }

    // Small bonus for larger items placed in tighter bins (tight fit preference).
    score -= (item_size as f64 / bin_capacity as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual already the base; amplify it)
    if post_residual == 0 {
        score -= 50.0; // perfect fit is excellent
    } else if post_residual <= 5 {
        score -= 20.0;
    } else if post_residual <= 10 {
        score -= 8.0;
    }

    // Penalize dead space that can never be reused by typical items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver below min item size (interface: min 1)
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // mild penalty so tight-fit among many candidates wins naturally
        score += 2.0 * (fitting_bins_count as f64).min(5.0);
    }

    // Lookahead: if the next item fits in the post-residual, reward this placement
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            score -= 10.0 + (slack as f64).min(30.0) * 0.2;
        } else {
            // next item won't fit here; slight penalty proportional to waste
            score += 5.0;
        }
    }

    // Global state coupling: prefer filling bins when mean residual is high (fragmentation risk)
    score += (mean_residual - post_residual as f64).max(0.0) * 0.15;

    // Time horizon: early in the stream, be more willing to open bins (score new bin lower);
    // late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open or early on,
        // reward slightly when progress is high and no good fit exists.
        score += 40.0 - 25.0 * progress + (open_bins_count as f64) * 0.5;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
    } else {
        // Existing bin: reward using it more as stream progresses
        score -= 10.0 * progress;
    }

    // Mild preference for bins with larger residual (keeps small bins for small items)
    score -= (bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    // Base: penalize post residual, with non-linear (quadratic/cubic) growth
    let mut score = pr * (1.0 + norm_pr * norm_pr);

    // Smooth coupling: small post residuals are valuable early, wasted late
    let tight_fit_bonus = (1.0 - norm_pr).powi(3);
    score -= tight_fit_bonus * (20.0 + 30.0 * progress);

    // If next item fits the post residual, reward this bin strongly
    if next_item_size > 0 && next_item_size <= post_residual {
        let snug = 1.0 - ((post_residual - next_item_size) as f64 / cap);
        score -= 15.0 + 25.0 * snug * (0.5 + 0.5 * progress);
    } else if next_item_size > 0 {
        // next item won't fit here: penalize proportionally to how much it overshoots
        let overshoot = (next_item_size - post_residual) as f64 / cap;
        score += 10.0 * overshoot * overshoot;
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 12.0 + 18.0 * (1.0 - progress);
    }

    // Penalize bins far from mean residual (smooth dispersion penalty)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev * dev * (1.0 - progress);

    // Mild reward for consolidating into many-open-bins regime
    score -= (open_bins_count as f64).ln().max(0.0) * (1.0 - norm_pr) * 2.0;

    // New-bin candidate: only attractive when item is huge relative to capacity
    if bin_residual == bin_capacity {
        score = cap - pr; // = 0 for empty bin baseline
        score += 40.0 * (1.0 - norm_item) * (1.0 - progress);
        if fitting_bins_count > 1 {
            score += 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals in "usable" classes
    // (small residuals = tight fit; residuals matching common item sizes = reusable).
    let pr = post_residual;
    let q = pr / 10; // integer-division class (capacity 100 => classes 0..10)
    match q {
        0 => score -= 25.0,               // near-perfect fit, dead space minimal
        1 => score -= 18.0,               // residual 10-19: fits smallest items
        2 => score -= 12.0,               // residual 20-29
        3 => score -= 8.0,                // residual 30-39
        4 => score -= 4.0,                // residual 40-49
        5 => score -= 6.0,                // residual 50-59: half bin, quite reusable
        6 => score -= 2.0,
        7 => score += 3.0,                // 70-79: awkward, large item may not come
        8 => score += 1.0,
        _ => {}                            // 90+: nearly empty bin
    }

    // Modulo-10 harmony: residuals that are multiples of 10 align with typical sizes
    if pr % 10 == 0 && pr > 0 {
        score -= 5.0;
    }

    // Lookahead coupling: does next_item_size fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // exact or near-exact chain fit is gold
            let slack = pr - next_item_size;
            score -= 8.0 + (slack as f64).min(20.0) * 0.15;
            if pr % next_item_size.max(1) == 0 {
                score -= 4.0; // divisor harmony
            }
        } else {
            // next item won't fit here; penalize more if it's a big item
            score += (next_item_size - pr) as f64 * 0.10;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a bin is only good when the item is huge
    // or no open bin fits well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = (open_bins_count as f64) / (1.0 + mean_residual / 10.0);
        // base cost of a fresh bin
        score += 40.0;
        // early in stream or under high pressure, new bins are cheaper
        score -= 30.0 * (1.0 - progress) + pressure.min(20.0);
        if item_size > 70 {
            score -= 20.0; // big items justify fresh bins
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 10.0; // room for the chained pair
        }
    }

    // Waste ratio penalty: fraction of bin that will be dead
    let waste = post_residual as f64 / bin_capacity as f64;
    score += waste * waste * 10.0;

    // Mild tightness reward relative to item size
    score -= (item_size as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no plausible item can use are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 100.0;
    }

    // Reward tight fits generally (small relative waste).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * tightness;

    // Open-bin pressure: discourage spreading across many bins unless the fit is good.
    score += 2.0 * open_bins_count as f64 * (1.0 - tightness);

    // Mean residual coupling: if this bin's residual is far above average, mildly penalize.
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Lookahead: if the next item fits exactly into the post-residual, reward; if it wastes it, penalize slightly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size > post_residual {
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits, to avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: only attractive when current bins are heavily fragmented.
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64) * 3.0 + mean_residual * 0.2;
        score += 55.0 - pressure.min(55.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: exact or near-exact placement strongly preferred.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    } else if post_residual <= 15 {
        score -= 100.0;
    }

    // Aggressive 2-step lookahead: if the next item fits into the post residual,
    // this bin becomes a great two-item container.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 900.0; // perfect two-item pairing
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // Prefer leaving small slack after also placing the next item.
            score -= 400.0 - slack * 4.0;
        } else {
            // Next item won't fit here; penalize leaving a gap sized near the
            // next item (tempting but unusable dead space).
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 2.0;
        }
        // Bonus if next item is small relative to capacity (easy to top off).
        if next_item_size <= post_residual && post_residual as f64 <= mean_residual {
            score -= 50.0;
        }
    }

    // Relative-to-mean residual: bins with residual far below the mean are
    // "almost full" — favor using them up before opening/spreading elsewhere.
    let res = post_residual as f64;
    if res < mean_residual {
        score -= (mean_residual - res) * 1.5;
    } else {
        score += (res - mean_residual) * 0.8;
    }

    // Last-chance bin: if this is the only bin that fits the item, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: make an empty bin less attractive unless the item is
    // huge (would leave little room anyway) or nothing else fits well.
    if bin_residual == bin_capacity {
        let fill_frac = item_size as f64 / bin_capacity as f64;
        if fill_frac > 0.75 {
            score -= 350.0; // big item: fresh bin is fine
        } else if fitting_bins_count == 0 {
            score -= 500.0; // forced new bin
        } else {
            score += 250.0; // discourage premature bin opening
        }
    }

    // Late in the stream: consolidate aggressively, avoid new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.8 && bin_residual != bin_capacity {
        score -= 60.0 * progress;
    }

    // Mild penalty for spreading across many open bins.
    score += open_bins_count as f64 * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let mut score = post;

    // Reward tight fits: small post_residual relative to item size.
    score -= (item - post).max(0.0) * 0.5;

    // Penalize dead space that is too small for typical future items.
    if post > 0.0 && post < 10.0 {
        score += 25.0 * (10.0 - post) / 10.0;
    }

    // Lookahead coupling: if next item fits into post_residual, reward this bin.
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 8.0;
    } else if next_item_size > 0 && (next_item_size as f64) > post {
        // Post-residual useless for the known next item: mild penalty scaled by gap.
        score += ((next_item_size as f64) - post).min(30.0) * 0.15;
    }

    // Last-chance bonus: only fitting bin -> strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Time horizon: early in stream, be more willing to open new bins
    // (penalize using existing bins slightly less later on).
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: prefer early, or when open bins are fragmented.
        score = post - 12.0 * (1.0 - t);
        if open_bins_count as f64 > mean_residual / 10.0 {
            score += 5.0;
        }
        if next_item_size > 0 && (next_item_size as f64) <= post {
            score -= 5.0;
        }
    } else {
        // Using an existing bin gets slightly more attractive as stream progresses.
        score -= 4.0 * t;
    }

    // Penalize bins whose residual deviates badly from the mean residual
    // (fragmentation control).
    let dev = (post - mean_residual).abs();
    score += dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: post residual, non-linearly scaled by fill fraction
    let fill = 1.0 - post / cap;
    let mut score = post * (0.5 + 0.5 * fill * fill);

    // Smooth polynomial coupling of post_residual with stream progress
    let prog2 = progress * progress;
    score += post * (0.6 * prog2 + 0.4 * progress) * (1.0 - fill);

    // Penalize large dead space more as stream progresses (quartic-ish coupling)
    score += (post * post) / cap * (0.3 + 0.7 * prog2);

    // Reward tight fits: post residual near zero
    if post == 0 {
        score -= 25.0 + 15.0 * progress;
    } else if post <= 10.0 {
        score -= 12.0 * (1.0 - post / 10.0);
    }

    // Lookahead: penalize if post residual can't fit next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 4.0 * (nxt / cap);
        } else {
            score += 3.0 * (nxt - post) / cap * (1.0 + progress);
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 18.0;
    }

    // Mild penalty for too many open bins relative to progress
    score += 0.15 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate: penalize unless current bin would be very wasteful
    if bin_residual == bin_capacity {
        score += 8.0 - 6.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fills heavily rewarded
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 60.0;
    }

    // Modulo arithmetic on post_residual: residual divisible by small classes
    // (10, 20, 25, 50) is more likely to be filled by future items.
    let pr = post_residual;
    if pr > 0 {
        if pr % 50 == 0 {
            score -= 25.0;
        } else if pr % 25 == 0 {
            score -= 15.0;
        } else if pr % 10 == 0 {
            score -= 10.0;
        } else if pr % 5 == 0 {
            score -= 4.0;
        }
    }

    // Dead-space penalty: residual that no plausible item (1..=100) can use
    // is already handled by pr==0, but tiny leftovers are near-perfect; mid
    // leftovers (just above typical small items) are fine. Penalize awkward
    // zones via integer-division thresholds.
    if pr >= 1 && pr <= 3 {
        score -= 40.0; // nearly full
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 200.0;
        } else if next_item_size < pr && pr - next_item_size <= 10 {
            score -= 50.0;
        } else if next_item_size > pr {
            // next item won't fit here; residual becomes dead space risk
            score += (pr as f64) * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: make it moderately attractive only when no open bin
    // fits well, i.e. base it on mean residual tightness.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // opening a new bin costs ~cap; discourage unless existing bins are fragmented
        score = cap * 0.55 + mean_residual * 0.5 - progress * 20.0;
        if post_residual == 0 { score -= 1000.0; }
    }

    // Tightness bonus: reward bins whose fill fraction is high.
    let fill = (bin_capacity - bin_residual) as f64 / cap;
    score -= fill * 30.0;

    // Mild penalty for spreading across many open bins
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small to hold even the smallest item are pure waste.
    if post_residual < 10 && post_residual > 0 {
        score += 60.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Reward tight fits (small usable post_residual) more aggressively than raw post_residual.
    if post_residual > 0 {
        score -= 25.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: when many bins are open, discourage new bins / large residuals.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 1.5 * (1.0 - progress);

    // New-bin candidate: only attractive when residual is large and next item is big,
    // otherwise penalize it so we prefer filling existing bins.
    if bin_residual == bin_capacity {
        if next_item_size > 0 && next_item_size as f64 > bin_residual as f64 * 0.6 && open_bins_count > 0 {
            score -= 20.0;
        } else {
            score += 45.0 + mean_residual * 0.3;
        }
    }

    // Lookahead: if next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // Penalize leaving a gap the next item cannot use.
    if next_item_size > post_residual && post_residual > 0 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    score -= (bin_capacity as f64 - post_residual as f64) * 0.15;

    // 2-step lookahead: if next item exactly fills post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // next item fits here later; reward proportionally to how snugly.
            score -= 25.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item cannot use this leftover space: penalize dead space.
            score += 10.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Compare against mean residual: prefer bins tighter than average.
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Penalize opening a new bin when decent open bins exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 + 15.0 * (1.0 - progress) + open_bins_count as f64;
        // Still allow new bin if item barely fits elsewhere.
        if bin_residual - item_size < 5 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);

    // Base: prefer small post_residual, but with diminishing sensitivity
    let mut score = pr * (1.0 + 0.5 * pr / cap) - 8.0 * (pr / cap).ln().max(0.0);

    // Smooth non-linear coupling of post_residual with stream progress:
    // late in the stream, tight fits matter more (penalize large residuals).
    let tightness = pr / cap;
    score += (tightness * tightness) * 30.0 * progress;
    score -= (tightness * (1.0 - tightness)) * 12.0 * (1.0 - progress);

    // Penalize residual that is too small to plausibly hold a future item
    // (dead space), smoothly via a logistic-like term on post_residual.
    let dead = (1.0 / (1.0 + (pr / 15.0).exp())) * 20.0;
    score += dead;

    // Lookahead: reward residual that can still fit the next item
    if next_item_size > 0 {
        let fits_next = if (post_residual as u32) >= next_item_size { 1.0 } else { 0.0 };
        let margin = (post_residual as f64 - next_item_size as f64) / cap;
        score -= fits_next * (10.0 + 20.0 * margin.max(0.0));
    }

    // Last-chance bin: strong bonus to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress * 0.5);
    }

    // Mild preference to fill bins with large residuals when many bins open
    score += (bin_residual as f64 / cap) * (open_bins_count as f64).ln().max(0.0) * 2.0;

    // New-bin candidate: make it slightly unattractive unless residual is tight
    if bin_residual == bin_capacity {
        score += 6.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: waste buckets by integer division
    let class = post_residual / 10; // 0..10 harmonic classes of dead space
    score += match class {
        0 => -40.0, // near-perfect fit
        1 => -15.0,
        2 => 0.0,
        3 => 8.0,
        4 => 15.0,
        5 => 22.0,
        _ => 30.0 + (class as f64 - 6.0) * 4.0, // large dead space strongly penalized
    };

    // Modulo coupling: residuals that pair with common item sizes are valuable
    let m = post_residual % 10;
    if m == 0 {
        score -= 6.0;
    } else if m >= 7 {
        score += 5.0; // awkward remainder, hard to fill
    }

    // Lookahead: does the next item fit harmonically into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let leftover = post_residual - next_item_size;
            if leftover == 0 {
                score -= 35.0; // chain completion
            } else if leftover <= 10 {
                score -= 18.0;
            } else {
                score += leftover as f64 * 0.15;
            }
        } else {
            score += 12.0; // next item won't fit here; dead end risk
        }
    }

    // Last-chance bin bonus: only fitting bin before opening a new one
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins are poor
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let tight = mean_residual < item_size as f64 * 1.2;
        score = cap * 0.55
            + mean_residual * 0.35
            + progress * 5.0
            + if tight { 0.0 } else { 20.0 };
    }

    // Mild preference for tighter bins overall
    score += (mean_residual - bin_residual as f64) * 0.05;

    // Early stream: encourage consolidation into few bins
    if step_index < total_items / 4 {
        score -= open_bins_count as f64 * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no item (min size 10, or the known next item) can use are toxic.
    let min_item = 10u32;
    if post_residual > 0 {
        let usable_by_any = post_residual >= min_item;
        let usable_by_next = next_item_size > 0 && post_residual >= next_item_size;
        if !usable_by_any {
            // completely dead gap: worst possible outcome, waste of the whole gap
            score += 4.0 * post_residual as f64 + 50.0;
        } else if !usable_by_next {
            // gap exists but next item can't use it: moderate penalty scaled by gap awkwardness
            score += 1.5 * post_residual as f64 + 10.0;
        } else {
            // gap usable by the lookahead item: reward a good fit
            score -= 0.5 * (next_item_size as f64 - post_residual as f64).abs();
        }
    } else {
        // perfect closure of the bin: strong reward
        score -= 30.0;
    }

    // Tight fit reward: small post_residual relative to capacity is good (if usable)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 0.3 * tightness;

    // Open-bin pressure: discourage spreading across many bins; encourage filling existing ones
    score += 0.05 * open_bins_count as f64;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // (unless the fit creates dead space, which the penalties above already punish).
    if fitting_bins_count == 1 && post_residual >= min_item {
        score -= 15.0;
    }

    // Mean-residual coupling: prefer bins whose residual deviates from the mean toward fullness
    score += 0.1 * (bin_residual as f64 - mean_residual);

    // New-bin candidate handling: residual == capacity means brand-new empty bin.
    // Penalize opening a new bin, more so when many bins are already open,
    // but relax the penalty late in the stream when leftovers may be unavoidable.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 + 0.2 * open_bins_count as f64 - 10.0 * progress;
        // if the item leaves a large unusable gap even in a fresh bin, extra penalty
        if post_residual > 0 && post_residual < min_item {
            score += 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize dead space relative to mean residual of open bins.
    score += 0.35 * (post_residual as f64 - mean_residual).max(0.0);

    // Reward (subtract) when the next item fits exactly into the post residual:
    // a perfect 2-step chain is highly desirable.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Reward tighter 2-step fits proportionally.
            score -= 25.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item cannot follow into this bin: penalize if post residual
            // is a small, hard-to-use fragment.
            let frag = post_residual as f64 / bin_capacity as f64;
            if frag < 0.2 {
                score += 30.0 * (0.2 - frag) / 0.2;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: discourage opening a new bin unless the current item
    // leaves a large, well-shaped residual (useful for future items).
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin; offset if the stream is early and many
        // items remain to fill it.
        score += 45.0;
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 1.0 };
        score -= 20.0 * (1.0 - progress);
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 15.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        }
    }

    // Slight preference for filling bins tighter as the stream progresses.
    score -= 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64) * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio) * 12.0;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Penalize wasteful placements when many bins can fit the item
    if fitting_bins_count > 2 {
        score += (fitting_bins_count as f64 - 2.0) * 1.5;
    }

    // Lookahead: if next item would fit in the post-residual, reward this placement
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size <= post_residual {
            score -= 8.0;
        } else if next_item_size > post_residual && next_item_size <= bin_residual {
            score += 4.0; // this placement may strand the next item
        }
    }

    // New-bin candidate handling: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        // Base penalty so open bins with decent fit are preferred
        score += 15.0;
        // If the item leaves a lot of dead space in a new bin anyway, or few bins fit, discount
        if fitting_bins_count <= 1 {
            score -= 30.0;
        }
        if item_size > bin_capacity * 2 / 3 {
            score -= 10.0;
        }
        // Early in stream, opening fresh bins is more acceptable
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 8.0;
    } else {
        // Penalize leaving large unusable gaps relative to typical item sizes
        if post_residual > 0 && post_residual < 10 {
            score += 2.0; // tiny gap is fine actually, slight penalty for near-perfect handled above
        }
        // Prefer bins whose residual is close to mean residual (balance load)
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.05;
    }

    // Mild preference for filling fuller bins as stream progresses
    let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill * 6.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress
    let pr_norm = post / cap;
    let prog_sq = progress * progress;
    let coupling = pr_norm * pr_norm * (1.0 - progress) * 40.0
                 + pr_norm * prog_sq * 25.0
                 + pr_norm * progress * (1.0 - progress) * 15.0;
    score += coupling;

    // Reward tight fits (small post_residual) more strongly as stream progresses
    score -= (1.0 - pr_norm).powi(3) * (10.0 + 20.0 * progress);

    // Penalize dead space that cannot fit the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post < nxt {
            score += (nxt - post) * (0.5 + progress);
        } else {
            score -= 3.0 * (1.0 - progress);
        }
    }

    // Last-chance bin bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * progress;
    }

    // Mild penalty when many bins are open (encourage consolidation early)
    score += open_bins_count as f64 * 0.3 * (1.0 - progress);

    // Deviation from mean residual: prefer bins near the mean to balance load
    score += ((post - mean_residual) / cap).abs() * 8.0 * progress;

    // New-bin candidate: penalize opening a new bin unless item is large
    if bin_residual == bin_capacity {
        score += 12.0 - 0.05 * item_size as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward small, "harmonically useful" residuals
    // Residuals in {0,10,20,25,30,40,50} are highly reusable classes.
    let pr = post_residual;
    let class_bonus: f64 = if pr == 0 {
        -60.0 // perfect fit, huge reward
    } else if pr % 10 == 0 {
        -25.0
    } else if pr % 25 == 0 {
        -20.0
    } else if pr % 5 == 0 {
        -10.0
    } else {
        5.0 // awkward residual
    };
    score += class_bonus;

    // Coupling with lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size <= pr && pr - next_item_size <= 10 {
            score -= 20.0;
        } else if next_item_size > pr {
            // next item won't fit here anyway; mild penalty for stranded residual
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        score += (fitting_bins_count as f64 - 1.0) * 2.0; // prefer tighter competition
    }

    // Prefer filling bins that are already relatively empty-ish (consolidation)
    let fill_frac = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_frac * 12.0;

    // Penalize bins far from mean residual (keep balance)
    score += ((bin_residual as f64 - mean_residual).abs()) * 0.15;

    // Late in stream: be greedier about tight fits
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0 * (1.0 - pr as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when item is large relative to capacity
    // or no good residual class exists.
    if bin_residual == bin_capacity {
        let large_item_bonus = (item_size as f64 / bin_capacity as f64) * 40.0;
        score -= large_item_bonus;
        if open_bins_count == 0 {
            score -= 50.0;
        }
        // discourage new bin if a decent harmonic residual exists elsewhere
        if class_bonus < 0.0 || (next_item_size > 0 && next_item_size <= pr) {
            score += 35.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }

    // Reward tight fits (small post residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * tightness;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: penalize opening new bins when many bins are open.
    if bin_residual == bin_capacity {
        score += 25.0 + 3.0 * open_bins_count as f64;
    }

    // Lookahead: if next item fits the post residual, reward this placement.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual > 0 && (post_residual as u32) < next_item_size {
        score += 10.0;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins).
    score += 0.3 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer filling the bin tightly (small post_residual).
    score = post_residual as f64 * 1.0;

    // Aggressive 2-step lookahead: strongly reward post_residual matching next_item_size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        // Perfect lookahead match: big reward.
        if post_residual as u32 == next_item_size {
            score -= 40.0;
        } else if post_residual as f64 >= nxt {
            // Next item could fit here: reward proportionally to closeness.
            score -= 25.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Dead space relative to lookahead item: penalize.
            score += 0.5 * (nxt - post_residual as f64);
        }
    } else {
        // Last item: only tightness matters.
        score -= 10.0;
    }

    // Penalize bins whose residual is far below the mean (precious small space)
    // and slightly favor bins near the mean residual.
    let res = post_residual as f64;
    let mean_gap = res - mean_residual;
    score += 0.15 * mean_gap.abs();

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Many open bins: encourage consolidation into emptier bins to reduce bin count.
    if open_bins_count > 2 {
        score += 0.1 * (bin_residual as f64 - res);
    }

    // Early in stream: be more willing to open bins / keep flexibility (penalize tight fits less).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * (1.0 - progress);

    // Brand-new bin candidate: only attractive when no good fit exists
    // (large post_residual baseline already penalizes it; add mild bonus if item is huge).
    if bin_residual == bin_capacity {
        score += 5.0 - 0.05 * item_size as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits.
    let residual_frac = post_residual as f64 / bin_capacity as f64;
    score += 12.0 * residual_frac * residual_frac;

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 4.0 * (next_item_size as f64 / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Dead space for the next item: penalize proportional to wasted slack.
        score += 3.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 2 {
        // Plenty of alternatives; mild penalty for burning a scarce-fit bin.
        score += 2.0;
    }

    // New-bin candidate logic: only attractive when open bins are crowded
    // or mean residual is too small for typical future items.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mean_ok = mean_residual > item_size as f64 * 1.5;
        let crowded = open_bins_count as f64 > 8.0 + 20.0 * (1.0 - progress);
        if mean_ok && !crowded {
            score += 40.0; // discourage new bin; existing space is usable
        } else {
            score -= 6.0;  // encourage fresh bin when fragmentation is high
        }
    }

    // Global fragmentation pressure: if mean residual is small relative to
    // the item, prefer bins that keep mean residual usable.
    if mean_residual > 0.0 {
        let frag = (item_size as f64 / mean_residual).min(3.0);
        score += 2.0 * frag;
    }

    // Late in the stream, tighten packing (less tolerance for slack).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * residual_frac;

    // Perfect-fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_post * norm_post * (1.0 + 2.0 * progress) + 0.35 * norm_post * (1.0 - progress);

    let mut score = post + 40.0 * poly;

    // Tight fits rewarded, with progress-dependent strength
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * tightness * tightness * (0.5 + progress);

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - 0.5 * progress);
    }

    // Lookahead: prefer leaving space usable by next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post >= nx {
            score -= 12.0 * (nx / cap) * (1.0 - progress);
        } else {
            score += 10.0 * (1.0 - post / nx.max(1.0)) * (0.5 + progress);
        }
    }

    // Penalize opening new bins when many open bins with slack exist
    let mean_norm = mean_residual / cap;
    if bin_residual as f64 >= cap - 0.5 {
        score += 15.0 + 30.0 * mean_norm * (1.0 - progress) + 10.0 * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));
    }

    // Mild scatter penalty relative to mean residual
    score += 3.0 * (post - mean_residual).abs() / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: reward post_residuals that are "friendly" sizes
    // (small, or divisible into useful fractions of capacity).
    let pr = post_residual;
    if pr == 0 {
        score -= 40.0; // perfect fit
    } else {
        // Class A: tiny dead space
        if pr <= 5 {
            score -= 25.0;
        } else if pr <= 10 {
            score -= 15.0;
        }
        // Class B: post_residual divisible by common small integers
        // (likely to pair with future items of harmonic sizes)
        if pr % 10 == 0 {
            score -= 10.0;
        } else if pr % 5 == 0 {
            score -= 6.0;
        }
        // Class C: quarter/half fractions of capacity
        if pr == bin_capacity / 4 || pr == bin_capacity / 2 || pr == 3 * bin_capacity / 4 {
            score -= 8.0;
        }
        // Class D: integer-division threshold bands
        let band = pr / 10; // 0..10 bands
        score += band as f64 * 1.5;
    }

    // Lookahead: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 35.0;
        } else if next_item_size < pr {
            score -= 8.0;
        } else {
            score += 5.0; // next item won't fit here anyway
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize slightly so it's chosen only when open bins are bad.
    if bin_residual == bin_capacity {
        score += 30.0;
    }

    // Mild pressure toward compacting residual distribution.
    score += (mean_residual - post_residual as f64).abs() * 0.1;

    // Late-stream urgency: prefer filling existing bins as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to ever fit another
    // item (min item size 1, but practically tiny gaps are waste) are
    // heavily penalized as unusable dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 18.0;
    }

    // Reward tight fits: the smaller the post_residual relative to capacity,
    // the better the packing.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Dead space is worse late in the stream (less chance to fill it).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < 30 {
        score += 25.0 * progress;
    }

    // If the lookahead item could exactly fill the post_residual, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap < 10 {
            score -= 20.0;
        }
    }
    // Penalize if post_residual can't fit the next item (stranded space).
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 8.0;
    }

    // Open-bin pressure: prefer spreading load when many bins are open,
    // avoid opening excessive bins.
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when no open bin fits well
        // or many bins are already open.
        score += 55.0;
        if fitting_bins_count == 0 {
            score -= 100.0;
        } else if fitting_bins_count == 1 {
            score -= 30.0;
        }
        score += 2.0 * open_bins_count as f64;
        if post_residual == bin_capacity {
            // last-item style edge: neutralize
            score -= 10.0;
        }
    } else {
        // Slight preference for filling existing bins when few are open.
        if open_bins_count <= 2 {
            score -= 6.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Mean residual coupling: if this bin is far below mean residual, it's
    // a laggard bin; using it helps balance.
    score -= 0.05 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-exact fit (small post_residual).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 15 {
        score -= 10.0;
    }

    // 2-step lookahead: reward when the next item can fit into the post residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        let leftover_after_next = post_residual - next_item_size;
        score -= 25.0;
        if leftover_after_next == 0 {
            score -= 25.0; // perfect two-item packing
        } else if leftover_after_next <= 10 {
            score -= 10.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space: next item cannot use what remains.
        score += (post_residual as f64).min(next_item_size as f64) * 0.3;
    }

    // Relative to mean residual: prefer bins tighter than average.
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Penalize opening a new empty bin unless nothing reasonable fits.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // New bin is acceptable for large items or when few bins fit the item.
        if item_size > bin_capacity / 2 {
            score += 5.0;
        } else if fitting_bins_count == 0 {
            score += 0.0;
        } else {
            score += 50.0 + 30.0 * (1.0 - progress);
        }
        // If next item is small, a fresh bin may still be fine.
        if next_item_size > 0 && next_item_size >= item_size && post_residual >= next_item_size {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let next = next_item_size as f64;

    // Base: prefer tight fits (small post residual).
    let mut score = post;

    // Fraction of the stream already processed -> dynamic time horizon.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Dead-space penalty: small leftovers are wasteful unless perfectly reusable.
    if post > 0.0 && post < 10.0 {
        score += (10.0 - post) * 1.5;
    }

    // Reward when this bin is the last chance to fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + item * 0.4;
    }

    // Lookahead coupling: if the next item fits into post_residual, reward this placement.
    if next > 0.0 && (post_residual as f64) >= next {
        score -= 8.0 + 0.1 * next;
    } else if next > 0.0 && post > 0.0 && next > post {
        // Next item cannot use the leftover: mild penalty proportional to leftover size.
        score += 0.05 * post;
    }

    // Global state: penalize placements into bins far from mean residual (fragmentation signal).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.03 * dev;

    // Early in the stream: keep bins flexible; late: pack greedily.
    score += (1.0 - progress) * 0.08 * post;
    score -= progress * 0.05 * item;

    // Crowding: with many open bins, prefer filling existing ones over spreading.
    if open_bins_count > 4 {
        score -= 0.5 * (open_bins_count.min(20) as f64);
    }

    // New-bin candidate handling: empty bin gets a handicap that shrinks when the item
    // is large or no good alternative exists.
    if bin_residual == bin_capacity {
        let handicap = 30.0 + 0.5 * item * (1.0 - progress);
        score += handicap;
        // Very large items may justify a fresh bin.
        if item as u32 >= bin_capacity * 3 / 4 && fitting_bins_count <= 1 {
            score -= 45.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let post_norm = post / cap;
    let fit_norm = item_size as f64 / cap;
    let next_norm = next_item_size as f64 / cap;

    // Base: penalize leftover space, non-linearly (dead space matters super-linearly)
    let mut score = post * (1.0 + 0.6 * post_norm * post_norm);

    // Smooth coupling: leftover waste weighted by stream progress (late items should pack tighter)
    score += 8.0 * progress * post_norm * post_norm * (1.0 - fit_norm);

    // Reward tight fits with smooth quadratic bump around post_residual == 0
    let tightness = 1.0 - post_norm;
    score -= 12.0 * tightness * tightness * tightness;

    // Lookahead coupling: bonus if leftover could host next item, penalize otherwise
    if next_item_size > 0 {
        let diff = post - next_item_size as f64;
        if diff >= 0.0 {
            score -= 3.0 * (1.0 - diff / cap);
        } else {
            score += 2.0 * (-diff / cap) * (1.0 + progress);
        }
    }

    // Last-chance bin: smooth reward scaled by scarcity of fitting bins
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 5.0 * (1.0 - progress * 0.5);
    }

    // Penalize many open bins mildly; smooth interaction with mean residual
    let mean_norm = mean_residual / cap;
    score += 0.4 * open_bins_count as f64 * mean_norm * mean_norm;

    // New-bin candidate: make empty bin attractive only when existing residuals are poor
    let is_new = (bin_residual as f64 - cap).abs() < 1e-6;
    if is_new {
        score += 2.0 + 10.0 * (1.0 - mean_norm) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual: residuals that are "nice" fractions of
    // capacity (multiples of 25, or exact halves) are more reusable.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Reward residuals that align with common item-size classes (1..=100).
    // A residual is "harmonic" if many item sizes divide it or fit exactly.
    let mut harmonic_bonus = 0.0;
    if post_residual % 50 == 0 { harmonic_bonus += 18.0; }
    else if post_residual % 25 == 0 { harmonic_bonus += 10.0; }
    else if post_residual % 10 == 0 { harmonic_bonus += 6.0; }
    else if post_residual % 5 == 0 { harmonic_bonus += 3.0; }
    score -= harmonic_bonus;

    // Penalize tiny dead space: residual too small for the smallest plausible
    // follow-up item (<= ~10) is nearly unusable.
    if post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // this placement creates a perfect packing chain.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // next item still fits: mild reward proportional to tightness
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / cap);
        } else {
            // next item won't fit here: this bin is likely closed after this
            // placement; reward tight closure (small post residual wasted).
            score += 8.0;
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 45.0;
    }

    // Prefer fuller bins: reward high fill fraction (capacity - residual).
    let fill = (bin_residual as f64) / cap;
    score -= 20.0 * fill * fill;

    // New-bin candidate: empty bin should only win when the placement here is
    // poor. Penalize the fresh bin moderately so open bins with decent fits win.
    if bin_residual == bin_capacity {
        score += 25.0;
        // But if many bins are open and mean residual is small, opening fresh
        // space is attractive (spread load).
        if open_bins_count > 0 {
            score -= 10.0 * (mean_residual / cap).min(1.0);
        }
    }

    // Stream progression: late in the stream, avoid opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 30.0 * progress;
    }

    // Mild penalty for too many open bins (fragmentation control).
    score += (open_bins_count as f64).sqrt() * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to fit any plausible
    // future item (min size 1, but small gaps < 20 are nearly unusable) get
    // heavily penalized as wasted capacity.
    if post_residual > 0 && post_residual < 20 {
        score += 60.0 * (1.0 - post_residual as f64 / 20.0);
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 100.0;
    } else {
        // Usable gap: mild reward proportional to how well a typical item fits.
        score -= 5.0;
    }

    // Reward tight fits: small post_residual relative to capacity.
    score -= 40.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize slightly less if residual is dead space anyway.
            score += 8.0;
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Open bins pressure: with many open bins, prefer consolidating into
    // existing bins; with few open bins, opening a new bin is cheaper.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual != bin_capacity {
        score -= 6.0 * pressure;
    } else {
        // New-bin candidate: penalize more when many bins are open.
        score += 10.0 + 8.0 * pressure;
    }

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it's already tight — reward filling it further.
    let diff = mean_residual - post_residual as f64;
    score += 0.05 * diff;

    // Early stream: slightly favor new bins to build a spread; late stream:
    // consolidate hard.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score -= 5.0 * (1.0 - progress);
    } else {
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match between post_residual and next_item_size.
    let post = post_residual as f64;
    let nxt = next_item_size as f64;
    let diff = (post - nxt).abs();
    if next_item_size > 0 {
        score -= 30.0 * (-diff / 20.0).exp();          // strong bonus for tight 2-step fit
        if post_residual == next_item_size {
            score -= 25.0;                             // exact match: bin closed perfectly
        }
        // Penalize leaving residual that is slightly too small for next item (dead space)
        if post_residual > 0 && post_residual < next_item_size {
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Reward tightness relative to mean residual of open bins
    score -= 0.3 * (mean_residual - post).max(0.0);

    // Penalize waste proportional to item size (avoid over-large gaps)
    score += 0.1 * (item_size as f64 / bin_capacity as f64) * (bin_residual as f64 - item_size as f64);

    // Last-chance bin: strongly favor using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: make it attractive only when no good fit exists
    if bin_residual == bin_capacity {
        let lookahead_penalty = if next_item_size > 0 && post_residual >= next_item_size { 0.0 } else { 10.0 };
        score = 0.5 * (bin_capacity - item_size) as f64 + lookahead_penalty
              + 0.2 * (open_bins_count as f64);
        if fitting_bins_count == 1 {
            score += 60.0; // don't open new bin when an existing bin is the last chance
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 45.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post_residual can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += 8.0;
        }
        // Perfect pairing: item + next item fills bin almost exactly.
        let pair_waste = post_residual as f64 - next_item_size as f64;
        if pair_waste >= 0.0 && pair_waste < 5.0 {
            score -= 30.0;
        }
    } else {
        // Last item: strongly prefer minimal residual.
        score -= 20.0 * tightness;
    }

    // Last-chance bonus: this is the only bin that fits the item.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Time horizon: early in stream, be conservative (prefer filling existing bins);
    // late in stream, allow opening new bins less readily too since fewer items remain.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 10.0 * progress;

    // Penalize bins whose residual is far from the mean residual (outliers are less flexible).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Prefer bins with more residual when many bins are open (consolidation).
    if open_bins_count > 4 {
        score += 0.1 * (open_bins_count as f64);
    }

    // New-bin candidate handling: opening a new bin is only attractive when no good fit exists.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty for opening a new bin.
        score += 60.0;
        // If many bins fit the item, definitely prefer existing bins.
        if fitting_bins_count > 2 {
            score += 40.0;
        }
        // If this is the last chance and the fit is terrible, allow the new bin.
        if fitting_bins_count == 1 && (bin_residual - item_size) > 0 {
            let waste_elsewhere = bin_residual - item_size; // wrong: residual of the fitting bin unknown; use item-based proxy
            let _ = waste_elsewhere;
            // Allow new bin if item is large relative to capacity (poor fits everywhere).
            if (item_size as f64) > 0.75 * bin_capacity as f64 {
                score -= 70.0;
            }
        }
        // Late in stream with few remaining items, avoid opening new bins.
        if progress > 0.8 {
            score += 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: minimize leftover space, with a non-linear (quadratic) penalty
    // that grows super-linearly for small unusable leftovers.
    let mut score = post * (1.0 + norm_post * (1.0 + progress));

    // Lookahead coupling: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual >= next_item_size {
            let slack = post - nxt;
            score -= 12.0 * (1.0 - (slack / cap).powi(2)) * (0.5 + progress);
        } else {
            // Post-residual is dead space with respect to the lookahead item.
            score += 6.0 * (1.0 - progress) * (nxt / cap);
        }
    }

    // Last-chance bin: strongly reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0 * (1.0 + 0.5 * progress);
    }

    // Scarcity of fitting bins: keep usable bins alive.
    if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).ln().max(0.0);
    }

    // Mean-residual coupling: placing into a bin far above the mean residual
    // concentrates waste; mildly penalize deviations.
    let dev = (mean_residual - post).abs();
    score += 0.05 * dev * (0.5 + 0.5 * progress);

    // New empty bin candidate: penalize opening a bin when the stream is early
    // or when open bins exist and can still absorb items; relax late.
    if bin_residual == bin_capacity {
        let open_bonus = if open_bins_count > 0 { (open_bins_count as f64).ln() } else { 0.0 };
        score += 20.0 + 25.0 * (1.0 - progress) + 4.0 * open_bonus;
        // If the item is huge relative to capacity, opening fresh is more forgivable.
        score -= 10.0 * (item_size as f64 / cap);
    }

    // Smooth tightness reward: bins that end nearly full are excellent.
    score -= 8.0 * ((1.0 - norm_post) * (1.0 - norm_post)) * (0.3 + 0.7 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tight fit reward: the smaller the post_residual, the better.
    score -= (1.0 - post_residual as f64 / cap) * 30.0;

    // Perfect / near-perfect fits get a strong bonus.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 120.0;
    }

    // Harmonic class: classify post_residual by modulo classes (capacity fractions).
    // Residuals that are multiples of common item sizes (10, 20, 25, 50) are reusable.
    let reusable = post_residual % 10 == 0 || post_residual % 20 == 0 || post_residual % 25 == 0 || post_residual % 50 == 0;
    if reusable {
        score -= 25.0;
    } else {
        score += 10.0;
    }

    // Lookahead coupling: reward bins whose post_residual can exactly host the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 150.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size <= 10 {
            score -= 60.0;
        } else if post_residual < next_item_size && post_residual > 0 {
            // dead space relative to lookahead
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
        // Harmonic class of lookahead: next item divisible into residual evenly
        if next_item_size > 0 && post_residual % next_item_size == 0 && post_residual > 0 {
            score -= 20.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // Penalize high fragmentation relative to mean residual.
    if (post_residual as f64) > mean_residual + 20.0 {
        score += (post_residual as f64 - mean_residual) * 0.3;
    }

    // New-bin candidate handling: an empty bin has post_residual == bin_capacity.
    if bin_residual == bin_capacity {
        // Prefer a new bin only late in the stream or when few bins fit the item,
        // and when the item is large (would leave little usable space anyway).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let item_frac = item_size as f64 / cap;
        let mut new_bin_score = 40.0;
        new_bin_score -= progress * 20.0;                 // late stream: consolidation matters, keep some penalty
        if item_frac > 0.7 { new_bin_score -= 30.0; }     // big items fine anywhere
        if fitting_bins_count == 0 { new_bin_score -= 100.0; }
        // Empty-bin harmonic class: residual 100 is perfectly reusable, but opening
        // bins freely fragments the pool; add penalty proportional to open bins.
        new_bin_score += open_bins_count as f64 * 3.0;
        score = score.max(0.0) + new_bin_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for typical future items
    // are waste. Penalize sharply when post_residual falls into the "unusable"
    // zone (below the smallest plausible item, ~10) or just below the lookahead item.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 40.0; // tiny sliver: pure dead space
        } else if next_item_size > 0 && post_residual < next_item_size {
            score += 18.0; // can't host the next item either
        } else {
            // Usable residual: reward proportionally (subtract), favoring mid-range gaps
            score -= 0.6 * (post_residual as f64).min(50.0);
        }
    } else {
        score -= 25.0; // perfect closure of the bin
    }

    // Tight-fit reward: item fills most of the bin
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    if fill > 0.8 {
        score -= 15.0 * (fill - 0.8);
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Open-bin pressure: mildly discourage spreading across many bins
    score += 0.35 * open_bins_count as f64;

    // New-bin candidate: only attractive when open bins have poor residuals
    if bin_residual == bin_capacity {
        score += 8.0 + 0.5 * mean_residual;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // fresh bin can serve the lookahead too
        }
    }

    // Late-stream tightening: as the stream ends, prefer closing bins cleanly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 6.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect or near-perfect fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else {
        // Penalize dead space relative to capacity (non-linear).
        let waste_frac = post_residual as f64 / bin_capacity as f64;
        score += 150.0 * waste_frac * waste_frac;
    }

    // Aggressive 2-step lookahead: reward bins whose post residual
    // exactly matches the next item size (chain packing).
    if next_item_size > 0 {
        let post = post_residual as f64;
        let nxt = next_item_size as f64;
        if post_residual == next_item_size {
            score -= 500.0; // perfect chain: next item fills this bin completely
        } else if post_residual > next_item_size {
            let gap = post - nxt;
            score -= 120.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize proportionally to shortfall
            let short = nxt - post;
            score += 0.8 * short;
        }
    }

    // Compare post residual against mean residual: prefer bins we tighten
    // below the mean (good consolidation), penalize staying above mean.
    let mean_post = mean_residual - item_size as f64;
    let diff = post_residual as f64 - mean_post;
    score += 0.6 * diff;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
        if post_residual <= 20 {
            score -= 60.0;
        }
    }

    // New-bin candidate handling: keep empty bins attractive only when
    // no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Base cost of opening a new bin, slightly cheaper late in stream.
        score += 90.0 - 30.0 * progress;
        // If many bins fit the item, opening a new bin is wasteful.
        if fitting_bins_count > 0 {
            score += 40.0 * fitting_bins_count as f64;
        }
    }

    // Mild preference for fuller bins among many open bins.
    score += 0.15 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic bonus for small post residual.
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 40.0 * tightness * tightness;

    // Lookahead: if the next item fits exactly into the post residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // next item fits but leaves more waste: mild reward scaled by fit quality
            let nxt_fit = 1.0 - ((post_residual - next_item_size) as f64) / cap;
            score -= 25.0 * nxt_fit;
        } else {
            // next item cannot use the post residual: penalize dead space creation
            score += 8.0 + 0.15 * (post_residual as f64);
        }
    }

    // Last chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
        if post_residual > 0 && post_residual < 10 {
            score -= 20.0; // nearly perfect closure
        }
    }

    // New-bin candidate (empty bin): neutral-ish baseline so it wins only
    // when open bins have poor fits. Slight preference late in the stream.
    if bin_residual == bin_capacity {
        score += 15.0;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * progress;
    }

    // Prefer bins whose residual deviates favorably from the mean residual:
    // using a bin with residual below mean consolidates space.
    if bin_residual < bin_capacity {
        let dev = (bin_residual as f64 - mean_residual) / cap;
        score += 10.0 * dev;
    }

    // Mild penalty for accumulating too many open bins (encourage consolidation).
    score += 0.3 * open_bins_count as f64;

    // Penalize leaving exactly awkward residuals that few items can fill.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let br = bin_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    let mut score = pr as f64;

    // Smooth non-linear coupling: quadratic waste penalty grows with stream progress
    let waste_curve = norm_pr * norm_pr * (1.0 + 2.0 * progress);
    score += 30.0 * waste_curve;

    // Reward tight fits via smooth sigmoid-like term on fill ratio
    let fill = norm_item;
    let tight_bonus = fill * fill * (1.0 - fill) * 4.0; // peaks near fill ~ 2/3
    score -= 25.0 * tight_bonus;

    // Interaction between residual and item smoothness
    score += 10.0 * (norm_pr - fill) * (norm_pr - fill) * (0.5 + progress);

    // Last-chance bin: smooth reward scaled by how well it fits
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - norm_pr);
    }

    // Lookahead: penalize if next item cannot use leftover space (smooth)
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let unusable = (nx - norm_pr).max(0.0);
        score += 20.0 * unusable * unusable;
        // reward if next item fits exactly into the post residual
        let match_bonus = 1.0 - (nx - norm_pr).abs() / cap;
        score -= 12.0 * match_bonus * match_bonus * norm_pr;
    }

    // Mean residual coupling: prefer bins below mean residual early, above later (smooth)
    let dev = (br - mean_residual) / cap;
    score += 8.0 * dev * (2.0 * progress - 1.0);

    // Mild pressure to consolidate when many bins are open
    let open_pressure = (open_bins_count as f64 / (1.0 + open_bins_count as f64)).ln();
    score += 5.0 * open_pressure * norm_pr;

    // New-bin candidate: penalize opening a bin unless residual is large and item small
    if bin_residual == bin_capacity {
        let reluctance = 1.0 - norm_item;
        score += 18.0 + 20.0 * reluctance * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues that are multiples of common
    // item-size blocks (e.g. multiples of 10, 25, 50) are more reusable.
    let pr = post_residual;
    let class_bonus = if pr == 0 {
        -60.0 // perfect fit: strongly reward
    } else if pr % 50 == 0 {
        -18.0
    } else if pr % 25 == 0 {
        -12.0
    } else if pr % 10 == 0 {
        -8.0
    } else if pr % 5 == 0 {
        -4.0
    } else {
        6.0 // awkward residue: penalize
    };
    score += class_bonus;

    // Lookahead: reward if the next item exactly or nearly fits into post_residual.
    if next_item_size > 0 && next_item_size <= pr {
        let slack = pr - next_item_size;
        if slack == 0 {
            score -= 25.0;
        } else {
            score -= 10.0 * (1.0 - slack as f64 / bin_capacity as f64);
        }
    } else if next_item_size > pr {
        // Next item won't fit here regardless; mildly penalize dead space.
        score += (pr as f64) * 0.05;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New empty-bin candidate: penalize so it is only chosen when open bins fit poorly.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 45.0 + mean_residual * 0.2;
    }

    // Fractional-capacity coupling: prefer filling bins past half capacity.
    let fill_frac = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_frac * 12.0;

    // Late in the stream, compact more aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 8.0;

    // Penalize bins far from the mean residual (fragmentation avoidance).
    score += ((post_residual as f64) - mean_residual).abs() * 0.03;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit: perfect placement, huge reward.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Strict dead-space avoidance: residual below the minimum item size is unusable.
    let dead_threshold: f64 = 10.0;
    if (post_residual as f64) < dead_threshold {
        score += 250.0 * (dead_threshold - post_residual as f64);
    }

    // Tight fit reward: item fills most of the bin.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 120.0 * fill_ratio;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // Open-bin pressure: more open bins -> prefer consolidating into existing bins.
    score += open_bins_count as f64 * 2.0;

    // New-bin candidate logic: only attractive when current bin residuals are badly fragmented.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so a new bin is only chosen when existing fits are poor.
        score += 80.0;
        // If lookahead item would fit the post-residual of this bin, reward using it.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 40.0;
        }
        // If next item is huge relative to capacity, opening fresh bin now is safer.
        if next_item_size > 0 && (next_item_size as f64) > 0.7 * bin_capacity as f64 {
            score -= 25.0;
        }
        // Late in the stream, avoid leaving many near-empty bins; slight extra penalty.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
    } else {
        // Reward bins whose residual would still accommodate the next item after placement.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 15.0;
        }
        // Penalize bins far below mean residual (wasteful use of a large-gap bin for small item).
        if (bin_residual as f64) > mean_residual + 20.0 && item_size < 40 {
            score += 20.0;
        }
    }

    // Mild preference for tighter residuals across candidates.
    score += (bin_residual as f64 - post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual) but keep usable space.
    score = post_residual as f64 * 0.9 + (bin_capacity as f64 - bin_residual as f64) * 0.1;

    // Aggressive 2-step lookahead: reward exact match with next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        // Perfect chain: post_residual == next_item_size is ideal.
        score -= (bin_capacity as f64 - diff) * 0.35;
        // If post_residual cannot fit next item, penalize dead space scaled by smallness.
        if (post_residual as f64) < nxt {
            score += (nxt - post_residual as f64) * 0.8;
            // Very small unusable residue is wasted space.
            if post_residual < 10 {
                score += (10.0 - post_residual as f64) * 1.5;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when open bins fit poorly.
    if bin_residual == bin_capacity {
        // Neutral-ish baseline; add penalty proportional to open bins that could fit.
        score = bin_capacity as f64 + 5.0;
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= next_item_size as f64 * 0.1;
        }
    }

    // Context: compare against mean residual — prefer bins deviating toward fuller use.
    score += (mean_residual - post_residual as f64) * 0.15;

    // Late in stream, be more conservative with new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;

    // Reward perfect / near-perfect fills (dead space elimination)
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual < 10 {
        score -= 12.0;
    } else if post_residual < 20 {
        score -= 4.0;
    }

    // Prefer bins that are already heavily used (consolidation)
    let used_frac = (bin_capacity.saturating_sub(bin_residual)) as f64 / bin_capacity as f64;
    score -= 6.0 * used_frac;

    // Lookahead coupling: reward leaving room for the next item,
    // penalize leaving a residual that just barely fails the next item
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // bonus scaled by how well next item matches the leftover
            let snug = 1.0 - (post_residual - next_item_size).min(50) as f64 / 50.0;
            score -= 3.0 + 5.0 * snug;
        } else {
            let overshoot = (next_item_size - post_residual).min(40) as f64;
            score += 0.20 * overshoot;
        }
    }

    // Last-chance bin: if this is the only open bin that fits, strongly favor it
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 22.0;
    }

    // New-bin candidate handling
    if is_new_bin {
        if fitting_bins_count == 0 {
            // No open bin can host the item: opening a new bin is mandatory/great
            score -= 45.0;
        } else if fitting_bins_count == 1 {
            // One existing bin fits; only open a new bin if that fit is terrible
            if post_residual > bin_capacity / 2 {
                score -= 15.0;
            } else {
                score += 18.0;
            }
        } else {
            // Multiple alternatives exist: generally discourage fragmentation,
            // but allow it slightly more early in the stream when mean residual is high
            let spread_allowance = (1.0 - progress) * mean_residual.min(100.0) * 0.10;
            score += 10.0 - spread_allowance;
        }
    }

    // Mild global pressure: as stream progresses, tighten tolerance for waste
    score += progress * (post_residual.min(60) as f64) * 0.05;

    // Discourage scattering across many open bins when mean residual is already low
    if open_bins_count > 4 && mean_residual < 25.0 && !is_new_bin {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post residual (tight fit), with smooth non-linear shaping
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Polynomial coupling of post_residual with stream progress:
    // late in the stream, tolerate larger residuals less harshly (avoid opening bins)
    let progress_coupling = 1.0 - 0.45 * progress * progress;
    score *= progress_coupling;

    // Smooth penalty for residual that cannot fit the lookahead item (dead space)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            let gap = (nxt - pr) / cap;
            score += gap * gap * cap * (0.5 + 0.5 * progress);
        } else {
            // smooth reward when lookahead fits perfectly
            let fit_quality = 1.0 - ((pr - nxt) / cap);
            score -= 2.0 * fit_quality * fit_quality;
        }
    }

    // Last-chance bin: strongly reward using it to avoid a new bin
    if fitting_bins_count == 1 {
        score -= 6.0 + 4.0 * progress;
    }

    // Mild reward for reducing residual spread relative to mean
    score -= 0.3 * (mean_residual - pr) / cap;

    // Penalize opening new bins when many bins are open and progress is low
    let new_bin = (bin_residual == bin_capacity) as i32 as f64;
    score += new_bin * (10.0 + 20.0 * (1.0 - progress) * (1.0 - progress) + 0.5 * open_bins_count as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: integer division thresholds
    let quarter = bin_capacity / 4; // 25
    let half = bin_capacity / 2;    // 50
    let eighth = bin_capacity / 8;  // 12

    // Dead-space penalty: residual too small to ever be useful (below smallest item class)
    if post_residual < eighth {
        score += 30.0 + (eighth - post_residual) as f64;
    }

    // Reward tight fits (small post_residual but still usable)
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= eighth {
        score -= 20.0;
    }

    // Modulo-class logic on post_residual relative to capacity quarters
    let post_class = post_residual / quarter; // 0..=4
    match post_class {
        0 => score -= 10.0,               // tiny leftover, fine
        1 => score += 5.0,                // 25..49: awkward zone
        2 => score -= 8.0,                // 50..74: good for mid items
        3 => score -= 4.0,                // 75..99: near-empty
        _ => {}                            // full bin (new bin candidate)
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        // Prefer new bin if existing bins are fragmented
        score += 15.0 * (open_bins_count as f64).sqrt();
        // But if item is huge and mean residual is low, opening is good
        if (item_size as f64) > mean_residual + 10.0 {
            score -= 25.0;
        }
        // Late in stream, avoid opening new bins that will stay nearly empty
        if total_items > 0 && step_index as f64 / total_items as f64 > 0.85 {
            score += 20.0;
        }
    }

    // Lookahead coupling: does post_residual fit next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward if leftover still fits the next item (harmonic pairing)
            let pair_waste = post_residual - next_item_size;
            if pair_waste < eighth {
                score -= 15.0;
            } else {
                score -= (pair_waste as f64) * 0.1;
            }
        } else {
            // Post residual cannot host next item: penalize proportionally
            score += 8.0 + (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Fragmentation guard: penalize leaving residual in awkward modulo classes of 25
    if post_residual % quarter == 0 && post_residual > 0 && post_residual < bin_capacity {
        score -= 6.0; // exact quarter boundaries are reusable slots
    }

    // Slight bias toward bins with residual close to item size (best-fit core)
    score += (bin_residual as f64 - item_size as f64) * 0.05;

    // Global fragmentation: if many open bins with high mean residual, prefer filling existing
    if open_bins_count > 2 && mean_residual > half as f64 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no plausible item (>=10, or next item) can use are toxic.
    let min_item = 1u32;
    let usable_threshold = if next_item_size > 0 { next_item_size.max(min_item) } else { min_item };

    if post_residual < usable_threshold && post_residual > 0 {
        // Unusable sliver: dead space penalty grows super-linearly as gap shrinks relative to capacity.
        let gap_frac = post_residual as f64 / bin_capacity as f64;
        score += 40.0 * (1.0 - gap_frac) * (1.0 - gap_frac);
    }

    // Perfect / near-perfect fits get strong reward.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual == next_item_size {
        // Gap exactly matches the lookahead item: excellent chaining opportunity.
        score -= 45.0;
    } else if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size <= 5 {
        // Can host next item and leave a tiny remainder.
        score -= 15.0;
    }

    // Reward filling a bin deeply (high utilization of this placement).
    let fill_frac = item_size as f64 / bin_residual as f64;
    score -= 20.0 * fill_frac * fill_frac;

    // Last-chance pressure: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading; prefer consolidating.
    let open_pressure = (open_bins_count as f64).ln().max(0.0);
    score += 3.0 * open_pressure * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins with residuals below the mean (tighter bins) to keep clean large gaps elsewhere.
    score += 0.5 * (mean_residual - bin_residual as f64);

    // New-bin candidate: baseline cost of opening a new bin, modulated by stream position
    // and how bad the best existing fit would be. Late in the stream, opening a bin is fine.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut new_bin_score = 55.0 - 20.0 * progress;
        // If the item would leave a large awkward gap in any bin, opening fresh is attractive.
        if post_residual == bin_capacity {
            // item == capacity case: perfect new bin.
            new_bin_score -= 40.0;
        }
        if fitting_bins_count == 0 {
            new_bin_score -= 30.0;
        }
        // Early stream: keep flexibility, opening bins is cheap.
        new_bin_score -= 10.0 * (1.0 - progress);
        score = score.min(f64::MAX); // guard
        return new_bin_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward: exact or near-exact fill is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: if the next item fits exactly into post_residual,
    // this placement sets up a perfect follow-up placement.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            // Next item fits: mild reward proportional to how snugly.
            let slack_after_next = post_residual - next_item_size;
            score -= 50.0 * (1.0 - slack_after_next as f64 / bin_capacity as f64);
        } else {
            // Next item cannot fit in the residual: penalize wasted potential.
            let overflow = next_item_size - post_residual;
            score += 30.0 + overflow as f64 * 0.5;
        }
    }

    // Relative to mean residual: bins with more room than average are
    // better candidates for large items; penalize using a spacious bin
    // for a small item.
    let res = post_residual as f64;
    if res > mean_residual {
        score += 0.6 * (res - mean_residual);
    } else {
        score -= 0.3 * (mean_residual - res);
    }

    // Last-chance bin: if this is the only bin that fits the item,
    // strongly favor it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // New-bin candidate handling: an empty bin should only win when the
    // item is large relative to capacity or nothing fits well elsewhere.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        // Empty bin baseline: neutral-ish score; large items favor new bin.
        score = (bin_capacity - post_residual) as f64 * 0.5 + 40.0;
        if fill_ratio > 0.6 {
            score -= 60.0 * (fill_ratio - 0.6) / 0.4;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0;
        }
    }

    // Late in the stream, prefer consolidating into existing bins.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        if bin_residual != bin_capacity {
            score -= 20.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared residual pressure
    let tight = post_residual as f64 / bin_capacity as f64;
    score += tight * tight * 30.0;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Lookahead: reward if next item fits in the post-residual (chaining)
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0 + (post_residual - next_item_size) as f64 * 0.1;
        } else {
            // Penalize creating residual that is too small for the next item
            // (dead space), scaled by how close next item is to fitting.
            let miss = (next_item_size - post_residual) as f64;
            if miss < 20.0 {
                score += miss * 0.6;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless the
    // current bin would leave a large unusable gap.
    if bin_residual == bin_capacity {
        // New empty bin baseline: moderate score so it only wins when
        // existing fits are poor.
        score += 40.0;
        // Late in the stream, opening bins is fine since many items remain
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= progress * 10.0;
        // If many bins are already open and fragmented, a new bin is cheap
        score -= (open_bins_count as f64).ln().max(0.0) * 3.0;
    }

    // Penalize bins whose residual deviates far from the mean (fragmentation)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Early stream: prefer keeping large residuals open for big future items
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * post_residual as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: penalize leftover space, with non-linear (quadratic) shaping
    let mut score = pr * (1.0 + 0.8 * norm_pr);

    // Smooth coupling: later in the stream, tighter packing matters more
    score += 12.0 * progress * norm_pr * norm_pr;

    // Reward filling a bin nearly completely (smooth via post_residual)
    score -= 6.0 * (1.0 - norm_pr).powi(3) * (item_size as f64 / cap);

    // Penalize creating dead space that next item cannot use
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr > 0.0 {
            let waste = ((pr - nx).abs() / cap).max(0.0);
            score += 4.0 * waste * (1.0 - progress);
        }
    } else {
        // last item: strongly favor any fit
        score -= 20.0;
    }

    // Last-chance bin: reward using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 8.0 + 10.0 * progress;
    }

    // Mild penalty when many bins are open (encourage consolidation)
    score += 0.05 * open_bins_count as f64 * norm_pr;

    // Deviation from mean residual: prefer bins near the mean to keep balance
    let dev = (pr - mean_residual) / cap;
    score += 3.0 * dev * dev;

    // New-bin candidate: slight baseline so it only wins when open bins are poor
    if bin_residual == bin_capacity {
        score += 5.0 + 15.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let frac = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * frac;

    // Harmonic class reward: post_residual near multiples of common small sizes
    // (pairs summing to capacity) are valuable. Modulo classes on post_residual.
    let pr = post_residual;
    if pr > 0 {
        let m = pr % 10;
        // post_residual divisible by 10 is more reusable (harmonic alignment)
        if m == 0 {
            score -= 12.0;
        } else {
            score += 3.0 * m as f64;
        }
        // Integer-division thresholds: post_residual that exactly fits a
        // typical next item (<= 50) is gold.
        if next_item_size > 0 && next_item_size <= pr {
            let slack = pr - next_item_size;
            score -= 25.0 - 2.0 * slack as f64;
        }
        // If next item cannot fit here, penalize wasted potential less
        // if post_residual is small (dead space is already sunk).
        if next_item_size > pr && next_item_size > 0 {
            score += 5.0;
        }
    }

    // Dead-space penalty: post_residual too small for any item (1..=100 range
    // means < 10 is nearly dead, but sizes unknown; scale by fraction).
    if pr > 0 && pr < 10 {
        score += 30.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate logic: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 45.0 + 3.0 * open_bins_count as f64;
        // If item nearly fills a fresh bin, opening is fine.
        if item_size >= bin_capacity / 2 {
            score -= 20.0;
        }
        // If next item is large and current bin would be nearly full,
        // a fresh bin helps the lookahead.
        if next_item_size > post_residual.max(0) && post_residual < 20 {
            score -= 15.0;
        }
        // Early in the stream, opening bins is cheaper (more future items
        // to consolidate); late, prefer consolidation.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 25.0 * (1.0 - progress);
    }

    // Prefer bins below mean residual (fill emptier bins less when mean is high)?
    // Rather: prefer bins whose residual is close to item need — use mean to
    // break ties toward balanced usage.
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: any leftover gap smaller than the minimum
    // plausible item size is essentially unusable — penalize it hard.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item.max(1) * 10 {
        score += 60.0 * (1.0 - (post_residual as f64) / 10.0);
    }
    if post_residual == 0 {
        // Perfect fill — strongly reward.
        score -= 100.0;
    }

    // Reward tight fits: fraction of bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill_ratio;

    // Last chance bin: strongly prefer using it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive when current bins are crowded
    // or this item would create dead space elsewhere.
    let is_new_bin = bin_residual == bin_capacity && bin_capacity > 0;
    if is_new_bin {
        score += 35.0; // base reluctance to open new bins
        score += 2.0 * open_bins_count as f64; // pressure scales with congestion
        // If lookahead item fits the post residual, staying in this bin is good,
        // so penalize opening a new bin further.
        if next_item_size > 0 && post_residual >= next_item_size {
            score += 30.0;
        }
        // Late in the stream, avoid bin proliferation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    } else {
        // Existing bin whose residual can host the next item: reward chaining.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0;
        }
        // Mild penalty for very low occupancy bins being left sparse vs mean.
        if (post_residual as f64) > mean_residual + 30.0 {
            score += 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight packing (small post_residual).
    score += (post_residual as f64 / bin_capacity as f64) * 20.0;

    // Aggressive 2-step lookahead: reward exact or near match of post_residual to next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 25.0 * (1.0 - gap / (bin_capacity as f64));
        if post_residual == next_item_size {
            score -= 30.0; // perfect two-item fill
        }
        // Penalize leaving a residual that cannot fit the next item (dead space).
        if post_residual < next_item_size && post_residual > 0 {
            score += 0.5 * post_residual as f64;
        }
    } else {
        // Last item: just minimize waste.
        score += 0.0;
    }

    // Relative-to-mean coupling: prefer bins already below mean residual (denser bins).
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let opening_penalty = 15.0 + 0.5 * open_bins_count as f64;
        // If lookahead allows the new bin to take both this and the next item, reward it.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score = opening_penalty - 20.0;
        } else {
            score = opening_penalty + post_residual as f64;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item leaves little dead space.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual < 10 {
        score -= 10.0;
    }

    // Lookahead: reward if the next item can fit into the post residual (chain packing).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0 + 0.05 * next_item_size as f64;
        } else {
            // Penalize leaving a residual that is too small for the next item (dead space trap),
            // scaled by how close the next item is to fitting.
            let gap = (next_item_size - post_residual) as f64;
            if gap < 20.0 {
                score += 0.4 * gap;
            }
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Prefer using bins with larger residuals among fitting bins (best-fit via post_residual
    // already handles this; add mild tie-break toward bins below the mean residual to
    // consolidate fragmented space).
    if (bin_residual as f64) < mean_residual {
        score -= 1.5;
    } else {
        score += 0.5;
    }

    // New-bin candidate handling: penalize opening a new bin, but less when the item is large
    // or late in the stream (fewer future opportunities to fill the new bin).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let size_frac = item_size as f64 / bin_capacity as f64;
        let mut new_bin_penalty = 25.0;
        new_bin_penalty -= 15.0 * size_frac;      // large items justify fresh bins
        new_bin_penalty -= 10.0 * progress;       // late in stream, fresh bin likely wasted
        if open_bins_count == 0 {
            new_bin_penalty = 0.0;                // must open a bin
        }
        score += new_bin_penalty.max(0.0);
    }

    // Mild preference to keep the number of open bins from exploding.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fill = 1.0 - post / cap;

    // Base: reward tight fits with a non-linear (quartic) coupling of post_residual and progress
    let mut score = post * (1.0 + 0.35 * progress) - 12.0 * fill * fill * (0.5 + progress);

    // Smooth penalty for leaving awkward residual space, scaled by stream progress
    let awkward = (post / cap).powi(3) * (1.0 - (post / cap));
    score += 18.0 * awkward * (0.6 + 0.8 * progress);

    // Reward using bins when few fitting bins remain (last-chance pressure), smoothly
    if fitting_bins_count <= 1 {
        score -= 8.0 + 6.0 * progress;
    } else {
        score += 2.0 / fitting_bins_count as f64;
    }

    // Coupling with mean residual: prefer bins whose post-residual aligns with fleet average
    let dev = (post - mean_residual).abs();
    score += 0.05 * dev * (1.0 + progress);

    // Lookahead: smooth bonus if next item fits the post-residual
    if next_item_size > 0 {
        let fit_next = (next_item_size as f64 / cap).max(0.0).min(1.0);
        if (next_item_size as u32) <= post_residual {
            score -= 6.0 * fit_next * (1.0 - post / cap);
        } else {
            score += 3.0 * fit_next * (post / cap);
        }
    } else {
        // Last item: strongly prefer minimizing post residual
        score -= 10.0 * fill;
    }

    // Mild penalty for proliferating open bins, smoothed
    score += (open_bins_count as f64).powi(2) * 0.01 * (1.0 - progress);

    // New-bin candidate handling: only attractive early or when current bin fit is terrible
    if bin_residual == bin_capacity {
        let escape_bonus = (1.0 - fill) * (post / cap);
        score += 5.0 * escape_bonus * (1.2 - progress) - 4.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals divisible by common item
    // sizes are more reusable than odd leftovers.
    let pr = post_residual;
    if pr > 0 {
        let mut harmony = 0.0f64;
        for m in [10u32, 20, 25, 50] {
            if pr % m == 0 {
                harmony += 6.0;
            }
        }
        // exact fill is perfect
        if pr == 0 {
            harmony += 20.0;
        }
        // small dead space (< 10) is nearly useless
        if pr < 10 {
            harmony -= 15.0;
        }
        score -= harmony;
    } else {
        score -= 25.0; // perfect closure reward
    }

    // Quotient-class threshold: prefer bins whose post residual falls in a
    // "friendly" band (>= 25 allows medium items later).
    if pr >= 25 {
        score -= 4.0;
    } else if pr < 10 && pr > 0 {
        score += 6.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using
    // it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current
    // fit would create tiny dead space while the next item is large.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 8.0;
        if pr < 10 && next_item_size > pr {
            score -= 20.0; // opening fresh is justified
        }
        // late in stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && pr >= next_item_size {
        let diff = pr - next_item_size;
        if diff == 0 {
            score -= 15.0;
        } else if diff < 10 {
            score += 3.0;
        } else {
            score -= 5.0;
        }
    }

    // Spread control: prefer bins below mean residual (tighter bins first).
    score += (mean_residual - bin_residual as f64) * 0.05;

    // Mild preference to keep number of open bins small early on.
    score += open_bins_count as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize leftovers too small for the lookahead item
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 45.0 + 0.6 * post_residual as f64;
    }

    // Reward perfect fills strongly
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward near-perfect fills that still fit the next item (chain packing)
    if next_item_size > 0 && post_residual >= next_item_size && post_residual <= next_item_size + 5 {
        score -= 12.0;
    }

    // Open-bins pressure: mildly discourage proliferation of active bins
    score += 0.18 * open_bins_count as f64;

    // Last-chance bin before opening a new one: strong bonus to use it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 22.0;
    }

    // Brand-new empty bin candidate: baseline moderate, chosen only when open fits are poor
    if bin_residual == bin_capacity {
        score = post_residual as f64 + 8.0 + 0.18 * open_bins_count as f64;
        if next_item_size > 0 && post_residual < next_item_size {
            score += 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual already favored).

    // --- Aggressive 2-step lookahead ---
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 == nxt {
            // Perfect chaining: next item exactly fills this bin.
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Next item still fits here: mild reward scaled by how much slack remains.
            let slack = post_residual as f64 - nxt;
            score -= 25.0 - slack.min(25.0);
        } else {
            // Next item won't fit: penalize proportionally to wasted potential.
            let miss = nxt - post_residual as f64;
            score += (miss * 0.6).min(40.0);
        }
        // Chain quality: if this bin's post-residual matches next item AND the item
        // itself was a near-perfect fit, strongly reward.
        if (post_residual as f64 - nxt).abs() <= 2.0 {
            score -= 15.0;
        }
    } else {
        // Last item: just minimize leftover.
        score += post_residual as f64 * 0.5;
    }

    // --- Relative to mean residual ---
    let pr = post_residual as f64;
    if pr < mean_residual {
        // Below-average leftover: tighter than typical, good.
        score -= (mean_residual - pr).min(30.0) * 0.8;
    } else {
        // Above-average leftover: creating dead space relative to fleet.
        score += (pr - mean_residual).min(30.0) * 0.5;
    }

    // --- Last-chance bin protection ---
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        // This is the only bin that can fit the item; avoid opening a new bin.
        score -= 45.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Fresh empty bin: attractive only if current item is large or no good fits exist.
        let large_item = item_size as f64 > 0.6 * bin_capacity as f64;
        let poor_fits = fitting_bins_count == 0
            || (fitting_bins_count == 1 && next_item_size > 0 && next_item_size as f64 > mean_residual);
        if large_item || poor_fits {
            score -= 35.0;
        } else {
            // Prefer packing into existing bins; penalize premature opening.
            score += 50.0 + open_bins_count as f64 * 2.0;
        }
    }

    // --- Slight preference for filling bins that are already partially used ---
    let fill_ratio = (bin_residual as f64) / (bin_capacity as f64);
    score += fill_ratio * 8.0;

    // --- Late-stream consolidation: near the end, avoid spreading items ---
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: square the post-residual to strongly prefer near-exact fills.
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 40.0;

    // Perfect (or near-perfect) fill bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Lookahead: reward if next item fits into post_residual (chaining), penalize otherwise.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
            // extra reward for near-exact chain fit
            let chain_waste = post_residual - next_item_size;
            if chain_waste <= 5 {
                score -= 10.0;
            }
        } else {
            // next item won't fit here; penalize more if we leave a large unusable gap
            let gap = post_residual as f64;
            if gap < next_item_size as f64 {
                score += gap * 0.5;
            }
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item, strongly favor using it
    // over opening a new bin (which would waste this bin's residual).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 45.0;
    }

    // New-bin candidate handling: empty bin gets a mild penalty so it's chosen only when
    // no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 20.0;
        // Late in the stream, opening new bins is less costly than scattering items.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= progress * 15.0;
    }

    // Prefer bins with below-average residual (consolidate waste into few bins).
    let bin_res_f = bin_residual as f64;
    if mean_residual > 0.0 {
        score += (bin_res_f - mean_residual) * 0.3;
    }

    // Many open bins: encourage packing into existing bins to avoid bin proliferation.
    if open_bins_count > 4 {
        score -= 0.5 * open_bins_count as f64;
    }

    // Prefer filling fuller bins first (best-fit flavor scaled by residual).
    score += bin_res_f * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Reward tight fits: quadratic bonus as post_residual shrinks.
    let tightness = 1.0 - (pr / cap);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space more as the stream progresses (less time to fill leftovers).
    let waste_weight = 0.35 + 1.4 * progress * progress;
    score += waste_weight * (pr / cap) * (pr / cap) * cap * 0.1;

    // Lookahead coupling: if the next item fits into the post residual, reward this bin.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let fit_ratio = nxt / cap;
            score -= 12.0 * fit_ratio * (1.0 - progress);
        } else {
            // Next item won't chain here: penalize proportionally to how far it misses.
            let miss = (nxt - pr) / cap;
            score += 6.0 * miss * miss;
        }
    }

    // Last-chance bin: strongly reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate (fresh empty bin): make it neutral-to-slightly-worse than
    // a genuinely tight fit, but preferable to leaving huge waste late in the stream.
    if bin_residual == bin_capacity {
        score = cap * (0.5 + 0.3 * progress) + 10.0 * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));
        // If nothing fits anywhere except this, opening is clearly right.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Mild dispersion term: prefer bins whose residual deviates from the mean
    // in the direction of a tighter fit.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 4.0 * dev * dev * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that are "nice"
    // fractions of capacity (usable by small items), penalize dead space.
    let pr = post_residual;
    if pr > 0 {
        // Perfect-fit classes: residual in {0} handled above; small usable bands
        if pr <= 10 {
            score -= 40.0; // tiny residual = near-perfect packing
        } else if pr <= 20 {
            score -= 20.0;
        } else if pr <= 30 {
            score -= 8.0;
        } else if pr <= 50 {
            score += 6.0;
        } else {
            score += 12.0;
        }
        // Modulo-10 harmony: residuals divisible by 10 pair well with typical sizes
        if pr % 10 == 0 {
            score -= 6.0;
        } else if pr % 5 == 0 {
            score -= 3.0;
        } else {
            score += 2.0;
        }
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 60.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / 30.0).max(0.0);
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a bin when decent fits exist
    if bin_residual == bin_capacity {
        score += 30.0 + 2.0 * open_bins_count as f64;
        // but if no open bin fits well, allow opening
        if fitting_bins_count == 0 {
            score -= 45.0;
        }
    }

    // Progress-based tightening: late in the stream, waste matters more
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * (post_residual as f64) * 0.5;

    // Prefer bins tighter than the mean (consolidation)
    score -= 0.3 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space aggressively (non-linear)
    if post_residual > 0 {
        let dead = post_residual as f64;
        if dead < 10.0 {
            score += (10.0 - dead) * 6.0; // tiny gap = wasted capacity
        } else if dead < 20.0 {
            score += (20.0 - dead) * 2.5;
        }
    }

    // Perfect or near-perfect fit reward
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Reward leaving a gap that exactly fits the next item (lookahead pairing)
    if next_item_size > 0 && post_residual > 0 {
        let gap = post_residual as f64;
        let nxt = next_item_size as f64;
        if (gap - nxt).abs() < 2.0 {
            score -= 12.0;
        } else if gap < nxt {
            // gap too small for next item: mild penalty scaled by tightness
            score += (nxt - gap).min(15.0) * 0.6;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Pressure from number of open bins: discourage spreading when many bins open
    let open_pressure = open_bins_count as f64 * 0.15;
    score += open_pressure * (post_residual as f64 / bin_capacity as f64);

    // Slight preference for fuller bins relative to fleet mean residual
    if (bin_residual as f64) < mean_residual {
        score += (mean_residual - bin_residual as f64) * 0.2;
    } else {
        score -= (bin_residual as f64 - mean_residual) * 0.2;
    }

    // New-bin candidate: only attractive when current bin fit is very poor
    if bin_residual == bin_capacity {
        // baseline cost of opening a new bin
        score += 30.0;
        // but if item barely fits anywhere / would create big dead space, new bin is good
        let waste = post_residual as f64;
        if waste > 40.0 {
            score -= 45.0; // opening fresh bin better than dumping into cramped bin
        }
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    // Late-stream tightening: as stream progresses, be more conservative with new bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Near match: next item fits snugly into post residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 / (1.0 + slack / 10.0);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here: penalize proportionally to wasted potential.
        let overflow = (next_item_size - post_residual) as f64;
        score += 0.3 * overflow;
    }

    // Penalize leaving dead space that no typical item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Relative to mean residual: prefer bins tighter than average.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Late in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (bin_residual != bin_capacity) as u8 as f64;

    // New-bin candidate: neutral-ish, penalize slightly so it's chosen only when fits are bad.
    if bin_residual == bin_capacity {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fit.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 15 {
        score -= 60.0;
    }

    // Relative tightness: penalize large waste relative to capacity.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += waste_frac * waste_frac * 300.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 500.0;
    }

    // Lookahead: if the next item fits in the post residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 80.0;
        } else {
            // Penalize leaving a residual that's too small for the next item (dead space).
            score += 40.0 * (1.0 - (post_residual as f64 / next_item_size.max(1) as f64).min(1.0));
        }
    }

    // Global state coupling: when many bins are open, prefer consolidating into existing bins.
    score += (open_bins_count as f64).ln().max(0.0) * 10.0 * waste_frac;

    // If mean residual is high, prefer bins below the mean (spread usage) slightly;
    // if this bin is tighter than average, small bonus.
    if (bin_residual as f64) < mean_residual {
        score -= 20.0;
    } else {
        score += 10.0;
    }

    // Time horizon: early in the stream, be more conservative (keep residuals large);
    // late in the stream, be greedy and fill bins tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * waste_frac * 150.0;

    // New-bin candidate: make it attractive only when no good existing option exists.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = bin_capacity as f64 + 50.0;
        // Cheaper to open a new bin late in the stream or when the item is large.
        score -= progress * 60.0;
        score -= (item_size as f64 / bin_capacity as f64) * 100.0;
        // If several bins already fit the item, opening a new bin is wasteful.
        if fitting_bins_count > 1 {
            score += 300.0;
        }
        // If the only fitting bin would leave bad dead space, new bin is competitive.
        if next_item_size > 0 && post_residual_of_fallback(next_item_size) {
            score -= 100.0;
        }
    }

    score
}

// Helper cannot access state; inline logic instead — kept simple.
fn post_residual_of_fallback(_next_item_size: u32) -> bool {
    false
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Core: quadratic penalty on wasted space, scaled by stream progress.
    let mut score = post * (1.0 + 1.5 * progress) + 0.008 * post * post;

    // Reward tight fits: fill fraction of the bin.
    let fill = (bin_residual - post_residual) as f64 / cap;
    score -= 30.0 * fill * fill;

    // Lookahead coupling: reward if next item fits the post-residual exactly-ish.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post_residual >= next_item_size {
            let gap = (post - nx) / cap;
            score -= 12.0 * (1.0 - 2.0 * gap * gap);
        } else {
            // dead space unusable by next item -> penalize more as stream advances
            score += 8.0 * (nx - post) / cap * (1.0 + progress);
        }
    }

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: make it unattractive unless current bin would be badly fragmented.
    if bin_residual == bin_capacity {
        score += 20.0 + 10.0 * progress;
    }

    // Mild penalty when bin's residual deviates far from mean residual (fragmentation).
    let dev = (post - mean_residual) / cap;
    score += 3.0 * dev * dev;

    // Slight preference for consolidating among many open bins.
    score += 0.05 * open_bins_count as f64 * (post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: quantize into 5 capacity-fraction classes.
    let frac = post_residual as f64 / bin_capacity as f64;
    let class = (frac * 5.0).floor() as i32; // 0..4
    // Dead-space penalty grows non-linearly for small unusable residuals.
    if post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0 + (10 - post_residual) as f64;
    } else if post_residual < 30 {
        score += 4.0;
    }

    // Modulo arithmetic on post_residual: residuals divisible by common item
    // sizes (10/20/25) are "harmonic" and reusable, reward them.
    if post_residual % 10 == 0 {
        score -= 6.0;
    }
    if post_residual % 25 == 0 {
        score -= 3.0;
    }
    if post_residual % 20 == 0 {
        score -= 2.0;
    }

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            let nxt_post = post_residual - next_item_size;
            // harmonic chaining: next placement also leaves a class-0 residual
            if nxt_post % 10 == 0 {
                score -= 8.0;
            }
            if nxt_post == 0 {
                score -= 15.0;
            }
        } else {
            // next item won't fit here: mild penalty scaled by mismatch
            score += (next_item_size - post_residual).min(20) as f64 * 0.3;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0;
    }

    // New-bin candidate handling: an empty bin should only win when no open
    // bin offers a good (low-class) residual. Penalize new bins moderately,
    // more so early in the stream when bins are few.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 14.0 + 10.0 * (1.0 - progress) + open_bins_count as f64 * 0.5;
        // but if the item is large and mean residual is tight, new bin is fine
        if item_size as f64 > bin_capacity as f64 * 0.6 && mean_residual < item_size as f64 {
            score -= 20.0;
        }
    }

    // Slight preference for tighter bins overall (best-fit flavor).
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    // Class-based tiebreak: lower harmonic class (larger residual fraction)
    // is slightly penalized since big residuals are more valuable to keep.
    score += class as f64 * -1.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are excellent: reward residual close to 0.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Strict dead-space avoidance: penalize small unusable gaps
    // (gaps too small for the smallest plausible item, i.e. <= 10).
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0;
    } else if post_residual > 10 && post_residual <= 20 {
        score += 15.0;
    }

    // Prefer bins whose residual is close to the item (best-fit flavor).
    let waste_ratio = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += waste_ratio * 30.0;

    // Open-bins pressure: when many bins are open, discourage opening
    // new ones by making existing bins slightly more attractive; when
    // few bins are open, allow consolidation to be less dominant.
    score += open_bins_count as f64 * 0.5;

    // Last-chance bin: if this is the only bin that fits, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: neutral baseline; make it slightly unattractive
    // unless it genuinely beats filling an awkward gap.
    if bin_residual == bin_capacity {
        score += 25.0;
        // If the next item could combine with this item's leftover,
        // opening a fresh bin is more forgivable.
        if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
            score -= 30.0;
        }
    }

    // Lookahead: if the leftover exactly accommodates the next item,
    // reward this placement.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }

    // Mean residual coupling: bins far below the mean residual are
    // already tight; prefer them (their score is naturally lower).
    score -= (mean_residual - post_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fills strongly (non-linear).
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 5 {
        score -= 60.0 + 6.0 * (6 - post_residual) as f64;
    }

    // Aggressive 2-step lookahead: exact match with next item is excellent.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 80.0 - slack.min(80.0); // small slack still rewarded, decaying
        } else {
            // next item cannot fit here: dead space penalty grows with gap
            let gap = (next_item_size - post_residual) as f64;
            score += 15.0 + gap * 0.5;
        }
    }

    // Relative-to-mean-residual coupling: bins below mean residual are "dying";
    // prefer packing into them to consolidate.
    score -= (mean_residual - post_residual as f64) * 0.6;

    // Last-chance bin: strongly prefer using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // New empty bin candidate: only attractive when current fit is very poor
    // (large dead space) or no real alternative exists.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 > 40.0 && next_item_size > 0 && post_residual < next_item_size;
        let no_alternative = fitting_bins_count == 0;
        if poor_fit || no_alternative {
            score -= 90.0;
        } else {
            score += 250.0; // discourage opening new bins when a decent fit exists
        }
    }

    // Slight late-stream conservatism: keep residuals flexible early on.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * (post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * tightness * tightness;

    // Lookahead: reward if the next item can still fit in the post residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
        } else {
            // Dead space that next item cannot use: penalize more when post residual is small-but-nonzero.
            score += 6.0 * (1.0 - post_residual as f64 / next_item_size as f64).max(0.0);
        }
    } else {
        // Last item: just fill as fully as possible.
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Penalize bins whose residual deviates far below the mean (fragmented bins),
    // unless this placement fixes them.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // New-bin candidate: make it unattractive unless no open bin fits well.
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        score += 55.0 * scarcity + 0.5 * open_bins_count as f64;
        // If next item is huge and current item is small, opening fresh may be fine.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 10.0;
        }
    }

    // Late in the stream, prefer consolidating into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 3.0 * progress * (open_bins_count as f64 / 10.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual
    let mut score = pr as f64;
    // non-linear polynomial coupling of post residual with stream progress
    let poly = x * x * (1.0 - 2.0 * progress) + x * (progress * progress) + x * x * x * progress;
    score += 40.0 * poly;
    // reward tight fits more strongly as stream progresses
    let tightness = 1.0 - x;
    score -= 25.0 * tightness * tightness * (0.5 + progress);
    // last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - x);
    }
    // lookahead: reward leaving room for the next item, penalize near-miss
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        if x >= nx {
            score -= 15.0 * nx * (1.0 - x);
        } else {
            score += 20.0 * (nx - x);
        }
    }
    // penalize scattering across many open bins
    score += 2.0 * open_bins_count as f64 * x;
    // new-bin candidate: prefer opening a new bin only for large items / late stream
    if bin_residual == bin_capacity {
        score += 15.0 + 10.0 * progress - 8.0 * (item_size as f64 / cap);
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize dead space into capacity fractions.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let post_frac = post / cap; // 0..1

    // Class A: near-perfect fit (post_residual in a small harmonic band)
    if post_residual <= 2 || post_residual % 10 == 0 {
        score -= 18.0;
    } else if post_residual <= 8 {
        score -= 10.0;
    }

    // Integer-division thresholds on post_residual: reward residuals that
    // still admit common item sizes (harmonic classes of 100).
    let admits = |r: u32, s: u32| r >= s;
    for s in [10u32, 20, 25, 40, 50] {
        if admits(post_residual, s) {
            score -= 2.0;
        }
    }
    // Penalize residuals in "dead zones" (only admit very large items)
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    } else if post_residual >= 10 && post_residual < 20 && next_item_size > post_residual && next_item_size > 0 {
        score += 6.0;
    }

    // Modulo coupling: if next item exactly divides / fits the post residual, reward strongly.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
        if post_residual % next_item_size == 0 {
            score -= 10.0;
        }
        if post_residual == next_item_size {
            score -= 12.0; // perfect two-item closure
        }
    } else if next_item_size > 0 {
        // next item cannot use this residual: penalize proportionally to wasted fraction
        score += 5.0 * post_frac;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: neutral-ish baseline, adjusted by stream context.
    if bin_residual == bin_capacity {
        // Prefer new bin early in stream or when existing bins are badly fragmented,
        // or when current item is small (save large residuals for large items).
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = mean_residual / cap;
        if post_frac < 0.35 {
            score -= 6.0; // small item into fresh bin keeps big residuals intact
        }
        if fragmentation < 0.25 && progress < 0.5 {
            score -= 4.0;
        }
        if next_item_size > 0 && next_item_size > item_size && item_size < 30 {
            score -= 5.0; // reserve space for the bigger lookahead item
        }
        // Slight penalty so we don't proliferate bins when a decent fit exists.
        score += 3.0 + 0.5 * open_bins_count as f64;
    }

    // Tie-break: prefer bins whose residual is close to the item (tight packing).
    score += 0.05 * (bin_residual as f64 - item_size as f64).abs();

    // Mild preference for bins below mean residual (fill emptier-but-usable bins first).
    score -= 0.02 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // --- Strict dead-space avoidance ---
    // A residual that is too small to ever hold a plausible future item is dead space.
    // Penalize it super-linearly: small gaps (1..=12) are almost certainly wasted.
    let pr = post_residual as f64;
    if post_residual < 12 {
        score += (12.0 - pr) * (12.0 - pr) * 1.5; // quadratic dead-space penalty
    } else if post_residual < 25 {
        score += (25.0 - pr) * 0.8; // mild penalty for tight-but-risky gaps
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // --- Open bins pressure ---
    // Prefer filling existing bins; escalate with how many bins are already open
    // and how late in the stream we are (consolidation matters more later).
    let bin_pressure = 6.0 + open_bins_count as f64 * 0.6 + progress * 8.0;
    score -= bin_pressure;

    // If this is the ONLY fitting bin, placing here avoids opening a new bin: strong reward.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 + progress * 10.0;
    }

    // --- Lookahead coupling ---
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        // If the next item fits exactly in the post residual, big reward for this placement.
        if (pr - nxt).abs() < 0.5 {
            score -= 35.0;
        } else if pr >= nxt {
            score -= 10.0; // residual remains usable for the lookahead item
        } else {
            // residual too small for next item: penalize proportionally to the shortfall
            score += (nxt - pr).min(30.0) * 0.7;
        }
    }

    // --- New-bin candidate calibration ---
    // The empty-bin candidate has bin_residual == bin_capacity. It should only win when
    // no open bin offers a decent fit. Penalize it moderately, scaled by open bins count.
    if bin_residual == bin_capacity {
        score += 15.0 + open_bins_count as f64 * 2.0 + progress * 10.0;
        // But if no open bin can fit the item at all, new bin must look attractive.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Slight tie-breaker: prefer bins whose residual is already below mean (denser bins).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: strongly reward leaving zero residual.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: if the next item exactly fills the
    // remaining residual, this placement sets up a perfect follow-up.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 500.0;
    }

    // Penalize residuals that are "almost" fitting the next item
    // (dead space the next item can't use).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score += 0.5 * slack;
    } else if next_item_size > 0 && post_residual > 0 {
        // Residual smaller than next item: unusable for lookahead item.
        score += 0.3 * post_residual as f64;
    }

    // Relative to mean residual: prefer bins that are already more
    // filled than average (tight packing).
    score -= (mean_residual - post_residual as f64) * 0.4;

    // Last-chance bin: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: make empty bins attractive only when the item
    // is large relative to capacity or the fit elsewhere is poor.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        score += 40.0 - 80.0 * fill_ratio;
        // Few open bins -> opening a new bin is cheap; many -> costly.
        score += 5.0 * (open_bins_count as f64).sqrt();
    }

    // Early in stream: slightly prefer consolidating into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;

    // Reward tight fits (small post residual) more strongly as the stream progresses.
    score -= (1.0 - post_residual as f64 / bin_capacity as f64) * (18.0 + 22.0 * progress);

    if is_new_bin {
        // Opening a new bin is expensive by default.
        score += 35.0 + 15.0 * progress;
        // But if this bin is the last chance (no other fitting bin), strongly favor it.
        if fitting_bins_count == 0 {
            score -= 200.0;
        } else if fitting_bins_count == 1 {
            score -= 25.0;
        }
        // Chain bonus: next item fits into the fresh residual.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 30.0;
        }
    } else {
        // Dead-space penalty: leftover that the lookahead item cannot use.
        if next_item_size > 0 && next_item_size > post_residual {
            score += (10.0 - post_residual as f64).max(0.0) * 1.5;
        }
        // Perfect chain: next item exactly consumes remaining space.
        if next_item_size > 0 && next_item_size == post_residual {
            score -= 40.0;
        }
        // Last-chance bin: prefer using it over opening a new bin.
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
        // Slight penalty when this bin's residual is far above the mean (hoarding space).
        score += ((bin_residual as f64 - mean_residual) * 0.15).max(0.0);
        // Early stream: prefer filling bins with larger residuals less aggressively.
        score += (1.0 - progress) * 4.0;
        // Many open bins: encourage consolidation.
        if open_bins_count > 4 {
            score -= 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let tightness = (item_size as f64 / cap).clamp(0.0, 1.0);
    let fill = 1.0 - post / cap;

    // Base: prefer small post_residual (tight fit)
    let mut score = post;

    // Non-linear polynomial coupling: tight fits are rewarded more as stream progresses
    let coupling = (fill * fill) * (1.0 + 2.0 * progress) * cap * 0.5;
    score -= coupling;

    // Penalize post-residual that cannot fit the lookahead item (dead space)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post < nx {
            score += (nx - post) * (0.6 + 0.8 * progress);
        } else {
            // reward leaving exactly room for the next item (smooth quadratic)
            let d = post - nx;
            score -= (nx / cap) * (1.0 - (d / cap)) * cap * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= cap * (0.8 + 0.6 * progress);
    }

    // New-bin candidate: neutral-ish, slightly penalized early, more attractive late
    if bin_residual == bin_capacity {
        score = cap * (1.15 - 0.5 * progress) + 0.3 * mean_residual;
    }

    // Mild penalty for residual far from useful sizes (dead-space shaping)
    let half = cap * 0.5;
    let waste = ((post - half) / cap).abs();
    score += waste * waste * cap * 0.25;

    // Penalize proliferation of open bins with large mean residual late in stream
    score += 0.05 * open_bins_count as f64 * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: classify post_residual by integer division
    // into capacity bands. Small classes (near-zero residual) are excellent fits.
    let band = post_residual / 13; // harmonic class width
    score -= match band {
        0 => 30.0,                       // residual <= 12: near-perfect packing
        1 => 15.0,                       // residual <= 25: still tight
        2 => 5.0,                        // moderate
        3 => -5.0,                       // roomy bin, mild penalty
        _ => -12.0,                      // large leftover: deprioritize
    };

    // Modulo arithmetic on post_residual: residuals that are common item-size
    // remainders are more reusable. Reward residuals divisible by small sizes.
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 8.0; }
        else if post_residual % 5 == 0 { score -= 4.0; }
        else if post_residual % 20 == 0 { score -= 10.0; }
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly reward this bin (perfect chain).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // reward proportional closeness of the chain fit
            let gap = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item won't fit here: slight penalty proportional to overshoot
            let over = (next_item_size - post_residual) as f64;
            score += 3.0 * (over / bin_capacity as f64);
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate (empty bin): make it attractive only if no open bin
    // offers a good (tight) fit. Base penalty keeps it behind decent fits.
    if bin_residual == bin_capacity {
        let tight_exists = post_residual == 0; // impossible for empty bin; use mean_residual as proxy
        let _ = tight_exists;
        // If mean residual across open bins is small, open bins are nearly full:
        // opening a new bin is reasonable.
        let mean_bonus = if mean_residual < 20.0 { 10.0 } else { 0.0 };
        score += 45.0 - mean_bonus;
        // Late in the stream, prefer consolidating into open bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 15.0 * progress;
        // Many open bins: discourage spreading further.
        score += 2.0 * open_bins_count as f64;
    }

    // Mild preference for filling fuller bins (waste-avoidance coupling).
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 10.0 * fill;

    // Dead-space penalty: residual too small for the smallest plausible item (1..100
    // unknown, assume ~10 floor) is wasted space.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // for any plausible future item are heavily penalized.
    let dead_threshold = 20.0;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 3.0;
    }

    // Reward tight fits (perfect fill is ideal).
    if post_residual == 0 {
        score -= 50.0;
    }

    // If the next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item can't use the leftover: penalize proportionally to wasted space.
        score += (next_item_size as f64 - post_residual as f64) * 0.5;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Pressure from number of open bins: discourage spreading across many bins
    // unless the fit is good.
    score += open_bins_count as f64 * 0.3;

    // Prefer bins whose residual is close to the mean (avoid fragmenting outliers).
    score += ((bin_residual as f64 - mean_residual).abs()) * 0.2;

    // New-bin candidate: make it attractive only when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin grows with stream progression.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 30.0 + progress * 20.0;
        // If other bins can fit the item, opening a new bin is rarely better.
        if fitting_bins_count > 0 {
            score += 15.0;
        }
    }

    // Mild reward for using bins that are already fairly full.
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    // Near-match: post_residual within a small window of next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as f64 - next_item_size as f64).abs();
        if diff <= 5.0 {
            score -= 200.0 - diff * 20.0;
        }
        // Penalize post_residual that is small but unusable by the next item
        if post_residual > 0 && post_residual < next_item_size {
            score += 30.0;
        }
    }

    // Zero residual is excellent (bin perfectly closed)
    if post_residual == 0 {
        score -= 500.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // New-bin candidate: prefer it only when no open bin fits well
    if bin_residual == bin_capacity {
        let pressure = fitting_bins_count as f64;
        score += 250.0 - 60.0 * pressure;
        // Early in the stream, opening fresh bins is cheaper
        if total_items > 0 {
            let progress = step_index as f64 / total_items as f64;
            score -= 50.0 * (1.0 - progress);
        }
    }

    // Slight preference for bins below mean residual (consolidate large residuals)
    score -= (mean_residual - bin_residual as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic penalty on large post-residual.
    score += (post_residual as f64 / cap).powi(2) * 40.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: reward residuals that exactly fit the next item,
    // penalize residuals just below the next item size (dead space).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if (post_residual as f64 - nx).abs() < 0.5 {
            score -= 45.0;
        } else if post_residual > 0 && (post_residual as u32) < next_item_size {
            score += (nx - post_residual as f64) * 0.6;
        } else if post_residual as f64 >= nx {
            score -= (1.0 - ((post_residual as f64 - nx) / cap).abs()) * 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Global pressure: many open bins with high mean residual -> prefer
    // filling existing bins rather than spreading.
    let pressure = (open_bins_count as f64).ln().max(0.0) * (mean_residual / cap).max(0.0);
    score -= pressure * 6.0;

    // Time horizon: early in the stream, be picky (penalize mediocre fits);
    // late in the stream, accept decent fits more readily.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * (post_residual as f64 / cap) * 25.0;

    // New-bin candidate: make it unattractive unless it would clearly beat
    // poor fits (e.g., item is huge relative to typical residuals).
    if bin_residual == bin_capacity {
        score += 55.0;
        // Allow opening a new bin when item barely fits anywhere and
        // mean residual is small (existing bins are nearly full anyway).
        if fitting_bins_count == 1 && mean_residual < item_size as f64 * 0.5 {
            score -= 70.0;
        }
        // Late in stream with many bins, discourage extra bins.
        score += progress * 20.0;
    }

    // Mild preference for bins whose residual was already small.
    score += (bin_residual as f64 / cap) * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer minimal post residual (tight fit).
    let mut score = pr;

    // Non-linear waste penalty: dead space grows super-linearly as residual shrinks
    // toward unusable sizes (quadratic coupling with normalized post-residual).
    let pr_norm = pr / cap;
    score += 0.6 * pr_norm * pr_norm * cap * (1.0 - pr_norm);

    // Tight-fit reward: strongly favor placements leaving small residuals,
    // amplified by stream progress (late stream => consolidate).
    let tight = 1.0 - pr_norm;
    score -= (1.5 + 2.5 * progress) * tight * tight * 10.0;

    // Perfect-fit style bonus when post residual could host the lookahead item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let match_term = 1.0 - ((pr - nxt).abs() / cap);
        if pr >= nxt {
            score -= 8.0 * match_term * match_term * (0.5 + progress);
        }
    }

    // Last-chance bin: penalize leaving it unusable if alternatives exist.
    if fitting_bins_count <= 1 && bin_residual != bin_capacity {
        score += 6.0 * (1.0 - progress);
    }

    // New-bin candidate: prefer opening a new bin only when it is early in the
    // stream or all open bins are badly fragmented (high mean residual).
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / cap;
        score += 14.0 * progress * (1.0 - fragmentation);
        score -= 4.0 * fragmentation * fragmentation;
        score += pr; // empty bin has maximal residual: slight self-penalty
    }

    // Mild penalty for spreading across too many open bins late in stream.
    score += 0.15 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: classify post_residual by
    // capacity fraction bands using integer division thresholds.
    let post = post_residual as f64;
    let class = (post_residual * 4) / bin_capacity; // 0..3 harmonic band
    match class {
        0 => score -= 60.0,                       // near-perfect fit, dead space ~0
        1 => score -= 20.0,                       // small but possibly usable sliver
        2 => score += 0.0,                        // mid band: neutral
        _ => score += 15.0,                       // large leftover: bin was underfilled
    }

    // Reward if the next item fits exactly into the post residual
    // (harmonic pairing between consecutive items).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            score -= 25.0;
            // finer: reward next item leaving its own tiny remainder
            let next_post = post_residual - next_item_size;
            if (next_post * 4) / bin_capacity == 0 {
                score -= 30.0;
            }
        } else {
            // next item cannot use this bin's leftover: mild penalty scaled
            // by how much of the leftover would be wasted
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly prefer using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate (empty bin): penalize opening bins unless the current
    // item is large relative to capacity or no good fit exists.
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / cap;
        // opening early is fine for big items, bad for small ones
        score += 70.0 - 90.0 * frac;
        if open_bins_count == 0 {
            score -= 100.0; // must open the first bin
        }
        // late in stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
    }

    // Prefer bins whose residual is below average (tighter bins first),
    // with a harmonic coupling to mean residual.
    let dev = mean_residual - bin_residual as f64;
    score -= 0.15 * dev;

    // Slight preference for filling bins with smaller residuals overall.
    score += 0.1 * (bin_residual as f64 / cap);

    // Penalize extremely fragmented open-bin pools.
    if open_bins_count > 8 {
        score += 0.5 * (open_bins_count as f64 - 8.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable small gaps are heavily penalized.
    // A gap is "dead" if it is smaller than the smallest plausible item (1),
    // but more meaningfully, gaps below ~10 waste capacity for typical streams.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Perfect fits are strongly rewarded.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Tight fits (small post_residual relative to item) get a mild bonus.
    if item_size > 0 {
        let tightness = post_residual as f64 / bin_capacity as f64;
        score += 30.0 * tightness * tightness;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // reward heavily; if it cannot fit, penalize (creates stranded space).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size > post_residual && post_residual > 0 {
            score += 15.0;
        } else {
            // next item fits: mild reward proportional to how well it fills
            score -= 10.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        }
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // rather than spreading; penalize candidates whose residual stays large.
    let obp = open_bins_count as f64;
    score += obp * (post_residual as f64 / bin_capacity as f64) * 8.0;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless post residual would be tiny/dead).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
        if post_residual < 10 && post_residual > 0 {
            score += 30.0; // cancel bonus if it creates dead space
        }
    }

    // New-bin candidate (empty bin): make it attractive only when open-bin
    // pressure is high and fits are poor. Base neutral cost for opening a bin.
    if bin_residual == bin_capacity {
        score += 20.0;
        // If many bins are open, discourage opening yet another unless necessary
        score += obp * 2.0;
        // But if mean residual across open bins is small (bins nearly full),
        // opening a new bin is reasonable — reduce penalty.
        score -= mean_residual * 0.3;
    }

    // Stream progression: late in the stream, consolidate aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward when post_residual exactly matches the next item (perfect 2-step chain).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Penalize leftover slack after the next item would fit.
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 - slack.min(25.0);
    }

    // Penalize small unusable post_residual (dead space).
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 15.0;
    }

    // Exact fill of the bin is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Prefer bins with residual below mean (tight bins pack better).
    let diff = post_residual as f64 - mean_residual;
    score += 0.3 * diff;

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New empty bin candidate: penalize moderately unless no good fit exists
    // (i.e., many bins fit but this would waste a fresh bin).
    if bin_residual == bin_capacity {
        score += 20.0;
        if next_item_size > 0 && next_item_size > bin_residual - item_size {
            score -= 0.0; // unreachable, kept for symmetry
        }
        // Opening a new bin is attractive when the item leaves awkward residue
        // in existing bins; approximate via large item size late in stream.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if item_size > 60 {
            score -= 15.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: penalize wasted space quadratically (dead space is worse the smaller it is).
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let tightness = 1.0 - (pr / cap);
    score += 0.35 * pr * pr / cap;
    score -= 6.0 * tightness; // reward tight fits

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            // Next item fits, but penalize leftover after next item.
            let next_left = post_residual - next_item_size;
            score -= 15.0 - 0.1 * next_left as f64;
        } else {
            // Next item won't fit here: slight penalty proportional to overshoot.
            let over = (next_item_size - post_residual) as f64;
            score += 0.08 * over;
        }
    } else {
        // Last item: just minimize residual.
        score += 0.0;
    }

    // Last-chance bin: strongly prefer using the only bin that fits the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Global state: when many bins are open with large mean residual, prefer
    // consolidating into bins that are already fragmented.
    let frag_gap = (mean_residual - pr).abs();
    score += 0.05 * frag_gap;

    // Prefer bins whose residual is below the mean (tighter than average).
    if (pr as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 2.0;
    }

    // Time horizon: early in the stream, opening new bins is cheap (keep new-bin
    // candidate competitive); late in the stream, squeeze existing bins harder.
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let new_bin_candidate = bin_residual == bin_capacity && post_residual == bin_capacity;
    if new_bin_candidate {
        // Cost of a new bin decreases early, increases late.
        score += 25.0 + 40.0 * progress - 10.0 * (1.0 - progress);
        // But if no open bin fits well, allow new bin when item is large.
        if item_size as f64 > 0.7 * cap {
            score -= 20.0;
        }
    }

    // Open-bin count pressure: with few open bins, filling them fully is good.
    if open_bins_count > 0 {
        score -= 2.0 / open_bins_count as f64;
    }

    // Slight preference for larger items going into emptier bins.
    score -= 0.02 * item_size as f64 * (pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: quadratic penalty on post-residual (dead space), slightly convex.
    let mut score = pr * (1.0 + 0.008 * pr / cap);

    // Smooth cubic coupling of dead space with stream progress:
    // late in the stream, residual waste matters more (fewer chances to fill it).
    let t = progress;
    let late = t * t * (3.0 - 2.0 * t); // smoothstep in [0,1]
    score += late * pr * pr / cap * 0.9;

    // Reward tight fits: bonus when post_residual is small relative to capacity.
    let tight = (1.0 - pr / cap).clamp(0.0, 1.0);
    score -= 6.0 * tight * tight * tight;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (penalize the alternative implicitly).
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Lookahead: reward bins whose post-residual can still host the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 3.0 * (1.0 - pr / cap);
        } else {
            // penalize leaving a residual too small for the lookahead item
            score += 2.0 * (nxt - pr) / cap * 10.0;
        }
    }

    // Mild pressure toward consolidating into fewer bins when many are open.
    score += 0.02 * open_bins_count as f64 * (pr / cap);

    // New-bin candidate: empty bin gets a moderate penalty so it only wins
    // when all open bins have large residuals (poor fits).
    if bin_residual == bin_capacity {
        score += 10.0 + 15.0 * late;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how well it pairs with common small items
    let pr = post_residual;
    if pr > 0 {
        // modulo arithmetic on post_residual: residues that divide cleanly by
        // common item sizes (10,20,25,50) are "harmonic" and reusable
        let harmonic = if pr % 50 == 0 { 3.0 }
            else if pr % 25 == 0 { 2.0 }
            else if pr % 20 == 0 { 2.0 }
            else if pr % 10 == 0 { 1.0 }
            else { 0.0 };
        score -= harmonic;

        // integer division threshold: post_residual in [1,9] is dead space
        if pr / 10 == 0 {
            score += 25.0; // heavy penalty: unusable sliver
        } else if pr <= 15 {
            score += 8.0; // near-dead space
        }
    } else {
        score -= 12.0; // perfect fit is ideal
    }

    // Coupling with lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 && next_item_size <= pr {
        if next_item_size == pr {
            score -= 20.0;
        } else {
            // harmonic match: post_residual % next_item_size == 0 means chainable
            if pr % next_item_size == 0 {
                score -= 10.0;
            }
            score -= 4.0;
        }
    } else if next_item_size > pr && next_item_size > 0 {
        score += 6.0; // next item won't fit here anyway
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New empty bin candidate: penalize mildly so it's chosen only when
    // existing fits are bad; encourage when residuals are fragmented
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 18.0 - 10.0 * progress;
        // open a new bin if open bins are fragmented (low mean residual)
        if mean_residual < item_size as f64 * 0.5 {
            score -= 10.0;
        }
    }

    // Prefer tighter bins: relative fill fraction
    let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 6.0 * fill;

    // Mild penalty for proliferating open bins
    score += 0.15 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64);
    }
    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward residuals that can still host the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += 5.0 + (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many bins open, prefer filling existing ones.
    let pressure = open_bins_count as f64 * 1.5;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins already open.
        score += pressure + 10.0;
        // Allow opening a new bin early in the stream when few bins exist.
        score -= (total_items.saturating_sub(step_index)) as f64 * 0.02;
    } else {
        score -= pressure * 0.5;
        // Slightly prefer bins tighter than average.
        score += (mean_residual - bin_residual as f64) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact/near-exact fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    } else if post_residual <= 15 {
        score -= 80.0;
    }

    // 2-step lookahead: if the next item fits exactly in post_residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            let leftover = post_residual - next_item_size;
            score -= 120.0 * (1.0 - leftover as f64 / 100.0);
        } else {
            // Next item cannot fit here; penalize leaving a gap smaller than next item.
            let gap = post_residual as f64;
            if gap < next_item_size as f64 {
                score += 40.0 + (next_item_size as f64 - gap);
            }
        }
    }

    // Compare against mean residual: prefer bins tighter than average.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // New-bin candidate handling: make empty bins attractive only when no good fit exists.
    if bin_residual == bin_capacity {
        if post_residual >= 60 {
            score += 150.0; // discourage wasting a fresh bin on small items
        } else {
            score += 60.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 30.0;
        }
    }

    // Late in the stream, consolidate aggressively into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 50.0 * progress * (fitting_bins_count as f64).recip().max(0.05);

    // Slight preference for bins with more open bins (packing density control).
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fractional fill quality: reward high fill ratio of the bin.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 12.0 * fill * fill;

    // Strongly prefer exact / near-exact fits.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    } else if post_residual < 10 {
        score -= 8.0;
    }

    // Dead-space penalty: residuals too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits in the post residual,
    // reward leaving that much space; otherwise penalize wasted space
    // relative to the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size && post_residual < next_item_size + 10 {
            score -= 10.0;
        }
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        score += 0.15 * gap;
    }

    // Time horizon: late in the stream, consolidate aggressively into
    // existing bins rather than opening new ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual < bin_capacity {
        score -= 20.0 * progress;
    } else {
        // New-bin candidate: penalize opening bins, more so later in the stream
        // and when many bins are already open.
        score += 30.0 + 40.0 * progress + 2.0 * open_bins_count as f64;
    }

    // Prefer bins with below-average residual (tighter bins) to keep
    // larger residual bins flexible for big future items.
    if bin_residual < bin_capacity {
        score += 0.3 * (mean_residual - bin_residual as f64);
    }

    // Slight preference for bins that fit well relative to item size.
    let ratio = item_size as f64 / bin_residual as f64;
    score -= 5.0 * ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let norm_pr = pr / cap; // in [0,1]
    let w = 0.5 + progress; // grows with stream progress
    score += w * norm_pr * norm_pr * cap * 0.35;

    // Penalize residual that is unusably small (dead space) more than quadratic.
    score += 6.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Lookahead: reward leaving room for the next item, penalize blocking it.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 4.0 * (1.0 - (nxt / cap)) * (1.0 - progress);
        } else {
            score += 5.0 * ((nxt - pr) / cap) * (0.5 + progress);
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Mild preference for bins tighter than the mean (good fits first).
    score += 0.15 * ((pr - mean_residual) / cap);

    // Early stream: encourage packing into open bins rather than opening new ones.
    score += (1.0 - progress) * 2.0 * (open_bins_count as f64).sqrt();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residue classes mod 10 / mod 20
    let post = post_residual;
    let class10 = (post % 10) as f64;
    let class20 = (post % 20) as f64;

    // Dead-space penalty: post residual that cannot be filled by small items (1..10)
    // is worse than a residual that lands exactly on a harmonic multiple.
    if post > 0 && post < 10 {
        score += 40.0; // tiny unusable sliver
    }
    if post == 0 {
        score -= 60.0; // perfect fill
    }

    // Reward post residuals on harmonic multiples of 10/20 (easy future fits)
    if class10 == 0.0 && post > 0 {
        score -= 12.0;
    }
    if class20 == 0.0 && post > 0 {
        score -= 6.0;
    }
    // Penalize odd/awkward residues
    score += class10 * 0.8;
    score += (10.0 - class20).abs() * 0.3;

    // Lookahead coupling: does next item fit exactly into post residual?
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 50.0; // exact chain fit
        } else if next_item_size <= post {
            let slack = (post - next_item_size) as f64;
            score += slack * 0.5;
            // harmonic check on chained residual
            if (post - next_item_size) % 10 == 0 {
                score -= 8.0;
            }
        } else {
            // next item cannot use this bin's residual; residual is final
            score += 15.0;
        }
    } else {
        // last item: prefer filling as much as possible
        score -= 20.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are crowded
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64) * (mean_residual / bin_capacity as f64);
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut nb = 55.0;
        nb -= pressure * 8.0;
        nb -= progress * 10.0;
        if fitting_bins_count == 0 {
            nb = -100.0; // no alternative
        }
        score += nb;
    }

    // Mild preference for fuller bins among equals
    score -= (bin_capacity - bin_residual) as f64 * 0.15;

    // Mean-residual coupling: when mean residual is high, prefer consolidating into large-residual bins
    score += (mean_residual - post as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // even the smallest plausible item are pure waste. Penalize them hard.
    let dead_threshold = 10.0f64.min(bin_capacity as f64 * 0.12);
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 6.0;
    }
    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Tight fit reward: how well the item fills this bin relative to its residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 25.0;

    // Last-chance pressure: if this is the only bin that fits, prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin is a fallback; make it
    // moderately unattractive unless the current item leaves a good gap
    // or no open bin fits well.
    if bin_residual == bin_capacity {
        score += 15.0 + open_bins_count as f64 * -1.0;
        // If next item is large, a fresh bin is more valuable.
        if next_item_size as f64 > bin_capacity as f64 * 0.5 {
            score -= 20.0;
        }
    }

    // Lookahead synergy: if the next item fits exactly into the post residual,
    // strongly favor this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    }
    // Penalize leaving a gap the next item cannot use.
    if next_item_size > post_residual && post_residual > 0 {
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing
    // bins rather than spreading out.
    score += open_bins_count as f64 * 0.8;

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is closer to being closed out; finishing it off is good.
    let residual_diff = mean_residual - bin_residual as f64;
    score += residual_diff * 0.3;

    // Stream progression: late in the stream, be more aggressive about
    // closing bins tightly.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score -= progress * (post_residual as f64) * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            score -= 25.0 * (1.0 - slack as f64 / bin_capacity as f64);
        } else {
            // next item can't follow: penalize wasted space
            score += 8.0 + 0.1 * post_residual as f64;
        }
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score -= 15.0;
    } else if post_residual < 20 {
        score -= 5.0;
    }

    // Relative-to-mean residual coupling
    score -= 0.3 * (bin_residual as f64 - mean_residual);

    // Last-chance bin pressure
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Penalize opening new bins when many open bins exist and item fits well elsewhere
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 + 20.0 * progress + 2.0 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size > bin_residual {
            score -= 60.0; // nothing fits anyway, new bin justified
        }
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 45.0; // new bin gives perfect lookahead fit
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 60.0 * fit_ratio * fit_ratio;

    // Penalize large dead space after placement (nonlinear).
    if post_residual > 0 {
        let dead = post_residual as f64 / bin_capacity as f64;
        score += 25.0 * dead * dead;
    } else {
        score -= 40.0; // perfect fill bonus
    }

    // Lookahead: reward if the next item fits the post-residual exactly or well.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_fit = next_item_size as f64 / post_residual as f64;
        score -= 35.0 * next_fit * next_fit;
    } else if next_item_size > 0 && post_residual > 0 {
        // next item won't fit: penalize proportionally to wasted residual
        score += 0.15 * post_residual as f64;
    }

    // Last-chance bonus: if this is the only bin that can fit the item, use it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: penalize opening a new bin unless current residuals are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual - post_residual as f64).abs();
        // Opening new bin is penalized more when few bins open or early in stream.
        score += 55.0 + 30.0 * (1.0 - progress) + 2.0 * open_bins_count as f64;
        // But if mean residual is small (bins nearly full), new bin is more attractive.
        score -= 0.4 * mean_residual;
        let _ = fragmentation;
    }

    // Mild preference for bins below mean residual (consolidating space).
    score += 0.1 * (bin_residual as f64 - mean_residual).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: prefer small post-residual (tight fit), non-linearly.
    let mut score = norm_post * norm_post * cap;

    // Smooth coupling: waste matters more as the stream progresses.
    let urgency = 1.0 + 2.0 * progress * progress;
    score *= urgency;

    // Penalize post-residuals that are "just barely unusable" (dead space):
    // smooth penalty peaking when post_residual is small but < typical item size.
    let deadness = if post > 0.0 {
        let r = norm_post;
        r * (1.0 - r) * (1.0 - r) * cap
    } else {
        -3.0 // perfect fit reward
    };
    score += deadness * 4.0;

    // Reward bins whose residual was already small (consolidation).
    let pre_norm = bin_residual as f64 / cap;
    score -= (1.0 - pre_norm) * (1.0 - pre_norm) * 2.0;

    // Last-chance bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 6.0;
    } else if fitting_bins_count > 1 {
        // Among several candidates, mildly prefer tighter ones (already via post).
        score += 0.5;
    }

    // Lookahead: if next item fits in the post-residual, reward this placement.
    if next_item_size > 0 && (post_residual as u64) >= (next_item_size as u64) {
        let slack = (post_residual - next_item_size) as f64 / cap;
        score -= 3.0 * (1.0 - slack);
    } else if next_item_size > 0 {
        // Next item won't fit here; penalize leaving awkward residual.
        score += 1.5 * norm_post;
    }

    // New-bin candidate (empty bin): should only win when no decent fit exists.
    if bin_residual == bin_capacity {
        // Penalize opening new bins early; allow it late or when few bins fit.
        let open_pressure = (fitting_bins_count as f64).recip();
        score = cap * (0.6 + 0.4 * (1.0 - progress)) * open_pressure * open_pressure + 2.0;
        if fitting_bins_count == 0 {
            score -= 10.0; // no alternative
        }
        // Late in stream, small residual waste elsewhere favors reuse: keep new-bin expensive.
        score += 2.0 * progress;
    }

    // Mild penalty for proliferation of open bins.
    score += (open_bins_count as f64).ln().max(0.0) * 0.3;

    // Slight pull toward mean residual state (stability term).
    score += 0.1 * (norm_post * cap - mean_residual).abs() / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact-fill / small-remainder classes are gold.
    let pr = post_residual as i64;
    let pr_mod = pr.rem_euclid(10) as i64;
    if pr == 0 {
        score -= 200.0; // perfect fill
    } else if pr <= 5 {
        score -= 120.0;
    } else if pr_mod == 0 {
        score -= 40.0; // multiple of 10: likely reusable by future items
    } else if pr_mod >= 7 {
        score += 15.0; // awkward sliver
    }

    // Dead-space penalty grows quadratically once residual is too small for any item.
    if pr > 0 && pr < 10 {
        score += 60.0 + (10 - pr) as f64 * 10.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        let nxt = next_item_size as i64;
        if nxt == pr {
            score -= 150.0;
        } else if nxt < pr && pr - nxt <= 5 {
            score -= 80.0;
        } else if nxt > pr && nxt <= bin_residual as i64 {
            // next item would need another bin; wasting this bin's space is fine
            score -= 20.0;
        } else if nxt > pr {
            score += 10.0; // next item won't fit here anyway
        }
        // modulo harmony between post_residual and next item size
        let harm = (pr - nxt).rem_euclid(10);
        if harm <= 2 {
            score -= 25.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 90.0;
    } else if fitting_bins_count > 1 {
        // with many options, prefer tightest fit (post_residual already does this)
        score += 5.0 * (fitting_bins_count as f64).ln();
    }

    // Prefer filling bins when many bins are open (reduce fragmentation).
    score -= (open_bins_count as f64) * (1.0 - post_residual as f64 / cap) * 3.0;

    // Late in the stream, compactness matters more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.3 * progress;

    // Deviation from mean residual: prefer bins near/below mean residual to balance load.
    score += ((post_residual as f64) - mean_residual).abs() * 0.15;

    // New-bin candidate: penalize opening a new bin unless this item is huge and
    // no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score = 100.0
            - 30.0 * (item_size as f64 / cap)
            - if fitting_bins_count == 0 { 40.0 } else { 0.0 };
        if next_item_size > 0 && (next_item_size as i64) <= pr {
            score += 25.0; // fresh bin could serve next item too, but open bins exist
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: residuals too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Strongly penalize leaving a gap just below the next item's size (blocks lookahead fit).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0 + 0.5 * (next_item_size - post_residual) as f64;
    }

    // Reward tight fits (small post_residual relative to item).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio;

    // Reward exact fits.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Open-bin pressure: when many bins are open, prefer using existing ones
    // (penalize the new-bin candidate relative to the fleet).
    score += 0.15 * open_bins_count as f64;

    // Last-chance bin: strongly prefer filling it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: make it unattractive unless existing residuals are all poor fits.
    if bin_residual == bin_capacity {
        score += 35.0 + mean_residual * 0.2;
    }

    // Late in the stream, consolidate harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: the smaller the post_residual relative to capacity, the better.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 60.0 * tightness * tightness;

    // Penalize dead space: small post_residual that cannot fit typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    } else if post_residual >= 10 && post_residual < 30 {
        // moderate dead space — worse late in the stream when fewer chances remain
        let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 8.0 + 12.0 * t;
    }

    // Lookahead: if the next item fits exactly into the post_residual, strongly reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let leftover = post_residual - next_item_size;
        score -= 30.0 - (leftover as f64) * 0.5;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item won't fit here anyway; mildly penalize hogging space it could use
        if bin_residual >= next_item_size && post_residual < next_item_size {
            score += 10.0;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 45.0;
    } else if fitting_bins_count > 1 {
        // many alternatives: mild penalty to keep competition meaningful
        score += 2.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // New-bin candidate handling: empty bin should only win when placement in open bins
    // is wasteful. Penalize the fresh bin by the "value" of keeping current bins compact.
    if bin_residual == bin_capacity {
        let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // early stream: opening bins is cheap; late stream: avoid proliferation
        let open_penalty = 20.0 + 60.0 * t + 5.0 * (open_bins_count as f64);
        score += open_penalty;
        // but if mean residual across open bins is large, opening new bin is fine
        score -= 0.3 * mean_residual;
        // if current item is huge relative to capacity, new bin is attractive
        score -= (item_size as f64) * 0.4;
    }

    // Global state coupling: prefer filling bins with below-average residual
    // (consolidate the emptiest bins first).
    if bin_residual != bin_capacity {
        let diff = (bin_residual as f64) - mean_residual;
        score += 0.15 * diff;
    }

    // Time-horizon scaling: as the stream progresses, be greedier about tight fits.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.5 * t;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let post_norm = post / cap;
    let fit = item_size as f64 / cap;

    // Core: minimize post residual, with non-linear (quadratic/cubic) shaping
    let mut score = post_norm + 0.8 * post_norm * post_norm + 0.5 * post_norm * post_norm * post_norm;

    // Smooth interaction: tight fits matter more later in the stream
    let tightness = 1.0 - post_norm;
    score -= (0.6 + 0.8 * progress) * tightness * tightness * fit;

    // Lookahead coupling: reward residuals that can host the next item smoothly
    if next_item_size > 0 {
        let nxt = next_item_size as f64 / cap;
        let gap = (post - nxt) / cap;
        let usable = 1.0 / (1.0 + (-gap * 6.0).exp());
        score -= 0.5 * usable * (1.0 - gap.abs()).max(0.0);
        score += 0.3 * (-gap.abs() * 4.0).exp() * (1.0 - progress);
    }

    // Penalize last-chance bin scarcity pressure
    if fitting_bins_count <= 1 && bin_residual != bin_capacity {
        score -= 1.2 * (1.0 - progress);
    }

    // New-bin candidate: only attractive when open bins are crowded or residual is dead space
    if bin_residual == bin_capacity {
        let dead = (post_norm < 0.15) as i32 as f64;
        let crowd = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
        score += 0.9 + 1.5 * (1.0 - crowd) - 0.8 * dead * (1.0 - progress) - 0.4 * dead * (fitting_bins_count as f64 / (fitting_bins_count as f64 + 2.0));
    } else {
        // Mild preference to spread load across many open bins
        score += 0.05 * (open_bins_count as f64).ln().max(0.0) * post_norm;
    }

    // Mean-residual drift: prefer bins below mean residual (tighter bins first)
    let mean_norm = mean_residual / cap;
    score += 0.25 * (post_norm - mean_norm);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual), especially perfect closures.
    if post_residual == 0 {
        score -= 1000.0; // perfect fit: close the bin
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 100.0;
    }

    // Harmonic class: post_residual divisible by small units is more reusable.
    if post_residual > 0 {
        if post_residual % 10 == 0 {
            score -= 30.0;
        } else if post_residual % 5 == 0 {
            score -= 15.0;
        }
        // Very small unusable dead space is bad unless it's zero.
        if post_residual < 10 {
            score += 40.0;
        }
    }

    // Lookahead coupling: if the next item fits exactly in post_residual, strongly favor.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 2.0;
            // bonus if next item lands in a "nice" class too
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 20.0;
            }
        } else {
            // next item won't fit here: slight penalty proportional to wasted potential
            score += 10.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: penalize opening a new bin when decent open bins exist.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Base penalty so open bins are preferred; relax late in stream or with few bins.
        let mut new_bin_penalty = 120.0
            - 60.0 * progress
            - (open_bins_count as f64).min(10.0) * 3.0;
        // If mean residual of open bins is large, opening new bin is wasteful.
        new_bin_penalty += mean_residual * 0.5;
        // If item is large and mean residual is small, opening new bin is reasonable.
        if item_size as f64 > mean_residual {
            new_bin_penalty -= 50.0;
        }
        score += new_bin_penalty.max(10.0);
    }

    // Mild penalty for leaving residual far from any typical item class (10..80 multiples).
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // typical future items (<= 10) are pure waste; penalize them heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    }

    // Reward tight fits (small post_residual) proportionally.
    score -= (bin_capacity - post_residual.min(bin_capacity)) as f64 * 0.05;

    // Dead space relative to bin capacity.
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 30.0;

    // Open-bin pressure: discourage proliferation of bins, but allow
    // opening a new bin when existing fits are very poor.
    score += open_bins_count as f64 * 0.8;

    // If this bin is the ONLY fitting bin, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a bin is only attractive if
    // current fits are bad (large post_residual) or no bins fit well.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin, modulated by how wasteful the
        // alternatives would be.
        score += 35.0;
        if post_residual == 0 || item_size >= bin_capacity {
            score -= 30.0; // item exactly fills a fresh bin: great
        }
        if fitting_bins_count == 0 {
            score -= 50.0; // forced choice
        }
        // If mean residual across open bins is large, prefer reusing.
        score += (mean_residual / bin_capacity as f64) * 25.0;
    }

    // Lookahead: if the next item fits into this bin's post_residual,
    // reward the placement; otherwise penalize slightly.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
        } else if post_residual > 0 && next_item_size > post_residual {
            score += 8.0;
        }
    }

    // Late in the stream, closing gaps matters more (fewer chances to
    // fill dead space later).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.3;

    // Slight preference for bins below mean residual (balancing load).
    score += (bin_residual as f64 - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong lookahead: reward exact match of post_residual with next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect 2-chain fit
        } else if post_residual >= next_item_size {
            // next item still fits; reward tightness of that fit
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 - slack.min(40.0);
        } else {
            // next item won't fit here; penalize dead space
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Penalize residuals that are too small to ever be useful (below min item size)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Prefer bins whose residual is below mean (tighter bins get priority)
    if (post_residual as f64) < mean_residual {
        score -= 8.0;
    } else {
        score += 4.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Late in stream: consolidate into fewer bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    // Mild penalty for many open bins to encourage packing
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core tightness preference: strongly favor small post_residual.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * tightness * tightness;

    // Perfect or near-perfect fit gets a big bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
        if post_residual <= 20 {
            score -= 25.0;
        }
    }

    // Lookahead: reward placements that leave room for the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            // Exact pairing: item + next item fills bin nicely.
            if post_residual == next_item_size {
                score -= 35.0;
            }
        } else {
            // Dead space relative to the next item's needs.
            let waste = next_item_size as f64 - post_residual as f64;
            score += 0.15 * waste;
        }
    }

    // New-bin candidate handling: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin grows with number of open bins.
        score += 55.0 + 2.0 * open_bins_count as f64;
        // If this bin is the last chance, opening new is less penalized.
        if fitting_bins_count == 0 {
            score -= 70.0;
        }
        // Early in stream, opening bins is cheaper (build flexibility).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 25.0 * (1.0 - progress);
    }

    // Prefer using bins whose residual is already small (consolidate fragments):
    // penalize placing into large-residual bins when other tighter options exist.
    if bin_residual < bin_capacity {
        let dev = bin_residual as f64 - mean_residual;
        score += 0.08 * dev;
    }

    // Mild penalty for leaving residuals in the "awkward" mid-range (30..55)
    // where few future items fit well.
    if post_residual > 30 && post_residual < 55 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_post = pr / cap;
    let mut score = pr as f64;
    // smooth polynomial coupling of post_residual with stream progress
    let poly = norm_post * norm_post * (1.0 - progress) + norm_post * progress * (1.0 - norm_post);
    score += 12.0 * poly * cap * 0.1;
    // reward tight fits more strongly as stream advances
    score -= (1.0 - norm_post) * (1.0 - norm_post) * (10.0 + 30.0 * progress);
    // penalize last-chance bins when a lookahead item would be stranded
    if next_item_size > 0 && (next_item_size as f64) > pr {
        score += 6.0 + 14.0 * progress;
    }
    // last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 8.0 + 10.0 * progress;
    }
    // new-bin candidate: mild penalty early, stronger later
    if bin_residual == bin_capacity {
        score += 5.0 + 20.0 * progress;
    }
    // deviation from mean residual penalty
    let dev = (pr - mean_residual) / cap;
    score += 4.0 * dev * dev * cap * 0.1;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual classes mod 10 and mod 25.
    let pr = post_residual;
    let class10 = (pr % 10) as f64;
    let class25 = (pr % 25) as f64;

    // Reward residuals that fall into "useful" harmonic classes (multiples of 10/25).
    if pr == 0 {
        score -= 45.0; // perfect fit is best
    } else if pr % 25 == 0 {
        score -= 12.0;
    } else if pr % 10 == 0 {
        score -= 7.0;
    } else {
        // Penalize awkward dead space proportional to class misalignment.
        score += 0.35 * class10 + 0.15 * class25;
    }

    // Tightness reward: filling most of the bin is good.
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= 18.0 * fill_frac * fill_frac;

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size < pr {
            score -= 4.0 * (pr - next_item_size) as f64 / 10.0;
        } else {
            // next item won't fit here; slight penalty scaled by overflow
            score += 0.05 * (next_item_size - pr) as f64;
        }
    }

    // Prefer keeping few open bins early; encourage consolidation.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.02 * open_bins_count as f64 * (1.0 - progress);

    // Prefer bins whose residual is near the mean (avoid starving one bin).
    score += 0.1 * ((post_residual as f64 - mean_residual).abs());

    // New-bin candidate guard: an empty bin gets a neutral-ish baseline so it
    // only wins when all open bins would create bad fits.
    if bin_residual == bin_capacity {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the next item are wasted.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 25.0 + (next_item_size - post_residual) as f64 * 0.6;
    }

    // Reward tight fits strongly (non-linear).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 15 {
        score -= 12.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a bin unless current bin is badly fragmented.
    if bin_residual == bin_capacity {
        score += 35.0 + open_bins_count as f64 * 0.5;
        // Allow new bin if all open bins would leave unusable dead space.
        if next_item_size > 0 && post_residual == bin_capacity {
            score -= 10.0;
        }
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing space.
    if open_bins_count > 3 {
        score -= (open_bins_count as f64).min(10.0) * 0.8;
    }

    // Slight preference for bins with residuals near the mean (balanced packing).
    score -= (mean_residual - bin_residual as f64).abs() * -0.1;

    // Late-stream urgency: as stream ends, close bins tightly.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        if progress > 0.8 {
            score -= post_residual as f64 * 0.15;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: penalize wasted space quadratically for small post-residuals.
    let waste = post_residual as f64 / bin_capacity as f64;
    score += waste * waste * 40.0;

    // 2-step lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain fill
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot fit here: penalize leaving a residual that
            // is neither usable nor empty (dead space).
            score += 15.0;
        }
    }

    // Compare against mean residual: prefer bins tighter than average.
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate: make it attractive only when current fits are poor
    // (large post_residual relative to typical item sizes) or few open bins.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 > 0.6 * bin_capacity as f64;
        if poor_fit || open_bins_count == 0 {
            score -= 10.0;
        } else {
            score += 25.0; // discourage wasteful new bins when fits are decent
        }
    }

    // Late in the stream, consolidate: slightly favor existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits: small post_residual is good.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize dead space that no plausible future item can use.
    if post_residual > 0 {
        let dead = if post_residual < 10 { 0.0 } else { post_residual as f64 };
        score += 0.35 * dead;
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 15.0 * (next_item_size as f64) / (post_residual as f64);
        } else {
            // next item would not fit here; slight penalty for wasting residual
            score += 5.0 * (next_item_size as f64 - post_residual as f64) / (bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Crowding: when many bins are open, prefer consolidating into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let crowd = (open_bins_count as f64).ln() + 1.0;
    if bin_residual < bin_capacity {
        score -= 8.0 * crowd * (0.5 + progress);
    }

    // Relative-to-mean residual: prefer bins below mean residual (already fuller).
    score += 0.5 * ((bin_residual as f64) - mean_residual);

    // New-bin candidate: only attractive when the item is huge relative to
    // residual options or nothing sensible fits. Penalize opening new bins
    // mildly; the tightness term on an empty bin gives post_residual = C,
    // so it needs extra discouragement.
    if bin_residual == bin_capacity {
        let desperation = if next_item_size > 0 && next_item_size > post_residual { 1.0 } else { 0.0 };
        score += 55.0 + 10.0 * crowd - 30.0 * desperation * (1.0 - progress);
        // Late in the stream, avoid scattering into new bins even more.
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-9;

    // Smooth base: quadratic penalty on wasted residual, modulated by progress.
    let norm_post = post / cap;
    let mut score = post * (1.0 + 0.9 * norm_post * norm_post);

    // Tight fits rewarded more strongly as stream progresses (smooth coupling).
    let tightness = 1.0 - norm_post;
    score -= 25.0 * tightness * tightness * (0.5 + progress);

    // Dead-space penalty: residual too small for typical future items.
    let small_thresh = 12.0;
    let dead = ((small_thresh - post) / small_thresh).max(0.0);
    score += 30.0 * dead * dead;

    // Lookahead: reward if next item fits the post residual (smooth decay).
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        let fit_quality = 1.0 - (post - next_item_size as f64) / cap;
        score -= 15.0 * fit_quality.max(0.0);
    } else if next_item_size > 0 {
        let gap = (next_item_size as f64 - post) / cap;
        score += 20.0 * gap * gap;
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 40.0 * (0.6 + 0.4 * progress);
    }

    // New-bin candidate: penalize, escalating with progress and existing bins,
    // but relax penalty when the item would leave large dead space elsewhere.
    if is_new_bin {
        let scarcity = (fitting_bins_count as f64).recip();
        score += 18.0 + 22.0 * progress + 1.5 * open_bins_count as f64;
        score -= 35.0 * scarcity * tightness;
    } else {
        // Mild preference for bins below mean residual (balance load smoothly).
        let dev = (bin_residual as f64 - mean_residual) / cap;
        score += 4.0 * dev * dev.abs();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover lies in "useful"
    // modular classes (multiples of small divisors) are rewarded.
    let pr = post_residual;
    if pr > 0 {
        let class_bonus = match pr % 10 {
            0 => 6.0,
            1 | 9 => 1.0,
            2 | 8 => 2.0,
            3 | 7 => 3.5,
            4 | 6 => 4.5,
            _ => 0.5,
        };
        score -= class_bonus;

        // Integer-division dead-space thresholds: leftover that no plausible
        // item (>=1) can pair with well is penalized super-linearly.
        if pr < 10 {
            score += (10 - pr) as f64 * 1.5;
        }
        // Harmonic fraction: post_residual / capacity quantized into eighths
        let eighth = ((pr as f64 / cap) * 8.0).floor();
        score -= eighth * 0.8;
    } else {
        // Perfect fit: strong reward
        score -= 25.0;
    }

    // Coupling with lookahead item: if next item fits exactly in post_residual,
    // this is a harmonic pair — heavily reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 20.0;
        } else if next_item_size <= pr {
            let slack = pr - next_item_size;
            score -= 6.0 - (slack as f64).min(12.0) * 0.5;
            if slack % 5 == 0 { score -= 2.0; }
        } else {
            // next item cannot use this bin's leftover: mild penalty scaled
            // by how much dead space remains
            score += (next_item_size - pr) as f64 * 0.15;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0;
    }

    // New-bin candidate (empty bin): penalize unless current bin would leave
    // tiny dead space or open_bins_count is low.
    if bin_residual == bin_capacity {
        score += 12.0;
        if fitting_bins_count == 0 { score -= 20.0; }
        if open_bins_count == 0 { score -= 5.0; }
        let t = step_index as f64 / (total_items.max(1) as f64);
        score -= t * 3.0; // slight preference to consolidate late in stream
    }

    // Mean-residual coupling: prefer bins near the mean residual (balanced fit)
    score += ((post_residual as f64 - mean_residual).abs()) * 0.05;

    // Small penalty for very large items into nearly-full bins creating waste
    if item_size as f64 > bin_residual as f64 * 0.95 && post_residual > 0 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0 * (1.0 - post_residual as f64 / 10.0) + 25.0;
    } else if post_residual > 10 && post_residual < 20 {
        // medium-small gaps still mildly risky
        score += 8.0 * (1.0 - (post_residual as f64 - 10.0) / 10.0);
    }

    // Reward tight fits (small post_residual relative to item size).
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fill_ratio;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: many open bins -> discourage opening another,
    // mildly discourage spreading residual across bins.
    let pressure = open_bins_count as f64 / (open_bins_count as f64 + 8.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline slightly above tight fits,
        // rises with pressure and with mean residual of open bins.
        score = 55.0 + 40.0 * pressure + 0.15 * mean_residual;
        // Late in the stream, opening new bins is less useful.
        score += 20.0 * (step_index as f64 / total_items.max(1) as f64);
        // If the next item is large and this new bin would fit it well,
        // opening a fresh bin is more attractive.
        if next_item_size > 0 && next_item_size as f64 >= 0.8 * bin_capacity as f64 {
            score -= 30.0;
        }
        // If no open bin fits well (large dead space would be created), prefer new bin.
        if post_residual > 25 && fitting_bins_count <= 2 {
            score -= 35.0;
        }
    } else {
        // Existing bin: penalize if it wastes capacity that next item could use.
        if next_item_size > 0 && post_residual > 0 && (post_residual as f64) < next_item_size as f64 {
            score += 0.3 * (next_item_size as f64 - post_residual as f64);
        }
        // Reward bins whose residual closely matches the next item.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 20.0;
        }
    }

    // Slight global preference to consolidate into fewer bins.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core archetype: aggressive 2-step lookahead matching.
    // Reward when the next item fits exactly into the post-residual (perfect chain).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack_after_next = (post_residual - next_item_size) as f64;
        score -= 30.0 - 0.8 * slack_after_next.min(50.0);
    }

    // Penalize post-residuals that are dead space: too small for typical items.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let dead_threshold = 10.0 + 5.0 * (1.0 - progress);
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += 25.0 * (dead_threshold - post_residual as f64) / dead_threshold;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Coupling with mean residual: prefer bins tighter than average.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // New-bin candidate handling: make empty bins mildly unattractive unless
    // the current item leaves a large usable residual for the next item.
    if bin_residual == bin_capacity {
        let usable = if next_item_size > 0 && post_residual >= next_item_size { 1.0 } else { 0.0 };
        score += 15.0 - 25.0 * usable;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: the smaller the post_residual relative to capacity, the better.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 18.0 * tightness * tightness;

    // Perfect fit gets a big bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 8.0;
