        let horizon = step_index as f64 / (total_items.max(1) as f64);
        score += 4.0 + 6.0 * horizon;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    } else if fitting_bins_count > 2 {
        // Many alternatives: be pickier about wasted space.
        score += 3.0 * tightness;
    }

    // New-bin candidate handling: an empty bin is only attractive when open bins
    // have poor residuals or the item leaves a large awkward gap elsewhere.
    if bin_residual == bin_capacity {
        let avg_tight = mean_residual / bin_capacity as f64;
        let gap_penalty = if next_item_size > 0 && post_residual >= next_item_size { 0.0 } else { 10.0 };
        score += 14.0 + 10.0 * avg_tight - gap_penalty + 2.0 * open_bins_count as f64 * 0.5;
    }

    // Slight preference to fill bins with larger residuals early (balance load).
    score -= 0.02 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_mean = mean_residual / cap;
    let norm_next = next_item_size as f64 / cap;

    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress:
    // later in the stream, tight fits (small post_residual) matter more.
    let tightness = 1.0 - norm_pr;
    let progress_coupling = norm_pr * (1.0 + 2.0 * progress * tightness * tightness);
    score += progress_coupling * cap * 0.5 - cap * 0.5;

    // Reward bins whose residual stays usable for the lookahead item:
    // smooth quadratic bonus when post_residual matches next item size.
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64) / cap;
        score -= 20.0 * (1.0 - gap * gap).max(-1.0) * (1.0 - progress * 0.5);
    }

    // Penalize waste relative to mean residual (smooth cubic coupling).
    let waste = norm_pr - norm_mean;
    score += 30.0 * waste * waste * waste.abs().sqrt() * cap * 0.1;

    // Last-chance bin: strongly favor using it (smooth in fitting count).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0 * (1.0 + norm_item);
    }

    // Mild penalty for spreading across many open bins, smooth in count.
    score += open_bins_count as f64 * 0.5;

    // New-bin candidate: neutral base; make it attractive only when no open bin
    // fits well (high post_residual everywhere) via smooth interaction.
    if bin_residual == bin_capacity {
        score = cap * 0.6 + 15.0 * (1.0 - progress) + norm_item * 20.0
            - 10.0 * (norm_mean - norm_item).max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how well it divides into capacity fractions
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Reward tight fits: post_residual near zero is ideal
    if post_residual == 0 {
        score -= 1000.0; // perfect fit
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 15 {
        score -= 50.0;
    }

    // Harmonic class: post_residual divisible by small integers means future items
    // of that size class could tile it exactly
    if post_residual > 0 {
        for k in 2..=6u32 {
            if post_residual % k == 0 {
                score -= (k as f64) * 4.0;
            }
        }
        // Exact half/quarter/third fill classes are attractive targets
        if (bin_capacity as u32 * post_residual) % bin_capacity == 0 {
            score -= 20.0;
        }
        let frac = post / cap;
        if (frac * 2.0).fract() < 1e-9 || (frac * 3.0).fract() < 1e-9 || (frac * 4.0).fract() < 1e-9 {
            score -= 15.0;
        }
    }

    // Lookahead coupling: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size < post_residual {
            let new_post = post_residual - next_item_size;
            score -= 40.0 - (new_post as f64) * 0.3;
        } else {
            // next item won't fit here; mild penalty proportional to waste
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Penalize opening a new bin when decent fits exist; new-bin candidate has
    // bin_residual == bin_capacity, so its base score is high (post = 100 - item).
    // Only allow it to win if all fitting bins would leave large dead space.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 80.0 + (open_bins_count as f64) * 2.0;
        // But if the item is huge relative to mean residual, opening fresh is fine
        if (item_size as f64) > mean_residual + 20.0 {
            score -= 60.0;
        }
        // Early in stream, new bins are cheaper
        if total_items > 0 && (step_index as f64) / (total_items as f64) < 0.2 {
            score -= 20.0;
        }
    }

    // Prefer filling bins with small residuals relative to mean (balance avoidance)
    if !is_new_bin {
        let dev = (bin_residual as f64) - mean_residual;
        score += dev * 0.2;
    }

    // Integer division threshold: bins whose residual falls in "awkward" band
    // (just above half capacity) are hard to fill later; penalize leaving them
    if post_residual > bin_capacity / 2 && post_residual < bin_capacity {
        score += 10.0;
    } else if post_residual <= bin_capacity / 2 && post_residual > 0 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let next = next_item_size as f64;
    let open = open_bins_count as f64;
    let fitting = fitting_bins_count as f64;

    let progress = if total_items > 0 {
        (step_index as f64 / total_items as f64).clamp(0.0, 1.0)
    } else {
        0.0
    };

    let mean_res = if mean_residual.is_finite() {
        mean_residual.max(0.0)
    } else {
        0.0
    };

    let mut score = post;

    // Mild penalty for leaving more space than the average open bin.
    score += 0.16 * (post - mean_res).max(0.0);

    // Reward exact closure, especially when many bins are open.
    if post_residual == 0 {
        score -= 20.0 + 1.4 * open + 8.0 * progress;
    }

    // A residual is treated as "useful" if it can accept the lookahead item,
    // capped to avoid overreacting to a very large next item, or at least a
    // small absolute fragment threshold.
    let lookahead_target = if next > 0.0 {
        next.min(0.45 * cap)
    } else {
        0.0
    };
    let fragment_target = (7.0 + 0.35 * open).min(18.0);
    let useful_target = lookahead_target.max(fragment_target);

    // Strict dead-space penalty for small, hard-to-use nonzero gaps.
    if post > 0.0 && useful_target > 0.0 && post < useful_target {
        let missing = useful_target - post;
        let dead_ratio = (missing / useful_target).clamp(0.0, 1.0);
        let alternative_pressure = 1.0 + 0.06 * fitting;

        score += (15.0 + 0.55 * open + 8.0 * (1.0 - progress))
            * dead_ratio
            * dead_ratio
            * alternative_pressure;

        // Extra lookahead mismatch penalty when this bin cannot accept the next item.
        if next > 0.0 && post < next {
            let lookahead_miss = ((next - post) / cap).clamp(0.0, 1.0);
            score += lookahead_miss * (6.0 + 0.15 * open + 4.0 * (1.0 - progress));
        }
    }

    // If this is the only existing bin that can fit the item, favor using it.
    if fitting_bins_count == 1 {
        score -= 10.0 + 0.6 * open + 5.0 * progress;
    }

    // Brand-new empty bin candidate.
    if bin_residual == bin_capacity {
        let mut new_score = post;

        // Explicit pressure against opening another bin.
        new_score += 15.0 + 2.0 * open + 8.0 * progress;

        // If existing bins could fit, opening a new one must be clearly better.
        new_score += 4.0 * fitting;

        // The new bin should also avoid creating a small dead gap.
        if post > 0.0 && useful_target > 0.0 && post < useful_target {
            let missing = useful_target - post;
            let dead_ratio = (missing / useful_target).clamp(0.0, 1.0);
            new_score += (10.0 + 0.30 * open) * dead_ratio * dead_ratio;
        }

        // Mild reward when the new bin can also accept the lookahead item.
        if next > 0.0 && post >= next {
            new_score -= 3.0 + 0.03 * next;
        }

        // Mandatory new bin when no open bin can fit the item.
        if fitting_bins_count == 0 {
            new_score -= 1000.0;
        }

        return new_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        // Next item still fits after this placement: mild reward proportional to tightness.
        let gap = (post_residual - next_item_size) as f64;
        score -= 30.0 / (1.0 + gap / 10.0);
    } else if next_item_size > 0 {
        // Next item cannot fit: penalize dead space created.
        let waste = (next_item_size - post_residual) as f64;
        score += 0.4 * waste;
    }

    // Reward leaving residuals below the smallest possible item (dead space anyway).
    if post_residual < 10 {
        score -= 15.0;
    }

    // Tight fit reward relative to bin capacity.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill_ratio;

    // Prefer bins whose residual is below mean (smaller bins get filled first).
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    } else {
        score += 4.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New empty bin candidate: penalize unless no other bin fits well.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 30.0 };
        score += pressure + open_bins_count as f64;
        // If next item is huge, opening fresh may be wise.
        if next_item_size >= bin_capacity / 2 && post_residual == bin_capacity {
            score -= 20.0;
        }
    }

    // Late-stream consolidation: fill existing bins more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post_residual non-linearly.
    if post_residual > 0 {
        score += (post_residual as f64 / bin_capacity as f64).powf(1.7) * 60.0;
    } else {
        score -= 25.0; // perfect fill
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            // dead space that cannot fit the lookahead item
            score += (post_residual as f64).min(next_item_size as f64) * 0.8;
        }
    } else {
        // last item: strongly prefer perfect fill
        score -= 15.0;
    }

    // Last chance: if this is the only bin that fits, prefer using it over a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Global state: when many bins are open with slack, discourage opening new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let open_f = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when open bins already carry slack.
        score += 8.0 + open_f * 1.5 + mean_residual * 0.25 + progress * 10.0;
    } else {
        // Reward using existing bins, more so mid/late stream.
        score -= 4.0 + progress * 6.0;
    }

    // Slight preference for bins with residuals close to the mean (balance).
    let diff = (bin_residual as f64 - mean_residual).abs();
    score += diff * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Smooth non-linear coupling: post_residual penalized more as stream progresses
    score += 30.0 * norm_pr * norm_pr * (0.5 + progress);
    score -= 12.0 * norm_pr * (1.0 - progress);

    // Tight fits rewarded, amplified late in the stream
    let tightness = 1.0 - norm_pr;
    score -= 20.0 * tightness * tightness * (0.3 + 0.7 * progress);

    // Penalize bins that waste relative to mean residual
    score += 0.15 * (pr - mean_residual);

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0).ln();
    }

    // Lookahead: reward residual that can host next item smoothly
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fit = (pr - nx).max(0.0);
        let fit_frac = fit / cap;
        score -= 18.0 * (fit_frac * (1.0 - fit_frac)) * 4.0;
        score += 8.0 * ((nx - pr).max(0.0) / cap);
    }

    // Mild penalty for too many open bins, smoothed
    score += 1.5 * (open_bins_count as f64).powf(0.8) * (0.5 + progress);

    // New-bin candidate: prefer opening a new bin only when residuals are fragmented
    if bin_residual == bin_capacity {
        score += 10.0 + 15.0 * (1.0 - progress) - 6.0 * (mean_residual / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;

    // Harmonic classes on post_residual (integer division thresholds)
    if pr == 0 {
        // Perfect fill: strongest reward
        score -= 45.0;
    } else if pr < 10 {
        // Dead-space class: unusable sliver, heavy penalty
        score += 30.0 + (10 - pr) as f64;
    } else {
        // Class = floor(pr / 10): bigger leftover chunks are progressively worse
        let class = (pr / 10) as f64;
        score += class * 2.5;
        // Sub-class refinement via modulo: odd remnants slightly worse
        if pr % 10 != 0 {
            score += 1.0;
        }
    }

    // Lookahead coupling: does the next item nest into the leftover?
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 12.0;
            // Extra reward if next item nearly fills the remainder exactly
            if pr - next_item_size < 10 {
                score -= 8.0;
            }
        } else {
            score += 6.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Crowding: many open bins -> prefer consolidation into existing space
    if open_bins_count > 3 {
        score -= (open_bins_count.min(20) as f64) * 0.5;
    }

    // Mean-residual coupling: penalize bins far above mean residual (poor consolidation)
    score += (post_residual as f64 - mean_residual).abs() * 0.15;

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            // No open bin can host the item: opening a new bin is mandatory
            score = -100.0;
        } else if fitting_bins_count == 1 {
            // One existing bin fits; it gets the last-chance bonus, so keep new bin expensive
            score = bin_capacity as f64 + 20.0;
        } else {
            // Multiple fits exist: new bin should generally lose to decent fits
            score = bin_capacity as f64 + 5.0;
            // But if all fits would leave tiny dead space, prefer the fresh bin
            // (approximated via item size class: large items fragment bins)
            if item_size > bin_capacity / 2 {
                score -= 15.0;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual <= 10 {
        score += (11.0 - post_residual as f64) * 25.0;
    }
    if post_residual > 10 && post_residual < 20 {
        score += (20.0 - post_residual as f64) * 3.0;
    }

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Lookahead: reward bins whose leftover can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + next_item_size as f64 * 0.2;
    }
    // Penalize leftovers that strand the next item just barely.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Open-bin pressure: prefer consolidating into few bins when many are open.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New empty bin: only attractive when current bins are nearly full/dead.
    if bin_residual == bin_capacity {
        score += 60.0 + mean_residual * 0.5;
    }

    // Mean residual coupling: penalize bins far below mean (wasteful spread).
    let diff = mean_residual - post_residual as f64;
    if diff > 0.0 {
        score += diff * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Dead space: post_residual too small for the next item
    if next_item_size > 0 && post_residual < next_item_size {
        let waste = (next_item_size - post_residual) as f64;
        score += waste * 0.8;
        // Extremely small unusable residual is very costly
        if post_residual < 10 {
            score += 25.0;
        }
    }

    // Post residual larger than next item: still usable, mild reward proportional
    if next_item_size > 0 && post_residual > next_item_size {
        score -= ((post_residual - next_item_size) as f64).min(40.0) * 0.15;
    }

    // Relative to mean residual: prefer bins tighter than average
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate: neutral baseline; only attractive when current fits are poor
    if bin_residual == bin_capacity {
        score += 15.0;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            // Fresh bin supports a clean 2-item pairing
            score -= 10.0;
        }
        // Late in the stream, avoid spawning bins with large leftover
        if total_items > 0 && step_index as f64 / total_items as f64 > 0.8 {
            score += 20.0;
        }
    }

    // Slight preference for bins already partially loaded (reduce open bin count pressure)
    if bin_residual < bin_capacity {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong preference for tight fits (best-fit core).
    score += (post_residual as f64).powi(2) / (bin_capacity as f64 * 2.0);

    // Reward near-perfect packing: post residual close to zero gets extra discount.
    if post_residual <= 3 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 8.0;
    }

    // Lookahead coupling: if the next item can fit in the post residual,
    // this placement chains nicely; reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 + (next_item_size as f64) * 0.1;
    }
    // Penalize leaving dead space the next item almost fits into (wasted gap).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let gap_waste = next_item_size as f64 - post_residual as f64;
        if gap_waste < 8.0 {
            score += (8.0 - gap_waste) * 1.5;
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive when existing fits are poor.
    if bin_residual == bin_capacity {
        // Base penalty so a new bin is chosen only when placement is bad elsewhere.
        score += 30.0;
        // If the item perfectly fills a fresh bin (full capacity item), it's great.
        if item_size >= bin_capacity {
            score -= 200.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 20.0;
        // Many open bins with low mean residual: avoid opening yet another.
        if open_bins_count > 3 && mean_residual < 25.0 {
            score += 15.0;
        }
    }

    // Mild penalty for wasting a large residual bin on a tiny item.
    if (item_size as f64) < bin_residual as f64 * 0.2 && bin_residual < bin_capacity {
        score += 5.0;
    }

    // Slight preference to fill bins with larger residuals first when
    // residuals are similar, to consolidate fragmented space.
    score -= (bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual, with non-linear polynomial coupling to stream progress.
    // Early on, prefer tight fills (low post_residual); later, tolerate some slack
    // because leftover capacity compounds less over a shrinking stream.
    let mut score = pr * (1.0 + 0.8 * progress * (1.0 - progress) * 4.0);
    score += 30.0 * norm_pr * norm_pr * (1.0 - progress);

    // Penalize large dead space relative to mean residual (wasted capacity vs fleet).
    score += 0.5 * (pr - mean_residual).abs();

    // Last-chance bin: strong reward to use it, scaled non-linearly by fit quality.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0 * (1.0 - norm_pr) * (1.0 - progress * 0.5);
    }

    // Lookahead coupling: reward if next item fits into post-residual (chaining),
    // penalize if post-residual is a nearly-useless sliver.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual >= next_item_size {
            score -= 15.0 * (1.0 - (pr - nxt) / cap);
        } else {
            score += 10.0 * (nxt - pr) / cap;
        }
    }

    // New-bin candidate: prefer opening a new bin only when existing fit is bad
    // (post_residual large) or few bins fit the item.
    if bin_residual == bin_capacity {
        let bad_fit = norm_pr; // post_residual == capacity here, so this is 1.0
        score = cap - 20.0 * bad_fit - 5.0 * (fitting_bins_count as f64).recip()
            + 10.0 * progress;
    }

    // Mild penalty for proliferating bins late in the stream.
    score += 0.3 * (open_bins_count as f64) * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: coarse capacity fractions
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap;

    // Penalize residuals that fall into "dead zones" — too small for typical items
    // (items in 1..=100; small residuals < 20 are hard to fill).
    if post_residual > 0 && post_residual < 20 {
        score += 30.0 * (20.0 - pr) / 20.0;
    }

    // Reward exact / near-exact fits (post_residual near zero).
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 50.0;
    } else if post_residual <= 10 {
        score -= 20.0;
    }

    // Integer-division harmonic classes: post_residual bucketed by 25s.
    let class = post_residual / 25; // 0..4
    score += class as f64 * 8.0;

    // Modulo arithmetic on post_residual: residuals that are multiples of small
    // item sizes are more reusable (likely to be exactly filled later).
    let mut reuse = 0.0;
    for m in [10u32, 20, 25, 50].iter() {
        if post_residual % m == 0 && post_residual > 0 {
            reuse += 6.0;
        }
    }
    score -= reuse;

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly favor this bin (chain completion).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            let leftover = post_residual - next_item_size;
            score -= 15.0 - (leftover as f64) * 0.2;
            if leftover < 20 {
                score += 10.0; // would create dead space for the item after
            }
        } else {
            // next item cannot use this bin's remainder: slight penalty
            score += 5.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it over
    // opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: make an empty bin mildly attractive only when
    // mean residual across open bins is low (nothing useful to pack into).
    if bin_residual == bin_capacity {
        let pressure = mean_residual / cap; // average leftover space
        score = cap * 0.55 + (1.0 - pressure) * 20.0;
        // late in the stream, avoid proliferating bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 15.0;
        // if many bins fit the item, opening a new bin is wasteful
        score += fitting_bins_count as f64 * 4.0;
    }

    // Mild normalization: compare against mean residual to spread scores.
    score -= mean_residual * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong dead-space penalty for small unusable gaps (< 10, or too small for next item).
    if post_residual < 10 {
        score -= 1000.0; // perfect closure is excellent
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Gap too small to fit the lookahead item: dead space penalty scaled by gap size.
        score += 40.0 + (10 - post_residual.min(10)) as f64 * 5.0;
    }

    // Reward tight fits: smaller post_residual relative to capacity is better.
    score += (post_residual as f64 / bin_capacity as f64) * 60.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is good.
    score += open_bins_count as f64 * 0.5;

    // Deviation from mean residual: prefer bins whose residual is close to item need.
    score += ((bin_residual as f64 - item_size as f64) - mean_residual).abs() * 0.3;

    // New-bin candidate handling: allow opening a new bin only when current fits are poor.
    if bin_residual == bin_capacity {
        // Neutral baseline; only wins if existing bins score badly (poor fits).
        score = 70.0 + (item_size as f64) * 0.1;
        if fitting_bins_count == 1 {
            score += 50.0; // never open a new bin when a last-chance bin exists
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly fits next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Post residual can still hold the next item: mild reward scaled by tightness.
    if next_item_size > 0 && post_residual >= next_item_size {
        let tightness = (post_residual - next_item_size) as f64;
        score -= 25.0 / (1.0 + tightness / 10.0);
    }
    // Post residual too small for next item but nonzero: dead-space penalty.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 0.5 * (post_residual as f64);
    }

    // Reward filling the bin nearly completely (low waste).
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill_ratio * fill_ratio;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad.
    if bin_residual == bin_capacity {
        let fit_quality = post_residual as f64; // = capacity - item_size for new bin
        let best_open = if fitting_bins_count > 0 { mean_residual } else { bin_capacity as f64 };
        // If an open bin's mean residual fits the item well, discourage new bin.
        if fitting_bins_count > 0 && mean_residual >= item_size as f64 {
            score += 45.0;
        }
        // Opening a new bin is fine for large items that leave small residuals.
        score += 0.3 * fit_quality;
        // Late in stream, prefer consolidating into open bins.
        if total_items > 0 && (step_index as f64) / (total_items as f64) > 0.7 {
            score += 15.0;
        }
        let _ = best_open;
    }

    // Slight preference for bins with residual close to item (tight fit).
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.1 * gap;

    // Coupling with mean residual: prefer bins below mean residual (fill emptier bins first).
    score -= 0.2 * (mean_residual - bin_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item fills a large fraction.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 60.0 * tightness * tightness;

    // Penalize post-residual dead space that is too small to be useful later
    // (unusable slivers), but reward mid-range residuals that stay flexible.
    if post_residual > 0 {
        let pr = post_residual as f64;
        if pr < 10.0 {
            score += 25.0 * (10.0 - pr) / 10.0; // tiny dead space is worthless
        } else {
            // residuals that can host a typical next item are valuable
            score -= 8.0 * ((pr / 50.0).min(1.0));
        }
    }

    // Lookahead coupling: if the next item fits the post-residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0 + 0.3 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        // partial overlap: mild penalty for blocking a likely next fit
        let overlap = 1.0 - (post_residual as f64 / next_item_size as f64).abs().min(1.0);
        score += 6.0 * overlap;
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // heavily reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the current item fits poorly everywhere (high post_residual relative
    // to capacity on existing bins) or few bins are open.
    if bin_residual == bin_capacity {
        // baseline cost of a fresh bin: its full residual
        // discount when many bins already open (amortization) and early stream
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 * (1.0 - progress);          // cheaper to open early
        score -= (open_bins_count as f64).min(20.0); // slight reluctance to proliferate
        // if existing bins would leave large post-residuals, opening fresh is fine
        let waste_elsewhere = (post_residual as f64 - mean_residual).abs();
        score -= 10.0 / (1.0 + waste_elsewhere);
    } else {
        // Existing-bin bonus scaled by global fragmentation pressure:
        // when mean residual is low, packing tightly matters more.
        score -= mean_residual * 0.15;
        // mildly prefer bins that are already fairly full
        let fill = 1.0 - bin_residual as f64 / bin_capacity as f64;
        score -= 15.0 * fill;
    }

    // Small stochastic-free tie-breaker by bin id proxy (residual hash-free):
    score += (bin_residual % 7) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post;

    // Non-linear waste penalty: dead space matters more as it grows cubically relative to capacity
    let norm_post = post / cap;
    score += 30.0 * norm_post * norm_post * norm_post;

    // Perfect-fit reward: strongly favor bins with small post_residual
    score -= 25.0 * (-post / 8.0).exp();

    // Stream progress coupling: as the stream advances, prefer tighter fits more aggressively
    score -= 20.0 * progress * (1.0 - norm_post);

    // Last-chance bonus: if this is the only fitting bin, strongly discourage opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless existing fits are bad
    if bin_residual == bin_capacity {
        score += 10.0 + 0.5 * open_bins_count as f64;
        // If next item is large and current fit is loose, opening new bin is less attractive
        if next_item_size > 0 {
            score += 5.0 * (next_item_size as f64 / cap) * norm_post;
        }
    }

    // Lookahead coupling: reward leaving post_residual close to next item size
    if next_item_size > 0 {
        let gap = (post - next_item_size as f64).abs();
        score -= 8.0 * (-gap / 15.0).exp();
    }

    // Mean residual interaction: bins deviating far from the mean residual are less attractive
    score += 0.1 * (mean_residual - post).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "reusable" is the leftover space
    // under modulo arithmetic of common item sizes (1..100 unknown distribution).
    let r = post_residual;
    if r > 0 {
        // Residuals divisible by small harmonic bases (10, 20, 25, 50) are more
        // likely to be exactly filled by future items -> reward them.
        let mut harmony = 0.0;
        if r % 50 == 0 { harmony += 6.0; }
        else if r % 25 == 0 { harmony += 4.0; }
        if r % 20 == 0 { harmony += 3.0; }
        if r % 10 == 0 { harmony += 2.0; }
        if r % 5 == 0 { harmony += 1.0; }
        score -= harmony;

        // Integer-division thresholds: classify residual into dead-space bands.
        // Very small leftover (<10) is nearly unusable dead space -> penalize.
        if r < 10 {
            score += (10 - r) as f64 * 0.8;
        } else if r <= 20 {
            // awkward band, mildly penalize unless harmonically aligned
            score += 1.5 - harmony * 0.2;
        }
    } else {
        // Perfect fill is ideal.
        score -= 12.0;
    }

    // Tightness: prefer bins where the item occupies a large fraction of residual.
    let fit_frac = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_frac * 8.0;

    // Lookahead coupling (k=2): if the next item fits exactly in post_residual,
    // strongly reward; if next item is close, mild reward; if clearly too big,
    // slight penalty for wasting a good harmonic slot.
    if next_item_size > 0 {
        if next_item_size == r {
            score -= 10.0;
        } else if next_item_size < r {
            let gap = r - next_item_size;
            if gap <= 5 {
                score -= 4.0;
            } else if gap > 30 {
                score += 1.0;
            }
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    // New-bin candidate: penalize opening a new bin early in the stream when
    // open bins exist, but allow it when existing bins are crowded.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowding = open_bins_count as f64 / (mean_residual.max(1.0) / bin_capacity as f64).max(0.1);
        score += 14.0 - progress * 4.0 - crowding.min(6.0);
        // New bin is attractive if item is large relative to mean residual.
        score -= (item_size as f64 - mean_residual).max(0.0) * 0.15;
    }

    // Mild preference for consolidating into fewer bins.
    score += (open_bins_count as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit: perfect placement, strongly favored.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: penalize tiny unusable gaps that no
    // plausible item (sizes >= 1, but practically >= 10 historically) can use.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    } else if post_residual >= 10 && post_residual < 25 {
        // Moderately awkward gap: mild penalty proportional to awkwardness.
        score += 8.0;
    }

    // Reward gaps that can still accommodate a typical item.
    if post_residual >= 25 {
        score -= 12.0;
    }

    // Last chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading;
    // with few open bins, opening a new empty bin is relatively attractive.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure so it loses to decent fits.
        score = 100.0 + pressure * 15.0;
        // If the current bin would be the only fitting bin, new bin must lose badly.
        if fitting_bins_count == 1 {
            score += 200.0;
        }
        // Early in stream, new bins are cheaper to open.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 20.0;
    } else {
        // Slight preference for tighter bins (lower residual before placement).
        score += (bin_residual as f64) * 0.05;
    }

    // Lookahead: if next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 30.0;
        } else if gap < 10 {
            score += 5.0; // would leave dead space for next item
        } else {
            score -= 10.0;
        }
    }

    // Mean residual coupling: prefer bins near the mean (balanced packing),
    // penalize outliers that hoard space.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic penalty on leftover space (dead space is bad).
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 40.0;

    // 2-step lookahead: reward bins whose post_residual exactly fits the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0; // perfect chain: next item exactly fills this bin
        } else if post_residual >= next_item_size {
            // residual left after also placing next item — smaller is better
            let after_next = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - after_next / bin_capacity as f64);
        } else {
            // next item cannot follow into this bin: penalize proportionally to the gap
            let gap = (next_item_size - post_residual) as f64;
            score += 8.0 * (gap / bin_capacity as f64);
        }
    }

    // Relative to mean residual: prefer bins that are already more filled than average.
    score += (mean_residual - bin_residual as f64) * 0.35;

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Late in the stream, consolidate aggressively (avoid opening new bins near the end).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0;

    // Penalize opening a brand-new bin when decent fits exist (new-bin candidate guard).
    if bin_residual == bin_capacity {
        score += 10.0;
        // but allow a new bin if the item is large and would leave a nearly empty bin anyway
        if item_size as f64 > 0.8 * bin_capacity as f64 {
            score -= 12.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fit quality: normalized tightness of the placement.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Strong reward for near-perfect fills (dead space <= 5).
    if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual > 40 {
        // Large dead space is only tolerable late in the stream.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 * (1.0 - progress);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead coupling: if the next item fits in the post-residual,
    // reward; if post-residual is stranded between sizes, penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0;
        } else if post_residual < next_item_size && post_residual < 10 {
            score -= 8.0; // small unusable sliver
        } else if post_residual < next_item_size {
            score += 5.0; // stranded medium space
        }
    }

    // Prefer filling bins that are below the mean residual (balance avoidance
    // of many half-empty bins), slightly penalize when many bins are open.
    let residual_gap = mean_residual - post_residual as f64;
    score += 0.15 * residual_gap;
    score += 0.3 * open_bins_count as f64;

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count <= 1 { 0.0 } else { 1.0 };
        score = 60.0 + desperation * 40.0 + 0.2 * mean_residual;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // opening a bin for a big item followed by bigger item is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual, with non-linear polynomial shaping
    let mut score = pr
        + 18.0 * norm_pr * norm_pr
        + 30.0 * norm_pr * norm_pr * norm_pr;

    // Smooth coupling: late in the stream, tight fits (small post_residual) are more valuable
    let tightness = 1.0 - norm_pr;
    score -= 25.0 * progress * tightness * tightness;

    // Penalize large dead space more when many bins are open (waste compounding)
    let open_factor = (open_bins_count as f64).ln().max(0.0);
    score += 6.0 * open_factor * norm_pr * norm_pr;

    // Reward bins that are already well-filled relative to the mean residual
    let mean_gap = mean_residual - pr;
    score += 0.35 * mean_gap;

    // Lookahead: if next item could fit into resulting residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 12.0 * (1.0 - pr / cap);
    } else if next_item_size > 0 {
        score += 4.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0 * tightness;
    }

    // New-bin candidate: smooth penalty that grows with progress and open bins
    if bin_residual == bin_capacity {
        score += 10.0 + 15.0 * progress + 2.0 * open_factor;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into
    // capacity-fraction bands (integer division thresholds).
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    let class = post_residual / eighth; // 0..=8 harmonic class

    // Reward tight fits strongly; penalize mid-range dead space.
    match class {
        0 => score -= 40.0,               // near-perfect fit
        1 => score -= 25.0,               // small but usable leftover
        2 => score -= 8.0,                // half-quarter leftover
        3 | 4 => score += 12.0,           // awkward mid residual (~25-50%)
        5 | 6 => score -= 4.0,            // roomy bin, fine
        _ => score -= 10.0,               // nearly empty bin usage is fine
    }

    // Modulo arithmetic on post_residual: leftovers divisible by common
    // small item sizes are more likely to be filled later.
    for m in [10u32, 15, 20, 25, 30, 40, 50] {
        if post_residual >= m && post_residual % m == 0 {
            score -= 6.0;
            break;
        }
    }
    // Odd, hard-to-fill leftovers get a penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual,
    // strongly favor this bin (chained perfect fits).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            let nr_class = (post_residual - next_item_size) / eighth;
            score -= match nr_class {
                0 => 18.0,
                1 => 10.0,
                _ => 3.0,
            };
        } else {
            // Next item won't fit here: leftover likely becomes dead space.
            score += (post_residual as f64) * 0.15;
        }
    }

    // Last-chance bin: avoid opening a new bin when this is the only fit.
    if fitting_bins_count == 1 && post_residual <= bin_residual {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless the item is
    // large and few bins fit it (then a fresh bin is a clean slate).
    if bin_residual == bin_capacity {
        score += 30.0;
        if item_size >= bin_capacity / 2 && fitting_bins_count <= 1 {
            score -= 55.0;
        }
        // Early in the stream, fresh bins are cheaper.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - progress) * 10.0;
    }

    // Mean-residual coupling: placing into a bin far below mean residual
    // balances the pool of open bins.
    let dev = mean_residual - post_residual as f64;
    score += 0.05 * dev;

    // Slight preference for using bins when many are open.
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: hard penalty for small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    } else if post_residual < 20 {
        score += 15.0;
    }

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Dead space is worse if the next item cannot use it.
    if next_item_size > post_residual && post_residual > 0 {
        score += 25.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open.
    if bin_residual == bin_capacity {
        score += 30.0 + 5.0 * open_bins_count as f64;
        // But allow a new bin if this item would leave a bad gap everywhere.
        if post_residual < 10 && fitting_bins_count > 0 {
            score -= 40.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Mild preference for fuller bins relative to the fleet mean residual.
    score += 0.3 * (mean_residual - post_residual as f64);

    // Early-stream flexibility: keep bins balanced early on.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 0.1 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item fits into post_residual exactly or well
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 50.0 + 0.5 * slack;
        if slack == 0.0 {
            score -= 300.0; // chain perfect fit
        }
    } else if next_item_size > 0 {
        // next item won't fit here: penalize wasted residual relative to next size
        score += 0.3 * (next_item_size as f64 - post_residual as f64).min(60.0);
    }

    // Relative to mean residual: prefer bins with less residual than average (tighter bins)
    score += 0.4 * (mean_residual - bin_residual as f64).max(-50.0).min(50.0);

    // Last chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Penalize opening a new bin when decent open bins exist
    if bin_residual == bin_capacity {
        score += 60.0 + 2.0 * open_bins_count as f64;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 30.0; // new bin can still host next item
        }
    }

    // Small progression term: early on, be slightly more willing to open bins
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 10.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post_residual) more aggressively.
    let tight_fit_bonus = (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64;
    score -= 8.0 * tight_fit_bonus * tight_fit_bonus;

    // Penalize dead space that can't hold the next item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            let unusable = (next_item_size - post_residual) as f64 / bin_capacity as f64;
            score += 12.0 * unusable;
        } else {
            // Reward bins that can also host the lookahead item.
            score -= 4.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // When many bins are open and mean residual is high, prefer consolidating
    // into bins with below-average residual (fill the emptier-feeling bins).
    if open_bins_count > 1 {
        let diff = mean_residual - bin_residual as f64;
        score += 0.05 * diff;
    }

    // Time horizon: early in the stream be more conservative about new bins,
    // late in the stream allow tighter packing priorities to dominate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * (1.0 - progress);

    // New-bin candidate: penalize slightly unless item is large relative to
    // capacity or no good fit exists (handled via fitting_bins_count).
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        score += 20.0 - 10.0 * large_item;
        if fitting_bins_count <= 1 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Normalized post-residual and its smooth non-linear coupling with progress
    let pr_norm = post_residual as f64 / cap;
    let pr_sq = pr_norm * pr_norm;
    score += 12.0 * pr_sq * (0.3 + 0.7 * progress);

    // Penalize large dead space quadratically; small leftovers (<= ~10) are valuable
    if pr_norm < 0.1 {
        score -= 8.0 * (0.1 - pr_norm) * (1.0 - progress);
    }

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 {
        score -= 25.0 + 10.0 * progress;
    } else {
        // Mild penalty when many bins compete (prefer tighter fits elsewhere)
        score += 1.5 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Tight-fit reward: post_residual close to next item size keeps lookahead usable
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        let gap_norm = gap / cap;
        score += 6.0 * gap_norm * gap_norm;
        // Reward bins whose post-residual exactly accommodates the next item
        if post_residual == next_item_size {
            score -= 10.0;
        }
    } else {
        // Last item: only post_residual matters; minimize waste
        score += 4.0 * pr_sq;
    }

    // New-bin candidate handling: empty bin has bin_residual == bin_capacity
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Opening a new bin is penalized, more so early/mid stream and when fitting bins exist
        let open_pressure = (open_bins_count as f64).ln().max(0.0);
        score += 20.0 + 15.0 * (1.0 - progress) + 4.0 * open_pressure;
        // But if nothing fits well anywhere (large mean residual unused), allow it:
        // penalize less when the new bin would be far emptier than the mean residual
        let mean_pr = mean_residual / cap;
        if pr_norm < mean_pr - 0.2 {
            score -= 30.0;
        }
    } else {
        // Favor bins with residual near the item (good fit) via smooth coupling
        let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
        score -= 10.0 * fit_ratio * fit_ratio * (0.5 + 0.5 * progress);
        // Slight preference for bins below mean residual (consolidating space)
        let dev = (bin_residual as f64 - mean_residual) / cap;
        score += 3.0 * dev * dev.abs();
    }

    // Smooth global regularization
    score += 0.5 * progress * pr_norm;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues divisible by large gcds are reusable
    let pr = post_residual;
    // Class 0: perfect fit
    if pr == 0 {
        score -= 1000.0;
    } else {
        // Reward post_residuals that fall into "useful" harmonic classes:
        // divisible by common item sizes (10,20,25,50)
        let mut bonus = 0.0;
        if pr % 50 == 0 { bonus += 60.0; }
        else if pr % 25 == 0 { bonus += 40.0; }
        else if pr % 20 == 0 { bonus += 30.0; }
        else if pr % 10 == 0 { bonus += 15.0; }
        score -= bonus;

        // Penalize tiny unusable dead space (pr < 10 can never be filled)
        if pr < 10 {
            score += 80.0;
        }

        // Lookahead coupling: if next item fits exactly in post_residual, big reward
        if next_item_size > 0 {
            if next_item_size == pr {
                score -= 200.0;
            } else if next_item_size <= pr {
                // next fits: reward proportionally to how well it fills
                let fill = next_item_size as f64 / pr as f64;
                score -= 40.0 * fill;
                // harmonic check for the leftover after next item
                let pr2 = pr - next_item_size;
                if pr2 % 25 == 0 && pr2 > 0 { score -= 20.0; }
            } else {
                // next item won't fit here: mild penalty for stranding
                score += 10.0;
            }
        }
    }

    // Tight fit reward: item fills most of the bin
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 50.0 * tightness * tightness;

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: only attractive when no good existing fit exists
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 150.0;
        // cheaper to open a new bin late in the stream? No: early bins amortize more.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 30.0 * progress;
        // if many open bins with large mean residual, prefer reusing them
        score += 0.5 * mean_residual;
        // if this is the only option anyway, soften
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    // Mild penalty for spreading across too many open bins
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item nearly fills residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 60.0 * fill_ratio * fill_ratio;

    // Dead space penalty: small unusable gaps are costly, especially if the
    // next item cannot fit into the leftover space.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 25.0 + 0.5 * post_residual as f64;
        } else {
            // Reward leaving a gap that exactly (or nearly) accommodates lookahead.
            let gap_fit = next_item_size as f64 / post_residual as f64;
            score -= 20.0 * gap_fit.min(1.0);
        }
    }

    // Last chance: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into new ones;
    // a new empty bin candidate gets penalized more as open_bins_count grows.
    if bin_residual == bin_capacity {
        score += 15.0 + 3.0 * open_bins_count as f64;
        // But if current bins would leave bad dead space, new bin is attractive.
        if next_item_size > 0 && post_residual < next_item_size && bin_residual == bin_capacity {
            score -= 10.0;
        }
    } else {
        // Slight preference for bins with larger residuals among open bins.
        score -= 0.05 * bin_residual as f64;
    }

    // Mean residual coupling: if this bin's residual is far below mean, it is
    // "waste-prone"; prefer placing into below-mean-residual bins to consolidate.
    score += 0.1 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    score = post_residual as f64 * 1.0;

    // Reward perfect/near-perfect fits.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // 2-step lookahead: if the next item fits exactly in post_residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            // Next item fits: reward proportionally to how well it fills again.
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - chain_waste / bin_capacity as f64);
        } else {
            // Next item does NOT fit in this bin after placement: penalize.
            let overflow = (next_item_size - post_residual) as f64;
            score += 10.0 + overflow * 0.3;
        }
    }

    // Compare against mean residual across open bins: bins with more room than
    // average are better targets for large items; tighter-than-average bins
    // should be preserved for small items.
    let residual_gap = bin_residual as f64 - mean_residual;
    score += residual_gap * 0.15;

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // no existing bin offers a good fit. Penalize new bins unless the item
    // would leave a lot of dead space everywhere else.
    if bin_residual == bin_capacity {
        // New bin starts with post_residual == capacity, which already scores high.
        // Add penalty that shrinks when open bins are plentiful and fragmented.
        score += 30.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: new bin is mandatory anyway
        } else if mean_residual < item_size as f64 * 1.1 {
            // Existing bins are all tight; opening fresh space is reasonable.
            score -= 25.0;
        }
    }

    // Late in the stream, consolidation matters more: prefer filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    // Mild penalty per open bin to avoid needless bin proliferation.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fraction of the stream completed (dynamic time horizon).
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness of fit: reward filling the bin snugly (small post_residual relative to capacity).
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    let tight_bonus = (1.0 - post_residual as f64 / bin_capacity as f64) * 18.0 * (0.4 + 0.6 * fill_ratio);
    score -= tight_bonus;

    // Dead-space penalty: residuals too small for typical future items are wasted.
    let dead_threshold = 10.0f64.min(bin_capacity as f64 * 0.1);
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += 25.0 * (1.0 - post_residual as f64 / dead_threshold);
    }

    // Lookahead: reward leaving room for the next item, punish blocking it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect chaining: this bin can also host the next item.
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= 10.0 - 0.35 * chain_waste.min(30.0);
        } else {
            // The next item won't fit here; mild penalty scaled by how close we were.
            let miss = (next_item_size - post_residual) as f64;
            score += 4.0 * (miss / bin_capacity as f64).min(1.0) * (0.5 + 0.5 * (1.0 - t));
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits, avoiding a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Crowding control: when many bins are open, prefer consolidating into existing bins;
    // when few are open, opening new bins is cheaper.
    let crowding = (open_bins_count as f64).ln_1p();
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost grows with open-bin count and stream progress.
        score += 22.0 + 6.0 * crowding + 10.0 * t;
        // But if the fit elsewhere would be terrible (huge post_residual on an open bin),
        // a fresh bin is attractive: discount the new-bin cost.
        let worst_open = mean_residual.max(0.0);
        if worst_open > 55.0 {
            score -= 12.0 * ((worst_open - 55.0) / 45.0).min(1.0);
        }
        // Late in the stream, prefer closing out bins over spreading items.
        score += 8.0 * (1.0 - t);
    } else {
        // Existing bin: reward when its residual is far from the mean (reduces variance),
        // penalize bins that are already very full unless the fit is tight.
        let dev = (bin_residual as f64 - mean_residual).abs();
        score -= 1.5 * (dev / bin_capacity as f64);
        if bin_residual < item_size + 15 {
            score += 5.0 * (1.0 - t); // near-full bins early on are risky
        }
    }

    // Mild global pressure to keep mean residual low (pack tightly across the fleet).
    score += 0.05 * mean_residual;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Smooth polynomial coupling of post_residual with stream progress.
    // Early stream: mildly favor tight fits (low x). Late stream: strongly penalize waste.
    let poly = 1.0 + 2.0 * x - 3.0 * x * x + 1.5 * x * x * x;
    let mut score = pr * poly * (1.0 + 2.5 * progress * progress);

    // Reward bins whose residual will still fit the lookahead item (smooth coupling).
    if next_item_size > 0 {
        let fits_next = (pr >= next_item_size as f64) as i32 as f64;
        let slack = (pr - next_item_size as f64).abs() / cap;
        score -= fits_next * (8.0 + 12.0 * progress) * (1.0 - slack);
    }

    // Penalize dead space: small but nonzero post residual is wasted capacity.
    let dead = if pr > 0.0 && pr < 10.0 { (10.0 - pr) / 10.0 } else { 0.0 };
    score += dead * (10.0 + 20.0 * progress);

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Slight preference against opening new bins when many are already open.
    let new_bin = (bin_residual as f64 == cap) as i32 as f64;
    score += new_bin * (5.0 + 0.5 * open_bins_count as f64) * (1.0 + progress);

    // Coupling with mean residual: prefer bins below mean residual (tighter bins).
    let dev = (mean_residual - pr) / cap;
    score -= 5.0 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual is a "usable" class
    // (large enough to host typical small items) are rewarded.
    let post = post_residual;
    let usable = if post >= 50 { 3 } else if post >= 30 { 2 } else if post >= 10 { 1 } else { 0 };
    score -= (usable as f64) * 7.0;

    // Penalize residuals that fall into "dead" classes: too small for the
    // smallest plausible item (1..100, but practically >= 10 common).
    if post > 0 && post < 10 {
        score += 25.0;
    }

    // Modulo-10 class coupling: residuals that are multiples of 10 pair well
    // with many item sizes drawn from integer distributions.
    let class = (post % 10) as f64;
    score += class * 0.6;

    // Perfect fit: zero post_residual is ideal.
    if post == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: if next item fits exactly in the post residual,
    // strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 45.0;
        } else if next_item_size < post {
            score -= (post - next_item_size) as f64 * 0.3;
        } else {
            // next item won't fit here: mild penalty proportional to overflow
            score += (next_item_size - post) as f64 * 0.1;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current residuals
    // are all fragmented (mean residual low relative to item size).
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        if fragmentation > (item_size as f64 + 15.0) / bin_capacity as f64 {
            score += 30.0; // keep using open bins
        } else {
            score -= 10.0; // residuals too fragmented, fresh bin is fine
        }
    }

    // Late in stream: prefer tightening existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (post as f64) * 0.15;

    // Prefer bins below mean residual (tighter bins first).
    score += (mean_residual - bin_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small non-zero gaps are almost unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 - (post_residual as f64) * 2.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Penalize large post_residual that still can't fit a typical future item.
    if post_residual > 0 && post_residual < item_size {
        score += 8.0;
    }

    // Lookahead: if next item fits exactly in post_residual, reward strongly.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
        // Exact lookahead fit is ideal.
        if next_item_size == post_residual {
            score -= 10.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Dead space relative to the known next item.
        score += (post_residual as f64) * 0.15;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Open-bin pressure: with many bins open, prefer tighter packing.
    let pressure = (open_bins_count as f64).sqrt() * 1.5;
    score += pressure * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when current bins are nearly full
    // or the fit is terrible.
    if bin_residual == bin_capacity {
        let base = 55.0
            + (open_bins_count as f64) * 3.0
            + (mean_residual / bin_capacity as f64) * 30.0;
        score = base + post_residual as f64;
        if fitting_bins_count <= 1 {
            score += 60.0; // never open a new bin if it's the only fit
        }
    }

    // Late-stream consolidation: as the stream progresses, favor filling
    // existing bins harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: leave nothing behind.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward exact match of post_residual with next item size.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual >= next_item_size {
            // Reward leaving room for the next item, scaled by tightness.
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot use this residual: penalize proportionally.
            let miss = (next_item_size - post_residual) as f64;
            score += 30.0 * (miss / 100.0);
        }
    }

    // Penalize creating dead space far below mean residual (unusable gap).
    if (post_residual as f64) > mean_residual {
        score += 0.5 * ((post_residual as f64) - mean_residual);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Mildly discourage proliferating bins when plenty of fitting bins exist.
    if fitting_bins_count > 2 {
        score += 10.0;
    }

    // Prefer filling older bins slightly as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 20.0 * progress * (item_size as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Penalize large dead space relative to the smallest plausible item (1..100 range).
    if post_residual > 0 {
        let dead = post_residual as f64;
        score += 0.35 * dead.sqrt();
        // Dead space that cannot fit the lookahead item is worse.
        if next_item_size > 0 && post_residual < next_item_size {
            score += 6.0;
        }
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Fragmentation pressure: bins whose residual is far below mean residual
    // are already fragmented; penalize dumping into them unless fit is tight.
    let dev = bin_residual as f64 - mean_residual;
    if dev < 0.0 {
        score += 0.10 * (-dev);
    }

    // Time horizon: early in the stream, be pickier (penalize mediocre fits);
    // late in the stream, just fill anything.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 8.0 * (1.0 - t) * (1.0 - fill_ratio);

    // New-bin candidate: only attractive when open bins fit poorly.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = 55.0;
        // Cheaper to open a new bin when few bins are open and item is large.
        score -= 2.0 * open_bins_count as f64;
        score -= 0.2 * item_size as f64;
        // If no open bin fits, opening is mandatory anyway.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // If this bin is the last chance, opening is worse.
        if fitting_bins_count == 1 {
            score += 20.0;
        }
        // Late in stream, prefer closing out existing bins.
        score += 12.0 * t;
        // If mean residual is large, existing bins have room; penalize new bin.
        score += 0.15 * mean_residual;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalize stream progress and residual space
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap; // 0..1 residual after placement
    let fill = 1.0 - pr_norm; // fill fraction

    // Non-linear polynomial coupling: quadratic in post_residual modulated by progress.
    // Early in the stream, large residuals are more acceptable (future items can use them);
    // late in the stream, tight packing matters more, so penalize residual super-linearly.
    let progress_gain = 0.5 + 2.0 * progress;
    score += progress_gain * pr_norm * pr_norm * cap;

    // Smooth cubic fill reward: bins that become very full get extra priority,
    // strongest when the bin is nearly closed out.
    score -= 8.0 * fill * fill * fill;

    // Lookahead coupling: reward keeping residual that exactly serves the next item,
    // penalize residual that is useless for the next item (smooth bump around mismatch).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            // next item fits into post-residual: reward proportionally to tightness
            let tight = nxt / pr.max(1.0);
            score -= 4.0 * tight * tight;
        } else {
            // next item cannot use the residual: mild penalty growing with wasted gap
            let gap = (nxt - pr) / cap;
            score += 3.0 * gap * gap * cap;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin (smoothly scaled by current residual scarcity).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0 + 0.1 * mean_residual;
    }

    // New-bin candidate handling: an empty bin should only win when open bins are
    // badly fragmented. Compare this bin's post-residual to the mean residual of
    // open bins via a smooth interaction term.
    if bin_residual == bin_capacity {
        let frag = (mean_residual / cap).clamp(0.0, 1.0);
        // penalty grows with number of open bins and their mean residual (fragmentation)
        let open_factor = (open_bins_count as f64).ln().max(0.0);
        let penalty = 25.0 + 10.0 * open_factor * frag;
        // discount penalty late in the stream (consolidation phase)
        score += penalty * (1.0 - 0.5 * progress);
    } else {
        // Slight preference for bins already more filled than average (best-fit flavor)
        let rel = ((bin_residual as f64) - mean_residual) / cap;
        score += 2.0 * rel * rel.abs();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: capacity fractions
    let cap = bin_capacity as f64;
    let post_frac = post_residual as f64 / cap;
    let item_frac = item_size as f64 / cap;

    // Penalize small-but-unusable dead space (post_residual in (0, 10))
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Reward exact fills (post_residual == 0) strongly
    if post_residual == 0 {
        score -= 200.0;
    }

    // Harmonic classes of post_residual via integer division thresholds
    let post_class = post_residual / 25; // 0..4 classes
    score -= match post_class {
        0 => 15.0,                 // post_residual < 25: tight fit
        1 => 5.0,                  // 25..49: can host small items
        2 => 0.0,                  // 50..74: half-full class
        3 => -8.0,                 // 75..99: roomy bin, good
        _ => -12.0,                // untouched/new bin
    };

    // Lookahead coupling: does post_residual still admit next_item_size?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // residual usable by next item: reward proportionally
            score -= 20.0 * (next_item_size as f64 / cap);
        } else {
            // next item cannot use this bin: penalize dead space
            score += 12.0 * (1.0 - post_frac);
            // extra penalty if next item would have fit before this placement
            if bin_residual >= next_item_size {
                score += 10.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: attractive early or when few bins fit
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // opening a new bin is fine when many bins already open and fit is poor
        let fit_pressure = 1.0 / (fitting_bins_count as f64);
        score -= 30.0 * fit_pressure * (1.0 - progress);
        // keep new bins mildly attractive when mean residual is high (fragmentation)
        score -= 0.15 * (mean_residual / cap - post_frac).max(0.0);
    } else {
        // prefer filling bins that are already partially used (reduce bin count)
        score -= 10.0 * (1.0 - bin_residual as f64 / cap);
    }

    // Modulo arithmetic on post_residual: multiples of 10 are "clean" slots
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    }

    // Mild penalty for very large items consuming roomy bins
    if item_frac > 0.7 && post_class >= 3 {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..10) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 3.0;
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward tight fits relative to current residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Open-bin pressure: discourage spreading across many bins unless fit is tight.
    score += (open_bins_count as f64).sqrt() * (1.0 - fill_ratio) * 8.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when this item fits poorly everywhere
    // (i.e., residual after placement is large) or no open bin exists.
    let is_new_bin = bin_residual == bin_capacity && bin_capacity > 0;
    if is_new_bin {
        // Penalize opening a new bin by default.
        score += 45.0;
        // But if the item would leave a big residual in an existing bin anyway,
        // a fresh bin with full residual is comparably good.
        score -= (post_residual as f64 / bin_capacity as f64) * 40.0;
        // Lookahead: if next item is large, a fresh bin is more valuable.
        if next_item_size > 50 {
            score -= 15.0;
        }
        // Early in stream, allow opening bins more freely.
        if total_items > 0 && (step_index as f64) / (total_items as f64) < 0.3 {
            score -= 10.0;
        }
    }

    // Lookahead synergy: bonus if post_residual can exactly host the next item.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 10 {
        score -= 20.0;
    }
    // Penalize leaving a residual that cannot fit the known next item and is tiny.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 20 {
        score += 12.0;
    }

    // Mild tie-break toward bins with below-mean residual (more filled bins).
    let bin_res_f = bin_residual as f64;
    if mean_residual > 0.0 {
        score += (bin_res_f - mean_residual) * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect or near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: if the next item exactly fits the post residual,
    // this is a chain match -> heavily favor this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 400.0;
        } else if gap <= 10 {
            score -= 100.0;
        } else {
            score -= 20.0;
        }
    } else if next_item_size > 0 {
        // Next item cannot use the leftover: penalize dead space proportionally.
        score += (post_residual as f64) * 0.3;
    }

    // Relative to mean residual: bins with more residual than average are
    // "wasteful" targets unless the lookahead matches; prefer tighter bins.
    let res = post_residual as f64;
    if res > mean_residual {
        score += (res - mean_residual) * 0.5;
    } else {
        score -= (mean_residual - res) * 0.2;
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: penalize opening a new bin unless the current fit is bad.
    if bin_residual == bin_capacity {
        score += 150.0;
        // But if the item is large relative to capacity and nothing else helps,
        // opening fresh is fine: soften when item is big.
        if item_size > bin_capacity / 2 {
            score -= 50.0;
        }
    }

    // Early in stream, keep bins compact to build good structure.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score += (1.0 - progress) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small dead space).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Lookahead: reward if the next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            score -= 15.0;
        } else {
            // Post-residual too small for next item: penalize wasted space more.
            let waste = (post_residual as f64) / (next_item_size as f64).max(1.0);
            score += 20.0 * waste;
        }
    }

    // Penalize leaving residual far from mean (fragmentation signal).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.3 * dev;

    // Opening a brand-new bin: only attractive when many items remain
    // and current bins are crowded (low mean residual).
    if bin_residual == bin_capacity {
        let horizon = (total_items.saturating_sub(step_index)) as f64;
        let crowding = 1.0 - (mean_residual / bin_capacity as f64);
        score += 25.0; // base cost of a new bin
        score -= 10.0 * crowding;
        if horizon > 50.0 { score -= 5.0; }
    }

    // Late in the stream, avoid spawning bins; prefer filling existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual != bin_capacity {
        score -= 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: penalize residual, with non-linear polynomial shaping.
    let mut score = post;

    // Quadratic-cubic residual shaping: small residuals are fine (dead space),
    // mid residuals are costly (wasted capacity), tiny residuals excellent.
    let x = post / cap; // in [0,1]
    score += 30.0 * x * (1.0 - x) * (1.0 - x); // peak penalty near x=1/3

    // Stream-progress coupling: early on, prefer tight fits less aggressively;
    // late in stream, tighten up (multiply penalty by (1 + progress)).
    score *= 1.0 + 1.5 * progress * x;

    // Perfect-fit reward (smooth exponential rather than hard threshold).
    if post == 0 {
        score -= 50.0;
    } else {
        score -= 20.0 * (-x * 8.0).exp() * (1.0 - progress);
    }

    // Lookahead: reward if next item fits the post residual (chaining bonus).
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 12.0 * (1.0 - post / cap) * (0.5 + progress);
    } else if next_item_size > 0 {
        // Penalize leaving a residual that no typical item can use.
        let gap = post - (next_item_size as f64);
        score += 5.0 * (gap / cap);
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // Among many candidates, mild preference for fuller bins.
        score += 3.0 * (1.0 - item_size as f64 / bin_residual.max(1) as f64);
    }

    // New-bin candidate: penalize opening a fresh bin when open bins fit,
    // unless existing residuals are all large (fragmented state).
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).clamp(0.0, 1.0);
        score = cap + 40.0 - 30.0 * fragmentation * fragmentation - 15.0 * progress;
        if fitting_bins_count == 0 {
            score -= 60.0; // no alternative: new bin is fine
        }
    }

    // Mild diversity term: discourage spreading when many bins are open early.
    score += 2.0 * (open_bins_count as f64).ln().max(0.0) * (1.0 - progress) * x;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect / near-perfect fit rewards
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // Harmonic class of post_residual: dead space classes modulo capacity fractions
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let quarter = cap / 4.0;
    let eighth = cap / 8.0;

    // Penalize residuals that fall into "useless" harmonic classes:
    // residuals just below common item sizes (10..80 grid) are hard to fill.
    let dead_zone = |r: u32| -> f64 {
        let mut pen = 0.0;
        for &s in &[10u32, 15, 20, 25, 30, 40, 50, 60, 70, 80] {
            if r > 0 && r < s && s - r <= 10 {
                pen += (s - r) as f64 * 1.5;
            }
        }
        pen
    };
    score += dead_zone(post_residual);

    // Residuals in "friendly" classes (multiples of 10, or >= 40) are reusable
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 25.0;
    }
    if pr >= 2.0 * quarter {
        score -= 10.0; // large residual likely reusable
    } else if pr < eighth && post_residual > 0 {
        score += 15.0; // tiny sliver, likely dead
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            score -= 60.0 - slack.min(60) as f64;
            score += dead_zone(post_residual - next_item_size) * 0.5;
        } else {
            // next item won't fit here: mild penalty scaled by gap
            score += ((next_item_size - post_residual).min(30)) as f64 * 0.8;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: only open a new bin when current fits are awful
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score = cap * 0.75;
        if next_item_size > 0 && next_item_size >= bin_residual {
            score -= 50.0;
        }
        // Prefer new bin late in stream when many bins are open with fragmented residuals
        if fitting_bins_count > 0 && mean_residual < 20.0 {
            score -= 40.0;
        }
        if step_index as f64 / total_items.max(1) as f64 > 0.8 && open_bins_count > 3 {
            score -= 20.0;
        }
    }

    // Prefer filling bins with below-average residual (consolidate fragments)
    if bin_residual != bin_capacity {
        score += (pr - mean_residual) * 0.3;
    }

    // Mild preference for keeping open-bin count low
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space heavily (non-linear "gap cliff")
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 15.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Reward near-perfect fits
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward leaving space usable by the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 {
        score += 5.0;
    }

    // Open bins pressure: discourage spreading when many bins are open
    score += (open_bins_count as f64) * 0.3;

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Slight preference for tighter existing bins vs empty new bin
    if bin_residual == bin_capacity {
        score += 8.0;
    }

    // Progress-based tightening: later in stream, be stricter about waste
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect / near-perfect fits
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    } else if post_residual <= 15 {
        score -= 15.0;
    }

    // 2-step lookahead: reward when next item fits exactly into post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0; // chain fit: ideal pairing
        } else if post_residual > next_item_size {
            let leftover_after_next = post_residual - next_item_size;
            if leftover_after_next <= 10 {
                score -= 80.0; // two-item chain nearly closes bin
            } else {
                score -= (leftover_after_next as f64).sqrt() * 4.0;
            }
        } else {
            // next item cannot fit here: penalize wasted potential
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.8;
        }
    } else {
        // last item: closing bins is free, prefer tightest fit
        score -= 50.0;
    }

    // Last-chance bin bonus: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Penalize opening a new bin when open bins still have good residual space
    if bin_residual == bin_capacity {
        // new-bin candidate: baseline is its residual; penalize unless item is large
        // relative to capacity or existing bins are fragmented
        let fragmentation = mean_residual / bin_capacity as f64;
        let large_item = item_size as f64 / bin_capacity as f64;
        score += 30.0 + 40.0 * (1.0 - large_item) - 30.0 * fragmentation;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 40.0; // new bin can host the next item too
        }
    } else {
        // prefer bins with residual below mean (tighter bins first)
        let diff = bin_residual as f64 - mean_residual;
        score += diff * 0.3;
    }

    // Late in the stream, consolidate aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0 * (post_residual as f64).sqrt();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: squared penalty on leftover space.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64 * 2.0);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= bin_capacity as f64 * 1.5;
    }

    // Lookahead: reward if the next item also fits in the remaining space.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 0.8;
    }
    // Penalize leaving a gap that exactly blocks nothing useful (dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += post_residual as f64 * 0.3;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }
    // Many fitting bins: mild penalty to prefer the tightest one (already via post_residual).

    // New-bin candidate: penalize opening a new bin, more so when good fits exist
    // and when many bins are already open (consolidation phase).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 + open_bins_count as f64 * 2.0 + progress * 20.0;
        // But if the item is huge relative to mean residual, opening fresh may be wise.
        if mean_residual > 0.0 && (item_size as f64) > mean_residual {
            score -= 15.0;
        }
    }

    // Prefer bins whose residual deviates below the mean (nearly-full bins get used up).
    if bin_residual != bin_capacity {
        let dev = mean_residual - bin_residual as f64;
        if dev > 0.0 {
            score -= dev * 0.5;
        }
    }

    // Late in the stream, avoid spreading across many bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (open_bins_count as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on, prefer tight fills (low post_residual) aggressively;
    // later, residual waste matters more, so amplify quadratic term.
    let pr_norm = pr / cap;
    let prog2 = progress * progress;
    let coupling = pr_norm * pr_norm * (0.5 + 2.5 * prog2) * cap;
    score += coupling;

    // Smooth cubic term: penalize mid-range residuals more as stream advances.
    score += 10.0 * prog2 * pr_norm * (1.0 - pr_norm) * (1.0 - pr_norm);

    // Reward bins that leave room for the lookahead item (smooth kernel).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let diff = (pr - nx) / cap;
        let k = (-diff * diff * 8.0).exp();
        score -= 12.0 * k;
    }

    // Last-chance bonus: strongly favor the only bin that can fit the item.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Slight preference for consolidating into fewer bins as they accumulate.
    score -= 0.5 * (open_bins_count as f64).ln().max(0.0);

    // Mild tie-break toward bins below mean residual (denser bins).
    score += 0.05 * (pr - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo arithmetic on capacity.
    // Perfect fits (residual 0) are heavily rewarded.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Classify dead space by integer-division thresholds on post_residual.
        // Small residuals (<10) are nearly unusable dead space -> penalize hard.
        if post_residual < 10 {
            score += 200.0;
        } else if post_residual < 20 {
            score += 80.0;
        }
        // Harmonic classes: residual mod capacity fraction buckets.
        // Residuals in "nice" classes (multiples of 10, matching typical item sizes)
        // are more likely to be filled by future items -> reward them.
        let class = post_residual % 10;
        if class == 0 {
            score -= 30.0;
        } else if class >= 5 {
            score -= 10.0;
        } else {
            score += 10.0;
        }
    }

    // Lookahead: does the next item fit exactly in the resulting residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            // Next item fits: reward proportionally to how well it fills.
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 50.0 + 100.0 * fill;
        } else {
            // Next item cannot use this residual: penalize proportional to leftover size.
            score += 0.5 * (post_residual as f64 - next_item_size as f64).abs();
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate handling: opening a new bin should only win when
    // no open bin offers a good fit. Give the fresh bin a mild penalty
    // so it's chosen only when all open bins score badly.
    if bin_residual == bin_capacity {
        score += 60.0 + mean_residual * 0.2;
    } else {
        // Slight reward for packing into bins with low mean residual overall.
        score -= (bin_residual as f64 - mean_residual) * 0.1;
    }

    // Progression: later in the stream, tighten up (prefer tight fits more).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 20.0 * (post_residual as f64 / bin_capacity as f64);

    // Prefer consolidating into fewer bins when many are open.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps after placement.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // tiny dead gap is worthless
    } else if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    } else if post_residual == 0 {
        score -= 40.0; // perfect fit reward
    }

    // Favor leaving residuals that can host the next item (lookahead k=2).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 8.0 * (1.0 - (post_residual as f64) / (next_item_size as f64).max(1.0));
    }

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: many open bins -> prefer filling existing ones.
    let pressure = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
    score += pressure * (post_residual as f64) * 0.5;

    // New-bin candidate: penalize opening a bin unless current fit is poor.
    if bin_residual == bin_capacity {
        score += 30.0 + 6.0 * (fitting_bins_count as f64);
        if post_residual < 20 {
            score -= 25.0; // large item into fresh bin is fine
        }
    }

    // Mean-residual coupling: if this bin's residual is far below mean, it is a good filler.
    score += 0.3 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fill: strongest reward.
    if post_residual == 0 {
        score -= 60.0;
    } else if next_item_size > 0 {
        // 2-step lookahead: exact match leaves room for the next item.
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual < next_item_size {
            // Dead space too small for the lookahead item: penalize proportionally.
            score += 0.6 * (next_item_size - post_residual) as f64;
        } else {
            // Leftover still usable by next item: mild reward scaling with slack.
            score -= 0.1 * (post_residual - next_item_size) as f64;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
