    }

    // New-bin candidate: penalize mildly, more so as open bins accumulate,
    // so a new bin is only chosen when fits into open bins are poor.
    if bin_residual == bin_capacity {
        score += 6.0 + 0.15 * open_bins_count as f64;
    }

    // Contextual coupling: prefer bins whose residual sits below the mean
    // (denser bins get closed out first), scaled by stream progression.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (0.05 + 0.10 * progress) * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that cannot fit the average upcoming item
    if post_residual > 0 {
        let usable = (post_residual as f64) / ((item_size as f64) / 2.0 + 1.0);
        score -= 3.0 * usable.min(10.0);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: reward bins whose post_residual can still hold the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += 0.35 * (next_item_size - post_residual.min(next_item_size)) as f64;
        }
    }

    // Time horizon: late in the stream, consolidate aggressively
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 6.0 * progress * tightness;

    // Global state: many open bins with high mean residual -> prefer filling existing bins
    if bin_residual != bin_capacity {
        score -= 0.05 * open_bins_count as f64 * (mean_residual / (bin_capacity as f64));
    } else {
        // New-bin candidate: penalize slightly unless current bins are nearly full
        score += 4.0;
        if mean_residual < 15.0 {
            score -= 6.0;
        }
    }

    // Prefer bins with residual just above item size (snug fit)
    let slack = (bin_residual - item_size) as f64;
    score += 0.1 * (slack / (bin_capacity as f64)) * (slack / (bin_capacity as f64)) * 100.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_post = post / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early in the stream, waste is more tolerable; later, tight packing matters more.
    let progress_penalty = (1.0 + progress * progress) * 20.0;

    // Base: post residual, with quadratic amplification of large waste.
    let mut score = post + norm_post * norm_post * 40.0 * progress_penalty / 20.0;

    // Reward near-perfect fits: small post_residual gets a strong discount.
    let tightness = 1.0 - norm_post;
    score -= tightness * tightness * tightness * 25.0;

    // Lookahead coupling: if the next item fits exactly in post_residual, reward heavily.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let fit_gap = (post - nxt) / cap;
            score -= (1.0 - fit_gap) * 15.0;
        } else {
            // Next item won't fit here; penalize slightly less if post_residual is large.
            score += (nxt - post) / cap * 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 18.0 + 10.0 * progress;
    }

    // Penalize bins whose residual is far from the mean residual (keeps bin states uniform).
    let dev = (post - mean_residual).abs() / cap;
    score += dev * dev * 12.0;

    // Slight preference to spread load when many bins are open.
    score += open_bins_count as f64 * 0.05;

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let escape = 10.0 + 25.0 * (1.0 - progress);
        score += escape;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact fit classes are heavily rewarded.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;

    // Perfect fit: overwhelming reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space penalty: residuals too small for the smallest plausible item (1).
    // Since sizes >= 1, any residual is technically usable, but tiny residuals waste slots.
    if post_residual < 5 {
        score += 25.0; // nearly-dead residual class
    } else if post_residual < 10 {
        score += 10.0;
    }

    // Harmonic class: group post_residual into capacity/8 octants.
    let octant = (post_residual * 8 / bin_capacity) as f64;
    score += octant * 3.0;

    // Modulo-class logic: residuals that are multiples of common size blocks (5,10,20,25)
    // are more likely to be filled by future items.
    if post_residual % 5 == 0 { score -= 6.0; }
    if post_residual % 10 == 0 { score -= 6.0; }
    if post_residual % 20 == 0 { score -= 4.0; }
    if post_residual % 25 == 0 { score -= 4.0; }

    // Lookahead coupling: reward if next item fits the post_residual exactly or nearly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 120.0; // chain fit
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - slack / cap);
        } else {
            // next item cannot fit: residual risks becoming dead space
            score += 0.5 * ((next_item_size - post_residual) as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when all open fits are terrible.
    if bin_residual == bin_capacity {
        // New bin starts with residual = capacity; neutral-ish baseline with mild bias.
        score = cap * 0.9 - (open_bins_count as f64).min(8.0) * 2.0;
        if next_item_size > 0 && next_item_size as f64 <= cap {
            score -= 5.0;
        }
        // If this is the only option, make it attractive.
        if fitting_bins_count == 0 {
            score -= 500.0;
        }
    }

    // Mean residual coupling: prefer bins whose residual is below mean (tighter packing).
    score += 0.3 * (pr - mean_residual).max(-cap) * 0.1;

    // Slight late-stream conservatism: keep residuals flexible early, pack tight late.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 2.0 * pr / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
