    // Last-chance bin: strongly prefer using the only fitting bin to avoid
    // opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones
    // and encourage consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.35 + 0.65 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportional to open-bin pressure.
        score += 55.0 + pressure * 6.0;
        // But if the item is large and no tight fit exists, new bin is safer.
        if item_size >= 60 && mean_residual < item_size as f64 {
            score -= 70.0;
        }
    } else {
        // Reward placing into bins whose residual is above mean (spread load),
        // penalize draining below-average bins too much.
        let dev = bin_residual as f64 - mean_residual;
        score -= 0.12 * dev;
    }

    // Lookahead: if next item fits exactly in the post_residual, reward;
    // if post_residual is just below next_item_size, penalize (near-miss gap).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual > next_item_size && post_residual - next_item_size < 10 {
            score -= 12.0;
        } else if post_residual < next_item_size && post_residual >= 10 {
            score += 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact / near-exact fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Tightness relative to capacity: smaller post_residual => much lower score.
        let tightness = post_residual as f64 / bin_capacity as f64;
        score += tightness * 50.0;
    }

    // 2-step lookahead: reward when next item fits the post-residual exactly or well.
    if next_item_size > 0 && post_residual >= next_item_size {
        let lookahead_slack = (post_residual - next_item_size) as f64;
        score -= 120.0 - lookahead_slack * 0.8;
        if post_residual == next_item_size {
            score -= 300.0;
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Penalize when next item cannot follow in this bin, scaled by how close it is.
        let gap = (next_item_size - post_residual) as f64;
        score += gap * 0.5;
    }

    // Last chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Prefer bins whose residual is already below mean residual (consolidating small leftovers).
    if (bin_residual as f64) < mean_residual {
        score -= 15.0;
    } else {
        score += (bin_residual as f64 - mean_residual) * 0.3;
    }

    // New-bin candidate handling: penalize opening a new bin unless no good fit exists.
    if bin_residual == bin_capacity {
        let base_penalty = 60.0;
        // Early in the stream, opening bins is cheaper (more items to come to fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += base_penalty + progress * 80.0;
        // If many open bins already, discourage yet another.
        score += open_bins_count as f64 * 2.0;
        // If next item is large, a fresh bin may be useful.
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual)
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * tightness * tightness;

    // Reward when post_residual would be 0 (perfect fit)
    if post_residual == 0 {
        score -= 100.0;
    }

    // Penalize leaving dead space that is too small for typical items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward if next item fits in post_residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
        } else {
            score += (next_item_size as f64 - post_residual as f64).min(40.0) * 0.5;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when existing residuals are fragmented
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score += 35.0 + 0.3 * open_bins_count as f64 - 0.2 * fragmentation;
        // Late in stream, prefer closing out existing bins rather than opening new ones
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    } else {
        // Prefer bins whose residual is below mean (consolidate fullness)
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        } else {
            score += 3.0;
        }
    }

    // Mild penalty for spreading across many open bins
    score += 0.15 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with smooth polynomial shrink factor over progress
    let shrink = 1.0 - 0.35 * progress * progress;
    let mut score = pr * shrink;

    // Smooth coupling: post_residual^2 normalized, weighted by progress
    score += 40.0 * norm_pr * norm_pr * (0.5 + progress);

    // Perfect/near fit reward (small post residual), stronger late
    let fit_bonus = (-norm_pr * 12.0).exp();
    score -= 25.0 * fit_bonus * (0.4 + 0.6 * progress);

    // Dead space penalty: large post residual relative to mean residual
    if mean_residual > 0.0 {
        score += 8.0 * ((pr - mean_residual) / cap).abs();
    }

    // Last-chance bin: strong reward to use it rather than open new bin
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - norm_pr);
    }

    // Lookahead: if next item fits into post residual, reward this placement
    if next_item_size > 0 {
        let next_fits = (post_residual as i64 - next_item_size as i64) >= 0;
        if next_fits {
            score -= 12.0 * (1.0 - (next_item_size as f64 / cap));
        } else {
            score += 5.0 * (next_item_size as f64 / cap) * progress;
        }
    }

    // Penalize opening new bins when many bins are open and progress is early
    if bin_residual == bin_capacity {
        score += 15.0 + 25.0 * (1.0 - progress);
    }

    // Mild crowding term: many open bins -> prefer filling existing ones
    score -= (open_bins_count as f64).ln().max(0.0) * (1.0 - norm_pr) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Base: best-fit core — prefer minimal post_residual (tight packing).
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: classify leftover space into
    // capacity fractions. Residuals that are "usable" (large enough for typical
    // future items) are rewarded; tiny unusable slivers are penalized.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;

    if post_residual == 0 {
        // Perfect fit — strong reward.
        score -= 25.0;
    } else if post_residual < quarter {
        // Dead space sliver: penalize proportionally to how useless it is.
        score += (quarter - post_residual) as f64 * 0.5;
    } else if post_residual <= half {
        // Mid-range residual: mildly good.
        score -= 3.0;
    } else {
        // Large residual left: this bin was a poor fit for the item.
        score += 4.0;
    }

    // Modulo-class coupling: residuals in {0, 25, 50, 75, 100} are ideal
    // "harmonic" states; reward proximity to the nearest harmonic value.
    let harmonics: [u32; 5] = [0, quarter, half, 3 * quarter, bin_capacity];
    let mut dist = u32::MAX;
    for h in harmonics.iter() {
        let d = if post_residual > *h { post_residual - *h } else { *h - post_residual };
        if d < dist { dist = d; }
    }
    score -= (12 - dist) as f64 * 0.6;

    // Lookahead: if the next item fits the post_residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0 + (next_item_size as f64) * 0.05;
        } else {
            // Next item won't fit: slight penalty, worse if residual is tiny.
            score += 2.0;
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item, strongly
    // favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing bins fit poorly. Base cost of opening a bin:
    if bin_residual == bin_capacity {
        score += 10.0;
        // But if the item is large (hard to place later), a fresh bin is fine.
        if item_size > half {
            score -= 12.0;
        }
        // Early in the stream with many bins already open, discourage sprawl.
        if open_bins_count > 0 && (step_index as f64) / (total_items.max(1) as f64) < 0.3 {
            score += 5.0;
        }
    } else {
        // Reward using already-open bins to keep bin count down,
        // scaled by how many bins are currently open.
        score -= 1.5 + (open_bins_count as f64).sqrt() * 0.8;
        // Prefer bins whose residual is close to the item (tight fit refinement).
        let tightness = (bin_residual - item_size) as f64;
        score += tightness * 0.02;
    }

    // Mild preference toward bins below mean residual (balancing residuals).
    score += (mean_residual - post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // possible item (1..100 interface) are pure waste.
    let dead_zone: f64 = 10.0;
    if (post_residual as f64) < dead_zone {
        score += 40.0 * (dead_zone - post_residual as f64) / dead_zone;
    }

    // Reward tight fits (small post_residual relative to item size).
    if item_size > 0 {
        score -= (item_size as f64) * 0.6;
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Penalize leaving a gap that the lookahead item cannot use.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }
    // Reward leaving a gap exactly usable by the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // over opening new bins.
    score += (open_bins_count as f64) * 1.5;

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when existing residuals
    // are large (poor fits elsewhere) or few bins are open.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        score += 20.0 + 60.0 * (1.0 - pressure);
        score -= (open_bins_count as f64) * 2.0;
    }

    // Mild progression term: later in the stream, waste matters more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * (post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item size
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            // Perfect match (next item exactly fills leftover) gets strong reward
            if gap == 0.0 {
                score -= 60.0;
            } else {
                // Closer match -> bigger reward; penalize large unusable leftovers
                score -= 30.0 * (1.0 - gap / bin_capacity as f64);
            }
        } else {
            // Next item cannot fit in leftover: penalize proportionally
            let deficit = (next_item_size - post_residual) as f64;
            score += 10.0 + 20.0 * (deficit / bin_capacity as f64);
        }
    } else {
        // Last item: prefer tightest fill
        score -= 40.0;
    }

    // Prefer bins already below mean residual (consolidating waste)
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strong incentive to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when open bins exist and fit reasonably
    if bin_residual == bin_capacity {
        score += 15.0 + 0.2 * open_bins_count as f64;
    }

    // Slight pressure toward tighter fits overall
    score += 0.1 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is superb
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tightness: reward small post residual relative to capacity
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tight * tight;

    // Lookahead: reward if next item fits the post residual
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 30.0 + 0.3 * next_item_size as f64;
    }
    // Penalize if next item almost fits (near miss creating dead space)
    if next_item_size > post_residual && next_item_size > 0 && post_residual > 0 {
        let gap = (next_item_size - post_residual) as f64;
        if gap < 15.0 {
            score += 25.0 * (1.0 - gap / 15.0);
        }
    }

    // Last chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // Penalize wasting space in a nearly full bin when many bins could fit
    if fitting_bins_count > 3 && post_residual > 40 {
        score += 15.0;
    }

    // Global state: when many open bins, prefer consolidation (low residual bins)
    let progress = step_index as f64 / total_items.max(1) as f64;
    if open_bins_count > 2 {
        score += 0.5 * (post_residual as f64 - mean_residual);
    }

    // New-bin candidate logic: empty bin gets a baseline score that adapts
    if bin_residual == bin_capacity {
        // Prefer new bin early or when existing residuals are large/poor fits
        let new_bin_score = 60.0 - 50.0 * progress - 0.2 * mean_residual;
        score = new_bin_score + 0.1 * item_size as f64;
        // If only this new bin can fit, must use it
        if fitting_bins_count == 0 {
            score -= 500.0;
        }
    }

    // Late stream: be greedy, minimize residual harder
    if progress > 0.7 {
        score -= 20.0 * tight;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: penalize wasted space with a non-linear (quadratic) coupling
    let mut score = pr * pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, large residuals are tolerable; late, they hurt more.
    let coupling = pr / cap;
    score += 40.0 * coupling * coupling * progress;
    score -= 15.0 * coupling * (1.0 - progress) * (1.0 - progress);

    // Reward tight fits: post_residual near zero gets a smooth cubic bonus
    score -= 30.0 * (1.0 - coupling).powi(3);

    // Lookahead: if next item fits into post_residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 20.0 * (1.0 - pr / cap);
    } else if next_item_size > 0 {
        // next item won't fit: mildly penalize leaving awkward residuals
        score += 10.0 * (pr / cap);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize contributing to residual dispersion across many open bins
    score += 0.05 * (pr - mean_residual).abs() * (open_bins_count as f64).ln().max(1.0);

    // New-bin candidate should rarely win: add a smooth penalty scaled by progress
    if bin_residual == bin_capacity {
        score += 30.0 + 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the space.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 60.0 * fill_ratio * fill_ratio;

    // Harmonic class of post_residual: residual mod 10 buckets.
    let rmod = post_residual % 10;
    score += match rmod {
        0 => -8.0,   // perfectly reusable residual
        5 => -4.0,   // half-decade residual
        1 | 9 => 6.0,
        _ => 2.0,
    };

    // Lookahead: reward if the next item also fits in the post residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 25.0;
        // Extra reward for chaining into a near-exact second fit.
        let second_fill = next_item_size as f64 / post_residual as f64;
        score -= 20.0 * second_fill;
    } else if next_item_size > 0 {
        // Penalize if lookahead item can't use the leftover.
        score += 8.0;
    }

    // Dead-space penalty: residuals too small for the smallest plausible item.
    if post_residual < 10 && post_residual > 0 {
        score += 30.0;
    }

    // Last-chance bin: strongly prefer using it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let poor_fit = 1.0 - fill_ratio;
        score += 35.0 - 45.0 * scarcity - 30.0 * poor_fit * (1.0 - scarcity);
        // Early in the stream, opening bins is cheap; later, consolidate.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Prefer distributing load when many bins are open with slack.
    if bin_residual < bin_capacity {
        let slack = mean_residual - bin_residual as f64;
        if slack > 0.0 {
            score -= 3.0 * slack.min(20.0) / 10.0;
        }
    }

    // Mild penalty for hoarding too many open bins.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any future item (min size 1,
    // but practically small gaps) are heavily penalized with a non-linear ramp.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 8.0;
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward bins whose post_residual can still hold a plausible next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Gap that cannot fit the lookahead item: mild penalty scaled by waste.
        score += (post_residual as f64).min(next_item_size as f64) * 0.5;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, discourage opening yet another bin.
    let new_bin_candidate = bin_residual == bin_capacity;
    if new_bin_candidate {
        score += 30.0 + open_bins_count as f64 * 2.5;
        // But allow new bin if no open bin fits well (this bin is the only option anyway).
        if fitting_bins_count <= 1 {
            score -= 45.0;
        }
    } else {
        // Favor bins tighter than the mean residual (better current fill).
        score += (mean_residual - bin_residual as f64) * 0.3;
    }

    // Late in the stream, consolidate aggressively to avoid ending with many half-full bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 5.0 * (bin_capacity - bin_residual) as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward post_residual that exactly fits the next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual > next_item_size {
            // leftover after hypothetically placing next item too
            let chain_left = post_residual - next_item_size;
            score -= 60.0 - (chain_left as f64).min(50.0);
        } else {
            // next item cannot fit in the leftover: penalize dead space
            score += 30.0 + (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Tight fit relative to residual
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 40.0;

    // Prefer bins with residuals near mean (avoid fragmenting outliers)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.3;

    // Last chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad
    if bin_residual == bin_capacity {
        score += 150.0;
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 100.0;
        }
    }

    // Late in stream: prefer consolidating into existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= progress * 20.0;
    }

    // Many open bins: encourage filling them rather than opening more
    score += open_bins_count as f64 * 2.0 * (if bin_residual == bin_capacity { 1.0 } else { -0.5 });

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (post_residual small relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful later (unusable gap).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    }

    // Lookahead coupling: reward if post_residual exactly accommodates next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here; mild penalty proportional to mismatch
            let miss = (next_item_size - post_residual) as f64;
            score += 0.15 * miss;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits to avoid opening new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Time horizon: early in stream, be pickier about waste (long future to regret it);
    // late in stream, closing bins tightly matters more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 0.10 * post_residual as f64;
    score -= progress * 10.0 * (1.0 - tightness);

    // Global state: many open bins with high mean residual -> encourage consolidation
    // into existing bins rather than opening new ones.
    if open_bins_count > 0 {
        score += 0.05 * (open_bins_count as f64) * (mean_residual / bin_capacity as f64).max(0.0);
    }

    // New-bin candidate: penalize opening a new bin unless current bin would leave
    // a large unusable residual while a fresh bin offers a clean slate.
    if bin_residual == bin_capacity {
        let poor_fit = if fitting_bins_count >= 1 && post_residual < 10 { 0.0 } else { 12.0 };
        score += poor_fit;
        // Opening a new bin is fine early, costly when many bins already open.
        score += 2.0 * (open_bins_count as f64).ln().max(0.0);
    }

    // Mild reward for filling bins completely (post_residual == 0).
    if post_residual == 0 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Non-linear coupling: quadratic in post_residual scaled by capacity,
    // modulated by smooth progress term.
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let coupling = pr_norm * pr_norm * (0.5 + progress) + pr_norm * (1.0 - progress) * 0.3;
    score += coupling * cap * 0.5;

    // Reward tight fits (small post_residual) more strongly as stream progresses
    let tightness = (bin_residual as f64 - pr) / cap; // = item_size / cap
    score -= tightness * tightness * cap * (0.4 + 0.6 * progress);

    // Penalize bins whose residual deviates from mean residual (fragmentation)
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += dev * dev * cap * 0.35;

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= cap * 0.8 * (1.0 + 0.5 * progress);
    } else {
        // Mild reward when many bins can fit (keeps options open)
        score -= (fitting_bins_count as f64).ln().max(0.0) * 2.0;
    }

    // Lookahead: reward leaving space for the next item
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if pr >= n {
            let slack_fit = (pr - n) / cap;
            score -= (1.0 - slack_fit) * cap * 0.25;
        } else {
            // post_residual can't host next item: penalize dead space
            score += (n - pr) / cap * cap * 0.2;
        }
    }

    // New empty bin candidate: penalize so it's chosen only when fits are poor,
    // with penalty decaying as stream progresses (consolidate late).
    if bin_residual == bin_capacity {
        score += cap * (1.2 - 0.4 * progress) + open_bins_count as f64 * 1.5;
    } else {
        // Slight bonus for using existing bins as open bin count grows
        score -= (open_bins_count as f64).ln().max(0.0) * 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: residual classes mod 10.
    // Leftovers that are "harmonic" (multiples of 10, or large enough to be
    // reusable) are less penalized than awkward dead space (1..9 mod 10).
    let pr = post_residual;
    let class = pr % 10;
    if pr > 0 {
        // Awkward tiny dead space (1..=9) is nearly useless: heavy penalty.
        if class >= 1 && pr < 10 {
            score += 12.0;
        }
        // Perfectly harmonic leftovers (mod 10 == 0) get a bonus.
        if class == 0 {
            score -= 6.0;
        }
        // Half-class (residual ~50): very reusable, mild bonus.
        if (pr as i32 - 50).abs() <= 5 {
            score -= 3.0;
        }
    } else {
        // Perfect fill: strongest reward.
        score -= 15.0;
    }

    // Integer-division thresholds: how many "typical" items (size ~20) still fit.
    let fits20 = pr / 20;
    score -= fits20 as f64 * 2.5;

    // Coupling with the lookahead item: reward leftovers that can host the next item.
    if next_item_size > 0 && pr >= next_item_size {
        score -= 4.0;
        // Extra reward if leftover after next item would again be harmonic.
        let pr2 = pr - next_item_size;
        if pr2 % 10 == 0 {
            score -= 3.0;
        }
    } else if next_item_size > 0 && next_item_size > pr {
        // Bin cannot host the next item: slight penalty unless it's a tight fit now.
        score += 1.5;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate (empty bin): penalize mildly so we only open a new bin
    // when open bins would create bad dead space; scale with stream progress
    // (early on, opening bins is cheaper; late, consolidate).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 + 10.0 * progress;
        // But if current item is huge relative to mean residual space, new bin ok.
        if mean_residual > 0.0 && (item_size as f64) > mean_residual {
            score -= 6.0;
        }
    }

    // Prefer filling bins that are already mostly full (small residual relative
    // to capacity) to keep the set of open bins "clean".
    let fill_frac = (bin_capacity - bin_residual) as f64 / cap;
    score -= 5.0 * fill_frac;

    // Mild penalty for scattering across many open bins when mean residual is high.
    if open_bins_count > 3 && mean_residual > 30.0 {
        score += 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (min size 1,
    // but practically tiny gaps) are unusable dead space -> heavy penalty.
    if post_residual < 10 {
        score += 60.0; // gap unusable for realistic items
    } else if post_residual < 20 {
        score += 25.0; // barely usable, risky dead space
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Tightness bonus: fit quality relative to residual before placement.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * tightness;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading to new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = open_bins_count as f64 * (0.4 + 0.6 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open.
        score += 30.0 + 3.0 * pressure;
        // But if no open bin fits well (large post_residual everywhere implied
        // by mean residual being small vs item), soften the penalty.
        if mean_residual < item_size as f64 * 0.5 {
            score -= 20.0;
        }
    } else {
        // Mild reward for consolidating into already-open bins.
        score -= 2.0 * pressure.min(15.0);
    }

    // Lookahead: if the next item fits exactly into the post-residual,
    // this placement is especially valuable.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_tightness = next_item_size as f64 / post_residual as f64;
        if next_tightness > 0.85 {
            score -= 25.0;
        } else {
            score -= 8.0 * next_tightness;
        }
    } else if next_item_size > post_residual && post_residual < 10 {
        // Next item cannot use the tiny dead space we would create.
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward exact match of post_residual with next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        let lookahead_reward = 60.0 * (-diff / 12.0).exp();
        score -= lookahead_reward;

        // Penalize residuals too small for the next item (dead space risk).
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
    }

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: penalize slightly so it's chosen only when open bins are poor fits,
    // but relax as stream progresses and open bins accumulate.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 - 20.0 * progress - 0.5 * open_bins_count as f64;
    }

    // Favor bins tighter than the mean (fragmented bins get filled first).
    score -= (mean_residual - post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progression of the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // ---- Lookahead coupling: penalize residuals that cannot host the next item ----
    if next_item_size > 0 {
        if next_item_size > post_residual {
            // Dead space with respect to lookahead: penalize proportionally to how far off it is
            let waste = (next_item_size - post_residual) as f64;
            score += 0.35 * waste;
        } else {
            // Residual is usable by the next item: reward tighter usable fits
            let slack = (post_residual - next_item_size) as f64;
            score -= 0.20 * (bin_capacity as f64 - slack).max(0.0) / bin_capacity as f64;
        }
    }

    // ---- Tight-fit reward: small post_residual is generally good ----
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 0.5 * tightness * tightness * (bin_capacity as f64);

    // ---- Last-chance bin: if this is the only bin that fits, strongly favor using it ----
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // ---- New-bin candidate handling (bin_residual == bin_capacity) ----
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            // No open bin can fit: opening a new bin is the right move
            score -= 100.0;
        } else {
            // Opening a new bin when alternatives exist: penalize, but less if
            // the item fits very poorly everywhere (large item) or we are early
            // in the stream with few open bins.
            let poor_fit = (item_size as f64 / bin_capacity as f64) < 0.5;
            let early = progress < 0.25;
            let penalty = if poor_fit && early { 5.0 } else { 40.0 };
            score += penalty;
        }
    }

    // ---- Global state: many open bins with high mean residual -> prefer consolidation ----
    if open_bins_count > 1 && mean_residual > 0.0 {
        // If this bin's residual is below the mean, it is a good consolidator
        let diff = mean_residual - post_residual as f64;
        score -= 0.10 * diff;
        // Mild pressure to close out bins when many are open
        score += 0.02 * (open_bins_count as f64 - 1.0);
    }

    // ---- Time horizon: late in the stream, avoid leaving tiny unusable fragments ----
    if progress > 0.75 {
        let fragment = (post_residual as f64 / bin_capacity as f64) * (post_residual as f64 / bin_capacity as f64);
        score += 10.0 * fragment * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Normalized post-residual (fraction of capacity left over)
    let pr_norm = post_residual as f64 / bin_capacity as f64;

    // Non-linear polynomial coupling: waste that is small is heavily rewarded,
    // large waste is progressively penalized more than linearly.
    score += 40.0 * pr_norm * pr_norm * (1.0 + 2.0 * progress);

    // Reward tight fits (post_residual near zero) with a smooth saturating term.
    score -= 30.0 * (-(post_residual as f64) / 12.0).exp();

    // Lookahead coupling: if the next item could use the post-residual, reward it smoothly.
    if next_item_size > 0 {
        let slack_gap = post_residual as f64 - next_item_size as f64;
        if slack_gap >= 0.0 {
            let fit_quality = 1.0 - slack_gap / bin_capacity as f64;
            score -= 25.0 * fit_quality * fit_quality;
        } else {
            // Post-residual too small for next item: mild smooth penalty scaled by progress.
            score += 10.0 * progress * (1.0 - (-(-slack_gap) / 40.0).exp());
        }
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Many open bins: penalize spreading residual capacity thinly (encourage consolidation).
    let open_norm = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    score += 8.0 * open_norm * (post_residual as f64 / bin_capacity as f64);

    // Mean-residual coupling: prefer bins whose residual deviates smoothly from the mean
    // (favor bins with more room when the mean is large, i.e. avoid fragmenting big spaces).
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score -= 6.0 * dev * (1.0 - progress);

    // New-bin candidate: make opening a new bin attractive only when fits are poor.
    if bin_residual == bin_capacity {
        score = 60.0 + 20.0 * (1.0 - progress) - 15.0 * (1.0 - pr_norm);
        // If the only fitting option is bad (large post residual), new bin wins.
        if post_residual as f64 > 0.35 * bin_capacity as f64 {
            score -= 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual classes mod capacity fractions
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let class_small = post_residual % 10;          // fine-grained harmonic class
    let class_quarter = post_residual % 25;        // quarter-capacity class
    let class_half = post_residual % 50;           // half-capacity class

    // Reward residuals that are "useful" multiples of common item granularities
    if class_small == 0 { score -= 8.0; }
    if class_quarter == 0 { score -= 6.0; }
    if class_half == 0 { score -= 4.0; }

    // Penalize awkward dead space: residual just above typical item sizes
    let awkward = |r: u32| -> f64 {
        let thresholds = [10u32, 20, 25, 30, 40, 50, 60, 70, 80];
        let mut pen = 0.0;
        for t in thresholds {
            if r > t && r < t + 5 { pen += 2.5; }
        }
        pen
    };
    score += awkward(post_residual);

    // Lookahead coupling: reward if next item fits perfectly in post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 15.0;
        } else if next_item_size < post_residual {
            let nxt_res = post_residual - next_item_size;
            score += 0.35 * (nxt_res as f64);
            score += awkward(nxt_res);
        } else {
            // next item cannot follow here: mild penalty proportional to overshoot
            score += 0.15 * ((next_item_size - post_residual) as f64);
        }
    } else {
        // last item: waste everything anyway, prefer tightest fit
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 12.0 + 0.1 * (item_size as f64);
    }

    // New-bin candidate: neutral-ish score tied to mean residual pressure
    if bin_residual == bin_capacity {
        // open a new bin when existing bins are tight or item is large
        let pressure = (mean_residual / c).max(0.0);
        score = 0.5 * c + 20.0 * pressure + (item_size as f64) * 0.3;
        if fitting_bins_count == 0 { score -= 30.0; }
    }

    // Late-stream consolidation: prefer filling existing bins as stream ends
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 6.0 * progress * (1.0 - pr / c);

    // Slight bias toward bins whose residual is close to mean (balance)
    score += 0.05 * ((pr - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize residuals that are too small
    // to hold any plausible future item (unusable gap).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
