    // Lookahead: if next item fits in the post-residual, reward leaving room.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
            // Bonus if next item exactly consumes the leftover.
            if next_item_size == post_residual {
                score -= 15.0;
            }
        } else {
            // Penalize leaving a residual that just barely fails the next item.
            let miss = next_item_size - post_residual;
            if miss <= 10 {
                score += 8.0 + miss as f64;
            }
        }
    }

    // Global state coupling: prefer filling bins when mean residual is high
    // (many open bins with slack -> consolidate).
    let mean_norm = mean_residual / bin_capacity as f64;
