    // Too many open bins: pressure to consolidate into existing bins.
    let open_pressure = open_bins_count as f64 / (total_items.max(1) as f64).sqrt();
    if bin_residual != bin_capacity {
        score -= 5.0 * open_pressure.min(3.0);
    }

    // Time horizon: early in stream, keep bins flexible (avoid tiny residuals);
    // late in stream, prioritize closing bins out.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 8.0 * (1.0 - t) * (post_residual as f64 / bin_capacity as f64);
    score -= 10.0 * t * fit_ratio;

    // New-bin candidate: default mild penalty so we only open when existing bins fit poorly.
    if bin_residual == bin_capacity {
        score += 14.0;
        // Opening a new bin is attractive if the item is huge and would leave
        // existing bins with unusable slivers, or if few bins fit at all.
        if item_size >= 60 {
            score -= 10.0;
        }
        if fitting_bins_count <= 1 {
            score -= 12.0;
        }
        // Late in stream, prefer packing into existing bins.
        score += 10.0 * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let t = step_index as f64 / total_items.max(1) as f64;
    let r = pr / cap;

    // Base: prefer tight fits (low post_residual), with a convex penalty
    // on large residuals that grows as the stream progresses.
    let mut score = pr as f64;
    let progress = t * t * (3.0 - 2.0 * t); // smoothstep-style coupling
    score += 60.0 * progress * r * r * cap;

    // Reward filling a bin nearly completely (dead-space avoidance).
    score -= 25.0 * (1.0 - r) * (1.0 - r) * (1.0 - progress);

    // Last-chance bin: strongly reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0 + 30.0 * progress;
    }

    // Lookahead: reward leaving a residual that can still host the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr as u32 >= next_item_size {
            score -= 15.0 * (nxt / cap) * (1.0 - progress);
        } else {
            score += 10.0 * (nxt / cap) * progress;
        }
    }

    // Mean-residual coupling: penalize bins far from the fleet mean
    // (keeps residual distribution tight and predictable).
    score += 0.5 * (pr - mean_residual).abs();

    // New-bin candidate: mild penalty so it is only chosen when open bins fit badly.
    if bin_residual == bin_capacity {
        score += 20.0 + 60.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space in small residues is more wasteful.
    let pr = post_residual;
    if pr > 0 {
        // classify residue into harmonic buckets (mod arithmetic on capacity fractions)
        let class = pr / 10; // 0..10 classes
        let class_penalty: f64 = match class {
            0 => 0.0,                 // perfect fit
            1 => 6.0,                 // 1..9 dead space: very hard to fill
            2 => 9.0,
            3 => 4.0,                 // ~20-30 can host small items
            4 => 1.0,
            5 => 0.5,
            6 => 1.5,
            7 => 3.0,
            8 => 5.0,
            9 => 7.0,                 // 90-99 nearly empty bin
            _ => 8.0,
        };
        score += class_penalty;

        // Integer-division threshold: residue divisible into common item sizes is reusable
        let reusable = (10 <= pr && pr % 10 == 0) || pr % 20 == 0 || pr % 25 == 0;
        if reusable { score -= 4.0; }

        // Non-linear coupling: penalty grows quadratically for tiny residues
        if pr < 10 {
            score += (10 - pr) as f64 * (10 - pr) as f64 * 0.15;
        }
    } else {
        score -= 12.0; // perfect fill, strongly reward
    }

    // Lookahead: reward if next item fits into the post residual
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 8.0;
            // extra reward for exact modular match with next item
            if pr % next_item_size.max(1) == 0 { score -= 3.0; }
        } else {
            score += 2.0;
        }
    }

    // Last chance: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Prefer fuller bins relative to mean residual across open bins
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Progress pressure: as stream advances, be more conservative with new bins
    let progress = step_index as f64 / (total_items.max(1) as f64);

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        // opening a new bin: baseline cost; cheaper early, more expensive later
        score = 55.0 + 30.0 * progress;
        if next_item_size > 0 && next_item_size <= pr {
            score -= 5.0;
        }
        // if few bins open and item is large, opening is natural
        if open_bins_count <= 2 { score -= 10.0; }
    } else {
        // reusing an open bin gets a flat advantage scaled by open bin count
        score -= (open_bins_count.min(20) as f64) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual >= 10 {
        // Usable residual: mild reward scaled by how much room remains for future items.
        score -= (post_residual as f64 / bin_capacity as f64) * 8.0;
    }

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Lookahead coupling: reward if the next item fits the post residual.
    if next_item_size > 0 {
        if (post_residual as f64) >= next_item_size as f64 {
            score -= 15.0;
        } else if post_residual > 0 {
            // Next item won't fit here; penalize leaving a gap that's neither 0 nor useful.
            score += 10.0;
        }
    }

    // Open-bin pressure: discourage spreading across many bins unless the fit is good.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.8 + 0.6 * progress);

    // Penalize bins whose residual is far from the mean (fragmentation pressure).
    score += ((post_residual as f64 - mean_residual) / (mean_residual + 1.0)).abs() * 3.0;

    // New-bin candidate: neutral baseline; only chosen if open bins score worse.
    if bin_residual == bin_capacity {
        score += 25.0 + open_bins_count as f64 * 2.0;
        // Prefer opening a new bin late in the stream when bins are crowded.
        if open_bins_count > 8 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Strongly reward near-perfect fills (small dead space is exponentially bad).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 15 {
        score -= 10.0;
    }

    // Aggressive 2-step lookahead: reward when the leftover residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Best when next item fits snugly; penalize loose fits quadratically.
            score -= 25.0 - 0.15 * slack;
            if slack <= 5.0 {
                score -= 20.0; // chain-friendly snug fit
            }
        } else {
            // Leftover is dead space relative to the next item: penalize proportionally.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.35 * gap + 8.0;
        }
    }

    // Coupling with mean residual: prefer bins whose residual deviates favorably.
    let dev = post_residual as f64 - mean_residual;
    score += 0.12 * dev; // prefer emptier-than-average bins (larger residual) slightly less

    // Last-chance bin: if this is the only fitting bin, avoid forcing a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0 + 10.0 * progress;
    }

    // As stream progresses, prefer consolidating into open bins rather than opening new ones.
    score += (open_bins_count as f64).sqrt() * 2.0 * (1.0 - progress);

    // New-bin candidate handling: opening a new bin is attractive only for large items
    // or when the stream is early.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        let new_bin_cost = 100.0 - 40.0 * large_item - 30.0 * (1.0 - progress);
        // Reserve: if next item is small and would nest in leftover, discourage new bin.
        let nest_bonus = if next_item_size > 0 && next_item_size <= post_residual { 15.0 } else { 0.0 };
        score += new_bin_cost + nest_bonus;
        // If no open bin truly fits well (this is a fallback call), soften the cost.
        if fitting_bins_count == 0 {
            score -= 45.0;
        }
    }

    // Mild penalty for wasteful placements of tiny items into huge residuals early on.
    if item_size <= 20 && post_residual >= 60 {
        score += 6.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward near-zero post residual.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that cannot hold even the smallest item (1).
    if post_residual < 1 {
        score -= 10.0; // perfect fill bonus
    } else if post_residual < 10 {
        score -= 5.0; // nearly dead space is actually good (small waste)
    } else {
        // Penalize residuals that are large but awkward relative to mean residual.
        let awkward = (post_residual as f64 - mean_residual).abs();
        score += 0.15 * awkward;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: default moderate cost; cheaper only when no open bin fits well
    // or the item is huge and lookahead suggests another large item.
    if bin_residual == bin_capacity {
        let mut open_cost = 40.0;
        if item_size > 70 {
            open_cost -= 10.0;
        }
        if next_item_size > 0 && next_item_size >= item_size {
            // Next item is large too: opening a fresh bin preserves room for it.
            open_cost -= 8.0;
        }
        if open_bins_count == 0 {
            open_cost = -100.0; // must open
        }
        score = open_cost + post_residual as f64;
    } else {
        // Favor fuller bins slightly more as the stream progresses (finite horizon).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * progress * tightness;

        // Lookahead: if next item fits exactly in the post residual, big reward.
        if next_item_size > 0 && next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size > 0 && next_item_size <= post_residual {
            score -= 4.0;
        } else if next_item_size > post_residual {
            // Next item won't fit here anyway; slightly prefer bins whose waste is small.
            score += 0.05 * post_residual as f64;
        }

        // Mild penalty when many bins are open and this bin is nearly empty (spread too thin).
        if post_residual as f64 > mean_residual * 1.5 && open_bins_count > 3 {
            score += 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Tight-fit reward: strongly favor small post_residual (non-linear).
    score -= 60.0 * (1.0 - pr / cap).powi(4);

    // Penalize dead space that is too small for typical future items.
    if pr > 0.0 {
        let dead = (pr / cap).powi(2);
        score += 25.0 * dead * (1.0 - progress);
    }

    // Coupling with mean residual: prefer bins whose residual deviates favorably.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score -= 12.0 * dev * (1.0 - progress);

    // Lookahead: reward leaving room for the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr as f64 >= nxt {
            score -= 18.0 * (1.0 - (pr as f64 - nxt) / cap);
        } else {
            score += 15.0;
        }
    }

    // Last-chance bin: strong bonus to use it rather than open a new one.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin, more so late in stream,
    // unless item is large relative to capacity (fewer future chances to use it).
    if bin_residual == bin_capacity {
        let large = item_size as f64 / cap;
        score += 40.0 * (1.0 - progress) + 20.0 * (1.0 - large);
    }

    // Mild preference to fill bins with larger residual early (keeps tight bins free).
    score += 8.0 * (bin_residual as f64 / cap) * (1.0 - progress);

    // Open-bins pressure: discourage spreading across many bins.
    score += 2.0 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: residuals divisible by common item sizes
    // (10, 20, 25, 50) are more reusable than odd residuals.
    let harmony: u32 = if post_residual == 0 { 0 }
        else if post_residual % 50 == 0 { 1 }
        else if post_residual % 25 == 0 { 2 }
        else if post_residual % 20 == 0 { 3 }
        else if post_residual % 10 == 0 { 4 }
        else { 5 };
    score -= (5 - harmony.min(5)) as f64 * 12.0;

    // Penalize small dead space that nothing (min size 10) can use
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Fractional capacity coupling: how full the bin becomes
    let fill_frac = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= fill_frac * fill_frac * 25.0;

    // Lookahead: does next item fit the resulting residual?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
            // exact chain fit
            if post_residual == next_item_size {
                score -= 40.0;
            }
        } else {
            score += 10.0;
        }
    }

    // Last chance: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: only attractive when current bins are crowded
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        // penalize opening new bin when existing bins have room
        score += 40.0 + pressure * 100.0;
        // but if many bins and residuals are tiny, opening is fine
        if mean_residual < 15.0 {
            score -= 55.0;
        }
    }

    // Mild penalty for accumulating too many open bins early
    let progress = step_index as f64 / total_items.max(1) as f64;
    if open_bins_count as f64 > 4.0 + progress * 10.0 {
        score += 8.0;
    }

    // Tie-breaker: prefer bins with larger residual (less fragmented)
    score += bin_residual as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // plausible future item (min size 1, but practically tiny gaps) are dead.
    // Penalize gaps in [1, 12] heavily (unusable), mildly reward large gaps.
    let pr = post_residual as f64;
    if post_residual == 0 {
        score -= 50.0; // perfect fit, ideal
    } else if post_residual < 12 {
        // dead space: gap too small to be useful
        score += (12 - post_residual) as f64 * 6.0;
    } else {
        // usable residual: reward, but with diminishing returns
        score -= ((post_residual as f64).sqrt()) * 3.0;
    }

    // Coupling: penalize residual that cannot fit the lookahead item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 8.0; // bin remains useful for next item
        } else {
            score += (nxt - pr) * 0.8; // dead for lookahead
        }
    }

    // Open-bin pressure: with many open bins, prefer compacting into
    // existing ones; opening new bins is cheap when few are open.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * 4.0;

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive if current fit is poor
    // (large post_residual waste) relative to mean residual.
    if bin_residual == bin_capacity {
        let waste_vs_mean = pr - mean_residual;
        score += waste_vs_mean * 1.5 + 10.0;
        // late in stream, prefer consolidation into open bins
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward a perfect chain fit
    // where post_residual exactly matches the next item's size.
    if next_item_size > 0 {
        let chain = post_residual as i64 - next_item_size as i64;
        let chain_abs = chain.abs() as f64;
        // Perfect chain fit gets a big bonus; near fits decay quadratically.
        score -= 60.0 * (-chain_abs / 12.0).exp();
        // If the next item cannot fit anywhere else in this bin's residual,
        // and this bin is the only fitting bin, prefer keeping residual small.
        if (post_residual as i64) < (next_item_size as i64) {
            score += 8.0; // dead space for the lookahead item
        }
    } else {
        // Last item: minimize waste exactly.
        score -= 40.0 * (-(bin_residual - item_size) as f64 / 10.0).exp();
    }

    // Relative-to-mean residual shaping: bins whose residual deviates strongly
    // from the mean residual are less flexible targets.
    let dev = post_residual as f64 - mean_residual;
    score += 0.15 * dev * dev / (mean_residual + 1.0);

    // Last-chance bin: if this is the only bin that fits, avoid opening a new
    // bin unless the fit is terrible (huge dead space).
    if fitting_bins_count == 1 && post_residual > 0 {
        score -= 15.0;
        // Penalize only very large leftovers harder in this case.
        if post_residual > bin_capacity / 2 {
            score += 12.0;
        }
    }

    // Early in the stream, be more willing to open fresh bins (better structure later).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive when fit is good (small post_residual
        // relative to mean residual), unattractive when open bins fit well.
        score = post_residual as f64 - 10.0 * (1.0 - progress);
        if post_residual as f64 > mean_residual {
            score += 6.0;
        }
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Slight preference for tighter bins as stream progresses.
    score -= (1.0 - progress) * 2.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins whose post_residual is small.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Lookahead: if the next item can fit into post_residual, reward this bin
    // (it enables a chained placement). Scale reward by how snugly next item fits.
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain_slack = (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 12.0 * (1.0 - chain_slack);
    } else if next_item_size > post_residual {
        // Dead space risk: leftover space too small for the next item.
        let dead = (post_residual as f64) / (next_item_size as f64);
        if post_residual > 0 {
            score += 6.0 / (1.0 + dead);
        }
    }

    // Last-chance bin: if this is the only open bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New empty bin candidate: penalize when open bins can already fit the item,
    // unless the fit is terrible (post_residual large relative to mean residual).
    if bin_residual == bin_capacity && open_bins_count > 0 {
        let poor_fit = (post_residual as f64) > mean_residual;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Early in the stream, opening bins is cheaper; late, prefer filling.
        let open_bias = 10.0 * (1.0 - progress);
        if poor_fit {
            score -= open_bias + 4.0;
        } else {
            score += 20.0 - open_bias;
        }
    }

    // Prefer bins with residuals close to the current bin's residual (balance).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Slight preference for already-open bins vs. creating fragmentation.
    if bin_residual < bin_capacity {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let post_norm = post / cap;
    let fill = 1.0 - post_norm;

    let mut score = post;

    // Smooth non-linear coupling of post_residual with stream progress:
    // late in the stream, prefer tighter fits more aggressively.
    let tightness = post_norm * post_norm * (1.0 - post_norm);
    score += 40.0 * tightness * (0.5 + progress);

    // Reward high fill ratio quadratically, amplified by progress.
    score -= 30.0 * fill * fill * (0.3 + 0.7 * progress);

    // Penalize dead space that next item cannot use (smooth interaction).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let unusable = (post - nxt).max(0.0) / cap;
        score += 25.0 * unusable * unusable;
        // Reward leaving exactly a usable gap for the lookahead item.
        let gap_match = 1.0 - ((post - nxt).abs() / cap);
        score -= 15.0 * gap_match * gap_match;
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0 * fill;
    }

    // Many open bins: prefer consolidating into existing bins.
    let pressure = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    score += 10.0 * pressure * post_norm;

    // Prefer bins whose residual is near the mean residual (balanced packing).
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += 8.0 * dev * dev;

    // New-bin candidate: keep it neutral-ish but slightly penalized so it only
    // wins when existing fits are poor (high post_residual elsewhere).
    if bin_residual == bin_capacity {
        score = post + 12.0 + 8.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover is a "dead zone"
    // (too small to ever hold typical items) are good targets; leftovers that
    // remain usable should be penalized slightly so we don't waste them.
    let dead_threshold = bin_capacity / 10; // 10 units
    if post_residual < dead_threshold {
        // Perfect or near-perfect fit: strongly reward.
        score -= 40.0 * (1.0 - post_residual as f64 / dead_threshold as f64);
    } else {
        // Usable leftover: penalize proportionally, but reward if the lookahead
        // item can exactly fill the remaining space.
        score += 8.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big bonus.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 60.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Next item fits: mildly reward, scaled by how much slack remains.
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > post_residual {
        // Next item cannot use this leftover: penalize leftover size.
        score += post_residual as f64 * 0.15;
    }

    // Integer-division class of item_size (harmonic bins of capacity fractions).
    let item_class = item_size / (bin_capacity / 4); // 0..=3
    match item_class {
        0 => score -= 5.0,  // tiny item: cheap to place anywhere
        1 => score -= 2.0,
        2 => score += 0.0,
        _ => score += 5.0,  // huge item: prefer tightest bin, score already low via post_residual
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 30.0;
        // Late in the stream, opening fresh bins is cheaper (less fragmentation risk).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * progress;
        // If many bins are open and mean residual is high, prefer reusing.
        score += (open_bins_count as f64).min(10.0) * 1.5;
        score += (mean_residual / bin_capacity as f64) * 20.0;
    }

    // Tie-break toward bins tighter than average (best-fit flavor).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual > 0 && post_residual < 20 {
        score += 18.0;
    } else if post_residual == 0 {
        // Perfect fit reward
        score -= 30.0;
    }

    // Reward tight fits (item fills most of the bin's residual)
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fill_ratio;

