    score += 0.35 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: if next item fits exactly into post_residual, reward this placement
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // partial reward if next item can still fit
        score -= 6.0;
    } else if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
        // penalize leaving gaps the next item cannot use
        score += 8.0;
    }

    // Deviation from mean residual: prefer bins whose residual is close to mean
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Slight early-stream aggression: pack tighter early when many bins remain
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 3.0 * (1.0 - progress);

    // New-bin candidate: penalize slightly so it's chosen only when fits are poor
    if bin_residual == bin_capacity {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are excellent: reward small post_residual strongly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // 2-step lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size < post_residual {
            // Reward proportional to how well next item fills the remainder.
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 25.0 * fill;
        } else {
            // Next item cannot use this leftover; penalize dead space relative to next size.
            let waste = post_residual as f64 / (next_item_size as f64).max(1.0);
            score += 15.0 * waste.min(1.0);
        }
    }

    // Compare post_residual to mean residual across open bins: leaving a residual
    // far below the mean is good (bin nearly closed); far above mean is wasteful.
    if mean_residual > 0.0 {
        let rel = post_residual as f64 / mean_residual;
        score += 8.0 * (rel - 1.0).clamp(-1.0, 1.0);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize opening a new bin when good fitting bins exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = open_bins_count as f64 / (total_items.max(1) as f64);
        // New bin cost grows with stream progress and existing bin count.
        score += 20.0 + 15.0 * progress + 10.0 * pressure;
        // But if the item is large and would leave a tiny residual in any bin,
        // a fresh bin is still penalized less than extreme fragmentation.
        if item_size >= bin_capacity * 3 / 4 {
            score -= 12.0;
        }
    }

    // Mild bonus for closing bins early as stream progresses.
    if post_residual < 10 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins whose residual is nearly consumed.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that no plausible future item can use.
    if post_residual > 0 {
        let max_future = if next_item_size > 0 { next_item_size as f64 } else { 10.0 };
        if (post_residual as f64) < max_future {
            score -= 12.0; // residual is small enough to be reusable soon
        } else {
            score += 0.15 * (post_residual as f64 - mean_residual).abs();
        }
    }

    // Lookahead: reward leaving exactly the space the next item needs.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs();
        if gap == 0 {
            score -= 25.0; // perfect chain placement
        } else {
            score += 0.08 * gap as f64;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate logic: only attractive when current bins fit poorly.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let phase = step_index as f64 / (total_items.max(1) as f64);
        score = 200.0 - 60.0 * pressure - 20.0 * (1.0 - phase);
        if mean_residual > item_size as f64 * 1.5 {
            score += 30.0; // plenty of slack elsewhere; don't open new bins
        }
    }

    // Mild global balance: prefer bins below mean residual to keep options open.
    if bin_residual != bin_capacity {
        score += 0.05 * (bin_residual as f64 - mean_residual);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_post = post_residual as f64 / bin_capacity as f64;
    let norm_item = item_size as f64 / bin_capacity as f64;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, prefer tight fills less aggressively; later, strongly punish waste.
    let progress_coupling = progress * progress * (1.0 - progress);
    score += 40.0 * progress_coupling * norm_post * norm_post;

    // Non-linear dead-space penalty: quadratic in post_residual, scaled by item size.
    score += 0.02 * norm_post * norm_post * (1.0 + norm_item);

    // Reward near-perfect fits smoothly.
    score -= 12.0 * (1.0 - norm_post) * (1.0 - norm_post) * (1.0 - progress);

    // Last-chance bin: strong smooth reward to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 + progress);
    }

    // Lookahead: penalize leaving a residual that barely fits the next item badly.
    if next_item_size > 0 {
        let next_norm = next_item_size as f64 / bin_capacity as f64;
        let gap = (post_residual as f64 - next_item_size as f64).abs() / bin_capacity as f64;
        score += 5.0 * gap * (1.0 - next_norm) * (0.5 + progress);
        // Smooth reward if next item fits exactly-ish.
        if next_item_size <= post_residual {
            score -= 6.0 * (1.0 - gap) * next_norm;
        }
    }

    // Mild coupling with mean residual: prefer bins below mean residual (tighter bins).
    let mean_norm = mean_residual / bin_capacity as f64;
    score += 2.0 * (norm_post - mean_norm) * (0.5 + progress);

    // Slight penalty for opening new bins when many are open.
    if bin_residual == bin_capacity {
        score += 1.5 + 0.05 * open_bins_count as f64 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: capacity fraction classes (1/3, 1/2, 2/3 thresholds)
    let cap = bin_capacity as f64;
    let item_frac = item_size as f64 / cap;

    // Reward tight fits (small post_residual)
    score -= 12.0 * (1.0 - post_residual as f64 / cap).powi(3);

    // Perfect fit is heavily rewarded
    if post_residual == 0 {
        score -= 60.0;
    }

    // Harmonic class logic: dead space is worse if it falls into a "useless" class.
    // Classify post_residual by integer division into capacity-fraction bands.
    let pr = post_residual;
    if pr > 0 {
        // Residual in (0,10] is nearly unusable dead space -> penalize
        if pr <= 10 {
            score += 18.0;
        }
        // Residual in (10, 33]: can host small items only; mild penalty unless next item fits
        else if pr <= 33 {
            if next_item_size > pr {
                score += 8.0;
            } else {
                score -= 10.0;
            }
        }
        // Residual in (33, 50]: half-bin class
        else if pr <= 50 {
            if next_item_size > pr {
                score += 6.0;
            } else {
                score -= 14.0;
            }
        }
        // Large residual: generally good, reward
        else {
            score -= 6.0;
        }
    }

    // Modulo arithmetic on post_residual: residuals that are multiples of common
    // item-size granules (e.g. multiples of 10 or 25) are more reusable.
    if pr > 0 && (pr % 10 == 0 || pr % 25 == 0) {
        score -= 5.0;
    }

    // Next-item coupling: reward if next item exactly fits post_residual (harmonic pairing)
    if next_item_size > 0 && next_item_size == pr {
        score -= 40.0;
    } else if next_item_size > 0 && next_item_size <= pr {
        // fraction of next item covered by this residual
        score -= 8.0 * (next_item_size as f64 / pr as f64);
    } else if next_item_size > pr {
        // next item cannot follow here; penalize proportionally to wasted pairing
        score += 4.0 * ((next_item_size - pr) as f64 / cap);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // relative to capacity or bin pool is crowded.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let open_pressure = (open_bins_count as f64) / (1.0 + mean_residual / cap);
        let base = 30.0 + 20.0 * item_frac + 10.0 * progress;
        // Prefer new bin for big items or when existing bins are badly fragmented
        score = base - 10.0 * (mean_residual / cap - item_frac).max(0.0) + 5.0 * open_pressure.min(3.0);
    }

    // Progress-dependent tightness pressure: late in the stream, prefer tighter packing
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * progress * (1.0 - post_residual as f64 / cap);

    // Mean-residual alignment: prefer bins whose residual is close to item needs
    score += 0.05 * ((bin_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
