        score += 20.0; // leftover likely dead for next item
    }

    // Last-chance bin: only fitting bin -> encourage using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin fit is bad
    if bin_residual == bin_capacity {
        score += 60.0 + 0.5 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= 50 {
            score += 30.0; // big next item: keep residuals large
        }
    }

    // Mean residual alignment: prefer bins whose residual is near mean (balanced packing)
    score += 0.3 * ((pr - mean_residual).abs());

    // Late-stream consolidation: as stream progresses, prefer filling existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress * (1.0 - frac);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tight fit reward: fill ratio of the bin by this item.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 6.0 * fill;

    // Strict dead-space avoidance: gaps that cannot fit the next item
    // (or are tiny slivers) are heavily penalized.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Dead space relative to lookahead item.
            score += 2.5 * (next_item_size - post_residual) as f64;
        }
        // If this placement leaves a gap that exactly fits the next item, reward strongly.
        if post_residual == next_item_size {
            score -= 8.0;
        }
    }
    // Absolute unusable sliver penalty (gap too small for the smallest plausible item).
    if post_residual < 10 {
        score += 12.0 * (10 - post_residual) as f64;
    }

    // Last-chance bonus: if this is the only bin that fits, prefer using it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones;
    // when few are open, a new bin is cheaper.
    let new_bin_candidate = bin_residual == bin_capacity;
    if new_bin_candidate {
        score += 3.0 * open_bins_count as f64 + 10.0 * progress;
        // But if the item fits nowhere tightly (bad fits elsewhere), allow new bin.
        if post_residual == 0 && open_bins_count > 0 {
            score -= 4.0;
        }
    } else {
        // Reward using existing bins when open-bin count is high.
        score -= 1.5 * open_bins_count as f64;
    }

    // Prefer bins whose residual deviates below the mean (more committed bins).
    let dev = mean_residual - bin_residual as f64;
    score += 0.05 * dev;

    // Slight preference for keeping near-full bins busy.
    let res_frac = bin_residual as f64 / bin_capacity as f64;
    score += 2.0 * res_frac * res_frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward perfect match of post_residual with next item.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let diff = (post_residual as f64 - next).abs();
        score -= 25.0 * (1.0 - diff / bin_capacity as f64).max(0.0);
        if post_residual as u32 == next_item_size {
            score -= 60.0; // exact 2-step fit: chain perfectly
        } else if post_residual < next_item_size {
            // dead space relative to lookahead item
            score += 0.35 * (next - post_residual as f64);
        }
    } else {
        // last item: prefer tightest fill
        score -= 40.0;
    }

    // Compare post_residual against mean residual across open bins:
    // leaving much more than average wastes capacity.
    if post_residual as f64 > mean_residual {
        score += 0.25 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.15 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: only attractive when it beats wasting space in a nearly-full bin.
    if bin_residual == bin_capacity {
        let waste_penalty = 0.5 * (mean_residual - item_size as f64).max(0.0);
        score += 30.0 + waste_penalty;
        if fitting_bins_count == 0 || (next_item_size > 0 && bin_residual < next_item_size) {
            score -= 35.0;
        }
    }

    // Slight pressure to consolidate into fewer bins early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the space.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    if fill_ratio > 0.85 {
        score -= 30.0 * fill_ratio;
    } else if fill_ratio > 0.6 {
        score -= 12.0 * fill_ratio;
    }

    // Penalize tiny dead space only if it's truly unusable later; otherwise
    // moderate residuals are fine, so apply a quadratic penalty on small leftovers.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // dead space trap
    }

    // Lookahead: if the next item fits exactly into post_residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            let next_fill = next_item_size as f64 / post_residual as f64;
            if next_fill > 0.7 {
                score -= 10.0 * next_fill;
            } else {
                score += 5.0 * (1.0 - next_fill);
            }
        } else {
            // Next item won't fit here; mild penalty for leaving a large gap.
            score += 3.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: only open a new bin when the current fit is bad
    // or no open bin fits well.
    if bin_residual == bin_capacity {
        if item_size > 50 {
            score -= 5.0; // large items are fine in fresh bins
        } else {
            score += 20.0 + mean_residual * 0.3; // discourage wasting fresh bins
        }
        // Late in the stream, prefer closing out open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * progress;
    }

    // Global pressure: many open bins with high mean residual -> prefer reusing
    // bins with larger residuals to consolidate.
    if open_bins_count > 3 && (bin_residual as f64) > mean_residual {
        score -= 4.0;
    } else if open_bins_count > 3 {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_norm = pr / cap;

    // Smooth non-linear coupling of post_residual with stream progress
    score -= 12.0 * (fit_norm * fit_norm) * (1.0 - progress);
    score -= 6.0 * fit_norm * progress;

    // Reward near-perfect fits smoothly (quartic valley)
    score -= 20.0 * (1.0 - fit_norm) * (1.0 - fit_norm) * (1.0 - fit_norm) * (1.0 - fit_norm);

    // Penalize dead space that cannot fit a plausible next item
    let nx = next_item_size as f64;
    let gap = (nx - pr).max(0.0);
    score += 0.35 * gap * (0.5 + progress);

    // Smooth lookahead synergy: reward residuals close to next item size
    let closeness = 1.0 - ((pr - nx) / cap).abs();
    score -= 8.0 * closeness.max(0.0) * closeness.max(0.0) * (1.0 - progress);

    // Last-chance bin before opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Penalize opening new bins late in the stream
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - progress) - 5.0 * progress;
    }

    // Mild pressure to consolidate when many bins are open
    score -= (open_bins_count as f64).ln().max(0.0) * fit_norm * 2.0;

    // Mean-residual alignment term
    score += 0.05 * (mean_residual - pr).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual modulo 10 (capacity fractions)
    let post_class = post_residual % 10;
    // Harmonic dead-space classes: residuals like 1..9 are hard to fill
    if post_residual > 0 {
        let deadness = match post_class {
            0 => -6.0,                       // perfectly harmonic residual
            5 => -3.0,                       // half-class, still fillable
            1 | 9 => 4.0,                    // near-full waste
            2 | 8 => 2.5,
            3 | 7 => 1.5,
            _ => 0.5,                        // 4 | 6
        };
        score += deadness;
    } else {
        score -= 10.0; // perfect closure: strongly reward exact fit
    }

    // Integer-division thresholds: how many "typical" items (size ~ mean of stream scale)
    // could still fit? Use capacity fraction 1/4 as the quantum.
    let quantum = bin_capacity / 4;
    let fits_left = post_residual / quantum.max(1);
    score -= 3.0 * fits_left as f64;

    // Lookahead coupling: does next item harmonically fit post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits exactly or leaves a harmonic class again
            let nxt_post = post_residual - next_item_size;
            if nxt_post % 10 == 0 { score -= 8.0; } else { score -= 4.0; }
        } else {
            // next item won't fit here: mildly penalize hoarding space
            score += 1.0;
        }
        // exact chain fit: next item exactly fills residual
        if next_item_size == post_residual {
            score -= 12.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Crowding pressure: many open bins -> prefer consolidating into existing bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.4 * open_bins_count as f64 * (0.5 + progress);

    // Mean residual deviation: prefer bins whose residual is near mean (balanced packing)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // New-bin candidate (bin_residual == bin_capacity): only attractive when
    // no open bin is a good fit or item is huge relative to residuals.
    if bin_residual == bin_capacity {
        let good_fit_exists = fitting_bins_count > 0 && (bin_capacity - item_size) as f64 > mean_residual * 0.5;
        if good_fit_exists && next_item_size > 0 && next_item_size <= mean_residual as u32 {
            score += 25.0; // keep using existing bins
        } else {
            score += 2.0;  // mild preference still for existing bins
        }
        // opening a bin early in the stream is cheap
        score -= 5.0 * (1.0 - progress);
    }

    // Tight-fit bonus: item nearly fills the bin (>= 90% utilization)
    let util = item_size as f64 / bin_capacity as f64;
    if util >= 0.9 {
        score -= 7.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual == 0 {
        // Perfect fit is highly rewarded.
        score -= 100.0;
    }

    // Reward tight fits relative to item size.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * tightness;

    // Open-bin pressure: discourage scattering across many bins.
    score += 2.0 * open_bins_count as f64;

    // Pull toward mean residual (balance residual capacities).
    score += 0.3 * ((bin_residual as f64) - mean_residual).abs();

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when no open bin fits well,
    // or the item is large and would leave a bad gap in any open bin.
    if bin_residual == bin_capacity {
        let gap_penalty = if post_residual > 0 && post_residual < 10 { 40.0 } else { 0.0 };
        score += 30.0 + gap_penalty - 0.5 * item_size as f64;
        // With lookahead: opening a fresh bin is fine if next item could use the remainder.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0;
        }
        // Late in the stream, avoid opening unnecessary bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: this bin's post residual exactly fits the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        // Post residual can still host the next item: reward closeness of the leftover chain.
        let chain_waste = (post_residual - next_item_size) as f64;
        score -= 20.0 * (1.0 - chain_waste / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item won't fit here after placement: penalize dead space relative to next item.
        let dead = (next_item_size - post_residual) as f64;
        score += 0.5 * dead.min(bin_capacity as f64);
    }

    // Reward tight fits (small post residual in absolute terms).
    score -= 15.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Compare against mean residual across open bins: prefer consuming large residuals.
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else {
        // Many fitting bins: slight preference to spread usage; keep scores comparable.
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Discourage opening new bins when few bins are open early in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 + 20.0 * (1.0 - progress) + open_bins_count as f64;
    }

    // Late-stream pressure: consolidate aggressively as the stream ends.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero is good.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize dead space that cannot fit the smallest plausible item (1..100 unknown, use small threshold).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Lookahead coupling: if next item fits in post_residual, big reward.
    if next_item_size > 0 {
        if (next_item_size as u32) <= post_residual {
            score -= 30.0;
        } else {
            score += 10.0; // forces next item elsewhere
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 60.0;
    } else if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate handling: empty bin gets baseline penalty unless open bins are crowded.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowding = open_bins_count as f64 / (mean_residual.max(1.0) / 10.0).max(1.0);
        score += 35.0 - 20.0 * progress - crowding.min(30.0);
    }

    // Prefer filling bins below mean residual (balance load).
    score += 0.15 * (bin_residual as f64 - mean_residual).max(0.0);

    // Slight preference for bins with less residual overall (best-fit bias).
    score += 0.1 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on, prefer tight fits (small post_residual); later, allow slightly
    // larger residuals since future items are more uncertain.
    let pr_norm = pr / cap; // in [0,1]
    let w = 1.0 + 0.8 * progress * progress;
    score += 60.0 * w * pr_norm * pr_norm;

    // Reward bins whose post_residual closely matches the lookahead item
    // (smooth kernel instead of hard threshold).
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64).abs();
        score -= 25.0 * (-diff * diff / 400.0);
    }

    // Penalize creating dead space relative to mean residual of open bins.
    score += 4.0 * (pr - mean_residual).abs() / cap;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 80.0 * (1.0 - pr_norm);
    }

    // Mild pressure to consolidate when many bins are open.
    score -= 2.0 * (open_bins_count as f64).ln() * (1.0 - pr_norm);

    // New-bin candidate: make it moderately attractive only when no open bin
    // is a good fit (post_residual of empty bin == capacity).
    if bin_residual == bin_capacity {
        score += 12.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual into residue classes mod 10 and mod 25.
    let pr = post_residual;
    let class10 = (pr % 10) as f64;
    let class25 = (pr % 25) as f64;
    // Penalize awkward leftover classes (small non-zero remainders are dead space).
    if pr > 0 {
        score += 6.0 * (10.0 - class10.min(10.0 - class10)) / 10.0;
        score += 4.0 * (25.0 - class25.min(25.0 - class25)) / 25.0;
    }
    // Perfect fit is heavily rewarded.
    if pr == 0 {
        score -= 40.0;
    }

    // Lookahead: does next item fit in post_residual?
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if next_item_size > 0 && next_item_size <= pr {
        // Next item chains nicely; reward, more so early in the stream.
        score -= 8.0 + 6.0 * (1.0 - progress);
        // Extra reward when next item exactly fills the new residual (perfect chaining).
        if next_item_size == pr {
            score -= 15.0;
        }
    } else if next_item_size > pr {
        // Next item won't fit here; penalize leaving a gap just under next_item_size.
        if pr > 0 && pr >= next_item_size.saturating_sub(10) {
            score += 10.0 * (1.0 - progress);
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin, reduced when many bins are open or stream is early.
        score = 55.0 - 3.0 * (open_bins_count as f64).min(10.0) - 15.0 * (1.0 - progress);
        // If the current item leaves a well-structured residual, opening is more attractive.
        if pr == 0 { score -= 25.0; }
        if next_item_size > 0 && next_item_size <= pr { score -= 10.0; }
        // If no other bin fits, opening is necessary: lower the score.
        if fitting_bins_count == 0 { score -= 30.0; }
        // Discourage opening when an open bin would be nearly full (tight fit exists).
        let tightness = 1.0 - (item_size as f64 / bin_capacity as f64);
        if tightness < 0.15 { score += 20.0; }
    } else {
        // Prefer filling bins that are already small relative to mean residual.
        score -= 0.5 * (mean_residual - bin_residual as f64).max(0.0);
    }

    // Mild preference for bins whose residual is a multiple of common item sizes (harmonic).
    if pr % 10 == 0 && pr > 0 {
        score -= 3.0;
    }
    if pr % 50 == 0 && pr > 0 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for the smallest plausible item are wasted.
    let dead_threshold = 12u32;
    if post_residual < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual) as f64 * 3.0;
    }

    // Perfect-fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward leaving room for the next item (lookahead k=2).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.1 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 5.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage opening new bins when open bins exist,
    // unless the new bin would be nearly filled (large item in empty bin).
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline cost plus pressure from open bins.
        score += 15.0 + 2.0 * open_bins_count as f64;
        // A big item justifies a fresh bin.
        if item_size > bin_capacity / 2 {
            score -= 0.8 * item_size as f64;
        }
    } else {
        // Reward using existing bins, scaled by how full the bin already is.
        let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= 5.0 + 10.0 * fill_ratio;
    }

    // Mild penalty for deviating far from mean residual (keeps bins balanced).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Late-stream tightening: prefer compact packing as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (1.0 - fill_ratio_safe(bin_residual, bin_capacity));

    score
}

#[inline]
fn fill_ratio_safe(bin_residual: u32, bin_capacity: u32) -> f64 {
    (bin_capacity - bin_residual) as f64 / bin_capacity.max(1) as f64
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Lookahead: reward bins whose post-residual exactly matches the next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if gap == 0.0 {
            score -= 25.0; // perfect two-item chain
        } else if post_residual >= next_item_size {
            score -= 8.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item cannot fit here; penalize proportionally to wasted space
            score += 0.5 * gap;
        }
    }

    // Tight fits are valuable: reward small post_residual relative to capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 20.0 * (1.0 - tightness) * (1.0 - tightness);

    // Compare against mean residual: prefer bins that are already more filled than average.
    score += 0.6 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize new-bin candidate unless current bins are nearly full or fit is bad.
    if bin_residual == bin_capacity {
        let avg_tight = mean_residual / bin_capacity as f64;
        let poor_fit = post_residual as f64 > 0.35 * bin_capacity as f64;
        if avg_tight < 0.15 || (poor_fit && next_item_size > post_residual && next_item_size > 0) {
            score -= 5.0; // opening fresh bin is fine
        } else {
            score += 40.0; // keep using open bins
        }
    }

    // Late in the stream, consolidate harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - tightness);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is ideal
    if post_residual == 0 {
        score -= 50.0;
    } else {
        // Penalize small but nonzero dead space (unusable slivers)
        if post_residual < 10 {
            score += (10 - post_residual) as f64 * 2.0;
        }
        // Reward moderately tight fits
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= tightness * 8.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // next item fits: prefer leaving usable space
            score -= 5.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here: penalize leaving space close to next_item_size (wasted)
            let gap = (next_item_size - post_residual) as f64;
            if gap < 10.0 {
                score += (10.0 - gap) * 1.5;
            }
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Many open bins: prefer filling existing ones over opening new
    if open_bins_count > 2 {
        score -= (open_bins_count as f64).ln() * 2.0;
    }

    // Bin with residual equal to capacity is the new-bin candidate:
    // penalize it mildly so it's only chosen when open bins are truly bad,
    // but relax the penalty late in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 6.0 - 4.0 * progress;
    }

    // Prefer bins below mean residual (balancing), scaled by item size
    let diff = mean_residual - bin_residual as f64;
    score += 0.05 * diff * (item_size as f64 / 100.0);

    // Early stream: be pickier about tight fits; late stream: just pack
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 - 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (0.5 + 1.5 * progress) - norm_pr * (0.3 * progress);

    // Penalize large dead space more as stream progresses (waste matters later)
    score += poly * cap * (0.2 + 0.8 * progress * progress);

    // Reward tight fits: near-zero post residual gets a bonus
    score -= (1.0 - norm_pr).powi(3) * 6.0;

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 8.0;
    }

    // Lookahead: favor bins whose post residual fits the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 3.0 * (1.0 - ((pr - nxt) / cap).abs());
        } else {
            score += 2.0 * (nxt - pr) / cap;
        }
    }

    // Mild preference for fuller bins relative to mean residual
    score -= (mean_residual - pr) * 0.05;

    // Slight penalty for bin proliferation early on
    score += (open_bins_count as f64) * 0.01 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: modulo classes on capacity fractions.
    let pr = post_residual as f64;
    let frac = pr / cap; // fraction of capacity left after placement

    // Dead-space classes: post_residual in [1,10] is a "perfect close" -> big reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 200.0 + (10 - post_residual) as f64 * 10.0;
    } else if post_residual <= 20 {
        score -= 80.0;
    } else if post_residual <= 30 {
        score -= 30.0;
    }

    // Integer-division threshold classes on post_residual (harmonic bins of size 10).
    let class = post_residual / 10;
    score += class as f64 * 5.0;

    // Coupling with next item: reward if next item fits exactly into post_residual,
    // penalize if next item is close to fitting but would leave awkward residue.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 150.0;
        } else if next_item_size < post_residual {
            let chain_res = post_residual - next_item_size;
            if chain_res <= 10 {
                score -= 60.0;
            } else {
                score += chain_res as f64 * 0.3;
            }
        } else {
            // next item cannot use this residual space: mild penalty proportional to wasted fraction
            score += frac * 40.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 {
        score -= 50.0 + frac * 30.0;
    }

    // Prefer bins with tighter residuals relative to mean residual of open bins.
    score += (pr - mean_residual) * 0.4;

    // Penalize opening a new bin early in the stream when many bins are open;
    // encourage bin consolidation as stream progresses.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // new-bin candidate: base cost plus progress-aware penalty
        score += 60.0 + 40.0 * (1.0 - progress) + open_bins_count as f64 * 2.0;
        // but if no open bin fits well (large item vs mean residual), new bin is fine
        if item_size as f64 > mean_residual + 15.0 {
            score -= 45.0;
        }
    }

    // Small tie-breaker on tightness of fit (item fills most of the bin).
    score += (1.0 - (item_size as f64) / cap) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no future item (min size 1..=small)
    // can usefully fill are heavily penalized. "Unusable" gap = small but nonzero.
    if post_residual > 0 {
        let pr = post_residual as f64;
        if pr < 10.0 {
            // tiny sliver: nearly worthless dead space
            score += (10.0 - pr) * 4.0;
        } else if pr <= 20.0 {
            // small gap: only usable by very small items
            score += (20.0 - pr) * 1.5;
        }
        // Perfect fit reward
        if post_residual == 0 {
            score -= 25.0;
        }
    }

    // Reward fills that leave room for the lookahead item exactly (k=2 lookahead).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if (pr - nxt).abs() < 0.5 {
            score -= 20.0; // next item fits perfectly after this placement
        } else if pr >= nxt && pr - nxt < 10.0 {
            score -= 8.0; // next item fits with small leftover
        } else if pr > 0.0 && pr < nxt {
            score += 6.0; // gap too small for the known next item
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // or the system is congested with dead residuals.
    if bin_residual == bin_capacity {
        let congestion = open_bins_count as f64 * mean_residual / bin_capacity as f64;
        // Opening a new bin is cheap when open bins are full of dead space,
        // expensive when open bins are well-utilized.
        score = bin_capacity as f64 * 0.6 + congestion * 5.0;
        if fitting_bins_count == 0 {
            score -= 40.0; // no alternative: new bin is fine
        }
        if fitting_bins_count == 1 {
            score += 50.0; // override last-chance: keep using the existing bin
        }
        // Early in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (1.0 - progress) * 20.0;
    }

    // Open-bin pressure: mild penalty per extra open bin for non-new bins,
    // pushing consolidation when many bins are open.
    if bin_residual != bin_capacity {
        score += open_bins_count as f64 * 0.5;
    }

    // Mean-residual coupling: if this bin's residual is far below the mean
    // (it is unusually full), reward placing here to balance waste.
    let res_f = bin_residual as f64;
    if res_f < mean_residual {
        score -= (mean_residual - res_f) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly favor exact or near-exact fills.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: reward bins whose residual matches the next item size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 / (1.0 + gap / 10.0);
        if post_residual == next_item_size {
            score -= 500.0;
        }
        // Penalize leaving a residual that no plausible item can use (dead space).
        if post_residual < 10 {
            score += 150.0;
        }
        // Penalize if next item fits perfectly elsewhere but poorly here (crude proxy via mean).
        if (post_residual as f64) < mean_residual * 0.5 {
            score += 40.0;
        }
    }

    // Relative-to-mean residual shaping: prefer bins that are tighter than average.
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: penalize opening a new bin unless it enables a great lookahead match.
    if bin_residual == bin_capacity {
        score += 120.0;
        if next_item_size > 0 && post_residual >= next_item_size && (post_residual - next_item_size) <= 5 {
            score -= 250.0;
        }
    }

    // Mild pressure to close out streams efficiently.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        let pr = post_residual as f64;
        // Squared penalty on leftover, scaled by capacity.
        score += (pr * pr) / bin_capacity as f64;
        // Dead space: leftovers too small for typical items are wasted.
        if post_residual < 10 {
            score += 15.0;
        }
    }

    // Lookahead: reward if the next item fits into the post residual (chaining),
    // penalize if next item would be blocked by a small leftover.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0 + 0.1 * next_item_size as f64;
        } else if post_residual > 0 && next_item_size > post_residual {
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing residuals are poor fits or the item is large.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin, amortized over stream progress.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut open_cost = 30.0 - 10.0 * progress;
        // Large items leave less usable residue; opening is safer for them.
        open_cost -= 0.15 * item_size as f64;
        // If many bins fit the item, opening a new one is wasteful.
        open_cost += 8.0 * (fitting_bins_count as f64).min(5.0);
        // If mean residual is small (bins nearly full), opening is reasonable.
        open_cost -= 0.2 * mean_residual;
        score = open_cost.max(1.0) + post_residual as f64;
    }

    // Mild pressure against hoarding many open bins when residuals are large.
    if open_bins_count > 3 && mean_residual > 30.0 && bin_residual < bin_capacity {
        score += 0.05 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Smooth non-linear polynomial in post_residual, modulated by stream progress.
    let quad = norm_pr * norm_pr;
    let cubic = quad * norm_pr;
    let mut score = pr * (1.0 - 0.5 * progress) + 30.0 * quad * (0.5 + progress) + 20.0 * cubic * progress;

    // Penalize dead space that is too small to be useful later (smooth window).
    let usefulness = (norm_pr * (1.0 - norm_pr) * 4.0).clamp(0.0, 1.0);
    score -= 15.0 * usefulness * (1.0 - progress);

    // Lookahead coupling: reward residual that can host the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits_next = (pr >= nxt) as i32 as f64;
        let gap = ((pr - nxt) / cap).abs();
        score -= fits_next * (10.0 + 15.0 * (1.0 - gap));
        score += 8.0 * (1.0 - fits_next) * (0.5 + progress);
    }

    // Last-chance bonus: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    } else if fitting_bins_count > 2 {
        score += 3.0 * (fitting_bins_count as f64 - 2.0).min(5.0);
    }

    // Mild penalty for spreading across many open bins relative to mean residual.
    score += 0.05 * open_bins_count as f64 * (mean_residual - pr).abs() / cap;

    // New-bin candidate: opening a fresh bin is attractive early, less so late.
    if bin_residual == bin_capacity {
        score += 5.0 + 20.0 * progress - 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "reusable" the leftover space is.
    // Residuals that are multiples of common size classes (10..=25) are more likely
    // to be filled by future items; penalize awkward residuals.
    let pr = post_residual;
    let harmonic_bonus = if pr == 0 {
        -60.0 // perfect fill
    } else if pr % 10 == 0 && pr >= 10 {
        -25.0 // round residual, highly reusable
    } else if pr % 5 == 0 {
        -12.0
    } else {
        // awkward residual: penalize proportionally to how far from a round class
        let frac = (pr % 10) as f64 / 10.0;
        18.0 * frac
    };
    score += harmonic_bonus;

    // Integer-division threshold classes on post_residual.
    let class = pr / 25; // 0: tiny leftover, 1: quarter, 2: half, 3: three-quarter
    score += match class {
        0 => -8.0,
        1 => 0.0,
        2 => 6.0,
        _ => 10.0,
    };

    // Lookahead coupling: does next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 14.0 - 0.05 * slack; // next item fits: reward tight chains
        } else {
            score += 6.0; // next item won't fit here
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing bins fit poorly (item barely fits or leaves bad residual).
    if bin_residual == bin_capacity {
        let fit_quality = (item_size as f64 / bin_capacity as f64).powf(2.0);
        // New bin leaves residual = capacity - item_size; score it as such but
        // add a switching cost that shrinks when existing fits are terrible.
        let poor_fit_penalty = if fitting_bins_count == 0 {
            0.0
        } else {
            // how badly does the best existing fit look? approximate via item size
            let tightness = item_size as f64 / bin_capacity as f64;
            20.0 * (1.0 - tightness).powf(3.0)
        };
        score += 15.0 - 25.0 * fit_quality + poor_fit_penalty;
        // Late in stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    } else {
        // Prefer fuller bins: reward proximity to capacity.
        let fill = 1.0 - (bin_residual as f64 / bin_capacity as f64);
        score -= 20.0 * fill * fill;
    }

    // Spread across many open bins is bad; favor bins near mean residual usage.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual that cannot accommodate the smallest plausible item is "dead".
    let dead_threshold: f64 = 8.0;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 25.0;
    } else if (post_residual as f64) < 15.0 {
        score += (15.0 - post_residual as f64) * 8.0;
    }

    // Reward tight fits: perfect fills are strongly favored.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Penalize bins whose post-residual is large but awkward relative to the
    // lookahead item: leaving a gap that next_item_size almost (but does not) fit.
    if next_item_size > 0 {
        if next_item_size > post_residual {
            // gap too small for next item -> likely dead space
            let gap = (next_item_size - post_residual) as f64;
            if gap < 20.0 {
                score += gap * 3.0;
            }
        } else if next_item_size == post_residual {
            // perfect setup for the next item: strong reward
            score -= 45.0;
        }
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: only attractive when no open bin fits well, i.e.
    // when current bin's fit is poor (large post_residual) or dead space.
    if bin_residual == bin_capacity {
        // baseline score for a fresh bin is its full residual (100)
        // penalize opening new bins when open-bin pressure is low
        score += 20.0;
        if fitting_bins_count > 0 {
            score += 30.0;
        }
    }

    // Mean-residual coupling: prefer bins deviating below the mean residual
    // (denser bins) when many bins are open.
    if open_bins_count > 2 {
        let dev = mean_residual - post_residual as f64;
        score -= dev * 0.4;
    }

    // Slight stream-progression term: tighten packing later in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            score -= 100.0 - (post_residual - next_item_size) as f64;
        } else {
            // dead space relative to lookahead
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Prefer bins tighter than mean residual
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Penalize opening a new bin when fitting bins exist, unless current fit is terrible
    if bin_residual == bin_capacity {
        let waste = bin_capacity as f64 - item_size as f64;
        score = waste + 50.0;
        if fitting_bins_count > 0 && (bin_residual - item_size) >= next_item_size.min(60) {
            score += 300.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that cannot fit the lookahead item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 6.0 + 0.4 * (next_item_size - post_residual) as f64;
        } else {
            // Reward bins that can also hold the next item.
            score -= 4.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Penalize opening a new bin when good fitting bins exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let penalty = 8.0 + 15.0 * (1.0 - progress) * (mean_residual / bin_capacity as f64);
        score += penalty;
        if fitting_bins_count == 0 {
            score -= 30.0; // no alternative, new bin is fine
        }
    }

    // Mild pressure to fill bins when many are open (fragmentation control).
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Encourage using bins whose residual deviates above the mean (consolidate).
    let dev = bin_residual as f64 - mean_residual;
    score -= 0.15 * dev;

    // Late-stream: prefer minimizing leftover waste more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit_ratio = item_size as f64 / cap;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let prog2 = progress * progress;
    let prog3 = prog2 * progress;
    score += norm_pr * norm_pr * (2.0 + 4.0 * progress) * cap;
    score -= fit_ratio * fit_ratio * (1.0 + 3.0 * prog2) * 20.0;

    // Reward tight fits smoothly
    score -= (1.0 - norm_pr).powi(3) * 15.0 * (1.0 + progress);

    // Lookahead coupling: favor bins whose post-residual can host next item
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 10.0 * (next_item_size as f64 / cap) * (1.0 + 2.0 * prog3);
    } else if next_item_size > 0 {
        score += 5.0 * (next_item_size as f64 / cap) * (1.0 - progress);
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Penalize many open bins mildly, coupled with mean residual
    score += (open_bins_count as f64).sqrt() * mean_residual * 0.05 * (1.0 - progress);

    // New-bin candidate: prefer it only for large items or late stream
    if bin_residual == bin_capacity {
        score += 8.0 - 10.0 * progress - 15.0 * fit_ratio;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual after placement: small post-residuals are valuable.
    let class: u32 = post_residual / 10;
    score += match class {
        0 => -60.0,                      // post_residual < 10: near-perfect fit
        1 => -30.0,                      // 10..20: still very tight
        2 => -10.0,                      // 20..30
        3..=5 => 5.0,                    // mid-class residuals: mildly wasteful
        _ => 15.0,                       // large leftover: dead space risk
    };

    // Exact-fill bonus: perfectly closed bin.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Modulo-10 harmony: residual divisible by 10 is more reusable by typical items.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }

    // Lookahead coupling: reward if the next item fits the post-residual well.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= 12.0 - (slack as f64).min(12.0) * 0.5;
            if slack == 0 {
                score -= 15.0; // chain of perfect fits
            }
        } else {
            // Next item won't fit here; penalize proportionally to how close we were.
            score += 6.0;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits, to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin is a fallback; make it mildly attractive
    // only when current bins would leave large unusable residue.
    if bin_residual == bin_capacity {
        score = 40.0 + mean_residual * 0.2 - (open_bins_count as f64) * 1.5;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
        // Late in the stream, prefer consolidating into existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 15.0;
        return score;
    }

    // Tightness term: prefer bins whose residual is close to item size (best-fit core),
    // modulated by harmonic class of bin_residual.
    let tightness = (bin_residual - item_size) as f64;
    score += tightness * 0.15;

    // Penalize bins far from mean residual (fragmentation of the pool).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    // Many open bins: encourage filling existing ones rather than spreading.
    if open_bins_count > 3 {
        score -= 3.0;
    }

    // Integer-division threshold: residuals in [50, 99] are half-bin classes;
    // placing here when item is large keeps classes balanced.
    if post_residual / 50 == 1 && item_size >= 50 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps more than large ones.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 4.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= tightness * 12.0;

    // Open-bin pressure: penalize adding bins when many are open.
    score += open_bins_count as f64 * 0.35;

    // Last-chance bonus: strongly favor the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make empty bin less attractive unless item is huge
    // relative to residual capacity of open bins (avoid fragmenting).
    if bin_residual == bin_capacity {
        score += 15.0;
        if item_size >= 60 {
            score -= 20.0;
        }
    }

    // Lookahead: if next item would fit in the post-residual, reward this placement.
    if next_item_size > 0 && (post_residual as i64) >= (next_item_size as i64) {
        score -= 8.0;
    }

    // Late-stream consolidation: prefer existing bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 3.0;

    // Prefer bins with residual below mean (filling tighter bins first).
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item exactly fills the post-residual.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += gap * 0.6;
        // Perfect chain: this placement lets the next item fit exactly.
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            score -= 8.0; // next item still fits here afterwards
        } else {
            score += 5.0; // next item won't fit in this bin afterwards
        }
    }

    // Penalize unusable dead space relative to mean residual of open bins.
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.35;
    } else {
        score -= (mean_residual - post_residual as f64) * 0.15;
    }

    // Very small residuals are excellent (tight fit).
    if post_residual < 5 {
        score -= 20.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is huge
    // relative to capacity (poor fit elsewhere) or many bins are already open.
    if bin_residual == bin_capacity {
        score += 12.0;
        if item_size * 4 >= bin_capacity * 3 {
            score -= 20.0; // big item: fresh bin is fine
        }
        if open_bins_count > 12 {
            score -= 6.0;
        }
        // Don't open a fresh bin when the next item could chain into residual space.
        if next_item_size > 0 && post_residual >= next_item_size {
            score += 10.0;
        }
    }

    // Mild progression bias: later in the stream, prefer consolidating.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 3.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: scale post_residual by how full the bin becomes.
    let fill_ratio = item_size as f64 / cap;
    score *= 0.5 + 0.9 * fill_ratio;

    // Lookahead: if the next item fits exactly-ish into the post residual, reward strongly.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - slack / cap);
    } else if next_item_size > post_residual {
        // Next item won't fit here; penalize leaving awkward medium residuals.
        if post_residual > 0 && post_residual < next_item_size {
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalize scattering across many open bins when residuals are large.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual < bin_capacity {
        score += (open_bins_count as f64 - mean_residual / 10.0).max(0.0) * 0.3 * (1.0 - progress);
    }

    // New-bin candidate: keep it attractive only when existing fits are poor.
    if bin_residual == bin_capacity {
        let tight_exists = post_residual == 0 && bin_residual == bin_capacity; // never for new bin
        let _ = tight_exists;
        score = cap * 0.75 - 10.0 * (1.0 - progress);
        if fitting_bins_count <= 1 {
            score -= 20.0; // no good open option -> open new bin
        }
        if next_item_size > 0 && next_item_size <= bin_capacity {
            let pair = item_size as f64 + next_item_size as f64;
            if pair > cap {
                score += 8.0; // pair won't share a bin anyway; keep new bin available
            }
        }
    }

    // Small bonus for exact fits.
    if post_residual == 0 {
        score -= 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth non-linear coupling of post_residual with stream progress.
    // Early on, prefer tight fits (low post_residual); later, tolerate
    // residual but reward near-perfect packing via a quartic trough.
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1]
    let trough = (x - 0.05).powi(2) * (1.0 + 2.0 * progress);
    score += 40.0 * trough;

    // Progress-driven multiplicative shaping of the raw residual:
    // residual becomes less costly as the stream matures (bins are sunk cost).
    score += pr * (0.25 * (1.0 - progress) * (1.0 - progress));

    // Lookahead coupling: reward residual that can still host the next item,
    // penalize residual that wastes space relative to the next item size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 12.0 * (1.0 - (pr - nxt) / cap) * (1.0 + progress);
        } else {
            score += 8.0 * (nxt - pr) / cap;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // New-bin candidate: penalize opening a bin unless residual waste elsewhere
    // is high relative to mean residual.
    if bin_residual == bin_capacity {
        let spread = mean_residual - pr; // typically negative for empty bin
        score += 30.0 + 20.0 * progress - 0.15 * spread;
        if open_bins_count == 0 {
            score -= 100.0; // must open first bin
        }
    }

    // Mild penalty for bin congestion: spreading items thinly is bad.
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: prefer residuals that are useful
    // "harmonics" of capacity (cap/2, cap/3, cap/4 ...) and penalize
    // dead-space classes (very small residuals).
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Dead-space penalty: residual below cap/4 is nearly unusable.
    if pr < cap / 4.0 {
        score += 2.0 * (cap / 4.0 - pr);
    }

    // Reward landing on harmonic residuals: cap/2, cap/3, cap/4, cap/5.
    let harmonics = [50u32, 33, 25, 20];
    for (i, &h) in harmonics.iter().enumerate() {
        let tol = 3 + i as i32;
        if ((post_residual as i32 - h as i32).abs() as u32) <= tol as u32 {
            score -= 4.0 - i as f64;
        }
    }

    // Integer-division threshold: post_residual class via modulo of capacity.
    let class = post_residual % (bin_capacity / 10);
    score -= (class as f64) * 0.05; // slight preference for residuals at class boundaries

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 10.0;
        } else if next_item_size <= post_residual {
            // reward proportional fit quality of the lookahead
            let fit_ratio = next_item_size as f64 / post_residual as f64;
            score -= 5.0 * fit_ratio;
        } else {
            // next item cannot use this residual at all: penalize small leftovers more
            score += (cap - pr.min(cap)) * 0.02;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: neutral-ish baseline, discouraged unless current bins are crowded.
    if bin_residual == bin_capacity {
        score = cap as f64 * 0.75 + open_bins_count as f64 * 0.5 - mean_residual * 0.1;
        if fitting_bins_count == 0 {
            score -= 20.0; // nothing else fits, must open
        }
        // late in stream, prefer consolidating into existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 5.0;
    }

    // Mild preference for bins tighter than the mean residual (better fill).
    if (bin_residual as f64) < mean_residual {
        score -= 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < next_item_size && next_item_size > 0 {
        score += 12.0 + 0.5 * (next_item_size as f64 - post_residual as f64);
    }
    if post_residual == 0 {
        score -= 30.0; // perfect fill
    }

    // Tightness reward: fraction of residual consumed.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fill_ratio * fill_ratio;

    // Open-bin pressure: prefer existing bins when many are open.
    score += 0.8 * open_bins_count as f64;

    // Last-chance bin before opening a new one: strong bonus.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Mean-residual alignment: bins whose residual is near mean are natural homes.
    score += 0.15 * ((post_residual as f64 - mean_residual).abs());

    // New-bin candidate: only attractive for very large items or when no bin fits well.
    if bin_residual == bin_capacity {
        let large = item_size as f64 / bin_capacity as f64;
        if large > 0.75 || (fitting_bins_count == 0) {
            score -= 10.0;
        } else {
            score += 25.0 + 10.0 * (1.0 - large);
        }
    }

    // Late in the stream: consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, but weight residual more when the bin is nearly full.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score += (bin_capacity as f64 - post_residual as f64) * 0.1 * tightness;

    // 2-step lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let match_quality = (post_residual - next_item_size) as f64;
        score -= 30.0 * (1.0 - match_quality / (bin_capacity as f64));
    } else if next_item_size > 0 {
        // Penalize if next item cannot fit into this bin's post residual
        // (dead space unless another bin absorbs it).
        score += 8.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Relative to mean residual: bins with less residual than average are
    // more valuable to fill aggressively.
    let rel = (bin_residual as f64) - mean_residual;
    score -= 0.05 * rel;

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate penalty: only open a new bin when no good fit exists,
    // i.e. when the item would leave a large awkward residual everywhere.
    if bin_residual == bin_capacity {
        let poor_fit_elsewhere = mean_residual < item_size as f64 * 0.9;
        if poor_fit_elsewhere {
            score -= 10.0;
        } else {
            score += 20.0;
        }
    }

    // Late in the stream, consolidation matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small wasted space), with a superlinear penalty on dead space.
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * waste_ratio * waste_ratio;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize the brand-new empty bin candidate, unless the item fits very poorly
    // everywhere (large post_residual relative to capacity) or many bins are open.
    if bin_residual == bin_capacity {
        let mut new_bin_penalty = 18.0;
        // As the stream progresses, discourage proliferating bins slightly more.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        new_bin_penalty += 10.0 * progress;
        // If mean residual across open bins is small, a new bin is more justified.
        new_bin_penalty -= (mean_residual / bin_capacity as f64) * 15.0;
        if open_bins_count == 0 {
            new_bin_penalty = -100.0; // must open a bin
        }
        score += new_bin_penalty;
    }

    // Lookahead: reward bins whose post_residual can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else if post_residual > 0 {
            // Penalize leaving a gap that neither fits the next item nor is tiny.
            score += 4.0 * (post_residual as f64 / next_item_size as f64);
        }
    }

    // Mild preference for bins with below-average residual (consolidate waste).
    let bin_residual_f = bin_residual as f64;
    if mean_residual > 0.0 {
        score += 2.0 * (bin_residual_f - mean_residual) / bin_capacity as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let prn = pr / cap;

    // Base: post-residual, with smooth non-linear coupling to stream progress.
    // Late in the stream, leftover space is less likely to be filled -> penalize more.
    let mut score = pr * (1.0 + progress * prn);

    // Non-linear polynomial coupling: (prn)^2 grows penalty quadratically for large dead space,
    // modulated by progress so early bins tolerate slack.
    score += 8.0 * prn * prn * (0.5 + progress);

    // Reward tight fits: small post_residual relative to item size.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 6.0 * fit_ratio * fit_ratio * (1.0 - prn);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 10.0 + 5.0 * progress;
    }

    // Lookahead: if next item fits exactly into post_residual, reward heavily.
    if next_item_size > 0 {
        let nd = (next_item_size as f64 - pr).abs();
        score -= 5.0 * (1.0 - nd / cap).max(0.0) * (1.0 - prn);
    }

    // Prefer bins with residual below mean residual (concentrating slack).
    score += 2.0 * (pr - mean_residual) / cap;

    // Mild penalty for spreading across many open bins late in stream.
    score += 0.05 * open_bins_count as f64 * progress;

    // New-bin candidate: keep it slightly attractive early, unattractive late.
    if bin_residual == bin_capacity {
        score += 3.0 - 6.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class: residual capacity fraction
    let frac = post_residual as f64 / bin_capacity as f64;
    // Penalize residuals in "dead zone" classes: 1..10 (unusable) but reward exact small fits
    let dead = post_residual > 0 && post_residual < 10;
    if dead {
        score += 60.0;
    }
    // Reward perfect fit
    if post_residual == 0 {
        score -= 200.0;
    }
    // Harmonic class of post_residual modulo 10: small mod classes pair well with 10..80 items
    let class = (post_residual % 10) as f64;
    score += 0.5 * class;

    // Lookahead: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 150.0;
        } else if gap < 10 {
            score -= 80.0;
        } else {
            score += gap as f64 * 0.3;
        }
    } else if next_item_size > 0 {
        // next item won't fit here; residual likely wasted
        score += post_residual as f64 * 0.2;
    }

    // Last chance bin: strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 100.0;
    }

    // New bin candidate: penalize opening a new bin unless existing bins are poor fits
    if bin_residual == bin_capacity {
        let base = 40.0 + 0.5 * (item_size as f64);
        // early stream: more willing to open bins
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = base + 50.0 * progress;
        // if many open bins with large mean residual, prefer them instead
        score += mean_residual * 0.4;
    }

    // Mild penalty for fragmentation relative to mean residual
    score += (mean_residual - post_residual as f64).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize unusable small gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 500.0;
    } else if post_residual < 20 {
        score += 120.0;
    } else if post_residual < 30 {
        score += 40.0;
    }

    // Perfect or near-perfect fit reward.
    if post_residual == 0 {
        score -= 300.0;
    } else if post_residual <= 5 {
        score -= 80.0;
    }

    // Dead space is worse if nothing else fits in it: penalize gaps smaller
    // than the lookahead item (which then cannot reuse this bin).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size as f64 {
        score += 60.0 + 0.5 * post_residual as f64;
    }

    // Reward bins whose residual exactly accommodates the next item.
    if next_item_size > 0 && post_residual as u32 == next_item_size {
        score -= 100.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // over spreading; with few open bins, opening a new bin is cheaper.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * 8.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Penalize the brand-new empty bin candidate unless open-bin pressure is
    // low or the fit would be terrible.
    let fit_quality = post_residual as f64 / bin_capacity as f64;
    if bin_residual == bin_capacity {
        let escape_cost = 40.0 + 250.0 * (1.0 - fit_quality);
        score += escape_cost - pressure * 12.0;
        if fitting_bins_count == 0 {
            score -= 400.0; // no alternative: new bin is the only choice
        }
    }

    // Mild progression term: later in the stream, waste hurts more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * fit_quality * 30.0;

    // Nudge toward bins with residuals close to item size (tight fits).
    score += (bin_residual as f64 - item_size as f64).abs() * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (post_residual small relative to item size)
    let tightness = post_residual as f64 / (item_size as f64 + 1.0);
    score -= 20.0 * (1.0 - tightness.min(1.0));

    // Aggressive 2-step lookahead: reward if next item fits into post_residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Perfect chain: next item exactly consumes remaining space
            let chain_gap = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - chain_gap / bin_capacity as f64);
        } else {
            // Next item cannot follow: penalize dead space proportionally
            let waste = (post_residual as f64) / bin_capacity as f64;
            score += 10.0 * waste;
        }
    } else {
        // Last item: prefer fullest packing
        score -= 5.0;
    }

    // Penalize bins whose residual is far above mean (hoarding space) unless tight fit
    let mean_gap = bin_residual as f64 - mean_residual;
    if mean_gap > 0.0 {
        score += 0.05 * mean_gap;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening a new bin unless this is a large item
    // and no open bin is a good fit (post_residual would be small anyway).
    if bin_residual == bin_capacity {
        let base_penalty = 25.0;
        // Large items with big post_residual waste benefit from a fresh bin
        let waste_penalty = (post_residual as f64) * 0.3;
        score += base_penalty - waste_penalty;
    }

    // Slight early-stream preference to consolidate into few bins
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    score += (1.0 - progress) * 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post * 1.0;

    // Strongly reward tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post / cap);
    score -= 45.0 * tightness * tightness;

    // Penalize dead space that cannot fit the next item (lookahead-aware)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post > 0.0 && post < nx {
            score += 12.0 * (nx - post) / cap * (1.0 + post / cap);
        }
        // Reward leaving exactly enough room for the next item
        if post == nx {
            score -= 15.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Penalize opening a new bin when decent open bins exist, especially early/mid stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 8.0 + 25.0 * (1.0 - progress);
        if open_bins_count > 0 && post < 0.5 * cap {
            score -= 10.0;
        }
    }

    // Mild preference for bins below mean residual (balance load)
    score += 0.05 * (mean_residual - bin_residual as f64);

    // Slight preference for fuller bins as stream progresses
    score -= 10.0 * progress * (1.0 - bin_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early: prefer tight fills (low post_residual). Late: tolerate slack slightly.
    let pr = post_residual as f64;
    let norm_pr = pr / bin_capacity as f64;
    let coupling = norm_pr * norm_pr * (1.0 + 3.0 * progress) * bin_capacity as f64;
    score += coupling - 0.5 * progress * norm_pr * bin_capacity as f64;

    // Reward filling bins tightly relative to current mean residual.
    score += 0.3 * (mean_residual - pr);

    // Penalize bins that could not fit (should rarely occur; safety).
    if bin_residual < item_size {
        score += 1e6;
    }

    // Last-chance bin: strong reward to use it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0 + 10.0 * progress;
    }

    // Lookahead: reward leaving post_residual that can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 4.0 + 0.05 * (post_residual - next_item_size) as f64;
    } else if next_item_size > 0 {
        // Penalize dead space unusable by the next item.
        score += 0.1 * (next_item_size as f64 - post_residual as f64).max(0.0);
    }

    // New-bin candidate handling: only open a new bin when existing fits are bad.
    if bin_residual == bin_capacity && item_size <= bin_capacity {
        score += 20.0 + 0.2 * mean_residual - 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals divisible by common
    // item sizes (10, 20, 25, 50) are more reusable; reward them.
    let pr = post_residual;
    if pr > 0 {
        if pr % 50 == 0 { score -= 8.0; }
        else if pr % 25 == 0 { score -= 5.0; }
        else if pr % 20 == 0 { score -= 4.0; }
        else if pr % 10 == 0 { score -= 3.0; }
        else if pr % 5 == 0 { score -= 1.5; }
        else {
            // Dead space: awkward residual, penalize quadratically.
            score += (pr as f64) * 0.05;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 20.0;
    }

    // Tight fit reward: post_residual small relative to item size.
    if pr > 0 && pr <= item_size / 2 {
        score -= 3.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual,
    // strongly favor this bin (chained harmonic match).
    if next_item_size > 0 && pr >= next_item_size {
        if pr == next_item_size { score -= 12.0; }
        else if pr % next_item_size == 0 { score -= 6.0; }
        else { score -= 2.0; }
    } else if next_item_size > 0 && next_item_size > pr {
        // Next item won't fit here; mild penalty proportional to excess.
        score += ((next_item_size - pr) as f64) * 0.03;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 4.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current
    // bins are nearly full / fragmented.
    if bin_residual == bin_capacity {
        score += 15.0;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Late in the stream, prefer reusing bins more strongly.
        score += 10.0 * (1.0 - progress);
        if mean_residual < item_size as f64 + 5.0 && fitting_bins_count >= 1 {
            score -= 5.0; // open bins are tight; new bin is fine
        }
    }

    // Prefer filling bins with large residuals when many bins are open.
    score += (open_bins_count as f64) * 0.02 * (post_residual as f64 / bin_capacity as f64);

    // Small global tie-breaker toward tighter bins.
    score += (bin_residual as f64) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever be
    // useful (below the minimum item size) are pure waste -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Small-but-usable gaps are risky if the next item cannot use them.
    if post_residual > 0 && post_residual < 20 {
        score += 12.0;
    }

    // Reward tight fits (best-fit flavor).
    score -= (item_size as f64 / bin_capacity as f64) * 8.0;

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // strongly reward this placement; penalize if it does not fit.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size > post_residual {
            score += 6.0;
        } else {
            score -= 4.0;
        }
    }

    // Open-bin pressure: discourage spreading across many bins unless the
    // fit is good; encourage consolidation when few bins are open.
    score += open_bins_count as f64 * 0.35;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: prefer keeping new bins closed unless the current
    // bin fit is poor (large dead space) or no bin fits well.
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive for very large items that would
        // leave awkward residuals elsewhere.
        if item_size >= 70 {
            score -= 15.0;
        } else if item_size >= 50 {
            score += 5.0;
        } else {
            score += 18.0 + mean_residual * 0.05;
        }
        // Late in the stream, closing out bins is cheaper than opening new ones.
        if total_items > 0 && (step_index as f64) / (total_items as f64) > 0.85 {
            score += 20.0;
        }
    }

    // Mild bonus for bins whose residual is close to the mean (consolidation).
    score -= ((bin_residual as f64) - mean_residual).abs() * -0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Base preference: tight fit (small post_residual)
    score = post_residual as f64 * (1.0 + 0.5 * (post_residual as f64 / cap));

    // 2-step lookahead: reward if next item exactly fills post_residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (nxt - post_residual as f64).abs() < 0.5 {
            score -= 40.0; // perfect chaining: item + next fill bin
        } else if next_item_size <= post_residual {
            score -= 12.0 * (1.0 - (post_residual as f64 - nxt) / cap);
        } else {
            // next item cannot fit in post_residual: penalize wasted lookahead space
            score += 6.0 * (nxt - post_residual as f64) / cap;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible
    if bin_residual == bin_capacity {
        score += 18.0;
        // but if lookahead chains perfectly into an empty bin, allow it
        if next_item_size > 0 && next_item_size as f64 + item_size as f64 >= cap * 0.95 {
            score -= 30.0;
        }
    }

    // Late in stream: prefer closing bins (fewer open bins)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.05 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Non-linear penalty for wasted space, amplified late in the stream.
        let waste = (post_residual as f64) / bin_capacity as f64;
        score += waste * waste * (200.0 + 300.0 * t);
    }

    // Penalize bins that remain barely usable (dead space trap).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Lookahead coupling: favor bins whose post-residual matches the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 / (1.0 + slack);
        } else {
            score += 25.0;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: only attractive when existing fits are poor or item is large.
    if bin_residual == bin_capacity {
        let urgency = if next_item_size > 0 { next_item_size as f64 } else { item_size as f64 };
        let poor_alternatives = if fitting_bins_count == 0 { 120.0 } else { 0.0 };
        score += 80.0 - urgency * 0.5 + poor_alternatives - 50.0 * t;
    }

    // Global state: many open bins with high mean residual -> prefer consolidation.
    if open_bins_count > 2 && mean_residual > (item_size as f64) {
        score -= 10.0 + 0.2 * mean_residual;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth non-linear polynomial coupling of post_residual with stream progress.
    let norm_post = post / cap; // 0..1 residual fraction
    let p = progress;
    // Polynomial interaction: residual cost grows with progress (late waste is worse)
    let poly = norm_post * norm_post * (1.0 + 2.0 * p) + norm_post * (0.5 + 1.5 * p * p);

    let mut score = post + 30.0 * poly;

    // Reward tight fits (small post_residual) more strongly later in the stream
    let tightness = 1.0 - norm_post;
    score -= 12.0 * tightness * tightness * (0.5 + p);

    // Lookahead coupling: if next item fits the post-residual, reward this bin
    if next_item_size > 0 && (next_item_size as f64) <= post {
        let gap = post - next_item_size as f64;
        score -= 8.0 * (1.0 - gap / cap) * (0.5 + p);
    } else if next_item_size > 0 {
        // Next item cannot use the leftover: penalize dead space, stronger late
        score += 6.0 * norm_post * (0.3 + p);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: prefer it only when open bins have poor residuals
    if bin_residual == bin_capacity {
        let mean_frac = mean_residual / cap;
        // Opening a new bin is attractive when mean residual is small (bins nearly full)
        let attractiveness = 1.0 - mean_frac;
        score = 15.0 + 40.0 * mean_frac * mean_frac - 10.0 * attractiveness * p;
        // Penalize opening new bins when many bins are already open
        score += 2.0 * (open_bins_count as f64).sqrt();
    } else {
        // Slight preference for bins whose residual deviates from mean (consolidation)
        let dev = (bin_residual as f64 - mean_residual).abs() / cap;
        score += 4.0 * dev * (1.0 - p);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Core: prefer minimal post_residual (tight fit).
    let mut score = post;

    // Harmonic class of the post residual: mod-10 classes.
    // Residuals that are "nice" (multiples of 10, or small) are more reusable.
    let pr = post_residual;
    let harmonic_bonus: f64 = match pr {
        0 => -30.0,                      // perfect fill
        1..=9 => -8.0,                   // small dead space, likely usable
        _ => {
            if pr % 10 == 0 { -12.0 }    // clean multiple of 10
            else if pr % 5 == 0 { -5.0 }
            else { 0.0 }
        }
    };
    score += harmonic_bonus;

    // Integer-division thresholds: residual buckets of size 20.
    // Large residuals are flexible; tiny residuals (1..10) are near-dead.
    if pr <= 10 && pr > 0 {
        score += 15.0; // near-dead space penalty
    } else if pr > (bin_capacity * 3 / 4) {
        score -= 6.0;  // very roomy bin, fine
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size <= pr {
            score -= 10.0;
            // prefer post_residual to be a divisor-like match class
            if pr % next_item_size == 0 {
                score -= 8.0;
            }
        } else {
            // next item won't fit here; slight penalty for stranding space
            score += 4.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // or open bins are nearly full on average.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / cap; // avg free fraction
        if fitting_bins_count == 0 {
            score -= 50.0; // must open a bin
        } else if pressure < 0.15 || open_bins_count == 0 {
            score -= 20.0; // existing bins nearly full -> new bin OK
        } else {
            score += 45.0 + pressure * 30.0; // discourage wasting fresh bins
        }
        // Late in stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Mild preference to balance load across bins when many are open.
    score -= 0.05 * (mean_residual - post).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no future item (min size 1..100 unknown,
    // but conservatively assume small items >= 10 exist) can use are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable sliver
    } else if post_residual < 20 {
        score += 18.0; // risky small gap
    } else if post_residual <= 30 {
        score += 4.0; // moderate gap
    } else {
        // large residual is valuable; reward keeping it usable
        score -= 6.0;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: if next item fits exactly into the post_residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        if gap == 0.0 {
            score -= 35.0;
        } else if gap < 10.0 {
            score += 8.0; // next item leaves a sliver -> discourage
        } else {
            score -= 10.0 * (1.0 - gap / bin_capacity as f64);
        }
    } else if next_item_size > 0 {
        // next item cannot fit in this bin's remainder; mild penalty unless residual is 0
        if post_residual > 0 {
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Open-bin pressure: prefer spreading load across already-open bins;
    // penalize opening new bins unless the current bin would be wasted.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: default cost, rising with number of open bins being low
        score += 25.0 + 10.0 * (1.0 - progress);
        // but if this bin is the only fitting option, opening new is fine
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    } else {
        // Existing bin: mild reward scaled by how full it already is (tight packing)
        let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= 12.0 * fill;
        // pressure to reduce open bin count when many are open
        if open_bins_count > 4 {
            score -= 2.0 * ((open_bins_count as f64) - 4.0).min(10.0);
        }
    }

    // Mean-residual coupling: if this bin's residual is far below mean, it's a good closer.
    let res = post_residual as f64;
    if res < mean_residual {
        score -= (mean_residual - res).min(20.0) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Lookahead: reward when next item fits snugly into the post residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post_residual as f64 - nxt).abs();
        if post_residual >= next_item_size {
            // Next item fits exactly or near-exactly -> strong reward.
            score -= (nxt / cap) * 30.0 * (1.0 - gap / cap);
            // Perfect two-item fill (post_residual == next_item_size)
            if gap < 1.0 {
                score -= 25.0;
            }
        } else {
            // Post residual too small for next item: penalize proportionally
            // to how much of the next item is wasted relative to residual.
            score += (nxt - post_residual as f64) * 0.35;
        }
        // If residual too small for next item but small in absolute terms, it's fine.
        if post_residual < 10 {
            score -= 8.0;
        }
    }

    // Tight fit reward: low post residual is good in general.
    score -= (1.0 - post_residual as f64 / cap) * 10.0;

    // Penalize bins whose residual is far below mean (fragmented bins),
    // reward bins with residual near mean for balanced packing.
    let dev = post_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize mildly so we prefer reusing open bins,
    // but allow opening when no open bin gives a decent fit.
    if bin_residual == bin_capacity {
        score += 15.0;
        // If many open bins already fit, opening a new bin is bad.
        if fitting_bins_count > 1 {
            score += 10.0 * (fitting_bins_count as f64 - 1.0);
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Slight penalty for very large dead space that no typical item (>=1)
    // can usefully fill when post residual is awkward (e.g. exactly 1..5).
    if post_residual >= 1 && post_residual <= 5 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 2.5 * tightness * tightness * (item_size as f64);

    // Penalize dead space that can't fit a typical future item.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Lookahead: reward if next item fits into the post-residual exactly or well.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 18.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; slight penalty proportional to overshoot.
            score += 0.15 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Time horizon: later in the stream, consolidate more aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 6.0 * progress * tightness;

    // Global state: many open bins with high mean residual -> prefer filling existing bins.
    if open_bins_count > 1 && mean_residual > item_size as f64 {
        score -= 4.0 * (mean_residual / bin_capacity as f64);
    }

    // New-bin candidate: penalize opening a new bin unless current fit is poor.
    if bin_residual == bin_capacity {
        let good_fit = (post_residual as f64) <= 0.35 * bin_capacity as f64;
        if good_fit {
            score -= 5.0;
        } else {
            score += 12.0 + 0.2 * (post_residual as f64);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: penalize leftover space, with non-linear (quadratic) growth.
    let mut score = post + (post / cap) * (post / cap) * 20.0;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post / cap);
    score -= tightness * tightness * 15.0;

    // Smooth stream-progress coupling: as stream advances, prefer filling bins tighter
    // (less tolerance for waste), via polynomial in progress.
    let p = progress;
    let progress_weight = p * p * (3.0 - 2.0 * p); // smoothstep
    score += progress_weight * post * 0.8;

    // Lookahead: if next item fits into post_residual, reward this bin strongly.
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 12.0 + progress_weight * 8.0;
    } else if next_item_size > 0 {
        // Next item won't fit: mild penalty scaled by how much it misses.
        let miss = (next_item_size as f64 - post) / cap;
        score += miss * miss * 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Many open bins with high mean residual: discourage spreading, favor consolidation.
    let crowding = (open_bins_count as f64).ln().max(0.0);
    score += crowding * (post / cap) * 5.0;
    score -= (mean_residual / cap) * 6.0;

    // New-bin candidate (empty bin): make it unattractive unless residual elsewhere is hopeless.
    if bin_residual == bin_capacity {
        score += 40.0 + progress_weight * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that belong to
    // "reusable" classes (multiples of 10, or small enough to likely absorb
    // small items), penalize awkward dead space.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class 1: post_residual divisible by 10 -> highly reusable residual
    if post_residual % 10 == 0 {
        score -= 8.0;
    } else if post_residual % 5 == 0 {
        score -= 3.0;
    }

    // Integer-division thresholds: tiny residuals are near-perfect fills
    if post_residual < 5 {
        score -= 20.0;
    } else if post_residual < 10 {
        score -= 12.0;
    }

    // Dead-space penalty: residual that is too small for the smallest
    // plausible future item is worthless.
    if post_residual > 0 && post_residual < 10 {
        score -= 6.0;
    }

    // Lookahead coupling: does next item fit in the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0 + (next_item_size as f64 / cap) * 8.0;
        } else {
            score += (next_item_size as f64 - pr) * 0.3;
        }
        // Harmonic class match: next item and post residual share a class
        if next_item_size % 10 == post_residual % 10 && next_item_size <= post_residual {
            score -= 4.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Penalize spreading across many open bins lightly; prefer filling
    // bins with low residual (tighter packing).
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // New-bin candidate handling: opening a new bin is only attractive when
    // no open bin fits well. The empty-bin call has post_residual == capacity.
    if bin_residual == bin_capacity {
        // Base reluctance to open new bins
        score = cap + 25.0;
        // If the current item is large, a fresh bin is reasonable
        score -= (item_size as f64 / cap) * 10.0;
        // If few bins can fit the item, opening a new bin is less wasteful
        if fitting_bins_count <= 1 {
            score -= 20.0;
        }
        // Late in the stream, avoid opening bins for marginal gains
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 10.0;
        // If next item is small, it could share the new bin efficiently
        if next_item_size > 0 && next_item_size <= 20 {
            score -= 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that cannot hold the smallest
    // plausible item (<=10) are pure waste; penalize them quadratically.
    if post_residual < 10 {
        score += (post_residual as f64 + 1.0) * 8.0;
    }

    // Penalize small-but-usable gaps less than the lookahead need.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    // Reward exact or near-exact fits.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, encourage
    // filling; few open bins -> tolerate new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln() * (1.0 + progress);
    score += pressure * 2.0;

    // New-bin candidate: allow opening when existing residuals are poor fits
    // (item leaves large gap or bin barely fits). Baseline neutral cost.
    if bin_residual == bin_capacity {
        score += 8.0 + pressure;
        // Opening a new bin is attractive if the item would leave a big
        // unusable-ish gap in any existing bin anyway.
        if post_residual >= 60 {
            score -= 10.0;
        }
        if next_item_size > 0 && next_item_size >= item_size && item_size <= 40 {
            score -= 4.0;
        }
    } else {
        // Prefer bins whose residual is close to the item (tight fit).
        let tightness = (bin_residual as f64 - item_size as f64).abs();
        score += tightness * 0.05;
        // Favor bins below mean residual (already well filled).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (low post_residual)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 20.0 * tightness * tightness;

    // Exact-fit bonus
    if post_residual == 0 {
        score -= 100.0;
    }

    // 2-step lookahead: reward if next item fits exactly or well into post_residual
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_fit = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - next_fit / (bin_capacity as f64));
    } else if next_item_size > 0 {
        // next item cannot fit here: penalize leaving a gap sized near next_item_size (wasted dead space)
        let gap = post_residual as f64;
        if gap > 0.0 && (next_item_size as f64) > gap {
            score += 8.0 * (1.0 - gap / (next_item_size as f64));
        }
    }

    // Penalize bins whose residual is far below mean (already fragmented)
    let dev = (bin_residual as f64) - mean_residual;
    if dev < 0.0 {
        score += 0.3 * (-dev);
    } else {
        score -= 0.1 * dev;
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: keep it neutral-to-slightly-costly so it's chosen only when
    // no open bin offers a decent fit. Cost grows with number of open bins.
    if bin_residual == bin_capacity {
        score += 25.0 + 2.0 * (open_bins_count as f64);
    }

    // Mild preference to fill older/fuller bins early in the stream
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 3.0 * (1.0 - progress) * (bin_residual as f64) / (bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero is ideal.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 24.0 * tight * tight;

    // Penalize dead space that cannot hold the next item (lookahead coupling).
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 12.0 + (next_item_size - post_residual) as f64 * 0.35;
        } else {
            // Bonus when the next item fits snugly in the leftover space.
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Penalize spreading across many open bins when alternatives exist.
    if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64).ln();
    }

    // Encourage consolidation when mean residual is high (bins are fragmented).
    score += 0.15 * mean_residual;

    // Time horizon: late in the stream, be more conservative (prefer filling existing bins).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // New empty bin: open it only when the fit into existing bins is poor
    // (large post_residual) or few bins can fit the item early on.
    if bin_residual == bin_capacity {
        score += 18.0;
        if post_residual as f64 > 0.6 * bin_capacity as f64 {
            score -= 15.0; // large item: new bin is fine
        }
        if fitting_bins_count == 1 && progress < 0.7 {
            score -= 10.0;
        }
    }

    // Prefer bins whose residual is already small relative to the mean.
    score += 0.08 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    let mut score = pr as f64;

    // Non-linear penalty on residual: small residuals are dead space, penalize quadratically
    score += 40.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * norm_pr;

    // Reward tight fits more strongly as the stream progresses
    let tight = 1.0 - norm_pr;
    score -= 25.0 * tight * tight * (0.3 + 0.7 * progress);

    // Last-chance bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * progress;
    } else if fitting_bins_count > 1 {
        score += 5.0 * (fitting_bins_count as f64 - 1.0).ln();
    }

    // Lookahead coupling: reward bins whose post-residual can host the next item
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64 / cap;
        score -= 18.0 * (1.0 - slack * slack);
    } else if next_item_size > 0 {
        score += 8.0 * (next_item_size as f64 / cap);
    }

    // Discourage spreading across many open bins; prefer filling existing ones
    score += 2.0 * (open_bins_count as f64).ln() * (1.0 - progress);

    // New-bin candidate: penalize slightly unless residual waste elsewhere is large
    if bin_residual == bin_capacity {
        score += 12.0 - 10.0 * (mean_residual / cap) * (1.0 - progress);
    }

    // Mean-residual alignment: prefer bins near the mean residual (balanced packing)
    let dev = (pr - mean_residual) / cap;
    score += 6.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: waste classes modulo small divisors.
    // Residuals that are "dead" (very small, unusable) should be penalized.
    let dead = post_residual < 10;
    if dead {
        score += 25.0; // unusable sliver
    }

    // Reward residuals that are multiples of 10 (harmonic with capacity 100)
    if post_residual % 10 == 0 {
        score -= 4.0;
    }
    if post_residual % 25 == 0 {
        score -= 4.0;
    }
    if post_residual % 50 == 0 {
        score -= 3.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
        // exact fit for the next item
        if post_residual == next_item_size {
            score -= 12.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item cannot use this residual: mild penalty scaled by leftover class
        let waste_class = (post_residual / 10) as f64;
        score += 2.0 + waste_class * 0.3;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // current item fits poorly everywhere (large dead space would result).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score += 12.0;
        // If item would leave a harmonic residual in a fresh bin, discount opening
        let pr = bin_capacity - item_size;
        if pr % 10 == 0 { score -= 6.0; }
        if pr % 25 == 0 { score -= 4.0; }
        // If no open bin fits at all, opening is necessary
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // Late in stream, prefer reusing existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        // Many open bins already: discourage opening
        score += open_bins_count as f64 * 0.5;
    }

    // Prefer bins whose residual is close to mean (balanced packing) mildly
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Tight-fit bonus: item fills most of the bin
    let fill = item_size as f64 / bin_capacity as f64;
    score -= fill * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size (1..100
    // interface, but treat small gaps as unusable) are pure waste.
    if post_residual > 0 {
        // gap smaller than a plausible future item => heavy dead-space penalty
        if post_residual < 10 {
            score += 60.0;
        } else if post_residual < 20 {
            score += 25.0;
        } else if post_residual < 35 {
            score += 8.0;
        } else {
            // large gaps are reusable; mild reward relative to baseline
            score -= 5.0;
        }
    } else {
        // perfect fill: strongly reward
        score -= 80.0;
    }

    // Tightness reward: fraction of the bin consumed by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill;

    // Pressure from many open bins: prefer packing into existing bins
    // rather than spreading; penalize when open bins are already numerous.
    score += 3.0 * open_bins_count as f64;

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: an empty bin is a fresh resource. Favor it
    // only when the item would leave a bad gap in every existing bin.
    if bin_residual == bin_capacity {
        if post_residual < 10 {
            score -= 20.0; // item nearly fills a fresh bin -> good
        } else {
            score += 35.0 + 0.5 * open_bins_count as f64; // discourage wasteful opening
        }
    }

    // Lookahead: if the next item fits exactly in the resulting residual,
    // reward this placement; if the residual is just barely too small for
    // the next item, penalize slightly (near-miss gap).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual > next_item_size && post_residual - next_item_size < 10 {
            score += 15.0;
        }
    }

    // Mild preference for balancing residuals early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 2.0 * (post_residual as f64 - mean_residual).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are excellent: reward small post_residual strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        let pr = post_residual as f64;
        // Penalize dead space non-linearly; small leftovers are fine, large ones waste capacity.
        score += (pr * pr) / 200.0;

        // 2-step lookahead: if the next item fits exactly in the post-residual, big reward.
        if next_item_size > 0 {
            let n = next_item_size as f64;
            if n <= pr {
                let slack = pr - n;
                if slack == 0.0 {
                    score -= 300.0;
                } else {
                    score -= 150.0 * (1.0 - slack / pr);
                }
            } else {
                // Next item cannot follow into this bin: mild penalty, worse if gap is small.
                score += 30.0 * (1.0 - (n - pr) / 100.0);
            }
        }

        // Compare against mean residual: bins with residual near mean are "normal" targets;
        // placing into a bin with much larger residual than mean wastes its capacity.
        let dev = pr - mean_residual;
        score += 0.5 * dev;

        // Last-chance bin: strongly prefer using it to avoid opening a new bin.
        if fitting_bins_count == 1 {
            score -= 200.0;
        } else if fitting_bins_count > 2 {
            // Many alternatives: slight penalty to prefer the tightest fits via other terms.
            score += 5.0;
        }

        // Early in stream, keep bins flexible (avoid creating tiny unusable residuals);
        // later, prioritize consolidation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if pr > 0.0 && pr < 10.0 {
            score += 40.0 * (1.0 - progress);
        }

        // Many open bins: encourage filling existing ones rather than opening more.
        score -= 3.0 * open_bins_count as f64;
    }

    // New-bin candidate: prefer it only when this bin's placement would be very poor.
    if bin_residual == bin_capacity {
        // Empty bin baseline: neutral-ish score; open new bin if best open-bin score is worse.
        score = 60.0 + 0.3 * item_size as f64;
        if fitting_bins_count <= 1 {
            // No real alternative anyway; opening is fine.
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor small post-residual (especially exact fits).
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 60.0 * tight * tight;

    // Penalize small-but-unusable residuals: dead space that few future items can use.
    if post_residual > 0 {
        let dead = (post_residual as f64).ln().max(0.0);
        score += 8.0 * dead;
    }
    // Exact fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits into the post-residual, reward; otherwise penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            let waste = (next_item_size - post_residual) as f64;
            score += 0.25 * waste;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Fragmentation pressure: penalize placing into bins whose residual deviates from mean badly.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Progress-based horizon: late in the stream, prefer consolidating into few bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 0.15 * post_residual as f64;
    score -= progress * 5.0 * (open_bins_count as f64).ln().max(0.0);

    // New-bin candidate handling: only attractive when no open bin is a decent fit
    // (i.e., residual would be badly fragmented) or open bins are nearly full.
    if bin_residual == bin_capacity {
        let decent_fit = fitting_bins_count > 0 && post_residual <= bin_capacity / 3;
        if decent_fit {
            score += 25.0; // discourage opening new bin when a decent fit exists
        } else {
            score -= 10.0; // encourage fresh bin when fits are poor
        }
        score += 0.02 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_frac = item_size as f64 / cap;
    let norm_pr = pr / cap;

    // Base: waste created by this placement
    let mut score = norm_pr;

    // Smooth polynomial coupling of waste with stream progress:
    // later in the stream, waste becomes increasingly costly.
    let progress_cost = norm_pr * norm_pr * (0.5 + 2.0 * progress * (1.0 - progress) + 2.0 * progress);
    score += progress_cost;

    // Reward tight fits (small post_residual) with a smooth saturating bonus.
    let tight = (1.0 - norm_pr).powi(3);
    score -= 1.5 * tight * (0.5 + 0.5 * progress);

    // Penalize creating residual that is too small for typical future items:
    // smooth penalty when residual is in the "dead zone" (small but nonzero).
    let dead = norm_pr * (1.0 - norm_pr) * 4.0; // peaks at norm_pr = 0.5
    score += 0.3 * dead;

    // Lookahead coupling: reward residual that can host the next item,
    // penalize residual slightly below the next item size.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let fits_next = if pr as f64 >= n { 1.0 } else { 0.0 };
        let gap = ((n - pr) / cap).max(0.0);
        score -= 0.8 * fits_next * (pr / cap);
        score += 1.2 * gap * (1.0 - fits_next);
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 2.0;
    }

    // New-bin candidate: opening a bin is only attractive when the current
    // fit is poor (large post_residual) or few bins fit the item.
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-6;
    if is_new_bin {
        let poor_fit = (fitting_bins_count as f64).recip();
        score = 0.55 + 0.9 * poor_fit - 0.4 * (1.0 - norm_pr).powi(2) + 0.3 * progress;
        // If an existing bin would be nearly perfect, discourage the new bin.
        if norm_pr < 0.05 {
            score += 1.5;
        }
    }

    // Mild penalty for scattering across many open bins.
    score += 0.01 * (open_bins_count as f64).ln().max(0.0);

    // Mean-residual alignment: prefer bins whose residual is near the mean
    // (keeps bin states uniform, easier to combine later).
    score += 0.1 * ((pr - mean_residual) / cap).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core tightness reward: squared waste penalty.
    let waste = post_residual as f64;
    score += 0.02 * waste * waste / (bin_capacity as f64);

    // Harmonic class: quantize post_residual into capacity-fraction buckets.
    // Residuals in "dead zones" (small unusable slivers) are penalized.
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap; // in [0,1]
    let class = (frac * 8.0).floor() as i32; // 8 harmonic classes
    let class_mid = (class as f64 + 0.5) / 8.0;
    let dead_zone = (frac < 0.1) && (post_residual > 0);
    if dead_zone {
        score += 6.0; // sliver that almost nothing fits into
    }
    // Reward residuals near class boundaries where common item sizes fit.
    let _ = class_mid;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead coupling: if next item fits in post_residual, strong reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0 + 0.1 * (next_item_size as f64);
    } else if next_item_size > post_residual {
        // Next item won't fit here anyway; mild penalty for large leftover.
        score += 0.05 * (post_residual as f64 - mean_residual).abs();
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: default neutral-high; allow opening only
    // when current fit is terrible and many bins are already open.
    if bin_residual == bin_capacity {
        score = 45.0
            - 0.15 * (open_bins_count as f64)
            + (step_index as f64 / total_items.max(1) as f64) * 5.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 0.05 * (next_item_size as f64);
        }
        // If an existing bin gives a near-perfect fit, discourage new bin.
        if post_residual == 0 || fitting_bins_count == 1 {
            score += 30.0;
        }
    }

    // Modulo harmonic touch: residuals divisible by common item sizes (10,20,25,50)
    // are more reusable.
    if post_residual > 0 && (post_residual % 10 == 0 || post_residual % 25 == 0 || post_residual % 50 == 0) {
        score -= 3.0;
    }

    // Keep score finite and sane.
    if !score.is_finite() {
        score = post_residual as f64;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Dead-space avoidance: penalize small nonzero leftovers that are hard to fill.
    let pr = post_residual as f64;
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - pr) / 10.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 15.0 * (20.0 - pr) / 10.0;
    }

    // Reward leaving room for the lookahead item when it fits the residual.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if pr >= n && pr - n < 10.0 {
            score -= 25.0; // next item will nearly fill this bin
        } else if pr < n && pr < 10.0 {
            score += 10.0; // leftover too small for lookahead
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: mild penalty when many bins are open, encouraging consolidation.
    score += open_bins_count as f64 * 0.5;

    // Progress pressure: later in the stream, be slightly more conservative with new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 8.0 + 6.0 * progress; // new-bin candidate penalty
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward near-exact fits (small post_residual).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 500.0;
    } else {
        // Penalize dead space quadratically relative to capacity.
        score += (post_residual as f64 / bin_capacity as f64) * 60.0;
    }

    // 2-step lookahead: reward if next item fits exactly in the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            // Reward proportionally to how well next item uses the leftover.
            let waste = (post_residual - next_item_size) as f64;
            score -= 200.0 - waste * 1.5;
        } else {
            // Next item cannot fit here: penalize leaving medium gaps that trap nothing.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.8;
        }
    }

    // Relative-to-mean coupling: bins with residual far below mean are tighter; prefer filling them.
    let dev = post_residual as f64 - mean_residual;
    score += dev * 0.5;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate: only attractive if all fits are poor (large post_residual).
    if bin_residual == bin_capacity {
        score += 120.0;
        // Early in stream, opening bins is cheaper; late, consolidate.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 100.0;
        // If next item is large, a fresh bin is valuable.
        if next_item_size > 60 {
            score -= 80.0;
        }
    }

    // Mild preference to keep open-bin count low.
    score += open_bins_count as f64 * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: normalized waste relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize residual that is too small to ever be useful (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward if the next item fits perfectly in the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect pairing
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here anyway; slight penalty for large leftovers.
            score += (post_residual as f64 - mean_residual).abs() * 0.1;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate logic: opening a new bin should only win when the fit
    // into existing bins is poor. An empty-bin call has post_residual == bin_capacity - item_size.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Penalize opening bins when many open bins exist and mean residual is large.
        score += 15.0 + 0.5 * mean_residual + open_bins_count as f64 * 2.0;
        // Early in the stream, opening bins is cheap and useful.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
        // If item is large relative to mean residual, opening fresh is fine.
        if (item_size as f64) > mean_residual {
            score -= 10.0;
        }
    } else {
        // Favor bins whose residual is below mean residual (denser bins first).
        score += (mean_residual - bin_residual as f64) * 0.2;
    }

    // Mild pressure to consolidate: prefer bins with less residual overall.
    score += bin_residual as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let r = post_residual as f64;
    let cap = bin_capacity as f64;
    let rn = r / cap; // normalized post residual
    let mut score = r;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = rn * rn * (1.0 - progress) + rn * progress * (1.0 - rn);
    score += 8.0 * poly * cap * 0.1;

    // Reward tight fits more strongly as the stream progresses
    let tightness = 1.0 - rn;
    score -= tightness * tightness * (1.0 + 3.0 * progress) * 6.0;

    // Penalize dead space that cannot serve the lookahead item
    if next_item_size > 0 {
        let gap = r - (next_item_size as f64).min(r);
        if gap > 0.0 && next_item_size as f64 > r {
            score += 4.0 * (1.0 - (next_item_size as f64 - r) / cap);
        } else if next_item_size as f64 <= r {
            score -= 3.0 * (1.0 - gap / cap);
        }
    } else {
        // last item: strongly prefer minimal residual
        score -= 10.0 * tightness;
    }

    // Last-chance bin: discourage opening a new bin
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Mild pressure to consolidate when many bins are open
    score += 0.05 * open_bins_count as f64 * rn;

    // Deviation from mean residual: prefer bins near the mean to keep balance
    score += 0.3 * (r - mean_residual).abs() / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Harmonic class of post_residual: capacity fractions /5
    let frac = post_residual as f64 / cap;
    let class = (frac * 5.0).floor(); // 0..5 harmonic class
    // Reward tight fits: post_residual in lowest class
    score -= (5.0 - class) * 8.0;

    // Dead-space penalty: residual too small for any plausible item (1..100 unknown, use 10 threshold)
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Modulo-arithmetic coupling: post_residual % 10 bonus (harmonic residue)
    score -= (post_residual % 10) as f64 * 0.5;

    // Lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0;
        if post_residual == next_item_size {
            score -= 20.0;
        }
    } else if next_item_size > post_residual {
        score += 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Prefer bins with residual near mean (balance), penalize extremes mildly
    score += ((post_residual as f64 - mean_residual).abs()) * 0.15;

    // New-bin candidate handling: make empty bin attractive only when fits are poor
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = post_residual as f64 + 18.0 - progress * 10.0;
        if fitting_bins_count <= 1 {
            score -= 10.0;
        }
        if item_size > bin_capacity / 2 {
            score -= 6.0;
        }
    }

    // Small progression-based tightening: later in stream, prefer tighter fits more
    score -= (step_index as f64 / total_items.max(1) as f64) * (100.0 - post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // Small unusable gaps are penalized super-linearly: a residual that is
    // positive but tiny is worse than a moderately large residual, because it
    // is unlikely any future item (sizes 1..100) will ever fill it.
    let dead_threshold = 12.0;
    let pr = post_residual as f64;
    if pr > 0.0 && pr < dead_threshold {
        let gap = dead_threshold - pr;
        score += 2.0 * gap * gap; // quadratic dead-space penalty
    }
    // Exact-zero residual is a perfect close: strong reward.
    if post_residual == 0 {
        score -= 20.0;
    }

    // --- Lookahead coupling (k=2) ---
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Residual is dead with respect to the very next item.
            score += 8.0;
        } else if post_residual == next_item_size {
            // Residual exactly absorbs the next item: near-perfect pipeline.
            score -= 15.0;
        }
    }

    // --- Last-chance pressure ---
    // If this is the only open bin that fits the item, using it avoids
    // fragmentation; strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // --- Open-bins-count pressure ---
    // Penalize opening yet another bin, with pressure growing with the number
    // of already-open bins (fragmentation control). Only the brand-new empty
    // bin candidate pays this, so it only wins when fits into open bins are
    // truly poor (large/dead post_residuals).
    if bin_residual == bin_capacity {
        score += 3.0 + open_bins_count as f64 * 0.7;
    }
    // Mild uniform consolidation pressure (cancels among open bins, but
    // reinforces the new-bin penalty under heavy fragmentation).
    score += open_bins_count as f64 * 0.05;

    // --- Residual-vs-mean coupling ---
    // Favor bins whose post_residual sits below the current mean residual
    // (i.e., tighter-than-average packs).
    if pr < mean_residual {
        score -= 0.3 * (mean_residual - pr).min(20.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual equals next item size exactly -> strong reward
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs();
        // Exact match reward
        if diff == 0 {
            score -= 60.0;
        } else if (next_item_size as u32) <= post_residual {
            // next item fits after this placement: reward closeness to exact fit
            score -= 40.0 * (1.0 - diff as f64 / bin_capacity as f64);
        } else {
            // next item won't fit: penalize if we leave a large but unusable-for-next gap
            score += 8.0;
        }

        // Near-match bonus within small slack window
        if diff > 0 && diff <= 5 {
            score -= 20.0;
        }
    } else {
        // Last item: prefer tightest fit (smallest post_residual) — already baseline
        score -= 5.0;
    }

    // Penalize tiny dead space (< 10) that is unlikely usable later
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only open a new bin when current fit is very poor
    if bin_residual == bin_capacity {
        // Baseline penalty so new bins are used only when beneficial
        score += 30.0;
        // Opening a new bin is more attractive early in the stream (more future items)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);
        // Attractive if next item is large and current best residual is small
        if next_item_size > 0 && next_item_size > post_residual {
            score -= 15.0;
        }
    }

    // Compare against mean residual: bins already tight are better targets
    if mean_residual > 0.0 {
        let tightness = 1.0 - (post_residual as f64 / mean_residual).min(2.0) / 2.0;
        score -= 10.0 * tightness;
    }

    // Slight penalty for spreading across too many open bins
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        let fit_ratio = item_size as f64 / bin_residual as f64;
        score -= 60.0 * fit_ratio * fit_ratio;
    }

    // Penalize dead space that cannot fit a plausible future item.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // tiny unusable sliver
    }

    // Lookahead coupling: reward if next item fits the post-residual, penalize otherwise.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 25.0 + 0.5 * next_item_size as f64;
        } else {
            score += 8.0 + 0.2 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: only attractive when existing bins fit poorly or are scarce.
    if bin_residual == bin_capacity {
        let scarcity = (fitting_bins_count == 0) as i32 as f64;
        let pressure = mean_residual / bin_capacity as f64;
        let mut new_bin_score = 120.0 - 80.0 * scarcity - 100.0 * pressure - 30.0 * (1.0 - progress);
        // If no bin fits, opening a new bin is mandatory-ish.
        if fitting_bins_count == 0 {
            new_bin_score -= 200.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        new_bin_score += 60.0 * progress;
        return new_bin_score;
    }

    // Mild penalty for spreading across many open bins when mean residual is high.
    score += 0.05 * open_bins_count as f64 * (mean_residual - post_residual as f64).abs() / bin_capacity as f64;

    // Prefer bins with below-average residual (denser bins) to keep empties available.
    score += 0.3 * (post_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_post = post / cap;

    // Base: prefer tight fits (low post_residual), with a smooth non-linear shaping.
    let tightness = norm_post * norm_post;
    let mut score = post * (1.0 + 0.8 * tightness);

    // Smooth coupling with stream progress: early on, tolerate slack; later, demand tightness.
    score += 30.0 * progress * (1.0 - (1.0 - norm_post) * (1.0 - norm_post));

    // Penalize post_residual that cannot accommodate the lookahead item (dead space),
    // smoothly scaled by how much it just barely fails.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post < nxt {
            let shortfall = (nxt - post) / cap;
            score += 25.0 * shortfall * (1.0 + progress);
        } else {
            // Reward leaving exactly usable space for the next item.
            let usable = 1.0 - ((post - nxt) / cap);
            score -= 10.0 * usable * usable;
        }
    }

    // Last-chance bin: strongly reward using it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0 * (1.0 - norm_post);
    }

    // New-bin candidate: penalize opening a new bin, more so as the stream progresses
    // and when open bins still have reasonable residual capacity.
    if bin_residual == bin_capacity {
        let open_pressure = if open_bins_count > 0 {
            (mean_residual / cap).min(1.0)
        } else {
            0.0
        };
        score += 15.0 + 45.0 * progress + 30.0 * open_pressure;
    }

    // Mild penalty for spreading across many open bins (consolidation pressure).
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * norm_post;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: classify post_residual into
    // capacity-fraction buckets (dead-space bands).
    let c = bin_capacity as f64;
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;

    // Reward tight fits strongly (small post_residual is good).
    if post_residual == 0 {
        score -= 50.0; // perfect closure
    } else if post_residual <= eighth {
        score -= 18.0; // near-perfect fit
    } else if post_residual <= quarter {
        score -= 8.0; // usable small gap
    } else if post_residual <= bin_capacity / 2 {
        score -= 2.0;
    } else {
        // Large leftover: penalize if it falls in a "dead zone" that few
        // future item sizes (1..100) can fill efficiently.
        score += 6.0;
    }

    // Modulo-arithmetic harmonic classes: leftover congruent to small
    // residues mod 10 tend to be unusable dead space.
    let m = post_residual % 10;
    if m > 0 && m < 5 {
        score += 4.0; // awkward sliver
    } else if m == 0 {
        score -= 3.0; // round leftover, more reusable
    }

    // Lookahead coupling: if next item fits exactly into the leftover,
    // strongly favor this bin (2-chain harmonic).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            let nxt_left = post_residual - next_item_size;
            if nxt_left <= eighth {
                score -= 12.0;
            } else {
                score -= (post_residual - next_item_size) as f64 * 0.05;
            }
        } else {
            // Next item cannot use this bin's leftover: slight penalty
            // proportional to how much space would be stranded.
            score += (next_item_size - post_residual) as f64 * 0.02;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: prefer keeping it closed early in the stream;
    // allow opening new bins more freely as the stream progresses when
    // many bins are open and mean residual is small (fragmented state).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual / c).clamp(0.0, 1.0);
        let openness = progress * 0.5 + (1.0 - fragmentation) * 0.3
            + (open_bins_count as f64).ln().max(0.0) * 0.05;
        score += 25.0 - openness * 20.0;
    } else {
        // Prefer bins whose residual is below mean (fill fuller bins first).
        let diff = bin_residual as f64 - mean_residual;
        score += diff * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small to hold the smallest plausible item are wasted.
    let min_item = 1u32;
    if post_residual < min_item {
        score -= 50.0; // perfect fill, best possible outcome
    } else if post_residual <= 10 {
        // Unusable-ish tiny gap: strong penalty so bins that seal themselves are favored
        // only if they beat other options... actually small gap is bad: penalize.
        score += 40.0 * (1.0 - post_residual as f64 / 10.0);
    } else if post_residual <= 25 {
        // Medium dead zone: moderately bad, scales down as gap grows
        score += 15.0 * (25.0 - post_residual as f64) / 15.0;
    }

    // Reward leaving room for the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.1 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        // Lookahead won't fit here either way; slight penalty if gap is just barely too small
        if post_residual >= next_item_size * 3 / 4 {
            score += 8.0;
        }
    }

    // Last-chance pressure: if this is the only fitting bin, prefer using it over new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Open bins pressure: many open bins -> favor filling existing ones, avoid opening more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.15 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Prefer bins tighter than the average residual (good fit indicator).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // New-bin candidate: make empty bins mildly unattractive unless current bins fit badly.
    if bin_residual == bin_capacity {
        score += 30.0 + 2.0 * open_bins_count as f64;
        // But if no open bin can fit, the new bin call will naturally win.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Slight reward for high fill ratio of this bin.
    score -= 0.2 * (item_size as f64 / bin_capacity as f64) * 100.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward near-exact fits (small post_residual).
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 100.0;
    } else if post_residual <= 10 {
        score -= 40.0;
    }

    // Aggressive 2-step lookahead: reward when the next item fits
    // exactly into the post_residual (perfect chain).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        let gap = (pr - nxt).abs();
        if nxt <= pr {
            // Next item fits: reward closeness to a perfect chain.
            score -= 60.0 * (1.0 - gap / bin_capacity as f64);
            if gap == 0.0 {
                score -= 80.0; // perfect 2-item chain
            }
        } else {
            // Next item would not fit here; penalize large leftover
            // dead space relative to the upcoming item.
            score += 0.3 * gap;
        }

        // Coupling with mean residual: prefer bins whose post_residual
        // tracks the stream's typical leftover scale.
        let dev = (pr - mean_residual).abs();
        score += 0.15 * dev;
    }

    // Last-chance bin: if this is the only bin that fits, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 70.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive
    // early in the stream or when few bins are open; otherwise penalize
    // it so we prefer packing into existing bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let openness = (open_bins_count as f64).ln().max(1.0);
        score += 90.0 * (1.0 - progress) * (1.0 / openness);
        // But if no existing bin fits well (post_residual would be large
        // elsewhere), a fresh bin with room for the next item is good.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 55.0;
        }
    }

    // Mild penalty for leaving residuals in the "awkward" zone
    // (too small for typical items 10..80 relative to capacity).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: penalize residuals that waste capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * tightness * tightness;

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    }

    // Lookahead: if the next item fits the post-residual, this is a great chain placement.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 20.0;
        } else {
            // Penalize leaving a residual just barely too small for the next item (dead space).
            let gap = (next_item_size as f64 - post_residual as f64).max(0.0);
            if gap < 10.0 {
                score += 12.0;
            }
        }
    }

    // Last-chance bin: heavily favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // When many bins are open, consolidate; when few, spreading is cheaper.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let consolidation = 1.0 + progress;
    score += (open_bins_count as f64).sqrt() * 2.0 * consolidation * tightness;

    // Prefer bins whose residual deviates from the mean (keep a diverse size portfolio).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score -= 0.3 * dev;

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 0.0 } else {
            (post_residual as f64).min(40.0) + (fitting_bins_count as f64 - 1.0) * 5.0
        };
        score += 35.0 + desperation;
        // Late in the stream, opening a fresh bin is less costly.
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: quadratic waste coupling with stream progress
    let mut score = pr * (1.0 + 1.5 * progress) + 40.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= 60.0 * tightness * tightness * (0.3 + 0.7 * progress);

    // Lookahead: favor residuals that can host the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 12.0 * (1.0 - (nx / cap)) * (0.4 + 0.6 * progress);
        } else {
            score += 8.0 * (nx - pr) / cap;
        }
    }

    // Last-chance bin: penalize skipping it (opening new bin is costly)
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0 * (0.5 + 0.5 * progress);
    }

    // Many open bins: prefer consolidating into existing capacity
    score += 2.0 * (open_bins_count as f64).ln().max(0.0) * norm_pr;

    // New-bin candidate: penalize unless existing fits are bad
    if bin_residual == bin_capacity {
        score += 18.0 + 10.0 * (1.0 - progress);
    }

    // Mean-residual deviation coupling
    score += 0.3 * (pr - mean_residual).abs() / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: which residue class mod 10 it falls into.
    let post = post_residual as u32;
    let class = (post % 10) as f64;

    // Dead-space penalty: tiny post_residual is great, but awkward classes (1..9 mod 10)
    // leave slivers that rarely fit future items (sizes 1..100).
    if post == 0 {
        score -= 60.0; // perfect fit
    } else if post <= 5 {
        score += 15.0; // unusable sliver
    } else {
        // Reward post residuals that are multiples of common size classes (10,20,25,50).
        if post % 10 == 0 { score -= 12.0; }
        if post % 25 == 0 { score -= 6.0; }
        if post % 50 == 0 { score -= 4.0; }
        // Penalize odd slivers in the awkward 1..9 band of each decade.
        score += class * 0.4;
    }

    // Lookahead coupling: if the next item fits the post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 40.0; // exact chain fit
        } else if next_item_size <= post {
            let slack = (post - next_item_size) as f64;
            score -= 20.0 - 0.25 * slack; // tighter lookahead fit preferred
        } else {
            score += 8.0; // next item won't fit here anyway
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // New-bin candidate handling: opening a bin is only good when current fit is bad
    // and there is slack in the stream.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Base cost of opening a new bin.
        score = cap * 0.75;
        // Early in the stream, a fresh bin is more acceptable.
        score -= 25.0 * (1.0 - progress);
        // If this bin is the only fitting option, new bin is less attractive.
        if fitting_bins_count <= 1 {
            score += 30.0;
        }
        // If mean residual is large, prefer existing bins.
        score += (mean_residual - cap * 0.4).max(0.0) * 0.3;
        // Small items pair well with a fresh bin.
        if item_size <= bin_capacity / 2 {
            score -= 10.0;
        }
    }

    // Mild preference for tighter existing bins overall.
    score += (bin_residual as f64 - post_residual as f64) * 0.0; // no-op guard
    score -= (bin_capacity - bin_residual) as f64 * 0.05; // favor fuller bins

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever be
    // useful (below the minimum plausible item size) are heavily penalized.
    let min_item = 1u32;
    let dead_threshold = 10u32;
    if post_residual < dead_threshold {
        // Dead space: this residual can essentially never be filled.
        score += 40.0 + (dead_threshold - post_residual) as f64 * 3.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    } else {
        // Progressive waste penalty: superlinear in how much capacity is wasted
        // relative to the bin, but only when the gap is "small-ish".
        let waste_ratio = post_residual as f64 / bin_capacity as f64;
        if waste_ratio < 0.25 {
            score += waste_ratio * waste_ratio * 50.0;
        }
    }

    // Coupling with lookahead: if the next item fits exactly in the post
    // residual, this is an excellent chaining opportunity -> reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack < dead_threshold {
            // Next item nearly fills the bin afterwards: excellent.
            score -= 25.0;
        } else {
            score -= 8.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 && post_residual < dead_threshold {
        // Next item cannot use the tiny residual either: double penalty.
        score += 15.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing
    // bins rather than opening more; scale with fraction of stream completed.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = open_bins_count as f64 * (0.3 + 0.7 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportional to open-bin pressure so that
        // opening a new bin only wins when existing fits are truly bad.
        score += 55.0 + pressure;
    } else {
        score -= pressure.min(20.0);
    }

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is already tight -> good to fill it further.
    let residual_gap = mean_residual - bin_residual as f64;
    if residual_gap > 0.0 {
        score -= residual_gap * 0.15;
    } else {
        score += (-residual_gap) * 0.05;
    }

    // Tie-break: slight preference for tighter fits regardless of everything.
    score += post_residual as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits exactly into post residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Perfect match for next item is highly desirable.
            score -= 30.0 * (1.0 - slack / bin_capacity as f64);
            // Extra penalty the tighter the combined fit.
            let combined = (item_size + next_item_size) as f64 / bin_capacity as f64;
            score -= 20.0 * combined;
        } else {
            // Next item cannot use the residual; penalize large unusable leftovers.
            let unusable = if next_item_size > post_residual { post_residual as f64 } else { 0.0 };
            score += 0.3 * unusable;
        }
    } else {
        // Last item: prefer fullest packing.
        score -= 10.0 * (item_size as f64 / bin_capacity as f64);
    }

    // Favor bins whose residual deviates favorably from mean residual (tight bins).
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score -= 8.0 * dev;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize opening new bins when open bins can fit, scaled by stream progression.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 15.0 + 10.0 * progress;
        // Allow new bin only when item is large and nothing fits well.
        if item_size as f64 > 0.8 * bin_capacity as f64 {
            score -= 12.0;
        }
    }

    // Small preference for high fill ratio of current placement.
    score -= 5.0 * (item_size as f64 / bin_capacity as f64);

    // Slight penalty for spreading across too many open bins.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress of the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness of this fit: fraction of the bin's residual consumed by the item.
    let fit_ratio = if bin_residual > 0 { item_size as f64 / bin_residual as f64 } else { 1.0 };

    // Reward tight fits (substantial discount for near-perfect packing).
    score -= 60.0 * fit_ratio * fit_ratio;

    // Penalize large dead space relative to capacity, nonlinearly.
    let dead = post_residual as f64 / bin_capacity as f64;
    score += 25.0 * dead * dead;

    // Lookahead coupling: if the next item fits into the post-residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain_fit = next_item_size as f64 / post_residual as f64;
        score -= 35.0 * chain_fit;
    } else if next_item_size > 0 {
        // Next item cannot follow into this bin: mild penalty scaled by wasted potential.
        score += 8.0 * (next_item_size as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using the only bin that fits the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Crowding penalty: when many bins are open, prefer consolidating into existing bins.
    let crowding = open_bins_count as f64 / (1.0 + mean_residual.max(1.0));
    score += 0.5 * crowding * (1.0 - progress);

    // Late in the stream, discourage opening new bins; early on, allow exploration.
    if bin_residual == bin_capacity {
        // New-bin candidate: base penalty that grows with progress and with the number of open bins.
        score += 30.0 * progress + 2.0 * open_bins_count as f64;
        // But if the item is large and would leave little room anyway, opening a fresh bin is fine.
        score -= 20.0 * (item_size as f64 / bin_capacity as f64);
        // If no existing bin can fit the item, opening a new bin is the only option.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // If the next item is huge, a fresh bin with room for it is attractive.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 15.0;
        }
    }

    // Global residual balance: prefer bins whose residual is close to the mean (keeps bins uniform).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Small bonus for perfectly filling a bin.
    if post_residual == 0 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Normalized post-residual and its smooth non-linear couplings
    let x = pr / cap; // in [0,1)
    let mut score = 100.0 * x;

    // Strong convex penalty for large residuals: dead space grows quadratically
    score += 60.0 * x * x;

    // Cubic term: extra pressure against wasteful placements as stream progresses
    score += 40.0 * x * x * x * (0.5 + progress);

    // Tight fit reward: subtract when post_residual is small (smooth, non-piecewise)
    let tightness = (-10.0 * x).exp(); // ~1 for tight fits, ~0 for loose
    score -= 25.0 * tightness * (1.0 + progress);

    // Lookahead coupling: reward if next item fits into post_residual smoothly
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let fill_after_next = (pr - next_item_size as f64) / cap;
        score -= 20.0 * (1.0 - fill_after_next) * (1.0 - progress * 0.5);
    } else if next_item_size > 0 {
        // Smooth penalty proportional to how badly next item misses
        let miss = ((next_item_size as f64 - pr) / cap).min(1.0);
        score += 15.0 * miss * miss;
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0 * (1.0 - x);
    }

    // New-bin candidate: penalize mildly when open bins fit well, reward when
    // mean residual across open bins is already fragmented
    if bin_residual == bin_capacity {
        let frag = if open_bins_count > 0 { (mean_residual / cap).clamp(0.0, 1.0) } else { 0.0 };
        score += 35.0 * (1.0 - frag) * (1.0 - progress * 0.3);
        score -= 10.0 * frag * frag;
    }

    // Mild preference to consolidate into fewer bins
    score += 0.5 * (open_bins_count as f64).ln().max(0.0) * x;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual).
    let tight = post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * (-8.0 * tight).exp();

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Penalize dead space that cannot plausibly be filled later.
    if post_residual > 0 {
        let dead = (post_residual as f64 / 10.0).powi(2);
        score += 0.15 * dead;
    }

    // Harmonic class coupling: if next item fits exactly in the post residual,
    // this bin is an excellent chain candidate.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // Next item won't fit here: mild penalty proportional to overflow gap.
            score += 0.2 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current fit is bad.
    if bin_residual == bin_capacity {
        score += 20.0;
        if post_residual >= 40 {
            score += 15.0; // wasteful to open a bin for a small item
        }
        if fitting_bins_count == 0 {
            score -= 60.0; // no alternative
        }
    }

    // Favor bins with residual below mean (consolidating fuller bins).
    score += 0.5 * ((bin_residual as f64 - mean_residual) / bin_capacity as f64);

    // Slight preference to fill older bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 2.0 * progress * (1.0 - tight);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    let mut score = post;

    // Strict dead-space avoidance: residuals below the minimum item size are pure waste.
    let dead_zone = 1.0; // any residual < 1 is impossible; residuals 1..min_item are near-dead
    if post_residual > 0 {
        // penalize unusable gaps quadratically; worst near residual ~ min item size
        let unusable = (dead_zone - post / cap).abs();
        score += 8.0 * (post / cap) * (1.0 - post / cap);
        if post_residual < 10 {
            score += 15.0; // tiny gap = dead space forever
        }
    } else {
        // perfect fit reward
        score -= 10.0;
    }

    // Reward tight fits: fraction of bin consumed by this item
    let fill_ratio = item / cap;
    score -= 12.0 * fill_ratio * fill_ratio;

    // Reward using bins that are already mostly full (best-fit flavor)
    let residual_ratio = bin_residual as f64 / cap;
    score += 6.0 * residual_ratio;

    // Open-bin pressure: discourage spreading across many bins
    score += 0.35 * open_bins_count as f64;

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate logic: only attractive when nothing fits well
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // base penalty so we prefer existing bins unless fit is terrible
        score += 5.0;
        // if existing bins would leave very small post_residual, opening new bin is fine
        if post_residual >= 0 && fitting_bins_count > 0 {
            let best_possible_waste = post; // for the new bin itself
            // if the new bin's post_residual is large (item small), penalize more
            score += 4.0 * (post / cap);
        }
        // early in stream, allow opening bins more freely
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 6.0 * (1.0 - progress);
    } else {
        // existing bin: penalize if this placement would strand a gap that next item can't use
        if next_item_size > 0 {
            let nxt = next_item_size as f64;
            if post > 0.0 && post < nxt {
                score += 10.0 * (1.0 - post / nxt); // gap too small for the next item
            } else if post >= nxt {
                score -= 4.0 * (nxt / cap); // next item can slot in nicely
            }
        }
    }

    // mild alignment with mean residual: prefer bins below mean (more full)
    score += 0.5 * (mean_residual - bin_residual as f64).max(0.0) * 0.0
          + 0.3 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // --- 2-step lookahead matching: reward post_residual close to next_item_size ---
    if next_item_size > 0 {
        let post = post_residual as f64;
        let nxt = next_item_size as f64;
        // Exact match is ideal: next item fills bin perfectly.
        let match_gap = (post - nxt).abs();
        // Strong reward for tight match; decayed by how far off we are.
        score -= 40.0 * (-match_gap / 8.0).exp();
        // Extra bonus for an exact fit of the next item (perfect packing).
        if post_residual == next_item_size {
            score -= 60.0;
        }
        // Penalize leaving residual that is slightly larger than next item
        // (awkward dead space the next item cannot use).
        if post_residual > next_item_size && post_residual < next_item_size + 10 {
            score += 15.0;
        }
        // Reward residual exactly consumed by next item relative to capacity.
        if post_residual >= next_item_size {
            let waste_after_next = post_residual - next_item_size;
            score += 0.25 * waste_after_next as f64;
        }
    } else {
        // Last item: minimize leftover waste only.
        score += 0.5 * post_residual as f64;
    }

    // --- Relative-to-mean coupling: prefer bins deviating from mean residual ---
    let post_f = post_residual as f64;
    let mean = if mean_residual.is_finite() { mean_residual } else { post_f };
    let deviation = post_f - mean;
    // Bins with residual below mean are already "tight" -> good to keep filling them.
    if deviation < 0.0 {
        score -= 0.3 * (-deviation);
    } else {
        // Bins with residual above mean: mildly penalize creating more slack.
        score += 0.15 * deviation;
    }

    // --- Last-chance bonus: if this is the only fitting bin, strongly prefer using it ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // --- New-bin candidate handling: opening a bin is costly; discourage unless ---
    // current bin fit is terrible (large post_residual) or no good match exists.
    let is_new_bin = bin_residual == bin_capacity && bin_capacity > 0;
    if is_new_bin {
        // Base penalty for opening a new bin.
        score += 45.0;
        // If post_residual of an existing bin is large relative to next item,
        // opening a fresh bin becomes more attractive: reduce the penalty.
        if next_item_size > 0 {
            let waste = post_residual as f64; // for new bin, post_residual == capacity
            let _ = waste;
            // Compare against what existing bins would leave: use mean_residual as proxy.
            let proxy_post = mean - item_size as f64;
            if proxy_post > next_item_size as f64 + 15.0 {
                score -= 55.0; // existing bins leave bad residuals -> open new bin
            }
        }
        // Late in the stream, opening new bins is fine (no future amortization needed).
        score -= 20.0 * progress;
    }

    // --- Tightness reward: the fuller the bin becomes, the better ---
    let fill_ratio = item_size as f64 / bin_capacity.max(1) as f64;
    score -= 25.0 * fill_ratio;

    // Small penalty scaling with number of open bins to discourage bin sprawl.
    score += 0.5 * open_bins_count as f64;

    // Guard: residual waste penalty scaled late in the stream.
    score += 0.2 * progress * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Penalize creating unusable dead space: post_residual too small for the
    // smallest conceivable item (<=100) is pure waste, scaled by its size.
    if post_residual > 0 {
        let dead = if post_residual < 10 { 60.0 } else { 0.0 };
        score += dead * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Lookahead: reward if the next item also fits in the leftover space.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0 + 8.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // Leftover can't host the next item: mild penalty proportional to gap.
            score += 3.0 * (1.0 - (post_residual as f64 / next_item_size.max(1) as f64));
        }
    } else {
        // Last item in the stream: just minimize post_residual, no future value.
        score -= 5.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Global-state coupling: many open bins with high mean residual → prefer
    // consolidating into existing bins rather than spreading out.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let consolidation = (mean_residual - post_residual as f64).abs() / bin_capacity as f64;
    score += 6.0 * consolidation * (open_bins_count as f64).ln().max(1.0);
    score -= 8.0 * progress * (mean_residual / bin_capacity as f64);

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // no existing bin offers a decent fit. Give it a calibrated standing cost
    // so it wins only when all open bins would leave large waste.
    if bin_residual == bin_capacity {
        score = 55.0 + 0.15 * (post_residual as f64) - 25.0 * progress;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 10.0; // fresh bin can host the next item too
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear penalty on wasted residual: quadratic coupling with capacity fraction.
    let pr_frac = pr / cap;
    score += 12.0 * pr_frac * pr_frac * cap;

    // Reward tight fits: smooth coupling of fill ratio with stream progress.
    let fill = (bin_residual - post_residual) as f64 / cap;
    score -= (8.0 + 10.0 * progress) * fill * fill;

    // Lookahead coupling: penalize residual that neither fits the next item well nor is near zero.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            // Residual large enough for next item: mild reward proportional to usefulness.
            score -= 3.0 * (1.0 - ((pr - nx) / cap).abs());
        } else {
            // Dead space that can't host the next item: growing penalty with progress.
            score += (4.0 + 14.0 * progress) * (nx - pr) / cap;
        }
    }

    // Last-chance bin: strongly reward using the only fitting bin to avoid opening a new one.
    if fitting_bins_count == 1 {
        score -= 20.0 + 15.0 * progress;
    }

    // Penalize spreading across many open bins mildly; encourage consolidation early.
    score += 0.3 * open_bins_count as f64 * (1.0 - progress);

    // Deviation from mean residual: prefer bins whose post-residual is consistent with fleet state.
    score += 0.5 * (pr - mean_residual).abs();

    // New-bin candidate: make it attractive only when existing fits are very poor (large post_residual).
    if bin_residual == bin_capacity {
        score = 0.6 * cap - 2.0 * pr_frac * cap - 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: small post_residual strongly favored (non-linear).
    if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 15 {
        score -= 20.0;
    } else {
        // Harmonic class penalty: dead space in awkward residue classes is worse.
        let r = post_residual % 10;
        if r == 1 || r == 9 {
            score += 6.0;
        } else if r == 5 {
            score += 3.0;
        }
    }

    // Exact fill is perfect.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: if next item fits exactly in the post-residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size < post_residual {
            let rem = post_residual - next_item_size;
            if rem <= 5 {
                score -= 15.0;
            } else {
                score += (rem as f64) * 0.3;
            }
        } else {
            // next item cannot use residual; residual is likely dead space
            score += (post_residual as f64) * 0.15;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless no bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of a new bin ~ capacity worth of waste.
        score += 100.0;
        // Prefer new bin if existing bins would leave large dead space.
        let avg_dead = if fitting_bins_count > 0 { mean_residual } else { 0.0 };
        if post_residual == 0 {
            // exact fit in new bin (item == capacity) — irrelevant but harmless
            score -= 50.0;
        }
        // If the item is small relative to capacity, opening a bin wastes space.
        score += (bin_capacity - item_size) as f64 * 0.5;
        // If open bins have plenty of room (mean residual large), use them instead.
        score -= avg_dead * 0.4;
        // Late in stream, avoid opening new bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 20.0;
        // Few fitting bins and large item: new bin less bad.
        if fitting_bins_count == 0 {
            score -= 120.0;
        } else if fitting_bins_count == 1 {
            // handled above via last-chance; new bin still costly
        }
    }

    // Mild preference for fuller bins overall.
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
