    // Reward near-perfect fits (post_residual small but still usable).
    if post_residual >= 10 && post_residual <= 25 {
        score -= 60.0;
    }

    // Tightness reward: fraction of bin filled by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 40.0 * fill * fill;

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, big bonus.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < 10.0 {
            score -= 200.0;
        } else if slack < 30.0 {
            score -= 80.0;
        } else {
            score -= 20.0;
        }
    }
    // If next item would NOT fit in this bin's residual, mild penalty (better to
    // keep large residuals for large upcoming items).
    if next_item_size > post_residual && next_item_size > 0 {
        score += 15.0;
    }

    // Open-bin pressure: discourage scattering across many bins; but this pressure
    // must NOT override dead-space logic, so keep it moderate.
    score += 4.0 * open_bins_count as f64;

    // Deviation from mean residual: prefer bins whose residual is close to the mean
    // (keeps bin states homogeneous, easier future packing).
    score += 0.3 * (bin_residual as f64 - mean_residual).abs();

    // New-bin candidate (empty bin): only attractive when no good open option exists.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 90.0 + 6.0 * open_bins_count as f64;
        // But if this bin is the ONLY fitting option, opening is necessary.
        if fitting_bins_count == 0 {
            score -= 250.0;
        }
        // Opening a new bin is fine if it avoids creating dead space in an existing bin.
        if item_size >= 70 {
            score -= 40.0;
        }
        // Late in the stream, prefer consolidating: raise new-bin cost.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 60.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= (bin_capacity as f64 / (1.0 + diff)) * 0.5;
        // bonus if next item fits exactly
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual < next_item_size {
            // dead space relative to lookahead item
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    } else {
        // last item: prefer tightest fit
        score -= 20.0;
    }

    // Penalize post_residual far above mean residual (wasteful large gap)
    score += ((post_residual as f64 - mean_residual).max(0.0)) * 0.4;

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + item_size as f64 * 0.1;
    }

    // New-bin candidate: penalize unless current open bins are crowded
    if bin_residual == bin_capacity {
        let crowding = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        score += 25.0 - crowding * 2.0;
        // still allow opening if lookahead won't fit anywhere nicely
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    // Slight preference for bins with less residual overall
    score += (bin_residual as f64 / bin_capacity as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post-fit residual (tight packing).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * tightness * tightness;

    // Reward near-perfect fits strongly (post_residual <= 10 is gold).
    if post_residual <= 10 {
        score -= 25.0 + 2.0 * (10 - post_residual) as f64;
    } else if post_residual > 40 {
        // Large dead space is hard to reuse later; penalize super-linearly.
        score += 0.15 * (post_residual - 40) as f64 * (post_residual - 40) as f64 / 10.0;
    }

    // Lookahead (k=2): if the next item fits the post residual, this placement
    // sets up a chain — reward proportionally to how well it will fit.
    if next_item_size > 0 && next_item_size <= post_residual {
        let next_fit = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 8.0 * next_fit;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here: mild penalty for leaving awkward residue.
        score += 3.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Global state: many open bins with high mean residual -> consolidate.
    // Prefer bins whose residual is below the mean (they are already tight).
    if bin_residual < bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score += 0.2 * diff;
        // Consolidation pressure grows with the number of open bins.
        score -= 0.5 * open_bins_count as f64 * (bin_residual as f64 / bin_capacity as f64);
    }

    // Time horizon: early in the stream, be more willing to open bins
    // (long horizon amortizes); late in the stream, squeeze existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 5.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: opening a bin is only attractive when no open bin
    // fits well — i.e., when the item is large relative to residuals and
    // post_residual in a fresh bin is small (large item nearly fills it).
    if bin_residual == bin_capacity {
        let fresh_efficiency = 1.0 - (post_residual as f64 / bin_capacity as f64);
        // Penalty for abandoning open bins; reduced when the item is big.
        score += 18.0 * (1.0 - fresh_efficiency) * (1.0 + 0.1 * open_bins_count as f64);
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0 * fresh_efficiency; // fresh bin can host the next item too
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear reward for tight fits: quadratic coupling of post_residual with capacity.
    let tightness = 1.0 - pr / cap;
    score -= 12.0 * tightness * tightness;

    // Smooth stream-progress coupling: late in the stream, squeeze bins harder.
    score -= (1.0 - progress) * 4.0 * (pr / cap) * (1.0 - pr / cap);

    // Lookahead synergy: reward residuals that leave room for the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs();
        score -= 8.0 * (1.0 - gap / cap).max(0.0) * (1.0 - progress);
    }

    // Penalize dead space relative to the fleet's mean residual (smooth cubic term).
    let dev = pr - mean_residual;
    score += 0.02 * dev * dev * dev / (cap * cap);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: mild penalty so it wins only when open bins are poor fits.
    if bin_residual == bin_capacity {
        score += 6.0 + 10.0 * (1.0 - progress) + 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let nxt = next_item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base: prefer small post residual, with quadratic dead-space penalty.
    let mut score = post + (post * post) / cap;

    // Harmonic class of post_residual: residuals in "useless" small classes
    // (too small for typical items) are penalized super-linearly.
    let class = post_residual % 10;
    let dead_class_penalty = match class {
        0 => -6.0, // perfectly divisible -> clean state, reward
        1 | 2 | 3 => 8.0 + post * 0.15, // tiny unusable slivers
        4 | 5 | 6 => 3.0,
        _ => 0.0,
    };
    score += dead_class_penalty;

    // Lookahead coupling: if the next item fits into post_residual, reward heavily.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0 + 0.1 * nxt;
        // Bonus if next item exactly fills the bin (perfect 2-chain).
        if next_item_size == post_residual {
            score -= 15.0;
        }
    } else if next_item_size > 0 && next_item_size > bin_residual {
        // Next item won't fit here anyway; mild reward for consuming big space now.
        score -= 2.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 12.0;
    }

    // Many open bins: encourage consolidation by rewarding bins below mean residual.
    if post < mean_residual {
        score -= 1.5;
    } else {
        score += 0.5 * (post - mean_residual).min(20.0);
    }

    // Early stream: be slightly greedier toward tight fills; late stream: keep flexibility.
    score -= (1.0 - progress) * 2.0 * (1.0 - post / cap);

    // New-bin candidate logic: only attractive when no open bin fits well
    // or open bins are nearly full / too few.
    if is_new_bin {
        let escape_penalty = if fitting_bins_count <= 1 {
            -20.0 // nothing else fits -> open new bin
        } else {
            // compare item fit quality: bad fit (large post residual) elsewhere
            // makes new bin relatively attractive
            let poor_fit_elsewhere = (post - item) / cap; // = 0 for empty bin
            6.0 - 4.0 * poor_fit_elsewhere + 0.05 * open_bins_count as f64
        };
        score += escape_penalty;
        // New bin early in stream when few bins open is cheap.
        if open_bins_count < 3 {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 35 {
        score += 10.0;
    } else {
        // Larger residual chunks are more reusable: mild reward relative to mean residual.
        score -= 8.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward bins that can also accommodate the lookahead item after this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    }
    // Penalize leaving a gap that exactly matches nothing likely to come.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading; few bins -> allow.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
    score += 0.05 * pressure * (0.5 + progress);

    // New-bin candidate: neutral baseline with slight penalty so it is chosen
    // only when existing bins look truly bad (dead-space penalties above dominate).
    if bin_residual == bin_capacity {
        score = 45.0 + 0.5 * item_size as f64;
        if fitting_bins_count == 1 {
            score += 30.0; // never open a new bin when it's the only fit
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward residuals that can host the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) >= nxt {
            // Perfect chain: post_residual exactly matches next item -> big reward.
            let slack = post_residual as f64 - nxt;
            score -= 30.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't chain: penalize dead space relative to mean residual.
            score += 8.0 + 0.5 * (mean_residual - post_residual as f64).abs();
        }
    } else {
        // Last item: minimize waste directly.
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when open bins exist with decent residual.
    if bin_residual == bin_capacity {
        score += 15.0 + 0.3 * mean_residual;
    }

    // Prefer tighter fits overall (small relative waste).
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score += 20.0 * waste_ratio * waste_ratio;

    // Late in the stream, consolidate harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - waste_ratio);

    // Mild penalty for spreading across many bins.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins whose post-residual is small.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio;

    // Penalize dead space that nothing (including lookahead item) can use.
    if post_residual > 0 {
        let min_item = 1.0;
        if (post_residual as f64) < min_item * 1.0 {
            score -= 5.0;
        }
        if next_item_size > 0 && next_item_size as f64 > post_residual as f64 {
            // leftover can't hold the next item: mild penalty scaled by leftover size
            score += 0.05 * post_residual as f64;
        } else if next_item_size > 0 {
            // leftover can hold the next item: reward
            score -= 4.0 * (next_item_size as f64 / post_residual as f64);
        }
    } else {
        // Perfect fit
        score -= 15.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0 + 0.1 * (bin_residual as f64 - post_residual as f64);
    }

    // New-bin candidate handling: it should only win when open bins are poor.
    if bin_residual == bin_capacity {
        // Baseline cost of opening a new bin, modulated by stream progress
        // and how crowded the current bins are.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowdedness = mean_residual / bin_capacity as f64;
        score += 20.0 + 10.0 * crowdedness - 5.0 * progress;
        // If many bins can already fit the item, discourage opening a new one.
        score += 2.0 * fitting_bins_count as f64;
        // If the next item is large and current mean residual is small, new bin is more attractive.
        if next_item_size > 0 {
            score -= 0.05 * next_item_size as f64 * (1.0 - crowdedness);
        }
    }

    // Prefer bins with residual below the mean (consolidate waste in fuller bins).
    score += 0.1 * (bin_residual as f64 - mean_residual).max(0.0);

    // Mild preference to keep number of open bins stable late in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.3 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    // Base: post residual, mildly convex in normalized residual
    let mut score = pr * (1.0 + 0.35 * x * x);

    // Tight fits rewarded more as stream progresses
    let tightness = 1.0 - x;
    score -= 12.0 * tightness * tightness * (0.4 + 0.6 * progress);

    // Penalize residuals that neither fit next item nor are near zero (dead space)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx > pr {
            score += 0.25 * (nx - pr) * (0.5 + progress);
        } else {
            score -= 0.15 * nx * (1.0 - progress);
        }
    } else {
        score += 0.5 * pr * progress;
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 8.0;
    }

    // Discard near-empty new-bin residual when many bins open (mild)
    score += 0.01 * open_bins_count as f64 * (x - mean_residual / cap).abs();

    // Smooth coupling: quadratic in progress
    score += 5.0 * progress * progress * (1.0 - x);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: dead space is worse when it is
    // small-but-unusable. Class residual modulo common item-size buckets.
    let class = post_residual % 20;
    if post_residual > 0 {
        // tiny unusable slivers (< 10) are dead space: penalize
        if post_residual < 10 {
            score += (10 - post_residual) as f64 * 2.0;
        }
        // residual in a "harmonic" band (multiple of 10/20) is reusable by
        // typical items: reward
        if class == 0 {
            score -= 12.0;
        } else if class <= 5 {
            score += 6.0;
        }
    }

    // Lookahead: reward residual that can host the next item exactly-ish
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            score -= 15.0;
            if slack < 5 { score -= 8.0; } // near-perfect two-item packing
        } else {
            // next item won't fit here; residual becomes a waiting class
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when nothing else fits well
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 + 10.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0;
        }
        if fitting_bins_count == 1 {
            score += 20.0; // don't abandon the last-chance bin
        }
    }

    // Progression: later in stream, consolidate into fewer bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (mean_residual - post_residual as f64).abs() * 0.3;

    // Prefer bins whose residual deviates below the mean (fill laggards)
    if (post_residual as f64) < mean_residual {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let is_new_bin = bin_residual == bin_capacity;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // --- Strict dead-space avoidance ---
    if post_residual == 0 {
        // Perfect fit: heavily rewarded
        score -= 60.0;
    } else {
        let gap = post_residual as f64;
        let dead_threshold = 12.0;
        if gap < dead_threshold {
            // Small unusable gaps are quadratic-ish dead space: spike the penalty
            score += (dead_threshold - gap) * 6.0;
        }
    }

    // --- Lookahead coupling (k=2) ---
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item can land in the leftover space: reward, scaled by snugness
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 + slack * 0.05;
        } else {
            // Leftover too small for the known next item: mild penalty
            score += 4.0;
        }
    }

    if is_new_bin {
        // Opening a new bin carries open-bin pressure that grows with
        // fragmentation and stream progression.
        score += 8.0 + open_bins_count as f64 * 1.5 + progress * 10.0;
        // If residual capacity is already abundant across open bins,
        // opening yet another bin is wasteful.
        score += mean_residual * 0.02;
        // If no open bin fits at all, the new bin is mandatory: guarantee selection.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    } else {
        // Last-chance bin: strongly favor using it before opening a new bin.
        if fitting_bins_count == 1 {
            score -= 25.0;
        }
        // Prefer bins tighter than the current average (consolidate scarce space).
        let diff = bin_residual as f64 - mean_residual;
        score += diff * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
