pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    if post_residual == 0 {
        score -= 60.0; // perfect fit is almost always best
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Lookahead: if the next item can use this bin's post_residual, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 8.0 + 0.15 * slack.min(40.0);
    }
    // Penalize leaving a dead zone the next item cannot use.
    if next_item_size > post_residual && post_residual > 0 {
        score += 6.0 + 0.1 * (next_item_size - post_residual) as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0;
    }
    // Many fitting bins: mild penalty for fragmenting when alternatives exist.
    if fitting_bins_count > 2 {
        score += 1.5 * (fitting_bins_count as f64 - 2.0).min(5.0);
    }

    // Time horizon: early in the stream, prefer opening fresh bins to keep
    // flexibility; later, consolidate into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let new_bin = (bin_residual == bin_capacity) as f64;
    score += new_bin * (14.0 - 22.0 * progress);

    // Global state: if mean residual across open bins is large, discourage
    // opening yet another bin; encourage filling scattered space.
    if new_bin < 0.5 {
        score -= 0.05 * mean_residual.min(60.0);
    } else {
        score += 0.08 * (mean_residual - 30.0).max(0.0);
    }

    // Many open bins: penalize new bins harder, reward consolidation.
    score += new_bin * 0.6 * open_bins_count as f64;
    if new_bin < 0.5 {
        score -= 0.3 * (open_bins_count as f64).min(12.0);
    }

    // Slight preference for bins whose residual is close to item size.
    score += 0.05 * ((bin_residual - item_size) as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear reward for tight fits (small post_residual), amplified over stream progress
    let tightness = (1.0 - pr / cap).powi(3);
    score -= 18.0 * tightness * (0.5 + progress);

    // Penalize large dead space quadratically
    score += 0.012 * pr * pr / cap;

    // Last-chance bin: strong bonus to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: penalize so it's chosen only when fits are poor,
    // with penalty decaying as stream progresses (late items pack less flexibly)
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-6;
    if is_new_bin {
        score += 40.0 * (1.0 - 0.5 * progress);
    } else {
        // Favor bins whose residual deviates favorably from the mean residual
        let dev = mean_residual - bin_residual as f64;
        score += 0.05 * dev * (1.0 - progress);
    }

    // Lookahead coupling: reward leaving room close to the next item size (smooth kernel)
    if next_item_size > 0 {
        let d = pr - next_item_size as f64;
        score -= 8.0 * (-(d * d) / 400.0);
    }

    // Mild pressure to consolidate when many bins are open
    score += 0.02 * open_bins_count as f64 * (1.0 - tightness);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit reward: zero dead space is always ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic classes: classify post_residual into capacity fraction classes.
    // Class boundaries at capacity/2, /3, /4 -> dead space below these thresholds
    // is more "reusable" for future items, so reward being in a low class.
    let quarter = bin_capacity / 4;
    let third = bin_capacity / 3;
    let half = bin_capacity / 2;
    if post_residual > 0 {
        if post_residual <= quarter {
            score -= 8.0;
        } else if post_residual <= third {
            score -= 4.0;
        } else if post_residual <= half {
            score += 3.0;
        } else {
            // Large residual is fine only for a fresh bin (which it is by construction).
            score += 0.0;
        }
    }

    // Lookahead: if the next item fits exactly or well into post_residual, reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= 20.0 - (slack as f64) * 0.15;
        } else {
            // Next item cannot use this residual: penalize proportional to waste risk.
            score += (next_item_size as f64) * 0.05;
        }
        // Modulo coupling: next item in same harmonic class as residual (both small)
        let cls = |x: u32| x / 10;
        if cls(next_item_size) == cls(post_residual) && post_residual > 0 {
            score -= 2.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 30.0;
        // Only attractive if no existing bin fits, or the item is huge and would
        // leave a tiny residual elsewhere (poor fragmentation).
        if fitting_bins_count == 0 {
            score -= 200.0;
        } else {
            // Penalize opening new bins when existing bins fit, unless all fits are bad.
            score += (fitting_bins_count as f64) * 2.0;
        }
        // Early in the stream, having spare open capacity is cheap.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - progress) * 10.0;
    }

    // Slight preference for bins tighter than average (best-fit flavor).
    score += ((bin_residual as f64) - mean_residual) * 0.05;

    // Mild pressure to consolidate as the stream progresses.
    score += (open_bins_count as f64) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space (post_residual in (0, 10))
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Reward near-perfect fills
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize when decent fits exist
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 2.0 + mean_residual * 0.5;
    }

    // Open bins pressure: discourage spreading across many bins
    score += open_bins_count as f64 * 0.3;

    // Lookahead: if next item fits exactly in post_residual, reward
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: item exactly fills the bin.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if the next item exactly fits the post-residual,
    // strongly reward this placement (chained perfect packing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // Next item still fits here afterward: mild reward proportional to slack left after both.
            score -= 2.0 * (post_residual - next_item_size) as f64 / bin_capacity as f64;
        } else {
            // Next item would NOT fit after placement: penalize wasting residual that
            // could have held the next item.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.5 * waste;
        }
    }

    // Penalize creating unusable dead space relative to the mean residual of open bins.
    let dead = post_residual as f64 - mean_residual;
    score += 0.3 * dead.max(0.0);

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Penalize opening a new bin when decent open bins exist.
    if bin_residual == bin_capacity {
        score += 40.0 + open_bins_count as f64;
    }

    // Slight preference for tighter bins early in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * (bin_residual as f64 - post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item nearly fills the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fit_ratio > 0.85 {
        score -= 40.0 * (fit_ratio - 0.85);
    } else if fit_ratio < 0.3 {
        score += 15.0 * (0.3 - fit_ratio); // wasteful placement in a big bin
    }

    // Exact fill is perfect.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead coupling: does the post-residual still serve the next item?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item fits here: reward proportional to how well it would fill.
            let next_fit = next_item_size as f64 / post_residual as f64;
            score -= 25.0 * next_fit;
        } else {
            // Post-residual too small for next item: dead-space penalty grows
            // the closer we came to being usable.
            let gap = (next_item_size - post_residual) as f64;
            if post_residual < 10 {
                score -= 5.0; // tiny dead space is fine
            } else {
                score += 0.4 * gap;
            }
        }
    } else {
        // Last item: minimize residual aggressively.
        score *= 1.5;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New empty bin candidate: only attractive when the item is large relative to
    // capacity or no good fits exist elsewhere.
    if bin_residual == bin_capacity {
        let load_frac = item_size as f64 / bin_capacity as f64;
        if load_frac > 0.7 {
            score -= 20.0 * (load_frac - 0.7); // big items deserve fresh bins
        } else {
            score += 25.0 + 20.0 * (1.0 - load_frac); // discourage fragmentation
        }
        // Early in the stream, opening bins is cheap; later, prefer consolidation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Global pressure: many open bins with high mean residual -> consolidate.
    if open_bins_count > 2 {
        let consolidation = mean_residual / bin_capacity as f64;
        if bin_residual < mean_residual {
            score -= 8.0 * consolidation; // favor below-average-residual bins
        } else {
            score += 4.0 * consolidation;
        }
    }

    // Mild preference for bins with residual close to item (best-fit core).
    let abs_gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.3 * abs_gap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_post = post_residual as f64 / bin_capacity as f64;
    let norm_item = item_size as f64 / bin_capacity as f64;
    // Smooth non-linear coupling: post_residual penalized more heavily as stream progresses
    score += 2.0 * norm_post * norm_post * (0.5 + progress);
    // Reward tight fits (small post_residual) with smooth decay
    score -= 1.5 * (1.0 - norm_post) * (1.0 - norm_post) * (1.0 - progress);
    // Penalize wasted space relative to mean residual of open bins
    score += 0.3 * (post_residual as f64 - mean_residual) / bin_capacity as f64;
    // Lookahead: reward leaving space for the next item smoothly
    let nxt = next_item_size as f64 / bin_capacity as f64;
    score -= 1.0 * (norm_post - nxt).abs() * (1.0 - (norm_post - nxt).abs());
    // Last-chance bin bonus (smooth in fitting_bins_count)
    if fitting_bins_count == 1 {
        score -= 3.0 * (1.0 - norm_post);
    }
    // Mild penalty for opening new bins when many are open
    if bin_residual == bin_capacity {
        score += 1.0 + 0.05 * open_bins_count as f64;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into "usable"
    // classes (multiples of common small sizes) are more attractive.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit is always best
    } else {
        // Class bonus: residual divisible by small harmonic denominators
        let mut class_bonus = 0.0;
        for d in [10u32, 20, 25, 50].iter() {
            if pr % d == 0 {
                class_bonus += 6.0;
            }
        }
        if pr % 5 == 0 {
            class_bonus += 2.0;
        }
        score -= class_bonus;

        // Dead space penalty grows super-linearly for awkward residuals
        if pr < 10 {
            score += 30.0;
        } else if pr < 20 {
            score += 8.0;
        }

        // Harmonic fraction thresholds: residual in (cap/3, cap/2) is a
        // "half-class" sweet spot for typical item sizes.
        let frac = pr as f64 / cap;
        if frac > 0.33 && frac < 0.5 {
            score -= 4.0;
        } else if frac > 0.8 {
            score += 6.0; // leaving a nearly-full bin untouched wastes little
        }

        // Lookahead coupling: if next item fits exactly into post_residual,
        // strongly reward (chained perfect fit).
        if next_item_size > 0 {
            if next_item_size == pr {
                score -= 25.0;
            } else if next_item_size <= pr {
                let npr = pr - next_item_size;
                if npr % 10 == 0 {
                    score -= 8.0;
                }
                score += (npr as f64) * 0.15;
            } else {
                // next item cannot use this residual: mild penalty scaled by waste
                score += (pr as f64) * 0.05;
            }
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: only attractive when current item is large and
    // existing residuals are fragmented; penalize default new-bin otherwise.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score = 55.0 + fragmentation * 0.3 - (item_size as f64) * 0.2 - progress * 5.0;
        if fitting_bins_count == 0 {
            score -= 40.0; // nothing fits elsewhere: new bin mandatory
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 6.0; // room to pair next item in fresh bin
        }
    }

    // Slight preference for tighter bins overall
    score += (bin_residual as f64 - post_residual as f64) * 0.05;
    score += (mean_residual - bin_residual as f64).abs() * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps heavily.
    if post_residual > 0 {
        // A residual gap is "dead" if it's too small for typical future items.
        // Threshold scales with the lookahead item size when available.
        let dead_threshold = if next_item_size > 0 {
            (next_item_size as f64 * 0.9).min(30.0)
        } else {
            20.0
        };
        if (post_residual as f64) < dead_threshold {
            // Dead space: quadratic penalty proportional to how "wasted" it is
            let waste = dead_threshold - post_residual as f64;
            score += 6.0 * waste * waste / dead_threshold;
        } else {
            // Usable residual: reward larger usable gaps
            score -= 2.0 * (post_residual as f64 - dead_threshold).min(50.0);
        }
    } else {
        // Perfect fit: strong reward
        score -= 15.0;
    }

    // Exact-fit anticipation: if the next item exactly consumes post_residual
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    }
    // Next item fits comfortably in the post residual: reward this bin
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Open-bins pressure: when many bins are open, discourage new-bin sprawl
    // and favor consolidating into existing bins.
    let bin_pressure = open_bins_count as f64 / 20.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as open bins grow
        score += 10.0 + 8.0 * bin_pressure;
        // Early in the stream with few open bins, a new bin is cheap
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 12.0 * (1.0 - progress) * (1.0 - (open_bins_count as f64 / 10.0).min(1.0));
    } else {
        // Reward placing into existing bins proportionally to pressure
        score -= 3.0 * bin_pressure;
    }

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it's already tight — prefer filling tight bins (best-fit behavior).
    let diff = mean_residual - bin_residual as f64;
    score += 0.15 * diff;

    // Mild penalty for leaving residual close to but not exactly matching
    // common item sizes (10..80), reducing awkward gap creation.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact / near-exact fit (post_residual small)
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    } else if post_residual <= 15 {
        score -= 100.0;
    }

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // next item fits: reward proportional to how well it fills the remainder
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 200.0 * fill;
            // double-bonus if the pair nearly exhausts the bin
            let after_next = post_residual as i64 - next_item_size as i64;
            if after_next <= 5 {
                score -= 150.0;
            }
        } else {
            // next item won't fit here: penalize leaving a residual that is
            // likely dead space relative to typical item sizes
            let waste = (next_item_size - post_residual) as f64;
            score += 0.5 * waste;
        }
    }

    // Compare post_residual against mean residual across open bins:
    // leaving below-mean residual is good (tight packing), above-mean is wasteful
    if mean_residual > 0.0 {
        let rel = post_residual as f64 / mean_residual;
        if rel < 0.5 {
            score -= 50.0 * (0.5 - rel);
        } else if rel > 1.5 {
            score += 50.0 * (rel - 1.5);
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate: make it moderately attractive only when no open bin
    // fits well (post_residual large relative to capacity on existing bins is
    // handled naturally), but discourage hoarding many open bins early
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 120.0 - 60.0 * progress + 5.0 * open_bins_count as f64;
    }

    // Mild preference for placing into fuller bins overall
    score -= 0.3 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (low post residual).
    score -= 8.0 * (1.0 - (post_residual as f64 / bin_capacity as f64)).powi(3);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Penalize dead space that no future item could plausibly use:
    // small residuals below the minimum item size are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item cannot use the leftover space: penalize proportionally.
            score += 4.0 * (1.0 - (post_residual as f64 / next_item_size as f64).min(1.0));
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Many open bins: prefer consolidating into existing bins rather than spreading.
    score += 0.05 * open_bins_count as f64;

    // Prefer bins whose residual is below the mean residual (more filled bins).
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Time horizon: early in the stream, be conservative (mild penalty on fills);
    // late in the stream, pack aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, discounted if current bins are crowded.
        score = 55.0 - 0.3 * mean_residual - 3.0 * (fitting_bins_count as f64);
        if fitting_bins_count == 0 {
            score -= 60.0; // no alternative: new bin is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear waste penalty: squared residual normalized, stronger late in the stream
    let norm_post = post / cap;
    score += 12.0 * norm_post * norm_post * (0.5 + progress);

    // Reward tight fits (small post_residual relative to item size)
    let tightness = item_size as f64 / (item_size as f64 + post + 1.0);
    score -= 8.0 * tightness * tightness;

    // Lookahead coupling: penalize if post_residual cannot hold next item, reward if it can
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post >= nx {
            score -= 5.0 * (nx / cap) * (1.0 - progress);
        } else {
            let gap = (nx - post) / cap;
            score += 6.0 * gap * gap;
        }
    }

    // Last-chance bin: strongly reward using the only bin that fits
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // New-bin candidate: mildly penalize opening a new bin when alternatives exist,
    // but relax late in the stream or when many bins are open
    if bin_residual == bin_capacity {
        let relax = (open_bins_count as f64 / (open_bins_count as f64 + 4.0)) * (1.0 - progress);
        score += 4.0 * (1.0 - relax);
    }

    // Slight penalty for leaving residual far from mean (fragmentation signal)
    let dev = (post - mean_residual) / cap;
    score += 2.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: prefer residuals landing on "useful"
    // coarse classes (multiples of 10 / 5), since typical item granularity
    // clusters there; odd tiny residuals are dead-space prone.
    let cls = (post_residual % 10) as f64;
    score += cls * 0.35;                      // within a decade, prefer smaller remainder
    if post_residual % 5 == 0 && post_residual > 0 {
        score -= 4.0;                          // reward class-aligned residuals
    }
    if post_residual > 0 && post_residual < 5 {
        score += 6.0;                          // penalize near-dead slivers
    }

    // Tight-fit reward: filling most of the bin now is excellent.
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill * 12.0;

    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 20.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding a new bin opening.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead coupling (k=2): if the next item exactly consumes the
    // remainder, this is a harmonic pair — big reward. If the remainder is
    // too small for the next item, penalize the waste proportionally.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 18.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // New-bin candidate: base score is already bin_capacity - item_size
    // (large), which naturally deprioritizes it; add mild pressure so it
    // only wins when all fits are poor, modulated by stream progress.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 8.0 - 4.0 * progress;
    }

    // Mild preference for balancing residuals across open bins.
    score += (post_residual as f64 - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: exponential bonus as post_residual approaches 0.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        score -= 60.0 / (post_residual as f64).sqrt();
    }

    // Strict dead space avoidance: residuals too small for ANY future item
    // (min item size 1... but practically penalize gaps below next_item_size
    //  and small gaps that are hard to fill).
    if post_residual > 0 {
        if next_item_size > 0 && post_residual < next_item_size {
            score += 25.0; // gap cannot host the lookahead item
        }
        if post_residual < 10 {
            score += 40.0; // nearly unusable micro-gap
        } else if post_residual <= 20 {
            score += 15.0; // hard-to-fill small gap
        }
    }

    // Lookahead harmony: reward if next item fits exactly in the post residual.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 45.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open bins pressure: discourage spreading across many bins when residuals
    // are similar; mild penalty scaled by count.
    score += open_bins_count as f64 * 1.5;

    // Prefer bins whose residual is close to the mean (balance load),
    // penalize outliers that create fragmented space.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.3;

    // New-bin candidate handling: empty bin gets a baseline cost so it is only
    // chosen when all open bins score poorly (poor fits / dead space).
    if bin_residual == bin_capacity {
        score += 55.0;
        // Late in the stream, opening new bins is less costly than fragmenting.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 20.0;
    }

    // Mild progress term: early on, keep bins open and flexible.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: perfect match with next item is highly rewarded.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if diff == 0.0 {
            score -= 60.0; // exact fit for the next item
        } else {
            score += 0.8 * diff; // penalize mismatch proportional to distance
        }
        // Bonus if next item fits into the residual left behind (chainability)
        if next_item_size <= post_residual {
            score -= 15.0;
        } else {
            score += 10.0 * (next_item_size - post_residual as u32) as f64;
        }
    }

    // Penalize dead space relative to mean residual across open bins
    score += 0.5 * (post_residual as f64 - mean_residual).max(0.0);
    score -= 0.2 * (mean_residual - post_residual as f64).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are crowded
    if bin_residual == bin_capacity {
        let crowding = mean_residual / bin_capacity as f64;
        score += 30.0 * (1.0 - crowding);
        if fitting_bins_count == 0 {
            score -= 100.0; // nothing else fits: must open new bin
        }
    }

    // Waste ratio: small leftover relative to item size is good packing
    score += 0.3 * (post_residual as f64 / item_size.max(1) as f64);

    // Late in the stream, prefer tighter packing to close bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fractional progress through the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // --- New-bin candidate handling ---
    // A brand-new empty bin has bin_residual == bin_capacity. Opening a new bin
    // is only attractive when the current item would leave a very awkward
    // residue in every existing bin, or when few bins fit the item.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a bin: moderately high so tight existing fits win.
        score += 18.0;
        // Late in the stream, prefer consolidating into open bins.
        score += 10.0 * progress;
        // If many bins fit, definitely prefer one of them.
        if fitting_bins_count > 1 {
            score += 15.0;
        }
        // If only this new bin can fit (fitting_bins_count==1 counting it), it's forced.
        // Reduce cost so it gets chosen over nothing.
        if fitting_bins_count <= 1 {
            score -= 25.0;
        }
        // If the item is huge relative to capacity, a fresh bin is natural.
        if item_size as f64 > 0.7 * bin_capacity as f64 {
            score -= 12.0;
        }
        // Lookahead: if the next item fits perfectly in the leftover of a fresh
        // bin (e.g. item 60 + next 40), opening a new bin is great.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 20.0;
        }
        return score;
    }

    // --- Existing-bin scoring ---

    // Reward tight fits: small post_residual is already the base score.
    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Dead-space penalty: leftover space too small for any plausible item
    // (items are >= 1, but small residues are hard to use).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // nearly-unusable sliver
    }

    // Lookahead coupling: reward if next item fits in the residue,
    // penalize if it doesn't (residue becomes a trap for that pairing).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item can follow: reward proportionally to how snug the pair is.
            let pair_slack = (post_residual - next_item_size) as f64;
            score -= 12.0 - 0.3 * pair_slack.min(20.0);
        } else {
            score += 5.0;
        }
    }

    // Last-chance bin: if this is the only open bin that fits, strongly favor
    // using it rather than opening a new bin.
    if fitting_bins_count == 1 {
        score -= 22.0;
    }

    // Global-state coupling: if mean residual across open bins is large,
    // we should be filling bins aggressively; reward placements into bins
    // whose residual is below the mean (below-average waste bins).
    let bin_residual_f = bin_residual as f64;
    if bin_residual_f < mean_residual {
        score -= 6.0;
    } else {
        score += 2.0;
    }

    // Many open bins: discourage leaving residues, encourage tight packing.
    if open_bins_count > 4 {
        score += 0.15 * post_residual as f64;
    }

    // Time-horizon term: early in the stream, keep bins flexible (mild
    // penalty for very tight fills that could strand space); late in the
    // stream, prioritize closing gaps.
    if progress < 0.3 {
        score += 0.05 * post_residual as f64;
    } else {
        score -= 0.08 * (bin_capacity - post_residual) as f64 * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let base = pr / cap;
    let mut score = pr as f64;
    let poly = base * base * (1.0 - progress) + base * progress;
    score += 40.0 * poly * pr;
    let tight = 1.0 - base;
    score -= 25.0 * tight * tight * (item_size as f64 / cap);
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = pr - nxt;
        if gap >= 0.0 {
            score -= 15.0 * (gap / cap);
        } else {
            score += 10.0 * (-gap / cap) * (1.0 + progress);
        }
    }
    if fitting_bins_count <= 1 {
        score -= 30.0 * (1.0 - progress);
    }
    score += 5.0 * ((open_bins_count as f64 / 10.0) * base * base);
    score += 8.0 * (mean_residual / cap - base).abs();
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: prefer post-residuals in "reusable" classes
    // (multiples of ~10 align with typical item granularity 1..100 / stream quantization).
    let class = post_residual / 10;
    score -= (class as f64) * 1.5; // reward post-residuals landing on coarse class boundaries

    // Perfect / near-perfect fits are gold.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 3 {
        score -= 25.0;
    } else if post_residual <= 8 {
        score -= 10.0;
    }

    // Dead space: post_residual too small for any plausible future item (items >= 1,
    // but practically small slivers are unusable). Penalize slivers in (0, 10).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Lookahead coupling: does the next item fit into the post-residual?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Chain-friendly: bonus scaled by how snugly the next item nests.
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 + 6.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here: penalize proportionally to the wasted gap.
            let gap = (next_item_size - post_residual) as f64;
            score += 3.0 + gap * 0.15;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    let is_new_bin = bin_residual == bin_capacity;
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 18.0;
        if post_residual <= 10 {
            score -= 12.0; // and it's a tight fit too: almost mandatory
        }
    }

    // New-bin candidate: only attractive when the item is large relative to capacity
    // (i.e., post_residual small) or when all existing fits are poor. Otherwise push
    // the new-bin option behind existing bins.
    if is_new_bin {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        score += 10.0 - 20.0 * fill_ratio; // large items make a fresh bin cheap
        if fitting_bins_count > 0 {
            score += 6.0; // some existing bin fits: prefer it unless very tight
        }
        // Late in the stream, consolidating matters more; discourage new bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 8.0 * progress;
    }

    // Mild consolidation pressure: prefer bins whose residual is near the mean
    // (balanced packing keeps future options open).
    score -= ((bin_residual as f64 - mean_residual) / bin_capacity as f64) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps that are too small for the
    // smallest plausible item (<= 10) are pure waste -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Penalize gaps too small for the upcoming item (lookahead-aware dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0;
    }
    // Reward perfect and near-perfect fits.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }
    // Reward residual sizes that the next item can exactly fill.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }

    // Open-bin pressure: discourage spreading across many bins when few fit.
    if fitting_bins_count <= 1 {
        score -= 30.0; // last-chance bin: strongly favor using it
    }
    score += 2.0 * open_bins_count as f64;

    // Mild pressure toward tighter-than-average bins.
    score += 0.3 * (mean_residual - post_residual as f64);

    // Early in the stream, allow new bins more freely; later, conserve bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 40.0 * (1.0 - progress);
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: reward minimal post_residual strongly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio) * 20.0;

    // Aggressive 2-step lookahead: reward when next item fits exactly into post_residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_fit_gap = (post_residual - next_item_size) as f64;
        score -= (1.0 - next_fit_gap / bin_capacity as f64) * 25.0;
        // Extra reward if next item fills the bin completely after placement.
        if post_residual == next_item_size {
            score -= 30.0;
        }
    } else if next_item_size > 0 {
        // Penalize leaving dead space next item cannot use.
        score += (next_item_size as f64 - post_residual as f64).min(30.0) * 0.8;
    }

    // Compare post_residual against mean residual: avoid creating outliers.
    score += (post_residual as f64 - mean_residual).abs() * 0.3;

    // Penalize wasting a nearly full bin on a small item.
    if item_size < bin_residual / 2 && bin_residual < bin_capacity / 2 {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless existing fits are poor.
    if bin_residual == bin_capacity {
        score += 35.0;
        // If next item is large, opening fresh space may be worthwhile.
        if next_item_size > 0 && next_item_size > bin_capacity / 2 {
            score -= 20.0;
        }
    }

    // Early stream: be slightly more willing to open bins (better long-run packing).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize leaving small unusable gaps (< smallest plausible item) harder.
    if post_residual < 10 {
        score -= 25.0; // near-perfect fill bonus
    } else if post_residual <= 15 {
        score += 12.0; // risky dead space
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0;
    }
    // Penalize if next item almost fits but not quite (fragmentation risk).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0 * (1.0 - post_residual as f64 / next_item_size as f64);
    }

    // Last chance: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).min(6.0);
    }

    // Prefer fuller bins when many bins are open (contain bin sprawl).
    score += (open_bins_count as f64).ln().max(0.0) * (bin_residual as f64 - item_size as f64) * 0.05;

    // Time horizon: early on, be conservative (favor new bins less); late, consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New bin candidate: attractive early, penalized late.
        score = 40.0 - 45.0 * progress + 0.15 * mean_residual;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // new bin fine when items are large
        }
    } else {
        // Consolidation pressure grows with progress.
        score -= 10.0 * progress * (1.0 - fit_ratio);
    }

    // Mild preference toward bins below mean residual (balance load lightly).
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64) / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;
    let norm_item = item_size as f64 / cap;

    let mut score = post;

    // Smooth non-linear coupling: post_residual polynomial in stream progress
    score += 8.0 * norm_post * norm_post * (0.5 + progress);
    score -= 4.0 * norm_post * norm_item * (1.0 - progress);

    // Penalize dead space that no plausible future item can use
    let next_norm = next_item_size as f64 / cap;
    if next_item_size > 0 {
        let waste = (post - next_item_size as f64).max(0.0) / cap;
        score += 12.0 * waste * waste * (1.0 + progress);
        // Reward leaving exactly the room the next item needs
        let match_term = (post - next_item_size as f64).abs() / cap;
        score -= 3.0 * (1.0 - match_term) * (1.0 - match_term);
    } else {
        score += 6.0 * norm_post * norm_post;
    }

    // Last-chance bin bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - norm_post * 0.5);
    }

    // Slight preference for bins tighter than the mean residual
    let mean_norm = mean_residual / cap;
    score += 2.0 * (norm_post - mean_norm) * (1.0 + progress);

    // Mild new-bin resistance, decaying as stream progresses
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - 0.6 * progress) + 3.0 * open_bins_count as f64 * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead-space quality classes.
    // Residuals in low "harmonics" (divisors of capacity) are more reusable.
    let cap = bin_capacity;
    let harmonic_bonus: f64 = if post_residual == 0 {
        -30.0 // perfect fill, best possible
    } else if cap % post_residual == 0 && post_residual <= cap / 2 {
        -18.0 // residual is an exact divisor of capacity (e.g. 50, 25, 20, 10)
    } else if post_residual <= 10 {
        -12.0 // tiny dead space, nearly full bin
    } else if post_residual <= 20 {
        -6.0
    } else if post_residual <= 40 {
        0.0
    } else {
        8.0 // large residual: bin was used wastefully
    };
    score += harmonic_bonus;

    // Integer-division threshold: does post_residual accommodate common small sizes?
    // Reward residuals that still fit "harmonic" item classes (multiples of 10/25).
    let reusable = post_residual >= 25 || post_residual % 10 == 0 && post_residual >= 10;
    if reusable {
        score -= 4.0;
    }

    // Lookahead coupling: if next item fits in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0;
            // extra reward if next item exactly consumes residual (harmonic pairing)
            if next_item_size == post_residual {
                score -= 15.0;
            }
        } else {
            // next item won't fit here; penalize moderately sized leftovers less
            score += 3.0;
        }
    } else {
        // last item: prefer tightest fill
        score += post_residual as f64 * 0.5;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < cap {
        score -= 14.0;
    }

    // New-bin candidate handling: only attractive when nothing fits well.
    let is_new_bin = bin_residual == cap;
    if is_new_bin {
        // Base penalty so open bins with decent fit win.
        score = 55.0 + post_residual as f64;
        // If many bins fit the item, opening new bin is bad.
        score += fitting_bins_count as f64 * 6.0;
        // If next item is large and current residual would be tiny anyway,
        // new bin slightly more attractive.
        if next_item_size > 60 {
            score -= 8.0;
        }
        // Late in stream, prefer consolidating into open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 10.0;
        // If mean residual is high, open bins have room; penalize new bin.
        score += (mean_residual / cap as f64) * 15.0;
    }

    // Mild penalty for waste relative to mean residual (avoid fragmenting).
    score += ((post_residual as f64 - mean_residual) * 0.05).max(0.0);

    // Tie-break: prefer bins with less residual at equal post_residual via tiny term.
    score += bin_residual as f64 * 0.001;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero gaps are the worst outcome.
    if post_residual > 0 {
        let dead = post_residual as f64;
        // Nonlinear penalty peaking for gaps too small for typical items (<= 10).
        if dead <= 10.0 {
            score += 40.0 * (1.0 - dead / 10.0);
        } else {
            // Larger gaps are progressively less "dead" per unit.
            score += 5.0 * (10.0 / dead);
        }
    } else {
        // Perfect fit: strong reward.
        score -= 30.0;
    }

    // Reward tight fits relative to residual (waste ratio).
    if bin_residual > 0 {
        let tightness = item_size as f64 / bin_residual as f64;
        score -= 12.0 * tightness * tightness;
    }

    // Open-bin pressure: discourage spreading across many bins early.
    score += 0.6 * open_bins_count as f64 * (1.0 - (post_residual as f64 / bin_capacity as f64));

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Mean residual coupling: prefer bins deviating below the mean (compact them first).
    score += 0.15 * (mean_residual - post_residual as f64);

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }
    // If next item would not fit and gap is small, penalize.
    if next_item_size > post_residual as u32 && post_residual > 0 && post_residual < 10 {
        score += 10.0;
    }

    // Late in the stream, be more conservative with new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost, reduced late (fewer alternatives matter less).
        score += 20.0 - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: normalize waste by capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * tightness * tightness;

    // Aggressive 2-step lookahead: reward if the next item fits into post_residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Perfect chaining: next item slots in exactly or nearly exactly.
            let gap = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item won't fit: this placement risks dead space.
            let overflow = (next_item_size - post_residual) as f64;
            score += 8.0 * (overflow / bin_capacity as f64);
        }
    } else {
        // Last item: only tightness matters.
        score -= 10.0;
    }

    // Compare against mean residual: prefer filling bins that are emptier
    // than average when post_residual is large (avoid many half-empty bins).
    if post_residual as f64 > mean_residual {
        score += 3.0 * (post_residual as f64 - mean_residual) / bin_capacity as f64;
    } else {
        score -= 2.0 * (mean_residual - post_residual as f64) / bin_capacity as f64;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current item is large
    // and would leave a useful residual for future items.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 18.0;
        // Worth opening a new bin for large items (keeps small residuals elsewhere usable).
        if item_size >= 60 {
            score -= 22.0;
        }
        // Early in stream: opening bins is cheaper (more future items to fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
        // Lookahead: if next item is small, new bin's residual is valuable.
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 6.0;
        }
    }

    // Mild bonus for using existing bins when many are open (consolidation).
    if open_bins_count > 4 && bin_residual != bin_capacity {
        score -= 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic penalty on wasted space.
    let waste = post_residual as f64;
    score += 0.35 * waste * waste / bin_capacity as f64;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: reward if the next item fits into post_residual (chained packing).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 18.0 + 0.25 * next_item_size as f64;
        } else if next_item_size > post_residual && post_residual < 10 {
            // Dead space too small for typical future items: penalize mildly.
            score += 8.0;
        }
        // Penalize leaving exactly a sliver that next item barely misses.
        if next_item_size > post_residual && post_residual > 0 && post_residual < next_item_size / 2 {
            score += 5.0;
        }
    } else {
        // Last item: strongly prefer tightest fit.
        score -= 25.0;
    }

    // Last chance: this is the only bin that fits -> avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: open a new bin only when existing fits are poor
    // or many bins are already open (fragmentation control).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 30.0;
        // If current item is large and mean residual is small, new bin is attractive.
        if item_size as f64 > mean_residual {
            score -= 55.0;
        }
        // Early stream: be generous with opening bins to build a portfolio.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress < 0.3 {
            score -= 15.0 * (0.3 - progress) / 0.3;
        }
        // Many open bins: discourage adding more.
        score += 2.5 * open_bins_count as f64;
        // Small items: keep them out of fresh bins.
        if item_size < 30 {
            score += 20.0;
        }
        // Large item nearly filling a bin alone: fresh bin is fine.
        if item_size >= 70 {
            score -= 20.0;
        }
    } else {
        // Reward using bins whose residual is close to the item (good occupancy).
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= 12.0 * fill_ratio;
        // Slight preference for bins with residual below mean (consolidate small leftovers).
        if (bin_residual as f64) < mean_residual {
            score -= 4.0;
        }
    }

    // Late-stream pressure: minimize bin count, prefer filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * (0.5 + progress);

    let mut score = pr + 20.0 * poly;

    // Reward tight fits via smooth interaction with progress
    let tightness = 1.0 - norm_pr;
    score -= 15.0 * tightness * tightness * (0.5 + progress);

    // Lookahead: reward bins whose post residual fits the next item
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 10.0 * (1.0 - (next_item_size as f64) / cap) * (1.0 - progress);
    }

    // Penalize near-mean residuals mildly (avoid cluster waste)
    score += 0.05 * (pr - mean_residual).abs();

    // Last-chance bonus: only fitting bin
    if fitting_bins_count == 1 {
        score -= 8.0;
    }

    // Mild penalty for too many open bins
    score += 0.5 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual mod 10 buckets.
    let post_mod = post_residual % 10;
    // Dead space penalty: residuals in (0,10) are nearly unusable since min item is 1... but small residuals waste space.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 - 2.0 * post_residual as f64;
    }
    // Perfect fit reward
    if post_residual == 0 {
        score -= 40.0;
    }

    // Harmonic classes: post_residual divisible by 5 or 10 is a "harmonic" residual,
    // more likely to be exactly filled by future items.
    if post_residual > 0 && post_mod == 0 {
        score -= 6.0;
    } else if post_residual > 0 && post_mod == 5 {
        score -= 3.0;
    } else if post_residual > 0 {
        // non-harmonic residual: penalize by distance to nearest multiple of 5
        let d = post_mod.min(10 - post_mod);
        score += d as f64 * 0.8;
    }

    // Coupling with next item: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            let next_post = post_residual - next_item_size;
            if next_post % 10 == 0 {
                score -= 8.0;
            } else if next_post < 10 {
                score += 6.0;
            }
        } else {
            // next item cannot follow in this bin; slight penalty if residual small
            if post_residual < next_item_size && post_residual > 0 {
                score += 4.0;
            }
        }
    }

    // Integer-division threshold classes on item_size (capacity fractions)
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    if item_size > half {
        score -= 10.0; // large items: prefer placing them somewhere soon
    } else if item_size > quarter {
        score += 2.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: neutral-ish score, tuned by stream position and load.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Prefer new bin when open bins are fragmented (low mean residual relative to item)
        let fragmentation = mean_residual / bin_capacity as f64;
        score = 30.0 + fragmentation * 40.0 - progress * 10.0;
        if next_item_size > 0 && next_item_size > bin_capacity - item_size.max(1) {
            score -= 5.0;
        }
        if fitting_bins_count <= 1 {
            score += 15.0; // avoid opening bins when alternatives are scarce
        }
    }

    // Mild preference to fill fuller bins (small residual before placement)
    score += (bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 18.0;
    } else if post_residual < 35 {
        score += 6.0;
    }

    // Reward tight fits (small post_residual relative to item).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Open-bin pressure: discourage opening new bins when open bins exist.
    if bin_residual == bin_capacity {
        score += 30.0 + 8.0 * open_bins_count as f64;
    } else {
        score -= 4.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Lookahead: favor bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 10.0;
        }
    }

    // Mild mean-residual coupling: prefer bins below mean residual (tighter bins).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Early stream: slightly prefer consolidation into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer perfect or near-perfect fills
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 150.0 + 0.5 * (next_item_size as f64);
        // extra reward if next item would then leave a tiny remainder
        let post2 = post_residual - next_item_size;
        if post2 <= 10 {
            score -= 80.0;
        }
    } else if next_item_size > 0 {
        // penalize dead space relative to lookahead item
        score += 0.6 * (next_item_size as f64 - post_residual as f64).max(0.0);
    }

    // Penalize wasted space relative to mean residual of open bins
    score += 0.3 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 120.0;
    } else if fitting_bins_count > 2 {
        // among many fitting bins, prefer tighter fits
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate: discourage opening a new bin unless item is huge
    // relative to residual or the fit would be very poor
    if bin_residual == bin_capacity {
        let waste = (bin_capacity - item_size) as f64;
        score += 250.0 - 1.5 * item_size as f64;
        // late in the stream, opening new bins is less costly
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 100.0 * progress;
        let _ = waste;
    }

    // Slight preference for filling larger residual bins early
    score -= 0.1 * bin_residual as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (post_residual close to 0)
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        let tightness = post_residual as f64 / bin_capacity as f64;
        score += tightness * tightness * 300.0; // penalize squared dead space
    }

    // Penalize leaving dead space smaller than the smallest plausible item
    if post_residual > 0 && post_residual < 10 {
        score += 120.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item (chaining)
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 60.0 + next_item_size as f64 * 0.4;
        } else if post_residual > 0 {
            score += 40.0; // residual too small for lookahead item = likely waste
        }
        // If this bin can take both current and next item exactly, extra reward
        if item_size + next_item_size <= bin_residual {
            score -= 25.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let fit_quality = (bin_residual - item_size) as f64 / bin_capacity as f64;
        // Opening a bin early in the stream is cheaper; late in the stream we
        // want to consolidate into existing bins.
        score += 150.0 + progress * 250.0;
        // But if the item is huge relative to capacity and mean residuals are small,
        // a fresh bin may genuinely be best.
        if fit_quality < 0.2 && mean_residual < item_size as f64 {
            score -= 180.0;
        }
        // Few open bins => mild bonus to open (spread future flexibility)
        if open_bins_count < 3 {
            score -= 40.0;
        }
    }

    // Mild preference for bins below mean residual (balancing residual spread)
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Late in the stream, avoid leaving many tiny residuals
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if post_residual > 0 && post_residual < 20 && progress > 0.7 {
        score += 60.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let p2 = progress * progress;
    let p3 = p2 * progress;
    score += norm_pr * norm_pr * (40.0 * p2 + 25.0 * p3) * cap;
    score -= item_size as f64 * (1.0 + 0.5 * p2) * (norm_pr * (1.0 - norm_pr) * 4.0);

    // Reward tight fits more strongly as stream progresses.
    let tight = 1.0 - norm_pr;
    score -= tight * tight * (30.0 + 40.0 * progress);

    // Penalize dead space relative to mean residual, smoothly.
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * 20.0 * (1.0 + progress);

    // Lookahead coupling: favor leaving room for next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs();
        score += gap * (0.3 + 0.7 * progress);
        if pr >= nxt {
            score -= 15.0 * (1.0 - progress);
        }
    }

    // Last-chance bonus: strongly favor the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0 * (1.0 + progress);
    }

    // Mild congestion penalty to avoid opening too many bins late.
    score += open_bins_count as f64 * 0.5 * progress;

    // New-bin candidate: prefer it only when all open residuals are poor.
    if bin_residual == bin_capacity {
        score += 35.0 - 30.0 * progress + mean_residual * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod 10 define "usable" dead space.
    let res_mod = post_residual % 10;
    // Residues 0 and small residues are valuable (other items may tile them).
    let residue_bonus = match res_mod {
        0 => 8.0,
        1 | 2 | 3 => 4.0,
        4 | 5 => 2.0,
        8 | 9 => -1.5, // awkward slivers, penalize slightly
        _ => 0.0,
    };
    score -= residue_bonus;

    // Integer-division thresholds: post_residual bucketed by quarters of capacity.
    let quarter = bin_capacity / 4;
    if post_residual < quarter / 2 {
        score += 6.0; // very tight leftover: near-perfect fill, but check next item
    } else if post_residual <= quarter {
        score -= 3.0; // sweet spot: fits small next item
    } else if post_residual <= 2 * quarter {
        score -= 1.0;
    }

    // Lookahead coupling: does next_item_size fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 12.0; // perfect chaining: place next item here
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) % 10;
            score -= 5.0 - (slack as f64) * 0.4; // good fit, mod-tuned
        } else {
            // next item cannot follow here; penalize more if this bin is last chance
            score += 2.0 + (next_item_size - post_residual) as f64 * 0.05;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: only attractive when existing bins fit poorly.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 20.0 } else { 0.0 };
        let tightness = (mean_residual - item_size as f64).abs();
        score = 100.0 - pressure + tightness * 0.2;
        if next_item_size > 0 && next_item_size > bin_capacity / 2 {
            score -= 8.0; // big next item: fresh bin is useful
        }
    }

    // Stream progression: late in stream, consolidate harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (post_residual as f64) * 0.15;

    // Coupling with mean residual: prefer bins below mean (tighter bins first).
    score += (mean_residual - bin_residual as f64).max(-20.0).min(20.0) * 0.1;

    // Modulo coupling between item class and residual class (harmonic tiling).
    let item_class = item_size / 10;
    let res_class = post_residual / 10;
    if (item_class + res_class) % 3 == 0 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Strict dead-space avoidance: residuals of 1..=10 are nearly unusable
    // (min item size is 1, but small gaps rarely match future items).
    if post_residual > 0 && post_residual <= 10 {
        score += 25.0 + (10 - post_residual) as f64 * 2.0;
    } else if post_residual > 10 && post_residual <= 25 {
        // Medium-small gaps: moderate penalty scaled by gap tightness.
        score += (25 - post_residual) as f64 * 0.6;
    }

    // If the next item can exactly fill this bin's post-residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    }
    // If next item fits in the post-residual, mild reward.
    if next_item_size > 0 && next_item_size < post_residual {
        score -= 8.0;
    }
    // If next item cannot use the leftover space, penalize (dead space likely).
    if next_item_size > post_residual && post_residual > 0 {
        score += 10.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, favor consolidation into
    // existing bins and penalize the new-bin candidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure that grows with
        // open bin count and stream progress.
        score += 15.0 + open_bins_count as f64 * 3.0 + progress * 20.0;
        // Early stream with few bins: opening a bin is cheap.
        if open_bins_count <= 2 {
            score -= 20.0;
        }
    } else {
        // Existing bin: reward when many bins are open (consolidation).
        score -= (open_bins_count as f64).min(10.0) * 1.5;
    }

    // Prefer bins tighter than the mean residual (well-packed bins).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    // Prefer bins whose residual is close to the item (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    let cap = bin_capacity as f64;
    let fit_ratio = item_size as f64 / bin_residual as f64;
    if fit_ratio > 0.9 {
        score -= 30.0 * fit_ratio;
    }

    // Penalize tiny dead space that nothing can use (items >= 1).
    if post_residual < 10 && post_residual > 0 {
        score += 12.0;
    }

    // 2-step lookahead: reward when next item exactly fills post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect chaining
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / cap).max(0.0);
        } else {
            // Next item won't fit here; penalize wasting a good residual.
            let overshoot = (next_item_size - post_residual) as f64;
            score += 5.0 * (overshoot / cap);
        }
    }

    // Compare residual against mean residual: prefer bins that are already tight
    // relative to the fleet average (best-fit style).
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: make it slightly unattractive by default, but attractive
    // when the current item is huge and no open bin is a good home.
    if bin_residual == bin_capacity {
        score += 6.0;
        if item_size > bin_capacity / 2 && mean_residual < item_size as f64 {
            score -= 15.0;
        }
    }

    // Mild late-stream preference to consolidate into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 2.0 * progress * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post-residual relative to item size.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize large dead space unless it could host the next item.
    if post_residual > 0 {
        if (next_item_size as u32) <= post_residual && next_item_size > 0 {
            score -= 12.0; // next item can chain into this bin
        } else {
            // dead space penalty scaled by how unusable it is
            score += 0.35 * post_residual as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Global pressure: many open bins with low mean residual -> prefer filling existing bins.
    let pressure = mean_residual / bin_capacity as f64;
    if open_bins_count > 2 {
        score -= 8.0 * (1.0 - pressure);
    }

    // Time horizon: early in the stream, opening new bins is cheap; later, consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 10.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * progress * fit_ratio;

    // Perfect or near-perfect fill bonus.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Lookahead exact-fit bonus.
    if next_item_size > 0 && (next_item_size as u32) == post_residual {
        score -= 20.0;
    }

    // New-bin candidate bias: only open a new bin when item is large and current fits are poor.
    if bin_residual == bin_capacity {
        let poor_fit = fitting_bins_count > 0 && fit_ratio < 0.5;
        if poor_fit || open_bins_count == 0 {
            score -= 10.0;
        } else {
            score += 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;

    // Base: penalize wasted residual, with a non-linear (quadratic) growth
    let mut score = post + 12.0 * norm_post * norm_post * cap;

    // Smooth stream-progress coupling: late in the stream, dead space matters more
    score *= 1.0 + 0.6 * progress * norm_post;

    // Interaction with mean residual: prefer bins whose post-residual stays near the mean
    let dev = (post - mean_residual) / cap;
    score += 8.0 * dev * dev * cap;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // Lookahead: reward leaving space that could fit the next item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let slack = post - ni;
        if slack >= 0.0 {
            // next item still fits: mild reward, smoother if slack is small
            score -= 6.0 * (1.0 - slack / cap);
        } else {
            // next item won't fit: penalize proportionally to overshoot
            score += 4.0 * (-slack / cap) * (1.0 + progress);
        }
    }

    // New-bin candidate handling: smooth preference depending on how poor fits are
    if bin_residual == bin_capacity {
        // A fresh bin is attractive when the item is large relative to capacity
        // and few bins fit, but unattractive when existing bins fit well.
        let item_frac = item_size as f64 / cap;
        let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
        score -= 30.0 * item_frac * item_frac * scarcity;
        // Opening new bins late is risky; dampen via progress
        score += 10.0 * progress;
    }

    // Mild penalty for accumulating too many open bins
    score += 0.5 * open_bins_count as f64 * norm_post;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward placements that fill a large fraction of the bin.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 15.0;

    // Dead-space penalty: post_residual too small to ever hold the lookahead item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 20.0 + post_residual as f64 * 0.3;
    }
    // Bonus when the leftover can still accommodate the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }

    // Last-chance bin before opening a new one: strong preference to use it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-empty-bin candidate handling.
    if bin_residual == bin_capacity {
        // Mildly penalize so existing bins are preferred by default.
        score += 10.0;
        // If this new bin is the only "fitting" candidate, opening it is justified.
        if fitting_bins_count == 1 {
            score += 12.0;
        }
    }

    // Harmonic classes on post_residual (decade buckets).
    let cls = post_residual % 10;
    if cls == 0 {
        // Round residuals are reusable classes: reward.
        score -= 4.0;
    } else if post_residual < 10 {
        // Tiny unusable slivers: penalize proportionally.
        score += (10 - post_residual) as f64 * 0.8;
    }

    // Slight preference to consolidate into fewer bins as the stream progresses.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * (open_bins_count as f64 - mean_residual / 10.0).max(0.0) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // minimum item size (1) are already counted by post_residual, but
    // residuals too small for typical items are dead weight. Penalize
    // unusable gaps (small but nonzero post_residual) quadratically.
    let pr = post_residual as f64;
    if post_residual > 0 {
        // gap is only useful if some future item (up to 80..100) fits
        let useful_threshold = 20.0;
        if pr < useful_threshold {
            score += (useful_threshold - pr) * (useful_threshold - pr) * 0.35;
        }
    }

    // Reward tight fits: small post_residual relative to item size.
    if item_size > 0 {
        let tightness = 1.0 - pr / (item_size as f64 + pr);
        score -= tightness * 8.0;
    }

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 15.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post
    // residual, strongly favor this bin (chain placement).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 12.0;
        } else if post_residual > next_item_size {
            score -= 2.0;
        } else if post_residual > 0 {
            // next item cannot use the leftover: dead space likely
            score += pr * 0.25;
        }
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // rather than spreading; the new-bin candidate gets penalized via its
    // large post_residual naturally, but add explicit pressure when bins
    // are scarce relative to stream progress.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (0.4 + 0.6 * progress);

    // Last-chance bonus: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // Slight preference toward bins with below-mean residual (consolidate
    // fragmentation into already-loose bins, keep tight bins tight).
    score -= (mean_residual - pr) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward a post_residual that exactly matches
    // the next item (perfect chain fit), penalize residuals too small for it.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if post_residual == next_item_size {
            score -= 25.0; // perfect lookahead match: place here
        } else if post_residual >= next_item_size {
            // partial lookahead fit: bonus proportional to closeness
            let tightness = 1.0 - (pr - nxt) / bin_capacity as f64;
            score -= 10.0 * tightness;
        } else {
            // post_residual too small for next item: dead space penalty
            score += 8.0 * (1.0 - pr / bin_capacity as f64);
        }
    }

    // Prefer tight fits for the current item: reward small post_residual
    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 5.0 * tight;

    // Penalize bins whose residual deviates strongly from mean (fragmentation)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: only attractive when current bin fits are poor
    if bin_residual == bin_capacity {
        score += 18.0;
        if fitting_bins_count <= 1 && next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0; // fresh bin guarantees good lookahead fit
        }
    }

    // Slight preference to keep bin count low early in the stream
    score += 0.05 * open_bins_count as f64 * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: prefer bins where post_residual is small relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: residuals too small for typical future items are wasted.
    let min_item = 1.0f64;
    if (post_residual as f64) < min_item {
        score += 25.0;
    } else if post_residual < item_size.min(next_item_size.max(1)) {
        // post-residual cannot fit even the smaller of current/next item
        score += 6.0;
    }

    // Lookahead coupling: bonus if the next item exactly fits the post residual.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }
    // Penalize if next item would be stranded by this placement.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 4.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // With many options, be pickier about residual quality.
        score += 0.05 * (fitting_bins_count as f64 - 1.0);
    }

    // Time horizon: early in the stream, be more conservative (favor packing into
    // existing bins to keep bin count low); late in the stream, allow new bins
    // since future flexibility matters less.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let new_bin_penalty = 30.0 * (1.0 - 0.5 * progress);
    if bin_residual == bin_capacity {
        score += new_bin_penalty;
        // Opening a new bin is attractive if the item is large and would leave
        // a well-balanced residual, or if few bins fit the item.
        if item_size >= bin_capacity / 2 {
            score -= 10.0;
        }
        if fitting_bins_count == 1 {
            score -= 18.0;
        }
    }

    // Global state: when mean residual across open bins is high, packing into
    // existing bins is cheap; when it's low, opening a new bin is less costly.
    let mean_res_gap = mean_residual - post_residual as f64;
    score += 0.10 * mean_res_gap;

    // Slight preference for bins with residual close to item_size (perfect fit).
    let slack = (bin_residual as f64 - item_size as f64).abs();
    score += 0.03 * slack;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit_frac = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let mut score = pr;

    // Smooth interaction: residual waste matters more as stream progresses.
    score += 8.0 * fit_frac * fit_frac * (0.5 + progress);

    // Reward tight fits (small post_residual) more strongly early on.
    score -= 6.0 * (1.0 - fit_frac) * (1.0 - progress);

    // Perfect-fit bonus via smooth term.
    score -= 10.0 * (-fit_frac * fit_frac * 20.0).exp();

    // Penalize bins whose residual deviates from mean residual (non-linear).
    let dev = (pr - mean_residual) / cap;
    score += 4.0 * dev * dev;

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: if next item fits exactly in post_residual, reward.
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64).abs() / cap;
        score -= 5.0 * (-diff * diff * 30.0).exp();
        // Penalize leaving residual that is awkwardly close but not equal to next item.
        score += 3.0 * diff * (1.0 - (-diff * diff * 30.0).exp());
    }

    // New-bin candidate: penalize mildly, but allow when open bins are crowded.
    if bin_residual == bin_capacity {
        let crowd = open_bins_count as f64 / (1.0 + mean_residual / cap * open_bins_count.max(1) as f64);
        score += 12.0 - 6.0 * (1.0 - (-crowd).exp());
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: quantize leftover space into capacity fractions.
    let frac = post_residual as f64 / bin_capacity as f64;

    // Penalize leftovers that fall into "dead zones" — small unusable slivers.
    // Modulo-10 classes: leftovers that are 1..=9 are hard to fill with items >=10 (or 1..100 general).
    let dead_class = post_residual % 10;
    if dead_class > 0 && post_residual < 20 {
        score += 25.0 - dead_class as f64 * 2.0;
    }

    // Integer-division thresholds on post_residual: reward coarse fill levels.
    let quarter = post_residual / (bin_capacity / 4).max(1);
    score -= quarter as f64 * 4.0;

    // Reward tight fits: post_residual small but item was large.
    if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 15 {
        score -= 10.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size < post_residual {
            let nxt_left = post_residual - next_item_size;
            // harmonic class of the double-fill leftover
            if nxt_left % 10 == 0 {
                score -= 20.0;
            }
            score += nxt_left as f64 * 0.5;
        } else {
            // next item cannot follow here; slight penalty if we're wasting a big residual on a small item
            score += (item_size as f64) * 0.1;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin to avoid opening a new one.
    if fitting_bins_count == 1 {
        score -= 35.0;
    } else if fitting_bins_count > 1 {
        score += (fitting_bins_count as f64 - 1.0) * 3.0;
    }

    // New-bin candidate handling: empty bin baseline.
    if bin_residual == bin_capacity {
        // Prefer new bin only if current residual landscape is tight (mean residual small)
        // or this item is large enough to justify a fresh bin.
        score = 40.0 + (100.0 - item_size as f64) * 0.3 - mean_residual * 0.2;
        if fitting_bins_count == 0 {
            score -= 50.0; // no open bin fits: new bin is necessary
        }
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 5.0; // fresh bin has room for lookahead too
        }
    }

    // Stream progression: late in the stream, be more conservative (avoid many near-empty bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += frac * progress * 15.0;

    // Mean residual coupling: if this bin's residual is far above mean, it's a "junk" bin — use it.
    let dev = bin_residual as f64 - mean_residual;
    if dev > 0.0 {
        score -= dev * 0.3;
    }

    // Modulo-25 harmonic bonus: residuals that are multiples of 25 pair well with common item sizes.
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize "dead space": residuals too small for the smallest plausible item (<= 10)
    // are unusable; add a strong penalty proportional to how close we are to that zone.
    let dead_zone = (10u32.saturating_sub(post_residual.min(10))) as f64;
    score += 8.0 * dead_zone * dead_zone;

    // Reward tight fits (small post_residual relative to bin capacity)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 6.0 * tightness * tightness;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 15.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Open-bin pressure: discourage spreading across many bins when residuals are large
    let pressure = open_bins_count as f64;
    score += 0.35 * pressure * ((post_residual as f64) / (bin_capacity as f64));

    // Lookahead: if the next item fits exactly in the post residual, reward this bin
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual == next_item_size {
            score -= 10.0;
        } else if post_residual - next_item_size <= 10 {
            score -= 5.0;
        }
    }

    // Mild progress-aware scaling: late in the stream, be more conservative
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 1.5 * progress * ((post_residual as f64) / (bin_capacity as f64));

    // Mean-residual coupling: bins with residual well below mean are scarcer; prefer them
    score -= 0.5 * ((mean_residual - bin_residual as f64).max(-20.0).min(20.0));

    // New-bin candidate: neutral-ish baseline so it only wins when fits are poor
    if bin_residual == bin_capacity {
        score += 25.0 + 0.5 * pressure;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: penalize (subtract) when post_residual is small but nonzero.
    if post_residual > 0 {
        score -= 12.0 / post_residual as f64;
    } else {
        // Perfect fit: strong reward.
        score -= 25.0;
    }

    // Dead-space penalty: residuals too small for any item (min size 1) are worthless,
    // but residuals below the typical small-item threshold are especially bad.
    if post_residual < 10 && post_residual > 0 {
        score += 8.0;
    }

    // 2-step lookahead: reward if the next item fits exactly in the post-residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0; // chain fit: this bin absorbs the next item perfectly
        } else if post_residual > next_item_size {
            score -= (post_residual - next_item_size) as f64 * 0.3; // next item still fits
        } else {
            score += (next_item_size - post_residual) as f64 * 0.4; // next item won't fit here
        }
    }

    // Relative-to-mean coupling: prefer bins tighter (smaller residual) than average.
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: make empty bins moderately unattractive unless the fit
    // is truly bad elsewhere (post_residual huge or next item mismatch).
    if bin_residual == bin_capacity {
        score += 10.0 + item_size as f64 * 0.2;
        // But if the item is large relative to capacity, opening fresh is fine.
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 18.0;
        }
    }

    // Mild late-stream consolidation: as the stream progresses, prefer filling
    // existing bins over opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= progress * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small to hold typical future items.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let dead_zone = (post_residual as f64 / bin_capacity as f64).powi(3);
    score += 25.0 * dead_zone * (0.5 + 0.5 * progress);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item can reuse the post-residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += 6.0;
        }
    }

    // Global state coupling: many open bins with high mean residual -> prefer consolidation.
    let spread = bin_residual as f64 - mean_residual;
    score += 0.05 * spread;
    score += 0.5 * open_bins_count as f64 * (1.0 - fit_ratio);

    // New-bin candidate: only attractive when no open bin fits (fitting_bins_count == 0
    // among open bins implies this empty bin is the sole fit) or the fit here is poor.
    if bin_residual == bin_capacity {
        if fitting_bins_count <= 1 {
            score -= 20.0; // opening a fresh bin is fine
        } else {
            score += 60.0; // strongly prefer reusing an existing bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 + 2.0 * progress) - norm_pr * progress * (1.0 - progress);

    let mut score = pr + 40.0 * poly;

    // Reward tight fits (small post_residual) more strongly as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= 25.0 * tightness * tightness * (0.5 + progress);

    // Last-chance bonus: strongly prefer this bin when it is the only fitting one
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * progress;
    }

    // Penalize bins far from mean residual (fragmentation avoidance)
    score += 5.0 * ((pr - mean_residual) / cap).abs();

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            score -= 12.0 * (1.0 - ((pr - ni) / cap).abs());
        } else {
            score += 10.0;
        }
    }

    // Mild penalty for opening a new bin when others fit, easing late in stream
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 35.0 - 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "usable" classes (large enough to host typical items) are favored.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fraction of capacity remaining after placement.
    let frac = pr / cap;

    // Dead-space penalty: residuals that are too small to host anything
    // useful (here < 10% of capacity) are heavily penalized.
    if pr > 0 && frac < 0.10 {
        score += 60.0 * (0.10 - frac);
    }

    // Harmonic classes via integer division: classify post_residual into
    // buckets of size 10 (capacity fractions). Buckets aligned with common
    // item sizes get a bonus.
    let class = post_residual / 10;
    match class {
        0 => score += 25.0,              // 0..9  : near-dead space
        1 => score += 12.0,              // 10..19: only tiny items fit
        2 => score += 4.0,               // 20..29
        3 => score -= 2.0,               // 30..39: decent slot
        4 | 5 => score -= 5.0,           // 40..59: good slot
        6 | 7 => score -= 7.0,           // 60..79: very good slot
        _ => score -= 9.0,               // 80..100: nearly fresh bin
    }

    // Modulo-based harmony: if next_item_size fits exactly into the
    // post_residual class boundary, reward it strongly.
    if next_item_size > 0 && next_item_size <= post_residual {
        let harmony = post_residual % next_item_size;
        if harmony == 0 {
            score -= 15.0; // perfect fit for the lookahead item
        } else if harmony < 5 {
            score -= 6.0;
        } else {
            score += harmony as f64 * 0.5; // wasted lookahead space
        }
    } else if next_item_size > 0 {
        // Next item cannot use this residual: mild penalty proportional
        // to how much space would be stranded.
        score += (next_item_size - post_residual) as f64 * 0.3;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: an empty bin has maximal residual;
    // make it attractive only when open bins are fragmented or the
    // current item is large relative to the best available space.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, offset when many open bins
        // already exist with low mean residual (fragmentation).
        score = cap - 12.0;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if open_bins_count > 0 {
            let frag = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
            score -= 20.0 * frag;          // fragmented state favors new bin
        }
        if item_size >= 70 {
            score -= 10.0;                 // big items like a fresh bin
        }
        if next_item_size > 0 && next_item_size >= 60 {
            score -= 8.0 * progress.max(0.5); // lookahead pairs well with fresh bin
        }
    }

    // Slight global pressure: later in the stream, prefer tightening
    // existing bins (closing them out) over spreading.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 3.0 * progress * (pr / cap);

    // Prefer bins below mean residual (tightening the worst bins first
    // keeps the fleet balanced).
    score += (mean_residual - pr) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual is "dead" if it is smaller than the smallest plausible item (1..100 stream).
    let min_gap = 10.0f64;
    if (post_residual as f64) < min_gap {
        score += 60.0; // wasted space, nothing can ever go here
    } else if post_residual <= 20 {
        score += 25.0 * (1.0 - post_residual as f64 / 20.0); // near-dead gap penalty
    }

    // Reward very tight fits (post_residual small but still usable).
    if post_residual > 0 && post_residual <= 15 {
        score -= 12.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless the fit is good.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.35 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Prefer bins whose residual deviates favorably from the mean residual
    // (place into tighter-than-average bins to consolidate space).
    let dev = bin_residual as f64 - mean_residual;
    score -= 0.15 * dev;

    // Lookahead: if the next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack <= 10 {
                score -= 20.0; // next item fills this bin nicely
            } else {
                score -= 5.0;
            }
        } else {
            score += 8.0; // next item won't fit here; residual likely becomes dead space
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: neutral baseline with mild bias so it is chosen only
    // when open bins have genuinely poor fits.
    if bin_residual == bin_capacity {
        score += 15.0 + 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: match post_residual to the next item's size (2-step lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 60.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Post-residual is dead space for the next item: penalize proportionally.
        score += 0.5 * (next_item_size - post_residual) as f64;
    }

    // Reward residuals that align with mean residual (keeps bins homogeneous).
    let diff = (post_residual as f64 - mean_residual).abs();
    score -= 0.3 * (bin_capacity as f64 - diff);

    // Tight fit bonus: penalize large leftover relative to bin capacity.
    score += 0.4 * (post_residual as f64 / bin_capacity as f64) * (post_residual as f64);

    // Last-chance bonus: strongly favor using the only bin that fits, avoid opening new bins.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Mild preference for existing bins over opening a new one early in the stream.
    if bin_residual == bin_capacity {
        score += 8.0 + (open_bins_count as f64).sqrt();
    } else {
        score -= 2.0;
    }

    // Late-stream consolidation: push toward filling bins as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (bin_capacity - post_residual) as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio;

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += (next_item_size as f64 - post_residual as f64) * 0.3;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item fits poorly everywhere.
    if bin_residual == bin_capacity {
        score += 30.0;
        if fitting_bins_count > 0 {
            score += 20.0 * (fitting_bins_count as f64).min(3.0);
        }
        // Late in stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 * progress;
    }

    // Prefer bins below mean residual (leave larger bins for larger future items).
    score += 0.15 * (bin_residual as f64 - mean_residual).max(0.0);

    // Many open bins: favor filling existing ones harder.
    score -= 2.0 * (open_bins_count as f64).ln().max(0.0) * (1.0 - fit_ratio);

    // Exact fill bonus.
    if post_residual == 0 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with mild non-linear sharpening.
    let mut score = post * (1.0 + 0.5 * (post / cap));

    // Smooth polynomial coupling with stream progress:
    // early on, keep bins flexible (favor larger post_residual slightly);
    // late, pack tightly (favor small post_residual strongly).
    let flex = 30.0 * (1.0 - progress) * (1.0 - progress) * (post / cap);
    score += flex;

    // Dead-space penalty: residual too small to fit the next item is wasted
    // unless the stream is nearly done.
    if next_item_size > 0 && post_residual < next_item_size {
        let waste = (next_item_size as f64 - post) / cap;
        score += 25.0 * waste * (1.0 + progress);
    } else if next_item_size > 0 {
        // Reward leaving room that exactly accommodates the next item.
        let gap = (post_residual - next_item_size) as f64 / cap;
        score -= 10.0 * (1.0 - gap.min(1.0)) * (1.0 - progress);
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Mildly discourage opening new bins when many bins are already open
    // and this bin has a good fit relative to the mean residual.
    let is_new_bin = (bin_residual as f64 - cap).abs() < 0.5;
    if is_new_bin {
        score += 15.0 + 5.0 * (open_bins_count as f64).ln().max(0.0);
        // But if mean residual across open bins is small (all bins tight),
        // opening a fresh bin is attractive.
        score -= (mean_residual / cap) * 20.0;
    }

    // Slight reward for bins already below mean residual (consolidation).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual space: classify by capacity fractions
    let frac = post_residual as f64 / bin_capacity as f64;
    let class = (frac * 10.0).floor() as i64; // 0..10 harmonic decile

    // Dead space penalty: residuals that can only fit tiny items are bad.
    // Penalize residuals in the "awkward" harmonic classes (small but nonzero).
    if post_residual > 0 {
        let awkward = (10 - class) as f64 / 10.0;
        score += awkward * awkward * 25.0;
    }

    // Perfect fit reward (harmonic class 0)
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 10 {
        // near-perfect: leaves a class-1 sliver, mild reward
        score -= 15.0;
    }

    // Modulo logic: does next item fit harmonically into the post residual?
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        // Reward chains where next item leaves another useful residual
        let next_class = ((gap as f64 / bin_capacity as f64) * 10.0).floor() as i64;
        score -= 10.0 + (next_class as f64);
        if gap == 0 {
            score -= 40.0; // double perfect chain
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Next item can't use this bin's remainder: penalize proportionally
        let waste = post_residual as f64;
        score += waste * 0.3;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: score it against mean residual of open bins.
    // Opening a new bin is attractive when open bins are already tight (low mean residual)
    if bin_residual == bin_capacity {
        // base cost of a fresh bin: proportional to stream progress
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = 60.0 + 40.0 * progress;
        // If current item is large, a fresh bin is more attractive (large items pair poorly)
        if item_size >= 50 {
            score -= 15.0;
        }
        // If many open bins have room (high mean residual), prefer reusing
        if mean_residual > item_size as f64 {
            score += 20.0;
        }
        // If only one fitting bin exists, discourage new bin
        if fitting_bins_count <= 1 {
            score += 50.0;
        }
    }

    // Small coupling: prefer filling bins whose residual is close to item size (tight fit)
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever hold
    // the smallest plausible item are pure waste -> heavy penalty.
    let min_item = 1u32;
    if post_residual < min_item {
        score -= 1000.0; // perfect fit (unreachable given min item 1, kept for safety)
    }

    // Penalize dead space relative to how "usable" it is.
    // A residual that can still fit typical items is fine; a sliver is bad.
    let dead_threshold = 15.0;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 4.0;
    }

    // Reward tight fits: small post_residual generally good (already base score).
    // Extra bonus for exact-ish fills.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Lookahead coupling: if the next item fits into this bin's post-residual,
    // reward; otherwise penalize slightly since gap may become dead space.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Open-bin pressure: prefer consolidating into existing bins rather than
    // opening new ones, especially as the number of open bins grows.
    let is_new_bin = bin_residual == bin_capacity && post_residual == bin_capacity - item_size;
    if is_new_bin {
        score += 30.0 + 5.0 * open_bins_count as f64;
        // Opening a new bin is acceptable early in the stream or when no
        // reasonable fit exists (last chance bin with bad post-residual).
        let progress = step_index as f64 / total_items.max(1) as f64;
        if fitting_bins_count <= 1 && post_residual < dead_threshold as u32 {
            score -= 40.0 * (1.0 - progress);
        }
    } else {
        // Favor bins that are already fairly full (low residual before placement).
        score += (bin_residual as f64) * 0.05;
        // Last-chance bonus: if this is the only bin that fits, use it.
        if fitting_bins_count == 1 {
            score -= 25.0;
        }
    }

    // Mild mean-residual coupling: placing into a bin below the mean residual
    // (i.e., a fuller bin than average) is preferred.
    score += (mean_residual - bin_residual as f64).max(-50.0).min(50.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= tightness * 12.0;

    // 2-step lookahead: reward when next item fits exactly into post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item cannot follow here; penalize large dead space.
            score += 0.15 * (next_item_size - post_residual) as f64;
        }
    }

    // Compare against mean residual: prefer bins with below-mean residual (fill fuller bins first).
    score += (post_residual as f64 - mean_residual) * 0.4;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize opening a new bin when plenty of open bins fit the item.
    if bin_residual == bin_capacity {
        score += 8.0 + 2.0 * fitting_bins_count as f64;
        // Late in the stream, avoid proliferation of open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Mild penalty for leaving very small unusable slivers (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic penalty on wasted space
    score += 0.35 * (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64);

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0 + 0.25 * (next_item_size as f64);
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // dead space that the next item cannot use
        score += 12.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Encourage filling bins with large residual when mean residual is high (fragmentation pressure)
    score -= 0.10 * (bin_residual as f64 - mean_residual);

    // Late in the stream: consolidate into fewer bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 8.0 * (open_bins_count as f64).ln().max(0.0) * (post_residual as f64) / (bin_capacity as f64);

    // New-bin candidate: neutral-ish baseline, only chosen when open bins fit poorly
    if bin_residual == bin_capacity {
        score += 30.0 + 0.5 * (post_residual as f64);
        // opening a new bin is more attractive early (more future items to fill it)
        score -= 20.0 * (1.0 - progress);
        // and when many bins can't fit well (few fitting bins)
        score -= 6.0 * (fitting_bins_count as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth base: reward tight fits (low post_residual), non-linearly.
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Polynomial coupling of post_residual with stream progress:
    // early on, tolerate larger residuals (open bins freely);
    // late in the stream, penalize wasted space more strongly.
    let late_weight = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += 25.0 * late_weight * norm_pr;

    // Dead-space penalty: residuals too small for any plausible item (1..100)
    // are wasted; smooth quadratic penalty around the unusable zone.
    if pr > 0 {
        let unusable = (1.0 - pr / 100.0).clamp(0.0, 1.0);
        score += 12.0 * unusable * unusable;
    }

    // Lookahead: if next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // soft reward proportional to how well next item fills leftover
        let fill = next_item_size as f64 / pr.max(1.0);
        score -= 10.0 * fill * fill;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0 * (1.0 - norm_pr);
    }

    // New-bin candidate handling: mild penalty so we prefer good existing fits,
    // but reduced late in the stream when opening fresh bins is often better.
    if bin_residual == bin_capacity {
        score = pr + 6.0 * (1.0 - late_weight) + 2.0 * (open_bins_count as f64).sqrt();
    }

    // Slight preference for bins whose residual deviates from the mean
    // (consolidate space): reward bins tighter than average.
    let dev = (mean_residual - bin_residual as f64) / cap;
    score -= 5.0 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: quantize dead space into capacity fractions.
    let cap_f = bin_capacity as f64;
    let post_f = post_residual as f64;
    let post_class = (post_residual / 10) as f64; // integer-division class, 0..=10

    // Reward near-perfect fits heavily (small post_residual classes).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    } else {
        // Penalize unusable dead space: residual too small for typical min item (1..100,
        // but small items are the only thing that can fill tiny gaps).
        score += post_class * 2.5;
        if post_residual < 10 {
            score += 20.0; // dead space: nothing smaller than 10 guaranteed
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
        // But if post-residual becomes dead space anyway, dampen the bonus.
        if post_residual > 0 && post_residual < 10 {
            score += 15.0;
        }
    }

    // New-bin candidate handling: an empty bin has large residual; make it moderately
    // attractive only when the current bin would leave big dead space or the item
    // pairs well with the lookahead item.
    if bin_residual == bin_capacity {
        // Baseline score for opening a new bin: post_residual = cap - item.
        // Add a fixed opening cost, discounted late in the stream.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 10.0 - 5.0 * progress;

        // If next item fits perfectly with this item in a fresh bin (sums to ~capacity),
        // strongly favor the new bin.
        let pair = item_size as u64 + next_item_size as u64;
        if next_item_size > 0 {
            if pair == bin_capacity as u64 {
                score -= 80.0;
            } else if pair <= bin_capacity as u64 {
                score -= (bin_capacity as u64 - pair) as f64 * 0.5;
            }
        }
    } else {
        // Placing in an open bin: reward if the lookahead item fits the post-residual
        // (keeps the bin productive).
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 12.0;
            // Extra reward for a tight follow-up fit.
            if post_residual - next_item_size <= 5 {
                score -= 8.0;
            }
        } else if next_item_size > post_residual {
            // Lookahead won't fit here; mildly penalize leaving awkward gaps.
            if post_residual > 0 && post_residual < 20 {
                score += 10.0;
            }
        }
    }

    // Modulo arithmetic on post_residual: harmonic classes that historically pack well
    // (multiples of 10 leaving room for mid-size items) get a small bonus.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    // Crowd control: many open bins -> prefer consolidating into existing bins.
    if open_bins_count > 8 {
        score -= 2.0;
    }
    if bin_residual < bin_capacity && mean_residual > 0.0 && (post_residual as f64) < mean_residual {
        score -= 4.0; // this bin ends up tighter than average: good consolidation
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for typical items are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - 6.0 * post_residual as f64;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 40.0;
    } else if post_residual <= 20 {
        // Moderately small gaps are risky dead space.
        score += 8.0;
    }

    // Reward bins whose residual tightly matches the item (small waste relative to residual).
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 12.0 * tightness;

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits the post-residual, this placement is doubly useful.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 5.0;
    }

    // Open-bin pressure: discourage proliferation of bins unless the fit is good.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.35 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // New-bin candidate: attractive when the item is large or fits are scarce,
    // unattractive when an open bin gives a near-perfect fit.
    if bin_residual == bin_capacity {
        let scarce = fitting_bins_count as f64;
        let item_pressure = item_size as f64 / bin_capacity as f64;
        score -= 15.0 * item_pressure + 6.0 / scarce.max(1.0);
        // Penalize opening a new bin when mean residual of open bins is still large.
        score += 0.25 * mean_residual;
        // A fresh bin is more attractive early in the stream.
        score -= 10.0 * (1.0 - progress);
    }

    // Mild preference for bins below mean residual (consolidating waste).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), scaled by capacity fraction.
    score += 0.5 * (post_residual as f64 / bin_capacity as f64) * 100.0;

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if (post_residual as i64 - next_item_size as i64).abs() <= 2 {
            score -= 60.0; // perfect chain: next item seals this bin
        } else if post_residual >= next_item_size {
            // next item can still fit here; reward proportional to how well it fills
            let chain_fit = 1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64);
            score -= 40.0 * chain_fit;
        } else {
            // next item cannot fit here; penalize dead space relative to next item
            let waste = (next - post_residual as f64).max(0.0);
            score += 0.8 * waste;
        }
    } else {
        // last item: any residual is pure waste; minimize it hard
        score += 2.0 * post_residual as f64;
    }

    // Relative-to-mean coupling: bins with residual far below mean are scarce-space bins;
    // placing there is efficient if fit is tight.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.15 * dev; // prefer bins tighter than average

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when no open bin
    // offers a decent fit. Penalize the fresh bin (residual == capacity) increasingly
    // as the stream progresses and open bins exist.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 25.0 + 30.0 * progress;
        if open_bins_count == 0 {
            score -= 200.0; // must open a bin
        }
        // fresh bin is fine if next item is large and no bin fits well
        if next_item_size > 0 && next_item_size as f64 > mean_residual {
            score -= 20.0;
        }
    }

    // Mild pressure to consolidate: fewer open bins is better; prefer filling existing bins
    // over spreading when fits are comparable.
    score += 0.5 * (open_bins_count as f64).ln().max(0.0) * (item_size as f64 / 100.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) more strongly than linear.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 8.0 * tight * tight;

    // Lookahead: if the next item fits exactly into post_residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here: penalize leaving large unusable gaps.
            score += 0.15 * (post_residual as f64 - (next_item_size as f64 - post_residual as f64)).abs();
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Penalize bins far below mean residual (fragmentation avoidance).
    score += 0.5 * (mean_residual - bin_residual as f64).abs();

    // Time horizon: early in stream, be conservative (prefer filling existing bins);
    // later, allow opening new bins for better long-term packing.
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    score += (1.0 - progress) * 6.0 * (bin_residual == bin_capacity) as i32 as f64;

    // Mild penalty for spreading across too many open bins.
    score += 0.05 * open_bins_count as f64;

    // Prefer bins whose residual will remain "useful" (>= smallest plausible item).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;

    // Base: minimize post residual, scaled by smooth progress coupling
    let mut score = pr * (1.0 + 0.5 * t * t);

    // Non-linear penalty on very small post residuals (dead space) via smooth polynomial
    let norm_pr = pr / cap;
    let dead = (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 - norm_pr);
    score += 8.0 * dead * (1.0 - it / cap);

    // Reward tight fits (post_residual small relative to item)
    let tight = (item_size as f64) / (bin_residual as f64 + 1.0);
    score -= 10.0 * tight * tight;

    // Last-chance bin: strong reward to use it
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * t;
    }

    // Lookahead: if next item fits post residual, reward; else penalize
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if post_residual >= next_item_size {
            score -= 6.0 * (n / cap);
        } else {
            score += 4.0 * (n / cap) * (1.0 - pr / n.max(1.0));
        }
    }

    // Encourage filling bins when many open bins exist
    score += 0.3 * (open_bins_count as f64).ln().max(0.0) * (pr / cap);

    // Prefer bins with residual close to mean (balance) via smooth quadratic
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 3.0 * dev * dev;

    // New-bin candidate: penalize mildly unless current fits are poor
    if bin_residual == bin_capacity {
        score += 5.0 - 8.0 * (pr / cap) * 0.0;
        score += 5.0;
        // If no other bin fits well, opening new bin becomes attractive
        if fitting_bins_count == 0 {
            score -= 12.0;
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: prefer residuals that fall into "useful"
    // residue classes modulo common item-size divisors.
    let pr = post_residual;
    let mut class_bonus = 0.0;

    // Residuals divisible by 10 or 20 are highly reusable (items 10..80 often multiples).
    if pr % 10 == 0 { class_bonus += 6.0; }
    if pr % 20 == 0 { class_bonus += 4.0; }
    if pr % 25 == 0 { class_bonus += 3.0; }

    // Dead-space penalty: small nonzero residuals are hard to fill.
    if pr > 0 && pr < 10 {
        score += 25.0;
    } else if pr >= 10 && pr < 20 {
        score += 8.0;
    }

    // Integer-division thresholds: how many "typical" small items still fit?
    let fits_10 = pr / 10;
    let fits_20 = pr / 20;
    let fits_40 = pr / 40;
    score -= 1.5 * fits_10 as f64;
    score -= 2.0 * fits_20 as f64;
    score -= 3.0 * fits_40 as f64;

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            class_bonus += 30.0;
        } else if next_item_size <= pr {
            let gap = pr - next_item_size;
            if gap % 10 == 0 { class_bonus += 8.0; }
            class_bonus += (gap as f64).sqrt() * 0.5;
        } else {
            // Next item won't fit here; slight penalty for near-full residual.
            class_bonus -= 2.0;
        }
    } else {
        // Last item: just minimize wasted space (already in base score).
        class_bonus += 2.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        class_bonus += 12.0;
    }

    // New-bin candidate: make it unattractive unless all open bins are bad fits.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        class_bonus -= 15.0;
        // But if the current bin would leave huge dead space, opening fresh is OK.
        if item_size >= 60 {
            class_bonus += 10.0;
        }
        // Late in stream, prefer closing out open bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        class_bonus -= progress * 5.0;
    }

    // Tight-fit reward: minimal post residual overall is good (already base), add
    // extra for near-perfect fills.
    if pr <= 5 && pr > 0 {
        class_bonus += 10.0;
    }
    if pr == 0 {
        class_bonus += 15.0;
    }

    // Mean-residual coupling: if this bin is far below mean residual, it's a
    // laggard bin — prefer filling it to consolidate.
    let diff = mean_residual - pr as f64;
    if diff > 10.0 {
        class_bonus += (diff * 0.3).min(10.0);
    }

    score -= class_bonus;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    // A post_residual below the minimum item size (1) is impossible, but gaps
    // that are too small for the *next* item are effectively dead space.
    if next_item_size > 0 && post_residual < next_item_size {
        let dead_ratio = (next_item_size - post_residual) as f64 / bin_capacity as f64;
        score += dead_ratio * 60.0;
    }

    // Extra penalty for very small gaps (likely unusable by any future item).
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 3.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage spreading across many bins early,
    // encourage compacting when many bins are open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.4 + 0.6 * progress);
    score += pressure * 0.5;

    // Slight preference for bins tighter than average (good packing zones).
    score += (mean_residual - bin_residual as f64) * 0.15;

    // Lookahead: if next item fits exactly in post_residual, reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }

    // New-bin candidate: mild penalty so it's only chosen when open bins are bad.
    if bin_residual == bin_capacity {
        score += 5.0 + open_bins_count as f64 * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // next item fits, but penalize leftover slack after the pair
            score -= 50.0 - ((post_residual - next_item_size) as f64).min(50.0);
        } else {
            // next item won't fit here: penalize dead space
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Relative to mean residual: prefer bins whose residual is close to item size (tight fit)
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.1;

    // Prefer bins with residual below mean (more filled bins get closed out)
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 2.0;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Early stream: be more conservative with opening new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize unless progress suggests many items remain
        score += 40.0 + progress * 20.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score += 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize large dead space non-linearly (squaring amplifies waste).
    score += 0.35 * (post_residual as f64) * (post_residual as f64) / bin_capacity as f64;

    // Reward tight fits: small post_residual relative to item size.
    if item_size > 0 {
        score -= (item_size as f64) * 0.6;
    }

    // Lookahead: if the next item can fit exactly into the post-residual,
    // strongly reward this placement (perfect chaining).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // Reward proportional to how well next item fills leftover space.
            score -= 12.0 * (next_item_size as f64) / (post_residual.max(1) as f64);
        } else {
            // Next item won't fit here; slight penalty scaled by overflow size.
            score += 0.08 * ((next_item_size - post_residual) as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0;
    }

    // Prefer bins with residual below the mean (compact the small leftovers).
    let diff = mean_residual - bin_residual as f64;
    score += 0.15 * diff;

    // Time horizon: early in the stream, be more conservative (favor opening
    // new bins when fit is poor); late in the stream, squeeze into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 8.0;
    score += (1.0 - progress) * 0.05 * post_residual as f64;

    // Mild penalty when many bins are already open (encourage consolidation).
    score += 0.02 * open_bins_count as f64;

    // New-bin candidate: make it attractive only when the item fits poorly
    // everywhere else; a fresh bin gets a neutral baseline with slight bonus
    // for large items that would leave big dead space elsewhere.
    if bin_residual == bin_capacity {
        score = 55.0 + 0.1 * post_residual as f64;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0;
        }
        if fitting_bins_count <= 1 {
            score -= 30.0; // no good alternative: opening a new bin is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let mut score = pr;

    // Non-linear polynomial coupling: residual cost grows super-linearly with progress
    let prn = pr / cap;
    score += 8.0 * prn * prn * (0.5 + progress);

    // Tight fits are valuable; reward quadratically
    let tight = 1.0 - prn;
    score -= 6.0 * tight * tight * (1.0 + progress);

    // Lookahead: bonus if next item fits the post-residual exactly-ish
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let slack = (pr - nxt) / cap;
            score -= 5.0 * (1.0 - slack) * (1.0 - slack);
        } else {
            score += 3.0 * ((nxt - pr) / cap);
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 7.0;
    }

    // Penalize fragmentation relative to mean residual
    score += 0.15 * (pr - mean_residual).abs();

    // Mild pressure to consolidate when many bins are open
    score += 0.05 * open_bins_count as f64 * prn;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: dead-space classes modulo capacity fractions
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Penalize residuals that are "hard to fill": small residuals that can't
    // host typical items (min item size is 1, but typical stream items larger).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable sliver
    }

    // Modulo-classes: residuals divisible by common sizes are reusable
    let harmonic = |r: u32| -> f64 {
        let mut h = 0.0;
        for m in [5u32, 10, 20, 25, 50] {
            if r % m == 0 && r > 0 {
                h += 12.0;
            }
        }
        h
    };
    score -= harmonic(post_residual);

    // Integer-division thresholds: classify post_residual into thirds of capacity
    let third = (bin_capacity / 3).max(1);
    let two_thirds = 2 * third;
    if post_residual > two_thirds {
        score -= 25.0; // roomy bin, good
    } else if post_residual > third {
        score += 10.0; // middle zone
    } else if post_residual > 0 {
        score += 20.0; // tight zone
    }

    // Lookahead coupling: if next item fits post_residual, big reward
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 45.0;
            // harmonic bonus if next item lands exactly
            if next_item_size == post_residual {
                score -= 80.0;
            }
        } else {
            // next item won't fit here; penalize proportionally to overshoot class
            let gap = next_item_size - post_residual;
            score += (gap as f64) * 0.5;
        }
    } else {
        // last item: just minimize residual
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 70.0;
    }

    // New-bin candidate handling: neutral-ish baseline, slightly worse than a
    // decent fit but better than a bad fit.
    if bin_residual == bin_capacity {
        score += 30.0;
        // If many open bins are fragmented, new bin is more attractive
        score -= (open_bins_count as f64) * 0.3;
    }

    // Mean residual context: prefer bins below mean residual (tighter packing)
    score += (pr - mean_residual) * 0.4;

    // Stream progression: early on, be greedy about filling; late, conservative
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        // Treat gaps below ~10 (typical minimum item) as total waste.
        let dead = if post_residual < 10 { post_residual as f64 * 8.0 } else { 0.0 };
        score += dead;

        // Non-linear penalty on residual that cannot host the lookahead item.
        if next_item_size > 0 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.6;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 25.0;
    }

    // Reward tight fits relative to residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 15.0;

    // Last-chance bin pressure: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: when many bins are open, prefer filling existing bins
    // over opening new ones; when few bins are open, new bins are cheaper.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let bin_pressure = (open_bins_count as f64).ln().max(0.0) * (2.0 + 3.0 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure term.
        score += 30.0 + bin_pressure;
        // Opening a fresh bin is attractive if residuals elsewhere are large
        // (existing bins are fragmented) or if lookahead fits a fresh bin well.
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 8.0;
        }
        if mean_residual > 40.0 {
            score -= 10.0;
        }
    } else {
        // Existing bin: mild bonus when its residual is below average (already compact).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // partial credit scaled by how well it fits
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 200.0 * fill;
        } else {
            // next item too big for this residual: penalize large dead space
            score += 0.5 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Compare post_residual against mean residual of open bins
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // Penalize opening a new bin early in the stream less; later, prefer consolidation
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 50.0 + 200.0 * progress;
    }

    // Slight penalty for leaving small unusable gaps
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong preference for tight fits: reward small post-residual non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize awkward dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    } else if post_residual >= 10 && post_residual < 30 {
        score += 6.0 * (1.0 - (post_residual as f64 - 10.0) / 20.0);
    }

    // Lookahead: reward bins whose post-residual exactly accommodates the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item cannot use leftover space; mild penalty scaled by gap.
            score += 4.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, using it avoids a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
        if post_residual <= 15 { score -= 10.0; } // near-perfect last-chance fit
    }

    // New-bin candidate handling: an empty bin should only win when open bins fit poorly.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; grows with number of open bins.
        score += 30.0 + 2.0 * open_bins_count as f64;
        // But if existing bins are fragmented (high mean residual spread) and this
        // item is large, opening fresh may be wise: discount the new-bin cost.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if item_size > bin_capacity / 2 && mean_residual < item_size as f64 * 1.2 {
            score -= 25.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0; // new bin can host the next item too
        }
        let _ = progress;
    }

    // Global fragmentation pressure: when many bins are open with large mean residual,
    // prefer consolidating into existing bins (favor bins whose residual is near mean).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Mild time-horizon modulation: early in stream, be conservative about waste;
    // late in stream, prioritize closing bins tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * 3.0 * tightness;
    score += progress * (post_residual as f64 / bin_capacity as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear waste penalty: quadratic in post-residual, amplified with progress
    score += (post / cap).powi(2) * cap * (0.5 + progress);

    // Reward tight fits (small post_residual relative to item size)
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * tightness * cap * 0.3;

    // Last-chance bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= cap * (0.8 + progress);
    }

    // Penalize bins far below mean residual (keeps residuals balanced)
    score += (post - mean_residual) * 0.15;

    // Lookahead: penalize leaving residual too small for the next item
    if next_item_size > 0 && post > 0 {
        let fits_next = post >= next_item_size as f64;
        if fits_next {
            score -= 4.0 + progress * 6.0;
        } else {
            score += 3.0;
        }
    }

    // New-bin candidate: penalize opening a bin, less so late in the stream
    if bin_residual == bin_capacity {
        score += cap * (1.2 - 0.4 * progress) + open_bins_count as f64 * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify dead space by residue classes mod 20
    let post = post_residual as i64;
    let cls = post % 20;
    // Classes that are "harmonic" with typical item sizes (multiples of 10, 20)
    let harmonic = if post == 0 { 3.0 }
        else if post % 10 == 0 { 2.0 }
        else if post % 5 == 0 { 1.0 }
        else { 0.0 };
    score -= harmonic * 6.0;

    // Dead-space penalty: small awkward residuals are wasted space
    if post > 0 && post < 10 {
        score += (10 - post) as f64 * 1.5;
    }
    // Integer-division threshold: post_residual in [10,30) can host mid-size items
    if post >= 10 && post < 30 {
        score -= 4.0;
    }

    // Lookahead coupling: can next item fit into post_residual?
    if next_item_size > 0 {
        if (next_item_size as u32) <= post_residual {
            // reward if next item's harmonic class matches post_residual
            let diff = post_residual - next_item_size;
            if diff % 10 == 0 { score -= 8.0; } else if diff % 5 == 0 { score -= 5.0; } else { score -= 2.0; }
        } else {
            // next item won't fit: penalize proportional to overflow gap
            let gap = next_item_size as i64 - post;
            score += gap as f64 * 0.5;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening a new bin unless item is large relative to capacity
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / bin_capacity as f64;
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // prefer new bins for large items or late in stream when mean residual is fragmented
        score += 20.0 - frac * 15.0 - progress * 5.0 - (mean_residual / bin_capacity as f64) * 5.0;
        if open_bins_count == 0 { score -= 30.0; }
    }

    // Tie-break toward tighter fills as stream progresses
    score -= (item_size as f64 / bin_capacity as f64) * (2.0 + 3.0 * (step_index as f64 / total_items.max(1) as f64));

    // Penalize bins far above mean residual (fragmented outliers)
    score += ((bin_residual as f64 - mean_residual).abs()) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // typical future items are "dead space" -> heavy penalty.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // nearly unusable gap
        } else if post_residual < 20 {
            score += 25.0;
        } else if post_residual < 30 {
            score += 8.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Prefer bins whose residual is close to the item (tight packing).
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score += tightness * 20.0;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, prefer filling.
    score += (open_bins_count as f64) * 1.5;

    // New-bin candidate: only attractive if no open bin fits well
    // (i.e., this call is on an empty bin with a large post_residual).
    if bin_residual == bin_capacity {
        // Opening a new bin is penalized by default; the dead-space terms
        // on open bins must be worse than this to win.
        score += 45.0 + (open_bins_count as f64) * 2.0;
        // If the next item is small, a fresh bin keeps flexibility.
        if next_item_size > 0 && next_item_size < 25 {
            score -= 15.0;
        }
    }

    // Lookahead: reward leaving room for the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: post_residual equals next item -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 50.0;
    }

    // Next item fits in the post residual: reward tight lookahead match.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here: penalize wasted residual.
        score += 6.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Prefer bins with residuals below the mean (tighter bins first).
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New empty bin candidate: penalize opening a new bin unless the item
    // is large and no good fit exists.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 > 0.7 * bin_capacity as f64;
        if fitting_bins_count > 1 || !large_item {
            score += 30.0;
        } else {
            score += 5.0;
        }
    }

    // Slight preference to consolidate into fewer bins early in the stream.
    score += 0.1 * open_bins_count as f64 * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (low post residual), non-linearly amplified.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness * tightness;

    // Perfect fit gets an extra bonus.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual < 10 {
        score -= 8.0;
    }

    // Penalize dead space that is too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item (chaining),
    // penalize bins that would leave a gap just barely missing the next item.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0 * (1.0 - (post_residual as f64 - next_item_size as f64) / bin_capacity as f64);
        } else if next_item_size > post_residual && next_item_size - post_residual <= 10 {
            score += 10.0; // near-miss gap: likely dead space
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // More competing bins -> prefer the tightest one; slight penalty for loose fits.
    if fitting_bins_count > 1 {
        score += (post_residual as f64) * 0.05 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate handling: opening a bin is costly early (few open bins),
    // cheaper later when many bins are open and fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        let open_pressure = (open_bins_count as f64 / 20.0).min(1.0);
        // Base cost of a new bin, discounted when existing bins are fragmented
        // and late in the stream.
        score += 45.0
            - 15.0 * fragmentation
            - 10.0 * open_pressure
            - 8.0 * progress;
        // If no open bin fits well (large post residuals elsewhere), new bin is fine.
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    } else {
        // Slight preference to fill bins below mean residual (balance avoidance
        // of fragmentation): bins with larger residual than mean get a nudge penalty.
        if (bin_residual as f64) > mean_residual {
            score += 0.05 * (bin_residual as f64 - mean_residual);
        }
    }

    // Late in stream: consolidate aggressively, avoid opening bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress > 0.8 && bin_residual < bin_capacity {
        score -= 6.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let residual = bin_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 1 {
        step_index as f64 / (total_items as f64).max(1.0)
    } else {
        0.0
    };
    let progress = progress.clamp(0.0, 1.0);

    // Base: prefer minimal post residual, scaled non-linearly
    let mut score = post * post / cap; // quadratic waste penalty

    // Tight fit reward: post_residual small relative to item size
    let tightness = 1.0 - (post / cap);
    score -= 30.0 * tightness * tightness * tightness;

    // Smooth non-linear coupling: waste matters more as stream progresses
    let progress_coupling = 1.0 + 2.0 * progress * (1.0 - progress) * 4.0;
    score *= progress_coupling;

    // Interaction: post_residual vs mean residual — avoid outliers vs fleet average
    let mean = mean_residual.max(0.0);
    score += 0.15 * (post - mean).abs();

    // Penalize bins whose residual becomes a "dead" sliver relative to typical item sizes
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let usable = if post >= nxt { 1.0 } else { post / nxt.max(1.0) };
        score += (1.0 - usable) * 8.0 * (0.5 + 0.5 * progress);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it unattractive unless nothing better exists
    if bin_residual == bin_capacity {
        // Opening cost grows with number of open bins and stream progress
        score = cap * cap / cap.max(1.0) + 40.0 + 5.0 * open_bins_count as f64 + 20.0 * progress;
        // But if post_residual of new bin is huge relative to item, slightly soften
        score -= 0.5 * item;
    }

    // Mild preference for fuller bins overall
    score -= 0.1 * (residual - post);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Harmonic class of the post residual: residues divisible by 10 are
    // "friendly" (likely to host future items in a 1..100 integer stream),
    // odd / prime-ish residues are dead space.
    let r = post_residual;
    if r == 0 {
        score -= 40.0; // perfect closure: best possible outcome
    } else if r % 10 == 0 {
        score -= 12.0;
    } else if r % 5 == 0 {
        score -= 4.0;
    } else {
        score += 6.0; // non-harmonic residue: penalize
    }

    // Integer-division threshold classes on post_residual.
    if r <= 10 {
        score += 10.0; // unusable sliver for most items
    } else if r <= 25 {
        score += 4.0;
    } else if r <= 50 {
        score -= 2.0;
    }

    // Coupling with the lookahead item: does the leftover invite next_item_size?
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size <= r {
            // leftover can host the next item: reward tight co-fit
            let gap = (r - next_item_size) as f64;
            score -= 15.0 * (1.0 - gap / cap);
            if gap % 10.0 == 0.0 {
                score -= 5.0; // chained harmonic fit
            }
        } else {
            // leftover cannot host next item: penalize proportionally
            score += 8.0 * (1.0 - post / cap);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only open a new bin when current residuals
    // are fragmented and mean residual is low (poor reuse potential).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual - post).abs() / cap;
        // prefer new bin late in stream or when open bins are nearly full
        score = 30.0 + 40.0 * (1.0 - mean_residual / cap) - 20.0 * progress
            - 10.0 * fragmentation;
        if item_size as f64 > 0.7 * cap {
            score -= 15.0; // big items deserve fresh bins
        }
    }

    // Mild tie-break: prefer filling bins with larger residual among equals.
    score -= 0.01 * (bin_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftovers are almost unusable
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    } else if post_residual == 0 {
        score -= 25.0; // perfect fit
    }

    // Lookahead: leftover that can host the next item is valuable
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if next_item_size >= post_residual && post_residual > 0 {
            score += 6.0; // leftover too small for lookahead item
        }
    }

    // Last chance: only bin that fits -> strong penalty for opening new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage proliferation of bins
    if bin_residual == bin_capacity {
        // new-bin candidate: accept only if open bins are tight or fit is terrible
        score += 15.0 + 3.0 * open_bins_count as f64;
        if mean_residual < item_size as f64 {
            score -= 20.0;
        }
    } else {
        score -= 2.0 * (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    }

    // Progression: later in stream, prefer packing into existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) super-linearly.
    score -= (bin_capacity as f64 - post_residual as f64) * 0.5;

    // Aggressive 2-step lookahead: strongly reward bins whose post_residual
    // exactly (or nearly) matches the next item's size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= (bin_capacity as f64 - gap) * 0.6;
        // Perfect match for the next item is a big bonus.
        if post_residual == next_item_size {
            score -= 30.0;
        }
        // Penalize leaving a dead space that no typical item (>=1) can use well:
        // residual smaller than half the next item but nonzero is risky.
        if post_residual > 0 && (post_residual as f64) < next_item_size as f64 * 0.5 {
            score += 15.0;
        }
    } else {
        // Last item: just pack as tightly as possible.
        score -= 20.0;
    }

    // Prefer bins already below mean residual (consolidating small leftovers),
    // penalize dipping into bins with large residuals that could host bigger items.
    score += (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is huge
    // relative to typical residuals, or many bins are already open and mean
    // residual is small (fragmentation would be wasteful otherwise).
    if bin_residual == bin_capacity {
        score += 40.0;
        let progress = step_index as f64 / total_items.max(1) as f64;
        if item_size as f64 > mean_residual + 10.0 {
            score -= 55.0; // item barely fits anywhere: new bin is good
        }
        if open_bins_count > 3 && mean_residual < 15.0 {
            score -= 10.0 * progress;
        }
    }

    // Slight preference for fuller bins early in the stream.
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 45.0 * tightness * tightness;

    // Penalize dead space: residuals too small for the smallest plausible item (<=10).
    if post_residual < 10 {
        score += 30.0;
    } else if post_residual <= 20 {
        score += 8.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0;
    }
    // Penalize placements that leave a residual just barely below the next item (awkward gap).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    // Prefer fuller bins when many bins are open (consolidation pressure).
    let fill_frac = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score -= 10.0 * fill_frac * pressure.min(4.0);

    // Early in the stream: be more willing to spread (favor new bins slightly);
    // late in the stream: consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus adjustments.
        score += 12.0;
        score -= 20.0 * (1.0 - progress);
        // Opening a new bin is attractive if existing residuals are large (fragmented state)
        // but unattractive if mean residual already comfortably fits the item.
        if mean_residual > item_size as f64 * 1.5 {
            score += 15.0;
        }
        // Avoid opening new bins for the last-chance scenario.
        if fitting_bins_count <= 1 && open_bins_count > 0 {
            score += 40.0;
        }
    } else {
        score += 10.0 * progress;
    }

    // Mild preference for bins below mean residual (balance residual distribution).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // Non-linear coupling: prefer residual states that remain versatile
    // (post_residual near multiples of common small sizes).
    let pr = post_residual as f64;
    let versatility = ((pr % 10.0) / 10.0 - 0.5).abs();
    score += 5.0 * versatility;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with polynomial sharpening
    let mut score = pr * (1.0 + 1.5 * norm_pr * norm_pr);

    // Smooth stream-progress coupling: tighten packing as stream advances
    score *= 1.0 + 0.8 * progress * norm_pr;

    // Reward tight fits relative to mean residual of open bins
    score -= (mean_residual - pr).max(0.0) * 0.3;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0 + 10.0 * progress;
    }

    // Lookahead: if next item fits exactly in post_residual, reward heavily
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let slack = (pr - nxt) as f64;
            score -= 12.0 * (1.0 - slack / cap);
        } else {
            score += 5.0 * ((nxt - pr) / cap);
        }
    }

    // New-bin candidate: penalize opening a new bin mildly, more when open bins exist and fit is decent
    if bin_residual == bin_capacity {
        score += 15.0 + 5.0 * (open_bins_count as f64).ln().max(0.0);
        // but if post_residual of alternatives would be huge, new bin stays attractive
        score -= 0.2 * mean_residual;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residue mod 10
    let class = post_residual % 10;
    // Dead-space penalty: residuals 1..9 are nearly unusable for items >=10
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else {
        // reward residuals that fall into "harmonic" classes matching common sizes
        match class {
            0 => score -= 6.0,           // multiple of 10: very reusable
            5 => score -= 3.0,           // half class
            2 | 4 | 6 | 8 => score -= 1.5,
            _ => {}
        }
    }

    // Integer-division band of post_residual (decades)
    let band = post_residual / 10;
    let band_f = band as f64;
    score += band_f * band_f * 0.15; // superlinear penalty for large leftover

    // Perfect fit reward
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: if next item fits exactly into post_residual, strong reward
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 45.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // next item fits but leaves residue: mild reward scaled by fit quality
        let frac = next_item_size as f64 / post_residual as f64;
        score -= 10.0 * frac;
    } else if next_item_size > 0 && next_item_size <= post_residual + 10 {
        // near-miss: penalize slightly
        score += 3.0;
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Prefer tighter bins relative to mean residual
    score += (mean_residual - bin_residual as f64) * 0.25;

    // Late in stream: consolidation matters more, avoid opening new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize more as stream progresses
        score += 8.0 + 25.0 * progress;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 2.0;
        }
    } else {
        score -= 4.0 * progress;
    }

    // Many open bins: favor filling existing ones
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A gap is "dead" if no plausible future item (min size 1, but typical >=10)
    // can use it well. Penalize gaps in the awkward small range superlinearly.
    if post_residual > 0 {
        let pr = post_residual as f64;
        if post_residual < 10 {
            // unusable under original regime -> strong penalty
            score += 60.0 + (10.0 - pr) * 8.0;
        } else if post_residual <= 30 {
            // awkward mid-small gap: mildly superlinear penalty
            score += (30.0 - pr) * 1.5;
        } else {
            // large residual is fine, even reward slightly
            score -= (pr - 30.0) * 0.3;
        }
    } else {
        // perfect fit: big reward
        score -= 40.0;
    }

    // Open-bin pressure: discourage spawning many bins; new empty bin should
    // only win when fits are bad. Penalize the new-bin candidate.
    if bin_residual == bin_capacity {
        score += 25.0 + open_bins_count as f64 * 0.5;
        // but if no other bin fits well (this is effectively the only fitting bin),
        // soften so a new bin can win over a terrible fit
        if fitting_bins_count <= 1 {
            score -= 30.0;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 {
        score += 5.0;
    }

    // Mild global pressure: when many bins are open, tighten packing
    // (prefer bins with small residuals relative to mean).
    score += (bin_residual as f64 - mean_residual) * 0.2 + open_bins_count as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (for mild phase-dependent tuning).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // ---- 2-step lookahead: reward when next item fits exactly into post_residual ----
    if next_item_size > 0 {
        if next_item_size == post_residual {
            // Perfect chained fit: strongly favor this bin.
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Next item fits, penalize by leftover slack after the chain placement.
            let chain_slack = post_residual - next_item_size;
            score -= 40.0 - (chain_slack as f64).min(40.0);
        } else {
            // Next item does not fit: penalize dead space that can't be used by lookahead.
            let dead = (next_item_size - post_residual) as f64;
            score += dead.min(30.0) * 0.5;
        }
    }

    // ---- Tightness reward: small post_residual means good fill ----
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 15.0;

    // ---- Penalize bins far below mean residual (wasteful use of a fuller bin) ----
    if (bin_residual as f64) > mean_residual {
        score += (bin_residual as f64 - mean_residual) * 0.15;
    } else {
        score -= (mean_residual - bin_residual as f64) * 0.10;
    }

    // ---- Last-chance bin: if this is the only fitting bin, avoid opening a new bin ----
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when existing bins are very tight
        // and the item is large; otherwise discourage spreading across bins.
        let avg_fill = 1.0 - (mean_residual / bin_capacity as f64);
        if avg_fill > 0.85 && item_size > bin_capacity / 2 {
            score -= 20.0;
        } else {
            score += 30.0 + 20.0 * (1.0 - progress);
        }
    }

    // Mild early-stream conservatism: prefer compacting early.
    score += progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // Penalize large dead space relative to capacity.
    let dead_frac = post_residual as f64 / bin_capacity as f64;
    score += dead_frac * dead_frac * 120.0;

    // Lookahead: if the next item fits exactly into the post-residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 600.0;
        } else if next_item_size <= post_residual {
            let slack_after_next = post_residual - next_item_size;
            score -= 60.0 - slack_after_next as f64 * 1.5;
        } else {
            // Next item cannot follow here; slight penalty for wasting a good bin.
            score += 20.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // Prefer bins tighter than the mean residual (good fits among open bins).
    score += (mean_residual - bin_residual as f64) * 0.8;

    // Time horizon: late in the stream, be more conservative (avoid tiny slivers);
    // early on, allow more exploration.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += t * dead_frac * 150.0;

    // Many open bins: encourage consolidation into existing bins rather than new ones.
    score += (open_bins_count as f64).ln().max(0.0) * 3.0;

    // New-bin candidate: only attractive when current item is large and fits poorly elsewhere.
    if bin_residual == bin_capacity {
        let big_item_bonus = (item_size as f64 / bin_capacity as f64).powi(2) * 90.0;
        score = 110.0 + dead_frac * 40.0 - big_item_bonus;
        if fitting_bins_count == 0 {
            score -= 500.0;
        }
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    let mut score = post;

    // Non-linear dead-space penalty: gaps that are too small to be useful later
    // (smoothly penalize residuals below ~20% of capacity using a smooth bump)
    let gap_frac = post / cap;
    let dead = (-((gap_frac - 0.10) * (gap_frac - 0.10)) / 0.008).exp();
    score += 25.0 * dead;

    // Reward near-perfect packing: smooth bonus as post_residual -> 0
    let perfect = (-post * post / (0.05 * cap * 0.05 * cap)).exp();
    score -= 15.0 * perfect;

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 {
        score -= 20.0 + 10.0 * progress;
    }

    // Lookahead coupling: if the next item fits in the post residual,
    // reward preserving this bin; otherwise penalize blocking it.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= 8.0 * (1.0 - nxt / cap);
        } else {
            score += 4.0 * (nxt - post) / cap;
        }
    }

    // Coupling with mean residual: avoid dumping into bins that deviate
    // strongly from the mean (keeps residual profile balanced, smooth term)
    let dev = (post - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // Stream progress: later in the stream, tighten up more aggressively
    // (smooth non-linear ramp, no piecewise constants)
    score *= 1.0 - 0.15 * progress * progress;

    // New-bin candidate handling: a fresh empty bin has post = cap - item.
    // Favor it only when it would leave a large usable residual while open
    // bins are poor fits; discourage needless bin proliferation early.
    if bin_residual == bin_capacity {
        let fresh_load = item_size as f64;
        score += 12.0 * (1.0 - progress) - 6.0 * (fresh_load / cap);
        if fitting_bins_count > 1 {
            score += 18.0; // don't open new bins when alternatives exist
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.81;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward bins whose residual can still host the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 18.0;
        }
    }

    // Last-chance pressure: strongly prefer the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.4 + 0.6 * progress);
    if bin_residual != bin_capacity {
        score -= 6.0 + 0.15 * pressure;
    } else {
        // New-bin candidate: only attractive when open bins are crowded.
        score += 10.0 + pressure;
    }

    // Prefer bins tighter than the mean residual (well-packed bins).
    if bin_residual != bin_capacity {
        score += 0.3 * (bin_residual as f64 - mean_residual);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item fits the post residual
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            // next item exactly fills this bin after current placement: excellent
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // next item still fits, but penalize leftover waste after both
            let two_step_waste = post_residual - next_item_size;
            score -= 100.0 - (two_step_waste as f64).min(100.0);
        } else {
            // next item won't fit: penalize creating dead space relative to next item
            let gap = next_item_size - post_residual;
            score += (gap as f64) * 1.5;
        }
    }

    // Penalize small unusable residuals (< smallest plausible item)
    if post_residual > 0 && post_residual < 10 {
        score += 200.0;
    }

    // Compare against mean residual: prefer bins tighter than average
    score -= (mean_residual - bin_residual as f64) * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // New-bin candidate: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        score += 50.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 30.0;
        }
    }

    // Late in stream: consolidation matters more
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tight fit reward: quadratic in fill ratio
    let fill = item_size as f64 / bin_residual as f64;
    score -= 40.0 * fill * fill;

    // Penalize dead space that no plausible item can use
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    }

    // Lookahead coupling: bonus if next item fits the post-residual exactly-ish
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 / (1.0 + slack);
    } else if next_item_size > post_residual && post_residual > 0 {
        // post-residual likely wasted for the next item
        score += 8.0 * (next_item_size as f64 - post_residual as f64) / 100.0;
    }

    // Last chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Prefer bins with smaller residual among many open bins
    score += 0.3 * ((bin_residual as f64) - mean_residual);

    // Time horizon: early on, be more willing to open new bins (explore);
    // late in the stream, consolidate aggressively.
    let t = step_index as f64 / (total_items.max(1) as f64);
    let new_bin = bin_residual == bin_capacity;
    if new_bin {
        // new bin baseline: its score equals item_size (post_residual)
        // penalize opening new bins when good alternatives exist
        if fitting_bins_count > 0 {
            score += 20.0 + 40.0 * t;
        }
    } else {
        // existing bin: bonus that shrinks as stream progresses? no—favor consolidation
        score -= 5.0 * t;
    }

    // Few open bins: discourage spreading
    if open_bins_count > 8 && !new_bin {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, tolerate residual; later, penalize dead space quadratically.
    let progress_coupling = pr_norm * pr_norm * (0.5 + 2.5 * progress);
    score += 40.0 * progress_coupling;

    // Reward tight fits (small post_residual) with a saturating non-linear bonus.
    let tightness = 1.0 - pr_norm;
    score -= 15.0 * tightness * tightness * (1.0 + progress);

    // Penalize bins whose residual deviates strongly from the mean residual
    // (keeps the population of open bins homogeneous).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 10.0 * dev * dev;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward;
    // if post-residual is too small for the (unknown) next item, mild penalty.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 8.0 * (1.0 - (pr - nxt) / cap);
        } else {
            score += 6.0 * (pr / nxt);
        }
    }

    // Mild penalty for proliferating open bins late in the stream.
    score += 0.5 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals divisible by common
    // item sizes (10/20/25/50) are more reusable -> reward them.
    let r = post_residual;
    if r > 0 {
        if r % 10 == 0 { score -= 6.0; }
        if r % 20 == 0 { score -= 4.0; }
        if r % 25 == 0 { score -= 3.0; }
        if r % 50 == 0 { score -= 5.0; }
    } else {
        // Perfect fit is ideal.
        score -= 40.0;
    }

    // Dead-space penalty: very small leftovers are hard to fill.
    if r > 0 && r < 10 {
        score += 25.0;
    } else if r >= 10 && r < 20 {
        score += 8.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == r {
            score -= 30.0;
        } else if r >= next_item_size {
            score -= 2.0;
            let leftover2 = r - next_item_size;
            if leftover2 % 10 == 0 { score -= 3.0; }
            if leftover2 == 0 { score -= 10.0; }
        } else {
            // next item won't fit here; penalize slightly.
            score += 4.0;
        }
    }

    // Last-chance logic: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: only attractive for large items or when
    // no open bin fits well (tight fit threshold).
    let is_new_bin = bin_residual == bin_capacity && bin_capacity > 0;
    if is_new_bin {
        let tight = item_size as f64 / bin_capacity as f64;
        if tight >= 0.9 {
            score -= 15.0; // big item deserves a fresh bin
        } else if tight < 0.5 && fitting_bins_count > 0 {
            score += 20.0; // prefer existing bins for small items
        } else {
            score += 5.0;
        }
    }

    // Prefer fuller bins overall (waste minimization): compare residual to mean.
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    // Early stream: be slightly conservative, keep bins balanced.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.2 {
        score += (bin_residual as f64 - mean_residual).abs() * 0.2;
    }

    // Mild preference for fewer open bins.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10 - post_residual) as f64;
    }
    // Perfect fit is highly rewarded.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward tight fits relative to residual (waste fraction).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fit_ratio;

    // Open-bin pressure: discourage spreading across many bins mildly.
    score += 0.35 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
        // Extra reward if next item fills the bin completely afterwards.
        if post_residual == next_item_size {
            score -= 25.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Penalize leaving a gap the next item cannot use.
        score += 15.0;
    }

    // Mean residual coupling: prefer bins deviating below mean (consolidate small residuals).
    score += 0.5 * ((post_residual as f64) - mean_residual);

    // New-bin candidate handling: empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when no good fit exists.
        // Penalize it unless the item would leave a large useful gap elsewhere.
        score += 30.0;
        if fitting_bins_count == 0 {
            score -= 200.0; // must open a new bin
        }
        // If item is large relative to capacity, a fresh bin is reasonable.
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 20.0;
        }
    }

    // Slight progression adaptation: later in stream, be more conservative with new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit, but weight dead space more when bins are plentiful.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.5 * (0.5 + progress);

    // Aggressive 2-step lookahead: reward if next item exactly fills post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect 2-item completion
        } else if post_residual >= next_item_size {
            let slack_after_next = post_residual - next_item_size;
            score -= 25.0 * (1.0 - slack_after_next as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here: penalize proportionally to the gap
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.6;
        }
    } else {
        // Last item: strongly prefer minimal leftover.
        score += post_residual as f64 * 0.3;
    }

    // Relative-to-mean coupling: bins with residual far above mean are better targets.
    score -= (bin_residual as f64 - mean_residual) * 0.15;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
        if post_residual <= 10 {
            score -= 15.0; // near-perfect fill, definitely use it
        }
    }

    // New-bin candidate: only attractive when open bins fit poorly.
    if bin_residual == bin_capacity {
        // New bin cost grows with how many bins are already open (bin-count minimization).
        score += 30.0 + open_bins_count as f64 * 0.5;
        // If item nearly fills a fresh bin, opening is fine.
        if item_size >= 90 {
            score -= 45.0;
        }
        // If no existing bin can take the item at all, new bin is mandatory.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // With lookahead: fresh bin makes sense if item + next item pair well.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual already favored by base).

    // Penalize dead space: post_residual that is too small to hold a typical item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual < item_size as f64 * 0.25 {
        score += 8.0;
    }

    // Reward leaving space for the lookahead item.
    if next_item_size > 0 && post_residual as f64 >= next_item_size as f64 {
        score -= 6.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // penalize wasted residual that can't fit the next item
        score += (next_item_size as f64 - post_residual as f64).min(15.0) * 0.5;
    }

    // Last-chance bin: strongly favor filling the final fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin fit is poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Base penalty for opening a new bin
        score += 30.0;
        // If the current fit is very tight elsewhere this penalty may be outweighed;
        // reduce penalty late in stream when item sizes trend unpredictable.
        score -= progress * 5.0;
        // If mean residual across open bins is large, opening a new bin is wasteful.
        score += mean_residual * 0.3;
    }

    // Slight preference for bins below mean residual (more filled bins first).
    score += (mean_residual - bin_residual as f64) * 0.15;

    // Prefer larger bins among fitting ones when many bins can fit (best-fit behavior
    // is already encoded via post_residual; add mild tiebreak on bin_residual).
    score += bin_residual as f64 * 0.01;

    // Encourage consolidation when many bins are open.
    if open_bins_count > 8 {
        score += (open_bins_count as f64).ln() * 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits, with non-linear (quadratic/cubic) shaping of dead space.
    let mut score = norm_pr * (1.0 + 0.8 * norm_pr + 0.6 * norm_pr * norm_pr);

    // Smooth interaction: tight fits matter more as the stream progresses.
    score *= 1.0 + 0.5 * progress;

    // Reward filling bins deeply (relative fill before placement).
    let fill = (bin_residual as f64 - pr) / cap;
    score -= 0.6 * fill * fill;

    // Penalize bins that deviate from the mean residual (smooth coupling).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 0.4 * dev * dev;

    // Lookahead coupling: reward leaving space compatible with the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs() / cap;
        score += 0.5 * gap * gap;
        score -= 0.3 * (pr / nxt.max(1.0)).ln().abs();
    }

    // Last-chance bonus: avoid opening a new bin when this is the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 1.2 * (1.0 - norm_pr);
    }

    // New-bin candidate: penalize mildly so it is chosen only when fits are poor,
    // with a smooth decay as the stream progresses (consolidate late).
    if bin_residual == bin_capacity {
        score += 0.8 + 0.4 * (1.0 - progress) - 0.3 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: capacity divided into 10 classes.
    let class = post_residual / 10;
    // Reward tight fits: lower class (small residual) is better, nonlinearly.
    score += (class as f64).powi(2) * 0.8;

    // Penalize dead space that no plausible item (>=1) can use well:
    // residual in awkward zones (e.g. 1..10 tiny slivers, or 51..60 mid-band)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }
    if post_residual > 50 && post_residual < 61 {
        score += 8.0; // mid-band awkwardness
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 60.0;
    }

    // Harmonic lookahead: can next item exactly fill the post residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0; // chain completion
        } else if next_item_size <= post_residual {
            // next item fits: reward proportional to how well it uses residual
            let fill_ratio = next_item_size as f64 / post_residual as f64;
            score -= 15.0 * fill_ratio;
            // bonus if combined fill leaves another harmonic class boundary
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 10.0;
            }
        } else {
            // next item cannot use this residual: penalize if residual was large
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    // or the fit here is poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, discounted when many bins are open
        // and mean residual is low (fragmented state).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_bin_score = 55.0 - 20.0 * progress;
        if mean_residual < 15.0 {
            new_bin_score -= 12.0; // open bins nearly full anyway
        }
        if open_bins_count == 0 {
            new_bin_score = -100.0; // must open
        }
        // If this item leaves a harmonic-friendly residual in a fresh bin
        // (i.e. item size near capacity fraction), slight discount.
        let fresh_post = bin_capacity - item_size;
        if fresh_post % 10 == 0 {
            new_bin_score -= 5.0;
        }
        score = score.min(new_bin_score.max(score));
        // Replace score entirely with new-bin evaluation baseline:
        score = new_bin_score + (post_residual as f64) * 0.5;
    }

    // Mild penalty for spreading across many open bins when residual is large:
    if post_residual as f64 > mean_residual + 30.0 {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 && post_residual >= 10 {
        score += 12.0;
    }

    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward near-perfect fits (gap smaller than typical minimum item size).
    if post_residual > 0 && post_residual <= 3 {
        score -= 15.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Pressure from number of open bins: discourage spreading across many bins
    // unless the fit is good; encourage consolidating when many bins are open.
    let open_pressure = open_bins_count as f64 * 0.6;
    score += open_pressure * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: prefer opening a new bin only when no open bin offers
    // a good fit. New bin starts with large residual; make it moderately
    // attractive so it beats bins that would leave dead space, but not so
    // attractive it beats decent fits.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.55 - 10.0;
        // If the item is large relative to capacity, a fresh bin is fine.
        if item_size as f64 / bin_capacity as f64 > 0.6 {
            score -= 15.0;
        }
        // Late in the stream, slightly prefer reusing existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 8.0;
    }

    // Lookahead: if the next item would fit snugly in the post-residual,
    // reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        score -= 25.0;
    }
    // Penalize if next item cannot fit here anyway (wasting good residual).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 15 {
        score += 10.0;
    }

    // Deviation from mean residual: bins far below mean residual are already
    // tight; slightly prefer them (they will be closed out soon).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual (tight fit), scaled
    score = post_residual as f64 * 1.0;

    // Aggressive 2-step lookahead: reward post_residual matching next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 / (1.0 + diff);
        // Exact match bonus: next item fills this bin perfectly
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // Penalize leaving dead space that next item cannot use
        if post_residual > 0 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
    } else {
        // Last item: just minimize residual
        score -= 10.0;
    }

    // Relative to mean residual: prefer bins with residual close to mean (balanced),
    // but strongly prefer below-mean residual (concentrate filling)
    let res = post_residual as f64;
    if mean_residual > 0.0 {
        let rel = (res - mean_residual) / mean_residual;
        score += 5.0 * rel;
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin should only win when no good fit exists
    if bin_residual == bin_capacity {
        // Penalize opening a new bin, scaled by how many bins could fit
        let base_penalty = 55.0;
        let fit_factor = if fitting_bins_count > 0 { fitting_bins_count as f64 } else { 1.0 };
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += base_penalty * (1.0 + 0.5 * fit_factor) * (1.0 - 0.3 * progress);
        // If next item is large, a fresh bin is more attractive
        if next_item_size >= 50 {
            score -= 15.0;
        }
    }

    // Mild penalty for high fragmentation (small post_residual that's still unusable)
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared penalty on leftover space (dead space is quadratic waste).
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 20.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        // Small residuals (<10) are nearly unusable given item sizes >= 10 originally;
        // treat tiny leftovers as near-perfect fits.
        score -= 30.0;
    }

    // Lookahead: strongly favor bins whose post-residual can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            // Blocking the next item: penalize proportionally to how far off we are.
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
        // Chain fit: residual also fits next item tightly (next item nearly fills the bin).
        if next_item_size > 0 && post_residual >= next_item_size && (post_residual - next_item_size) < 10 {
            score -= 8.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin should only win when open bins offer poor fits.
    if bin_residual == bin_capacity {
        // Mild default penalty so existing bins are preferred on decent fits.
        score += 15.0;
        // But early in the stream, or when many bins are open with slack, a fresh bin
        // keeps the residual landscape uniform.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        if open_bins_count == 0 {
            score -= 100.0; // must open a bin
        } else if progress < 0.3 {
            score -= 5.0;
        }
        // If mean residual across open bins is large (lots of slack spread around),
        // opening yet another bin wastes capacity — penalize more.
        score += mean_residual * 0.3;
        // If the item is large relative to capacity, prefer filling existing bins.
        if item_size > bin_capacity / 2 {
            score += 10.0;
        }
    }

    // Prefer bins whose current residual is close to the item (classic best-fit sharpening).
    score += (bin_residual - item_size) as f64 * 0.1;

    // Slight preference for more-filled bins as stream progresses (consolidation).
    let fill_ratio = 1.0 - bin_residual as f64 / bin_capacity as f64;
    score -= fill_ratio * (1.0 + step_index as f64 / (total_items.max(1) as f64)) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on: tolerate large residuals (bins stay flexible). Later: punish waste.
    let progress_weight = 0.5 + 1.5 * progress * progress;
    score += progress_weight * (pr / cap) * (pr / cap) * cap * 0.1;

    // Smooth quadratic penalty when post_residual is just below common item sizes
    // (dead space that nothing can fill). Use smooth troughs around 1..=cap.
    let dead = (pr / cap).powi(2) * (1.0 - (pr / cap)).powi(2);
    score += 8.0 * dead * (1.0 + progress);

    // Reward tight fits (small post_residual) more strongly as stream progresses.
    score -= (1.0 - pr / cap).powi(3) * 6.0 * (0.5 + progress);

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0 * (1.0 + progress);
    }

    // Lookahead: if next item fits exactly in post_residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64 - pr).abs() < 1e-9 {
        score -= 10.0;
    } else if next_item_size > 0 && (next_item_size as u32) > post_residual {
        // Next item won't fit here anyway; slight reward for keeping residual useful.
        score -= 2.0 * (pr / cap);
    }

    // Mild penalty for spreading across many open bins relative to mean residual.
    score += 0.05 * (open_bins_count as f64) * ((pr - mean_residual).abs() / cap);

    // New-bin candidate: baseline score so it only wins when open bins are poor fits.
    if bin_residual == bin_capacity {
        score += 15.0 - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: exact fill is perfect, small post_residual is good.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 60.0;
    } else if post_residual <= 20 {
        score -= 25.0;
    }

    // Harmonic class of dead space: residuals that are "useless" for typical
    // small items (i.e. not expressible as sums of small sizes) are penalized.
    // Class post_residual mod 10: residual divisible by 10 is reusable.
    let cls = post_residual % 10;
    let cls_pen = match cls {
        0 => -15.0,
        1 | 9 => 10.0,
        2 | 8 => 6.0,
        3 | 7 => 3.0,
        _ => 0.0,
    };
    score += cls_pen;

    // Dead-space quadratic penalty for large unusable leftover.
    if post_residual > 20 {
        score += 0.35 * (post_residual as f64 - 20.0);
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: opening a new bin wastes capacity = bin_residual of
    // an existing bin. Penalize the new-bin option unless current bin fit is bad.
    if bin_residual == bin_capacity {
        // A fresh bin is attractive when item is large relative to capacity
        // (would leave awkward residual elsewhere) or no open bin fits well.
        score = 100.0
            - (item_size as f64 / bin_capacity as f64) * 40.0
            + if post_residual > 20 { 0.0 } else { 45.0 };
        if fitting_bins_count == 0 {
            score -= 200.0; // nothing fits: new bin is the only option
        }
    }

    // Lookahead: if next item fits exactly into the post-residual, big reward
    // (harmonic pairing of consecutive items).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0;
        } else if next_item_size <= post_residual {
            score -= 20.0 + 0.2 * next_item_size as f64;
        } else {
            // next item cannot use this bin's leftover; leftover is dead weight
            score += 8.0;
        }
    }

    // Prefer filling bins with many open bins (limit bin proliferation).
    score += 0.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins whose residual is far below the mean (fill the emptiest first)
    score += (post_residual as f64 - mean_residual) * 0.15;

    // Slight urgency late in the stream: consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=15) are heavily penalized.
    if post_residual > 0 && post_residual <= 15 {
        score += 40.0 * (16.0 - post_residual as f64);
    }
    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward placements that leave room for the lookahead item when possible.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: when many bins are open, avoid spreading; prefer tight fits.
    let pressure = open_bins_count as f64 / 10.0;
    score += pressure * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when no open bin fits well or
    // the item is large relative to typical residuals.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit = mean_residual < item_size as f64 * 0.6;
        if poor_fit || post_residual < 20 {
            score -= 12.0 + 10.0 * progress;
        } else {
            score += 15.0;
        }
    }

    // Mild preference for bins whose residual is close to the item (best fit flavor).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += 0.15 * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: strongly favor bins where the item nearly fills the residual.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    }

    // 2-step lookahead: reward if the next item can fit into the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0; // chain fit: next item exactly fills remaining space
        } else if next_item_size < post_residual {
            score -= 50.0 + 0.5 * (post_residual - next_item_size) as f64;
        } else {
            // next item cannot fit here; penalize wasted post residual relative to mean
            score += 0.3 * (post_residual as f64 - mean_residual).abs();
        }
    } else {
        // last item: just minimize post residual
        score += 0.0;
    }

    // Last-chance bonus: if this is the only bin that fits, prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Penalize opening a new bin when open bins could accommodate decently
    if bin_residual == bin_capacity {
        // new-bin candidate: base cost plus penalty scaled by stream progress
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 120.0 + 80.0 * progress;
        // but if next item is large and no open bin chains well, slight relief
        if next_item_size > 0 && next_item_size > post_residual {
            score -= 60.0;
        }
    }

    // Mild preference for tighter bins overall (best-fit bias)
    score += 0.1 * (bin_residual as f64 - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post-residual) more aggressively than linear.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio) * (1.0 - fit_ratio) * 30.0;

    // Penalize dead space: residuals too small to be useful later.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if next item fits exactly in the post-residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 15.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; slight penalty proportional to waste
            score += 5.0 * (1.0 - post_residual as f64 / next_item_size as f64).max(0.0);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: prefer new bin when open bins fit poorly.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by global state.
        let mut new_bin_score = 55.0;
        // If mean residual across open bins is small (fragmented), new bin is attractive.
        new_bin_score -= (mean_residual / bin_capacity as f64) * 40.0;
        // Early in stream, cheaper to open bins; late, prefer packing tight.
        let progress = step_index as f64 / total_items.max(1) as f64;
        new_bin_score += progress * 30.0;
        // Many open bins: discourage opening more.
        new_bin_score += (open_bins_count as f64).ln().max(0.0) * 8.0;
        score = new_bin_score + post_residual as f64 * 0.1;
    }

    // Mild reward for using fuller bins relative to average residual.
    if bin_residual < bin_capacity {
        if (bin_residual as f64) < mean_residual {
            score -= 8.0;
        } else {
            score += 4.0;
        }
    }

    // Time-horizon coupling: early items can afford slight waste for future flexibility.
    let horizon = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 - 0.15 * (1.0 - horizon);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let post_norm = post / cap;

    // Base: post residual, smoothed by stream progress
    let mut score = post * (1.0 + 0.5 * progress);

    // Non-linear polynomial coupling of post_residual with progress
    let coupling = post_norm * post_norm * (1.0 - post_norm) * (2.0 * progress - 1.0);
    score += 40.0 * coupling;

    // Reward tight fits (small post_residual) more strongly later in the stream
    score -= (1.0 - post_norm) * (1.0 - post_norm) * 20.0 * (0.5 + progress);

    // Penalize dead space that cannot fit the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post < nxt {
            score += 15.0 * (nxt - post) / cap;
        } else {
            score -= 10.0 * (1.0 - post / nxt.max(1.0)).abs() * progress;
        }
    }

    // Last-chance bin: strong reward to use it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - post_norm);
    }

    // Prefer bins with below-mean residual (keeps larger residuals distributed)
    let diff = (bin_residual as f64 - mean_residual) / cap;
    score += 12.0 * diff * diff * (2.0 * progress - 1.0);
    score += 5.0 * diff;

    // Mild penalty for many open bins, encouraging consolidation
    score += 0.3 * open_bins_count as f64 * post_norm;

    // New-bin candidate: neutral-ish baseline with progress-dependent caution
    if bin_residual == bin_capacity {
        score = 60.0 + 40.0 * progress - 20.0 * (1.0 - post_norm);
        if next_item_size > 0 && next_item_size as f64 > 0.5 * cap {
            score -= 10.0;
        }
        if fitting_bins_count == 1 {
            score += 50.0; // never open a new bin when a last-chance bin exists
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals that are "clean" fractions
    // of capacity (multiples of 10/25) are more reusable, reward them.
    let pr = post_residual;
    if pr > 0 {
        if pr % 10 == 0 {
            score -= 6.0;
        }
        if pr % 25 == 0 {
            score -= 4.0;
        }
        if pr % 50 == 0 {
            score -= 3.0;
        }
        // Dead-space penalty: tiny unusable slivers (below smallest item size 1..10 band)
        if pr < 10 {
            score += 12.0;
        } else if pr < 20 {
            score += 5.0;
        }
    } else {
        // Perfect fill is ideal
        score -= 20.0;
    }

    // Harmonic class of the item: large items (close to half or more of capacity)
    // should prefer tight fits; small items are flexible.
    let frac = item_size as f64 / bin_capacity as f64;
    if frac > 0.5 {
        score -= 4.0; // prefer placing big items into existing bins
    }

    // Coupling with lookahead: if next item fits exactly in post_residual,
    // strongly reward this placement.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 15.0;
        } else if next_item_size <= pr {
            score -= 5.0;
        } else {
            // next item won't fit here; mild penalty proportional to overflow
            score += ((next_item_size - pr) as f64) * 0.15;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 8.0;
    }

    // New-bin candidate handling: empty bin has large residual.
    if bin_residual == bin_capacity {
        // Prefer new bin only when existing fits are terrible (post_residual tiny)
        // or no bins fit. Base new-bin score high unless justified.
        score += 10.0;
        if mean_residual < 15.0 && open_bins_count > 0 {
            score -= 12.0; // all bins nearly full -> open fresh bin
        }
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size.min(bin_capacity) {
            score -= 3.0;
        }
    }

    // Stream progression: late in the stream, consolidate harder (avoid new bins).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 3.0;

    // Spread-aware: if this bin's residual is far below mean, it's already tight;
    // filling tight bins fully is good.
    let res_gap = mean_residual - bin_residual as f64;
    if res_gap > 0.0 {
        score -= res_gap * 0.2;
    } else {
        score += (-res_gap) * 0.1;
    }

    // Harmonic modulo threshold on post_residual vs next item: divisible classes
    if next_item_size > 0 && pr > 0 && pr % next_item_size == 0 && pr > next_item_size {
        score -= 4.0; // leaves room for another exact copy of next item
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small unusable gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 80.0;
    } else {
        // Reward tight fits relative to residual.
        score -= 25.0 * (item_size as f64 / bin_residual.max(1) as f64);
    }

    // Penalize residual that cannot fit the next item (lookahead coupling).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }
    // Reward residual that exactly accommodates the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open.
    if bin_residual == bin_capacity {
        score += 20.0 + 6.0 * open_bins_count as f64;
        // But opening a new bin is fine if existing residuals are large/wasteful.
        score -= 0.15 * mean_residual;
    } else {
        // Mild pressure to prefer bins with small residual (best-fit style).
        score += 0.05 * (bin_residual as f64 - mean_residual);
    }

    // Early stream: be slightly greedy toward consolidation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual).
    // Aggressive 2-step lookahead: reward when the leftover space exactly
    // (or nearly) matches the next item size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        if post_residual as u32 == next_item_size {
            // Perfect chain: this placement leaves exactly the next item's size.
            score -= 30.0 + 0.5 * nxt;
        } else if diff <= 3.0 {
            score -= 15.0 - 2.0 * diff;
        } else {
            // Penalize leftovers that the next item cannot use.
            let progress = step_index as f64 / total_items.max(1) as f64;
            if (post_residual as f64) < nxt {
                score += 0.15 * (post_residual as f64) * (1.0 + progress);
            } else {
                score += 0.05 * diff;
            }
        }
        // If next item fits in the post-residual at all, mild bonus.
        if next_item_size <= post_residual {
            score -= 4.0;
        }
    } else {
        // Last item: purely minimize waste.
        score += 0.0;
    }

    // Compare against mean residual across open bins: bins with residual
    // far below mean are "tight" — placing here preserves large-space bins
    // for large items. Reward placing into below-mean-residual bins.
    let res = bin_residual as f64;
    if res < mean_residual {
        score -= 0.20 * (mean_residual - res);
    } else {
        score += 0.10 * (res - mean_residual);
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    } else if fitting_bins_count > 1 {
        // With alternatives, slight penalty so the tightest fit wins naturally.
        score += 1.5 * (fitting_bins_count.min(6) as f64 - 1.0);
    }

    // New-bin candidate handling: opening a fresh bin is only attractive
    // when the item is large relative to capacity (poor fit elsewhere would
    // waste little) and there are many open bins already.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let frac = item_size as f64 / bin_capacity as f64;
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Penalize new bins normally; relax penalty for large items late in stream.
        score += 25.0 - 20.0 * frac * progress;
        // If next item is large, a fresh bin has more chain potential.
        if next_item_size > 0 && (next_item_size as f64) >= 0.5 * bin_capacity as f64 {
            score -= 6.0;
        }
    }

    // Mild preference to consolidate when many bins are open.
    score += 0.02 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but penalize tiny dead space
    // that no future item can realistically use.
    let dead = post_residual as f64;
    if dead > 0.0 && dead < 10.0 {
        score += (10.0 - dead) * 2.5; // unusable sliver penalty
    }

    // Lookahead: if the next item fits exactly in the post-residual, strongly reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (nxt - dead).abs() < 0.5 {
            score -= 30.0;
        } else if nxt <= dead {
            // next item fits: value the leftover capacity for it
            score -= 8.0 * (1.0 - (dead - nxt) / bin_capacity as f64);
        } else {
            // next item won't fit here: penalize leaving large unusable gaps
            score += 4.0 * (nxt - dead).min(40.0) / 40.0 * (dead / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin over opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when existing
    // residuals are poor fits (large post_residual) or many bins are already open.
    if bin_residual == bin_capacity {
        // baseline for a fresh bin: slightly worse than a decent fit
        score = bin_capacity as f64 * 0.5;
        let pressure = mean_residual / bin_capacity as f64;
        // if open bins have lots of residual (fragmented), new bin is less attractive
        score += 15.0 * pressure;
        // early in stream, prefer consolidating; late, new bins are cheaper
        let t = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * t;
        // many open bins: discourage opening yet another
        score += (open_bins_count as f64).ln().max(0.0) * 3.0;
    } else {
        // reward using bins with larger residual (best-fit style via post_residual already),
        // plus mild bonus for keeping open_bins_count low
        score -= 2.0 * (1.0 - (bin_residual as f64) / bin_capacity as f64);
        score -= 1.5 / (open_bins_count as f64 + 1.0);
    }

    // Global fragmentation coupling: if mean residual is small (bins nearly full),
    // favor placements that leave flexible (mid-sized) residuals.
    let flex = 1.0 - ((post_residual as f64 - 25.0).abs() / 50.0).min(1.0);
    score -= 5.0 * flex * (1.0 - mean_residual / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    let mut score = pr as f64;

    // Smooth non-linear coupling of post_residual with stream progress
    score -= 12.0 * norm_pr * norm_pr * (1.0 - progress);
    score += 8.0 * norm_pr * norm_pr * norm_pr * progress;

    // Tight fits reward: penalize large post_residual, more so when item is large
    score += 15.0 * norm_item * norm_item * (1.0 - norm_pr);

    // Lookahead interaction: reward residual matching next item
    let ni = next_item_size as f64 / cap;
    if next_item_size > 0 {
        let match_term = 1.0 - (norm_pr - ni).abs() * 2.0;
        score -= 10.0 * match_term.max(-1.0) * ni;
    }

    // Mean residual coupling: discourage diverging from fleet average
    let mr = mean_residual / cap;
    score += 6.0 * (norm_pr - mr) * (norm_pr - mr);

    // Last-chance bonus when few fitting bins
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 - progress * 0.5);
    }

    // Penalize opening new bins late in stream
    if bin_residual == bin_capacity {
        score += 5.0 + 25.0 * progress;
    }

    // Mild penalty for bin proliferation
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: coarse size classes via integer division.
    let item_class = item_size / 10;              // 0..=10
    let next_class = next_item_size / 10;         // 0..=10 (0 if last item)

    // Perfect-fit reward: exact fill is always ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space penalty: post_residual too small for the smallest item (1)
    // is fine, but residual in the "dead zone" (1..10) wastes capacity.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Modulo-arithmetic harmonic classes on post_residual:
    // residuals that are multiples of 10 pair well with the 10..80 class grid.
    let pr = post_residual;
    if pr % 10 == 0 {
        score -= 12.0; // clean harmonic residual, easy to fill later
    } else if pr % 5 == 0 {
        score -= 5.0;
    } else {
        score += 6.0; // awkward residual
    }

    // Coupling: does the next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Chain-friendly: reward proportional to how snugly next item fits.
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 + 0.3 * slack;
            // Harmonic match: same class chains pack tightly.
            if next_class == item_class {
                score -= 10.0;
            }
        } else {
            // Next item won't fit here; penalize less if residual is harmonic (multiple of 10).
            if pr % 10 != 0 {
                score += 10.0;
            }
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin gets a mild inertia penalty so we
    // prefer existing bins unless the fit is poor; but reward opening a fresh
    // bin for large items that would leave ugly residuals elsewhere.
    if bin_residual == bin_capacity {
        score += 18.0; // inertia against opening new bins
        if item_size >= 50 {
            score -= 20.0; // large items are fine to start fresh bins
        }
        if next_item_size > 0 && next_item_size > bin_capacity - item_size {
            score -= 8.0; // next item needs a big bin anyway
        }
    }

    // Stream progression: early on, be conservative (keep bins flexible);
    // late in the stream, squeeze hard into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual != bin_capacity {
        score -= 10.0 * progress; // late stream: favor existing bins
    }

    // Mean-residual coupling: if this bin is far below mean residual, it is
    // already "worn"; prefer to drain bins with residuals near the mean.
    let diff = mean_residual - bin_residual as f64;
    score += 0.15 * diff;

    // Penalize leaving residual that no class (10..80 multiples-ish) can use well:
    if pr > 0 && pr < 20 && next_item_size > pr {
        score += 15.0; // stranded small residual with a bigger next item
    }

    // Penalty scaling with number of open bins: discourage bin proliferation.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 12.0;
    } else if post_residual <= 30 {
        score += 4.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward tight fits relative to capacity.
    score -= (item_size as f64 / bin_capacity as f64) * 20.0;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open-bins pressure: when many bins are open, discourage opening new ones;
    // a brand-new empty bin gets a penalty proportional to open bin count.
    if bin_residual == bin_capacity {
        score += 30.0 + 5.0 * open_bins_count as f64;
    } else {
        score -= 5.0;
    }

    // Prefer bins with residual below the mean (consolidate space).
    score += ((bin_residual as f64) - mean_residual) * 0.3;

    // Lookahead: if next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    }
    // If next item cannot fit post-residual and post_residual is small, mild penalty.
    if next_item_size > post_residual && post_residual > 0 && post_residual < 25 {
        score += 8.0;
    }

    // Early stream: be slightly more willing to open bins (exploration).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity && progress < 0.2 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact/tight fits: small post_residual is good, already base score.
    // Strong reward when post_residual exactly matches the next item size (2-step lookahead).
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let pr = post_residual as f64;
        if pr >= next {
            let gap = pr - next;
            score -= 30.0 * (1.0 - gap / 100.0).max(0.0); // next item fits perfectly-ish
        } else {
            // next item cannot fit here; penalize proportionally to wasted potential
            score += 8.0 * (next - pr) / next.max(1.0);
        }
        // Bonus if bin residual can hold both current and next item snugly
        if bin_residual as f64 >= item_size as f64 + next {
            score -= 6.0;
        }
    }

    // Penalize dead space: post_residual too small to ever fit typical items
    if post_residual < 10 && post_residual > 0 {
        score += 15.0;
    }

    // Compare against mean residual: prefer bins tighter than average
    score -= 0.5 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate: penalize mildly unless current bin fit is terrible
    if bin_residual == bin_capacity {
        score += 12.0;
        // but if next item is huge and current fit is loose, opening a fresh bin is fine
        if next_item_size > 0 && post_residual as f64 > next_item_size as f64 + 25.0 {
            score -= 10.0;
        }
    }

    // Late in stream: consolidate, avoid opening new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual relative to bin capacity is better.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 2.5 * tightness * (post_residual as f64);

    // Penalize small unusable dead space: if post_residual is tiny but nonzero,
    // that space is likely wasted forever.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Perfect fit is highly desirable.
    if post_residual == 0 {
        score -= 20.0;
    }

    // Lookahead: if the next item fits exactly into the post_residual,
    // strongly favor this bin (chain placement).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            let next_leftover = post_residual - next_item_size;
            if next_leftover < 10 {
                score += 8.0; // would create dead space next step
            } else {
                score -= 6.0;
            }
        } else {
            // next item can't fit here; slightly favor this bin consuming it fully
            score += 2.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Time horizon: early in the stream, be more conservative about filling bins
    // (keep flexibility); later, pack greedily.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.3 * (1.0 - progress);

    // Global state: many open bins with high mean residual -> encourage using
    // existing bins rather than opening new ones.
    if bin_residual < bin_capacity {
        score -= 0.05 * mean_residual;
        score -= 1.0 * open_bins_count as f64;
    } else {
        // Candidate is a brand-new empty bin: penalize opening it unless
        // existing bins are quite full.
        let fullness = 1.0 - (mean_residual / bin_capacity as f64);
        score += 10.0 * (1.0 - fullness);
        if post_residual < 20 {
            score -= 12.0; // new bin would be nearly filled by this item
        }
    }

    // Mild preference for placing large items into fuller bins.
    score -= 0.1 * (item_size as f64) * (1.0 - (bin_residual as f64) / (bin_capacity as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let norm_pr = pr / cap;

    // Base: quadratic waste coupling (dead space penalized super-linearly)
    let mut score = pr + 60.0 * norm_pr * norm_pr;

    // Smooth stream-progress interaction: late in stream, waste matters more
    score *= 1.0 + 0.8 * progress * norm_pr;

    // Reward tight fits (small post_residual relative to item) via smooth term
    let tightness = it / (bin_residual as f64 + 1.0);
    score -= 30.0 * tightness * tightness;

    // Lookahead coupling: if next item fits into post_residual, reward this placement
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fits_next = (pr - nx) / cap;
        if fits_next >= 0.0 {
            score -= 12.0 * (1.0 - 2.0 * fits_next.abs()).max(0.0);
        } else {
            score += 6.0 * (-fits_next).min(1.0);
        }
    }

    // Last-chance bin: strongly reward using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize mildly early, more when many bins already fit
    if bin_residual == bin_capacity {
        score += 15.0 + 8.0 * fitting_bins_count as f64;
    } else {
        // Slight preference for bins below mean residual (balance load)
        score += 0.05 * (mean_residual - pr);
    }

    // Mild open-bins pressure: prefer reusing bins when many are open
    score -= 0.5 * open_bins_count as f64 * (1.0 - norm_pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: reward post_residuals divisible by common item-size buckets
    let pr = post_residual;
    if pr > 0 {
        // dead-space penalty grows quadratically for small unusable residue
        if pr < 10 {
            score += (10 - pr) as f64 * 3.0;
        }
        // class bonus: post_residual that is a multiple of 10 or 25 is more reusable
        if pr % 10 == 0 { score -= 6.0; }
        if pr % 25 == 0 { score -= 4.0; }
        if pr % 50 == 0 { score -= 3.0; }
    } else {
        // perfect fill is excellent
        score -= 25.0;
    }

    // Lookahead: does the next item fit into the post-residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 8.0;
            // harmonic match: next item exactly consumes a class of the residual
            if pr % next_item_size == 0 { score -= 5.0; }
            let frac = pr / next_item_size;
            if frac <= 2 { score -= 3.0; } // near-tight fit leaves little waste
        } else {
            // next item won't fit here: penalize proportionally to wasted potential
            score += (next_item_size - pr) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // no open bin offers a tight fit
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        if fitting_bins_count > 0 && tightness > 0.7 {
            // large item: prefer reusing an existing bin that fits
            score += 15.0;
        } else {
            // small item or no fitting bins: neutral-ish, mild preference to open
            score -= 2.0;
        }
    }

    // Progress-aware pressure: later in the stream, consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (mean_residual - post_residual as f64).max(0.0) * (0.5 + progress);

    // Prefer bins whose residual is close to the item (tight fits)
    let tight = (bin_residual - item_size) as f64;
    score += tight * tight / (bin_capacity as f64 * 4.0);

    // Slight penalty for spreading across many open bins
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    let dead = (post_residual as f64) / (bin_capacity as f64);
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (1.0 - dead);
    } else if post_residual < 20 {
        score += 25.0 * (1.0 - dead);
    }

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Open-bin pressure: with many open bins, prefer reusing existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    score += pressure * 0.8;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead coupling: if next item fits the post residual, this is a great placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        score += 10.0; // dead space relative to lookahead
    }

    // Prefer bins tighter than average residual (good fits).
    score += ((bin_residual as f64) - mean_residual) * 0.3;

    // New-bin candidate: neutral-ish baseline, only attractive when no decent fit exists.
    if bin_residual == bin_capacity {
        score = 70.0 + pressure * 0.3;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: reward perfect match of post_residual with next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match bonus
        if post_residual == next_item_size {
            score -= 60.0;
        } else if (post_residual as u32) >= next_item_size {
            // next item still fits: mild reward proportional to closeness
            score -= 25.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item won't fit here: penalize leaving a stranded residual
            score += 15.0 + 0.5 * (next_item_size as f64 - post_residual as f64);
        }
        // Extra reward if post_residual equals next item AND the item after that
        // could also relate (coupled lookahead approximation)
        if post_residual == next_item_size {
            score -= 10.0 * (1.0 - step_index as f64 / total_items.max(1) as f64);
        }
    } else {
        // Last item: simply minimize waste
        score -= 20.0;
    }

    // Compare post_residual against mean residual of open bins:
    // leaving less than average waste is good (tight packing).
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // rather than opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 0.2 * item_size as f64;
    }

    // Penalize choosing a fresh empty bin when open bins could take the item,
    // unless the item is large and residual waste would be small anyway.
    if bin_residual == bin_capacity {
        score += 45.0 - 0.25 * item_size as f64;
    }

    // Slight preference for bins with less residual before placement (tighter bins).
    score += 0.1 * (bin_capacity as f64 - bin_residual as f64) * -1.0;

    // Mild pressure to consolidate as stream progresses.
    score -= 5.0 * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post-residual (tight fit), normalized
    let cap = bin_capacity as f64;
    let tightness = 1.0 - (post_residual as f64) / cap; // 1 = perfect fit
    score -= 0.6 * tightness * cap;

    // Strongly reward perfect / near-perfect fits
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Lookahead: reward if the next item fits exactly into the post-residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0; // chain fit: excellent
        } else if next_item_size < post_residual {
            // next item fits but leaves more waste; mild reward scaled by fill
            let chain_fill = next_item_size as f64 / post_residual as f64;
            score -= 12.0 * chain_fill;
        } else {
            // next item won't fit here: penalize leaving large unusable gaps
            score += 0.15 * (post_residual as f64);
        }
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize opening new bins when good open bins exist
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when open bins are crowded or fit is bad
        let open_pressure = if open_bins_count > 0 {
            1.0 - (mean_residual / cap).min(1.0)
        } else {
            1.0
        };
        // baseline cost of a fresh bin (full capacity of unused space)
        score += cap;
        // discount when bins are nearly full or many bins are open
        score -= 45.0 * open_pressure;
        score -= 2.0 * (open_bins_count as f64).ln().max(0.0);
        // late in the stream, avoid spawning extra bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 * progress;
        // if next item is huge, a fresh bin is valuable as a clean slate
        if next_item_size >= 60 {
            score -= 20.0;
        }
    }

    // Global residual balancing: prefer bins whose residual is below the mean
    // (drain the fullest bins first to consolidate space)
    let diff = mean_residual - bin_residual as f64;
    score -= 0.1 * diff;

    // Mild penalty for leaving residuals that no typical item can use
    if post_residual > 0 && post_residual < 5 {
        score += 8.0; // tiny dead space is worthless
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: prefer bins with small post residual (tight fit).
    let mut score = post;

    // Quadratic dead-space penalty: small residuals are hard to reuse.
    let norm_post = post / cap;
    score += 18.0 * norm_post * norm_post;

    // Perfect-fit reward: subtract aggressively as post_residual approaches 0.
    if post == 0 {
        score -= 40.0;
    } else if post <= 10.0 {
        score -= 20.0 * (1.0 - post / 10.0);
    }

    // Lookahead coupling: reward bins whose post residual matches next item size.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let diff = (post - nx).abs();
        let coupling = 1.0 - (diff / cap).min(1.0);
        score -= 15.0 * coupling * coupling;
        // Strong bonus if next item fits exactly after this placement.
        if post == nx {
            score -= 25.0;
        }
    }

    // Stream progress: later in the stream, waste is more costly; tighten selection.
    score += 10.0 * progress * norm_post;

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Many open bins: mild penalty to avoid proliferating bins; prefer consolidation.
    score += 0.3 * open_bins_count as f64 * norm_post;

    // Mean residual interaction: if this bin's residual is far below the mean, it's a good niche fit.
    let dev = (mean_residual - post) / cap;
    score -= 6.0 * dev.max(0.0) * dev.max(0.0);

    // New-bin candidate: penalize opening a new bin unless current fit is poor.
    if bin_residual == bin_capacity {
        score += 30.0 - 20.0 * (1.0 - norm_post);
        // If no open bin fits, this call is the only option; the fitting count check
        // is implicit since open bins that fit would score lower with tight fits.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero gets strong discount.
    if post_residual == 0 {
        score -= 200.0; // perfect fit
    } else {
        // Harmonic-class penalty: dead space that no small item (>=1) can use.
        // Fractional dead space relative to capacity.
        let frac = post_residual as f64 / bin_capacity as f64;
        score += 40.0 * frac * frac; // quadratic dead-space penalty

        // Harmonic classes: bin residual mod common item sizes.
        // If post_residual matches typical small item sizes exactly, reward.
        let pr = post_residual;
        if pr % 10 == 0 && pr > 0 { score -= 15.0; }
        if pr % 5 == 0 && pr > 0 { score -= 7.0; }

        // If next item fits into post_residual exactly or well, big reward.
        if next_item_size > 0 && next_item_size <= pr {
            let chain_residual = pr - next_item_size;
            score -= 25.0;
            if chain_residual == 0 { score -= 40.0; }
            // harmonic threshold classes on chained residual
            if chain_residual % 10 == 0 && chain_residual > 0 { score -= 10.0; }
        } else if next_item_size > 0 && next_item_size > pr {
            // next item won't fit here: penalize leaving awkward space
            score += 12.0;
            // but if post_residual too small to matter (<10), mild bonus (nearly full)
            if pr < 10 { score -= 20.0; }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening new bins unless existing fits are bad.
    if bin_residual == bin_capacity {
        score = 150.0 + post_residual as f64;
        // early in stream, opening bins is cheaper; late in stream, prefer filling
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 30.0 * (1.0 - progress);
        // if many open bins already, discourage yet another
        score += 3.0 * open_bins_count as f64;
    }

    // Prefer bins with residual below mean (consolidating fuller bins).
    score -= 0.5 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that can't fit typical future items are wasted.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 40.0; // tiny unusable sliver
        } else if post_residual < next_item_size.max(1) as f64 {
            score += 25.0; // can't fit the lookahead item
        } else {
            score -= 8.0; // residual still usable
        }
    } else {
        score -= 30.0; // perfect fit
    }

    // Reward tight fits (large fill fraction of the bin).
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 20.0 * fill * fill;

    // Pressure: with many open bins, prefer reusing existing bins (penalize new bin).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64) * (0.5 + 0.5 * progress);

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 35.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0;
    }

    // Mean residual coupling: prefer bins close to the mean to keep balance.
    score += ((bin_residual as f64) - mean_residual).abs() * 0.15;

    // New-bin candidate: penalize opening a new bin unless item is large relative to it.
    if bin_residual == bin_capacity {
        score += 45.0 - (item_size as f64) * 0.4;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Base: reward tight fits (small post_residual already dominates).

    // Aggressive 2-step lookahead: strongly reward exact match of next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post_residual as f64 - nxt).abs();
        if post_residual as u32 >= next_item_size {
            // next item fits exactly -> huge reward
            score -= 30.0 * (1.0 - gap / cap);
            // bonus for perfect wrap (post_residual == next_item_size)
            if post_residual as u32 == next_item_size {
                score -= 20.0;
            }
        } else {
            // next item does NOT fit here: penalize leaving a sliver of dead space
            let slack = post_residual as f64;
            if slack < 10.0 {
                score += 15.0 * (10.0 - slack);
            }
        }
    }

    // Relative-to-mean coupling: prefer bins with residual below mean (denser bins)
    let dev = mean_residual - post_residual as f64;
    score -= 0.3 * dev;

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fits are bad
    if bin_residual == bin_capacity {
        score += 35.0;
        // less penalty late in stream when consolidation matters less
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
    }

    // Mild penalty for wasting a large residual on a small item
    let waste = post_residual as f64 / cap;
    score += 10.0 * waste * waste;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - tightness) * (1.0 - tightness) * 20.0;

    // Penalize dead space that can never host a typical item.
    if post_residual > 0 && post_residual < item_size.min(80) {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: bonus if the next item fits exactly in post_residual (chaining).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            score -= (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // Next item won't fit here; slight penalty proportional to waste.
            score += post_residual as f64 * 0.1;
        }
    }

    // Prefer fuller bins when many bins are open (consolidation pressure).
    score += (open_bins_count as f64).ln().max(0.0) * post_residual as f64 * 0.05;

    // Global mean residual: if this bin's residual is below mean, it's a good home.
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.2;

    // Time horizon: early on, be more willing to open new bins (explore);
    // late in the stream, consolidate aggressively.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let new_bin = (bin_residual == bin_capacity) as f64;
    score += new_bin * (30.0 - 40.0 * t);

    // Mild penalty for opening a new bin when an existing bin fits well.
    if new_bin > 0.0 && fitting_bins_count > 0 && post_residual as f64 > mean_residual {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr_norm = pr / cap;

    // Base: prefer low post-residual, with non-linear sharpening
    let mut score = pr + 12.0 * pr_norm * pr_norm;

    // Smooth polynomial coupling of residual with stream progress:
    // early on, tolerate slack; later, penalize dead space quadratically
    let progress_coupling = pr_norm * (1.0 - progress) * 20.0
                          - pr_norm * progress * 15.0;
    score += progress_coupling;

    // Cubic interaction: large residuals late in the stream are heavily penalized
    score += 30.0 * pr_norm.powi(3) * progress;

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 10.0 * progress;
    }

    // Lookahead: reward bins whose post-residual fits the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 8.0 * (1.0 - (pr - nxt) / cap);
        } else {
            score += 5.0 * (nxt - pr) / cap;
        }
    }

    // Crowding: mildly prefer bins in bins with many fitting candidates
    if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Mean-residual alignment: prefer bins near the mean (balanced packing)
    score += 0.15 * (pr - mean_residual).abs();

    // New-bin candidate: baseline score so it wins only when fits are poor
    if bin_residual == bin_capacity {
        score = cap * (0.85 + 0.25 * progress) + 0.15 * mean_residual;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: dead space classification via
    // integer division into capacity-fraction buckets.
    let cap_f = bin_capacity as f64;
    let post = post_residual as f64;

    // Fractional class of post_residual relative to capacity.
    let post_frac = post / cap_f; // in [0, 1]

    // Reward tight fits: post_residual in the lowest harmonic band.
    if post_residual == 0 {
        score -= 1000.0; // perfect fill
    } else if post_residual <= bin_capacity / 10 {
        score -= 40.0;
    } else if post_residual <= bin_capacity / 4 {
        score -= 15.0;
    } else if post_residual <= bin_capacity / 2 {
        score -= 5.0;
    } else {
        // Large leftover: penalize, dead space.
        score += 10.0 + post_frac * 20.0;
    }

    // Modulo arithmetic on post_residual: residuals divisible by small
    // harmonic steps (10, 20, 25) are more likely reusable by future items.
    let pr = post_residual;
    if pr > 0 && pr % 10 == 0 {
        score -= 6.0;
    }
    if pr > 0 && pr % 20 == 0 {
        score -= 3.0;
    }
    if pr > 0 && pr % 25 == 0 {
        score -= 3.0;
    }

    // Lookahead coupling: if the next item fits the post-residual exactly
    // or closely, strongly favor this bin.
    if next_item_size > 0 {
        let ni = next_item_size;
        if ni <= post_residual {
            let slack = (post_residual - ni) as f64;
            // Harmonic class of the pair (post_residual, next_item).
            if slack == 0 {
                score -= 80.0;
            } else if slack <= 10 {
                score -= 30.0;
            } else if slack <= 20 {
                score -= 12.0;
            } else {
                score -= 20.0 / (1.0 + slack / 10.0);
            }
        } else {
            // Next item cannot use the leftover; penalize proportional to gap class.
            let gap = (ni - post_residual) as f64;
            score += 4.0 + (gap / 20.0).min(10.0);
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 18.0;
    } else if fitting_bins_count > 1 {
        // Slight preference for bins with less competition (scarcer fit).
        score -= 2.0 / fitting_bins_count as f64;
    }

    // Mean-residual coupling: prefer bins below mean residual (tighter bins),
    // penalize bins far above mean (wasteful bins).
    let res_f = bin_residual as f64;
    let dev = (res_f - mean_residual) / cap_f;
    score += dev * 15.0;

    // Stream progression: early on, be more willing to open bins (favor
    // spreading); late, consolidate to avoid leftover fragmentation.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 3.0 * post_frac;

    // New-bin candidate handling: opening a new bin is only attractive when
    // the item is large relative to capacity or no good fit exists.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin: discourage unless item is big.
        let big_item_bonus = (item_size as f64 / cap_f) * 60.0;
        score = 55.0 - big_item_bonus;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            // Room for lookahead item in fresh bin.
            score -= 8.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
        if fitting_bins_count == 1 {
            // Existing bin is last chance; only open new if that fit is bad.
            if post_residual <= bin_capacity / 4 {
                score += 25.0;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = 0.0;

    // Base: prefer tight fits (small post_residual).
    score += post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps.
    // If post_residual is small but nonzero and can't plausibly hold a future item,
    // treat it as dead space and punish heavily.
    if post_residual > 0 {
        // Gap is "dead" if smaller than the smallest possible item (1) is fine,
        // but gaps below a meaningful threshold relative to capacity are wasted.
        let dead_threshold = (bin_capacity as f64 * 0.12).max(6.0);
        if (post_residual as f64) < dead_threshold {
            // Dead space: penalize proportionally to how close to the threshold it is.
            let deadness = 1.0 - (post_residual as f64 / dead_threshold);
            score += 40.0 * deadness;
        }
    }

    // Perfect fit reward: zero residual is ideal.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward bins whose residual closely matches the item (tight packing ratio).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fill_ratio;

    // Pressure from number of open bins: prefer filling existing bins when many are open.
    score += 1.5 * open_bins_count as f64;

    // Mean residual coupling: if mean residual is high, we have slack everywhere;
    // be pickier about tight fits. If mean residual is low, accept decent fits.
    score -= 0.3 * mean_residual;

    // Lookahead: if the next item fits in the post residual, bonus for preserving that option.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
        // Extra bonus if next item fills the post residual almost exactly.
        let gap_after_next = post_residual - next_item_size;
        if gap_after_next <= 5 {
            score -= 6.0;
        }
    } else if next_item_size > 0 {
        // Next item won't fit here; mildly penalize leaving a gap that helps nothing.
        score += 2.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin should only win when fits are bad.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 55.0;
        // Opening a new bin is more attractive early in the stream (more future items
        // to fill it with) and when few bins are open.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);
        // If no open bin fits well (large post_residual everywhere), new bin is fine.
        if post_residual == bin_capacity {
            // Neutralize some of the new-bin cost when the alternative is bad.
            score -= 10.0;
        }
    }

    // Slight preference for bins with larger residual being used by larger items
    // (avoid putting tiny items in big-gap bins when tighter bins exist).
    score += 0.05 * (bin_residual as f64 - item_size as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let residual = bin_residual as f64;
    let nxt = next_item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;

    // Fill-ratio reward: favor bins whose residual the item consumes tightly.
    let fill_ratio = item / residual.max(1.0);
    score -= 25.0 * fill_ratio;

    // Relative-to-mean coupling: prefer placements that end below the mean
    // residual (concentrating free space into fewer, emptier bins).
    score += 0.30 * (post - mean_residual);

    if !is_new_bin {
        // Last-chance bonus: this is the only open bin that fits the item;
        // strongly prefer using it over opening a new bin.
        if fitting_bins_count == 1 {
            score -= 250.0 + 150.0 * (1.0 - progress);
        }
        // Consolidation reward: with many bins open, favor reusing them.
        score -= 1.5 * (open_bins_count as f64).min(12.0);
    } else {
        // New-bin candidate: penalize when many bins are already open or
        // when open bins still hold ample average space.
        score += 2.0 * open_bins_count as f64 + 0.40 * mean_residual;
    }

    // Aggressive 2-step lookahead against the next item.
    if next_item_size > 0 {
        if post == nxt {
            // Perfect chain: the next item exactly fills this leftover.
            score -= 160.0;
        } else if nxt < post {
            // Next item can also be hosted here; reward tighter chains.
            score -= 40.0 * (nxt / post);
        } else {
            // Leftover cannot host the next item: penalize crumbs harder
            // when the upcoming item is large (higher chance of dead space).
            let crumb = (14.0 - post).max(0.0);
            score += crumb * (2.5 + 2.0 * (nxt / cap));
        }
    } else {
        // Final item: extra reward for closing a bin exactly.
        if post == 0.0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item nearly fills the residual.
    let fill_ratio = if bin_residual > 0 { item_size as f64 / bin_residual as f64 } else { 0.0 };
    score -= 60.0 * fill_ratio * fill_ratio;

    // Dead-space penalty: residual left behind that is hard to reuse (very small leftovers).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward if the next item fits into the post residual (chaining).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 18.0;
            // Extra reward for near-exact chaining.
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - chain_waste / bin_capacity as f64);
        } else {
            // Penalize blocking the next item with a large unusable leftover.
            score += 8.0;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits, to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin should only win when the item
    // fits poorly everywhere else. The empty-bin call has fill_ratio ~ item/capacity.
    if bin_residual == bin_capacity {
        // Mild structural penalty so new bins are opened only for good reason.
        score += 12.0;
        // More open bins -> slightly discourage spawning yet another.
        score += 1.5 * open_bins_count as f64;
        // If the item is large relative to capacity, a fresh bin is more attractive.
        score -= 25.0 * (item_size as f64 / bin_capacity as f64);
        // Early in the stream, allow more bins (future flexibility).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
        // If mean residual across open bins is already high, reuse is cheap; penalize new bin.
        score += 0.15 * mean_residual;
    } else {
        // Reusing an existing bin is generally good; scale with how full it will become.
        let post_fill = 1.0 - post_residual as f64 / bin_capacity as f64;
        score -= 15.0 * post_fill;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    // smooth polynomial coupling of post_residual with stream progress
    let poly = 1.0 + 2.0 * progress * progress + 3.0 * progress * progress * progress;
    score += 6.0 * poly * pr_norm * pr_norm;
    // reward tight fits, stronger later in stream
    score -= (1.0 - pr_norm) * (1.0 + progress) * 4.0;
    // penalize dead space that next item cannot use
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap > 0.0 {
            score += 3.0 * (gap / cap) * poly;
        } else {
            score -= 2.0; // next item fits exactly in residual
        }
    }
    // last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 8.0 + 6.0 * progress;
    }
    // many open bins: mild penalty to prefer consolidation
    score += (open_bins_count as f64).ln().max(0.0) * 0.5;
    // penalize bins far from mean residual (fragmentation)
    let dev = (pr - mean_residual).abs() / cap;
    score += 2.0 * dev * (1.0 + progress);
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues near multiples of small
    // denominators (2,3,4,5 of capacity) are "usable" dead space, others are waste.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // fraction of capacity left after placement

    // Tightness reward: strongly favor small post_residual.
    score += (frac * frac) * 40.0;

    // Harmonic bonus: if post_residual lies close to a "good" fraction of capacity
    // (1/4, 1/3, 1/2), the leftover is likely reusable by future items.
    let harmonics = [0.25f64, 1.0 / 3.0, 0.5];
    let mut h_bonus = 0.0;
    for h in harmonics.iter() {
        let d = (frac - h).abs();
        if d < 0.06 {
            h_bonus += (0.06 - d) * 60.0;
        }
    }
    score -= h_bonus;

    // Integer-division class: post_residual divisible by small ints packs better.
    if post_residual > 0 {
        let r = post_residual;
        if r % 10 == 0 { score -= 6.0; }
        else if r % 5 == 0 { score -= 3.0; }
        else if r % 3 == 0 { score -= 1.5; }
        // awkward primes get penalized
        if r % 7 != 0 && r % 10 != 0 && r % 5 != 0 && r % 3 != 0 && r % 2 != 0 {
            score += 4.0;
        }
    }

    // Lookahead: reward bins whose post_residual admits the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 18.0 - (slack / cap) * 20.0; // exact fit of next item rewarded most
    } else if next_item_size > 0 {
        // next item won't fit here: mild penalty proportional to how far off
        score += ((next_item_size - post_residual) as f64 / cap) * 10.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin (residual == capacity).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        let mut new_bin_score = cap * 0.55; // 55 units: cost of fresh capacity
        // If the item leaves a harmonic-friendly residual, opening is more attractive.
        let nfrac = (bin_capacity - item_size) as f64 / cap;
        for h in harmonics.iter() {
            if (nfrac - h).abs() < 0.08 { new_bin_score -= 12.0; }
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        new_bin_score += progress * 10.0;
        // Many open bins already: discourage another.
        new_bin_score += (open_bins_count as f64).sqrt() * 4.0;
        // If some open bin fits decently, make new bin less attractive.
        if fitting_bins_count > 0 && (post_residual as f64) <= mean_residual {
            new_bin_score += 15.0;
        }
        score = new_bin_score;
    }

    // Mild consolidation pressure: prefer bins with residual below the mean
    // (fill the emptier bins first, keep large holes open).
    if bin_residual < bin_capacity {
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        } else {
            score += 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let dead_threshold: f64 = 10.0;
    let pr = post_residual as f64;
    if pr > 0.0 && pr <= dead_threshold {
        // Dead space: the smaller (worse) the gap, the bigger the penalty.
        score += (dead_threshold - pr + 1.0) * 6.0;
    } else if pr == 0.0 {
        // Perfect fit: strong reward.
        score -= 40.0;
    } else {
        // Usable leftover: mild quadratic reward for larger leftovers.
        score -= (pr / bin_capacity as f64) * 8.0;
    }

    // Reward leaving room for the lookahead item if it fits.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if next_item_size > bin_residual {
            // Next item won't fit anywhere in this bin anyway; leftover is free dead space.
            score -= 3.0;
        } else {
            // We block the next item that could otherwise have fit here.
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Last chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into new bins,
    // encourage filling existing ones (especially when mean residual is low).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open or mean residual is high.
        score += 15.0 + open_bins_count as f64 * 2.0 + mean_residual * 0.3 + progress * 10.0;
    } else {
        // Existing bin: slight reward scaled by how full it already is.
        score -= (bin_capacity as f64 - bin_residual as f64) / bin_capacity as f64 * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near match: next item fits with small slack left.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 10 {
        score -= 25.0 - (post_residual - next_item_size) as f64;
    }
    // Penalize when next item cannot fit here (dead space from lookahead view).
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Compare post_residual against mean residual: leaving more than average is wasteful.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize opening a new bin when decent fits exist.
    if bin_residual == bin_capacity {
        score += 55.0;
        if fitting_bins_count > 0 {
            let best_possible = (bin_residual - item_size) as f64;
            if best_possible <= 20.0 {
                score += 30.0; // an open bin would leave little slack; keep new-bin penalty high anyway
            }
        }
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 20.0; // reserve fresh bin for pairing current + next item
        }
    }

    // Tight fits are good: small post_residual rewarded nonlinearly.
    if post_residual <= 10 {
        score -= 15.0;
    }
    // Avoid leaving large unusable gaps (nothing in 1..100 range may fit well).
    if post_residual > 0 && post_residual < 10 {
        score -= 10.0;
    }

    // Mild preference to fill older bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= progress * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 45.0 * tightness * tightness;

    // Penalize post-residuals that are too small to be useful for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // dead space
    } else if post_residual >= 10 && post_residual < 30 {
        score += 6.0 * (30.0 - post_residual as f64) / 20.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: opening a new bin is penalized mildly,
    // unless the fit in existing bins is poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 30.0 + 0.15 * open_bins_count as f64;
        // If the item fits perfectly in a fresh bin and lookahead also fits, encourage it.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 20.0;
        }
        // Late in the stream, avoid opening bins unless nothing fits well.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
    } else {
        // Reward using bins that are already partially filled (consolidation).
        let fill = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
        score -= 15.0 * fill;
    }

    // Lookahead coupling: if the next item fits into the post-residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // If next item won't fit here, slightly penalize leaving a near-miss gap.
            let gap = (next_item_size as f64 - post_residual as f64).max(0.0);
            if gap < 15.0 {
                score += gap * 0.8;
            }
        }
    }

    // Global state: many open bins with high mean residual -> prefer filling emptier bins
    // to reduce fragmentation; few open bins -> prefer tightest fit.
    if open_bins_count > 1 {
        let deviation = (bin_residual as f64 - mean_residual).abs();
        score += 0.1 * deviation;
    }

    // Mild preference for bins whose residual is close to item_size (perfect-ish fit).
    let exactness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 10.0 * exactness * exactness;

    // Small noise-free tiebreaker by step progression to stabilize ordering.
    score += 0.001 * (step_index as f64 % 7.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let fit_frac = item_size as f64 / cap;
    let post_frac = pr / cap;
    let mean_frac = mean_residual / cap;

    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let p2 = progress * progress;
    let p3 = p2 * progress;
    score *= 1.0 - 0.35 * p2 - 0.25 * p3;

    // Reward tight fits (small post_residual) increasingly over time
    score -= 8.0 * (1.0 - post_frac) * (1.0 - post_frac) * (0.4 + 0.6 * progress);

    // Penalize dead space that cannot fit the lookahead item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += 6.0 * (nxt - pr) / cap * (1.0 + progress);
        } else {
            score -= 3.0 * (pr - nxt) / cap;
        }
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 + 0.5 * progress);
    }

    // Slight penalty when bin residual deviates from mean residual (encourage balanced fills)
    score += 2.0 * (post_frac - mean_frac) * (post_frac - mean_frac) * (1.0 - 0.5 * progress);

    // Mild preference to reuse open bins vs opening new ones as stream matures
    score += 0.8 * (open_bins_count as f64).ln().max(0.0) * (1.0 - fit_frac) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward post-residuals that are "usable"
    // by common future item sizes (multiples of 10, or small residuals).
    let pr = post_residual;
    if pr == 0 {
        score -= 25.0; // perfect fit, ideal
    } else if pr < 10 {
        score -= 10.0; // dead space but tiny
    } else {
        // modulo arithmetic on residual: residuals divisible by 10 are
        // most reusable; residuals near capacity fractions are okay.
        if pr % 10 == 0 {
            score -= 6.0;
        }
        // integer-division thresholds: how many "typical" items (>=10) fit
        let slots = pr / 10;
        score -= (slots as f64).min(8.0) * 1.5;
        // penalize awkward middle residuals (dead zones)
        if pr > 5 && pr < 20 {
            score += 8.0;
        }
    }

    // Fractional fill of the bin: reward high fill ratio
    let fill = 1.0 - (post_residual as f64) / cap;
    score -= fill * fill * 20.0;

    // Lookahead coupling: if next item fits in post_residual, big reward
    if next_item_size > 0 && next_item_size <= pr {
        score -= 15.0;
        // extra reward if next item nearly fills the remaining space
        let gap = pr - next_item_size;
        if gap < 10 {
            score -= 8.0;
        }
    } else if next_item_size > 0 {
        // next item won't fit here: mild penalty scaled by mismatch
        score += ((next_item_size - pr) as f64).min(60.0) * 0.15;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else {
        // competition: slightly penalize when many bins fit, prefer tight fits
        score += (fitting_bins_count as f64).min(10.0) * 0.8;
    }

    // New-bin candidate handling: only attractive when no good open option
    if bin_residual == bin_capacity {
        let stream_progress = step_index as f64 / (total_items.max(1) as f64);
        // base cost of opening a new bin
        score += 40.0;
        // if item is large relative to capacity, new bin is fine
        score -= (item_size as f64 / cap) * 30.0;
        // early in stream, opening bins is cheaper (more future items to fill)
        score -= (1.0 - stream_progress) * 15.0;
        // if few bins fit the item, new bin becomes reasonable
        if fitting_bins_count <= 1 {
            score -= 35.0;
        }
        // if open bins are already crowded (low mean residual), new bin good
        if mean_residual < item_size as f64 {
            score -= 20.0;
        }
    } else {
        // mild preference for reusing existing bins over opening new
        score -= 5.0;
        // reward using bins whose residual deviates from mean (consolidate)
        let dev = (bin_residual as f64 - mean_residual).abs();
        score -= dev.min(50.0) * 0.1;
    }

    // open bins count pressure: many open bins -> prefer consolidation
    score += (open_bins_count as f64).min(30.0) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..10) are heavily penalized
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Reward near-perfect fits
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits into post_residual, this is a great chain
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 + slack * 0.3;
    }

    // Last chance: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 50.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    let pressure = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
    score -= pressure * 20.0 + mean_residual * 0.1;

    // Early in the stream, slightly prefer opening bins to build a diverse pool
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: residual after placement exactly fits the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-perfect match: next item fits with small slack.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64).max(0.0);
    } else if next_item_size > 0 {
        // Dead space: next item cannot use the leftover residual.
        let dead = (next_item_size - post_residual) as f64;
        score += 0.8 * dead.min(50.0);
    }

    // Compare post_residual against mean residual across open bins:
    // leaving less than average residual is efficient packing.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Early in the stream, allow opening new bins more freely to build a good
    // pool of residuals; late in the stream, consolidate tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as packing consolidates.
        score += 20.0 + 30.0 * progress;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0; // fresh bin trivially fits the next item
        }
    }

    // Mild penalty for many open bins to discourage fragmentation.
    score += 0.4 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward small post_residual non-linearly.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * tightness * tightness;

    // Penalize wasted residual relative to the bin's own remaining space.
    if bin_residual > 0 {
        score -= 8.0 * (1.0 - post_residual as f64 / bin_residual as f64);
    }

    // Lookahead: if the next item fits into the post residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            // Post residual cannot host next item: penalize proportionally to dead space.
            score += 5.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }
    // Many fitting bins: mild penalty for splurging space when alternatives exist.
    if fitting_bins_count > 2 {
        score += 2.0 * (fitting_bins_count as f64 - 2.0);
    }

    // Global state: prefer filling bins when many bins are open (reduce bin count pressure).
    score -= 1.5 * (open_bins_count as f64).ln().max(0.0);

    // Deviation from mean residual: prefer bins whose residual is below/at mean (consolidate).
    let dev = post_residual as f64 - mean_residual;
    score += 0.3 * dev;

    // Time horizon: early in stream, be conservative (favor new bins slightly); later, pack tighter.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (1.0 - tightness);

    // New-bin candidate handling: an empty bin should only win when the fit is bad elsewhere.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, discounted as stream progresses.
        score = 55.0 - 20.0 * progress;
        // If this is the only fitting option, opening is fine.
        if fitting_bins_count <= 1 {
            score -= 25.0;
        }
        // Small items waste a fresh bin more.
        score += 0.2 * (bin_capacity as f64 - item_size as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post-residual in [0,1]

    // Base: prefer tight fits, with a smooth non-linear (quartic) shaping of post-residual.
    let mut score = pr as f64 * (1.0 + 2.0 * x * x * (1.0 - x));

    // Smooth polynomial coupling with stream progress: early on, tolerate larger leftovers;
    // late in the stream, aggressively penalize wasted space.
    let progress_weight = 3.0 * t * t - 1.0 * t; // smooth in t
    score += progress_weight * pr;

    // Non-linear coupling of post-residual with mean residual across open bins:
    // penalize creating residuals that deviate upward from the fleet mean.
    let dev = pr - mean_residual;
    score += 0.5 * dev * (1.0 + (dev / cap).abs());

    // Lookahead: reward residuals that can host the next item smoothly.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if pr >= n {
            score -= 4.0 * (1.0 - (pr - n) / cap) * (t.max(0.2));
        } else {
            score += 2.0 * (n - pr) * (1.0 - t);
        }
    }

    // Last-chance bin: strong smooth reward to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * t;
    }

    // Mild penalty for bin proliferation, smoothly scaled by progress.
    score += (open_bins_count as f64).ln() * (1.0 + t);

    // New-bin candidate: make it attractive only when the fit is poor, smoothly.
    if bin_residual == bin_capacity {
        score += 6.0 * (1.0 - x) - 10.0 * t * (x.max(0.9) - 0.9) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit: overwhelming reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: dead space in (0,10) is nearly unusable
    // (min item size class), penalize hard; small-but-usable residuals graded.
    if post_residual > 0 {
        let pr = post_residual;
        if pr < 10 {
            score += 40.0; // dead space
        } else {
            // mod-10 class: residuals near class boundaries pack better
            let class = pr % 10;
            score -= (10 - class) as f64 * 0.5;
        }
    }

    // Tightness: reward filling most of the bin (fractional capacity coupling).
    let fill = (bin_residual - post_residual) as f64 / cap;
    score -= fill * fill * 30.0;

    // Lookahead: bonus if next item fits the resulting residual exactly or well.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        if gap == 0.0 {
            score -= 120.0; // chain of perfect fits
        } else if gap < 10.0 {
            score -= 25.0;
        } else {
            score -= 20.0 / (1.0 + gap / 20.0);
        }
    } else if next_item_size > 0 {
        // next item won't fit here: mild penalty proportional to wasted potential
        score += 8.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 60.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate handling: empty bin should only win when no open bin
    // offers a decent fit. Penalize opening a new bin normally.
    if bin_residual == bin_capacity {
        score += 55.0 + mean_residual * 0.3;
        // late in stream, prefer consolidation into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
        // exception: if item is huge and residual of open bins is tight, allow new bin
        if item_size as f64 > 0.8 * cap && mean_residual < item_size as f64 * 0.35 {
            score -= 90.0;
        }
    }

    // Prefer bins whose residual deviates from the mean toward tighter states.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Mild pressure against bin sprawl.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=9) are heavily penalized,
    // but a perfect fit (post_residual == 0) is strongly rewarded.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score += 30.0; // dead space too small for any future item (min size 1..100, be conservative)
    } else {
        // Non-linear reward for tight fits: quadratic falloff of usable residual
        let r = post_residual as f64;
        score -= 40.0 * (1.0 - r / bin_capacity as f64).powi(3);
    }

    // Prefer bins whose residual tightly matches the item (waste ratio penalty)
    let tightness = (bin_residual - item_size) as f64 / bin_residual.max(1) as f64;
    score += 15.0 * tightness;

    // Lookahead coupling: if next item fits exactly in the post residual, big reward;
    // if next item cannot fit in post residual, mild penalty.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual < next_item_size {
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new bins,
    // encourage consolidating into existing ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.5 + progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open-bin pressure
        score += 10.0 + pressure;
    } else {
        score -= pressure * 0.3;
    }

    // Mean residual coupling: placing into a bin below mean residual helps balance
    if bin_residual as f64 > mean_residual {
        score += 3.0;
    } else {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small dead space)
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * (1.0 - tightness) * (1.0 - tightness);

    // Exact / near-exact fit bonus
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 120.0;
    } else if post_residual < 10 {
        score -= 60.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual >= next_item_size {
            // next item can also fit here -> very good chaining
            score -= 45.0 * (1.0 - diff / (bin_capacity as f64));
            if diff == 0.0 {
                score -= 80.0; // perfect 2-chain
            }
        } else {
            // next item won't fit in residual; penalize unless residual is tiny (dead space anyway)
            if post_residual >= 10 {
                score += 15.0 * (1.0 - (post_residual as f64) / (bin_capacity as f64));
            }
        }
    }

    // Relative-to-mean coupling: prefer bins with residual below mean (more filled bins)
    score += 0.4 * ((bin_residual as f64) - mean_residual);

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 90.0;
    }

    // New-bin candidate handling: discourage opening a new bin unless current fits are bad
    if bin_residual == bin_capacity {
        // base cost of a new bin
        score += 110.0;
        // but if item is large relative to capacity and fits poorly nowhere, new bin is fine
        if (item_size as f64) / (bin_capacity as f64) > 0.6 {
            score -= 40.0;
        }
        // late in stream, prefer consolidation into open bins
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 30.0 * progress;
    }

    // Mild penalty for spreading across too many open bins
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic penalty on leftover space.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64 * 2.0);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: penalize residuals that can't host the next item,
    // reward residuals that host it snugly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score += slack * 0.3;
        } else {
            score -= 5.0; // dead space for next item is fine here
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when existing bins are crowded or fits are poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowding = mean_residual / bin_capacity as f64;
        let mut nb = 60.0;
        nb -= crowding * 40.0;
        nb -= progress * 10.0;
        if fitting_bins_count <= 1 {
            nb -= 30.0;
        }
        score = score.max(nb);
    }

    // Mild penalty for leaving many nearly-empty bins open.
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;

    // Smooth polynomial coupling of post_residual with stream progress
    let poly = progress * progress * (1.0 - progress) * (1.0 - progress);
    score += 3.0 * poly * pr;

    // Reward tight fits more aggressively as the stream progresses
    let tightness = 1.0 - pr / cap;
    score -= 20.0 * tightness * tightness * (0.3 + 0.7 * progress);

    // Penalize dead space relative to mean residual of open bins
    score += 0.15 * (pr - mean_residual).abs();

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: reward leaving space compatible with the next item
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score += 0.1 * gap;
        if next_item_size as f64 <= pr {
            score -= 5.0 * (1.0 - gap / cap);
        }
    }

    // Mild penalty for spreading across too many open bins
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover lands in a
    // "small-item friendly" residue class are preferred.
    let cap = bin_capacity as f64;
    let pr = post_residual as u32;

    // Modulo-10 class: residuals divisible by 10 pair well with the
    // 10..80 item granularity; reward them.
    if pr % 10 == 0 {
        score -= 4.0;
    } else if pr % 5 == 0 {
        score -= 1.5;
    }

    // Integer-division thresholds on post_residual: quarter bins.
    let q = pr / (bin_capacity / 4);
    match q {
        0 => score -= 6.0,              // near-perfect fit
        1 => score -= 2.0,
        2 => score += 1.0,
        _ => score += 3.0,              // wasteful leftover
    }

    // Coupling with lookahead item: does next item fit in post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 3.0 + (next_item_size as f64) * 0.02;
        } else {
            // leftover too small for the known next item: dead-space penalty
            score += (pr as f64) * 0.05;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: only open a new bin when existing residuals are tight.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let tight = mean_residual < 25.0;
        if tight {
            score -= 5.0; // existing bins nearly full, opening is fine
        } else {
            score += 12.0 + mean_residual * 0.1 - progress * 3.0;
        }
        // Large items prefer a fresh bin when nothing fits well.
        if item_size > bin_capacity / 2 && mean_residual < item_size as f64 {
            score -= 6.0;
        }
    }

    // Mild preference to fill bins with high residual (balance load).
    score -= (bin_residual as f64 / cap) * 2.0;

    // Penalize scattering across many open bins slightly.
    score += (open_bins_count as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong penalty for dead space that is too small to be useful
    // (dead space below the minimum item size is pure waste).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - (post_residual as f64) * 3.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= tightness * 25.0;

    // Reward exact fills.
    if post_residual == 0 {
        score -= 100.0;
    }

    // If this bin is the last chance to avoid opening a new bin, favor it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // If next item could fit into the post_residual, reward preserving it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // Penalize leaving a gap that just barely misses the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Open bins pressure: discourage spreading across many bins,
    // but make new bins attractive when few are open.
    if bin_residual == bin_capacity {
        // New bin candidate: base cost plus pressure from open bin count.
        score = 55.0 + (open_bins_count as f64) * 4.0;
        // Opening a new bin is good if it would leave a large usable residual
        // for the next item.
        if next_item_size > 0 {
            let new_residual = bin_capacity - item_size;
            if new_residual >= next_item_size {
                score -= 20.0;
            }
        }
        // Avoid opening new bins when a perfect/tight fit exists elsewhere.
        if fitting_bins_count > 0 && mean_residual > (item_size as f64) * 1.5 {
            score += 30.0;
        }
    } else {
        // Mild penalty for using a bin whose residual deviates far from mean
        // (keeps bin residuals balanced).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.15;
    }

    // Slight late-stream conservatism: as stream progresses, waste matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect or near-perfect fits (small post_residual is already low, add bonus).
    if post_residual == 0 {
        score -= 1000.0; // perfect fit is always ideal
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 15 {
        score -= 60.0;
    }

    // 2-step lookahead: strongly reward bins whose leftover can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 300.0 - slack.min(100.0) * 1.5; // tight chain fit best
        } else {
            // Next item won't fit here: penalize wasted leftover relative to next item.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 2.0;
        }
        // Bonus if the next item fits *exactly* (chain perfect match).
        if next_item_size == post_residual {
            score -= 250.0;
        }
    } else {
        // Last item: only immediate tightness matters; score = post_residual already.
        score -= 500.0; // end of stream: minimize residual aggressively
    }

    // Penalize creating dead space far below any plausible future item (min item 1,
    // but tiny unusable slivers relative to mean residual are bad).
    let mr = if mean_residual > 0.0 { mean_residual } else { 1.0 };
    if (post_residual as f64) < mr * 0.5 && post_residual > 0 {
        score += (mr * 0.5 - post_residual as f64) * 1.2;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate (empty bin): penalize opening a new bin unless existing
    // placements would create large waste. A fresh bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is costly; make it unattractive by default.
        score += 250.0 + open_bins_count as f64 * 5.0;
        // But if no existing bin fits well (post_residual would be huge elsewhere),
        // the base post_residual=capacity here is still competitive when item is small.
        // If the item is large relative to capacity, a fresh bin is fine.
        if item_size as f64 > 0.7 * bin_capacity as f64 {
            score -= 200.0;
        }
        // If next item could chain into remaining space of fresh bin, soften penalty.
        if next_item_size > 0 && (bin_capacity - item_size) >= next_item_size {
            score -= 80.0;
        }
    }

    // Slight penalty for bins whose residual is much larger than the item (bad fill ratio).
    if bin_residual > item_size * 3 && bin_residual < bin_capacity {
        score += (bin_residual - item_size * 3) as f64 * 0.3;
    }

    // Mild stream-progression pressure: late in stream, prefer tighter packing.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Penalize small dead space that nothing (>=10) can ever use,
    // unless it is exactly zero.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Lookahead coupling: reward bins whose leftover could host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 30.0 + 0.5 * next_item_size as f64;
        } else {
            // Dead space relative to the next item.
            score += 0.3 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate handling: only attractive if the item fits snugly
    // (near-perfect fill) or no existing bin fits well.
    if bin_residual == bin_capacity {
        let snug = (bin_capacity - item_size) as f64;
        if snug == 0.0 {
            score -= 900.0; // perfect fill in a fresh bin
        } else if snug < 10.0 {
            score += 80.0;  // unusable sliver in a fresh bin: bad
        } else {
            // Baseline cost of a fresh bin; soften when many bins fit poorly.
            score += 40.0 + 0.2 * snug;
            if fitting_bins_count == 0 {
                score -= 100.0;
            }
            if next_item_size > 0 && snug >= next_item_size as f64 {
                score -= 20.0;
            }
        }
    }

    // Global state: when mean residual is high, prefer tightening the fullest
    // (smallest-residual) bins; when mean residual is low, spread less.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let residual_gap = mean_residual - post_residual as f64;
    score += 0.1 * residual_gap * (1.0 - t);

    // Late in the stream, prioritize minimizing leftover waste more aggressively.
    score += t * post_residual as f64 * 0.5;

    // Mild pressure to reuse existing bins when many are open.
    score += 0.01 * open_bins_count as f64 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let pr_norm = pr / cap;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let t = progress;
    let poly = pr_norm * pr_norm * (0.5 + 1.5 * t) + pr_norm * (1.0 - t) * (1.0 - t);
    score += poly * cap * 0.4;

    // Reward tight fits more strongly as the stream progresses
    score -= fit_ratio * (10.0 + 40.0 * t * t);

    // Penalize wasted residual relative to mean residual across open bins
    score += (pr as f64 - mean_residual).abs() * (0.2 + 0.6 * t);

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 {
        score -= 25.0 + 30.0 * t;
    }

    // Lookahead coupling: reward leaving room for the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr as f64 >= nx {
            score -= (nx / cap) * (8.0 + 12.0 * t);
        } else {
            score += (nx - pr as f64) * 0.15;
        }
    }

    // Mild penalty for opening new bins late in the stream
    if bin_residual == bin_capacity {
        score += 6.0 + 18.0 * t + 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact fills are perfect.
    if post_residual == 0 {
        score -= 40.0;
    } else {
        // Penalize small dead space that nothing can use (items >= 1).
        if post_residual < 10 {
            score += 15.0;
        }
        // Harmonic bucketing: residuals divisible by common size classes are reusable.
        for k in [5u32, 10, 20, 25, 50] {
            if post_residual % k == 0 {
                score -= 6.0;
            }
        }
        // Dead space worse than the smallest plausible item is wasted.
        if post_residual < 20 {
            score += 8.0;
        }
    }

    // Lookahead: reward if next item fits in the post residual (chain packing).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= (next_item_size as f64) * 0.5;
        } else if post_residual > 0 && next_item_size > bin_residual {
            // next item won't fit anywhere anyway; mild bonus for tighter packing
            score -= 2.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let avg_fill = 1.0 - mean_residual / bin_capacity as f64;
        // Penalize opening new bins while existing bins are decently filled,
        // but allow it late in the stream or when mean residual is large.
        score += 25.0 * (1.0 - avg_fill) + 10.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    // Prefer bins whose residual is close to item_size (tight fit).
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score += tightness * 10.0;

    // Mild pressure to consolidate when many bins are open.
    score += open_bins_count as f64 * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps.
    // A residual is "dead" if it is too small to hold even the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }
    // Penalize residuals that can only hold tiny items relative to bin capacity.
    if post_residual > 0 && post_residual < 20 {
        score += 20.0;
    }

    // Reward tight fits (small post_residual) nonlinearly.
    score -= (bin_capacity - post_residual) as f64 / bin_capacity as f64 * 15.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: when many bins are open, prefer filling existing ones
    // and discourage opening new bins.
    let pressure = open_bins_count as f64 / (1.0 + step_index as f64);
    score += pressure * 2.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are already open.
        score += open_bins_count as f64 * 5.0;
        // But if the item is large and mean residual is small, new bin is fine.
        if (item_size as f64) > mean_residual {
            score -= 10.0;
        }
    }

    // Lookahead: if the next item fits exactly in the post_residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    }
    // If next item cannot fit in post_residual but this bin could hold it, slight penalty
    // for wasting the chance to combine.
    if next_item_size > 0 && next_item_size > post_residual && next_item_size <= bin_residual {
        score += 5.0;
    }

    // Prefer bins whose residual is close to the mean (balanced packing) early on;
    // late in the stream, prefer using up the largest residuals.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * (1.0 - progress) * 0.5;

    // Slight bonus for leaving residuals that are "nice" sizes (multiples of 10),
    // which pair well with typical item sizes.
    if post_residual % 10 == 0 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Exact fit: extremely strong preference.
    if post_residual == 0 {
        score -= 500.0;
    }

    // Aggressive 2-step lookahead: if next item exactly fills post_residual, this is ideal.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 250.0;
        } else if next_item_size <= post_residual {
            // Next item fits: reward proportionally to how well post_residual is used next.
            let next_use = (next_item_size as f64) / (post_residual as f64);
            score -= 60.0 * next_use;
            // Bonus if next placement would also be near-exact.
            let next_leftover = post_residual as f64 - next_item_size as f64;
            if next_leftover <= 5.0 {
                score -= 80.0;
            }
        } else {
            // Next item will NOT fit in this bin's leftover: penalize dead space,
            // especially when leftover is small-but-unusable.
            let waste = post_residual as f64;
            if waste < next_item_size as f64 {
                score += 25.0 + 0.5 * waste;
            }
        }
    }

    // Compare against mean residual across open bins: prefer bins that reduce variance
    // (place into large-residual bins, avoid fragmenting tight bins).
    let res_f = bin_residual as f64;
    if res_f > mean_residual {
        score -= 0.3 * (res_f - mean_residual);
    } else {
        score += 0.4 * (mean_residual - res_f);
    }

    // Last chance: only fitting bin -> strong penalty for opening a new bin instead.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: opening a new bin should only win when all open
    // bins would leave poor fits (high post_residual / unusable leftovers).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 90.0;
        // Less costly to open a new bin when many bins are already open (spread load).
        score -= (open_bins_count as f64).sqrt() * 4.0;
        // If next item is large, a fresh bin is valuable.
        if next_item_size >= 60 {
            score -= 30.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 40.0 * progress;
    }

    // Mild penalty for very small unusable leftovers (dead space < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 35.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Best-fit core: reward tight fits non-linearly.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 + 0.05 * next_item_size as f64;
        } else {
            score += 4.0;
        }
        // Chain fit: bin residual itself fits next item even if this placement doesn't chain.
        if bin_residual >= next_item_size && post_residual < next_item_size {
            score += 2.0;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Time horizon: early on, be more willing to spread items (favor new bins slightly);
    // later, consolidate aggressively to avoid leftover open bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 6.0 * progress * (mean_residual / bin_capacity as f64);

    // Global state: many open bins with large mean residual -> discourage opening new bins,
    // encourage filling existing ones.
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive early, or when open bins fit poorly.
        let new_bin_base = 45.0 - 30.0 * progress;
        if open_bins_count == 0 {
            score = new_bin_base - 15.0;
        } else if fitting_bins_count == 0 {
            score = new_bin_base;
        } else {
            score = new_bin_base + 10.0 + 2.0 * open_bins_count as f64 * (1.0 - progress);
        }
    } else {
        // Existing bin: bonus for reducing mean residual gap.
        let gap = mean_residual - post_residual as f64;
        score -= 0.3 * gap.max(0.0);
        // Penalize leaving large residual when few items remain.
        if progress > 0.8 {
            score += 0.1 * post_residual as f64 * progress;
        }
    }

    // Mild preference for bins with residual close to item size (exact-fit shaping).
    let diff = (bin_residual as f64 - item_size as f64).abs();
    score += 0.15 * diff;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let fit = fitting_bins_count as f64;
    let open_c = open_bins_count as f64;

    // Reward tight fits: quadratic decay of residual is better than linear
    score -= 12.0 * norm_pr * norm_pr;

    // Perfect fill bonus (smooth, not piecewise)
    score -= 20.0 * (1.0 - norm_pr).powi(6);

    // Late in the stream, prefer consolidating into existing bins
    score += 8.0 * t * norm_pr;

    // Penalize wasting the last fitting bin's space
    if fitting_bins_count == 1 {
        score -= 15.0 * norm_pr;
    }

    // New-bin candidate: penalize opening a new bin, more so early and when alternatives exist
    if bin_residual == bin_capacity {
        score += 25.0 + 20.0 * (1.0 - t) + 3.0 * open_c;
        // But if no open bin fits well, allow it: reduce penalty
        score -= 30.0 * (1.0 - (fit.min(3.0) / 3.0));
    }

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = pr - nx;
        if gap >= 0.0 {
            score -= 10.0 * (1.0 - (gap / cap).abs());
        } else {
            score += 5.0;
        }
    }

    // Mean residual coupling: prefer bins deviating favorably from the mean
    score += 0.05 * (pr - mean_residual);

    // Mild penalty for spreading across too many open bins
    score += 0.5 * open_c * (1.0 - t);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: prefer residuals that fall into
    // "reusable" size classes (small leftovers that future items can fill).
    let r = post_residual;
    let class = r / 10; // integer division threshold classes
    match class {
        0 => score -= 40.0,          // r < 10: nearly perfect fit
        1 => score -= 25.0,          // 10..19: very reusable
        2 => score -= 15.0,          // 20..29
        3 => score -= 5.0,           // 30..39
        4 => score += 0.0,           // 40..49 neutral
        5 => score += 8.0,           // 50..59 slightly wasteful
        6 => score += 14.0,          // 60..69
        7 => score += 20.0,          // 70..79
        _ => score += 28.0,          // 80+: large dead space
    }

    // Modulo coupling: residuals divisible by 10 pair well with the
    // 10-80 item grid; reward multiples of 10, penalize odd residues.
    if r % 10 == 0 && r > 0 {
        score -= 6.0;
    }
    if r % 2 == 1 {
        score += 2.0;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // strongly reward; if it cannot fit, mild penalty only if other bins exist.
    if next_item_size > 0 {
        if next_item_size == r {
            score -= 30.0;
        } else if next_item_size <= r {
            score -= 12.0 * (1.0 - (r - next_item_size) as f64 / 20.0).max(0.0);
        } else {
            score += 4.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the item is large or existing residuals are badly fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual - post_residual as f64).abs();
        let pressure = (item_size as f64 / bin_capacity as f64) * 30.0
            + fragmentation * 0.15
            + (open_bins_count as f64).ln().max(0.0) * 2.0;
        // New bin starts with full residual: baseline score equals capacity.
        score = bin_capacity as f64 - pressure + progress * 5.0;
        // Never open a new bin when a perfect-fit class exists elsewhere.
        if r <= 10 && fitting_bins_count >= 1 {
            score += 100.0;
        }
    }

    // Mild global pressure: with many open bins, prefer consolidation.
    score += (open_bins_count as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual gap is "dead" if it is smaller than the smallest plausible item (1..100, use 10 as typical lower bound).
    let dead_threshold = 10.0_f64;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += 40.0; // unusable sliver
    }

    // Penalize near-full waste mildly; reward tight fits (small positive post_residual).
    if post_residual > 0 && post_residual <= 5 {
        score -= 8.0;
    }

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Penalize leaving a gap that exactly fits the next item (wasted opportunity otherwise).
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 6.0;
    } else if next_item_size > 0 && post_residual < next_item_size {
        score += 4.0; // next item cannot use this gap
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is excellent.
    score += open_bins_count as f64 * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: make it attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        // Baseline cost of opening a new bin; compare against dead-space penalties of open bins.
        score = bin_capacity as f64 * 0.35 + open_bins_count as f64 * 0.3;
        if post_residual == 0 { score -= 25.0; }
    }

    // Progress-based mild adjustment: late in stream, tighten up (avoid waste more).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Base: prefer tight fits (small post_residual), with a mild nonlinearity
    // that punishes mid-range dead space more than near-full bins.
    score += 0.35 * (post * (cap - post) / cap);

    // Aggressive 2-step lookahead: reward if next item fits exactly into
    // the post residual; penalize if next item cannot fit.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (next_item_size as u32) == post_residual as u32 {
            score -= 45.0; // perfect chaining: post residual becomes next item
        } else if next_item_size <= post_residual as u32 {
            // next item fits: reward proportional to how snugly it chains
            let chain_post = post - nxt;
            score -= 25.0 * (1.0 - chain_post / cap);
        } else {
            // next item won't fit here: penalize leftover dead space
            score += 12.0 * (post / cap);
        }
    }

    // Relative to mean residual: bins with less residual than average are
    // "nearly done" — prefer filling them to close them out.
    score -= 6.0 * (mean_residual - post) / cap;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive
    // when no open bin offers a decent fit (post_residual would be large
    // relative to typical item sizes). Make the empty-bin score unattractive
    // unless the item is large relative to capacity.
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / cap;
        // Empty bin gets a penalty that shrinks for large items (poor fits elsewhere)
        score += 20.0 - 18.0 * frac;
        // If many bins are open, discourage adding more unless item is huge
        score += 0.8 * (open_bins_count as f64).sqrt() * (1.0 - frac);
    }

    // Slight stream-progression pressure: late in the stream, be more
    // conservative about leaving loose residual (fewer chances to fill it).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 4.0 * progress * (post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Reward tight fits (low post residual) more strongly than linear.
    let tightness = 1.0 - post / cap;
    score -= 12.0 * tightness * tightness * tightness;

    // Penalize dead space that cannot fit a typical future item.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if post > 0.0 && post < 10.0 {
        score += 25.0 * (1.0 - progress); // early small dead space is costly
    }

    // Lookahead: strongly reward leaving room for the next item.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if post >= n {
            let slack = post - n;
            score -= 10.0 * (1.0 - slack / cap);
        } else {
            // next item won't fit here; mild penalty proportional to overflow
            score += 4.0 * (n - post) / cap;
        }
    }

    // Last-chance bin: avoid opening a new bin if this is the only fitter.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when existing fits are bad.
    if bin_residual == bin_capacity {
        let base_penalty = 30.0 + 20.0 * (1.0 - progress);
        // If current bin fits poorly (large post residual vs mean), opening new bin
        // becomes competitive: reduce penalty when post_residual is large.
        let poor_fit = (post - mean_residual).max(0.0) / cap;
        score = base_penalty - 15.0 * poor_fit + post; // post == cap here, large
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
    } else {
        // Prefer bins with residual below the mean (consolidate fullness).
        let dev = (bin_residual as f64 - mean_residual) / cap;
        score += 8.0 * dev;
    }

    // Slight preference for fewer open bins late in the stream.
    score += 0.5 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let tightness = 1.0 - (pr / cap);
    // smooth polynomial coupling of residual waste with stream progress
    let prog_poly = progress * progress * (3.0 - 2.0 * progress);
    score += 8.0 * pr * pr / cap * (0.5 + prog_poly);
    // reward tight fits, stronger later in the stream
    score -= 25.0 * tightness * tightness * (0.4 + 0.6 * prog_poly);
    // penalize opening new bins early / when many bins fit the item
    if bin_residual == bin_capacity {
        score += 12.0 + 18.0 * (1.0 - prog_poly) + 2.0 * fitting_bins_count as f64;
    }
    // last-chance bin: strong reward to use it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }
    // lookahead: reward leaving space that fits the next item
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score -= 6.0 * (1.0 - gap / cap) * (1.0 - gap / cap);
    }
    // mildly prefer bins with residuals near the mean (balance)
    score += 0.3 * (pr - mean_residual).abs() * (0.5 + prog_poly);
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals in "useful" classes
    // (small residuals waste little; residuals divisible by common item classes are reusable)
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else if pr <= 10 {
        score -= 25.0;
    } else {
        // mod-based harmonic classes: residuals matching common size classes (10..=20, 30, 40, 50) are reusable
        let reusable = pr % 10 == 0;
        if reusable {
            score -= 12.0;
        }
        if pr >= 30 && pr <= 50 {
            score -= 8.0;
        }
        if pr > 50 {
            score += (pr - 50) as f64 * 0.5; // large leftover = wasteful bin
        }
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / cap);
        } else {
            score += 10.0; // next item won't fit here; this bin likely closes
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Prefer bins below mean residual (filling emptier bins keeps tight bins for tight items)
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Late in stream: avoid opening new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize, more so late in the stream
        score += 15.0 + 25.0 * progress + open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= bin_capacity as u32 - 10 {
            score -= 10.0; // big next item may need a fresh bin anyway
        }
    } else {
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever be
    // useful (below the minimum plausible item size) are pure waste.
    if post_residual < 10 {
        score += 60.0; // unusable sliver
    } else if post_residual < 20 {
        score += 25.0;
    }

    // Dead space that cannot fit the lookahead item is doubly penalized.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 12.0 + 0.15 * next_item_size as f64;
    }

    // Reward tight fits (low post_residual relative to item size).
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= 18.0 * tightness;
    if post_residual == 0 {
        score -= 30.0; // perfect fill
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 22.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins; with few open bins, new bins are cheap.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / 20.0);
    score += 0.6 * pressure * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when current bin fits are poor
    // (large post_residual or heavy dead-space penalties accumulated).
    if bin_residual == bin_capacity {
        score += 15.0 + 0.25 * open_bins_count as f64;
        if fitting_bins_count > 0 && mean_residual > 30.0 {
            score += 20.0; // existing bins have room; opening new is wasteful
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 15 {
        score -= 60.0;
    }

    // 2-step lookahead: reward if next item fits the post residual exactly
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // next item fits: reward proportionally to how well it fills
            let fill_after_next = post_residual - next_item_size;
            score -= 150.0 * (1.0 - fill_after_next as f64 / bin_capacity as f64);
        } else {
            // next item does NOT fit: penalize wasted residual that next item can't use
            let waste = next_item_size - post_residual;
            score += 40.0 + 0.8 * waste as f64;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate penalty: only open a new bin if no decent fit exists
    if bin_residual == bin_capacity {
        score += 80.0;
        // If current item fills a fresh bin substantially, opening is less bad
        if item_size as f64 > 0.7 * bin_capacity as f64 {
            score -= 60.0;
        }
        // Lookahead: if next item is large, a fresh bin is more valuable
        if next_item_size >= item_size {
            score -= 30.0;
        }
    }

    // Early in stream: slightly discourage hoarding many open bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if open_bins_count > 4 && progress < 0.5 {
        score += 5.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to item size)
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 12.0 * tightness;

    // Reward if the lookahead item can also fit in the leftover space
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0 + 0.15 * next_item_size as f64;
    }
    // Penalize if next item nearly fits but misses (dead space risk)
    if next_item_size > post_residual && post_residual > 0 && next_item_size - post_residual <= 10 {
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalize creating large unusable dead space (< smallest plausible item)
    if post_residual > 0 && post_residual < 10 {
        score += 5.0;
    }

    // Global state: penalize placements that leave residual far from mean residual
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    // New-bin candidate handling: brand-new empty bin
    if bin_residual == bin_capacity {
        // Base penalty so existing decent fits win
        let mut nb = 20.0;
        // If no open bin fits (this call is the only option), it's necessary
        if fitting_bins_count == 0 {
            nb -= 25.0;
        }
        // Late in the stream, prefer consolidation into open bins
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        nb += 10.0 * progress;
        // Many open bins: discourage adding another
        nb += 0.5 * open_bins_count as f64;
        // Small items waste a fresh bin; large items justify it
        nb += 0.1 * (100 - item_size.min(100)) as f64;
        score += nb;
    }

    // Mild time coupling: early on, encourage packing into fewer bins
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 3.0 * (1.0 - t) * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized residual
    let p = progress;
    let poly = x * x * (3.0 - 2.0 * p) + x * p * p;
    score += poly * 12.0;

    // Reward tight fits more strongly as the stream progresses.
    let tightness = 1.0 - x;
    score -= tightness * tightness * (20.0 + 40.0 * p);

    // Penalize creating dead space that cannot host the lookahead item.
    if next_item_size > 0 && post_residual > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0) / cap;
        score += gap * gap * 25.0 * (0.5 + p);
    }

    // Last-chance bin: strong bonus to use it rather than open a new one.
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * (1.0 - p);
    }

    // Mild penalty for spreading across many open bins.
    score += open_bins_count as f64 * 0.5;

    // Slight preference to fill bins below mean residual (balancing).
    score += (mean_residual - pr) * 0.15;

    // New-bin candidate: penalize opening a bin unless residuals are tight.
    if bin_residual == bin_capacity {
        score += 15.0 + 25.0 * (1.0 - p) + mean_residual * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 and integer division bands
    let post = post_residual;
    let decile = post % 10;
    let band = post / 10; // 0..=10 harmonic band

    // Penalize dead space in awkward bands: very small residuals are hard to reuse
    if post < 10 {
        score += 30.0 * (10 - post) as f64; // unusable sliver
    } else if post <= 20 {
        score += 6.0;
    } else if post >= 50 {
        score -= 4.0 * (post as f64) / cap_f * 10.0; // roomy residual is valuable
    }

    // Modulo-10 resonance: residuals that are multiples of 10 pair well with
    // common item sizes (items often cluster on decade boundaries)
    if decile == 0 && post > 0 {
        score -= 5.0;
    } else if decile == 5 {
        score -= 2.0;
    } else if decile <= 2 || decile >= 8 {
        score += 2.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 25.0;
        } else if next_item_size <= post && post - next_item_size < 10 {
            score -= 10.0; // near-perfect chain
        } else if next_item_size <= post {
            score -= 3.0;
        } else {
            // next item cannot use this residual; penalize proportionally
            score += 4.0 * (next_item_size as f64) / cap_f;
        }
    } else {
        // last item: prefer tightest fit, any residual is dead
        score += (post as f64) * 0.5;
    }

    // Last-chance bin: strongly reward using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: neutral base; only open a new bin when existing fits are poor
    if bin_residual == bin_capacity {
        // Opening cost: amortize over remaining stream
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = cap_f * 0.9 + 10.0 * (1.0 - progress);
        // open new bin is attractive if next item is large and current item is small
        if next_item_size > item_size && item_size <= 30 {
            score -= 20.0;
        }
        if post == 0 { score -= 100.0; } // never (post==cap here), guard
    }

    // Many open bins: prefer filling existing ones to allow closing
    if open_bins_count > 4 && bin_residual != bin_capacity {
        score -= 2.0;
    }

    // Mean-residual alignment: if this bin's residual deviates from mean, slight nudge
    score += 0.05 * ((post as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to be useful later
    // are heavily penalized. Define "unusable" as a gap smaller than the
    // smallest conceivable item (1) plus a safety margin, but more precisely
    // as a gap that cannot fit the lookahead item nor a typical small item.
    let min_useful = if next_item_size > 0 { next_item_size.min(20).max(1) } else { 1 };
    if post_residual > 0 && post_residual < min_useful {
        score += 40.0 * (min_useful as f64 - post_residual as f64);
    }

    // Reward near-perfect fits strongly (post_residual close to 0).
    if post_residual == 0 {
        score -= 100.0;
    } else {
        let fit_ratio = post_residual as f64 / bin_capacity as f64;
        score += 30.0 * fit_ratio * fit_ratio;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // no open bin offers a decent fit. Penalize the fresh bin mildly so it is
    // chosen only when existing bins would waste a lot of space.
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64;
        // But if this is the last item, a fresh bin is fine (nothing to waste).
        if next_item_size == 0 {
            score -= 30.0;
        }
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than spreading items out.
    score += 0.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins whose residual is close to the mean residual (keeps the
    // bin population homogeneous, leaving larger bins for larger items).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.2 * dev;

    // Lookahead coupling: if the next item would fit exactly in the
    // post_residual, reward this placement.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual), with mild superlinear penalty on waste.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Lookahead: if the next item exactly fills the post-residual, this is a perfect
    // 2-item packing -> strongly reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Next item still fits after this placement: mild reward, scaled by
            // how well the next item consumes the leftover.
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 15.0 * fill;
        } else {
            // Next item cannot use the leftover: penalize proportionally to the
            // stranded capacity, especially when the leftover is small (dead space).
            let waste = (next_item_size - post_residual) as f64;
            score += 0.35 * waste.min(40.0);
            // If next item would exactly fit a fresh bin, prefer not to strand it here.
            if next_item_size == bin_capacity {
                score += 10.0;
            }
        }
    }

    // Relative-to-mean coupling: a bin whose residual is far below the mean is
    // already "specialized"; placing here when it creates large waste is bad.
    let dev = post_residual as f64 - mean_residual;
    if dev > 0.0 {
        score += 0.10 * dev;
    } else {
        score += 0.04 * dev; // slight reward for below-mean residual bins
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual <= bin_capacity / 4 {
        score -= 12.0;
    }

    // New-bin candidate (empty bin): only attractive when the current item is large
    // relative to capacity or open bins are numerous/cluttered.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        let clutter = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
        score = 45.0 + 40.0 * (1.0 - large_item) + 3.0 * clutter;
        // Exact pairing of item with next item in a fresh bin.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 20.0;
        }
    }

    // Mild stream-progression pressure: later in the stream, waste matters more
    // (less opportunity to amortize it).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize wasted fraction quadratically.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * waste_frac * waste_frac * (bin_capacity as f64);

    // Reward bins whose residual is close to item_size (near-perfect fill).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score -= 25.0 * (1.0 - tightness * 2.0).abs().min(1.0) * (1.0 - tightness);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
        }
        // If post_residual is a tiny dead zone the next item can't use, penalize.
        if post_residual < next_item_size && post_residual > 0 {
            score += 0.3 * post_residual as f64;
        }
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // no open bin fits well (high mean residual spread) or few bins are open.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let poor_fits = (fitting_bins_count == 0) as i32 as f64;
        let new_bin_bonus = -30.0 * poor_fits
            + 10.0 * (1.0 - progress)
            + 0.5 * (open_bins_count as f64).ln().max(0.0);
        // Baseline: an empty bin leaves residual = capacity - item_size.
        score = (bin_capacity - item_size) as f64 + new_bin_bonus;
        // If open bins fit fine, discourage opening a new one.
        if fitting_bins_count > 1 {
            score += 45.0;
        }
        return score;
    }

    // Prefer bins below mean residual (consolidate fullness) when many bins open.
    if open_bins_count > 1 {
        let diff = mean_residual - bin_residual as f64;
        score += 0.2 * diff;
    }

    // Late in the stream, consolidate into fewer bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 20.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let fit_ratio = item_size as f64 / cap;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // wasted space is punished increasingly quadratically as the stream advances.
    let norm_post = post / cap;
    score += 3.0 * norm_post * norm_post * (0.5 + progress) * cap;

    // Reward tight fits (small post_residual) with a smooth cubic bonus.
    score -= 2.0 * (1.0 - norm_post).powi(3) * (1.0 + fit_ratio) * 10.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 15.0 * progress;
    }

    // Lookahead: penalize leaving a residual that barely fails to fit the next item,
    // reward residuals that can accommodate it.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 8.0 * (1.0 - ((post - nxt) / cap)) * (0.5 + progress);
        } else {
            let gap = (nxt - post) / cap;
            score += 10.0 * gap * (1.0 - gap) * (1.0 + progress);
        }
    }

    // Prefer bins whose residual deviates below the mean (consolidate fullness).
    score -= 0.15 * (mean_residual - post) * (0.5 + progress);

    // Mild penalty scaled by number of open bins to discourage bin sprawl.
    score += 0.5 * open_bins_count as f64 * (0.3 + 0.7 * progress);

    // New-bin candidate: neutral base with slight penalty so it only wins
    // when no open bin offers a reasonably tight fit.
    if bin_residual == bin_capacity {
        score += 12.0 + 18.0 * (1.0 - progress) + 2.0 * fitting_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small residue" classes (<= 10) are nearly perfectly packed.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Reward tiny residuals strongly (perfect fits).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 60.0;
    } else if post_residual <= 20 {
        score -= 25.0;
    } else if post_residual <= 30 {
        score -= 8.0;
    }

    // Modulo-10 class: residuals that are multiples of 10 pair well with
    // typical item sizes (also multiples of 10). Favor them.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 12.0;
    }

    // Harmonic coupling with lookahead: if the next item fits exactly into
    // the post residual, this is a two-item harmonic match.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 200.0; // exact chain fit
        } else if next_item_size <= post_residual {
            // next item fits: leftover after chaining determines quality
            let chain_left = post_residual - next_item_size;
            score -= 20.0 + (chain_left as f64).min(40.0) * 0.5;
            if chain_left % 10 == 0 {
                score -= 10.0;
            }
        } else {
            // next item won't fit here: penalize large dead space more
            // when the leftover is in an awkward class (> half of next item
            // but smaller than next item).
            if post_residual > next_item_size / 2 {
                score += 10.0;
            }
        }
        // Fractional capacity classes of the lookahead item
        let frac = n / cap;
        if frac > 0.5 {
            // big next item: prefer to keep small-residual bins free of waste
            score += (pr / cap) * 15.0;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: penalize mildly so we only open new bins when
    // existing fits are truly bad; make its baseline attractive for
    // perfect-fit-seeking strategies by keeping its raw score = capacity.
    if bin_residual == bin_capacity {
        score += 30.0 * (open_bins_count as f64).sqrt().min(6.0);
        // but if no existing bin can even come close, opening is fine
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Waste relative to mean residual: bins far below mean residual are
    // tighter fits, prefer them.
    score += (pr - mean_residual) * 0.3;

    // Late in the stream, tighten packing (less tolerance for waste).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += pr * 0.2 * progress;

    // Small penalty for many open bins to encourage closing bins out.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic decay of penalty as post_residual shrinks.
    score -= (bin_capacity as f64 - post_residual as f64) * 0.6;

    // Strict dead-space avoidance: residuals below the minimum item size (1..=100
    // interface, but typical small items ~10) are nearly unusable -> heavy penalty.
    let dead_threshold = 10u32;
    if post_residual > 0 && post_residual < dead_threshold {
        score += (dead_threshold - post_residual) as f64 * 8.0;
    }
    // Perfect fill is ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly reward this placement (chained packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // reward proportionally, but penalize leaving a gap the next item
            // only partially uses (creates new dead space).
            let gap_after_next = post_residual - next_item_size;
            score -= 15.0 - (gap_after_next.min(20) as f64) * 0.4;
        } else {
            // next item cannot use this residual: mild penalty scaled by waste
            score += (next_item_size - post_residual).min(30) as f64 * 0.3;
        }
    }

    // Open-bin pressure: discourage spreading across many bins unless the fit is good.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Mean-residual coupling: prefer bins whose residual is below mean
    // (concentrate filling in fuller bins -> best-fit-like behavior).
    let residual_f = bin_residual as f64;
    if mean_residual > 0.0 {
        score += (residual_f - mean_residual) * 0.3;
    }

    // New-bin candidate (empty bin): make it attractive only when the item is
    // large relative to capacity or open-bin fits would be very loose.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        // Base cost of opening a new bin, discounted for large items.
        score = 30.0 - fill_ratio * 55.0 + open_bins_count as f64 * 0.5;
        // If a lone existing bin fits, opening new is rarely better.
        if fitting_bins_count == 1 {
            score += 20.0;
        }
    }

    // Slight progression term: early in stream, be more willing to open bins;
    // late in stream, squeeze into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (post_residual near 0).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Aggressive 2-step lookahead: reward if next item fits the post residual exactly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / (bin_capacity as f64));
    } else if next_item_size > 0 {
        // Penalize when next item cannot follow into this bin.
        score += 12.0;
    }

    // Perfect chaining bonus: post_residual exactly equals next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }

    // Penalize dead space below minimum plausible item size (1..100 unknown, use small threshold).
    if post_residual > 0 && post_residual < 5 {
        score += 20.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize mildly so it's chosen only when fits are poor,
    // but give it a clean lookahead if next item is large.
    if bin_residual == bin_capacity {
        score += 18.0;
        if next_item_size > 0 && next_item_size > bin_residual - item_size.min(bin_residual) {
            score -= 10.0;
        }
    }

    // Relate to mean residual: prefer bins whose post residual is below mean (consolidating space).
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Late in stream, be greedier with tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * tightness;

    // Slight penalty for many open bins to encourage consolidation.
    score += 0.5 * open_bins_count as f64 * (1.0 - tightness);

    score
}
